create or replace force view prm_system_copy.v_bakasha_last_status as
select /*+ INDEX( p PRISHA_PK)
        INDEX( e EZOR_OVDIM_PK)
        INDEX( po PORSHIM_LIST_PK)
        INDEX( c1 CODE_ACTION_PK)
        INDEX( b BAKASHA_PK)
        INDEX( wf WORKFLOW_2_SUG_BAKASHA_UK1)
        INDEX( l1 ACTION_LOG_PK)
        INDEX( cr CODE_ROLE_PK)
        INDEX( w WORKFLOW_UK1)
        */
       b.code_sug_bakasha,
       e.code_makor,
       po.mispar_zehut,
       bakasha_union.taarich_prisha,
       b.seq_bakasha,
       p.seq_prisha,
       b.code_source,
       l1.date_action,
       c1.teur_action,
       c1.is_external,
       l1.seq_action_log,
       l1.code_action,
       l1.code_user_update,
       l1.remarks,
       l1.code_user_to_internal,
       l1.date_to_do,
       l1.date_do,
       l1.code_user_to_external,
       c1.is_new,
       po.porshim_seq seq_porshim,
       p.seq_ezor_ovdim,
       bakasha_union.code_seif_prisha,
       cr.code_department code_department_action,
       wf.code_sug_workflow,
       w.code_role_to,
       w.is_automatic,
       sb.code_merge_bakasha,
       b.date_bakasha,
       p.gimla_number,
       c1.code_sug_action  w_code_document,
  decode( l1.code_action,17,0,1) is_active,
  b.code_bakasha_detail,po.sug_zihuy
  from bakasha b
  left join prisha p
    on b.seq_prisha = p.seq_prisha
  left join poresh po
    on p.seq_poresh = po.porshim_seq
  left join code_ezor_ovdim e
    on p.seq_ezor_ovdim = e.seq_ezor_ovdim
  left join (select r.seq_bakasha, r.taarich_prisha, r.code_seif_prisha
               from bakasha_regila r
             union
             select t1.seq_bakasha, t2.taarich_prisha, t1.code_seif_prisha
               from bakasha_mukdemet t1
               left join tikim_mukdemet_hachlatot t2
                 on t1.seq_bakasha = t2.seq_bakasha) bakasha_union
    on b.seq_bakasha = bakasha_union.seq_bakasha
  left join (select max(l.seq_action_log) seq_action_log, l.seq_bakasha
               from action_log l
               left join code_action c
                 on l.code_action = c.code_action
              where c.is_status = 1
              group by l.seq_bakasha) max_action_log
    on b.seq_bakasha = max_action_log.seq_bakasha
  left join action_log l1
    on l1.seq_action_log = max_action_log.seq_action_log
  left join code_action c1
    on c1.code_action = l1.code_action
    left join workflow_2_sug_bakasha wf
on wf.code_source = b.code_source
and wf.code_sug_bakasha = b.code_sug_bakasha
left join workflow w
on w.code_sug_workflow = wf.code_sug_workflow
and w.code_action = l1.code_action
left join code_role cr
on cr.code_role = w.code_role_to
left join code_sug_bakasha sb
on sb.code_sug_bakasha = b.code_sug_bakasha;

