select p."MISPAR_ZEHUT",
       p."TAARICH_RISHUM",
       p."SHEM_PRATI",
       p."SHEM_KODEM",
       p."SHEM_MISHPACHA",
       p."TAARICH_ALIYA",
       p."CODE_MEDINAT_MOZA",
       p."TAARICH_LEDA",
       p."ADDRESS",
       p."CITY_CODE",
       p."PORSHIM_SEQ",
       p."MIKUD",
       p."TELEPHON",
       p."PELEPHON",
       p."CODE_MIN",
       p."TAARICH_PTIRA",
       p."MEKABAL_KIZVA",
       p."CODE_MAZAV_MISHPACHTI",
       p."MISPAR_OVED_MERKAVA",
       p."TELEPHON2",
       p."SUG_ZIHUY",
       p."TOAR",
       t.taarich_prisha,
       t.seq_ezor_ovdim,
       r.chisuv_lefy_sheerut,
