         t.code_address,
         t.code_city,
         t.mikud,
         t.date_update,
         t.code_user_update,
         t.seq_address,

         t.seq_bney_mishpacha,
         t.street,
         t.house,
         t.apartment,
         t.entrance,
         t.street ||
         case
         when t.apartment is null
            THEN to_char(t.house,'9999999999')
             when  t.house is null
               then '  /'|| trim(to_char(t.apartment,'9999999999'))
               else
               to_char(t.house,'9999999999')||'/'|| trim(to_char(t.apartment,'9999999999'))
             end   ktovet
    from address t where t.seq_bney_mishpacha> 0;

