create or replace function prm_system_copy.f_get_taarich_tchula_murchav(p_seq_bakasha number,
                                                p_teur_sug_bakasha out varchar2,
                                                p_status out number,
                                                p_ora_message out varchar2 ) return date is

  v_date_tchula date;
  v_code_sug_bakasha number;
  v_teur_sug_bakasha varchar2(500);

begin
  select v.code_sug_bakasha, c.code_teur_bakasha
  into v_code_sug_bakasha, v_teur_sug_bakasha
  from v_bakasha_last_status v, code_sug_bakasha c
  where v.seq_bakasha = p_seq_bakasha
  and c.code_sug_bakasha = v.code_sug_bakasha;

  p_teur_sug_bakasha := v_teur_sug_bakasha;
  p_status := 1; --הצלחה
  p_ora_message := '';

  if v_code_sug_bakasha in(1,3,5,13) then
    select min(t.date_start_zakaut)
    into v_date_tchula
    from netuney_tik_mechushavim t
    where t.seq_bakasha = p_seq_bakasha
    and t.code_department = 2;
   --end if;

  elsif v_code_sug_bakasha in(7,8,9,18,23) then
    select min(t.date_payment)
    into v_date_tchula
    from participation t
    where t.seq_bakasha = p_seq_bakasha;
  --end if;

  elsif v_code_sug_bakasha in(10,11) then
    select t.date_payment
    into v_date_tchula
    from bakasha_regila t
    where t.seq_bakasha = p_seq_bakasha;
  --end if;

  elsif v_code_sug_bakasha = 12 then
    select t.hp_date_start_zakaut
    into v_date_tchula
    from netuney_tik_mechushavim t
    where t.seq_bakasha = p_seq_bakasha
    and t.code_department =2;
  --end if;

  elsif v_code_sug_bakasha = 14 then
    select min(t.from_date)
    into v_date_tchula
    from netuney_sachar t, code_sug_maskoret c
    where t.seq_bakasha = p_seq_bakasha
    and t.code_sug_maskoret = c.code_sug_maskoret
    and c.teur_sug_maskoret like '%קצבה%'
    and t.mispar_misra = 0;
    if v_date_tchula is null then
            select distinct min(n.date_start_zakaut)
            into v_date_tchula
            from v_bakasha_last_status v1, netuney_tik_mechushavim n
            where v1.gimla_number =
            (select v2.gimla_number
            from v_bakasha_last_status v2
            where v2.seq_bakasha = p_seq_bakasha
            )
            and v1.code_sug_bakasha in (1,3,5,13)
            and v1.code_action = 98
            and v1.seq_bakasha = n.seq_bakasha
            and v1.seq_bakasha =
            (select max(v3.seq_bakasha)
            from v_bakasha_last_status v3
            where v3.gimla_number = v1.gimla_number
            and v3.code_sug_bakasha in (1,3,5,13)
            and v3.code_action = 98);

    end if;
   --end if;

   elsif v_code_sug_bakasha = 15 then
    select case when t.date_update is not null then t.date_update else sysdate end
    into v_date_tchula
    from bank_account t
    where t.seq_bakasha = p_seq_bakasha;
   --end if;

   elsif v_code_sug_bakasha = 16 then
    select t.date_bakasha
    into v_date_tchula
    from hivun t
    where t.seq_bakasha = p_seq_bakasha;
   --end if;

   elsif v_code_sug_bakasha = 17 then
    select t.from_date
    into v_date_tchula
    from hachnasot t
    where t.seq_bakasha = p_seq_bakasha;
   --end if;

   elsif v_code_sug_bakasha in (19,20) then
    select t.from_date
    into v_date_tchula
    from bakasha t
    where t.seq_bakasha = p_seq_bakasha;
   --end if;

   elsif v_code_sug_bakasha = 21 then
    select case when t.date_update is not null then t.date_update else sysdate end
    into v_date_tchula
    from address t
    where t.seq_bakasha = p_seq_bakasha;
   --end if;

   elsif v_code_sug_bakasha in (33,35) then
    v_date_tchula := trunc(sysdate);

   elsif v_code_sug_bakasha = 26 then
    select case when t.date_mazav_mishpachti is not null then t.date_mazav_mishpachti else case when t.date_update is not null then date_update else sysdate end end
    into v_date_tchula
    from mazav_mishpachti t
    where t.seq_bakasha = p_seq_bakasha;
 
   elsif v_code_sug_bakasha = 24 then
    select t.month_year
    into v_date_tchula
    from mikdamot t
    where t.seq_bakasha = p_seq_bakasha;

   elsif v_code_sug_bakasha = 37 then
    v_date_tchula := trunc(sysdate);
 
  end if;

   if v_date_tchula is null then
        p_status  := 0; --error
        p_ora_message := 'תאריך תחולה לא מוגדר';
   end if;

    return(v_date_tchula);

    exception
    when others then
    p_status  := 0;
    p_ora_message := sqlerrm;
    return (null);

end;
/

create or replace function prm_system_copy.f_get_taarich_tchula(p_seq_bakasha number) return date is

  v_date_tchula date;
  v_status number;
  v_teur_sug_bakasha varchar2(50);
  v_ora_message varchar(500);

begin
  v_date_tchula := f_get_taarich_tchula_murchav(p_seq_bakasha, v_teur_sug_bakasha, v_status, v_ora_message);
  return(v_date_tchula);
end;
/

create or replace package prm_system_copy.pk_prm_utils is
  ----------------------------------------------------------------------------
  function is_action_bakash_bfor_specific(p_seq_bakasha          number,
                                          p_code_action_to_check number)
    return number;
  -----------------------------------------------------------
  function insert_action_particiption_frm return number;
  ----------------------------------------------------------
  function insert_action_Retirement_age return number;
  -------------------------------------------------------------
  function insert_new_kapam(p_seq_prisha number) return number;
  -------------------------------------------------------------
  function duplicate_new_kapam(p_seq_bakasha_old number) return number;
  -------------------------------------------------------------
  procedure update_misra_when_choze_bchirim(p_seq_bakasha number);
  -----------------------------------------------
  function get_previos_bakasha_by_seq(v_seq_bakasha number) return number;
  -----------------------------------------------
  --Merge the new bakasha with the previos
  procedure External_Merge_versions(v_seq_bakasha_prev number,
                                    v_seq_bakasha_new  number);

  ----------------------------------------------------------
  --Merge the new bakasha with the previos
  procedure Merge_versions(v_seq_bakasha_new  in out number,
                           v_add_action       in out number,
                           v_seq_bakasha_prev number default null);

  ----------------------------------------------------------
  procedure Add_steps(p_seq_bakasha      in out number,
                      p_code_user_update number default null,
                      p_count_steps      number default 1);
  ----------------------------------------------------------
  procedure Add_next_action(v_seq_bakasha                number,
                            v_code_user_update           number,
                            v_code_sug_workflow          number,
                            v_current_action             number,
                            v_next_code_user_to_internal number default null);
  ----------------------------------------------------------
