create or replace function prm_system_copy.CONVERT_LOW_HEBREW_TO_ASCII(s varchar2)
  return varchar2 is
  Result varchar2(1000) := '';
  v_char varchar2(1);
  ascii_ number;
begin
  v_char := substr(s, 1, 1);
  if ascii(v_char) > 223 and ascii(v_char) < 251 then
    return s;
  end if;
  for i in 1 .. length(s) loop
    v_char := substr(s, i, 1);
    ascii_ := ascii(v_char);
    begin
    
      if ascii_ < 32 or ascii_ > 64 then
        Result := Result || chr(ascii_ + 96);
      else
        Result := Result || v_char;
      end if;
    exception
      when others then
        Result := Result || v_char;
    end;
  end loop;
  return(Result);
exception
  when others then
    return s;
end;
/

create or replace function prm_system_copy.Create_Tables(v_table_name varchar2) return varchar2 is
  Result varchar2(10000);

 
    i number;
    s varchar2(4000) := 'create table '||substr(v_table_name,3,26)||chr(10) ||
                               '   as select * from '||v_table_name||chr(10) ||
                               ' where 1<>1;'
                        ;
    s2  varchar2(4000) := 'alter table' || chr(10) ||
                            substr(v_table_name,3,26)||chr(10) ||
                            'add' || chr(10) ||
                            '   (' || chr(10) ||
                            '   CHG_DATE date         ,' || chr(10) ||
                            '   CHG_TYPE varchar2(10)  ,' || chr(10) ||
                            '   CHG_by varchar2(100)    ' || chr(10) ||
                            '   );'
                        ;
   s3 varchar2(4000) := 'CREATE INDEX ' || chr(10) ||
                        substr(v_table_name,3,22)||'_idx on '||
                        substr(v_table_name,3,26)||'(CHG_DATE,CHG_by);'
                        ;
  begin 
    select count(*)
    into i
    from user_tables t
    where table_name = upper(substr(v_table_name,3,26))
    ;
    if i = 1 then
      return 'The history table allready exists.';
    end if;
    return s||chr(10)||s2||chr(10)||s3;
    
   
  return(Result);
end ;
/

