create or replace function prm_system_copy.f_ascii(p_str varchar2) return varchar2 is
  FunctionResult varchar2(1000);
begin
  FunctionResult := '';
  for i in 1..length(p_str)
  loop
    FunctionResult := FunctionResult || ' - ' || to_char(ascii(substr(p_str,i,1)));
  end loop;
  return(FunctionResult);
end f_ascii;
/

create or replace function prm_system_copy.f_get_bakasha_netunim (p_sug_gimlay varchar2, p_seq_prisha number, p_mispar_misra number) return number is
  v_seq_bakasha number;
begin
 if p_sug_gimlay = 'פורש' then
   select max(n1.seq_bakasha)
      into v_seq_bakasha
      from prisha pr1, bakasha b1, netuney_tik_mechushavim n1, v_bakasha_last_status v
      where pr1.seq_prisha = p_seq_prisha
      and b1.seq_prisha = pr1.seq_prisha
      and n1.seq_bakasha = b1.seq_bakasha
      and n1.seq_bakasha = v.seq_bakasha
      and n1.code_department = 2
      and n1.mispar_misra = p_mispar_misra
      and v.code_action = 98
      and b1.code_sug_bakasha in (1,3,5);
      return v_seq_bakasha;
  else
    select max(n1.seq_bakasha)
      into v_seq_bakasha
      from prisha pr1, bakasha b1, bakasha_regila br1, netuney_tik_mechushavim n1, v_bakasha_last_status v
      where pr1.seq_prisha = p_seq_prisha
      and b1.seq_prisha = pr1.seq_prisha
      and b1.seq_bakasha = br1.seq_bakasha
      and n1.seq_bakasha = b1.seq_bakasha
      and n1.seq_bakasha = v.seq_bakasha
      and n1.code_department = 2
      and n1.mispar_misra = p_mispar_misra
      and v.code_action = 98
      and (b1.code_sug_bakasha in (1,5) and n1.code_group_prisha = 4
      or b1.code_sug_bakasha = 13);
      if v_seq_bakasha is not null then
         return v_seq_bakasha;
      else
         select max(n1.seq_bakasha)
          into v_seq_bakasha
          from prisha pr1, bakasha b1, netuney_tik_mechushavim n1, v_bakasha_last_status v
          where pr1.seq_prisha = p_seq_prisha
          and b1.seq_prisha = pr1.seq_prisha
          and n1.seq_bakasha = b1.seq_bakasha
          and n1.seq_bakasha = v.seq_bakasha
          and n1.code_department = 2
          and n1.mispar_misra = p_mispar_misra
          and v.code_action = 98
          and b1.code_sug_bakasha in (1,3,5)
          and n1.code_group_prisha <> 4;
          return (-v_seq_bakasha);
      end if;
     end if;
    exception
    when others then
          return (null);
end ;
/

