create or replace function prm_system_copy.f_get_darga(p_mispar_zehut number, p_mispar_gimla number) return number is

  v_darga number;
begin
select c.darga_malam
into v_darga
from temp_porshim_hilan t, code_derug_darga_hilan c
where t.mispar_zehut = p_mispar_zehut
and t.mispar_gimla = p_mispar_gimla
and c.derug_hilan = t.code_derug
and c.darga_hilan = t.code_darga * 100 + t.code_sub_darga;
return v_darga;
    exception
    when others then
    return (null);
end;
/

create or replace function prm_system_copy.f_get_date_end_zakaut(p_mispar_zehut number) return date is
  FunctionResult date;
  --v_max_date_start_zakaut date;
  v_max_date_end_zakaut date;
begin
select --v.mispar_zehut,v.code_sug_bakasha, v.code_bakasha_detail, n.date_start_zakaut, v.seq_bakasha,
n.date_end_zakaut
into v_max_date_end_zakaut
from netuney_tik_mechushavim n
left join v_bakasha_last_status v on v.seq_bakasha = n.seq_bakasha
left join poresh p on p.mispar_zehut = v.mispar_zehut
where  p.taarich_ptira is null
and v.code_action = 98
and v.seq_bakasha =
(select max(v1.seq_bakasha)
from v_bakasha_last_status v1
left join netuney_tik_mechushavim n1 on n1.seq_bakasha = v1.seq_bakasha
where v1.seq_prisha = v.seq_prisha
and v1.code_action = 98
and n1.seq_bakasha is not null)
and n.date_end_zakaut is not null
and n.date_start_zakaut is not null
and n.date_start_zakaut - n.date_end_zakaut = 1
and v.code_sug_bakasha = 19
and v.code_bakasha_detail in (5,13)
and v.mispar_zehut = p_mispar_zehut;
  FunctionResult := v_max_date_end_zakaut;  
  return(FunctionResult);
exception when others then
  return(null);
end f_get_date_end_zakaut;
/

create or replace function prm_system_copy.f_get_documents(p_seq_bakasha in number, p_sug_gimlay in varchar2, p_from_date in varchar2) return number is
pragma autonomous_transaction;
v_code_sug_bakasha         number;
v_code_bakasha_detail      number;
v_code_group_prisha        number;
v_mispar_zehut             number;
v_cnt                      number;
v_date_hosafa              date := to_date(p_from_date,'YYYY-MM-DD HH24:MI:SS') + interval '30' minute;

begin
  --return 1;
  select DISTINCT v.code_sug_bakasha, v.code_bakasha_detail, v.mispar_zehut, n.code_group_prisha
  into v_code_sug_bakasha, v_code_bakasha_detail, v_mispar_zehut, v_code_group_prisha
  from v_bakasha_last_status v
  left join netuney_tik_mechushavim n on
  n.seq_bakasha = v.seq_bakasha
  and n.code_department = 2
  and n.mispar_misra = 0
  where v.seq_bakasha = p_seq_bakasha;
  if p_sug_gimlay = 'p' 
     and (v_code_sug_bakasha not in (1,8,5,3,7) 
     or  nvl(v_code_group_prisha,0) = 4) then
  return 0;
  end if;
  if p_sug_gimlay = 's'
     and (v_code_sug_bakasha not in (1,9,3,5,13,12,23)
     or nvl(v_code_group_prisha,0) <> 4) then
  return 0;
  end if;
  for r in (

    select db.seq_document
    from document_bakasha db
    left join document d on
    d.seq_document = db.seq_document
    left join code_document_type c on
    c.seq_document_type = d.seq_document_type
    where db.seq_bakasha = p_seq_bakasha
    --and d.date_update >= to_date('01/01/2022','dd/mm/yyyy')
    and instr(d.document_url,'mofgimlaot',1) = 0
    and instr(d.document_url,'\\',1) > 0
    and c.is_external in (0,1)
    and db.pail = 1
    )
    loop
       select count(*)
       into v_cnt
       from sf_add_document s
       where s.mispar_zehut = v_mispar_zehut
       and   s.seq_document = r.seq_document;
       --and   s.taarich_hosafa = v_date_hosafa;
       if v_cnt > 0 then
         delete
         from sf_add_document s
         where s.mispar_zehut = v_mispar_zehut
         and   s.seq_document = r.seq_document;
         commit;
       end if;
       insert into sf_add_document
        (mispar_zehut,
         seq_document,
         taarich_hosafa,
         from_date,
         seq_bakasha)
       values
        (v_mispar_zehut,
        r.seq_document,
        --to_date(p_from_date,'YYYY-MM-DD HH24:MI:SS') + interval '30' minute
        sysdate,
        --v_date_hosafa,
        p_from_date,
        p_seq_bakasha
        );
       
       commit;
 end loop;
return (1);
end;
/

create or replace function prm_system_copy.f_get_handler_crm(p_seq_bakasha in number, p_code_status_pniyat_crm in number) return number is
 v_handler number;
 v_max_seq_action_log number;
begin
  select max(a.seq_action_log)
  into v_max_seq_action_log
  from action_log a
  left join code_action c on
  c.code_action = a.code_action
  where a.seq_bakasha = p_seq_bakasha
  and (p_code_status_pniyat_crm = 2 and nvl(c.code_status_pniyat_crm,0)in (1,2) 
   or  p_code_status_pniyat_crm = 4 and nvl(c.code_status_pniyat_crm,0) = 4);
  
  if v_max_seq_action_log is not null then
    select a1.code_user_to_internal
    into v_handler
    from action_log a1
    where a1.seq_action_log = v_max_seq_action_log;
    --return v_handler;
    return(case when v_handler = 1855 then 168 
                when v_handler = 1795 then 144
                when v_handler = 2715 then 168 
                when v_handler = 2775 then 144  
                when v_handler = 2735 then 168  
                when v_handler = 2835 then 168
                when v_handler = 2395 then 168
                when v_handler = 2635 then 144                    
                when v_handler = 2855 then 168
                when v_handler = 795  then 168
                when v_handler = 2875 then 168                                                    
                when v_handler = 2575 then 168  
                when v_handler = 3015 then 168
                when v_handler = 1296 then 144 
                when v_handler = 2595 then 168 
                when v_handler = 2975 then 144  
                when v_handler = 3155 then 144  
                when v_handler = 3215 then 144  
                when v_handler = 3275 then 168  
                when v_handler = 2756 then 160
                when v_handler = 3475 then 355 
                when v_handler = 3555 then 168  
                when v_handler = 3335 then 168
                when v_handler = 151  then 119
                when v_handler = 3595 then 168
                when v_handler = 2492 then 144
                when v_handler = 2492 then 144
                when v_handler = 3655 then 455
                when v_handler = 2416 then 163
                when v_handler = 3715 then 455
                when v_handler = 3035 then 118
                when v_handler = 3455 then 168                
                when p_seq_bakasha in (
                  619569,620299,620424,619662,617416,619700,619669) and p_code_status_pniyat_crm = 4 then 164     
                else v_handler end);
  else
    return null;
    --return (case when p_code_status_pniyat_crm = 2 then 0 else null end);
  end if;
  
end f_get_handler_crm;
/

create or replace function prm_system_copy.f_get_more_details_for_bakasha(p_seq_bakasha in number
                                             --   ,p_status out number,
                                              ---  p_ora_message out varchar2
                                               ) return varchar2 is
v_code_sug_bakasha number(2);
v_code_bakasha_detail  number(2);
v_teur_bakasha_detail varchar2(100);
v_remarks varchar2(1000);
v_seq_porshim number(10);
begin
  -- p_seq_bakasha=310195
  -- p_status := 1; --הצלחה
  --  p_ora_message := '';
   v_remarks:='';
   v_teur_bakasha_detail:='';
  select ls.code_sug_bakasha,ls.code_bakasha_detail,tb.teur_bakasha_detail    ,ls.seq_porshim
  into  v_code_sug_bakasha,v_code_bakasha_detail,v_teur_bakasha_detail,v_seq_porshim
  from v_bakasha_last_status ls
  left join code_bakasha_detail tb
   on ls.code_bakasha_detail=  tb.code_bakasha_detail
      where ls.seq_bakasha = p_seq_bakasha;
 --- and b.seq_bakasha =153520

if v_code_sug_bakasha in(7,8,9,23) then    -----גופים
 for r in (
       select cop.teur_ezor_ovdim||' '
       ||to_char(p.percent_participate)||
        case when (p.percent_participate is  NOT null AND p.percent_participate >0) then
        '%'      end
       ||case when (p.chodshey_arai is  NOT null and p.chodshey_arai>0) then
          'חודשי ארעי'
      end
       ||to_char(p.chodshey_arai) remark1
        from participation p ,code_ezor_ovdim cop
         where seq_bakasha = p_seq_bakasha
           and p.seq_guf(+)= cop.seq_ezor_ovdim)
            loop
              if  v_remarks is not null
               then
                 v_remarks := v_remarks ||', ';
               end if;
                  v_remarks  := v_remarks || r.remark1;
            end loop;
 return v_teur_bakasha_detail||' '||v_remarks;
elsif  v_code_sug_bakasha =12 then  --- חסכון פנסיוני
  select
   'סוג פרישה:'  ||
       case when (br.hp_status_prisha is null or br.hp_status_prisha=0) then 'פעיל'
         else case when br.code_seif_prisha <> 315 then(g.teur_group_prisha)else 'נכות'end
       end
     ||
     case when (br.hp_taarich_psak_din is null or c.code_action=0) then '' else ' פס"ד:'
       ||case when br.hp_taarich_psak_din < to_date('06/02/2015','DD/MM/YYYY')
          then 'ישן' else 'חדש'  end
      end
     ||' שיעור העברה:'
     ||to_char(br.hp_sheur_havara)||'%'
     into v_remarks
from bakasha b
     ,bakasha_regila br
     ,v_bakasha_last_status ls
     ,code_action c
     ,code_group_prisha g
where
       b.seq_bakasha =p_seq_bakasha
  ---  b.seq_bakasha =153520
and  b.seq_bakasha = br.seq_bakasha
and b.seq_bakasha = ls.seq_bakasha
and c.code_action=ls.code_action
and br.hp_status_prisha =g.code_group_prisha;
 v_remarks := v_teur_bakasha_detail||v_remarks ;
return  v_remarks;
elsif  v_code_sug_bakasha =13 then  ---שארים
 for r in (select bml.shem_prati || cr2.teur_relative||' '||
  to_char(bml.achuz_kizba)||
  case when (bml.achuz_kizba is not null and bml.achuz_kizba >0) then unistr('\0025')
    end remark1
---  into v_remarks
  from bney_mishpacha bml
  left join code_relative cr2
  on bml.code_relative = cr2.code_relative
  and cr2.pail=1
  where
    bml.seq_porshim = v_seq_porshim
    and bml.TAARICH_Ptira is not null
    and sysdate >= bml.TO_DATE_SIUM_ZAKAUT
   and bml.CODE_KIRVA <> 99)
     loop
              if  v_remarks is not null
               then
                 v_remarks := v_remarks ||', ';
               end if;
                  v_remarks  := v_remarks || r.remark1;
            end loop;
 return v_teur_bakasha_detail||' '||v_remarks;

 v_remarks :=v_teur_bakasha_detail ||' '||v_remarks;
  return v_remarks;

 elsif  v_code_sug_bakasha =21 then  -- שינוי כתובת
    select t.ktovet ||' '||ci.teur_ir || ' ' ||t.mikud
    into v_remarks
    from v_address_poresh t
    left join code_ir ci
     on t.code_city= ci.code_ir
    where t.seq_bakasha =p_seq_bakasha;
    v_remarks :=v_teur_bakasha_detail ||' '||v_remarks;
   return v_remarks;
   elsif  v_code_sug_bakasha =15 then  --שינוי בנק
  select cb.teur_bank||', '||csb.teur_snif_bank||', '||to_char( account_number)
  into v_remarks
  from bank_account ba
  left join code_bank cb on
  ba.code_bank=cb.code_bank
  left join code_snif_bank csb on
  ba.code_bank=csb.code_bank
  and ba.code_snif= csb.code_snif_bank
  where ba.seq_bakasha =p_seq_bakasha;
   v_remarks :=v_teur_bakasha_detail ||' '||v_remarks;
  return v_remarks;
   elsif  v_code_sug_bakasha =16 then  --יוון
   select to_char(achuz_hivun)
   into v_remarks
   from hivun h
  where h.seq_bakasha =p_seq_bakasha;
    if  v_remarks is not null then
      v_remarks:= 'אחוז היוון- ' ||v_remarks ;
    end if;
     v_remarks :=v_teur_bakasha_detail ||' '||v_remarks;
  return v_remarks;
elsif  v_code_sug_bakasha =17 then---השתכרות
select 'מתאריך: '||to_char(h.from_date,'DD/MM/YYYY')||to_char(' עד תאריך: ')
||to_char(h.to_date,'DD/MM/YYYY')
||' גוף: '||c.TEUR_EZOR_OVDIM
into v_remarks
from hachnasot h
left join code_ezor_ovdim c on
h.seq_ezor_ovdim=c.seq_ezor_ovdim
where H.seq_bakasha =p_seq_bakasha;
     v_remarks :=v_teur_bakasha_detail ||' '||v_remarks;
  return v_remarks;
 Elsif  v_code_sug_bakasha =18 then--גמלאות כפל
 select 'גוף: '||c.teur_ezor_ovdim|| ' סכום: '||TO_CHAR( p.sum,'9999999G999')||' אחוז: '
||TO_CHAR(p.achuz_guf_final)
into v_remarks
from participation p
left join code_ezor_ovdim c on
p.seq_guf=c.seq_ezor_ovdim
where p.seq_bakasha =p_seq_bakasha;
     v_remarks :=v_teur_bakasha_detail ||' '||v_remarks;
  return v_remarks;
  ---
 elsif  v_code_sug_bakasha =14 then  --- שינוי שכר
 select 'משכורת קובעת: '|| to_char(ns.maskoret_kovaat)||' דירוג: '||cde.teur_derug||' דרגה: ' ||cda.teur_darga
 into v_remarks
from netuney_sachar ns
   left join code_derug cde
   on ns.code_derug=cde.code_derug
   left join code_darga cda
  on ns.code_darga=cda.code_darga
   and ns.code_derug=cda.code_derug
   where ns.seq_bakasha=p_seq_bakasha
   and ns.mispar_misra=0
   and ns.code_sug_maskoret=1;
   v_remarks :=v_teur_bakasha_detail||' ' ||v_remarks;
  return v_remarks;
    ---
   elsif  v_code_sug_bakasha =19 or v_code_sug_bakasha =20  then  --- הפסקת תשלום/חידוש תשלום
 select b.remarks
  into v_remarks
 from bakasha b
   where b.seq_bakasha=p_seq_bakasha;
   v_remarks :=v_teur_bakasha_detail||' ' ||v_remarks;
  return v_remarks;

else    v_remarks :=v_teur_bakasha_detail||' ' ||v_remarks;
  return v_remarks;
 end if;
 exception
   when others then
 --  p_status  := 0;
 -- p_ora_message := sqlerrm;
  return (null);
end;
/

create or replace function prm_system_copy.f_get_seq_bakasha_sachar(p_gimla_number in number) return number is
  FunctionResult number;
begin
  select max(v.seq_bakasha)
  into FunctionResult
  from v_bakasha_last_status v
  where v.gimla_number = p_gimla_number
  and v.code_action <> 17
  and exists
  (select 1
  from netuney_sachar n
  where n.seq_bakasha = v.seq_bakasha);
  return FunctionResult;
end;
/

create or replace function prm_system_copy.f_get_seq_bakasha_zakaut(p_gimla_number in number,p_sug_gimlay in varchar2) return number is
  FunctionResult number;
begin
  select max(v.seq_bakasha)
  into FunctionResult
  from v_bakasha_last_status v
  where v.gimla_number = p_gimla_number
  and v.code_sug_bakasha in (1,3,5,13)
  and v.code_action in (98,129,130)
  and exists
  (select 1
  from netuney_tik_mechushavim n
  where n.seq_bakasha = v.seq_bakasha
  and n.code_department = 2
  and (p_sug_gimlay = 'poresh' and nvl(n.code_group_prisha,0) < 4
    or p_sug_gimlay = 'sheer'  and nvl(n.code_group_prisha,0) = 4));
  return FunctionResult;
end;
/

create or replace function prm_system_copy.f_get_seq_bakasha_zakaut_test(p_gimla_number in number,p_sug_gimlay in varchar2) return number is
  FunctionResult number;
begin
select max(seq_bakasha)
into FunctionResult
from
     (select seq_bakasha , gimla_number, row_number() over (partition by seq_bakasha
                                                               order by seq_bakasha desc) as rn
     from v_bakasha_last_status v
     where v.gimla_number = p_gimla_number
     and v.code_sug_bakasha in (1,3,5,13)
     and v.code_action in (98,129,130)
     and exists
      (select 1
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v.seq_bakasha
      and n.code_department = 2
      and (p_sug_gimlay = 'poresh' and nvl(n.code_group_prisha,0) < 4
        or p_sug_gimlay = 'sheer'  and nvl(n.code_group_prisha,0) = 4))
      ) where rn = 1;
  return FunctionResult;
end;
/

create or replace function prm_system_copy.f_get_shem(p_mispar_zehut number, p_sug_shem number) return varchar2 is
  v_shem varchar2(30);
begin
select sel.shem
into v_shem
from
(select 1 sug, case when p_sug_shem = 1 then t.shem_prati else t.shem_mishpacha end shem
from poresh t
where t.mispar_zehut = p_mispar_zehut
union
select 2 sug, case when p_sug_shem = 1 then t.shem_prati else t.shem_mishpacha end shem
from bney_mishpacha t
where t.mispar_zehut_ben_mishpacha = p_mispar_zehut
order by 1) sel
where rownum = 1;
return v_shem;
    exception
    when others then
    return (null);
end;
/

create or replace function prm_system_copy.f_get_taarich_prisha(p_seq_prisha number) return date is

  v_date_prisha date;
begin
select max(br1.taarich_prisha)
into v_date_prisha
from prisha pr1, bakasha b1, bakasha_regila br1
where b1.seq_prisha = pr1.seq_prisha
and br1.seq_bakasha = b1.seq_bakasha
and b1.code_sug_bakasha = 1
and pr1.seq_prisha = p_seq_prisha;
return v_date_prisha;
    exception
    when others then
    return (null);
end;
/

create or replace function prm_system_copy.f_is_hospital(p_seq_ezor_ovdim in number) return number is
  v_is_hospital  number;
begin
  v_is_hospital:=0 ;
  select case when INSTR(t.teur_ezor_ovdim, 'בית חולים') =
  1 
    or   INSTR(t.teur_ezor_ovdim,'ביה"ח' )
    =1 
 then 1 else  0 end 
  into v_is_hospital
  from code_ezor_ovdim t
  where t.seq_ezor_ovdim=p_seq_ezor_ovdim;

  return(v_is_hospital );

end ;
/

create or replace function prm_system_copy.f_is_to_hilan(p_seq_bakasha in number) return number is
  v_is_hilan  number;
  v_code_sug_bakasha number;
  v_code_bakasha_detail number;
  v_code_e_zakaut number;
begin
  v_is_hilan:=1 ;
  select ls.code_sug_bakasha,ls.code_bakasha_detail,n.code_e_zakaut
  into  v_code_sug_bakasha,v_code_bakasha_detail,v_code_e_zakaut
  from v_bakasha_last_status ls
  left  join netuney_tik_mechushavim n on n.seq_bakasha=ls.seq_bakasha and n.mispar_misra=0 and n.code_department=2
  where ls.seq_bakasha=p_seq_bakasha;
  -------------------
  --השתתפות מגוף העברת כספים
  if( v_code_sug_bakasha in(7,23) and v_code_bakasha_detail  in (26,40)) or     
  -- חסכון פנסיוני דחיה
    ( v_code_sug_bakasha=12       and nvl(v_code_e_zakaut,0)=0)   
  then  v_is_hilan:=0; end if;
  return(v_is_hilan);

end ;
/

create or replace function prm_system_copy.f_mispar_bakashot(p_month in varchar2) return number is
  FunctionResult number;
begin
  select count(*)
  into FunctionResult
  from
(select distinct t1.seq_bakasha
from ld_log_events t1
where to_char(t1.date_create,'YYYYMM') = p_month
and exists
(select t11.seq_bakasha
from ld_log_events t11
where t11.seq_bakasha = t1.seq_bakasha
and t11.code_record_level is not null));
  return(FunctionResult);
end f_mispar_bakashot;
/

create or replace function prm_system_copy.f_mispar_events(p_month in varchar2) return number is
  FunctionResult number;
begin
  select count(*)
  into FunctionResult
  from
(select distinct t1.code_event, t1.code_event_semel, t1.seq_bakasha
from ld_log_events t1
where to_char(t1.date_create,'YYYYMM') = p_month
and exists
(select t11.seq_bakasha
from ld_log_events t11
where t11.seq_bakasha = t1.seq_bakasha
and t11.code_record_level is not null));
  return(FunctionResult);
end f_mispar_events;
/

create or replace function prm_system_copy.f_street(p_seq_address number,p_street varchar2 := ' ') return varchar2 is
  v_street varchar2(50);
begin
if p_seq_address <> 0 then
select case when a.house is not null then trim(a.street) || ' ' || to_char(a.house) ||
case when a.apartment is null then '' else '/' || to_char(a.apartment) end ||
case when a.entrance is null then '' else ' ' || trim(a.entrance) end
else a.street end
into v_street
from address a
where a.seq_address = p_seq_address;
else
v_street := p_street;
end if;
v_street := replace(v_street,
'רחוב '
,''
);
v_street := replace(v_street,
'רח'''
,'רח '
);
v_street := replace(v_street,'רח ',''
);
v_street := replace(v_street,
'שדרות '
,''
);
v_street := replace(v_street,
'שד'''
,'שד '
);
v_street := replace(v_street,'שד ',''
);
v_street := replace(v_street,
'ת.ד.'
,'תד '
);
v_street := replace(v_street,
'ת.ד'
,'תד '
);
v_street := replace(v_street,
'ת"ד'
,'תד '
);
v_street := replace(v_street,
'ת ד'
,'תד '
);
v_street := replace(v_street,'"','');
v_street := replace(v_street,'  ',' ');

return trim(v_street);
end;
/

CREATE OR REPLACE FUNCTION PRM_SYSTEM_COPY."HEBSOUNDEX" (srcStr in varchar2) return varchar2
is
   type arr1 is varray(265) of varchar2(1);
   type arr2 is varray(500) of varchar2(1);
   trans arr1 := arr1();
   mish arr2 := arr2();
   i number; j number;
   nxt varchar2(1);
   temp varchar2(1000);
   prv varchar2(1);

begin

  if srcStr is null then
     temp := srcStr;
     goto endFunc;
  end if;
  trans.extend(265);
  mish.extend(500);
  trans(65) := 'ש';
  trans(66) := 'נ';
  trans(67) := 'ב';
  trans(68) := 'ג';
  trans(69) := 'ק';
  trans(70) := 'כ';
  trans(71) := 'ע';
  trans(72) := 'י';
  trans(73) := 'ן';
  trans(74) := 'ח';
  trans(75) := 'ל';
  trans(76) := 'ך';
  trans(77) := 'צ';
  trans(78) := 'מ';
  trans(79) := 'ם';
  trans(80) := 'פ';
  trans(59) := 'ף';
  trans(82) := 'ר';
  trans(83) := 'ד';
  trans(84) := 'א';
  trans(85) := 'ו';
  trans(86) := 'ה';
  trans(46) := 'ץ';
  trans(88) := 'ס';
  trans(89) := 'ט';
  trans(90) := 'ז';
  trans(44) := 'ת';
  trans(97) := 'ש';
  trans(98) := 'נ';
  trans(99) := 'ב';
  trans(100) := 'ג';
  trans(101) := 'ק';
  trans(102) := 'כ';
  trans(103) := 'ע';
  trans(104) := 'י';
  trans(105) := 'ן';
  trans(106) := 'ח';
  trans(107) := 'ל';
  trans(108) := 'ך';
  trans(109) := 'צ';
  trans(110) := 'מ';
  trans(111) := 'ם';
  trans(112) := 'פ';
  trans(114) := 'ר';
  trans(115) := 'ד';
  trans(116) := 'א';
  trans(117) := 'ו';
  trans(118) := 'ה';
  trans(120) := 'ס';
  trans(121) := 'ט';
  trans(122) := 'ז';
  i := Length(srcStr);
  temp := srcStr;
  for x in 1..i
  loop
   j:= ascii(Substr(temp, 1, 1));
   --j := Ascii(Left(temp, 1));
   If j > 223 Then
    mish(x) := Substr(temp, 1, 1);
   Else
      If j < 65 and j != 44 And j != 46 And j != 59 Then
         mish(x) := Substr(temp, 1, 1);
       Else
           mish(x) := trans(j);
       End if;
   End If;
   temp := Substr(temp,2);
   --temp := Right(temp, i - x);
  end loop;
     If (mish(1) = '%') Then goto lbl73; end if;
     If (mish(1) < 'א') or (mish(1) > 'ת') Then mish(1) := ' '; end if;
     If (mish(1) = 'ה') Or (mish(1) = 'ע') Then mish(1) := 'א'; end if;
     If (mish(1) = 'ו') Then mish(1) := 'ב'; end if;

  <<lbl73>>
      nxt := ' ';
  for x in 2..i
  loop
       prv := mish(x - 1);
       nxt := mish(x + 1);
       If mish(x) = ' ' Or mish(x) = '-' Or mish(x) = ',' Then
          mish(x) := '$';
       end if;
       If prv != '$' Then GoTo lbl74; end if;
         If mish(x) = 'ע' Or mish(x) = 'ה' Then
           mish(x) := 'א';
         End If;
      GoTo lbl75;
  <<lbl74>>
     If mish(x) = 'א' Or mish(x) = 'י' Or mish(x) = 'ע' Or mish(x) = 'ה' Then mish(x) := ' '; end if;
  <<lbl75>>
     If mish(x) = '%' Or mish(x) = '$' Then GoTo lbl76; end if;
     If (mish(x) < 'א') Or (mish(x) > 'ת') Then mish(x) := ' '; end if;
  <<lbl76>>
     If (mish(x) = 'ו') And (nxt = 'י') Then mish(x) := 'ב'; end if;
     If (mish(x) = 'ו') Then mish(x) := ' ';end if;
  end loop;
  For x in 1..i
  loop
    If x <> 1 Then prv := mish(x - 1); end if;
    if mish(x)='פ' then mish(x) := 'ב';
    elsif mish(x)='ף' then mish(x) := 'ב';
    elsif mish(x)='ק' then mish(x) := 'כ';
    elsif mish(x)='ך' then mish(x) := 'כ';
    elsif mish(x)= 'ם' then mish(x) := 'מ';
    elsif mish(x)='צ' then mish(x) := 'ס';
    elsif mish(x)='ץ' then mish(x) := 'ס';
    elsif mish(x)='ז' then mish(x) := 'ס';
    elsif mish(x)='ש' then mish(x) := 'ס';
    elsif mish(x)='ן' then mish(x) := 'נ';
    elsif mish(x)='ט' then mish(x) := 'ת';
    End if;
    If (x > 1) And (prv != '$') And (mish(x) = 'ח') Then mish(x) := 'כ'; end if;
  end loop;
  temp := '';
  For x in 1..i
  loop
   If mish(x) = '$' Then
    temp := temp || ' ';
   Elsif mish(x) != ' ' Then temp := temp || mish(x);
   End If;
  end loop;
<<endFunc>>
  return(temp);
end hebSoundex;
/

create or replace function prm_system_copy.hilan_get_mpm_code_mazav_mishpachti(v_mazav_mishpachti varchar2) return number is
  FunctionResult number;
begin
  
  return case when v_mazav_mishpachti = 'רווק ' then 0 
    when v_mazav_mishpachti = 'רווקה' then 0
     when v_mazav_mishpachti = 'רווקה' then 0
       when v_mazav_mishpachti =  'נשוי' then 1
         when v_mazav_mishpachti =  'נשואה' then 1
           when v_mazav_mishpachti =  'אלמן' then 2
             when v_mazav_mishpachti =  'אלמנה' then 2
               when v_mazav_mishpachti =  'גרוש' then 3
                 when v_mazav_mishpachti =  'גרושה' then 3
      else 999 end;
end hilan_get_mpm_code_mazav_mishpachti;
/

