create or replace function prm_system_copy.replace_tz(p_str in varchar2) return varchar2 is
  ll integer;
  len number;
  str varchar2(500);
begin
  ll := 0;
  len := length(p_str);
  str := p_str;
  for i in 1..len
  loop
    if substr(str,i,1) between '0' and '9' then
      if ll > 0 then
        ll := ll + 1;
      else
        ll := 1;
      end if;
    else
      if ll >= 6 then
        str := substr(str,1,i-ll-1) || pk_hilan_prd.lpad_zeroez(0,ll) || substr(str,i);
        ll := 0;
       end if;
      ll := 0;
    end if;
  end loop;
  if ll>= 6 then
        str := substr(str,1,length(str)-ll-1) || pk_hilan_prd.lpad_zeroez(0,ll);
  end if;
  return(str);
end ;
/

create or replace function prm_system_copy.update_tkufot_avoda_mehushv(v_id number) return boolean is
    v_seq_tkufot_avoda_mechushv number;
    v_code_sugey_tkufot         number;
    v_code_sugey_zchuyot        number;
    v_tafkid_meuhad             number;
    v_is_kana_zchuyot           number;
    v_keren                     number;
    v_achuz_mugdal              number;
    v_achuz_chelkyut            number;
    v_except_from_tkufa         number;
    v_seq_bakasha number;
  begin
  select v.SEQ_BAKASHA
  into v_seq_bakasha
  from v_regila_last_status v
  where v.MISPAR_ZEHUT = v_id;  
  
    delete from err_tkufot_avoda_mechushv t;

    delete from tkufot_avoda_mechushv t
     where t.seq_bakasha = v_seq_bakasha;

    for r in (select *
                from tkufot_magal t
               where t.zehut = v_id) loop
      if (r.helkiut > 999.99) then
        v_achuz_chelkyut := null;
      else
        v_achuz_chelkyut := trunc(r.helkiut, 2);
      end if;

      if (r.lemaet_tkufa > 999.99) then
        v_except_from_tkufa := null;
      else
        v_except_from_tkufa := trunc(r.lemaet_tkufa, 2);
      end if;

      if (r.basis_gimla > 999.99) then
        v_achuz_mugdal := null;
      else
        v_achuz_mugdal := trunc(r.basis_gimla, 2);
      end if;
      v_is_kana_zchuyot           :=convert_data_mgl_2_mpm_logist.convert_0_or_1_number(r.is_kana_zchuyot);
      v_seq_tkufot_avoda_mechushv := tkufot_avoda_mechushav_seq.nextval;
      v_keren                     := convert_data_mgl_2_mpm_logist.convert_0_or_1_number(r.is_took_money_m_keren);
      v_code_sugey_zchuyot        := convert_data_mgl_2_mpm_logist.convert_code_sugey_zchuyot(trim(r.kd_zchuyot));
      v_code_sugey_tkufot         := convert_data_mgl_2_mpm_logist.convert_code_sugey_tkufot(trim(r.kd_tkufa));
      v_tafkid_meuhad             := convert_data_mgl_2_mpm_logist.convert_0_or_1(r.kd_tafkid_meyuhad); ---!!!!!!!!!!!!!!!!!!!שונה מהאיפיון
      insert into tkufot_avoda_mechushv
        (shanim,
         chodashim,
         yamim,
         seq_tkufot_avoda_mechushv,
         taarich_me,
         code_sugey_tkufot,
         taarich_ad,
         code_sugey_zchuyot,
         achuz_chelkyut,
         haim_kana_zchuyot,
         code_takanon_magal,
         seq_bakasha,
         is_took_money_m_keren,
         except_from_tkufa,
         achuz_mugdal,
         code_achuz_mugdal)
      values
        (r.shanim,
         r.chodashim,
         r.yamim,
         v_seq_tkufot_avoda_mechushv,
         r.date_start,
         v_code_sugey_tkufot,
         decode((r.date_end - r.date_start) -
                abs(r.date_end - r.date_start),
                0,
                r.date_end,
                null),
         v_code_sugey_zchuyot,
         v_achuz_chelkyut,
         v_is_kana_zchuyot,
         to_number(trim(r.kd_takanon)),
         v_seq_bakasha,
         v_keren,
         v_except_from_tkufa,
         v_achuz_mugdal,
         to_number(trim(r.kd_tafkid_meyuhad))) log errors into err_tkufot_avoda_mechushv
         reject limit unlimited;

    end loop;
    if pk_load_mimshak.count_rowes('err_tkufot_avoda_mechushv') > 0 then
      rollback;
      return false;
    else
      commit;
      return true;
    end if;
  end;
/

create or replace function prm_system_copy.vp_mesimot_fnc_num_to_time_str
(p_num varchar2) return varchar2 is
  shaa number;
  dakot number;
  dakot_str varchar2(6);

begin
  shaa:= trunc(p_num,0);
  dakot:= mod(p_num,1)*60;
  if dakot=0 then
    dakot_str:='00';
  else
    if dakot <10 then
       dakot_str:='0'||trunc(dakot,0);
    else
       dakot_str:= trunc(dakot,0);
    end if;
  end if;
  return shaa||':'||dakot_str;
end ;
/

create or replace function prm_system_copy.vp_mesimot_fnc_time_str_to_num(p_time_str varchar2) return number is
  shaa number;
  dakot number;

begin
  shaa:= to_number(substr(p_time_str,1,2));
  dakot:= to_number(substr(p_time_str,3,2));
  if dakot > 0 then
    dakot:= 1/(60/to_number(substr(p_time_str,3,2)));
  end if;
  return shaa+dakot;
end ;
/

create or replace procedure prm_system_copy.create_maakav_history
as
-- Created on 29/13/2009 by ISYURII
  -- Local variables here
  au_table varchar2(50);
  dynamic_sql varchar2(32767);
  key_columns varchar2(500);
  key_columns_with_new varchar2(700);
  p_table_name varchar2(100);


begin
  -- Clean --
  au_table:='';
  p_table_name := upper('PORESH');
  p_table_name := upper(p_table_name);
  --key_columns_with_new:=':new.sIDURI,:new.PAIL,:new.id_divuach,:new.id_yechida,:new.id_yaad,:new.id_num';
key_columns_with_new:=':new.porshim_seq';
  key_columns:= ' porshim_seq';

  -- Create AU Table --
  select p_table_name || '_HIS'
  into au_table
  from dual;

  -- inserting --
  dynamic_sql :='create or replace trigger '|| au_table || '_TRG' ||chr(10) ||
              'after insert or update or delete on ' || p_table_name || chr(10) ||
              'for each row' || chr(10)||
              'begin'|| chr(10);


    -- Cols --
  for c in (
            select c.column_name  Col, c.comments comments
            from user_col_comments c
            where c.table_name = p_table_name
            order by c.column_name asc
          ) loop

  dynamic_sql :=dynamic_sql || 'if :old.'|| c.col || ' <> :new.' || c.col || ' then '|| chr(10) ||
              'insert into '|| au_table || chr(10)||
              '( ' || key_columns || ', date_change, shem_meadken_acharon, col_name , old_value , new_value)' || chr(10)||
              'values' || chr(10)||
              '(' || key_columns_with_new || ',sysdate, :new.shem_meadken_acharon,''' || c.comments || ''',:old.' || c.col || ',:new.' || c.col || ');' || chr(10);

  dynamic_sql :=dynamic_sql || 'end if;' || chr(10);

  end loop;


   -- close --
  dynamic_sql :=dynamic_sql || 'end;';

  /*execute immediate  dynamic_sql; */
  insert into prm_to_drop select '1' from dual;
  update prm_to_drop set col = dynamic_sql;
  COMMIT;


end;
/

create or replace procedure prm_system_copy.create_netunet_tik_ben_mishpacha_by_bney_mishpacha is
  v_seq_bakasha_last_zakaut     number;
  v_seq_netuney_tik_mechushavim number;
  v_code_relative               number;
  v_code_sug_bakasha            number;
  v_zehut_poresh                number;
  v_exists_record               number;

begin

  for r in (select t1.*, p.*, po.*
              from v_prisha_last_zakaut t
              left join netuney_tik_mechushavim t1
                on t."SEQ_BAKASHA_ZAKAUT" = t1.seq_bakasha
               and t1.code_department = 2
               and t1.mispar_misra = 0
              left join prisha p
                on p.seq_prisha = t."SEQ_PRISHA"
              left join poresh po
                on p.seq_poresh = po.porshim_seq
              left join prisha p_n
                on p.seq_poresh = p_n.seq_poresh
               and p.seq_prisha <> p_n.seq_prisha
             where t1.code_group_prisha = 4
               and t.is_exist_another_job = 0
               and p_n.seq_prisha is null) loop
    v_zehut_poresh := r.mispar_zehut;
    select v."SEQ_BAKASHA_ZAKAUT",
           t1.seq_netuney_tik_mechushavim,
           v.code_sug_bakasha
      into v_seq_bakasha_last_zakaut,
           v_seq_netuney_tik_mechushavim,
           v_code_sug_bakasha
      from table(fn_obj_prisha_last_zakaut_arr(pk_select_function.fn_prisha_poresh_header(v_seq_prisha => r.seq_prisha))) v
      left join netuney_tik_mechushavim t1
        on v."SEQ_BAKASHA_ZAKAUT" = t1.seq_bakasha
       and t1.code_department = 2
       and t1.mispar_misra = 0;
    begin
    
      if v_seq_netuney_tik_mechushavim is null and
         v_code_sug_bakasha in (19, 20) then
        insert into netuney_tik_mechushavim
          (seq_bakasha,
           seq_netuney_tik_mechushavim,
           code_department,
           mispar_misra)
        values
          (v_seq_bakasha_last_zakaut,
           netuney_tik_mechushavim_seq.nextval,
           2,
           0);
        select t1.seq_netuney_tik_mechushavim
          into v_seq_netuney_tik_mechushavim
          from netuney_tik_mechushavim t1
         where v_seq_bakasha_last_zakaut = t1.seq_bakasha
           and t1.code_department = 2
           and t1.mispar_misra = 0;
        /*else
        pk_zakaut.main(v_seq_bakasha_last_zakaut);*/
      end if;
    
      /* end if;*/
    exception
      when no_data_found then
        dbms_output.put_line(v_zehut_poresh || ',');
        continue;
    end;
  
    for b in (select *
                from bney_mishpacha bn
               where bn.seq_porshim = r.porshim_seq
                 and bn.code_relative is not null) loop
    
      v_code_relative := b.code_relative;
      if nvl(b.to_date_sium_zakaut, to_date('31122999', 'ddmmyyyy')) <
         sysdate then
        update bney_mishpacha tb
           set tb.code_relative = 9
         where tb.seq_bney_mishpacha = b.seq_bney_mishpacha;
      end if;
      begin
        insert into NETUNEY_TIK_BEN_MISHPACHA ntb
          (ntb.seq_netuney_tik_ben_mishpacha,
           ntb.seq_bney_mishpacha,
           ntb.seq_netuney_tik_mechushavim,
           ntb.date_start_zakaut,
           ntb.date_end_zakaut,
           ntb.code_relative,
           ntb.achuz_kizba_chuka,
           ntb.achuz_kizba,
           ntb.achuz_tosefet_chuka,
           ntb.achuz_tosefet)
        values
          (NETUNEY_TIK_BEN_MISHPACHA_SEQ.Nextval,
           b.seq_bney_mishpacha,
           v_seq_netuney_tik_mechushavim,
           r.date_start_zakaut,
           b.to_date_sium_zakaut,
           v_code_relative,
           b.achuz_kizba_chuka,
           b.achuz_kizba,
           b.achuz_tosefet,
           b.achuz_tosefet_sofi);
      exception
        when others then
          --          dbms_output.put_line(v_zehut_poresh || ',exists record');
          null;
          continue;
      end;
    end loop;
    commit;
  end loop;

end create_netunet_tik_ben_mishpacha_by_bney_mishpacha;
/

create or replace procedure prm_system_copy.data_duplication_136(p_seq_bakasha in number) is
v_code_sug_bakasha       number;
v_code_bakasha_detail    number;
v_seq_bakasha            number;
v_mispar_zehut           number;
v_mispar_zehut_to_hilan  number;
v_code_city              number;
v_mikud                  varchar2(10);
v_seq_poresh             number;
v_seq_bney_mishpacha     number;
v_street                 varchar2(30);
v_house                  number;
v_apartment              number;
v_seq_address            number;
v_mail                   varchar2(30);
v_mobile                 varchar2(10);

    procedure  add_to_table(p_seq number) is
    begin
     insert into data_duplication_136_table
            (seq_bakashat_av,
            seq,
            code_sug_bakashat_av,
            mispar_zehut,
            date_update,
            seq_data_duplication_136_table)
            values
            (p_seq_bakasha,
            p_seq,
            v_code_sug_bakasha,
            v_mispar_zehut_to_hilan,
            sysdate,
            data_duplication_136_table_seq.nextval);
    end;

  begin
    select bk.code_sug_bakasha, bk.seq_bakasha, bk.code_bakasha_detail, p.mispar_zehut
    into v_code_sug_bakasha, v_seq_bakasha, v_code_bakasha_detail, v_mispar_zehut
    from bakasha bk
    left join prisha pr on
    pr.seq_prisha = bk.seq_prisha
    left join poresh p on
    p.porshim_seq = pr.seq_poresh
    where bk.seq_bakasha = p_seq_bakasha;


    if v_code_sug_bakasha in (21,1,13) or v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25 then
    for r1 in
    (select a.code_city,
           a.mikud,
           a.seq_poresh,
           a.seq_bney_mishpacha,
           a.street,
           a.house,
           a.apartment
    into
           v_code_city,
           v_mikud,
           v_seq_poresh,
           v_seq_bney_mishpacha,
           v_street,
           v_house,
           v_apartment
    from address a
    where a.seq_bakasha = p_seq_bakasha
    ) loop
    select l.mispar_zehut
    into v_mispar_zehut_to_hilan
    from ld_log_events l
    where l.seq_bakasha = p_seq_bakasha
    and l.code_trigger = 2
    and l.code_event = 218;
    for r in
           (select p.porshim_seq
           from poresh p
           where p.mispar_zehut = to_number(v_mispar_zehut_to_hilan)
                 and p.porshim_seq <> nvl(v_seq_poresh,0)
           ) loop
           v_seq_address := address_seq.nextval;
           insert into address a1
            (a1.seq_bakasha,
             a1.code_address,
             a1.code_city,
             a1.mikud,
             a1.date_update,
             a1.code_user_update,
             a1.seq_address,
             a1.seq_poresh,
             a1.seq_bney_mishpacha,
             a1.street,
             a1.house,
             a1.apartment,
             a1.entrance,
             a1.house_letter,
             a1.seq_apotropus)
            values
            (null,
             2,
             v_code_city,
             v_mikud,
             sysdate,
             0,
             v_seq_address,
             r.porshim_seq,
             null,
             v_street,
             v_house,
             v_apartment,
             null,
             null,
             null);
             add_to_table(v_seq_address);
    end loop;
    for r in
           (select b.seq_bney_mishpacha
           from bney_mishpacha b
           where b.mispar_zehut_ben_mishpacha = to_number(v_mispar_zehut_to_hilan)
                 and b.seq_bney_mishpacha <> nvl(v_seq_bney_mishpacha,0)
           ) loop
           v_seq_address := address_seq.nextval;
           insert into address a1
            (a1.seq_bakasha,
             a1.code_address,
             a1.code_city,
             a1.mikud,
             a1.date_update,
             a1.code_user_update,
             a1.seq_address,
             a1.seq_poresh,
             a1.seq_bney_mishpacha,
             a1.street,
             a1.house,
             a1.apartment,
             a1.entrance,
             a1.house_letter,
             a1.seq_apotropus)
            values
            (null,
             2,
             v_code_city,
             v_mikud,
             sysdate,
             0,
             v_seq_address,
             null,
             r.seq_bney_mishpacha,
             v_street,
             v_house,
             v_apartment,
             null,
             null,
             null);
             add_to_table(v_seq_address);
    end loop;
    end loop;
    end if;

    if v_code_sug_bakasha = 33 then
     for r1 in
     (select l.mispar_zehut
     from ld_log_events l
     where l.seq_bakasha = p_seq_bakasha
     and l.code_trigger = 2
     and l.code_event = 298
     and exists
     (select 1
     from requests_crm rc
     where rc.seq_bakasha = p_seq_bakasha))
     loop

     v_mispar_zehut_to_hilan := r1.mispar_zehut;

     select rc.person_id, p.porshim_seq, bm.seq_bney_mishpacha
     into v_mispar_zehut, v_seq_poresh, v_seq_bney_mishpacha
     from requests_crm rc
     /*left join v_bakasha_last_status v on
     v.seq_bakasha = rc.seq_bakasha*/
     left join bakasha bk on
     bk.seq_bakasha = rc.seq_bakasha
     left join prisha pr on
     pr.seq_prisha = bk.seq_prisha
     left join poresh p on
     p.porshim_seq = pr.seq_poresh
     and p.mispar_zehut = v_mispar_zehut_to_hilan
     left join bney_mishpacha bm on
     bm.seq_porshim = pr.seq_poresh
     and bm.mispar_zehut_ben_mishpacha = v_mispar_zehut_to_hilan
     where rc.seq_bakasha = p_seq_bakasha;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if v_seq_bney_mishpacha is null then
       select p1.email, p1.mispar_zehut
       into v_mail, v_mispar_zehut_to_hilan
       from poresh p1
       where p1.porshim_seq = v_seq_poresh;
     else
       select b1.email, b1.mispar_zehut_ben_mishpacha
       into v_mail, v_mispar_zehut_to_hilan
       from bney_mishpacha b1
       where b1.seq_bney_mishpacha = v_seq_bney_mishpacha;
     end if;

     if v_mail is not null then

        for r in
           (select p.porshim_seq
           from poresh p
           where p.mispar_zehut = to_number(v_mispar_zehut_to_hilan)
                 --and p.porshim_seq <> nvl(v_seq_poresh,0)
           ) loop
           update poresh p
           set p.email = v_mail
           where p.porshim_seq = r.porshim_seq;
           add_to_table(r.porshim_seq);
        end loop;

        for r in
           (select b.seq_bney_mishpacha
           from bney_mishpacha b
           where b.mispar_zehut_ben_mishpacha = to_number(v_mispar_zehut_to_hilan)
                 --and b.seq_bney_mishpacha <> nvl(v_seq_bney_mishpacha,0)
           ) loop
           update bney_mishpacha b
           set b.email = v_mail
           where b.seq_bney_mishpacha = r.seq_bney_mishpacha;
           add_to_table(r.seq_bney_mishpacha);
       end loop;

     end if;
     end loop;
    end if;

    if v_code_sug_bakasha = 35 then

    for r1 in (
     select l.mispar_zehut
     from ld_log_events l
     where l.seq_bakasha = p_seq_bakasha
     and l.code_trigger = 2
     and l.code_event = 218
     ) loop

     v_mispar_zehut_to_hilan := r1.mispar_zehut;

     select rc.person_id, p.porshim_seq, bm.seq_bney_mishpacha
     into v_mispar_zehut, v_seq_poresh, v_seq_bney_mishpacha
     from requests_crm rc
     /*left join v_bakasha_last_status v on
     v.seq_bakasha = rc.seq_bakasha*/
     left join bakasha bk on
     bk.seq_bakasha = rc.seq_bakasha
     left join prisha pr on
     pr.seq_prisha = bk.seq_prisha
     left join poresh p on
     p.porshim_seq = pr.seq_poresh
     and p.mispar_zehut = v_mispar_zehut_to_hilan
     left join bney_mishpacha bm on
     bm.seq_porshim = pr.seq_poresh
     and bm.mispar_zehut_ben_mishpacha = v_mispar_zehut_to_hilan
     where rc.seq_bakasha = p_seq_bakasha;
     if v_seq_bney_mishpacha is null then
       select p1.pelephon, p1.mispar_zehut
       into v_mobile, v_mispar_zehut_to_hilan
       from poresh p1
       where p1.porshim_seq = v_seq_poresh;
      else
       select b1.pelephone, b1.mispar_zehut_ben_mishpacha
       into v_mobile, v_mispar_zehut_to_hilan
       from bney_mishpacha b1
       where b1.seq_bney_mishpacha = v_seq_bney_mishpacha;
      end if;

      if v_mobile is not null and to_number(pk_hilan_prd.get_telephone(v_mobile)) <> 0 then
      for r in
           (select p.porshim_seq
           from poresh p
           where p.mispar_zehut = to_number(v_mispar_zehut_to_hilan)
                 --and p.porshim_seq <> nvl(v_seq_poresh,0)
           ) loop
           update poresh p
           set p.pelephon = pk_hilan_prd.get_telephone(v_mobile)
           where p.porshim_seq = r.porshim_seq;
           add_to_table(r.porshim_seq);
       end loop;

       for r in
           (select b.seq_bney_mishpacha
           from bney_mishpacha b
           where b.mispar_zehut_ben_mishpacha = to_number(v_mispar_zehut_to_hilan)
                 --and b.seq_bney_mishpacha <> nvl(v_seq_bney_mishpacha,0)
           ) loop
           update bney_mishpacha b
           set b.pelephone = pk_hilan_prd.get_telephone(v_mobile)
           where b.seq_bney_mishpacha = r.seq_bney_mishpacha;
           add_to_table(r.seq_bney_mishpacha);
       end loop;
       end if;
    end loop;
    end if;

    --commit;
  end data_duplication_136;
/

create or replace procedure prm_system_copy.data_for_actuaria is
  v_vetek              number;
  v_hagdalot           number;
  v_seq_bakasha_zakaut number;
  v_taarich_prisha     date;
begin
  -- Test statements here
  for r in (select * from z_actuaria_hagdalot) loop
    begin
      select br.vetek, v1."SEQ_BAKASHA_ZAKAUT", v1.taarich_prisha
        into v_vetek, v_seq_bakasha_zakaut, v_taarich_prisha
        from v_bakasha_last_status v
        left join v_prisha_last_zakaut v1
          on v.seq_prisha = v1."SEQ_PRISHA"
        left join bakasha_regila br
          on v1."SEQ_BAKASHA_ZAKAUT" = br.seq_bakasha
       where to_number(r.zehut) = v.mispar_zehut fetch first 1 rows only;
      if v_vetek is null then
        select t.seniority
          into v_vetek
          from ld_mlm_18 t
         where t.identity_number = r.zehut
           and t.is_erased = 0
           and t.seniority_code = '01' fetch first 1 rows only;
      end if;
    exception
      when no_data_found then
        v_vetek := null;
    end;
    if v_seq_bakasha_zakaut is null then
      -- dbms_output.put_line('zehut is not exists ' || r.zehut);
      continue;
    end if;
    if v_taarich_prisha is null then
      dbms_output.put_line('date prisha missing ' || v_seq_bakasha_zakaut);
      continue;
    end if;
    pk_zakaut.calc_hagdalot(v_seq_bakasha_zakaut,
                            v_hagdalot,
                            0,
                            v_taarich_prisha);
    update z_actuaria_hagdalot
       set vetek = v_vetek, hagdalot = v_hagdalot
     where zehut = r.zehut;
    commit;
  
  end loop;
end;
/

create or replace procedure prm_system_copy.doch_bakarat_maanakim1(p_from_date date,
                      p_to_date   date default null,
                      cur         out sys_refcursor) is
  begin
    open cur for

    with m as
(select distinct v.seq_bakasha, cb.code_sug_bakasha code_sug_bakasha, cb.code_teur_bakasha teur_bakasha, v.mispar_zehut,
        v.seq_prisha, p.shem_prati || ' ' || p.shem_mishpacha shem, p.taarich_leda, v.taarich_prisha, v.seq_ezor_ovdim, c.teur_ezor_ovdim,
        ccr.teur_chinuch_reforma || ' - ' || ca.teur_chinuch_alterntive reforma,
        --case when ts1.seq_tosefot is not null then 'גמול מבחני בגרות' else null end gmul_mivchaney_bagrut,
        case when ts1.seq_tosefot is not null then ts1.sum else null end sum_mivchaney_bagrut,
        case when ts3.seq_tosefot is not null then ts3.sum else null end sum_mivchaney_bagrut_60,
        --case when ts2.seq_tosefot is not null then 'חינוך כיתה' else null end hinuch_kita,
        case when ts2.seq_tosefot is not null then ts2.sum else null end sum_hinuch_kita,
        case when ts4.seq_tosefot is not null then ts4.sum else null end sum_hinuch_kita_60,
        nm.achuz_kizba_sofi, nm.achuz_kizba_gil_60,
        /*case when cr.code_chinuch_alterntive <> 1 then */
        n.maskoret_kovaat
             /*else null end  */ maskoret_kovaat,
        case when cr.factor < 1 then cr.factor else null end factor,
        case when (cr.code_chinuch_alterntive = 1 and (ts1.seq_tosefot is not null or ts2.seq_tosefot is not null)) then
          case when n.maskoret_kovaat_sum is not null then n.maskoret_kovaat_sum
          else nvl(n.schar_ysod,0) +
                   (select sum(nvl(t.sum,0))
                    from tosefot t
                    where t.seq_netuney_sachar = n.seq_netuney_sachar
                   )
           end
         else null end  sachar_acharon,
        /*case when cr.code_chinuch_alterntive <> 1 then */n60.maskoret_kovaat
             /*else null end  */ maskoret_kovaat_legil_60,
                case when not(cr.code_chinuch_alterntive = 1 and (ts3.seq_tosefot is not null or ts3.seq_tosefot is not null)) then null
                else  nvl(n60.schar_ysod,0) +
                   (select sum(nvl(t60.sum,0))
                    from tosefot t60
                    where t60.seq_netuney_sachar = n60.seq_netuney_sachar
                   ) end sachar_aharon_legil_60,
        n.maskoret_kovaat_percent + nvl(n.maskoret_kovaat_shiur_miztaber,0) shiur_miztaber,
        n60.maskoret_kovaat_percent + nvl(n60.maskoret_kovaat_shiur_miztaber,0) shiur_miztaber_legil_60,
        --np.maskoret_kovaat maskoret_le_pizuim,
        n.havraa_days, n.sum_havraa, n.ramat_bigud, n.sum_bigud,
        case when nvl(ch.code_nimuk,0) in (7,17,11) then h.achuz_meushar else null end achuz_hagdala,
        v.code_seif_prisha,
        nm.tkufa_mezaka_medina_only,
        nm.tkufa_mezaka_sherut,
        nm.chelkiyut_sofit,
        case when v.code_seif_prisha = 215 then nm.chelkiyut_meshuklelet_sherut else null end  chelkiyut_legil_60,
        cmm.teur_mazav_mishpachti,
        case when p.code_min = 1 then 'זכר' else 'נקבה' end migdar,
        case when br.chinuch_mikzoa = 911 then 'גננת' else null end is_ganenet,
        cg.teur_group_prisha,
        --case when v.code_sug_bakasha <> 14 then nm.mispar_misra else n.mispar_misra end mispar_misra,
        nm.mispar_misra misra_zakaut,
        n.mispar_misra  misra_sachar,
        'הוראה' derug,
        v.date_action,
        v.gimla_number
from v_bakasha_last_status v
left join code_sug_bakasha cb     on cb.code_sug_bakasha = v.code_sug_bakasha
left join poresh p           on p.mispar_zehut = v.mispar_zehut
left join code_ezor_ovdim c  on c.seq_ezor_ovdim = v.seq_ezor_ovdim
left join netuney_tik_mechushavim nm on nm.seq_bakasha = v.seq_bakasha
                            and nm.code_department = 2
left join code_group_prisha cg on cg.code_group_prisha = nm.code_group_prisha
left join chinuch_reforma cr on cr.seq_bakasha = v.seq_bakasha
left join code_chinuch_alterntive ca on ca.code_chinuch_alterntive = cr.code_chinuch_alterntive
/*left join netuney_sachar np  on np.seq_bakasha = v.seq_bakasha
                             and np.code_sug_maskoret = 14
*/
left join code_sug_maskoret m on m.code_chinuch_alterntive = cr.code_chinuch_alterntive
                            and m.teur_sug_maskoret not like '%60%'
left join code_sug_maskoret m60 on m60.code_chinuch_alterntive = cr.code_chinuch_alterntive
                            and m60.teur_sug_maskoret like '%60%'
left join netuney_sachar n   on n.seq_bakasha = v.seq_bakasha
                            and n.seq_chinuch_reforma = cr.seq_chinuch_reforma
                            and n.code_sug_maskoret = m.code_sug_maskoret
                            and (nm.mispar_misra = nm.mispar_misra or v.code_sug_bakasha <> 1)
left join netuney_sachar n60 on n60.seq_bakasha  = v.seq_bakasha
                            and n60.seq_chinuch_reforma = cr.seq_chinuch_reforma
                            and n60.code_sug_maskoret = m60.code_sug_maskoret
                            and (n60.mispar_misra = nm.mispar_misra or v.code_sug_bakasha <> 1)
left join tosefot ts1       on ts1.seq_netuney_sachar = n.seq_netuney_sachar
                            and ts1.code_semel_tosefet in (13,41) --בחינות בגרות
left join tosefot ts2        on ts2.seq_netuney_sachar = n.seq_netuney_sachar
                            and ts2.code_semel_tosefet  in (31,108,190) --חינוך כיתה
left join tosefot ts3       on ts3.seq_netuney_sachar = n60.seq_netuney_sachar
                            and ts3.code_semel_tosefet in (13,41) --בחינות בגרות
left join tosefot ts4       on ts4.seq_netuney_sachar = n60.seq_netuney_sachar
                            and ts4.code_semel_tosefet  in (31,108,190) --חינוך כיתה
left join code_chinuch_reforma ccr on ccr.code_chinuch_reforma = cr.code_reforma
left join hagdala_nimuk h on h.seq_bakasha = v.seq_bakasha
left join code_hagdala_nimuk ch on ch.code_nimuk = h.code_nimuk
left join bakasha_regila br on br.seq_bakasha = v.seq_bakasha and br.chinuch_mikzoa = 911
left join (select seq_poresh, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
from (
     select seq_poresh, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
          , row_number() over (partition by seq_poresh
                               order by nvl(date_mazav_mishpachti,to_date('01/01/1900','dd/mm/yyyy')) desc, seq_mazav_mishpachti desc) as rn
     from mazav_mishpachti mm1
     where mm1.seq_bney_mishpacha is null
     /*and (nvl(mm1.seq_bakasha,0) = 0 or
     (select distinct first_value(al.code_action) over(partition by al.seq_bakasha order by al.seq_action_log desc)
        from action_log al
        left join code_action ca on
        ca.code_action = al.code_action
        where al.seq_bakasha = mm1.seq_bakasha
        and ca.is_status = 1
        ) in (98,129,130,212,41,42))*/)
where rn = 1) mm2                    on mm2.seq_poresh = p.porshim_seq
left join code_matsav_mishpachti cmm on cmm.code_mazav_mishpachti = mm2.code_mazav_mishpachti
where v.code_sug_bakasha in (1,3,5,14)
--and   v.taarich_prisha >= to_date('31/10/2023','dd/mm/yyyy')
and   (v.taarich_prisha <  last_day(p_from_date) or v.code_sug_bakasha = 14)
and exists


(select 1
from action_log a
where a.seq_bakasha = v.seq_bakasha
--and to_char(a.date_action,'mm/yyyy') = '11/2023'
and to_char(a.date_action,'mm/yyyy') = to_char(p_from_date,'mm/yyyy')
and a.code_action = 136)
and exists
  (select 1
  from v_bakasha_last_status v_1
  left join netuney_tik_mechushavim n_1 on n_1.seq_bakasha = v_1.seq_bakasha
  and n_1.code_department = 2
  where v_1.seq_prisha = v.seq_prisha
  and v_1.code_sug_bakasha = 1
  and v_1.code_action in (98, 129, 130)
  and n_1.is_zakai_lmaanak = 1)
--and   n.seq_netuney_sachar is not null
--and   (m.code_sug_maskoret = n.code_sug_maskoret or v.code_sug_bakasha <> 1)
and v.code_action not in (17,100)
and v.seq_ezor_ovdim = 206
--and cr.seq_chinuch_reforma is not null
--and not (v.code_sug_bakasha in (3,5) and nm.seq_bakasha is null or v.code_sug_bakasha not in (3,5) and n.seq_netuney_sachar is null)
union
select distinct v.seq_bakasha, cb.code_sug_bakasha code_sug_bakasha, cb.code_teur_bakasha teur_bakasha, v.mispar_zehut,
 v.seq_prisha, p.shem_prati || ' ' || p.shem_mishpacha shem, p.taarich_leda,
 v.taarich_prisha, v.seq_ezor_ovdim, c.teur_ezor_ovdim,
        null,
        --null,
        null,
        null,
        --null,
        null,
        null,
        nm.achuz_kizba_sofi,
        nm.achuz_kizba_gil_60,
        n.maskoret_kovaat,
        null,
        null,
        n60.maskoret_kovaat,
        null,
        null,
        null,
        --null,
        --np.maskoret_kovaat maskoret_le_pizuim,
        n.havraa_days, n.sum_havraa, n.ramat_bigud, n.sum_bigud,


/*        null,
        n.maskoret_kovaat,
        null,
        null,
        n60.maskoret_kovaat,
--        null,
        null,
        null,
        null,
        --np.maskoret_kovaat maskoret_le_pizuim,
        n.havraa_days, n.sum_havraa, n.ramat_bigud, n.sum_bigud,*/
        case when nvl(ch.code_nimuk,0) in (7,17,11) then h.achuz_meushar else null end achuz_hagdala,
        v.code_seif_prisha,
        nm.tkufa_mezaka_medina_only,
        nm.tkufa_mezaka_sherut,
        nm.chelkiyut_sofit,
        case when v.code_seif_prisha = 215 then nm.chelkiyut_meshuklelet_sherut else null end  chelkiyut_legil_60,
        cmm.teur_mazav_mishpachti,
        case when p.code_min = 1 then 'זכר' else 'נקבה' end migdar,
        case when nvl(br.chinuch_mikzoa,0) = 911 then 'גננת' else null end is_ganenet,
        cg.teur_group_prisha,
        --case when v.code_sug_bakasha <> 14 then nm.mispar_misra else n.mispar_misra end mispar_misra,
        nm.mispar_misra misra_zakaut,
        n.mispar_misra  misra_sachar,
        cd.teur_derug,
        v.date_action,
        v.gimla_number

         --,
        --nm.odef_sherut_chodashim
        /*,
        m.teur_sug_maskoret,
        m60.teur_sug_maskoret,
        n.seq_netuney_sachar,
        cr.seq_chinuch_reforma*/
from v_bakasha_last_status v
left join code_sug_bakasha cb     on cb.code_sug_bakasha = v.code_sug_bakasha
left join poresh p           on p.mispar_zehut = v.mispar_zehut
left join code_ezor_ovdim c  on c.seq_ezor_ovdim = v.seq_ezor_ovdim
left join netuney_tik_mechushavim nm on nm.seq_bakasha = v.seq_bakasha
                            and nm.code_department = 2
left join chinuch_reforma cr on cr.seq_bakasha = v.seq_bakasha
left join code_group_prisha cg on cg.code_group_prisha = nm.code_group_prisha
/*left join netuney_sachar np on np.seq_bakasha = v.seq_bakasha
                            and np.code_sug_maskoret = 14
*/
left join netuney_sachar n  on n.seq_bakasha = v.seq_bakasha
                            and n.code_sug_maskoret = 1
                            and (n.mispar_misra = nm.mispar_misra/* or v.code_sug_bakasha <> 1*/)
left join netuney_sachar n60 on n60.seq_bakasha  = v.seq_bakasha
                            and n60.code_sug_maskoret = 2
                            and (n60.mispar_misra = nm.mispar_misra/* or v.code_sug_bakasha <> 1*/)
left join hagdala_nimuk h   on h.seq_bakasha = v.seq_bakasha
left join code_hagdala_nimuk ch on ch.code_nimuk = h.code_nimuk
left join bakasha_regila br on br.seq_bakasha = v.seq_bakasha and br.chinuch_mikzoa = 911
left join code_derug cd     on cd.code_derug = n.code_derug
left join (select seq_poresh, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
from (
     select seq_poresh, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
          , row_number() over (partition by seq_poresh
                               order by nvl(date_mazav_mishpachti,to_date('01/01/1900','dd/mm/yyyy')) desc, seq_mazav_mishpachti desc) as rn
     from mazav_mishpachti mm1
     where mm1.seq_bney_mishpacha is null
     /*and (nvl(mm1.seq_bakasha,0) = 0 or
     (select distinct first_value(al.code_action) over(partition by al.seq_bakasha order by al.seq_action_log desc)
        from action_log al
        left join code_action ca on
        ca.code_action = al.code_action
        where al.seq_bakasha = mm1.seq_bakasha
        and ca.is_status = 1
        ) in (98,129,130,212,41,42))*/)
where rn = 1) mm2                    on mm2.seq_poresh = p.porshim_seq
left join code_matsav_mishpachti cmm on cmm.code_mazav_mishpachti = mm2.code_mazav_mishpachti
where v.code_sug_bakasha in (1,3,5,14)
--and   v.taarich_prisha >= to_date('31/10/2023','dd/mm/yyyy')
and   (v.taarich_prisha <  last_day(p_from_date) or v.code_sug_bakasha = 14)
and exists
(select 1
from action_log a
where a.seq_bakasha = v.seq_bakasha
--and to_char(a.date_action,'mm/yyyy') = '11/2023'
and to_char(a.date_action,'mm/yyyy') = to_char(p_from_date,'mm/yyyy')
and a.code_action = 136)
and exists
  (select 1
  from v_bakasha_last_status v_1
  left join netuney_tik_mechushavim n_1 on n_1.seq_bakasha = v_1.seq_bakasha
  and n_1.code_department = 2
  where v_1.seq_prisha = v.seq_prisha
  and (v_1.code_sug_bakasha = 1 or v_1.code_sug_bakasha = 5 and v_1.code_bakasha_detail = 25)
  and v_1.code_action in (98, 129, 130)
  and n_1.is_zakai_lmaanak = 1)
--and   n.seq_netuney_sachar is not null
and   v.seq_ezor_ovdim  not in (
13,
155,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
10154,
10149
)
and v.code_action not in (17,100)
--and not (v.code_sug_bakasha in(3,5) and nm.seq_bakasha is null or v.code_sug_bakasha not in (3,5) and n.seq_bakasha is null)
--and (v.seq_ezor_ovdim <> 206 or v.seq_ezor_ovdim = 206 and cr.seq_chinuch_reforma is null)
and v.seq_ezor_ovdim <> 206
)

select distinct
/*m3.seq_bakasha,
m4.seq_bakasha,
m5.seq_bakasha,
vm4.seq_bakasha,vm4.code_sug_bakasha,
vm5.seq_bakasha,vm5.code_sug_bakasha,*/
m3.teur_bakasha,
m3.mispar_zehut,
m3.shem,
m3.taarich_leda,
case when m5.seq_bakasha is null then m4.taarich_prisha else vm5.taarich_prisha end taarich_prisha,
m3.teur_ezor_ovdim,
m5.reforma,
m5.sum_mivchaney_bagrut,
m5.sum_mivchaney_bagrut_60,
m5.sum_hinuch_kita,
m5.sum_hinuch_kita_60,
case when m5.seq_bakasha is null then m4.achuz_kizba_sofi else nm5.achuz_kizba_sofi end achuz_kizba_sofi,
case when m5.seq_bakasha is null then m4.achuz_kizba_gil_60 else nm5.achuz_kizba_gil_60 end achuz_kizba_gil_60,
case when m5.maskoret_kovaat is null  or m5.seq_bakasha is null then ns4.maskoret_kovaat
/*     case when m3.seq_ezor_ovdim <> 206 then ns4.maskoret_kovaat
     else null end
*/
else m5.maskoret_kovaat end maskoret_kovaat,
--m5.maskoret_kovaat_legil_60,
case when m5.maskoret_kovaat_legil_60 is null or m5.seq_bakasha is null then ns4_60.maskoret_kovaat
/*     case when m3.seq_ezor_ovdim <> 206 then ns4_60.maskoret_kovaat
     else null end
*/
else m5.maskoret_kovaat_legil_60 end maskoret_kovaat_legil_60,
m5.factor,
m5.shiur_miztaber,
m5.shiur_miztaber_legil_60,
m5.sachar_acharon,
--m5.havraa_days,
case when m5.havraa_days is null or m5.seq_bakasha is null then ns4.havraa_days
/*     case when m3.seq_ezor_ovdim <> 206 then ns4.havraa_days
     else null end
*/
else m5.havraa_days end havraa_days,
--m5.sum_havraa,
case when m5.sum_havraa is null or m5.seq_bakasha is null then ns4.sum_havraa
/*     case when m3.seq_ezor_ovdim <> 206 then ns4.sum_havraa
     else null end
*/
else m5.sum_havraa end sum_havraa,
--m5.ramat_bigud,
case when m5.ramat_bigud is null or m5.seq_bakasha is null then ns4.ramat_bigud
/*     case when m3.seq_ezor_ovdim <> 206 then ns4.ramat_bigud
     else null end
*/
else m5.ramat_bigud end ramat_bigud,
--m5.sum_bigud,
case when m5.sum_bigud is null or m5.seq_bakasha is null then ns4.sum_bigud
/*     case when m3.seq_ezor_ovdim <> 206 then ns4.sum_bigud
     else null end
*/
else m5.sum_bigud end sum_bigud,
case when m5.seq_bakasha is null then m4.achuz_hagdala else case when nvl(ch5.code_nimuk,0) in (7,17,11) then h5.achuz_meushar else null end end achuz_hagdala,
case when m4.seq_bakasha is null then vm5.code_seif_prisha else m4.code_seif_prisha end code_seif_prisha,
case when m5.seq_bakasha is null then m4.tkufa_mezaka_medina_only else nm5.tkufa_mezaka_medina_only end tkufa_mezaka_medina_only,
case when m5.seq_bakasha is null then m4.tkufa_mezaka_sherut else nm5.tkufa_mezaka_sherut end tkufa_mezaka_sherut,
case when m5.seq_bakasha is null then m4.chelkiyut_sofit else nm5.chelkiyut_sofit end chelkiyut_sofit,
case when m5.seq_bakasha is null then m4.chelkiyut_legil_60 else case when vm5.code_seif_prisha = 215 then nm5.chelkiyut_meshuklelet_sherut else null end end chelkiyut_legil_60,
m3.teur_mazav_mishpachti,
m3.migdar,
case when m5.seq_bakasha is null then case when br5.chinuch_mikzoa = 911 then 'גננת' else null end else m4.is_ganenet end is_ganenet,
case when m5.seq_bakasha is null then cg5.teur_group_prisha else m4.teur_group_prisha end teur_group_prisha,
nvl(m5.misra_sachar,0) misra_sachar,
nvl(m4.misra_zakaut,0) misra_zakaut,
--m5.derug
case when m5.seq_bakasha is null then
     case when m3.seq_ezor_ovdim <> 206 then cd4.teur_derug
     else null end
else m5.derug end derug
from
(select
m1.*,
(select max(m2.seq_bakasha)
from m m2
where m2.mispar_zehut = m1.mispar_zehut
and   m2.seq_prisha   = m1.seq_prisha
and   m2.code_sug_bakasha in (1,14)) s_sachar,
(select max(m2.seq_bakasha)
from m m2
where m2.mispar_zehut = m1.mispar_zehut
and   m2.seq_prisha   = m1.seq_prisha
and   m2.code_sug_bakasha in (1,3,5)) s_zakaut
from m m1
) sel
left join m m3 on
m3.seq_bakasha = case when sel.s_sachar is not null then sel.s_sachar else sel.s_zakaut end
left join m m4 on
m4.seq_bakasha = case when sel.s_zakaut is not null then sel.s_zakaut end
left join m m5 on
m5.seq_bakasha = case when sel.s_sachar is not null then sel.s_sachar end
left join v_bakasha_last_status vm5 on vm5.seq_bakasha = f_get_seq_bakasha_zakaut(m3.gimla_number,'poresh')
left join netuney_tik_mechushavim nm5 on nm5.seq_bakasha = vm5.seq_bakasha
                                     and nm5.code_department = 2
                                     and nvl(nm5.mispar_misra,0) = nvl(m5.misra_sachar,0)
left join code_group_prisha cg5 on cg5.code_group_prisha = nm5.code_group_prisha
left join bakasha_regila br5 on br5.seq_bakasha = vm5.seq_bakasha and br5.chinuch_mikzoa = 911
left join hagdala_nimuk h5 on h5.seq_bakasha = vm5.seq_bakasha
left join code_hagdala_nimuk ch5 on ch5.code_nimuk = h5.code_nimuk
left join v_bakasha_last_status vm4 on vm4.seq_bakasha = f_get_seq_bakasha_sachar(m3.gimla_number)
left join netuney_sachar ns4 on ns4.seq_bakasha = vm4.seq_bakasha
                            and nvl(ns4.mispar_misra,0) = nvl(m4.misra_zakaut,0)
                            and ns4.code_sug_maskoret = 1
                            --and vm4.seq_ezor_ovdim <> 206
left join netuney_sachar ns4_60 on ns4_60.seq_bakasha = vm4.seq_bakasha
                            and nvl(ns4_60.mispar_misra,0) = nvl(m4.misra_zakaut,0)
                            and ns4_60.code_sug_maskoret = 2
                            --and vm4.seq_ezor_ovdim <> 206
left join code_derug cd4    on cd4.code_derug = ns4.code_derug
where (m3.code_sug_bakasha <> 1 or (m3.code_sug_bakasha = 1 and nvl(m4.misra_zakaut,0) = nvl(m5.misra_sachar,0)) )
and not(m5.code_sug_bakasha in(1,14) and m5.maskoret_kovaat is null and m3.seq_ezor_ovdim = 206)
--and m3.seq_ezor_ovdim <> 206
order by 2;
end;
/

create or replace procedure prm_system_copy.fix_bney_mishpacha is
begin
  for te in (select *
               from bney_mishpacha_010720_prp t
              where t.seq_bney_mishpacha in
                    (select t.seq_bney_mishpacha from zz_bney_mishpacha t)) loop
    UPDATE bney_mishpacha m
       SET m.code_relative = te.code_relative,
           m.achuz_tosefet = te.achuz_tosefet,
           m.achuz_kizba   = te.achuz_kizba,
           --not set to null when expirieds
           m.to_date_sium_zakaut = te.to_date_sium_zakaut,
           m.achuz_kizba_chuka   = te.achuz_kizba_chuka,
           m.achuz_tosefet_sofi  = te.achuz_tosefet_sofi
     WHERE m.seq_bney_mishpacha = TE.seq_bney_mishpacha;
    dbms_output.put_line(te.seq_bney_mishpacha);
  end loop;
end fix_bney_mishpacha;
/

create or replace procedure prm_system_copy.Get_Document_Maor(p_i   number,
                                              p_cur out sys_refcursor) is
begin
  open p_cur for
  --Get main select
    select a.*,
           nvl(to_char(a.date_update, 'yyyy'), a.date_doc) year_doc,
           nvl(to_char(a.date_update, 'mm'), '01') month_doc
      from (select d.seq_document,
                   d.document_url,
                   d.date_update,
                   substr(d.document_url, 0, 4) date_doc
              from document d
             where d.document_url like '%/%') a;
end;
/

create or replace procedure prm_system_copy.Get_ld_protokol_last(days_number in number,
                                                 cur         out sys_refcursor) is
begin
  open cur for
    select p.description,
           l.code_process,
           l.code_sub_process,
           l.begin_date,
           l.end_date,
           l.status,
           l.ld_result,
           l.count_success_tikim,
           l.count_errors_tikim,
           l.message,
           l.seq_ld_protocol
    
      from ld_protocol l
      left join ld_process p
        on p.code_process = l.code_process
       and p.code_sub_process = l.code_sub_process
     where trunc(l.begin_date) = case
             when days_number is null then
             --Get the max date in the table
              (select max(trunc(l2.begin_date)) from ld_protocol l2)
             else
              trunc(sysdate - days_number)
           end
     order by l.seq_ld_protocol;

end Get_ld_protokol_last;
/

create or replace procedure prm_system_copy.get_SF_Document(from_date In Varchar2, Document Out sys_refcursor) is
/*"DocExternalID"
"Name"
"Active"
"Source"
"Type"
"Link"
"External"
"Person Account External ID"
"Retirement External ID"
"Owner"*/

begin

open Document for

select distinct/*sel.sug,*/
       sel.seq_document,
       sel.mispar_zehut_document,
       encrypt_tz(sel.seq_document)          "DocExternalID",
       --sel.mispar_zehut_document,
       --sel.sug_gimlay,      
       trim(sel.teur_document_type) || ' -- ' || sel.mispar_zehut_document 
       || ' --- ' || to_char(sel.seq_document) "Name",
       sel.pail                              "Active",
       'Mapam'                               "Source",
       sel.seq_document_type                 "Type",
       sel.document_url                      "Link",
       case when sel.is_external = 1 and sel.pail = 1 
              or sel.seq_document = 720940  then 1
                                            else 0 end   "External",
       encrypt_tz(sel.mispar_zehut_document) "Person Account External ID",
       encrypt_tz(sel.seq_prisha * 1000000000 + sel.mispar_zehut_document) "Eligibility External ID",
       --encrypt_tz(sel.seq_prisha)            "Retirement External ID",
       --sel.code_user                         "Owner"
       case when u.id_user is null then 'לא ידוע'
            else  nvl(u.shem_prati, ' ') || ' ' || nvl(u.shem_mishpacha,' ' ) end "Owner Name"--,
       --,sel.date_compare date_update

from
(select 1 sug, d.date_update, d.seq_document, d.document_url,
        case when d.code_user is null and d.document_url like '%mofgimlaot%' then 3 else d.code_user end code_user,
        b.seq_bakasha, v.mispar_zehut, bm.mispar_zehut_ben_mishpacha,
        v.code_sug_bakasha,
        v.code_source, v.seq_prisha,
        c.teur_document_type, d.seq_document_type, db.pail, c.is_external,
        case when d.seq_document_type = 158
            or p.taarich_ptira is null 
            and v.code_sug_bakasha <> 12
            and b.seq_bney_mishpacha is null
            and instr(c.teur_document_type,
            'שאר') = 0
            or p.taarich_ptira is not null and p.taarich_ptira > d.date_update then 'poresh'
            when bm.seq_bney_mishpacha is not null then 'sheer 0'
            when bm1.seq_bney_mishpacha is not null then 'sheer 1'
            when bm2.seq_bney_mishpacha is not null then 'sheer 2'
            else null end sug_gimlay,
        case when d.seq_document_type = 158
            or p.taarich_ptira is null
            and v.code_sug_bakasha <> 12
            and b.seq_bney_mishpacha is null
            and instr(c.teur_document_type,
            'שאר') = 0
            or p.taarich_ptira is not null and p.taarich_ptira > d.date_update then p.mispar_zehut
            when bm.seq_bney_mishpacha is not null then bm.mispar_zehut_ben_mishpacha
            when bm1.seq_bney_mishpacha is not null then bm1.mispar_zehut_ben_mishpacha
            when bm2.seq_bney_mishpacha is not null then bm2.mispar_zehut_ben_mishpacha
            else 0 end mispar_zehut_document,
        case when d.seq_document_type = 158
            or p.taarich_ptira is null
            and v.code_sug_bakasha <> 12
            and b.seq_bney_mishpacha is null
            and instr(c.teur_document_type,
            'שאר') = 0
            or p.taarich_ptira is not null and p.taarich_ptira > d.date_update then
                 trim(nvl(p.shem_prati,' ')) || ' ' || trim(nvl(p.shem_mishpacha,' '))
            when bm.seq_bney_mishpacha is not null then
                 trim(nvl(bm.shem_prati,' ')) || ' ' || trim(nvl(bm.shem_mishpacha,' '))
            when bm1.seq_bney_mishpacha is not null then
                 trim(nvl(bm1.shem_prati,' ')) || ' ' || trim(nvl(bm1.shem_mishpacha,' '))
            when bm2.seq_bney_mishpacha is not null then
                 trim(nvl(bm2.shem_prati,' ')) || ' ' || trim(nvl(bm2.shem_mishpacha,' '))
            else '***' end name
from document d
left join document d1 on
d1.seq_document = d."SEQ_DOCUMENT"
and d1.date_update >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
left join document_bakasha db on
db.seq_document = d.seq_document
left join code_document_type c on
c.seq_document_type = d.seq_document_type
left join bakasha b on
b.seq_bakasha = db.seq_bakasha
left join v_bakasha_last_status v on
v.seq_bakasha = b.seq_bakasha
left join poresh p on
p.mispar_zehut = v.mispar_zehut
left join bney_mishpacha bm on
bm.seq_bney_mishpacha = b.seq_bney_mishpacha
left join bney_mishpacha bm1 on
bm1.seq_porshim = v.seq_porshim
and (bm1.code_kirva in (1,14/*,10*/) or  bm1.code_relative in (1,5/*,6*/))
left join bney_mishpacha bm2 on
bm2.seq_porshim = v.seq_porshim
and bm2.code_kirva = 2
and bm2.code_relative in (2,3,4,9)
and bm2.taarich_leda =
(select min(bm3.taarich_leda)
from bney_mishpacha bm3
where bm3.seq_porshim = p.porshim_seq
and bm2.code_kirva = 2
and bm2.code_relative in (2,3,4,9)
)
where b.seq_bakasha is not null
and d.source_type <> 5
and not (v.code_sug_bakasha in (1,3,5,13,12,8,9,7,23) and v.code_action not in (98,129,130,132))
and d1.seq_document is not null
and c.is_external in (0,1)
and v.seq_ezor_ovdim not in (
155,
158,
154,
--159,
163,
164,
--225,
13,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149
)
--and d.date_update >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
and instr(d.document_url,'mofgimlaot',1) = 0
/*and instr(d.document_url,'srika',1) = 0
and instr(d.document_url,'SRIKA',1) = 0*/
and instr(d.document_url,'\\',1) > 0
and not (d.seq_document_type = 94 and nvl(d.code_department,0) in (1))
and (db.seq_bakasha = 514450 or
(d.seq_document_type <> 94 or
d.seq_document_type = 94 and nvl(d.code_department,0)  not in (1)
/*and (v.code_sug_bakasha in (1,8) or v.code_sug_bakasha = 5 and v.code_bakasha_detail = 25)
and v.seq_ezor_ovdim = 206
*/
and not exists
(select 1
from document_bakasha db2, document d2
where db2.seq_bakasha = db.seq_bakasha
and d2.seq_document = db2.seq_document
and db2.pail = 1
and db2.seq_document > db.seq_document
and d2.seq_document_type = 94 and d2.code_department  not in (1))
))
and exists
(select 1
from v_bakasha_last_status vs
where vs.seq_prisha = v.seq_prisha
and ((vs.code_sug_bakasha in(1,8,13)
    or vs.code_sug_bakasha = 5 and v.code_bakasha_detail = 25)
    and vs.code_action in (98,129,130,132)
    or  vs.code_sug_bakasha in (8,9) and v.code_action in (41,42)
)
)
union
select  2, ds1.taarich_hosafa, d1.seq_document, d1.document_url,
        case when d1.code_user is null and d1.document_url like '%mofgimlaot%' then 3 else d1.code_user end code_user,
        b.seq_bakasha, v.mispar_zehut, bm.mispar_zehut_ben_mishpacha,
        v.code_sug_bakasha,
        v.code_source, v.seq_prisha,
        c.teur_document_type, d1.seq_document_type, db.pail, c.is_external,
        case when c.seq_document_type = 158
            or (p.taarich_ptira is null or d1.seq_document in (874367,874751))
            and v.code_sug_bakasha <> 12
            and b.seq_bney_mishpacha is null
            and instr(c.teur_document_type,
            'שאר') = 0
            or p.taarich_ptira is not null and p.taarich_ptira > d1.date_update
            then 'poresh'
            when bm.seq_bney_mishpacha is not null then 'sheer 0'
            when bm1.seq_bney_mishpacha is not null then 'sheer 1'
            when bm2.seq_bney_mishpacha is not null then 'sheer 2'
            else null end sug_gimlay,
        case when c.seq_document_type = 158
            or p.taarich_ptira is null
            and v.code_sug_bakasha <> 12
            and b.seq_bney_mishpacha is null
            and instr(c.teur_document_type,
            'שאר') 
            = 0
            or p.taarich_ptira is not null and p.taarich_ptira > d1.date_update
            then p.mispar_zehut
            when bm.seq_bney_mishpacha is not null then bm.mispar_zehut_ben_mishpacha
            when bm1.seq_bney_mishpacha is not null then bm1.mispar_zehut_ben_mishpacha
            when bm2.seq_bney_mishpacha is not null then bm2.mispar_zehut_ben_mishpacha
            else 0 end mispar_zehut_document,
        case when c.seq_document_type = 158
            or p.taarich_ptira is null
            and v.code_sug_bakasha <> 12
            and b.seq_bney_mishpacha is null
            and instr(c.teur_document_type,
            'שאר') = 0
            or p.taarich_ptira is not null and p.taarich_ptira > d1.date_update
            then
                 trim(nvl(p.shem_prati,' ')) || ' ' || trim(nvl(p.shem_mishpacha,' '))
            when bm.seq_bney_mishpacha is not null then
                 trim(nvl(bm.shem_prati,' ')) || ' ' || trim(nvl(bm.shem_mishpacha,' '))
            when bm1.seq_bney_mishpacha is not null then
                 trim(nvl(bm1.shem_prati,' ')) || ' ' || trim(nvl(bm1.shem_mishpacha,' '))
            when bm2.seq_bney_mishpacha is not null then
                 trim(nvl(bm2.shem_prati,' ')) || ' ' || trim(nvl(bm2.shem_mishpacha,' '))
            else '***' end name
from sf_add_document ds
left join sf_add_document ds1 on
ds1.mispar_zehut = ds.mispar_zehut
and ds1.seq_document = ds.seq_document
and ds1.taarich_hosafa = ds.taarich_hosafa
and ds1.seq_bakasha = ds.seq_bakasha
left join document d1 on
d1.seq_document = ds."SEQ_DOCUMENT"
--and d1.date_update = trunc(to_date(from_date,'YYYY-MM-DD HH24:MI:SS')) - 1
--and ds.taarich_hosafa >= to_date('2022-01-01','YYYY-MM-DD HH24:MI:SS')
left join document_bakasha db on
db.seq_document = ds.seq_document
and db.seq_bakasha = ds.seq_bakasha
left join code_document_type c on
c.seq_document_type = d1.seq_document_type
left join bakasha b on
b.seq_bakasha = db.seq_bakasha
left join v_bakasha_last_status v on
v.seq_bakasha = b.seq_bakasha
left join poresh p on
p.mispar_zehut = v.mispar_zehut
left join bney_mishpacha bm on
bm.seq_bney_mishpacha = b.seq_bney_mishpacha
left join bney_mishpacha bm1 on
bm1.seq_porshim = v.seq_porshim
and (bm1.code_kirva in (1,14/*,10*/) or  bm1.code_relative in (1,5/*,6*/))
left join bney_mishpacha bm2 on
bm2.seq_porshim = v.seq_porshim
and bm2.code_kirva = 2
and bm2.code_relative in (2,3,4,9)
and bm2.taarich_leda =
(select min(bm3.taarich_leda)
from bney_mishpacha bm3
where bm3.seq_porshim = p.porshim_seq
and bm2.code_kirva = 2
and bm2.code_relative in (2,3,4,9))
where /*ds1.taarich_hosafa \*+ interval '30' minute*\ >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
and */b.seq_bakasha is not null
and d1.seq_document is not null
and d1.source_type <> 5
and c.is_external in (0,1)
and instr(d1.document_url,'mofgimlaot',1) = 0
--and ds.taarich_hosafa >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
/*and instr(d1.document_url,'srika',1) = 0
and instr(d1.document_url,'SRIKA',1) = 0*/
and instr(d1.document_url,'\\',1) > 0
and not(d1.seq_document_type = 94 and nvl(d1.code_department,0) in (1))
and (d1.seq_document_type <> 94 or
d1.seq_document_type = 94 and nvl(d1.code_department,0)  not in (1)
--and (v.code_sug_bakasha in (1,8,13) or v.code_sug_bakasha = 5 and v.code_bakasha_detail = 25)
--and v.seq_ezor_ovdim = 206
and not exists
(select 1
from document_bakasha db2, document d2
where db2.seq_bakasha = db.seq_bakasha
and d2.seq_document = db2.seq_document
and db2.pail = 1
and db2.seq_document > db.seq_document
and d2.seq_document_type = 94 and d2.code_department  not in (1))
)
)sel
left join code_user u on
u.id_user = sel.code_user
where sel.mispar_zehut_document <> 0
/*and sel.mispar_zehut_document not in (337175939,337175921)
and sel.mispar_zehut_document <> 700401946
and sel.mispar_zehut_document <> 57413742 
and sel.mispar_zehut_document <> 23211824 
and sel.mispar_zehut_document <> 17639410
and sel.mispar_zehut_document <> 63326342
and sel.mispar_zehut_document <> 64675002
and sel.mispar_zehut_document <> 4976882
and sel.mispar_zehut_document  <> 53498069
and sel.mispar_zehut_document <> 65204448
and sel.mispar_zehut_document <> 12534723
*/
and sel.mispar_zehut_document <> 7559529
--and sel.mispar_zehut_document  <> 218647915 --למחוק אחר כך

and   sel.name <> '***' -- is not null
and sel.date_update >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS');
--order by sel.seq_document desc;

end get_SF_Document;
/

create or replace procedure prm_system_copy.get_SF_Document_new(from_date In Varchar2, Document Out sys_refcursor) is
/*"DocExternalID"
"Name"
"Active"
"Source"
"Type"
"Link"
"External"
"Person Account External ID"
"Retirement External ID"
"Owner"*/

begin

open Document for

select /*sel.sug,
       sel.seq_document,*/
       encrypt_tz(sel.seq_document)          "DocExternalID",
       sel.mispar_zehut_document,
       sel.sug_gimlay,
       sel.name || '-' || trim(sel.teur_document_type) || '-' || to_char(sel.date_update,'yyyy-mm-dd') "Name",
       sel.pail                              "Active",
       'Mapam'                               "Source",
       sel.seq_document_type                 "Type",
       sel.document_url                      "Link",
       case when sel.is_external = 1 and
            sel.pail = 1 then 1 else 0 end   "External",
       encrypt_tz(sel.mispar_zehut_document) "Person Account External ID",
       encrypt_tz(sel.seq_prisha)            "Retirement External ID",
       --sel.code_user                         "Owner"
       case when u.id_user is null then 'לא יודוע'
            else  nvl(u.shem_prati, ' ') || ' ' || nvl(u.shem_mishpacha,' ' ) end "Owner Name"--,
       --sel.date_compare

from
(select 1 sug, d.date_update date_compare , d.seq_document, d.document_url,
        case when d.code_user is null and d.document_url like '%mofgimlaot%' then 3 else d.code_user end code_user,
        b.seq_bakasha, v.mispar_zehut, bm.mispar_zehut_ben_mishpacha,
        v.code_sug_bakasha,
        trunc(d.date_update) date_update,  v.code_source, v.seq_prisha,
        c.teur_document_type, d.seq_document_type, db.pail, c.is_external,
        case when p.taarich_ptira is null
            and v.code_sug_bakasha <> 12
            and b.seq_bney_mishpacha is null
            and instr(c.teur_document_type,
            'שאר') = 0
            or p.taarich_ptira is not null and p.taarich_ptira > d.date_update then 'poresh'
            when bm.seq_bney_mishpacha is not null then 'sheer 0'
            when bm1.seq_bney_mishpacha is not null then 'sheer 1'
            when bm2.seq_bney_mishpacha is not null then 'sheer 2'
            else null end sug_gimlay,
        case when p.taarich_ptira is null
            and v.code_sug_bakasha <> 12
            and b.seq_bney_mishpacha is null
            and instr(c.teur_document_type,
            'שאר') = 0
            or p.taarich_ptira is not null and p.taarich_ptira > d.date_update then p.mispar_zehut
            when bm.seq_bney_mishpacha is not null then bm.mispar_zehut_ben_mishpacha
            when bm1.seq_bney_mishpacha is not null then bm1.mispar_zehut_ben_mishpacha
            when bm2.seq_bney_mishpacha is not null then bm2.mispar_zehut_ben_mishpacha
            else 0 end mispar_zehut_document,
        case when p.taarich_ptira is null
            and v.code_sug_bakasha <> 12
            and b.seq_bney_mishpacha is null
            and instr(c.teur_document_type,
            'שאר') = 0
            or p.taarich_ptira is not null and p.taarich_ptira > d.date_update then
                 trim(nvl(p.shem_prati,' ')) || ' ' || trim(nvl(p.shem_mishpacha,' '))
            when bm.seq_bney_mishpacha is not null then
                 trim(nvl(bm.shem_prati,' ')) || ' ' || trim(nvl(bm.shem_mishpacha,' '))
            when bm1.seq_bney_mishpacha is not null then
                 trim(nvl(bm1.shem_prati,' ')) || ' ' || trim(nvl(bm1.shem_mishpacha,' '))
            when bm2.seq_bney_mishpacha is not null then
                 trim(nvl(bm2.shem_prati,' ')) || ' ' || trim(nvl(bm2.shem_mishpacha,' '))
            else '***' end name
from document d
left join document d1 on
d1.seq_document = d."SEQ_DOCUMENT"
and d1.date_update >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
left join document_bakasha db on
db.seq_document = d.seq_document
left join code_document_type c on
c.seq_document_type = d.seq_document_type
left join bakasha b on
b.seq_bakasha = db.seq_bakasha
left join v_bakasha_last_status v on
v.seq_bakasha = b.seq_bakasha
left join poresh p on
p.mispar_zehut = v.mispar_zehut
left join bney_mishpacha bm on
bm.seq_bney_mishpacha = b.seq_bney_mishpacha
left join bney_mishpacha bm1 on
bm1.seq_porshim = v.seq_porshim
and (bm1.code_kirva in (1,14,10) or  bm1.code_relative in (1,5,6))
left join bney_mishpacha bm2 on
bm2.seq_porshim = v.seq_porshim
and bm2.code_kirva = 2
and bm2.code_relative in (2,3,4,9)
and bm2.taarich_leda =
(select min(bm3.taarich_leda)
from bney_mishpacha bm3
where bm3.seq_porshim = p.porshim_seq
and bm2.code_kirva = 2
and bm2.code_relative in (2,3,4,9)
)
where b.seq_bakasha is not null
and d1.seq_document is not null
and c.is_external in (0,1)
and v.seq_ezor_ovdim not in (
155,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
10154,
10149
)
and instr(d.document_url,'mofgimlaot',1) = 0
and instr(d.document_url,'\\',1) > 0
and exists
(select 1
from v_bakasha_last_status vs
where vs.seq_prisha = v.seq_prisha
and ((vs.code_sug_bakasha in(1,8,13)
    or vs.code_sug_bakasha = 5 and v.code_bakasha_detail = 25)
    and vs.code_action in (98,129,130)
    or  vs.code_sug_bakasha in (8,9) and v.code_action in (41,42)  
)
)
union
select  2, ds1.taarich_hosafa, d1.seq_document, d1.document_url,
        case when d1.code_user is null and d1.document_url like '%mofgimlaot%' then 3 else d1.code_user end code_user,
        b.seq_bakasha, v.mispar_zehut, bm.mispar_zehut_ben_mishpacha,
        v.code_sug_bakasha, 
        trunc(d1.date_update) date_update, v.code_source, v.seq_prisha,
        c.teur_document_type, d1.seq_document_type, db.pail, c.is_external,
        case when p.taarich_ptira is null
            and v.code_sug_bakasha <> 12
            and b.seq_bney_mishpacha is null
            and instr(c.teur_document_type,
            'שאר') = 0
            or p.taarich_ptira is not null and p.taarich_ptira > d1.date_update then 'poresh'
            when bm.seq_bney_mishpacha is not null then 'sheer 0'
            when bm1.seq_bney_mishpacha is not null then 'sheer 1'
            when bm2.seq_bney_mishpacha is not null then 'sheer 2'
            else null end sug_gimlay,
        case when p.taarich_ptira is null
            and v.code_sug_bakasha <> 12
            and b.seq_bney_mishpacha is null
            and instr(c.teur_document_type,
            'שאר') = 0
            or p.taarich_ptira is not null and p.taarich_ptira > d1.date_update then p.mispar_zehut
            when bm.seq_bney_mishpacha is not null then bm.mispar_zehut_ben_mishpacha
            when bm1.seq_bney_mishpacha is not null then bm1.mispar_zehut_ben_mishpacha
            when bm2.seq_bney_mishpacha is not null then bm2.mispar_zehut_ben_mishpacha
            else 0 end mispar_zehut_document,
        case when p.taarich_ptira is null
            and v.code_sug_bakasha <> 12
            and b.seq_bney_mishpacha is null
            and instr(c.teur_document_type,
            'שאר') = 0
            or p.taarich_ptira is not null and p.taarich_ptira > d1.date_update then
                 trim(nvl(p.shem_prati,' ')) || ' ' || trim(nvl(p.shem_mishpacha,' '))
            when bm.seq_bney_mishpacha is not null then
                 trim(nvl(bm.shem_prati,' ')) || ' ' || trim(nvl(bm.shem_mishpacha,' '))
            when bm1.seq_bney_mishpacha is not null then
                 trim(nvl(bm1.shem_prati,' ')) || ' ' || trim(nvl(bm1.shem_mishpacha,' '))
            when bm2.seq_bney_mishpacha is not null then
                 trim(nvl(bm2.shem_prati,' ')) || ' ' || trim(nvl(bm2.shem_mishpacha,' '))
            else '***' end name
from sf_add_document ds
left join sf_add_document ds1 on
ds1.mispar_zehut = ds.mispar_zehut
and ds1.seq_document = ds.seq_document
and ds1.taarich_hosafa = ds.taarich_hosafa
left join document d1 on
d1.seq_document = ds."SEQ_DOCUMENT"
--and d1.date_update = trunc(to_date(from_date,'YYYY-MM-DD HH24:MI:SS')) - 1
and d1.date_update >= to_date('2022-01-01','YYYY-MM-DD HH24:MI:SS')
left join document_bakasha db on
db.seq_document = ds.seq_document
left join code_document_type c on
c.seq_document_type = d1.seq_document_type
left join bakasha b on
b.seq_bakasha = db.seq_bakasha
left join v_bakasha_last_status v on
v.seq_bakasha = b.seq_bakasha
left join poresh p on
p.mispar_zehut = v.mispar_zehut
left join bney_mishpacha bm on
bm.seq_bney_mishpacha = b.seq_bney_mishpacha
left join bney_mishpacha bm1 on
bm1.seq_porshim = v.seq_porshim
and (bm1.code_kirva in (1,14,10) or  bm1.code_relative in (1,5,6))
left join bney_mishpacha bm2 on
bm2.seq_porshim = v.seq_porshim
and bm2.code_kirva = 2
and bm2.code_relative in (2,3,4,9)
and bm2.taarich_leda =
(select min(bm3.taarich_leda)
from bney_mishpacha bm3
where bm3.seq_porshim = p.porshim_seq
and bm2.code_kirva = 2
and bm2.code_relative in (2,3,4,9))
where /*ds1.taarich_hosafa \*+ interval '30' minute*\ >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
and */b.seq_bakasha is not null
and d1.seq_document is not null
and c.is_external in (0,1)
and instr(d1.document_url,'mofgimlaot',1) = 0
and instr(d1.document_url,'\\',1) > 0

)sel
left join code_user u on
u.id_user = sel.code_user
where sel.mispar_zehut_document <> 0
and   sel.name <> '***' -- is not null
and sel.date_compare >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
order by sel.seq_document desc;

end get_SF_Document_new;
/

