from sf_add_document ds
left join sf_add_document ds1 on
ds1.mispar_zehut = ds.mispar_zehut
and ds1.seq_document = ds.seq_document
and ds1.taarich_hosafa = ds.taarich_hosafa
and ds1.seq_bakasha = ds.seq_bakasha
left join document d1 on
d1.seq_document = ds."SEQ_DOCUMENT"
--and d1.date_update = trunc(to_date(from_date,'YYYY-MM-DD HH24:MI:SS')) - 1
--and ds.taarich_hosafa >= to_date('2022-01-01','YYYY-MM-DD HH24:MI:SS')
left join document_bakasha db on
db.seq_document = ds.seq_document
and db.seq_bakasha = ds.seq_bakasha
left join code_document_type c on
c.seq_document_type = d1.seq_document_type
left join bakasha b on
b.seq_bakasha = db.seq_bakasha
left join v_bakasha_last_status v on
v.seq_bakasha = b.seq_bakasha
left join poresh p on
p.mispar_zehut = v.mispar_zehut
left join bney_mishpacha bm on
bm.seq_bney_mishpacha = b.seq_bney_mishpacha
left join bney_mishpacha bm1 on
bm1.seq_porshim = v.seq_porshim
and (bm1.code_kirva in (1,14,10) or  bm1.code_relative in (1,5,6))
left join bney_mishpacha bm2 on
bm2.seq_porshim = v.seq_porshim
and bm2.code_kirva = 2
and bm2.code_relative in (2,3,4,9)
and bm2.taarich_leda =
(select min(bm3.taarich_leda)
from bney_mishpacha bm3
where bm3.seq_porshim = p.porshim_seq
and bm2.code_kirva = 2
and bm2.code_relative in (2,3,4,9))
where /*ds1.taarich_hosafa \*+ interval '30' minute*\ >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
and */b.seq_bakasha is not null
and d1.seq_document is not null
and d1.source_type <> 5
and c.is_external in (0,1)
and instr(d1.document_url,'mofgimlaot',1) = 0
--and ds.taarich_hosafa >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
/*and instr(d1.document_url,'srika',1) = 0
and instr(d1.document_url,'SRIKA',1) = 0*/
and instr(d1.document_url,'\\',1) > 0
and not(d1.seq_document_type = 94 and nvl(d1.code_department,0) in (1,3))
and (d1.seq_document_type <> 94 or
d1.seq_document_type = 94 and nvl(d1.code_department,0)  not in (1,3)
--and (v.code_sug_bakasha in (1,8,13) or v.code_sug_bakasha = 5 and v.code_bakasha_detail = 25)
--and v.seq_ezor_ovdim = 206
and not exists
(select 1
from document_bakasha db2, document d2
where db2.seq_bakasha = db.seq_bakasha
and d2.seq_document = db2.seq_document
and db2.pail = 1
and db2.seq_document > db.seq_document
and d2.seq_document_type = 94 and d2.code_department  not in (1,3))
)
)sel
left join code_user u on
u.id_user = sel.code_user
where sel.mispar_zehut_document <> 0
and   sel.name <> '***' -- is not null
and sel.date_update >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS');
--order by sel.seq_document desc;

end get_SF_Document_test;
/

create or replace procedure prm_system_copy.get_SF_Eligibility(from_date In Varchar2, Eligibility Out sys_refcursor) is

begin
open Eligibility for
select distinct  /*'poresh' sug,
                 sel1.mispar_zehut_amiti,
                 v1.code_action,*/
                 encrypt_tz(sel1.seq_prisha)                                "Retirement External ID",
                 encrypt_tz(sel1.mispar_zehut_amiti)                        "Person Account External ID",
                 vz.date_start_zakaut                                       "Eligibility Start date",
                 case when p2.taarich_ptira is null then null
                 else to_date('01/' ||
                 to_char(add_months(p2.taarich_ptira,1),'mm/yyyy'),
                 'dd/mm/yyyy') - 1 end                                      "Eligibility End date",
              
/*                 case when p2.taarich_ptira is not null then 
                      to_date('01/' ||
                      to_char(add_months(p2.taarich_ptira,1),'mm/yyyy'),
                      'dd/mm/yyyy') - 1
                      when f_get_date_end_zakaut (p2.mispar_zehut) is not null then
                      f_get_date_end_zakaut (p2.mispar_zehut)
                      else null end                                         "Eligibility End date",
*/               
                 v1.code_seif_prisha                                        "Retirement Section",
                 case when exists (select 1
                                   from v_bakasha_last_status vg
                                   where vg.seq_prisha = sel1.seq_prisha
                                   and   vg.code_sug_bakasha = 8
                                   and   vg.code_action <> 17) then 50
                                                               else  0
                      end                                                   "Type Of Benefit",
                 case when ba1.code_bank is not null then
                   ba1.code_bank
                 else
                   999 end                                                  "Bank",
                 case when ba1.code_bank is not null
                       and ba1.code_snif is not null then
                   ba1.code_bank * 1000 + ba1.code_snif 
                 else 999999 end                                            "BranchNumber",
                 ba1.account_number                                         "Account",
                 encrypt_tz(sel1.seq_prisha * 1000000000 + p2.mispar_zehut) "Eligibility External ID",
                 case when p2.shem_prati = 'הסבה'
                   then 'לא מזוהה'
                   else p2.shem_prati end || ' ' ||
                 case when p2.shem_mishpacha = 'הסבה'
                   then 'לא מזוהה'
                   else p2.shem_mishpacha end                               "Person Name",
                 sel1.mispar_gimla                                          "Benefit Number"


from
(select distinct porshim.*,
            case when p.mispar_zehut is null then z.mispar_zheut else p.mispar_zehut end mispar_zehut_amiti
from
((select distinct v.mispar_zehut,
                  v.gimla_number mispar_gimla,
                  v.seq_ezor_ovdim,
                  v.seq_prisha,
                  v.seq_porshim
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha = le.seq_bakasha
                                  and v.mispar_zehut = le.mispar_zehut
where v.code_action not in (17,100)
and v.code_sug_bakasha not in (14,7,23)
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
)
)
union
(select distinct v.mispar_zehut,
                  v.gimla_number mispar_gimla,
                  v.seq_ezor_ovdim,
                  v.seq_prisha,
                  v.seq_porshim
from action_log a
left join v_bakasha_last_status v on  v.seq_bakasha = a.seq_bakasha
left join netuney_tik_mechushavim n on n.seq_bakasha = v.seq_bakasha
                                   and n.code_department = 2
where v.code_sug_bakasha = 1
and v.code_action not in (17,100)
and nvl(n.code_department,0) <> 4
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 19
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
and n.date_start_zakaut is not null)
)
union
(select distinct v.mispar_zehut,
                 v.gimla_number mispar_gimla,
                 v.seq_ezor_ovdim,
                 v.seq_prisha,
                 v.seq_porshim
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha = le.seq_bakasha
                                  and v.mispar_zehut <> le.mispar_zehut
/*left join netuney_tik_mechushavim n on
n.seq_bakasha = v.seq_bakasha
and n.code_department = 2
*/
where v.code_action not in (17,100)
--and v.code_sug_bakasha in (1,13,9)
--and n.code_group_prisha = 4
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
)
)
union
select distinct v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha,
                v.seq_porshim
from v_bakasha_last_status v
left join sf_gimlaim_nosafim gn        on gn.mispar_zehut = v.mispar_zehut
where gn.taarich_hosafa >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')

order by 1)
porshim
left join poresh p                   on p.mispar_zehut = porshim.mispar_zehut
left join zheut_fictivi_from_hilan z on z.mispar_zheut_fictivi = porshim.mispar_zehut
left join poresh p1                  on p1.mispar_zehut = z.mispar_zheut
where (p.mispar_zehut is not null or p1.mispar_zehut is not null)
/*and p.mispar_zehut <> 23179443
and p.mispar_zehut <> 46528733
and p.mispar_zehut <> 58452988*/ 
and porshim.seq_ezor_ovdim not in (
155,
158,
13,
154,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149
)
)
sel1

left join poresh p2                  on p2.mispar_zehut = sel1.mispar_zehut_amiti

left join (select seq_porshim, code_bank, code_snif, account_number, mispar_gimla
from (
select seq_porshim,
       code_bank, code_snif, account_number, ba.gimla_number mispar_gimla
               , row_number() over (partition by ba.seq_porshim, ba.gimla_number
                               order by ba.seq_bakasha desc) as rn
     from v_bank_account ba
     where /*not exists
           (select v1.seq_bakasha
           from v_bakasha_last_status v1
           where v1.seq_porshim = ba.seq_porshim
           and   v1.gimla_number = ba.gimla_number
           and v1.code_sug_bakasha <> 1)
        or*/ (select distinct first_value(al.code_action) over(partition by al.seq_bakasha order by al.seq_action_log desc)
        from action_log al
        left join code_action ca on
        ca.code_action = al.code_action
        left join v_bakasha_last_status v3 on v3.seq_bakasha = al.seq_bakasha
                                            and v3.gimla_number = ba.gimla_number
        where al.seq_bakasha = ba.seq_bakasha
        and ba.SEQ_BNEY_MISHPACHA is null
        and v3.seq_bakasha is not null
        and ca.is_status = 1
        ) in (98,129,130,212,41,42))
     where rn = 1) ba1               on ba1.seq_porshim = sel1.seq_porshim
                                     and ba1.mispar_gimla = sel1.mispar_gimla

left join lateral (select seq_porshim, seq_bakasha, code_action, code_sug_bakasha, code_bakasha_detail, taarich_prisha, gimla_number, code_seif_prisha, seq_prisha
from (
select seq_porshim, seq_bakasha, code_action, code_sug_bakasha, code_bakasha_detail, taarich_prisha, gimla_number, code_seif_prisha, seq_prisha
          , row_number() over (partition by seq_porshim, gimla_number
                               order by seq_bakasha desc) as rn
     from v_bakasha_last_status v2
     where v2.mispar_zehut = p2.mispar_zehut
          and (not exists
           (select v3.seq_bakasha
           from v_bakasha_last_status v3
           where v3.seq_porshim = v2.seq_porshim
           and   v3.seq_prisha = v2.seq_prisha
           and v3.code_sug_bakasha not in (1,2,33,35))
           and v2.code_sug_bakasha = 1
           )
           or ((v2.code_sug_bakasha in (1,8,9) or v2.code_sug_bakasha = 5 and v2.code_bakasha_detail = 25
                                               or v2.code_sug_bakasha = 20 and v2.code_bakasha_detail in (15,16/*,168*/))
           and nvl(v2.code_action,0) in (98,129,130,132,212,41,42))
     )
where rn = 1) v1                     on v1.seq_prisha = sel1.seq_prisha
left join v_bakasha_last_zakaut vz   on vz."SEQ_BAKASHA" = v1.seq_bakasha
left join netuney_tik_mechushavim nz on nz.seq_bakasha = v1."SEQ_BAKASHA"
                                     and nz.code_department = 2
--left join code_group_prisha cg       on cg.code_group_prisha = nz.code_group_prisha

where nz.mispar_misra = 0
and nvl(nz.code_group_prisha,0) <> 4

union

select distinct  /*'sheer',
                 sel1.mispar_zehut_ben_mishpacha,
                 v1.code_action,*/
                 encrypt_tz(sel1.seq_prisha)                                "Retirement External ID",
                 encrypt_tz(sel1.mispar_zehut_ben_mishpacha)                "Person Account External ID",
                 case when v1.code_sug_bakasha in (1,13) then vz.date_start_zakaut
                      when sel1.code_relative = 6 then nz.hp_date_start_zakaut
                      else /* code_sug_bakasha = 9 */  pt.date_payment
                      end                                                   "Eligibility Start date",
                 sel1.to_date_sium_zakaut                                   "Eligibility End date",
                 case when mod(nvl(v1.code_seif_prisha,0),100) not in (26,28)
                           or sel1.code_relative = 26
                           or sel1.code_relative = 9 and sel1.code_kirva not in (1,2,14) then
                           v1.code_seif_prisha
                      when sel1.code_relative = 9 and sel1.code_kirva in (1,2,14) then
                           to_number(to_char( case when sel1.code_kirva = 1 then 1
                                         when sel1.code_kirva = 2 then decode(nvl(sel1.is_taluy,0),1,4,2)
                                         when sel1.code_kirva = 14 then 5 end) ||
                           to_char(mod(v1.code_seif_prisha,100)))
                      else to_number(to_char(decode(sel1.code_relative,6,1,7,1,8,2,sel1.code_relative)) ||
                           to_char(mod(v1.code_seif_prisha,100)))
                      end                                                   "Retirement Section",
                 case when exists (select 1
                                   from v_bakasha_last_status vg
                                   where vg.seq_prisha = sel1.seq_prisha
                                   and   vg.code_sug_bakasha in (8,9)
                                   and   vg.code_action <> 17) then 51
                                                               else  sel1.code_relative 
                      end                                                   "Type Of Benefit",
                 case when ba1.code_bank is not null then
                   ba1.code_bank
                 else
                   999 end                                                  "Bank",
                 case when ba1.code_bank is not null
                       and ba1.code_snif is not null then
                   ba1.code_bank * 1000 + ba1.code_snif 
                 else 999999 end                                            "BranchNumber",
                 ba1.account_number                                         "Account",
                 encrypt_tz(v1.seq_prisha * 1000000000 + sel1.mispar_zehut_ben_mishpacha)  "Eligibility External ID",
                 sel1.shem_prati || ' ' || sel1.shem_mishpacha              "Person Name",
                 sel1.mispar_gimla                                          "Benefit Number"

from
(select distinct sheerim.*,
b1.shem_prati, b1.shem_mishpacha, b1.code_relative, b1.code_kirva, b1.is_taluy, b1.to_date_sium_zakaut, b1.mispar_zehut_ben_mishpacha
from(
select distinct le.mispar_zehut mispar_zehut_sheer,
                b0.seq_bney_mishpacha,
                v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha = le.seq_bakasha
                                 and v.mispar_zehut <> le.mispar_zehut
left join poresh p0              on p0.mispar_zehut = v.mispar_zehut
left join bney_mishpacha b0      on b0.mispar_zehut_ben_mishpacha = le.mispar_zehut
                                 and b0.seq_porshim = p0.porshim_seq
where v.code_action not in (17,100)
and v.code_sug_bakasha not in (14,7,23)
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
)
union
select distinct b.mispar_zehut_ben_mishpacha mispar_zehut_sheer,
                b.seq_bney_mishpacha,
                v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha  = le.seq_bakasha
                                  and v.mispar_zehut = le.mispar_zehut
left join poresh p                on  p.mispar_zehut = v.mispar_zehut
left join bney_mishpacha b        on  b.seq_porshim  = p.porshim_seq
where v.code_action not in (17,100)
and (v.code_sug_bakasha in (1,8,9) or v.code_sug_bakasha = 5 and v.code_bakasha_detail = 25)
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
and b.mispar_zehut_ben_mishpacha is not null)
union
select distinct b.mispar_zehut_ben_mishpacha mispar_zehut_sheer,
                b.seq_bney_mishpacha,
                v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha
from v_bakasha_last_status v
left join sf_gimlaim_nosafim gn        on gn.mispar_zehut = v.mispar_zehut
left join poresh p                     on p.mispar_zehut = v.mispar_zehut
left join bney_mishpacha b             on b.seq_porshim = p.porshim_seq
where gn.taarich_hosafa >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
order by 1)
sheerim
left join bney_mishpacha b1           on b1.seq_bney_mishpacha  = sheerim.seq_bney_mishpacha
where sheerim.mispar_zehut_sheer is not null
and b1.mispar_zehut_ben_mishpacha not in
(1911817,
1540699,
3534815,
4119863,
4882288,
43292804,
42554949,
47639422,
46708319,
45923224,
65320293,
67433458,
050034396
)
and b1.code_relative is not null
and nvl(b1.shem_prati,' ') <> substr(nvl(b1.shem_prati,' '),1,1)
and b1.mispar_zehut_ben_mishpacha not in(1,18,26,34,59,67)
and nvl(b1.sug_zihuy,0) <> 5
and b1.mispar_zehut_ben_mishpacha <> 111111111
and b1.shem_mishpacha is not null
and nvl(b1.code_kirva,0) not in (0/*,24*/,25)
and sheerim.seq_ezor_ovdim not in (
155,
158,
13,
154,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149
)
) sel1

left join bney_mishpacha b2          on  b2.seq_bney_mishpacha = sel1.seq_bney_mishpacha

left join (select seq_bney_mishpacha, code_bank, code_snif, account_number, mispar_gimla
from (
     select ba.seq_bney_mishpacha,  code_bank, code_snif, account_number, ba.gimla_number mispar_gimla
               , row_number() over (partition by ba.seq_bney_mishpacha, ba.gimla_number
                               order by ba.seq_bakasha desc) as rn
     from v_bank_account ba
     where (select distinct first_value(al.code_action) over(partition by al.seq_bakasha order by al.seq_action_log desc)
        from action_log al
        left join code_action ca on
        ca.code_action = al.code_action
        left join v_bakasha_last_status v3 on v3.seq_bakasha = al.seq_bakasha
                                            and v3.gimla_number = ba.gimla_number
        where al.seq_bakasha = ba.seq_bakasha
        and ca.is_status = 1
        ) in (98,129,130,212,41,42))
     where rn = 1) ba1               on ba1.seq_bney_mishpacha = sel1.seq_bney_mishpacha
                                     and ba1.mispar_gimla = sel1.mispar_gimla

left join lateral (select seq_porshim, seq_bakasha, code_action, code_sug_bakasha, code_bakasha_detail, taarich_prisha, gimla_number, code_seif_prisha, seq_prisha
from (
     select seq_porshim, seq_bakasha, code_action, code_sug_bakasha, code_bakasha_detail, taarich_prisha, gimla_number, code_seif_prisha, seq_prisha
          , row_number() over (partition by seq_porshim, gimla_number
                               order by seq_bakasha desc) as rn
     from v_bakasha_last_status v2
     where v2.seq_porshim = b2.seq_porshim
           and v2.code_sug_bakasha in (1,13,9,12)
           and v2.code_action in (98,129,130,212,41,42)
     )
where rn = 1) v1                     on v1.seq_prisha = sel1.seq_prisha
left join v_bakasha_last_zakaut vz   on vz."SEQ_BAKASHA" = v1.seq_bakasha
left join netuney_tik_mechushavim nz on nz.seq_bakasha = vz."SEQ_BAKASHA"
                                     and nz.code_department = 2
                                     and (nvl(nz.code_group_prisha,0) = 4 or vz."CODE_SUG_BAKASHA" = 12)
left join participation pt           on pt.seq_bakasha = v1.seq_bakasha and pt.code_participation = 1
where v1.seq_bakasha is not null
and (nz.mispar_misra = 0 and nvl(nz.code_group_prisha,0) = 4 or b2.code_relative = 6)
    order by 3,1,2;
end get_SF_Eligibility;
/

create or replace procedure prm_system_copy.get_SF_Eligibility_19(from_date In Varchar2, Eligibility Out sys_refcursor) is

begin
open Eligibility for
select distinct  /*'poresh' sug,
                 sel1.mispar_zehut_amiti,
                 v1.code_action,*/
                 encrypt_tz(sel1.seq_prisha)                                "Retirement External ID",
                 encrypt_tz(sel1.mispar_zehut_amiti)                        "Person Account External ID",
                 vz.date_start_zakaut                                       "Eligibility Start date",
                 case when p2.taarich_ptira is null then null
                 else to_date('01/' ||
                 to_char(add_months(p2.taarich_ptira,1),'mm/yyyy'),
                 'dd/mm/yyyy') - 1 end                                      "Eligibility End date",
                 v1.code_seif_prisha                                        "Retirement Section",
                 0                                                          "Type Of Benefit",
                 case when ba1.code_bank is not null then
                   ba1.code_bank
                 else
                   999 end                                                  "Bank",
                 case when ba1.code_bank is not null
                       and ba1.code_snif is not null then
                   ba1.code_bank * 1000 + ba1.code_snif 
                 else 999999 end                                            "BranchNumber",
                 ba1.account_number                                         "Account",
                 encrypt_tz(sel1.seq_prisha * 1000000000 + p2.mispar_zehut) "Eligibility External ID",
                 case when p2.shem_prati = 'הסבה'
                   then 'לא מזוהה'
                   else p2.shem_prati end || ' ' ||
                 case when p2.shem_mishpacha = 'הסבה'
                   then 'לא מזוהה'
                   else p2.shem_mishpacha end                               "Person Name",
                 sel1.mispar_gimla                                          "Benefit Number"


from
(select distinct porshim.*,
            case when p.mispar_zehut is null then z.mispar_zheut else p.mispar_zehut end mispar_zehut_amiti
from
((select distinct v.mispar_zehut,
                  v.gimla_number mispar_gimla,
                  v.seq_ezor_ovdim,
                  v.seq_prisha,
                  v.seq_porshim
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha = le.seq_bakasha
                                  and v.mispar_zehut = le.mispar_zehut
where v.code_action not in (17,100)
and v.code_sug_bakasha not in (14,7,23)
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
)
)
union
(select distinct v.mispar_zehut,
                  v.gimla_number mispar_gimla,
                  v.seq_ezor_ovdim,
                  v.seq_prisha,
                  v.seq_porshim
from action_log a
left join v_bakasha_last_status v on  v.seq_bakasha = a.seq_bakasha
left join netuney_tik_mechushavim n on n.seq_bakasha = v.seq_bakasha
                                   and n.code_department = 2
where v.code_sug_bakasha = 1
and v.code_action not in (17,100)
and nvl(n.code_department,0) <> 4
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 19
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
and n.date_start_zakaut is not null)
)
union
(select distinct v.mispar_zehut,
                 v.gimla_number mispar_gimla,
                 v.seq_ezor_ovdim,
                 v.seq_prisha,
                 v.seq_porshim
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha = le.seq_bakasha
                                  and v.mispar_zehut <> le.mispar_zehut
/*left join netuney_tik_mechushavim n on
n.seq_bakasha = v.seq_bakasha
and n.code_department = 2
*/
where v.code_action not in (17,100)
--and v.code_sug_bakasha in (1,13,9)
--and n.code_group_prisha = 4
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
)
)
union
select distinct v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha,
                v.seq_porshim
from v_bakasha_last_status v
left join sf_gimlaim_nosafim gn        on gn.mispar_zehut = v.mispar_zehut
where gn.taarich_hosafa >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')

order by 1)
porshim
left join poresh p                   on p.mispar_zehut = porshim.mispar_zehut
left join zheut_fictivi_from_hilan z on z.mispar_zheut_fictivi = porshim.mispar_zehut
left join poresh p1                  on p1.mispar_zehut = z.mispar_zheut
where (p.mispar_zehut is not null or p1.mispar_zehut is not null)
and porshim.seq_ezor_ovdim not in (
155,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149
)
)
sel1

left join poresh p2                  on p2.mispar_zehut = sel1.mispar_zehut_amiti

left join (select seq_porshim, code_bank, code_snif, account_number, mispar_gimla
from (
     select ba.seq_porshim,  code_bank, code_snif, account_number, ba.gimla_number mispar_gimla
               , row_number() over (partition by ba.seq_porshim, ba.gimla_number
                               order by ba.seq_bakasha desc) as rn
from v_bank_account ba
     where /*not exists
           (select v1.seq_bakasha
           from v_bakasha_last_status v1
           where v1.seq_porshim = ba.seq_porshim
           and   v1.gimla_number = ba.gimla_number
           and v1.code_sug_bakasha <> 1)
        or*/ (select distinct first_value(al.code_action) over(partition by al.seq_bakasha order by al.seq_action_log desc)
        from action_log al
        left join code_action ca on
        ca.code_action = al.code_action
        where al.seq_bakasha = ba.seq_bakasha
        and ca.is_status = 1
        ) in (98,129,130,212,41,42))
     where rn = 1) ba1               on ba1.seq_porshim = sel1.seq_porshim
                                     and ba1.mispar_gimla = sel1.mispar_gimla

left join (select seq_porshim, seq_bakasha, code_action, code_sug_bakasha, code_bakasha_detail, taarich_prisha, gimla_number, code_seif_prisha, seq_prisha
from (
select seq_porshim, seq_bakasha, code_action, code_sug_bakasha, code_bakasha_detail, taarich_prisha, gimla_number, code_seif_prisha, seq_prisha
          , row_number() over (partition by seq_porshim, gimla_number
                               order by seq_bakasha desc) as rn
     from v_bakasha_last_status v2
     where (not exists
           (select v3.seq_bakasha
           from v_bakasha_last_status v3
           where v3.seq_porshim = v2.seq_porshim
           and   v3.seq_prisha = v2.seq_prisha
           and v3.code_sug_bakasha not in (1,2,33,35))
           and v2.code_sug_bakasha = 1
           )
           or ((v2.code_sug_bakasha in (1,8,9) or v2.code_sug_bakasha = 5 and v2.code_bakasha_detail = 25)
           and nvl(v2.code_action,0) in (98,129,130,132,212,41,42))
     )
where rn = 1) v1                     on v1.seq_prisha = sel1.seq_prisha
left join v_bakasha_last_zakaut vz   on vz."SEQ_BAKASHA" = v1.seq_bakasha
left join netuney_tik_mechushavim nz on nz.seq_bakasha = v1."SEQ_BAKASHA"
                                     and nz.code_department = 2
--left join code_group_prisha cg       on cg.code_group_prisha = nz.code_group_prisha

where nz.mispar_misra = 0
and nvl(nz.code_group_prisha,0) <> 4

union

select distinct  /*'sheer',
                 sel1.mispar_zehut_ben_mishpacha,
                 v1.code_action,*/
                 encrypt_tz(sel1.seq_prisha)                                "Retirement External ID",
                 encrypt_tz(sel1.mispar_zehut_ben_mishpacha)                "Person Account External ID",
                 case when v1.code_sug_bakasha in (1,13)
                      then vz.date_start_zakaut
                      else /* code_sug_bakasha = 9 */
                           pt.date_payment
                      end                                                   "Eligibility Start date",
                 sel1.to_date_sium_zakaut                                   "Eligibility End date",
                 case when mod(nvl(v1.code_seif_prisha,0),100) not in (26,28)
                           or sel1.code_relative = 26
                           or sel1.code_relative = 9 and sel1.code_kirva not in (1,2,14) then
                           v1.code_seif_prisha
                      when sel1.code_relative = 9 and sel1.code_kirva in (1,2,14) then
                           to_number(to_char( case when sel1.code_kirva = 1 then 1
                                         when sel1.code_kirva = 2 then decode(nvl(sel1.is_taluy,0),1,4,2)
                                         when sel1.code_kirva = 14 then 5 end) ||
                           to_char(mod(v1.code_seif_prisha,100)))
                      else to_number(to_char(decode(sel1.code_relative,6,1,7,1,8,2,sel1.code_relative)) ||
                           to_char(mod(v1.code_seif_prisha,100)))
                      end                                                   "Retirement Section",
                 sel1.code_relative                                         "Type Of Benefit",
                 case when ba1.code_bank is not null then
                   ba1.code_bank
                 else
                   999 end                                                  "Bank",
                 case when ba1.code_bank is not null
                       and ba1.code_snif is not null then
                   ba1.code_bank * 1000 + ba1.code_snif 
                 else 999999 end                                            "BranchNumber",
                 ba1.account_number                                         "Account",
                 encrypt_tz(v1.seq_prisha * 1000000000 + sel1.mispar_zehut_ben_mishpacha)  "Eligibility External ID",
                 sel1.shem_prati || ' ' || sel1.shem_mishpacha              "Person Name",
                 sel1.mispar_gimla                                          "Benefit Number"

from
(select distinct sheerim.*,
b1.shem_prati, b1.shem_mishpacha, b1.code_relative, b1.code_kirva, b1.is_taluy, b1.to_date_sium_zakaut, b1.mispar_zehut_ben_mishpacha
from(
select distinct le.mispar_zehut mispar_zehut_sheer,
                b0.seq_bney_mishpacha,
                v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha = le.seq_bakasha
                                 and v.mispar_zehut <> le.mispar_zehut
left join poresh p0              on p0.mispar_zehut = v.mispar_zehut
left join bney_mishpacha b0      on b0.mispar_zehut_ben_mishpacha = le.mispar_zehut
                                 and b0.seq_porshim = p0.porshim_seq
where v.code_action not in (17,100)
and v.code_sug_bakasha not in (14,7,23)
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
)
union
select distinct b.mispar_zehut_ben_mishpacha mispar_zehut_sheer,
                b.seq_bney_mishpacha,
                v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha  = le.seq_bakasha
                                  and v.mispar_zehut = le.mispar_zehut
left join poresh p                on  p.mispar_zehut = v.mispar_zehut
left join bney_mishpacha b        on  b.seq_porshim  = p.porshim_seq
where v.code_action not in (17,100)
and (v.code_sug_bakasha in (1,8,9) or v.code_sug_bakasha = 5 and v.code_bakasha_detail = 25)
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
and b.mispar_zehut_ben_mishpacha is not null)
union
select distinct b.mispar_zehut_ben_mishpacha mispar_zehut_sheer,
                b.seq_bney_mishpacha,
                v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha
from v_bakasha_last_status v
left join sf_gimlaim_nosafim gn        on gn.mispar_zehut = v.mispar_zehut
left join poresh p                     on p.mispar_zehut = v.mispar_zehut
left join bney_mishpacha b             on b.seq_porshim = p.porshim_seq
where gn.taarich_hosafa >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
order by 1)
sheerim
left join bney_mishpacha b1           on b1.seq_bney_mishpacha  = sheerim.seq_bney_mishpacha
where sheerim.mispar_zehut_sheer is not null
and b1.mispar_zehut_ben_mishpacha not in
(1911817,
1540699,
3534815,
4119863,
4882288,
43292804,
42554949,
47639422,
46708319,
45923224,
65320293,
67433458
)
and b1.code_relative is not null
and nvl(b1.shem_prati,' ') <> substr(nvl(b1.shem_prati,' '),1,1)
and b1.mispar_zehut_ben_mishpacha not in(1,18,26,34,59,67)
and nvl(b1.sug_zihuy,0) <> 5
and b1.mispar_zehut_ben_mishpacha <> 111111111
and b1.shem_mishpacha is not null
and nvl(b1.code_kirva,0) not in (0/*,24*/,25)
and sheerim.seq_ezor_ovdim not in (
155,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149
)
) sel1

left join bney_mishpacha b2          on  b2.seq_bney_mishpacha = sel1.seq_bney_mishpacha

left join (select seq_bney_mishpacha, code_bank, code_snif, account_number, mispar_gimla
from (
     select ba.seq_bney_mishpacha,  code_bank, code_snif, account_number, ba.gimla_number mispar_gimla
               , row_number() over (partition by ba.seq_bney_mishpacha, ba.gimla_number
                               order by ba.seq_bakasha desc) as rn
     from v_bank_account ba
     where (select distinct first_value(al.code_action) over(partition by al.seq_bakasha order by al.seq_action_log desc)
        from action_log al
        left join code_action ca on
        ca.code_action = al.code_action
        where al.seq_bakasha = ba.seq_bakasha
        and ca.is_status = 1
        ) in (98,129,130,212,41,42))
     where rn = 1) ba1               on ba1.seq_bney_mishpacha = sel1.seq_bney_mishpacha
                                     and ba1.mispar_gimla = sel1.mispar_gimla

left join (select seq_porshim, seq_bakasha, code_action, code_sug_bakasha, code_bakasha_detail, taarich_prisha, gimla_number, code_seif_prisha, seq_prisha
from (
     select seq_porshim, seq_bakasha, code_action, code_sug_bakasha, code_bakasha_detail, taarich_prisha, gimla_number, code_seif_prisha, seq_prisha
          , row_number() over (partition by seq_porshim, gimla_number
                               order by seq_bakasha desc) as rn
     from v_bakasha_last_status v2
     where v2.code_sug_bakasha in (1,13,9)
           and v2.code_action in (98,129,130,212,41,42)
     )
where rn = 1) v1                     on v1.seq_prisha = sel1.seq_prisha
left join v_bakasha_last_zakaut vz   on vz."SEQ_BAKASHA" = v1.seq_bakasha
left join netuney_tik_mechushavim nz on nz.seq_bakasha = vz."SEQ_BAKASHA"
                                     and nz.code_department = 2
                                     and nvl(nz.code_group_prisha,0) = 4
left join participation pt           on pt.seq_bakasha = v1.seq_bakasha
where v1.seq_bakasha is not null
and (nz.mispar_misra = 0 and nvl(nz.code_group_prisha,0) = 4 or b2.code_relative = 6)
    order by 3,1,2;
end get_SF_Eligibility_19;
/

create or replace procedure prm_system_copy.get_SF_Eligibility_First(Eligibility Out sys_refcursor) is

begin
open Eligibility for
select distinct  encrypt_tz(sel1.seq_prisha)                                "Retirement External ID",
                 encrypt_tz(p2.mispar_zehut)                                "Person Account External ID",
                 vz.taarich_prisha                                          "Eligibility Start date",
                 case when p2.taarich_ptira is null then null
                 else to_date('01/' || 
                 to_char(add_months(p2.taarich_ptira,1),'mm/yyyy'),       
                 'dd/mm/yyyy') - 1 end                                      "Eligibility End date",
                 v1.code_seif_prisha                                        "Retirement Section",
                 0                                                          "Type Of Benefit",
                 ba2.code_bank                                              "Bank",
                 case when ba2.code_bank is not null 
                       and ba2.code_snif is not null then 
                   ba2.code_bank * 1000 + ba2.code_snif
                 else null end                                              "BranchNumber",
                 ba2.account_number                                         "Account",
                 encrypt_tz(v1.seq_prisha * 1000000000 + p2.mispar_zehut)   "Eligibility External ID",
                 case when p2.shem_prati = 'הסבה'
                   then 'לא מזוהה'
                   else p2.shem_prati end || ' ' ||
                 case when p2.shem_mishpacha = 'הסבה'
                   then 'לא מזוהה'
                   else p2.shem_mishpacha end                               "Person Name",
                 pr.gimla_number                                            "Benefit Number"/*,
                 'poresh'                                                   sug*/

from v_porshim2 sel1
left join poresh p2                  on p2.mispar_zehut = sel1.mispar_zehut_amiti
--left join tz_crm tz                  on tz.mispar_zehut = sel1.mispar_zehut_amiti
left join prisha pr                  on pr.seq_poresh = p2.porshim_seq
                                     and pr.seq_prisha = sel1.seq_prisha
left join code_ezor_ovdim ce         on ce.seq_ezor_ovdim = pr.seq_ezor_ovdim
left join (select seq_porshim, seq_bank_account, gimla_number
from (
     select seq_porshim,  seq_bank_account , gimla_number
               , row_number() over (partition by seq_porshim, gimla_number
                               order by seq_bakasha desc) as rn
     from v_bank_account ba
     where (select distinct first_value(al.code_action) over(partition by al.seq_bakasha order by al.seq_action_log desc) 
        from action_log al
        left join code_action ca on
        ca.code_action = al.code_action
        where al.seq_bakasha = ba.seq_bakasha
        and ca.is_status = 1
        ) in (98,129,130)
     and seq_bney_mishpacha is null )
where rn = 1) ba1                    on ba1.seq_porshim = p2.porshim_seq
                                     and ba1.gimla_number = pr.gimla_number
left join bank_account ba2           on ba2.seq_bank_account = ba1.seq_bank_account

left join (select seq_porshim, seq_bakasha, code_action, code_sug_bakasha, code_bakasha_detail, taarich_prisha, gimla_number, code_seif_prisha, seq_prisha
from (
select seq_porshim, seq_bakasha, code_action, code_sug_bakasha, code_bakasha_detail, taarich_prisha, gimla_number, code_seif_prisha, seq_prisha
          , row_number() over (partition by seq_porshim, gimla_number
                               order by seq_bakasha desc) as rn
     from v_bakasha_last_status v2
     where (v2.code_sug_bakasha in (1,8) or v2.code_sug_bakasha = 5 and v2.code_bakasha_detail = 25)
           and v2.code_action in (98,129,130)
     )
where rn = 1) v1                     on v1.seq_prisha = sel1.seq_prisha
left join v_bakasha_last_zakaut vz   on vz."SEQ_BAKASHA" = v1.seq_bakasha
left join netuney_tik_mechushavim nz on nz.seq_bakasha = vz."SEQ_BAKASHA"
                                     and nz.code_department = 2
                                     and nvl(nz.code_group_prisha,0) <> 4
left join code_group_prisha cg       on cg.code_group_prisha = nz.code_group_prisha

where nvl(v1.code_action,0) in (98,129,130)
and nz.mispar_misra = 0
/*and not exists
(select b1.seq_bakasha
    from bakasha b1
    left join v_bakasha_last_status bv1 on
    bv1.seq_bakasha = b1.seq_bakasha
    where b1.seq_prisha = pr.seq_prisha
    and b1.code_sug_bakasha = 19
    and b1.code_bakasha_detail not in (12,181)
    and b1.seq_bney_mishpacha is null
    and b1.from_date > to_date('01/10/2021','dd/mm/yyyy')
    and bv1.code_action <> 17
    and not exists
    (select b2.seq_bakasha
    from bakasha b2
    left join v_bakasha_last_status bv2 on
    bv2.seq_bakasha = b2.seq_bakasha
    where b2.seq_prisha = pr.seq_prisha
    and b2.code_sug_bakasha = 20
    and b2.seq_bney_mishpacha is null
    and b2.from_date >= b1.from_date
    and bv2.code_action <> 17)
)*/
--and p2.taarich_ptira is null
--and tz.mispar_zehut is not null


union

select distinct  encrypt_tz(sel1.seq_prisha)                                "Retirement External ID",
                 encrypt_tz(bm2.mispar_zehut_ben_mishpacha)                 "Person Account External ID",
                 vz.date_start_zakaut                                       "Eligibility Start date",
                 bm2.to_date_sium_zakaut                                    "Eligibility End date",
                 case when mod(nvl(v1.code_seif_prisha,0),100) not in (26,28)
                           or bm2.code_relative = 26
                           or bm2.code_relative = 9 and bm2.code_kirva not in (1,2,14) then
                           v1.code_seif_prisha
                      when bm2.code_relative = 9 and bm2.code_kirva in (1,2,14) then
                           to_number(to_char( case when bm2.code_kirva = 1 then 1
                                         when bm2.code_kirva = 2 then decode(nvl(bm2.is_taluy,0),1,4,2)
                                         when bm2.code_kirva = 14 then 5 end) ||
                           to_char(mod(v1.code_seif_prisha,100)))
                      else to_number(to_char(decode(bm2.code_relative,6,1,7,1,8,2,bm2.code_relative)) ||
                           to_char(mod(v1.code_seif_prisha,100)))
                      end                                                   "Retirement Section",
                 bm2.code_relative                                          "Type Of Benefit",
                 ba2.code_bank                                              "Bank",
                 case when ba2.code_bank is not null 
                       and ba2.code_snif is not null then 
                   ba2.code_bank * 1000 + ba2.code_snif
                 else null end                                              "BranchNumber",
                 ba2.account_number                                         "Account",
                 encrypt_tz(sel1.seq_prisha * 1000000000 + bm2.mispar_zehut_ben_mishpacha)  "Eligibility External ID",
                 bm2.shem_prati || ' ' || bm2.shem_mishpacha                "Person Name",
                 sel1.gimla_number                                          "Benefit Number"/*,
                 'sheer'*/
from
(select porshim.mispar_zehut_amiti, bm3.seq_bney_mishpacha, pr.seq_prisha, pr.gimla_number, bm3.mispar_zehut_ben_mishpacha
from v_porshim2 porshim
left join poresh p                   on p.mispar_zehut = porshim.mispar_zehut_amiti
--left join tz_crm tz                  on tz.mispar_zehut = porshim.mispar_zehut
left join bney_mishpacha bm3         on bm3.seq_porshim = p.porshim_seq
left join prisha pr                  on/* pr.seq_poresh = bm3.seq_porshim
