and bm3.shem_mishpacha is not null
and nvl(bm3.code_kirva,0) not in(0,24,25)
and bm3.mispar_zehut_ben_mishpacha not in
(1911817,
1540699,
3534815,
4119863,
4882288,
43292804,
42554949,
47639422,
46708319,
45923224,
65320293,
67433458
)
and pr.seq_ezor_ovdim
not in (
155,
159,
163,
164,
225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
10154,
10149
)
