from (
     select seq_poresh, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
          , row_number() over (partition by seq_poresh
                               order by nvl(date_mazav_mishpachti,to_date('01/01/1900','dd/mm/yyyy')) desc, seq_mazav_mishpachti desc) as rn
     from mazav_mishpachti mm1
     where mm1.seq_bney_mishpacha is null
     and (nvl(mm1.seq_bakasha,0) = 0 or
     (select distinct first_value(al.code_action) over(partition by al.seq_bakasha order by al.seq_action_log desc)
        from action_log al
        left join code_action ca on
        ca.code_action = al.code_action
