                 a1.street                                           "Street",
                 a1.house                                            "Street Number",
                 a1.apartment                                        "Apartment Number",
                 a1.entrance                                         "Entrance",
                 case when exists
                 (select t.code_ir
                 from code_ir t
                 where a1.code_city is null or t.code_ir = a1.code_city and a1.code_city <> 0)
                      then a1.code_city
                      else null end                                  "City",
                 a1.mikud                                            "Postal Code",

                 case when pk_hilan.get_telephone(
                   case when b2.code_relative is null and p3.mispar_zehut is not null then p3.telephon else
                                                                                           b2.telephone end, 1) = '0000000000'
