left join poresh p2                  on  p2.mispar_zehut = sel1.mispar_zehut
left join bney_mishpacha b2          on  b2.seq_bney_mishpacha = sel1.seq_bney_mishpacha
left join poresh p3                  on p3.mispar_zehut = b2.mispar_zehut_ben_mishpacha
left join (select seq_bney_mishpacha, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
from (
     select seq_bney_mishpacha, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
          , row_number() over (partition by seq_bney_mishpacha
                               order by nvl(date_mazav_mishpachti,to_date('01/01/1900','dd/mm/yyyy')) desc, seq_mazav_mishpachti desc) as rn
     from mazav_mishpachti mm1
     where nvl(mm1.seq_bakasha,0) = 0 or
     (select distinct first_value(al.code_action) over(partition by al.seq_bakasha order by al.seq_action_log desc)
        from action_log al
        left join code_action ca on
        ca.code_action = al.code_action
        where al.seq_bakasha = mm1.seq_bakasha
        and ca.is_status = 1
        ) in (98,129,130,212,41,42))
where rn = 1) mm2                    on mm2.seq_bney_mishpacha = b2.seq_bney_mishpacha
--left join code_matsav_mishpachti cmm on cmm.code_mazav_mishpachti = mm2.code_mazav_mishpachti
left join (select seq_bney_mishpacha, code_address, seq_address, street, house, apartment, entrance, code_city, mikud
from (
     select seq_bney_mishpacha, code_address, seq_address, street, house, apartment, entrance, code_city, mikud
          , row_number() over (partition by seq_bney_mishpacha
                               order by code_address desc, seq_address desc) as rn
     from address a
     where a.seq_bakasha is null
        or not exists
           (select v1.seq_bakasha
           from v_bakasha_last_status v1
           where v1.seq_porshim = a.seq_poresh
           and v1.code_sug_bakasha not in (1,2,33,35))
        or (select distinct first_value(al.code_action) over(partition by al.seq_bakasha order by al.seq_action_log desc)
        from action_log al
        left join code_action ca on
        ca.code_action = al.code_action
        where al.seq_bakasha = a.seq_bakasha
        and ca.is_status = 1
        ) in (98,129,130,212,41,42))
where rn = 1) a1                     on a1.seq_bney_mishpacha = b2.seq_bney_mishpacha

order by 2;

end get_SF_person;
/

create or replace procedure prm_system_copy.get_SF_Person_19(from_date In Varchar2, Person Out sys_refcursor) is
begin

open Person for

select distinct  --'poresh' sug,
                 encrypt_tz(p2.mispar_zehut)                         "Person Account External ID",
                 p2.mispar_zehut                                     "ID Number",
                 case when p2.shem_prati = 'הסבה'
                   then 'לא מזוהה'
                   else p2.shem_prati end                            "First Name",
                 case when p2.shem_mishpacha = 'הסבה'
                   then 'לא מזוהה'
                   else p2.shem_mishpacha end                        "Last Name",
                 p2.code_min                                         "Gender",
                 case when p2.taarich_leda <= to_date('01/01/1900','dd/mm/yyyy')
                        or p2.taarich_leda is null then null
                      else p2.taarich_leda end                       "Date of birth",
                 p2.taarich_ptira                                    "Date of death",
                 a1.street                                           "Street",
                 a1.house                                            "Street number",
                 a1.apartment                                        "Apartment Number",
                 a1.entrance                                         "Entrance",
                 case when exists
                 (select t.code_ir
                 from code_ir t
                 where a1.code_city is null or t.code_ir = a1.code_city and a1.code_city <> 0)
                      then a1.code_city
                      else null end                                  "City",
                 a1.mikud                                            "Postal Code",
                 case when pk_hilan.get_telephone(p2.telephon) = '0000000000'
                   then null
                   else pk_hilan.get_telephone(p2.telephon) end  "Phone",
                 case when pk_hilan.get_telephone(p2.telephon2) = '0000000000'
                   then null
                   else pk_hilan.get_telephone(p2.telephon2) end "Other Phone",
                 case when pk_hilan.get_telephone(p2.pelephon) = '0000000000'
                   then null
                   else pk_hilan.get_telephone(p2.pelephon) end  "Mobile",
                 p2.email                                            "Email",
                 case when mm2.code_mazav_mishpachti = 999
                        or mm2.code_mazav_mishpachti is null then null
                      else mm2.code_mazav_mishpachti end             "Marital Status",
                 case when mm2.date_mazav_mishpachti < to_date('01/01/1900','dd/mm/yyyy')
                        or mm2.date_mazav_mishpachti is null then null
                      else mm2.date_mazav_mishpachti end             "Marital Status Date",
                 null                                                "Hilan Code"
from
(select distinct porshim.*,
            case when p.mispar_zehut is null then z.mispar_zheut else p.mispar_zehut end mispar_zehut_amiti
from
((select distinct v.mispar_zehut,
                  v.gimla_number mispar_gimla,
                  v.seq_ezor_ovdim,
                  v.seq_prisha,
                  --f_get_documents(v.seq_bakasha,'p',from_date)
                  0
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha = le.seq_bakasha
                                  and v.mispar_zehut = le.mispar_zehut
where v.code_action not in (17,100)
and v.code_sug_bakasha not in (14,7,23)
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
)
)
union
(select distinct v.mispar_zehut,
                  v.gimla_number mispar_gimla,
                  v.seq_ezor_ovdim,
                  v.seq_prisha,
                  0
from action_log a
left join v_bakasha_last_status v on  v.seq_bakasha = a.seq_bakasha
left join netuney_tik_mechushavim n on n.seq_bakasha = v.seq_bakasha
                                   and n.code_department = 2
where v.code_sug_bakasha = 1
and v.code_action not in (17,100)
and nvl(n.code_department,0) <> 4
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 19
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
and n.date_start_zakaut is not null)
)
union
(select distinct v.mispar_zehut,
                 v.gimla_number mispar_gimla,
                 v.seq_ezor_ovdim,
                 v.seq_prisha,
                 --f_get_documents(v.seq_bakasha,'p',from_date)
                 0
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha = le.seq_bakasha
                                  and v.mispar_zehut <> le.mispar_zehut
/*left join netuney_tik_mechushavim n on
n.seq_bakasha = v.seq_bakasha
and n.code_department = 2*/
where v.code_action not in (17,100)
--and v.code_sug_bakasha in (1,13,9)
--and n.code_group_prisha = 4
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
)
)
union
select distinct p.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha,
                0
from poresh p
left join v_bakasha_last_status v on
v.seq_porshim = p.porshim_seq
where sysdate - p.date_update_pelmail < 0.084
and v.code_sug_bakasha in (33,35)
and v.code_action in (134,135)
and exists
(select r.person_id
from requests_crm r
where r.person_id = p.mispar_zehut
and   r.subject_code = case when v.code_sug_bakasha = 33 then 169 else 175 end
and   sysdate - r.ld_date < 0.125
and   r.seq_bakasha = v.seq_bakasha
and   r.is_bakasha_butla = 0)
union
select distinct v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha,
                0            
from bney_mishpacha b
left join v_bakasha_last_status v on
v.seq_porshim = b.seq_porshim
left join bakasha bk on
bk.seq_bney_mishpacha = b.seq_bney_mishpacha
where sysdate - b.date_update_pelmail < 0.084
and v.code_sug_bakasha in (33,35)
and v.code_action in (134,135)
and exists
(select r.person_id
from requests_crm r
where r.person_id = b.mispar_zehut_ben_mishpacha
and   r.subject_code = case when v.code_sug_bakasha = 33 then 169 else 175 end
and   sysdate - r.ld_date < 0.125
and   r.seq_bakasha = v.seq_bakasha
and   r.is_bakasha_butla = 0)
union
select distinct v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha,
                0               
from v_bakasha_last_status v
left join sf_gimlaim_nosafim gn        on gn.mispar_zehut = v.mispar_zehut
where gn.taarich_hosafa >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
union
select distinct v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha,
                0
from sf_gimlaim_nosafim s
left join v_bakasha_last_status v on v.mispar_zehut = s.mispar_zehut
where v.code_source = 24
and v.code_action = 98
and v.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
union
select distinct v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha,
                0              
from action_log al
left join v_bakasha_last_status v on v.seq_bakasha = al.seq_bakasha
where v.code_source = 24
and v.code_action = 98
and al.code_action = 210
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')

order by 1)
porshim
left join poresh p                   on p.mispar_zehut = porshim.mispar_zehut
left join zheut_fictivi_from_hilan z on z.mispar_zheut_fictivi = porshim.mispar_zehut
left join poresh p1                  on p1.mispar_zehut = z.mispar_zheut
where (p.mispar_zehut is not null or p1.mispar_zehut is not null)
and porshim.seq_ezor_ovdim not in (
155,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149
)
)
 sel1
left join poresh p2                  on p2.mispar_zehut = sel1.mispar_zehut_amiti
left join (select seq_poresh, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
from (
     select seq_poresh, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
          , row_number() over (partition by seq_poresh
                               order by nvl(date_mazav_mishpachti,to_date('01/01/1900','dd/mm/yyyy')) desc, seq_mazav_mishpachti desc) as rn
     from mazav_mishpachti mm1
     where mm1.seq_bney_mishpacha is null
     and (nvl(mm1.seq_bakasha,0) = 0 or
     (select distinct first_value(al.code_action) over(partition by al.seq_bakasha order by al.seq_action_log desc)
        from action_log al
        left join code_action ca on
        ca.code_action = al.code_action
        where al.seq_bakasha = mm1.seq_bakasha
        and ca.is_status = 1
        ) in (98,129,130,212,41,42)))
where rn = 1) mm2                    on mm2.seq_poresh = p2.porshim_seq
--left join code_matsav_mishpachti cmm on cmm.code_mazav_mishpachti = mm2.code_mazav_mishpachti
left join (select seq_poresh, code_address, seq_address, street, house, apartment, entrance, code_city, mikud
from (
     select seq_poresh, code_address, seq_address, street, house, apartment, entrance, code_city, mikud
          , row_number() over (partition by seq_poresh
                               order by code_address desc, seq_address desc) as rn
     from address a
     where a.seq_bakasha is null
        or not exists
           (select v1.seq_bakasha
           from v_bakasha_last_status v1
           where v1.seq_porshim = a.seq_poresh
           and v1.code_sug_bakasha not in (1,2,33,35))
        or (select distinct first_value(al.code_action) over(partition by al.seq_bakasha order by al.seq_action_log desc)
        from action_log al
        left join code_action ca on
        ca.code_action = al.code_action
        where al.seq_bakasha = a.seq_bakasha
        and ca.is_status = 1
        ) in (98,129,130,212,41,42))
where rn = 1) a1                     on a1.seq_poresh = p2.porshim_seq


union

select distinct  --'sheer' sug,
                 encrypt_tz(b2.mispar_zehut_ben_mishpacha)           "Person Account External ID",
                 b2.mispar_zehut_ben_mishpacha                       "ID Number",
                 b2.shem_prati                                       "First Name",
                 b2.shem_mishpacha                                   "Last Name",
                 b2.code_min                                         "Gender",
                 case when b2.taarich_leda <= to_date('01/01/1900','dd/mm/yyyy')
                        or b2.taarich_leda is null then null
                      else b2.taarich_leda end                       "Date of birth",
                 b2.taarich_ptira                                    "Date of death",
                 a1.street                                           "Street",
                 a1.house                                            "Street Number",
                 a1.apartment                                        "Apartment Number",
                 a1.entrance                                         "Entrance",
                 case when exists
                 (select t.code_ir
                 from code_ir t
                 where a1.code_city is null or t.code_ir = a1.code_city and a1.code_city <> 0)
                      then a1.code_city
                      else null end                                  "City",
                 a1.mikud                                            "Postal Code",
                 case when pk_hilan.get_telephone(b2.telephone) = '0000000000'
                   then null
                   else pk_hilan.get_telephone(b2.telephone) end  "Phone",
                 null                                                "Other Phone",
                 case when pk_hilan.get_telephone(b2.pelephone) = '0000000000'
                   then null
                   else pk_hilan.get_telephone(b2.pelephone) end "Mobile",
                 b2.email                                            "Email",
                 case when mm2.code_mazav_mishpachti = 999
                        or mm2.code_mazav_mishpachti is null then null
                      else mm2.code_mazav_mishpachti end             "Marital Status",
                 case when mm2.date_mazav_mishpachti <= to_date('01/01/1900','dd/mm/yyyy')
                        or mm2.date_mazav_mishpachti is null then null
                      else mm2.date_mazav_mishpachti end             "Marital Status Date",
                 null                                                "Hilan Code"
from
(select distinct sheerim.*--, b1.*
from(
select distinct le.mispar_zehut mispar_zehut_sheer,
                b.seq_bney_mishpacha,
                v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha,
                --f_get_documents(v.seq_bakasha,'s',from_date)
                0                
from ld_log_events le
left join v_bakasha_last_status v on v.seq_bakasha = le.seq_bakasha
                                 and v.mispar_zehut <> le.mispar_zehut
left join poresh p                on p.mispar_zehut = v.mispar_zehut
left join bney_mishpacha b        on b.mispar_zehut_ben_mishpacha = le.mispar_zehut
                                   and b.seq_porshim = p.porshim_seq
where v.code_action not in (17,100)
and v.code_sug_bakasha not in (14,7,23)
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
)
union
select distinct b.mispar_zehut_ben_mishpacha mispar_zehut_sheer,
                b.seq_bney_mishpacha,
                v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha,
                --f_get_documents(v.seq_bakasha,'s',from_date),
                0
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha  = le.seq_bakasha
                                  and v.mispar_zehut = le.mispar_zehut
left join poresh p               on  p.mispar_zehut = v.mispar_zehut
left join bney_mishpacha b       on  b.seq_porshim  = p.porshim_seq
where v.code_action not in (17,100)
--and (v.code_sug_bakasha in (1,8) or v.code_sug_bakasha = 5 and v.code_bakasha_detail = 25)
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS'))
and b.mispar_zehut_ben_mishpacha is not null


union
(select distinct  b.mispar_zehut_ben_mishpacha,
                  b.seq_bney_mishpacha,
                  v.mispar_zehut,
                  v.gimla_number mispar_gimla,
                  v.seq_ezor_ovdim,
                  v.seq_prisha,
                  0
from action_log a
left join v_bakasha_last_status v on  v.seq_bakasha = a.seq_bakasha
left join netuney_tik_mechushavim n on n.seq_bakasha = v.seq_bakasha
                                  and n.code_department = 2
left join bney_mishpacha b        on b.seq_porshim = v.seq_porshim
where v.code_sug_bakasha = 1
and v.code_action not in (17,100)
and nvl(n.code_department,0) <> 4
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 19
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
and n.date_start_zakaut is not null)
)
union
select distinct b.mispar_zehut_ben_mishpacha mispar_zehut_sheer,
                b.seq_bney_mishpacha,
                v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha,
                0
from bney_mishpacha b
left join v_bakasha_last_status v on
v.seq_porshim = b.seq_porshim
left join bakasha bk on
bk.seq_bney_mishpacha = b.seq_bney_mishpacha
where sysdate - b.date_update_pelmail < 0.084
and v.code_sug_bakasha in (33,35)
and v.code_action in (134,135)
and exists
(select r.person_id
from requests_crm r
where r.person_id = b.mispar_zehut_ben_mishpacha
and   r.subject_code = case when v.code_sug_bakasha = 33 then 169 else 175 end
and   sysdate - r.ld_date < 0.125
and   r.seq_bakasha = v.seq_bakasha
and   r.is_bakasha_butla = 0)
union
select distinct b.mispar_zehut_ben_mishpacha mispar_zehut_sheer,
                b.seq_bney_mishpacha,
                v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha,
                0
from v_bakasha_last_status v
left join sf_gimlaim_nosafim gn        on gn.mispar_zehut = v.mispar_zehut
left join poresh p                     on p.mispar_zehut = v.mispar_zehut
left join bney_mishpacha b             on b.seq_porshim = p.porshim_seq
where gn.taarich_hosafa >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
union
select distinct b.mispar_zehut_ben_mishpacha mispar_zehut_sheer,
                b.seq_bney_mishpacha,
                v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha,
                0
from action_log al
left join v_bakasha_last_status v      on v.seq_bakasha = al.seq_bakasha
left join bney_mishpacha b             on b.seq_porshim = v.seq_porshim
where v.code_source = 24
and v.code_action = 98
and al.code_action = 210
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')

order by 1
)
sheerim
left join bney_mishpacha b1           on b1.seq_bney_mishpacha  = sheerim.seq_bney_mishpacha
where sheerim.mispar_zehut_sheer is not null
and b1.mispar_zehut_ben_mishpacha not in
(1911817,
1540699,
3534815,
4119863,
4882288,
43292804,
42554949,
47639422,
46708319,
45923224,
65320293,
67433458
)
and b1.code_kirva is not null
and nvl(b1.shem_prati,' ') <> substr(nvl(b1.shem_prati,' '),1,1)
and b1.mispar_zehut_ben_mishpacha not in(1,18,26,34,59,67)
and nvl(b1.sug_zihuy,0) <> 5
and b1.mispar_zehut_ben_mishpacha <> 111111111
and b1.shem_mishpacha is not null
and nvl(b1.code_kirva,0) not in (0/*,24*/,25)
and b1.shem_mishpacha is not null
and sheerim.seq_ezor_ovdim not in (
155,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149
)
and b1.mispar_zehut_ben_mishpacha not in
(select distinct case when p.mispar_zehut is null then z.mispar_zheut else p.mispar_zehut end mispar_zehut_amiti
from
((select distinct v.mispar_zehut,
                  v.gimla_number mispar_gimla,
                  v.seq_ezor_ovdim,
                  v.seq_prisha
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha = le.seq_bakasha
                                  and v.mispar_zehut = le.mispar_zehut
where v.code_action not in (17,100)
and v.code_sug_bakasha not in (14,7,23)
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
)
)
union
(select distinct v.mispar_zehut,
                 v.gimla_number mispar_gimla,
                 v.seq_ezor_ovdim,
                 v.seq_prisha
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha = le.seq_bakasha
                                  and v.mispar_zehut <> le.mispar_zehut
/*left join netuney_tik_mechushavim n on
n.seq_bakasha = v.seq_bakasha
and n.code_department = 2
*/
where v.code_action not in (17,100)
--and v.code_sug_bakasha in (1,13,9)
--and n.code_group_prisha = 4
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
)
)
union
select distinct v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha
from bney_mishpacha b
left join v_bakasha_last_status v on
v.seq_porshim = b.seq_porshim
left join bakasha bk on
bk.seq_bney_mishpacha = b.seq_bney_mishpacha
where sysdate - b.date_update_pelmail < 0.084
and v.code_sug_bakasha in (33,35)
and v.code_action in (134,135)
and exists
(select r.person_id
from requests_crm r
where r.person_id = b.mispar_zehut_ben_mishpacha
and   r.subject_code = case when v.code_sug_bakasha = 33 then 169 else 175 end
and   sysdate - r.ld_date < 0.125
and   r.seq_bakasha = v.seq_bakasha
and   r.is_bakasha_butla = 0)
union
select distinct v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha
from v_bakasha_last_status v
left join sf_gimlaim_nosafim gn        on gn.mispar_zehut = v.mispar_zehut
where gn.taarich_hosafa >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
order by 1)
porshim
left join poresh p                   on p.mispar_zehut = porshim.mispar_zehut
left join zheut_fictivi_from_hilan z on z.mispar_zheut_fictivi = porshim.mispar_zehut
left join poresh p1                  on p1.mispar_zehut = z.mispar_zheut
where (p.mispar_zehut is not null or p1.mispar_zehut is not null)
and porshim.seq_ezor_ovdim not in (
155,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149
)
)
) sel1

left join poresh p2                  on  p2.mispar_zehut = sel1.mispar_zehut
left join bney_mishpacha b2          on  b2.seq_bney_mishpacha = sel1.seq_bney_mishpacha
left join (select seq_bney_mishpacha, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
from (
     select seq_bney_mishpacha, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
          , row_number() over (partition by seq_bney_mishpacha
                               order by nvl(date_mazav_mishpachti,to_date('01/01/1900','dd/mm/yyyy')) desc, seq_mazav_mishpachti desc) as rn
     from mazav_mishpachti mm1
     where nvl(mm1.seq_bakasha,0) = 0 or
     (select distinct first_value(al.code_action) over(partition by al.seq_bakasha order by al.seq_action_log desc)
        from action_log al
        left join code_action ca on
        ca.code_action = al.code_action
        where al.seq_bakasha = mm1.seq_bakasha
        and ca.is_status = 1
        ) in (98,129,130,212,41,42))
where rn = 1) mm2                    on mm2.seq_bney_mishpacha = b2.seq_bney_mishpacha
--left join code_matsav_mishpachti cmm on cmm.code_mazav_mishpachti = mm2.code_mazav_mishpachti
left join (select seq_bney_mishpacha, code_address, seq_address, street, house, apartment, entrance, code_city, mikud
from (
     select seq_bney_mishpacha, code_address, seq_address, street, house, apartment, entrance, code_city, mikud
          , row_number() over (partition by seq_bney_mishpacha
                               order by code_address desc, seq_address desc) as rn
     from address a
     where a.seq_bakasha is null
        or not exists
           (select v1.seq_bakasha
           from v_bakasha_last_status v1
           where v1.seq_porshim = a.seq_poresh
           and v1.code_sug_bakasha not in (1,2,33,35))
        or (select distinct first_value(al.code_action) over(partition by al.seq_bakasha order by al.seq_action_log desc)
        from action_log al
        left join code_action ca on
        ca.code_action = al.code_action
        where al.seq_bakasha = a.seq_bakasha
        and ca.is_status = 1
        ) in (98,129,130,212,41,42))
where rn = 1) a1                     on a1.seq_bney_mishpacha = b2.seq_bney_mishpacha

order by 2;

end get_SF_person_19;
/

create or replace procedure prm_system_copy.get_SF_person_first(Person Out sys_refcursor) is

begin
open Person for

select distinct  encrypt_tz(p3.mispar_zehut)                         "Person Account External ID",
                 pk_hilan_prd.lpad_zeroez(p3.mispar_zehut,9)         "ID Number",
                 case when p3.shem_prati = 'הסבה'
                   then 'לא מזוהה'
                   else p3.shem_prati end                            "First Name",
                 case when p3.shem_mishpacha = 'הסבה'
                   then 'לא מזוהה'
                   else p3.shem_mishpacha end                        "Last Name",
                 p3.code_min                                         "Gender",
                 case when p3.taarich_leda <= to_date('01/01/1900','dd/mm/yyyy')
                        or p3.taarich_leda is null then null
                      else p3.taarich_leda end                       "Date of birth",
                 p3.taarich_ptira                                    "Date of death",
                 a1.street                                           "Street",
                 a1.house                                            "Street number",
                 a1.apartment                                        "Apartment Number",
                 case when exists
                 (select t.code_ir
                 from code_ir t
                 where a1.code_city is null or t.code_ir = a1.code_city and a1.code_city <> 0)
                      then a1.code_city
                      else null end                                  "City",
                 a1.mikud                                            "Postal Code",
                 case when pk_hilan_prd.get_telephone(p3.telephon) = '0000000000'
                   then null
                   else pk_hilan_prd.get_telephone(p3.telephon) end  "Phone",
                 case when pk_hilan_prd.get_telephone(p3.telephon2) = '0000000000'
                   then null
                   else pk_hilan_prd.get_telephone(p3.telephon2) end "Other Phone",
                 case when pk_hilan_prd.get_telephone(p3.pelephon) = '0000000000'
                   then null
                   else pk_hilan_prd.get_telephone(p3.pelephon) end  "Mobile",
                 p3.email                                            "Email",
                 case when mm2.code_mazav_mishpachti = 999 
                        or mm2.code_mazav_mishpachti is null then null
                      else mm2.code_mazav_mishpachti end             "Marital Status",
                 case when mm2.date_mazav_mishpachti < to_date('01/01/1900','dd/mm/yyyy')
                        or mm2.date_mazav_mishpachti is null then null
                      else mm2.date_mazav_mishpachti end             "Marital Status Date",
                 null                                                "Hilan Code",
                 'poresh'                                            sug,
                 pk_hilan_prd.lpad_zeroez(p3.mispar_zehut,9)         "ID PORESH"
from
v_porshim2 sel1
left join poresh p3                  on p3.mispar_zehut = sel1.mispar_zehut_amiti
--left join tz_crm tz                  on tz.mispar_zehut = sel1.mispar_zehut_amiti
left join (select seq_poresh, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
from (
     select seq_poresh, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
          , row_number() over (partition by seq_poresh
                               order by nvl(date_mazav_mishpachti,to_date('01/01/1900','dd/mm/yyyy')) desc, seq_mazav_mishpachti desc) as rn
     from mazav_mishpachti mm1
     left join v_bakasha_last_status vmm1 on vmm1.seq_bakasha = mm1.seq_bakasha
     where vmm1.seq_bakasha is null
     or    vmm1.code_action in (98,129,130))
where rn = 1) mm2                    on mm2.seq_poresh = sel1.porshim_seq
left join code_matsav_mishpachti cmm on cmm.code_mazav_mishpachti = mm2.code_mazav_mishpachti
left join (select seq_poresh, code_address, seq_address, street, house, apartment, code_city, mikud
from (
     select seq_poresh, code_address, seq_address, street, house, apartment, code_city, mikud, va.seq_bakasha
          , row_number() over (partition by seq_poresh
                               order by code_address desc, seq_address desc) as rn
     from address a
     left join v_bakasha_last_status va on va.seq_bakasha = a.seq_bakasha
     where va.code_action in (98,129,130) or va.seq_bakasha is null)
where rn = 1) a1                     on a1.seq_poresh = sel1.porshim_seq
--left join code_ir ci                 on ci.code_ir = a1.code_city
/*where not exists
(select b1.seq_bakasha
    from bakasha b1
    left join v_bakasha_last_status bv1 on
    bv1.seq_bakasha = b1.seq_bakasha
    where b1.seq_prisha = sel1.seq_prisha
    and b1.code_sug_bakasha = 19
    and b1.code_bakasha_detail not in (12,181)
    and b1.seq_bney_mishpacha is null
    and b1.from_date > to_date('01/10/2021','dd/mm/yyyy')
    and bv1.code_action <> 17
    and not exists
    (select b2.seq_bakasha
    from bakasha b2
    left join v_bakasha_last_status bv2 on
    bv2.seq_bakasha = b2.seq_bakasha
    where b2.seq_prisha = sel1.seq_prisha
    and b2.code_sug_bakasha = 20
    and b2.seq_bney_mishpacha is null
    and b2.from_date >= b1.from_date
    and bv2.code_action <> 17)
)*/
--and tz.mispar_zehut is not null

union

select distinct  encrypt_tz(bm2.mispar_zehut_ben_mishpacha)          "Person Account External ID",
                 pk_hilan_prd.lpad_zeroez(bm2.mispar_zehut_ben_mishpacha,9)  "ID Number",
                 bm2.shem_prati                                      "First Name",
                 bm2.shem_mishpacha                                  "Last Name",
                 bm2.code_min                                        "Gender",
                 case when bm2.taarich_leda <= to_date('01/01/1900','dd/mm/yyyy')
                        or bm2.taarich_leda is null then null
                      else bm2.taarich_leda end                      "Date of birth",
                 bm2.taarich_ptira                                   "Date of death",
                 a1.street                                           "Street",
                 a1.house                                            "Street Number",
                 a1.apartment                                        "Apartment Number",
                 case when exists
                 (select t.code_ir
                 from code_ir t
                 where a1.code_city is null or t.code_ir = a1.code_city and a1.code_city <> 0)
                      then a1.code_city
                      else null end                                  "City",
                 a1.mikud                                            "Postal Code",
                 case when pk_hilan_prd.get_telephone(bm2.telephone) = '0000000000'
                   then null
                   else pk_hilan_prd.get_telephone(bm2.telephone) end  "Phone",
                 null                                                "Other Phone",
                 case when pk_hilan_prd.get_telephone(bm2.pelephone) = '0000000000'
                   then null
                   else pk_hilan_prd.get_telephone(bm2.pelephone) end "Mobile",
                bm2.email                                            "Email",
                case when mm2.code_mazav_mishpachti = 999 
                        or mm2.code_mazav_mishpachti is null then null
                      else mm2.code_mazav_mishpachti end             "Marital Status",
                 case when mm2.date_mazav_mishpachti <= to_date('01/01/1900','dd/mm/yyyy')
                        or mm2.date_mazav_mishpachti is null then null
                      else mm2.date_mazav_mishpachti end             "Marital Status Date",
                 null                                                "Hilan Code",
                 'sheer'                                             SUG,
                 pk_hilan_prd.lpad_zeroez(sel1.mispar_zehut,9)          "ID PORESH"                                           
from
(select distinct      bm3.mispar_zehut_ben_mishpacha mispar_zehut_ben_mishpacha,
                      porshim.mispar_gimla,
                      p.mispar_zehut,
                      bm3.seq_bney_mishpacha seq_bney_mishpacha,
                      pr.seq_prisha,
                      p.taarich_ptira
from v_porshim2 porshim
left join poresh p                   on p.mispar_zehut = porshim.mispar_zehut_amiti
--left join tz_crm tz                  on tz.mispar_zehut = porshim.mispar_zehut
left join bney_mishpacha bm3         on bm3.seq_porshim = p.porshim_seq
left join prisha pr                  on pr.seq_poresh = bm3.seq_porshim
                                     and instr(to_char(porshim.mispar_gimla),to_char(pr.gimla_number)) > 0
where /*(bm3.code_kirva is not null and p.taarich_ptira is null
      or bm3.code_relative is not null and p.taarich_ptira is not null)*/
bm3.code_kirva is not null
and nvl(bm3.shem_prati,' ') <> substr(nvl(bm3.shem_prati,' '),1,1)
and bm3.mispar_zehut_ben_mishpacha not in(1,18,26,34,59,67)
and bm3.sug_zihuy <> 5
and bm3.mispar_zehut_ben_mishpacha <> 111111111
and nvl(bm3.code_kirva,0) not in (0,24,25)
and bm3.shem_mishpacha is not null
--and (bm3.to_date_sium_zakaut is null or bm3.to_date_sium_zakaut > sysdate)
and bm3.mispar_zehut_ben_mishpacha not in
(1911817,
1540699,
3534815,
4119863,
4882288,
43292804,
42554949,
47639422,
46708319,
45923224,
65320293,
67433458
)
and pr.seq_ezor_ovdim = 10154
/*not in (
155,
159,
163,
164,
225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
10154,
10149
)*/
--and tz.mispar_zehut is not null
)
 sel1

left join bney_mishpacha bm2         on bm2.seq_bney_mishpacha = sel1.seq_bney_mishpacha

left join (select seq_bney_mishpacha, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
from (
     select seq_bney_mishpacha, date_mazav_mishpachti, seq_mazav_mishpachti, code_mazav_mishpachti
          , row_number() over (partition by seq_bney_mishpacha
                               order by nvl(date_mazav_mishpachti,to_date('01/01/1900','dd/mm/yyyy')) desc, seq_mazav_mishpachti desc) as rn
     from mazav_mishpachti mm1
     left join v_bakasha_last_status vmm1 on vmm1.seq_bakasha = mm1.seq_bakasha
     where (vmm1.seq_bakasha is null
     or    vmm1.code_action in (98,129,130))
     and   mm1.seq_bney_mishpacha is null)
where rn = 1) mm2                    on mm2.seq_bney_mishpacha = bm2.seq_bney_mishpacha

left join (select seq_bney_mishpacha, code_address, seq_address, street, house, apartment, code_city, mikud
from (
     select seq_bney_mishpacha, code_address, seq_address, street, house, apartment, code_city, mikud, va.seq_bakasha
          , row_number() over (partition by seq_bney_mishpacha
                               order by code_address desc, seq_address desc) as rn
     from address a
     left join v_bakasha_last_status va on va.seq_bakasha = a.seq_bakasha
     where va.code_action in (98,129,130) or va.seq_bakasha is null)
where rn = 1) a1                     on a1.seq_bney_mishpacha = bm2.seq_bney_mishpacha

left join v_porshim3 vp3 on
vp3.mispar_zehut_amiti = bm2.mispar_zehut_ben_mishpacha

where vp3.mispar_zehut_amiti is not null

--bm2.mispar_zehut_ben_mishpacha not in (select  vp2.mispar_zehut_amiti from v_porshim2 vp2)
/*and not exists
(select b1.seq_bakasha
    from bakasha b1
    left join v_bakasha_last_status bv1 on
    bv1.seq_bakasha = b1.seq_bakasha
    where b1.seq_prisha = sel1.seq_prisha
    and b1.code_sug_bakasha = 19
    and b1.code_bakasha_detail not in (12,181)
    and b1.seq_bney_mishpacha is null
    and b1.from_date > to_date('01/10/2021','dd/mm/yyyy')
    and bv1.code_action <> 17
    and not exists
    (select b2.seq_bakasha
    from bakasha b2
    left join v_bakasha_last_status bv2 on
    bv2.seq_bakasha = b2.seq_bakasha
    where b2.seq_prisha = sel1.seq_prisha
    and b2.code_sug_bakasha = 20
    and b2.seq_bney_mishpacha is null
    and b2.from_date >= b1.from_date
    and bv2.code_action <> 17)
)*/
    order by 20;

/*where to_number("ID Number")
in(13292875,
