from action_log al
left join v_bakasha_last_status v on v.seq_bakasha = al.seq_bakasha
where v.code_source = 24
and v.code_action = 98
and al.code_action = 210
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')

order by 1)
