                                      and b1.seq_porshim = sheerim.porshim_seq
where sheerim.mispar_zehut_sheer is not null
and b1.mispar_zehut_ben_mishpacha not in
(1911817,
1540699,
3534815,
4119863,
4882288,
43292804,
42554949,
47639422,
46708319,
45923224,
65320293,
67433458,
050034396
)
and b1.code_kirva is not null
and nvl(b1.shem_prati,' ') <> substr(nvl(b1.shem_prati,' '),1,1)
and b1.mispar_zehut_ben_mishpacha not in(1,18,26,34,59,67)
and nvl(b1.sug_zihuy,0) <> 5
and b1.mispar_zehut_ben_mishpacha <> 111111111
and b1.shem_mishpacha is not null
and nvl(b1.code_kirva,0) not in (0,24,25)
and sheerim.seq_ezor_ovdim not in (
155,
158,
13,
154,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149
)
)
sel1
left join poresh p2                  on p2.porshim_seq = sel1.seq_porshim
order by 2;
end get_SF_Relation;
/

create or replace procedure prm_system_copy.get_SF_Relation_19(from_date In Varchar2, Relation Out sys_refcursor) is
begin

open Relation for
select distinct  --p2.mispar_zehut,
                 --sel1.mispar_zehut_sheer,
                 encrypt_tz(p2.mispar_zehut)                         "Person 1",
                 encrypt_tz(sel1.mispar_zehut_sheer)                 "Person 2",
                 decode(sel1.code_kirva,15,2,sel1.code_kirva)        "Relation Type",
                 encrypt_tz(sel1.seq_bney_mishpacha)                 "Relation External ID"
from
(select distinct sheerim.*, b1.*
from(
select distinct le.mispar_zehut mispar_zehut_sheer,
                v.mispar_zehut,
