create or replace procedure prm_system_copy.get_SF_Relation_First(Relation Out sys_refcursor) is

begin
open Relation for

select distinct  encrypt_tz(sel1.mispar_zehut)                        "Person 1",
                 encrypt_tz(bm2.mispar_zehut_ben_mishpacha)           "Person 2",
                 case when nvl(bm2.code_kirva,0) = 15 then 2 
                      else bm2.code_kirva end                         "Relation Type",
                 encrypt_tz(bm2.seq_bney_mishpacha)                   "Relation External ID"
from
(select distinct      bm3.mispar_zehut_ben_mishpacha mispar_zehut_ben_mishpacha,
                      porshim.mispar_gimla,
                      p.mispar_zehut,
                      bm3.seq_bney_mishpacha seq_bney_mishpacha,
                      pr.seq_prisha,
                      p.taarich_ptira
from v_porshim2 porshim
left join poresh p                   on p.mispar_zehut = porshim.mispar_zehut_amiti
--left join tz_crm tz                  on tz.mispar_zehut = porshim.mispar_zehut
left join bney_mishpacha bm3         on bm3.seq_porshim = p.porshim_seq
left join prisha pr                  on pr.seq_poresh = bm3.seq_porshim
                                     and instr(to_char(porshim.mispar_gimla),to_char(pr.gimla_number)) > 0
where /*(bm3.code_kirva is not null and p.taarich_ptira is null
      or bm3.code_relative is not null and p.taarich_ptira is not null)*/
bm3.code_kirva is not null
and nvl(bm3.shem_prati,' ') <> substr(nvl(bm3.shem_prati,' '),1,1)
and bm3.mispar_zehut_ben_mishpacha not in(1,18,26,34,59,67)
and bm3.sug_zihuy <> 5
and bm3.mispar_zehut_ben_mishpacha <> 111111111
and nvl(bm3.code_kirva,0) not in (0,24,25)
and bm3.shem_mishpacha is not null
--and (bm3.to_date_sium_zakaut is null or bm3.to_date_sium_zakaut > sysdate)
and bm3.mispar_zehut_ben_mishpacha not in
(1911817,
1540699,
3534815,
4119863,
4882288,
43292804,
42554949,
47639422,
46708319,
45923224,
65320293,
67433458
)
and pr.seq_ezor_ovdim
not in (
155,
159,
163,
164,
225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
10154,
10149
)
--and tz.mispar_zehut is not null
)
 sel1

--left join bney_mishpacha bm2         on bm2.mispar_zehut_ben_mishpacha = sel1.mispar_zehut_ben_mishpacha
left join bney_mishpacha bm2         on bm2.seq_bney_mishpacha = sel1.seq_bney_mishpacha
where not exists
(select b1.seq_bakasha
    from bakasha b1
    left join v_bakasha_last_status bv1 on
    bv1.seq_bakasha = b1.seq_bakasha
    where b1.seq_prisha = sel1.seq_prisha
    and b1.code_sug_bakasha = 19
    and b1.code_bakasha_detail not in (12,181)
    and b1.seq_bney_mishpacha is null
    and b1.from_date > to_date('01/10/2021','dd/mm/yyyy')
    and bv1.code_action <> 17
    and not exists
    (select b2.seq_bakasha
    from bakasha b2
    left join v_bakasha_last_status bv2 on
    bv2.seq_bakasha = b2.seq_bakasha
    where b2.seq_prisha = sel1.seq_prisha
    and b2.code_sug_bakasha = 20
    and b2.seq_bney_mishpacha is null
    and b2.from_date >= b1.from_date
    and bv2.code_action <> 17)
)
    order by 2;

end get_SF_Relation_First;
/

create or replace procedure prm_system_copy.get_sf_requests(from_date In Varchar2, requests In Clob) is

l_count                                               number;
v_request_name                                        varchar2(50);
v_person_id                                           varchar2(50);
v_subject_code                                        varchar2(50);
v_gimla_number                                        varchar2(50);
v_is_gimla_number_requered                            number;
v_is_document_required                                number;
v_code_sug_bakasha                                    number;
v_created_date                                        varchar2(19);
v_bank_number                                         number;
v_bank_branch                                         number;

v_error_code                                           number;
v_error_text                                           varchar2(2000);
v_check_result1                                        number;
v_check_result2                                        number;
v_errors                                               clob;
v_success_number                                       number;
v_error_number                                        number;
v_title                                               varchar2(2000);
v_report                                              varchar2(2000);

function add_error_text(p_error_text varchar2) return varchar2 is

  f_v_error_text varchar2(2000);
begin
  if v_error_text is null then
    f_v_error_text := v_request_name || ': ' || p_error_text || '(' || to_char(v_error_code) || ')' || ' * ';
  else
    f_v_error_text := v_error_text   || chr(10) || p_error_text || '(' || to_char(v_error_code) || ')' || '*';
  end if;
  return f_v_error_text;
end;

procedure send_mail is
  begin
    --dbms_output.put_line(v_errors);

v_title := 'total success requests: ' || to_char(v_success_number) || chr(10) ||
           'total errors requests: ' || to_char(v_error_number) || chr(10);
  
v_report := '<html><body>' || '<h1>' ||
                'requests interface finished' || '</h1>' ||
                '<h1>' || 'total success rows: ' || to_char(v_success_number) || '<h1/>' ||
                '<h1>' || 'total errors rows: '  || to_char(v_error_number)   || '<h1/>' ||
                '<h4><html/><body/>' || v_errors || '<html/><body/><h4/>';

    --select sys_context('userenv', 'DB_NAME') into v_userenv from dual;
    pk_prm_utils.send_attach(
    /*case when v_userenv='xt1' then*/ 'liba@mof.gov.il'
                              /*else 'liba@mof.gov.il' end*/,
                               'The requests interface finished',
                               v_title,
                               v_report,
                               'html',
                               'requests_interface.htm');
end; 
begin
 v_success_number := 0;
 v_error_number := 0;
 
 apex_json.parse(requests);
 l_count := apex_json.get_count (p_path => 'records');
for i IN 1 .. l_count
loop
insert into LD_Requests_CRM t
      (t.request_name,
       t.Request_URL,
       t.created_date,
       t.person_id,
       t.request_source,
       t.subject_code,
       t.description,
       t.benefit_number,
       t.bank_number,
       t.bank_branch,
       t.account_number,
       t.street,
       t.street_number,
       t.apartment_number,
       t.city_code,
       t.postal_code,
       t.file_url,
       t.sfid,
       t.ld_date
)
VALUES(
apex_json.get_varchar2(p_path => 'records[%d].Name', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].attributes.url', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].CreatedDate', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Pensioner__r.GIM_PersonIdNumber__pc', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Source__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Subject__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Description__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].BenefitNumber__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].BankBranch__r.BranchNumber__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].BankAccountNumber__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Street__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].ApartmentNumber__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].City__r.CityCode__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].PostalCode__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => i),
sysdate
);
commit;

v_error_code := 0;
v_error_text := '';
v_request_name := apex_json.get_varchar2(p_path => 'records[%d].Name', p0 => i);

--PersonIdNumber
v_person_id := apex_json.get_varchar2(p_path => 'records[%d].Pensioner__r.GIM_PersonIdNumber__pc', p0 => i);
select validate_conversion(v_person_id as number) into v_check_result1 from dual;
select (case when not exists (
  select p.mispar_zehut
  from poresh p
  where p.mispar_zehut = to_number(v_person_id))
  and not exists (
  select b.mispar_zehut_ben_mishpacha
  from bney_mishpacha b
  where b.mispar_zehut_ben_mishpacha = to_number(v_person_id))
  then 0 else 1 end)
    into v_check_result2 from dual;
if v_person_id is null then
  v_error_code := 10;
  v_error_text := add_error_text('מספר תעודת זהות שדה חובה')
  ;
end if;
if v_check_result1 = 0 then
  v_error_code := 20;
  v_error_text := add_error_text('מספר תעודת זהות אינו נומרי')
  ;
end if;
if v_check_result2 = 0 then
  v_error_code := 30;
  v_error_text := add_error_text('גמלאי לא קיים במפ"מ')
  ;
end if;

--SubjectCode
if v_error_text is null then
v_subject_code := apex_json.get_varchar2(p_path => 'records[%d].Subject__c', p0 => i);
select validate_conversion(v_subject_code as number) into v_check_result1 from dual;
select (case when not exists (
  select p.code_subject_crm
  from perm_subject_crm_sug_bakasha p
  where p.code_subject_crm = to_number(nvl(v_subject_code,0)))
  then 0 else 1 end)
  into v_check_result2 from dual;
if v_subject_code is null then
  v_error_code := 110;
  v_error_text := add_error_text('קוד נושא שדה חובה')
  ;
end if;  
if v_check_result1 = 0 then
  v_error_code := 120;
  v_error_text := add_error_text('קוד נושא אינו נומרי')
  ;
end if;  
if v_check_result2 = 0 then
  v_error_code := 130;
  v_error_text := add_error_text('קוד נושא לא מוגדר')
  ;
end if;
end if;

--BenefitNumber
if v_error_text is null then
v_gimla_number := apex_json.get_varchar2(p_path => 'records[%d].BenefitNumber__c', p0 => i);

select p.code_sug_bakasha, p.is_document_required, p.IS_GIMLA_NUMBER_REQUIRED
  into v_code_sug_bakasha,
       v_is_document_required,
       v_is_gimla_number_requered
from perm_subject_crm_sug_bakasha p
where p.code_subject_crm = to_number(v_subject_code);

select validate_conversion(v_gimla_number as number) into v_check_result1 from dual;
select (case when not exists (
  select pr.seq_prisha
  from prisha pr
  left join poresh p on p.porshim_seq = pr.seq_poresh 
  left join bney_mishpacha b on b.seq_porshim = pr.seq_poresh
  where pr.gimla_number = to_number(v_gimla_number)
  and (p.mispar_zehut = to_number(v_person_id) or
       b.mispar_zehut_ben_mishpacha = to_number(v_person_id)))
  then 0 else 1 end)
  into v_check_result2 from dual;

if v_is_gimla_number_requered = 1 then
if v_gimla_number is null then
  v_error_code := 110;
  v_error_text := add_error_text('מספר גמלה שדה חובה עבןר נושא הפניה')
  ;
end if;  
if v_check_result1 = 0 then
  v_error_code := 120;
  v_error_text := add_error_text('מספר גמלה אינו נומרי')
  ;
end if;  
if v_check_result2 = 0 then
  v_error_code := 130;
  v_error_text := add_error_text('פרישה אינה קיימת')
  ;
end if;
else
v_gimla_number := null;
end if;
end if;

if v_error_text is not null then
  v_errors := v_errors || '<br />' || v_error_text;
  dbms_output.put_line(v_error_text);
  v_error_number := v_error_number + 1;
  insert into Ld_Requests_Crm_Errors t
      (t.request_name,
       t.Request_URL,
       t.created_date,
       t.person_id,
       t.request_source,
       t.subject_code,
       t.description,
       t.benefit_number,
       t.bank_number,
       t.bank_branch,
       t.account_number,
       t.street,
       t.street_number,
       t.apartment_number,
       t.city_code,
       t.postal_code,
       t.file_url,
       t.sfid,
       t.ld_date,
       t.error_text
)
VALUES(
apex_json.get_varchar2(p_path => 'records[%d].Name', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].attributes.url', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].CreatedDate', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Pensioner__r.GIM_PersonIdNumber__pc', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Source__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Subject__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Description__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].BenefitNumber__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].BankBranch__r.BranchNumber__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].BankAccountNumber__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Street__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].ApartmentNumber__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].City__r.CityCode__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].PostalCode__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => i),
sysdate,
v_error_text
);
else
  v_success_number := v_success_number + 1;
  v_bank_number := case when apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => i) is null
                        then null
                        else to_number(apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => i)) end;
  v_bank_branch := case when apex_json.get_varchar2(p_path => 'records[%d].BankBranch__r.BranchNumber__c', p0 => i) is null
                        then null
                        else to_number(apex_json.get_varchar2(p_path => 'records[%d].BankBranch__r.BranchNumber__c', p0 => i)) end;
                         
  v_created_date := replace(substr(apex_json.get_varchar2(p_path => 'records[%d].CreatedDate', p0 => i),1,19),'T',' ');
    insert into Requests_Crm t
      (t.request_name,
       t.Request_URL,
       t.created_date,
       t.person_id,
       t.request_source,
       t.subject_code,
       t.description,
       t.benefit_number,
       t.bank_number,
       t.bank_branch,
       t.account_number,
       t.street,
       t.street_number,
       t.apartment_number,
       t.city_code,
       t.postal_code,
       t.file_url,
       t.sfid,
       t.ld_date,
       t.seq_bakasha
)
VALUES(
apex_json.get_varchar2(p_path => 'records[%d].Name', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].attributes.url', p0 => i),
to_date(v_created_date,'yyyy-mm-dd HH24:MI:SS'),
to_number(apex_json.get_varchar2(p_path => 'records[%d].Pensioner__r.GIM_PersonIdNumber__pc', p0 => i)),
to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].Source__c', p0 => i),'0')),
to_number(apex_json.get_varchar2(p_path => 'records[%d].Subject__c', p0 => i)),
apex_json.get_varchar2(p_path => 'records[%d].Description__c', p0 => i),
to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].BenefitNumber__c', p0 => i),'0')),
v_bank_number,
v_bank_branch,
to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].BankAccountNumber__c', p0 => i),'0')),
apex_json.get_varchar2(p_path => 'records[%d].Street__c', p0 => i),
to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i),'0')),
to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].ApartmentNumber__c', p0 => i),'0')),
to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].City__r.CityCode__c', p0 => i),'0')),
apex_json.get_varchar2(p_path => 'records[%d].PostalCode__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => i),
sysdate,
bakasha_seq.nextval
);

end if;


end loop;

if v_error_number > 0 then send_mail; end if;


/*exception
  when others*/
  
end get_sf_requests;
/

create or replace procedure prm_system_copy.get_SF_Retirement (from_date In Varchar2, Retirement Out sys_refcursor) is
begin

open Retirement for
select distinct  --'poresh' sug,
                 --sel1.mispar_zehut_amiti,
                 encrypt_tz(sel1.mispar_zehut_amiti)                 "Person Account",
                 sel1.seq_ezor_ovdim                                 "Account",
                 sel1.mispar_gimla                                   "Benefit number",
                 f_get_taarich_prisha(sel1.seq_prisha)               "Retirement date",
                 encrypt_tz(sel1.seq_prisha)                         "Retirement External ID",
                 case when sel1.shem_prati = 'הסבה'
                   then 'לא מזוהה'
                   else sel1.shem_prati end || ' ' ||
                 case when sel1.shem_mishpacha = 'הסבה'
                   then 'לא מזוהה'
                   else sel1.shem_mishpacha end                      "Person Name"
from
(select distinct porshim.*, p.shem_prati, p.shem_mishpacha,
            case when p.mispar_zehut is null then z.mispar_zheut else p.mispar_zehut end mispar_zehut_amiti
from
((select distinct v.mispar_zehut,
                  v.gimla_number mispar_gimla,
                  v.seq_ezor_ovdim,
                  v.seq_prisha
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha = le.seq_bakasha
                                  and v.mispar_zehut = le.mispar_zehut
where v.code_action not in (17,100)
and v.code_sug_bakasha not in (14,7,23)
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
)
)
union
(select distinct v.mispar_zehut,
                  v.gimla_number mispar_gimla,
                  v.seq_ezor_ovdim,
                  v.seq_prisha
from action_log a
left join v_bakasha_last_status v on  v.seq_bakasha = a.seq_bakasha
left join netuney_tik_mechushavim n on n.seq_bakasha = v.seq_bakasha
                                   and n.code_department = 2
where v.code_sug_bakasha = 1
and v.code_action not in (17,100)
and nvl(n.code_department,0) <> 4
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 19
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
and n.date_start_zakaut is not null)
)
union
(select distinct v.mispar_zehut,
                 v.gimla_number mispar_gimla,
                 v.seq_ezor_ovdim,
                 v.seq_prisha
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha = le.seq_bakasha
                                  and v.mispar_zehut <> le.mispar_zehut
/*left join netuney_tik_mechushavim n on
n.seq_bakasha = v.seq_bakasha
and n.code_department = 2*/
where v.code_action not in (17,100)
--and v.code_sug_bakasha in (1,13,9)
--and n.code_group_prisha = 4
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
)
)
union
select distinct v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha
from v_bakasha_last_status v
left join sf_gimlaim_nosafim gn        on gn.mispar_zehut = v.mispar_zehut
where gn.taarich_hosafa >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')

order by 1)
porshim
left join poresh p                   on p.mispar_zehut = porshim.mispar_zehut
left join zheut_fictivi_from_hilan z on z.mispar_zheut_fictivi = porshim.mispar_zehut
left join poresh p1                  on p1.mispar_zehut = z.mispar_zheut
where (p.mispar_zehut is not null or p1.mispar_zehut is not null)
and porshim.seq_ezor_ovdim not in (
155,
158,
13,
154,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149
)
) sel1

/*union

select distinct  --'sheer' sug,
                 --sel1.mispar_zehut_sheer,
                 encrypt_tz(sel1.mispar_zehut_sheer)                 "Person Account",
                 sel1.seq_ezor_ovdim                                 "Account",
                 sel1.mispar_gimla                                   "Benefit number",
                 f_get_taarich_prisha(sel1.seq_prisha)               "Retirement date",
                 encrypt_tz(sel1.seq_prisha)                         "Retirement External ID"
from
(select distinct sheerim.*, b1.*
from(
select distinct le.mispar_zehut mispar_zehut_sheer,
                v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha
from ld_log_events le
left join v_bakasha_last_status v on v.seq_bakasha = le.seq_bakasha
                                 and v.mispar_zehut <> le.mispar_zehut
where v.code_action not in (17,100)
and v.code_sug_bakasha not in (14,7,23)
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
)
union
select distinct b.mispar_zehut_ben_mishpacha mispar_zehut_sheer,
                v.mispar_zehut,
                v.gimla_number mispar_gimla,
                v.seq_ezor_ovdim,
                v.seq_prisha
from ld_log_events le
left join v_bakasha_last_status v on  v.seq_bakasha  = le.seq_bakasha
                                  and v.mispar_zehut = le.mispar_zehut
left join poresh p                on  p.mispar_zehut = v.mispar_zehut
left join bney_mishpacha b        on  b.seq_porshim  = p.porshim_seq
where v.code_action not in (17,100)
and (v.code_sug_bakasha in (1,8) or v.code_sug_bakasha = 5 and v.code_bakasha_detail = 25)
and exists
(select al.seq_bakasha
from action_log al
where al.seq_bakasha = v.seq_bakasha
and al.code_action = 136
and al.date_action >= to_date(from_date,'YYYY-MM-DD HH24:MI:SS')
and b.mispar_zehut_ben_mishpacha is not null)
order by 1)
sheerim
left join bney_mishpacha b1           on b1.mispar_zehut_ben_mishpacha  = sheerim.mispar_zehut_sheer
where sheerim.mispar_zehut_sheer is not null
and b1.mispar_zehut_ben_mishpacha not in
(1911817,
1540699,
3534815,
4119863,
4882288,
43292804,
42554949,
47639422,
46708319,
45923224,
65320293,
67433458
)
and b1.code_kirva is not null
and nvl(b1.shem_prati,' ') <> substr(nvl(b1.shem_prati,' '),1,1)
and b1.mispar_zehut_ben_mishpacha not in(1,18,26,34,59,67)
and nvl(b1.sug_zihuy,0) <> 5
and b1.mispar_zehut_ben_mishpacha <> 111111111
and b1.shem_mishpacha is not null
and nvl(b1.code_kirva,0) not in (0,24,25)
and b1.shem_mishpacha is not null
and sheerim.seq_ezor_ovdim not in (
155,
159,
163,
164,
225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
10154
)
) sel1*/

order by 1;
end get_SF_Retirement;
/

