              from v_bakasha_last_status t
             where t.code_action = 148
               and t.code_user_to_internal = 126
               --and pk_expiried.is_ezor_ovdim_hilan(t.seq_ezor_ovdim) = 1
               ) loop
    pk_prm_utils.insert_actions_for_bakasha(r.seq_bakasha, 126);
  end loop;
end sing_document;
/

create or replace procedure prm_system_copy.temp_copy_thashlum_guf is
begin
  for r in (select t.seq_guf, t.sum - nvl(t.kizuz, 0) as sum
              from tashlum_guf t
             where t.for_month = to_date('01/09/2019', 'dd/mm/yyyy')
               and t.code_sug_workflow = 8) loop
    update tashlum_guf t
       set t.kizuz = nvl(t.kizuz, 0) + r.sum * -1
     where t.for_month = to_date('01/10/2019', 'dd/mm/yyyy')
       and t.seq_guf = r.seq_guf;
  end loop;

end;
/

create or replace procedure prm_system_copy.test_date_micun is
  date_micun date;
  v_report clob := '<html><body>no hilan interface<body/><html/>';
begin
  dbms_output.enable(99999);
  select t.date_close
  into date_micun
  from date_close_report t
  where to_char(sysdate,'MMYYYY') = to_char(t.date_close,'MMYYYY');
  if trunc(date_micun) <= trunc(sysdate) then
  dbms_output.put_line('no hilan interface');
  else
  dbms_output.put_line('yes hilan interface');
  end if;
    exception
    when others then
       dbms_output.put_line('no hilan interface') ;
       pk_prm_utils.send_attach(
            'liba@mof.gov.il',
            'no hilan interface, test date micun falled:' || sqlerrm,
                               'no hilan interface',
                               v_report,
                               'html',
                               'hilan_interface.htm');
end;
/

create or replace procedure prm_system_copy.test_date_micun_mule (is_micun out number, p_sysdate IN  DATE DEFAULT SYSDATE) is

  -- Local variables here
  v_date_close_test1   DATE;
  v_date_close_test2   DATE;
  v_date_close_chodesh DATE;
  v_date_open_chodesh  DATE;

  v_report clob := '<html><body>no hilan interface<body/><html/>';
begin
  -- Test statements here
  dbms_output.enable(999999);
  select t.date_close_test1,
         t.date_close_test2,
         t.date_close_chodesh,
         t.date_open_chodesh
  into v_date_close_test1,
       v_date_close_test2,
       v_date_close_chodesh,
       v_date_open_chodesh
  from date_close_report t
  where to_char(p_sysdate,'MMYYYY') = to_char(t.date_open_chodesh,'MMYYYY');


  if p_sysdate < v_date_open_chodesh then
    dbms_output.put_line('no hilan interface');
    is_micun := 0;
  elsif trunc(v_date_close_test1) = trunc(p_sysdate) then
    if p_sysdate > v_date_close_test1 then
        dbms_output.put_line('no hilan interface');
        is_micun := 0;
    else
        dbms_output.put_line('yes hilan interface');
        is_micun := 1;
    end if;
  elsif trunc(v_date_close_test2) = trunc(p_sysdate) then
    if p_sysdate > v_date_close_test2 or
       to_char(p_sysdate,'HH24:MI:SS') < '12:20:00'
      then
        dbms_output.put_line('no hilan interface');
        is_micun := 0;
    else
        dbms_output.put_line('yes hilan interface');
        is_micun := 1;
    end if;
   elsif trunc(p_sysdate) > trunc(v_date_close_test1) and
        trunc(p_sysdate) < trunc(v_date_close_test2) then
    if to_char(p_sysdate,'HH24:MI:SS') < '12:20:00' 
       or to_char(p_sysdate,'HH24:MI:SS') > '16:40:00' then
        dbms_output.put_line('no hilan interface');
        is_micun := 0;
    else
        dbms_output.put_line('yes hilan interface');
        is_micun := 1;
    end if;
   elsif trunc(p_sysdate) > trunc(v_date_close_test2) and
        trunc(p_sysdate) < trunc(v_date_close_chodesh) then
    if to_char(p_sysdate,'HH24:MI:SS') < '12:20:00' 
       or to_char(p_sysdate,'HH24:MI:SS') > '16:40:00' then
        dbms_output.put_line('no hilan interface');
        is_micun := 0;
    else
        dbms_output.put_line('yes hilan interface');
        is_micun := 1;
    end if;
  elsif trunc(v_date_close_chodesh) <= trunc(p_sysdate) then
    if p_sysdate > v_date_close_chodesh or
       to_char(p_sysdate,'HH24:MI:SS') < '12:20:00'
      then
        dbms_output.put_line('no hilan interface');
        is_micun := 0;
    else
        dbms_output.put_line('yes hilan interface');
        is_micun := 1;
    end if;
  else
        dbms_output.put_line('yes hilan interface');
        is_micun := 1;
end if;
/*  dbms_output.put_line(to_char(v_date_close_test1,'yyyy-mm-dd HH24:MI:SS') || ' ' ||
                       to_char(v_date_close_test2,'yyyy-mm-dd HH24:MI:SS') || ' ' ||
                       to_char(v_date_close_chodesh,'yyyy-mm-dd HH24:MI:SS') || ' ' ||
                       to_char(v_date_open_chodesh,'yyyy-mm-dd HH24:MI:SS'));*/


    EXCEPTION
    WHEN OTHERS THEN
       IS_MICUN := 0;
       DBMS_OUTPUT.PUT_LINE('no hilan interface') ;
       DBMS_OUTPUT.PUT_LINE(SQLERRM) ;
       PK_PRM_UTILS.SEND_ATTACH(
            'liba@mof.gov.il',
            'no hilan interface, test date micun mule falled:' || SQLERRM,
                               'no hilan interface',
                               V_REPORT,
                               'html',
                               'hilan_interface.htm'); 
end;
/

create or replace procedure prm_system_copy.test_date_micun_AI is
  v_is_micun NUMBER;

  -- פרוצדורה פנימית להרצת טסט בודד
  PROCEDURE run_test(p_desc VARCHAR2, p_test_date DATE, p_expected NUMBER) IS
    v_actual NUMBER;
  BEGIN
    test_date_micun_mule(v_actual, p_test_date);

    DBMS_OUTPUT.PUT('Test: ' || RPAD(p_desc, 30) || ' ' || to_char(p_test_date,'DD/MM/YYYY HH24:MI:SS'));
    IF v_actual = p_expected THEN
      DBMS_OUTPUT.PUT_LINE(' [PASS]');
    ELSE
      DBMS_OUTPUT.PUT_LINE(' [FAIL] - Expected ' || p_expected || ' but got ' || v_actual);
    END IF;
     DBMS_OUTPUT.PUT_LINE(to_char(p_expected));
     DBMS_OUTPUT.PUT_LINE(' ');
  END;

BEGIN
  -- 1. עדכון טבלת הבקרה לערכי בדיקה (נניח יוני 2026)
  UPDATE date_close_report
  SET date_open_chodesh  = TO_DATE('01/06/2026 12:00:00', 'DD/MM/YYYY HH24:MI:SS'),
      date_close_test1   = TO_DATE('21/06/2026 16:40:00', 'DD/MM/YYYY HH24:MI:SS'),
      date_close_test2   = TO_DATE('24/06/2026 16:40:00', 'DD/MM/YYYY HH24:MI:SS'),
      date_close_chodesh = TO_DATE('28/06/2026 12:40:00', 'DD/MM/YYYY HH24:MI:SS')
  WHERE TO_CHAR(date_open_chodesh, 'MMYYYY') = '062026';
  COMMIT;

  DBMS_OUTPUT.PUT_LINE('--- Starting Tests ---');

  --OPEN_CHODESH
  run_test('Before Month Open', TO_DATE('01/06/2026 09:00', 'DD/MM/YYYY HH24:MI:SS'), 0);
  run_test('Before Month Open', TO_DATE('01/06/2026 13:00', 'DD/MM/YYYY HH24:MI:SS'), 1);

  --NORMAL_DAY
  run_test('Normal Day', TO_DATE('15/06/2026', 'DD/MM/YYYY HH24:MI:SS'), 1);

  --CLOSE_TEST_1
  run_test('Close Test 1', TO_DATE('21/06/2026 10:00:00', 'DD/MM/YYYY HH24:MI:SS'), 1);
  run_test('Close Test 1', TO_DATE('21/06/2026 18:00:00', 'DD/MM/YYYY HH24:MI:SS'), 0);


  --CLOSE_TEST_2
  run_test('Close Test 2', TO_DATE('24/06/2026 10:00:00', 'DD/MM/YYYY HH24:MI:SS'), 0);
  run_test('Close Test 2', TO_DATE('24/06/2026 12:30:00', 'DD/MM/YYYY HH24:MI:SS'), 1);
  run_test('Close Test 2', TO_DATE('24/06/2026 16:30:00', 'DD/MM/YYYY HH24:MI:SS'), 1);
  run_test('Close Test 2', TO_DATE('24/06/2026 18:00:00', 'DD/MM/YYYY HH24:MI:SS'), 0);

  --בין הטסטים
  run_test('Close Test 1-2', TO_DATE('25/06/2026 00:30:00', 'DD/MM/YYYY HH24:MI:SS'), 0);
  run_test('Close Test 1-2', TO_DATE('25/06/2026 10:00:00', 'DD/MM/YYYY HH24:MI:SS'), 0);
  run_test('Close Test 1-2', TO_DATE('25/06/2026 13:00:00', 'DD/MM/YYYY HH24:MI:SS'), 1);
  run_test('Close Test 1-2', TO_DATE('25/06/2026 15:30:00', 'DD/MM/YYYY HH24:MI:SS'), 1);
  run_test('Close Test 1-2', TO_DATE('26/06/2026 16:30:00', 'DD/MM/YYYY HH24:MI:SS'), 1);
  run_test('Close Test 1-2', TO_DATE('26/06/2026 00:30:00', 'DD/MM/YYYY HH24:MI:SS'), 0);


  --CLOSE_HODESH
  run_test('After Month Close', TO_DATE('28/06/2026 10:00', 'DD/MM/YYYY HH24:MI:SS'), 0);
  run_test('After Month Close', TO_DATE('28/06/2026 12:30', 'DD/MM/YYYY HH24:MI:SS'), 1);
  run_test('After Month Close', TO_DATE('28/06/2026 15:30', 'DD/MM/YYYY HH24:MI:SS'), 0);
  run_test('After Month Close', TO_DATE('30/06/2026 15:30', 'DD/MM/YYYY HH24:MI:SS'), 0);

  --בדיקות, מוצעות על ידי GEMINI אחרי הבדיקות שלי

  run_test('Close Test 1 Early Morning', TO_DATE('21/06/2026 07:00:00', 'DD/MM/YYYY HH24:MI:SS'), 1);

  -- בדיקות גבולות מדויקות (Boundary Tests) בין הטסטים
  run_test('Boundary: 1 minute before open', TO_DATE('22/06/2026 12:19:00', 'DD/MM/YYYY HH24:MI:SS'), 0);
  run_test('Boundary: Exact open time', TO_DATE('22/06/2026 12:20:00', 'DD/MM/YYYY HH24:MI:SS'), 1);
  run_test('Boundary: Exact close time', TO_DATE('22/06/2026 16:40:00', 'DD/MM/YYYY HH24:MI:SS'), 1);
  run_test('Boundary: 1 minute after close', TO_DATE('22/06/2026 16:41:00', 'DD/MM/YYYY HH24:MI:SS'), 0);

  -- בדיקת יום סגירה - שעה שעוברת את שעת הסגירה אך בטווח המותר לכאורה
  run_test('After Close Hour on Close Day', TO_DATE('28/06/2026 13:00:00', 'DD/MM/YYYY HH24:MI:SS'), 0);

  -- בדיקת חריגה (חודש שלא קיים בטבלה)
  --run_test('Exception: Month not in DB', TO_DATE('01/07/2026 10:00:00', 'DD/MM/YYYY HH24:MI:SS'), 0);

END;
/

