create or replace procedure prm_system_copy.update_achuz_kizba_gil_60 is
  v_achuz_kizba_gil_60_0   number;
  v_achuz_kizba_gil_60_1   number;
  v_achuz_kizba_gil_60_cur number;
begin
  for r in (select t.seq_bakasha,
                   t.mispar_misra,
                   t.achuz_kizba_gil_60,
                   t1.mispar_zehut
              from netuney_tik_mechushavim t
              left join v_bakasha_last_status t1
                on t.seq_bakasha = t1.seq_bakasha
             where t.code_department = 2
               and t.date_start_zakaut >=
                   to_date('01/01/2019', 'dd/mm/yyyy')
               and t.achuz_kizba_gil_60 is not null) loop
  
    pk_zakaut.internal_main(r.seq_bakasha, 2, null);
  
    select t.achuz_kizba_gil_60
      into v_achuz_kizba_gil_60_0
      from netuney_tik_mechushavim t
     where t.seq_bakasha = r.seq_bakasha
       and t.code_department = 2
       and t.mispar_misra = 0;
    if r.mispar_misra = 1 then
      select t.achuz_kizba_gil_60
        into v_achuz_kizba_gil_60_1
        from netuney_tik_mechushavim t
       where t.seq_bakasha = r.seq_bakasha
         and t.code_department = 2
         and t.mispar_misra = 1;
    end if;
  
    rollback;
  
    if nvl(r.achuz_kizba_gil_60, 0) <> v_achuz_kizba_gil_60_0 and
       r.mispar_misra = 0 or nvl(r.achuz_kizba_gil_60, 0) <>
       v_achuz_kizba_gil_60_1 and r.mispar_misra = 1 then
    
      dbms_output.put_line(r.mispar_zehut || ', ' || r.mispar_misra ||
                           ', prev:,' || r.achuz_kizba_gil_60 || ', new:,' ||
                           v_achuz_kizba_gil_60_0);
    
      update netuney_tik_mechushavim t
         set t.achuz_kizba_gil_60 = v_achuz_kizba_gil_60_0
       where t.seq_bakasha = r.seq_bakasha
         and t.code_department = 2
         and t.mispar_misra = 0;
    
      update netuney_tik_mechushavim t
         set t.achuz_kizba_gil_60 = v_achuz_kizba_gil_60_1
       where t.seq_bakasha = r.seq_bakasha
         and t.code_department = 2
         and t.mispar_misra = 1;
      commit;
    end if;
  end loop;

end;
/

create or replace procedure prm_system_copy.update_address_yatom_gil_20 is
begin
  for r in (select t.seq_bakasha, t.seq_porshim, b.seq_bney_mishpacha
              from v_bakasha_last_status t
              left join bakasha b
                on t.seq_bakasha = b.seq_bakasha
              left join address a
                on a.seq_bney_mishpacha = b.seq_bney_mishpacha
             where t.code_sug_bakasha = 25
               and t.code_bakasha_detail = 21
               and t.code_action not in (17, 98)
               and a.seq_bney_mishpacha is null) loop
  
    insert into address
      (select r.seq_bakasha,
              ad.code_address,
              ad.code_city,
              ad.mikud,
              sysdate,
              0,
              address_seq.nextval,
              r.seq_porshim,
              r.seq_bney_mishpacha,
              ad.street,
              ad.house,
              ad.apartment,
              ad.entrance,
              ad.house_letter,
              null,
              bn.shem_meadken_acharon,
              bn.taarich_yetzira
         from bney_mishpacha bn
         left join v_address_bney_mishpacha addr
           on bn.seq_bney_mishpacha = addr.seq_bney_mishpacha
         left join address ad
           on addr.seq_address = ad.seq_address
        where bn.seq_porshim = r.seq_porshim
          and ad.seq_address is not null
          and bn.seq_bney_mishpacha is not null);
  end loop;
end;
/

create or replace procedure prm_system_copy.update_bigud_havraa is
begin
  for r in (select distinct b.seq_bakasha,
                            t1.seq_netuney_tik_mechushavim,
                            tbh.bigud,
                            tbh.havraa,
                            tbh.sum,
                            case
                              when b.code_sug_bakasha = 8 then
                               p2.mispar_zehut
                              else
                               bm.mispar_zehut_ben_mishpacha
                            end as mispar_zehut
              from bakasha b
              left join bakasha_regila br
                on b.seq_bakasha = br.seq_bakasha
              left join netuney_tik_mechushavim t1
                on b.seq_bakasha = t1.seq_bakasha
               and t1.code_department = 2
              left join prisha p1
                on b.seq_prisha = p1.seq_prisha
              left join poresh p2
                on p1.seq_poresh = p2.porshim_seq
              left join v_bakasha_last_status v_b
                on v_b.SEQ_BAKASHA = b.seq_bakasha
               and v_b.SEQ_PRISHA = p1.seq_prisha
              left join (select *
                          from bney_mishpacha t
                         where t.code_kirva in (1, 2, 14)
                           and (t.taarich_ptira is null or
                               last_day(t.taarich_ptira) >
                               to_date('01/01/2020', 'dd/mm/yyyy'))) bm
                on bm.seq_porshim = p2.porshim_seq
            
              join temp_bigud_havraa tbh
                on (v_b.mispar_zehut = tbh.id and v_b.code_sug_bakasha = 8 or
                   bm.mispar_zehut_ben_mishpacha = tbh.id and
                   v_b.code_sug_bakasha = 9)
             where v_b.code_sug_bakasha in (8, 9)) loop
    update bakasha_regila t
       set t.bigud = round(r.bigud, 2), t.havrah = round(r.havraa, 2)
     where t.seq_bakasha = r.seq_bakasha;
  
    update netuney_tik_mechushavim t
       set t.schum_kizba = round(r.sum, 2)
     where t.seq_netuney_tik_mechushavim = r.seq_netuney_tik_mechushavim;
  
  end loop;
  commit;
end;
/

create or replace procedure prm_system_copy.update_birth_date_from_hilan is
  v_birth_date_hilan varchar(10);
begin
  for r in (select * from bney_mishpacha t where t.taarich_leda is null) loop
    begin
      select h.birth_date
        into v_birth_date_hilan
        from LD_HILAN_200 h
       where identity_number = r.mispar_zehut_ben_mishpacha;
    
      update bney_mishpacha b
         set b.taarich_leda = to_date(substr(v_birth_date_hilan, 5, 4) ||
                                      substr(v_birth_date_hilan, 3, 2) ||
                                      substr(v_birth_date_hilan, 1, 2),
                                      'yyyymmdd')
       where r.mispar_zehut_ben_mishpacha = b.mispar_zehut_ben_mishpacha;
    
      /* dbms_output.put_line(r.mispar_zehut_ben_mishpacha || '-' ||
      to_date(substr(v_birth_date_hilan, 5, 4) ||
              substr(v_birth_date_hilan, 3, 2) ||
              substr(v_birth_date_hilan, 1, 2),
              'yyyymmdd'));*/
    
    exception
      when others then
        continue;
    end;
    commit;
  end loop;

end;
/

create or replace procedure prm_system_copy.update_bney_mishpacha is

  v_is_ben_mishpacha_mpm number;
  v_toal_child           number;
  v_toal_ben_zug         number;
begin
  for r in (select identity_number, to_date, is_erased, code_expired
              from ld_mlm_215
             where CODE_EXPIRED = '02'
               and IS_ERASED = '0') loop
    begin
      select distinct b.mispar_zehut_ben_mishpacha
        into v_is_ben_mishpacha_mpm
        from bney_mishpacha b
       where b.mispar_zehut_ben_mishpacha = to_number(r.identity_number);
      dbms_output.put_line(r.identity_number);
    exception
      when no_data_found then
      
        continue;
    end;
    dbms_output.put_line(r.identity_number);
    update bney_mishpacha b
       set b.to_date_sium_zakaut = to_date(r.to_date, 'dd/mm/yyyy'),
           b.taarich_leda = case
                              when r.to_date is not null then
                               decode(b.taarich_leda,
                                      null,
                                      add_months(to_date(r.to_date,
                                                         'dd/mm/yyyy'),
                                                 -240),
                                      b.taarich_leda)
                              else
                               null
                            end
     where b.mispar_zehut_ben_mishpacha = r.identity_number
       and b.code_kirva = 2;
  end loop;
  commit;

  update bney_mishpacha b
     set b.taarich_leda = add_months(b.to_date_sium_zakaut, -240)
  
   where b.taarich_leda is null
     and b.to_date_sium_zakaut is not null
     and b.code_kirva = 2;

  for r in (select t1.seq_poresh,
                   t.seq_bakasha,
                   t2.seq_netuney_tik_mechushavim,
                   t2.achuz_kizba_sofi,
                   t."CODE_SUG_BAKASHA"
              from v_bakasha_last_zakaut t
              left join prisha t1
                on t."SEQ_PRISHA" = t1.seq_prisha
              left join netuney_tik_mechushavim t2
                on t.seq_bakasha = t2."SEQ_BAKASHA"
               and t2.code_department = 2
               and t2.mispar_misra = 0) loop
    select sum(nvl(b.achuz_kizba, 0) + nvl(b.achuz_tosefet, 0) * case
                 when r."CODE_SUG_BAKASHA" = 13 then
                  r.achuz_kizba_sofi / 100
                 else
                  1
               end)
      into v_toal_child
      from bney_mishpacha b
     where b.code_relative in (2, 3, 4)
       and r.seq_poresh = b.seq_porshim;
    update netuney_tik_mechushavim n
       set n.total_child = v_toal_child
     where n.seq_netuney_tik_mechushavim = r.seq_netuney_tik_mechushavim;
    commit;
  
  end loop;
  for r in (select t1.seq_poresh,
                   t.seq_bakasha,
                   t2.seq_netuney_tik_mechushavim
              from v_bakasha_last_zakaut t
              left join prisha t1
                on t."SEQ_PRISHA" = t1.seq_prisha
              left join netuney_tik_mechushavim t2
                on t.seq_bakasha = t2."SEQ_BAKASHA"
               and t2.code_department = 2
               and t2.mispar_misra = 0) loop
    select sum(nvl(b.achuz_kizba, 0))
      into v_toal_ben_zug
      from bney_mishpacha b
     where b.code_relative in (1, 14)
       and r.seq_poresh = b.seq_porshim;
    update netuney_tik_mechushavim n
       set n.total_ben_zug = v_toal_ben_zug
     where n.seq_netuney_tik_mechushavim = r.seq_netuney_tik_mechushavim;
  
    commit;
  
  end loop;

end;
/

create or replace procedure prm_system_copy.update_date_enter is
v_count number := 0;
begin
  for r in (select * from v_bakasha_last_status b
                   where b.code_action <> 98
