create or replace procedure prm_system_copy.update_hisachon_pensyoni is
  v_date_zakaut_letter date;
  v_day                number;
begin
  --update taarich prisha
  for r in (select t3.taarich_prisha taarich_prisha_b,
                   t.taarich_prisha,
                   t.seq_bakasha
              from v_bakasha_last_status t
              left join (select max(seq_bakasha) seq_bakasha, v.seq_prisha
                          from v_bakasha_last_status v
                         where v.code_merge_bakasha = 1
                         group by v.seq_prisha) t2
                on t.seq_prisha = t2.seq_prisha
              left join bakasha_regila t3
                on t2.seq_bakasha = t3.seq_bakasha
              left join netuney_tik_mechushavim t1
                on t1.seq_bakasha = t.seq_bakasha
             where t.code_sug_bakasha = 12
               and t.date_bakasha > to_date('01/01/2019', 'dd/mm/yyyy')
               and nvl(t1.code_e_zakaut, 0) = 0
               and pk_expiried.is_ezor_ovdim_hilan(t.seq_ezor_ovdim) = 1
               and t.code_action <> 17
               and t3.taarich_prisha <> t.taarich_prisha
               and t.taarich_prisha > to_date('01/01/2019', 'dd/mm/yyyy')) loop
  
    update bakasha_regila t
       set t.taarich_prisha = r.taarich_prisha_b
     where t.seq_bakasha = r.seq_bakasha;
  
    dbms_output.put_line(r.seq_bakasha);
  end loop;
  commit;

  dbms_output.put_line('----------------');

  for r in (select t1.hp_date_start_zakaut,
                   t1.hp_date_haavara,
                   
                   t.seq_bakasha,
                   t.mispar_zehut
              from v_bakasha_last_status t
              left join netuney_tik_mechushavim t1
                on t1.seq_bakasha = t.seq_bakasha
             where t.code_sug_bakasha = 12
               and t.date_bakasha > to_date('01/01/2019', 'dd/mm/yyyy')
               and nvl(t1.code_e_zakaut, 0) = 0
               and pk_expiried.is_ezor_ovdim_hilan(t.seq_ezor_ovdim) = 1
               and t.code_action <> 17
               and t.taarich_prisha < sysdate) loop
    select max(t1.date_update)
      into v_date_zakaut_letter
      from bakasha t
      left join document_bakasha t2
        on t2.seq_bakasha = t.seq_bakasha
      left join document t1
        on t1.seq_document = t2.seq_document
     where t1.SEQ_DOCUMENT_TYPE in
           (select distinct t.seq_document_type
              from perm_document_by_bakasha t
              left join code_document_type t1
                on t.seq_document_type = t1.seq_document_type
             where is_confirm = 1
               and t.code_department = 2)
       and t.seq_bakasha = r.seq_bakasha
       and t2.pail = 1
     order by 1 desc;
  
    if v_date_zakaut_letter is not null then
      v_day := EXTRACT(day FROM v_date_zakaut_letter + 45);
      update netuney_tik_mechushavim n
         set n.hp_date_start_zakaut = last_day(v_date_zakaut_letter) + 1,
             n.hp_date_haavara = case
                                   when v_day > 15 then
                                    last_day(v_date_zakaut_letter + 45) + 1
                                   else
                                    trunc(v_date_zakaut_letter + 45, 'mm')
                                 end
       where n.seq_bakasha = r.seq_bakasha
         and n.code_department = 2;
    end if;
    dbms_output.put_line(r.mispar_zehut);
  end loop;
  commit;
end update_hisachon_pensyoni;
/

create or replace procedure prm_system_copy.update_mazav_mispachti_poresh is
begin
  for r in (with pr as -- שליפת פורשים פעילים  ומצב משפחתי חילן 
               (select distinct to_number(t.a) mispar_zehut,
                               p.porshim_seq seq_poresh,
                               p.shem_prati shem_prati,
                               p.shem_mishpacha shem_mishpacha,
                               ll.TAARICH_PRISHA TAARICH_PRISHA,
                               t.h,
                               hilan_get_mpm_code_mazav_mishpachti(t.h) as mm_hilan,
                               'פורש' sug_gimlay
                 from TEMP_PORSHIM_HILAN_30092020 t
                 left join poresh p
                   on p.mispar_zehut = to_number(t.a)
                 --------------- 
                 left join (select po.porshim_seq seq_poresh,po.mispar_zehut, t.taarich_prisha from poresh  po   
                        left join prisha p on p.seq_poresh=po.porshim_seq
                       left  join v_prisha_last_zakaut t on t.SEQ_PRISHA=p.seq_prisha) ll on ll.seq_poresh=p.porshim_seq  
                 
                 ---------------  
                 /*left join v_regila_last_status ll
                   on p.mispar_zehut = ll.mispar_zehut
                  and ll.CODE_SUG_BAKASHA in (1, 3, 5)*/
                where t.as1 in (5, 6)
                  and t.ah in ('פעיל',
                               'חזר לפעילות',
                               'הפסקה זמנית')
                  and to_number(t.d) < 8),
              
              pr1 as
               (select distinct (t.id_number) as id_number,
                               pr.seq_poresh as seq_poresh,
                               max(t.marital_date) as marital_date,
                               PK_INTERIOR.get_mpm_code_mazav_mishpachti(t.marital_status) as int_status,
                               pr.mm_hilan as mm_chilan,
                               pr.TAARICH_PRISHA
                 from pr, ld_interior_all_30_3_22 t
                where pr.mispar_zehut = t.id_number
                group by t.id_number,
                         pr.seq_poresh,
                         t.marital_date,
                         t.marital_status,
                         pr.mm_hilan,
                         pr.TAARICH_PRISHA
                order by id_number)
              
              select pr1.id_number מספר_זהות,
                     pr1.seq_poresh seq_poresh,
                     pk_interior.convert_string_to_date(pr1.marital_date) date_int,
                     pr1.int_status code_int,
                     ------------------------------------------
                     a.code_mazav_mishpachti קוד_מפם,
                     a.date_mazav_mishpachti תאריך_מפם,
                     pr1.mm_chilan           קוד_חילן
                from pr1
              ----שליפת מצב משפחתי 
                left join (select seq_poresh,
                                  date_mazav_mishpachti,
                                  seq_mazav_mishpachti,
                                  code_mazav_mishpachti
                             from (select seq_poresh,
                                          date_mazav_mishpachti,
                                          seq_mazav_mishpachti,
                                          code_mazav_mishpachti,
                                          row_number() over(partition by seq_poresh order by nvl(date_mazav_mishpachti, to_date('01/01/1900', 'dd/mm/yyyy')) desc, seq_mazav_mishpachti desc) as rn
                                     from mazav_mishpachti mm1)
                            where rn = 1) a
                  on a.seq_poresh = pr1.seq_poresh
              
              ----------------------------------------------     
              
               where (pr1.TAARICH_PRISHA <
                     pk_interior.convert_string_to_date(pr1.marital_date) or
                     pr1.TAARICH_PRISHA is null)
                 and a.code_mazav_mishpachti <> pr1.int_status
                 and a.code_mazav_mishpachti not in (8, 4)) loop
    begin
    
     insert into mazav_mishpachti
        (seq_mazav_mishpachti,
         seq_poresh,
         seq_bney_mishpacha,
         code_mazav_mishpachti,
         date_mazav_mishpachti,
         date_update,
         code_user)
      values
        (mazav_mishpachti_seq.nextval,
         r.seq_poresh,
         null,
         r.code_int,
         r.date_int,
         sysdate,
         0);
    
     -- dbms_output.put_line(r.mispar_zehut || '-' || TO_CHAR(r.seq_poresh)  || '  ' || TO_CHAR(r.code_int) || '   '
     -- || TO_CHAR(r.date_int);
      
      
      
     
    
    exception
      when others then
        continue;
    end;
   -- commit;
  end loop;

--end;
end update_mazav_mispachti_poresh;
/

