create or replace procedure prm_system_copy.update_zakaut_misrot(
p_mispar_bakasha number,
p_mispar_gimla number,
p_mispar_teudat_zehut number) is

v_rows_number number;
v_netuney_tik_mechushavim_seq number;
v_mispar_misra number;
begin
  dbms_output.enable(999999);

  for r in (select t.*
    from temp_porshim_hilan t
    where t.mispar_zehut = p_mispar_teudat_zehut
    and t.mispar_gimla in (p_mispar_gimla, p_mispar_gimla*10 + 1, p_mispar_gimla*10 + 2))
  loop
         v_mispar_misra :=
         case when r.mispar_gimla = p_mispar_gimla then 0
              when r.mispar_gimla = p_mispar_gimla*10 + 1 then 0
              when r.mispar_gimla = p_mispar_gimla*10 + 2 then 1 end;
         dbms_output.put_line(to_char(r.mispar_zehut) || ',' || to_char(r.mispar_gimla) );
         select count(*)
         into v_rows_number
         from netuney_tik_mechushavim n
         where n.seq_bakasha = p_mispar_bakasha
         and n.code_department = 2
         and n.mispar_misra = v_mispar_misra;

         if v_rows_number = 0 then
           v_netuney_tik_mechushavim_seq := netuney_tik_mechushavim_seq.nextval;
           insert into netuney_tik_mechushavim n1
                                    (n1.seq_netuney_tik_mechushavim,
                                     n1.seq_bakasha,
                                     n1.code_department,
                                     n1.chelkiyut_sofit,
                                     n1.achuz_kizba_sofi,
                                     n1.mispar_misra,
                                     n1.date_start_zakaut,
                                     n1.date_update,
                                     n1.code_group_prisha)
                                  values
                                    (v_netuney_tik_mechushavim_seq,
                                     p_mispar_bakasha,
                                     2,
                                     r.chelkiyut_misra / 100,
                                     r.achuz_gimla,
                                     v_mispar_misra,
                                     r.taarich_minuy,
                                     sysdate,
                                     4);
         dbms_output.put_line(to_char(v_netuney_tik_mechushavim_seq) || ',' || to_char(v_mispar_misra));
         end if;
  end loop;
end;
/

create or replace procedure prm_system_copy.yatom_gil_20 is
  v_sug_bakasha_temp      number;
  v_sub_sug_bakasha_temp  number;
  v_is_exist_same_bakasha number;
begin

  for r in (select v1.mispar_zehut,
                   v1.seq_ezor_ovdim,
                   t.seq_bney_mishpacha,
                   v1.seq_porshim,
                   v.SEQ_BAKASHA,
                   t.to_date_sium_zakaut,
                   v1.seq_prisha
              from bney_mishpacha t
              left join prisha t1
                on t.seq_porshim = t1.seq_poresh
              left join v_bakasha_last_zakaut v
                on t1.seq_prisha = v.SEQ_PRISHA
              left join v_bakasha_last_status v1
                on v."SEQ_BAKASHA" = v1.seq_bakasha
             where pk_expiried.is_ezor_ovdim_hilan(v1.seq_ezor_ovdim) = 1
               and t.to_date_sium_zakaut < sysdate
               and t.to_date_sium_zakaut > sysdate - 50
                  /*and (nvl(t.achuz_kizba, 0) <> 0 or
                  nvl(t.achuz_tosefet, 0) <> 0)*/
               and t.code_kirva = 2
                  /*and t.code_relative in (2, 3)*/
               and t.taarich_ptira is null
               and (mod(v1.code_seif_prisha, 100) = 26 and
                    v1.code_merge_bakasha = 1 or v1.code_sug_bakasha = 13)
               and v1.code_action = 98
               and v1.mispar_zehut = 15134133) loop
  
    if pk_zakaut.get_sheer_group(r.seq_bakasha) = 1 then
      v_sug_bakasha_temp     := 5;
      v_sub_sug_bakasha_temp := 28;
    else
      v_sug_bakasha_temp     := 13;
      v_sub_sug_bakasha_temp := 30;
    end if;
  
    --by rivka 13/05/2019
    -- temp until hani will check it
    select count(*)
      into v_is_exist_same_bakasha
      from v_bakasha_last_status v
     where v.seq_prisha = r.seq_prisha
       and v.code_bakasha_detail in (7, 28, 30)
       and trunc(v.date_bakasha) >= trunc(sysdate)
       and v.code_action <> 17;
  
    if v_is_exist_same_bakasha = 0 then
    
      pk_expiried.create_bakasha_by_zakaut_data(r.seq_bakasha,
                                                v_sug_bakasha_temp,
                                                r.seq_bney_mishpacha,
                                                r.seq_porshim,
                                                r.seq_ezor_ovdim,
                                                r.mispar_zehut,
                                                v_sub_sug_bakasha_temp);
    
      --- total achuz diffrent, commit or back to start the worflow
    end if;
  end loop;
end;
------------------------------------------
/

create or replace package body prm_system_copy.convert_data_Hishtatfut_2_mpm is

  ----------------------------------------------------
  --  CREATE OR REPLACE TYPE num_nt  as table of number
  -----------------------------------------------------------
  v_id           number;
  v_ezor_ovdim   number;
  v_date_gzira   date;
  v_porshim_seq  number;
  v_seq_prisha   number;
  v_seq_bakasha  number;
  v_ora_err_tag$ varchar2(100);
  v_where        varchar2(100);
  --if_exist_participation_M_guf need to create additional bakasha
  v_is_exist_participation_M_guf boolean;
  v_is_exist_tkufot_avoda        boolean;
  v_CODE_GROUP_PRISHA            number;
  V_CHELKIYUT_MESHUKLELET        number;
  v_is_NOT_VALID_ID              boolean;
  v_sach_chodashim               number;
  v_CODE_SEIF_PRISHA             number;
  v_date_start_zakahut           date;
  v_is_RetirementSectionsMoreOne boolean;
  v_job_number                   number;
  V_code_makor                   number;
  V_is_updated_PORESH_DATA       boolean;
  V_is_updated_BenMishpacha_DATA boolean;
  v_misrad_maskoret              number;
  v_seq_Another_bakasha          number;
  v_date_end_zakaut              date;
  v_code_bakasha_detail          number;
  v_seq_MinBakasha               number;
  v_date_bakasha                 date;
  v_No_compatibility             boolean;
  v_CODE_SEIF_PRISHA_HILAN       number;
  v_CODE_MIN_PORESH              number;
  v_mis_Gimla                    number;
  v_delete_bakasha               varchar2(1000);
  v_date_prisha                  date;
  v_date_ptira                   date;
  v_is_do_commit                 boolean;
  v_SHEER_ID                     number;
  V_from_COpy_BAKAHSHA           number;
  V_sug_zihuy                    number;
  v_is_HOZE_BHIRIM               boolean;
  v_mis_misra                    number;
  v_ezor_ovdim_HILAN             number;
  V_IS_HAARACHAT_SHERUT          boolean;
  v_seq_bakasha_REGILA           number;
  v_seq_ben_mishpacha            number;
  --שדה לחיסכון פנסיוני
  v_hp_sheur_havara number;
  v_gender          varchar2(1000);
  v_is_ptira        number;
  ----------------------------------------------

  procedure set_global_fields(sug_bakasha number) is
    sugeyBakasha        num_nt;
    count_PRISHOR_MPM   number;
    count_PRISHOR_HILAN number;
  begin
  
    /*  begin
      select p.porshim_seq
        into v_porshim_seq
        from poresh p
       where p.mispar_zehut = v_id;
    exception
      when no_data_found then
        v_porshim_seq := null;
    end;*/
    --לשאול את דבורה כשיש כמה בקשות מסוג השתתפות מה לעשות ?
    begin
      select distinct max(b.seq_bakasha)
        into v_seq_bakasha
        from v_bakasha_last_status b
       where b.code_sug_bakasha = sug_bakasha
         and b.seq_prisha = v_seq_prisha;
    exception
      when no_data_found then
        v_seq_bakasha := null;
    end;
  
    if v_seq_bakasha is null then
      begin
        select distinct b.seq_bakasha
          into v_seq_bakasha
          from v_bakasha_last_status b
         where b.code_sug_bakasha = 1
           and b.seq_prisha = v_seq_prisha;
      exception
        when no_data_found then
          v_seq_bakasha := null;
      end;
      v_seq_bakasha_REGILA := v_seq_bakasha;
    
    end if;
  
  end;

