  procedure set_code_bakasha_detail(v_code_bakasha_hilan number,
                                    v_is_sheer           boolean) is
  begin
  
    if (v_code_bakasha_hilan = 42) then
      if v_is_sheer = true then
        v_code_bakasha_detail := 19;
      else
        v_code_bakasha_detail := 6;
      end if;
    else
      begin
        select t.code_bakasha_detail
          into v_code_bakasha_detail
          from CODE_BAKASHA_DETAIL t
         where t.code_bakasha_hilan = v_code_bakasha_hilan
           and t.code_sug_bakasha = 19;
      exception
        when no_data_found then
          v_code_bakasha_detail := null;
      end;
    end if;
  end;
  ---------------------------------------------
  --במקרה שיש 2 מספרי גימלה ורק הספרה האחרונה שונה , יש לקחת את מספר הגימלה ללא הסיפרה האחאחרונה
  procedure set_MIS_GIMLA is
    MIS_GIMLA1 number;
    MIS_GIMLA2 number;
  begin
    begin
      select MIS_GIMLA1
        into MIS_GIMLA1
        from (select ROWNUM as RN, (to_number(t.value)) as MIS_GIMLA1
              --into MIS_GIMLA1
                from ld_hilan_312 t
               where t.identity_number = V_ID
                 and t.variable_type = 100)
       where RN = 1;
    exception
      when no_data_found then
        MIS_GIMLA1 := null;
    end;
    begin
      select MIS_GIMLA2
        into MIS_GIMLA2
        from (select ROWNUM as RN, (to_number(t.value)) as MIS_GIMLA2
              --into MIS_GIMLA2
                from ld_hilan_312 t
               where t.identity_number = V_ID
                 and t.variable_type = 100)
       where RN = 2;
    exception
      when no_data_found then
        MIS_GIMLA2 := null;
    end;
    if (nvl(MIS_GIMLA1, 0) <> nvl(MIS_GIMLA2, 0) and nvl(MIS_GIMLA1, 0) > 0 and
       nvl(MIS_GIMLA2, 0) > 0 and
       trunc(MIS_GIMLA1 / 10) = trunc(MIS_GIMLA2 / 10)) then
      v_is_HOZE_BHIRIM := true;
      v_mis_Gimla      := MIS_GIMLA1;
    end if;
  
  end;
