  procedure update_actions_log_42_179 is
    --     41-178
  begin
    for r in (select al.Seq_Action_Log, b.seq_bakasha
                from ld_participation p
                left join code_ezor_ovdim e
                  on e.seq_ezor_ovdim = p.code_guf
                left join v_bakasha_last_status b
                  on b.mispar_zehut = p.identity_number
                left join action_log al
                  on al.Seq_Bakasha = b.seq_bakasha
               where e.Seq_Ezor_Ovdim in (10406, 10410)
                    --nvl(e.merkava_sapak_number, 0) = 0
                 and al.Code_Action in (42)) loop
    
      update action_log al
         set al.code_action = 179
       where al.Seq_Action_Log = r.Seq_Action_Log;
    
    end loop;
  
    for r in (select al.Seq_Action_Log, b.seq_bakasha
                from ld_participation p
                left join code_ezor_ovdim e
                  on e.seq_ezor_ovdim = p.code_guf
                left join v_bakasha_last_status b
                  on b.mispar_zehut = p.identity_number
                left join action_log al
                  on al.Seq_Bakasha = b.seq_bakasha
               where --nvl(e.merkava_sapak_number, 0) = 0
               e.Seq_Ezor_Ovdim in (10406, 10410)
           and al.Code_Action in (41)) loop
    
      update action_log al
         set al.code_action = 178
       where al.Seq_Action_Log = r.Seq_Action_Log;
    
    end loop;
  end;
