    --מחיקת בני משפחה שזהותם חופפת לזהות הפורש
  begin
    --dbms_output.enable(999999999);
    for r in (select distinct bm.Seq_Bney_Mishpacha,
                              b.mispar_zehut,
                              bm.mispar_zehut_ben_mishpacha
                from bney_mishpacha bm
                left join v_bakasha_BY_ZHEUT b
