      delete from bney_mishpacha bm
       where bm.Seq_Bney_Mishpacha = r.seq_bney_mishpacha;
      -- dbms_output.put_line('DELETE mispar_zehut_ben_mishpacha ' ||
    --                     r.mispar_zehut_ben_mishpacha);
    end loop;
  
  end;

