  function convert_seq_ezor_ovdim(v_kd_misrad_maskoret varchar,
                                  v_ezor_ovdim_        varchar) return number is
    v_kd_misrad       number;
    v_ezor_ovdim      number;
    v_SEQ_EZOR_OVDIM_ number;
  
  begin
    v_kd_misrad  := to_number(trim(v_kd_misrad_maskoret));
    v_ezor_ovdim := to_number(trim(v_ezor_ovdim_));
    begin
    
      select t.Seq_Ezor_Ovdim, t.code_makor
        into v_SEQ_EZOR_OVDIM_, V_code_makor
        from CODE_EZOR_OVDIM t
       where t.code_misrad_maskret = v_kd_misrad
         and t.code_ezor_ovdim = v_ezor_ovdim
            --פעיל = 1 לבקשת ליבה22_05_19
         and t.pail = 1
         and ROWNUM = 1;
