  function convert_code_seif_prisha(v_kd_sibat_prisha_ varchar) return number is
    v_kd_sibat_prisha number;
  begin
    v_kd_sibat_prisha := to_number(v_kd_sibat_prisha_);
    return case when v_kd_sibat_prisha = 15 then 126 when v_kd_sibat_prisha = 15 then 415 when v_kd_sibat_prisha = 218 then 118 when v_kd_sibat_prisha in(138,
                                                                                                                                                          162,
                                                                                                                                                          628,
                                                                                                                                                          815,
                                                                                                                                                          915) then null else v_kd_sibat_prisha end;
  end;

  --------------------------------------------------
  function convert_code_kirva(StatusCode char) return number is
    v_StatusCode number;
  begin
    v_StatusCode := to_NUMBER(StatusCode);
    return case when StatusCode in(1, 5) then 2 when StatusCode in(2,
                                                                   4,
                                                                   6,
                                                                   8) then 1 else null
    
    end;
  end;

  ----------------------------------------------------------
  function convert_0_or_1_number(var number) return number is
  begin
    return case var when 1 then 1 else 0 end;
  end;
  ----------------------------------------------------------
  function convert_0_or_1(var varchar2) return number is
    v_var number;
  begin
    begin
      v_var := to_number(trim(var));
    exception
      when others then
        v_var := null;
    end;
  
    return convert_0_or_1_number(v_var);
  end;

  -----------------------------------
  procedure update_CODE_MIN is
  begin
    if (v_gender like ('%גברים%')) then
      v_CODE_MIN_PORESH := 1;
    else
      v_CODE_MIN_PORESH := 2;
    end if;
  
  end;

  ----------------------------------------------------------
  function update_poresh return boolean is
    poresh_row err_porshim%rowtype;
  begin
    for r in (select distinct t.identity_number,
                              t.first_name      as first_name,
                              t.last_name       as last_name,
                              t.birth_date,
                              t.gender
              
                from Ld_Participation t
               where t.identity_number = v_id) loop
      v_gender := r.gender;
      update_CODE_MIN;
      poresh_row.code_min       := v_CODE_MIN_PORESH;
      poresh_row.mispar_zehut   := r.identity_number;
      poresh_row.shem_prati     := r.first_name;
      poresh_row.shem_mishpacha := r.last_name;
      poresh_row.taarich_leda   := r.birth_date;
      --      poresh_row.mikud          := r.Zone;
      PORESH_ROW.SUG_ZIHUY := V_sug_zihuy;
    
      --if v_porshim_seq is null and
      -- pk_load_mimshak.is_exist_poresh(v_id, v_porshim_seq) = false then
      if (v_porshim_seq is null) then
        v_porshim_seq := porshim_seq.nextval;
      end if;
      --      end if;
      --merge into poresh
      merge into poresh
      using dual
      on (poresh.mispar_zehut = poresh_row.mispar_zehut)
      when matched then
        update
           set --city_code             = poresh_row.city_code,
               
               shem_mishpacha = poresh_row.shem_mishpacha,
               shem_prati     = poresh_row.shem_prati,
               -- shem_kodem     = poresh_row.shem_kodem,
               code_min     = poresh_row.code_min,
               taarich_leda = poresh_row.taarich_leda,
               sug_zihuy    = poresh.Sug_Zihuy
        
      
      when not matched then
        insert
          ( --city_code,
           seq_apotropus,
           porshim_seq,
           mispar_zehut,
           shem_mishpacha,
           shem_prati,
           --shem_kodem,
           code_min,
           taarich_leda,
           --address,
           --mikud,
           --telephon,
           --code_mazav_mishpachti,
           taarich_aliya,
           is_newcomer,
           is_asir,
           date_begin_maasar,
           date_end_maasar,
           taarich_ptira,
           code_ptira_siba,
           is_owner_teudat_ptira,
           email,
           telephon,
           telephon2,
           sug_zihuy)
        values
          ( --poresh_row.city_code,
           poresh_row.seq_apotropus,
           v_porshim_seq,
           poresh_row.mispar_zehut,
           poresh_row.shem_mishpacha,
           poresh_row.shem_prati,
           --  poresh_row.shem_kodem,
           poresh_row.code_min,
           poresh_row.taarich_leda,
           --poresh_row.address,
           -- poresh_row.mikud,
           -- poresh_row.telephon,
           --poresh_row.code_mazav_mishpachti,
           poresh_row.taarich_aliya,
           poresh_row.is_newcomer,
           poresh_row.is_asir,
           poresh_row.date_begin_maasar,
           poresh_row.date_end_maasar,
           poresh_row.taarich_ptira,
           poresh_row.code_ptira_siba,
           poresh_row.is_owner_teudat_ptira,
           poresh_row.email,
           poresh_row.telephon,
           poresh_row.telephon2,
           poresh_row.Sug_Zihuy) log errors into err_porshim
          (v_ora_err_tag$) reject limit unlimited;
    end loop;
  
    if pk_load_mimshak.count_rowes('err_porshim', v_where) > 0 then
      return false;
    else
      return true;
    end if;
  
  end;
  ---------------------------------------

  PROCEDURE merge_bakasha_regila_AND_PORES is
    v_CODE_SEIF_P number;
  begin
  
    if (nvl(v_CODE_SEIF_PRISHA, 0) = 0) then
      v_CODE_SEIF_P := case v_CODE_SEIF_PRISHA_HILAN
                         when 15 then
                          126
                         when 115 then
                          415
                         when 218 then
                          118
                         else
                          v_CODE_SEIF_PRISHA_HILAN
                       end;
    
      UPDATE bakasha_regila br
         SET br.Code_Seif_Prisha = v_CODE_SEIF_P
       WHERE br.Seq_Bakasha = v_seq_bakasha;
    end if;
  
    UPDATE PORESH p
       SET p.sug_zihuy = V_sug_zihuy
     WHERE p.Porshim_Seq = v_porshim_seq;
  
  end;

  -------------------------------------------------
  PROCEDURE merge_PORESH is
    v_birth_date date;
  
  begin
    update_CODE_MIN;
    begin
      select distinct to_date(h200.birth_date, 'ddmmyyyy')
        into v_birth_date
        from ld_hilan_200 h200
       where h200.identity_number = v_id;
    exception
      when no_data_found then
        v_birth_date := null;
    end;
  
    if (v_birth_date is not null) then
      UPDATE PORESH p
         SET p.Taarich_Leda = v_birth_date
       WHERE p.mispar_zehut = v_ID
         and p.taarich_leda is null;
    end if;
  
    UPDATE PORESH p
       SET p.Code_Min = v_CODE_MIN_PORESH
     WHERE p.mispar_zehut = v_ID
       and nvl(p.Code_Min, 0) = 0;
  
  end;

  --------------------------------------------------------------
  function update_bakasha_regila return boolean is
    bakasha_regila_row err_bakasha_regila%rowtype;
    v_CODE_SEIF_P      number;
  begin
    for r in (select distinct t.identity_number,
                              t.retirement_section,
                              t.date_start,
                              t.Dummy_Salary
              
                from ld_participation t
              
               where t.identity_number = v_id) loop
    
      v_CODE_SEIF_P := r.retirement_section;
    
      bakasha_regila_row.maskoret_kovaat := r.Dummy_Salary;
      bakasha_regila_row.Taarich_Prisha  := r.date_start - INTERVAL '1' DAY;
    
      bakasha_regila_row.code_seif_prisha := v_CODE_SEIF_P;
      set_CODE_GROUP_PRISHA(bakasha_regila_row.code_seif_prisha);
    
      merge into bakasha_regila
      using dual
      on (bakasha_regila.seq_bakasha = v_seq_bakasha)
      when matched then
        update
           set --code_takanon_magal       = bakasha_regila_row.code_takanon_magal,
               
                taarich_prisha = bakasha_regila_row.taarich_prisha,
               code_seif_prisha = bakasha_regila_row.code_seif_prisha,
               maskoret_kovaat  = bakasha_regila_row.maskoret_kovaat
        
      
      when not matched then
        insert
          (seq_bakasha,
           taarich_prisha,
           code_seif_prisha,
           maskoret_kovaat
           
           )
        values
          (v_seq_bakasha,
           bakasha_regila_row.taarich_prisha,
           bakasha_regila_row.code_seif_prisha,
           bakasha_regila_row.maskoret_kovaat) log errors into err_bakasha_regila
          (v_ora_err_tag$) reject limit unlimited;
    
      if pk_load_mimshak.count_rowes('err_bakasha_regila', v_where) > 0 then
        return false;
      else
        return true;
      end if;
    
    end loop;
    return false;
  end;
  --------------------------------------------
  procedure ComparingValues(v_value1    number,
                            v_value2    number,
                            v_sourceTbl varchar2,
                            v_FieldName varchar2) is
  begin
    if v_value1 <> v_value2 then
      --חוסר תאימות
      v_No_compatibility := true;
      insert into warning_data_conversion
        (seq_bakasha,
         seq_porshim,
         mispar_zheut,
         source_table,
         field_name,
         current_value,
         conversion_value,
         date_bakasha,
         update_date)
      values
        (v_seq_bakasha,
         v_porshim_seq,
         v_ID,
         v_sourceTbl,
         v_FieldName,
         v_value1,
         v_value2,
         v_date_bakasha,
         sysdate);
    end if;
  
  end;
  ---------------------------------------------
  procedure Add_warning_data_conversion_ROW(v_value1    varchar2,
                                            v_value2    varchar2,
                                            v_sourceTbl varchar2,
                                            v_FieldName varchar2) is
  begin
    if (nvl(v_seq_bakasha, 0) = 0) then
      insert into warning_data_conversion
        (
         
         mispar_zheut,
         source_table,
         field_name,
         current_value,
         conversion_value,
         
         update_date)
      values
        (
         
         v_ID,
         v_sourceTbl,
         v_FieldName,
         v_value1,
         v_value2,
         
         sysdate);
    else
      insert into warning_data_conversion
        (seq_bakasha,
         seq_porshim,
         mispar_zheut,
         source_table,
         field_name,
         current_value,
         conversion_value,
         date_bakasha,
         update_date)
      values
        (v_seq_bakasha,
         v_porshim_seq,
         v_ID,
         v_sourceTbl,
         v_FieldName,
         v_value1,
         v_value2,
         v_date_bakasha,
         sysdate);
    end if;
  end;
  ---------------------
  procedure SET_CODE_SEIF_PRISHA_HILAN is
  begin
    begin
      select distinct h102.value
        into v_CODE_SEIF_PRISHA_HILAN
        from ld_hilan_312 h102
       where h102.identity_number = V_ID
         and h102.variable_type = 102
         and h102.job_number = v_job_number
         and h102.To_Date =
             (select max(hh102.To_Date)
                from ld_hilan_312 hh102
               where hh102.identity_number = h102.identity_number
                 and hh102.job_number = h102.job_number);
      --אם נופל להוסיף תנאי של ROWNUM
    exception
      when no_data_found then
        v_CODE_SEIF_PRISHA_HILAN := null;
      
    end;
  
  end;
  --------------------------------------------------
  procedure Find_charigim_data is
  begin
    for r in (select distinct h312.value,
                              b.gimla_number,
                              b.code_seif_prisha,
                              h102.value as HILAN_seif_prisha,
                              to_date(h537.From_Date, 'ddmmyyyy') as From_Date_prisha,
                              b.taarich_prisha
                from v_bakasha_last_status b
                left join ld_hilan_312 h312
                  on h312.identity_number = b.mispar_zehut
                 and h312.variable_type = 100
                 and h312.job_number = v_job_number
                left join ld_hilan_312 h102
                  on h102.identity_number = b.mispar_zehut
                 and h102.variable_type = 102
                 and h102.job_number = v_job_number
                left join ld_hilan_537 h537
                  on h537.identity_number = b.mispar_zehut
                 and h537.job_number = v_job_number
                 and h537.to_date like ('%9999999%')
               where b.seq_bakasha = v_seq_bakasha) loop
    
      set_MIS_GIMLA;
      if (nvl(v_mis_Gimla, 0) = 0) then
        v_mis_Gimla := r.value;
      end if;
      if (v_is_HOZE_BHIRIM = false) then
        ComparingValues(r.gimla_number,
                        v_mis_Gimla,
                        
                        'PRISHA',
                        'gimla_number');
      end if;
      v_CODE_SEIF_PRISHA_HILAN := to_number(nvl(r.HILAN_seif_prisha, 0));
      ComparingValues(nvl(r.code_seif_prisha, 0),
                      to_number(nvl(r.HILAN_seif_prisha, 0)),
                      
                      'BAKASHA_REGILA',
                      'code_seif_prisha');
      if ((r.taarich_prisha - r.From_Date_prisha) > 1) then
        insert into warning_data_conversion
          (seq_bakasha,
           seq_porshim,
           mispar_zheut,
           source_table,
           field_name,
           current_value,
           conversion_value,
           date_bakasha,
           update_date)
        values
          (v_seq_bakasha,
           v_porshim_seq,
           v_ID,
           'BAKASHA_REGILA',
           'taarich_prisha',
           r.taarich_prisha,
           r.From_Date_prisha,
           v_date_bakasha,
           sysdate);
      end if;
    
    end loop;
  end;
