  procedure merge_netuny_tik_2SHeeR_PNSYNY is
  begin
    --לעדכן סעיף פישה וגרופ פרישה במקרה והערכים רייקים
    SET_CODE_SEIF_PRISHA_HILAN;
    set_CODE_GROUP_PRISHA(v_CODE_SEIF_PRISHA_HILAN);
    for r in (select distinct nt.Chelkiyut_Lefi_Sherut,
                              nt.Tkufa_Mezaka_Sherut,
                              nt.Tkufa_Lo_Mezaka_Sherut,
                              nt.achuz_kizba_kafuf_chelkiyut,
                              nt.achuz_kizba_chelkiyut_melea,
                              nt.ahuz_kizb_achry_hagdl_kaf_chel
                from netuney_tik_mechushavim nt
               where nt.Seq_Bakasha = V_from_COpy_BAKAHSHA
                 and nt.code_department = 2
                 and nt.Mispar_Misra = 0) loop
    
      merge into netuney_tik_mechushavim n
      using dual
      on (n.SEQ_BAKASHA = v_seq_bakasha and n.code_department = 1)
      when matched then
        update
           set n.Chelkiyut_Lefi_Sherut          = r.Chelkiyut_Lefi_Sherut,
               n.Tkufa_Mezaka_Sherut            = r.Tkufa_Mezaka_Sherut,
               n.Tkufa_Lo_Mezaka_Sherut         = r.Tkufa_Lo_Mezaka_Sherut,
               n.achuz_kizba_kafuf_chelkiyut    = r.achuz_kizba_kafuf_chelkiyut,
               n.achuz_kizba_chelkiyut_melea    = r.achuz_kizba_chelkiyut_melea,
               n.ahuz_kizb_achry_hagdl_kaf_chel = r.ahuz_kizb_achry_hagdl_kaf_chel,
               n.Code_Group_Prisha              = nvl(n.Code_Group_Prisha,
                                                      v_CODE_GROUP_PRISHA)
      when not matched then
      
        insert
          (code_department,
           n.seq_netuney_tik_mechushavim,
           n.seq_bakasha,
           n.Chelkiyut_Lefi_Sherut,
           n.Tkufa_Mezaka_Sherut,
           n.Tkufa_Lo_Mezaka_Sherut,
           n.achuz_kizba_kafuf_chelkiyut,
           n.achuz_kizba_chelkiyut_melea,
           n.ahuz_kizb_achry_hagdl_kaf_chel,
           n.Code_Group_Prisha)
        values
          (1,
           netuney_tik_mechushavim_seq.nextval,
           v_seq_bakasha,
           
           r.Chelkiyut_Lefi_Sherut,
           r.Tkufa_Mezaka_Sherut,
           r.Tkufa_Lo_Mezaka_Sherut,
           r.achuz_kizba_kafuf_chelkiyut,
           r.achuz_kizba_chelkiyut_melea,
           r.ahuz_kizb_achry_hagdl_kaf_chel,
           v_CODE_GROUP_PRISHA) log errors into err_netuney_tik_mechushavim
          (v_ora_err_tag$) reject limit unlimited;
    
      --------------------------------------------------------------------------------------------
      merge into netuney_tik_mechushavim n
      using dual
      on (n.SEQ_BAKASHA = v_seq_bakasha and n.code_department = 2 and n.mispar_misra = 0)
      when matched then
        update
           set n.Chelkiyut_Lefi_Sherut          = r.Chelkiyut_Lefi_Sherut,
               n.Tkufa_Mezaka_Sherut            = r.Tkufa_Mezaka_Sherut,
               n.Tkufa_Lo_Mezaka_Sherut         = r.Tkufa_Lo_Mezaka_Sherut,
               n.achuz_kizba_kafuf_chelkiyut    = r.achuz_kizba_kafuf_chelkiyut,
               n.achuz_kizba_chelkiyut_melea    = r.achuz_kizba_chelkiyut_melea,
               n.ahuz_kizb_achry_hagdl_kaf_chel = r.ahuz_kizb_achry_hagdl_kaf_chel,
               n.Code_Group_Prisha              = nvl(n.Code_Group_Prisha,
                                                      v_CODE_GROUP_PRISHA)
      when not matched then
      
        insert
          (n.code_department,
           n.seq_netuney_tik_mechushavim,
           n.seq_bakasha,
           n.Chelkiyut_Lefi_Sherut,
           n.Tkufa_Mezaka_Sherut,
           n.Tkufa_Lo_Mezaka_Sherut,
           n.achuz_kizba_kafuf_chelkiyut,
           n.achuz_kizba_chelkiyut_melea,
           n.ahuz_kizb_achry_hagdl_kaf_chel,
           n.code_group_prisha)
        values
          (2,
           netuney_tik_mechushavim_seq.nextval,
           v_seq_bakasha,
           r.Chelkiyut_Lefi_Sherut,
           r.Tkufa_Mezaka_Sherut,
           r.Tkufa_Lo_Mezaka_Sherut,
           r.achuz_kizba_kafuf_chelkiyut,
           r.achuz_kizba_chelkiyut_melea,
           r.ahuz_kizb_achry_hagdl_kaf_chel,
           v_CODE_GROUP_PRISHA) log errors into err_netuney_tik_mechushavim
          (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  
  end;
  -----------------------------
  procedure HOZE_BHIRM_2_netny_tik_mchshvm(v_come_from_new_Bakasha boolean) is
    v_achuz_kizba_chelkiyut_melea number;
    v_code_sug_prisha             number;
    v_odef_sherut_yamim           number;
    v_odef_sherut_chodashim       number;
    v_odef_sherut_shanim          number;
  
    v_is_zakai_lmaanak             number;
    v_is_zakai_lkitzba             number;
    V_CHELKIYUT_MESHUKLELET_SHERUT number;
    V_TKUFA_MEZAKA_SHERUT          number;
    V_INDEX_MISRA                  number;
  begin
    V_INDEX_MISRA := 0;
  
    --LOOP JOB NUMBER 2 MISRAD _MASKORET
    for r1 in (select distinct h537.identity_number, h537.job_number
                 from ld_hilan_537 h537
                where h537.identity_number = v_id
                  and substr(h537.office, 1, 3) = v_misrad_maskoret) loop
    
      for r in (select distinct h567.identity_number,
                                h567.job_number,
                                to_number(h567.benefit_percent / 100) as benefit_percent,
                                to_number(h537.percent) / 10000 as percent,
                                h567.from_date_tokef,
                                to_number(h241.sum) as codashim,
                                to_number(h243.sum) as tkufa_mezaka_sherut,
                                to_number(h240.code) as is_z_maanak,
                                to_number(h24.sum) / 10000000 as achuz_gil_60,
                                
                                (select min(h2567.from_date_tokef)
                                   from ld_hilan_567 h2567
                                  where h2567.identity_number =
                                        h567.identity_number
                                    and h2567.job_number = h567.job_number) as date_start_zakaut
                /*, nt.achuz_kizba_sofi as current_Achuz_kizba_sofi,
                nt.date_start_zakaut as current_date_start_zakaut,
                nt.chelkiyut_meshuklelet_sherut as current_chelkiyut_meshuklelet_sherut,
                nt.tkufa_mezaka_sherut as current_tkufa_mezaka_sherut,
                nt.is_zakai_lmaanak as current_is_zakai_lmaanak,
                nt.ACHUZ_KIZBA_GIL_60 as current_ACHUZ_KIZBA_GIL_60,
                nt.ODEF_SHERUT_SHANIM as current_ODEF_SHERUT_SHANIM,
                nt.ODEF_SHERUT_CHODASHIM as current_ODEF_SHERUT_CHODASHIM,
                nt.Odef_Sherut_Yamim as current_Odef_Sherut_Yamim,
                nt.Chelkiyut_Sofit as current_Chelkiyut_Sofit*/
                
                  from ld_hilan_567 h567
                  left join ld_hilan_527 h240
                    on h240.identity_number = h567.identity_number
                   and h240.job_number = h567.job_number
                   and h240.semel = 242
                  left join ld_hilan_527 h241
                    on h241.identity_number = h567.identity_number
                   and h241.job_number = h567.job_number
                   and h241.semel = 241
                   and h241.to_date =
                       (select max(Hh241.To_Date)
                          from ld_hilan_527 Hh241
                         where Hh241.semel = 241
                           and hh241.identity_number = h567.identity_number
                           and hh241.job_number = h567.job_number)
                  left join ld_hilan_527 h243
                    on h243.identity_number = h567.identity_number
                   and h243.job_number = h567.job_number
                   and h243.semel = 243
                  left join ld_hilan_527 h24
                    on h24.identity_number = h567.identity_number
                   and h24.job_number = h567.job_number
                   and h24.semel = 24
                  left join ld_hilan_537 h537
                    on h537.identity_number = h567.identity_number
                   and h537.job_number = h567.job_number
                   and h537.to_date like ('%9999999%')
                  left join ld_hilan_537 h537
                    on h537.identity_number = h567.identity_number
                   and h537.job_number = h567.job_number
                   and h537.to_date like ('%9999999%')
                /*  left join netuney_tik_mechushavim nt
                 on nt.Seq_Bakasha = v_seq_bakasha
                and nt.code_department = 2*/
                
                 where h567.identity_number = V_ID
                   and h567.job_number = r1.job_number
                   and h567.from_date =
                       (select max(hh567.from_date)
                          from ld_hilan_567 hh567
                         where hh567.identity_number = h567.identity_number
                           and hh567.job_number = h567.job_number)
                   and h567.to_date_tokef like ('%9999999%')
                
                ) loop
      
        v_odef_sherut_chodashim := trunc(r.codashim / 100);
      
        v_odef_sherut_shanim := trunc(v_odef_sherut_chodashim / 12);
        v_odef_sherut_yamim  := round(MOD((r.codashim / 100), 1) * 30.44);
        v_date_start_zakahut := to_date(r.date_start_zakaut, 'DDMMYYYY');
        -- v_date_start_zakahut := to_date('0' || substr(r.from_date_tokef, 1, 7), 'DDMMYYYY');
      
        --       substr(h537.office, 1, 3)
      
        /* V_CHELKIYUT_MESHUKLELET_SHERUT := r.partiality / 1000;
        if (V_CHELKIYUT_MESHUKLELET_SHERUT > 70) then
          V_CHELKIYUT_MESHUKLELET_SHERUT := 70;
        end if;*/
        V_TKUFA_MEZAKA_SHERUT := r.tkufa_mezaka_sherut / 100;
        v_No_compatibility    := false;
      
        --אם אין חוסר תאימות או שתאריכי הבקשה קטן מ2017
        /* if v_come_from_new_Bakasha or
          --v_No_compatibility = false or
          --אם הגיע מהסבות ואחוז קיצבה ריק , כן יש לעדכן את הטבלה
           v_date_bakasha < to_date('01102017', 'ddmmyyyy') or
           (v_date_bakasha >= to_date('01102017', 'ddmmyyyy') and
           V_INDEX_MISRA > 0)
        --   or nvl(r.current_achuz_kizba_sofi, 0) = 0 
         then*/
      
        -- execute immediate 'ALTER TRIGGER Netuney_Tik_Mechushavim_maakav_history_TRG ENABLE';
      
        merge into netuney_tik_mechushavim n
        using dual
        on (n.SEQ_BAKASHA = v_seq_bakasha and n.code_department = 1 and n.mispar_misra = V_INDEX_MISRA)
        when matched then
          update
             set n.date_start_zakaut = n.date_start_zakaut --v_date_start_zakahut,
          -- n.achuz_kizba_sofi             = to_number(r.Benefit_Percent),
          -- n.achuz_kizba_kafuf_chelkiyut  = to_number(r.Benefit_Percent),
          -- n.CHELKIYUT_MESHUKLELET_SHERUT = to_number(r.percent),
          -- n.TKUFA_MEZAKA_SHERUT          = V_TKUFA_MEZAKA_SHERUT,
          
          --n.IS_ZAKAI_LMAANAK = r.is_z_maanak,
          --n.CHELKIYUT_SOFIT  = to_number(r.percent),
          -- n.ACHUZ_KIZBA_GIL_60    = r.achuz_gil_60,
          --n.IS_HACHLATA_SOFIT              = 1,
          --                 n.ODEF_SHERUT_SHANIM             = v_odef_sherut_shanim,
          --               n.ODEF_SHERUT_CHODASHIM          = v_odef_sherut_chodashim,
          --             n.ODEF_SHERUT_YAMIM              = v_odef_sherut_yamim,
          --           n.achuz_kizb_achry_hagdl_chl_mla = to_number(r.Benefit_Percent)
          
        
        when not matched then
        
          insert
            (code_department,
             n.seq_netuney_tik_mechushavim,
             n.seq_bakasha,
             n.date_start_zakaut,
             n.achuz_kizba_sofi,
             n.achuz_kizba_kafuf_chelkiyut,
             n.CHELKIYUT_MESHUKLELET_SHERUT,
             n.TKUFA_MEZAKA_SHERUT,
             n.CODE_GROUP_PRISHA,
             n.IS_ZAKAI_LMAANAK,
             n.CHELKIYUT_SOFIT,
             -- n.ACHUZ_KIZBA_GIL_60,
             n.IS_HACHLATA_SOFIT,
             n.ODEF_SHERUT_SHANIM,
             n.ODEF_SHERUT_CHODASHIM,
             n.ODEF_SHERUT_YAMIM,
             n.mispar_misra,
             Ahuz_Kizb_Achry_Hagdl_Kaf_Chel)
          values
            (1,
             netuney_tik_mechushavim_seq.nextval,
             v_seq_bakasha,
             v_date_start_zakahut,
             to_number(r.Benefit_Percent),
             to_number(r.Benefit_Percent),
             to_number(r.percent),
             V_TKUFA_MEZAKA_SHERUT,
             v_CODE_GROUP_PRISHA,
             r.is_z_maanak,
             to_number(r.percent),
             -- r.achuz_gil_60,
             1,
             v_odef_sherut_shanim,
             v_odef_sherut_chodashim,
             v_odef_sherut_yamim,
             V_INDEX_MISRA,
             to_number(r.Benefit_Percent)) log errors into err_netuney_tik_mechushavim
            (v_ora_err_tag$) reject limit unlimited;
      
        ------------------------------------------
        merge into netuney_tik_mechushavim n
        using dual
        on (n.SEQ_BAKASHA = v_seq_bakasha and n.code_department = 2 and n.mispar_misra = V_INDEX_MISRA)
        when matched then
          update
             set n.date_start_zakaut            = v_date_start_zakahut,
                 n.achuz_kizba_sofi             = to_number(r.Benefit_Percent),
                 n.achuz_kizba_kafuf_chelkiyut  = to_number(r.Benefit_Percent),
                 n.CHELKIYUT_MESHUKLELET_SHERUT = to_number(r.percent),
                 n.TKUFA_MEZAKA_SHERUT          = V_TKUFA_MEZAKA_SHERUT,
                 
                 n.IS_ZAKAI_LMAANAK = r.is_z_maanak,
                 n.CHELKIYUT_SOFIT  = to_number(r.percent),
                 -- n.ACHUZ_KIZBA_GIL_60    = r.achuz_gil_60,
                 n.IS_HACHLATA_SOFIT              = 1,
                 n.ODEF_SHERUT_SHANIM             = v_odef_sherut_shanim,
                 n.ODEF_SHERUT_CHODASHIM          = v_odef_sherut_chodashim,
                 n.ODEF_SHERUT_YAMIM              = v_odef_sherut_yamim,
                 n.Ahuz_Kizb_Achry_Hagdl_Kaf_Chel = to_number(r.Benefit_Percent)
        when not matched then
        
          insert
            (code_department,
             n.seq_netuney_tik_mechushavim,
             n.seq_bakasha,
             n.date_start_zakaut,
             n.achuz_kizba_sofi,
             n.achuz_kizba_kafuf_chelkiyut,
             n.CHELKIYUT_MESHUKLELET_SHERUT,
             n.TKUFA_MEZAKA_SHERUT,
             n.CODE_GROUP_PRISHA,
             n.IS_ZAKAI_LMAANAK,
             n.CHELKIYUT_SOFIT,
             -- n.ACHUZ_KIZBA_GIL_60,
             n.IS_HACHLATA_SOFIT,
             n.ODEF_SHERUT_SHANIM,
             n.ODEF_SHERUT_CHODASHIM,
             n.ODEF_SHERUT_YAMIM,
             n.mispar_misra,
             n.Ahuz_Kizb_Achry_Hagdl_Kaf_Chel)
          values
            (2,
             netuney_tik_mechushavim_seq.nextval,
             v_seq_bakasha,
             v_date_start_zakahut,
             to_number(r.Benefit_Percent),
             to_number(r.Benefit_Percent),
             to_number(r.percent),
             V_TKUFA_MEZAKA_SHERUT,
             v_CODE_GROUP_PRISHA,
             r.is_z_maanak,
             to_number(r.percent),
             -- r.achuz_gil_60,
             1,
             v_odef_sherut_shanim,
             v_odef_sherut_chodashim,
             v_odef_sherut_yamim,
             V_INDEX_MISRA,
             to_number(r.Benefit_Percent)) log errors into err_netuney_tik_mechushavim
            (v_ora_err_tag$) reject limit unlimited;
      
        -- end if;
        V_INDEX_MISRA := V_INDEX_MISRA + 1;
      end loop;
    
    end loop;
  end;
  -----------------------------------

  procedure merge_netuney_tik_mechushavim is
    v_achuz_kizba_chelkiyut_melea number;
    v_code_sug_prisha             number;
    v_odef_sherut_yamim           number;
    v_odef_sherut_chodashim       number;
    v_odef_sherut_shanim          number;
  
    v_is_zakai_lmaanak             number;
    v_is_zakai_lkitzba             number;
    V_CHELKIYUT_MESHUKLELET_SHERUT number;
    V_TKUFA_MEZAKA_SHERUT          number;
  begin
    SET_CODE_SEIF_PRISHA_HILAN;
    set_CODE_GROUP_PRISHA(v_CODE_SEIF_PRISHA_HILAN);
    for r in (select distinct h567.identity_number,
                              h567.job_number,
                              to_number(h567.benefit_percent / 100) as benefit_percent,
                              to_number(h537.percent) / 10000 as percent,
                              h567.from_date_tokef,
                              to_number(h241.sum) as codashim,
                              to_number(h243.sum) as tkufa_mezaka_sherut,
                              to_number(h240.code) as is_z_maanak,
                              to_number(h24.sum) / 10000000 as achuz_gil_60,
                              
                              (select min(h2567.from_date_tokef)
                                 from ld_hilan_567 h2567
                                where h2567.identity_number =
                                      h567.identity_number
                                  and h2567.job_number = h567.job_number) as date_start_zakaut,
                              nt.achuz_kizba_sofi as current_Achuz_kizba_sofi,
                              nt.date_start_zakaut as current_date_start_zakaut,
                              nt.chelkiyut_meshuklelet_sherut as current_chelkiyut_meshuklelet_sherut,
                              nt.tkufa_mezaka_sherut as current_tkufa_mezaka_sherut,
                              nt.is_zakai_lmaanak as current_is_zakai_lmaanak,
                              nt.ACHUZ_KIZBA_GIL_60 as current_ACHUZ_KIZBA_GIL_60,
                              nt.ODEF_SHERUT_SHANIM as current_ODEF_SHERUT_SHANIM,
                              nt.ODEF_SHERUT_CHODASHIM as current_ODEF_SHERUT_CHODASHIM,
                              nt.Odef_Sherut_Yamim as current_Odef_Sherut_Yamim,
                              nt.Chelkiyut_Sofit as current_Chelkiyut_Sofit
              
                from ld_hilan_567 h567
                left join ld_hilan_527 h240
                  on h240.identity_number = h567.identity_number
                 and h240.job_number = h567.job_number
                 and h240.semel = 242
                left join ld_hilan_527 h241
                  on h241.identity_number = h567.identity_number
                 and h241.job_number = h567.job_number
                 and h241.semel = 241
                 and h241.to_date =
                     (select max(Hh241.To_Date)
                        from ld_hilan_527 Hh241
                       where Hh241.semel = 241
                         and hh241.identity_number = h567.identity_number
                         and hh241.job_number = h567.job_number)
                left join ld_hilan_527 h243
                  on h243.identity_number = h567.identity_number
                 and h243.job_number = h567.job_number
                 and h243.semel = 243
                left join ld_hilan_527 h24
                  on h24.identity_number = h567.identity_number
                 and h24.job_number = h567.job_number
                 and h24.semel = 24
                left join ld_hilan_537 h537
                  on h537.identity_number = h567.identity_number
                 and h537.job_number = h567.job_number
                 and h537.to_date like ('%9999999%')
                left join ld_hilan_537 h537
                  on h537.identity_number = h567.identity_number
                 and h537.job_number = h567.job_number
                 and h537.to_date like ('%9999999%')
                left join netuney_tik_mechushavim nt
                  on nt.Seq_Bakasha = v_seq_bakasha
                 and nt.code_department = 2
                 and nt.mispar_misra = 0
               where h567.identity_number = V_ID
                 and h567.job_number = v_job_number
                 and h567.from_date =
                     (select max(hh567.from_date)
                        from ld_hilan_567 hh567
                       where hh567.identity_number = h567.identity_number
                         and hh567.job_number = h567.job_number)
                 and h567.to_date_tokef like ('%9999999%')
              
              ) loop
    
      v_odef_sherut_chodashim := trunc(r.codashim / 100);
    
      v_odef_sherut_shanim := trunc(v_odef_sherut_chodashim / 12);
      v_odef_sherut_yamim  := round(MOD((r.codashim / 100), 1) * 30.44);
      v_date_start_zakahut := to_date(r.date_start_zakaut, 'DDMMYYYY');
      -- v_date_start_zakahut := to_date('0' || substr(r.from_date_tokef, 1, 7), 'DDMMYYYY');
    
      --       substr(h537.office, 1, 3)
    
      /* V_CHELKIYUT_MESHUKLELET_SHERUT := r.partiality / 1000;
      if (V_CHELKIYUT_MESHUKLELET_SHERUT > 70) then
        V_CHELKIYUT_MESHUKLELET_SHERUT := 70;
      end if;*/
      V_TKUFA_MEZAKA_SHERUT := r.tkufa_mezaka_sherut / 100;
      v_No_compatibility    := false;
      if (v_is_HOZE_BHIRIM = false) then
        ComparingValues(r.current_achuz_kizba_sofi,
                        to_number(nvl(r.Benefit_Percent, 0)),
                        'Netuney_Tik_Mechushavim',
                        'achuz_kizba_sofi');
        ComparingValues(r.current_Chelkiyut_Sofit,
                        to_number(nvl(r.percent, 0)),
                        'Netuney_Tik_Mechushavim',
                        'Chelkiyut_Sofit');
        --לבקשת דבור - לא רלבנטי כי הם לא שולחים לנו ערך
        /*      ComparingValues(r.Current_Tkufa_Mezaka_Sherut,
        nvl(V_TKUFA_MEZAKA_SHERUT, 0),
        'Netuney_Tik_Mechushavim',
        'Tkufa_Mezaka_Sherut');*/
        ComparingValues(r.Current_Is_Zakai_Lmaanak,
                        to_number(nvl(r.is_z_maanak, 0)),
                        'Netuney_Tik_Mechushavim',
                        'Is_Zakai_Lmaanak');
        /*ComparingValues(r.Current_Achuz_Kizba_Gil_60,
        to_number(nvl(r.achuz_gil_60, 0)),
        'Netuney_Tik_Mechushavim',
        'Achuz_Kizba_Gil_60');*/
        ComparingValues(r.current_odef_sherut_shanim,
                        to_number(nvl(v_odef_sherut_shanim, 0)),
                        'Netuney_Tik_Mechushavim',
                        'odef_sherut_shanim');
        ComparingValues(r.Current_Odef_Sherut_Chodashim,
                        nvl(v_odef_sherut_chodashim, 0),
                        'Netuney_Tik_Mechushavim',
                        'Odef_Sherut_Chodashim');
        ComparingValues(r.Current_Odef_Sherut_Yamim,
                        nvl(v_odef_sherut_yamim, 0),
                        'Netuney_Tik_Mechushavim',
                        'Odef_Sherut_Yamim');
      end if;
      --אם אין חוסר תאימות או שתאריכי הבקשה קטן מ2017
      if
      --v_No_compatibility = false or
      --אם הגיע מהסבות ואחוז קיצבה ריק , כן יש לעדכן את הטבלה
       v_date_bakasha < to_date('01102017', 'ddmmyyyy') or
       nvl(r.current_achuz_kizba_sofi, 0) = 0 then
      
        -- execute immediate 'ALTER TRIGGER Netuney_Tik_Mechushavim_maakav_history_TRG ENABLE';
      
        merge into netuney_tik_mechushavim n
        using dual
        on (n.SEQ_BAKASHA = v_seq_bakasha and n.code_department = 1)
        when matched then
          update
             set n.date_start_zakaut = v_date_start_zakahut,
                 n.achuz_kizba_sofi  = nvl(to_number(r.Benefit_Percent),
                                           n.achuz_kizba_sofi),
                 --בגלל שזה במדינה אז לדרוס רק כשריק
                 n.achuz_kizba_kafuf_chelkiyut  = nvl(n.achuz_kizba_kafuf_chelkiyut,
                                                      to_number(r.Benefit_Percent)),
                 n.CHELKIYUT_MESHUKLELET_SHERUT = nvl(to_number(r.percent),
                                                      n.CHELKIYUT_MESHUKLELET_SHERUT),
                 n.TKUFA_MEZAKA_SHERUT          = V_TKUFA_MEZAKA_SHERUT,
                 
                 n.IS_ZAKAI_LMAANAK = r.is_z_maanak,
                 n.CHELKIYUT_SOFIT  = to_number(r.percent),
                 -- n.ACHUZ_KIZBA_GIL_60    = r.achuz_gil_60,
                 n.IS_HACHLATA_SOFIT     = 1,
                 n.ODEF_SHERUT_SHANIM    = v_odef_sherut_shanim,
                 n.ODEF_SHERUT_CHODASHIM = v_odef_sherut_chodashim,
                 n.ODEF_SHERUT_YAMIM     = v_odef_sherut_yamim,
                 
                 n.ahuz_kizb_achry_hagdl_kaf_chel = NVL(n.ahuz_kizb_achry_hagdl_kaf_chel,
                                                        to_number(r.Benefit_Percent)),
                 n.code_group_prisha              = nvl(n.code_group_prisha,
                                                        v_CODE_GROUP_PRISHA)
          
        
        when not matched then
        
          insert
            (code_department,
             n.seq_netuney_tik_mechushavim,
             n.seq_bakasha,
             n.date_start_zakaut,
             n.achuz_kizba_sofi,
             n.achuz_kizba_kafuf_chelkiyut,
             n.CHELKIYUT_MESHUKLELET_SHERUT,
             n.TKUFA_MEZAKA_SHERUT,
             n.CODE_GROUP_PRISHA,
             n.IS_ZAKAI_LMAANAK,
             n.CHELKIYUT_SOFIT,
             -- n.ACHUZ_KIZBA_GIL_60,
             n.IS_HACHLATA_SOFIT,
             n.ODEF_SHERUT_SHANIM,
             n.ODEF_SHERUT_CHODASHIM,
             n.ODEF_SHERUT_YAMIM,
             
             n.ahuz_kizb_achry_hagdl_kaf_chel)
          values
            (1,
             netuney_tik_mechushavim_seq.nextval,
             v_seq_bakasha,
             v_date_start_zakahut,
             to_number(r.Benefit_Percent),
             to_number(r.Benefit_Percent),
             to_number(r.percent),
             V_TKUFA_MEZAKA_SHERUT,
             v_CODE_GROUP_PRISHA,
             r.is_z_maanak,
             to_number(r.percent),
             -- r.achuz_gil_60,
             1,
             v_odef_sherut_shanim,
             v_odef_sherut_chodashim,
             v_odef_sherut_yamim,
             to_number(r.Benefit_Percent)) log errors into err_netuney_tik_mechushavim
            (v_ora_err_tag$) reject limit unlimited;
      
        --------------------------------------------------------------------------------------------
        merge into netuney_tik_mechushavim n
        using dual
        on (n.SEQ_BAKASHA = v_seq_bakasha and n.code_department = 2 and n.mispar_misra = 0)
        when matched then
          update
             set n.date_start_zakaut = v_date_start_zakahut,
                 n.achuz_kizba_sofi  = nvl(to_number(r.Benefit_Percent),
                                           n.achuz_kizba_sofi),
                 --בגלל שזה במדינה אז לדרוס רק כשריק
                 n.achuz_kizba_kafuf_chelkiyut  = nvl(n.achuz_kizba_kafuf_chelkiyut,
                                                      to_number(r.Benefit_Percent)),
                 n.CHELKIYUT_MESHUKLELET_SHERUT = nvl(to_number(r.percent),
                                                      n.CHELKIYUT_MESHUKLELET_SHERUT),
                 n.TKUFA_MEZAKA_SHERUT          = V_TKUFA_MEZAKA_SHERUT,
                 
                 n.IS_ZAKAI_LMAANAK = r.is_z_maanak,
                 n.CHELKIYUT_SOFIT  = to_number(r.percent),
                 -- n.ACHUZ_KIZBA_GIL_60    = r.achuz_gil_60,
                 n.IS_HACHLATA_SOFIT     = 1,
                 n.ODEF_SHERUT_SHANIM    = v_odef_sherut_shanim,
                 n.ODEF_SHERUT_CHODASHIM = v_odef_sherut_chodashim,
                 n.ODEF_SHERUT_YAMIM     = v_odef_sherut_yamim,
                 
                 n.ahuz_kizb_achry_hagdl_kaf_chel = NVL(n.ahuz_kizb_achry_hagdl_kaf_chel,
                                                        to_number(r.Benefit_Percent)),
                 n.code_group_prisha              = nvl(n.code_group_prisha,
                                                        v_CODE_GROUP_PRISHA)
          
        
        when not matched then
        
          insert
            (code_department,
             n.seq_netuney_tik_mechushavim,
             n.seq_bakasha,
             n.date_start_zakaut,
             n.achuz_kizba_sofi,
             n.achuz_kizba_kafuf_chelkiyut,
             n.CHELKIYUT_MESHUKLELET_SHERUT,
             n.TKUFA_MEZAKA_SHERUT,
             n.CODE_GROUP_PRISHA,
             n.IS_ZAKAI_LMAANAK,
             n.CHELKIYUT_SOFIT,
             -- n.ACHUZ_KIZBA_GIL_60,
             n.IS_HACHLATA_SOFIT,
             n.ODEF_SHERUT_SHANIM,
             n.ODEF_SHERUT_CHODASHIM,
             n.ODEF_SHERUT_YAMIM,
             n.ahuz_kizb_achry_hagdl_kaf_chel)
          values
            (2,
             netuney_tik_mechushavim_seq.nextval,
             v_seq_bakasha,
             v_date_start_zakahut,
             to_number(r.Benefit_Percent),
             to_number(r.Benefit_Percent),
             to_number(r.percent),
             V_TKUFA_MEZAKA_SHERUT,
             v_CODE_GROUP_PRISHA,
             r.is_z_maanak,
             to_number(r.percent),
             -- r.achuz_gil_60,
             1,
             v_odef_sherut_shanim,
             v_odef_sherut_chodashim,
             v_odef_sherut_yamim,
             to_number(r.Benefit_Percent)) log errors into err_netuney_tik_mechushavim
            (v_ora_err_tag$) reject limit unlimited;
      
      end if;
    
    end loop;
  
  end;
  -------------------------------------

  procedure update_netuney_tik_mechushavim is
  
  begin
    for r in (select distinct t.identity_number,
                              t.perecentage,
                              t.partiality,
                              --במקום SALARY
                              t.pension_without_taxes as SALARY,
                              t.date_start,
                              t.PENSION_WITHOUT_TAXES
                from ld_participation t
              
               where t.identity_number = v_ID
              
              ) loop
    
      merge into netuney_tik_mechushavim n
      using dual
      on (n.Seq_Bakasha = v_seq_bakasha and n.code_department = 2)
      when matched then
        update
           set n.date_start_zakaut            = r.date_start,
               n.achuz_kizba_sofi             = to_number(r.perecentage),
               n.Chelkiyut_Sofit              = to_number(r.partiality),
               n.Chelkiyut_Meshuklelet_Sherut = r.partiality,
               
               n.achuz_kizba_kafuf_chelkiyut    = to_number(r.perecentage),
               n.ahuz_kizb_achry_hagdl_kaf_chel = round(to_number(r.perecentage),
                                                        2),
               n.maskoret_kizba                 = to_number(r.salary),
               n.date_update                    = r.date_start,
               n.schum_kizba                    = r.PENSION_WITHOUT_TAXES
      when not matched then
        insert
          (code_department,
           n.seq_netuney_tik_mechushavim,
           n.seq_bakasha,
           n.date_start_zakaut,
           n.achuz_kizba_sofi,
           n.Chelkiyut_Sofit,
           n.Chelkiyut_Meshuklelet_Sherut,
           n.achuz_kizba_kafuf_chelkiyut,
           n.ahuz_kizb_achry_hagdl_kaf_chel,
           n.maskoret_kizba,
           n.date_update,
           n.schum_kizba)
        values
          (2,
           netuney_tik_mechushavim_seq.nextval,
           v_seq_bakasha,
           r.date_start,
           to_number(r.perecentage),
           to_number(r.partiality),
           round(to_number(r.partiality), 2),
           to_number(r.perecentage),
           round(to_number(r.perecentage), 2),
           to_number(r.salary),
           r.date_start,
           r.PENSION_WITHOUT_TAXES) log errors into err_netuney_tik_mechushavim
          (v_ora_err_tag$) reject limit unlimited;
    
      --------------------------------------
      merge into netuney_tik_mechushavim n
      using dual
      on (n.Seq_Bakasha = v_seq_bakasha and n.code_department = 1)
      when matched then
        update
           set n.date_start_zakaut              = r.date_start,
               n.achuz_kizba_sofi               = to_number(r.perecentage),
               n.Chelkiyut_Sofit                = to_number(r.partiality),
               n.Chelkiyut_Meshuklelet_Sherut   = r.partiality,
               n.achuz_kizba_kafuf_chelkiyut    = to_number(r.perecentage),
               n.ahuz_kizb_achry_hagdl_kaf_chel = round(to_number(r.perecentage),
                                                        2),
               n.maskoret_kizba                 = to_number(r.salary),
               n.date_update                    = r.date_start,
               n.schum_kizba                    = r.PENSION_WITHOUT_TAXES
      when not matched then
        insert
          (code_department,
           n.seq_netuney_tik_mechushavim,
           n.seq_bakasha,
           n.date_start_zakaut,
           n.achuz_kizba_sofi,
           n.Chelkiyut_Sofit,
           n.Chelkiyut_Meshuklelet_Sherut,
           n.achuz_kizba_kafuf_chelkiyut,
           n.ahuz_kizb_achry_hagdl_kaf_chel,
           n.maskoret_kizba,
           n.date_update,
           n.schum_kizba)
        values
          (1,
           netuney_tik_mechushavim_seq.nextval,
           v_seq_bakasha,
           r.date_start,
           to_number(r.perecentage),
           to_number(r.partiality),
           r.partiality,
           to_number(r.perecentage),
           round(to_number(r.perecentage), 2),
           to_number(r.salary),
           r.date_start,
           r.PENSION_WITHOUT_TAXES) log errors into err_netuney_tik_mechushavim
          (v_ora_err_tag$) reject limit unlimited;
    end loop;
  end;
  -------------------------------------------------
  procedure update_netuneyTik2HafsakatTslm(v_code_satate number,
                                           v_IS_SHEER    boolean) is
    v_achuz_kizba_chelkiyut_melea number;
    v_code_sug_prisha             number;
    v_odef_sherut_yamim           number;
    v_odef_sherut_chodashim       number;
    v_odef_sherut_shanim          number;
  
    v_is_zakai_lmaanak             number;
    v_is_zakai_lkitzba             number;
    V_CHELKIYUT_MESHUKLELET_SHERUT number;
    V_TKUFA_MEZAKA_SHERUT          number;
    v_v_ID                         number;
  begin
    if (v_IS_SHEER) then
      v_v_ID := v_SHEER_ID;
    else
      v_v_ID := v_ID;
    end if;
    for r in (select distinct h567.identity_number,
                              h567.job_number,
                              to_number(h567.benefit_percent / 100) as benefit_percent,
                              to_number(h537.percent) / 10000 as percent,
                              h567.from_date_tokef,
                              to_number(h241.sum) as codashim,
                              to_number(h243.sum) as tkufa_mezaka_sherut,
                              to_number(h240.code) as is_z_maanak,
                              to_number(h24.sum) / 10000000 as achuz_gil_60,
                              
                              (select min(h2567.from_date_tokef)
                                 from ld_hilan_567 h2567
                                where h2567.identity_number =
                                      h567.identity_number
                                  and h2567.job_number = h567.job_number) as date_start_zakaut,
                              (select max(h2567.from_date_tokef)
                                 from ld_hilan_567 h2567
                                where h2567.identity_number =
                                      h567.identity_number
                                  and h2567.job_number = h567.job_number) as date_start_zkt_HAARAHAT_SHERUT
              
                from ld_hilan_567 h567
                left join ld_hilan_527 h240
                  on h240.identity_number = h567.identity_number
                 and h240.job_number = h567.job_number
                 and h240.semel = 242
                left join ld_hilan_527 h241
                  on h241.identity_number = h567.identity_number
                 and h241.job_number = h567.job_number
                 and h241.semel = 241
                 and h241.to_date =
                     (select max(Hh241.To_Date)
                        from ld_hilan_527 Hh241
                       where Hh241.semel = 241
                         and hh241.identity_number = h567.identity_number
                         and hh241.job_number = h567.job_number)
                left join ld_hilan_527 h243
                  on h243.identity_number = h567.identity_number
                 and h243.job_number = h567.job_number
                 and h243.semel = 243
                left join ld_hilan_527 h24
                  on h24.identity_number = h567.identity_number
                 and h24.job_number = h567.job_number
                 and h24.semel = 24
                left join ld_hilan_537 h537
                  on h537.identity_number = h567.identity_number
                 and h537.job_number = h567.job_number
                 and h537.to_date like ('%9999999%')
              
               where h567.identity_number = v_v_ID
                 and h567.job_number = v_job_number
                 and h567.from_date =
                     (select max(hh567.from_date)
                        from ld_hilan_567 hh567
                       where hh567.identity_number = h567.identity_number
                         and hh567.job_number = h567.job_number)
                 and h567.to_date_tokef like ('%9999999%')
              
              ) loop
    
      v_odef_sherut_chodashim := trunc(r.codashim / 100);
    
      v_odef_sherut_shanim := v_odef_sherut_chodashim / 12;
      v_odef_sherut_yamim  := MOD((r.codashim / 100), 1) * 30.44;
    
      if (v_code_satate = 41) then
        --הארכת שירות יש לקחת את הערך המקסימלי
        v_date_start_zakahut := to_date(r.date_start_zkt_haarahat_sherut,
                                        'DDMMYYYY');
      else
        v_date_start_zakahut := to_date(r.date_start_zakaut, 'DDMMYYYY');
      end if;
      -- v_date_start_zakahut := to_date('0' || substr(r.from_date_tokef, 1, 7), 'DDMMYYYY');
    
      --       substr(h537.office, 1, 3)
    
      /* V_CHELKIYUT_MESHUKLELET_SHERUT := r.partiality / 1000;
      if (V_CHELKIYUT_MESHUKLELET_SHERUT > 70) then
        V_CHELKIYUT_MESHUKLELET_SHERUT := 70;
      end if;*/
      V_TKUFA_MEZAKA_SHERUT := r.tkufa_mezaka_sherut / 100;
      if (v_code_satate = 43) then
        --43- תום זכאות ליתום לא אמור לסגור את הזכאות
      
        insert into netuney_tik_mechushavim n
          (code_department,
           n.seq_netuney_tik_mechushavim,
           n.seq_bakasha,
           n.date_start_zakaut,
           n.achuz_kizba_sofi,
           n.achuz_kizba_kafuf_chelkiyut,
           n.CHELKIYUT_MESHUKLELET_SHERUT,
           n.TKUFA_MEZAKA_SHERUT,
           n.CODE_GROUP_PRISHA,
           n.IS_ZAKAI_LMAANAK,
           n.CHELKIYUT_SOFIT,
           n.ACHUZ_KIZBA_GIL_60,
           n.IS_HACHLATA_SOFIT,
           n.ODEF_SHERUT_SHANIM,
           n.ODEF_SHERUT_CHODASHIM,
           n.ODEF_SHERUT_YAMIM,
           n.ahuz_kizb_achry_hagdl_kaf_chel)
        values
          (1,
           netuney_tik_mechushavim_seq.nextval,
           v_seq_Another_bakasha,
           v_date_start_zakahut,
           to_number(r.Benefit_Percent),
           to_number(r.Benefit_Percent),
           to_number(r.percent),
           V_TKUFA_MEZAKA_SHERUT,
           v_CODE_GROUP_PRISHA,
           r.is_z_maanak,
           to_number(r.percent),
           r.achuz_gil_60,
           1,
           v_odef_sherut_shanim,
           v_odef_sherut_chodashim,
           v_odef_sherut_yamim,
           to_number(r.Benefit_Percent)) log errors into err_netuney_tik_mechushavim
          (v_ora_err_tag$) reject limit unlimited;
      
        insert into netuney_tik_mechushavim n
          (code_department,
           n.seq_netuney_tik_mechushavim,
           n.seq_bakasha,
           n.date_start_zakaut,
           n.achuz_kizba_sofi,
           n.achuz_kizba_kafuf_chelkiyut,
           n.CHELKIYUT_MESHUKLELET_SHERUT,
           n.TKUFA_MEZAKA_SHERUT,
           n.CODE_GROUP_PRISHA,
           n.IS_ZAKAI_LMAANAK,
           n.CHELKIYUT_SOFIT,
           n.ACHUZ_KIZBA_GIL_60,
           n.IS_HACHLATA_SOFIT,
           n.ODEF_SHERUT_SHANIM,
           n.ODEF_SHERUT_CHODASHIM,
           n.ODEF_SHERUT_YAMIM,
           n.ahuz_kizb_achry_hagdl_kaf_chel)
        values
          (2,
           netuney_tik_mechushavim_seq.nextval,
           v_seq_Another_bakasha,
           v_date_start_zakahut,
           --r.achuz_kizba,
           to_number(r.Benefit_Percent),
           to_number(r.Benefit_Percent),
           --V_CHELKIYUT_MESHUKLELET_SHERUT,
           to_number(r.percent),
           V_TKUFA_MEZAKA_SHERUT,
           v_CODE_GROUP_PRISHA,
           r.is_z_maanak,
           to_number(r.percent),
           r.achuz_gil_60,
           1,
           v_odef_sherut_shanim,
           v_odef_sherut_chodashim,
           v_odef_sherut_yamim,
           to_number(r.Benefit_Percent)) log errors into err_netuney_tik_mechushavim
          (v_ora_err_tag$) reject limit unlimited;
      
      else
        insert into netuney_tik_mechushavim n
          (code_department,
           n.seq_netuney_tik_mechushavim,
           n.seq_bakasha,
           n.date_start_zakaut,
           n.achuz_kizba_sofi,
           n.achuz_kizba_kafuf_chelkiyut,
           n.CHELKIYUT_MESHUKLELET_SHERUT,
           n.TKUFA_MEZAKA_SHERUT,
           n.CODE_GROUP_PRISHA,
           n.IS_ZAKAI_LMAANAK,
           n.CHELKIYUT_SOFIT,
           n.ACHUZ_KIZBA_GIL_60,
           n.IS_HACHLATA_SOFIT,
           n.ODEF_SHERUT_SHANIM,
           n.ODEF_SHERUT_CHODASHIM,
           n.ODEF_SHERUT_YAMIM,
           n.DATE_END_ZAKAUT,
           n.ahuz_kizb_achry_hagdl_kaf_chel)
        values
          (1,
           netuney_tik_mechushavim_seq.nextval,
           v_seq_Another_bakasha,
           v_date_start_zakahut,
           to_number(r.Benefit_Percent),
           to_number(r.Benefit_Percent),
           to_number(r.percent),
           V_TKUFA_MEZAKA_SHERUT,
           v_CODE_GROUP_PRISHA,
           r.is_z_maanak,
           to_number(r.percent),
           r.achuz_gil_60,
           1,
           v_odef_sherut_shanim,
           v_odef_sherut_chodashim,
           v_odef_sherut_yamim,
           v_date_end_zakaut,
           to_number(r.Benefit_Percent)) log errors into err_netuney_tik_mechushavim
          (v_ora_err_tag$) reject limit unlimited;
      
        insert into netuney_tik_mechushavim n
          (code_department,
           n.seq_netuney_tik_mechushavim,
           n.seq_bakasha,
           n.date_start_zakaut,
           n.achuz_kizba_sofi,
           n.achuz_kizba_kafuf_chelkiyut,
           n.CHELKIYUT_MESHUKLELET_SHERUT,
           n.TKUFA_MEZAKA_SHERUT,
           n.CODE_GROUP_PRISHA,
           n.IS_ZAKAI_LMAANAK,
           n.CHELKIYUT_SOFIT,
           n.ACHUZ_KIZBA_GIL_60,
           n.IS_HACHLATA_SOFIT,
           n.ODEF_SHERUT_SHANIM,
           n.ODEF_SHERUT_CHODASHIM,
           n.ODEF_SHERUT_YAMIM,
           n.DATE_END_ZAKAUT,
           n.ahuz_kizb_achry_hagdl_kaf_chel)
        values
          (2,
           netuney_tik_mechushavim_seq.nextval,
           v_seq_Another_bakasha,
           v_date_start_zakahut,
           --r.achuz_kizba,
           to_number(r.Benefit_Percent),
           to_number(r.Benefit_Percent),
           --V_CHELKIYUT_MESHUKLELET_SHERUT,
           to_number(r.percent),
           V_TKUFA_MEZAKA_SHERUT,
           v_CODE_GROUP_PRISHA,
           r.is_z_maanak,
           to_number(r.percent),
           r.achuz_gil_60,
           1,
           v_odef_sherut_shanim,
           v_odef_sherut_chodashim,
           v_odef_sherut_yamim,
           v_date_end_zakaut,
           to_number(r.Benefit_Percent)) log errors into err_netuney_tik_mechushavim
          (v_ora_err_tag$) reject limit unlimited;
      end if;
    
    end loop;
  end;
  ------------------------------------------
  procedure update_hafsakat_tashlum(v_is_sheer boolean) is
    v_VID number;
  begin
    --למקרה שהפסקת טיפול לשאר יש לעדכן את הID של השאר
    if (v_is_sheer = true) then
      v_VID := v_SHEER_ID;
    else
      v_VID := v_ID;
    end if;
    for r in (select distinct h221.identity_number,
                              h221.job_number,
                              h221.from_date_tokef,
                              h221.code_state,
                              h312.value as seif_prisha
                from ld_hilan_221 h221
                left join ld_hilan_312 h312
                  on h312.identity_number = h221.identity_number
                 and h312.job_number = h221.job_number
                 and h312.variable_type = 102
               where h221.identity_number = v_VID --V_ID
                 and h221.job_number = v_job_number
                 and h221.code_state > 40
              --                 and h221.code_state not in (43,44)
               order by to_date(h221.from_date_tokef, 'ddmmyyyy') asc) loop
      if (r.code_state = 41) then
        --הארכת שירות
        V_IS_HAARACHAT_SHERUT := true;
      end if;
    
      v_date_end_zakaut := to_date(r.from_date_tokef, 'ddmmyyyy');
    
      Create_Another_Bakasha(19,
                             to_date(r.from_date_tokef, 'ddmmyyyy'),
                             to_number(r.code_state),
                             v_is_sheer,
                             null);
    
      set_CODE_GROUP_PRISHA(r. seif_prisha);
    
      update_netuneyTik2HafsakatTslm(r.code_state, v_is_sheer);
      if v_is_sheer then
        --UPDATE TO_DATE IN BNEY_MISPACHA 
      
        UPDATE BNEY_MISHPACHA bm
           SET bm.To_Date_Sium_Zakaut = to_date(r.from_date_tokef,
                                                'ddmmyyyy')
         WHERE bm.mispar_zehut_ben_mishpacha = v_SHEER_ID;
      end if;
    
    end loop;
  end;

