  procedure update_participation_l_guf is
  
    v_is_heskem_yachid    number;
    v_is_mevutach_beguf   number;
    v_seq_ezor_ovdim      number;
    V_percent_participate number;
    V_SUM_participate     number;
  begin
  
    for r in (select distinct p.date_start,
                              p.pension_without_taxes,
                              p.code_guf
                from ld_participation P
               where p.identity_number = v_id) loop
    
      v_seq_ezor_ovdim := nvl(r.code_guf, 999);
      /*    for r2 in (select distinct p.Percent_Participate, p.achuz_guf_final
                 from participation p
                where p.seq_bakasha = v_seq_bakasha
                  and p.code_participation = 2
                  and p.Seq_Guf = v_seq_ezor_ovdim) loop
      ComparingValues(r2.Percent_Participate,
                      V_percent_participate,
                      'participation',
                      'Percent_Participate');
      ComparingValues(r2.achuz_guf_final,
                      V_percent_participate,
                      'participation',
                      'Percent_Participate');*/
    
      merge into participation p1
      using dual
      on (p1.seq_bakasha = v_seq_bakasha and p1.seq_guf = v_seq_ezor_ovdim)
      when matched then
        update
           set date_payment       = r.date_start,
               kizba_chodshit     = to_number(r.pension_without_taxes),
               code_participation = 1
        
      
      when not matched then
        insert
          (SEQ_BAKASHA,
           seq_participation,
           code_participation,
           seq_guf,
           date_payment,
           kizba_chodshit)
        values
          (v_seq_bakasha,
           participation_seq.nextval,
           1,
           v_seq_ezor_ovdim,
           r.date_start,
           to_number(r.pension_without_taxes)) log errors into err_participation
          (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  
  end;

  -----------------------
  procedure update_Sum_BM_N_T_MCHUSHAVIM is
  begin
    for r in (select bm.Seq_Porshim,
                     b.seq_bakasha,
                     b.mispar_zehut,
                     SUM(nvl(bm.Achuz_Kizba, 0)) as sumkizba
                FROM bney_mishpacha bm
                left join v_bakasha_by_zheut b
                  on b.porshim_seq = bm.seq_porshim
                left join netuney_tik_mechushavim nt
                  on nt.Seq_Bakasha = b.seq_bakasha
                 and nt.code_department = 2
                 and nt.mispar_misra = 0
               where --b.code_sug_bakasha = 1
              --             and nt.code_group_prisha = 4
              --                 and 
               bm.code_relative >= 1
           and bm.code_relative < 99
              -- and b.mispar_zehut = V_ID
           and b.seq_bakasha = v_seq_bakasha
               GROUP BY bm.seq_porshim, b.seq_bakasha, b.mispar_zehut) loop
    
      update netuney_tik_mechushavim ntm
         set ntm.Achuz_Kizba_Sofi = r.sumkizba
       where ntm.seq_bakasha = r.seq_bakasha;
    
    end loop;
  end;
