  procedure update_ADDRESS_2_Ben_Mishpacha(V_Seq_Bney_Mishpacha number) is
    v_code_address number;
    v_indexAdress  number;
    v_address      varchar2(100);
    v_house        number;
    v_apartment    number;
  begin
  
    delete from address t
     where t.seq_bakasha = v_seq_bakasha
        or t.Seq_Bney_Mishpacha = V_Seq_Bney_Mishpacha;
  
    for r in (select distinct h218.identity_number,
                              h218.code_c_ity,
                              convert_low_hebrew_to_ascii(h218.street) as address,
                              h218.house,
                              /*case
                                when trim(TRANSLATE(h218.house,
                                                    '0123456789-,.',
                                                    ' ')) is null then
                                 h218.house
                                else
                                 null
                              end as house,*/
                              h218.apartment,
                              /*case
                                when trim(TRANSLATE(h218.apartment,
                                                    '0123456789-,.',
                                                    ' ')) is null then
                                 h218.apartment
                                else
                                 null
                              end as APARTMENT,*/
                              -- h218.house as house,
                              --h218.apartment as apartment,
                              h218.from_date,
                              h218.zone
                from ld_hilan_218 h218
               where h218.identity_number = v_SHEER_ID
               order by to_date(h218.from_date, 'ddmmyyyy') asc) loop
    
      insert into address aa
        (seq_bakasha,
         seq_address,
         Seq_Bney_Mishpacha,
         street,
         code_city,
         
         code_address,
         MIKUD,
         CODE_USER_UPDATE,
         date_update
         /*,HOUSE,
         APARTMENT*/)
      values
        (v_seq_bakasha,
         address_seq.nextval,
         V_Seq_Bney_Mishpacha,
         trim(r.address) || ' ' || trim(r.HOUSE) || ' ' ||
         decode(trim(r.APARTMENT), '', '', '/' || trim(r.APARTMENT)),
         v_code_address,
         
         2,
         r.zone,
         1,
         to_date(r.from_date, 'ddmmyyyy')
         /*,r.HOUSE,
         r.APARTMENT*/) log errors into err_address
        (v_ora_err_tag$) reject limit unlimited;
    end loop;
  end;
  ----------------------------------

  procedure update_ADDRESS_2_NEW_BAKASHOT is
  begin
    dbms_output.enable(99999999999999999999999999999999999999999999999999999999999999999999999);
    for r in (select distinct b."SEQ_PRISHA",
                              b.porshim_seq,
                              b.SEQ_BAKASHA,
                              b.MISPAR_ZEHUT
                from mgl_log_hasava l
                join v_Bakasha_By_Zheut b
                  on b.MISPAR_ZEHUT = l.mispar_zehut
                 and b.code_sug_bakasha = 1
               where l.code_hasava = 12
                 and rownum < 11
              
              ) loop
      v_id := r.MISPAR_ZEHUT;
      dbms_output.put_line(v_id);
      v_seq_bakasha := r.SEQ_BAKASHA;
    
      v_seq_prisha  := r.SEQ_PRISHA;
      v_porshim_seq := r.porshim_seq;
      V_code_makor  := 1;
    
      update_ADDRESS;
    end loop;
    commit;
  end;

  ---------------------------------------------
  procedure update_ADDRESS is
    v_code_address number;
    v_indexAdress  number;
    v_address      varchar2(100);
  begin
  
    delete from address t
     where t.seq_bakasha = v_seq_bakasha
        or t.seq_poresh = v_porshim_seq;
  
    --TODO: לולאה שרצה על בקשות שינוי כתובת ומוחקת אותם
    --לא מןחקת הפסקת תשלום כי יש מצב שנוצר גם לפורש וגם לשאר
    --לבדוק מול רבקי מתי למוק בקשות של שאר ומתי של פורש
    for r in (select distinct b.seq_bakasha
                from v_bakasha_by_zheut b
               where b.porshim_seq = v_porshim_seq
                    --b.seq_prisha = v_seq_prisha
                 and b.code_sug_bakasha = 21) loop
      v_delete_bakasha := pk_prm_utils.delete_bakasha_WITHOUT_COMMIT(r.seq_bakasha);
    end loop;
    v_indexAdress := 0;
    for r in (select distinct h218.identity_number,
                              h218.code_c_ity,
                              convert_low_hebrew_to_ascii(h218.address) as address,
                              h218.from_date,
                              h218.zone
                from ld_hilan_218 h218
               where h218.identity_number = v_id
               order by to_date(h218.from_date, 'ddmmyyyy') asc) loop
      v_indexAdress  := v_indexAdress + 1;
      v_code_address := r.code_c_ity;
      if (nvl(v_address, ' ')) not like (r.address) then
        if (v_indexAdress = 1) then
          --connect first adress to the bakasha
          insert into address aa
            (seq_bakasha,
             seq_address,
             seq_poresh,
             street,
             code_city,
             
             code_address,
             MIKUD,
             CODE_USER_UPDATE,
             date_update)
          values
            (v_seq_bakasha,
             address_seq.nextval,
             v_porshim_seq,
             r.address,
             v_code_address,
             
             2,
             r.zone,
             1,
             to_date(r.from_date, 'ddmmyyyy')) log errors into err_address
            (v_ora_err_tag$) reject limit unlimited;
        else
        
          Create_Another_Bakasha(21,
                                 to_date(r.from_date, 'ddmmyyyy'),
                                 0,
                                 null,
                                 null);
          insert into address
            (seq_bakasha,
             seq_address,
             seq_poresh,
             street,
             code_city,
             code_address,
             MIKUD,
             CODE_USER_UPDATE,
             date_update)
          values
            (v_seq_Another_bakasha,
             address_seq.nextval,
             v_porshim_seq,
             r.address,
             v_code_address,
             2,
             r.zone,
             1,
             to_date(r.from_date, 'ddmmyyyy')) log errors into err_address
            (v_ora_err_tag$) reject limit unlimited;
        end if;
        v_address := r.address;
      end if;
    end loop;
  end;

