  procedure Create_Another_Bakasha(v_sug_bakasha          number,
                                   v_from_date            date,
                                   v_code_state           number,
                                   v_IS_SHEER             boolean,
                                   v_code_bakasha_detail_ number) is
    v_delete_bakasha varchar2(1000);
  
  begin
    v_seq_Another_bakasha := null;
    v_seq_Another_bakasha := bakasha_seq.nextval;
  
    if v_sug_bakasha = 19 then
      --הפסקת תשלום
    
      set_code_bakasha_detail(v_code_state, v_IS_SHEER);
    
      --TODO: לולאה שרצה על הבקשות הללו ומוחקת אותם
      --לא מןחקת הפסקת תשלום כי יש מצב שנוצר גם לפורש וגם לשאר
      --לבדוק מול רבקי מתי למוק בקשות של שאר ומתי של פורש
    
      for r in (select distinct b.seq_bakasha
                  from bakasha b
                 where b.seq_prisha = v_seq_prisha
                   and b.code_sug_bakasha = v_sug_bakasha
                   and b.CODE_BAKASHA_DETAIL = v_code_bakasha_detail) loop
        v_delete_bakasha := pk_prm_utils.delete_bakasha_WITHOUT_COMMIT(r.seq_bakasha);
      end loop;
    
      insert into bakasha
        (seq_bakasha,
         seq_prisha,
         code_sug_bakasha,
         code_source,
         date_bakasha,
         FROM_DATE,
         DATE_UPDATE,
         CODE_BAKASHA_DETAIL)
      values
        (v_seq_Another_bakasha,
         v_seq_prisha,
         v_sug_bakasha,
         
         V_code_makor,
         v_from_date,
         v_from_date,
         v_from_date,
         v_code_bakasha_detail) log errors into err_bakasha
        (v_ora_err_tag$) reject limit unlimited;
    
    else
    
      insert into bakasha
        (seq_bakasha,
         seq_prisha,
         code_sug_bakasha,
         code_source,
         
         DATE_UPDATE,
         date_bakasha,
         CODE_BAKASHA_DETAIL)
      values
        (v_seq_Another_bakasha,
         v_seq_prisha,
         v_sug_bakasha,
         
         V_code_makor,
         
         v_from_date,
         v_from_date,
         v_code_bakasha_detail_) log errors into err_bakasha
        (v_ora_err_tag$) reject limit unlimited;
    end if;
    pk_prm_utils.insert_action_log_row(98,
                                       v_from_date,
                                       1,
                                       null,
                                       null,
                                       null,
                                       null,
                                       null,
                                       v_seq_Another_bakasha,
                                       null);
    pk_prm_utils.insert_action_log_row(145,
                                       SYSDATE,
                                       1,
                                       null,
                                       null,
                                       null,
                                       null,
                                       null,
                                       v_seq_Another_bakasha,
                                       null);
  end;
