  function is_RetirementSectionsOnlyOne return boolean is
  
    v_countRtirmentSctions number;
  begin
    v_is_RetirementSectionsMoreOne := false;
    select count(distinct m10.retirement_section)
      into v_countRtirmentSctions
      from ld_mlm_10 m10
     where m10.is_erased = 0
       and m10.retirement_section not in ('000', '126', '128')
       and m10.identity_number = v_id;
    if (v_countRtirmentSctions > 1) then
      v_is_RetirementSectionsMoreOne := true;
      return false;
    else
      return true;
    end if;
  end;
  -----------------------------------------------------------
  function update_bakasha(p_code_sug_bakasha number) return boolean is
    bakasha_row   err_bakasha%rowtype;
    v_sug_bakasha number;
  begin
  
    v_sug_bakasha := p_code_sug_bakasha;
    for r in (select distinct t.identity_number,
                              
                              t.date_start
                from Ld_Participation t
               where t.identity_number = v_id) loop
      --      v_sug_bakasha                := 1;
      bakasha_row.date_bakasha     := r.date_start - INTERVAL '1' DAY;
      bakasha_row.code_sug_bakasha := v_sug_bakasha;
      --ידני השתתפויות
      bakasha_row.code_source := 7;
      bakasha_row.Seq_Prisha  := v_seq_prisha;
    
      if (v_seq_bakasha is null and v_seq_prisha is not null) then
        set_seq_bakasha;
      end if;
      merge into bakasha
      using dual
      on (bakasha.seq_bakasha = v_seq_bakasha)
      when matched then
        update
           set code_sug_bakasha = bakasha_row.code_sug_bakasha,
               date_bakasha     = bakasha_row.date_bakasha,
               code_source      = bakasha_row.code_source
        
      
      when not matched then
        insert
          (seq_bakasha,
           seq_prisha,
           code_sug_bakasha,
           
           code_source,
           date_bakasha)
        values
          (v_seq_bakasha,
           v_seq_prisha,
           bakasha_row.code_sug_bakasha,
           
           bakasha_row.code_source,
           bakasha_row.date_bakasha) log errors into err_bakasha
          (v_ora_err_tag$) reject limit unlimited;
    
      if pk_load_mimshak.count_rowes('err_bakasha', v_where) > 0 then
        return false;
      else
        return true;
      end if;
    end loop;
    return false;
  end;
  --------------------------------------------------------------------------------------------------------
  function update_prisha return boolean is
    prisha_row err_prisha%rowtype;
  begin
  
    v_seq_prisha          := prisha_seq.nextval;
    prisha_row.seq_poresh := v_porshim_seq;
    v_ezor_ovdim          := 999;
  
    prisha_row.seq_ezor_ovdim := v_ezor_ovdim;
  
    merge into prisha
    using dual
    on (prisha.seq_prisha = v_seq_prisha)
    when matched then
      update
         set --gimla_number   = prisha_row.gimla_number,
             seq_ezor_ovdim = seq_ezor_ovdim
    when not matched then
      insert
        (seq_prisha,
         seq_poresh,
         seq_ezor_ovdim
         --,gimla_number
         )
      values
        (v_seq_prisha,
         v_porshim_seq,
         v_ezor_ovdim
         --,prisha_row.gimla_number
         ) log errors into err_prisha
        (v_ora_err_tag$) reject limit unlimited;
  
    if pk_load_mimshak.count_rowes('err_prisha', v_where) > 0 then
      return false;
    else
      return true;
    end if;
  
  end;
