  function info_about_errors_and_commit(v_do_commit boolean,
                                        P_ErrrMesg  varchar2) return clob is
    v_report       clob := null;
    v_is_do_commit number;
  begin
    --add to the report info about the error tables.
    v_report := get_erorr_from_table('err_porshim');
    v_report := v_report || get_erorr_from_table('err_prisha');
    v_report := v_report || get_erorr_from_table('err_bakasha');
    v_report := v_report || get_erorr_from_table('err_bakasha_regila');
    v_report := v_report ||
                get_erorr_from_table('err_tkufot_avoda_mechushv');
    v_report := v_report || get_erorr_from_table('err_medical_vaada');
    v_report := v_report || get_erorr_from_table('err_apotropus');
    v_report := v_report || get_erorr_from_table('err_bney_mishpacha');
    v_report := v_report || get_erorr_from_table('err_decisions');
    v_report := v_report || get_erorr_from_table('err_participation');
    v_report := v_report ||
                get_erorr_from_table('err_netuney_tik_mechushavim');
    v_report := v_report || get_erorr_from_table('err_hagdala_nimuk');
    v_report := v_report || get_erorr_from_table('err_action_log');
    v_report := v_report || get_erorr_from_table('ERR_HIVUN');
    v_report := v_report || get_erorr_from_table('ERR_MAZAV_MISHPACHTI');
    v_report := v_report || get_erorr_from_table('ERR_VETEK_DETAIL');
    v_report := v_report || get_erorr_from_table('ERR_bank_account');
    v_report := v_report || get_erorr_from_table('err_darga_vederug_tik');
  
    if v_do_commit = false then
      rollback;
      --   --------not (v_is_exist_tkufot_avoda)
      if (v_is_NOT_VALID_ID) then
        v_report := '<h2>' || '********** zeut: ' || v_id || ' **********' ||
                    '<h2/>' || '<h3>' ||
                    'Was not converted .Not Valid id  ' || '<h3/>' ||
                    chr(13) || chr(10) || v_report;
      
        add_row_to_mgl_log_hasava(v_id, 2, 'Not Valid id');
      else
        add_row_to_mgl_log_hasava(v_id, 23, '');
      
      end if;
      commit;
      --   ----------
    elsif v_do_commit = true then
      commit;
      v_report := '<h2>' || '********** zeut: ' || v_id || ' **********' ||
                  '<h2/>' || '<h3>' || 'Converted. ' || '<h3/>' || chr(13) ||
                  chr(10) || v_report;
    end if;
  
    v_is_do_commit := case v_do_commit
                        when true then
                         1
                        else
                         0
                      end;
  
    insert into temp_convert_2_mpm
      (id, is_do_commit)
    values
      (v_id, v_is_do_commit);
  
    return v_report;
  
  end;
  --------------------------------------------------

  function validate_id(sug_zihuy number, v_id number) return boolean is
    type num_arr_type is table of number;
    mask_arr num_arr_type := num_arr_type(1, 2, 1, 2, 1, 2, 1, 2, 1);
    j        number;
    k        number := 0;
  begin
    if sug_zihuy = 2 -- darkon
     then
      return False;
    elsif sug_zihuy = 1 -- mispar zeut
     then
      for i in 1 .. 8 loop
        j := mask_arr(i) *
             to_number(substr(lpad(to_char(v_id), 9, '0'), i, 1));
        k := k + case length(to_char(j))
               when 1 then
                j
               else
                to_number(substr(to_char(j), 1, 1)) +
                to_number(substr(to_char(j), 2, 1))
             end;
      end loop;
      k                 := case mod(k, 10)
                             when 0 then
                              0
                             else
                              10 - mod(k, 10)
                           end;
      v_is_NOT_VALID_ID := False;
      if k <> to_number(substr(lpad(to_char(v_id), 9, '0'), 9, 1)) then
        -- not valid id 
        v_is_NOT_VALID_ID := true;
        /*add_row_to_err_porshim(v_id || '-' || 'not valid id',
        20000,
        'mispar_zehut');*/
        -- add_row_to_mgl_log_hasava(v_id, 2);
        -- dbms_output.put_line('NOT_VALID_ID' || v_id);
        -- raise_application_error(-20000, 'not valid id');
        return False;
      end if;
    end if;
    return true;
  end;
  ------------------------------------

  procedure update_mazav_mishpachti(v_SEQ_BM number) is
    v_code_mazav_mishpachti number;
    v_seq_mazav_mishpachti  number;
    v_from_date             date;
  begin
  
    if (nvl(v_SEQ_BM, 0) > 0) then
      delete from MAZAV_MISHPACHTI mm where SEQ_BNEY_MISHPACHA = v_SEQ_BM;
    else
    
      delete from MAZAV_MISHPACHTI mm where mm.seq_poresh = v_porshim_seq;
    end if;
    for r in (select distinct h205.identity_number,
                              DECODE(h205.status_code,
                                     1,
                                     0,
                                     2,
                                     1,
                                     3,
                                     3,
                                     4,
                                     2,
                                     5,
                                     0,
                                     6,
                                     1,
                                     7,
                                     3,
                                     8,
                                     2) as CODE_MAZAV_MISHPACHTI,
                              h205.status_code,
                              h205.from_date,
                              h205.dummy5 AS TOKEF_DATE
              
                from Ld_Hilan_205 h205
               where h205.identity_number =
                     decode(nvl(v_SEQ_BM, 0), 0, v_id, v_SHEER_ID)) loop
    
      v_code_mazav_mishpachti := r.CODE_MAZAV_MISHPACHTI;
      v_seq_mazav_mishpachti  := MAZAV_MISHPACHTI_seq.nextval;
      if (to_number(r.from_date) > 0) then
        v_from_date := to_date(r.from_date, 'ddmmyyyy');
      end if;
      if (to_number(r.TOKEF_DATE) > 0) then
        v_from_date := to_date('01' || r.TOKEF_DATE, 'ddmmyyyy');
      end if;
      /*      INSERT INTO MAZAV_MISHPACHTI mm
        (mm.seq_mazav_mishpachti,
         mm.seq_poresh,
         mm.code_mazav_mishpachti,
         mm.date_mazav_mishpachti)
      VALUES
        (MAZAV_MISHPACHTI_seq.nextval,
         v_porshim_seq,
         v_code_mazav_mishpachti,
         to_date(r.from_date, 'dd/mm/yyyy'));*/
    
      if (nvl(v_SEQ_BM, 0) > 0) then
      
        merge into MAZAV_MISHPACHTI
        using dual
        on (MAZAV_MISHPACHTI.Seq_Mazav_Mishpachti = v_seq_mazav_mishpachti and SEQ_BNEY_MISHPACHA = v_SEQ_BM)
        when matched then
          update set code_mazav_mishpachti = v_code_mazav_mishpachti
        when not matched then
          insert
            (seq_mazav_mishpachti,
             
             SEQ_BAKASHA,
             code_mazav_mishpachti,
             date_mazav_mishpachti,
             CODE_USER,
             SEQ_BNEY_MISHPACHA)
          values
            (MAZAV_MISHPACHTI_seq.nextval,
             
             v_seq_bakasha,
             v_code_mazav_mishpachti,
             v_from_date,
             1,
             v_SEQ_BM) log errors into err_MAZAV_MISHPACHTI
            (v_ora_err_tag$) reject limit unlimited;
      
      else
      
        merge into MAZAV_MISHPACHTI
        using dual
        on (MAZAV_MISHPACHTI.Seq_Mazav_Mishpachti = v_seq_mazav_mishpachti)
        when matched then
          update set code_mazav_mishpachti = v_code_mazav_mishpachti
        when not matched then
          insert
            (seq_mazav_mishpachti,
             seq_poresh,
             SEQ_BAKASHA,
             code_mazav_mishpachti,
             date_mazav_mishpachti,
             CODE_USER)
          values
            (MAZAV_MISHPACHTI_seq.nextval,
             v_porshim_seq,
             0,
             v_code_mazav_mishpachti,
             v_from_date,
             1) log errors into err_MAZAV_MISHPACHTI
            (v_ora_err_tag$) reject limit unlimited;
      end if;
    
    end loop;
  end;
