  function main return clob is
    v_report_html clob;
  
    v_delete_bakasha varchar2(1000);
  
  begin
  
    execute immediate 'alter session set nls_language= ''american''';
    execute immediate 'alter session set nls_date_language=''english''';
    execute immediate 'alter session set nls_date_format=''dd-mon-yyyy''';
  
    --regular bakashot
  
    for r in (select distinct p.parent_identity_number,
                              p.last_name,
                              p.first_name,
                              p.birth_date,
                              p.date_start,
                              p.gender,
                              p.retirement_section,
                              p.rank,
                              p.rate,
                              p.office,
                              p.seniority,
                              p.perecentage,
                              p.partiality,
                              p.pension,
                              p.guf,
                              p.guf_bank_account,
                              p.code_guf,
                              p.salary,
                              p.is4360,
                              p.salary_with_bh,
                              p.taxes,
                              p.pension_without_taxes,
                              p.is_mas_sachar,
                              p.bigud,
                              p.havraa,
                              p.DUMMY_SALARY,
                              p.avraa_bih,
                              p.bigud_bi,
                              p.identity_number
                from ld_participation p
                left join v_bakasha_last_status b
                  on b.mispar_zehut = p.identity_number
               where b.mispar_zehut is null
                 and p.parent_identity_number = 0 --like ('%אין%')
                 and p.reported_taxes = 3
              /*and not exists
              (select *
                       from mgl_log_hasava l
                      where l.code_hasava in (22, 23)
                        and l.mispar_zehut = p.identity_number)*/
              
              )
    
     loop
      --begin  --exception
    
      --------------
      ResetFields;
      v_is_do_commit := true;
      --v_date_gzira   := r.date_gzira;
      v_id := r.identity_number;
      -- v_ezor_ovdim := convert_seq_ezor_ovdim(r.kd_misrad,
      --                                           TRIM(r.kd_yehida));
      v_ora_err_tag$ := to_char(v_id);
      --|| ' - ' to_char(v_date_gzira, 'dd/mm/yyyy');
      v_where := ' where ora_err_tag$= ''' || v_ora_err_tag$ || '''';
    
      if validate_id(1, r.identity_number) = false then
        V_sug_zihuy := 2;
      else
        V_sug_zihuy := 1;
      end if;
    
      if
      --must tables
       update_poresh = false then
      
        v_is_do_commit := false;
        goto endloop1;
      end if;
      v_ezor_ovdim := 999;
      if update_prisha = false or update_bakasha(8) = false or
         update_bakasha_regila = false then
        v_is_do_commit := false;
        goto endloop1;
      end if;
      --add row log succses
      add_row_to_mgl_log_hasava(v_id, 22, '');
    
      update_netuney_tik_mechushavim; --V
      update_participation_l_guf;
    
      merge_actions_log;
      update_actions_log;
    
      --I'M inserting
      -- commit;
      <<endloop1>>
      v_report_html := v_report_html ||
                      
                       info_about_errors_and_commit(v_is_do_commit, '');
    end loop;
  
    --UPDATE_PTIRA_DATE;
    commit;
    return v_report_html;
  
  end;
