  v_date_ptira                   date;
  v_is_do_commit                 boolean;
  v_SHEER_ID                     number;
  V_from_COpy_BAKAHSHA           number;
  V_sug_zihuy                    number;
  v_is_HOZE_BHIRIM               boolean;
