  v_seq_TEMP_PORSHIM_HILAN  number;
  v_sum_achuz_gimla         number;
  v_SEQ_bakashat_syum_tipul number;
  ----------------------------------------------

  procedure set_global_fields(sug_bakasha            number,
                              v_is_from_zakai_maanak boolean) is
    sugeyBakasha        num_nt;
    count_PRISHOR_MPM   number;
    count_PRISHOR_HILAN number;
  begin
  
    begin
      select p.porshim_seq
        into v_porshim_seq
        from poresh p
       where p.mispar_zehut = v_id;
    exception
      when no_data_found then
        v_porshim_seq := null;
    end;
  
    begin
    
      /*   select t.Seq_Ezor_Ovdim, t.code_makor
       into v_ezor_ovdim, V_code_makor
       from CODE_EZOR_OVDIM t
      where t.code_misrad_maskret = v_misrad_maskoret
           
        and ROWNUM = 1;*/
    
      select b.seq_ezor_ovdim, e.Code_Makor
        into v_ezor_ovdim, V_code_makor
        from V_BAKASHA_BY_ZHEUT b
        left join code_ezor_ovdim e
          on e.seq_ezor_ovdim = b.seq_ezor_ovdim
       where b.mispar_zehut = v_ID
         and e.code_misrad_maskret = v_misrad_maskoret
         and rownum = 1;
    exception
      when no_data_found then
        v_ezor_ovdim := convert_seq_ezor_ovdim(v_misrad_maskoret,
                                               v_ezor_ovdim_HILAN);
        if (v_ezor_ovdim = 999) then
          --במקרה שלא נמצא , יש לאפס בכדי שלא יהיה פשלות ה MERGE
          v_ezor_ovdim := null;
        end if;
        V_code_makor := (case sug_bakasha
                          when 23 then
                           7
                          else
                           1
                        end);
      
    end;
  
    begin
    
      select p.seq_prisha
        into v_seq_prisha
        from prisha p
       where p.seq_poresh = v_porshim_seq
         and p.seq_ezor_ovdim = v_ezor_ovdim
         and ROWNUM = 1;
    exception
      when no_data_found then
        v_seq_prisha := null;
      
    end;
  
    if (v_seq_prisha IS NULL) then
    
      begin
        select count(distinct b.seq_prisha)
          into count_PRISHOR_MPM
          from v_Bakasha_BY_ZHEUT b
         where b.mispar_zehut = V_ID;
      exception
      
        when no_data_found then
          count_PRISHOR_MPM := null;
      end;
    
      begin
        select count(substr(h537.office, 1, 3))
          into count_PRISHOR_HILAN
        
          from ld_hilan_537 h537
         where h537.identity_number = v_id
              --************
              --ורק פרישות שהם לא של שארים 
           and exists
         (select *
                  from ld_hilan_312 h312
                 where h312.identity_number = h537.identity_number
                   and h312.job_number = h537.job_number
                   and h312.variable_type = 102
                   and to_number(h312.value) not in
                       (126,
                        128,
                        226,
                        228,
                        326,
                        426,
                        526,
                        528,
                        428,
                        328,
                        628));
      exception
      
        when no_data_found then
          count_PRISHOR_HILAN := null;
      end;
      if nvl(count_PRISHOR_MPM, 0) = 1 and
        --nvl(count_PRISHOR_HILAN, 0) in (0, 1)   התנאי להסבת השארים ...הוספתי את ה0  בשביל 
         nvl(count_PRISHOR_HILAN, 0) in (0, 1) then
      
        begin
        
          select p.seq_prisha, p.seq_ezor_ovdim
            into v_seq_prisha, v_ezor_ovdim
            from prisha p
           where p.seq_poresh = v_porshim_seq
             and rownum = 1;
        exception
          when no_data_found then
            v_seq_prisha := null;
        end;
      
      end if;
    
    end if;
  
    if (sug_bakasha = 1 and not (v_is_from_zakai_maanak)) then
      sugeyBakasha := num_nt(1, 3, 5, 7);
    else
      --בשביל עדכון שדה זכאי למענק , יש לעדכן רק בקשות מסוג זה
      if (sug_bakasha = 1 and (v_is_from_zakai_maanak)) then
        sugeyBakasha := num_nt(1, 3, 5);
      else
        --בקשה מסוג שארים למשל..
        sugeyBakasha := num_nt(sug_bakasha);
      end if;
    end if;
  
    v_seq_MinBakasha := null;
    begin
      select min(b.seq_bakasha)
        into v_seq_MinBakasha
        from V_BAKASHA_BY_ZHEUT b
       where b.seq_ezor_ovdim = v_ezor_ovdim
         and b.mispar_zehut = v_id
         and b.code_sug_bakasha in (SELECT * FROM TABLE(sugeyBakasha));
    exception
      when no_data_found then
        v_seq_MinBakasha := null;
    end;
  
    begin
      select max(b.seq_bakasha)
        into v_seq_Bakasha
        from v_Bakasha_BY_ZHEUT b
       where b.seq_ezor_ovdim = v_ezor_ovdim
         and b.mispar_zehut = v_id
         and b.code_sug_bakasha in (SELECT * FROM TABLE(sugeyBakasha))
         and exists (select a.seq_bakasha
                from action_log a
               where a.seq_bakasha = b.seq_bakasha
                 and a.code_action = 98)
         and not exists (select a.seq_bakasha
                from action_log a
               where a.seq_bakasha = b.seq_bakasha
                 and a.code_action = 17);
    exception
      when no_data_found then
        v_seq_Bakasha := null;
    end;
  
    if v_seq_Bakasha is null then
      begin
        --לוקחת בקשה עם הסבת נתונים במקרה שאין סיום טיפול
        select max(b.seq_bakasha)
          into v_seq_Bakasha
          from V_BAKASHA_by_ZHEUT b
         where b.seq_ezor_ovdim = v_ezor_ovdim
           and b.mispar_zehut = v_id
           and b.code_sug_bakasha in (SELECT * FROM TABLE(sugeyBakasha))
           and exists (select a.seq_bakasha
                  from action_log a
                 where a.seq_bakasha = b.seq_bakasha
                   and a.code_action = 99)
           and not exists (select a.seq_bakasha
                  from action_log a
                 where a.seq_bakasha = b.seq_bakasha
                   and a.code_action = 17);
      exception
        when no_data_found then
          v_seq_Bakasha := null;
      end;
    
    end if;
    ----------------------עדכון בקשה רגילה בכדי לעדכן גם את נתוני תיק מחושבים של הבקשה הרגילה במקרה ואין שם ערכים--------  
    begin
      select max(b.seq_bakasha)
        into v_seq_bakasha_REGILA
        from v_Bakasha_BY_ZHEUT b
       where b.seq_ezor_ovdim = v_ezor_ovdim
         and b.mispar_zehut = v_id
         and b.code_sug_bakasha = 1
         and exists (select a.seq_bakasha
                from action_log a
               where a.seq_bakasha = b.seq_bakasha
                 and a.code_action in (99, 98))
         and not exists (select a.seq_bakasha
                from action_log a
               where a.seq_bakasha = b.seq_bakasha
                 and a.code_action = 17);
    exception
      when no_data_found then
        --??
        v_seq_bakasha_REGILA := null;
    end;
  
    begin
      select distinct b.date_bakasha, b.code_seif_prisha
        into v_date_bakasha, v_CODE_SEIF_PRISHA
        from v_Bakasha_Last_Status b
       where b.seq_bakasha = v_seq_Bakasha
         and rownum = 1;
    exception
      when no_data_found then
        v_date_bakasha := null;
    end;
  
  end;

