  procedure DELETE_BNEY_MISHPACHA is
    --מחיקת בני משפחה שזהותם חופפת לזהות הפורש
  begin
    --dbms_output.enable(999999999);
    for r in (select distinct bm.Seq_Bney_Mishpacha,
                              b.mispar_zehut,
                              bm.mispar_zehut_ben_mishpacha
                from bney_mishpacha bm
                left join v_bakasha_BY_ZHEUT b
                  on b.porshim_seq = bm.Seq_Porshim
               where bm.mispar_zehut_ben_mishpacha = b.mispar_zehut) loop
      delete from mazav_mishpachti mm
       where mm.Seq_Bney_Mishpacha = r.Seq_Bney_Mishpacha;
      delete from address a
       where a.seq_bney_mishpacha = r.Seq_Bney_Mishpacha;
      -----------------
      delete from bank_account ba
       where ba.seq_bney_mishpacha = r.seq_bney_mishpacha;
      -------------------------------
      delete from bney_mishpacha bm
       where bm.Seq_Bney_Mishpacha = r.seq_bney_mishpacha;
      -- dbms_output.put_line('DELETE mispar_zehut_ben_mishpacha ' ||
    --                     r.mispar_zehut_ben_mishpacha);
    end loop;
  
  end;

