  procedure delete_code_action_132 is
  begin
    --מחיקת סטטוס ממתין לגיל פרישה תקנוני
    for r in (select b.seq_bakasha
                from v_bakasha_last_status b
                left join netuney_tik_mechushavim nt
                  on nt.Seq_Bakasha = b.seq_bakasha
                 and nt.code_department = 2
               where b.code_action = 132
                 and nt.date_start_zakaut < to_date('07042019', 'ddmmyyyy')
                 and b.code_sug_bakasha = 1) loop
    
      delete from action_log al
       where al.seq_bakasha = r.seq_bakasha
         and al.code_action = 132;
    end loop;
  end;
  ------------------------------
  procedure UPDATE_SUG_BAKASHA_7_TO_23 is
  
    --עדכון בקשת השתתפות מגוף לסוג בקשה השתתפות מגוף שארים  
  begin
  
    for r in (select distinct b."DATE_BAKASHA",
                              (SELECT max(bb."SEQ_BAKASHA")
                                 from v_bakasha_by_zheut bb
                                where bb.mispar_zehut = b.mispar_zehut
                                  and bb."CODE_SUG_BAKASHA" = 7
                                  and not exists
                                (select *
                                         from action_log al
                                        where al.seq_bakasha =
                                              bb."SEQ_BAKASHA"
                                          and al.code_action = 17)) as SEQ_BAKASHA,
                              br.Code_Seif_Prisha,
                              b.mispar_zehut,
                              br.taarich_prisha,
                              b.taarich_ptira,
                              b.taarich_ptira - br.taarich_prisha
                from v_bakasha_by_zheut b
                join poresh p
                  on p.mispar_zehut = b.mispar_zehut
                join bakasha_regila br
                  on br.Seq_Bakasha = b."SEQ_BAKASHA"
               where b."DATE_BAKASHA" > b.taarich_ptira
                 and b.taarich_ptira is not null
                 and b.taarich_ptira - br.taarich_prisha >= 30
                 and b."CODE_SUG_BAKASHA" = 7
                 and br.Code_Seif_Prisha <> 126
                 and not exists
               (select *
                        from action_log al
                       where al.seq_bakasha = b."SEQ_BAKASHA"
                         and al.code_action = 17)) loop
    
      update BAKASHA b
         set b.code_sug_bakasha = 23
       where b.Seq_Bakasha = r.SEQ_BAKASHA
         and b.code_sug_bakasha = 7;
    
    end loop;
    commit;
  end;
