  -------------------------------
  function is_exist_Code_derug(p_KD_DERUG number) return boolean is
    v_is_exist_Code_derug boolean;
  begin
    if (nvl(p_KD_DERUG, 0) > 0) then
      v_is_exist_Code_derug := false;
      for r in (select t.code_derug
                  from CODE_DERUG t
                 where t.code_derug = p_KD_DERUG) loop
        v_is_exist_Code_derug := true;
        return true;
      end loop;
    end if;
    return false;
  end;
  ---------------------------------

  function CONVERT_CODE_DERUG(v_code_derug_hilan number,
                              v_code_darga_hilan varchar) return number is
    v_code_derug number;
  begin
    begin
    
      select dh.derug_malam
        into v_code_derug
        from CODE_DERUG_DARGA_HILAN dh
       where dh.derug_hilan = v_code_derug_hilan
         and dh.darga_hilan = v_code_darga_hilan
         and ROWNUM = 1;
    exception
      when no_data_found then
        v_code_derug := null;
    end;
    return v_code_derug;
  end;
  -------------------------

  procedure update_DARGA_VEDERUG_TIK is
    v_code_derug number;
  begin
  
    delete from Darga_Vederug_Tik dd where dd.seq_bakasha = v_seq_bakasha;
    for r in (select distinct h535.identity_number,
                              h535.job_number,
                              h535.from_date,
                              h535.code_rank,
                              h535.code_rate || h535.dummy_sub_rate as code_rate
                from ld_hilan_535 h535
               where h535.identity_number = v_id
                 and h535.job_number = v_job_number) loop
    
      /*      merge into Darga_Vederug_Tik derug
      using dual
      on (derug.SEQ_BAKASHA = v_seq_bakasha)
      when matched then
        update
           set TAARICH_ME = r.from_date,
               code_derug = r.rate,
               code_darga = r.rank,
               TAARICH_AD = R.TO_DATE
      when not matched then*/
      v_code_derug := CONVERT_CODE_DERUG(to_number(r.code_rank),
                                         R.code_rate);
      insert into Darga_Vederug_Tik
        (SEQ_DARGOT_VEDERUG_TIK,
         SEQ_BAKASHA,
         TAARICH_ME,
         code_darga,
         code_derug)
      values
        (DARGA_VEDERUG_TIK_SEQ.nextval,
         v_seq_bakasha,
         to_DATE(r.from_date, 'ddmmyyyy'),
         
         to_number(R.code_rate),
         v_code_derug) log errors into err_darga_vederug_tik
        (v_ora_err_tag$) reject limit unlimited;
    end loop;
  
  end;

  -------------------------
  function UpdateMonths(p_taarich_me date, p_taarich_ad date) return number is
  begin
    begin
      select months_between(p_taarich_ad + 1, p_taarich_me)
        into v_sach_chodashim
        from dual t;
    
    exception
      when OTHERS then
        v_sach_chodashim := null;
    end;
    return trunc(v_sach_chodashim, 2);
  
  end;
