  ------------------------------------------------------------
  function convert_KD_GUF_seq_ezor_ovdim(v_kd_guf varchar) return number is
    v_kd_misrad      number;
    v_SEQ_ezor_ovdim number;
  
  begin
    --   v_kd_guf := substr(v_kd_guf, 1, 3)
    --יש להחליף את  2 התווים האחרונים מ 99 ל 00
    v_kd_misrad := to_number(trim(trunc(v_kd_guf / 100) || '00'));
  
    --יש הרבה קודי מרכבה זהים 
    select e.seq_ezor_ovdim
      into v_SEQ_ezor_ovdim
      from Code_Ezor_Ovdim e
     where e.Code_Ezor_Ovdim_Hilan = v_kd_misrad
       and rownum = 1;
    --12/06/2019 ליבה טוענת שצריך להוסיף את התנאי הנ"ל במקום ROWNUM
    --and code_misrad_maskret is null
    return v_SEQ_ezor_ovdim;
  exception
    when no_data_found then
      return 999;
    
  end;
