  function convert_code_seif_prisha(v_kd_sibat_prisha_ varchar) return number is
    v_kd_sibat_prisha number;
  begin
    v_kd_sibat_prisha := to_number(v_kd_sibat_prisha_);
    return case when v_kd_sibat_prisha = 15 then 126 when v_kd_sibat_prisha = 15 then 415 when v_kd_sibat_prisha = 218 then 118 when v_kd_sibat_prisha in(138,
                                                                                                                                                          162,
                                                                                                                                                          628,
                                                                                                                                                          815,
                                                                                                                                                          915) then null else v_kd_sibat_prisha end;
  end;

  --------------------------------------------------
  function convert_code_kirva(StatusCode char) return number is
    v_StatusCode number;
  begin
    v_StatusCode := to_NUMBER(StatusCode);
    return case when StatusCode in(1, 5) then 2 when StatusCode in(2,
                                                                   4,
                                                                   6,
                                                                   8) then 1 else null
    
    end;
  end;

  ----------------------------------------------------------
  function convert_0_or_1_number(var number) return number is
  begin
    return case var when 1 then 1 else 0 end;
  end;
  ----------------------------------------------------------
  function convert_0_or_1(var varchar2) return number is
    v_var number;
  begin
    begin
      v_var := to_number(trim(var));
    exception
      when others then
        v_var := null;
    end;
  
    return convert_0_or_1_number(v_var);
  end;

  -----------------------------------
  procedure update_CODE_MIN is
  begin
    select distinct DECODE(h205.status_code,
                           1,
                           1,
                           2,
                           1,
                           3,
                           1,
                           4,
                           1,
                           5,
                           2,
                           6,
                           2,
                           7,
                           2,
                           8,
                           2) as CODE_MIN
    
      into v_CODE_MIN_PORESH
      from Ld_Hilan_205 h205
     where h205.identity_number = v_id
       and h205.dummy5 =
           (select max(h205_1.dummy5)
              from Ld_Hilan_205 h205_1
             where h205_1.identity_number = h205.identity_number);
  exception
    when no_data_found then
      v_CODE_MIN_PORESH := null;
  end;

  ----------------------------------------------------------
  function update_poresh return boolean is
    poresh_row err_porshim%rowtype;
  begin
    for r in (select distinct h200.identity_number,
                              convert_low_hebrew_to_ascii(h200.first_name) as first_name,
                              convert_low_hebrew_to_ascii(h200.last_name) as last_name,
                              h200.birth_date,
                              h218.telephone1,
                              h218.telephine2,
                              convert_low_hebrew_to_ascii(h298.email) as email
                from ld_hilan_200 h200
                left join ld_hilan_218 h218
                  on h218.identity_number = h200.identity_number
                 and h218.from_date =
                     (select max(h.from_date)
                        from ld_hilan_218 h
                       where h.identity_number = h200.identity_number)
                left join ld_hilan_298 h298
                  on h298.identity_number = h200.identity_number
                 and h298.from_date =
                     (select max(hh.from_date)
                        from ld_hilan_298 hh
                       where hh.identity_number = h200.identity_number)
               where h200.identity_number = v_id) loop
      update_CODE_MIN;
      poresh_row.code_min       := v_CODE_MIN_PORESH;
      poresh_row.mispar_zehut   := r.identity_number;
      poresh_row.shem_prati     := r.first_name;
      poresh_row.shem_mishpacha := r.last_name;
      poresh_row.taarich_leda   := to_date(r.birth_date, 'DDMMYYYY');
      --      poresh_row.mikud          := r.Zone;
      if (TO_NUMBER(r.telephone1) > 0) then
        poresh_row.telephon := r.telephone1;
      end if;
      if (TO_NUMBER(r.telephine2) > 0) then
        poresh_row.Telephon2 := r.telephine2;
      end if;
    
      poresh_row.email     := r.email;
      PORESH_ROW.SUG_ZIHUY := V_sug_zihuy;
    
      /*if trim(r.gender_status_code) in (1, 2, 3, 4) then
        poresh_row.code_min := 1;
      else
        if trim(r.gender_status_code) in (5, 6, 7, 8) then
          poresh_row.code_min := 2;
        end if;
        --  else מין לא ידוע poresh_row.code_min := 999;
      end if;*/
    
      if pk_load_mimshak.is_exist_poresh(v_id, v_porshim_seq) = false then
        v_porshim_seq := porshim_seq.nextval;
      end if;
      --merge into poresh
      merge into poresh
      using dual
      on (poresh.mispar_zehut = poresh_row.mispar_zehut)
      when matched then
        update
           set --city_code             = poresh_row.city_code,
               seq_apotropus = poresh_row.seq_apotropus,
               shem_mishpacha = poresh_row.shem_mishpacha,
               shem_prati     = poresh_row.shem_prati,
               -- shem_kodem     = poresh_row.shem_kodem,
               code_min     = poresh_row.code_min,
               taarich_leda = poresh_row.taarich_leda,
               --address               = poresh_row.address,
               --mikud    = poresh_row.mikud,
               telephon = poresh_row.telephon,
               --code_mazav_mishpachti = poresh_row.code_mazav_mishpachti,
               taarich_aliya         = poresh_row.taarich_aliya,
               is_newcomer           = poresh_row.is_newcomer,
               is_asir               = poresh_row.is_asir,
               date_begin_maasar     = poresh_row.date_begin_maasar,
               date_end_maasar       = poresh_row.date_end_maasar,
               taarich_ptira         = poresh_row.taarich_ptira,
               code_ptira_siba       = poresh_row.code_ptira_siba,
               is_owner_teudat_ptira = poresh_row.is_owner_teudat_ptira,
               email                 = poresh_row.email,
               sug_zihuy             = poresh.Sug_Zihuy
        
      
      when not matched then
        insert
          ( --city_code,
           seq_apotropus,
           porshim_seq,
           mispar_zehut,
           shem_mishpacha,
           shem_prati,
           --shem_kodem,
           code_min,
           taarich_leda,
           --address,
           --mikud,
           --telephon,
           --code_mazav_mishpachti,
           taarich_aliya,
           is_newcomer,
           is_asir,
           date_begin_maasar,
           date_end_maasar,
           taarich_ptira,
           code_ptira_siba,
           is_owner_teudat_ptira,
           email,
           telephon,
           telephon2,
           sug_zihuy)
        values
          ( --poresh_row.city_code,
           poresh_row.seq_apotropus,
           v_porshim_seq,
           poresh_row.mispar_zehut,
           poresh_row.shem_mishpacha,
           poresh_row.shem_prati,
           --  poresh_row.shem_kodem,
           poresh_row.code_min,
           poresh_row.taarich_leda,
           --poresh_row.address,
           -- poresh_row.mikud,
           -- poresh_row.telephon,
           --poresh_row.code_mazav_mishpachti,
           poresh_row.taarich_aliya,
           poresh_row.is_newcomer,
           poresh_row.is_asir,
           poresh_row.date_begin_maasar,
           poresh_row.date_end_maasar,
           poresh_row.taarich_ptira,
           poresh_row.code_ptira_siba,
           poresh_row.is_owner_teudat_ptira,
           poresh_row.email,
           poresh_row.telephon,
           poresh_row.telephon2,
           poresh_row.Sug_Zihuy) log errors into err_porshim
          (v_ora_err_tag$) reject limit unlimited;
    end loop;
  
    if pk_load_mimshak.count_rowes('err_porshim', v_where) > 0 then
      return false;
    else
      return true;
    end if;
  
  end;
