  PROCEDURE merge_bakasha_regila_AND_PORES is
    v_CODE_SEIF_P number;
  begin
  
    if (nvl(v_CODE_SEIF_PRISHA, 0) = 0) then
      v_CODE_SEIF_P := case v_CODE_SEIF_PRISHA_HILAN
                         when 15 then
                          126
                         when 115 then
                          415
                         when 218 then
                          118
                         else
                          v_CODE_SEIF_PRISHA_HILAN
                       end;
    
      UPDATE bakasha_regila br
         SET br.Code_Seif_Prisha = v_CODE_SEIF_P
       WHERE br.Seq_Bakasha = v_seq_bakasha;
    end if;
  
    UPDATE PORESH p
       SET p.sug_zihuy = V_sug_zihuy
     WHERE p.Porshim_Seq = v_porshim_seq;
  
  end;

  -------------------------------------------------
  PROCEDURE merge_PORESH is
    v_birth_date date;
  
  begin
    update_CODE_MIN;
    begin
      select distinct to_date(h200.birth_date, 'ddmmyyyy')
        into v_birth_date
        from ld_hilan_200 h200
       where h200.identity_number = v_id;
    exception
      when no_data_found then
        v_birth_date := null;
    end;
  
    if (v_birth_date is not null) then
      UPDATE PORESH p
         SET p.Taarich_Leda = v_birth_date
       WHERE p.mispar_zehut = v_ID
         and p.taarich_leda is null;
    end if;
  
    UPDATE PORESH p
       SET p.Code_Min = v_CODE_MIN_PORESH
     WHERE p.mispar_zehut = v_ID
       and nvl(p.Code_Min, 0) = 0;
  
  end;

  --------------------------------------------------------------
  function update_bakasha_regila return boolean is
    bakasha_regila_row err_bakasha_regila%rowtype;
    v_CODE_SEIF_P      number;
  begin
    for r in (select distinct h537.identity_number,
                              h537.job_number,
                              h312.value,
                              h537.from_date
                from ld_hilan_537 h537
                left join ld_hilan_312 h312
                  on h312.identity_number = h537.identity_number
                 and h312.variable_type = 102
                 and h312.job_number = h537.job_number
               where h537.identity_number = v_id
                 and h537.job_number = v_job_number) loop
    
      v_CODE_SEIF_P := case --v_CODE_SEIF_PRISHA_HILAN
                       --הסבת שארים STEP B
                       --צריך להוריד את התנאי להסבה הרגילה    
                       --315 גם היה כאן בתנאי וזה אמור להישאר ב03/12/2019  315            
                       --when r.Value in (115, 118, 215, 217, 415) then
                       -- 126
                       -------------------------
                         when r.Value = 15 then
                          126
                         when r.Value = 115 then
                          415
                         when r.Value = 218 then
                          118
                         when r.Value in
                             --סעיף פרישה לא ידוע
                              (140, 21, 121, 12, 612, 180, 40, 815, 628, 11, 41) then
                         
                          999
                         else
                          r.value
                       end;
    
      bakasha_regila_row.Taarich_Prisha := to_date(r.from_date,
                                                   'DD/MM/YYYY');
    
      --bakasha_regila_row.Nechut_Achuz_Nechut_Leprisha := to_number(r.enter_disabilty_percentage);
      bakasha_regila_row.code_seif_prisha := v_CODE_SEIF_P;
      set_CODE_GROUP_PRISHA(bakasha_regila_row.code_seif_prisha);
    
      merge into bakasha_regila
      using dual
      on (bakasha_regila.seq_bakasha = v_seq_bakasha)
      when matched then
        update
           set --code_takanon_magal       = bakasha_regila_row.code_takanon_magal,
               psul_histakrut = bakasha_regila_row.psul_histakrut,
               --salary_seniority         = bakasha_regila_row.salary_seniority,
               has_another_income  = bakasha_regila_row.has_another_income,
               is_mevutach_beguf   = bakasha_regila_row.is_mevutach_beguf,
               makor_gimla_nosefet = bakasha_regila_row.makor_gimla_nosefet,
               date_end_work       = bakasha_regila_row.date_end_work,
               -- dargat_nechut_bitahon    = bakasha_regila_row.dargat_nechut_bitahon,
               --vetek_max = bakasha_regila_row.vetek_max,
               -- is_pasul_varam           = bakasha_regila_row.is_pasul_varam,
               -- is_baal_gimlaot_kefel    = bakasha_regila_row.is_baal_gimlaot_kefel,
               date_vaada_refuit      = bakasha_regila_row.date_vaada_refuit,
               is_sheer_chose_pitzuim = bakasha_regila_row.is_sheer_chose_pitzuim,
               -- is_oblig_tashlum_mezonot = bakasha_regila_row.is_oblig_tashlum_mezonot,
               is_lo_hotzi_pitzuim    = bakasha_regila_row.is_lo_hotzi_pitzuim,
               is_hitzhir_eino_oved   = bakasha_regila_row.is_hitzhir_eino_oved,
               taarich_chatimat_tofes = bakasha_regila_row.taarich_chatimat_tofes,
               taarich_prisha         = bakasha_regila_row.taarich_prisha,
               code_seif_prisha       = bakasha_regila_row.code_seif_prisha,
               --taarich_knisa          = bakasha_regila_row.taarich_knisa,
               hivun_percent      = bakasha_regila_row.hivun_percent,
               is_tvia_zad_gimel  = bakasha_regila_row.is_tvia_zad_gimel,
               date_freeze_haskem = bakasha_regila_row.date_freeze_haskem,
               --  is_contract_medina_vshikum = bakasha_regila_row.is_contract_medina_vshikum,
               is_contract_shikum           = bakasha_regila_row.is_contract_shikum,
               chinuch_mikzoa               = bakasha_regila_row.chinuch_mikzoa,
               Nechut_Achuz_Nechut_Leprisha = bakasha_regila_row.Nechut_Achuz_Nechut_Leprisha
      when not matched then
        insert
          ( --code_takanon_magal,
           psul_histakrut,
           -- salary_seniority,
           has_another_income,
           is_mevutach_beguf,
           makor_gimla_nosefet,
           date_end_work,
           -- dargat_nechut_bitahon,
           --vetek_max,
           --is_pasul_varam,
           --is_baal_gimlaot_kefel,
           date_vaada_refuit,
           is_sheer_chose_pitzuim,
           --is_oblig_tashlum_mezonot,
           is_lo_hotzi_pitzuim,
           is_hitzhir_eino_oved,
           seq_bakasha,
           taarich_chatimat_tofes,
           taarich_prisha,
           code_seif_prisha,
           --taarich_knisa,
           hivun_percent,
           is_tvia_zad_gimel,
           date_freeze_haskem,
           -- is_contract_medina_vshikum,
           is_contract_shikum,
           chinuch_mikzoa,
           Nechut_Achuz_Nechut_Leprisha,
           hp_sheur_havara)
        values
          ( --bakasha_regila_row.code_takanon_magal,
           bakasha_regila_row.psul_histakrut,
           --bakasha_regila_row.salary_seniority,
           bakasha_regila_row.has_another_income,
           bakasha_regila_row.is_mevutach_beguf,
           bakasha_regila_row.makor_gimla_nosefet,
           bakasha_regila_row.date_end_work,
           -- bakasha_regila_row.dargat_nechut_bitahon,
           -- bakasha_regila_row.vetek_max,
           -- bakasha_regila_row.is_pasul_varam,
           -- bakasha_regila_row.is_baal_gimlaot_kefel,
           bakasha_regila_row.date_vaada_refuit,
           bakasha_regila_row.is_sheer_chose_pitzuim,
           -- bakasha_regila_row.is_oblig_tashlum_mezonot,
           bakasha_regila_row.is_lo_hotzi_pitzuim,
           bakasha_regila_row.is_hitzhir_eino_oved,
           v_seq_bakasha,
           bakasha_regila_row.taarich_chatimat_tofes,
           bakasha_regila_row.taarich_prisha,
           bakasha_regila_row.code_seif_prisha,
           --  bakasha_regila_row.taarich_knisa,
           bakasha_regila_row.hivun_percent,
           bakasha_regila_row.is_tvia_zad_gimel,
           bakasha_regila_row.date_freeze_haskem,
           -- bakasha_regila_row.is_contract_medina_vshikum,
           bakasha_regila_row.is_contract_shikum,
           bakasha_regila_row.chinuch_mikzoa,
           bakasha_regila_row.Nechut_Achuz_Nechut_Leprisha,
           --הוספתי את השדה בשביל חסכון פנסיוני
           v_hp_sheur_havara) log errors into err_bakasha_regila
          (v_ora_err_tag$) reject limit unlimited;
    
      if pk_load_mimshak.count_rowes('err_bakasha_regila', v_where) > 0 then
        return false;
      else
        return true;
      end if;
    
    end loop;
    return false;
  end;
  --------------------------------------------
  procedure ComparingValues(v_value1    number,
                            v_value2    number,
                            v_sourceTbl varchar2,
                            v_FieldName varchar2) is
  begin
    if v_value1 <> v_value2 then
      --חוסר תאימות
      v_No_compatibility := true;
      insert into warning_data_conversion
        (seq_bakasha,
         seq_porshim,
         mispar_zheut,
         source_table,
         field_name,
         current_value,
         conversion_value,
         date_bakasha,
         update_date)
      values
        (v_seq_bakasha,
         v_porshim_seq,
         v_ID,
         v_sourceTbl,
         v_FieldName,
         v_value1,
         v_value2,
         v_date_bakasha,
         sysdate);
    end if;
  
  end;
  ---------------------------------------------
  procedure Add_warning_data_conversion_ROW(v_value1    varchar2,
                                            v_value2    varchar2,
                                            v_sourceTbl varchar2,
                                            v_FieldName varchar2) is
  begin
    if (nvl(v_seq_bakasha, 0) = 0) then
      insert into warning_data_conversion
        (
         
         mispar_zheut,
         source_table,
         field_name,
         current_value,
         conversion_value,
         
         update_date)
      values
        (
         
         v_ID,
         v_sourceTbl,
         v_FieldName,
         v_value1,
         v_value2,
         
         sysdate);
    else
      insert into warning_data_conversion
        (seq_bakasha,
         seq_porshim,
         mispar_zheut,
         source_table,
         field_name,
         current_value,
         conversion_value,
         date_bakasha,
         update_date)
      values
        (v_seq_bakasha,
         v_porshim_seq,
         v_ID,
         v_sourceTbl,
         v_FieldName,
         v_value1,
         v_value2,
         v_date_bakasha,
         sysdate);
    end if;
  end;
  ---------------------
  procedure SET_CODE_SEIF_PRISHA_HILAN is
  begin
    begin
      select distinct h102.value
        into v_CODE_SEIF_PRISHA_HILAN
        from ld_hilan_312 h102
       where h102.identity_number = V_ID
         and h102.variable_type = 102
         and h102.job_number = v_job_number
         and h102.To_Date =
             (select max(hh102.To_Date)
                from ld_hilan_312 hh102
               where hh102.identity_number = h102.identity_number
                 and hh102.job_number = h102.job_number);
      --אם נופל להוסיף תנאי של ROWNUM
    exception
      when no_data_found then
        v_CODE_SEIF_PRISHA_HILAN := null;
      
    end;
  
  end;
  --------------------------------------------------
  procedure Find_charigim_data is
  begin
    for r in (select distinct h312.value,
                              b.gimla_number,
                              b.code_seif_prisha,
                              h102.value as HILAN_seif_prisha,
                              to_date(h537.From_Date, 'ddmmyyyy') as From_Date_prisha,
                              b.taarich_prisha
                from v_bakasha_last_status b
                left join ld_hilan_312 h312
                  on h312.identity_number = b.mispar_zehut
                 and h312.variable_type = 100
                 and h312.job_number = v_job_number
                left join ld_hilan_312 h102
                  on h102.identity_number = b.mispar_zehut
                 and h102.variable_type = 102
                 and h102.job_number = v_job_number
                left join ld_hilan_537 h537
                  on h537.identity_number = b.mispar_zehut
                 and h537.job_number = v_job_number
                 and h537.to_date like ('%9999999%')
               where b.seq_bakasha = v_seq_bakasha) loop
    
      set_MIS_GIMLA;
      if (nvl(v_mis_Gimla, 0) = 0) then
        v_mis_Gimla := r.value;
      end if;
      if (v_is_HOZE_BHIRIM = false) then
        ComparingValues(r.gimla_number,
                        v_mis_Gimla,
                        
                        'PRISHA',
                        'gimla_number');
      end if;
      v_CODE_SEIF_PRISHA_HILAN := to_number(nvl(r.HILAN_seif_prisha, 0));
      ComparingValues(nvl(r.code_seif_prisha, 0),
                      to_number(nvl(r.HILAN_seif_prisha, 0)),
                      
                      'BAKASHA_REGILA',
                      'code_seif_prisha');
      if ((r.taarich_prisha - r.From_Date_prisha) > 1) then
        insert into warning_data_conversion
          (seq_bakasha,
           seq_porshim,
           mispar_zheut,
           source_table,
           field_name,
           current_value,
           conversion_value,
           date_bakasha,
           update_date)
        values
          (v_seq_bakasha,
           v_porshim_seq,
           v_ID,
           'BAKASHA_REGILA',
           'taarich_prisha',
           r.taarich_prisha,
           r.From_Date_prisha,
           v_date_bakasha,
           sysdate);
      end if;
    
    end loop;
  end;
  ----------------------------------
  procedure merge_netuny_tik_2SHeeR_PNSYNY is
  begin
    --לעדכן סעיף פישה וגרופ פרישה במקרה והערכים רייקים
    SET_CODE_SEIF_PRISHA_HILAN;
    set_CODE_GROUP_PRISHA(v_CODE_SEIF_PRISHA_HILAN);
    for r in (select distinct nt.Chelkiyut_Lefi_Sherut,
                              nt.Tkufa_Mezaka_Sherut,
                              nt.Tkufa_Lo_Mezaka_Sherut,
                              nt.achuz_kizba_kafuf_chelkiyut,
                              nt.achuz_kizba_chelkiyut_melea,
                              nt.ahuz_kizb_achry_hagdl_kaf_chel
                from netuney_tik_mechushavim nt
               where nt.Seq_Bakasha = V_from_COpy_BAKAHSHA
                 and nt.code_department = 2
                 and nt.Mispar_Misra = 0) loop
    
      merge into netuney_tik_mechushavim n
      using dual
      on (n.SEQ_BAKASHA = v_seq_bakasha and n.code_department = 1)
      when matched then
        update
           set n.Chelkiyut_Lefi_Sherut          = r.Chelkiyut_Lefi_Sherut,
               n.Tkufa_Mezaka_Sherut            = r.Tkufa_Mezaka_Sherut,
               n.Tkufa_Lo_Mezaka_Sherut         = r.Tkufa_Lo_Mezaka_Sherut,
               n.achuz_kizba_kafuf_chelkiyut    = r.achuz_kizba_kafuf_chelkiyut,
               n.achuz_kizba_chelkiyut_melea    = r.achuz_kizba_chelkiyut_melea,
               n.ahuz_kizb_achry_hagdl_kaf_chel = r.ahuz_kizb_achry_hagdl_kaf_chel,
               n.Code_Group_Prisha              = nvl(n.Code_Group_Prisha,
                                                      v_CODE_GROUP_PRISHA)
      when not matched then
      
        insert
          (code_department,
           n.seq_netuney_tik_mechushavim,
           n.seq_bakasha,
           n.Chelkiyut_Lefi_Sherut,
           n.Tkufa_Mezaka_Sherut,
           n.Tkufa_Lo_Mezaka_Sherut,
           n.achuz_kizba_kafuf_chelkiyut,
           n.achuz_kizba_chelkiyut_melea,
           n.ahuz_kizb_achry_hagdl_kaf_chel,
           n.Code_Group_Prisha)
        values
          (1,
           netuney_tik_mechushavim_seq.nextval,
           v_seq_bakasha,
           
           r.Chelkiyut_Lefi_Sherut,
           r.Tkufa_Mezaka_Sherut,
           r.Tkufa_Lo_Mezaka_Sherut,
           r.achuz_kizba_kafuf_chelkiyut,
           r.achuz_kizba_chelkiyut_melea,
           r.ahuz_kizb_achry_hagdl_kaf_chel,
           v_CODE_GROUP_PRISHA) log errors into err_netuney_tik_mechushavim
          (v_ora_err_tag$) reject limit unlimited;
    
      --------------------------------------------------------------------------------------------
      merge into netuney_tik_mechushavim n
      using dual
      on (n.SEQ_BAKASHA = v_seq_bakasha and n.code_department = 2 and n.mispar_misra = 0)
      when matched then
        update
           set n.Chelkiyut_Lefi_Sherut          = r.Chelkiyut_Lefi_Sherut,
               n.Tkufa_Mezaka_Sherut            = r.Tkufa_Mezaka_Sherut,
               n.Tkufa_Lo_Mezaka_Sherut         = r.Tkufa_Lo_Mezaka_Sherut,
               n.achuz_kizba_kafuf_chelkiyut    = r.achuz_kizba_kafuf_chelkiyut,
               n.achuz_kizba_chelkiyut_melea    = r.achuz_kizba_chelkiyut_melea,
               n.ahuz_kizb_achry_hagdl_kaf_chel = r.ahuz_kizb_achry_hagdl_kaf_chel,
               n.Code_Group_Prisha              = nvl(n.Code_Group_Prisha,
                                                      v_CODE_GROUP_PRISHA)
      when not matched then
      
        insert
          (n.code_department,
           n.seq_netuney_tik_mechushavim,
           n.seq_bakasha,
           n.Chelkiyut_Lefi_Sherut,
           n.Tkufa_Mezaka_Sherut,
           n.Tkufa_Lo_Mezaka_Sherut,
           n.achuz_kizba_kafuf_chelkiyut,
           n.achuz_kizba_chelkiyut_melea,
           n.ahuz_kizb_achry_hagdl_kaf_chel,
           n.code_group_prisha)
        values
          (2,
           netuney_tik_mechushavim_seq.nextval,
           v_seq_bakasha,
           r.Chelkiyut_Lefi_Sherut,
           r.Tkufa_Mezaka_Sherut,
           r.Tkufa_Lo_Mezaka_Sherut,
           r.achuz_kizba_kafuf_chelkiyut,
           r.achuz_kizba_chelkiyut_melea,
           r.ahuz_kizb_achry_hagdl_kaf_chel,
           v_CODE_GROUP_PRISHA) log errors into err_netuney_tik_mechushavim
          (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  
  end;
  -----------------------------
  procedure HOZE_BHIRM_2_netny_tik_mchshvm(v_come_from_new_Bakasha boolean) is
    v_achuz_kizba_chelkiyut_melea number;
    v_code_sug_prisha             number;
    v_odef_sherut_yamim           number;
    v_odef_sherut_chodashim       number;
    v_odef_sherut_shanim          number;
  
    v_is_zakai_lmaanak             number;
    v_is_zakai_lkitzba             number;
    V_CHELKIYUT_MESHUKLELET_SHERUT number;
    V_TKUFA_MEZAKA_SHERUT          number;
    V_INDEX_MISRA                  number;
  begin
    V_INDEX_MISRA := 0;
  
    --LOOP JOB NUMBER 2 MISRAD _MASKORET
    for r1 in (select distinct h537.identity_number, h537.job_number
                 from ld_hilan_537 h537
                where h537.identity_number = v_id
                  and substr(h537.office, 1, 3) = v_misrad_maskoret) loop
    
      for r in (select distinct h567.identity_number,
                                h567.job_number,
                                to_number(h567.benefit_percent / 100) as benefit_percent,
                                to_number(h537.percent) / 10000 as percent,
                                h567.from_date_tokef,
                                to_number(h241.sum) as codashim,
                                to_number(h243.sum) as tkufa_mezaka_sherut,
                                to_number(h240.code) as is_z_maanak,
                                to_number(h24.sum) / 10000000 as achuz_gil_60,
                                
                                (select min(h2567.from_date_tokef)
                                   from ld_hilan_567 h2567
                                  where h2567.identity_number =
                                        h567.identity_number
                                    and h2567.job_number = h567.job_number) as date_start_zakaut
                /*, nt.achuz_kizba_sofi as current_Achuz_kizba_sofi,
                nt.date_start_zakaut as current_date_start_zakaut,
                nt.chelkiyut_meshuklelet_sherut as current_chelkiyut_meshuklelet_sherut,
                nt.tkufa_mezaka_sherut as current_tkufa_mezaka_sherut,
                nt.is_zakai_lmaanak as current_is_zakai_lmaanak,
                nt.ACHUZ_KIZBA_GIL_60 as current_ACHUZ_KIZBA_GIL_60,
                nt.ODEF_SHERUT_SHANIM as current_ODEF_SHERUT_SHANIM,
                nt.ODEF_SHERUT_CHODASHIM as current_ODEF_SHERUT_CHODASHIM,
                nt.Odef_Sherut_Yamim as current_Odef_Sherut_Yamim,
                nt.Chelkiyut_Sofit as current_Chelkiyut_Sofit*/
                
                  from ld_hilan_567 h567
                  left join ld_hilan_527 h240
                    on h240.identity_number = h567.identity_number
                   and h240.job_number = h567.job_number
                   and h240.semel = 242
                  left join ld_hilan_527 h241
                    on h241.identity_number = h567.identity_number
                   and h241.job_number = h567.job_number
                   and h241.semel = 241
                   and h241.to_date =
                       (select max(Hh241.To_Date)
                          from ld_hilan_527 Hh241
                         where Hh241.semel = 241
                           and hh241.identity_number = h567.identity_number
                           and hh241.job_number = h567.job_number)
                  left join ld_hilan_527 h243
                    on h243.identity_number = h567.identity_number
                   and h243.job_number = h567.job_number
                   and h243.semel = 243
                  left join ld_hilan_527 h24
                    on h24.identity_number = h567.identity_number
                   and h24.job_number = h567.job_number
                   and h24.semel = 24
                  left join ld_hilan_537 h537
                    on h537.identity_number = h567.identity_number
                   and h537.job_number = h567.job_number
                   and h537.to_date like ('%9999999%')
                  left join ld_hilan_537 h537
                    on h537.identity_number = h567.identity_number
                   and h537.job_number = h567.job_number
                   and h537.to_date like ('%9999999%')
                /*  left join netuney_tik_mechushavim nt
                 on nt.Seq_Bakasha = v_seq_bakasha
                and nt.code_department = 2*/
                
                 where h567.identity_number = V_ID
                   and h567.job_number = r1.job_number
                   and h567.from_date =
                       (select max(hh567.from_date)
                          from ld_hilan_567 hh567
                         where hh567.identity_number = h567.identity_number
                           and hh567.job_number = h567.job_number)
                   and h567.to_date_tokef like ('%9999999%')
                
                ) loop
      
        v_odef_sherut_chodashim := trunc(r.codashim / 100);
      
        v_odef_sherut_shanim := trunc(v_odef_sherut_chodashim / 12);
        v_odef_sherut_yamim  := round(MOD((r.codashim / 100), 1) * 30.44);
        v_date_start_zakahut := to_date(r.date_start_zakaut, 'DDMMYYYY');
        -- v_date_start_zakahut := to_date('0' || substr(r.from_date_tokef, 1, 7), 'DDMMYYYY');
      
        --       substr(h537.office, 1, 3)
      
        /* V_CHELKIYUT_MESHUKLELET_SHERUT := r.partiality / 1000;
        if (V_CHELKIYUT_MESHUKLELET_SHERUT > 70) then
          V_CHELKIYUT_MESHUKLELET_SHERUT := 70;
        end if;*/
        V_TKUFA_MEZAKA_SHERUT := r.tkufa_mezaka_sherut / 100;
        v_No_compatibility    := false;
      
        --אם אין חוסר תאימות או שתאריכי הבקשה קטן מ2017
        /* if v_come_from_new_Bakasha or
          --v_No_compatibility = false or
          --אם הגיע מהסבות ואחוז קיצבה ריק , כן יש לעדכן את הטבלה
           v_date_bakasha < to_date('01102017', 'ddmmyyyy') or
           (v_date_bakasha >= to_date('01102017', 'ddmmyyyy') and
           V_INDEX_MISRA > 0)
        --   or nvl(r.current_achuz_kizba_sofi, 0) = 0 
         then*/
      
        -- execute immediate 'ALTER TRIGGER Netuney_Tik_Mechushavim_maakav_history_TRG ENABLE';
      
        merge into netuney_tik_mechushavim n
        using dual
        on (n.SEQ_BAKASHA = v_seq_bakasha and n.code_department = 1 and n.mispar_misra = V_INDEX_MISRA)
        when matched then
          update
             set n.date_start_zakaut = n.date_start_zakaut --v_date_start_zakahut,
          -- n.achuz_kizba_sofi             = to_number(r.Benefit_Percent),
          -- n.achuz_kizba_kafuf_chelkiyut  = to_number(r.Benefit_Percent),
          -- n.CHELKIYUT_MESHUKLELET_SHERUT = to_number(r.percent),
          -- n.TKUFA_MEZAKA_SHERUT          = V_TKUFA_MEZAKA_SHERUT,
          
          --n.IS_ZAKAI_LMAANAK = r.is_z_maanak,
          --n.CHELKIYUT_SOFIT  = to_number(r.percent),
          -- n.ACHUZ_KIZBA_GIL_60    = r.achuz_gil_60,
          --n.IS_HACHLATA_SOFIT              = 1,
          --                 n.ODEF_SHERUT_SHANIM             = v_odef_sherut_shanim,
          --               n.ODEF_SHERUT_CHODASHIM          = v_odef_sherut_chodashim,
          --             n.ODEF_SHERUT_YAMIM              = v_odef_sherut_yamim,
          --           n.achuz_kizb_achry_hagdl_chl_mla = to_number(r.Benefit_Percent)
          
        
        when not matched then
        
          insert
            (code_department,
             n.seq_netuney_tik_mechushavim,
             n.seq_bakasha,
             n.date_start_zakaut,
             n.achuz_kizba_sofi,
             n.achuz_kizba_kafuf_chelkiyut,
             n.CHELKIYUT_MESHUKLELET_SHERUT,
             n.TKUFA_MEZAKA_SHERUT,
             n.CODE_GROUP_PRISHA,
             n.IS_ZAKAI_LMAANAK,
             n.CHELKIYUT_SOFIT,
             -- n.ACHUZ_KIZBA_GIL_60,
             n.IS_HACHLATA_SOFIT,
             n.ODEF_SHERUT_SHANIM,
             n.ODEF_SHERUT_CHODASHIM,
             n.ODEF_SHERUT_YAMIM,
             n.mispar_misra,
             Ahuz_Kizb_Achry_Hagdl_Kaf_Chel)
          values
            (1,
             netuney_tik_mechushavim_seq.nextval,
             v_seq_bakasha,
             v_date_start_zakahut,
             to_number(r.Benefit_Percent),
             to_number(r.Benefit_Percent),
             to_number(r.percent),
             V_TKUFA_MEZAKA_SHERUT,
             v_CODE_GROUP_PRISHA,
             r.is_z_maanak,
             to_number(r.percent),
             -- r.achuz_gil_60,
             1,
             v_odef_sherut_shanim,
             v_odef_sherut_chodashim,
             v_odef_sherut_yamim,
             V_INDEX_MISRA,
             to_number(r.Benefit_Percent)) log errors into err_netuney_tik_mechushavim
            (v_ora_err_tag$) reject limit unlimited;
      
        ------------------------------------------
        merge into netuney_tik_mechushavim n
        using dual
        on (n.SEQ_BAKASHA = v_seq_bakasha and n.code_department = 2 and n.mispar_misra = V_INDEX_MISRA)
        when matched then
          update
             set n.date_start_zakaut            = v_date_start_zakahut,
                 n.achuz_kizba_sofi             = to_number(r.Benefit_Percent),
                 n.achuz_kizba_kafuf_chelkiyut  = to_number(r.Benefit_Percent),
                 n.CHELKIYUT_MESHUKLELET_SHERUT = to_number(r.percent),
                 n.TKUFA_MEZAKA_SHERUT          = V_TKUFA_MEZAKA_SHERUT,
                 
                 n.IS_ZAKAI_LMAANAK = r.is_z_maanak,
                 n.CHELKIYUT_SOFIT  = to_number(r.percent),
                 -- n.ACHUZ_KIZBA_GIL_60    = r.achuz_gil_60,
                 n.IS_HACHLATA_SOFIT              = 1,
                 n.ODEF_SHERUT_SHANIM             = v_odef_sherut_shanim,
                 n.ODEF_SHERUT_CHODASHIM          = v_odef_sherut_chodashim,
                 n.ODEF_SHERUT_YAMIM              = v_odef_sherut_yamim,
                 n.Ahuz_Kizb_Achry_Hagdl_Kaf_Chel = to_number(r.Benefit_Percent)
        when not matched then
        
          insert
            (code_department,
             n.seq_netuney_tik_mechushavim,
             n.seq_bakasha,
             n.date_start_zakaut,
             n.achuz_kizba_sofi,
             n.achuz_kizba_kafuf_chelkiyut,
             n.CHELKIYUT_MESHUKLELET_SHERUT,
             n.TKUFA_MEZAKA_SHERUT,
             n.CODE_GROUP_PRISHA,
             n.IS_ZAKAI_LMAANAK,
             n.CHELKIYUT_SOFIT,
             -- n.ACHUZ_KIZBA_GIL_60,
             n.IS_HACHLATA_SOFIT,
             n.ODEF_SHERUT_SHANIM,
             n.ODEF_SHERUT_CHODASHIM,
             n.ODEF_SHERUT_YAMIM,
             n.mispar_misra,
             n.Ahuz_Kizb_Achry_Hagdl_Kaf_Chel)
          values
            (2,
             netuney_tik_mechushavim_seq.nextval,
             v_seq_bakasha,
             v_date_start_zakahut,
             to_number(r.Benefit_Percent),
             to_number(r.Benefit_Percent),
             to_number(r.percent),
             V_TKUFA_MEZAKA_SHERUT,
             v_CODE_GROUP_PRISHA,
             r.is_z_maanak,
             to_number(r.percent),
             -- r.achuz_gil_60,
             1,
             v_odef_sherut_shanim,
             v_odef_sherut_chodashim,
             v_odef_sherut_yamim,
             V_INDEX_MISRA,
             to_number(r.Benefit_Percent)) log errors into err_netuney_tik_mechushavim
            (v_ora_err_tag$) reject limit unlimited;
      
        -- end if;
        V_INDEX_MISRA := V_INDEX_MISRA + 1;
      end loop;
    
    end loop;
  end;
  -----------------------------------

  procedure merge_netuney_tik_mechushavim is
    v_achuz_kizba_chelkiyut_melea number;
    v_code_sug_prisha             number;
    v_odef_sherut_yamim           number;
    v_odef_sherut_chodashim       number;
    v_odef_sherut_shanim          number;
  
    v_is_zakai_lmaanak             number;
    v_is_zakai_lkitzba             number;
    V_CHELKIYUT_MESHUKLELET_SHERUT number;
    V_TKUFA_MEZAKA_SHERUT          number;
  begin
    SET_CODE_SEIF_PRISHA_HILAN;
    set_CODE_GROUP_PRISHA(v_CODE_SEIF_PRISHA_HILAN);
    for r in (select distinct h567.identity_number,
                              h567.job_number,
                              to_number(h567.benefit_percent / 100) as benefit_percent,
                              to_number(h537.percent) / 10000 as percent,
                              h567.from_date_tokef,
                              to_number(h241.sum) as codashim,
                              to_number(h243.sum) as tkufa_mezaka_sherut,
                              to_number(h240.code) as is_z_maanak,
                              to_number(h24.sum) / 10000000 as achuz_gil_60,
                              
                              (select min(h2567.from_date_tokef)
                                 from ld_hilan_567 h2567
                                where h2567.identity_number =
                                      h567.identity_number
                                  and h2567.job_number = h567.job_number) as date_start_zakaut,
                              nt.achuz_kizba_sofi as current_Achuz_kizba_sofi,
                              nt.date_start_zakaut as current_date_start_zakaut,
                              nt.chelkiyut_meshuklelet_sherut as current_chelkiyut_meshuklelet_sherut,
                              nt.tkufa_mezaka_sherut as current_tkufa_mezaka_sherut,
                              nt.is_zakai_lmaanak as current_is_zakai_lmaanak,
                              nt.ACHUZ_KIZBA_GIL_60 as current_ACHUZ_KIZBA_GIL_60,
                              nt.ODEF_SHERUT_SHANIM as current_ODEF_SHERUT_SHANIM,
                              nt.ODEF_SHERUT_CHODASHIM as current_ODEF_SHERUT_CHODASHIM,
                              nt.Odef_Sherut_Yamim as current_Odef_Sherut_Yamim,
                              nt.Chelkiyut_Sofit as current_Chelkiyut_Sofit
              
                from ld_hilan_567 h567
                left join ld_hilan_527 h240
                  on h240.identity_number = h567.identity_number
                 and h240.job_number = h567.job_number
                 and h240.semel = 242
                left join ld_hilan_527 h241
                  on h241.identity_number = h567.identity_number
                 and h241.job_number = h567.job_number
                 and h241.semel = 241
                 and h241.to_date =
                     (select max(Hh241.To_Date)
                        from ld_hilan_527 Hh241
                       where Hh241.semel = 241
                         and hh241.identity_number = h567.identity_number
                         and hh241.job_number = h567.job_number)
                left join ld_hilan_527 h243
                  on h243.identity_number = h567.identity_number
                 and h243.job_number = h567.job_number
                 and h243.semel = 243
                left join ld_hilan_527 h24
                  on h24.identity_number = h567.identity_number
                 and h24.job_number = h567.job_number
                 and h24.semel = 24
                left join ld_hilan_537 h537
                  on h537.identity_number = h567.identity_number
                 and h537.job_number = h567.job_number
                 and h537.to_date like ('%9999999%')
                left join ld_hilan_537 h537
                  on h537.identity_number = h567.identity_number
                 and h537.job_number = h567.job_number
                 and h537.to_date like ('%9999999%')
                left join netuney_tik_mechushavim nt
                  on nt.Seq_Bakasha = v_seq_bakasha
                 and nt.code_department = 2
                 and nt.mispar_misra = 0
               where h567.identity_number = V_ID
                 and h567.job_number = v_job_number
                 and h567.from_date =
                     (select max(hh567.from_date)
                        from ld_hilan_567 hh567
                       where hh567.identity_number = h567.identity_number
                         and hh567.job_number = h567.job_number)
                 and h567.to_date_tokef like ('%9999999%')
              
              ) loop
    
      v_odef_sherut_chodashim := trunc(r.codashim / 100);
    
      v_odef_sherut_shanim := trunc(v_odef_sherut_chodashim / 12);
      v_odef_sherut_yamim  := round(MOD((r.codashim / 100), 1) * 30.44);
      v_date_start_zakahut := to_date(r.date_start_zakaut, 'DDMMYYYY');
      -- v_date_start_zakahut := to_date('0' || substr(r.from_date_tokef, 1, 7), 'DDMMYYYY');
    
      --       substr(h537.office, 1, 3)
    
      /* V_CHELKIYUT_MESHUKLELET_SHERUT := r.partiality / 1000;
      if (V_CHELKIYUT_MESHUKLELET_SHERUT > 70) then
        V_CHELKIYUT_MESHUKLELET_SHERUT := 70;
      end if;*/
      V_TKUFA_MEZAKA_SHERUT := r.tkufa_mezaka_sherut / 100;
      v_No_compatibility    := false;
      if (v_is_HOZE_BHIRIM = false) then
        ComparingValues(r.current_achuz_kizba_sofi,
                        to_number(nvl(r.Benefit_Percent, 0)),
                        'Netuney_Tik_Mechushavim',
                        'achuz_kizba_sofi');
        ComparingValues(r.current_Chelkiyut_Sofit,
                        to_number(nvl(r.percent, 0)),
                        'Netuney_Tik_Mechushavim',
                        'Chelkiyut_Sofit');
        --לבקשת דבור - לא רלבנטי כי הם לא שולחים לנו ערך
        /*      ComparingValues(r.Current_Tkufa_Mezaka_Sherut,
        nvl(V_TKUFA_MEZAKA_SHERUT, 0),
        'Netuney_Tik_Mechushavim',
        'Tkufa_Mezaka_Sherut');*/
        ComparingValues(r.Current_Is_Zakai_Lmaanak,
                        to_number(nvl(r.is_z_maanak, 0)),
                        'Netuney_Tik_Mechushavim',
                        'Is_Zakai_Lmaanak');
        /*ComparingValues(r.Current_Achuz_Kizba_Gil_60,
        to_number(nvl(r.achuz_gil_60, 0)),
        'Netuney_Tik_Mechushavim',
        'Achuz_Kizba_Gil_60');*/
        ComparingValues(r.current_odef_sherut_shanim,
                        to_number(nvl(v_odef_sherut_shanim, 0)),
                        'Netuney_Tik_Mechushavim',
                        'odef_sherut_shanim');
        ComparingValues(r.Current_Odef_Sherut_Chodashim,
                        nvl(v_odef_sherut_chodashim, 0),
                        'Netuney_Tik_Mechushavim',
                        'Odef_Sherut_Chodashim');
        ComparingValues(r.Current_Odef_Sherut_Yamim,
                        nvl(v_odef_sherut_yamim, 0),
                        'Netuney_Tik_Mechushavim',
                        'Odef_Sherut_Yamim');
      end if;
      --אם אין חוסר תאימות או שתאריכי הבקשה קטן מ2017
      if
      --v_No_compatibility = false or
      --אם הגיע מהסבות ואחוז קיצבה ריק , כן יש לעדכן את הטבלה
       v_date_bakasha < to_date('01102017', 'ddmmyyyy') or
       nvl(r.current_achuz_kizba_sofi, 0) = 0 then
      
        -- execute immediate 'ALTER TRIGGER Netuney_Tik_Mechushavim_maakav_history_TRG ENABLE';
      
        merge into netuney_tik_mechushavim n
        using dual
        on (n.SEQ_BAKASHA = v_seq_bakasha and n.code_department = 1)
        when matched then
          update
             set n.date_start_zakaut = v_date_start_zakahut,
                 n.achuz_kizba_sofi  = nvl(to_number(r.Benefit_Percent),
                                           n.achuz_kizba_sofi),
                 --בגלל שזה במדינה אז לדרוס רק כשריק
                 n.achuz_kizba_kafuf_chelkiyut  = nvl(n.achuz_kizba_kafuf_chelkiyut,
                                                      to_number(r.Benefit_Percent)),
                 n.CHELKIYUT_MESHUKLELET_SHERUT = nvl(to_number(r.percent),
                                                      n.CHELKIYUT_MESHUKLELET_SHERUT),
                 n.TKUFA_MEZAKA_SHERUT          = V_TKUFA_MEZAKA_SHERUT,
                 
                 n.IS_ZAKAI_LMAANAK = r.is_z_maanak,
                 n.CHELKIYUT_SOFIT  = to_number(r.percent),
                 -- n.ACHUZ_KIZBA_GIL_60    = r.achuz_gil_60,
                 n.IS_HACHLATA_SOFIT     = 1,
                 n.ODEF_SHERUT_SHANIM    = v_odef_sherut_shanim,
                 n.ODEF_SHERUT_CHODASHIM = v_odef_sherut_chodashim,
                 n.ODEF_SHERUT_YAMIM     = v_odef_sherut_yamim,
                 
                 n.ahuz_kizb_achry_hagdl_kaf_chel = NVL(n.ahuz_kizb_achry_hagdl_kaf_chel,
                                                        to_number(r.Benefit_Percent)),
                 n.code_group_prisha              = nvl(n.code_group_prisha,
                                                        v_CODE_GROUP_PRISHA)
          
        
        when not matched then
        
          insert
            (code_department,
             n.seq_netuney_tik_mechushavim,
             n.seq_bakasha,
             n.date_start_zakaut,
             n.achuz_kizba_sofi,
             n.achuz_kizba_kafuf_chelkiyut,
             n.CHELKIYUT_MESHUKLELET_SHERUT,
             n.TKUFA_MEZAKA_SHERUT,
             n.CODE_GROUP_PRISHA,
             n.IS_ZAKAI_LMAANAK,
             n.CHELKIYUT_SOFIT,
             -- n.ACHUZ_KIZBA_GIL_60,
             n.IS_HACHLATA_SOFIT,
             n.ODEF_SHERUT_SHANIM,
             n.ODEF_SHERUT_CHODASHIM,
             n.ODEF_SHERUT_YAMIM,
             
             n.ahuz_kizb_achry_hagdl_kaf_chel)
          values
            (1,
             netuney_tik_mechushavim_seq.nextval,
             v_seq_bakasha,
             v_date_start_zakahut,
             to_number(r.Benefit_Percent),
             to_number(r.Benefit_Percent),
             to_number(r.percent),
             V_TKUFA_MEZAKA_SHERUT,
             v_CODE_GROUP_PRISHA,
             r.is_z_maanak,
             to_number(r.percent),
             -- r.achuz_gil_60,
             1,
             v_odef_sherut_shanim,
             v_odef_sherut_chodashim,
             v_odef_sherut_yamim,
             to_number(r.Benefit_Percent)) log errors into err_netuney_tik_mechushavim
            (v_ora_err_tag$) reject limit unlimited;
      
        --------------------------------------------------------------------------------------------
        merge into netuney_tik_mechushavim n
        using dual
        on (n.SEQ_BAKASHA = v_seq_bakasha and n.code_department = 2 and n.mispar_misra = 0)
        when matched then
          update
             set n.date_start_zakaut = v_date_start_zakahut,
                 n.achuz_kizba_sofi  = nvl(to_number(r.Benefit_Percent),
                                           n.achuz_kizba_sofi),
                 --בגלל שזה במדינה אז לדרוס רק כשריק
                 n.achuz_kizba_kafuf_chelkiyut  = nvl(n.achuz_kizba_kafuf_chelkiyut,
                                                      to_number(r.Benefit_Percent)),
                 n.CHELKIYUT_MESHUKLELET_SHERUT = nvl(to_number(r.percent),
                                                      n.CHELKIYUT_MESHUKLELET_SHERUT),
                 n.TKUFA_MEZAKA_SHERUT          = V_TKUFA_MEZAKA_SHERUT,
                 
                 n.IS_ZAKAI_LMAANAK = r.is_z_maanak,
                 n.CHELKIYUT_SOFIT  = to_number(r.percent),
                 -- n.ACHUZ_KIZBA_GIL_60    = r.achuz_gil_60,
                 n.IS_HACHLATA_SOFIT     = 1,
                 n.ODEF_SHERUT_SHANIM    = v_odef_sherut_shanim,
                 n.ODEF_SHERUT_CHODASHIM = v_odef_sherut_chodashim,
                 n.ODEF_SHERUT_YAMIM     = v_odef_sherut_yamim,
                 
                 n.ahuz_kizb_achry_hagdl_kaf_chel = NVL(n.ahuz_kizb_achry_hagdl_kaf_chel,
                                                        to_number(r.Benefit_Percent)),
                 n.code_group_prisha              = nvl(n.code_group_prisha,
                                                        v_CODE_GROUP_PRISHA)
          
        
        when not matched then
        
          insert
            (code_department,
             n.seq_netuney_tik_mechushavim,
             n.seq_bakasha,
             n.date_start_zakaut,
             n.achuz_kizba_sofi,
             n.achuz_kizba_kafuf_chelkiyut,
             n.CHELKIYUT_MESHUKLELET_SHERUT,
             n.TKUFA_MEZAKA_SHERUT,
             n.CODE_GROUP_PRISHA,
             n.IS_ZAKAI_LMAANAK,
             n.CHELKIYUT_SOFIT,
             -- n.ACHUZ_KIZBA_GIL_60,
             n.IS_HACHLATA_SOFIT,
             n.ODEF_SHERUT_SHANIM,
             n.ODEF_SHERUT_CHODASHIM,
             n.ODEF_SHERUT_YAMIM,
             n.ahuz_kizb_achry_hagdl_kaf_chel)
          values
            (2,
             netuney_tik_mechushavim_seq.nextval,
             v_seq_bakasha,
             v_date_start_zakahut,
             to_number(r.Benefit_Percent),
             to_number(r.Benefit_Percent),
             to_number(r.percent),
             V_TKUFA_MEZAKA_SHERUT,
             v_CODE_GROUP_PRISHA,
             r.is_z_maanak,
             to_number(r.percent),
             -- r.achuz_gil_60,
             1,
             v_odef_sherut_shanim,
             v_odef_sherut_chodashim,
             v_odef_sherut_yamim,
             to_number(r.Benefit_Percent)) log errors into err_netuney_tik_mechushavim
            (v_ora_err_tag$) reject limit unlimited;
      
      end if;
    
    end loop;
  
  end;
  -------------------------------------

  procedure update_netuney_tik_mechushavim is
    v_achuz_kizba_chelkiyut_melea number;
    v_code_sug_prisha             number;
    v_odef_sherut_yamim           number;
    v_odef_sherut_chodashim       number;
    v_odef_sherut_shanim          number;
  
    v_is_zakai_lmaanak             number;
    v_is_zakai_lkitzba             number;
    V_CHELKIYUT_MESHUKLELET_SHERUT number;
    V_TKUFA_MEZAKA_SHERUT          number;
  begin
    for r in (select distinct h567.identity_number,
                              h567.job_number,
                              to_number(h567.benefit_percent / 100) as benefit_percent,
                              to_number(h537.percent) / 10000 as percent,
                              h567.from_date_tokef,
                              to_number(h241.sum) as codashim,
                              to_number(h243.sum) as tkufa_mezaka_sherut,
                              to_number(h240.code) as is_z_maanak,
                              to_number(h24.sum) / 10000000 as achuz_gil_60,
                              
                              (select min(h2567.from_date_tokef)
                                 from ld_hilan_567 h2567
                                where h2567.identity_number =
                                      h567.identity_number
                                  and h2567.job_number = h567.job_number) as date_start_zakaut,
                              --במקרה שיש CODE_STATE =41 בהפסקת תשלות הוה אומר הארכת שירות ויש לקחת את התאריך המקסימלי
                              (select max(h2567.from_date_tokef)
                                 from ld_hilan_567 h2567
                                where h2567.identity_number =
                                      h567.identity_number
                                  and h2567.job_number = h567.job_number) as date_start_zkut_haarahat_shrut
              
                from ld_hilan_567 h567
                left join ld_hilan_527 h240
                  on h240.identity_number = h567.identity_number
                 and h240.job_number = h567.job_number
                 and h240.semel = 242
                left join ld_hilan_527 h241
                  on h241.identity_number = h567.identity_number
                 and h241.job_number = h567.job_number
                 and h241.semel = 241
                 and h241.to_date =
                     (select max(Hh241.To_Date)
                        from ld_hilan_527 Hh241
                       where Hh241.semel = 241
                         and hh241.identity_number = h567.identity_number
                         and hh241.job_number = h567.job_number)
                left join ld_hilan_527 h243
                  on h243.identity_number = h567.identity_number
                 and h243.job_number = h567.job_number
                 and h243.semel = 243
                left join ld_hilan_527 h24
                  on h24.identity_number = h567.identity_number
                 and h24.job_number = h567.job_number
                 and h24.semel = 24
                left join ld_hilan_537 h537
                  on h537.identity_number = h567.identity_number
                 and h537.job_number = h567.job_number
                 and h537.to_date like ('%9999999%')
              
               where h567.identity_number = V_ID
                 and h567.job_number = v_job_number
                 and h567.from_date =
                     (select max(hh567.from_date)
                        from ld_hilan_567 hh567
                       where hh567.identity_number = h567.identity_number
                         and hh567.job_number = h567.job_number)
                 and h567.to_date_tokef like ('%9999999%')
              
              ) loop
    
      v_odef_sherut_chodashim := trunc(r.codashim / 100);
    
      v_odef_sherut_shanim := v_odef_sherut_chodashim / 12;
      v_odef_sherut_yamim  := MOD((r.codashim), 1) * 30.44;
      if (V_IS_HAARACHAT_SHERUT) then
        v_date_start_zakahut := to_date(r.date_start_zkut_haarahat_shrut,
                                        'DDMMYYYY');
      else
        v_date_start_zakahut := to_date(r.date_start_zakaut, 'DDMMYYYY');
      end if;
      -- v_date_start_zakahut := to_date('0' || substr(r.from_date_tokef, 1, 7), 'DDMMYYYY');
    
      --       substr(h537.office, 1, 3)
    
      /* V_CHELKIYUT_MESHUKLELET_SHERUT := r.partiality / 1000;
      if (V_CHELKIYUT_MESHUKLELET_SHERUT > 70) then
        V_CHELKIYUT_MESHUKLELET_SHERUT := 70;
      end if;*/
      V_TKUFA_MEZAKA_SHERUT := r.tkufa_mezaka_sherut / 100;
      insert into netuney_tik_mechushavim n
        (code_department,
         n.seq_netuney_tik_mechushavim,
         n.seq_bakasha,
         n.date_start_zakaut,
         n.achuz_kizba_sofi,
         n.achuz_kizba_kafuf_chelkiyut,
         n.CHELKIYUT_MESHUKLELET_SHERUT,
         n.TKUFA_MEZAKA_SHERUT,
         n.CODE_GROUP_PRISHA,
         n.IS_ZAKAI_LMAANAK,
         n.CHELKIYUT_SOFIT,
         n.ACHUZ_KIZBA_GIL_60,
         n.IS_HACHLATA_SOFIT,
         n.ODEF_SHERUT_SHANIM,
         n.ODEF_SHERUT_CHODASHIM,
         n.ODEF_SHERUT_YAMIM,
         
         n.ahuz_kizb_achry_hagdl_kaf_chel)
      values
        (1,
         netuney_tik_mechushavim_seq.nextval,
         v_seq_bakasha,
         v_date_start_zakahut,
         to_number(r.Benefit_Percent),
         to_number(r.Benefit_Percent),
         to_number(r.percent),
         V_TKUFA_MEZAKA_SHERUT,
         v_CODE_GROUP_PRISHA,
         r.is_z_maanak,
         to_number(r.percent),
         r.achuz_gil_60,
         1,
         v_odef_sherut_shanim,
         v_odef_sherut_chodashim,
         v_odef_sherut_yamim,
         to_number(r.Benefit_Percent)) log errors into err_netuney_tik_mechushavim
        (v_ora_err_tag$) reject limit unlimited;
    
      insert into netuney_tik_mechushavim n
        (code_department,
         n.seq_netuney_tik_mechushavim,
         n.seq_bakasha,
         n.date_start_zakaut,
         n.achuz_kizba_sofi,
         n.achuz_kizba_kafuf_chelkiyut,
         n.CHELKIYUT_MESHUKLELET_SHERUT,
         n.TKUFA_MEZAKA_SHERUT,
         n.CODE_GROUP_PRISHA,
         n.IS_ZAKAI_LMAANAK,
         n.CHELKIYUT_SOFIT,
         n.ACHUZ_KIZBA_GIL_60,
         n.IS_HACHLATA_SOFIT,
         n.ODEF_SHERUT_SHANIM,
         n.ODEF_SHERUT_CHODASHIM,
         n.ODEF_SHERUT_YAMIM,
         n.ahuz_kizb_achry_hagdl_kaf_chel)
      values
        (2,
         netuney_tik_mechushavim_seq.nextval,
         v_seq_bakasha,
         v_date_start_zakahut,
         --r.achuz_kizba,
         to_number(r.Benefit_Percent),
         to_number(r.Benefit_Percent),
         --V_CHELKIYUT_MESHUKLELET_SHERUT,
         to_number(r.percent),
         V_TKUFA_MEZAKA_SHERUT,
         v_CODE_GROUP_PRISHA,
         r.is_z_maanak,
         to_number(r.percent),
         r.achuz_gil_60,
         1,
         v_odef_sherut_shanim,
         v_odef_sherut_chodashim,
         v_odef_sherut_yamim,
         to_number(r.Benefit_Percent)) log errors into err_netuney_tik_mechushavim
        (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  end;
