  ------------------------------------------
  procedure update_hafsakat_tashlum(v_is_sheer boolean) is
    v_VID number;
  begin
    --למקרה שהפסקת טיפול לשאר יש לעדכן את הID של השאר
    if (v_is_sheer = true) then
      v_VID := v_SHEER_ID;
    else
      v_VID := v_ID;
    end if;
    for r in (select distinct h221.identity_number,
                              h221.job_number,
                              h221.from_date_tokef,
                              h221.code_state,
                              h312.value as seif_prisha
                from ld_hilan_221 h221
                left join ld_hilan_312 h312
                  on h312.identity_number = h221.identity_number
                 and h312.job_number = h221.job_number
                 and h312.variable_type = 102
               where h221.identity_number = v_VID --V_ID
                 and h221.job_number = v_job_number
                 and h221.code_state > 40
              --                 and h221.code_state not in (43,44)
               order by to_date(h221.from_date_tokef, 'ddmmyyyy') asc) loop
      if (r.code_state = 41) then
        --הארכת שירות
        V_IS_HAARACHAT_SHERUT := true;
      end if;
    
      v_date_end_zakaut := to_date(r.from_date_tokef, 'ddmmyyyy');
    
      Create_Another_Bakasha(19,
                             to_date(r.from_date_tokef, 'ddmmyyyy'),
                             to_number(r.code_state),
                             v_is_sheer,
                             null);
    
      set_CODE_GROUP_PRISHA(r. seif_prisha);
    
      update_netuneyTik2HafsakatTslm(r.code_state, v_is_sheer);
      if v_is_sheer then
        --UPDATE TO_DATE IN BNEY_MISPACHA 
      
        UPDATE BNEY_MISHPACHA bm
           SET bm.To_Date_Sium_Zakaut = to_date(r.from_date_tokef,
                                                'ddmmyyyy')
         WHERE bm.mispar_zehut_ben_mishpacha = v_SHEER_ID;
      end if;
    
    end loop;
  end;

  ----------------------------------------------------------------

  procedure update_participation_m_guf is
  
    v_is_heskem_yachid    number;
    v_is_mevutach_beguf   number;
    v_seq_ezor_ovdim      number;
    V_percent_participate number;
    V_SUM_participate     number;
  begin
    if nvl(v_date_bakasha, to_date('01/01/0001', 'DD/MM/YYYY')) <=
       to_date('01092016', 'ddmmyyyy') then
      delete from participation p
       where p.Seq_Bakasha = v_seq_bakasha
         and p.sum = 0
            --לשאול את דבור אם להוסיף לתנאי המחיקה...
         and p.Code_Participation in (2, 5);
    end if;
    for r in (select distinct h413.identity_number,
                              h413.code_guf,
                              h413.amount,
                              h413.sum,
                              to_date('01' || from_date, 'ddmmyyyy') AS from_date,
                              -- h413.from_date,
                              h413.semel
                from ld_hilan_413 h413
               where
              --תוים מוזרים שמציינים מינוס
               (substr(h413.sum, 9, 1) not like ('%J%') and
               substr(h413.sum, 9, 1) not like ('%K%') and
               substr(h413.sum, 9, 1) not like ('%R%') and
               substr(h413.sum, 9, 1) not like ('%M%') and
               substr(h413.sum, 9, 1) not like ('%R%') and
               substr(h413.sum, 9, 1) not like ('%N%') and
               substr(h413.sum, 9, 1) not like ('%R%') and
               substr(h413.sum, 9, 1) not like ('%O%') and
               substr(h413.sum, 9, 1) not like ('%R%') and
               substr(h413.sum, 9, 1) not like ('%P%') and
               substr(h413.sum, 9, 1) not like ('%R%') and
               substr(h413.sum, 9, 1) not like ('%Q%') and
               substr(h413.sum, 9, 1) not like ('%R%') and
               substr(h413.sum, 9, 1) not like ('%L%') and
               substr(h413.sum, 9, 1) not like ('%R%') and
               substr(h413.sum, 9, 1) not like ('%}%'))
           and h413.code_guf <> 0
           and h413.identity_number = v_id
           and h413.From_Date =
               (select max(hh413.From_Date)
                  from ld_hilan_413 hh413
                 where hh413.identity_number = h413.identity_number
                   and hh413.code_guf = h413.code_guf)) loop
      --GET OR CREATE BAKASAT HISHTATFUT MEGUF
      v_is_exist_participation_M_guf := true;
    
      v_seq_ezor_ovdim := convert_KD_GUF_seq_ezor_ovdim(r.code_guf);
    
      V_percent_participate := trunc(r.amount / 100, 2);
      if V_percent_participate = 0 then
        V_percent_participate := null;
      end if;
    
      V_SUM_participate := trunc(r.sum / 100, 2);
      if V_SUM_participate = 0 then
        V_SUM_participate := null;
      end if;
    
      if (v_date_bakasha >= to_date('01102017', 'ddmmyyyy')) then
        -- v_seq_ezor_ovdim := 10380;       
        for r2 in (select distinct p.Percent_Participate, p.achuz_guf_final
                     from participation p
                    where p.seq_bakasha = v_seq_bakasha
                      and p.code_participation = 2
                      and p.Seq_Guf = v_seq_ezor_ovdim) loop
          ComparingValues(r2.Percent_Participate,
                          V_percent_participate,
                          'participation',
                          'Percent_Participate');
          ComparingValues(r2.achuz_guf_final,
                          V_percent_participate,
                          'participation',
                          'Percent_Participate');
        end loop;
      
        if nvl(V_SUM_participate, 0) > 0 or
           nvl(V_percent_participate, 0) > 0 then
          if r.code_guf in (710199, 710299) then
            --סמל ארעי אזור עובדים הינו קרן מבטחים
            v_seq_ezor_ovdim := 10380;
          
            merge into participation p1
            using dual
            on (p1.seq_bakasha = v_seq_bakasha and p1.seq_guf = v_seq_ezor_ovdim)
            when matched then
              update
                 set sum_participation = nvl(V_SUM_participate,
                                             sum_participation),
                     achuz_arai        = nvl(V_percent_participate,
                                             achuz_arai),
                     PARTIAL_PERIOD    = nvl(PARTIAL_PERIOD, 1)
              
            
            when not matched then
              insert
                (SEQ_BAKASHA,
                 seq_participation,
                 code_participation,
                 seq_guf,
                 percent_participate,
                 achuz_guf_final,
                 sum_participation,
                 date_payment,
                 achuz_arai,
                 PARTIAL_PERIOD)
              values
                (v_seq_bakasha,
                 participation_seq.nextval,
                 2,
                 v_seq_ezor_ovdim,
                 V_percent_participate,
                 V_percent_participate,
                 V_SUM_participate,
                 r.from_date,
                 V_percent_participate,
                 1) log errors into err_participation
                (v_ora_err_tag$) reject limit unlimited;
          else
            merge into participation p1
            using dual
            on (p1.seq_bakasha = v_seq_bakasha and p1.seq_guf = v_seq_ezor_ovdim)
            when matched then
              update
                 set sum_participation = nvl(V_SUM_participate,
                                             sum_participation),
                     PARTIAL_PERIOD    = nvl(PARTIAL_PERIOD, 1)
              
            
            when not matched then
              insert
                (SEQ_BAKASHA,
                 seq_participation,
                 code_participation,
                 seq_guf,
                 percent_participate,
                 achuz_guf_final,
                 sum_participation,
                 date_payment,
                 PARTIAL_PERIOD)
              values
                (v_seq_bakasha,
                 participation_seq.nextval,
                 2,
                 v_seq_ezor_ovdim,
                 V_percent_participate,
                 V_percent_participate,
                 V_SUM_participate,
                 r.from_date,
                 1) log errors into err_participation
                (v_ora_err_tag$) reject limit unlimited;
          end if;
        end if;
      else
        if nvl(V_SUM_participate, 0) > 0 or
           nvl(V_percent_participate, 0) > 0 then
          if r.code_guf in (710199, 710299) then
            --סמל ארעי אזור עובדים הינו קרן מבטחים
            v_seq_ezor_ovdim := 10380;
          
            merge into participation p1
            using dual
            on (p1.seq_bakasha = v_seq_bakasha and p1.seq_guf = v_seq_ezor_ovdim)
            when matched then
              update
                 set sum_participation   = nvl(V_SUM_participate,
                                               sum_participation),
                     achuz_guf_final     = nvl(V_percent_participate,
                                               achuz_guf_final),
                     percent_participate = nvl(V_percent_participate,
                                               percent_participate),
                     achuz_arai          = nvl(V_percent_participate,
                                               achuz_arai),
                     PARTIAL_PERIOD      = nvl(PARTIAL_PERIOD, 1)
            when not matched then
              insert
                (SEQ_BAKASHA,
                 seq_participation,
                 code_participation,
                 seq_guf,
                 percent_participate,
                 achuz_guf_final,
                 sum_participation,
                 date_payment,
                 achuz_arai,
                 PARTIAL_PERIOD)
              values
                (v_seq_bakasha,
                 participation_seq.nextval,
                 2,
                 v_seq_ezor_ovdim,
                 V_percent_participate,
                 V_percent_participate,
                 V_SUM_participate,
                 r.from_date,
                 V_percent_participate,
                 1) log errors into err_participation
                (v_ora_err_tag$) reject limit unlimited;
          else
            merge into participation p1
            using dual
            on (p1.seq_bakasha = v_seq_bakasha and p1.seq_guf = v_seq_ezor_ovdim)
            when matched then
              update
                 set sum_participation   = nvl(V_SUM_participate,
                                               sum_participation),
                     achuz_guf_final     = nvl(V_percent_participate,
                                               achuz_guf_final),
                     percent_participate = nvl(V_percent_participate,
                                               percent_participate),
                     PARTIAL_PERIOD      = nvl(PARTIAL_PERIOD, 1)
              
            
            when not matched then
              insert
              
                (SEQ_BAKASHA,
                 seq_participation,
                 code_participation,
                 seq_guf,
                 percent_participate,
                 achuz_guf_final,
                 sum_participation,
                 date_payment,
                 PARTIAL_PERIOD)
              values
                (v_seq_bakasha,
                 participation_seq.nextval,
                 2,
                 v_seq_ezor_ovdim,
                 V_percent_participate,
                 V_percent_participate,
                 V_SUM_participate,
                 r.from_date,
                 1) log errors into err_participation
                (v_ora_err_tag$) reject limit unlimited;
          end if;
        end if;
      end if;
    
    end loop;
  
  end;

  -----------------------
  procedure update_Sum_BM_N_T_MCHUSHAVIM is
  begin
    for r in (select bm.Seq_Porshim,
                     b.seq_bakasha,
                     b.mispar_zehut,
                     SUM(nvl(bm.Achuz_Kizba, 0)) as sumkizba
                FROM bney_mishpacha bm
                left join v_bakasha_by_zheut b
                  on b.porshim_seq = bm.seq_porshim
                left join netuney_tik_mechushavim nt
                  on nt.Seq_Bakasha = b.seq_bakasha
                 and nt.code_department = 2
                 and nt.mispar_misra = 0
               where bm.code_relative >= 1
                 and bm.code_relative < 99
                    -- and b.mispar_zehut = V_ID
                 and b.seq_bakasha = v_seq_bakasha
               GROUP BY bm.seq_porshim, b.seq_bakasha, b.mispar_zehut) loop
    
      update netuney_tik_mechushavim ntm
         set ntm.Achuz_Kizba_Sofi = r.sumkizba
       where ntm.seq_bakasha = r.seq_bakasha;
    
    end loop;
  end;
  -------------------------------------------
  procedure RESET_Bney_Mishpaha_FIELDS is
  begin
    update bney_mishpacha bm
       set bm.Achuz_Kizba = null, bm.Code_Relative = null
     where bm.Seq_Porshim = v_porshim_seq;
  end;
  -----------------------------
  procedure update_SHEERIM_bney_mishpaha is
    v_CODE_KIRVA        number;
    v_seq_ben_mishpacha number;
    v_sug_zihuy_bm      number;
    v_bd                date;
  begin
  
    --select * from BNEY_MISHPACHA bm where bm.mispar_zehut_ben_mishpacha= and bm.seq_porshim=
    for r in (select distinct h205.status_code,
                              convert_low_hebrew_to_ascii(h200.last_name) as last_name,
                              convert_low_hebrew_to_ascii(h200.First_Name) as First_Name,
                              to_number(h567.benefit_percent / 100) as benefit_percent,
                              to_number(h537.percent) / 10000 as percent,
                              h219.birth_date,
                              h200.birth_date as birth_date2
                from ld_hilan_567 h567
                left join ld_hilan_537 h537
                  on h537.identity_number = h567.identity_number
                 and h537.job_number = h567.job_number
                 and h537.to_date like ('%9999999%')
                left join ld_hilan_205 h205
                  on h205.identity_number = h567.identity_number
                left join ld_hilan_200 h200
                  on h200.identity_number = h567.identity_number
                left join ld_hilan_219 h219
                  on h219.relative_identity_number = v_SHEER_ID
              
               where h567.identity_number = v_SHEER_ID
                 and h567.job_number = v_job_number
                 and h567.from_date =
                     (select max(hh567.from_date)
                        from ld_hilan_567 hh567
                       where hh567.identity_number = h567.identity_number
                         and hh567.job_number = h567.job_number)
                 and h567.to_date_tokef like ('%9999999%')
              
              ) loop
      if r.birth_date is null then
        v_bd := to_date(r.birth_date2, 'ddmmyyyy');
      else
        v_bd := to_date(r.birth_date, 'ddmmyyyy');
      end if;
      v_CODE_KIRVA := convert_code_kirva(r.status_code);
      if v_CODE_KIRVA is null then
        v_CODE_KIRVA := 1;
      end if;
      v_sug_zihuy_bm := 1;
    
      if validate_id(1, v_SHEER_ID) = false then
        v_sug_zihuy_bm := 2;
      end if;
    
      begin
        select bm.Seq_Bney_Mishpacha
          into v_seq_ben_mishpacha
          from BNEY_MISHPACHA bm
         where bm.seq_porshim = v_porshim_seq
           and bm.mispar_zehut_ben_mishpacha = v_SHEER_ID
           and rownum = 1;
      exception
        when no_data_found then
          v_seq_ben_mishpacha := Bney_Mishpacha_Seq.Nextval;
      end;
    
      merge into BNEY_MISHPACHA bm
      using dual
      on (bm.seq_porshim = v_porshim_seq and bm.mispar_zehut_ben_mishpacha = v_SHEER_ID)
      when matched then
        update
           set bm.code_kirva    = v_CODE_KIRVA,
               bm.achuz_kizba   = r.benefit_percent,
               bm.Code_Relative = v_CODE_KIRVA,
               bm.taarich_leda  = v_bd, --to_date(r.birth_date, 'ddmmyyyy'),
               bm.Sug_Zihuy     = v_sug_zihuy_bm,
               --הוספתי לעדכון את 2 השדות דלהלן על דעתי
               bm.shem_prati     = r.first_name,
               bm.shem_mishpacha = r.last_name
        
      
      when not matched then
        insert
          (bm.Seq_Bney_Mishpacha,
           bm.Seq_Porshim,
           bm.mispar_zehut_ben_mishpacha,
           bm.shem_prati,
           bm.shem_mishpacha,
           bm.code_kirva,
           bm.Code_Relative,
           bm.achuz_kizba,
           bm.Taarich_Leda,
           bm.Sug_Zihuy)
        values
          (v_seq_ben_mishpacha,
           v_porshim_seq,
           v_SHEER_ID,
           r.First_Name,
           r.last_name,
           v_CODE_KIRVA,
           v_CODE_KIRVA,
           r.benefit_percent,
           v_bd, --to_date(r.birth_date, 'ddmmyyyy'),
           v_sug_zihuy_bm) log errors into err_BNEY_MISHPACHA
          (v_ora_err_tag$) reject limit unlimited;
    
      update_ADDRESS_2_Ben_Mishpacha(v_seq_ben_mishpacha);
      update_BANK_ACCOUNT_2_BM(v_seq_ben_mishpacha);
      update_mazav_mishpachti(v_seq_ben_mishpacha);
      update_hafsakat_tashlum(TRUE);
    end loop;
  end;

  ---------------------------------------------------------
  procedure update_bney_mishpaha is
    v_seq_apotropus             number;
    v_is_get_bituach_leumi      number;
    v_is_baal_ishur_tzava       number;
    v_is_baal_tzav_imutz        number;
    v_is_oved                   number;
    v_is_study                  number;
    v_code_min                  number;
    v_code_relative             number;
    v_code_kirva                number;
    v_code_mazav_mishpachti     number;
    v_kd_sug_sheer              number;
    v_month_salary              number;
    v_is_hakira                 number;
    v_is_ishur_eino_oved        number;
    v_is_samuch_al_shulhan_ehad number;
    v_almana_hara               number;
    v_parent_of_common_child    number;
    v_sug_zihuy_bm              number;
  
  begin
  
    for r2 in (
               
               select bm.Seq_Porshim, bm.seq_bney_mishpacha
                 from bney_mishpacha bm
                where bm.Seq_Porshim = v_porshim_seq) loop
      delete from MAZAV_MISHPACHTI mm
       where mm.seq_bney_mishpacha = r2.seq_bney_mishpacha;
    
      delete from ADDRESS a
       where a.Seq_Bney_Mishpacha = r2.seq_bney_mishpacha;
    
      delete from bank_account ba
       where ba.Seq_Bney_Mishpacha = r2.seq_bney_mishpacha;
    
    end loop;
  
    delete from bney_mishpacha where seq_porshim = v_porshim_seq;
  
    for r in (select distinct h219.identity_number,
                              h219.relative_identity_number,
                              h219.birth_date,
                              convert_low_hebrew_to_ascii(h219.first_name) as SHEM_PRATI,
                              convert_low_hebrew_to_ascii(h315.description) as SHEM_MISHPACHA,
                              convert_low_hebrew_to_ascii(h219.code_relative) AS Code_Relative
                from ld_hilan_219 h219
                left join ld_hilan_315 h315
                  on h315.identity_number = h219.identity_number
                 and h315.variable_type = 211
                 and to_number(h315.value) =
                     to_number(h219.relative_identity_number)
               where h219.identity_number = v_id) loop
      v_sug_zihuy_bm := 1;
      if validate_id(1, r.relative_identity_number) = false then
        v_sug_zihuy_bm := 2;
      end if;
    
      v_code_kirva := case
                        when trim(r.Code_Relative) in ('ז', 'י', 'כ', 'נ') then
                         2
                        when trim(r.Code_Relative) in ('ב') then
                         1
                        when trim(r.Code_Relative) in ('מ') then
                         12
                        when trim(r.Code_Relative) in ('ד') then
                         11
                        when trim(r.Code_Relative) in ('א') then
                         3
                        when trim(r.Code_Relative) in ('צ', 'ץ') then
                         14
                      
                      end;
      v_code_min := case
                      when trim(r.Code_Relative) in ('ז', 'י') then
                       1
                      when trim(r.Code_Relative) in ('נ', 'כ', 'מ', 'ץ') then
                       2
                      when trim(r.Code_Relative) in ('ד', 'צ') then
                       1
                    
                    end;
      --יש לבדוק כשיש לאותו בנ"א כמה רשומות עם תאריך נישואין לבדוק מה לעשות...    
      insert into bney_mishpacha
        (seq_porshim,
         seq_bney_mishpacha,
         mispar_zehut_ben_mishpacha,
         shem_prati,
         shem_mishpacha,
         taarich_leda,
         
         code_kirva,
         code_min,
         sug_zihuy)
      values
        (v_porshim_seq,
         bney_mishpacha_seq.nextval,
         r.relative_identity_number,
         r.SHEM_PRATI,
         r.SHEM_MISHPACHA,
         to_date(r.birth_date, 'DDMMYYYY'),
         
         v_code_kirva,
         v_code_min,
         v_sug_zihuy_bm) log errors into err_bney_mishpacha
        (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  end;
  -------------------------------
  procedure update_tkufot_avoda_mehushv is
  begin
    delete from tkufot_avoda_mechushv tam
     where tam.seq_bakasha = v_seq_bakasha;
    for r in (select distinct ta.taarich_me,
                              ta.taarich_ad,
                              ta.achuz_chelkyut,
                              ta.praklit,
                              ta.sach_chodeshim,
                              ta.haim_kana_zchuyot,
                              ta.code_sugey_tkufot,
                              ta.code_sugey_haasaka,
                              ta.code_sugey_zchuyot,
                              --ta.seq_tkufot_avoda_mechushv,
                              ta.ezor_ovdim_be_tkufa,
                              ta.shanim,
                              ta.chodashim,
                              ta.yamim,
                              ta.seq_tkufot_avoda_golmi,
                              ta.seq_tkufot_michutz_lasharut,
                              ta.seq_tkufot_sherut_tsvaii,
                              --ta.seq_bakasha,
                              ta.except_from_tkufa,
                              ta.achuz_mugdal,
                              ta.code_achuz_mugdal,
                              ta.kd_takanon,
                              ta.code_takanon_magal,
                              ta.is_took_money_m_keren
                from tkufot_avoda_mechushv ta
               where ta.seq_bakasha = V_from_COpy_BAKAHSHA) loop
    
      insert into tkufot_avoda_mechushv ta
        (ta.Seq_Tkufot_Avoda_Mechushv,
         ta.Seq_Bakasha,
         ta.taarich_me,
         ta.taarich_ad,
         ta.achuz_chelkyut,
         ta.praklit,
         ta.sach_chodeshim,
         ta.haim_kana_zchuyot,
         ta.code_sugey_tkufot,
         ta.code_sugey_haasaka,
         ta.code_sugey_zchuyot,
         --ta.seq_tkufot_avoda_mechushv,
         ta.ezor_ovdim_be_tkufa,
         ta.shanim,
         ta.chodashim,
         ta.yamim,
         ta.seq_tkufot_avoda_golmi,
         ta.seq_tkufot_michutz_lasharut,
         ta.seq_tkufot_sherut_tsvaii,
         --ta.seq_bakasha,
         ta.except_from_tkufa,
         ta.achuz_mugdal,
         ta.code_achuz_mugdal,
         ta.kd_takanon,
         ta.code_takanon_magal,
         ta.is_took_money_m_keren)
      values
        (TKUFOT_AVODA_MECHUSHAV_SEQ.NEXTVAL,
         v_seq_bakasha,
         r.taarich_me,
         r.taarich_ad,
         r.achuz_chelkyut,
         r.praklit,
         r.sach_chodeshim,
         r.haim_kana_zchuyot,
         r.code_sugey_tkufot,
         r.code_sugey_haasaka,
         r.code_sugey_zchuyot,
         --ta.seq_tkufot_avoda_mechushv,
         r.ezor_ovdim_be_tkufa,
         r.shanim,
         r.chodashim,
         r.yamim,
         r.seq_tkufot_avoda_golmi,
         r.seq_tkufot_michutz_lasharut,
         r.seq_tkufot_sherut_tsvaii,
         --ta.seq_bakasha,
         r.except_from_tkufa,
         r.achuz_mugdal,
         r.code_achuz_mugdal,
         r.kd_takanon,
         r.code_takanon_magal,
         r.is_took_money_m_keren
         
         ) log errors into Err_Tkufot_Avoda_Mechushv
        (v_ora_err_tag$) reject limit unlimited;
    end loop;
  
  end;
  -----------------------------------
  procedure update_ADDRESS_2_Ben_Mishpacha(V_Seq_Bney_Mishpacha number) is
    v_code_address number;
    v_indexAdress  number;
    v_address      varchar2(100);
    v_house        number;
    v_apartment    number;
  begin
  
    delete from address t
     where t.seq_bakasha = v_seq_bakasha
        or t.Seq_Bney_Mishpacha = V_Seq_Bney_Mishpacha;
  
    for r in (select distinct h218.identity_number,
                              h218.code_c_ity,
                              convert_low_hebrew_to_ascii(h218.street) as address,
                              h218.house,
                              /*case
                                when trim(TRANSLATE(h218.house,
                                                    '0123456789-,.',
                                                    ' ')) is null then
                                 h218.house
                                else
                                 null
                              end as house,*/
                              h218.apartment,
                              /*case
                                when trim(TRANSLATE(h218.apartment,
                                                    '0123456789-,.',
                                                    ' ')) is null then
                                 h218.apartment
                                else
                                 null
                              end as APARTMENT,*/
                              -- h218.house as house,
                              --h218.apartment as apartment,
                              h218.from_date,
                              h218.zone
                from ld_hilan_218 h218
               where h218.identity_number = v_SHEER_ID
               order by to_date(h218.from_date, 'ddmmyyyy') asc) loop
    
      insert into address aa
        (seq_bakasha,
         seq_address,
         Seq_Bney_Mishpacha,
         street,
         code_city,
         
         code_address,
         MIKUD,
         CODE_USER_UPDATE,
         date_update
         /*,HOUSE,
         APARTMENT*/)
      values
        (v_seq_bakasha,
         address_seq.nextval,
         V_Seq_Bney_Mishpacha,
         trim(r.address) || ' ' || trim(r.HOUSE) || ' ' ||
         decode(trim(r.APARTMENT), '', '', '/' || trim(r.APARTMENT)),
         v_code_address,
         
         2,
         r.zone,
         1,
         to_date(r.from_date, 'ddmmyyyy')
         /*,r.HOUSE,
         r.APARTMENT*/) log errors into err_address
        (v_ora_err_tag$) reject limit unlimited;
    end loop;
  end;
