  procedure update_HIVUN is
    v_code_address      number;
    v_seq_bakasha_HIVUN number;
  begin
    v_seq_bakasha_HIVUN := null;
    -- delete from hagdala_nimuk t where t.seq_bakasha = v_seq_bakasha;
  
    for r in (
              ------------------------------
              
              select h315.identity_number,
                      h315.job_number,
                      h315.from_date,
                      to_number(h315.value2) / 100 as percentHivun,
                      h315.value2
                from LD_HILAN_315 h315
               where h315.identity_number = v_id
                 and h315.job_number = v_job_number
                 and h315.variable_type = 567) loop
    
      if v_date_start_zakahut <> to_date(r.from_date, 'ddmmyyyy') then
        Create_Another_Bakasha(16,
                               to_date(r.from_date, 'ddmmyyyy'),
                               0,
                               null,
                               2);
        v_seq_bakasha_HIVUN := v_seq_Another_bakasha;
      else
        v_seq_bakasha_HIVUN := v_seq_bakasha;
      
      end if;
    
      insert into HIVUN
        (seq_bakasha,
         seq_hivun,
         code_hivun,
         achuz_hivun,
         date_update,
         date_bakasha,
         user_update)
      values
        (v_seq_bakasha_HIVUN,
         HIVUN_seq.nextval,
         2,
         r.percentHivun,
         to_date(r.from_date, 'ddmmyyyy'),
         to_date(r.from_date, 'ddmmyyyy'),
         0
         
         ) log errors into err_HIVUN
        (v_ora_err_tag$) reject limit unlimited;
      /*
              declare 
        i integer;
      begin
        dbms_errlog.create_error_log('HIVUN','err_HIVUN');
      end;
              */
    
    end loop;
  end;
