  procedure update_HIVUN_2_BAKASHOT is
  begin
  
    dbms_output.enable(99999999999999999999999999999999999999999999999999999999999999999999999);
    for r in (select distinct b.mispar_zehut,
                              b.seq_bakasha,
                              b.seq_prisha,
                              b.seq_porshim,
                              b.code_makor,
                              --to_number(h315.value2) / 100 as hivun_perecent,
                              h315.job_number,
                              (select min(to_date(h2567.from_date_tokef,
                                                  'ddmmyyyy'))
                                 from ld_hilan_567 h2567
                                where h2567.identity_number =
                                      h315.identity_number
                                  and h2567.job_number = h315.job_number) as date_start_zakaut
                from LD_HILAN_315 h315
                left join v_Bakasha_Last_Status b
                  on b.mispar_zehut = h315.identity_number
                left join mgl_log_hasava l
                  on l.mispar_zehut = b.mispar_zehut
               where b.code_sug_bakasha = 1
                 and h315.variable_type = 567
                 and h315.identity_number not in
                     (35355940, 35355098, 30211874, 2275410, 47402912)
                    --כאלה שיש להם 2 JOBNUMBER
                 and h315.identity_number not in
                     (79202,
                      055254882,
                      013132600,
                      045983418,
                      005811641,
                      000011403,
                      001226125,
                      008640971,
                      068899418,
                      070801832,
                      005704143,
                      005725007,
                      000792655,
                      099139956,
                      013583604,
                      065541609,
                      008174906,
                      069658367,
                      061326468,
                      021436969,
                      055435135,
                      055670699,
                      003633260,
                      052523669,
                      068887454,
                      001578913,
                      002530491,
                      047402318,
                      042610956)
                 and l.code_hasava in (12, 15)
              --and h315.identity_number = 79202
              ) loop
      v_id         := r.MISPAR_ZEHUT;
      v_job_number := r.job_number;
      dbms_output.put_line(v_id);
      v_seq_bakasha := r.SEQ_BAKASHA;
    
      v_seq_prisha         := r.SEQ_PRISHA;
      v_porshim_seq        := r.seq_porshim;
      V_code_makor         := r.code_makor;
      v_date_start_zakahut := r.date_start_zakaut;
      update_HIVUN;
    end loop;
    commit;
  
  end;
