  procedure update_VETEK_DETAIL is
    v_code_nimuk     number;
    v_achuz_meushar  number;
    v_meushar_natsiv number;
  begin
  
    delete from VETEK_DETAIL t where t.seq_bakasha = v_seq_bakasha;
  
    for r in (select distinct h539.identity_number,
                              h539.job_number,
                              (case to_number(h539.code_seniority)
                                when 2 then
                                 1
                                when 5 then
                                 2
                              end) as code_seniority,
                              to_number(h539.years) / 100 as years
                from LD_HILAN_539 h539
               where h539.identity_number = v_id
                 and h539.job_number = v_job_number
                 and h539.code_seniority in (2, 5)) loop
    
      insert into VETEK_DETAIL
        (seq_bakasha, SEQ_VETEK_DETAIL, CODE_TYPE_VETEK, YEARS)
      values
        (v_seq_bakasha,
         VETEK_DETAIL_seq.nextval,
         r.code_seniority,
         r.years) log errors into Err_Vetek_Detail
        (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  end;
