  function is_RetirementSectionsOnlyOne return boolean is
  
    v_countRtirmentSctions number;
  begin
    v_is_RetirementSectionsMoreOne := false;
    select count(distinct m10.retirement_section)
      into v_countRtirmentSctions
      from ld_mlm_10 m10
     where m10.is_erased = 0
       and m10.retirement_section not in ('000', '126', '128')
       and m10.identity_number = v_id;
    if (v_countRtirmentSctions > 1) then
      v_is_RetirementSectionsMoreOne := true;
      return false;
    else
      return true;
    end if;
  end;
  -----------------------------------------------------------
  function update_bakasha(p_code_sug_bakasha number) return boolean is
    bakasha_row   err_bakasha%rowtype;
    v_sug_bakasha number;
  begin
  
    v_sug_bakasha := p_code_sug_bakasha;
    for r in (select distinct h537.identity_number,
                              h537.job_number,
                              
                              h537.from_date
                from ld_hilan_537 h537
              
               where h537.identity_number = v_id
                 and h537.job_number = v_job_number) loop
      --      v_sug_bakasha                := 1;
      bakasha_row.date_bakasha     := to_date(r.from_date, 'ddmmyyyy');
      bakasha_row.code_sug_bakasha := v_sug_bakasha;
      bakasha_row.code_source      := V_code_makor;
      bakasha_row.Seq_Prisha       := v_seq_prisha;
      v_seq_bakasha                := null;
    
      set_seq_bakasha;
      --v_date_start_zakahut := to_date(r.date_start_payment, 'DD/MM/YYYY');
      merge into bakasha
      using dual
      on (bakasha.seq_bakasha = v_seq_bakasha)
      when matched then
        update
           set code_sug_bakasha = bakasha_row.code_sug_bakasha,
               date_bakasha     = bakasha_row.date_bakasha,
               code_source      = bakasha_row.code_source
        
      
      when not matched then
        insert
          (seq_bakasha,
           seq_prisha,
           code_sug_bakasha,
           
           code_source,
           date_bakasha)
        values
          (v_seq_bakasha,
           v_seq_prisha,
           bakasha_row.code_sug_bakasha,
           
           bakasha_row.code_source,
           bakasha_row.date_bakasha) log errors into err_bakasha
          (v_ora_err_tag$) reject limit unlimited;
    
      if pk_load_mimshak.count_rowes('err_bakasha', v_where) > 0 then
        return false;
      else
        return true;
      end if;
    end loop;
    return false;
  end;
  --------------------------------------------------------------------------------------------------------
  function update_prisha return boolean is
    prisha_row err_prisha%rowtype;
  begin
    for r in (select distinct h537.identity_number,
                              h537.job_number,
                              substr(h537.office, 1, 3) as misrad_maskoret,
                              substr(h537.office, 4, 4) as ezor_ovdim,
                              substr(h537.office, 8, 2) as CODE_UCHLUSIA,
                              h537.office,
                              
                              to_number(h312.value) as GIMLA_NUMBER
                from ld_hilan_537 h537
                left join ld_hilan_312 h312
                  on h312.identity_number = h537.identity_number
                 and h312.variable_type = 100
                 and h312.job_number = h537.job_number
              /*left join ld_hilan_312 h102
                on h102.identity_number = h537.identity_number
               and h102.variable_type = 102
               and h102.job_number = h537.job_number
              left join ld_hilan_312 h410
                on h410.identity_number = h537.identity_number
               and h410.variable_type = 410
               and h410.job_number = h537.job_number*/
              
               where h537.identity_number = v_ID
                    --*************הורדתי מהערה בשביל השלמת הסבות...
                 and h537.job_number = v_job_number
                 and substr(h537.office, 1, 3) = v_misrad_maskoret
              
              ) loop
    
      --***********
      v_job_number := r.job_number;
      v_seq_prisha := prisha_seq.nextval;
      set_MIS_GIMLA;
      if (nvl(v_mis_Gimla, 0) = 0) then
        v_mis_Gimla := r.GIMLA_NUMBER;
      end if;
      prisha_row.gimla_number := v_mis_Gimla;
      prisha_row.seq_poresh   := v_porshim_seq;
      v_ezor_ovdim            := convert_seq_ezor_ovdim(r.misrad_maskoret,
                                                        r.ezor_ovdim);
    
      prisha_row.seq_ezor_ovdim := v_ezor_ovdim;
    
      merge into prisha
      using dual
      on (prisha.seq_prisha = v_seq_prisha)
      when matched then
        update
           set gimla_number   = prisha_row.gimla_number,
               seq_ezor_ovdim = prisha_row.seq_ezor_ovdim
      when not matched then
        insert
          (seq_prisha, seq_poresh, seq_ezor_ovdim, gimla_number)
        values
          (v_seq_prisha,
           v_porshim_seq,
           v_ezor_ovdim,
           prisha_row.gimla_number) log errors into err_prisha
          (v_ora_err_tag$) reject limit unlimited;
    end loop;
    if pk_load_mimshak.count_rowes('err_prisha', v_where) > 0 then
      return false;
    else
      return true;
    end if;
  
  end;
