  function mergeData return clob is
    v_report_html clob;
    V_ERR         varchar2(100);
  begin
  
    execute immediate 'alter session set nls_language= ''american''';
    execute immediate 'alter session set nls_date_language=''english''';
    execute immediate 'alter session set nls_date_format=''dd-mon-yyyy''';
  
    --regular bakashot
  
    for r in (select distinct l200.identity_number
                from ld_hilan_200 l200
                join v_Bakasha_by_zheut b
                  on b.mispar_zehut = l200.identity_number
              --and b."CODE_SUG_BAKASHA" = 1
              -- and b.date_start_zakaut is null
              /* where to_number(l200.identity_number) in
              (select po.mispar_zehut
                 from poresh po
                where po.mispar_zehut = l200.identity_number)*/
               where --b."DATE_BAKASHA" >= to_date('01102017', 'ddmmyyyy')     and
               l200.identity_number in
               (select h312.identity_number
                  from ld_hilan_312 h312
                 where h312.identity_number = l200.identity_number
                   and h312.variable_type = 102
                      
                   and to_number(h312.value) not in
                       (126, 128, 226, 228, 326, 426, 526, 528, 428, 328, 628))
              -- and rownum <= 1500             
           and l200.identity_number in (12171104)
              /*and l200.identity_number not in
              (select l.mispar_zehut
                 from mgl_log_hasava l
                where l.mispar_zehut = l200.identity_number
                  and l.code_hasava in ( --12, 13
                                        12,
                                        13,
                                        16,
                                        15))*/
               order by l200.identity_number
              
              )
    
     loop
      --begin  --exception
    
      --------------
      ResetFields;
      V_ERR          := null;
      v_is_do_commit := true;
    
      v_id           := r.identity_number;
      v_ora_err_tag$ := to_char(v_id);
      v_where        := ' where ora_err_tag$= ''' || v_ora_err_tag$ || '''';
    
      --DELETE_CONVERTED_DATA;
      if validate_id(1, r.identity_number) = false then
        V_sug_zihuy := 2;
        --  v_is_do_commit := false;
        --  goto endloop1;
      else
        V_sug_zihuy := 1;
      end if;
      --LOPP PRISHOT
      for r2 in (select distinct h537.identity_number,
                                 substr(h537.office, 1, 3) as misrad_maskoret,
                                 --הוספתי בשביל למצוא את ה SEQ אזור עובדים ע"ס 2 השדות הנ"ל
                                 substr(h537.office, 4, 4) as ezor_ovdim_hilan,
                                 h537.job_number
                   from ld_hilan_537 h537
                  where h537.identity_number = v_id
                       
                       --ורק פרישות שהם לא של שארים 
                    and exists
                  (select *
                           from ld_hilan_312 h312
                          where h312.identity_number = h537.identity_number
                            and h312.job_number = h537.job_number
                            and h312.variable_type = 102
                            and to_number(h312.value) not in
                                (126,
                                 128,
                                 226,
                                 228,
                                 326,
                                 426,
                                 526,
                                 528,
                                 428,
                                 328,
                                 628))) loop
        v_job_number := r2.job_number;
        if nvl(v_misrad_maskoret, 0) <> r2.misrad_maskoret then
        
          v_misrad_maskoret  := r2.misrad_maskoret;
          v_ezor_ovdim_HILAN := r2.ezor_ovdim_hilan;
          set_global_fields(1, false);
          if (v_seq_prisha is null) then
          
            -- if update_prisha = false or update_bakasha(1) = false or
            --  update_bakasha_regila = false then
            --ADD ROW TO CHRIGIM...
            V_ERR := 'merge - SEQ__prisha not found';
          
            v_is_do_commit := false;
            goto endloop1;
            --v_report_html := v_report_html ||
            --               info_about_errors_and_commit(v_is_do_commit, '');
            --continue;
            --          end if;
          else
            if v_seq_bakasha is null then
              V_ERR := 'merge - SEQ_BAKASHA not found';
            
              v_is_do_commit := false;
              goto endloop1;
            end if;
          end if;
          --add row log succses
          add_row_to_mgl_log_hasava(v_id, 15, '');
        
          if (v_date_bakasha >= to_date('01102017', 'ddmmyyyy')) then
            Find_charigim_data;
          else
            ------------
            set_MIS_GIMLA;
            ---------------
            SET_CODE_SEIF_PRISHA_HILAN;
          end if;
          merge_bakasha_regila_AND_PORES;
        
          --not must tables
          if (V_is_updated_PORESH_DATA = false) then
            V_is_updated_PORESH_DATA := TRUE;
            merge_PORESH;
            update_mazav_mishpachti(null); --V
            update_ADDRESS; --V
            update_PRISHA_BANK_ACCOUNT; --V       
            update_bney_mishpaha; --V
          end if;
          V_CHELKIYUT_MESHUKLELET := null;
          update_hafsakat_tashlum(false);
          if (v_is_HOZE_BHIRIM) then
            --טיפול מיוחד לחוזה בכירים
            HOZE_BHIRM_2_netny_tik_mchshvm(false);
          else
            merge_netuney_tik_mechushavim; --V
          end if;
          update_HIVUN;
        
          update_DARGA_VEDERUG_TIK; --V  
          update_VETEK_DETAIL;
          merge_actions_log;
        
          --------------השתתפות מגוף---------
          SET_IS_participation_M_guf;
          -- dbms_output.enable(99999999999999999999);
        
          --השתתפות מגוף
          if (v_is_exist_participation_M_guf) then
          
            v_seq_bakasha := null;
            set_global_fields(7, false);
            if v_seq_bakasha is null then
              --כשלא מצא בקשת השתתפות מגוף לאותה זהות
              if update_bakasha(7) = false or update_bakasha_regila = false then
                v_is_do_commit := false;
                goto endloop1;
              
              end if;
              -- dbms_output.put_line('השתתפות מגוף חדש' || V_ID);
              if (v_is_HOZE_BHIRIM) then
                --טיפול מיוחד לחוזה בכירים
                HOZE_BHIRM_2_netny_tik_mchshvm(true);
              else
                update_netuney_tik_mechushavim; --V
              end if;
              update_HIVUN;
              update_DARGA_VEDERUG_TIK; --V  
              update_VETEK_DETAIL;
              update_participation_m_guf;
              merge_actions_log;
              update_actions_log;
            
            else
              ----אם מצא בקשת השתתפות מגוף יש לעדכן את ה PARTIPICATION
              --dbms_output.put_line('עדכון השתתפות מגוף' || V_ID);
              update_participation_m_guf;
            end if;
          end if;
        
          -------------סוף השתתפות מגוף----------
        
        end if;
      end loop;
      --I'M inserting
      -- commit;
    
      <<endloop1>>
    
      v_report_html := v_report_html ||
                      
                       info_about_errors_and_commit(v_is_do_commit, V_ERR);
    end loop;
    -- UPDATE_PTIRA_DATE;
    commit;
    return v_report_html;
  
  end;

  ------------------------------------

  function MERGE_SHEERIM return clob is
    v_report_html          clob;
    v_is_do_commit         boolean;
    v_is_update_Porsh_data boolean;
    V_ERR                  varchar2(100);
  
  begin
  
    execute immediate 'alter session set nls_language= ''american''';
    execute immediate 'alter session set nls_date_language=''english''';
    execute immediate 'alter session set nls_date_format=''dd-mon-yyyy''';
  
    --  DELETE_BNEY_MISHPACHA;
    --LOOP PORSHIM
    for r in (select distinct h312.value as identity_number
              
                from Ld_Hilan_312 h312
                left join LD_HILAN_312 hh312
                  on hh312.identity_number = h312.identity_number
                 and hh312.job_number = h312.job_number
                 and hh312.variable_type = 102
               where h312.value = 001759521
                 and h312.variable_type = 410
                 and hh312.value in
                     (126, 128, 226, 228, 326, 426, 526, 528, 428, 328, 628)
                 and exists (select p.mispar_zehut
                        from PORESH p
                       where p.mispar_zehut = h312.Value)
                    
                 and not exists
               (select *
                        from mgl_log_hasava l
                       where l.mispar_zehut = h312.value
                         and l.code_hasava in ( --12, 13
                                               16,
                                               17))
              
               order by h312.value) loop
      ResetFields;
      V_ERR          := null;
      v_is_do_commit := true;
      v_id           := r.identity_number;
      --v_SHEER_ID     := r.bm_identity_number;
      v_ora_err_tag$ := to_char(v_id);
      v_where        := ' where ora_err_tag$= ''' || v_ora_err_tag$ || '''';
    
      /*if validate_id(1, r.identity_number) = false then
      
        v_is_do_commit := false;
        goto endloop1;
      end if;*/
    
      -------------**********
      --LOPP MISRADEY PRISHA
      for r2 in (select distinct h312.value as identity_number,
                                 substr(h537.office, 1, 3) as misrad_maskoret,
                                 h537.job_number
                   from ld_hilan_537 h537
                   left join ld_hilan_312 h312
                     on h312.identity_number = h537.identity_number
                    and h312.job_number = h537.job_number
                    and h312.variable_type = 410
                   left join LD_HILAN_312 hh312
                     on hh312.identity_number = h312.identity_number
                    and hh312.job_number = h312.job_number
                    and hh312.variable_type = 102
                  where h312.variable_type = 410
                    and h312.value is not null
                    and hh312.value in (126,
                                        128,
                                        226,
                                        228,
                                        326,
                                        426,
                                        526,
                                        528,
                                        428,
                                        328,
                                        628)
                    and h312.value = r.identity_number) loop
      
        v_job_number      := r2.job_number;
        v_misrad_maskoret := r2.misrad_maskoret;
        set_global_fields(1, false);
        if (v_seq_prisha is null) then
        
          --ADD ROW TO CHRIGIM...
          Add_warning_data_conversion_ROW('SEQ__prisha not found',
                                          'SEQ_prisha not found',
                                          'PRISHA',
                                          'SEQ_prisha');
          v_is_do_commit := false;
          goto endloop1;
        
        else
          if v_seq_bakasha is null then
            Add_warning_data_conversion_ROW('SEQ_BAKASHA not found',
                                            'SEQ_BAKASHA not found',
                                            'BAKASHA',
                                            'SEQ_BAKASHA');
          
            v_is_do_commit := false;
            goto endloop1;
          end if;
        end if;
      
        set_Taarich_PRISHA_PTIRA;
        --איפוס שדות CODE_RELATIVE ו ACHUZ_KIZTBA
        RESET_Bney_Mishpaha_FIELDS;
      
        --LOOP SHEERIM
        v_is_update_Porsh_data := false;
        for r3 in (select distinct h312.identity_number as bm_identity_number,
                                   h312.job_number
                     from ld_hilan_312 h312
                    where h312.value = r.identity_number
                      and h312.job_number = r2.job_number
                      and h312.variable_type = 410) loop
        
          v_SHEER_ID := r3.bm_identity_number;
          if (v_date_ptira <= v_date_prisha) then
          
            --טיפול בשאר בשירות
          
            if (v_is_update_Porsh_data = false) then
              v_is_update_Porsh_data := true;
              add_row_to_mgl_log_hasava(v_id, 17, 'שאר בשירות');
            
              /*              v_id := r3.bm_identity_number;
              mergeDataHandling;
              v_id := r.identity_number;*/
            end if;
            update_SHEERIM_bney_mishpaha;
          
            -------------------השתתפות מגוף לשאר בשירות------------           
            SET_IS_participation_M_guf;
            if (v_is_exist_participation_M_guf) then
              v_seq_bakasha := null;
              v_id          := r.identity_number;
              set_global_fields(7, false);
              set_MIS_GIMLA;
              participation_m_guf_Handling(7);
            end if;
            -----------------------סוף השתתפות מגוף לשאר בשרות-----------------
          else
            --טיפול בשאר פנסיוני
            V_from_COpy_BAKAHSHA := v_seq_bakasha;
            v_seq_bakasha        := null;
            set_global_fields(13, false);
            -- יש ליצור בקשת שאר פנסיוני במקרה שלא מצא..
            if (v_seq_bakasha is null and v_seq_prisha is not null) then
              v_id := r3.bm_identity_number;
              if (update_bakasha(13) = false or
                 update_bakasha_regila = false) then
              
                V_ERR          := 'Failed to create a Bakashat Sheer Pensyony';
                v_is_do_commit := false;
                goto endloop1;
              else
              
                V_CHELKIYUT_MESHUKLELET := null;
                -- update_hafsakat_tashlum; --הכנסתי את הטיםול update_SHEERIM_bney_mishpahaל 
                update_netuney_tik_mechushavim; --V
                update_HIVUN;
              
                update_DARGA_VEDERUG_TIK; --V  
                update_VETEK_DETAIL;
                merge_actions_log;
                update_actions_log;
                update_SHEERIM_bney_mishpaha;
                v_id := r3.bm_identity_number;
                add_row_to_mgl_log_hasava(r.identity_number,
                                          17,
                                          v_SHEER_ID || '-' ||
                                          'שאר פנסיוני - נוצרה בקשה חדשה מסוג שאר פנסיוני');
              
              end if;
            
            else
              if v_seq_bakasha is not null then
              
                if (v_is_update_Porsh_data = false) then
                  v_is_update_Porsh_data := true;
                
                  --mergeDataHandling;
                  add_row_to_mgl_log_hasava(v_id,
                                            17,
                                            v_SHEER_ID || '-' ||
                                            'שאר פנסיוני - עדכון בקשת שאר קיימת');
                  merge_actions_log;
                
                end if;
                update_SHEERIM_bney_mishpaha;
              
              end if;
            end if;
            v_id := r3.bm_identity_number;
            merge_netuny_tik_2SHeeR_PNSYNY;
            update_tkufot_avoda_mehushv;
          
            --השתתפות מגוף לשאר פנסיוני
          
            SET_IS_participation_M_guf;
            if (v_is_exist_participation_M_guf) then
              v_seq_bakasha := null;
              v_id          := r.identity_number;
              set_global_fields(23, false);
              set_MIS_GIMLA;
              v_id := r3.bm_identity_number;
              participation_m_guf_Handling(23);
            
            end if;
            v_id := r.identity_number;
            ------------------סוף השתתפות מגוף לשאר פנסיוני-----------
            --END SHEER PENSYONY
          end if;
        
        end loop;
        update_Sum_BM_N_T_MCHUSHAVIM;
      end loop;
    
      <<endloop1>>
    
      v_report_html := v_report_html ||
                      
                       info_about_errors_and_commit(v_is_do_commit, V_ERR);
    end loop;
  
    commit;
    return v_report_html;
  end;
  -------------------------------------------
  function MERGE_SHEERIM_STEP_B return clob is
    v_report_html          clob;
    v_is_do_commit         boolean;
    v_is_update_Porsh_data boolean;
    V_ERR                  varchar2(100);
  
  begin
  
    execute immediate 'alter session set nls_language= ''american''';
    execute immediate 'alter session set nls_date_language=''english''';
    execute immediate 'alter session set nls_date_format=''dd-mon-yyyy''';
  
    --  DELETE_BNEY_MISHPACHA;
    --LOOP PORSHIM
    for r in (select distinct h312.value as identity_number
              
                from Ld_Hilan_312 h312
                left join LD_HILAN_312 hh312
                  on hh312.identity_number = h312.identity_number
                    --and hh312.job_number = h312.job_number
                 and hh312.variable_type = 102
              
               where h312.variable_type = 410
                 and hh312.value in
                     (126, 128, 226, 228, 326, 426, 526, 528, 428, 328, 628)
                 and exists
               (select p.mispar_zehut
                        from PORESH p
                       where p.mispar_zehut = h312.Value)
                    
                    /*  and not exists
                    (select *
                             from mgl_log_hasava l
                            where l.mispar_zehut = h312.value
                              and l.code_hasava in ( --12, 13
                                                    16,
                                                    17))*/
                 and exists((select *
                              from mgl_log_hasava l
                             where l.mispar_zehut = h312.value
                               and l.code_hasava = 12
                               and l.update_date >
                                   to_date('21072019', 'ddmmyyyy'))
                            
                            )
              
              -- and rowNUM <= 10
              --and h312.value in (006537955)
               order by h312.value) loop
      ResetFields;
    
      V_ERR          := null;
      v_is_do_commit := true;
      v_id           := r.identity_number;
      --v_SHEER_ID     := r.bm_identity_number;
      v_ora_err_tag$ := to_char(v_id);
      v_where        := ' where ora_err_tag$= ''' || v_ora_err_tag$ || '''';
    
      /*if validate_id(1, r.identity_number) = false then
      
        v_is_do_commit := false;
        goto endloop1;
      end if;*/
    
      -------------**********
      --LOPP MISRADEY PRISHA
      for r2 in (select distinct h312.value as identity_number,
                                 substr(h537.office, 1, 3) as misrad_maskoret,
                                 substr(h537.office, 4, 4) as ezor_ovdim,
                                 h537.job_number
                   from ld_hilan_537 h537
                   left join ld_hilan_312 h312
                     on h312.identity_number = h537.identity_number
                       -- and h312.job_number = h537.job_number
                    and h312.variable_type = 410
                   left join LD_HILAN_312 hh312
                     on hh312.identity_number = h312.identity_number
                    and hh312.job_number = h537.job_number
                    and hh312.variable_type = 102
                  where h312.variable_type = 410
                    and h312.value is not null
                    and hh312.value in (
                                        ---------הוספתי עוד 
                                        /*115,
                                        118,
                                        215,
                                        217,
                                        315,
                                        415,*/
                                        -------------------
                                        
                                        126,
                                        128,
                                        226,
                                        228,
                                        326,
                                        426,
                                        526,
                                        528,
                                        428,
                                        328,
                                        628)
                    and h312.value = r.identity_number) loop
      
        v_job_number       := r2.job_number;
        v_misrad_maskoret  := r2.misrad_maskoret;
        v_ezor_ovdim_HILAN := r2.ezor_ovdim;
        set_global_fields(1, false);
      
        select b.seq_ezor_ovdim
          into v_ezor_ovdim_Sheer_mpm
          from V_BAKASHA_BY_ZHEUT b
         where b.mispar_zehut = v_ID
           and rownum = 1;
      
        v_ezor_ovdim_Sheer_hilan := convert_seq_ezor_ovdim(v_misrad_maskoret,
                                                           v_ezor_ovdim_HILAN);
      
        if (v_seq_prisha is null) then
        
          --ADD ROW TO CHRIGIM...
          Add_warning_data_conversion_ROW('SEQ__prisha not found',
                                          'SEQ_prisha not found',
                                          'PRISHA',
                                          'SEQ_prisha');
          v_is_do_commit := false;
          goto endloop1;
        
        else
          if v_seq_bakasha is null then
            Add_warning_data_conversion_ROW('SEQ_BAKASHA not found',
                                            'SEQ_BAKASHA not found',
                                            'BAKASHA',
                                            'SEQ_BAKASHA');
          
            v_is_do_commit := false;
            goto endloop1;
          end if;
        end if;
      
        if (nvl(v_ezor_ovdim_Sheer_hilan, 999) <> 999 and
           nvl(v_ezor_ovdim_Sheer_hilan, 999) <>
           nvl(v_ezor_ovdim_Sheer_mpm, 999)) then
          update prisha p
             set p.seq_ezor_ovdim = v_ezor_ovdim_Sheer_hilan
           where p.seq_prisha = v_seq_prisha;
        end if;
      
        set_Taarich_PRISHA_PTIRA;
        --איפוס שדות CODE_RELATIVE ו ACHUZ_KIZTBA
        RESET_Bney_Mishpaha_FIELDS;
      
        --LOOP SHEERIM
        v_is_update_Porsh_data := false;
        for r3 in (select distinct h312.identity_number as bm_identity_number,
                                   h312.job_number
                     from ld_hilan_312 h312
                    where h312.value = r.identity_number
                         --הורדתי התייחסות לJN בגלל שראינו שאין קשר בין Jמ 
                         -- and h312.job_number = r2.job_number
                      and h312.variable_type = 410) loop
        
          v_SHEER_ID := r3.bm_identity_number;
          if (v_date_ptira <= v_date_prisha) then
          
            --טיפול בשאר בשירות
          
            if (v_is_update_Porsh_data = false) then
              v_is_update_Porsh_data := true;
              add_row_to_mgl_log_hasava(v_id, 17, 'שאר בשירות');
            
              /*              v_id := r3.bm_identity_number;
              mergeDataHandling;
              v_id := r.identity_number;*/
            end if;
            update_SHEERIM_bney_mishpaha;
          
            -------------------השתתפות מגוף לשאר בשירות------------           
            SET_IS_participation_M_guf;
            if (v_is_exist_participation_M_guf) then
              v_seq_bakasha := null;
              v_id          := r.identity_number;
              set_global_fields(7, false);
              set_MIS_GIMLA;
              participation_m_guf_Handling(7);
            end if;
            -----------------------סוף השתתפות מגוף לשאר בשרות-----------------
          else
            --טיפול בשאר פנסיוני
            V_from_COpy_BAKAHSHA := v_seq_bakasha;
            v_seq_bakasha        := null;
            set_global_fields(13, false);
            -- יש ליצור בקשת שאר פנסיוני במקרה שלא מצא..
            if (v_seq_bakasha is null and v_seq_prisha is not null) then
              v_id := r3.bm_identity_number;
              if (update_bakasha(13) = false or
                 update_bakasha_regila = false) then
              
                V_ERR          := 'Failed to create a Bakashat Sheer Pensyony';
                v_is_do_commit := false;
                goto endloop1;
              else
              
                V_CHELKIYUT_MESHUKLELET := null;
                -- update_hafsakat_tashlum; --הכנסתי את הטיםול update_SHEERIM_bney_mishpahaל 
                update_netuney_tik_mechushavim; --V
                update_HIVUN;
              
                update_DARGA_VEDERUG_TIK; --V  
                update_VETEK_DETAIL;
                merge_actions_log;
                update_actions_log;
                update_SHEERIM_bney_mishpaha;
                v_id := r3.bm_identity_number;
                add_row_to_mgl_log_hasava(r.identity_number,
                                          17,
                                          v_SHEER_ID || '-' ||
                                          'שאר פנסיוני - נוצרה בקשה חדשה מסוג שאר פנסיוני');
              
              end if;
            
            else
              if v_seq_bakasha is not null then
              
                if (v_is_update_Porsh_data = false) then
                  v_is_update_Porsh_data := true;
                
                  --mergeDataHandling;
                  add_row_to_mgl_log_hasava(v_id,
                                            17,
                                            v_SHEER_ID || '-' ||
                                            'שאר פנסיוני - עדכון בקשת שאר קיימת');
                  merge_actions_log;
                
                end if;
                update_SHEERIM_bney_mishpaha;
              
              end if;
            end if;
            v_id := r3.bm_identity_number;
            merge_netuny_tik_2SHeeR_PNSYNY;
            update_tkufot_avoda_mehushv;
          
            --השתתפות מגוף לשאר פנסיוני
          
            SET_IS_participation_M_guf;
            if (v_is_exist_participation_M_guf) then
              v_seq_bakasha := null;
              v_id          := r.identity_number;
              set_global_fields(23, false);
              set_MIS_GIMLA;
              v_id := r3.bm_identity_number;
              participation_m_guf_Handling(23);
            
            end if;
            v_id := r.identity_number;
            ------------------סוף השתתפות מגוף לשאר פנסיוני-----------
            --END SHEER PENSYONY
          end if;
        
        end loop;
        update_Sum_BM_N_T_MCHUSHAVIM;
      end loop;
    
      <<endloop1>>
    
      v_report_html := v_report_html ||
                      
                       info_about_errors_and_commit(v_is_do_commit, V_ERR);
    end loop;
  
    commit;
    return v_report_html;
  end;

  ---------------------------
  function MERGE_SHEERIM_WITH_MLM22 return clob is
    v_report_html          clob;
    v_is_do_commit         boolean;
    v_is_update_Porsh_data boolean;
    V_ERR                  varchar2(100);
  
  begin
  
    execute immediate 'alter session set nls_language= ''american''';
    execute immediate 'alter session set nls_date_language=''english''';
    execute immediate 'alter session set nls_date_format=''dd-mon-yyyy''';
  
    DELETE_BNEY_MISHPACHA;
    --LOOP PORSHIM
    for r in (select distinct m22.Pensioner_Identity as identity_number
                from LD_HILAN_312 hh312
                left join Ld_Mlm_22 m22
                  on m22.identity_number = hh312.identity_number
                 and m22.is_erased = 0
               where hh312.variable_type = 102
                 and nvl(m22.Pensioner_Identity, 0) > 0
                 and hh312.value in (15,
                                     126,
                                     128,
                                     226,
                                     228,
                                     326,
                                     426,
                                     526,
                                     528,
                                     428,
                                     328,
                                     628)
                 and not exists
               (select *
                        from LD_HILAN_312 h312
                       where h312.identity_number = hh312.identity_number
                         and h312.variable_type = 410)
                 and exists
               (select p.mispar_zehut
                        from PORESH p
                       where p.mispar_zehut = m22.Pensioner_Identity)
                 and m22.Pensioner_Identity = 068884360
                    
                 and not exists
               (select *
                        from mgl_log_hasava l
                       where l.mispar_zehut = m22.Pensioner_Identity
                         and l.code_hasava in ( --12, 13
                                               
                                               16,
                                               17))
              
               order by m22.Pensioner_Identity) loop
      ResetFields;
      V_ERR          := null;
      v_is_do_commit := true;
    
      v_id := r.identity_number;
      --v_SHEER_ID     := r.bm_identity_number;
      v_ora_err_tag$ := to_char(v_id);
      v_where        := ' where ora_err_tag$= ''' || v_ora_err_tag$ || '''';
    
      /*if validate_id(1, r.identity_number) = false then
      
        v_is_do_commit := false;
        goto endloop1;
      end if;*/
    
      -------------**********
      --LOPP MISRADEY PRISHA
      for r2 in (select distinct h537.identity_number,
                                 substr(h537.office, 1, 3) as misrad_maskoret,
                                 h537.job_number
                   from ld_hilan_537 H537
                   left join Ld_Mlm_22 m22
                     on m22.pensioner_identity = H537.IDENTITY_NUMBER
                    and m22.is_erased = 0
                   left join LD_HILAN_312 hh312
                     on hh312.identity_number = m22.identity_number
                    and hh312.job_number = h537.job_number
                    and hh312.variable_type = 102
                  Where hh312.value in (126,
                                        128,
                                        226,
                                        228,
                                        326,
                                        426,
                                        526,
                                        528,
                                        428,
                                        328,
                                        628)
                    and h537.identity_number = r.identity_number) loop
      
        v_job_number      := r2.job_number;
        v_misrad_maskoret := r2.misrad_maskoret;
        set_global_fields(1, false);
        if (v_seq_prisha is null) then
        
          --ADD ROW TO CHRIGIM...
          Add_warning_data_conversion_ROW('SEQ__prisha not found',
                                          'SEQ_prisha not found',
                                          'PRISHA',
                                          'SEQ_prisha');
          v_is_do_commit := false;
          goto endloop1;
        
        else
          if v_seq_bakasha is null then
            Add_warning_data_conversion_ROW('SEQ_BAKASHA not found',
                                            'SEQ_BAKASHA not found',
                                            'BAKASHA',
                                            'SEQ_BAKASHA');
          
            v_is_do_commit := false;
            goto endloop1;
          end if;
        end if;
      
        set_Taarich_PRISHA_PTIRA;
        --איפוס שדות CODE_RELATIVE ו ACHUZ_KIZTBA
        RESET_Bney_Mishpaha_FIELDS;
      
        --LOOP SHEERIM
        v_is_update_Porsh_data := false;
        for r3 in (select m22.identity_number as bm_identity_number,
                          hh312.job_number
                     from Ld_Mlm_22 m22
                     left join LD_HILAN_312 hh312
                       on hh312.identity_number = m22.identity_number
                      and hh312.variable_type = 102
                    Where m22.pensioner_identity = r2.identity_number
                      and hh312.job_number = r2.job_number
                      and m22.is_erased = 0
                      and hh312.value in (126,
                                          128,
                                          226,
                                          228,
                                          326,
                                          426,
                                          526,
                                          528,
                                          428,
                                          328,
                                          628)) loop
        
          v_SHEER_ID := r3.bm_identity_number;
          if (v_date_ptira <= v_date_prisha) then
          
            --טיפול בשאר בשירות
          
            if (v_is_update_Porsh_data = false) then
              v_is_update_Porsh_data := true;
              add_row_to_mgl_log_hasava(v_id, 17, 'שאר בשירות');
            
              /*              v_id := r3.bm_identity_number;
              mergeDataHandling;
              v_id := r.identity_number;*/
            end if;
            update_SHEERIM_bney_mishpaha;
            -------------------השתתפות מגוף לשאר בשירות------------           
            SET_IS_participation_M_guf;
            if (v_is_exist_participation_M_guf) then
              v_seq_bakasha := null;
              v_id          := r.identity_number;
              set_global_fields(7, false);
              set_MIS_GIMLA;
              participation_m_guf_Handling(7);
            end if;
            -----------------------סוף השתתפות מגוף לשאר בשרות-----------------
          
          else
            --טיפול בשאר פנסיוני
            V_from_COpy_BAKAHSHA := v_seq_bakasha;
            v_seq_bakasha        := null;
            set_global_fields(13, false);
            -- יש ליצור בקשת שאר פנסיוני במקרה שלא מצא..
            if (v_seq_bakasha is null and v_seq_prisha is not null) then
              v_id := r3.bm_identity_number;
              if (update_bakasha(13) = false or
                 update_bakasha_regila = false) then
              
                V_ERR          := 'Failed to create a Bakashat Sheer Pensyony';
                v_is_do_commit := false;
                goto endloop1;
              else
              
                V_CHELKIYUT_MESHUKLELET := null;
                -- update_hafsakat_tashlum; --הכנסתי את הטיםול update_SHEERIM_bney_mishpahaל 
                update_netuney_tik_mechushavim; --V
                update_HIVUN;
              
                update_DARGA_VEDERUG_TIK; --V  
                update_VETEK_DETAIL;
                merge_actions_log;
                update_actions_log;
                update_SHEERIM_bney_mishpaha;
                v_id := r3.bm_identity_number;
                add_row_to_mgl_log_hasava(r.identity_number,
                                          17,
                                          v_SHEER_ID || '-' ||
                                          'שאר פנסיוני - נוצרה בקשה חדשה מסוג שאר פנסיוני');
              
              end if;
            
            else
              if v_seq_bakasha is not null then
              
                if (v_is_update_Porsh_data = false) then
                  v_is_update_Porsh_data := true;
                
                  --mergeDataHandling;
                  add_row_to_mgl_log_hasava(v_id,
                                            17,
                                            v_SHEER_ID || '-' ||
                                            'שאר פנסיוני - עדכון בקשת שאר קיימת');
                
                end if;
                update_SHEERIM_bney_mishpaha;
              
              end if;
            end if;
            v_id := r3.bm_identity_number;
            merge_netuny_tik_2SHeeR_PNSYNY;
            update_tkufot_avoda_mehushv;
            --השתתפות מגוף לשאר פנסיוני
          
            SET_IS_participation_M_guf;
            if (v_is_exist_participation_M_guf) then
              v_seq_bakasha := null;
              v_id          := r.identity_number;
              set_global_fields(23, false);
              set_MIS_GIMLA;
              v_id := r3.bm_identity_number;
              participation_m_guf_Handling(23);
            
            end if;
            v_id := r.identity_number;
            ------------------סוף השתתפות מגוף לשאר פנסיוני-----------
          
            --END SHEER PENSYONY
          end if;
        
        end loop;
        update_Sum_BM_N_T_MCHUSHAVIM;
      end loop;
    
      <<endloop1>>
    
      v_report_html := v_report_html ||
                      
                       info_about_errors_and_commit(v_is_do_commit, V_ERR);
    end loop;
  
    commit;
    return v_report_html;
  end;

