           on hh312.identity_number = m22.identity_number
          and hh312.variable_type = 102
        Where m22.pensioner_identity = r2.identity_number
          and hh312.job_number = r2.job_number
          and m22.is_erased = 0
          and hh312.value in (126,
                              128,
                              226,
                              228,
                              326,
                              426,
                              526,
                              528,
                              428,
                              328,
                              628)) loop*/
      
        v_SHEER_ID := r.mispar_zehut_ben_mishpacha;
        if (v_date_ptira <= v_date_prisha) then
        
          --טיפול בשאר בשירות
        
          if (v_is_update_Porsh_data = false) then
            v_is_update_Porsh_data := true;
            add_row_to_mgl_log_hasava(v_id, 17, 'שאר בשירות');
          
            /*              v_id := r3.bm_identity_number;
            mergeDataHandling;
            v_id := r.identity_number;*/
          end if;
          update_SHEERIM_bney_mishpaha;
          -------------------השתתפות מגוף לשאר בשירות------------           
          SET_IS_participation_M_guf;
          if (v_is_exist_participation_M_guf) then
            v_seq_bakasha := null;
            v_id          := r.identity_number;
            set_global_fields(7, false);
            set_MIS_GIMLA;
            participation_m_guf_Handling(7);
          end if;
          -----------------------סוף השתתפות מגוף לשאר בשרות-----------------
        
        else
          --טיפול בשאר פנסיוני
          V_from_COpy_BAKAHSHA := v_seq_bakasha;
          v_seq_bakasha        := null;
          set_global_fields(13, false);
          -- יש ליצור בקשת שאר פנסיוני במקרה שלא מצא..
          if (v_seq_bakasha is null and v_seq_prisha is not null) then
            ------******
            v_id := r.mispar_zehut_ben_mishpacha;
            if (update_bakasha(13) = false or update_bakasha_regila = false) then
            
              V_ERR          := 'Failed to create a Bakashat Sheer Pensyony';
              v_is_do_commit := false;
              goto endloop1;
            else
            
              V_CHELKIYUT_MESHUKLELET := null;
              -- update_hafsakat_tashlum; --הכנסתי את הטיםול update_SHEERIM_bney_mishpahaל 
              update_netuney_tik_mechushavim; --V
              update_HIVUN;
            
              update_DARGA_VEDERUG_TIK; --V  
              update_VETEK_DETAIL;
              merge_actions_log;
              update_actions_log;
              update_SHEERIM_bney_mishpaha;
              --******
              v_id := r.mispar_zehut_ben_mishpacha;
              add_row_to_mgl_log_hasava(r.identity_number,
                                        17,
                                        v_SHEER_ID || '-' ||
                                        'שאר פנסיוני - נוצרה בקשה חדשה מסוג שאר פנסיוני');
            
            end if;
          
          else
            if v_seq_bakasha is not null then
            
              if (v_is_update_Porsh_data = false) then
                v_is_update_Porsh_data := true;
              
                --mergeDataHandling;
                add_row_to_mgl_log_hasava(v_id,
                                          17,
                                          v_SHEER_ID || '-' ||
                                          'שאר פנסיוני - עדכון בקשת שאר קיימת');
              
              end if;
              update_SHEERIM_bney_mishpaha;
            
            end if;
          end if;
          --*****
          v_id := r.mispar_zehut_ben_mishpacha;
          merge_netuny_tik_2SHeeR_PNSYNY;
          update_tkufot_avoda_mehushv;
          --השתתפות מגוף לשאר פנסיוני
        
          SET_IS_participation_M_guf;
          if (v_is_exist_participation_M_guf) then
            v_seq_bakasha := null;
            v_id          := r.identity_number;
            set_global_fields(23, false);
            set_MIS_GIMLA;
            --****
            v_id := r.mispar_zehut_ben_mishpacha;
            participation_m_guf_Handling(23);
          
          end if;
          v_id := r.identity_number;
          ------------------סוף השתתפות מגוף לשאר פנסיוני-----------
        
          --END SHEER PENSYONY
        end if;
      
        --***        end loop; -----
        update_Sum_BM_N_T_MCHUSHAVIM;
      end loop;
    
      <<endloop1>>
    
      v_report_html := v_report_html ||
                      
                       info_about_errors_and_commit(v_is_do_commit, V_ERR);
    end loop;
  
    commit;
    return v_report_html;
  end;
  -------------------------------
  procedure update_bakashat_chinuch_hescem is
  begin
    --עדכון בקשת חינוך מורים שהגיעה מחילן עם קוד משרד משכורת 990 ויש לו הסכם מיוחד
    for r in (select b.seq_bakasha,
                     b.seq_prisha,
                     b.code_seif_prisha,
                     dd.code_derug,
                     h537.*,
                     substr(h537.office, 1, 3)
                from ld_hilan_537 h537
                left join v_bakasha_last_status b
                  on b.mispar_zehut = h537.identity_number
                left join darga_vederug_tik dd
                  on dd.seq_bakasha = b.seq_bakasha
               where substr(h537.office, 1, 3) in (990)
                 and dd.code_derug = 41
                 and (select count(p11.seq_prisha)
                        from prisha p11
                       where p11.seq_poresh = b.seq_porshim) = 1
                 and b.seq_ezor_ovdim = 999
                 and b.code_seif_prisha = 415) loop
    
      update prisha pp
         set pp.seq_ezor_ovdim = 206
       where pp.seq_prisha = r.seq_prisha;
    
      update bakasha_regila br
         set br.Code_Sub_Seif_Prisha = 990
       where br.Seq_Bakasha = r.seq_bakasha;
    
    end loop;
  
  end;
  ------------------------
  procedure update_HISACHON_PENSYONY is
  begin
    --עדכון בקשת חינוך מורים שהגיעה מחילן עם קוד משרד משכורת 990 ויש לו הסכם מיוחד
    for r in (select b.seq_bakasha,
                     b.seq_prisha,
                     b.code_seif_prisha,
                     
                     h537.*,
                     substr(h537.office, 1, 3)
                from ld_hilan_537 h537
                left join v_bakasha_last_status b
                  on b.mispar_zehut = h537.identity_number
               where substr(h537.office, 1, 3) in (988)
                 and b.seq_ezor_ovdim = 999) loop
      v_delete_bakasha := pk_prm_utils.delete_bakasha(r.seq_bakasha);
    
    end loop;
  
  end;
  ---------------------------
  procedure COPY_TKUFOT_AVODA_MECHUSHV is
    --COPPY TKUFOT_AVODA_MECHUSHV from bakasha regila to bakashat hishtatfut meguf when TKUFOT_AVODA_MECHUSHV is empty
  begin
    for r in (select distinct (select max(ta2.Seq_Bakasha)
                                 from TKUFOT_AVODA_MECHUSHV ta2
                                 left join v_bakasha_last_status bb
                                   on bb.seq_bakasha = ta2.Seq_Bakasha
                                where bb.mispar_zehut = b.mispar_zehut
                                  and ta2.Seq_Bakasha < b."SEQ_BAKASHA") as Seq_bakashaFromCopy,
                              b.seq_bakasha,
                              b."CODE_SUG_BAKASHA",
                              b.mispar_zehut
                from v_bakasha_last_status b
               where b."CODE_SUG_BAKASHA" in (6, 7, 13)
                 and not exists
               (select *
                        from TKUFOT_AVODA_MECHUSHV ta
                       where ta.Seq_Bakasha = b."SEQ_BAKASHA")
                 and b.mispar_zehut in
                     (select bb3.mispar_zehut --max(ta3.Seq_Bakasha) 
                        from TKUFOT_AVODA_MECHUSHV ta3
                        left join v_bakasha_last_status bb3
                          on bb3.seq_bakasha = ta3.Seq_Bakasha
                       where bb3.mispar_zehut = b.mispar_zehut
                         and ta3.Seq_Bakasha < b."SEQ_BAKASHA")) loop
      V_from_COpy_BAKAHSHA := r.Seq_bakashaFromCopy;
      v_seq_bakasha        := r.Seq_Bakasha;
      update_tkufot_avoda_mehushv;
    end loop;
  
  end;
  ------------------------------
  procedure update_taarich_bakasha is
    --עדכון תאריך בקשה בתאריך זכאות , כשתאריך הבקשה גדול מתאריך הזכאות
  begin
  
    for r in (select distinct b.seq_bakasha,
                              b.code_seif_prisha,
                              b."DATE_BAKASHA" - nt.date_start_zakaut,
                              nt.date_start_zakaut,
                              b."DATE_BAKASHA",
                              b.mispar_zehut
                from v_bakasha_last_status b
                left join netuney_tik_mechushavim nt
                  on nt.Seq_Bakasha = b."SEQ_BAKASHA"
              
               where b."CODE_SUG_BAKASHA" = 1
                 and b."DATE_BAKASHA" > nt.date_start_zakaut
                 and b."DATE_BAKASHA" < to_date('01012019', 'ddmmyyyy')
                 and b."DATE_BAKASHA" - nt.date_start_zakaut > 90) loop
    
      UPDATE bakasha bbb
         SET bbb.date_bakasha = r.date_start_zakaut
       WHERE bbb.Seq_Bakasha = r.seq_bakasha;
    
    end loop;
  
  end;
  ---------------------------------
  procedure update_ben_zug_lesheavar is
    --עדכון בן זוג לשעבר בשביל חסכון פנסיוני לכאלה שלא קיימים
  
    v_sug_zihuy_bm number;
    v_code_kirva   number;
    v_code_min     number;
  
  begin
  
    for r in (select distinct h200.identity_number,
                              convert_low_hebrew_to_ascii(h200.first_name) as SHEM_PRATI,
                              convert_low_hebrew_to_ascii(h200.last_name) as SHEM_MISHPACHA,
                              h200.birth_date
                from ld_hilan_200 h200
               where h200.identity_number = v_id) loop
      v_sug_zihuy_bm := 1;
      if validate_id(1, v_ID) = false then
        v_sug_zihuy_bm := 2;
      end if;
    
      v_code_kirva := 10;
      update_CODE_MIN;
      v_code_min          := v_CODE_MIN_PORESH;
      v_seq_ben_mishpacha := bney_mishpacha_seq.nextval;
      --יש לבדוק כשיש לאותו בנ"א כמה רשומות עם תאריך נישואין לבדוק מה לעשות...    
      insert into bney_mishpacha
        (seq_porshim,
         seq_bney_mishpacha,
         mispar_zehut_ben_mishpacha,
         shem_prati,
         shem_mishpacha,
         taarich_leda,
         
         code_kirva,
         code_min,
         sug_zihuy)
      values
        (v_porshim_seq,
         v_seq_ben_mishpacha,
         r.identity_number,
         r.SHEM_PRATI,
         r.SHEM_MISHPACHA,
         to_date(r.birth_date, 'DDMMYYYY'),
         
         v_code_kirva,
         v_code_min,
         v_sug_zihuy_bm) log errors into err_bney_mishpacha
        (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  end;
