  -------------------------------
  procedure CHISACHON_PENSYONI is
    v_report_html clob;
  begin
    for r in (select distinct h312.identity_number,
                              h312.value,
                              b.seq_ezor_ovdim,
                              b.seq_prisha,
                              b.seq_porshim,
                              bm.Seq_Bney_Mishpacha,
                              bm.code_kirva
              
                from ld_hilan_312 h312
                left join v_bakasha_last_status b
                  on b.mispar_zehut = h312.identity_number
                left join bney_mishpacha bm
                  on bm.mispar_zehut_ben_mishpacha = h312.value
                 and bm.Seq_Porshim = b.seq_porshim
                left join mgl_log_hasava l
                  on l.mispar_zehut = h312.identity_number
              
               where h312.variable_type = 410
                 and h312.value2 > 0
                 and not exists
               (select *
                        from mgl_log_hasava l
                       where l.mispar_zehut = h312.identity_number
                         and l.code_hasava = 21)
                 and h312.job_number = 1
              /*and l.code_hasava <> 13
                 
              and (h312.job_number = 1 or
                  h312.identity_number in
                  (002636553, 006900302, 051308963))*/
              
              --  and h312.identity_number = 10688430 -- 051308963
              
              ) loop
      ResetFields;
    
      v_porshim_seq := r.seq_porshim;
      v_seq_prisha  := r.seq_prisha;
      v_ezor_ovdim  := r.seq_ezor_ovdim;
    
      if (r.Seq_Bney_Mishpacha > 0) then
      
        v_seq_ben_mishpacha := r.Seq_Bney_Mishpacha;
        UPDATE BNEY_MISHPACHA bm
           SET bm.code_kirva = 10
         WHERE bm.Seq_Bney_Mishpacha = r.Seq_Bney_Mishpacha;
      else
      
        --need to create new bney mishpacha
        V_ID := r.value;
        update_ben_zug_lesheavar;
      
      end if;
      --מעדכנת את הפרמטר v_SHEER_ID כי כך הפרוצדורות מתייחסות לשדה הנ"ל
      v_SHEER_ID := r.value;
      V_ID       := r.identity_number;
      /* update_ADDRESS_2_Ben_Mishpacha(v_seq_ben_mishpacha);
      update_BANK_ACCOUNT_2_BM(v_seq_ben_mishpacha);
      update_mazav_mishpachti(v_seq_ben_mishpacha);
      update_hafsakat_tashlum(TRUE);*/
      -----------------
      v_ora_err_tag$ := to_char(v_id);
      v_where        := ' where ora_err_tag$= ''' || v_ora_err_tag$ || '''';
    
      for r2 in (select distinct b12.code_action,
                                 b12.seq_bakasha as HP_seq_bakasha,
                                 (select min(h312_2.from_date)
                                    from ld_hilan_312 h312_2
                                   where h312_2.identity_number =
                                         h312.identity_number
                                     and h312_2.job_number = h312.job_number
                                     and h312_2.variable_type = 410
                                     and h312_2.value2 > 0) as from_date,
                                 (select min(h312_2.To_Date)
                                    from ld_hilan_312 h312_2
                                   where h312_2.identity_number =
                                         h312.identity_number
                                     and h312_2.job_number = h312.job_number
                                     and h312_2.variable_type = 410
                                     and h312_2.value2 > 0) as to_date,
                                 nt.*,
                                 h312.job_number,
                                 b.seq_ezor_ovdim,
                                 b.seq_prisha,
                                 b.seq_porshim,
                                 bm.Seq_Bney_Mishpacha,
                                 bm.code_kirva,
                                 h312.identity_number,
                                 h312.value,
                                 h312.value2,
                                 to_number(h312.value2 / 100) as sheur_havara
                   from ld_hilan_312 h312
                   left join v_bakasha_last_status b
                     on b.mispar_zehut = h312.identity_number
                   left join v_bakasha_last_status b12
                     on b12.mispar_zehut = h312.identity_number
                    and b12.code_sug_bakasha = 12
                    and b12.code_action <> 17
                   left join netuney_tik_mechushavim nt
                     on nt.Seq_Bakasha = b12.seq_bakasha
                   left join bney_mishpacha bm
                     on bm.mispar_zehut_ben_mishpacha = h312.value
                    and bm.Seq_Porshim = b.seq_porshim
                   left join mgl_log_hasava l
                     on l.mispar_zehut = h312.identity_number
                   left join ld_hilan_312 t
                     on t.identity_number = h312.identity_number
                    and t.variable_type = 100
                  where h312.variable_type = 410
                    and h312.value2 > 0
                       /*and l.code_hasava <> 13
                       and (h312.job_number = 1 or
                           h312.identity_number in
                           (002636553, 006900302, 051308963))*/
                    and h312.identity_number = r.identity_number
                       --הוספתי לשלב 2
                    and h312.job_number = 1
                 
                 ) loop
        v_job_number         := r2.job_number;
        v_hp_sheur_havara    := r2.sheur_havara;
        v_date_start_zakahut := to_date(r2.from_date, 'ddmmyyyy');
        --עדכון הבקשה בבקשת חסכון פנסיוני
        v_seq_bakasha := r2.HP_seq_bakasha;
        if (nvl(r2.HP_seq_bakasha, 0) = 0) then
          --בדיקה אם לא קיים בקשת חיסכון פנסיוני
          v_seq_bakasha := null;
          if update_bakasha(12) = false or update_bakasha_regila = false then
            v_is_do_commit := false;
            goto endloop2;
          else
            v_is_do_commit := true;
            --עדכון נתוני בן זוג         
            --עדכון נתוני תיק מחושבים
            update_HP_netuney_tik;
            pk_prm_utils.insert_action_log_row(98,
                                               to_date(r2.from_date,
                                                       'ddmmyyyy'),
                                               1,
                                               null,
                                               null,
                                               null,
                                               null,
                                               null,
                                               v_seq_bakasha,
                                               null);
            merge_actions_log;
          end if;
        
        end if;
        --בכל מקרה לעדכן את שאר הפרטים , גם כשקיימת בקשת חסכון פנסיוני
      
        update_ADDRESS_2_Ben_Mishpacha(v_seq_ben_mishpacha);
        update_BANK_ACCOUNT_2_BM(v_seq_ben_mishpacha);
        update_mazav_mishpachti(v_seq_ben_mishpacha);
        if (V_is_updated_BenMishpacha_DATA = false) then
          V_is_updated_BenMishpacha_DATA := TRUE;
          update_hafsakat_tashlum(TRUE);
        end if;
        --add row log succses
        add_row_to_mgl_log_hasava(v_id, 21, '');
      end loop;
      commit;
      <<endloop2>>
    
      v_report_html := v_report_html ||
                       info_about_errors_and_commit(v_is_do_commit, '');
    end loop;
    --UPDATE_PTIRA_DATE;
    commit;
  
  end;
  -------------------------------
  procedure update_ADDRESS_TABLE is
  begin
    for r in (select h218.seq,
                     subSTR(convert_low_hebrew_to_ascii(h218.Address),
                            1,
                            (instr(h218.Address, ':', 1, 1) - 1)) as STREET,
                     subSTR(convert_low_hebrew_to_ascii(h218.Address),
                            instr(h218.Address, ':', 1, 1) + 1,
                            (instr(h218.Address, ':', 1, 2) -
                            instr(h218.Address, ':', 1, 1) - 1)) as house,
                     subSTR(convert_low_hebrew_to_ascii(h218.Address),
                            instr(h218.Address, ':', 1, 2) + 1,
                            (instr(h218.Address, ':', 1, 3) -
                            instr(h218.Address, ':', 1, 2) - 1)) as apartment,
                     instr(h218.Address, ':', 1, 1),
                     instr(h218.Address, ':', 1, 2),
                     instr(h218.Address, ':', 1, 3)
                from ld_hilan_218 h218) loop
    
      UPDATE ld_hilan_218 h218
         SET h218.street    = r.street,
             h218.house     = r.house,
             h218.apartment = r.apartment
       WHERE h218.Seq = r.seq;
    end loop;
  
  end;
  ----------------------
  procedure hafskt_tshlm_01022019_01042019 is
    v_date date;
  begin
    for r in (select distinct b.code_makor,
                              b.seq_prisha,
                              b.mispar_zehut,
                              p.shem_prati,
                              p.shem_mishpacha,
                              p.taarich_ptira
                from v_bakasha_last_status b
                left join poresh p
                  on p.porshim_seq = b.seq_porshim
               where p.taarich_ptira <> b.taarich_prisha
                 and b.mispar_zehut <> 42747121
                 and nvl(p.taarich_ptira,
                         to_date('01/01/0001', 'dd/mm/yyyy')) >
                     to_date('01/02/2019', 'dd/mm/yyyy')
                 and nvl(p.taarich_ptira,
                         to_date('01/01/0001', 'dd/mm/yyyy')) <
                     to_date('01/04/2019', 'dd/mm/yyyy')
                 and not exists
               (select *
                        from v_bakasha_last_status bb
                       where bb.mispar_zehut = b.mispar_zehut
                         and bb.code_sug_bakasha = 19)
                 and (b.seq_ezor_ovdim not in
                     (select c.seq_ezor_ovdim
                         from ezor_ovdim_category c
                       --all security
                        where c.code_sug_ezor_ovdim = 8) or
                     b.seq_ezor_ovdim in
                     (select c.seq_ezor_ovdim
                         from ezor_ovdim_category c
                       --security that his payment in hilan
                        where c.code_sug_ezor_ovdim = 14))) loop
      V_ID := r.mispar_zehut;
      --לאתחל לראשון לחודש הבא
      --v_date                := r.taarich_ptira + INTERVAL '1' MONTH;
      v_date                := to_date(
                                       
                                       '01' ||
                                       ('0' ||
                                       (to_char(r.taarich_ptira, 'MM') + 1)) ||
                                       (to_char(r.taarich_ptira, 'YYYY')),
                                       'ddmmyyyy');
      v_seq_Another_bakasha := bakasha_seq.nextval;
    
      insert into bakasha
        (seq_bakasha,
         seq_prisha,
         code_sug_bakasha,
         code_source,
         date_bakasha,
         FROM_DATE,
         DATE_UPDATE,
         CODE_BAKASHA_DETAIL)
      values
        (v_seq_Another_bakasha,
         r.seq_prisha,
         19,
         16,
         v_DATE,
         v_DATE,
         v_DATE,
         6) log errors into err_bakasha
        (v_ora_err_tag$) reject limit unlimited;
    
      pk_prm_utils.insert_action_log_row(134,
                                         v_DATE,
                                         1,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         v_seq_Another_bakasha,
                                         null);
      commit;
      --134
    end loop;
  
  end;
  -----------------------------
  procedure update_IS_ZAKAI_LMANAK is
  begin
    dbms_output.enable(999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999);
    for r in (select distinct h527.Code, h527.identity_number
                from ld_hilan_527 h527
               where h527.semel = 242) loop
      ResetFields;
    
      v_id := r.identity_number;
    
      for r2 in (select distinct h537.identity_number,
                                 substr(h537.office, 1, 3) as misrad_maskoret,
                                 --הוספתי בשביל למצוא את ה SEQ אזור עובדים ע"ס 2 השדות הנ"ל
                                 substr(h537.office, 4, 4) as ezor_ovdim_hilan,
                                 h537.job_number
                   from ld_hilan_537 h537
                  where h537.identity_number = v_id
                       --ורק פרישות שהם לא של שארים 
                    and exists
                  (select *
                           from ld_hilan_312 h312
                          where h312.identity_number = h537.identity_number
                            and h312.job_number = h537.job_number
                            and h312.variable_type = 102
                            and to_number(h312.value) not in
                                (126,
                                 128,
                                 226,
                                 228,
                                 326,
                                 426,
                                 526,
                                 528,
                                 428,
                                 328,
                                 628))) loop
        v_job_number := r2.job_number;
        if nvl(v_misrad_maskoret, 0) <> r2.misrad_maskoret then
        
          v_misrad_maskoret  := r2.misrad_maskoret;
          v_ezor_ovdim_HILAN := r2.ezor_ovdim_hilan;
          set_global_fields(1, true);
          for r3 in (select distinct nt1.is_zakai_lmaanak
                       from netuney_tik_mechushavim nt1
                      where nt1.Seq_Bakasha = v_seq_bakasha
                        and nt1.Code_Department = 2) loop
          
            ComparingValues(nvl(r3.is_zakai_lmaanak, 0),
                            to_number(nvl(r.Code, 0)),
                            'Netuney_Tik_Mechushavim',
                            'Is_Zakai_Lmaanak');
          
          end loop;
        
          if v_date_bakasha < to_date('01102017', 'ddmmyyyy') then
            dbms_output.put_line(V_ID);
            update netuney_tik_mechushavim nt
               set nt.is_zakai_lmaanak = r.Code
             where nt.seq_bakasha = v_seq_bakasha;
          end if;
        
        end if;
      end loop;
    end loop;
  end;

  -----------------------------
  procedure update_ODEF_SHERUT_CHODASHIM is
    v_odef_sherut_yamim     number;
    v_odef_sherut_chodashim number;
    v_odef_sherut_shanim    number;
  begin
  
    dbms_output.enable(999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999);
    for r in (select distinct h527.identity_number,
                              h527.job_number,
                              to_number(h527.sum) as codashim
                from ld_hilan_527 h527
               where h527.semel = 241
                 and h527.to_date =
                     (select max(t.to_date)
                        from ld_hilan_527 t
                       where t.identity_number = h527.identity_number
                         and t.job_number = h527.job_number
                         and t.semel = 241)) loop
      ResetFields;
    
      v_id := r.identity_number;
    
      for r2 in (select distinct h537.identity_number,
                                 substr(h537.office, 1, 3) as misrad_maskoret,
                                 --הוספתי בשביל למצוא את ה SEQ אזור עובדים ע"ס 2 השדות הנ"ל
                                 substr(h537.office, 4, 4) as ezor_ovdim_hilan,
                                 h537.job_number
                   from ld_hilan_537 h537
                  where h537.identity_number = v_id
                       --ורק פרישות שהם לא של שארים 
                    and exists
                  (select *
                           from ld_hilan_312 h312
                          where h312.identity_number = h537.identity_number
                            and h312.job_number = h537.job_number
                            and h312.variable_type = 102
                            and to_number(h312.value) not in
                                (126,
                                 128,
                                 226,
                                 228,
                                 326,
                                 426,
                                 526,
                                 528,
                                 428,
                                 328,
                                 628))) loop
        v_job_number := r2.job_number;
        if nvl(v_misrad_maskoret, 0) <> r2.misrad_maskoret then
        
          v_misrad_maskoret  := r2.misrad_maskoret;
          v_ezor_ovdim_HILAN := r2.ezor_ovdim_hilan;
          set_global_fields(1, false);
          v_odef_sherut_chodashim := trunc(r.codashim / 100);
          v_odef_sherut_shanim    := trunc(v_odef_sherut_chodashim / 12);
          v_odef_sherut_yamim     := round(MOD((r.codashim / 100), 1) *
                                           30.44);
        
          for r3 in (select distinct nt1.ODEF_SHERUT_SHANIM    as current_ODEF_SHERUT_SHANIM,
                                     nt1.ODEF_SHERUT_CHODASHIM as current_ODEF_SHERUT_CHODASHIM,
                                     nt1.Odef_Sherut_Yamim     as current_Odef_Sherut_Yamim
                       from netuney_tik_mechushavim nt1
                      where nt1.Seq_Bakasha = v_seq_bakasha
                        and nt1.Code_Department = 2) loop
          
            ComparingValues(r3.current_odef_sherut_shanim,
                            to_number(nvl(v_odef_sherut_shanim, 0)),
                            'Netuney_Tik_Mechushavim',
                            'odef_sherut_shanim');
            ComparingValues(r3.Current_Odef_Sherut_Chodashim,
                            nvl(v_odef_sherut_chodashim, 0),
                            'Netuney_Tik_Mechushavim',
                            'Odef_Sherut_Chodashim');
            ComparingValues(r3.Current_Odef_Sherut_Yamim,
                            nvl(v_odef_sherut_yamim, 0),
                            'Netuney_Tik_Mechushavim',
                            'Odef_Sherut_Yamim');
          end loop;
        
          if v_date_bakasha < to_date('01102017', 'ddmmyyyy') then
            dbms_output.put_line(V_ID);
            update netuney_tik_mechushavim nt
               set nt.ODEF_SHERUT_SHANIM    = v_odef_sherut_shanim,
                   nt.ODEF_SHERUT_CHODASHIM = v_odef_sherut_chodashim,
                   nt.ODEF_SHERUT_YAMIM     = v_odef_sherut_yamim
             where nt.seq_bakasha = v_seq_bakasha;
          end if;
        end if;
      end loop;
    end loop;
  end;
