  procedure update_mispar_zheut_fictivi is
    V_sug_zihuy1 number;
  begin
    dbms_output.enable(999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999);
  
    for r in (select distinct h200.identity_number,
                              h200.dummy_identity_number
                from ld_hilan_200 h200
                left join poresh p
                  on p.mispar_zehut = h200.identity_number
               where p.mispar_zehut > 0
                 and h200.identity_number <> h200.dummy_identity_number
                 and not exists
               (select *
                        from poresh p
                       where p.mispar_zehut = h200.dummy_identity_number)) loop
      dbms_output.put_line(r.identity_number || ' ' ||
                           r.dummy_identity_number);
      if validate_id(1, r.dummy_identity_number) = false then
        V_sug_zihuy1 := 2;
      else
        V_sug_zihuy1 := 1;
      end if;
      update poresh p
         set p.mispar_zehut = r.dummy_identity_number,
             p.sug_zihuy    = V_sug_zihuy1
       where p.mispar_zehut = r.identity_number;
    end loop;
  end;

