  function MERGE_SHEERIM_Unrecognized return clob is
    v_report_html          clob;
    v_is_do_commit         boolean;
    v_is_update_Porsh_data boolean;
    V_ERR                  varchar2(100);
    v_fictivi_id_poresh    number;
  
  begin
  
    execute immediate 'alter session set nls_language= ''american''';
    execute immediate 'alter session set nls_date_language=''english''';
    execute immediate 'alter session set nls_date_format=''dd-mon-yyyy''';
    v_fictivi_id_poresh := 600002000;
    -- DELETE_BNEY_MISHPACHA;
    --LOOP PORSHIM
    for r in (select distinct h200.identity_number as sheer_identity_number,
                              (select max(h537.from_date)
                                 from ld_hilan_537 h537
                                where h537.identity_number =
                                      h200.identity_number) as from_date
                from ld_hilan_200 h200
                left join ld_hilan_312 h3122
                  on h3122.identity_number = h200.identity_number
                 and h3122.variable_type = 102
              --left join ld_mlm_110 m110 on m110.identity_number =h200.identity_number
              
               where h200.identity_number in (9772070, 45954351, 2356020)
                 and h3122.value <> 121
                    /* and h200.dummy_identity_number not in
                    (select b.mispar_zehut from v_bakasha_last_status b)*/
                 and h200.dummy_identity_number not in
                     (select bm.mispar_zehut_ben_mishpacha
                        from bney_mishpacha bm)
                 and not exists
               (select *
                        from ld_mlm_110 m110
                       where m110.identity_number =
                             h200.dummy_identity_number
                         and m110.is_erased = 0
                         and m110.death_date is not null)
              --and rownum < 2
              
              ) loop
      ResetFields;
      V_ERR          := null;
      v_is_do_commit := true;
    
      v_id := v_fictivi_id_poresh;
      --insert poresh
      v_porshim_seq := porshim_seq.nextval;
    
      INSERT INTO poresh
        (MISPAR_ZEHUT,
         SHEM_PRATI,
         SHEM_MISHPACHA,
         PORSHIM_SEQ,
         SUG_ZIHUY,
         TAARICH_PTIRA)
      VALUES
        (v_id,
         'הסבה',
         'הסבה',
         v_porshim_seq,
         2,
         to_date(r.from_date, 'ddmmyyyy'));
    
      --v_SHEER_ID     := r.bm_identity_number;
      v_ora_err_tag$ := to_char(v_id);
      v_where        := ' where ora_err_tag$= ''' || v_ora_err_tag$ || '''';
    
      -------------**********
      --LOPP MISRADEY PRISHA
      for r2 in (select distinct h537.identity_number,
                                 substr(h537.office, 1, 3) as misrad_maskoret,
                                 substr(h537.office, 4, 4) as ezor_ovdim,
                                 h537.job_number
                   from ld_hilan_537 h537
                  where h537.identity_number = r.sheer_identity_number) loop
        v_ezor_ovdim := convert_seq_ezor_ovdim(r2.misrad_maskoret,
                                               r2.ezor_ovdim);
        v_seq_prisha := prisha_seq.nextval;
      
        INSERT INTO prisha
          (SEQ_PRISHA, SEQ_PORESH, SEQ_EZOR_OVDIM)
        VALUES
          (v_seq_prisha, v_porshim_seq, v_ezor_ovdim);
        v_seq_bakasha := bakasha_seq.nextval;
        INSERT INTO bakasha
          (SEQ_BAKASHA, SEQ_PRISHA, CODE_SUG_BAKASHA, DATE_BAKASHA)
        VALUES
          (v_seq_bakasha, v_seq_prisha, 1, to_date('01011990', 'ddmmyyyy'));
      
        INSERT INTO bakasha_regila
          (SEQ_BAKASHA, Code_Seif_Prisha, TAARICH_PRISHA)
        VALUES
          (v_seq_bakasha, 999, to_date('01011990', 'ddmmyyyy'));
        --סתם תקענו ערך , בכדי שיהיה איזשהו תאריך לסיום טיפול...
        --update_actions_log;
        pk_prm_utils.insert_action_log_row(98,
                                           to_date(r.from_date, 'ddmmyyyy'),
                                           1,
                                           null,
                                           null,
                                           null,
                                           null,
                                           null,
                                           v_seq_bakasha,
                                           null);
      
        merge_actions_log;
      
        v_job_number      := r2.job_number;
        v_misrad_maskoret := r2.misrad_maskoret;
        --set_global_fields(1, false);
        if (v_seq_prisha is null) then
        
          --ADD ROW TO CHRIGIM...
          Add_warning_data_conversion_ROW('SEQ__prisha not found',
                                          'SEQ_prisha not found',
                                          'PRISHA',
                                          'SEQ_prisha');
          v_is_do_commit := false;
          goto endloop1;
        
        else
          if v_seq_bakasha is null then
            Add_warning_data_conversion_ROW('SEQ_BAKASHA not found',
                                            'SEQ_BAKASHA not found',
                                            'BAKASHA',
                                            'SEQ_BAKASHA');
          
            v_is_do_commit := false;
            goto endloop1;
          end if;
        end if;
      
        --LOOP SHEERIM
        v_is_update_Porsh_data := false;
      
        v_SHEER_ID := r.sheer_identity_number;
      
        --טיפול בשאר פנסיוני
        V_from_COpy_BAKAHSHA := v_seq_bakasha;
        v_seq_bakasha        := null;
        set_global_fields(13, false);
        -- יש ליצור בקשת שאר פנסיוני במקרה שלא מצא..
        if (v_seq_bakasha is null and v_seq_prisha is not null) then
          v_id := r.sheer_identity_number;
          if (update_bakasha(13) = false or update_bakasha_regila = false) then
          
            V_ERR          := 'Failed to create a Bakashat Sheer Pensyony';
            v_is_do_commit := false;
            goto endloop1;
          else
          
            V_CHELKIYUT_MESHUKLELET := null;
            -- update_hafsakat_tashlum; --הכנסתי את הטיםול update_SHEERIM_bney_mishpahaל 
            update_netuney_tik_mechushavim; --V
            update_HIVUN;
          
            update_DARGA_VEDERUG_TIK; --V  
            update_VETEK_DETAIL;
            merge_actions_log;
            -- update_actions_log;
          
            pk_prm_utils.insert_action_log_row(98,
                                               v_date_start_zakahut,
                                               1,
                                               null,
                                               null,
                                               null,
                                               null,
                                               null,
                                               v_seq_bakasha,
                                               null);
            update_SHEERIM_bney_mishpaha;
            v_id := r.sheer_identity_number;
            add_row_to_mgl_log_hasava(v_fictivi_id_poresh,
                                      17,
                                      v_SHEER_ID || '-' ||
                                      'שאר פנסיוני - נוצרה בקשה חדשה מסוג שאר פנסיוני');
          
          end if;
        
        else
          if v_seq_bakasha is not null then
          
            if (v_is_update_Porsh_data = false) then
              v_is_update_Porsh_data := true;
            
              --mergeDataHandling;
              add_row_to_mgl_log_hasava(v_id,
                                        17,
                                        v_SHEER_ID || '-' ||
                                        'שאר פנסיוני - עדכון בקשת שאר קיימת');
            
            end if;
            update_SHEERIM_bney_mishpaha;
          
          end if;
        end if;
        v_id := r.sheer_identity_number;
        merge_netuny_tik_2SHeeR_PNSYNY;
        update_tkufot_avoda_mehushv;
        --השתתפות מגוף לשאר פנסיוני
      
        SET_IS_participation_M_guf;
        if (v_is_exist_participation_M_guf) then
          v_seq_bakasha := null;
          v_id          := v_fictivi_id_poresh;
          set_global_fields(23, false);
          set_MIS_GIMLA;
          v_id := r.sheer_identity_number;
          participation_m_guf_Handling(23);
        
        end if;
        v_id := v_fictivi_id_poresh;
        ------------------סוף השתתפות מגוף לשאר פנסיוני-----------
      
        --END SHEER PENSYONY
        --end if;
      
        --end loop;
        update_Sum_BM_N_T_MCHUSHAVIM;
      end loop;
      v_fictivi_id_poresh := v_fictivi_id_poresh + 1;
    
      <<endloop1>>
    
      v_report_html := v_report_html ||
                      
                       info_about_errors_and_commit(v_is_do_commit, V_ERR);
    end loop;
  
    commit;
    return v_report_html;
  end;
  ---------------------------------------------
  procedure update_Sheer2Pagey_tokef is
    v_report_html          clob;
    v_is_do_commit         boolean;
    v_is_update_Porsh_data boolean;
    V_ERR                  varchar2(100);
    v_fictivi_id_poresh    number;
  
  begin
  
    for r in (select distinct p.porshim_seq,
                              m15.family_identity_number,
                              m15.identity_number,
                              m15.last_name,
                              m15.first_name,
                              (select max(m15.birth_date)
                                 from ld_mlm_15 m15
                                where m15.family_identity_number =
                                      t.identity_number) as birth_date,
                              (select max(to_date(t2.to_date, 'dd/mm/yyyy'))
                                 from ld_mlm_215 t2
                                where t2.identity_number = t.identity_number) as date_syum_zakaut
                from ld_mlm_215 t
                left join ld_mlm_15 t1
                  on t.identity_number = t1.identity_number
                left join ld_mlm_15 m15
                  on m15.family_identity_number = t.identity_number
                left join poresh p
                  on p.mispar_zehut = m15.identity_number
               where to_number(t.identity_number) in
                     (select distinct to_number(identity_number)
                        from ld_mlm_215
                       where CODE_EXPIRED = '02'
                         and IS_ERASED = '0'
                         and to_date(to_date, 'dd/mm/yyyy') >
                             to_date('01/04/2019', 'dd/mm/yyyy')
                      minus
                      select b.mispar_zehut_ben_mishpacha
                        from bney_mishpacha b)) loop
    
      insert into bney_mishpacha bm
        (seq_porshim,
         seq_bney_mishpacha,
         mispar_zehut_ben_mishpacha,
         shem_prati,
         shem_mishpacha,
         taarich_leda,
         
         code_kirva,
         --code_min,
         --sug_zihuy
         bm.to_date_sium_zakaut)
      values
        (r.porshim_seq,
         bney_mishpacha_seq.nextval,
         r.family_identity_number,
         r.first_name,
         r.last_name,
         to_date(r.birth_date, 'DD/MM/YYYY'),
         
         2,
         r.date_syum_zakaut
         
         --v_code_min,
         --v_sug_zihuy_bm
         ) log errors into err_bney_mishpacha
        (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  
  end;

