  procedure Zehut_fictivi_handling is
  
  begin
  
    for r in (select lm.code_hasava  as mgl,
                     lm2.code_hasava as mgl_fictivi,
                     lm3.code_hasava as mlm,
                     lm4.code_hasava as mlm_fictivi,
                     f.*
                from zheut_fictivi_from_hilan f
                left join mgl_log_hasava_mgl lm
                  on lm.mispar_zehut = f.mispar_zheut
                left join mgl_log_hasava_mgl lm2
                  on lm2.mispar_zehut = f.mispar_zheut_fictivi
                left join mgl_log_hasava lm3
                  on lm3.mispar_zehut = f.mispar_zheut
                left join mgl_log_hasava lm4
                  on lm4.mispar_zehut = f.mispar_zheut_fictivi
               where exists
               (select *
                        from poresh p
                       where p.mispar_zehut = f.mispar_zheut_fictivi
                         and exists
                       (select *
                                from poresh p
                               where p.mispar_zehut = f.mispar_zheut))) loop
      dbms_output.enable(9999999999999999999999);
      for r2 in (select distinct b.seq_bakasha
                   from v_bakasha_last_status b
                  where b.mispar_zehut = r.mispar_zheut) loop
        v_delete_bakasha := pk_prm_utils.delete_bakasha(r2.Seq_Bakasha);
      
        dbms_output.put_line(v_delete_bakasha || ' ' || 'מחיקה ' ||
                             r.mispar_zheut);
      end loop;
    end loop;
  
  end;

  procedure delete_prishot is
  
  begin
    dbms_output.enable(9999999999999999999999);
    for r in (select distinct po.mispar_zehut, p.*
                from prisha p
                left join poresh po
                  on po.porshim_seq = p.seq_prisha
               where not exists (select *
                        from v_bakasha_last_status b
                       where b.seq_prisha = p.seq_prisha)) loop
    
      delete from prisha p where p.seq_prisha = r.seq_prisha;
      --delete from poresh po where po.Porshim_Seq = r.seq_poresh;
      dbms_output.put_line('delete prisha : ' || r.mispar_zehut);
    
    end loop;
  
  end;

  procedure delete_porshim is
  
  begin
    dbms_output.enable(9999999999999999999999);
    for r in (select distinct *
                from poresh po
              
               where not exists
               (select *
                        from prisha pr
                       where pr.seq_poresh = po.porshim_seq)) loop
      for r2 in (select *
                   from bney_mishpacha bm
                  where bm.seq_porshim = r.porshim_seq) loop
        delete from mazav_mishpachti mm
         where mm.Seq_Bney_Mishpacha = r2.Seq_Bney_Mishpacha;
      end loop;
    
      delete from mazav_mishpachti mm where mm.seq_poresh = r.porshim_seq;
      delete from bney_mishpacha bm where bm.Seq_Porshim = r.porshim_seq;
    
      delete from poresh po where po.Porshim_Seq = r.porshim_seq;
      dbms_output.put_line('delete poresh id : ' || r.mispar_zehut);
    
    end loop;
  
  end;

