  procedure clean_date is
    --מחיקת זהויות לא נכונות מהסלקט של נתניה
  begin
    dbms_output.enable(9999999999999999999999);
  
    execute immediate 'ALTER TRIGGER ERROR_ON_ID_UPDATE DISABLE';
    for r in (with a as
                 (select distinct (a.gimla_number) as gimla,
                                 max(a.seq_poresh) as aaap,
                                 a.seq_ezor_ovdim as aprisha
                   from prisha a
                  where a.gimla_number is not null
                    and a.gimla_number > 1
                  group by a.gimla_number, a.seq_poresh, a.seq_ezor_ovdim
                  order by a.gimla_number),
                x as
                 (select distinct (x.gimla_number) gimx,
                                 min(x.seq_poresh) as xxxp,
                                 x.seq_ezor_ovdim as xprisha
                   from prisha x
                  where x.gimla_number is not null
                    and x.gimla_number > 1
                  group by x.gimla_number, x.seq_poresh, x.seq_ezor_ovdim
                  order by x.gimla_number),
                pelet as
                 (select gimla, aaap, aprisha, gimx, xxxp, xprisha
                   from a, x
                  where gimla = gimx
                    and aaap <> xxxp)
                select distinct --lm4.code_hasava as X_mlm_code_hasava,lm4.update_date,
                                -- lm2.code_hasava as  a_mgl_code_hasava,
                                --lm.code_hasava as X_mgl_code_hasava, 
                                --lm3.code_hasava as a_mlm_code_hasava
                                --, lm3.update_date,
                                --  bx.seq_bakasha as seq_bakasha_x,
                                 k.mispar_zehut as a_mispar_zehut,
                                l.mispar_zehut as x_mispar_zehut
                --, b.seq_bakasha as seq_bakasha_a, gimla,k.mispar_zehut as a_mispar_zehut,k.shem_prati,k.shem_mishpacha,aprisha,xprisha,l.mispar_zehut as x_mispar_zehut,l.shem_prati,l.shem_mishpacha
                  from pelet t
                  left join poresh k
                    on k.porshim_seq = aaap
                  left join poresh l
                    on l.porshim_seq = xxxp
                  left join v_bakasha_last_status b
                    on b.seq_porshim = aaap
                  left join v_bakasha_last_status bx
                    on bx.seq_porshim = xxxp
                  left join mgl_log_hasava_mgl lm
                    on lm.mispar_zehut = l.mispar_zehut
                  left join mgl_log_hasava_mgl lm2
                    on lm2.mispar_zehut = k.mispar_zehut
                  left join mgl_log_hasava lm3
                    on lm3.mispar_zehut = k.mispar_zehut
                  left join mgl_log_hasava lm4
                    on lm4.mispar_zehut = l.mispar_zehut
                
                 where aprisha = xprisha
                   and (lm.code_hasava = 1 and lm3.code_hasava = 12 and
                       nvl(lm4.code_hasava, 0) = 0 and
                       nvl(lm2.code_hasava, 0) = 0)
                --and k.mispar_zehut in (99149261, 52175734)
                 order by k.mispar_zehut) loop
    
      for r2 in (select distinct *
                   from v_bakasha_last_status b
                  where b.mispar_zehut = r.x_mispar_zehut) loop
        v_delete_bakasha := pk_prm_utils.delete_bakasha(r2.seq_bakasha);
        dbms_output.put_line(r.x_mispar_zehut || ' ' || r.a_mispar_zehut ||
                             v_delete_bakasha);
      end loop;
    
      if v_delete_bakasha like ('%done!%') then
        for r3 in (select distinct h.mispar_zheut, h.mispar_zheut_fictivi
                   
                     from zheut_fictivi_from_hilan h
                    where h.mispar_zheut_fictivi in
                          (r.x_mispar_zehut, r.a_mispar_zehut)) loop
          update poresh po
             set po.mispar_zehut = r3.mispar_zheut
           where po.mispar_zehut = r3.mispar_zheut_fictivi;
        
        end loop;
      
      end if;
    
    end loop;
    execute immediate 'ALTER TRIGGER ERROR_ON_ID_UPDATE ENABLE';
  
    /* for r4 in (select distinct h.mispar_zheut, bm.*
                 from zheut_fictivi_from_hilan h
                 left join bney_mishpacha bm
                   on bm.mispar_zehut_ben_mishpacha = h.mispar_zheut_fictivi
                where nvl(bm.mispar_zehut_ben_mishpacha, 0) > 0) loop
      update bney_mishpacha bm
         set bm.mispar_zehut_ben_mishpacha = r4.mispar_zheut
       where bm.Seq_Bney_Mishpacha = r4.Seq_Bney_Mishpacha;
    end loop;*/
  
  end;

