  procedure clean_data3 is
    --עדכון כל הפורשים שהגיעו גם כבני משפחה וגם כפורשים כזהות פיקטיבית
  begin
    dbms_output.enable(9999999999999999999999);
  
    execute immediate 'ALTER TRIGGER ERROR_ON_ID_UPDATE DISABLE';
  
    for r in (select distinct h.mispar_zheut_fictivi, h.mispar_zheut
                from zheut_fictivi_from_hilan h
                left join poresh p
                  on p.mispar_zehut = h.mispar_zheut_fictivi
                left join poresh p2
                  on p2.mispar_zehut = h.mispar_zheut
               where h.mispar_zheut_fictivi in
                     (select p.mispar_zehut
                        from poresh p
                       where p.mispar_zehut = h.mispar_zheut_fictivi
                         and p.taarich_ptira is null)
                 and p.taarich_ptira is null
                 and p2.taarich_ptira is null
                 and nvl(p2.mispar_zehut, 0) = 0) loop
      dbms_output.put_line(r.mispar_zheut_fictivi || ' ' || r.mispar_zheut ||
                           v_delete_bakasha);
      update poresh p
         set p.sug_zihuy = 1, p.mispar_zehut = r.mispar_zheut
       where p.mispar_zehut = r.mispar_zheut_fictivi;
    end loop;
    execute immediate 'ALTER TRIGGER ERROR_ON_ID_UPDATE ENABLE';
  end;
  ---------------------
  procedure clean_data4 is
  
  begin
    dbms_output.enable(9999999999999999999999);
  
    execute immediate 'ALTER TRIGGER ERROR_ON_ID_UPDATE DISABLE';
  
    for r in (select p.porshim_seq as fictivi_porshim_seq,
                     p2.porshim_seq,
                     h.mispar_zheut_fictivi,
                     h.mispar_zheut,
                     (select min(b.seq_bakasha)
                        from v_bakasha_last_status b
                       where b.mispar_zehut = h.mispar_zheut) as seq_bakasha,
                     (select min(b.seq_bakasha)
                        from v_bakasha_last_status b
                       where b.mispar_zehut = h.mispar_zheut_fictivi) as fictivi_seq_bakasha
              
                from zheut_fictivi_from_hilan h
                left join poresh p
                  on p.mispar_zehut = h.mispar_zheut_fictivi
                left join poresh p2
                  on p2.mispar_zehut = h.mispar_zheut
                left join prisha pr
                  on pr.seq_poresh = p.porshim_seq
                left join prisha pr2
                  on pr2.seq_poresh = p2.porshim_seq
               where -- rownum < 5
               h.mispar_zheut not in (51166361, 896928, 8539520, 4265179)
           and h.mispar_zheut_fictivi in
               (select p.mispar_zehut
                  from poresh p
                 where p.mispar_zehut = h.mispar_zheut_fictivi
                   and p.taarich_ptira is null)
           and p.taarich_ptira is null
           and p2.taarich_ptira is null) loop
      dbms_output.put_line(r.mispar_zheut_fictivi || ' ' || r.mispar_zheut ||
                           v_delete_bakasha);
    
      for r2 in (select distinct *
                   from prisha pr
                  where pr.seq_poresh = r.fictivi_porshim_seq) loop
        update prisha pr
           set pr.seq_poresh = r.porshim_seq
         where pr.seq_prisha = r2.seq_prisha;
      end loop;
    
      delete from action_log where SEQ_PORESH = r.fictivi_porshim_seq;
      for r5 in (select *
                   from bney_mishpacha bm
                  where bm.Seq_Porshim = r.fictivi_porshim_seq) loop
        delete from MAZAV_MISHPACHTI mm
        
         where mm.seq_bney_mishpacha = r5.seq_bney_mishpacha;
      end loop;
      --TODO: להוסיף הערה מתפרצת : קיים 2 פרישות עקב 2 חשבונות שונים מחילן
      pk_prm_utils.insert_action_log_row(45,
                                         sysdate,
                                         1,
                                         null,
                                         'קיימות 2 פרישות עקב 2 חשבונות שונים מחילן',
                                         null,
                                         null,
                                         null,
                                         r.fictivi_seq_bakasha,
                                         null);
      pk_prm_utils.insert_action_log_row(45,
                                         sysdate,
                                         1,
                                         null,
                                         'קיימות 2 פרישות עקב 2 חשבונות שונים מחילן',
                                         null,
                                         null,
                                         null,
                                         r.seq_bakasha,
                                         null);
    
      delete from bney_mishpacha where SEQ_PORSHIM = r.fictivi_porshim_seq;
      delete from medical_vaada where SEQ_PORESH = r.fictivi_porshim_seq;
      delete from tashlum_guf where SEQ_PORESH = r.fictivi_porshim_seq;
      delete from tashlum_guf_draft
       where SEQ_PORESH = r.fictivi_porshim_seq;
      delete from address where seq_poresh = r.fictivi_porshim_seq;
      delete from MAZAV_MISHPACHTI
       where seq_poresh = r.fictivi_porshim_seq;
      delete from poresh p where p.porshim_seq = r.fictivi_porshim_seq;
    
      delete poresh po where po.porshim_seq = r.fictivi_porshim_seq;
      commit;
    end loop;
    execute immediate 'ALTER TRIGGER ERROR_ON_ID_UPDATE ENABLE';
  
  end;

  procedure BEN_ZUG_SHENI is
  
  begin
    for r in (select distinct bm.*
                from ld_mlm_10 m10
                left join bney_mishpacha bm
