  procedure delete_bm_kfulim is
  
  begin
    dbms_output.enable(999999999);
    for r in (SELECT DISTINCT p.porshim_seq,
                              bm.mispar_zehut_ben_mishpacha,
                              bm.Seq_Bney_Mishpacha,
                              p.mispar_zehut
                FROM BNEY_MISHPACHA BM
                left join poresh p
                  on p.porshim_seq = bm.Seq_Porshim
                left join BNEY_MISHPACHA BM2
                  on bm2.mispar_zehut_ben_mishpacha =
                     bm.mispar_zehut_ben_mishpacha
                 and bm2.Seq_Bney_Mishpacha <> bm.Seq_Bney_Mishpacha
                 and bm2.Seq_Porshim = bm.Seq_Porshim
               WHERE bm.mispar_zehut_ben_mishpacha not in
                     (42648261, 53340931)
                 and NOT EXISTS
               (SELECT *
                        FROM MAZAV_MISHPACHTI MM
                       WHERE MM.SEQ_BNEY_MISHPACHA = BM.Seq_Bney_Mishpacha)
                 AND BM.MISPAR_ZEHUT_BEN_MISHPACHA IN
                     (select bm.mispar_zehut_ben_mishpacha
                        from bney_mishpacha bm
                       group by bm.Seq_Porshim,
                                bm.taarich_leda,
                                bm.mispar_zehut_ben_mishpacha
                      having count(bm.mispar_zehut_ben_mishpacha) > 1)) loop
      dbms_output.put_line(r.mispar_zehut_ben_mishpacha || ' ' ||
                           r.mispar_zehut || ' ' || r.seq_bney_mishpacha);
      delete from bney_mishpacha bm
       where bm.Seq_Bney_Mishpacha = r.Seq_Bney_Mishpacha;
      commit;
    end loop;
  end;
