  procedure delete_kfulim_from_netuney_tik is
  begin
    dbms_output.enable(999999999);
    for r in (select distinct v.MISPAR_ZEHUT,
                              t.seq_bakasha,
                              t.code_department,
                              t.mispar_misra
                              
                             ,
                              count(*) as count
                from netuney_tik_mechushavim t
                left join v_bakasha v
                  on t.seq_bakasha = v.SEQ_BAKASHA
                left join mgl_log_hasava l
                  on l.mispar_zehut = v.MISPAR_ZEHUT
               where l.code_hasava = 12
                 and l.update_date > to_date('22072019', 'ddmmyyyy')
               group by v.MISPAR_ZEHUT,
                        t.seq_bakasha,
                        t.code_department,
                        t.mispar_misra
              having count(*) > 1
               order by count(*) desc) loop
      dbms_output.put_line(r.mispar_zehut || ' ' || r.count);
      delete from netuney_tik_mechushavim nt
       where nt.Seq_Bakasha = r.seq_bakasha
         and rownum <= (r.count - 1);
    
    end loop;
  end;

