  procedure hafskt_tshlm_TAHAS is
    --הפסקת תשלום תעש עבור שושנה שולמן
    v_date      date;
    V_MONTH     NUMERIC;
    V_MONTH_str varchar2(2);
  begin
    dbms_output.enable(999999999);
    for r in (select distinct po.taarich_leda, b.mispar_zehut, b.seq_prisha
                from v_bakasha_last_status b
                left join poresh po
                  on po.porshim_seq = b.seq_porshim
               where b.mispar_zehut in (12400222,
                                        27082064,
                                        51735488,
                                        51736700,
                                        51934347,
                                        52051836,
                                        52111671,
                                        52136231,
                                        52203585,
                                        52219714,
                                        52258969,
                                        52344090,
                                        53908323,
                                        65470809,
                                        67887059,
                                        67907444,
                                        51329399,
                                        50425602,
                                        64542319,
                                        65470213,
                                        76498070,
                                        78773785,
                                        52051836
                                        
                                        )) loop
      V_ID := r.mispar_zehut;
      --לאתחל לראשון לחודש הבא
      --v_date                := r.taarich_ptira + INTERVAL '1' MONTH;
      v_date := add_months(R.TAARICH_LEDA, 12 * 67);
      --  dbms_output.put_line(R.TAARICH_LEDA || ' ' || V_DATE);
      V_MONTH := (to_char(v_date, 'MM') + 1);
    
      IF (V_MONTH < 10) THEN
        V_MONTH_str := '0' || V_MONTH;
      ELSE
      
        V_MONTH_str := V_MONTH;
      END IF;
    
      IF (to_char(v_date, 'MM') < 12) THEN
      
        v_date := to_date(
                          
                          '01' || (V_MONTH_str) || (to_char(v_date, 'YYYY')),
                          'ddmmyyyy');
      
      ELSE
        V_MONTH_str := '01';
        v_date      := to_date(
                               
                               '01' || (V_MONTH_str) ||
                               (to_char(v_date, 'YYYY') + 1),
                               'ddmmyyyy');
      
      END IF;
      -- dbms_output.put_line(V_DATE);
      v_seq_Another_bakasha := bakasha_seq.nextval;
    
      insert into bakasha
        (seq_bakasha,
         seq_prisha,
         code_sug_bakasha,
         code_source,
         date_bakasha,
         FROM_DATE,
         DATE_UPDATE,
         CODE_BAKASHA_DETAIL)
      values
        (v_seq_Another_bakasha,
         r.seq_prisha,
         19,
         14,
         v_DATE,
         v_DATE,
         v_DATE,
         13) log errors into err_bakasha
        (v_ora_err_tag$) reject limit unlimited;
      dbms_output.put_line(r.mispar_zehut || ' ' || R.TAARICH_LEDA || ' ' ||
                           V_DATE || ' ' || v_seq_Another_bakasha);
    
      pk_prm_utils.insert_action_log_row(134,
                                         v_DATE,
                                         1,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         v_seq_Another_bakasha,
                                         null);
      commit;
      --134
    end loop;
  
  end;

