  PROCEDURE porshim_unidentified_EzorOvdim is
    --פורשים מזוהים לפי מספר גימלה ומ.ז, אך המשרד מחילן לא מזוהה במפמ  
  begin
    for r in (select distinct b.seq_ezor_ovdim,
                              b."SEQ_PRISHA",
                              b.porshim_seq,
                              b.mispar_zehut,
                              t.seq
                from temp_porshim_hilan t
                left join v_bakasha_by_zheut b
                  on (b.gimla_number = t.mispar_gimla or
                     b.gimla_number = trunc(t.mispar_gimla / 10))
                 and b.mispar_zehut = t.mispar_zehut
                left join code_ezor_ovdim e
                  on e.code_misrad_maskret = t.code_misrad_maskret
                 and e.code_ezor_ovdim = t.code_ezor_ovdim
               where t.log = 0
                 and b.mispar_zehut is not null) loop
    
      update temp_porshim_hilan tp
         set tp.Seq_Prisha = r.seq_prisha,
             tp.seq_poresh = r.porshim_seq,
             
             tp.log  = 7,
             tp.Note = 'Same values in:mispar zheut, mis_gimla / Without the last character and unidentified ezor_ovdim_hilan,  seq_ezor_ovdim mpm:' ||
                       r.seq_ezor_ovdim
       where tp.seq = r.seq;
      commit;
    end loop;
  
  end;
  -------------
  PROCEDURE porsh_BM_unidentified_EzrOvdim is
    -- בני משפחה מזוהים לפי מספר גימלה ומ.ז, אך המשרד מחילן לא מזוהה במפמ  
  begin
    for r in (select distinct b.seq_ezor_ovdim,
                              b."SEQ_PRISHA",
                              b.porshim_seq,
                              t.mispar_zehut,
                              b.mispar_zehut as mispar_zehut_poresh,
                              t.Seq,
                              bm.Seq_Bney_Mishpacha
                from temp_porshim_hilan t
                left join v_bakasha_by_zheut b
                  on (b.gimla_number = t.mispar_gimla or
                     b.gimla_number = trunc(t.mispar_gimla / 10))
                left join bney_mishpacha bm
                  on bm.Seq_Porshim = b.porshim_seq
                 and bm.mispar_zehut_ben_mishpacha = t.mispar_zehut
                left join code_ezor_ovdim e
                  on e.code_misrad_maskret = t.code_misrad_maskret
                 and e.code_ezor_ovdim = t.code_ezor_ovdim
               where t.log = 0
                 and bm.mispar_zehut_ben_mishpacha is not null) loop
    
      update temp_porshim_hilan tp
         set tp.Seq_Prisha          = r.seq_prisha,
             tp.seq_poresh          = r.porshim_seq,
             tp.Seq_Bney_Mishpacha  = r.Seq_Bney_Mishpacha,
             tp.mispar_zehut_poresh = r.mispar_zehut_poresh,
             tp.log                 = 8,
             tp.Note                = 'SHEER Same values in:mispar zheut, mis_gimla / Without last character and unidentified ezor_ovdim_hilan,  seq_ezor_ovdim mpm:' ||
                                      r.seq_ezor_ovdim
       where tp.seq = r.seq;
      commit;
    end loop;
  
  end;
  ---------------------------
  PROCEDURE poresh_ONCE_HILAN_MPM_B is
    -- פורש מופיע פעם אחת בחילן ופעם אחת במפמ עם  אזור עובדים שונה ןמס גימלה שונה
  begin
    for r in (select distinct b.gimla_number,
                              t.mispar_zehut,
                              t.Seq,
                              b."SEQ_PRISHA",
                              b.porshim_seq
              --,(select count (distinct  bm.Seq_Bney_Mishpacha) from bney_mishpacha bm where bm.mispar_zehut_ben_mishpacha=t.mispar_zehut) as bm_mpm,
              --(select count (distinct  b."SEQ_PRISHA") from v_bakasha_by_zheut b where b.mispar_zehut=t.mispar_zehut) as mpm,
              --(select count (distinct  tt.Seq) from TEMP_PORSHIM_HILAN tt where tt.mispar_zehut=t.mispar_zehut) as hilan,
              --(select count (distinct  ttt.Seq) from TEMP_PORSHIM_HILAN ttt where ttt.log=0 and ttt.mispar_zehut=t.mispar_zehut) as hilan_log_0
                from TEMP_PORSHIM_HILAN t
                left join v_bakasha_by_zheut b
                  on b.mispar_zehut = t.mispar_zehut
                left join Code_Ezor_Ovdim e
                  on e.Seq_Ezor_Ovdim = b.seq_ezor_ovdim
                left join Code_Ezor_Ovdim e2
                  on e2.code_ezor_ovdim = t.Code_Ezor_Ovdim
                 and e2.code_misrad_maskret = t.code_misrad_maskret
               where t.log = 0
                 and (e2.Seq_Ezor_Ovdim is null or
                     e2.Seq_Ezor_Ovdim <> b.seq_ezor_ovdim)
                 and b.mispar_zehut is not null
                 and (select count(distinct bm.Seq_Bney_Mishpacha)
                        from bney_mishpacha bm
                       where bm.mispar_zehut_ben_mishpacha = t.mispar_zehut) = 0
                 and (select count(distinct b."SEQ_PRISHA")
                        from v_bakasha_by_zheut b
                       where b.mispar_zehut = t.mispar_zehut) = 1
                 and (select count(distinct tt.Seq)
                        from TEMP_PORSHIM_HILAN tt
                       where tt.mispar_zehut = t.mispar_zehut) = 1) loop
    
      update temp_porshim_hilan tp
         set tp.Seq_Prisha = r.seq_prisha,
             tp.seq_poresh = r.porshim_seq,
             tp.log        = 10,
             tp.Note       = 'Poresh appears once in a HILAN and once in mapam in different\unidentified EzorOvdim  & different mispar gimla mpm' ||
                             r.gimla_number
       where tp.seq = r.seq;
      commit;
    end loop;
  
  end;
