  PROCEDURE update_ezor_ovdim_999 is
    --עדכון אזור עובדים של לא ידועים כשהגיע רק רשומה אחת מחילן
  begin
    for r in
    
     (select distinct bm.mispar_zehut_ben_mishpacha,
                      t.mispar_zehut,
                      b.seq_prisha,
                      
                      e.Seq_Ezor_Ovdim,
                      e.teur_ezor_ovdim,
                      t.code_misrad_maskret,
                      t.misrad_p_name,
                      t.code_ezor_ovdim,
                      t.yechida_name,
                      t.mispar_zehut_poresh
        from v_bakasha_last_status b
      
        left join temp_porshim_hilan t
          on --t.mispar_zehut = b.mispar_zehut
       nvl(t.mispar_gimla, 0) = b.gimla_number
        left join bney_mishpacha bm
          on bm.mispar_zehut_ben_mishpacha = t.mispar_zehut
        left join code_ezor_ovdim e
          on e.code_ezor_ovdim = t.Code_Ezor_Ovdim
         and e.code_misrad_maskret = t.code_misrad_maskret
       where e.Seq_Ezor_Ovdim is not null
         and bm.mispar_zehut_ben_mishpacha is not null
         and b.gimla_number = t.mispar_gimla
         and b.seq_ezor_ovdim = 999
         and t.mispar_zehut is not null
         and (select count(t.mispar_zehut)
                from temp_porshim_hilan t
               where t.mispar_gimla = b.gimla_number) = 1)
    
     loop
    
      update prisha pr
         set pr.seq_ezor_ovdim = r.Seq_Ezor_Ovdim
       where pr.seq_prisha = r.seq_prisha;
    end loop;
  
  end;
