  function mergePrishot return clob is
    v_report_html clob;
    --ריצה על פורשים שמספר הגימלה ומשרד המשכורת לא מופיעים במפמ
    code_ezor_ovdim NUMber;
    mis_prisha      NUMber;
  begin
  
    dbms_output.enable(9999999999999999999999999999);
    for r in (select distinct t.Seq,
                              substr(h5377.office, 1, 3) as misrad_maskoret,
                              substr(h5377.office, 4, 4) as ezor_ovdim,
                              h312.identity_number,
                              h312.value as midgimla,
                              h312.job_number
                from TEMP_PORSHIM_HILAN t
                left join v_bakasha_by_zheut b
                  on b.mispar_zehut = t.mispar_zehut
                left join Code_Ezor_Ovdim e
                  on e.Seq_Ezor_Ovdim = b.seq_ezor_ovdim
                left join Code_Ezor_Ovdim e2
                  on e2.code_ezor_ovdim = t.Code_Ezor_Ovdim
                 and e2.code_misrad_maskret = t.code_misrad_maskret
                left join ld_hilan_312 h312
                  on h312.identity_number = t.mispar_zehut
                 and h312.variable_type = 100
                 and (to_number(h312.value)) = t.mispar_gimla
                left join WARNING_DATA_CONVERSION w
                  on w.mispar_zheut = t.mispar_zehut
                 and w.Current_Value in
                     ('SEQ_BAKASHA not found', 'SEQ__prisha not found')
              
                left join ld_hilan_537 h5377
                  on h5377.identity_number = h312.identity_number
                 and h5377.job_number = h312.job_number
              
               where -- h312.identity_number = 10440493 and
               h312.value is not null
           and t.log = 0
           and (select count(h312.job_number)
                  from ld_hilan_312 h312
                 where h312.identity_number in
                       ((select distinct h200.identity_number
                          from ld_hilan_200 h200
                         where h200.dummy_identity_number = t.mispar_zehut))
                      
                   and h312.variable_type = 102
                   and to_number(h312.value) in
                       (126, 128, 226, 228, 326, 426, 526, 528, 428, 328, 628)) = 0
              --   and t.mispar_zehut = 6381990
              /*  and not exists
              (select *
                       from mgl_log_hasava l
                      where l.update_date > to_date('09122019', 'ddmmyyyy')
                        and l.code_hasava = 12
                        and l.mispar_zehut = t.mispar_zehut)*/
              
              ) loop
      ResetFields;
      mis_prisha        := null;
      V_ID              := r.identity_number;
      v_misrad_maskoret := r.misrad_maskoret;
      v_job_number      := r.job_number;
      v_ora_err_tag$    := to_char(v_id);
      v_where           := ' where ora_err_tag$= ''' || v_ora_err_tag$ || '''';
      code_ezor_ovdim   := convert_seq_ezor_ovdim(r.misrad_maskoret,
                                                  r.ezor_ovdim);
    
      begin
      
        select distinct b.seq_porshim
          into v_porshim_seq
          from v_bakasha_last_status b
         where b.mispar_zehut in
               (select distinct h200.identity_number
                  from ld_hilan_200 h200
                 where h200.dummy_identity_number = v_id)
              
           and rownum = 1;
      
      exception
        when no_data_found then
          mis_prisha := null;
        
      end;
    
      begin
      
        select distinct b.seq_prisha
          into mis_prisha
          from v_bakasha_last_status b
         where b.mispar_zehut in
               (select distinct h200.identity_number
                  from ld_hilan_200 h200
                 where h200.dummy_identity_number = r.identity_number)
           and b.seq_ezor_ovdim = code_ezor_ovdim
           and rownum = 1;
      
      exception
        when no_data_found then
          mis_prisha := null;
        
      end;
      dbms_output.put_line(r.identity_number || 'v_seq_prisha' ||
                           mis_prisha);
    
      if mis_prisha is null then
      
        --************
      
        if update_prisha = false or update_bakasha(1) = false or
           update_bakasha_regila = false then
          v_is_do_commit := false;
          goto endloop1;
        end if;
        --add row log succses
        add_row_to_mgl_log_hasava(v_id,
                                  12,
                                  'v_job_number :' || v_job_number);
        update temp_porshim_hilan t
           set t.log        = 13,
               t.Note       = 'New prisha was added per poresh',
               t.seq_prisha = v_seq_prisha,
               t.Seq_Poresh = v_porshim_seq
         where t.Seq = r.Seq
           and t.log = 0;
      
        --not must tables
        if (V_is_updated_PORESH_DATA = false) then
          V_is_updated_PORESH_DATA := TRUE;
          update_mazav_mishpachti(null); --V
          update_ADDRESS; --V
          update_PRISHA_BANK_ACCOUNT; --V       
          update_bney_mishpaha; --V
        end if;
        V_CHELKIYUT_MESHUKLELET := null;
        update_hafsakat_tashlum(false);
        if (v_is_HOZE_BHIRIM) then
          --טיפול מיוחד לחוזה בכירים
          HOZE_BHIRM_2_netny_tik_mchshvm(true);
        else
          update_netuney_tik_mechushavim; --V
        end if;
        update_HIVUN;
        update_DARGA_VEDERUG_TIK; --V  
        update_VETEK_DETAIL;
        merge_actions_log;
        update_actions_log;
        -- end if;
      
        SET_IS_participation_M_guf;
      
        --השתתפות מגוף
        if (v_is_exist_participation_M_guf) then
          v_seq_bakasha := null;
          if update_bakasha(7) = false or update_bakasha_regila = false then
            v_is_do_commit := false;
            goto endloop1;
          
          end if;
          if (v_is_HOZE_BHIRIM) then
            --טיפול מיוחד לחוזה בכירים
            HOZE_BHIRM_2_netny_tik_mchshvm(true);
          else
            update_netuney_tik_mechushavim; --V
          end if;
          update_HIVUN;
          update_DARGA_VEDERUG_TIK; --V  
          update_VETEK_DETAIL;
          merge_actions_log;
          update_actions_log;
          update_participation_m_guf;
        
        end if;
      end if;
      --I'M inserting
      -- commit;
      <<endloop1>>
      v_report_html := v_report_html ||
                      
                       info_about_errors_and_commit(v_is_do_commit, '');
      commit;
    
    end loop;
  
    return v_report_html;
    --********************
  
  end;

  PROCEDURE update_aaa is
    --עדכון הרשומות מטבלת בני משפחה למרות שמספר הגימלה שונה 
  begin
    for r in (select distinct p.porshim_seq,
                              bm.Seq_Bney_Mishpacha,
                              pr.seq_prisha,
                              p.mispar_zehut as mispar_zehut_PORESH,
                              t.Seq
                from TEMP_PORSHIM_HILAN t
                left join bney_mishpacha bm
                  on bm.mispar_zehut_ben_mishpacha = t.mispar_zehut
                left join poresh p
                  on p.Porshim_Seq = bm.Seq_Porshim
                left join PRISHA pr
                  on pr.seq_poresh = bm.Seq_Porshim
               where bm.mispar_zehut_ben_mishpacha > 0
                 and (select count(tt.Seq)
                        from temp_porshim_hilan tt
                       where tt.mispar_zehut = t.mispar_zehut) = 1
                 and exists (select h312.job_number
                        from ld_hilan_312 h312
                       where h312.identity_number in
                             ((select distinct h200.identity_number
                                from ld_hilan_200 h200
                               where h200.dummy_identity_number =
                                     t.mispar_zehut))
                            
                         and h312.variable_type = 102
                         and to_number(h312.value) in
                             (126,
                              128,
                              226,
                              228,
                              326,
                              426,
                              526,
                              528,
                              428,
                              328,
                              628))
                 and
                    
                     t.log = 0) loop
    
      update temp_porshim_hilan tp
         set tp.Seq_Prisha         = r.SEQ_PRISHA,
             tp.seq_bney_mishpacha = r.seq_bney_mishpacha,
             tp.Seq_Poresh         = r.porshim_seq,
             tp.log                = 14,
             tp.note               = 'Sheer: update this record from bney mishpacha tbl, Different mis gimla'
       where tp.Seq = r.seq;
    end loop;
  end;

  PROCEDURE update_Job_number_312_410 is
  begin
    dbms_output.enable(9999999999999999999999999999999999999);
    for r in (select distinct h3112.Seq, h312.job_number, t.mispar_zehut
              
              /*               , (select count (distinct  bm.Seq_Bney_Mishpacha) from bney_mishpacha bm where bm.mispar_zehut_ben_mishpacha=t.mispar_zehut) as bm_mpm,
              (select count (distinct  b."SEQ_PRISHA") from v_bakasha_by_zheut b where b.mispar_zehut=t.mispar_zehut) as mpm,
              (select count (distinct  tt.Seq) from TEMP_PORSHIM_HILAN tt where tt.mispar_zehut=t.mispar_zehut) as hilan,
              (select count (distinct  ttt.Seq) from TEMP_PORSHIM_HILAN ttt where ttt.log=0 and ttt.mispar_zehut=t.mispar_zehut) as hilan_log_0,
               (select count (distinct  h537.job_number) from Ld_Hilan_537 h537 where h537.identity_number = t.mispar_zehut) as hilan_hasava
               ,(select count (h312.job_number)
                           from ld_hilan_312 h312
                          where h312.identity_number = t.mispar_zehut
                            
                            and h312.variable_type = 102
                            and to_number(h312.value)  in
                                (126,
                                 128,
                                 226,
                                 228,
                                 326,
                                 426,
                                 526,
                                 528,
                                 428,
                                 328,
                                 628)) as hilan_hasava_sheer*/
              
                from TEMP_PORSHIM_HILAN t
                left join v_bakasha_by_zheut b
                  on b.mispar_zehut = t.mispar_zehut
                left join Code_Ezor_Ovdim e
                  on e.Seq_Ezor_Ovdim = b.seq_ezor_ovdim
                left join Code_Ezor_Ovdim e2
                  on e2.code_ezor_ovdim = t.Code_Ezor_Ovdim
                 and e2.code_misrad_maskret = t.code_misrad_maskret
                left join ld_hilan_537 h537
                  on h537.identity_number = t.mispar_zehut
              
                left join ld_hilan_312 h312
                  on h312.identity_number = t.mispar_zehut
                 and h312.variable_type = 100
                 and (to_number(h312.value)) = t.mispar_gimla
                left join WARNING_DATA_CONVERSION w
                  on w.mispar_zheut = t.mispar_zehut
                 and w.Current_Value in
                     ('SEQ_BAKASHA not found', 'SEQ__prisha not found')
                left join v_bakasha_by_zheut b2
                  on b2.gimla_number > 2
                 and b2.gimla_number = t.mispar_gimla
                left join ld_hilan_312 h3112
                  on h3112.identity_number in
                     ((select distinct h200.identity_number
                        from ld_hilan_200 h200
                       where h200.dummy_identity_number = t.mispar_zehut))
                 and h3112.variable_type = 410
              
               where h312.value is not null
                 and t.log = 0
                 and nvl(b2.gimla_number, 0) > 0
                 and h3112.value > 0
                    
                 and (select count(distinct b."SEQ_PRISHA")
                        from v_bakasha_by_zheut b
                       where b.mispar_zehut = t.mispar_zehut) = 1
                 and (select count(distinct tt.Seq)
                        from TEMP_PORSHIM_HILAN tt
                       where tt.mispar_zehut = t.mispar_zehut) = 2
                 and (select count(h312.job_number)
                        from ld_hilan_312 h312
                       where h312.identity_number = t.mispar_zehut
                            
                         and h312.variable_type = 102
                         and to_number(h312.value) in
                             (126,
                              128,
                              226,
                              228,
                              326,
                              426,
                              526,
                              528,
                              428,
                              328,
                              628)) = 1) loop
      update ld_hilan_312 h312
         set h312.job_number = r.job_number
       where h312.Seq = r.seq;
      dbms_output.put_line(r.seq);
    
    end loop;
  end;

  function MERGE_SHEERIM_whith_JN return clob is
    v_report_html          clob;
    v_is_do_commit         boolean;
    v_is_update_Porsh_data boolean;
    V_ERR                  varchar2(100);
  
  begin
  
    execute immediate 'alter session set nls_language= ''american''';
    execute immediate 'alter session set nls_date_language=''english''';
    execute immediate 'alter session set nls_date_format=''dd-mon-yyyy''';
  
    --  DELETE_BNEY_MISHPACHA;
    --LOOP PORSHIM
    for r in (select distinct h312.value as identity_number
              
                from Ld_Hilan_312 h312
                left join LD_HILAN_312 hh312
                  on hh312.identity_number = h312.identity_number
                 and hh312.job_number = h312.job_number
                 and hh312.variable_type = 102
               where h312.value in
                     (select distinct h3112.value
                        from TEMP_PORSHIM_HILAN t
                        left join v_bakasha_by_zheut b
                          on b.mispar_zehut = t.mispar_zehut
                        left join Code_Ezor_Ovdim e
                          on e.Seq_Ezor_Ovdim = b.seq_ezor_ovdim
                        left join Code_Ezor_Ovdim e2
                          on e2.code_ezor_ovdim = t.Code_Ezor_Ovdim
                         and e2.code_misrad_maskret = t.code_misrad_maskret
                        left join ld_hilan_537 h537
                          on h537.identity_number = t.mispar_zehut
                      
                        left join ld_hilan_312 h312
                          on h312.identity_number = t.mispar_zehut
                         and h312.variable_type = 100
                         and (to_number(h312.value)) = t.mispar_gimla
                        left join WARNING_DATA_CONVERSION w
                          on w.mispar_zheut = t.mispar_zehut
                         and w.Current_Value in
                             ('SEQ_BAKASHA not found',
                              'SEQ__prisha not found')
                        left join v_bakasha_by_zheut b2
                          on b2.gimla_number > 2
                         and b2.gimla_number = t.mispar_gimla
                        left join ld_hilan_312 h3112
                          on h3112.identity_number in
                             ((select distinct h200.identity_number
                                from ld_hilan_200 h200
                               where h200.dummy_identity_number =
                                     t.mispar_zehut))
                         and h3112.variable_type = 410
                      
                       where h312.value is not null
                         and t.log = 0
                         and nvl(b2.gimla_number, 0) > 0
                         and h3112.value > 0
                            
                         and (select count(distinct b."SEQ_PRISHA")
                                from v_bakasha_by_zheut b
                               where b.mispar_zehut = t.mispar_zehut) = 1
                         and (select count(distinct tt.Seq)
                                from TEMP_PORSHIM_HILAN tt
                               where tt.mispar_zehut = t.mispar_zehut) = 2
                         and (select count(h312.job_number)
                                from ld_hilan_312 h312
                               where h312.identity_number = t.mispar_zehut
                                    
                                 and h312.variable_type = 102
                                 and to_number(h312.value) in
                                     (126,
                                      128,
                                      226,
                                      228,
                                      326,
                                      426,
                                      526,
                                      528,
                                      428,
                                      328,
                                      628)) = 1)
                    
                 and h312.variable_type = 410
                 and hh312.value in
                     (126, 128, 226, 228, 326, 426, 526, 528, 428, 328, 628)
                 and exists (select p.mispar_zehut
                        from PORESH p
                       where p.mispar_zehut = h312.Value)
                    
                 and not exists
               (select *
                        from mgl_log_hasava l
                       where l.mispar_zehut = h312.value
                         and l.code_hasava in ( --12, 13
                                               16,
                                               17))
              
               order by h312.value) loop
      ResetFields;
      V_ERR          := null;
      v_is_do_commit := true;
      v_id           := r.identity_number;
      --v_SHEER_ID     := r.bm_identity_number;
      v_ora_err_tag$ := to_char(v_id);
      v_where        := ' where ora_err_tag$= ''' || v_ora_err_tag$ || '''';
    
      /*if validate_id(1, r.identity_number) = false then
      
        v_is_do_commit := false;
        goto endloop1;
      end if;*/
    
      -------------**********
      --LOPP MISRADEY PRISHA
      for r2 in (select distinct h312.value as identity_number,
                                 substr(h537.office, 1, 3) as misrad_maskoret,
                                 h537.job_number
                   from ld_hilan_537 h537
                   left join ld_hilan_312 h312
                     on h312.identity_number = h537.identity_number
                    and h312.job_number = h537.job_number
                    and h312.variable_type = 410
                   left join LD_HILAN_312 hh312
                     on hh312.identity_number = h312.identity_number
                    and hh312.job_number = h312.job_number
                    and hh312.variable_type = 102
                  where h312.variable_type = 410
                    and h312.value is not null
                    and hh312.value in (126,
                                        128,
                                        226,
                                        228,
                                        326,
                                        426,
                                        526,
                                        528,
                                        428,
                                        328,
                                        628)
                    and h312.value = r.identity_number) loop
      
        v_job_number      := r2.job_number;
        v_misrad_maskoret := r2.misrad_maskoret;
        set_global_fields(1, false);
        if (v_seq_prisha is null) then
        
          --ADD ROW TO CHRIGIM...
          Add_warning_data_conversion_ROW('SEQ__prisha not found',
                                          'SEQ_prisha not found',
                                          'PRISHA',
                                          'SEQ_prisha');
          v_is_do_commit := false;
          goto endloop1;
        
        else
          if v_seq_bakasha is null then
            Add_warning_data_conversion_ROW('SEQ_BAKASHA not found',
                                            'SEQ_BAKASHA not found',
                                            'BAKASHA',
                                            'SEQ_BAKASHA');
          
            v_is_do_commit := false;
            goto endloop1;
          end if;
        end if;
      
        set_Taarich_PRISHA_PTIRA;
        --איפוס שדות CODE_RELATIVE ו ACHUZ_KIZTBA
        RESET_Bney_Mishpaha_FIELDS;
      
        --LOOP SHEERIM
        v_is_update_Porsh_data := false;
        for r3 in (select distinct h312.identity_number as bm_identity_number,
                                   h312.job_number
                     from ld_hilan_312 h312
                    where h312.value = r.identity_number
                      and h312.job_number = r2.job_number
                      and h312.variable_type = 410) loop
        
          v_SHEER_ID := r3.bm_identity_number;
          if (v_date_ptira <= v_date_prisha) then
          
            --טיפול בשאר בשירות
          
            if (v_is_update_Porsh_data = false) then
              v_is_update_Porsh_data := true;
              add_row_to_mgl_log_hasava(v_id, 17, 'שאר בשירות');
            
              /*              v_id := r3.bm_identity_number;
              mergeDataHandling;
              v_id := r.identity_number;*/
            end if;
            update_SHEERIM_bney_mishpaha;
          
            -------------------השתתפות מגוף לשאר בשירות------------           
            SET_IS_participation_M_guf;
            if (v_is_exist_participation_M_guf) then
              v_seq_bakasha := null;
              v_id          := r.identity_number;
              set_global_fields(7, false);
              set_MIS_GIMLA;
              participation_m_guf_Handling(7);
            end if;
            -----------------------סוף השתתפות מגוף לשאר בשרות-----------------
          else
            --טיפול בשאר פנסיוני
            V_from_COpy_BAKAHSHA := v_seq_bakasha;
            v_seq_bakasha        := null;
            set_global_fields(13, false);
            -- יש ליצור בקשת שאר פנסיוני במקרה שלא מצא..
            if (v_seq_bakasha is null and v_seq_prisha is not null) then
              v_id := r3.bm_identity_number;
              if (update_bakasha(13) = false or
                 update_bakasha_regila = false) then
              
                V_ERR          := 'Failed to create a Bakashat Sheer Pensyony';
                v_is_do_commit := false;
                goto endloop1;
              else
              
                V_CHELKIYUT_MESHUKLELET := null;
                -- update_hafsakat_tashlum; --הכנסתי את הטיםול update_SHEERIM_bney_mishpahaל 
                update_netuney_tik_mechushavim; --V
                update_HIVUN;
              
                update_DARGA_VEDERUG_TIK; --V  
                update_VETEK_DETAIL;
                merge_actions_log;
                update_actions_log;
                update_SHEERIM_bney_mishpaha;
                v_id := r3.bm_identity_number;
                add_row_to_mgl_log_hasava(r.identity_number,
                                          17,
                                          v_SHEER_ID || '-' ||
                                          'שאר פנסיוני - נוצרה בקשה חדשה מסוג שאר פנסיוני');
              
              end if;
            
            else
              if v_seq_bakasha is not null then
              
                if (v_is_update_Porsh_data = false) then
                  v_is_update_Porsh_data := true;
                
                  --mergeDataHandling;
                  add_row_to_mgl_log_hasava(v_id,
                                            17,
                                            v_SHEER_ID || '-' ||
                                            'שאר פנסיוני - עדכון בקשת שאר קיימת');
                  merge_actions_log;
                
                end if;
                update_SHEERIM_bney_mishpaha;
              
              end if;
            end if;
            v_id := r3.bm_identity_number;
            merge_netuny_tik_2SHeeR_PNSYNY;
            update_tkufot_avoda_mehushv;
          
            --השתתפות מגוף לשאר פנסיוני
          
            SET_IS_participation_M_guf;
            if (v_is_exist_participation_M_guf) then
              v_seq_bakasha := null;
              v_id          := r.identity_number;
              set_global_fields(23, false);
              set_MIS_GIMLA;
              v_id := r3.bm_identity_number;
              participation_m_guf_Handling(23);
            
            end if;
            v_id := r.identity_number;
            ------------------סוף השתתפות מגוף לשאר פנסיוני-----------
            --END SHEER PENSYONY
          end if;
        
          update temp_porshim_hilan tp
             set tp.Seq_Poresh          = v_porshim_seq,
                 tp.seq_prisha          = v_seq_prisha,
                 tp.mispar_zehut_poresh = v_id,
                 tp.log                 = 15,
                 tp.note                = 'SHEER: Added from MERGE_SHEERIM_whith_JobNumber'
           where tp.mispar_zehut = v_SHEER_ID
             and tp.log = 0
             and tp.mispar_gimla = v_mis_Gimla;
        
        end loop;
        update_Sum_BM_N_T_MCHUSHAVIM;
      end loop;
    
      <<endloop1>>
    
      v_report_html := v_report_html ||
                      
                       info_about_errors_and_commit(v_is_do_commit, V_ERR);
    end loop;
  
    commit;
    return v_report_html;
  end;

  PROCEDURE INSERT_SHEERIM_2_BM_TBL is
    v_seq_new_bm number;
  begin
  
    for r in (select distinct b."SEQ_PRISHA",
                              b.porshim_seq,
                              t.seq,
                              t.mispar_zehut,
                              t.last_name,
                              t.first_name
                from TEMP_PORSHIM_HILAN t
                left join v_bakasha_by_zheut b
                  on b.gimla_number = t.mispar_gimla
                left join bney_mishpacha bm
                  on bm.mispar_zehut_ben_mishpacha = t.mispar_zehut
                left join v_bakasha_by_zheut b2
                  on b2.porshim_seq = bm.Seq_Porshim
               where t.log = 0
                 and b.gimla_number > 2
                 and b.shem_mishpacha = t.last_name
                 and b.mispar_zehut <> t.mispar_zehut
                 and t.mispar_zehut <> 51166361
                 and b2.mispar_zehut is null
                 and b.shem_prati not like t.first_name) loop
      v_seq_new_bm := bney_mishpacha_seq.nextval;
      insert into bney_mishpacha bm
        (bm.mispar_zehut_ben_mishpacha,
         bm.Seq_Porshim,
         bm.shem_prati,
         bm.shem_mishpacha,
         bm.Code_Relative,
         bm.code_kirva,
         bm.Seq_Bney_Mishpacha)
      VALUES
        (r.mispar_zehut,
         r.porshim_seq,
         r.first_name,
         r.last_name,
         1,
         1,
         v_seq_new_bm);
      update TEMP_PORSHIM_HILAN t
         set t.Seq_Prisha         = r.Seq_Prisha,
             t.Seq_Poresh         = r.Porshim_Seq,
             t.Seq_Bney_Mishpacha = v_seq_new_bm
       where t.Seq = r.Seq;
    end loop;
  
  end;
  -----------------------------
  function MERGE_SHEERIM_WITH_BM_TBL_B return clob is
    --הסבת שארים שנוצרו בטבלת בני משפחה ב INSERT_SHEERIM_2_BM_TBL 
    v_report_html          clob;
    v_is_do_commit         boolean;
    v_is_update_Porsh_data boolean;
    V_ERR                  varchar2(100);
  
  begin
  
    execute immediate 'alter session set nls_language= ''american''';
    execute immediate 'alter session set nls_date_language=''english''';
    execute immediate 'alter session set nls_date_format=''dd-mon-yyyy''';
  
    DELETE_BNEY_MISHPACHA;
    --LOOP PORSHIM
    for r in (select distinct t.Seq,
                              bm.Seq_Bney_Mishpacha,
                              hh312.identity_number as bm_identity_number,
                              p.mispar_zehut as identity_number,
                              hh312.job_number,
                              substr(h537.office, 1, 3) as misrad_maskoret
              --, bm.mispar_zehut_ben_mishpacha, bm.shem_prati || bm.shem_mishpacha, convert_low_hebrew_to_ascii(h200.first_name||h200.last_name) 
                from LD_HILAN_312 hh312
                left join ld_hilan_200 h200
                  on h200.identity_number = hh312.identity_number
                left join bney_mishpacha bm
                  on bm.mispar_zehut_ben_mishpacha = hh312.identity_number
                left join poresh p
                  on p.Porshim_Seq = bm.Seq_Porshim
                left join ld_hilan_537 h537
                  on h537.identity_number = hh312.identity_number
                 and h537.job_number = hh312.job_number
                left join TEMP_PORSHIM_HILAN t
                  on t.mispar_zehut = bm.mispar_zehut_ben_mishpacha
               where t.log = 0
                 and nvl(t.Seq_Poresh, 0) > 0
                 and nvl(bm.mispar_zehut_ben_mishpacha, 0) > 0
                 and hh312.variable_type = 102
                 and hh312.value in
                     (126, 128, 226, 228, 326, 426, 526, 528, 428, 328, 628)
                 and not exists
               (select *
                        from mgl_log_hasava l
                       where l.mispar_zehut = p.mispar_zehut
                         and l.code_hasava in (16, 17))
               order by p.mispar_zehut) loop
      ResetFields;
      V_ERR          := null;
      v_is_do_commit := true;
    
      v_id := r.identity_number;
      --v_SHEER_ID     := r.bm_identity_number;
      v_ora_err_tag$ := to_char(v_id);
      v_where        := ' where ora_err_tag$= ''' || v_ora_err_tag$ || '''';
    
      -------------**********
      --LOPP MISRADEY PRISHA
      /*  for r2 in (select distinct bm.mispar_zehut_ben_mishpacha as bm_identity_number,
                      h537.identity_number,
                      substr(h537.office, 1, 3) as misrad_maskoret,
                      h5372.job_number
                      -- p.mispar_zehut as  identity_number
                      --, bm.mispar_zehut_ben_mishpacha
                     ,
                      bm.shem_prati || bm.shem_mishpacha,
                      convert_low_hebrew_to_ascii(h200.first_name ||
                                                  h200.last_name)
        from LD_HILAN_312 hh312
        left join ld_hilan_200 h200
          on h200.identity_number = hh312.identity_number
        left join bney_mishpacha bm
          on bm.mispar_zehut_ben_mishpacha =
             hh312.identity_number
        left join poresh p
          on p.Porshim_Seq = bm.Seq_Porshim
        left join ld_hilan_537 h537
          on h537.identity_number = R.identity_number
      --and h537.job_number = hh312.job_number
        left join ld_hilan_537 h5372
          on h5372.identity_number = hh312.identity_number
         and h5372.office = h537.office
      
       where h5372.office = h537.office
         AND nvl(bm.mispar_zehut_ben_mishpacha, 0) > 0
         and hh312.variable_type = 102
         and hh312.value in (126,
                             128,
                             226,
                             228,
                             326,
                             426,
                             526,
                             528,
                             428,
                             328,
                             628)
         and not exists
       (select *
                from mgl_log_hasava l
               where l.mispar_zehut = p.mispar_zehut
                 and l.code_hasava in (16, 17))
         and h537.identity_number = r.identity_number) loop*/
    
      v_job_number      := r.job_number;
      v_misrad_maskoret := r.misrad_maskoret;
      set_global_fields(1, false);
      if (v_seq_prisha is null) then
      
        --ADD ROW TO CHRIGIM...
        Add_warning_data_conversion_ROW('SEQ__prisha not found',
                                        'SEQ_prisha not found',
                                        'PRISHA',
                                        'SEQ_prisha');
        v_is_do_commit := false;
        goto endloop1;
      
      else
        if v_seq_bakasha is null then
          Add_warning_data_conversion_ROW('SEQ_BAKASHA not found',
                                          'SEQ_BAKASHA not found',
                                          'BAKASHA',
                                          'SEQ_BAKASHA');
        
          v_is_do_commit := false;
          goto endloop1;
        end if;
      end if;
    
      set_Taarich_PRISHA_PTIRA;
      --איפוס שדות CODE_RELATIVE ו ACHUZ_KIZTBA
      RESET_Bney_Mishpaha_FIELDS;
    
      --LOOP SHEERIM
      v_is_update_Porsh_data := false;
      /* for r3 in (select m22.identity_number as bm_identity_number,
            hh312.job_number
       from Ld_Mlm_22 m22
       left join LD_HILAN_312 hh312
         on hh312.identity_number = m22.identity_number
        and hh312.variable_type = 102
      Where m22.pensioner_identity = r2.identity_number
        and hh312.job_number = r2.job_number
        and m22.is_erased = 0
        and hh312.value in (126,
                            128,
                            226,
                            228,
                            326,
                            426,
                            526,
                            528,
                            428,
                            328,
                            628)) loop*/
    
      v_SHEER_ID := r.bm_identity_number;
    
      update temp_porshim_hilan tp
         set tp.Seq_Prisha          = v_seq_prisha,
             tp.seq_poresh          = v_porshim_seq,
             tp.mispar_zehut_poresh = v_id,
             tp.Seq_Bney_Mishpacha  = r.Seq_Bney_Mishpacha,
             tp.log                 = 16,
             tp.Note                = 'SHEER: Added from MERGE_SHEERIM_WITH_BM_TBL_B:apear same mispar gimla'
       where tp.seq = r.seq;
    
      if (v_date_ptira <= v_date_prisha) then
      
        --טיפול בשאר בשירות
      
        if (v_is_update_Porsh_data = false) then
          v_is_update_Porsh_data := true;
          add_row_to_mgl_log_hasava(v_id, 17, 'שאר בשירות');
        
          /*              v_id := r3.bm_identity_number;
          mergeDataHandling;
          v_id := r.identity_number;*/
        end if;
        update_SHEERIM_bney_mishpaha;
        -------------------השתתפות מגוף לשאר בשירות------------           
        SET_IS_participation_M_guf;
        if (v_is_exist_participation_M_guf) then
          v_seq_bakasha := null;
          v_id          := r.identity_number;
          set_global_fields(7, false);
          set_MIS_GIMLA;
          participation_m_guf_Handling(7);
        end if;
        -----------------------סוף השתתפות מגוף לשאר בשרות-----------------
      
      else
        --טיפול בשאר פנסיוני
        V_from_COpy_BAKAHSHA := v_seq_bakasha;
        v_seq_bakasha        := null;
        set_global_fields(13, false);
        -- יש ליצור בקשת שאר פנסיוני במקרה שלא מצא..
        if (v_seq_bakasha is null and v_seq_prisha is not null) then
          v_id := r.bm_identity_number;
          if (update_bakasha(13) = false or update_bakasha_regila = false) then
          
            V_ERR          := 'Failed to create a Bakashat Sheer Pensyony';
            v_is_do_commit := false;
            goto endloop1;
          else
          
            V_CHELKIYUT_MESHUKLELET := null;
            -- update_hafsakat_tashlum; --הכנסתי את הטיםול update_SHEERIM_bney_mishpahaל 
            update_netuney_tik_mechushavim; --V
            update_HIVUN;
          
            update_DARGA_VEDERUG_TIK; --V  
            update_VETEK_DETAIL;
            merge_actions_log;
            update_actions_log;
            update_SHEERIM_bney_mishpaha;
            v_id := r.bm_identity_number;
            add_row_to_mgl_log_hasava(r.identity_number,
                                      17,
                                      v_SHEER_ID || '-' ||
                                      'שאר פנסיוני - נוצרה בקשה חדשה מסוג שאר פנסיוני');
          
          end if;
        
        else
          if v_seq_bakasha is not null then
          
            if (v_is_update_Porsh_data = false) then
              v_is_update_Porsh_data := true;
            
              --mergeDataHandling;
              add_row_to_mgl_log_hasava(v_id,
                                        17,
                                        v_SHEER_ID || '-' ||
                                        'שאר פנסיוני - עדכון בקשת שאר קיימת');
            
            end if;
            update_SHEERIM_bney_mishpaha;
          
          end if;
        end if;
        v_id := r.bm_identity_number;
        merge_netuny_tik_2SHeeR_PNSYNY;
        update_tkufot_avoda_mehushv;
        --השתתפות מגוף לשאר פנסיוני
      
        SET_IS_participation_M_guf;
        if (v_is_exist_participation_M_guf) then
          v_seq_bakasha := null;
          v_id          := r.identity_number;
          set_global_fields(23, false);
          set_MIS_GIMLA;
          v_id := r.bm_identity_number;
          participation_m_guf_Handling(23);
        
        end if;
        v_id := r.identity_number;
        ------------------סוף השתתפות מגוף לשאר פנסיוני-----------
      
        --END SHEER PENSYONY
      end if;
    
      --end loop;
      update_Sum_BM_N_T_MCHUSHAVIM;
      --end loop;
    
      <<endloop1>>
    
      v_report_html := v_report_html ||
                      
                       info_about_errors_and_commit(v_is_do_commit, V_ERR);
    end loop;
  
    commit;
    return v_report_html;
  end;
