  PROCEDURE porshim_from_hilan_BM_15 is
    --לוג 15 שארים שהוקמו  בהסבה MERGE_SHEERIM_whith_JobNumber  ...
  begin
  
    for r in (SELECT distinct b.mispar_zehut as mispar_zehut_poresh,
                              t.Seq,
                              b.seq_porshim,
                              b.seq_prisha,
                              bm.Seq_Bney_Mishpacha,
                              t.mispar_zehut,
                              t.code_misrad_maskret,
                              t.code_ezor_ovdim
                FROM temp_porshim_hilan t
                left join bney_mishpacha bm
                  on bm.mispar_zehut_ben_mishpacha = t.mispar_zehut
                left join v_bakasha_last_status b
                  on b.seq_porshim = bm.Seq_Porshim
                left join code_ezor_ovdim ee
                  on ee.Seq_Ezor_Ovdim = b.seq_ezor_ovdim
               where t.log = 15
                 and ee.Code_Misrad_Maskret = t.Code_Misrad_Maskret
                 and ee.code_ezor_ovdim = t.Code_Ezor_Ovdim
                 and (t.mispar_gimla = b.gimla_number or
                     trunc(t.mispar_gimla / 10) = b.gimla_number)) loop
    
      update temp_porshim_hilan tp
         set tp.Seq_Prisha          = r.seq_prisha,
             tp.seq_poresh          = r.seq_porshim,
             tp.Seq_Bney_Mishpacha  = r.seq_bney_mishpacha,
             tp.mispar_zehut_poresh = r.mispar_zehut_poresh,
             -- tp.log                 = 4,
             tp.Note = 'SHEER: Added from MERGE_SHEERIM_whith_JobNumber,Record of SHEER: Same values in: mis_gimla/Without the last character , Code_Misrad_Maskret,code_ezor_ovdim'
       where tp.seq = r.seq;
      commit;
    end loop;
  
  end;

  PROCEDURE porshim_BM_dfrnt_EzorOvdim_15 is
  
  begin
    --זיהוי לפי מספר גימלה ובן משפחה מטבלת בני משפחה
    --ומשרדים שונים
    for r in (select distinct t.Seq,
                              b.mispar_zehut         as mispar_zehut_poresh,
                              b."SEQ_PRISHA",
                              b.porshim_seq,
                              t.mispar_zehut,
                              bm.Seq_Bney_Mishpacha,
                              t.misrad_p_name,
                              t.yechida_name,
                              e.code_ezor_ovdim,
                              e.code_misrad_maskret,
                              e.teur_ezor_ovdim,
                              e2.code_ezor_ovdim     as code_ezor_ovdim_MPM,
                              e2.code_misrad_maskret as code_misrad_maskret_MPM,
                              e2.Teur_Ezor_Ovdim     as Teur_Ezor_Ovdim_MPM,
                              e2.Seq_Ezor_Ovdim      as Seq_Ezor_Ovdim_MPM
                from temp_porshim_hilan t
                left join v_Bakasha_By_Zheut b
                  on b.gimla_number = nvl(t.mispar_gimla, 0)
                  or b.gimla_number = trunc((nvl(t.mispar_gimla, 0)) / 10)
                left join bney_mishpacha bm
                  on bm.Seq_Porshim = b.porshim_seq
                 and bm.mispar_zehut_ben_mishpacha = t.mispar_zehut
                left join code_ezor_ovdim e
                  on e.code_ezor_ovdim = t.code_ezor_ovdim
                 and e.code_misrad_maskret = t.code_misrad_maskret
                left join code_ezor_ovdim e2
                  on e2.Seq_Ezor_Ovdim = b.seq_ezor_ovdim
               where t.log = 15
                 and nvl(t.Seq_Prisha, 0) = 0
                 and bm.Seq_Bney_Mishpacha is not null
                 and e.Seq_Ezor_Ovdim <> b.seq_ezor_ovdim) loop
    
      update temp_porshim_hilan tp
         set tp.Seq_Prisha          = r.seq_prisha,
             tp.seq_poresh          = r.porshim_seq,
             tp.Seq_Bney_Mishpacha  = r.seq_bney_mishpacha,
             tp.mispar_zehut_poresh = r.mispar_zehut_poresh,
             -- tp.log                 = 5,
             tp.Note = 'SHEER: Added from MERGE_SHEERIM_whith_JobNumber,Record of SHEER: Same values in:mis_gimla / Without the last character and Different seq_ezor_ovdim mpm:' ||
                       r.Seq_Ezor_Ovdim_MPM || ' ' || r.Teur_Ezor_Ovdim_MPM
       where tp.seq = r.seq;
      commit;
    end loop;
  
  end;

  -------------------------------------
  PROCEDURE merge_temp_porshim_hilan is
    bakasha_regila_row err_bakasha_regila%rowtype;
    v_CODE_SEIF_P      number;
    --MERGE לטבלה המקורית מהנתונים החדשים שנטענו מאוחר יותר לטבלת temp_porshim_hilan_2020
  begin
  
    for r in (select distinct tt.taarich_minuy,
                              tt.chelkiyut_misra,
                              tt.taarich_hatchalat_avoda,
                              tt.code_derug,
                              tt.derug_name,
                              tt.code_darga,
                              tt.code_sub_darga,
                              tt.achuz_gimla,
                              tt.code_hahasaka_pensyony,
                              tt.hahasaka_pensyony_name,
                              tt.taarich_matzav,
                              tt.code_matzav,
                              tt.matzav_name,
                              tt.code_seif_prisha,
                              tt.seif_prisha_name,
                              tt.code_mahamad,
                              tt.mahamad_name
                              
                             ,
                              t.Seq as seq_porshim_hilan
                from temp_porshim_hilan t
                left join temp_porshim_hilan_2020 tt
                  on tt.mispar_zehut = t.mispar_zehut
                 and tt.mispar_gimla = t.mispar_gimla
                 and tt.minuy_id_3 = t.minuy_id
               where nvl(tt.seq, 0) > 0) loop
      update temp_porshim_hilan t
         set t.taarich_minuy           = r.Taarich_Minuy,
             t.chelkiyut_misra        =
             (nvl(r.Chelkiyut_Misra, 0)) / 100,
             t.taarich_hatchalat_avoda = to_date(r.taarich_hatchalat_avoda,
                                                 'dd/mm/yyyy'),
             t.code_derug              = nvl(r.Code_Derug, 0),
             t.derug_name              = r.derug_name,
             t.code_darga              = nvl(r.code_darga, 0),
             t.code_sub_darga          = nvl(r.code_sub_darga, 0),
             t.achuz_gimla             = nvl(r.Achuz_Gimla, 0),
             t.code_hahasaka_pensyony  = nvl(r.Code_Hahasaka_Pensyony, 0),
             t.hahasaka_pensyony_name  = r.Hahasaka_Pensyony_Name,
             t.taarich_matzav          = to_date(r.taarich_matzav,
                                                 'dd/mm/yyyy'),
             t.code_matzav             = nvl(r.Code_Matzav, 0),
             t.matzav_name             = r.matzav_name,
             t.code_seif_prisha        = nvl(r.Code_Seif_Prisha, 0),
             t.seif_prisha_name        = r.Seif_Prisha_Name,
             t.code_mahamad            = nvl(r.Code_Mahamad, 0),
             t.mahamad_name            = r.mahamad_name
       where t.Seq = r.Seq_Porshim_Hilan;
      commit;
    
    end loop;
  
  end;

  --------------
  function update_bakasha_regilaFromHilan return boolean is
    bakasha_regila_row err_bakasha_regila%rowtype;
    v_CODE_SEIF_P      number;
  begin
    for r in (select distinct t.mispar_zehut,
                              t.Taarich_Minuy,
                              t.code_seif_prisha
                from temp_porshim_hilan t
              
               where t.Seq = v_seq_TEMP_PORSHIM_HILAN) loop
    
      v_CODE_SEIF_P                     := r.Code_Seif_Prisha;
      bakasha_regila_row.Taarich_Prisha := r.Taarich_Minuy;
      --to_date(r.taarich_hatchalat_avoda,
      --                                            'DD/MM/YYYY');
    
      --bakasha_regila_row.Nechut_Achuz_Nechut_Leprisha := to_number(r.enter_disabilty_percentage);
      bakasha_regila_row.code_seif_prisha := v_CODE_SEIF_P;
      set_CODE_GROUP_PRISHA(bakasha_regila_row.code_seif_prisha);
    
      merge into bakasha_regila
      using dual
      on (bakasha_regila.seq_bakasha = v_seq_bakasha)
      when matched then
        update
           set taarich_prisha   = bakasha_regila_row.taarich_prisha,
