  ----------------------
  function update_bakasha_from_hilan(p_code_sug_bakasha number)
    return boolean is
    bakasha_row   err_bakasha%rowtype;
    v_sug_bakasha number;
  begin
  
    v_sug_bakasha := p_code_sug_bakasha;
    for r in (select distinct t.mispar_zehut, t.Taarich_Minuy
                from temp_porshim_hilan t
              
               where t.Seq = v_seq_TEMP_PORSHIM_HILAN) loop
      --      v_sug_bakasha                := 1;
      bakasha_row.date_bakasha := r.Taarich_Minuy;
      --       to_date(,
      --                                            'dd/mm/yyyy');
      v_date_start_zakahut := r.Taarich_Minuy;
      --      to_date(r.taarich_hatchalat_avoda,
      --                                            'dd/mm/yyyy');
      bakasha_row.code_sug_bakasha := v_sug_bakasha;
      bakasha_row.code_source      := V_code_makor;
      bakasha_row.Seq_Prisha       := v_seq_prisha;
      v_seq_bakasha                := null;
    
      set_seq_bakasha;
    
      merge into bakasha
      using dual
      on (bakasha.seq_bakasha = v_seq_bakasha)
      when matched then
        update
           set code_sug_bakasha = bakasha_row.code_sug_bakasha,
               date_bakasha     = bakasha_row.date_bakasha,
               code_source      = bakasha_row.code_source
        
      
      when not matched then
        insert
          (seq_bakasha,
           seq_prisha,
           code_sug_bakasha,
           
           code_source,
           date_bakasha)
        values
          (v_seq_bakasha,
           v_seq_prisha,
           bakasha_row.code_sug_bakasha,
           
           bakasha_row.code_source,
           bakasha_row.date_bakasha) log errors into err_bakasha
          (v_ora_err_tag$) reject limit unlimited;
    
      if pk_load_mimshak.count_rowes('err_bakasha', v_where) > 0 then
        return false;
      else
        return true;
      end if;
    end loop;
    return false;
  end;
