  -----------------------------
  procedure updateSheerim_bney_mishpaha is
    v_CODE_KIRVA        number;
    v_CODE_relative     number;
    v_seq_ben_mishpacha number;
    v_sug_zihuy_bm      number;
    v_bd                date;
  begin
  
    for r in (select distinct t.First_Name,
                              t.last_name,
                              t.Seq_Bney_Mishpacha,
                              t.mispar_zehut,
                              t.chelkiyut_misra,
                              
                              t.Taarich_Minuy,
                              t.Code_Seif_Prisha
                from temp_porshim_hilan t
              
               where t.Seq = v_seq_TEMP_PORSHIM_HILAN) loop
    
      v_CODE_KIRVA    := (case r.Code_Seif_Prisha
                           when 128 then
                            1
                           else
                            2
                         end);
      v_CODE_relative := (case r.Code_Seif_Prisha
                           when 128 then
                            1
                           else
                            4
                         end);
    
      v_sug_zihuy_bm := 1;
    
      if validate_id(1, v_SHEER_ID) = false then
        v_sug_zihuy_bm := 2;
      end if;
    
      v_seq_ben_mishpacha := r.Seq_Bney_Mishpacha;
      if nvl(v_seq_ben_mishpacha, 0) = 0 then
        v_seq_ben_mishpacha := BNEY_MISHPACHA_SEQ.NEXTVAL;
      end if;
    
      merge into BNEY_MISHPACHA bm
      using dual
      on (bm.seq_porshim = v_porshim_seq and bm.mispar_zehut_ben_mishpacha = v_SHEER_ID)
      when matched then
        update
           set bm.code_kirva    = nvl(bm.code_kirva, v_CODE_KIRVA),
               bm.code_relative = v_CODE_relative,
               bm.achuz_kizba   = v_sum_achuz_gimla,
               --bm.Code_Relative = v_CODE_KIRVA,
               bm.Sug_Zihuy = v_sug_zihuy_bm,
               --הוספתי לעדכון את 2 השדות דלהלן על דעתי
               bm.shem_prati     = r.first_name,
               bm.shem_mishpacha = r.last_name
        
      
      when not matched then
        insert
          (bm.Seq_Bney_Mishpacha,
           bm.Seq_Porshim,
           bm.mispar_zehut_ben_mishpacha,
           bm.shem_prati,
           bm.shem_mishpacha,
           bm.Code_Kirva,
           bm.Code_Relative,
           bm.achuz_kizba,
           -- bm.Taarich_Leda,
           bm.Sug_Zihuy)
        values
          (v_seq_ben_mishpacha,
           v_porshim_seq,
           v_SHEER_ID,
           r.First_Name,
           r.last_name,
           v_CODE_KIRVA,
           v_CODE_relative,
           v_sum_achuz_gimla,
           v_sug_zihuy_bm) log errors into err_BNEY_MISHPACHA
          (v_ora_err_tag$) reject limit unlimited;
    
    --update_ADDRESS_2_Ben_Mishpacha(v_seq_ben_mishpacha);
    -- update_BANK_ACCOUNT_2_BM(v_seq_ben_mishpacha);
    --update_mazav_mishpachti(v_seq_ben_mishpacha);
    -- update_hafsakat_tashlum(TRUE);
    end loop;
  end;
  ----------------
  function ADD_1_MONTH(from_date date) return date is
    v_date      date;
    V_MONTH     NUMERIC;
    V_MONTH_str varchar2(2);
  begin
    dbms_output.enable(999999999999999999999999999999999999999999);
    -- v_date := add_months(from_date, 12 * 67);
    v_date  := from_date;
    V_MONTH := (to_char(v_date, 'MM') + 1);
  
    IF (V_MONTH < 10) THEN
      V_MONTH_str := '0' || V_MONTH;
    ELSE
    
      V_MONTH_str := V_MONTH;
    END IF;
  
    IF (to_char(v_date, 'MM') < 12) THEN
    
      v_date := to_date(
                        
                        '01' || (V_MONTH_str) || (to_char(v_date, 'YYYY')),
                        'ddmmyyyy');
    
    ELSE
      V_MONTH_str := '01';
      v_date      := to_date(
                             
                             '01' || (V_MONTH_str) ||
                             (to_char(v_date, 'YYYY') + 1),
                             'ddmmyyyy');
    
    END IF;
    dbms_output.put_line(from_date || ' ' || v_date || ' ' || V_ID);
    return v_date;
  end;

  -------------------------
  PROCEDURE create_bakashat_sheer_pensyony is
    -- טיפול ברשומות שהגיעו מחילן כרשומות שאר פנסיוני אך אין במערכת בקשת שאר פנסיוני
  begin
    dbms_output.enable(999999999999999999999999999999999999999999);
    for r in (select distinct t.mispar_zehut,
                              t.Seq_Bney_Mishpacha,
                              t.Code_Seif_Prisha,
                              
                              MAX(t.last_name) as last_name,
                              MAX(t.first_name),
                              MAX(t.minuy_id),
                              MAX(t.mispar_gimla) as mispar_gimla,
                              MAX(t.code_misrad_maskret) as code_misrad_maskret,
                              MAX(t.misrad_p_name),
                              MAX(t.code_ezor_ovdim) as code_ezor_ovdim,
                              MAX(t.yechida_name),
                              MAX(t.sug_huclusiya),
                              MAX(t.huclusiya_name),
                              MAX(t.seq) as seq,
                              MAX(t.load_date),
                              MAX(t.seq_prisha) as seq_prisha,
                              MAX(t.seq_poresh) as seq_poresh,
                              --MAX(t.seq_bney_mishpacha) as seq_bney_mishpacha,
                              MAX(t.log),
                              MAX(t.note),
                              MAX(t.mispar_zehut_poresh) as mispar_zehut_poresh,
                              MAX(t.taarich_minuy) as taarich_minuy,
                              MAX(t.chelkiyut_misra) as chelkiyut_misra,
                              MAX(t.taarich_hatchalat_avoda) as taarich_hatchalat_avoda,
                              MAX(t.code_derug),
                              MAX(t.derug_name),
                              MAX(t.code_darga),
                              MAX(t.code_sub_darga),
                              sum(t.achuz_gimla) as achuz_gimla,
                              MAX(t.code_hahasaka_pensyony),
                              MAX(t.hahasaka_pensyony_name),
                              MAX(t.taarich_matzav) as taarich_matzav,
                              MAX(t.code_matzav) as code_matzav,
                              MAX(t.matzav_name),
                              --MAX(t.code_seif_prisha) as code_seif_prisha,
                              MAX(t.seif_prisha_name) as seif_prisha_name,
                              MAX(t.code_mahamad)
              --irst   (t.mahamad_name)
                from Temp_Porshim_Hilan t
              
               where t.mispar_zehut_poresh > 0
                 and t.code_hahasaka_pensyony = 2
                 and t.Code_Seif_Prisha not in (126, 226, 326, 426, 526)
                 and t.Seq_Poresh <> 0
                 and not exists
               (select *
                        from v_bakasha_by_zheut b
                       where b.porshim_seq = t.Seq_Poresh
                         and b."CODE_SUG_BAKASHA" = 13)
               group by t.mispar_zehut,
                        t.Seq_Bney_Mishpacha,
                        t.Code_Seif_Prisha) loop
      ResetFields;
      v_SHEER_ID               := r.mispar_zehut;
      V_ID                     := r.mispar_zehut_poresh;
      v_porshim_seq            := r.seq_poresh;
      v_seq_prisha             := r.Seq_Prisha;
      v_seq_TEMP_PORSHIM_HILAN := r.seq;
      v_sum_achuz_gimla        := r.achuz_gimla;
      set_Taarich_PTIRA_prisha2porsh;
      if (v_date_ptira > v_date_prisha) then
        dbms_output.put_line('ID' || v_ID);
        --טיפול בשאר פנסיוני
        --בדיקה האם מופיע סיום טיפול    
        begin
          v_SEQ_bakashat_syum_tipul := 0;
          select MAX(b.seq_bakasha)
            into v_SEQ_bakashat_syum_tipul
            from v_bakasha_last_status b
           where b.seq_prisha = v_seq_prisha
             and b.code_sug_bakasha = 19;
        exception
          when no_data_found then
            v_SEQ_bakashat_syum_tipul := 0;
        end;
        if nvl(v_SEQ_bakashat_syum_tipul, 0) = 0 then
          --יש לצור הפסקת תשלום
        
          Create_Another_Bakasha(19,
                                 ADD_1_MONTH(v_date_ptira),
                                 42,
                                 FALSE,
                                 6);
        
        end if;
      
        if (update_bakasha_from_hilan(13) = false or
           update_bakasha_regilaFromHilan = false) then
        
          -- V_ERR          := 'Failed to create a Bakashat Sheer Pensyony';
          v_is_do_commit := false;
          --goto endloop1;
        else
          update_netuney_tik_sheer; --V
          --     update_HIVUN;
        
          --   update_DARGA_VEDERUG_TIK; --V  
          --  update_VETEK_DETAIL;
          merge_actions_log;
          update_actions_log;
          updateSheerim_bney_mishpaha;
          --v_id := r3.bm_identity_number;
          add_row_to_mgl_log_hasava(v_id,
                                    17,
                                    v_SHEER_ID || '-' ||
                                    ' .שאר פנסיוני - נוצרה בקשה חדשה מסוג שאר פנסיוני' ||
                                    'create_bakashat_sheer_pensyony');
          COMMIT;
        end if;
      end if;
    end loop;
  end;
  ---------------------------------------
  procedure update_fictivim is
    --עדכון בני משפחה של פורשים פיקטיביים
  begin
    for r in (select distinct t.Seq,
                              bm.Seq_Bney_Mishpacha,
                              B1.seq_porshim,
                              b1.mispar_zehut
                from temp_porshim_hilan t
                left join bney_mishpacha bm
                  on bm.mispar_zehut_ben_mishpacha = t.mispar_zehut
                left join v_bakasha_last_status b1
                  on b1.seq_porshim = bm.seq_porshim
                left join code_ezor_ovdim e
                  on e.Seq_Ezor_Ovdim = b1.seq_ezor_ovdim
               where b1.mispar_zehut >= 500000000
                 and t.Seq_Bney_Mishpacha = 0
                 and t.code_hahasaka_pensyony = 2
                 and t.log = 0) loop
      update temp_porshim_hilan t
         set t.mispar_zehut_poresh = r.mispar_zehut,
             t.seq_poresh          = r.seq_porshim,
             t.log                 = 17,
             t.note                = 'poresh fictivi',
             t.Seq_Bney_Mishpacha  = r.seq_bney_mishpacha
       where t.Seq = r.seq;
    end loop;
  
  end;
  ---------------------------------
  procedure Sheerim_codeEzorOvdim996 is
    --עדכון בני משפחה של פורשים ממשרד פרישה 996 רוא"ה ת"א, הגיעו בטבלה מחילן ללא מס גימלה נכון
  begin
    for r in (select distinct b1.seq_prisha,
                              b1.seq_porshim,
                              bm.Seq_Bney_Mishpacha,
                              t.Seq,
                              t.Code_Ezor_Ovdim,
                              b1.mispar_zehut,
                              b1.gimla_number,
                              t.mispar_gimla,
                              bm.mispar_zehut_ben_mishpacha
                from temp_porshim_hilan t
                left join bney_mishpacha bm
                  on bm.mispar_zehut_ben_mishpacha = t.mispar_zehut
                left join v_bakasha_last_status b1
                  on b1.seq_porshim = bm.seq_porshim
                left join code_ezor_ovdim e
                  on e.Seq_Ezor_Ovdim = b1.seq_ezor_ovdim
               where b1.mispar_zehut > 0
                 and t.code_ezor_ovdim = 996
                 and t.Seq_Bney_Mishpacha = 0
                 and t.code_hahasaka_pensyony = 2
                 and t.log = 0) loop
      update temp_porshim_hilan t
         set t.mispar_zehut_poresh = r.mispar_zehut,
             t.seq_poresh          = r.seq_porshim,
             t.Seq_Prisha          = r.Seq_Prisha,
             t.Seq_Bney_Mishpacha  = r.Seq_Bney_Mishpacha,
             
             t.log  = 18,
             t.note = 'sheer: code ezor ovdim :996 : Seeerim_codeEzorOvdim996'
      
       where t.Seq = r.seq;
    end loop;
  
  end;
  ---------------------------
  procedure Sheerim_same_code_ezor_ovdim is
    --שארים שהגיעו עם אותו קוד אזור עובדים אך מספר גימלה שונה
    --והגיעו רק עם מינוי אחד בטבלת TEMP_PORSHIM_HILAN
  begin
    for r in (select distinct b1.seq_prisha,
                              b1.seq_porshim,
                              bm.Seq_Bney_Mishpacha,
                              b1.mispar_zehut,
                              b1.gimla_number,
                              t.mispar_gimla,
                              bm.mispar_zehut_ben_mishpacha,
                              t.Seq
                from temp_porshim_hilan t
                left join bney_mishpacha bm
                  on bm.mispar_zehut_ben_mishpacha = t.mispar_zehut
                left join v_bakasha_last_status b1
                  on b1.seq_porshim = bm.seq_porshim
                left join code_ezor_ovdim e
                  on e.Seq_Ezor_Ovdim = b1.seq_ezor_ovdim
               where e.Code_Ezor_Ovdim = t.Code_Ezor_Ovdim
                 and t.Seq_Bney_Mishpacha = 0
                 and t.code_hahasaka_pensyony = 2
                 and t.log = 0) loop
      update temp_porshim_hilan t
         set t.mispar_zehut_poresh = r.mispar_zehut,
             t.seq_poresh          = r.seq_porshim,
             t.Seq_Prisha          = r.Seq_Prisha,
             t.Seq_Bney_Mishpacha  = r.Seq_Bney_Mishpacha,
             
             t.log  = 19,
             t.note = 'sheer: same_code_ezor_ovdim ,different gimla number : Sheerim_same_code_ezor_ovdim '
      
       where t.Seq = r.seq;
    end loop;
  
  end;
  ------------------

  procedure set_MIS_GIMLA_from_hilan is
    MIS_GIMLA1 number;
    MIS_GIMLA2 number;
  begin
    begin
      select MIS_GIMLA1
        into MIS_GIMLA1
        from (select ROWNUM as RN, t.mispar_gimla as MIS_GIMLA1
                from temp_porshim_hilan t
               where t.mispar_zehut = v_SHEER_ID
                 and t.log = 0
                 and t.code_hahasaka_pensyony = 2)
       where RN = 1;
    exception
      when no_data_found then
        MIS_GIMLA1 := null;
    end;
  
    begin
      select MIS_GIMLA2
        into MIS_GIMLA2
        from (select ROWNUM as RN, t.mispar_gimla as MIS_GIMLA2
                from temp_porshim_hilan t
               where t.mispar_zehut = v_SHEER_ID
                 and t.log = 0)
       where RN = 2;
    exception
      when no_data_found then
        MIS_GIMLA2 := null;
    end;
    if (nvl(MIS_GIMLA1, 0) <> nvl(MIS_GIMLA2, 0) and nvl(MIS_GIMLA1, 0) > 0 and
       nvl(MIS_GIMLA2, 0) > 0 and
       trunc(MIS_GIMLA1 / 10) = trunc(MIS_GIMLA2 / 10)) then
      v_is_HOZE_BHIRIM := true;
      v_mis_Gimla      := trunc(MIS_GIMLA1 / 10);
    end if;
  
  end;
  -------------------------

  function MERGE_SHEERIM_Unrecognized2 return clob is
    v_report_html          clob;
    v_is_do_commit         boolean;
    v_is_update_Porsh_data boolean;
    V_ERR                  varchar2(100);
    v_fictivi_id_poresh    number;
    v_cs_prisha            number;
  begin
  
    execute immediate 'alter session set nls_language= ''american''';
    execute immediate 'alter session set nls_date_language=''english''';
    execute immediate 'alter session set nls_date_format=''dd-mon-yyyy''';
    v_fictivi_id_poresh := 600002000;
    v_fictivi_id_poresh := 600002115;
    for r in (select distinct /*t.seq           as seq,
                                                                                            t.mispar_zehut,
                                                                                            t.taarich_minuy as taarich_minuy,
                                                                                            t.achuz_gimla   as achuz_gimla,
                                                                                            t.mispar_gimla  as mispar_gimla*/
                              
                              max(t.seq) as seq,
                              t.mispar_zehut,
                              max(t.taarich_minuy) as taarich_minuy,
                              sum(t.achuz_gimla) as achuz_gimla,
                              max(t.mispar_gimla) as mispar_gimla
              
                from temp_porshim_hilan t
                left join bney_mishpacha bm
                  on bm.mispar_zehut_ben_mishpacha = t.mispar_zehut
                left join v_bakasha_last_status b1
                  on b1.seq_porshim = bm.seq_porshim
                left join code_ezor_ovdim e
                  on e.Seq_Ezor_Ovdim = b1.seq_ezor_ovdim
                left join poresh po
                  on po.mispar_zehut = t.mispar_zehut
               where --t.Seq in (6010, 29456, 4422) --101181
              
               bm.seq_bney_mishpacha is null
           and t.Seq_Bney_Mishpacha = 0
           and t.code_hahasaka_pensyony = 2
           and t.log = 0
               group by t.mispar_zehut) loop
      ResetFields;
      V_ERR          := null;
      v_is_do_commit := true;
    
      v_id       := v_fictivi_id_poresh;
      v_SHEER_ID := r.mispar_zehut;
      --insert poresh
      v_porshim_seq     := porshim_seq.nextval;
      v_sum_achuz_gimla := r.achuz_gimla;
      INSERT INTO poresh
        (MISPAR_ZEHUT,
         SHEM_PRATI,
         SHEM_MISHPACHA,
         PORSHIM_SEQ,
         SUG_ZIHUY,
         TAARICH_PTIRA)
      VALUES
        (v_id, 'הסבה', 'הסבה', v_porshim_seq, 2, r.taarich_minuy);
    
      --v_SHEER_ID     := r.bm_identity_number;
      v_ora_err_tag$           := to_char(v_id);
      v_where                  := ' where ora_err_tag$= ''' ||
                                  v_ora_err_tag$ || '''';
      v_seq_TEMP_PORSHIM_HILAN := r.seq;
      -------------**********
      for r2 in (select distinct t.mispar_zehut,
                                 t.Code_Ezor_Ovdim,
                                 t.code_misrad_maskret,
                                 t.code_seif_prisha
                   from TEMP_PORSHIM_HILAN t
                  where t.Seq = v_seq_TEMP_PORSHIM_HILAN) loop
        v_ezor_ovdim := convert_seq_ezor_ovdim(r2.code_misrad_maskret,
                                               r2.Code_Ezor_Ovdim);
        v_seq_prisha := prisha_seq.nextval;
        --טיפול במספר גימלה , במקרה שיש 2 משרה נוספת
        set_MIS_GIMLA_from_hilan;
      
        INSERT INTO prisha
          (SEQ_PRISHA, SEQ_PORESH, SEQ_EZOR_OVDIM, GIMLA_NUMBER)
        VALUES
          (v_seq_prisha,
           v_porshim_seq,
           v_ezor_ovdim,
           nvl(v_mis_Gimla, r.mispar_gimla));
        v_seq_bakasha := bakasha_seq.nextval;
        INSERT INTO bakasha
          (SEQ_BAKASHA, SEQ_PRISHA, CODE_SUG_BAKASHA, DATE_BAKASHA)
        VALUES
          (v_seq_bakasha, v_seq_prisha, 1, to_date('01011990', 'ddmmyyyy'));
        if (r2.code_seif_prisha in (126, 226, 326, 426, 526)) then
          v_cs_prisha := r2.code_seif_prisha;
        else
          v_cs_prisha := 999;
        end if;
        INSERT INTO bakasha_regila
          (SEQ_BAKASHA, Code_Seif_Prisha, TAARICH_PRISHA)
        VALUES
          (v_seq_bakasha, v_cs_prisha, to_date('01011990', 'ddmmyyyy'));
        --סתם תקענו ערך , בכדי שיהיה איזשהו תאריך לסיום טיפול...
        --update_actions_log;
        pk_prm_utils.insert_action_log_row(98,
                                           r.Taarich_Minuy,
                                           1,
                                           null,
                                           null,
                                           null,
                                           null,
                                           null,
                                           v_seq_bakasha,
                                           null);
      
        merge_actions_log;
      
        v_misrad_maskoret := r2.code_misrad_maskret;
        --set_global_fields(1, false);
      
        v_id := v_fictivi_id_poresh;
        if (r2.code_seif_prisha not in (126, 226, 326, 426, 526)) then
          --מדובר בבקשת שאר פנסיוני ולא שאר בשרות
        
          ------------------סוף השתתפות מגוף לשאר פנסיוני-----------
          if (update_bakasha_from_hilan(13) = false or
             update_bakasha_regilaFromHilan = false) then
          
            v_is_do_commit := false;
          
          else
            merge_actions_log;
            update_actions_log;
          end if;
        
        end if;
        set_CODE_GROUP_PRISHA(r2.code_seif_prisha);
        updateSheerim_bney_mishpaha;
        update_netuney_tik_sheer; --V
      
        add_row_to_mgl_log_hasava(v_id,
                                  17,
                                  v_SHEER_ID || '-' ||
                                  ' טעינת שארים לפורשים פיקטיביים מבלת הTEMP של חילן' ||
                                  'MERGE_SHEERIM_Unrecognized2');
      
        for r3 in (select distinct t.Seq
                     from temp_porshim_hilan t
                    where t.mispar_zehut = v_SHEER_ID
                         
                      and t.Seq_Bney_Mishpacha = 0
                      and t.code_hahasaka_pensyony = 2
                      and t.log = 0) loop
          --במקרה שצריך לעדכן כמה רשומות לשאר
          update temp_porshim_hilan t
             set t.log                 = 20,
                 t.note                = 'sheer to poresh fictivi: MERGE_SHEERIM_Unrecognized2',
                 t.mispar_zehut_poresh = v_id,
                 t.seq_prisha          = v_seq_prisha,
                 t.seq_poresh          = v_porshim_seq,
                 t.seq_bney_mishpacha  = v_seq_ben_mishpacha
           where t.seq = r3.Seq;
        end loop;
        COMMIT;
      end loop;
    
      v_fictivi_id_poresh := v_fictivi_id_poresh + 1;
    
      <<endloop1>>
    
      v_report_html := v_report_html ||
                      
                       info_about_errors_and_commit(v_is_do_commit, V_ERR);
    end loop;
  
    commit;
    return v_report_html;
  end;

  procedure update_temp_p_h_tahas is
    --עדכון שארים של תעד אותו קוד אזור עובדים מספר גימלה שונה 
    --מדובר בשארים שהגיעו פעמיים בטבלה מחילן פעם כשארים ופעם כPURAHO
  begin
    for r in (select distinct bm.Seq_Bney_Mishpacha,
                              b1.seq_prisha,
                              b1.seq_porshim,
                              b1.mispar_zehut,
                              t.Seq
                from temp_porshim_hilan t
                left join bney_mishpacha bm
                  on bm.mispar_zehut_ben_mishpacha = t.mispar_zehut
                left join v_bakasha_last_status b1
                  on b1.seq_porshim = bm.seq_porshim
                left join code_ezor_ovdim e
                  on e.Seq_Ezor_Ovdim = b1.seq_ezor_ovdim
               where t.Code_Ezor_Ovdim = 5040
                 and t.Seq_Bney_Mishpacha = 0
                 and t.code_hahasaka_pensyony = 2
                 and t.log = 0
                 and (select count(distinct t2.Code_Hahasaka_Pensyony)
                        from temp_porshim_hilan t2
                       where t2.mispar_zehut = t.mispar_zehut) > 1) LOOP
    
      update temp_porshim_hilan tp
         set tp.Seq_Prisha          = r.seq_prisha,
             tp.seq_poresh          = r.seq_porshim,
             tp.mispar_zehut_poresh = r.mispar_zehut,
             tp.Seq_Bney_Mishpacha  = r.seq_bney_mishpacha,
             tp.log                 = 21,
             tp.Note                = 'SHEER: Same values in:code_ezor_ovdim(תע"ש) & different mispar gimla mpm :update_temp_p_h_tahas '
       where tp.seq = r.seq;
      commit;
    end loop;
  end;
  ----------------
  procedure update_temp_p_h_kabayiim is
    --עדכון שארים של תעד אותו קוד אזור עובדים מספר גימלה שונה    
    --מדובר בשארים שהגיעו פעמיים בטבלה מחילן פעם כשארים ופעם כPURAHO
    --שארים מנציבות כבאות והצלה
  begin
    for r in (select distinct bm.Seq_Bney_Mishpacha,
                              b1.seq_prisha,
                              b1.seq_porshim,
                              b1.mispar_zehut,
                              t.Seq
                from temp_porshim_hilan t
                left join bney_mishpacha bm
                  on bm.mispar_zehut_ben_mishpacha = t.mispar_zehut
                left join v_bakasha_last_status b1
                  on b1.seq_porshim = bm.seq_porshim
                left join code_ezor_ovdim e
                  on e.Seq_Ezor_Ovdim = b1.seq_ezor_ovdim
               where --t.Code_Ezor_Ovdim = 8050
               t.mispar_zehut in (7468143, 1875657)
           and t.Seq_Bney_Mishpacha = 0
           and t.code_hahasaka_pensyony = 2
           and t.log = 0
           and (select count(distinct t2.Code_Hahasaka_Pensyony)
                  from temp_porshim_hilan t2
                 where t2.mispar_zehut = t.mispar_zehut) > 1) LOOP
    
      update temp_porshim_hilan tp
         set tp.Seq_Prisha          = r.seq_prisha,
             tp.seq_poresh          = r.seq_porshim,
             tp.mispar_zehut_poresh = r.mispar_zehut,
             tp.Seq_Bney_Mishpacha  = r.seq_bney_mishpacha,
             tp.log                 = 21,
             tp.Note                = 'SHEER: Same values in:code_ezor_ovdim & different mispar gimla mpm '
      --             :update_temp_p_h_kabayiim '
       where tp.seq = r.seq;
      commit;
    end loop;
  end;

  procedure update_temp_p_h_yadani is
  
  begin
    for r in (select distinct t.Code_Matzav,
                              t.matzav_name,
                              t.Taarich_Minuy,
                              t.Achuz_Gimla,
                              bm.Seq_Bney_Mishpacha,
                              b1.seq_prisha,
                              b1.seq_porshim,
                              b1.mispar_zehut,
                              t.Seq
                from temp_porshim_hilan t
                left join bney_mishpacha bm
                  on bm.mispar_zehut_ben_mishpacha = t.mispar_zehut
                left join v_bakasha_last_status b1
                  on b1.seq_porshim = bm.seq_porshim
                left join code_ezor_ovdim e
                  on e.Seq_Ezor_Ovdim = b1.seq_ezor_ovdim
               where t.mispar_zehut in (195180, 3217056, 7581176, 9464538)
                 and e.code_ezor_ovdim in (2200, 2440, 1670, 4099)
                 and t.Code_Matzav = 0
                 and t.Seq_Bney_Mishpacha = 0
                 and t.code_hahasaka_pensyony = 2
                 and t.log = 0) loop
      update temp_porshim_hilan tp
         set tp.Seq_Prisha          = r.seq_prisha,
             tp.seq_poresh          = r.seq_porshim,
             tp.mispar_zehut_poresh = r.mispar_zehut,
             tp.Seq_Bney_Mishpacha  = r.seq_bney_mishpacha,
             tp.log                 = 21,
             tp.Note                = 'SHEER:  different mispar gimla (נעשה עדכון ידני) :update_temp_p_h_yadani'
      
       where tp.seq = r.seq;
      commit;
    end loop;
  end;
end;
/

