    --         and rownum <= 10
    /*(select h.mispar_zehut
     from mgl_log_hasava h
    where h.code_hasava = 1
      and rownum <= 220
       or h.mispar_zehut = 5920988)*/
    --(5920988)
    --          ) loop
    --and l.mispar_zehut in (11, 670315)) loop
  
    for r2 in (select *
                 from V_BAKASHA_LAST_STATUS bl
                where bl.mispar_zehut in (55978563, 56816051)) loop
    
      v_delete_bakasha := pk_prm_utils.delete_bakasha(r2.seq_bakasha);
