  procedure update_participation_m_guf is
    v_is_transfer_agreement number;
    v_is_heskem_yachid      number;
    v_is_mevutach_beguf     number;
    v_seq_ezor_ovdim        number;
  begin
    for r in (select t.zehut,
                     t.date_start,
                     t.date_end,
                     t.date_heskem,
                     t.kd_guf,
                     t.is_heskem_haavara,
                     t.date_heskem_haavara,
                     t.helkiut_tkufa,
                     t.achuz_hish_m_guf,
                     t.hisht_bfoal_bmaanak,
                     t.misgeret_hisht,
                     t.helkiut_mezaka,
                     t.date_payment,
                     t.is_mevutach_beguf,
                     t.tkufa_mezaka
                from tg_system.tg_p_retzifut_m_guf t
               where t.zehut = v_id
                 and t.nosaf = 0) loop
      v_is_exist_participation_M_guf := true;
      v_is_heskem_yachid             := 0;
      v_is_mevutach_beguf            := convert_0_or_1_number(r.is_mevutach_beguf);
      v_is_transfer_agreement        := convert_0_or_1_number(r.is_heskem_haavara);
      v_seq_ezor_ovdim               := convert_KD_GUF_seq_ezor_ovdim(r.kd_guf);
      insert into participation
        (seq_participation,
         date_start,
         date_end,
         code_participation,
         date_agreement,
         seq_guf,
         is_transfer_agreement,
         date_transfer,
         partial_period,
         percent_participate,
         hisht_bfoal_bmaanak,
         misgeret_hisht,
         helkiut_mezaka,
         date_payment,
         is_mevutach_beguf,
         tkufa_mezaka,
         seq_bakasha,
         is_heskem_yachid)
      values
        (participation_seq.nextval,
         r.date_start,
         r.date_end,
         2,
         r.date_heskem,
         v_seq_ezor_ovdim,
         v_is_transfer_agreement,
         r.date_heskem_haavara,
         r.helkiut_tkufa,
         r.achuz_hish_m_guf,
         r.hisht_bfoal_bmaanak,
         r.misgeret_hisht,
         r.helkiut_mezaka,
         r.date_payment,
         v_is_mevutach_beguf,
         r.tkufa_mezaka,
         v_seq_bakasha,
         v_is_heskem_yachid) log errors into err_participation
        (v_ora_err_tag$) reject limit unlimited;
    
      ------הוספתי
      update Bakasha_Regila br
         set br.date_haskem_rezifut = r.date_heskem
      
       where br.seq_bakasha = v_seq_bakasha;
    
    -----------------------
    end loop;
  
  end;
