  procedure update_bney_mishpaha is
    v_seq_apotropus             number;
    v_is_get_bituach_leumi      number;
    v_is_baal_ishur_tzava       number;
    v_is_baal_tzav_imutz        number;
    v_is_oved                   number;
    v_is_study                  number;
    v_code_min                  number;
    v_code_relative             number;
    v_code_kirva                number;
    v_code_mazav_mishpachti     number;
    v_kd_sug_sheer              number;
    v_month_salary              number;
    v_is_hakira                 number;
    v_is_ishur_eino_oved        number;
    v_is_samuch_al_shulhan_ehad number;
    v_almana_hara               number;
    v_parent_of_common_child    number;
  
  begin
    delete from bney_mishpacha where seq_porshim = v_porshim_seq;
  
    for r in (select re.zehut_rel, --mispar_zehut_ben_mishpacha
                     re.kd_REL,
                     convert_low_hebrew_to_ascii(re.first_name_rel) first_name_rel, --shem_prati
                     convert_low_hebrew_to_ascii(re.surname_rel) surname_rel, --shem_mishpacha
                     re.date_birth_rel, --taarich_leda
                     convert_low_hebrew_to_ascii(re.is_oved) is_oved, --haim_oved
                     convert_low_hebrew_to_ascii(re.mkom_avoda) mkom_avoda,
                     re.kd_min, --code_min
                     re.zehut, --seq_porshim
                     re.index_rel, --seq_bney_mishpacha
                     re.is_get_bituach_leumi, --is_get_social_security
                     re.is_get_salary, --is_get_salary
                     re.kd_maanak_o_kitzba, --code_maanak_kitzba
                     re.kd_sug_sheer, --kd_sug_sheer
                     re.is_tofes_bank_hatum, --is_tofes_bank_hatum
                     re.is_mesharet_btzahal, --is_mesharet_btzahal
                     re.is_baal_ishur_tzava, --is_army_ishur
                     re.is_baal_tzav_imutz, --is_owner_tzav_imutz
                     re.sachar_chodshi, --month_salary
                     convert_low_hebrew_to_ascii(re.adress) adress, --address
                     i.code_ir, --code_city
                     re.mikud, --zone
                     re.kd_min_mazav, --code_mazav_mishpachti
                     re.separat_date, --date_separated
                     re.is_study, --is_learn
                     convert_low_hebrew_to_ascii(re.apotr_name) apotr_name,
                     convert_low_hebrew_to_ascii(re.apotr_adress) apotr_adress,
                     re.kd_kirva_to_dead,
                     re.date_hatimat_tvia,
                     re.almana_hara,
                     re.is_hakira,
                     re.parent_of_common_child,
                     re.is_ishur_eino_oved,
                     re.is_samuch_al_1_table
                from tg_system.tg_p_relatives re
                left join code_ir i
                  on replace(i.teur_ir, ' ') =
                     replace(convert_low_hebrew_to_ascii(trim(re.city)), ' ')
               where re.zehut = v_id
                 and re.nosaf = 0) loop
      v_kd_sug_sheer := to_number(trim(r.kd_sug_sheer));
      if (v_kd_sug_sheer > 0 and v_kd_sug_sheer < 11) then
        v_code_relative := convert_code_RELATIVE(trim(r.kd_sug_sheer));
      
      else
        v_code_relative := null;
      end if;
      v_code_mazav_mishpachti := convert_code_mazav_mishpachti(to_number(trim(r.kd_min_mazav)));
      v_is_study              := convert_0_or_1_number(r.is_study);
      v_code_min              := convert_code_min(trim(r.kd_min));
      v_code_kirva            := convert_code_kirva(trim(r.kd_kirva_to_dead),
                                                    v_code_min);
      -------------------------------
      if v_code_kirva is null or v_code_kirva = 0 then
        v_code_kirva := convert_code_REL_kirva(trim(r.kd_REL));
      end if;
    
      v_is_baal_ishur_tzava       := convert_0_or_1_number(r.is_baal_ishur_tzava);
      v_is_baal_tzav_imutz        := convert_0_or_1_number(r.is_baal_tzav_imutz);
      v_is_get_bituach_leumi      := convert_0_or_1_number(r.is_get_bituach_leumi);
      v_is_oved                   := convert_0_or_1_number(r.is_oved);
      v_is_hakira                 := convert_0_or_1_number(r.is_hakira);
      v_is_ishur_eino_oved        := convert_0_or_1_number(r.is_ishur_eino_oved);
      v_is_samuch_al_shulhan_ehad := convert_0_or_1(r.is_samuch_al_1_table);
      v_almana_hara               := convert_0_or_1_number(r.almana_hara);
      v_parent_of_common_child    := convert_0_or_1_number(r.parent_of_common_child);
      if (r.sachar_chodshi > 999999.99) then
        v_month_salary := null;
      else
        v_month_salary := trunc(r.sachar_chodshi, 2);
      end if;
      v_seq_apotropus := get_create_apotropus(trim(r.apotr_name),
                                              trim(r.apotr_adress),
                                              null,
                                              null);
      insert into bney_mishpacha
        (seq_porshim,
         seq_bney_mishpacha,
         mispar_zehut_ben_mishpacha,
         shem_prati,
         shem_mishpacha,
         taarich_leda,
         haim_oved,
         makom_avoda,
         code_kirva,
         code_min,
         is_get_social_security,
         code_maanak_kitzba,
         code_relative,
         date_sign_tvia_form,
         is_army_ishur,
         is_owner_tzav_imutz,
         month_salary,
         address,
         code_city,
         zone,
         code_mazav_mishpachti,
         is_learn,
         almana_hara,
         is_hakira,
         parent_of_common_child,
         is_ishur_eino_oved,
         is_samuch_al_shulhan_ehad,
         seq_apotropus,
         date_separated)
      values
        (v_porshim_seq,
         bney_mishpacha_seq.nextval,
         r.zehut_rel,
         r.first_name_rel,
         r.surname_rel,
         r.date_birth_rel,
         v_is_oved,
         r.mkom_avoda,
         v_code_kirva,
         v_code_min,
         v_is_get_bituach_leumi,
         to_number(trim(r.kd_maanak_o_kitzba)),
         --to_number(trim(r.kd_sug_sheer)),
         v_code_relative,
         r.date_hatimat_tvia,
         v_is_baal_ishur_tzava,
         v_is_baal_tzav_imutz,
         v_month_salary,
         r.adress,
         r.code_ir,
         to_char(r.mikud),
         v_code_mazav_mishpachti,
         v_is_study,
         v_almana_hara,
         v_is_hakira,
         v_parent_of_common_child,
         v_is_ishur_eino_oved,
         v_is_samuch_al_shulhan_ehad,
         v_seq_apotropus,
         --הוספתי
         r.separat_date) log errors into err_bney_mishpacha
        (v_ora_err_tag$) reject limit unlimited;
    
    -- dbms_output.put_line('update_bney_mishpaha -ID: ' || v_id ||
    --                    'from date ' || to_char(sysdate, 'dd/mm/yyyy'));
    end loop;
  end;
  ---------------------------------------------------------
  procedure update_tkufot_sikum is
  begin
  
    delete from tkufot_sikum t where t.seq_bakasha = v_seq_bakasha;
  
    for r in (select trim(th.kd_sug_sikum) kd_sug_sikum,
                     th.years,
                     th.months,
                     th.days,
                     th.sach_months_mezakim
                from tg_system.tg_p_tkufat_hasherut th
               where th.zehut = v_id
                 and th.nosaf = 0
                 and (nvl(th.years, 0) <> 0 or nvl(th.months, 0) <> 0 or
                     nvl(th.days, 0) <> 0)) loop
      insert into tkufot_sikum
        (code_sug_sikum,
         years,
         months,
         days,
         sach_months_mezakim,
         seq_bakasha,
         seq_tkufot_sikum)
      values
        (r.kd_sug_sikum,
         r.years,
         r.months,
         r.days,
         r.sach_months_mezakim,
         v_seq_bakasha,
         tkufot_sikum_seq.nextval) log errors into err_tkufot_sikum
        (v_ora_err_tag$) reject limit unlimited;
    end loop;
  end;
  -----------------------------------------------------------
  procedure update_hagdala_nimuk is
    v_code_nimuk     number;
    v_achuz_meushar  number;
    v_meushar_natsiv number;
  begin
  
    delete from hagdala_nimuk t where t.seq_bakasha = v_seq_bakasha;
  
    for r in (select t.kd_hagdala,
                     t.achuz_hagdala,
                     t.date_hagdala,
                     t.is_ishur_hagdala,
                     t.months_hagdala,
                     t.years_hagdala
                from tg_system.tg_p_hagdalot t
               where t.zehut = v_id
                 and t.nosaf = 0) loop
      if (r.achuz_hagdala > 999.99)
      
       then
        v_achuz_meushar := null;
      else
        v_achuz_meushar := trunc(r.achuz_hagdala, 2);
      end if;
      v_code_nimuk     := convert_code_nimuk(trim(r.kd_hagdala));
      v_meushar_natsiv := convert_0_or_1_number(r.is_ishur_hagdala);
      insert into hagdala_nimuk
        (seq_bakasha,
         seq_hagdala_nimuk,
         code_nimuk,
         achuz_meushar,
         me_taarich,
         meushar_natsiv,
         months_hagdala,
         years_hagdala,
         code_hagdala_status_nimuk)
      values
        (v_seq_bakasha,
         hagdala_nimuk_seq.nextval,
         v_code_nimuk,
         r.achuz_hagdala,
         r.date_hagdala,
         v_meushar_natsiv,
         r.months_hagdala,
         r.years_hagdala,
         case v_meushar_natsiv when 1 then 3 else 1 end) log errors into err_hagdala_nimuk
        (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  end;
  -----------------------------------------------------------
  function update_bakasha(p_code_sug_bakasha number) return boolean is
    bakasha_row err_bakasha%rowtype;
  begin
    for r in (select p.date_gzira, p.time_gzira, p.kd_makor, p.kd_misrad
                from tg_system.tg_poresh p
               where p.zehut = v_id
                 and p.nosaf = 0) loop
      begin
        bakasha_row.date_bakasha := to_date(to_char(r.date_gzira,
                                                    'dd/mm/yyyy') ||
                                            to_char(r.time_gzira,
                                                    '00g00g00',
                                                    'nls_numeric_characters=.:'),
                                            'dd/mm/yyyy  hh24:mi:ss');
      exception
        when others then
          bakasha_row.date_bakasha := r.date_gzira;
      end;
    
      bakasha_row.code_source      := get_mpm_code_source(r.kd_misrad,
                                                          r.kd_makor);
      bakasha_row.code_sug_bakasha := p_code_sug_bakasha;
    
      set_seq_bakasha(p_code_sug_bakasha);
    
      merge into bakasha
      using dual
      on (bakasha.seq_bakasha = v_seq_bakasha)
      when matched then
        update
           set code_sug_bakasha = bakasha_row.code_sug_bakasha,
               date_bakasha     = bakasha_row.date_bakasha,
               code_source      = bakasha_row.code_source
      when not matched then
        insert
          (seq_bakasha,
           seq_prisha,
           code_sug_bakasha,
           date_bakasha,
           code_source)
        values
          (v_seq_bakasha,
           v_seq_prisha,
           bakasha_row.code_sug_bakasha,
           bakasha_row.date_bakasha,
           bakasha_row.code_source) log errors into err_bakasha
          (v_ora_err_tag$) reject limit unlimited;
    end loop;
    if pk_load_mimshak.count_rowes('err_bakasha', v_where) > 0 then
      return false;
    else
      return true;
    end if;
  end;
  --------------------------------------------------------------------------------------------------------
  function update_prisha return boolean is
    prisha_row err_prisha%rowtype;
  begin
    for r in (select t.zehut, t.kd_misrad, t.mis_gimla --, t.kd_yehida
                from tg_system.tg_poresh t
               where t.zehut = v_id
                 and t.nosaf = 0) loop
      if pk_load_mimshak.is_exist_prisha(v_porshim_seq,
                                         v_ezor_ovdim,
                                         v_seq_prisha) = false then
        v_seq_prisha := prisha_seq.nextval;
      end if;
      prisha_row.seq_poresh     := v_porshim_seq;
      prisha_row.seq_ezor_ovdim := v_ezor_ovdim;
      prisha_row.gimla_number   := trim(r.mis_gimla);
      -- prisha_row.code_unit      := trim(r.kd_yehida);
    
      merge into prisha
      using dual
      on (prisha.seq_prisha = v_seq_prisha)
      when matched then
        update
           set gimla_number = prisha_row.gimla_number /*,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                        
                                                                                                                        
                                                                                                                                
                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   seq_code_unit = prisha_row.code_unit*/
        
      
      when not matched then
        insert
          (seq_prisha,
           seq_poresh,
           seq_ezor_ovdim,
           gimla_number /*,     seq_code_unit*/)
        values
          (v_seq_prisha,
           v_porshim_seq,
           v_ezor_ovdim,
           trim(r.mis_gimla) /*,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                               
                                                                                                                                                                     
                                                                                                                                                                                
                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                