  -------------------------------------------------------------
  procedure update_actions_log(date_haavara_hash  date,
                               is_histatfoot_lguf boolean) is
    date_haavara_or_letter date;
  begin
  
    if (date_haavara_hash is null) then
      v_isWithoutDateHahavaraHash := true;
      set_date_letter();
      date_haavara_or_letter := v_dateLetter;
    else
      v_isWithoutDateHahavaraHash := false;
      date_haavara_or_letter      := date_haavara_hash;
    end if;
  
    --add action log row: conversion ('hasava').
    pk_prm_utils.insert_action_log_row(99,
                                       sysdate,
                                       null,
                                       null,
                                       null,
                                       null,
                                       null,
                                       null,
                                       v_seq_bakasha,
                                       null);
    --add action log row: transfer to malam ('avar le malam').
    pk_prm_utils.insert_action_log_row(22,
                                       date_haavara_or_letter,
                                       null,
                                       null,
                                       null,
                                       null,
                                       null,
                                       null,
                                       v_seq_bakasha,
                                       null);
  
    if (is_histatfoot_lguf) then
      pk_prm_utils.insert_action_log_row(36,
                                         date_haavara_or_letter,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha,
                                         null);
    else
    
      pk_prm_utils.insert_action_log_row(103,
                                         date_haavara_or_letter,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha,
                                         null);
    
    end if;
    --סיום טיפול
    pk_prm_utils.insert_action_log_row(98,
                                       date_haavara_or_letter,
                                       null,
                                       null,
                                       null,
                                       null,
                                       null,
                                       null,
                                       v_seq_bakasha,
                                       null);
    if (v_CODE_SEIF_PRISHA in (171, 117, 317, 92) and
       v_date_start_zakahut > sysdate) then
      --ממתין לגיל פרישה תקנוני
      pk_prm_utils.insert_action_log_row(132,
                                         date_haavara_or_letter,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha,
                                         null);
    end if;
  
  end;
  ----------------------------------------------------------
  function get_erorr_from_table(p_table varchar2) return clob is
    v_report clob := null;
  begin
    if pk_load_mimshak.count_rowes(p_table, v_where) > 0 then
      v_report := '<h4>' || p_table || ' count ' ||
                  pk_load_mimshak.count_rowes(p_table, v_where) || '.' ||
                  '<h4/>' || chr(10);
      v_report := v_report ||
                  pk_load_mimshak.create_sql_clob_format_html(p_table,
                                                              v_where);
    end if;
    return v_report;
  end;
  ----------------------------------------------------------
  function info_about_errors_and_commit(v_do_commit boolean,
                                        P_ErrrMesg  varchar2) return clob is
    v_report       clob := null;
    v_is_do_commit number;
  begin
    --add to the report info about the error tables.
    v_report := get_erorr_from_table('err_porshim');
    v_report := v_report || get_erorr_from_table('err_prisha');
    v_report := v_report || get_erorr_from_table('err_bakasha');
    v_report := v_report || get_erorr_from_table('err_bakasha_regila');
    v_report := v_report ||
                get_erorr_from_table('err_tkufot_avoda_mechushv');
    v_report := v_report || get_erorr_from_table('err_medical_vaada');
    v_report := v_report || get_erorr_from_table('err_apotropus');
    v_report := v_report || get_erorr_from_table('err_bney_mishpacha');
    v_report := v_report || get_erorr_from_table('err_decisions');
    v_report := v_report || get_erorr_from_table('err_participation');
    v_report := v_report ||
                get_erorr_from_table('err_netuney_tik_mechushavim');
    v_report := v_report || get_erorr_from_table('err_hagdala_nimuk');
    v_report := v_report || get_erorr_from_table('err_action_log');
  
    if v_do_commit = false then
      rollback;
      --   --------not (v_is_exist_tkufot_avoda)
      if (v_is_NOT_VALID_ID) then
        v_report := '<h2>' || '********** zeut: ' || v_id || ' **********' ||
                    '<h2/>' || '<h3>' ||
                    'Was not converted .Not Valid id  ' || '<h3/>' ||
                    chr(13) || chr(10) || v_report;
      
        add_row_to_mgl_log_hasava(v_id, 2, 'Not Valid id');
      else
        v_report := '<h2>' || '********** zeut: ' || v_id || ' **********' ||
                    '<h2/>' || '<h3>' || 'Was not converted. ' || '<h3/>' ||
                    chr(13) || chr(10) || v_report;
        add_row_to_mgl_log_hasava(v_id, 4, P_ErrrMesg);
      
      end if;
      commit;
      --   ----------
    elsif v_do_commit = true then
      commit;
      v_report := '<h2>' || '********** zeut: ' || v_id || ' **********' ||
                  '<h2/>' || '<h3>' || 'Converted. ' || '<h3/>' || chr(13) ||
                  chr(10) || v_report;
    end if;
  
    v_is_do_commit := case v_do_commit
                        when true then
                         1
                        else
                         0
                      end;
  
    insert into temp_convert_2_mpm
      (id, is_do_commit)
    values
      (v_id, v_is_do_commit);
  
    return v_report;
  
  end;
  --------------------------------------------------

  function validate_id(sug_zihuy number, v_id number) return boolean is
    type num_arr_type is table of number;
    mask_arr num_arr_type := num_arr_type(1, 2, 1, 2, 1, 2, 1, 2, 1);
    j        number;
    k        number := 0;
  begin
    if sug_zihuy = 2 -- darkon
     then
      return False;
    elsif sug_zihuy = 1 -- mispar zeut
     then
      for i in 1 .. 8 loop
        j := mask_arr(i) *
             to_number(substr(lpad(to_char(v_id), 9, '0'), i, 1));
        k := k + case length(to_char(j))
               when 1 then
                j
               else
                to_number(substr(to_char(j), 1, 1)) +
                to_number(substr(to_char(j), 2, 1))
             end;
      end loop;
      k                 := case mod(k, 10)
                             when 0 then
                              0
                             else
                              10 - mod(k, 10)
                           end;
      v_is_NOT_VALID_ID := False;
      if k <> to_number(substr(lpad(to_char(v_id), 9, '0'), 9, 1)) then
        -- not valid id 
        v_is_NOT_VALID_ID := true;
        /*add_row_to_err_porshim(v_id || '-' || 'not valid id',
        20000,
        'mispar_zehut');*/
        -- add_row_to_mgl_log_hasava(v_id, 2);
        -- dbms_output.put_line('NOT_VALID_ID' || v_id);
        -- raise_application_error(-20000, 'not valid id');
        return False;
      end if;
    end if;
    return true;
  end;
  --------------------------------------------------
  procedure update_HEAROT_TO_ACTION_LOG is
  
    v_code_user number;
  begin
    for rr in (select *
                 from (select
                       -- v.SEQ_BAKASHA,
                        t.index_heara,
                        t.date_heara,
                        t.teur_heara,
                        t.User_Last_Idkun
                         from tg_system.tg_P_HEAROT t
                       --left join v_bakasha v
                       --  on t.zehut = v.MISPAR_ZEHUT
                        where t.zehut = v_id
                          and t.nosaf = 0
                        order by nvl(t.date_heara,
                                     to_date('01010001', 'ddmmyyyy')),
                                 t.index_heara asc)
               --where rownum = 1
               ) loop
      v_code_user := convert_code_USER(convert_low_hebrew_to_ascii(rr.user_last_idkun));
      pk_prm_utils.insert_action_log_row(31,
                                         rr.date_heara,
                                         v_code_user,
                                         null,
                                         convert_low_hebrew_to_ascii(rr.teur_heara),
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha,
                                         null);
    
    /* update bakasha_regila b
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       set b.nechut_taarich_hamigbala = rr.date_start_nechut,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           b.nechut_achuz             = rr.dargat_nechut
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- b.date_vaada_refuit            = rr.date_decision,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    -- b.nechut_achuz_nechut_leprisha = rr.dargat_nechut_l_chishuv,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     where b.seq_bakasha = rr.seq_bakasha;*/
    end loop;
  end;

  --------------------------------------------------
  function main return clob is
    v_report_html    clob;
    v_is_do_commit   boolean;
    v_delete_bakasha varchar2(1000);
    v_is_tam         boolean;
  
  begin
  
    /*     for r in (select * from bakasha b where b.seq_prisha ) loop
      v_delete_bakasha := pk_prm_utils.delete_bakasha(r.seq_bakasha);
    end loop;*/
  
    execute immediate 'alter session set nls_language= ''american''';
    execute immediate 'alter session set nls_date_language=''english''';
    execute immediate 'alter session set nls_date_format=''dd-mon-yyyy''';
    -- execute immediate 'update netuney_tik_mechushavim a set a.code_department = 1 where a.code_department is null';
    -- execute immediate 'delete from netuney_tik_mechushavim a where a.code_department = 2';
  
    --truncate 'err' tables
    /* execute immediate 'truncate table err_medical_vaada';
    execute immediate 'truncate table err_apotropus';
    execute immediate 'truncate table err_bney_mishpacha';
    execute immediate 'truncate table err_decisions';
    execute immediate 'truncate table err_participation';
    execute immediate 'truncate table err_netuney_tik_mechushavim';
    execute immediate 'truncate table err_tkufot_avoda_mechushv';
    execute immediate 'truncate table err_bakasha_regila';
    execute immediate 'truncate table err_hagdala_nimuk';
    execute immediate 'truncate table err_bakasha';
    execute immediate 'truncate table err_prisha';
    execute immediate 'truncate table err_porshim';
    execute immediate 'truncate table err_action_log';
    execute immediate 'truncate table err_tkufot_sikum';
    -- execute immediate 'truncate table mgl_log_hasava';*/
  
    --regular bakashot
    /**/
    for r in (select p.zehut,
                     p.date_gzira,
                     p.date_haavara_hash,
                     p.kd_misrad,
                     p.kd_yehida
                from tg_system.tg_poresh p
              --left join tg_SYSTEM.Tg_p_Retzifut_l_Guf rl
              --   on rl.zehut = p.zehut
               where
              --  and rl.zehut is not null
               p.zehut in (55978563, 56816051)
              --and
              -- and p.date_haavara_hash >= to_date('01010010', 'ddmmyyyy')
              
              /*and p.zehut in (select h.mispar_zehut
               from mgl_log_hasava h
              where h.code_hasava = 1
                and rownum <= 220
                 or h.mispar_zehut = 5920988)*/
              --(5920988)
           and p.nosaf = 0
              --and p.zehut not in
              --  (select ml.mispar_zehut from mgl_log_hasava ml)
              /*  and (p.date_haavara_hash is not null or
              (p.date_haavara_hash is null and p.date_ptira is null and
              exists (select *
                         from tg_system.tg_p_letter ll
                        where ll.zehut = p.zehut
                          and ll.file_path is not null)
              
              ))*/
              --and rownum < 1000
           and p.zehut not in (select po.mispar_zehut from poresh po)
               order by p.zehut) loop
      begin
        --------------
      
        v_is_do_commit := true;
        v_date_gzira   := r.date_gzira;
        v_id           := r.zehut;
        v_ezor_ovdim   := convert_seq_ezor_ovdim(r.kd_misrad,
                                                 TRIM(r.kd_yehida));
        v_ora_err_tag$ := to_char(v_id) || ' - ' ||
                          to_char(v_date_gzira, 'dd/mm/yyyy');
        v_where        := ' where ora_err_tag$= ''' || v_ora_err_tag$ || '''';
      
        --delete table 'bakasha'
        /* for r2 in (select *
                     from V_BAKASHA_LAST_STATUS bl
                    where bl.mispar_zehut = r.zehut) loop
          --22624 
          v_delete_bakasha := pk_prm_utils.delete_bakasha(r2.seq_bakasha);
        end loop;*/
        v_is_exist_tkufot_avoda := false;
        if validate_id(1, r.zehut) = false or
          --must tables
           update_poresh = false or update_prisha = false or
           update_bakasha(1) = false or update_bakasha_regila = false
        /*or(update_tkufot_avoda_mehushv = false or
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_is_exist_tkufot_avoda = false) */
         then
          v_is_do_commit := false;
          -- add_row_to_mgl_log_hasava(v_id, 3);
          goto endloop;
        end if;
      
        --add row log succses
        if (v_isWithoutDateHahavaraHash) then
          add_row_to_mgl_log_hasava(v_id, 9, '');
        else
          add_row_to_mgl_log_hasava(v_id, 1, '');
        end if;
      
        dbms_output.enable(999999999);
      
        --not must tables
      
        update_bney_mishpaha;
        V_CHELKIYUT_MESHUKLELET := null;
        update_netuney_tik_mechushavim;
      
        update_decisions;
        update_relative_decisions;
      
        update_hagdala_nimuk;
      
        update_vaada_ref;
      
        update_HEAROT_TO_ACTION_LOG;
      
        v_is_tam := update_tkufot_avoda_mehushv;
      
        --? pk_zakaut.main(v_seq_bakasha);
      
        --null;
        --הוספתי-------
      
        update_participation_l_guf;
        --העברתי לפה
        update_actions_log(r.date_haavara_hash,
                           v_is_exist_participation_2_guf);
        v_is_exist_participation_m_guf := false;
      
        update_participation_m_guf;
        update_DERUG;
        if (v_is_exist_participation_m_guf) then
          if (update_bakasha(7) and update_bakasha_regila) then
          
            update_netuney_tik_mechushavim;
            update_decisions;
            update_relative_decisions;
            update_hagdala_nimuk;
            update_vaada_ref;
            update_actions_log(r.date_haavara_hash, true);
            -- v_is_exist_participation_2_guf);
            update_HEAROT_TO_ACTION_LOG;
            v_is_tam := update_tkufot_avoda_mehushv;
            update_participation_l_guf;
            update_participation_m_guf;
            v_is_exist_participation_m_guf := false;
            update_DERUG;
          end if;
        end if;
        <<endloop>>
        v_report_html := v_report_html ||
                        
                         info_about_errors_and_commit(v_is_do_commit, '');
      
      exception
        when others then
          dbms_output.put_line('ERR' || v_id || sqlerrm);
          v_is_do_commit := false;
          v_report_html  := v_report_html ||
                           
                            info_about_errors_and_commit(v_is_do_commit,
                                                         sqlerrm);
        
      end;
    
    --commit;
    end loop;
    /**/
    --    DELETE_CONVERTED_DATA;
    commit;
    return v_report_html;
  
  end;

----------------------------------------------------------
end;
/

