  -------------------------------------

  procedure set_new_min_seq_bakasha(v_min_seq_bakasha number) is
    v_new_seq_bakasha number;
  begin
    v_new_seq_bakasha := null;
    begin
      /* for i in reverse 1 .. v_min_seq_bakasha - 1 loop
      begin
        select i
          into v_new_seq_bakasha
          from dual
         where i not in
               (select b.seq_bakasha from V_BAKASHA_LAST_STATUS b);*/
    
      select max(round((l + seq_bakasha) / 2)) as v_new_seq_bakasha
        into v_new_seq_bakasha
        from (select seq_bakasha,
                     lead(seq_bakasha) over(order by seq_bakasha asc) as l
                from V_BAKASHA_LAST_STATUS t
               order by seq_bakasha asc) t
       where 1 = 1
            --and rownum = 1
         and l - seq_bakasha > 1
         and l <= v_min_seq_bakasha;
    
    exception
      when no_data_found then
        v_new_seq_bakasha := null;
    end;
  
    --  EXIT WHEN v_new_seq_bakasha is not null;
    --end loop;
  
    if (v_new_seq_bakasha is not null) then
      v_seq_bakasha := v_new_seq_bakasha;
    end if;
  
    -- end;
  end;
  --------------------------------------------------
  --לא נבדק ...........כי אין צורך לשימוש בינתיים
  procedure set_new_seq_bakasha_between(v_min_seq_bakasha number,
                                        v_max_seq_bakasha number) is
    v_new_seq_bakasha number;
  begin
    v_new_seq_bakasha := null;
    begin
    
      select max(round((l + seq_bakasha) / 2)) as v_new_seq_bakasha
        into v_new_seq_bakasha
        from (select seq_bakasha,
                     lead(seq_bakasha) over(order by seq_bakasha asc) as l
                from V_BAKASHA_LAST_STATUS t
               order by seq_bakasha asc) t
       where 1 = 1
         and l - seq_bakasha > 1
         and l >= v_min_seq_bakasha
         and l <= v_max_seq_bakasha
      
      ;
    
    exception
      when no_data_found then
        v_new_seq_bakasha := null;
    end;
  
    if (v_new_seq_bakasha is not null) then
      v_seq_bakasha := v_new_seq_bakasha;
    end if;
  end;

  --------------------------------------------------
  procedure set_seq_bakasha(v_code_sug_bakasha number) is
  
  begin
    begin
    
      if (v_code_sug_bakasha = 1 and is_exist_bakasha_regila is null) then
        if (is_exist_bakasha_mukdemet is not null) then
          --אם קיימ בקשה מוקדמת לפרישה 
          v_seq_bakasha := bakasha_seq.nextval;
        else
          --צריך למצוא את הקטן מ הנמוך ביותר
          set_new_min_seq_bakasha(v_seq_MinBakasha);
        end if;
      else
        if (v_seq_bakashaMaxDate is not null) then
          v_seq_bakasha := v_seq_bakashaMaxDate;
        else
          v_seq_bakasha := bakasha_seq.nextval;
        end if;
      end if;
    end;
  end;
  ---------------------------------------

  procedure CREATE_NEW_DATA_BAKASHA(p_date_haavara_hash date) is
    v_is_tam boolean;
  begin
  
    /*  if (v_CODE_GROUP_PRISHA = 4) then
      update_bney_mishpaha;
    
    end if;*/
    V_CHELKIYUT_MESHUKLELET := null;
    update_netuney_tik_mechushavim;
    update_decisions;
    update_relative_decisions;
    update_hagdala_nimuk;
    update_vaada_ref;
  
    update_HEAROT_TO_ACTION_LOG;
    v_is_tam := update_tkufot_avoda_mehushv;
    update_participation_l_guf;
    update_actions_log(p_date_haavara_hash, v_is_exist_participation_2_guf);
    v_is_exist_participation_m_guf := false;
    update_participation_m_guf;
    update_DERUG;
  end;
  --------------------------------------------------
  procedure set_CODE_GROUP_PRISHA(v_code_seif number) is
  begin
    begin
      select t.code_group_prisha
        into v_CODE_GROUP_PRISHA
        from code_seif_prisha t
       where t.code_seif_prisha = v_code_seif
         and ROWNUM = 1;
    exception
      when no_data_found then
        v_CODE_GROUP_PRISHA := null;
    end;
  end;
  -------------------------------------------------

