  function is_exist_bakasha_regila return number is
    seq_bakasha_regila number;
  begin
    seq_bakasha_regila := null;
    begin
      select b.seq_bakasha
        into seq_bakasha_regila
        from V_BAKASHA_LAST_STATUS b
       where b.code_sug_bakasha = 1
         and b.seq_ezor_ovdim = v_ezor_ovdim
         and b.mispar_zehut = v_id
         and rownum = 1;
    
    exception
      when no_data_found then
        seq_bakasha_regila := null;
    end;
    return seq_bakasha_regila;
  end;

