  procedure SetMaxdateDecision is
  begin
  
    v_Max_Date_Decision := null;
    begin
      select max(d.date_decision)
        into v_Max_Date_Decision
        from tg_system.tg_p_decision d
       where d.nosaf = d.nosaf
         and d.zehut = v_id;
    exception
      when no_data_found then
        v_Max_Date_Decision := to_date('01010001', 'ddmmyyyy');
    end;
    if (v_Max_Date_Decision is null) then
      v_Max_Date_Decision := to_date('01010001', 'ddmmyyyy');
    end if;
  
  end;

  procedure SET_Ezor_Ovdim(p_kd_misrad varchar, p_kd_yechida varchar) is
    countMisPrisha number;
  begin
    begin
      select count(p.seq_prisha)
        into countMisPrisha
        from PORESH po
        left join prisha p
          on p.seq_poresh = po.Porshim_Seq
       where po.mispar_zehut = v_id;
    exception
      when no_data_found then
        countMisPrisha := 0;
    end;
    if (countMisPrisha > 1) then
      v_ezor_ovdim := convert_seq_ezor_ovdim(p_kd_misrad, p_kd_yechida);
    else
      if (countMisPrisha = 1) then
        begin
          select p.seq_ezor_ovdim
            into v_ezor_ovdim
            from PORESH po
            left join prisha p
              on p.seq_poresh = po.Porshim_Seq
           where po.mispar_zehut = v_id;
        exception
          when no_data_found then
            v_ezor_ovdim := 204;
        end;
      
      end if;
    end if;
  
  end;
  ----------------
  function UpdateMonths(p_taarich_me date, p_taarich_ad date) return number is
  begin
    begin
      select months_between(p_taarich_ad + 1, p_taarich_me)
        into v_sach_chodashim
        from dual t;
    
    exception
      when OTHERS then
        v_sach_chodashim := null;
    end;
    return trunc(v_sach_chodashim, 2);
  
  end;

