  procedure SETMaxDateActionLogForAction(p_code_action number) is
  
    IsEXISTSsugBakashaRegila number;
    sugeyBakasha             num_nt;
  
  begin
  
    if (v_sug_bakasha = 1) then
      sugeyBakasha := num_nt(1, 3, 5);
    else
      sugeyBakasha := num_nt(v_sug_bakasha);
    end if;
    begin
      v_max_date_action := null;
      select max(a.date_action)
        into v_max_date_action
        from action_log a
        left join V_BAKASHA_LAST_STATUS b
          on b.seq_bakasha = a.Seq_Bakasha
       where b.code_sug_bakasha in (SELECT * FROM TABLE(sugeyBakasha))
            --(sugeyBakasha)
            
         and b.seq_ezor_ovdim = v_ezor_ovdim
         and b.mispar_zehut = v_id
         and a.code_action = p_code_action;
    exception
      when no_data_found then
        v_max_date_action := null;
    end;
  
    v_seq_MinBakasha := null;
    begin
      select min(b.seq_bakasha)
        into v_seq_MinBakasha
        from V_BAKASHA_LAST_STATUS b
       where b.seq_ezor_ovdim = v_ezor_ovdim
         and b.mispar_zehut = v_id;
    exception
      when no_data_found then
        v_seq_MinBakasha := null;
    end;
  
    v_seq_bakashaMaxDate := null;
    begin
      v_date_bakasha := null;
      select max(b.seq_bakasha)
        into v_seq_bakashaMaxDate
        from V_BAKASHA_LAST_STATUS b
       where b.code_sug_bakasha in (SELECT * FROM TABLE(sugeyBakasha))
         and b.seq_ezor_ovdim = v_ezor_ovdim
         and b.mispar_zehut = v_id
      /* and not exists (select a.seq_bakasha
        from action_log a
      --התנאי מכפיל את זמן הביצוע בפי3 מהזמן
       where a.seq_bakasha = b.seq_bakasha
         and a.code_action = 17)*/
      ;
    exception
      when no_data_found then
        v_seq_bakashaMaxDate := null;
    end;
  
    ------נתוני הבקשה האחרונה
    if (v_seq_bakashaMaxDate is not null) then
      begin
        select b.date_bakasha, b.code_sug_bakasha, b.seq_prisha
          into v_date_bakasha, v_sug_bakasha, v_seq_prisha
          from V_BAKASHA_LAST_STATUS b
         where b.seq_bakasha = v_seq_bakashaMaxDate;
      
      exception
        when no_data_found then
          v_seq_bakashaMaxDate := null;
          v_date_bakasha       := null;
          v_sug_bakasha        := v_sug_bakasha; --???
      end;
      --else
      --בקשה לאותו משרד ולאותו סוג בקשה\
      --לבקשת דבורה : אם אין  תאריך אישור יש לפתוח בקשת פרישה רגילה או שינויים
      /* BEGIN
        select b.seq_bakasha, b.date_bakasha
          into v_seq_bakashaMaxDate, v_date_bakasha
          from V_BAKASHA_LAST_STATUS b
         where b.code_sug_bakasha  in ||sugeyBakasha
           and b.seq_ezor_ovdim = v_ezor_ovdim
           and b.mispar_zehut = v_id
           and ROWNUM = 1;
      exception
        when no_data_found then
          v_seq_bakashaMaxDate := null;
          v_date_bakasha       := null;
      end;*/
      /*  v_seq_bakashaMaxDate := null;
      begin
        v_date_bakasha := null;
        select max(b.date_bakasha)
          into v_date_bakasha
          from V_BAKASHA_LAST_STATUS b
         where b.code_sug_bakasha in trim(sugeyBakasha)
           and b.seq_ezor_ovdim = v_ezor_ovdim
           and b.mispar_zehut = v_id;
      exception
        when no_data_found then
          v_date_bakasha := null;
      end;*/
    end if;
    if (v_max_date_action is null) then
      v_max_date_action := to_date('01010001', 'ddmmyyyy');
    end if;
    if (v_date_bakasha is null) then
      v_date_bakasha := to_date('01010001', 'ddmmyyyy');
    end if;
    --במקרה שאין בקשה מאותו סוג יש לעדכן את משרד הפרישה
    --ואת סוג הבקשה שרוצים ליצור
  
    if (v_seq_bakashaMaxDate is null) then
      begin
        select p11.seq_prisha, p11.gimla_number
          into v_seq_prisha, v_mis_gimla_MPM
          from prisha p11
          left join poresh p
            on p.porshim_seq = p11.seq_poresh
           and p.mispar_zehut = v_id
         where p.mispar_zehut = v_id
           and p11.seq_ezor_ovdim = v_ezor_ovdim;
      exception
        when no_data_found then
          v_seq_prisha    := null;
          v_mis_gimla_MPM := null;
        when others then
          dbms_output.enable(999999999);
          Dbms_Output.put_line(v_ID);
      end;
    
      /*     if (v_sug_bakasha <> 7 and v_sug_bakasha <> 8) then
        begin
          select b.code_sug_bakasha
            into IsEXISTSsugBakashaRegila
            from v_Bakasha_Last_Status b
           where b.code_sug_bakasha = 1
             and b.mispar_zehut = v_ID;
        exception
          when no_data_found then
            IsEXISTSsugBakashaRegila := null;
            v_sug_bakasha            := 1;
        end;
        if (IsEXISTSsugBakashaRegila = 1) then
          v_sug_bakasha := 5;        
        end if;  
      end if;*/
    
    end if;
  
  end;

