  function delete_bakasha(p_seq_bakasha number) return varchar2 is
    pragma autonomous_transaction;
    v_cnt_other_bakashot_fr_prisha number;
    v_cnt_other_prishot_for_poresh number;
    --v_seq_prisha1                   number;
    v_seq_poresh number;
  
  begin
  
    select v.seq_prisha, v.seq_porshim, v.gimla_number
      into v_seq_prisha, v_seq_poresh, v_mis_gimla_MPM
      from v_bakasha_last_status v
     where v.seq_bakasha = p_seq_bakasha;
  
    select count(*)
      into v_cnt_other_bakashot_fr_prisha
      from v_bakasha v
     where v.SEQ_PRISHA = v_seq_prisha
       and v.SEQ_BAKASHA <> p_seq_bakasha;
  
    select count(*)
      into v_cnt_other_prishot_for_poresh
      from v_bakasha_last_status v
     where v.seq_porshim = v_seq_poresh
       and v.seq_prisha <> v_seq_prisha;
  
    delete from document_bakasha t11 where t11.seq_bakasha = p_seq_bakasha;
  
    delete from action_log t17 where t17.seq_bakasha = p_seq_bakasha;
  
    -----
    delete from tikim_mukdemet_hachlatot t16
     where t16.seq_bakasha = p_seq_bakasha;
  
    delete from tikim_mukdemet_misrot_lebitul t15
     where t15.seq_bakasha = p_seq_bakasha;
  
    delete from bakasha_mukdemet t14 where t14.seq_bakasha = p_seq_bakasha;
    -----
    -- נתוני דרגה ודרוג תיק   שמירת 
  
    select count(*)
      into v_cnt_darga_vederug_tik
      from darga_vederug_tik dvd
     where dvd.seq_bakasha = p_seq_bakasha;
    /* 
    if (v_cnt_darga_vederug_tik > 0) then
      v_dvd_Seq_Bakasha := v_seq_bakasha;
      UPDATE darga_vederug_tik dd
         SET dd.seq_bakasha = v_seq_bakasha
       WHERE dd.seq_bakasha = p_seq_bakasha;
    
      /*select dvd.taarich_me,
            dvd.taarich_ad,
            dvd.code_sug_darga,
            dvd.code_darga,
            dvd.code_derug,
            dvd.code_darga_ofek,
            dvd.code_derug_ofek
       into v_dvd_taarich_me,
            v_dvd_taarich_ad,
            v_dvd_code_sug_darga,
            v_dvd_code_darga,
            v_dvd_code_derug,
            v_dvd_code_darga_ofek,
            v_dvd_code_derug_ofek
       from darga_vederug_tik dvd
      where dvd.seq_bakasha = p_seq_bakasha;*/
    --end if;
  
    ---------------------------------  
    /*delete from darga_vederug_tik t13
    where t13.seq_bakasha = p_seq_bakasha;*/
  
    delete from decisions t12 where t12.seq_bakasha = p_seq_bakasha;
  
    delete from hagdala_nimuk t10 where t10.seq_bakasha = p_seq_bakasha;
  
    delete from netuney_tik_mechushavim t9
     where t9.seq_bakasha = p_seq_bakasha;
  
    delete from netuney_tik_mechushav_chnuch t19
     where t19.seq_bakasha = p_seq_bakasha;
  
    delete from netuney_tik_meushar_ozar t8
     where t8.seq_bakasha = p_seq_bakasha;
  
    delete participation_tkufot t19
     where t19.seq_participation in
           (select p.seq_participation
              from participation p
             where p.seq_bakasha = p_seq_bakasha);
  
    delete participation t7 where t7.seq_bakasha = p_seq_bakasha;
  
    delete from tkufot_avoda_mechushv t5
     where t5.seq_bakasha = p_seq_bakasha;
  
    delete from tkufot_avoda_golmi t6 where t6.seq_bakasha = p_seq_bakasha;
  
    delete tkufot_michutz_lasharut t4 where t4.seq_bakasha = p_seq_bakasha;
  
    delete from tkufot_sherut_tsvaii t3
     where t3.seq_bakasha = p_seq_bakasha;
  
    delete from tkufot_sikum t2 where t2.seq_bakasha = p_seq_bakasha;
  
    delete from bakasha_regila t1 where t1.seq_bakasha = p_seq_bakasha;
    -----------------
    update ld_log t18
       set t18.seq_bakasha = null, t18.date_delete = sysdate
     where seq_bakasha = p_seq_bakasha;
    -----------------
    /* delete from bakasha t where t.seq_bakasha = p_seq_bakasha;*/
  
    --If there is no other bakashot for the prisha
    /*  if v_cnt_other_bakashot_fr_prisha = 0 then
      delete from porshim_achronim b where b.seq_prisha = v_seq_prisha;
      delete from prisha a where a.seq_prisha = v_seq_prisha;
      
      --If there is no other prishot for the poresh
      if v_cnt_other_prishot_for_poresh = 0 then
        delete from action_log where SEQ_PORESH = v_seq_poresh;
        delete from bney_mishpacha where SEQ_PORSHIM = v_seq_poresh;
        delete from medical_vaada where SEQ_PORESH = v_seq_poresh;
        delete from tashlum_guf where SEQ_PORESH = v_seq_poresh;
        delete from tashlum_guf_draft where SEQ_PORESH = v_seq_poresh;
        delete from poresh p where p.porshim_seq = v_seq_poresh;
      end if;
    
    end if;*/
  
    commit;
    return 'done!';
  exception
    when others then
      rollback;
      return sqlerrm;
  end;
