    err_porshim_row.ora_err_mesg$ := field_name || ': ' || err_mesg;
    --else
    --   err_porshim_row.ora_err_mesg$ := get_message_according_code(info_type,
    --                                                             err_number,
    --                                                           field_name);
    -- end if;
  
    --הכנסת הערה לטבלת הERR
    insert into err_porshim values err_porshim_row;
    -- (v_ora_err_tag$) reject limit unlimited;
  
  end;
  ----------------------------------------
  procedure update_DERUG is
  
    v_code_derug number;
  begin
  
    if (v_cnt_darga_vederug_tik > 0) then
      --לדעתי הIF מיותר כי משאירים את הבקשה כולל דירוגים ודרגות
      if (1 = 0 and v_dvd_Seq_Bakasha <> v_seq_bakasha) then
        for r in (select p.taarich_me,
                         p.taarich_ad,
                         code_sug_darga,
                         code_darga,
                         code_derug,
                         code_darga_ofek,
                         code_derug_ofek,
                         p.seq_dargot_vederug_tik
                    from Darga_Vederug_Tik p
                   where p.seq_bakasha = v_dvd_Seq_Bakasha) loop
          --מעתיקים את דירוגים ודרגות מהבקשה המקורית
          merge into Darga_Vederug_Tik derug
          using dual
          on (derug.SEQ_BAKASHA = v_seq_bakasha and derug.seq_dargot_vederug_tik = r.seq_dargot_vederug_tik)
          when matched then
          --לא רלוונטי אבל גם לא מזיק
            update set TAARICH_ME = r.TAARICH_ME, code_derug = code_derug
          when not matched then
            insert
              (SEQ_DARGOT_VEDERUG_TIK,
               SEQ_BAKASHA,
               taarich_me,
               taarich_ad,
               code_sug_darga,
               code_darga,
               code_derug,
               code_darga_ofek,
               code_derug_ofek)
            values
              (DARGA_VEDERUG_TIK_SEQ.nextval,
               v_seq_bakasha,
               r.taarich_me,
               r.taarich_ad,
               r.code_sug_darga,
               r.code_darga,
               r.code_derug,
               r.code_darga_ofek,
               r.code_derug_ofek) log errors into err_darga_vederug_tik
              (v_ora_err_tag$) reject limit unlimited;
        end loop;
      end if;
      /*insert into Darga_Vederug_Tik
        (SEQ_DARGOT_VEDERUG_TIK,
         SEQ_BAKASHA,
         taarich_me,
         taarich_ad,
         code_sug_darga,
         code_darga,
         code_derug,
         code_darga_ofek,
         code_derug_ofek
         
         )
      values
        (DARGA_VEDERUG_TIK_SEQ.nextval,
         v_seq_bakasha,
         v_dvd_taarich_me,
         v_dvd_taarich_ad,
         v_dvd_code_sug_darga,
         v_dvd_code_darga,
         v_dvd_code_derug,
         v_dvd_code_darga_ofek,
         v_dvd_code_derug_ofek
         
         ) log errors into err_darga_vederug_tik
        (v_ora_err_tag$) reject limit unlimited;*/
    
    else
    
      for r in (select p.date_darga, p.kd_derug, p.teur_tafkid, p.kd_misrad
                  from tg_system.tg_poresh p
                 where p.zehut = v_id
                   and p.nosaf = 0) loop
      
        if r.kd_misrad = 210 or r.kd_misrad = 250 then
          v_code_derug := 41;
        else
          -- לבדוק אם הקוד דירוג קיים
          if (is_exist_Code_derug(to_number(trim(r.kd_derug)))) then
            v_code_derug := r.kd_derug;
          end if;
        end if;
      
        merge into Darga_Vederug_Tik derug
        using dual
        on (derug.SEQ_BAKASHA = v_seq_bakasha)
        when matched then
          update set TAARICH_ME = r.date_darga, code_derug = v_code_derug
        when not matched then
          insert
            (SEQ_DARGOT_VEDERUG_TIK, SEQ_BAKASHA, TAARICH_ME, code_derug)
          values
            (DARGA_VEDERUG_TIK_SEQ.nextval,
             v_seq_bakasha,
             r.date_darga,
             v_code_derug) log errors into err_darga_vederug_tik
            (v_ora_err_tag$) reject limit unlimited;
      end loop;
    end if;
  end;

