        --------------
        ResetFields;
        v_is_do_commit := true;
        v_date_gzira   := r.date_gzira;
        v_id           := r.zehut;
        v_mis_gimla    := trim(r.mis_gimla);
        --v_ezor_ovdim   :=
        SET_Ezor_Ovdim(r.kd_misrad, r.kd_yehida);
        v_ora_err_tag$ := to_char(v_id) || ' - ' ||
                          to_char(v_date_gzira, 'dd/mm/yyyy');
        v_where        := ' where ora_err_tag$= ''' || v_ora_err_tag$ || '''';
      
        v_is_exist_tkufot_avoda := false;
        if validate_id(1, r.zehut) = false then
          v_is_do_commit := false;
          goto endloop;
        end if;
      
        v_is_exist_participation_2_guf := is_exist_participation_l_guf;
        v_is_exist_participation_M_guf := is_exist_participation_m_guf;
        if (v_is_exist_participation_2_guf = true) then
          v_sug_bakasha := 8;
          SetMaxdateDecision;
          SETMaxDateActionLogForAction(36);
          if (v_Max_Date_Decision is not null and
             v_Max_Date_Decision > trunc(v_max_date_action) and
             v_Max_Date_Decision > v_date_bakasha) then
          
            /* if (v_seq_bakashaMaxDate is not null) then
              v_delete_bakasha := delete_bakasha(v_seq_bakashaMaxDate);
            end if;*/
          
            --השתתפות לגוף
            if ((v_seq_bakashaMaxDate is not null and
               not (delete_bakasha(v_seq_bakashaMaxDate) like ('%done!%'))) or
               update_bakasha(v_sug_bakasha) = false or
               update_bakasha_regila = false) then
            
              v_is_do_commit := false;
              goto endloop;
            else
              if (v_CODE_GROUP_PRISHA = 4) then
                update_bney_mishpaha;
              
              end if;
              V_CHELKIYUT_MESHUKLELET := null;
              update_netuney_tik_mechushavim;
              update_decisions;
              update_relative_decisions;
              update_hagdala_nimuk;
              update_vaada_ref;
            
              update_HEAROT_TO_ACTION_LOG;
              v_is_tam := update_tkufot_avoda_mehushv;
              update_participation_l_guf;
              update_actions_log(r.date_haavara_hash,
                                 v_is_exist_participation_2_guf);
              v_is_exist_participation_m_guf := false;
              update_participation_m_guf;
              update_DERUG;
              --add row log succses
              add_row_to_mgl_log_hasava(v_id,
                                        6,
                                        'MGL:' || v_Max_Date_Decision ||
                                        ' MPM:' || v_max_date_action);
            end if;
          else
            --לא הוסב 
            --תאריך החלטה במפמ מעודען יותר או שתאריך החלטה במגל NULL
            v_is_do_commit := false;
            goto endloop;
          end if;
          -------------------סוף השתתפות לגוף
        ELSE
          if (v_is_exist_participation_M_guf) then
            -----------השתתפות מגוף
            v_sug_bakasha := 7;
            SetMaxdateDecision;
            SETMaxDateActionLogForAction(36);
          
            if (v_Max_Date_Decision is not null and
               v_Max_Date_Decision > trunc(v_max_date_action) and
               v_Max_Date_Decision > v_date_bakasha) then
            
              /* if (v_seq_bakashaMaxDate is not null) then
                v_delete_bakasha := delete_bakasha(v_seq_bakashaMaxDate);
              end if;*/
            
              if ((v_seq_bakashaMaxDate is not null and not (delete_bakasha(v_seq_bakashaMaxDate) like
                  ('%done!%'))) or update_bakasha(v_sug_bakasha) = false or
                 update_bakasha_regila = false) then
                v_is_do_commit := false;
                goto endloop;
              else
                if (v_CODE_GROUP_PRISHA = 4) then
                  update_bney_mishpaha;
                
                end if;
                V_CHELKIYUT_MESHUKLELET := null;
                update_netuney_tik_mechushavim;
                update_decisions;
                update_relative_decisions;
                update_hagdala_nimuk;
                update_vaada_ref;
                update_actions_log(r.date_haavara_hash, true);
                update_HEAROT_TO_ACTION_LOG;
                v_is_tam := update_tkufot_avoda_mehushv;
                update_participation_l_guf;
                v_is_exist_participation_m_guf := false;
                update_participation_m_guf;
                update_DERUG;
                --add row log succses
              
                --לבדוק אם קיימת בקשה רגילה
                if (is_exist_bakasha_regila is null) then
                  if (update_bakasha(1) = false or
                     update_bakasha_regila = false) then
                    v_is_do_commit := false;
                    goto endloop;
                  else
                  
                    CREATE_NEW_DATA_BAKASHA(r.date_haavara_hash);
                  
                  end if;
                end if;
                --סוף הסבה השתתפות מגוף 
                add_row_to_mgl_log_hasava(v_id,
                                          6,
                                          'MGL:' || v_Max_Date_Decision ||
                                          ' MPM:' || v_max_date_action);
              
              end if;
            else
              --בכל מקרה צריך גם בקשה רגילה
              --לבדוק אם קיימת בקשה רגילה
              if (is_exist_bakasha_regila is null) then
                if (update_bakasha(1) = false or
                   update_bakasha_regila = false) then
                  v_is_do_commit := false;
                  goto endloop;
                else
                  /*  if (v_CODE_GROUP_PRISHA = 4) then
                    update_bney_mishpaha;
                  
                  end if;*/
                  CREATE_NEW_DATA_BAKASHA(r.date_haavara_hash);
                
                end if;
              else
                --------------
                --לא הוסב 
                --תאריך החלטה במפמ מעודען יותר או שתאריך החלטה במגל NULL
                v_is_do_commit := false;
                goto endloop;
              end if;
            end if;
          else
            ------------מסוג בקשה רגילה          
            v_sug_bakasha := 1;
            SetMaxdateDecision;
            SETMaxDateActionLogForAction(12);
            if (v_Max_Date_Decision is not null and
               v_Max_Date_Decision > v_max_date_action and
               v_Max_Date_Decision > v_date_bakasha) then
              /*            if (v_seq_bakashaMaxDate is not null) then
                v_delete_bakasha := delete_bakasha(v_seq_bakashaMaxDate);
              end if;*/
            
              ---------
              if ((v_seq_bakashaMaxDate is not null and not (delete_bakasha(v_seq_bakashaMaxDate) like
                  ('%done!%'))) or update_bakasha(v_sug_bakasha) = false or
                 update_bakasha_regila = false) then
              
                v_is_do_commit := false;
                goto endloop;
              else
                if (v_CODE_GROUP_PRISHA = 4) then
                  update_bney_mishpaha;
                
                end if;
                V_CHELKIYUT_MESHUKLELET := null;
                update_netuney_tik_mechushavim;
                update_decisions;
                update_relative_decisions;
                update_hagdala_nimuk;
                update_vaada_ref;
                update_actions_log(r.date_haavara_hash,
                                   v_is_exist_participation_2_guf);
                update_HEAROT_TO_ACTION_LOG;
                v_is_tam := update_tkufot_avoda_mehushv;
                update_participation_l_guf;
                v_is_exist_participation_m_guf := false;
                update_participation_m_guf;
                update_DERUG;
                add_row_to_mgl_log_hasava(v_id,
                                          6,
                                          'MGL:' || v_Max_Date_Decision ||
                                          ' MPM:' || v_max_date_action);
              
                --בכל מקרה צריך גם בקשה רגילה
                --לבדוק אם קיימת בקשה רגילה
                if (is_exist_bakasha_regila is null) then
                  if (update_bakasha(1) = false or
                     update_bakasha_regila = false) then
                    v_is_do_commit := false;
                    goto endloop;
                  else
                  
                    CREATE_NEW_DATA_BAKASHA(r.date_haavara_hash);
                  
                  end if;
                end if;
              
              end if;
              ----------
            else
              -------------אם לא קיימת בקשה רגילה , יש להוסיפה עם סיק בקשה קטן יותר בכל מקרה
            
              if (is_exist_bakasha_regila is null) then
                if (update_bakasha(1) = false or
                   update_bakasha_regila = false) then
                  v_is_do_commit := false;
                  goto endloop;
                else
                
                  CREATE_NEW_DATA_BAKASHA(r.date_haavara_hash);
                
                end if;
              else
                --*
              
                ---------------רשומה שלא הוסב
                --לא הוסב 
                --תאריך החלטה במפמ מעודען יותר או שתאריך החלטה במגל NULL
                v_is_do_commit := false;
                goto endloop;
              end if; --*
            end if;
          
          end if;
        
        end if;
      
        --במקרה שמספר גמלה במפמ ריק יש לעדכן ממגל
        if (v_seq_prisha is not null and
           (v_mis_gimla_MPM is null or v_mis_gimla_MPM = 0)) then
          update_mis_gimla;
        end if;
      
        <<endloop>>
        v_report_html := v_report_html ||
                        
                         info_about_errors_and_commit(v_is_do_commit, '');
      
        /*exception
          when
          others         then dbms_output.put_line('ERRROR' || v_id || sqlerrm);
          v_is_do_commit := false;
          v_report_html  := v_report_html ||
                           
                            info_about_errors_and_commit(v_is_do_commit, sqlerrm);
        
        end;*/
      
      exception
        when others then
          dbms_output.put_line('ERRROR' || v_id || sqlerrm);
          v_is_do_commit := false;
          v_report_html  := v_report_html ||
                           
                            info_about_errors_and_commit(v_is_do_commit,
                                                         sqlerrm);
        
      end;
    
    end loop;
  
    commit;
    return v_report_html;
  
  end;

----------------------------------------------------------
end;
/

create or replace package body prm_system_copy.convert_data_mgl_2_mpm_real3 is
  -----------------------------------------------------------
  /*--run on tg
    grant select on tg_poresh to PRM_HASAVOT_MAGAL;
    grant select on tg_p_tkufot_online to PRM_HASAVOT_MAGAL;
    grant select on tg_p_relatives to PRM_HASAVOT_MAGAL;
    
      grant select on tg_p_vaada_ref to PRM_HASAVOT_MAGAL;
    grant select on tg_p_decision to PRM_HASAVOT_MAGAL;
    grant select on tg_p_rel_history_decision to PRM_HASAVOT_MAGAL;
    
    grant select on tg_p_retzifut_l_guf to PRM_HASAVOT_MAGAL;
      grant select on tg_p_retzifut_m_guf to PRM_HASAVOT_MAGAL;
        grant select on tg_p_tkufat_hasherut to PRM_HASAVOT_MAGAL;
          grant select on tg_p_hagdalot to PRM_HASAVOT_MAGAL;
          grant select on tg_gimla_number to PRM_HASAVOT_MAGAL;
          grant insert on tg_gimla_number to PRM_HASAVOT_MAGAL;
          -- Grant/Revoke object privileges 
  grant SELECT on TG_K_GUFIM to PRM_HASAVOT_MAGAL;
  -- Grant/Revoke object privileges 
  grant select on TG_K_MISRAD to prm_hasavot_magal;
  
  -- Grant/Revoke object privileges 
  grant select on TG_P_AVODA_MEDINA to prm_system;
  
  -- Grant/Revoke object privileges 
  grant select on TG_P_SHERUT_KODEM to prm_hasavot_magal;
  -- Grant/Revoke object privileges 
  grant select on TG_P_ARAIM to prm_hasavot_magal;
  -- Grant/Revoke object privileges 
  grant insert on TG_P_TKUFOT_ONLINE to PRM_HASAVOT_MAGAL;
  grant select on tg_P_HEAROT to PRM_HASAVOT_MAGAL ;
    
    */
  -----------------------------------------------------------
  v_id           number;
  v_ezor_ovdim   number;
  v_date_gzira   date;
  v_porshim_seq  number;
  v_seq_prisha   number;
  v_seq_bakasha  number;
  v_ora_err_tag$ varchar2(100);
  v_where        varchar2(100);
  --if_exist_participation_M_guf need to create additional bakasha
  v_is_exist_participation_M_guf boolean;
  v_is_exist_tkufot_avoda        boolean;
  v_CODE_GROUP_PRISHA            number;
  v_is_exist_participation_2_guf boolean;
  V_CHELKIYUT_MESHUKLELET        number;
  v_is_NOT_VALID_ID              boolean;
  v_Max_Date_Decision            date;
  v_max_date_action              date;
  v_seq_bakashaMaxDate           number;
  v_sug_bakasha                  number;
  v_date_bakasha                 date;
  v_sach_chodashim               number;
  v_seq_MinBakasha               number;
  --שמירת דירוג ודרגה
  v_cnt_darga_vederug_tik number;
  v_dvd_taarich_me        date;
  v_dvd_taarich_ad        date;
  v_dvd_code_sug_darga    number;
  v_dvd_code_darga        number;
  v_dvd_code_derug        number;
  v_dvd_code_darga_ofek   number;
  v_dvd_code_derug_ofek   number;
  v_dvd_Seq_Bakasha       number;

  v_CODE_SEIF_PRISHA   number;
  v_date_start_zakahut date;
  v_mis_gimla          number;
  v_mis_gimla_MPM      number;
  --ממתין לטיפול נש"מ
  v_DATE_NASHAM_6 date;
  --אישור בודק נש"מ
  v_DATE_NASHAM_7 date;
  -------------------------------------

  procedure set_new_min_seq_bakasha(v_min_seq_bakasha number) is
    v_new_seq_bakasha number;
  begin
    v_new_seq_bakasha := null;
    begin
      /* for i in reverse 1 .. v_min_seq_bakasha - 1 loop
      begin
        select i
          into v_new_seq_bakasha
          from dual
         where i not in
               (select b.seq_bakasha from V_BAKASHA_LAST_STATUS b);*/
    
      select max(round((l + seq_bakasha) / 2)) as v_new_seq_bakasha
        into v_new_seq_bakasha
        from (select seq_bakasha,
                     lead(seq_bakasha) over(order by seq_bakasha asc) as l
                from V_BAKASHA_LAST_STATUS t
               order by seq_bakasha asc) t
       where 1 = 1
            --and rownum = 1
         and l - seq_bakasha > 1
         and l <= v_min_seq_bakasha;
    
    exception
      when no_data_found then
        v_new_seq_bakasha := null;
    end;
  
    --  EXIT WHEN v_new_seq_bakasha is not null;
    --end loop;
  
    if (v_new_seq_bakasha is not null) then
      v_seq_bakasha := v_new_seq_bakasha;
    end if;
  
    -- end;
  end;
  --------------------------
  procedure set_NASHAM_DATES(p_Seq_bakasha number) is
  begin
    begin
      select max(al.date_action)
        into v_DATE_NASHAM_6
      
        from Action_Log al
       where al.seq_bakasha = p_Seq_bakasha
         and al.code_action = 6;
    exception
      when no_data_found then
        v_DATE_NASHAM_6 := null;
    end;
  
    begin
      select max(al.date_action)
        into v_DATE_NASHAM_7
      
        from Action_Log al
       where al.seq_bakasha = p_Seq_bakasha
         and al.code_action = 7;
    exception
      when no_data_found then
        v_DATE_NASHAM_7 := null;
    end;
  end;
  --------------------------------------------------
  --לא נבדק ...........כי אין צורך לשימוש בינתיים
  procedure set_new_seq_bakasha_between(v_min_seq_bakasha number,
                                        v_max_seq_bakasha number) is
    v_new_seq_bakasha number;
  begin
    v_new_seq_bakasha := null;
    begin
    
      select max(round((l + seq_bakasha) / 2)) as v_new_seq_bakasha
        into v_new_seq_bakasha
        from (select seq_bakasha,
                     lead(seq_bakasha) over(order by seq_bakasha asc) as l
                from V_BAKASHA_LAST_STATUS t
               order by seq_bakasha asc) t
       where 1 = 1
         and l - seq_bakasha > 1
         and l >= v_min_seq_bakasha
         and l <= v_max_seq_bakasha
      
      ;
    
    exception
      when no_data_found then
        v_new_seq_bakasha := null;
    end;
  
    if (v_new_seq_bakasha is not null) then
      v_seq_bakasha := v_new_seq_bakasha;
    end if;
  end;

  --------------------------------------------------
  procedure set_seq_bakasha(v_code_sug_bakasha number) is
  
  begin
    begin
    
      if (v_code_sug_bakasha = 1 and is_exist_bakasha_regila is null) then
        if (is_exist_bakasha_mukdemet is not null) then
          --אם קיימ בקשה מוקדמת לפרישה 
          v_seq_bakasha := bakasha_seq.nextval;
        else
          --צריך למצוא את הקטן מ הנמוך ביותר
          set_new_min_seq_bakasha(v_seq_MinBakasha);
        end if;
      else
        if (v_seq_bakashaMaxDate is not null) then
          v_seq_bakasha := v_seq_bakashaMaxDate;
        else
          v_seq_bakasha := bakasha_seq.nextval;
        end if;
      end if;
    end;
  end;
  ---------------------------------------

  procedure CREATE_NEW_DATA_BAKASHA(p_date_haavara_hash date) is
    v_is_tam boolean;
  begin
  
    /*  if (v_CODE_GROUP_PRISHA = 4) then
      update_bney_mishpaha;
    
    end if;*/
    V_CHELKIYUT_MESHUKLELET := null;
    update_netuney_tik_mechushavim;
    update_decisions;
    update_relative_decisions;
    update_hagdala_nimuk;
    update_vaada_ref;
  
    update_HEAROT_TO_ACTION_LOG;
    v_is_tam := update_tkufot_avoda_mehushv;
    update_participation_l_guf;
    update_actions_log(p_date_haavara_hash, v_is_exist_participation_2_guf);
    v_is_exist_participation_m_guf := false;
    update_participation_m_guf;
    update_DERUG;
  end;
  --------------------------------------------------
  procedure set_CODE_GROUP_PRISHA(v_code_seif number) is
  begin
    begin
      select t.code_group_prisha
        into v_CODE_GROUP_PRISHA
        from code_seif_prisha t
       where t.code_seif_prisha = v_code_seif
         and ROWNUM = 1;
    exception
      when no_data_found then
        v_CODE_GROUP_PRISHA := null;
    end;
  end;
  -------------------------------------------------

  procedure DELETE_MAX_BAKASHA is
    v_delete_bakasha varchar2(1000);
  begin
    --טיוב נתונים - מחיקת כפולים של חינוך
    /* for r in (select bl.mispar_zehut, max(bl.seq_bakasha) as seq_bakasha
                from V_BAKASHA_LAST_STATUS bl
               where bl.code_sug_bakasha = 1
                 and bl.mispar_zehut in (54790555,
                                         51627677,
                                         80980204,
                                         33309261,
                                         17322389,
                                         13804141,
                                         53427654,
                                         50505866,
                                         303949937,
                                         30362883,
                                         22326375,
                                         22704266)
               GROUP BY bl.mispar_zehut) loop
      v_delete_bakasha := pk_prm_utils.delete_bakasha(r.seq_bakasha);
      delete from MGL_LOG_HASAVA m where m.mispar_zehut = r.mispar_zehut;
    end loop;*/
  
    commit;
  end;

  ----------------------------------------------
  procedure DELETE_CONVERTED_DATA is
    v_delete_bakasha varchar2(1000);
  
  begin
    --טיוב נתונים - מחיקת כפולים של חינוך
    for r in (select
              -- b.mispar_zehut,
               b.seq_bakasha
              --, b.code_sug_bakasha, b.seq_ezor_ovdim
                from v_bakasha_last_status b
               where (b.seq_ezor_ovdim = 206 and b.code_sug_bakasha = 5 and
                     exists (select a.seq_bakasha
                               from action_log a
                              where a.seq_bakasha = b.seq_bakasha
                                and a.code_action = 98) and not exists
                      (select a.seq_bakasha
                         from action_log a
                        where a.seq_bakasha = b.seq_bakasha
                          and a.code_action = 12
                          and nvl(a.code_user_update, 0) <> 0))
                 and not exists (select a.seq_bakasha
                        from action_log a
                       where a.seq_bakasha = b.seq_bakasha
                         and a.code_action = 100)
               order by b.mispar_zehut) loop
      v_delete_bakasha := pk_prm_utils.delete_bakasha(r.seq_bakasha);
    end loop;
  
    /*    for r in (select *
                from MGL_LOG_HASAVA l
               where l.code_hasava = 1
              ) loop  
      for r2 in (select *
                   from V_BAKASHA_LAST_STATUS bl
                  where bl.mispar_zehut = r.mispar_zehut) loop
      
        v_delete_bakasha := pk_prm_utils.delete_bakasha(r2.seq_bakasha);
      end loop;
    end loop;
    delete from MGL_LOG_HASAVA m
     where m.mispar_zehut not in (select p.mispar_zehut from PORESH p);*/
    ---- v_delete_bakasha := delete_bakasha(43150);
    -- v_delete_bakasha := delete_bakasha(50143);
    -- delete from darga_vederug_tik t13 where t13.seq_bakasha = 42280;
    ----  delete from darga_vederug_tik t13 where t13.seq_bakasha = 43150;
    -- delete from bakasha t where t.seq_bakasha = 42280;
    ---- delete from bakasha t where t.seq_bakasha = 43150;
    commit;
  end;
  -------------------------------------------------
  procedure validate_MZ is
  
  begin
    dbms_output.enable(999999999);
    for r in (select distinct l.mispar_zehut as zehut
                from MGL_LOG_HASAVA l
              
              /*for r in (select p.zehut from tg_system.tg_poresh p*/
              
              ) loop
      if (validate_id(1, r.zehut) = false) then
        dbms_output.put_line(r.zehut);
      end if;
    end loop;
  
    commit;
  end;
  --------------------------------
  procedure ResetFields is
  begin
    v_id                    := null;
    v_ezor_ovdim            := null;
    v_date_gzira            := null;
    v_porshim_seq           := null;
    v_seq_prisha            := null;
    v_seq_bakasha           := null;
    v_CODE_GROUP_PRISHA     := null;
    v_seq_bakashaMaxDate    := null;
    v_sug_bakasha           := null;
    v_seq_MinBakasha        := null;
    v_cnt_darga_vederug_tik := 0;
    v_DATE_NASHAM_6         := null;
    v_DATE_NASHAM_7         := null;
    /*v_is_exist_participation_M_guf boolean;
