  ----------------------------------------------------------
  function update_poresh return boolean is
    poresh_row err_porshim%rowtype;
  begin
    for r in (select p.zehut,
                     convert_low_hebrew_to_ascii(p.surname) surname,
                     convert_low_hebrew_to_ascii(p.first_name) first_name,
                     convert_low_hebrew_to_ascii(p.sm_kodem) sm_kodem,
                     convert_low_hebrew_to_ascii(p.adress) adress,
                     p.mikud,
                     p.tel,
                     p.kd_min,
                     p.kd_min_mazav,
                     p.date_leida,
                     p.date_aliya,
                     p.is_ole_hadash,
                     p.is_asir,
                     p.date_begin_maasar,
                     p.date_end_maasar,
                     p.date_ptira,
                     p.kd_sibat_ptira,
                     convert_low_hebrew_to_ascii(p.apotr_name) apotr_name,
                     convert_low_hebrew_to_ascii(p.apotr_adress) apotr_adress,
                     p.apotr_mikud,
                     i.code_ir apotr_city,
                     j.code_ir city,
                     p.is_baal_teudat_ptira
                from tg_system.tg_poresh p
                left join code_ir i
                  on replace(i.teur_ir, ' ') =
                     replace(convert_low_hebrew_to_ascii(trim(p.apotr_city)),
                             ' ')
                left join code_ir j
                  on replace(j.teur_ir, ' ') =
                     replace(convert_low_hebrew_to_ascii(trim(p.city)), ' ')
               where p.nosaf = 0
                 and p.zehut = v_id) loop
      poresh_row.city_code             := nvl(r.city, 0);
      poresh_row.mispar_zehut          := r.zehut;
      poresh_row.shem_mishpacha        := r.surname;
      poresh_row.shem_prati            := r.first_name;
      poresh_row.shem_kodem            := r.sm_kodem;
      poresh_row.taarich_leda          := r.date_leida;
      poresh_row.address               := r.adress;
      poresh_row.mikud                 := r.mikud;
      poresh_row.telephon              := r.tel;
      poresh_row.taarich_aliya         := r.date_aliya;
      poresh_row.date_begin_maasar     := r.date_begin_maasar;
      poresh_row.date_end_maasar       := r.date_end_maasar;
      poresh_row.taarich_ptira         := r.date_ptira;
      poresh_row.code_ptira_siba       := to_number(trim(r.kd_sibat_ptira));
      poresh_row.is_owner_teudat_ptira := convert_0_or_1_number(r.is_baal_teudat_ptira);
    
      if r.is_asir = 1 and r.date_begin_maasar is not null then
        poresh_row.is_asir := 1;
      else
        poresh_row.is_asir := 0;
      end if;
      if trim(r.kd_min) in (1, 2) then
        poresh_row.code_min := to_number(trim(r.kd_min));
        -- else
        --  poresh_row.code_min := 999;
      end if;
      poresh_row.seq_apotropus := get_create_apotropus(trim(r.apotr_name),
                                                       trim(r.apotr_adress),
                                                       trim(r.apotr_mikud),
                                                       nvl(r.apotr_city, 0));
    
      poresh_row.is_newcomer           := convert_0_or_1_number(r.is_ole_hadash);
      poresh_row.code_mazav_mishpachti := convert_code_mazav_mishpachti(to_number(trim(r.kd_min_mazav)));
      if pk_load_mimshak.is_exist_poresh(v_id, v_porshim_seq) = false then
        v_porshim_seq := porshim_seq.nextval;
      end if;
      --merge into poresh
      merge into poresh
      using dual
      on (poresh.mispar_zehut = poresh_row.mispar_zehut)
      when matched then
        update
           set city_code1             = poresh_row.city_code,
               seq_apotropus          = poresh_row.seq_apotropus,
               shem_mishpacha         = poresh_row.shem_mishpacha,
               shem_prati             = poresh_row.shem_prati,
               shem_kodem             = poresh_row.shem_kodem,
               code_min               = poresh_row.code_min,
               taarich_leda           = poresh_row.taarich_leda,
               address1               = poresh_row.address,
               mikud1                 = poresh_row.mikud,
               telephon               = poresh_row.telephon,
               code_mazav_mishpachti1 = poresh_row.code_mazav_mishpachti,
               taarich_aliya          = poresh_row.taarich_aliya,
               is_newcomer            = poresh_row.is_newcomer,
               is_asir                = poresh_row.is_asir,
               date_begin_maasar      = poresh_row.date_begin_maasar,
               date_end_maasar        = poresh_row.date_end_maasar,
               taarich_ptira          = poresh_row.taarich_ptira,
               code_ptira_siba        = poresh_row.code_ptira_siba,
               is_owner_teudat_ptira  = poresh_row.is_owner_teudat_ptira
      when not matched then
        insert
          (city_code1,
           seq_apotropus,
           porshim_seq,
           mispar_zehut,
           shem_mishpacha,
           shem_prati,
           shem_kodem,
           code_min,
           taarich_leda,
           address1,
           mikud1,
           telephon,
           code_mazav_mishpachti1,
           taarich_aliya,
           is_newcomer,
           is_asir,
           date_begin_maasar,
           date_end_maasar,
           taarich_ptira,
           code_ptira_siba,
           is_owner_teudat_ptira)
        values
          (poresh_row.city_code,
           poresh_row.seq_apotropus,
           v_porshim_seq,
           poresh_row.mispar_zehut,
           poresh_row.shem_mishpacha,
           poresh_row.shem_prati,
           poresh_row.shem_kodem,
           poresh_row.code_min,
           poresh_row.taarich_leda,
           poresh_row.address,
           poresh_row.mikud,
           poresh_row.telephon,
           poresh_row.code_mazav_mishpachti,
           poresh_row.taarich_aliya,
           poresh_row.is_newcomer,
           poresh_row.is_asir,
           poresh_row.date_begin_maasar,
           poresh_row.date_end_maasar,
           poresh_row.taarich_ptira,
           poresh_row.code_ptira_siba,
           poresh_row.is_owner_teudat_ptira) log errors into err_porshim
          (v_ora_err_tag$) reject limit unlimited;
    end loop;
  
    if pk_load_mimshak.count_rowes('err_porshim', v_where) > 0 then
      return false;
    else
      return true;
    end if;
  
  end;
  --------------------------------------------------------------------------------
  procedure update_vaada_ref is
    v_medical_vaada_seq      number;
    v_is_permanent_nechut    number;
    v_is_teuna               number;
    v_is_hagbala_ref_b_knisa number;
    v_dargat_nechut          number;
    v_dargat_nechut_lchishuv number;
    v_accident_percent       number;
  begin
    for rr in (select *
                 from (select v.SEQ_BAKASHA,
                              t.zehut,
                              t.kd_timing,
                              t.date_decision,
                              t.dargat_nechut,
                              t.is_permanent_nechut,
                              t.dargat_nechut_l_chishuv,
                              t.tkufa_nechut,
                              t.date_start_nechut,
                              t.is_teuna,
                              t.achuze_ekev_teuna,
                              t.is_hagbala_ref_b_knisa
                         from tg_system.tg_p_vaada_ref t
                         left join v_bakasha v
                           on t.zehut = v.MISPAR_ZEHUT
                        where (t.date_decision is not null or
                              t.date_decision is not null or
                              t.dargat_nechut is not null or
                              t.dargat_nechut_l_chishuv is not null or
                              t.tkufa_nechut is not null or
                              t.date_start_nechut is not null or
                              t.is_teuna is not null or
                              t.achuze_ekev_teuna is not null or
                              t.is_hagbala_ref_b_knisa is not null and
                              t.kd_timing = '2')
                          and t.zehut = v_id
                          and t.nosaf = 0
                        order by nvl(t.date_decision,
                                     to_date('01010001', 'ddmmyyyy')) desc)) loop
      update bakasha_regila b
         set b.nechut_taarich_hamigbala = rr.date_start_nechut,
             b.nechut_achuz             = rr.dargat_nechut
      -- b.date_vaada_refuit            = rr.date_decision,
      -- b.nechut_achuz_nechut_leprisha = rr.dargat_nechut_l_chishuv,
       where b.seq_bakasha = rr.seq_bakasha;
    end loop;
  end;
  --------------------------------------------------------------
  function update_bakasha_regila return boolean is
    bakasha_regila_row err_bakasha_regila%rowtype;
  begin
    v_CODE_SEIF_PRISHA := null;
    for r in (select p.is_poresh_briut_after_hakpaa,
                     p.date_chatima_tofes,
                     p.date_prisha,
                     p.kd_sibat_prisha,
                     decode(p.date_kabala_police,
                            null,
                            p.date_kabala_lasherut,
                            p.date_kabala_police) date_kabala_lasherut,
                     p.achuz_hivun,
                     p.date_leida,
                     p.is_zchut_tvia_tzad_3,
                     p.date_heskem_hakpaa,
                     p.is_chose_medina_v_shikum,
                     p.is_chose_shikum,
                     p.is_hitzhir_eino_oved,
                     p.date_vaada_refuit,
                     p.is_sheer_chose_pitzuim,
                     p.is_oblig_tashlum_mezonot,
                     p.is_lo_hotzi_pitzuim,
                     p.is_baal_gimlaot_kefel,
                     p.is_pasul_varam,
                     p.vetek_max,
                     p.dargat_nechut_bitahon,
                     p.date_end_work,
                     convert_low_hebrew_to_ascii(p.makor_gimla_nosefet) makor_gimla_nosefet,
                     p.is_mevutach_beguf,
                     p.has_another_income,
                     p.vetek_maskoret,
                     p.kd_takanon,
                     p.maskoret_kovaat,
                     p.teur_tafkid
                from tg_system.tg_poresh p
               where p.zehut = v_id
                 and p.nosaf = 0) loop
      bakasha_regila_row.psul_histakrut := convert_0_or_1_number(r.is_poresh_briut_after_hakpaa);
      if (r.achuz_hivun > 999.99) then
        bakasha_regila_row.hivun_percent := null;
      else
        bakasha_regila_row.hivun_percent := trunc(r.achuz_hivun, 2);
      end if;
      if trim(r.kd_takanon) = 4 then
        bakasha_regila_row.chinuch_mikzoa := 911;
      end if;
      ------הוספתי--------
      if (r.teur_tafkid like ('%מורה%')) then
        bakasha_regila_row.chinuch_mikzoa := 3;
      else
        if (r.teur_tafkid like ('%גננת%')) then
          bakasha_regila_row.chinuch_mikzoa := 2;
        end if;
      end if;
      ---------------------
      bakasha_regila_row.is_lo_hotzi_pitzuim  := convert_0_or_1_number(r.is_lo_hotzi_pitzuim);
      bakasha_regila_row.is_hitzhir_eino_oved := convert_0_or_1_number(r.is_hitzhir_eino_oved);
      bakasha_regila_row.is_tvia_zad_gimel    := convert_0_or_1_number(r.is_zchut_tvia_tzad_3);
      bakasha_regila_row.is_contract_shikum   := convert_0_or_1_number(r.is_chose_shikum);
      --bakasha_regila_row.is_contract_medina_vshikum := convert_0_or_1_number(r.is_chose_medina_v_shikum);
      bakasha_regila_row.code_seif_prisha := convert_code_seif_prisha(trim(r.kd_sibat_prisha));
      v_CODE_SEIF_PRISHA                  := bakasha_regila_row.code_seif_prisha;
      --------------CONVERT CODE_GROUP_PRISHA
      set_CODE_GROUP_PRISHA(bakasha_regila_row.code_seif_prisha);
    
      --bakasha_regila_row.code_takanon_magal       := to_number(trim(r.kd_takanon));
      --bakasha_regila_row.salary_seniority := r.vetek_maskoret;
      bakasha_regila_row.has_another_income  := convert_0_or_1_number(r.has_another_income);
      bakasha_regila_row.is_mevutach_beguf   := convert_0_or_1_number(r.is_mevutach_beguf);
      bakasha_regila_row.makor_gimla_nosefet := r.makor_gimla_nosefet;
      bakasha_regila_row.date_end_work       := r.date_end_work;
      --bakasha_regila_row.dargat_nechut_bitahon    := r.dargat_nechut_bitahon;
      --bakasha_regila_row.vetek_max                := r.vetek_max;
      --bakasha_regila_row.is_pasul_varam           := convert_0_or_1_number(r.is_pasul_varam);
      --bakasha_regila_row.is_baal_gimlaot_kefel    := convert_0_or_1_number(r.is_baal_gimlaot_kefel);
      bakasha_regila_row.date_vaada_refuit      := r.date_vaada_refuit;
      bakasha_regila_row.is_sheer_chose_pitzuim := convert_0_or_1_number(r.is_sheer_chose_pitzuim);
      --bakasha_regila_row.is_oblig_tashlum_mezonot := convert_0_or_1_number(r.is_oblig_tashlum_mezonot);
      bakasha_regila_row.taarich_chatimat_tofes := r.date_chatima_tofes;
      bakasha_regila_row.taarich_prisha         := r.date_prisha;
      /*case
        when r.date_prisha > r.date_leida then
         r.date_prisha
        else
         null
      end;*/
      -- bakasha_regila_row.taarich_knisa      := r.date_kabala_lasherut;
      bakasha_regila_row.date_freeze_haskem := r.date_heskem_hakpaa;
      bakasha_regila_row.maskoret_kovaat    := r.maskoret_kovaat;
    
      merge into bakasha_regila
      using dual
      on (bakasha_regila.seq_bakasha = v_seq_bakasha)
      when matched then
        update
           set --code_takanon_magal       = bakasha_regila_row.code_takanon_magal,
               psul_histakrut = bakasha_regila_row.psul_histakrut,
               --salary_seniority         = bakasha_regila_row.salary_seniority,
               has_another_income  = bakasha_regila_row.has_another_income,
               is_mevutach_beguf   = bakasha_regila_row.is_mevutach_beguf,
               makor_gimla_nosefet = bakasha_regila_row.makor_gimla_nosefet,
               date_end_work       = bakasha_regila_row.date_end_work,
               -- dargat_nechut_bitahon    = bakasha_regila_row.dargat_nechut_bitahon,
               --vetek_max = bakasha_regila_row.vetek_max,
               -- is_pasul_varam           = bakasha_regila_row.is_pasul_varam,
               -- is_baal_gimlaot_kefel    = bakasha_regila_row.is_baal_gimlaot_kefel,
               date_vaada_refuit      = bakasha_regila_row.date_vaada_refuit,
               is_sheer_chose_pitzuim = bakasha_regila_row.is_sheer_chose_pitzuim,
               -- is_oblig_tashlum_mezonot = bakasha_regila_row.is_oblig_tashlum_mezonot,
               is_lo_hotzi_pitzuim    = bakasha_regila_row.is_lo_hotzi_pitzuim,
               is_hitzhir_eino_oved   = bakasha_regila_row.is_hitzhir_eino_oved,
               taarich_chatimat_tofes = bakasha_regila_row.taarich_chatimat_tofes,
               taarich_prisha         = bakasha_regila_row.taarich_prisha,
               code_seif_prisha       = bakasha_regila_row.code_seif_prisha,
               --taarich_knisa          = bakasha_regila_row.taarich_knisa,
               hivun_percent      = bakasha_regila_row.hivun_percent,
               is_tvia_zad_gimel  = bakasha_regila_row.is_tvia_zad_gimel,
               date_freeze_haskem = bakasha_regila_row.date_freeze_haskem,
               --  is_contract_medina_vshikum = bakasha_regila_row.is_contract_medina_vshikum,
               is_contract_shikum = bakasha_regila_row.is_contract_shikum,
               chinuch_mikzoa     = bakasha_regila_row.chinuch_mikzoa
      when not matched then
        insert
          ( --code_takanon_magal,
           psul_histakrut,
           -- salary_seniority,
           has_another_income,
           is_mevutach_beguf,
           makor_gimla_nosefet,
           date_end_work,
           -- dargat_nechut_bitahon,
           --vetek_max,
           --is_pasul_varam,
           --is_baal_gimlaot_kefel,
           date_vaada_refuit,
           is_sheer_chose_pitzuim,
           --is_oblig_tashlum_mezonot,
           is_lo_hotzi_pitzuim,
           is_hitzhir_eino_oved,
           seq_bakasha,
           taarich_chatimat_tofes,
           taarich_prisha,
           code_seif_prisha,
           --taarich_knisa,
           hivun_percent,
           is_tvia_zad_gimel,
           date_freeze_haskem,
           -- is_contract_medina_vshikum,
           is_contract_shikum,
           chinuch_mikzoa)
        values
          ( --bakasha_regila_row.code_takanon_magal,
           bakasha_regila_row.psul_histakrut,
           --bakasha_regila_row.salary_seniority,
           bakasha_regila_row.has_another_income,
           bakasha_regila_row.is_mevutach_beguf,
           bakasha_regila_row.makor_gimla_nosefet,
           bakasha_regila_row.date_end_work,
           -- bakasha_regila_row.dargat_nechut_bitahon,
           -- bakasha_regila_row.vetek_max,
           -- bakasha_regila_row.is_pasul_varam,
           -- bakasha_regila_row.is_baal_gimlaot_kefel,
           bakasha_regila_row.date_vaada_refuit,
           bakasha_regila_row.is_sheer_chose_pitzuim,
           -- bakasha_regila_row.is_oblig_tashlum_mezonot,
           bakasha_regila_row.is_lo_hotzi_pitzuim,
           bakasha_regila_row.is_hitzhir_eino_oved,
           v_seq_bakasha,
           bakasha_regila_row.taarich_chatimat_tofes,
           bakasha_regila_row.taarich_prisha,
           bakasha_regila_row.code_seif_prisha,
           --bakasha_regila_row.taarich_knisa,
           bakasha_regila_row.hivun_percent,
           bakasha_regila_row.is_tvia_zad_gimel,
           bakasha_regila_row.date_freeze_haskem,
           -- bakasha_regila_row.is_contract_medina_vshikum,
           bakasha_regila_row.is_contract_shikum,
           bakasha_regila_row.chinuch_mikzoa) log errors into err_bakasha_regila
          (v_ora_err_tag$) reject limit unlimited;
    end loop;
  
    if pk_load_mimshak.count_rowes('err_bakasha_regila', v_where) > 0 then
      return false;
    else
      return true;
    end if;
  end;
  ----------------------------------------------------------------

  procedure update_netuney_tik_mechushavim is
    v_achuz_kizba_chelkiyut_melea number;
    v_code_sug_prisha             number;
    v_odef_sherut_yamim           number;
    v_is_zakai_lmaanak            number;
    v_is_zakai_lkitzba            number;
  begin
    for r in (select p.pizuy_odef_shanim_months odef_sherut_chodashim,
                     p.pizuy_odef_shanim_days odef_shert_yamim,
                     p.hok_helk_lefi_years,
                     p.hok_helk_lkitzba,
                     p.hok_helk_lmaanak,
                     p.hok_is_zakai_lkitzba,
                     p.hok_achuz_kitzba_sofi,
                     p.hok_is_zakai_lmaanak,
                     p.hok_helk_lefi_nechut,
                     p.hok_kitzba_lefi_nechut,
                     p.hok_medina_meshuklal_bhelkiut,
                     p.hok_kitzba_lefi_medina_only,
                     p.pizuy_odef_shanim_days,
                     p.hok_medina_vhisht_meshuklal,
                     convert_low_hebrew_to_ascii(trim(p.kd_sug_prisha)) kd_sug_prisha,
                     p.hok_kitzba_bhelkiut_nechut,
                     p.hok_kitzba_lefi_medina_vhisht,
                     p.date_start_zakaut,
                     p.schum_maanak,
                     p.Hok_Sach_Months_Mezakim
              
                from tg_system.tg_poresh p
               where p.zehut = v_id
                 and p.nosaf = 0) loop
    
      V_CHELKIYUT_MESHUKLELET := r.hok_helk_lefi_years;
      if (r.hok_medina_meshuklal_bhelkiut > 99) then
        v_achuz_kizba_chelkiyut_melea := null;
      else
        v_achuz_kizba_chelkiyut_melea := trunc(r.hok_medina_meshuklal_bhelkiut,
                                               2);
      end if;
    
      if (r.pizuy_odef_shanim_days >= 0 and r.pizuy_odef_shanim_days < 100) then
        v_odef_sherut_yamim := r.pizuy_odef_shanim_days;
      else
        v_odef_sherut_yamim := null;
      end if;
    
      if (r.kd_sug_prisha = 'ש' or r.kd_sug_prisha = 'y') then
        v_code_sug_prisha := 1;
      elsif (r.kd_sug_prisha = 'נ' or r.kd_sug_prisha = 'p') then
        v_code_sug_prisha := 2;
      else
        v_code_sug_prisha := null;
      end if;
    
      v_is_zakai_lmaanak := convert_0_or_1_number(r.hok_is_zakai_lmaanak);
      v_is_zakai_lkitzba := convert_0_or_1_number(r.hok_is_zakai_lkitzba);
      insert into netuney_tik_mechushavim n
        (n.odef_sherut_chodashim,
         n.odef_sherut_yamim,
         code_department,
         achuz_kizba_nechut,
         achuz_kizba_chelkiyut_melea,
         achuz_kizba_kafuf_chelkiyut,
         odef_sherut_yamim,
         seq_netuney_tik_mechushavim,
         seq_bakasha,
         --code_sug_prisha,
         chelkiut_lefi_nechut,
         achuz_kizba_sofi,
         --chelkiut_lkitzba,
         is_zakai_lmaanak,
         --is_zakai_lkitzba,
         --chelkiut_lefi_sherut,
         --chelkiut_lmaanak,
         --kitzba_bchelkiut_nechut,
         -- kitzba_lefi_medina_vhisht,
         kitzba_medina_hisht_meshukll,
         date_start_zakaut,
         -- schum_maanak,
         tkufa_mezaka_sherut,
         ahuz_kizb_achry_hagdl_kaf_chel,
         CHELKIYUT_MESHUKLELET_SHERUT)
      values
        (r.odef_sherut_chodashim,
         r.odef_shert_yamim,
         1,
         r.hok_kitzba_lefi_nechut,
         v_achuz_kizba_chelkiyut_melea,
         r.hok_kitzba_lefi_medina_only,
         r.pizuy_odef_shanim_days,
         netuney_tik_mechushavim_seq.nextval,
         v_seq_bakasha,
         --,
         r.hok_helk_lefi_nechut,
         r.hok_achuz_kitzba_sofi,
         -- r.hok_helk_lkitzba,
         v_is_zakai_lmaanak,
         -- v_is_zakai_lkitzba,
         --r.hok_helk_lefi_years,
         -- r.hok_helk_lmaanak,
         -- r.hok_kitzba_bhelkiut_nechut,
         --  r.hok_kitzba_lefi_medina_vhisht,
         r.hok_medina_vhisht_meshuklal,
         r.date_start_zakaut,
         
         -- r.schum_maanak,
         r.Hok_Sach_Months_Mezakim,
         r.hok_kitzba_lefi_medina_only,
         r.hok_helk_lefi_years) log errors into err_netuney_tik_mechushavim
        (v_ora_err_tag$) reject limit unlimited;
    
      -----------------------הוספתי----------------
      insert into netuney_tik_mechushavim n
        (n.odef_sherut_chodashim,
         n.odef_sherut_yamim,
         code_department,
         achuz_kizba_nechut,
         achuz_kizba_chelkiyut_melea,
         achuz_kizba_kafuf_chelkiyut,
         odef_sherut_yamim,
         seq_netuney_tik_mechushavim,
         seq_bakasha,
         --code_sug_prisha,
         chelkiut_lefi_nechut,
         achuz_kizba_sofi,
         --chelkiut_lkitzba,
         is_zakai_lmaanak,
         --is_zakai_lkitzba,
         --chelkiut_lefi_sherut,
         --chelkiut_lmaanak,
         --kitzba_bchelkiut_nechut,
         -- kitzba_lefi_medina_vhisht,
         kitzba_medina_hisht_meshukll,
         date_start_zakaut,
         -- schum_maanak,
         tkufa_mezaka_sherut,
         ahuz_kizb_achry_hagdl_kaf_chel
         --achuz_kizba_kafuf_chelkiyut
         
         -- n.achuz_kizba_kafuf_chelkiyut= pORESH.Hok_Kitzba_Lefi_Medina_Only
        ,
         CHELKIYUT_MESHUKLELET_SHERUT)
      values
        (r.odef_sherut_chodashim,
         r.odef_shert_yamim,
         2,
         r.hok_kitzba_lefi_nechut,
         v_achuz_kizba_chelkiyut_melea,
         r.hok_kitzba_lefi_medina_only,
         r.pizuy_odef_shanim_days,
         netuney_tik_mechushavim_seq.nextval,
         v_seq_bakasha,
         --,
         r.hok_helk_lefi_nechut,
         r.hok_achuz_kitzba_sofi,
         -- r.hok_helk_lkitzba,
         v_is_zakai_lmaanak,
         -- v_is_zakai_lkitzba,
         --r.hok_helk_lefi_years,
         -- r.hok_helk_lmaanak,
         -- r.hok_kitzba_bhelkiut_nechut,
         --  r.hok_kitzba_lefi_medina_vhisht,
         r.hok_medina_vhisht_meshuklal,
         r.date_start_zakaut,
         -- r.schum_maanak,
         r.Hok_Sach_Months_Mezakim,
         r.hok_kitzba_lefi_medina_only,
         r.hok_helk_lefi_years) log errors into err_netuney_tik_mechushavim
        (v_ora_err_tag$) reject limit unlimited;
    end loop;
  end;
  ----------------------------------------------------------------
  procedure update_decisions is
    v_is_hand_decision  number;
    v_is_hachlata_sofit number;
    v_is_zakai_lmaanak  number;
    --v_date_start_zakahut date;
  begin
    v_date_start_zakahut := null;
    for r in (select n1.seq_netuney_tik_mechushavim,
                     t.date_decision,
                     t.kd_decision,
                     t.achuz_kitzba,
                     t.helkiut,
                     t.date_start,
                     t.hok_is_zakai_lmaanak,
                     t.hok_sach_months_mezakim,
                     t.pizuy_odef_shanim_months,
                     t.helkiut_lefi_orech_sherut,
                     t.helkiut_lefi_nechut
                from tg_system.tg_p_decision t
                left join v_bakasha v
                  on t.zehut = v.MISPAR_ZEHUT
                left join netuney_tik_mechushavim n1
                  on v.SEQ_BAKASHA = n1.seq_bakasha
                 and n1.code_department in (1, 2)
              
               where V.SEQ_BAKASHA = v_seq_bakasha ---הוספתי תתנאי 
                 and t.nosaf = 0
                 and t.zehut = v_id
                 and t.date_decision =
                     (select max(d.date_decision)
                        from tg_system.tg_p_decision d
                       where t.nosaf = d.nosaf
                         and t.zehut = d.zehut)) loop
      --לאתחל את התאריך לראשון לחודש
      v_date_start_zakahut := r.date_start + INTERVAL '1' DAY;
      if (to_char(v_date_start_zakahut, 'DD') = '01') then
        v_date_start_zakahut := v_date_start_zakahut - INTERVAL '1' MONTH;
      else
        v_date_start_zakahut := r.date_start;
      end if;
      -- ADD_DAYS(r.date_start, 1);
    
      v_is_hachlata_sofit := case (trim(r.kd_decision))
                               when 2 then
                                0
                               else
                                1
                             end;
    
      if (V_CHELKIYUT_MESHUKLELET is null or V_CHELKIYUT_MESHUKLELET = 0) then
        v_chelkiyut_meshuklelet := r.helkiut_lefi_orech_sherut;
      end if;
    
      v_is_zakai_lmaanak := convert_0_or_1_number(r.hok_is_zakai_lmaanak);
    
      update netuney_tik_mechushavim n
         set n.date_update       = r.date_decision,
             n.is_hachlata_sofit = v_is_hachlata_sofit,
             n.achuz_kizba_sofi  = r.achuz_kitzba
             --,
             --n.chelkiyut_sofit   = if (r.helkiut is null or r.helkiut = 0 then n.chelkiyut_sofit;
             --else r.helkiut;
             --end if;
             --)
            ,
             -- n.date_end_zakaut   = r.date_start,
             --מכאן אני הוספתי
             n.is_zakai_lmaanak             = v_is_zakai_lmaanak,
             n.tkufa_mezaka_sherut          = r.hok_sach_months_mezakim,
             n.odef_sherut_chodashim        = r.pizuy_odef_shanim_months,
             n.chelkiyut_lefi_sherut        = round(r.helkiut_lefi_orech_sherut,
                                                    2),
             n.chelkiyut_meshuklelet_sherut = V_CHELKIYUT_MESHUKLELET,
             n.chelkiut_lefi_nechut         = r.helkiut_lefi_nechut,
             n.date_start_zakaut            = v_date_start_zakahut,
             n.code_group_prisha            = v_CODE_GROUP_PRISHA,
             n.Chelkiyut_Sofit              = r.helkiut
      
       where n.seq_netuney_tik_mechushavim = r.seq_netuney_tik_mechushavim;
    
    end loop;
  end;
  ----------------------------------------------------------------
  procedure update_relative_decisions is
    v_code_decision         number;
    v_achuz_kizba           number;
    v_code_sug_maanak       number;
    v_code_letter           number;
    v_achuz_maanak_o_kitzba number;
  begin
    for rd in (select
               --b.seq_bney_mishpacha,
               --p.seq_bakasha,
                t.date_decision,
                t.kd_decision,
                t.date_start_zakaut,
                t.achuz_maanak_o_kitzba,
                t.schum_maanak_o_kitzba,
                t.kd_sug_letter,
                t.kd_maanak_o_kitzba
               
                 from tg_system.tg_p_rel_history_decision t
               -- left join v_regila_last_status p
               --   on t.zehut = p.mispar_zehut
               -- left join bney_mishpacha b
               --    on p.SEQ_PORSHIM = b.seq_porshim
               --   and b.mispar_zehut_ben_mishpacha = t.zehut_rel
               
                where t.nosaf = 0
                  and t.zehut = v_id
               --and b.seq_bney_mishpacha is not null
               ) loop
    
      --dbms_output.put_line(' update_relative_decisions -ID: ' || v_id ||
      --                   'from date ' || to_char(sysdate, 'dd/mm/yyyy'));
      v_code_decision := convert_data_mgl_2_mpm_real3.convert_code_decision(trim(rd.kd_decision));
    
      begin
        v_achuz_kizba := to_number(rd.schum_maanak_o_kitzba);
      exception
        when others then
          v_achuz_kizba := null;
      end;
      begin
        v_code_sug_maanak := to_number(rd.kd_maanak_o_kitzba);
      exception
        when others then
          v_code_sug_maanak := null;
      end;
      begin
        v_code_letter := to_number(rd.kd_sug_letter);
      exception
        when others then
          v_code_letter := null;
      end;
    
      ------------------הוספתי--------------
    
      if to_number(trim(rd.kd_maanak_o_kitzba)) = 4 then
        update bney_mishpacha b
           set achuz_kizba = rd.achuz_maanak_o_kitzba
         where seq_porshim = v_porshim_seq;
      end if;
    
      update netuney_tik_mechushavim nt
         set nt.date_start_zakaut = rd.date_start_zakaut,
             nt.achuz_kizba_sofi  = rd.achuz_maanak_o_kitzba,
             nt.code_group_prisha = 4
       where nt.seq_bakasha = v_seq_bakasha;
    
    --date_bakasha     = bakasha_row.date_bakasha,
    --  code_source      = bakasha_row.code_source
    /* when not matched then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                    
                                                                    
                                                                                
                                                                                        
                                                                                                                                                                                    
                                                                                                                                                                                        
                                                                                                                                                                                            
                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    insert
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                    
                                                                    
                                                                                
                                                                                        
                                                                                                                                                                                    
                                                                                                                                                                                        
                                                                                                                                                                                            
                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      (seq_bakasha,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                    
                                                                    
                                                                                
                                                                                        
                                                                                                                                                                                    
                                                                                                                                                                                        
                                                                                                                                                                                            
                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       seq_prisha,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                    
                                                                    
                                                                                
                                                                                        
                                                                                                                                                                                    
                                                                                                                                                                                        
                                                                                                                                                                                            
                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
