  -------------------------------------------------------------
  procedure update_actions_log(date_haavara_hash  date,
                               is_histatfoot_lguf boolean) is
    dateAction date;
  begin
    if (v_Max_Date_Decision > date_haavara_hash) then
      dateAction := v_Max_Date_Decision;
    else
      dateAction := date_haavara_hash;
    end if;
    dbms_output.enable(999999999);
    dbms_output.put_line(v_id);
    if (v_DATE_NASHAM_6 is not null) then
      pk_prm_utils.insert_action_log_row(6,
                                         v_DATE_NASHAM_6,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha,
                                         null);
    
    end if;
  
    if (v_DATE_NASHAM_7 is not null) then
      pk_prm_utils.insert_action_log_row(7,
                                         v_DATE_NASHAM_7,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha,
                                         null);
    end if;
  
    --add action log row: conversion ('hasava').
    pk_prm_utils.insert_action_log_row(99,
                                       sysdate,
                                       null,
                                       null,
                                       null,
                                       null,
                                       null,
                                       null,
                                       v_seq_bakasha,
                                       null);
    --add action log row: transfer to malam ('avar le malam').
    if (v_sug_bakasha = 1) then
      pk_prm_utils.insert_action_log_row(22,
                                         date_haavara_hash,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha,
                                         null);
    end if;
  
    if (is_histatfoot_lguf) then
      pk_prm_utils.insert_action_log_row(36,
                                         v_Max_Date_Decision,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha,
                                         null);
    else
    
      pk_prm_utils.insert_action_log_row(103,
                                         v_Max_Date_Decision,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha,
                                         null);
    end if;
    pk_prm_utils.insert_action_log_row(98,
                                       date_haavara_hash,
                                       null,
                                       null,
                                       null,
                                       null,
                                       null,
                                       null,
                                       v_seq_bakasha,
                                       null);
    if (v_CODE_SEIF_PRISHA in (171, 117, 317, 92) and
       v_date_start_zakahut > sysdate) then
      --ממתין לגיל פרישה תקנוני
      pk_prm_utils.insert_action_log_row(132,
                                         date_haavara_hash,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha,
                                         null);
    end if;
  end;
  ----------------------------------------------------------
  function get_erorr_from_table(p_table varchar2) return clob is
    v_report clob := null;
  begin
    if pk_load_mimshak.count_rowes(p_table, v_where) > 0 then
      v_report := '<h4>' || p_table || ' count ' ||
                  pk_load_mimshak.count_rowes(p_table, v_where) || '.' ||
                  '<h4/>' || chr(10);
      v_report := v_report ||
                  pk_load_mimshak.create_sql_clob_format_html(p_table,
                                                              v_where);
    end if;
    return v_report;
  end;
  ----------------------------------------------------------
  function info_about_errors_and_commit(v_do_commit boolean,
                                        P_ErrrMesg  varchar2) return clob is
    v_report       clob := null;
    v_is_do_commit number;
  begin
    --add to the report info about the error tables.
    v_report := get_erorr_from_table('err_porshim');
    v_report := v_report || get_erorr_from_table('err_prisha');
    v_report := v_report || get_erorr_from_table('err_bakasha');
    v_report := v_report || get_erorr_from_table('err_bakasha_regila');
    v_report := v_report ||
                get_erorr_from_table('err_tkufot_avoda_mechushv');
    v_report := v_report || get_erorr_from_table('err_medical_vaada');
    v_report := v_report || get_erorr_from_table('err_apotropus');
    v_report := v_report || get_erorr_from_table('err_bney_mishpacha');
    v_report := v_report || get_erorr_from_table('err_decisions');
    v_report := v_report || get_erorr_from_table('err_participation');
    v_report := v_report ||
                get_erorr_from_table('err_netuney_tik_mechushavim');
    v_report := v_report || get_erorr_from_table('err_hagdala_nimuk');
    v_report := v_report || get_erorr_from_table('err_action_log');
  
    if v_do_commit = false then
      rollback;
      --   --------not (v_is_exist_tkufot_avoda)
      if (v_is_NOT_VALID_ID) then
        v_report := '<h2>' || '********** zeut: ' || v_id || ' **********' ||
                    '<h2/>' || '<h3>' ||
                    'Was not converted .Not Valid id  ' || '<h3/>' ||
                    chr(13) || chr(10) || v_report;
      
        add_row_to_mgl_log_hasava(v_id, 2, 'Not Valid id' || P_ErrrMesg);
      else
        v_report := '<h2>' || '********** zeut: ' || v_id || ' **********' ||
                    '<h2/>' || '<h3>' || 'Was not converted. ' || '<h3/>' ||
                    chr(13) || chr(10) || v_report;
        if (v_max_date_action >= v_Max_Date_Decision or
           v_date_bakasha > v_Max_Date_Decision or 1 = 2) then
          add_row_to_mgl_log_hasava(v_id,
                                    8,
                                    P_ErrrMesg || 'MGL:' ||
                                    to_date(v_Max_Date_Decision,
                                            'dd/MM/YYYY') || 'MPM:' ||
                                    to_date(v_max_date_action, 'DD/MM/YYYY') ||
                                    'date bakasha: ' ||
                                    to_date(v_date_bakasha, 'DD/MM/YYYY'));
        else
          add_row_to_mgl_log_hasava(v_id,
                                    7,
                                    P_ErrrMesg || 'MGL:' ||
                                    to_date(v_Max_Date_Decision,
                                            'dd/MM/YYYY') || 'MPM:' ||
                                    to_date(v_max_date_action, 'DD/MM/YYYY') ||
                                    'date bakasha: ' ||
                                    to_date(v_date_bakasha, 'DD/MM/YYYY'));
        end if;
      
      end if;
      commit;
      --   ----------
    elsif v_do_commit = true then
      commit;
      v_report := '<h2>' || '********** zeut: ' || v_id || ' **********' ||
                  '<h2/>' || '<h3>' || 'Converted. ' || '<h3/>' || chr(13) ||
                  chr(10) || v_report;
    end if;
  
    v_is_do_commit := case v_do_commit
                        when true then
                         1
                        else
                         0
                      end;
  
    insert into temp_convert_2_mpm
      (id, is_do_commit)
    values
      (v_id, v_is_do_commit);
  
    return v_report;
  
  end;
  --------------------------------------------------

  function validate_id(sug_zihuy number, v_id number) return boolean is
    type num_arr_type is table of number;
    mask_arr num_arr_type := num_arr_type(1, 2, 1, 2, 1, 2, 1, 2, 1);
    j        number;
    k        number := 0;
  begin
    if sug_zihuy = 2 -- darkon
     then
      return False;
    elsif sug_zihuy = 1 -- mispar zeut
     then
      for i in 1 .. 8 loop
        j := mask_arr(i) *
             to_number(substr(lpad(to_char(v_id), 9, '0'), i, 1));
        k := k + case length(to_char(j))
               when 1 then
                j
               else
                to_number(substr(to_char(j), 1, 1)) +
                to_number(substr(to_char(j), 2, 1))
             end;
      end loop;
      k                 := case mod(k, 10)
                             when 0 then
                              0
                             else
                              10 - mod(k, 10)
                           end;
      v_is_NOT_VALID_ID := False;
      if k <> to_number(substr(lpad(to_char(v_id), 9, '0'), 9, 1)) then
        -- not valid id 
        v_is_NOT_VALID_ID := true;
        /*add_row_to_err_porshim(v_id || '-' || 'not valid id',
        20000,
        'mispar_zehut');*/
        -- add_row_to_mgl_log_hasava(v_id, 2);
        -- dbms_output.put_line('NOT_VALID_ID' || v_id);
        -- raise_application_error(-20000, 'not valid id');
        return False;
      end if;
    end if;
    return true;
  end;
  --------------------------------------------------
  procedure update_HEAROT_TO_ACTION_LOG is
  
    v_code_user number;
  begin
    for rr in (select *
                 from (select
                       -- v.SEQ_BAKASHA,
                        t.index_heara,
                        t.date_heara,
                        t.teur_heara,
                        t.User_Last_Idkun
                         from tg_system.tg_P_HEAROT t
                       --left join v_bakasha v
                       --  on t.zehut = v.MISPAR_ZEHUT
                        where t.zehut = v_id
                          and t.nosaf = 0
                        order by nvl(t.date_heara,
                                     to_date('01010001', 'ddmmyyyy')),
                                 t.index_heara asc)
               --where rownum = 1
               ) loop
      v_code_user := convert_code_USER(convert_low_hebrew_to_ascii(rr.user_last_idkun));
      pk_prm_utils.insert_action_log_row(31,
                                         rr.date_heara,
                                         v_code_user,
                                         null,
                                         convert_low_hebrew_to_ascii(rr.teur_heara),
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha,
                                         null);
    end loop;
  end;

