  function main return clob is
    v_report_html    clob;
    v_is_do_commit   boolean;
    v_delete_bakasha varchar2(1000);
    v_is_tam         boolean;
  
  begin
  
    /*     for r in (select * from bakasha b where b.seq_prisha ) loop
      v_delete_bakasha := pk_prm_utils.delete_bakasha(r.seq_bakasha);
    end loop;*/
  
    execute immediate 'alter session set nls_language= ''american''';
    execute immediate 'alter session set nls_date_language=''english''';
    execute immediate 'alter session set nls_date_format=''dd-mon-yyyy''';
    -- execute immediate 'update netuney_tik_mechushavim a set a.code_department = 1 where a.code_department is null';
    -- execute immediate 'delete from netuney_tik_mechushavim a where a.code_department = 2';
  
    --truncate 'err' tables
    /*  execute immediate 'truncate table err_medical_vaada';
    execute immediate 'truncate table err_apotropus';
    execute immediate 'truncate table err_bney_mishpacha';
    execute immediate 'truncate table err_decisions';
    execute immediate 'truncate table err_participation';
    execute immediate 'truncate table err_netuney_tik_mechushavim';
    execute immediate 'truncate table err_tkufot_avoda_mechushv';
    execute immediate 'truncate table err_bakasha_regila';
    execute immediate 'truncate table err_hagdala_nimuk';
    execute immediate 'truncate table err_bakasha';
    execute immediate 'truncate table err_prisha';
    execute immediate 'truncate table err_porshim';
    execute immediate 'truncate table err_darga_vederug_tik';*/
    --execute immediate 'truncate table err_action_log';
    -- execute immediate 'truncate table err_tkufot_sikum';
    -- execute immediate 'truncate table mgl_log_hasava';
  
    --regular bakashot
    /**/
    for r in (select p.zehut,
                     p.date_gzira,
                     p.date_haavara_hash,
                     p.kd_misrad,
                     p.kd_yehida,
                     p.mis_gimla
                from tg_system.tg_poresh p
               where p.nosaf = 0
                 and p.zehut in (55978563, 56816051)
              /*and p.zehut in (select po.mispar_zehut from poresh po)
              and (select max(br.taarich_chatimat_tofes)
                     from v_Bakasha_Last_Status b
                     left join bakasha_regila br
                       on br.Seq_Bakasha = b.seq_bakasha
                    where b.mispar_zehut = p.zehut) is null
              and exists (select h.mispar_zehut
                     from mgl_log_hasava h
                    where h.mispar_zehut = p.zehut
                      and h.code_hasava = 8)*/
              --and rowNUM < 10
               order by p.zehut) loop
      begin
        --------------
        ResetFields;
        v_is_do_commit := true;
        v_date_gzira   := r.date_gzira;
        v_id           := r.zehut;
        v_mis_gimla    := trim(r.mis_gimla);
        --v_ezor_ovdim   :=
        SET_Ezor_Ovdim(r.kd_misrad, r.kd_yehida);
        v_ora_err_tag$ := to_char(v_id) || ' - ' ||
                          to_char(v_date_gzira, 'dd/mm/yyyy');
        v_where        := ' where ora_err_tag$= ''' || v_ora_err_tag$ || '''';
      
        v_is_exist_tkufot_avoda := false;
        if validate_id(1, r.zehut) = false then
          v_is_do_commit := false;
          goto endloop;
        end if;
      
        v_is_exist_participation_2_guf := is_exist_participation_l_guf;
        v_is_exist_participation_M_guf := is_exist_participation_m_guf;
        if (v_is_exist_participation_2_guf = true) then
          v_sug_bakasha := 8;
          SetMaxdateDecision;
          SETMaxDateActionLogForAction(36);
          if (v_Max_Date_Decision is not null
             /*and
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_Max_Date_Decision > trunc(v_max_date_action) and
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_Max_Date_Decision > v_date_bakasha*/
             ) then
          
            --השתתפות לגוף
            if ((v_seq_bakashaMaxDate is not null and
               not (delete_bakasha(v_seq_bakashaMaxDate) like ('%done!%'))) or
               update_bakasha(v_sug_bakasha) = false or
               update_bakasha_regila = false) then
            
              v_is_do_commit := false;
              goto endloop;
            else
              if (v_CODE_GROUP_PRISHA = 4) then
                update_bney_mishpaha;
              
              end if;
              V_CHELKIYUT_MESHUKLELET := null;
              update_netuney_tik_mechushavim;
              update_decisions;
              update_relative_decisions;
              update_hagdala_nimuk;
              update_vaada_ref;
            
              update_HEAROT_TO_ACTION_LOG;
              v_is_tam := update_tkufot_avoda_mehushv;
              update_participation_l_guf;
              update_actions_log(r.date_haavara_hash,
                                 v_is_exist_participation_2_guf);
              v_is_exist_participation_m_guf := false;
              update_participation_m_guf;
              update_DERUG;
              --add row log succses
              add_row_to_mgl_log_hasava(v_id,
                                        10,
                                        'MGL:' || v_Max_Date_Decision ||
                                        ' MPM:' || v_max_date_action);
            end if;
          else
            --לא הוסב 
            --תאריך החלטה במפמ מעודען יותר או שתאריך החלטה במגל NULL
            v_is_do_commit := false;
            goto endloop;
          end if;
          -------------------סוף השתתפות לגוף
        ELSE
          if (v_is_exist_participation_M_guf) then
            -----------השתתפות מגוף
            v_sug_bakasha := 7;
            SetMaxdateDecision;
            SETMaxDateActionLogForAction(36);
          
            if (v_Max_Date_Decision is not null /* and
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_Max_Date_Decision > trunc(v_max_date_action) and
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 v_Max_Date_Decision > v_date_bakasha*/
               ) then
            
              /* if (v_seq_bakashaMaxDate is not null) then
                v_delete_bakasha := delete_bakasha(v_seq_bakashaMaxDate);
              end if;*/
            
              if ((v_seq_bakashaMaxDate is not null and not (delete_bakasha(v_seq_bakashaMaxDate) like
                  ('%done!%'))) or update_bakasha(v_sug_bakasha) = false or
                 update_bakasha_regila = false) then
                v_is_do_commit := false;
                goto endloop;
              else
                if (v_CODE_GROUP_PRISHA = 4) then
                  update_bney_mishpaha;
                
                end if;
                V_CHELKIYUT_MESHUKLELET := null;
                update_netuney_tik_mechushavim;
                update_decisions;
                update_relative_decisions;
                update_hagdala_nimuk;
                update_vaada_ref;
                update_actions_log(r.date_haavara_hash, true);
                update_HEAROT_TO_ACTION_LOG;
                v_is_tam := update_tkufot_avoda_mehushv;
                update_participation_l_guf;
                v_is_exist_participation_m_guf := false;
                update_participation_m_guf;
                update_DERUG;
                --add row log succses
              
                --לבדוק אם קיימת בקשה רגילה
                if (is_exist_bakasha_regila is null) then
                  if (update_bakasha(1) = false or
                     update_bakasha_regila = false) then
                    v_is_do_commit := false;
                    goto endloop;
                  else
                  
                    CREATE_NEW_DATA_BAKASHA(r.date_haavara_hash);
                  
                  end if;
                end if;
                --סוף הסבה השתתפות מגוף 
                add_row_to_mgl_log_hasava(v_id,
                                          10,
                                          'MGL:' || v_Max_Date_Decision ||
                                          ' MPM:' || v_max_date_action);
              
              end if;
            else
              --בכל מקרה צריך גם בקשה רגילה
              --לבדוק אם קיימת בקשה רגילה
              if (is_exist_bakasha_regila is null) then
                if (update_bakasha(1) = false or
                   update_bakasha_regila = false) then
                  v_is_do_commit := false;
                  goto endloop;
                else
                  /*  if (v_CODE_GROUP_PRISHA = 4) then
                    update_bney_mishpaha;
                  
                  end if;*/
                  CREATE_NEW_DATA_BAKASHA(r.date_haavara_hash);
                
                end if;
              else
                --------------
                --לא הוסב 
                --תאריך החלטה במפמ מעודען יותר או שתאריך החלטה במגל NULL
                v_is_do_commit := false;
                goto endloop;
              end if;
            end if;
          else
            ------------מסוג בקשה רגילה          
            v_sug_bakasha := 1;
            SetMaxdateDecision;
            SETMaxDateActionLogForAction(12);
            if (v_Max_Date_Decision is not null /*and
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_Max_Date_Decision > v_max_date_action and
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_Max_Date_Decision > v_date_bakasha*/
               ) then
              /*            if (v_seq_bakashaMaxDate is not null) then
                v_delete_bakasha := delete_bakasha(v_seq_bakashaMaxDate);
              end if;*/
            
              ---------
              if ((v_seq_bakashaMaxDate is not null and not (delete_bakasha(v_seq_bakashaMaxDate) like
                  ('%done!%'))) or update_bakasha(v_sug_bakasha) = false or
                 update_bakasha_regila = false) then
              
                v_is_do_commit := false;
                goto endloop;
              else
                if (v_CODE_GROUP_PRISHA = 4) then
                  update_bney_mishpaha;
                
                end if;
                V_CHELKIYUT_MESHUKLELET := null;
                update_netuney_tik_mechushavim;
                update_decisions;
                update_relative_decisions;
                update_hagdala_nimuk;
                update_vaada_ref;
                update_actions_log(r.date_haavara_hash,
                                   v_is_exist_participation_2_guf);
                update_HEAROT_TO_ACTION_LOG;
                v_is_tam := update_tkufot_avoda_mehushv;
                update_participation_l_guf;
                v_is_exist_participation_m_guf := false;
                update_participation_m_guf;
                update_DERUG;
                add_row_to_mgl_log_hasava(v_id,
                                          10,
                                          'MGL:' || v_Max_Date_Decision ||
                                          ' MPM:' || v_max_date_action);
              
                --בכל מקרה צריך גם בקשה רגילה
                --לבדוק אם קיימת בקשה רגילה
                if (is_exist_bakasha_regila is null) then
                  if (update_bakasha(1) = false or
                     update_bakasha_regila = false) then
                    v_is_do_commit := false;
                    goto endloop;
                  else
                  
                    CREATE_NEW_DATA_BAKASHA(r.date_haavara_hash);
                  
                  end if;
                end if;
              
              end if;
              ----------
            else
              -------------אם לא קיימת בקשה רגילה , יש להוסיפה עם סיק בקשה קטן יותר בכל מקרה
            
              if (is_exist_bakasha_regila is null) then
                if (update_bakasha(1) = false or
                   update_bakasha_regila = false) then
                  v_is_do_commit := false;
                  goto endloop;
                else
                
                  CREATE_NEW_DATA_BAKASHA(r.date_haavara_hash);
                
                end if;
              else
                --*
              
                ---------------רשומה שלא הוסב
                --לא הוסב 
                --תאריך החלטה במפמ מעודען יותר או שתאריך החלטה במגל NULL
                v_is_do_commit := false;
                goto endloop;
              end if; --*
            end if;
          
          end if;
        
        end if;
      
        --במקרה שמספר גמלה במפמ ריק יש לעדכן ממגל
        if (v_seq_prisha is not null and
           (v_mis_gimla_MPM is null or v_mis_gimla_MPM = 0)) then
          update_mis_gimla;
        end if;
      
        <<endloop>>
        v_report_html := v_report_html ||
                        
                         info_about_errors_and_commit(v_is_do_commit, '');
      
        /*exception
          when
          others         then dbms_output.put_line('ERRROR' || v_id || sqlerrm);
          v_is_do_commit := false;
          v_report_html  := v_report_html ||
                           
                            info_about_errors_and_commit(v_is_do_commit, sqlerrm);
        
        end;*/
      
      exception
        when others then
          dbms_output.put_line('ERRROR' || v_id || sqlerrm);
          v_is_do_commit := false;
          v_report_html  := v_report_html ||
                           
                            info_about_errors_and_commit(v_is_do_commit,
                                                         sqlerrm);
        
      end;
    
    end loop;
  
    commit;
    return v_report_html;
  
  end;

----------------------------------------------------------
end;
/

create or replace package body prm_system_copy.convert_data_mgl_2_mpm_real4 is
  --שארים פנסיונים
  -----------------------------------------------------------
  /*--run on tg
      grant select on tg_poresh to PRM_HASAVOT_MAGAL;
      grant select on tg_p_tkufot_online to PRM_HASAVOT_MAGAL;
