      grant select on tg_p_decision to PRM_HASAVOT_MAGAL;
      grant select on tg_p_rel_history_decision to PRM_HASAVOT_MAGAL;    
      grant select on tg_p_retzifut_l_guf to PRM_HASAVOT_MAGAL;
        grant select on tg_p_retzifut_m_guf to PRM_HASAVOT_MAGAL;
          grant select on tg_p_tkufat_hasherut to PRM_HASAVOT_MAGAL;
            grant select on tg_p_hagdalot to PRM_HASAVOT_MAGAL;
            grant select on tg_gimla_number to PRM_HASAVOT_MAGAL;
            grant insert on tg_gimla_number to PRM_HASAVOT_MAGAL;
            -- Grant/Revoke object privileges 
    grant SELECT on TG_K_GUFIM to PRM_HASAVOT_MAGAL;
    -- Grant/Revoke object privileges 
    grant select on TG_K_MISRAD to prm_hasavot_magal;
    -- Grant/Revoke object privileges 
    grant select on TG_P_AVODA_MEDINA to prm_hasavot_magal;
    -- Grant/Revoke object privileges 
    grant select on TG_P_SHERUT_KODEM to prm_hasavot_magal;
    -- Grant/Revoke object privileges 
    grant select on TG_P_ARAIM to prm_hasavot_magal;
    -- Grant/Revoke object privileges 
    grant insert on TG_P_TKUFOT_ONLINE to PRM_HASAVOT_MAGAL;
    grant select on tg_P_HEAROT to PRM_HASAVOT_MAGAL ;
    -- Grant/Revoke object privileges 
  grant select on TG_P_LETTER to PRM_HASAVOT_MAGAL;
  
    
    */
  ----------------------------------------------------
  --  CREATE OR REPLACE TYPE num_nt  as table of number
  -----------------------------------------------------------
  v_id           number;
  v_ezor_ovdim   number;
  v_date_gzira   date;
  v_porshim_seq  number;
  v_seq_prisha   number;
  v_seq_bakasha  number;
  v_ora_err_tag$ varchar2(100);
  v_where        varchar2(100);
  --if_exist_participation_M_guf need to create additional bakasha
  v_is_exist_participation_M_guf boolean;
  v_is_exist_tkufot_avoda        boolean;
  v_CODE_GROUP_PRISHA            number;
  v_is_exist_participation_2_guf boolean;
  V_CHELKIYUT_MESHUKLELET        number;
  v_is_NOT_VALID_ID              boolean;
  v_sach_chodashim               number;

  v_CODE_SEIF_PRISHA          number;
  v_date_start_zakahut        date;
  v_isWithoutDateHahavaraHash boolean;
  v_dateLetter                date;
  --------------------------------------------------
  procedure set_seq_bakasha(v_code_sug_bakasha number) is
  begin
    begin
      select t.seq_bakasha
        into v_seq_bakasha
        from bakasha t
       where t.seq_prisha = v_seq_prisha
         and t.code_sug_bakasha = v_code_sug_bakasha;
    exception
      when no_data_found then
        v_seq_bakasha := bakasha_seq.nextval;
    end;
  end;
  ------------------------------------------
  procedure set_date_letter is
  begin
    begin
      select max(l.date_letter)
        into v_dateLetter
        from tg_SYSTEM.tg_p_letter l
       where l.zehut = v_ID
         and l.nosaf = 0;
    exception
      when no_data_found then
        v_dateLetter := null;
    end;
  end;
  --------------------------------------------------
  procedure set_CODE_GROUP_PRISHA(v_code_seif number) is
  begin
    begin
      select t.code_group_prisha
        into v_CODE_GROUP_PRISHA
        from code_seif_prisha t
       where t.code_seif_prisha = v_code_seif
         and ROWNUM = 1;
    exception
      when no_data_found then
        v_CODE_GROUP_PRISHA := null;
    end;
  end;
  -------------------------------------------------

  procedure DELETE_CONVERTED_DATA is
    v_delete_bakasha varchar2(1000);
  
  begin
    dbms_output.enable(999999999);
    -- for r in (
  
    /* select h.mispar_zehut
         from mgl_log_hasava h
        where
       --h.update_date > =
       --    to_date('03102018 17:00', 'ddmmyyyy hh24:mi') and 
