    and rownum <= 10
       /*(select h.mispar_zehut
        from mgl_log_hasava h
       where h.code_hasava = 1
         and rownum <= 220
          or h.mispar_zehut = 5920988)*/
    --(5920988)
    --) loop
    --and l.mispar_zehut in (11, 670315)) loop
  
    /*      for r2 in (select *
                   from V_BAKASHA_LAST_STATUS bl
                  where bl.mispar_zehut = r.mispar_zehut) loop
      
        v_delete_bakasha := pk_prm_utils.delete_bakasha(r2.seq_bakasha);
        delete from MGL_LOG_HASAVA m
         where m.mispar_zehut = r2.mispar_zehut;
      end loop;
    end loop;*/
  
    -- not in (select p.mispar_zehut from PORESH p);
    -- v_delete_bakasha := pk_prm_utils.delete_bakasha(146928);
    --commit;
  
    for r in (select distinct b.seq_bakasha,
                              b.date_start_zakaut,
                              b.mispar_zehut,
                              l.code_hasava
                from v_bakasha_last_status b
                left join mgl_log_hasava l
                  on l.mispar_zehut = b.mispar_zehut
