  ------------------------------

  procedure DELETE_BAKASHA_2GUF_PENSYONY is
    v_delete_bakasha varchar2(1000);
  
  begin
    dbms_output.enable(999999999);
    for r in (
              
              select b.mispar_zehut, min(b.seq_bakasha) as seq_bakasha
                from v_bakasha_last_status b
                left join mgl_log_hasava h
                  on h.mispar_zehut = b.mispar_zehut
               where h.code_hasava = 11
                 and b.code_sug_bakasha = 8
               group by b.mispar_zehut) loop
    
      dbms_output.put_line(r.mispar_zehut);
      dbms_output.put_line('BAKASHA ' || r.seq_bakasha);
      v_delete_bakasha := pk_prm_utils.delete_bakasha(r.seq_bakasha);
    
    end loop;
    commit;
  end;

  --------------------------------
  procedure DELETE_BAKASHA_PENSYONY is
    v_delete_bakasha varchar2(1000);
  
  begin
    dbms_output.enable(999999999);
    for r in (
              
              /*select distinct b.mispar_zehut, l.code_hasava
                                                                                                                                                                                                                                                                                                        from v_bakasha_last_status b
                                                                                                                                                                                                                                                                                                        left join mgl_log_hasava l
                                                                                                                                                                                                                                                                                                          on l.mispar_zehut = b.mispar_zehut
                                                                                                                                                                                                                                                                                                        left join netuney_tik_mechushavim nt
                                                                                                                                                                                                                                                                                                          on nt.Seq_Bakasha = b.seq_bakasha
                                                                                                                                                                                                                                                                                                       where b.code_sug_bakasha = 13
                                                                                                                                                                                                                                                                                                         and nt.achuz_kizba_sofi = 40
                                                                                                                                                                                                                                                                                                         and l.code_hasava = 11*/
              select distinct b.mispar_zehut, l.code_hasava
                from v_bakasha_last_status b
                left join mgl_log_hasava l
                  on l.mispar_zehut = b.mispar_zehut
                left join netuney_tik_mechushavim nt
                  on nt.Seq_Bakasha = b.seq_bakasha
                left join bney_mishpacha bm
                  on bm.Seq_Porshim = b.seq_porshim
                 and bm.code_relative = 1
               where b.code_sug_bakasha = 13
                 and bm.Achuz_Kizba = 40
                 and l.code_hasava = 11) loop
    
      for r2 in (select *
                   from V_BAKASHA_LAST_STATUS bl
                  where bl.mispar_zehut = r.mispar_zehut
                    and bl.code_sug_bakasha = 13) loop
        dbms_output.put_line(r.mispar_zehut);
        dbms_output.put_line('BAKASHA ' || r2.seq_bakasha);
        v_delete_bakasha := pk_prm_utils.delete_bakasha(r2.seq_bakasha);
        /*delete from MGL_LOG_HASAVA m
        where m.mispar_zehut = r2.mispar_zehut;*/
      end loop;
    end loop;
    commit;
  end;

  --------------------------------------
  procedure UPDATE_NETUNEY_TIK_PENSYONY is
    v_delete_bakasha varchar2(1000);
  
  begin
    dbms_output.enable(999999999);
    for r in (
              
              select distinct b.mispar_zehut, l.code_hasava, b.seq_bakasha
                from v_bakasha_last_status b
                left join mgl_log_hasava l
                  on l.mispar_zehut = b.mispar_zehut
                left join netuney_tik_mechushavim nt
                  on nt.Seq_Bakasha = b.seq_bakasha
               where b.code_sug_bakasha = 1
                 and b.code_seif_prisha = 126
                 and nt.Code_Group_Prisha = 4
                 and (nt.Achuz_Kizba_Sofi is null or nt.Achuz_Kizba_Sofi = 0)
                 and l.code_hasava = 11) loop
    
      dbms_output.put_line(r.mispar_zehut);
      dbms_output.put_line('BAKASHA ' || r.seq_bakasha);
      update NETUNEY_TIK_MECHUSHAVIM nt
         set nt.code_group_prisha = null,
             nt.date_start_zakaut = null,
             nt.Chelkiyut_Sofit   = null,
             nt.is_zakai_lmaanak  = null
       where nt.Seq_Bakasha = r.seq_bakasha;
    
    end loop;
    commit;
  end;

  -------------------------------------------------
  procedure validate_MZ is
  
  begin
    dbms_output.enable(999999999);
    for r in (select distinct l.mispar_zehut as zehut
                from MGL_LOG_HASAVA l
              
              /*for r in (select p.zehut from tg_system.tg_poresh p*/
              
              ) loop
      if (validate_id(1, r.zehut) = false) then
        /*update MGL_LOG_HASAVA lh
          set lh.code_hasava = 2
        where lh.mispar_zehut = r.zehut
          and lh.code_hasava <> 1;*/
        dbms_output.put_line(r.zehut);
      end if;
    end loop;
  
    commit;
  end;

  -------------------------------------------------
  procedure FILL_DATA_TG_P_TKUFOT_ONLINE is
  
  begin
    dbms_output.enable(999999999);
  
    for r in (select p.zehut
                from tg_system.tg_poresh p
              
               where not exists (select tao.zehut
                        from tg_system.tg_p_tkufot_online tao
                       where tao.zehut = p.zehut)
                 and p.nosaf = 0
              --and p.zehut not in (select po.mispar_zehut from poresh po)
               order by p.zehut) loop
      begin
        --dbms_output.put_line(r.zehut);
        FILL_TA_FROM_AVODA_MEDINA(r.zehut);
        FILL_TA_FROM_SHERUT_KODEM(r.zehut);
        FILL_TA_FROM_ARAIM(r.zehut);
      
      exception
        when others then
          dbms_output.put_line('ERROR ' || r.zehut || sqlerrm);
      end;
      commit;
    end loop;
  
  end;

  ------------------------------------
  procedure FILL_TA_FROM_AVODA_MEDINA(p_mis_zheut number) is
  
  begin
    insert into tg_system.TG_P_TKUFOT_ONLINE
      (ZEHUT,
       NOSAF,
       DATE_START,
       DATE_END,
       KD_TKUFA,
       KD_ZCHUYOT,
       SUG_SHURA,
       HELKIUT,
       LEMAET_TKUFA,
       IS_TOOK_MONEY_M_KEREN,
       KD_TAKANON,
       KD_TAFKID_MEYUHAD,
       was_a_prime_minister,
       BASIS_GIMLA)
      select ZEHUT,
             NOSAF,
             DATE_START,
             DATE_END,
             KD_TKUFA,
             KD_ZCHUYOT,
             'ע',
             HELKIUT,
             LEMAET_TKUFA,
             IS_TOOK_MONEY_M_KEREN,
             KD_TAKANON,
             KD_TAFKID_MEYUHAD,
             was_a_prime_minister,
             BASIS_GIMLA
        from tg_SYSTEM.TG_P_AVODA_MEDINA
       where ZEHUT = p_mis_zheut
         and NOSAF = 0;
  
  end;
  ---------------------------------------------------

  procedure FILL_TA_FROM_SHERUT_KODEM(p_mis_zheut number) is
  
  begin
  
    insert into tg_SYSTEM.TG_P_TKUFOT_ONLINE
      (ZEHUT,
       NOSAF,
       DATE_START,
       DATE_END,
       KD_TKUFA,
       KD_ZCHUYOT,
       SUG_SHURA,
       HELKIUT,
       IS_ISHUR_TZERUF_SK,
       LEMAET_TKUFA,
       IS_TOOK_MONEY_M_KEREN,
       KD_TAKANON,
       KD_TAFKID_MEYUHAD,
       basis_gimla)
      select ZEHUT,
             NOSAF,
             DATE_START,
             DATE_END,
             KD_TKUFA,
             KD_ZCHUYOT,
             'ש',
             HELKIUT,
             IS_ISHUR_TZERUF_SK,
             LEMAET_TKUFA,
             IS_TOOK_MONEY_M_KEREN,
             KD_TAKANON,
             KD_TAFKID_MEYUHAD,
             basis_gimla
        from tg_SYSTEM.TG_P_SHERUT_KODEM
       where ZEHUT = p_mis_zheut
         and NOSAF = 0;
  
  end;

  -------------------------------------------------

  procedure FILL_TA_FROM_ARAIM(p_mis_zheut number) is
  
  begin
  
    insert into tg_SYSTEM.TG_P_TKUFOT_ONLINE
      (ZEHUT,
       NOSAF,
       DATE_START,
       DATE_END,
       KD_TKUFA,
       KD_ZCHUYOT,
       SUG_SHURA,
       HELKIUT,
       LEMAET_TKUFA,
       IS_TOOK_MONEY_M_KEREN,
       KD_TAKANON,
       IS_KANA_ZCHUYOT,
       IS_WANT_TO_MOVE_MONEY,
       IS_PENSION_RIGHTS,
       IS_ISHUR_GET_MONEY,
       IS_ISHUR_SHARED_PENSION,
       HOK_IS_INCLUD_IN_HISHUV,
       KD_TAFKID_MEYUHAD,
       basis_gimla)
      select ZEHUT,
             NOSAF,
             DATE_START,
             DATE_END,
             KD_TKUFA,
             KD_ZCHUYOT,
             'א',
             HELKIUT,
             LEMAET_TKUFA,
             IS_TOOK_MONEY_M_KEREN,
             KD_TAKANON,
             IS_KANA_ZCHUYOT,
             IS_WANT_TO_MOVE_MONEY,
             IS_PENSION_RIGHTS,
             IS_ISHUR_GET_MONEY,
             IS_ISHUR_SHARED_PENSION,
             HOK_IS_INCLUD_IN_HISHUV,
             KD_TAFKID_MEYUHAD,
             basis_gimla
        from tg_SYSTEM.TG_P_ARAIM
       where ZEHUT = p_mis_zheut
         and NOSAF = 0;
  
  end;
  -------------------------------
  function is_exist_Code_derug(p_KD_DERUG number) return boolean is
    v_is_exist_Code_derug boolean;
  begin
    if (nvl(p_KD_DERUG, 0) > 0) then
      v_is_exist_Code_derug := false;
      for r in (select t.code_derug
                  from CODE_DERUG t
                 where t.code_derug = p_KD_DERUG) loop
        v_is_exist_Code_derug := true;
        return true;
      end loop;
    end if;
    return false;
  end;

  -------------------------

  procedure update_DERUG is
  
    v_code_derug number;
  begin
  
    for r in (select p.date_darga, p.kd_derug, p.teur_tafkid, p.kd_misrad
                from tg_system.tg_poresh p
               where p.zehut = v_id
                 and p.nosaf = 0) loop
    
      if r.kd_misrad = 210 or r.kd_misrad = 250 then
        v_code_derug := 41;
      else
        -- לבדוק אם הקוד דירוג קיים
        if (is_exist_Code_derug(to_number(trim(r.kd_derug)))) then
          v_code_derug := r.kd_derug;
        end if;
      end if;
    
      merge into Darga_Vederug_Tik derug
      using dual
      on (derug.SEQ_BAKASHA = v_seq_bakasha)
      when matched then
        update set TAARICH_ME = r.date_darga, code_derug = v_code_derug
      when not matched then
        insert
          (SEQ_DARGOT_VEDERUG_TIK, SEQ_BAKASHA, TAARICH_ME, code_derug)
        values
          (DARGA_VEDERUG_TIK_SEQ.nextval,
           v_seq_bakasha,
           r.date_darga,
           v_code_derug) log errors into err_darga_vederug_tik
          (v_ora_err_tag$) reject limit unlimited;
    end loop;
  
  end;

  -------------------------
  function UpdateMonths(p_taarich_me date, p_taarich_ad date) return number is
  begin
    begin
      select months_between(p_taarich_ad + 1, p_taarich_me)
        into v_sach_chodashim
        from dual t;
    
    exception
      when OTHERS then
        v_sach_chodashim := null;
    end;
    return trunc(v_sach_chodashim, 2);
  
  end;
  ---------------------------------------------------------
  procedure add_row_to_err_porshim(err_mesg   varchar2,
                                   err_number number,
                                   field_name varchar2) is
    err_porshim_row err_porshim%rowtype;
  begin
    --    err_porshim_row := err_porshim_r;
  
    err_porshim_row.ora_err_number$ := err_number;
    --    if err_mesg is not null then
    err_porshim_row.ora_err_mesg$ := field_name || ': ' || err_mesg;
    --else
    --   err_porshim_row.ora_err_mesg$ := get_message_according_code(info_type,
    --                                                             err_number,
    --                                                           field_name);
    -- end if;
  
    --הכנסת הערה לטבלת הERR
    insert into err_porshim values err_porshim_row;
    -- (v_ora_err_tag$) reject limit unlimited;
  
  end;
  ----------------------------------------

  function convert_code_RELATIVE(var char) return number is
  begin
    return case when var = '01' then 1 when var = '02' then 1 when var = '03' then 5 when var = '04' then 5 when var = '05' then 2 when var = '06' then 3 when var = '07' then 3 when var = '08' then 4 when var = '09' then 4 else null
    
    end;
  end;

  --------------------------------------------------

  function convert_code_USER(var char) return number is
    v_id_user number;
  
  begin
    return case when var = 'אביתר פינטו' then 170 when var = 'אירית צייגר' then 119 when var = 'אנאל ענת כהן' then 255 when var = 'בר ברדה' then 141 when var = 'ג''והאנה סטרווייס' then 140 when var = 'גיטה דוידוב' then 133 when var = 'דבאח מאיסאא' then 295 when var = 'חגית קליין' then 137 when var = 'חנה אדרי' then 132 when var = 'יקיר כהן' then 258 when var = 'מיכל אולו' then 136 when var = 'מעיין אביב' then 175 when var = 'מרים מלמד' then 160 when var = 'משי גנון' then 149 when var = 'מתי עצור' then 116 when var = 'נאוה כהן' then 131 when var = 'ניסים ביבי' then 117 when var = 'נעמה באואר' then 130 when var = 'ראובן יששכר' then 139 when var = 'רות בן-חיים' then 157 when var = 'רות טולדאנו' then 127 when var = 'סימונה ציסמריו' then 118 when var = 'ספיר פרץ' then 142 when var = 'עמיר כץ' then 153 when var = 'פסי ציסמריו' then 144 when var = 'שי ואזנה' then 151 when var = 'שני פסטמן' then 126 else null
    
    end;
  
    /*begin
    
      select u.id_user
        into v_id_user
        from code_user u
       where replace(u.shem_prati || ' ' || u.shem_mishpacha, ' ') =
             replace(convert_low_hebrew_to_ascii(trim(var)), '')
         and rownum = 1;
    
      return v_id_user;
    exception
      when no_data_found then
        return null;*/
  
  end;

  --------------------------------------------------
  procedure add_row_to_mgl_log_hasava(mispar_zehut number,
                                      code_hasava  number,
                                      p_ErrMess    varchar2) is
    log_hasava_row mgl_log_hasava%rowtype;
  begin
  
    log_hasava_row.mispar_zehut := mispar_zehut;
    log_hasava_row.code_hasava  := code_hasava;
    log_hasava_row.update_date  := sysdate;
    log_hasava_row.remarks      := p_ErrMess;
  
    insert into mgl_log_hasava values log_hasava_row;
  
  end;

  --------------------------------------------------

  function get_create_apotropus(v_apotr_name   varchar2,
                                v_apotr_adress varchar2,
                                mikud          varchar2,
                                v_apotr_city   number) return number is
    v_apotropus_seq number;
  begin
    if (v_apotr_name is not null) then
      begin
        --if apotropus is exist, return his seq.
        select a.apotropus_seq
          into v_apotropus_seq
          from apotropus a
         where replace(a.name, ' ') = replace(v_apotr_name, ' ')
           and replace(a.address, ' ') = replace(v_apotr_adress, ' ');
      
        return v_apotropus_seq;
      exception
        when no_data_found then
          v_apotropus_seq := apotropus_seq.nextval;
          --insert new row to apotropus table.
          insert into apotropus
            (apotropus_seq, name, address, zone, code_city)
          values
            (v_apotropus_seq,
             v_apotr_name,
             v_apotr_adress,
             mikud,
             v_apotr_city) log errors into err_apotropus reject limit unlimited;
        
          return v_apotropus_seq;
      end;
    else
      --if apotropus name is null, return null.
      return null;
    end if;
  end;
  -------------------------------------------------------------
  function get_mpm_code_source(v_kd_misrad_ varchar2, v_kd_makor_ varchar2)
    return number is
    v_kd_misrad varchar2(100);
    v_kd_makor  varchar2(100);
  begin
    v_kd_misrad := trim(v_kd_misrad_);
    v_kd_makor  := trim(v_kd_makor_);
    return case when v_kd_makor = '03' and v_kd_misrad = '210' or v_kd_misrad = '250' then 3 when v_kd_makor = '03' and v_kd_misrad <> '210' and v_kd_misrad <> '250' then 1 when v_kd_makor = '04' then 4 when v_kd_makor = '10' then 5 else null end;
  
  end get_mpm_code_source;
