  function convert_code_kirva(var char, min_ number) return number is
  begin
    return case when var = '01' then 3 when var = '02' then 3 when var = '03' then 1 when var = '04' then 1 when var = '05' then 10 when var = '06' then 10 when var = '07' then 14 when var = '08' then 14 when var = '11' then 2 when var = '12' then 22 when var = '13' then 21 when var = '14' then 23 when var = '21' then 2 when var = '22' then 22 when var = '23' then 21 when var = '24' then 23 when var = '31' and min_ = 1 then 11 when var = '31' and min_ = 2 then 12 when var = '32' then 7 when var = '33' then 7 when var = '41' then 9 when var = '42' then 9 else null
    
    end;
  end;
  -------------------------------------------------------------------------
  function convert_code_REL_kirva(var char) return number is
  begin
    return case when var = '132' then 1 when var = '163' then 1 when var = '190' then 1 when var = '213' then 2 when var = '214' then 2 when var = '241' then 2 when var = '253' then 2 when var = '254' then 2 when var = '255' then 2 when var = '281' then 2 when var = '113' then 1 when var = '123' then 1 when var = '141' then 1 when var = '163' then 1 when var = '291' then 14 when var = '281' then 2 else null
    
    end;
  end;
  ----------------------------------------------------------
  function convert_0_or_1_number(var number) return number is
  begin
    return case var when 1 then 1 else 0 end;
  end;
  ----------------------------------------------------------
  function convert_0_or_1(var varchar2) return number is
    v_var number;
  begin
    begin
      v_var := to_number(trim(var));
    exception
      when others then
        v_var := null;
    end;
  
    return convert_0_or_1_number(v_var);
  end;

