                    where bl.mispar_zehut = r.zehut) loop
          --22624 
          v_delete_bakasha := pk_prm_utils.delete_bakasha(r2.seq_bakasha);
        end loop;*/
        v_is_exist_tkufot_avoda := false;
        if validate_id(1, r.zehut) = false or
          --must tables
           update_poresh = false or update_prisha = false or
           update_bakasha(1) = false or update_bakasha_regila = false
        /*or(update_tkufot_avoda_mehushv = false or
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_is_exist_tkufot_avoda = false) */
         then
          v_is_do_commit := false;
          -- add_row_to_mgl_log_hasava(v_id, 3);
          goto endloop;
        end if;
      
        --add row log succses
        /* if (v_isWithoutDateHahavaraHash) then
        add_row_to_mgl_log_hasava(v_id, 9, '');*/
        --else
        add_row_to_mgl_log_hasava(v_id, 11, '');
        --end if;
      
        dbms_output.enable(999999999);
      
        --not must tables
      
        update_bney_mishpaha;
        V_CHELKIYUT_MESHUKLELET := null;
        update_netuney_tik_mechushavim;
      
        update_decisions;
        update_relative_decisions;
      
        update_hagdala_nimuk;
      
        update_vaada_ref;
      
        update_HEAROT_TO_ACTION_LOG;
      
        v_is_tam := update_tkufot_avoda_mehushv;
      
        --? pk_zakaut.main(v_seq_bakasha);
      
        --null;
        --הוספתי-------
      
        update_participation_l_guf;
        --העברתי לפה
        update_actions_log(r.date_haavara_hash,
                           v_is_exist_participation_2_guf);
        v_is_exist_participation_m_guf := false;
      
        update_participation_m_guf;
        update_DERUG;
        if (v_is_exist_participation_m_guf) then
          if (update_bakasha(7) and update_bakasha_regila) then
          
            update_netuney_tik_mechushavim;
            update_decisions;
            update_relative_decisions;
            update_hagdala_nimuk;
            update_vaada_ref;
            update_actions_log(r.date_haavara_hash, true);
            -- v_is_exist_participation_2_guf);
            update_HEAROT_TO_ACTION_LOG;
            v_is_tam := update_tkufot_avoda_mehushv;
            update_participation_l_guf;
            update_participation_m_guf;
            v_is_exist_participation_m_guf := false;
            update_DERUG;
          end if;
        end if;
        --הקמת בקשת שאר פנסיוני
        if (update_bakasha(13) and update_bakasha_regila) then
          update_netuney_tik_mechushavim;
          update_decisions;
          update_relative_decisions;
          update_hagdala_nimuk;
          update_vaada_ref;
          update_actions_log(r.date_haavara_hash, true);
          -- v_is_exist_participation_2_guf);
          update_HEAROT_TO_ACTION_LOG;
          v_is_tam := update_tkufot_avoda_mehushv;
          update_participation_l_guf;
          update_participation_m_guf;
          v_is_exist_participation_m_guf := false;
          update_DERUG;
        end if;
      
        <<endloop>>
        v_report_html := v_report_html ||
                        
                         info_about_errors_and_commit(v_is_do_commit, '');
      
      exception
        when others then
          dbms_output.put_line('ERR' || v_id || sqlerrm);
          v_is_do_commit := false;
          v_report_html  := v_report_html ||
                           
                            info_about_errors_and_commit(v_is_do_commit,
                                                         sqlerrm);
        
      end;
    
    --commit;
    end loop;
    /**/
    --    DELETE_CONVERTED_DATA;
    commit;
    return v_report_html;
  
  end;

----------------------------------------------------------
end;
/

create or replace package body prm_system_copy.convert_data_mgl_2_mpm_real5 is

  -----------------------------------------------------------
  /*--run on tg
