  ---------------------
  procedure INSERT_DOCUMENT_bakashot is
    v_update_bakasha varchar2(1000);
  
  begin
    dbms_output.enable(999999999);
    for r in (select *
                from PRM_SYSTEM_TMP.document_bakasha db
                left join v_bakasha_last_status b
                  on b.seq_bakasha = db.seq_bakasha
               where db.seq_document_bakasha not in
                     (select d.seq_document_bakasha from document_bakasha d)
                 and db.Seq_Bakasha in
                     (select b2.seq_bakasha from v_bakasha_last_status b2)) loop
    
      INSERT INTO document_bakasha
        (seq_document_bakasha, seq_document, seq_bakasha, pail)
        SELECT seq_document_bakasha, seq_document, seq_bakasha, pail
          FROM PRM_SYSTEM_TMP.document_bakasha a
         WHERE a.seq_document_bakasha = r.seq_document_bakasha;
      dbms_output.put_line('SUCSSES ' || r.mispar_zehut);
    end loop;
    commit;
  end;
  --------------------------------------
  procedure UPdate_GUF_PARTIFICATION is
  begin
    for r in (select ceo.Seq_Ezor_Ovdim AS Seq_Ezor_Ovdim_NEW,
                     p.seq_participation,
                     b.mispar_zehut,
                     p.Seq_Guf,
                     g.kod,
                     eo. code_ezor_ovdim,
                     convert_low_hebrew_to_ascii(g.Teur),
                     eo.teur_ezor_ovdim,
                     ceo.teur_ezor_ovdim as teur_ezor_ovdim_new
                from participation p
                left join v_bakasha_last_status b
                  on b.seq_bakasha = p.seq_bakasha
                left join mgl_log_hasava l
                  on l.mispar_zehut = b.mispar_zehut
                left join code_ezor_ovdim eo
                  on eo.seq_ezor_ovdim = p.seq_guf
              
                left join tg_system.tg_k_gufim g
                  on trim(g.kod) = eo.code_ezor_ovdim
                left join code_ezor_ovdim ceo
                  on ceo.teur_ezor_ovdim =
                     convert_low_hebrew_to_ascii(g.teur)
                    --את התנאי הקרוב להוריד בשביל האוניברסיטה י-ם
                 and ceo.code_ezor_ovdim = eo.code_ezor_ovdim
               where --l.mispar_zehut = 7941388
               l.code_hasava in --(6,10)
               (1, 6, 9, 11, 10)
           and convert_low_hebrew_to_ascii(g.teur) <>
               trim(eo.teur_ezor_ovdim)
           and (select count(e.code_makor)
                  from Code_Ezor_Ovdim e
                 where e.code_ezor_ovdim = eo.code_ezor_ovdim
                 group by e.code_ezor_ovdim) > 1
           and b.code_sug_bakasha in (1, 7, 8)
              --(7, 8)
              --שווה בשביל האוניברסיטה העברית
           and p.seq_guf <> 23) loop
    
      update participation p
         set p.Seq_Guf = r.seq_ezor_ovdim_new
       where p.seq_participation = r.seq_participation;
    end loop;
  end;

  -------------------------------------------------------
  procedure UPdate_CODE_SOURCE is
  begin
    for r in (select b.mispar_zehut,
                     b1.code_source,
                     b2.code_source as prev_code_source,
                     max(b.seq_bakasha) AS seq_bakasha
                from v_bakasha_last_status b
                left join mgl_log_hasava l
                  on l.mispar_zehut = b.mispar_zehut
                left join bakasha b1
                  on b1.seq_bakasha = b.seq_bakasha
                left join prm_system_tmp.bakasha b2
                  on b2.seq_bakasha = b.seq_bakasha
               where b.code_sug_bakasha in (7, 8)
                 and b1.code_source <> b2.code_source
                 and l.code_hasava = 10
               group by b.mispar_zehut, b1.code_source, b2.code_source) loop
    
      UPDATE bakasha b
         set b.code_source = r.prev_code_source
       where b.seq_bakasha = r.seq_bakasha;
    end loop;
  
  end;
  -------------------
  procedure UPdate_bakashot is
    v_update_bakasha number;
  
  begin
    dbms_output.enable(999999999);
    for r in (
              /*      select b.mispar_zehut, max(b.seq_bakasha) AS seq_bakasha
                                                                                                                                                            from v_bakasha_last_status b
                                                                                                                                                            left join mgl_log_hasava l
                                                                                                                                                              on l.mispar_zehut = b.mispar_zehut
                                                                                                                                                           where b.code_sug_bakasha in (7, 8)
                                                                                                                                                             and l.code_hasava = 10
                                                                                                                                                             and b.seq_bakasha = 49704
                                                                                                                                                           group by b.mispar_zehut*/
              select l.code_hasava, b.seq_bakasha, b.mispar_zehut
                from v_bakasha_last_status b
                left join mgl_log_hasava l
                  on l.mispar_zehut = b.mispar_zehut
               where b.code_sug_bakasha = 3
                 and not exists (select *
                        from hagdala_nimuk h1
                       where h1.seq_bakasha = b.seq_bakasha)
                 and exists (select *
                        from mgl_log_hasava l
                       where l.mispar_zehut = b.mispar_zehut
                         and l.code_hasava in (1, 6, 10, 11, 9))
                 and l.code_hasava in (1, 6, 10, 11, 9)
              --and b.mispar_zehut = 51729465
              
              ) loop
      v_update_bakasha := UPDATE_bakasha_without_commit(r.seq_bakasha, '');
    
      if v_update_bakasha = 1 then
        dbms_output.put_line('SUCSSES ' || r.mispar_zehut);
        commit;
      
      else
        rollback;
        dbms_output.put_line('ERROR ' || r.mispar_zehut);
      
      end if;
    
    end loop;
  end;

  ---------------------------------------
  function UPDATE_bakasha_without_commit(p_seq_bakasha number,
                                         p_source_db   varchar2)
    return number is
    v_cnt_other_bakashot_fr_prisha number;
    v_cnt_other_prishot_for_poresh number;
    v_seq_prisha                   number;
    v_seq_poresh                   number;
    v_source_db                    varchar2(15);
  begin
    v_source_db := p_source_db;
    v_source_db := 'PRM_SYSTEM';
    select v.seq_prisha, v.seq_porshim
      into v_seq_prisha, v_seq_poresh
      from v_bakasha_last_status v
     where v.seq_bakasha = p_seq_bakasha;
  
    select count(*)
      into v_cnt_other_bakashot_fr_prisha
      from v_bakasha v
     where v.SEQ_PRISHA = v_seq_prisha
       and v.SEQ_BAKASHA <> p_seq_bakasha;
  
    select count(*)
      into v_cnt_other_prishot_for_poresh
      from v_bakasha_last_status v
     where v.seq_porshim = v_seq_poresh
       and v.seq_prisha <> v_seq_prisha;
  
    --delete from document_bakasha t11 where t11.seq_bakasha = p_seq_bakasha;
  
    delete from action_log t17 where t17.seq_bakasha = p_seq_bakasha;
    INSERT INTO action_log
      SELECT *
        FROM PRM_SYSTEM_TMP.action_log a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    -----
    delete from tikim_mukdemet_hachlatot t16
     where t16.seq_bakasha = p_seq_bakasha;
    INSERT INTO tikim_mukdemet_hachlatot
      SELECT *
        FROM PRM_SYSTEM_TMP.tikim_mukdemet_hachlatot a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete from tikim_mukdemet_misrot_lebitul t15
     where t15.seq_bakasha = p_seq_bakasha;
    INSERT INTO tikim_mukdemet_misrot_lebitul
      SELECT *
        FROM PRM_SYSTEM_TMP.tikim_mukdemet_misrot_lebitul a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete from bakasha_mukdemet t14 where t14.seq_bakasha = p_seq_bakasha;
  
    INSERT INTO bakasha_mukdemet
      SELECT *
        FROM PRM_SYSTEM_TMP.bakasha_mukdemet a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    -----
    delete from vetek_detail t23 where t23.seq_bakasha = p_seq_bakasha;
  
    INSERT INTO vetek_detail
      SELECT *
        FROM PRM_SYSTEM_TMP.vetek_detail a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete from chinuch_salary t24 where t24.seq_bakasha = p_seq_bakasha;
  
    INSERT INTO chinuch_salary
      SELECT *
        FROM PRM_SYSTEM_TMP.chinuch_salary a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete from darga_vederug_tik t13
     where t13.seq_bakasha = p_seq_bakasha;
  
    INSERT INTO darga_vederug_tik
      SELECT *
        FROM PRM_SYSTEM_TMP.darga_vederug_tik a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete from decisions t12 where t12.seq_bakasha = p_seq_bakasha;
    INSERT INTO decisions
      SELECT *
        FROM PRM_SYSTEM_TMP.decisions a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete from hagdala_nimuk t10 where t10.seq_bakasha = p_seq_bakasha;
  
    INSERT INTO hagdala_nimuk
      SELECT *
        FROM PRM_SYSTEM_TMP.hagdala_nimuk a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete from netuney_tik_mechushavim t9
     where t9.seq_bakasha = p_seq_bakasha;
    INSERT INTO netuney_tik_mechushavim
      SELECT *
        FROM PRM_SYSTEM_TMP.netuney_tik_mechushavim a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete from netuney_tik_mechushav_chnuch t19
     where t19.seq_bakasha = p_seq_bakasha;
    INSERT INTO netuney_tik_mechushav_chnuch
      SELECT *
        FROM PRM_SYSTEM_TMP.netuney_tik_mechushav_chnuch a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete from netuney_tik_meushar_ozar t8
     where t8.seq_bakasha = p_seq_bakasha;
  
    INSERT INTO netuney_tik_meushar_ozar
      SELECT *
        FROM PRM_SYSTEM_TMP.netuney_tik_meushar_ozar a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete participation_tkufot t19
     where t19.seq_participation in
           (select p.seq_participation
              from participation p
             where p.seq_bakasha = p_seq_bakasha);
  
    INSERT INTO participation_tkufot
      SELECT *
        FROM PRM_SYSTEM_TMP.participation_tkufot a
       WHERE a.Seq_Participation in
             (select p.seq_participation
                from PRM_SYSTEM_TMP.participation p
               where p.seq_bakasha = p_seq_bakasha);
  
    delete participation t7 where t7.seq_bakasha = p_seq_bakasha;
  
    INSERT INTO participation
      SELECT *
        FROM PRM_SYSTEM_TMP.participation a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete from tkufot_avoda_mechushv t5
     where t5.seq_bakasha = p_seq_bakasha;
  
    INSERT INTO tkufot_avoda_mechushv
      SELECT *
        FROM PRM_SYSTEM_TMP.tkufot_avoda_mechushv a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete from tkufot_avoda_golmi t6 where t6.seq_bakasha = p_seq_bakasha;
    INSERT INTO tkufot_avoda_golmi
      SELECT *
        FROM PRM_SYSTEM_TMP.tkufot_avoda_golmi a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete tkufot_michutz_lasharut t4 where t4.seq_bakasha = p_seq_bakasha;
  
    INSERT INTO tkufot_michutz_lasharut
      SELECT *
        FROM PRM_SYSTEM_TMP.tkufot_michutz_lasharut a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete from tkufot_sherut_tsvaii t3
     where t3.seq_bakasha = p_seq_bakasha;
  
    INSERT INTO tkufot_sherut_tsvaii
      SELECT *
        FROM PRM_SYSTEM_TMP.tkufot_sherut_tsvaii a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete from tkufot_sikum t2 where t2.seq_bakasha = p_seq_bakasha;
  
    INSERT INTO tkufot_sikum
      SELECT *
        FROM PRM_SYSTEM_TMP.tkufot_sikum a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    delete from bakasha_regila t1 where t1.seq_bakasha = p_seq_bakasha;
  
    INSERT INTO bakasha_regila
      SELECT *
        FROM PRM_SYSTEM_TMP.bakasha_regila a
       WHERE a.seq_bakasha = p_seq_bakasha;
  
    -----------------
    update ld_log t18
       set t18.seq_bakasha = null, t18.date_delete = sysdate
     where seq_bakasha = p_seq_bakasha;
    -----------------
    --delete from bakasha t where t.seq_bakasha = p_seq_bakasha;
  
    --If there is no other bakashot for the prisha
    --    if v_cnt_other_bakashot_fr_prisha = 0 then
    -- delete from porshim_achronim b where b.seq_prisha = v_seq_prisha;
    --  delete from prisha a where a.seq_prisha = v_seq_prisha;
  
    --If there is no other prishot for the poresh
    /* if v_cnt_other_prishot_for_poresh = 0 then
      delete from action_log where SEQ_PORESH = v_seq_poresh;
      delete from bney_mishpacha where SEQ_PORSHIM = v_seq_poresh;
      delete from medical_vaada where SEQ_PORESH = v_seq_poresh;
      delete from tashlum_guf where SEQ_PORESH = v_seq_poresh;
      delete from tashlum_guf_draft where SEQ_PORESH = v_seq_poresh;
      delete from poresh p where p.porshim_seq = v_seq_poresh;
    end if;*/
  
    --  end if;
  
    return 1;
  exception
    when others then
      return sqlcode;
  end;

