  procedure UPDATE_NETUNEY_TIK_PENSYONY is
    v_delete_bakasha varchar2(1000);
  
  begin
    dbms_output.enable(999999999);
    for r in (
              
              select distinct b.mispar_zehut, l.code_hasava, b.seq_bakasha
                from v_bakasha_last_status b
                left join mgl_log_hasava l
                  on l.mispar_zehut = b.mispar_zehut
                left join netuney_tik_mechushavim nt
                  on nt.Seq_Bakasha = b.seq_bakasha
               where b.code_sug_bakasha = 1
                 and b.code_seif_prisha = 126
                 and nt.Code_Group_Prisha = 4
                 and (nt.Achuz_Kizba_Sofi is null or nt.Achuz_Kizba_Sofi = 0)
                 and l.code_hasava = 11) loop
    
      dbms_output.put_line(r.mispar_zehut);
      dbms_output.put_line('BAKASHA ' || r.seq_bakasha);
      update NETUNEY_TIK_MECHUSHAVIM nt
         set nt.code_group_prisha = null,
             nt.date_start_zakaut = null,
             nt.Chelkiyut_Sofit   = null,
             nt.is_zakai_lmaanak  = null
       where nt.Seq_Bakasha = r.seq_bakasha;
    
    end loop;
    commit;
  end;

