  -------------------------------
  function convert_seq_ezor_ovdim(v_kd_misrad_  varchar,
                                  v_kd_yechida_ varchar) return number is
    v_kd_misrad  number;
    v_kd_yechida number;
  begin
    v_kd_misrad  := to_number(trim(v_kd_misrad_));
    v_kd_yechida := to_number(trim(v_kd_yechida_));
    if (v_kd_misrad_ = 137) then
