  function convert_KD_GUF_seq_ezor_ovdim(v_kd_misrad_ varchar) return number is
    v_kd_misrad      number;
    v_SEQ_ezor_ovdim number;
  
  begin
    v_kd_misrad := to_number(trim(v_kd_misrad_));
  
    select e.seq_ezor_ovdim
      into v_SEQ_ezor_ovdim
      from Code_Ezor_Ovdim e
     where e.code_ezor_ovdim = v_kd_misrad
       and rownum = 1;
    return v_SEQ_ezor_ovdim;
  exception
    when no_data_found then
      return 999;
    
  end;
