  function convert_code_seif_prisha(v_kd_sibat_prisha_ varchar) return number is
    v_kd_sibat_prisha number;
  begin
    v_kd_sibat_prisha := to_number(v_kd_sibat_prisha_);
    return case when v_kd_sibat_prisha = 15 then 126 when v_kd_sibat_prisha = 115 then 415 when v_kd_sibat_prisha = 218 then 118 when v_kd_sibat_prisha = 415 then 415 when v_kd_sibat_prisha = 117 then 117 when v_kd_sibat_prisha = 118 then 118 when v_kd_sibat_prisha = 126 then 126 when v_kd_sibat_prisha = 128 then 128 when v_kd_sibat_prisha = 138 then 138 when v_kd_sibat_prisha = 162 then 162 when v_kd_sibat_prisha = 171 then 171 when v_kd_sibat_prisha = 215 then 215 when v_kd_sibat_prisha = 217 then 217 when v_kd_sibat_prisha = 226 then 226 when v_kd_sibat_prisha = 228 then 228 when v_kd_sibat_prisha = 315 then 315 when v_kd_sibat_prisha = 317 then 317 when v_kd_sibat_prisha = 326 then 326 when v_kd_sibat_prisha = 328 then 328 when v_kd_sibat_prisha = 92 then 92 when v_kd_sibat_prisha = 426 then 426 when v_kd_sibat_prisha = 428 then 428 when v_kd_sibat_prisha = 526 then 526 when v_kd_sibat_prisha = 528 then 528 when v_kd_sibat_prisha = 417 then 92 when v_kd_sibat_prisha = 815 then 415 when v_kd_sibat_prisha = 915 then 415 when v_kd_sibat_prisha = 990 then 990
    
    else null end;
  end;
