  --------------------------------------------------
  function main return clob is
    v_report_html    clob;
    v_is_do_commit   boolean;
    v_delete_bakasha varchar2(1000);
    v_is_tam         boolean;
  
  begin
  
    /*     for r in (select * from bakasha b where b.seq_prisha ) loop
      v_delete_bakasha := pk_prm_utils.delete_bakasha(r.seq_bakasha);
    end loop;*/
  
    execute immediate 'alter session set nls_language= ''american''';
    execute immediate 'alter session set nls_date_language=''english''';
    execute immediate 'alter session set nls_date_format=''dd-mon-yyyy''';
    -- execute immediate 'update netuney_tik_mechushavim a set a.code_department = 1 where a.code_department is null';
    -- execute immediate 'delete from netuney_tik_mechushavim a where a.code_department = 2';
  
    --truncate 'err' tables
    /* execute immediate 'truncate table err_medical_vaada';
    execute immediate 'truncate table err_apotropus';
    execute immediate 'truncate table err_bney_mishpacha';
    execute immediate 'truncate table err_decisions';
    execute immediate 'truncate table err_participation';
    execute immediate 'truncate table err_netuney_tik_mechushavim';
    execute immediate 'truncate table err_tkufot_avoda_mechushv';
    execute immediate 'truncate table err_bakasha_regila';
    execute immediate 'truncate table err_hagdala_nimuk';
    execute immediate 'truncate table err_bakasha';
    execute immediate 'truncate table err_prisha';
    execute immediate 'truncate table err_porshim';
    execute immediate 'truncate table err_action_log';
    execute immediate 'truncate table err_tkufot_sikum';
    -- execute immediate 'truncate table mgl_log_hasava';*/
  
    --regular bakashot
    /**/
    for r in (select p.zehut,
                     p.date_gzira,
                     p.date_haavara_hash,
                     p.kd_misrad,
                     p.kd_yehida,
                     p.mis_gimla
                from tg_system.tg_poresh p
              
               where p.date_haavara_hash is null
                 and exists (select l.kod_sug_letter
                        from tg_system.tg_p_letter l
                       where l.zehut = p.zehut)
                 and p.nosaf = 0
                 and p.date_ptira is not null
                 and not exists
               (select d.*
                        from tg_SYSTEM.Tg_p_Decision d
                       where d.zehut = p.zehut
                         and d.nosaf = 0)
                 and p.zehut not in (select po.mispar_zehut from poresh po)
                 and p.zehut not in
                     (select h.mispar_zehut from mgl_log_hasava h)
              --and rowNum < 100
               order by p.zehut
              
              )
    
     loop
      begin
        --------------
      
        v_is_do_commit := true;
        v_date_gzira   := r.date_gzira;
        v_id           := r.zehut;
        v_ezor_ovdim   := convert_seq_ezor_ovdim(r.kd_misrad,
                                                 TRIM(r.kd_yehida));
        v_ora_err_tag$ := to_char(v_id) || ' - ' ||
                          to_char(v_date_gzira, 'dd/mm/yyyy');
        v_where        := ' where ora_err_tag$= ''' || v_ora_err_tag$ || '''';
      
        --delete table 'bakasha'
        /* for r2 in (select *
                     from V_BAKASHA_LAST_STATUS bl
                    where bl.mispar_zehut = r.zehut) loop
          --22624 
          v_delete_bakasha := pk_prm_utils.delete_bakasha(r2.seq_bakasha);
        end loop;*/
        v_is_exist_tkufot_avoda := false;
        if validate_id(1, r.zehut) = false or
          --must tables
           update_poresh = false or update_prisha = false or
           update_bakasha(1) = false or update_bakasha_regila = false
        /*or(update_tkufot_avoda_mehushv = false or
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_is_exist_tkufot_avoda = false) */
         then
          v_is_do_commit := false;
          -- add_row_to_mgl_log_hasava(v_id, 3);
          goto endloop;
        end if;
      
        --add row log succses
        /* if (v_isWithoutDateHahavaraHash) then
        add_row_to_mgl_log_hasava(v_id, 9, '');*/
        --else
        add_row_to_mgl_log_hasava(v_id, 11, '');
        --end if;
      
        dbms_output.enable(999999999);
      
        --not must tables
      
        update_bney_mishpaha;
        V_CHELKIYUT_MESHUKLELET := null;
        update_netuney_tik_mechushavim;
      
        update_decisions;
        update_relative_decisions;
      
        update_hagdala_nimuk;
      
        update_vaada_ref;
      
        update_HEAROT_TO_ACTION_LOG;
      
        v_is_tam := update_tkufot_avoda_mehushv;
      
        --? pk_zakaut.main(v_seq_bakasha);
      
        --null;
        --הוספתי-------
      
        update_participation_l_guf;
        --העברתי לפה
        update_actions_log(r.date_haavara_hash,
                           v_is_exist_participation_2_guf);
        v_is_exist_participation_m_guf := false;
      
        update_participation_m_guf;
        update_DERUG;
        if (v_is_exist_participation_m_guf) then
          if (update_bakasha(7) and update_bakasha_regila) then
          
            update_netuney_tik_mechushavim;
            update_decisions;
            update_relative_decisions;
            update_hagdala_nimuk;
            update_vaada_ref;
            update_actions_log(r.date_haavara_hash, true);
            -- v_is_exist_participation_2_guf);
            update_HEAROT_TO_ACTION_LOG;
            v_is_tam := update_tkufot_avoda_mehushv;
            update_participation_l_guf;
            update_participation_m_guf;
            v_is_exist_participation_m_guf := false;
            update_DERUG;
          end if;
        end if;
        --הקמת בקשת שאר פנסיוני
        if (update_bakasha(13) and update_bakasha_regila) then
          update_netuney_tik_mechushavim;
          update_decisions;
          update_relative_decisions;
          update_hagdala_nimuk;
          update_vaada_ref;
          update_actions_log(r.date_haavara_hash, true);
          -- v_is_exist_participation_2_guf);
          update_HEAROT_TO_ACTION_LOG;
          v_is_tam := update_tkufot_avoda_mehushv;
          update_participation_l_guf;
          update_participation_m_guf;
          v_is_exist_participation_m_guf := false;
          update_DERUG;
        end if;
      
        <<endloop>>
        v_report_html := v_report_html ||
                        
                         info_about_errors_and_commit(v_is_do_commit, '');
      
      exception
        when others then
          dbms_output.put_line('ERR' || v_id || sqlerrm);
          v_is_do_commit := false;
          v_report_html  := v_report_html ||
                           
                            info_about_errors_and_commit(v_is_do_commit,
                                                         sqlerrm);
        
      end;
    
    --commit;
    end loop;
    /**/
    --    DELETE_CONVERTED_DATA;
    commit;
    return v_report_html;
  
  end;

----------------------------------------------------------
end;
