  procedure update_DERUG is
  
    v_code_derug number;
  begin
  
    for r in (select distinct m17.identity_number,
                              m17.rank,
                              m17.rate,
                              m17.from_date,
                              m17.to_date
                from ld_mlm_17 m17
               where m17.is_erased = 0
                 and m17.identity_number = v_id) loop
    
      /*      merge into Darga_Vederug_Tik derug
      using dual
      on (derug.SEQ_BAKASHA = v_seq_bakasha)
      when matched then
        update
           set TAARICH_ME = r.from_date,
               code_derug = r.rate,
               code_darga = r.rank,
               TAARICH_AD = R.TO_DATE
      when not matched then*/
      insert into Darga_Vederug_Tik
        (SEQ_DARGOT_VEDERUG_TIK,
         SEQ_BAKASHA,
         TAARICH_ME,
         TAARICH_AD,
         code_derug,
         code_darga)
      values
        (DARGA_VEDERUG_TIK_SEQ.nextval,
         v_seq_bakasha,
         to_DATE(r.from_date, 'dd/mm/yyyy'),
         to_DATE(R.TO_DATE, 'dd/mm/yyyy'),
         R.RATE,
         r.rank) log errors into err_darga_vederug_tik
        (v_ora_err_tag$) reject limit unlimited;
    end loop;
  
  end;

  -------------------------
  function UpdateMonths(p_taarich_me date, p_taarich_ad date) return number is
  begin
    begin
      select months_between(p_taarich_ad + 1, p_taarich_me)
        into v_sach_chodashim
        from dual t;
    
    exception
      when OTHERS then
        v_sach_chodashim := null;
    end;
    return trunc(v_sach_chodashim, 2);
  
  end;
