    return case when v_kd_sibat_prisha in(0, 126) then 999 when v_kd_sibat_prisha = 15 then 126 when v_kd_sibat_prisha = 15 then 415 when v_kd_sibat_prisha = 218 then 118 when v_kd_sibat_prisha in(138,
                                                                                                                                                                                                     162,
                                                                                                                                                                                                     628,
                                                                                                                                                                                                     815,
                                                                                                                                                                                                     915) then null else v_kd_sibat_prisha end;
  end;
