  procedure update_netuney_tik_mechushavim is
    v_achuz_kizba_chelkiyut_melea  number;
    v_code_sug_prisha              number;
    v_odef_sherut_yamim            number;
    v_is_zakai_lmaanak             number;
    v_is_zakai_lkitzba             number;
    V_CHELKIYUT_MESHUKLELET_SHERUT number;
    V_TKUFA_MEZAKA_SHERUT          number;
  begin
    for r in (select distinct ml10.identity_number,
                              ml10.date_start_payment,
                              
                              --m19.yearly_percentage,
                              m19.eligible_months,
                              m19.partiality,
                              (select sum(m16.pension_percentage)
                                 from ld_mlm_16 m16
                                where m16.is_erased = 0
                                  and m16.from_date =
                                      (select max(m16b.from_date)
                                         from ld_mlm_16 m16b
                                        where to_number(m16.reason_pension_changed) in
                                              (0, 2, 3, 5, 6, 13, 31, 32)
                                          and m16b.is_erased = 0
                                          and m16b.identity_number =
                                              m16.identity_number)
                                  and m16.identity_number =
                                      ml10.identity_number
                                group by m16.identity_number) as achuz_kizba,
                              
                              (select (m16c.pension_percentage)
                                 from ld_mlm_16 m16c
                                where m16c.is_erased = 0
                                  and m16c.reason_pension_changed = '00'
                                  and m16c.identity_number =
                                      ml10.identity_number
                                  and rownum = 1) as achuz_kizba_kafuf
                from ld_mlm_10 ml10
                left join ld_mlm_19 m19
                  on m19.identity_number = ml10.identity_number
                 and m19.is_erased = 0
                 and m19.job_number = ml10.job_number
               where ml10.job_number = v_job_number
                 and ml10.is_erased = 0
                 and ml10.identity_number = v_id
                    --'000', '126',
                 and ml10.retirement_section not in ('128')) loop
    
      V_CHELKIYUT_MESHUKLELET_SHERUT := r.partiality / 1000;
      if (V_CHELKIYUT_MESHUKLELET_SHERUT > 70) then
        V_CHELKIYUT_MESHUKLELET_SHERUT := 70;
      else
        if nvl(V_CHELKIYUT_MESHUKLELET_SHERUT, 0) = 0 then
          V_CHELKIYUT_MESHUKLELET_SHERUT := 1;
        end if;
      end if;
      V_TKUFA_MEZAKA_SHERUT := r.eligible_months / 100;
      insert into netuney_tik_mechushavim n
        (code_department,
         n.seq_netuney_tik_mechushavim,
         n.seq_bakasha,
         n.date_start_zakaut,
         n.achuz_kizba_sofi,
         n.achuz_kizba_kafuf_chelkiyut,
         n.CHELKIYUT_MESHUKLELET_SHERUT,
         n.TKUFA_MEZAKA_SHERUT,
         n.CODE_GROUP_PRISHA,
         n.ahuz_kizb_achry_hagdl_kaf_chel)
      values
        (1,
         netuney_tik_mechushavim_seq.nextval,
         v_seq_bakasha,
         to_date(r.date_start_payment, 'DD/MM/YYYY'),
         r.achuz_kizba,
         r.achuz_kizba_kafuf,
         V_CHELKIYUT_MESHUKLELET_SHERUT,
         V_TKUFA_MEZAKA_SHERUT,
         v_CODE_GROUP_PRISHA,
         r.achuz_kizba) log errors into err_netuney_tik_mechushavim
        (v_ora_err_tag$) reject limit unlimited;
    
      insert into netuney_tik_mechushavim n
        (code_department,
         n.seq_netuney_tik_mechushavim,
         n.seq_bakasha,
         n.date_start_zakaut,
         n.achuz_kizba_sofi,
         n.achuz_kizba_kafuf_chelkiyut,
         n.CHELKIYUT_MESHUKLELET_SHERUT,
         n.TKUFA_MEZAKA_SHERUT,
         n.CODE_GROUP_PRISHA,
         n.ahuz_kizb_achry_hagdl_kaf_chel)
      values
        (2,
         netuney_tik_mechushavim_seq.nextval,
         v_seq_bakasha,
         to_date(r.date_start_payment, 'DD/MM/YYYY'),
         r.achuz_kizba,
         r.achuz_kizba_kafuf,
         V_CHELKIYUT_MESHUKLELET_SHERUT,
         V_TKUFA_MEZAKA_SHERUT,
         v_CODE_GROUP_PRISHA,
         r.achuz_kizba) log errors into err_netuney_tik_mechushavim
        (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  end;

