  procedure update_participation_m_guf is
    v_is_transfer_agreement number;
    v_is_heskem_yachid      number;
    v_is_mevutach_beguf     number;
    v_seq_ezor_ovdim        number;
    V_percent_participate   number;
  begin
    for r in (select distinct m112.identity_number,
                              m112.institution_code,
                              m112.participation_percentage
                from ld_mlm_112 m112
               where m112.is_erased = 0
                 and m112.identity_number = v_id) loop
      v_is_exist_participation_M_guf := true;
    
      v_seq_ezor_ovdim := convert_KD_GUF_seq_ezor_ovdim(r.institution_code);
    
      V_percent_participate := trunc(r.participation_percentage / 100, 2);
      insert into participation p1
        (SEQ_BAKASHA,
         seq_participation,
         code_participation,
         seq_guf,
         percent_participate)
      values
        (v_seq_bakasha,
         participation_seq.nextval,
         2,
         v_seq_ezor_ovdim,
         V_percent_participate) log errors into err_participation
        (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  
  end;

  ---------------------------------------------------------
  procedure update_bney_mishpaha is
    v_seq_apotropus             number;
    v_is_get_bituach_leumi      number;
    v_is_baal_ishur_tzava       number;
    v_is_baal_tzav_imutz        number;
    v_is_oved                   number;
    v_is_study                  number;
    v_code_min                  number;
    v_code_relative             number;
    v_code_kirva                number;
    v_code_mazav_mishpachti     number;
    v_kd_sug_sheer              number;
    v_month_salary              number;
    v_is_hakira                 number;
    v_is_ishur_eino_oved        number;
    v_is_samuch_al_shulhan_ehad number;
    v_almana_hara               number;
    v_parent_of_common_child    number;
  
  begin
    delete from bney_mishpacha where seq_porshim = v_porshim_seq;
  
    for r in (select distinct m15.identity_number,
                              m15.family_identity_number,
                              m15.first_name,
                              m15.last_name,
                              m15.relation_code,
                              m15.birth_date,
                              m115.marriage_date
                from ld_mlm_15 m15
                left join ld_mlm_115 m115
                  on m115.identity_number = m15.family_identity_number
                 and m115.is_erased = 0
               where to_number(m15.family_identity_number) <> 0
                 and m15.is_erased = 0
                 and m15.identity_number = v_id) loop
    
      v_is_oved := case
                     when r.relation_code in (131, 190) then
                      1
                     else
                      0
                   end;
      v_code_kirva := case
                        when r.relation_code in (113, 131, 190, 191) then
                         1
                        when r.relation_code in (212, 213, 254, 261) then
                         2
                        when r.relation_code = 291 then
                         14
                      end;
      v_code_min := case
                      when r.relation_code in (113, 131) then
                       2
                      when r.relation_code in (190, 191) then
                       1
                    end;
      --יש לבדוק כשיש לאותו בנ"א כמה רשומות עם תאריך נישואין לבדוק מה לעשות...    
      insert into bney_mishpacha
        (seq_porshim,
         seq_bney_mishpacha,
         mispar_zehut_ben_mishpacha,
         shem_prati,
         shem_mishpacha,
         taarich_leda,
         haim_oved,
         code_kirva,
         code_min,
         TAARICH_NISUIN)
      values
        (v_porshim_seq,
         bney_mishpacha_seq.nextval,
         r.family_identity_number,
         r.first_name,
         r.last_name,
         to_date(r.birth_date, 'DD/MM/YYYY'),
         v_is_oved,
         v_code_kirva,
         v_code_min,
         to_date(r.marriage_date, 'dd/mm/yyyy')) log errors into err_bney_mishpacha
        (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  end;
  ---------------------------------------------------------

  procedure update_hagdala_nimuk is
    v_code_nimuk     number;
    v_achuz_meushar  number;
    v_meushar_natsiv number;
  begin
  
    delete from hagdala_nimuk t where t.seq_bakasha = v_seq_bakasha;
  
    for r in (select distinct m16.reason_pension_changed,
                              m16.pension_percentage,
                              m16.identity_number,
                              m16.from_date,
                              m16.to_date
                from LD_MLM_16 m16
               where m16.reason_pension_changed not in
                     ('00', '99', '07', '08', '09', '10', '11')
                 and m16.is_erased = 0
                 and m16.identity_number = v_id) loop
    
      v_code_nimuk := convert_code_nimuk(r.reason_pension_changed);
    
      if (r.pension_percentage > 999.99)
      
       then
        v_achuz_meushar := null;
      else
        v_achuz_meushar := trunc(r.pension_percentage, 2);
      end if;
    
      insert into hagdala_nimuk h
        (seq_bakasha,
         seq_hagdala_nimuk,
         CODE_NIMUK,
         achuz_meushar,
         me_taarich,
         AD_taarich)
      values
        (v_seq_bakasha,
         hagdala_nimuk_seq.nextval,
         v_code_nimuk,
         v_achuz_meushar,
         to_date(r.from_date, 'dd/mm/yyyy'),
         to_date(r.to_date, 'dd/mm/yyyy')) log errors into err_hagdala_nimuk
        (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  end;
  ---------------------------------------------
  procedure update_ADDRESS is
    v_code_address number;
  
  begin
  
    -- delete from hagdala_nimuk t where t.seq_bakasha = v_seq_bakasha;
  
    for r in (select distinct m14.identity_number,
                              m14.city_code,
                              m14.city_name,
                              m14.address,
                              m14.zone,
                              ci.code_ir          as city_code2,
                              ci.teur_ir          as city_name2
                from ld_mlm_14 m14
                left join code_ir ci
                  on trim(ci.teur_ir) = trim(m14.city_name)
               where m14.is_erased = 0
                 and m14.identity_number = v_id) loop
    
      if to_number(r.city_code) = 0
      
       then
        v_code_address := r.city_code2;
      else
        v_code_address := r.city_code;
      end if;
    
      insert into address
        (seq_bakasha,
         seq_address,
         seq_poresh,
         street,
         code_city,
         mikud,
         code_address)
      values
        (v_seq_bakasha,
         address_seq.nextval,
         v_porshim_seq,
         r.address,
         v_code_address,
         r.zone,
         2) log errors into err_address
        (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  end;
