  procedure update_GIMLAOT_KEFEL is
    v_code_address number;
    v_SEQ_guf      number;
  begin
  
    for r in (select distinct m211.pension_sum,
                              m211.pension_percentage,
                              m211.from_date,
                              m211.deductions_file
              
                from ld_mlm_211 m211
               where m211.is_erased = 0
                 and m211.identity_number = v_id) loop
      v_SEQ_guf := convert_deductions_file(r.deductions_file);
    
      insert into participation p
        (SEQ_BAKASHA,
         seq_participation,
         code_participation,
         seq_guf,
         percent_participate,
         p.SUM_PARTICIPATION,
         p.DATE_PAYMENT)
      values
        (v_seq_bakasha,
         participation_seq.nextval,
         6,
         v_SEQ_guf,
         r.pension_percentage,
         r.pension_sum,
         to_date(r.from_date, 'DD/MM/YYYY')) log errors into err_participation
        (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  
  end;
  ------------------------------------------

  function convert_deductions_file(v_deductions_file number) return number is
  
    v_SEQ_ezor_ovdim number;
  
  begin
    begin
      select c.seq_ezor_ovdim
        into v_SEQ_ezor_ovdim
        from CODE_EZOR_OVDIM c
       where c.deductions_file = v_deductions_file
         and ROWNUM = 1;
    exception
      when no_data_found then
        v_SEQ_ezor_ovdim := 999;
    end;
    return v_SEQ_ezor_ovdim;
  
  end;
