  procedure update_PRISHA_BANK_ACCOUNT is
  
  begin
  
    -- delete from BANK_ACCOUNT t where t.seq_prisha = v_seq_prisha;
  
    for r in (select distinct m22.identity_number,
                              m22.bank_branch,
                              substr(m22.bank_branch, 0, 2) as bank,
                              substr(m22.bank_branch, 3, 4) as snif,
                              m22.account_number,
                              m22.from_date
                from ld_mlm_22 m22
               where m22.is_erased = 0
                 and m22.identity_number = v_id) loop
      insert into BANK_ACCOUNT
        (seq_bakasha,
         --SEQ_PRISHA,
         SEQ_BANK_ACCOUNT,
         --SEQ_PORESH,
         CODE_BANK,
         CODE_SNIF,
         ACCOUNT_NUMBER,
         DATE_UPDATE)
      values
        (v_seq_bakasha,
         --v_seq_prisha,
         BANK_ACCOUNT_SEQ.nextval,
         -- v_porshim_seq,
         r.bank,
         r.snif,
         r.account_number,
         TO_DATE(r.from_date, 'dd/mm/yyyy')) log errors into Err_BANK_ACCOUNT
      /*
               declare 
        -- Local variables here
        i integer;
      begin
        -- Test statements here
        dbms_errlog.create_error_log('BANK_ACCOUNT','Err_BANK_ACCOUNT');
      end;
      
               */
        (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  end;
  -----------------------------------
  function is_RetirementSectionsOnlyOne return boolean is
  
    v_countRtirmentSctions number;
  begin
    v_is_RetirementSectionsMoreOne := false;
    select count(distinct m10.retirement_section)
      into v_countRtirmentSctions
      from ld_mlm_10 m10
     where m10.is_erased = 0
       and m10.job_number <> 9
          --'000', '126',
       and m10.retirement_section not in ('128')
       and m10.identity_number = v_id;
    if (v_countRtirmentSctions > 1) then
      v_is_RetirementSectionsMoreOne := true;
      return false;
    else
      return true;
    end if;
  end;
  -----------------------------------------------------------
  function update_bakasha(p_code_sug_bakasha number) return boolean is
    bakasha_row   err_bakasha%rowtype;
    v_sug_bakasha number;
  begin
    for r in (select distinct m10.retirement_section,
                              m10.identity_number,
                              m10.date_start_payment
                from ld_mlm_10 m10
               where m10.job_number = v_job_number
                 and m10.is_erased = 0
                    --'000', '126',
                 and m10.retirement_section not in ('128')
                 and m10.identity_number = v_id) loop
    
      if p_code_sug_bakasha = 1 AND
         trim(r.retirement_section) in (128, 228, 328, 428, 528, 628) then
        --שאר פנסיונר
        v_sug_bakasha := 13;
      else
        v_sug_bakasha := p_code_sug_bakasha;
      END IF;
      bakasha_row.date_bakasha     := to_date(r.date_start_payment,
                                              'DD/MM/YYYY');
      bakasha_row.code_sug_bakasha := v_sug_bakasha;
    
      set_seq_bakasha(v_sug_bakasha);
      v_date_start_zakahut := to_date(r.date_start_payment, 'DD/MM/YYYY');
      merge into bakasha
      using dual
      on (bakasha.seq_bakasha = v_seq_bakasha)
      when matched then
        update
           set code_sug_bakasha = bakasha_row.code_sug_bakasha,
               date_bakasha     = bakasha_row.date_bakasha,
               code_source      = bakasha_row.code_source
        
      
      when not matched then
        insert
          (seq_bakasha,
           seq_prisha,
           code_sug_bakasha,
           
           code_source,
           date_bakasha)
        values
          (v_seq_bakasha,
           v_seq_prisha,
           bakasha_row.code_sug_bakasha,
           
           bakasha_row.code_source,
           bakasha_row.date_bakasha) log errors into err_bakasha
          (v_ora_err_tag$) reject limit unlimited;
    end loop;
    if pk_load_mimshak.count_rowes('err_bakasha', v_where) > 0 then
      return false;
    else
      return true;
    end if;
  end;
  --------------------------------------------------------------------------------------------------------
  function update_prisha return boolean is
    prisha_row err_prisha%rowtype;
  begin
    for r in (select distinct m10.identity_number,
                              m10.benefit_number,
                              m12.retirement_office,
                              m22.wing
                from ld_mlm_10 m10
                left join ld_mlm_12 m12
                  on m12.identity_number = m10.identity_number
                 and m12.is_erased = 0
                 and m12.job_number = m10.job_number
                left join ld_mlm_22 m22
                  on m22.identity_number = m10.identity_number
                 and m22.is_erased = 0
                 and m22.job_number = m10.job_number
               where m10.job_number = v_job_number
                 and m10.is_erased = 0
                    --'000', '126',
                 and m10.retirement_section not in ('128')
                 and m10.identity_number = v_ID) loop
      /* if pk_load_mimshak.is_exist_prisha(v_porshim_seq,
                                         v_ezor_ovdim,
                                         v_seq_prisha) = false then
        v_seq_prisha := prisha_seq.nextval;
      end if;
      prisha_row.seq_poresh     := v_porshim_seq;
      prisha_row.seq_ezor_ovdim := v_ezor_ovdim;
      prisha_row.gimla_number   := trim(r.mis_gimla);*/
      -- prisha_row.code_unit      := trim(r.kd_yehida);
      v_seq_prisha              := prisha_seq.nextval;
      prisha_row.gimla_number   := r.benefit_number;
      prisha_row.seq_poresh     := v_porshim_seq;
      v_ezor_ovdim              := convert_seq_ezor_ovdim(r.retirement_office,
                                                          r.wing);
      prisha_row.seq_ezor_ovdim := v_ezor_ovdim;
      merge into prisha
      using dual
      on (prisha.seq_prisha = v_seq_prisha)
      when matched then
        update
           set gimla_number   = prisha_row.gimla_number,
               seq_ezor_ovdim = prisha_row.seq_ezor_ovdim
      when not matched then
        insert
          (seq_prisha,
           seq_poresh,
           seq_ezor_ovdim,
           gimla_number /*,     seq_code_unit*/)
        values
          (v_seq_prisha,
           v_porshim_seq,
           v_ezor_ovdim,
           trim(r.benefit_number)) log errors into err_prisha
          (v_ora_err_tag$) reject limit unlimited;
    end loop;
    if pk_load_mimshak.count_rowes('err_prisha', v_where) > 0 then
      return false;
    else
      return true;
    end if;
  
  end;
