  procedure update_mazav_mishpachti is
    v_code_mazav_mishpachti number;
    v_seq_mazav_mishpachti  number;
  begin
    for r in (select distinct t.identity_number,
                              t.from_date,
                              t.gender_status_code
                from LD_MLM_13 t
               where t.is_erased = 0
                 and t.identity_number = v_id) loop
    
      v_code_mazav_mishpachti := case
                                   when trim(r.gender_status_code) = 1 then
                                    0
                                   when trim(r.gender_status_code) = 2 then
                                    1
                                   when trim(r.gender_status_code) = 3 then
                                    3
                                   when trim(r.gender_status_code) = 4 then
                                    2
                                   when trim(r.gender_status_code) = 5 then
                                    0
                                   when trim(r.gender_status_code) = 6 then
                                    1
                                   when trim(r.gender_status_code) = 7 then
                                    3
                                   when trim(r.gender_status_code) = 8 then
                                    2
                                   else
                                    null
                                 end;
      v_seq_mazav_mishpachti  := MAZAV_MISHPACHTI_seq.nextval;
      /*      INSERT INTO MAZAV_MISHPACHTI mm
        (mm.seq_mazav_mishpachti,
         mm.seq_poresh,
         mm.code_mazav_mishpachti,
         mm.date_mazav_mishpachti)
      VALUES
        (MAZAV_MISHPACHTI_seq.nextval,
         v_porshim_seq,
         v_code_mazav_mishpachti,
         to_date(r.from_date, 'dd/mm/yyyy'));*/
    
      merge into MAZAV_MISHPACHTI
      using dual
      on (MAZAV_MISHPACHTI.Seq_Mazav_Mishpachti = v_seq_mazav_mishpachti)
      when matched then
        update set code_mazav_mishpachti = v_code_mazav_mishpachti
      when not matched then
        insert
          (seq_mazav_mishpachti,
           seq_poresh,
           code_mazav_mishpachti,
           date_mazav_mishpachti,
           CODE_USER)
        values
          (MAZAV_MISHPACHTI_seq.nextval,
           v_porshim_seq,
           v_code_mazav_mishpachti,
           to_date(r.from_date, 'dd/mm/yyyy'),
           1) log errors into err_MAZAV_MISHPACHTI
          (v_ora_err_tag$) reject limit unlimited;
    
    end loop;
  end;

