create or replace package body prm_system_copy.pk_Actions_collection is
  ----------------------------------------------------------------
  procedure delete_tik(p_seq_porshim number) is
  begin
    delete bney_mishpacha t where t.seq_porshim = p_seq_porshim;
  end;
  ----------------------------------------------------------------
  procedure delete_bney_mishpacha(p_seq_porshim number) is
  begin
    delete bney_mishpacha t where t.seq_porshim = p_seq_porshim;
  end;
  ----------------------------------------------------------------
  procedure Get_zehut_not_loaded(cur out sys_refcursor) is
  begin
    open cur for
      select regexp_substr(main_title, '\d+', 1, 2) as zeut, seq - 1
        from (select last_value(case
                                --Get main title row
                                  when regexp_like(a,
                                                   '^~.{0,100}~.{0,100}~.{0,100}~.{0,1}~.{0,1}~') then
                                   a
                                  else
                                   null
                                end ignore nulls) over(order by seq asc rows between unbounded preceding and 1 preceding) as main_title
                     
                    ,
                     replace(a, '~~', '~0~') as contact,
                     seq
                from ld_merkava
              --Include main title row and contact title row
               where regexp_like(a,
                                 '^~.{0,100}~.{0,100}~.{0,100}~.{0,100}~.{0,100}~.{0,100}')) internal
      --Filter Only contact title rowes
       where not
              regexp_like(contact,
                          '^~.{0,100}~.{0,100}~.{0,100}~.{0,100}~.{0,100}~.{0,100}~')
         and regexp_substr(main_title, '\d+', 1, 2) in
             (select v.MISPAR_ZEHUT
                from v_regila_last_status v
               where v.CODE_ACTION = 6);
  end;
  ----------------------------------------------------------------
  procedure delete_from_ld_merkava(min_seq number, max_seq number) is
  begin
    delete from ld_merkava m
     where m.seq < min_seq
       and m.seq > max_seq;
  
    commit;
  end;
  ----------------------------------------------------------------
  procedure delete_poresh(p_id number) is
  begin
    for r in (select t.porshim_seq from poresh t where t.mispar_zehut = p_id) loop
      delete_bney_mishpacha(r.porshim_seq);
      delete_tik(r.porshim_seq);
    
      delete poresh where porshim_seq = r.porshim_seq;
    end loop;
  end;
  ----------------------------------------------------------------
  function load_tik_date(p_seq_bakasha number, p_temp number) return date is
    v_load_date date;
  begin
    select s.date_action
      into v_load_date
      from action_log s
     where s.seq_bakasha = p_seq_bakasha
       and s.code_action = 6;
  
    return v_load_date;
  end;
  --------------------------------------------------------------

end;
/

create or replace package body prm_system_copy.pk_chinuch is
  ------------------------------------------------
  v_code_sug_mimshak number(1);
  ----------------------------------------------------------
  function check_porshim(p_mispar_zehut  number,
                         err_porshim_row in out err_porshim%rowtype)
    return boolean is
    pragma autonomous_transaction;
  begin
    begin
      err_porshim_row.mispar_zehut := to_number(err_porshim_row.mispar_zehut);
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9022',
                              p_field_name   => 'mispar_zehut',
                              p_value        => err_porshim_row.mispar_zehut);
        commit;
        return false;
    end;
  
    -- check  date fields format.
    if length(err_porshim_row.taarich_leda) <> 8 then
      pk_load.Insert_errors(p_mispar_zehut,
                            20005,
                            p_table_name   => '9022',
                            p_field_name   => 'taarich_leda',
                            p_value        => err_porshim_row.taarich_leda);
    end if;
    if length(err_porshim_row.taarich_aliya) <> 8 then
      pk_load.Insert_errors(p_mispar_zehut,
                            20005,
                            p_table_name   => '9022',
                            p_field_name   => 'taarich_aliya',
                            p_value        => err_porshim_row.taarich_aliya);
    end if;
    begin
      err_porshim_row.taarich_aliya := to_date(err_porshim_row.taarich_aliya,
                                               'ddmmyyyy');
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9022',
                              p_field_name   => 'taarich_aliya',
                              p_value        => err_porshim_row.taarich_aliya);
    end;
    begin
      err_porshim_row.taarich_leda := to_date(err_porshim_row.taarich_leda,
                                              'ddmmyyyy');
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9022',
                              p_field_name   => 'taarich_leda',
                              p_value        => err_porshim_row.taarich_leda);
    end;
  
    commit;
    return true;
  end;
  ------------------------------------------------
  procedure Porshim
  -- The variable p_mispar_zehut is not number,
    -- in order to avoid Running failed,
    -- when the value is not number.
  (p_mispar_zehut varchar2) is
    porshim_row err_porshim%rowtype;
  begin
    for r in (select distinct Pratim_Ishiym.Sug_Zihuy,
                              Pratim_Ishiym.MISPAR_ZEHUT,
                              Pratim_Ishiym.SHEM_PRATI,
                              Pratim_Ishiym.SHEM_MISHPACHA,
                              Pratim_Ishiym.TAA_ALIYA,
                              Pratim_Ishiym.TAA_LEDA,
                              Ktovet_Oved.kidomet || '-' ||
                              Ktovet_Oved.Telephone Telephone,
                              Ktovet_Oved.kidomet_nosefet || '-' ||
                              Ktovet_Oved.telephone_nosaf telephone2,
                              Pratim_Ishiym.Min,
                              Pratim_Ishiym.Doar_Elektrony
                from ld_Chinuch_9022_Pratim_Ishiym Pratim_Ishiym
              
                left join ld_Chinuch_9024_Ktovet_Oved Ktovet_Oved
                  on Pratim_Ishiym.Mispar_Zehut = Ktovet_Oved.mispar_zehut
              
               where nvl(Pratim_Ishiym.Mispar_Zehut, ' ') =
                     nvl(p_mispar_zehut, ' ')) loop
      --fill porshim_row
      porshim_row := null;
      --porshim_row.ora_err_tag$ := rowInData.Seq;
      porshim_row.sug_zihuy      := r.Sug_Zihuy;
      porshim_row.mispar_zehut   := r.mispar_zehut;
      porshim_row.shem_prati     := r.shem_prati;
      porshim_row.shem_mishpacha := r.shem_mishpacha;
      porshim_row.taarich_aliya  := r.taa_aliya;
      porshim_row.taarich_leda   := r.taa_leda;
      porshim_row.telephon       := r.telephone;
      porshim_row.pelephon       := r.telephone2;
      porshim_row.code_min       := r.min;
      porshim_row.email          := r.doar_elektrony;
    
      --check_fields
      if (check_porshim(p_mispar_zehut, porshim_row)) then
        --merge into PORSHIM
        merge into poresh porshim
        using dual
        on (porshim.mispar_zehut = porshim_row.mispar_zehut)
        when matched then
          update
             set porshim.shem_prati     = porshim_row.shem_prati,
                 porshim.shem_mishpacha = porshim_row.shem_mishpacha,
                 porshim.taarich_aliya  = porshim_row.taarich_aliya,
                 porshim.taarich_leda   = porshim_row.taarich_leda,
                 porshim.telephon       = porshim_row.telephon,
                 porshim.pelephon       = porshim_row.pelephon,
                 porshim.code_min       = porshim_row.code_min,
                 porshim.email          = porshim_row.email
        when not matched then
          insert
            (mispar_zehut,
             shem_prati,
             shem_mishpacha,
             taarich_aliya,
             taarich_leda,
             telephon,
             pelephon,
             code_min,
             email,
             porshim_seq)
          values
            (porshim_row.mispar_zehut,
             porshim_row.shem_prati,
             porshim_row.shem_mishpacha,
             porshim_row.taarich_aliya,
             porshim_row.taarich_leda,
             porshim_row.telephon,
             porshim_row.pelephon,
             porshim_row.code_min,
             porshim_row.email,
             porshim_seq.nextval) log errors into ERR_Porshim REJECT LIMIT UNLIMITED;
      end if;
    end loop;
  end;
  ------------------------------------------------
  procedure check_darga_vederug(p_mispar_zehut    varchar2,
                                darga_vederug_row in out err_darga_vederug_tik%rowtype) is
  begin
  
    begin
      darga_vederug_row.taarich_me := to_date(darga_vederug_row.taarich_me,
                                              'ddmmyyyy');
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9023',
                              p_field_name   => 'taarich_me',
                              p_value        => darga_vederug_row.taarich_me);
    end;
    if darga_vederug_row.code_darga is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9023',
                            p_field_name   => 'code_darga',
                            p_value        => darga_vederug_row.code_darga);
    
    end if;
  end;
  ------------------------------------------------
  function convert_code_darge(p_code_darge number) return number is
  begin
    return case p_code_darge when 1 then 120 when 2 then 110 when 3 then 100 when 7 then 91 when 8 then 90 when 9 then 80 when 10 then 70 when 11 then 60 when 12 then 50 when 13 then 40 when 14 then 30 when 16 then 10 else 999 end;
  end;
  ------------------------------------------------
  procedure darga_vederug_tik(p_mispar_zehut varchar2,
                              p_seq_bakasha  number) is
    darga_vederug_tik_row err_darga_vederug_tik%rowtype;
  begin
  
    for r in (select distinct oved_poresh.darga,
                              oved_poresh.taarich_darga,
                              oved_poresh.derug_ofek,
                              oved_poresh.dargat_ofek
              
                from ld_chinuch_9023_oved_poresh oved_poresh
              
                left join poresh porshim
                  on porshim.mispar_zehut = oved_poresh.MISPAR_ZEHUT
              
               where nvl(oved_poresh.Mispar_Zehut, ' ') =
                     nvl(p_mispar_zehut, ' ')) loop
      darga_vederug_tik_row.seq_bakasha     := p_seq_bakasha;
      darga_vederug_tik_row.code_darga      := convert_code_darge(r.darga);
      darga_vederug_tik_row.taarich_me      := r.taarich_darga;
      darga_vederug_tik_row.code_darga_ofek := r.dargat_ofek;
      darga_vederug_tik_row.code_derug_ofek := r.derug_ofek;
    
      check_darga_vederug(p_mispar_zehut, darga_vederug_tik_row);
    
      insert into darga_vederug_tik
        (seq_bakasha,
         code_derug,
         code_darga,
         taarich_me,
         code_darga_ofek,
         code_derug_ofek,
         seq_dargot_vederug_tik,
         shem_meadken_acharon)
      values
        (darga_vederug_tik_row.seq_bakasha,
         41,
         darga_vederug_tik_row.code_darga,
         darga_vederug_tik_row.taarich_me,
         darga_vederug_tik_row.code_darga_ofek,
         darga_vederug_tik_row.code_derug_ofek,
         darga_vederug_tik_seq.nextval,
         SYS_CONTEXT('USERENV','OS_USER'))
      
      log errors into err_darga_vederug_tik REJECT LIMIT UNLIMITED;
    end loop;
  end;
  ------------------------------------------------
  procedure check_chinuch_salary(p_mispar_zehut     varchar2,
                                 chinuch_salary_row in out err_chinuch_salary%rowtype) is
  begin
    begin
      chinuch_salary_row.date_begin_ofek := to_date(chinuch_salary_row.date_begin_ofek,
                                                    'ddmmyyyy');
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9031',
                              p_field_name   => 'date_begin_ofek',
                              p_value        => chinuch_salary_row.date_begin_ofek);
    end;
    begin
      chinuch_salary_row.date_begin_oz := to_date(chinuch_salary_row.date_begin_oz,
                                                  'ddmmyyyy');
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9031',
                              p_field_name   => 'date_begin_oz',
                              p_value        => chinuch_salary_row.date_begin_oz);
    end;
  
    begin
      chinuch_salary_row.hekef_misra_ofek := chinuch_salary_row.hekef_misra_ofek /
                                             100000;
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9031',
                              p_field_name   => 'hekef_misra_ofek',
                              p_value        => chinuch_salary_row.hekef_misra_ofek);
      
    end;
  
    begin
      chinuch_salary_row.hekef_misra_oz := chinuch_salary_row.hekef_misra_oz /
                                           100000;
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9031',
                              p_field_name   => 'hekef_misra_oz',
                              p_value        => chinuch_salary_row.hekef_misra_oz);
      
    end;
  
  end;
  ------------------------------------------------
  procedure chinuch_salary(p_mispar_zehut varchar2, p_seq_bakasha number) is
    chinuch_salary_row err_chinuch_salary%rowtype;
  begin
  
    for r in (select distinct oved_poresh.kidum_darga,
                              oved_poresh.taarich_hiztarfut_leofek,
                              oved_poresh.taarich_hiztarfut_leoz,
                              oved_poresh.gmuley_hishtalmut,
                              oved_poresh.kefel_toar,
                              oved_poresh.gmul_banaim,
                              oved_poresh.hekef_misra_beofek,
                              oved_poresh.hekef_misra_oz,
                              oved_poresh.gmuley_hishtalmut_oz
              
                from ld_chinuch_9023_oved_poresh oved_poresh
              
                left join poresh porshim
                  on porshim.mispar_zehut = oved_poresh.MISPAR_ZEHUT
              
               where nvl(oved_poresh.Mispar_Zehut, ' ') =
                     nvl(p_mispar_zehut, ' ')
                 and (oved_poresh.kidum_darga is not null or
                      oved_poresh.taarich_hiztarfut_leofek is not null or
                      oved_poresh.taarich_hiztarfut_leoz is not null or
                      oved_poresh.gmuley_hishtalmut is not null or
                      oved_poresh.kefel_toar is not null or
                      oved_poresh.gmul_banaim is not null or
                      oved_poresh.hekef_misra_beofek is not null or
                      oved_poresh.hekef_misra_oz is not null or
                      oved_poresh.gmuley_hishtalmut_oz is not null)) loop
      chinuch_salary_row.seq_bakasha          := p_seq_bakasha;
      chinuch_salary_row.kidum_darga_ofek     := r.kidum_darga;
      chinuch_salary_row.date_begin_ofek      := r.taarich_hiztarfut_leofek;
      chinuch_salary_row.date_begin_oz        := r.taarich_hiztarfut_leoz;
      chinuch_salary_row.gmuley_hishtalmut    := r.gmuley_hishtalmut;
      chinuch_salary_row.is_kefel_toar        := r.kefel_toar;
      chinuch_salary_row.is_gmul_benaim       := r.gmul_banaim;
      chinuch_salary_row.hekef_misra_ofek     := r.hekef_misra_beofek;
      chinuch_salary_row.hekef_misra_oz       := r.hekef_misra_oz;
      chinuch_salary_row.gmuley_hishtalmut_oz := r.gmuley_hishtalmut_oz;
    
      check_chinuch_salary(p_mispar_zehut, chinuch_salary_row);
    
      insert into chinuch_salary
        (seq_bakasha,
         kidum_darga_ofek,
         date_begin_ofek,
         date_begin_oz,
         gmuley_hishtalmut,
         is_kefel_toar,
         is_gmul_benaim,
         hekef_misra_ofek,
         hekef_misra_oz,
         gmuley_hishtalmut_oz,
         shem_meadken_acharon)
      values
        (chinuch_salary_row.seq_bakasha,
         chinuch_salary_row.kidum_darga_ofek,
         chinuch_salary_row.date_begin_ofek,
         chinuch_salary_row.date_begin_oz,
         chinuch_salary_row.gmuley_hishtalmut,
         chinuch_salary_row.is_kefel_toar,
         chinuch_salary_row.is_gmul_benaim,
         chinuch_salary_row.hekef_misra_ofek,
         chinuch_salary_row.hekef_misra_oz,
         chinuch_salary_row.gmuley_hishtalmut_oz,
         SYS_CONTEXT('USERENV','OS_USER')) log errors into err_chinuch_salary REJECT LIMIT UNLIMITED;
    
    end loop;
  end;
  ------------------------------------------------
  procedure insert_vetek_detail(p_seq_bakasha     number,
                                p_code_type_vetek number,
                                p_vetek           number) is
  begin
    if nvl(p_vetek, 0) <> 0 then
      insert into vetek_detail
        (seq_vetek_detail,
         seq_bakasha,
         code_type_vetek,
         years,
         date_update,
         shem_meadken_acharon)
      values
        (vetek_detail_seq.nextval,
         p_seq_bakasha,
         p_code_type_vetek,
         p_vetek,
         sysdate,
         SYS_CONTEXT('USERENV','OS_USER')) log errors into err_vetek_detail REJECT LIMIT UNLIMITED;
    end if;
  
  end;
  ------------------------------------------------
  function get_vetek_horaha(p_mispar_zehut varchar2) return number is
    v_vetek number;
  begin
    select distinct oved_poresh.vetek_horaha
      into v_vetek
      from ld_chinuch_9023_oved_poresh oved_poresh
     where nvl(oved_poresh.Mispar_Zehut, ' ') = nvl(p_mispar_zehut, ' ');
  
    return nvl(v_vetek, 0);
  end;
  ------------------------------------------------
  function get_vetek_tzahal(p_mispar_zehut varchar2) return number is
    v_vetek number;
  begin
    select distinct oved_poresh.vetek_tzahal
      into v_vetek
      from ld_chinuch_9023_oved_poresh oved_poresh
     where nvl(oved_poresh.Mispar_Zehut, ' ') = nvl(p_mispar_zehut, ' ');
    if v_vetek is not null then
      -- Divide months to years
      v_vetek := v_vetek / 12;
      --Round quarterly
      v_vetek := round(v_vetek / 25, 2) * 25;
    end if;
  
    return nvl(v_vetek, 0);
  end;
  ------------------------------------------------
  procedure vetek_detail(p_mispar_zehut varchar2, p_seq_bakasha number) is
  begin
    --horaha
    insert_vetek_detail(p_seq_bakasha, 1, get_vetek_horaha(p_mispar_zehut));
    --tzahal
    insert_vetek_detail(p_seq_bakasha, 2, get_vetek_tzahal(p_mispar_zehut));
  
  end;
  ------------------------------------------------
  PROCEDURE check_sherut_svaii(p_mispar_zehut               number,
                               err_tkufot_sherut_tsvaii_row in out err_tkufot_sherut_tsvaii%rowtype) is
    pragma autonomous_transaction;
  begin
    if err_tkufot_sherut_tsvaii_row.taarich_me is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9034',
                            p_field_name   => 'taarich_me',
                            p_value        => err_tkufot_sherut_tsvaii_row.taarich_me);
    
    end if;
    if err_tkufot_sherut_tsvaii_row.taarich_ad is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9034',
                            p_field_name   => 'taarich_ad',
                            p_value        => err_tkufot_sherut_tsvaii_row.taarich_ad);
    end if;
    if err_tkufot_sherut_tsvaii_row.code_sug_sherut_tzaii is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9034',
                            p_field_name   => 'code_sug_sherut_tzaii',
                            p_value        => err_tkufot_sherut_tsvaii_row.code_sug_sherut_tzaii);
    end if;
    -- check  date fields format.
    if length(err_tkufot_sherut_tsvaii_row.taarich_me) <> 8 then
      pk_load.Insert_errors(p_mispar_zehut,
                            20005,
                            p_table_name   => '9034',
                            p_field_name   => 'taarich_me',
                            p_value        => err_tkufot_sherut_tsvaii_row.taarich_me);
    end if;
    if length(err_tkufot_sherut_tsvaii_row.taarich_ad) <> 8 then
      pk_load.Insert_errors(p_mispar_zehut,
                            20005,
                            p_table_name   => '9034',
                            p_field_name   => 'taarich_ad',
                            p_value        => err_tkufot_sherut_tsvaii_row.taarich_ad);
    end if;
    if length(err_tkufot_sherut_tsvaii_row.taarich_zchuyot) <> 8 then
      pk_load.Insert_errors(p_mispar_zehut,
                            20005,
                            p_table_name   => '9034',
                            p_field_name   => 'taarich_zchuyot',
                            p_value        => err_tkufot_sherut_tsvaii_row.taarich_zchuyot);
    end if;
    begin
      err_tkufot_sherut_tsvaii_row.taarich_me := to_date(err_tkufot_sherut_tsvaii_row.taarich_me,
                                                         'ddmmyyyy');
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9034',
                              p_field_name   => 'taarich_me',
                              p_value        => err_tkufot_sherut_tsvaii_row.taarich_me);
      
    end;
    begin
      err_tkufot_sherut_tsvaii_row.taarich_ad := to_date(err_tkufot_sherut_tsvaii_row.taarich_ad,
                                                         'ddmmyyyy');
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9034',
                              p_field_name   => 'taarich_ad',
                              p_value        => err_tkufot_sherut_tsvaii_row.taarich_ad);
    end;
    begin
      err_tkufot_sherut_tsvaii_row.taarich_zchuyot := to_date(err_tkufot_sherut_tsvaii_row.taarich_zchuyot,
                                                              'ddmmyyyy');
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9034',
                              p_field_name   => 'taarich_zchuyot',
                              p_value        => err_tkufot_sherut_tsvaii_row.taarich_zchuyot);
    end;
  
    commit;
  end;
  ------------------------------------------------
  procedure tkufot_sherut_tsvaii(p_mispar_zehut varchar2,
                                 p_seq_bakasha  number) is
    tkufot_sherut_tsvaii_row err_tkufot_sherut_tsvaii%rowtype;
  begin
  
    for r in (select distinct sherut_tsvaii.taarich_me,
                              sherut_tsvaii.taarich_ad,
                              sherut_tsvaii.taarich_zchuyot,
                              sherut_tsvaii.kod_sherut
              
                from ld_chinuch_9034_sherut_tsvaii sherut_tsvaii
              
                left join ld_Chinuch_9022_Pratim_Ishiym Pratim_Ishiym
                  on sherut_tsvaii.MISPAR_ZEHUT = Pratim_Ishiym.MISPAR_ZEHUT
              
                left join code_ezor_ovdim ezor_ovdim
                  on Pratim_Ishiym.MISRAD_AGAF = ezor_ovdim.code_ezor_ovdim
                 and code_makor = 3 -- Chinuch
              
                left join poresh porshim
                  on porshim.mispar_zehut = sherut_tsvaii.MISPAR_ZEHUT
              
               where nvl(sherut_tsvaii.Mispar_Zehut, ' ') =
                     nvl(p_mispar_zehut, ' ')) loop
      tkufot_sherut_tsvaii_row.seq_bakasha           := p_seq_bakasha;
      tkufot_sherut_tsvaii_row.taarich_me            := r.taarich_me;
      tkufot_sherut_tsvaii_row.taarich_ad            := r.taarich_ad;
      tkufot_sherut_tsvaii_row.taarich_zchuyot       := r.taarich_zchuyot;
      tkufot_sherut_tsvaii_row.code_sug_sherut_tzaii := r.kod_sherut;
    
      --check_fields
      check_sherut_svaii(p_mispar_zehut, tkufot_sherut_tsvaii_row);
    
      insert into tkufot_sherut_tsvaii
        (seq_bakasha,
         taarich_me,
         taarich_ad,
         taarich_zchuyot,
         code_sug_sherut_tzaii,
         seq_tkufot_sherut_tsvaii,
         shem_meadken_acharon)
      values
        (tkufot_sherut_tsvaii_row.seq_bakasha,
         tkufot_sherut_tsvaii_row.taarich_me,
         tkufot_sherut_tsvaii_row.taarich_ad,
         tkufot_sherut_tsvaii_row.taarich_zchuyot,
         tkufot_sherut_tsvaii_row.code_sug_sherut_tzaii,
         tkufot_sherut_tsvaii_seq.nextval,
         SYS_CONTEXT('USERENV','OS_USER'))
      
      log errors into ERR_TKUFOT_SHERUT_TSVAII REJECT LIMIT UNLIMITED;
    end loop;
  end;
  ------------------------------------------------
  PROCEDURE check_tikim(p_mispar_zehut number,
                        err_tikim_row  in out err_bakasha_regila%rowtype,
                        taarich_leda   date,
                        taarich_ptira  date) is
    pragma autonomous_transaction;
    taarich_prisha date;
  begin
    if taarich_prisha is not null and
       to_date(err_tikim_row.taarich_prisha, 'ddmmyyyy') <= taarich_leda then
      pk_load.Insert_errors(p_mispar_zehut,
                            20004,
                            'taarich_prisha: ' ||
                            err_tikim_row.taarich_prisha,
                            p_table_name => '9031',
                            p_field_name => 'taarich_leda',
                            p_value => err_tikim_row.taarich_prisha);
    
    end if;
    if taarich_prisha is not null and
       to_date(err_tikim_row.taarich_prisha, 'ddmmyyyy') > taarich_ptira then
      pk_load.Insert_errors(p_mispar_zehut,
                            20004,
                            'taarich_ptira: ' ||
                            err_tikim_row.taarich_prisha,
                            p_table_name => '9031',
                            p_field_name => 'taarich_prisha',
                            p_value => err_tikim_row.taarich_prisha);
    
    end if;
    --check Required fields.
    if v_code_sug_mimshak = 1 and
       err_tikim_row.ishur_prisha_lo_sof_hodesh is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9031',
                            p_field_name   => 'ishur_prisha_lo_sof_hodesh',
                            p_value        => err_tikim_row.ishur_prisha_lo_sof_hodesh);
    
    end if;
  
    if err_tikim_row.vetek is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9031',
                            p_field_name   => 'vetek',
                            p_value        => err_tikim_row.vetek);
    
    end if;
    /*  
     if nvl(err_tikim_row.nechut_achuz, 0) <> 0 and
        err_tikim_row.nechut_taarich_hamigbala is null then
       pk_load.Insert_errors(p_mispar_zehut,
                             20001,
                             p_table_name   => '9031',
                             p_field_name   => 'nechut_taarich_hamigbala',
                             p_value        => err_tikim_row.nechut_taarich_hamigbala);
     
     end if;
    
    if nvl(err_tikim_row.nechut_achuz, 0) <> 0 and
        err_tikim_row.nechut_taarich_end_hamigbala is null then
       pk_load.Insert_errors(p_mispar_zehut,
                             20001,
                             p_table_name   => '9031',
                             p_field_name   => 'nechut_taarich_end_hamigbala',
                             p_value        => err_tikim_row.nechut_taarich_end_hamigbala);
     
     end if;*/
  
    -- check date fields format.
    if length(err_tikim_row.taarich_prisha) <> 8 then
      pk_load.Insert_errors(p_mispar_zehut,
                            20005,
                            p_table_name   => '9031',
                            p_field_name   => 'taarich_prisha',
                            p_value        => err_tikim_row.taarich_prisha);
    end if;
    begin
      err_tikim_row.taarich_prisha := to_date(err_tikim_row.taarich_prisha,
                                              'ddmmyyyy');
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9031',
                              p_field_name   => 'taarich_prisha',
                              p_value        => err_tikim_row.taarich_prisha);
    end;
  
    begin
      err_tikim_row.nechut_taarich_hamigbala := to_date(err_tikim_row.nechut_taarich_hamigbala,
                                                        'ddmmyyyy');
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9031',
                              p_field_name   => 'nechut_taarich_hamigbala',
                              p_value        => err_tikim_row.nechut_taarich_hamigbala);
    end;
  
    begin
      err_tikim_row.nechut_taarich_end_hamigbala := to_date(err_tikim_row.nechut_taarich_end_hamigbala,
                                                            'ddmmyyyy');
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9031',
                              p_field_name   => 'nechut_taarich_end_hamigbala',
                              p_value        => err_tikim_row.nechut_taarich_end_hamigbala);
    end;
  
    begin
      err_tikim_row.taarich_chatimat_tofes := to_date(err_tikim_row.taarich_chatimat_tofes,
                                                      'ddmmyyyy');
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9031',
                              p_field_name   => 'taarich_chatimat_tofes',
                              p_value        => err_tikim_row.taarich_chatimat_tofes);
    end;
  
    -- update format  
    if length(err_tikim_row.nechut_achuz) > 6 then
      pk_load.Insert_errors(p_mispar_zehut,
                            20006,
                            p_table_name   => '9031',
                            p_field_name   => 'nechut_achuz',
                            p_value        => err_tikim_row.nechut_achuz);
    
    else
      begin
        err_tikim_row.nechut_achuz := err_tikim_row.nechut_achuz / 100;
      exception
        when others then
          pk_load.Insert_errors(p_mispar_zehut,
                                sqlcode,
                                sqlerrm,
                                p_table_name   => '9031',
                                p_field_name   => 'nechut_achuz',
                                p_value        => err_tikim_row.nechut_achuz);
        
      end;
    end if;
    commit;
  end;
  ------------------------------------------------
  function convert_chinuch_mikzoa(p_chinuch_mikzoa number) return number is
  begin
    return case p_chinuch_mikzoa when 1 then 912 when 2 then 911 else p_chinuch_mikzoa end;
  end;
  ------------------------------------------------
  function Tikim(p_seq_bakasha_previos number,
                 p_mispar_zehut        varchar2,
                 p_taarich_leda        date,
                 p_taarich_ptira       date,
                 p_seq_porshim         number,
                 p_code_sug_bakasha    number,
                 p_machoz              number) return number is
    tikim_row     err_bakasha_regila%rowtype;
    addinal_years number;
    v_seq_bakasha number;
  begin
  
    for r in (select distinct porshim_ch.lefi_nechut,
                              porshim_ch.ind_prisha_lo_besof_chodesh,
                              porshim_ch.taarich_prisha,
                              oved_poresh.machoz,
                              nvl(oved_poresh.ganenet, 0) ganenet,
                              porshim_ch.orech_sherut orech_sherut,
                              case
                                when porshim_ch.TAT_SEIF_PRISHA is not null and
                                     porshim_ch.SEIF_PRISHA is not null then
                                 porshim_ch.TAT_SEIF_PRISHA ||
                                 porshim_ch.SEIF_PRISHA
                                else
                                 null
                              end seif_prisha,
                              porshim_ch.ACHUZ_NECHUT,
                              Pratim_Ishiym.taa_leda,
                              Pratim_Ishiym.min,
                              porshim_ch.me_taarich_mevukash,
                              porshim_ch.ad_taarich_mevukash,
                              porshim_ch.taarich_chatimat_tofes
              
                from ld_chinuch_9031_porshim porshim_ch
              
                left join ld_Chinuch_9023_Oved_Poresh Oved_Poresh
                  on porshim_ch.MISPAR_ZEHUT = Oved_Poresh.MISPAR_ZEHUT
              
                left join ld_Chinuch_9022_Pratim_Ishiym Pratim_Ishiym
                  on Oved_Poresh.MISPAR_ZEHUT = Pratim_Ishiym.MISPAR_ZEHUT
              
               where nvl(porshim_ch.Mispar_Zehut, ' ') =
                     nvl(p_mispar_zehut, ' ')) loop
    
      if p_seq_bakasha_previos is not null then
        -----------------------Get previous bakasha---------------------------------
        tikim_row := pk_load_mimshak.get_bakasha_regila_by_previous(p_seq_bakasha_previos);
        ----------------------------------------------------------------------------
      else
        tikim_row := null;
      end if;
    
      --Update fields that got from chinuch
      tikim_row.chisuv_lefy_nechut         := r.lefi_nechut;
      tikim_row.ishur_prisha_lo_sof_hodesh := r.ind_prisha_lo_besof_chodesh;
      if nullif(r.taarich_prisha, 0) is not null then
        tikim_row.taarich_prisha := r.taarich_prisha;
      elsif v_code_sug_mimshak = 2 then
        --Set default value when it's participation
        if r.min = 1 then
          addinal_years := 67;
        elsif r.min = 2 then
          addinal_years := 62;
        end if;
        --Calculate:
        --Date of birth + 67/62 years + end of one month after.
        tikim_row.taarich_prisha := trunc(ADD_MONTHS(r.taa_leda,
                                                     12 * addinal_years + 2),
                                          'MONTH') - 1;
      end if;
    
      tikim_row.chinuch_mikzoa      := convert_chinuch_mikzoa(r.ganenet);
      tikim_row.chisuv_lefy_sheerut := r.orech_sherut;
      if nullif(r.seif_prisha, 0) is not null then
        tikim_row.code_seif_prisha := pk_load_mimshak.get_new_code_seif_prisha(r.seif_prisha);
      elsif v_code_sug_mimshak = 2 then
        --Set default value when it's participation of chinuch
        tikim_row.code_seif_prisha := 217;
      end if;
      tikim_row.misrad_maskoret := 150;
      tikim_row.nechut_achuz    := r.achuz_nechut;
      tikim_row.vetek           := get_vetek_horaha(p_mispar_zehut) +
                                   get_vetek_tzahal(p_mispar_zehut);
      if tikim_row.code_seif_prisha in (215, 315) and
         r.me_taarich_mevukash is null then
        tikim_row.nechut_taarich_hamigbala := r.taarich_prisha;
      else
        tikim_row.nechut_taarich_hamigbala := r.me_taarich_mevukash;
      end if;
    
      tikim_row.nechut_taarich_end_hamigbala := r.ad_taarich_mevukash;
      tikim_row.taarich_chatimat_tofes       := r.taarich_chatimat_tofes;
    
      --check_fields
      check_tikim(p_mispar_zehut,
                  tikim_row,
                  p_taarich_leda,
                  p_taarich_ptira);
      --------------insert new data with data from previous bakasha---------------
      v_seq_bakasha := pk_load_mimshak.insert_bakasha_regila(3,
                                                             tikim_row,
                                                             p_seq_porshim,
                                                             206,
                                                             sysdate,
                                                             p_code_sug_bakasha,
                                                             p_machoz);
      ----------------------------------------------------------------------------
    
      --update the field is_electronic
      update bakasha b
         set b.is_electronic = 1
       where b.seq_bakasha = v_seq_bakasha;
    
      -- update taarich ptira by seif prisha
      if tikim_row.code_seif_prisha = 126 then
        update poresh porshim
           set porshim.taarich_ptira = tikim_row.taarich_prisha
         where porshim.mispar_zehut = p_mispar_zehut log errors into
         Err_Porshim REJECT LIMIT UNLIMITED;
      end if;
    
    end loop;
    return v_seq_bakasha;
  end;
  ------------------------------------------------
  PROCEDURE check_tkufot_avoda_golmi(p_mispar_zehut             number,
                                     err_tkufot_avoda_golmi_row in out err_tkufot_avoda_golmi%rowtype,
                                     v_seq_bakasha              number) is
    pragma autonomous_transaction;
    continuous_period varchar2(1);
    max_taarich_ad    date;
  begin
    --check Required fields.
    if err_tkufot_avoda_golmi_row.code_sugey_zchuyot is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9050',
                            p_field_name   => 'code_sugey_zchuyot',
                            p_value        => err_tkufot_avoda_golmi_row.code_sugey_zchuyot);
    end if;
  
    if err_tkufot_avoda_golmi_row.sach_chodeshim is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9050',
                            p_field_name   => 'sach_chodeshim',
                            p_value        => err_tkufot_avoda_golmi_row.sach_chodeshim);
    end if;
    if err_tkufot_avoda_golmi_row.code_sugey_tkufot is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9050',
                            p_field_name   => 'code_sugey_tkufot',
                            p_value        => err_tkufot_avoda_golmi_row.code_sugey_tkufot);
    end if;
    if err_tkufot_avoda_golmi_row.achuz_chelkyut is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9050',
                            p_field_name   => 'achuz_chelkyut',
                            p_value        => err_tkufot_avoda_golmi_row.achuz_chelkyut);
    end if;
    -- check fields format.
    if length(err_tkufot_avoda_golmi_row.taarich_me) <> 8 then
      pk_load.Insert_errors(p_mispar_zehut,
                            20005,
                            p_table_name   => '9050',
                            p_field_name   => 'taarich_me',
                            p_value        => err_tkufot_avoda_golmi_row.taarich_me);
    end if;
    if length(err_tkufot_avoda_golmi_row.taarich_ad) <> 8 then
      pk_load.Insert_errors(p_mispar_zehut,
                            20005,
                            p_table_name   => '9050',
                            p_field_name   => 'taarich_ad',
                            p_value        => err_tkufot_avoda_golmi_row.taarich_ad);
    end if;
    begin
      err_tkufot_avoda_golmi_row.taarich_me := to_date(err_tkufot_avoda_golmi_row.taarich_me,
                                                       'ddmmyyyy');
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9050',
                              p_field_name   => 'taarich_me',
                              p_value        => err_tkufot_avoda_golmi_row.taarich_me);
    end;
    begin
      err_tkufot_avoda_golmi_row.taarich_ad := to_date(err_tkufot_avoda_golmi_row.taarich_ad,
                                                       'ddmmyyyy');
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9050',
                              p_field_name   => 'taarich_ad',
                              p_value        => err_tkufot_avoda_golmi_row.taarich_ad);
    end;
    begin
      err_tkufot_avoda_golmi_row.achuz_chelkyut := pk_load_mimshak.Convert_number_to_Decimal(err_tkufot_avoda_golmi_row.achuz_chelkyut / 10);
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9050',
                              p_field_name   => 'achuz_chelkyut',
                              p_value        => err_tkufot_avoda_golmi_row.achuz_chelkyut);
    end;
  
    begin
      err_tkufot_avoda_golmi_row.sach_chodeshim := err_tkufot_avoda_golmi_row.sach_chodeshim / 100;
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9050',
                              p_field_name   => 'sach_chodeshim',
                              p_value        => err_tkufot_avoda_golmi_row.sach_chodeshim);
    end;
  
    select max(ld_temp_tkufot_avoda_golmi.taarich_ad)
      into max_taarich_ad
      from ld_temp_tkufot_avoda_golmi
     where ld_temp_tkufot_avoda_golmi.seq_bakasha = v_seq_bakasha;
  
    begin
      if max_taarich_ad is not null then
        if max_taarich_ad + 1 = err_tkufot_avoda_golmi_row.taarich_me then
          continuous_period := 'Y';
        else
          continuous_period := 'N';
        end if;
      end if;
      if continuous_period = 'N' then
        pk_load.Insert_errors(p_mispar_zehut,
                              20002,
                              p_table_name   => '9050',
                              p_value        => err_tkufot_avoda_golmi_row.taarich_me);
      end if;
    
      --insert into ld_temp_tkufot_avoda_golmi
      insert into ld_temp_tkufot_avoda_golmi
      values
        (err_tkufot_avoda_golmi_row.taarich_me,
         err_tkufot_avoda_golmi_row.taarich_ad,
         v_seq_bakasha);
    exception
      when others then
        -- The next row is unnecessary. 
        -- And it is writed,
        -- because the syntax of exception is must someting to do.
        continuous_period := continuous_period;
    end;
    commit;
  end;
  ------------------------------------------------
  procedure Tkufot_Avoda_Golmi(p_mispar_zehut varchar2,
                               p_seq_bakasha  number) is
    tkufot_avoda_golmi_row err_tkufot_avoda_golmi%rowtype;
  begin
  
    for r in (select distinct Tkufot_Retsifot.TAARICH_ME,
                              Tkufot_Retsifot.TAARICH_AD,
                              Tkufot_Retsifot.HEKEF_MISRA,
                              Tkufot_Retsifot.ORECH_SHERUT,
                              Tkufot_Retsifot.SUG_TKUFA,
                              Tkufot_Retsifot.SUG_ZECHUYOT_LEGIMLA
                from ld_Chinuch_9050_Tkufot_Retsif Tkufot_Retsifot
              
                left join ld_Chinuch_9022_Pratim_Ishiym Pratim_Ishiym
                  on Tkufot_Retsifot.MISPAR_ZEHUT =
                     Pratim_Ishiym.MISPAR_ZEHUT
              
                left join code_ezor_ovdim ezor_ovdim
                  on Pratim_Ishiym.MISRAD_AGAF = ezor_ovdim.code_ezor_ovdim
                 and code_makor = 3 -- Chinuch
              
                left join poresh porshim
                  on porshim.mispar_zehut = Tkufot_Retsifot.MISPAR_ZEHUT
              
               where nvl(Tkufot_Retsifot.Mispar_Zehut, ' ') =
                     nvl(p_mispar_zehut, ' ')
              
              /*Sort the rowes by the dates ('taarich_me').
              In order to check validate Continuity periods ('Retsifot').
              
              I don't use in the function: 'to_date' because 
              all the select is failed when one of the values
              can't be convert to date (Ex: when it is contain non number char ).
              so, I change the value to be : year + month + day
              and sql is sort it as numeric values */
               order by substr(Tkufot_Retsifot.taarich_me, 5) ||
                        substr(Tkufot_Retsifot.taarich_me, 3, 2) ||
                        substr(Tkufot_Retsifot.taarich_me, 1, 2)) loop
      tkufot_avoda_golmi_row                    := null;
      tkufot_avoda_golmi_row.taarich_me         := r.taarich_me;
      tkufot_avoda_golmi_row.taarich_ad         := r.taarich_ad;
      tkufot_avoda_golmi_row.achuz_chelkyut     := r.hekef_misra;
      tkufot_avoda_golmi_row.sach_chodeshim     := r.orech_sherut;
      tkufot_avoda_golmi_row.code_sugey_tkufot  := r.sug_tkufa;
      tkufot_avoda_golmi_row.code_sugey_zchuyot := r.sug_zechuyot_legimla;
      tkufot_avoda_golmi_row.seq_bakasha        := p_seq_bakasha;
    
      check_tkufot_avoda_golmi(p_mispar_zehut,
                               tkufot_avoda_golmi_row,
                               p_seq_bakasha);
    
      insert into Tkufot_Avoda_Golmi
        (taarich_me,
         taarich_ad,
         achuz_chelkyut,
         sach_chodeshim,
         haim_kana_zchuyot,
         code_sugey_tkufot,
         code_sugey_zchuyot,
         seq_tkufot_avoda_golmi,
         seq_bakasha,
         shem_meadken_acharon)
      values
        (tkufot_avoda_golmi_row.taarich_me,
         tkufot_avoda_golmi_row.taarich_ad,
         tkufot_avoda_golmi_row.achuz_chelkyut,
         tkufot_avoda_golmi_row.sach_chodeshim,
         tkufot_avoda_golmi_row.haim_kana_zchuyot,
         tkufot_avoda_golmi_row.code_sugey_tkufot,
         tkufot_avoda_golmi_row.code_sugey_zchuyot,
         tkufot_avoda_golmi_seq.nextval,
         tkufot_avoda_golmi_row.seq_bakasha,
         SYS_CONTEXT('USERENV','OS_USER')) log errors into Err_Tkufot_Avoda_Golmi REJECT LIMIT UNLIMITED;
    end loop;
  end;
