  procedure Bney_Mishpacha(p_mispar_zehut varchar2) is
    bney_mishpacha_row err_bney_mishpacha%rowtype;
  begin
    for r in (select distinct Pratey_Mishpacha.ZEHUT,
                              Pratey_Mishpacha.SHEM_PRATI,
                              Pratey_Mishpacha.TAARICH_LEDA,
                              Pratey_Mishpacha.Mekom_Avoda,
                              Pratey_Mishpacha.KIRVA,
                              porshim.Porshim_Seq
                from ld_chinuch_9025_bney_mishpacha Pratey_Mishpacha
              
                left join ld_Chinuch_9022_Pratim_Ishiym Pratim_Ishiym
                  on Pratey_Mishpacha.MISPAR_ZEHUT =
                     Pratim_Ishiym.MISPAR_ZEHUT
              
                left join code_ezor_ovdim ezor_ovdim
                  on Pratim_Ishiym.MISRAD_AGAF = ezor_ovdim.code_ezor_ovdim
                 and code_makor = 3 -- Chinuch
              
                left join poresh porshim
                  on porshim.mispar_zehut = Pratey_Mishpacha.MISPAR_ZEHUT
              
               where nvl(Pratey_Mishpacha.Mispar_Zehut, ' ') =
                     nvl(p_mispar_zehut, ' '))
    
     loop
      bney_mishpacha_row.mispar_zehut_ben_mishpacha := r.zehut;
      bney_mishpacha_row.shem_prati                 := r.shem_prati;
      bney_mishpacha_row.taarich_leda               := r.taarich_leda;
      bney_mishpacha_row.makom_avoda                := r.mekom_avoda;
      bney_mishpacha_row.code_kirva                 := r.kirva;
      bney_mishpacha_row.seq_porshim                := r.porshim_seq;
    
      check_Bney_Mishpacha(p_mispar_zehut, bney_mishpacha_row);
    
      insert into bney_mishpacha
        (MISPAR_ZEHUT_BEN_MISHPACHA,
         SHEM_PRATI,
         TAARICH_LEDA,
         MAKOM_AVODA,
         CODE_KIRVA,
         SEQ_PORSHIM,
         seq_bney_mishpacha,
         shem_meadken_acharon)
      values
        (bney_mishpacha_row.mispar_zehut_ben_mishpacha,
         bney_mishpacha_row.shem_prati,
         bney_mishpacha_row.taarich_leda,
         bney_mishpacha_row.makom_avoda,
         bney_mishpacha_row.code_kirva,
         bney_mishpacha_row.seq_porshim,
         bney_mishpacha_seq.nextval,
         SYS_CONTEXT('USERENV','OS_USER'))
      
      log errors into ERR_BNEY_MISHPACHA REJECT LIMIT UNLIMITED;
    end loop;
  end;
