  PROCEDURE check_netuney_tik_mechushavim(p_mispar_zehut      number,
                                          err_mechushavim_row in out err_netuney_tik_mechushavim%rowtype) is
    pragma autonomous_transaction;
  begin
    --check Required fields.
    if v_code_sug_mimshak = 1 and
       err_mechushavim_row.achuz_kizba_kafuf_chelkiyut is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9031',
                            p_field_name   => 'achuz_kizba_kafuf_chelkiyut',
                            p_value        => err_mechushavim_row.achuz_kizba_kafuf_chelkiyut);
    end if;
    if v_code_sug_mimshak = 1 and
       err_mechushavim_row.chelkiyut_meshuklelet_sherut is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9031',
                            p_field_name   => 'chelkiyut_meshuklelet_sherut',
                            p_value        => err_mechushavim_row.chelkiyut_meshuklelet_sherut);
    end if;
    if v_code_sug_mimshak = 1 and
       err_mechushavim_row.tkufa_mezaka_sherut is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9031',
                            p_field_name   => 'tkufa_mezaka_sherut',
                            p_value        => err_mechushavim_row.tkufa_mezaka_sherut);
    end if;
    -- check fields format
    begin
      err_mechushavim_row.achuz_kizba_kafuf_chelkiyut := err_mechushavim_row.achuz_kizba_kafuf_chelkiyut / 100;
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9031',
                              p_field_name   => 'achuz_kizba_kafuf_chelkiyut',
                              p_value        => err_mechushavim_row.achuz_kizba_kafuf_chelkiyut);
      
    end;
  
    begin
      err_mechushavim_row.chelkiyut_meshuklelet_sherut := pk_load_mimshak.Convert_number_to_Decimal(err_mechushavim_row.chelkiyut_meshuklelet_sherut / 10);
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9031',
                              p_field_name   => 'chelkiyut_meshuklelet_sherut',
                              p_value        => err_mechushavim_row.chelkiyut_meshuklelet_sherut);
    end;
  
    begin
      err_mechushavim_row.achuz_kizba_chelkiyut_melea := round(err_mechushavim_row.achuz_kizba_kafuf_chelkiyut *
                                                               err_mechushavim_row.chelkiyut_meshuklelet_sherut,
                                                               2);
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9031',
                              p_field_name   => 'achuz_kizba_chelkiyut_melea',
                              p_value        => err_mechushavim_row.achuz_kizba_chelkiyut_melea);
    end;
  
    commit;
  end;
  ------------------------------------------------
  procedure netuney_tik_mechushavim(p_mispar_zehut varchar2,
                                    p_seq_bakasha  number) is
    netuney_tik_mechushavim_row err_netuney_tik_mechushavim%rowtype;
  begin
    for r in (select distinct PorshimChinuch.ACHUZ_KITZBA,
                              PorshimChinuch.SACH_CHODASHIM,
                              PorshimChinuch.CHELKIUT
                from ld_chinuch_9031_porshim PorshimChinuch
              
                left join ld_Chinuch_9022_Pratim_Ishiym Pratim_Ishiym
                  on PorshimChinuch.MISPAR_ZEHUT =
                     Pratim_Ishiym.MISPAR_ZEHUT
              
                left join code_ezor_ovdim ezor_ovdim
                  on Pratim_Ishiym.MISRAD_AGAF = ezor_ovdim.code_ezor_ovdim
                 and code_makor = 3 -- Chinuch
              
                left join poresh porshim
                  on porshim.mispar_zehut = PorshimChinuch.MISPAR_ZEHUT
              
               where nvl(PorshimChinuch.Mispar_Zehut, ' ') =
                     nvl(p_mispar_zehut, ' '))
    
     loop
    
      netuney_tik_mechushavim_row.achuz_kizba_kafuf_chelkiyut  := r.achuz_kitzba;
      netuney_tik_mechushavim_row.TKUFA_MEZAKA_SHERUT          := r.sach_chodashim;
      netuney_tik_mechushavim_row.CHELKIYUT_MESHUKLELET_SHERUT := r.chelkiut;
      --In the function 'check_netuney_tik_mechushavim', Add value also to 'achuz_kizba_chelkiyut_melea' field
      netuney_tik_mechushavim_row.seq_bakasha     := p_seq_bakasha;
      netuney_tik_mechushavim_row.code_department := 1;
    
      check_netuney_tik_mechushavim(p_mispar_zehut,
                                    netuney_tik_mechushavim_row);
    
      insert into netuney_tik_mechushavim
        (achuz_kizba_kafuf_chelkiyut,
         ACHUZ_KIZBA_CHELKIYUT_MELEA,
         TKUFA_MEZAKA_SHERUT,
         CHELKIYUT_MESHUKLELET_SHERUT,
         SEQ_bakasha,
         SEQ_netuney_tik_mechushavim,
         code_department,
         shem_meadken_acharon)
      values
        (netuney_tik_mechushavim_row.achuz_kizba_kafuf_chelkiyut,
         netuney_tik_mechushavim_row.achuz_kizba_chelkiyut_melea,
         netuney_tik_mechushavim_row.TKUFA_MEZAKA_SHERUT,
         netuney_tik_mechushavim_row.CHELKIYUT_MESHUKLELET_SHERUT,
         netuney_tik_mechushavim_row.seq_bakasha,
         netuney_tik_mechushavim_seq.nextval,
         netuney_tik_mechushavim_row.code_department,
         SYS_CONTEXT('USERENV','OS_USER')) log errors into err_netuney_tik_mechushavim REJECT LIMIT UNLIMITED;
    end loop;
  end;
