  procedure Tkufot_Michutz_Lasherut(p_mispar_zehut varchar2,
                                    p_seq_bakasha  number) is
    tkufot_michutz_lasharut_row err_tkufot_michutz_lasharut%rowtype;
  begin
  
    for r in (select distinct Avoda_Kodmim.TAARICH_ME,
                              Avoda_Kodmim.TAARICH_AD,
                              Avoda_Kodmim.TAARICH_HESKEM,
                              Avoda_Kodmim.Sug_Mekom_Avoda,
                              Avoda_Kodmim.KEREN_PENSIA,
                              Avoda_Kodmim.ZCHUYOT_PENSIA,
                              Avoda_Kodmim.SHEM_MAAVID
              
                from ld_chinuch_9030_avoda_kodmim Avoda_Kodmim
              
                left join ld_Chinuch_9022_Pratim_Ishiym Pratim_Ishiym
                  on Avoda_Kodmim.MISPAR_ZEHUT = Pratim_Ishiym.MISPAR_ZEHUT
              
                left join code_ezor_ovdim ezor_ovdim
                  on Pratim_Ishiym.MISRAD_AGAF = ezor_ovdim.code_ezor_ovdim
                 and code_makor = 3 -- Chinuch
              
                left join poresh porshim
                  on porshim.mispar_zehut = Avoda_Kodmim.MISPAR_ZEHUT
              
               where nvl(Avoda_Kodmim.Mispar_Zehut, ' ') =
                     nvl(p_mispar_zehut, ' ')) loop
      tkufot_michutz_lasharut_row.taarich_me           := r.taarich_me;
      tkufot_michutz_lasharut_row.taarich_ad           := r.taarich_ad;
      tkufot_michutz_lasharut_row.taarich_heskem       := r.taarich_heskem;
      tkufot_michutz_lasharut_row.code_sug_makom_avoda := r.sug_mekom_avoda;
      tkufot_michutz_lasharut_row.code_keren_pensia    := r.keren_pensia;
      tkufot_michutz_lasharut_row.code_sugey_zchuyot   := r.zchuyot_pensia;
      tkufot_michutz_lasharut_row.shem_maavid          := r.shem_maavid;
      tkufot_michutz_lasharut_row.seq_bakasha          := p_seq_bakasha;
    
      check_michutz_lasharut(p_mispar_zehut, tkufot_michutz_lasharut_row);
    
      insert into tkufot_michutz_lasharut
        (taarich_me,
         taarich_ad,
         taarich_heskem,
         code_sug_makom_avoda,
         code_keren_pensia,
         code_sugey_zchuyot,
         shem_maavid,
         seq_bakasha,
         seq_tkufot_michutz_lasharut,
         shem_meadken_acharon)
      values
        (tkufot_michutz_lasharut_row.taarich_me,
         tkufot_michutz_lasharut_row.taarich_ad,
         tkufot_michutz_lasharut_row.taarich_heskem,
         tkufot_michutz_lasharut_row.code_sug_makom_avoda,
         tkufot_michutz_lasharut_row.code_keren_pensia,
         tkufot_michutz_lasharut_row.code_sugey_zchuyot,
         tkufot_michutz_lasharut_row.shem_maavid,
         tkufot_michutz_lasharut_row.seq_bakasha,
         tkufot_michutz_lasharut_seq.nextval,
         SYS_CONTEXT('USERENV','OS_USER')) log errors into ERR_tkufot_michutz_lasharut REJECT LIMIT UNLIMITED;
    end loop;
  end;
  ------------------------------------------------
  PROCEDURE check_hagdala_nimuk(p_mispar_zehut        number,
                                err_hagdala_nimuk_row in out err_hagdala_nimuk%rowtype) is
    pragma autonomous_transaction;
  begin
    --check Required fields.
    if err_hagdala_nimuk_row.code_nimuk is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9032',
                            p_field_name   => 'code_nimuk',
                            p_value        => err_hagdala_nimuk_row.code_nimuk);
    end if;
    if err_hagdala_nimuk_row.achuz_meushar is null then
      pk_load.Insert_errors(p_mispar_zehut,
                            20001,
                            p_table_name   => '9032',
                            p_field_name   => 'achuz_meushar',
                            p_value        => err_hagdala_nimuk_row.achuz_meushar);
    end if;
    -- update format
    begin
      err_hagdala_nimuk_row.achuz_meushar := err_hagdala_nimuk_row.achuz_meushar / 100;
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '9032',
                              p_field_name   => 'achuz_meushar',
                              p_value        => err_hagdala_nimuk_row.achuz_meushar);
    end;
  
    commit;
  end;
  ------------------------------------------------
  procedure Add_row_hagdala_nimuk(p_mispar_zehut        number,
                                  p_seq_bakasha         number,
                                  v_seq_bakasha_previos number,
                                  lefy_seif             varchar2,
                                  shiur_hagdala         varchar2) is
    hagdala_nimuk_row err_hagdala_nimuk%rowtype;
  begin
    hagdala_nimuk_row.code_nimuk    := lefy_seif;
    hagdala_nimuk_row.achuz_meushar := shiur_hagdala;
  
    --update achuz kodem
    begin
      select max(hn.achuz_meushar)
        into hagdala_nimuk_row.achuz_kodem
        from hagdala_nimuk hn
       where hn.seq_bakasha = v_seq_bakasha_previos
         and hn.code_nimuk = hagdala_nimuk_row.code_nimuk;
    exception
      when no_data_found then
        hagdala_nimuk_row.achuz_kodem := null;
    end;
  
    check_hagdala_nimuk(p_mispar_zehut, hagdala_nimuk_row);
  
    insert into hagdala_nimuk
      (seq_bakasha,
       code_nimuk,
       achuz_meushar,
       achuz_kodem,
       seq_hagdala_nimuk,
       code_hagdala_status_nimuk,
       shem_meadken_acharon)
    values
      (p_seq_bakasha,
       hagdala_nimuk_row.code_nimuk,
       hagdala_nimuk_row.achuz_meushar,
       hagdala_nimuk_row.achuz_kodem,
       hagdala_nimuk_seq.nextval,
       3, -- confirm
       SYS_CONTEXT('USERENV','OS_USER') 
       ) log errors into err_hagdala_nimuk REJECT LIMIT UNLIMITED;
  end;
  ------------------------------------------------
  function is_nimuk(lefy_seif varchar2) return number is
  begin
    if nvl(lefy_seif, 0) <> 0 then
      return 1;
    else
      return 0;
    end if;
  end;
  ------------------------------------------------
  procedure Hagdalot(p_mispar_zehut        varchar2,
                     v_seq_bakasha_previos number,
                     v_seq_bakasha         number) is
  begin
  
    for r in (select distinct Tikim.seq_bakasha,
                              Hadgalot.mispar_zehut,
                              Hadgalot.zihuy_nosaf,
                              Hadgalot.taarich_hagdala,
                              Hadgalot.sherut_mugdal,
                              case Hadgalot.code_hachlata
                                when '1' then
                                 '8' --'ishur naziv'
                                when '2' then
                                 '9' --'nidcha naziv'
                                else
                                 Hadgalot.code_hachlata
                              end as code_hachlata,
                              Hadgalot.lefy_seif_1,
                              Hadgalot.shiur_hagdala_1,
                              Hadgalot.lefy_seif_2,
                              Hadgalot.shiur_hagdala_2,
                              Hadgalot.lefy_seif_3,
                              Hadgalot.shiur_hagdala_3,
                              Hadgalot.lefy_seif_4,
                              Hadgalot.shiur_hagdala_4,
                              Hadgalot.lefy_seif_5,
                              Hadgalot.shiur_hagdala_5,
                              Hadgalot.lefy_seif_6,
                              Hadgalot.shiur_hagdala_6,
                              Hadgalot.Taarich_Tchula,
                              Hadgalot.taarich_ishur,
                              porshim.porshim_seq,
                              ezor_ovdim.seq_ezor_ovdim
              
                from ld_chinuch_9032_hagdalot Hadgalot
              
                left join ld_Chinuch_9022_Pratim_Ishiym Pratim_Ishiym
                  on hadgalot.MISPAR_ZEHUT = Pratim_Ishiym.MISPAR_ZEHUT
              
                left join code_ezor_ovdim ezor_ovdim
                  on Pratim_Ishiym.MISRAD_AGAF = ezor_ovdim.code_ezor_ovdim
                 and code_makor = 3 -- Chinuch
              
                left join poresh porshim
                  on porshim.mispar_zehut = hadgalot.MISPAR_ZEHUT
              
                left join v_regila_last_status Tikim
                  on Tikim.seq_porshim = porshim.porshim_seq
                 and Tikim.SEQ_EZOR_OVDIM = ezor_ovdim.seq_ezor_ovdim
              
               where nvl(Hadgalot.Mispar_Zehut, ' ') =
                     nvl(p_mispar_zehut, ' ')) loop
    
      -- Is required at least one nimuk.  
      Add_row_hagdala_nimuk(p_mispar_zehut,
                            v_seq_bakasha,
                            v_seq_bakasha_previos,
                            r.lefy_seif_1,
                            r.shiur_hagdala_1);
    
      if nvl(r.lefy_seif_2, ' ') <> ' ' then
        Add_row_hagdala_nimuk(p_mispar_zehut,
                              v_seq_bakasha,
                              v_seq_bakasha_previos,
                              r.lefy_seif_2,
                              r.shiur_hagdala_2);
      end if;
    
      if nvl(r.lefy_seif_3, ' ') <> ' ' then
        Add_row_hagdala_nimuk(p_mispar_zehut,
                              v_seq_bakasha,
                              v_seq_bakasha_previos,
                              r.lefy_seif_3,
                              r.shiur_hagdala_3);
      end if;
    
      if nvl(r.lefy_seif_4, ' ') <> ' ' then
        Add_row_hagdala_nimuk(p_mispar_zehut,
                              v_seq_bakasha,
                              v_seq_bakasha_previos,
                              r.lefy_seif_4,
                              r.shiur_hagdala_4);
      end if;
    
      if nvl(r.lefy_seif_5, ' ') <> ' ' then
        Add_row_hagdala_nimuk(p_mispar_zehut,
                              v_seq_bakasha,
                              v_seq_bakasha_previos,
                              r.lefy_seif_5,
                              r.shiur_hagdala_5);
      end if;
    
      if nvl(r.lefy_seif_6, ' ') <> ' ' then
        Add_row_hagdala_nimuk(p_mispar_zehut,
                              v_seq_bakasha,
                              v_seq_bakasha_previos,
                              r.lefy_seif_6,
                              r.shiur_hagdala_6);
      end if;
    
    end loop;
  end;
  -----------------------------------------------
  procedure temp_script_up_to_next_version is
  begin
    update tkufot_avoda_mechushv m
       set m.seq_tkufot_michutz_lasharut = null
     where m.seq_tkufot_avoda_mechushv in
           (select m.seq_tkufot_avoda_mechushv
              from tkufot_avoda_mechushv m
              left join tkufot_michutz_lasharut l
                on m.seq_tkufot_michutz_lasharut =
                   l.seq_tkufot_michutz_lasharut
              left join v_bakasha_last_status v1
                on v1.seq_bakasha = m.seq_bakasha
              left join v_bakasha_last_status v2
                on v2.seq_bakasha = l.seq_bakasha
             where m.seq_tkufot_michutz_lasharut is not null
               and m.seq_bakasha <> l.seq_bakasha);
    commit;
  end;
  -----------------------------------------------
  procedure Loop_Over_All_Tikim(p_seq_ld_protocol number) is
    v_is_valid_load       boolean;
    v_seq_porshim         number;
    v_taarich_leda        date;
    v_taarich_ptira       date;
    v_ReceivedMustTables  varchar2(100) := null;
    v_seq_bakasha_previos number;
    v_seq_bakasha         number;
    v_code_sug_bakasha    number;
    v_machoz              number;
    v_seq_ld_log          number;
  begin
  
    if p_seq_ld_protocol is null then
      RAISE_APPLICATION_ERROR(-20000,
                              'The parameter: p_seq_ld_protocol can not equal null');
    end if;
  
    --temp
    temp_script_up_to_next_version;
  
    execute immediate 'alter session set NLS_LANGUAGE= ''AMERICAN''';
    execute immediate 'alter session set NLS_DATE_LANGUAGE=''ENGLISH''';
    execute immediate 'alter session set NLS_DATE_FORMAT=''dd-MON-yyyy''';
  
    for r in (select t.mispar_zehut, t.misrad_agaf, t1.code_sug_mimshak
                from ld_chinuch_9022_pratim_ishiym t
                left join ld_chinuch_9015_title t1
                  on t.mispar_zehut = t1.mispar_zehut
                  --zehut yaffa
                 --and t.mispar_zehut=53204780
              --Temp: not load participation 2 guf
               where nvl(t1.code_sug_mimshak, 0) <> 2
              --End temp
              
               order by t.seq) loop
      --Transaction by id
      begin
        --restart system tables
        pk_load.restart_system_tables;
        --Insert new row to ld_log
        v_seq_ld_log := pk_load.Add_row_ld_log(p_seq_ld_protocol,
                                               r.mispar_zehut);
      
        --Define code_sug_mimshak
        if r.code_sug_mimshak is not null then
          v_code_sug_mimshak := r.code_sug_mimshak;
        else
          v_code_sug_mimshak := 1;
        end if;
      
        --Restart variables for the new id
        v_is_valid_load       := true;
        v_seq_porshim         := null;
        v_seq_bakasha_previos := null;
        v_code_sug_bakasha    := null;
      
        if r.misrad_agaf <> 1099 then
          pk_load.Insert_errors(r.mispar_zehut,
                                20009,
                                null,
                                9022,
                                'misrad_agaf',
                                p_value => r.misrad_agaf);
        end if;
      
        /* must data from the next info type: 9022,9023, 9024, 9050,9031 */
        select case
                 when (select count(t2.mispar_zehut)
                         from ld_chinuch_9023_oved_poresh t2
                        where t2.mispar_zehut = r.mispar_zehut) > 0 and
                      (select count(t3.mispar_zehut)
                         from ld_chinuch_9024_ktovet_oved t3
                        where t3.mispar_zehut = r.mispar_zehut) > 0 and
                      (select count(t4.mispar_zehut)
                         from ld_chinuch_9050_tkufot_retsif t4
                        where t4.mispar_zehut = r.mispar_zehut) > 0 and
                      (select count(t5.mispar_zehut)
                         from ld_chinuch_9031_porshim t5
                        where t5.mispar_zehut = r.mispar_zehut) > 0 then
                  'Y'
                 else
                  'N'
               end
          into v_ReceivedMustTables
          from dual;
      
        if v_ReceivedMustTables = 'N' then
          pk_load.Insert_errors(r.mispar_zehut,
                                20010,
                                p_more_details => ' מסוג: 9022,9023, 9024, 9050,9031');
        end if;
      
        --Check previos bakasha
        v_seq_bakasha_previos := pk_load.Check_previos_bakasha(r.mispar_zehut,
                                                               206,
                                                               1);
      
        --When the new bakasha is first to the poresh
        if v_seq_bakasha_previos is null then
          --Load porshim
          Porshim(r.mispar_zehut);
        
          /* --Load Bney Mishpacha
          Bney_Mishpacha(r.mispar_zehut);*/
        
        end if;
      
        --Get the values whatever when it's new bakasha and when it's not.
        if pk_load_mimshak.count_rowes('ERR_Porshim') <> 0 then
          v_is_valid_load := false;
        else
          begin
            select p.porshim_seq,
                   p.taarich_leda,
                   p.taarich_ptira,
                   c.seq_code_unit
              into v_seq_porshim, v_taarich_leda, v_taarich_ptira, v_machoz
              from poresh p
              left join ld_Chinuch_9023_Oved_Poresh o
                on o.mispar_zehut = p.mispar_zehut
              left join code_unit c
                on o.machoz = c.code_unit
             where p.mispar_zehut = r.mispar_zehut;
          exception
            when OTHERS then
              v_is_valid_load := false;
          end;
        end if;
      
        if v_is_valid_load then
          --get sug mimshak
          if v_code_sug_mimshak = 2
          --if it's regular bakasha, update sug bakasha at the end of the loop.
           then
            v_code_sug_bakasha := 8;
          end if;
        
          v_seq_bakasha := Tikim(v_seq_bakasha_previos,
                                 r.mispar_zehut,
                                 v_taarich_leda,
                                 v_taarich_ptira,
                                 v_seq_porshim,
                                 v_code_sug_bakasha,
                                 v_machoz);
        
          --Update fields
          if pk_load_mimshak.count_rowes('err_bakasha_regila') <> 0 then
            v_is_valid_load := false;
          end if;
        end if;
      
        if v_is_valid_load then
        
          netuney_tik_mechushavim(r.mispar_zehut, v_seq_bakasha);
        
          tkufot_sherut_tsvaii(r.mispar_zehut, v_seq_bakasha);
        
          Tkufot_Avoda_Golmi(r.mispar_zehut, v_seq_bakasha);
        
          Tkufot_Michutz_Lasherut(r.mispar_zehut, v_seq_bakasha);
        
          Hagdalot(r.mispar_zehut, v_seq_bakasha_previos, v_seq_bakasha);
        
          darga_vederug_tik(r.mispar_zehut, v_seq_bakasha);
        
          chinuch_salary(r.mispar_zehut, v_seq_bakasha);
        
          vetek_detail(r.mispar_zehut, v_seq_bakasha);
        
          if v_code_sug_mimshak = 1 then
            v_code_sug_bakasha := pk_prm_utils.get_sug_bakasha(v_seq_bakasha);
          end if;
        
          --add calculation data
          pk_load.calculation_data(v_seq_bakasha);
        end if;
        --End load
        pk_load.In_end_load(v_seq_bakasha_previos,
                            v_seq_bakasha,
                            r.mispar_zehut,
                            v_seq_ld_log);
      exception
        when others then
          pk_load.Insert_errors(r.mispar_zehut, sqlcode, sqlerrm);
      end;
    end loop;
  end;
  -----------------------------------------------
end;
/

create or replace package body prm_system_copy.pk_chinuch_salary is
----------------------------------------------------------
function get_decimal_number(p_num number, p_digit_size number)
  return number is
begin
  if nvl(p_num, 0) > 0 then
    return p_num / power(10, p_digit_size);
  end if;
  return null;
end;
  --------------------------------------------------------
  procedure update_vetek_maskrt_ofek_kizba(p_seq_chinuch_salary_01 number,
                                           p_seq_bakasha           number,
                                           p_seq_netuney_sachar    number) is
  begin
    for r in (select t.*,t1.w nihul,t1.x yeutz,t1.y hadracha
                from ld_chinuch_salary_01 t
                left join ld_chinuch_salary_03 t1
                  on t.b = t1.b
                 and trunc(t1.load_date) = trunc(t.load_date)
                 and t1.c = 1
               where t.seq_ld_chinuch_salary_01 = p_seq_chinuch_salary_01) loop
    
      --nihol_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         7,
                                         r.nihul,
                                         p_seq_netuney_sachar);
      --yeuz_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         8,
                                         r.yeutz,
                                         p_seq_netuney_sachar);
      --hadracha_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         9,
                                         r.hadracha,
                                         p_seq_netuney_sachar);
    
      --salary seniority
     /* pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         6,
                                         r.c +
                                         Get_zahal_vetek_by_years(r.d),
                                         p_seq_netuney_sachar);*/
    
    end loop;
  end;

  --------------------------------------------------------

  function Get_zahal_vetek_by_years(p_zahal_vetek number) return number is
    v_vetek number;
  begin
    if p_zahal_vetek is not null then
      -- Divide months to years
      v_vetek := p_zahal_vetek / 12;
      --Round quarterly
      v_vetek := round(v_vetek / 25, 2) * 25;
    end if;
  
    return v_vetek;
  end;
  --------------------------------------------------------
  procedure update_vetek_detail_maskoret_1(p_seq_chinuch_salary_01 number,
                                           p_seq_bakasha           number,
                                           p_seq_netuney_sachar    number) is
  begin
    for r in (select t.*
                from ld_chinuch_salary_01 t
               where t.seq_ld_chinuch_salary_01 = p_seq_chinuch_salary_01) loop
    
      --salary seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         6,
                                         r.c +
                                         Get_zahal_vetek_by_years(r.d),
                                         p_seq_netuney_sachar);
    
      --horaha_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         1,
                                         r.c,
                                         p_seq_netuney_sachar);
    
      --zahal_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         2,
                                         Get_zahal_vetek_by_years(r.d),
                                         p_seq_netuney_sachar);
    
    end loop;
  end;
  --------------------------------------------------------
  procedure insert_tosefot(p_seq_netuney_sachar number,
                           p_code_semel_tosefet number,
                           p_sum                number,
                           p_amount             number,
                            p_percent             number) is
  begin
    if nvl(p_sum, 0) > 0 then
    
      --Insert to tosefot table
      insert into tosefot
        (seq_tosefot,
         seq_netuney_sachar,
         code_semel_tosefet,
         sum,
         amount,
         date_update,
         user_update,
         shem_meadken_acharon)
      values
        (tosefot_seq.nextval,
         p_seq_netuney_sachar,
         p_code_semel_tosefet,
         get_decimal_number(p_sum,2),
         get_decimal_number(p_amount,2),
         sysdate,
         0,
         'aa'/*SYS_CONTEXT('USERENV','OS_USER')*/);
    
    end if;
  end;
  --------------------------------------------------------
  procedure update_chinuch_salary(p_seq_ld_chinuch_salary_01 number,
                                  p_seq_bakasha              number) is
    v_date_begin_ofek date;
  begin
    for r in (select t1.*,t.r maskoret_kovaat_meshuklelet,t.ac maskoret_meshuklelet_gil_60
                from ld_chinuch_salary_03 t
                left join ld_chinuch_salary_01 t1
                 on t.b = t1.b
                 and trunc(t.load_date) = trunc(t1.load_date)
               where t1.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01
               ) loop
    
    
      merge into chinuch_salary l
      using dual
      on (l.seq_bakasha = p_seq_bakasha)
      when matched then
        update
           set l.maskoret_kovaat_meshuklelet    = get_decimal_number(r.maskoret_kovaat_meshuklelet,2),
           l.shaot_yeutz_chodesh_acharon = r.h,
           l.hekef_chanam = r.o,
           l.maskoret_kovaat_meshuklelet_60 = get_decimal_number(r.maskoret_meshuklelet_gil_60,2)
           /*,
              l.mkadem_misra_klali             = r.p,
               l.mkadem_misra                   = r.r,
               l.gmuley_hishtalmut              = r.s,
               l.kefel_toar                     = r.t,
               l.date_begin_ofek                = v_date_begin_ofek,
               l.kidum_darga_ofek               = r.w,
               l.hekef_misra_ofek               = r.aa,
               l.maskoret_kovaat_meshuklelet_60 = r.ae,
               l.tosefet_vetek_horah            = r.ab*/
        
      
      when not matched then
        insert
          ( l.maskoret_kovaat_meshuklelet,
          l.shaot_yeutz_chodesh_acharon,
          l.hekef_chanam,
          l.maskoret_kovaat_meshuklelet_60,
           /*l.mkadem_misra_klali,
           l.mkadem_misra,
           l.gmuley_hishtalmut,
           l.kefel_toar,
           l.date_begin_ofek,
           l.kidum_darga_ofek,
           l.hekef_misra_ofek,
           l.maskoret_kovaat_meshuklelet_60,
           l.tosefet_vetek_horah,*/
           l.seq_bakasha)
        values
          (get_decimal_number(r.maskoret_kovaat_meshuklelet,2),
          r.h,
          r.o,
          get_decimal_number(r.maskoret_meshuklelet_gil_60,2),
           /*r.p,
           r.r,
           r.s,
           r.t,
           v_date_begin_ofek,
           r.w,
           r.aa,
           r.ae,
           r.ab,*/
           p_seq_bakasha);
    
    end loop;
  end;
  --------------------------------------------------------
  function Get_code_semel_tosefet(v_mispar_zehut       number,
                                  v_code_semel_chinuch number,
                                  p_code_chinuch_reforma number,
                                  p_code_chinuch_alterntive number) return number is
    v_taarich_tokef     date;
    v_code_seif_prisha number;
    v_code_semel_tosefet number;
  begin
     select (v.TAARICH_PRISHA) ,
    (v.code_seif_prisha)
      into v_taarich_tokef,v_code_seif_prisha
      from v_bakasha_last_status v
     where v.mispar_zehut = v_mispar_zehut
     and v.code_sug_bakasha in (1,3,5) and v.code_action<>17
     order by v.SEQ_BAKASHA desc 
      fetch first 1 rows only;
  if v_code_seif_prisha in (171,317,117) then
    select t.date_start_zakaut-1
    into v_taarich_tokef
    from netuney_tik_mechushavim t
    left join v_bakasha_last_status v
    on t.seq_bakasha=v.seq_bakasha
    where v.mispar_zehut=v_mispar_zehut
    and v.code_sug_bakasha in (1,3,5)and v.code_action<>17
    and  t.code_department=2
    and t.mispar_misra=0
    order by t.seq_bakasha desc
    fetch first 1 rows only;
  end if;
    begin--Get semel tosefet by date prisha 
    if v_taarich_tokef >= to_date('31082020', 'ddmmyyyy') then
      select max(s.code_semel_tosefet)
        into v_code_semel_tosefet
        from code_semel_tosefet s
       where (s.semel_sikum =p_code_chinuch_alterntive||'0'||p_code_chinuch_reforma ||lpad(v_code_semel_chinuch,4,'0') and p_code_chinuch_reforma is not null
             or p_code_chinuch_reforma is null and s.code_semel_tosefet = v_code_semel_chinuch)
       and s.sug_natun = 182
       fetch first 1 rows only;
    else
      select min(s.code_semel_tosefet)
        into v_code_semel_tosefet
        from code_semel_tosefet s
       where s.semel_chinuch = v_code_semel_chinuch
       and s.sug_natun = 106;
    end if;
  exception when no_data_found then
    return null;
    end;
    return v_code_semel_tosefet;
  end;
  --------------------------------------------------------
  procedure update_tosafot(p_seq_ld_chinuch_salary_01 number,
                           p_seq_netuney_sachar       number,
                           p_type_prisha              number,
                           p_type_reforma             number,
                           p_code_alternative         number,
                           p_code_sug_maskoret number) is
    v_code_semel_tosefet number;
    v_amount             number;
   
  begin
    --Loop over all additions
    for r in (select t2.*
                from ld_chinuch_salary_02 t2
                left join ld_chinuch_salary_01 t1
                  on to_number(t2.b) = to_number(t1.b)
                 and trunc(t2.load_date) = trunc(t1.load_date)
               where t1.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01
       --for maskoret kizba chinuch sends sug_maskoret = 0
         and (t2.e) = to_char(decode(p_type_prisha,1,0,p_type_prisha))
         --for maskoret pizuim chinuch sends reforma 0
         and (t2.c) = decode(p_code_sug_maskoret,14,00,10,00, p_type_reforma)
         --for maskoret pizuim chinuch sends alterntive 0
         and (t2.d) = decode(p_code_sug_maskoret,14,0,10,0, p_code_alternative)
         and (t2.f) not in (1, 10,102)) loop
    
      --Get code_semel_tosefet
      v_code_semel_tosefet := Get_code_semel_tosefet(r.b, r.f,p_type_reforma,p_code_alternative);
    
      --When code_semel_tosefet is null
      if v_code_semel_tosefet is null then
        pk_salary_base.code_addition_not_exist(r.f, p_seq_netuney_sachar);
        --Continue to the next addition
        continue;
      end if;
      
      --tosefet hishtalmut-nipuach amount with 1.2
    if r.f in (39,249) then
       v_amount := r.j * 1.2;
       else 
         v_amount := r.j;
    end if;
      --Insert to tosefot table
      insert_tosefot(p_seq_netuney_sachar, v_code_semel_tosefet, r.i, v_amount, r.h);
    
    end loop;
  end;
  -------------------------------------------------------
  function netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01 number,
                                          p_seq_bakasha_for_insert   number,
                                          p_date_start_zakaut        date,
                                          p_code_sug_maskoret        number,
                                          p_sum_havraa               number,
                                          p_sum_bigud                number,
                                          p_is_maanak_yovel          number,
                                          p_chodashim                number,
                                          p_maskoret_kovaat          number,
                                          p_code_derug               number,
                                          p_code_darga               number,
                                          p_havraa_days              number,
                                          p_ramat_bigud              number,
                                          p_seq_reforma              number
                                          )
    return number is
    v_seq_netuney_sachar      number;
    v_type_prisha             number;
    v_type_reforma            number;
    v_count_derug_darga       number;
    v_base_salary             number;
    v_code_chinuch_alterntive number;
  begin
    if nvl(p_maskoret_kovaat, 0) = 0 then
      return null;
    end if;
  
    v_seq_netuney_sachar := netuney_sachar_seq.nextval;
  
    select nvl(t.code_chinuch_alterntive,0), t.code_chinuch_sug_maskoret
      into v_code_chinuch_alterntive, v_type_prisha
      from code_sug_maskoret t
     where t.code_sug_maskoret = p_code_sug_maskoret
    and t.code_makor=3;
  
    if p_seq_reforma is not null then
       select t.code_reforma
      into v_type_reforma
      from chinuch_reforma t
     where t.seq_chinuch_reforma = p_seq_reforma;
     end if;
  
    begin
      select sum(get_decimal_number(t2.i,2))
        into v_base_salary
        from ld_chinuch_salary_02 t2
        left join ld_chinuch_salary_01 t1
          on to_number(t2.b) = to_number(t1.b)
         and trunc(t2.load_date) = trunc(t1.load_date)
       where t1.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01
       --for maskoret kizba chinuch sends sug_maskoret = 0
         and to_number(t2.e) = to_char(decode(v_type_prisha,1,0,v_type_prisha))
         --for maskoret pizuim chinuch sends reforma 0
         and to_number(t2.c) = decode(p_code_sug_maskoret,14,00,10,00, v_type_reforma)
         --for maskoret pizuim chinuch sends alterntive 0
         and to_number(t2.d) = decode(p_code_sug_maskoret,14,0,10,0, v_code_chinuch_alterntive)
            --Get base salary
         and (t2.f) in ('0001','0010','0102');
    exception
      when others then
        v_base_salary := null;
    end;
  
    --select from code_darge in order to check that we have the codes
    --and when the codes is not exist, set null.
    select count(*)
      into v_count_derug_darga
      from code_darga d
     where d.code_derug = p_code_derug
       and d.code_darga = p_code_darga;
  
    insert into netuney_sachar
      (seq_netuney_sachar,
       seq_bakasha,
       mispar_misra,
       code_sug_maskoret,
       sum_havraa,
       sum_bigud,
       is_maanak_yovel,
       chodashim,
       maskoret_kovaat,
       code_derug,
       code_darga,
       date_update,
       user_update,
       from_date,
       schar_ysod,
       havraa_days,
       ramat_bigud,
       seq_chinuch_reforma,
       shem_meadken_acharon)
    values
      (v_seq_netuney_sachar,
       p_seq_bakasha_for_insert,
       --The next value is temp in order to compare 2 same rows
       --And will updated in end
       99,
       p_code_sug_maskoret,
       p_sum_havraa,
       p_sum_bigud,
       p_is_maanak_yovel,
       p_chodashim,
       p_maskoret_kovaat,
       case when v_count_derug_darga > 0 then p_code_derug else null end,
       case when v_count_derug_darga > 0 then p_code_darga else null end,
       sysdate,
       0,
       p_date_start_zakaut,
       v_base_salary,
       p_havraa_days,
       p_ramat_bigud,p_seq_reforma,
       'aa'/*SYS_CONTEXT('USERENV','OS_USER')*/);
  
    update_tosafot(p_seq_ld_chinuch_salary_01,
                   v_seq_netuney_sachar,
                   v_type_prisha,
                   v_type_reforma,
                   v_code_chinuch_alterntive,
                   p_code_sug_maskoret);
  
    return v_seq_netuney_sachar;
  end;
  --------------------------------------------------------
  procedure insert_extra_to_maskoret_kovaat(p_seq_netuney_sachar number,
                                            p_sum_to_add         number) is
  begin
    update netuney_sachar n
       set n.maskoret_kovaat = round(n.maskoret_kovaat + p_sum_to_add, 2)
     where n.seq_netuney_sachar = p_seq_netuney_sachar;
  end;
  --------------------------------------------------------
  procedure insert_extra_to_addition_chinuch(p_seq_tosefet number,
                                             p_sum_to_add  number) is
  begin
    update tosefot n
       set n.sum = round(n.sum + p_sum_to_add, 2)
     where n.seq_tosefot = p_seq_tosefet;
  end;
  --------------------------------------------------------
  function Calc_extra_addition_education(p_seq_netuney_sachar number,
                                         p_orginal_sum        number)
    return number is
    v_factor            number;
    v_achuz_kizba       number;
    v_chelkiyut_sofit   number;
    v_code_sug_maskoret number;
  begin
    select n.code_sug_maskoret
      into v_code_sug_maskoret
      from netuney_sachar n
     where n.seq_netuney_sachar = p_seq_netuney_sachar;
  
    if v_code_sug_maskoret = 1 then
    
      select n2.achuz_kizba_sofi, n2.chelkiyut_sofit
        into v_achuz_kizba, v_chelkiyut_sofit
        from netuney_sachar n
        left join (select max(v.seq_bakasha) seq_bakasha,
                          v.current_seq_bakasha
                     from v_mechushavim_2_curnt_and_prev v
                    where v.code_department = 2
                    group by v.current_seq_bakasha) v
          on v.current_seq_bakasha = n.seq_bakasha
        left join netuney_tik_mechushavim n2
          on v.seq_bakasha = n2.seq_bakasha
         and n2.code_department = 2
         and n2.mispar_misra = 0
       where n.seq_netuney_sachar = p_seq_netuney_sachar;
    
    elsif v_code_sug_maskoret = 2 then
    
      select n2.achuz_kizba_gil_60,
             --Get chelkiyut
             case
               when n2.code_group_prisha = 2 and n2.is_zakai_lmaanak = 1 then
                n2.chelkiyut_meshuklelet_sherut
               else
                n2.chelkiyut_sofit
             end
        into v_achuz_kizba, v_chelkiyut_sofit
        from netuney_sachar n
        left join (select max(v.seq_bakasha) seq_bakasha,
                          v.current_seq_bakasha
                     from v_mechushavim_2_curnt_and_prev v
                    where v.code_department = 2
                    group by v.current_seq_bakasha) v
          on v.current_seq_bakasha = n.seq_bakasha
        left join netuney_tik_mechushavim n2
          on v.seq_bakasha = n2.seq_bakasha
         and n2.code_department = 2
         and n2.mispar_misra = 0
       where n.seq_netuney_sachar = p_seq_netuney_sachar;
    end if;
  
    v_factor := least(greatest(nvl(v_achuz_kizba, 0), 70) / 70 *
                      nvl(v_chelkiyut_sofit, 0),
                      1);
  
    if v_factor = 0 then
      return 0;
    end if;
  
    return(p_orginal_sum / round(v_factor, 4))
    --Get only the extra
    - p_orginal_sum;
  end;

  --------------------------------------------------------
  function calc_complement_ofek_a(p_maskoret_kovaat_meshukll_old number,
                                  p_maskoret_kovaat_old          number)
    return number is
  begin
    return nvl(p_maskoret_kovaat_meshukll_old, 0) - nvl(p_maskoret_kovaat_old,
                                                        0);
  end;

  --------------------------------------------------------
  function calc_complement_ofek_b(p_seq_netuney_sachar   number,
                                  p_orginal_sum_tosefet  number,
                                  p_maskoret_kovaat_old  number,
                                  p_chodashim_old        number,
                                  p_maskoret_kovaat_ofek number,
                                  p_chodashim_ofek       number)
    return number is
    v_calc_maskoret_kovaat_old number;
    v_total_chodashim          number;
    v_partial_maskoret_old     number;
    v_partial_maskoret_ofek    number;
    v_total_maskoret           number;
    v_extra_addition           number;
  begin
    v_extra_addition := Calc_extra_addition_education(p_seq_netuney_sachar,
                                                      p_orginal_sum_tosefet);
  
    v_calc_maskoret_kovaat_old := nvl(v_extra_addition, 0) +
                                  nvl(p_maskoret_kovaat_old, 0);
  
    v_total_chodashim := nvl(p_chodashim_old, 0) + nvl(p_chodashim_ofek, 0);
  
    v_partial_maskoret_old := v_calc_maskoret_kovaat_old * p_chodashim_old /
                              v_total_chodashim;
  
    v_partial_maskoret_ofek := p_maskoret_kovaat_ofek * p_chodashim_ofek /
                               v_total_chodashim;
  
    v_total_maskoret := v_partial_maskoret_old + v_partial_maskoret_ofek;
  
    return round(v_total_maskoret - v_calc_maskoret_kovaat_old, 2);
  end;

  --------------------------------------------------------
  procedure insert_tosefot_complement_ofek(p_seq_netuney_sachar           number,
                                           p_maskoret_kovaat_meshukll_old number,
                                           p_maskoret_kovaat_old          number,
                                           p_chodashim_old                number,
                                           p_maskoret_kovaat_ofek         number,
                                           p_chodashim_ofek               number) is
    v_sum_tosefet_chinuch           number;
    v_extra_tosefet_complement_ofek number;
    v_extra_tosefet_chinuch         number;
    v_seq_tosefet                   number;
    v_code_sug_maskoret             number;
  begin
  
    begin
      select n.code_sug_maskoret, t.seq_tosefot, t.sum
        into v_code_sug_maskoret, v_seq_tosefet, v_sum_tosefet_chinuch
        from tosefot t
        left join netuney_sachar n
          on t.seq_netuney_sachar = n.seq_netuney_sachar
       where t.seq_netuney_sachar = p_seq_netuney_sachar
         and t.code_semel_tosefet in (3073, 3074);
    exception
      when others then
        v_sum_tosefet_chinuch := null;
    end;
  
    if v_sum_tosefet_chinuch is null then
      v_extra_tosefet_complement_ofek := calc_complement_ofek_a(p_maskoret_kovaat_meshukll_old,
                                                                p_maskoret_kovaat_old);
    else
      v_extra_tosefet_complement_ofek := calc_complement_ofek_b(p_seq_netuney_sachar,
                                                                v_sum_tosefet_chinuch,
                                                                p_maskoret_kovaat_old,
                                                                p_chodashim_old,
                                                                p_maskoret_kovaat_ofek,
                                                                p_chodashim_ofek);
    
      if v_code_sug_maskoret = 2 then
        --Calc extra tosefet chinuch
        v_extra_tosefet_chinuch := Calc_extra_addition_education(p_seq_netuney_sachar,
                                                                 v_sum_tosefet_chinuch);
        --update tosefet chinuch
        insert_extra_to_addition_chinuch(v_seq_tosefet,
                                         v_extra_tosefet_chinuch);
      
        --update maskoret  
        insert_extra_to_maskoret_kovaat(p_seq_netuney_sachar,
                                        v_extra_tosefet_chinuch);
      end if;
    end if;
  
    --insert tosefet
    insert_tosefot(p_seq_netuney_sachar,
                   879,
                   v_extra_tosefet_complement_ofek,
                   null,
                   null);
    --update maskoret  
    insert_extra_to_maskoret_kovaat(p_seq_netuney_sachar,
                                    v_extra_tosefet_complement_ofek);
  end;
  --------------------------------------------------------
  function is_get_new_salary(p_seq_bakasha_for_compare number,
                             p_seq_bakasha_for_insert  number) return number is
    v_is_get_new_salary number :=1;
    v_count_rows_new number;
    v_exists_netuney_sachar number;
    v_odef                  number;
  
  begin
    
  --there is no netuney sachar in p_seq_bakasha_for_compare
  select count(*)
  into v_exists_netuney_sachar 
  from netuney_sachar n
  where n.seq_bakasha=p_seq_bakasha_for_compare;
  
  --if there is odef-check maskoret pizuim
 select nvl(sum( nvl(v.odef_sherut_chodashim,0)+nvl(v.odef_sherut_yamim,0)),0)
 into v_odef
 from bakasha b
 left join v_prisha_last_zakaut tt
 on b.seq_prisha=tt."SEQ_PRISHA"
 left join netuney_tik_mechushavim v
 on v.seq_bakasha=tt."SEQ_BAKASHA_ZAKAUT"
 where b.seq_bakasha=p_seq_bakasha_for_insert
 and v.mispar_misra=0 and v.code_department=2;
 
 
 v_is_get_new_salary:=0;
 --compare maskoret_kovaat
 
    select count(*)
      into v_count_rows_new
      from (select t1.code_reforma, t.maskoret_kovaat
              from netuney_sachar t
              left join chinuch_reforma t1
                on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
             where t.seq_bakasha = p_seq_bakasha_for_compare
               and (p_seq_bakasha_for_compare <> p_seq_bakasha_for_insert or
                   t.mispar_misra = 99)
                  
               and (t.code_sug_maskoret <> 14)
            minus
            select t1.code_reforma, t.maskoret_kovaat
              from netuney_sachar t
              left join chinuch_reforma t1
                on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
             where t.seq_bakasha = p_seq_bakasha_for_insert
               and (p_seq_bakasha_for_compare <> p_seq_bakasha_for_insert or
                   t.mispar_misra = 0)
               and (t.code_sug_maskoret <> 14)
            
            );
   
    if v_exists_netuney_sachar = 0 or nvl(v_count_rows_new, 0) > 0 then
        v_is_get_new_salary:=1;
    else 
      --check havara bigud
        select count(*)
          into v_count_rows_new
          from (select t1.code_reforma,
                       t.havraa_days,
                       t.sum_bigud,
                       t.ramat_bigud,
                       t.is_maanak_yovel
                  from netuney_sachar t
                  left join chinuch_reforma t1
                    on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
                 where t.seq_bakasha = p_seq_bakasha_for_compare
                   and (p_seq_bakasha_for_compare <> p_seq_bakasha_for_insert or
                       t.mispar_misra = 99)
                   and (t.code_sug_maskoret <> 14)
                minus
                select t1.code_reforma,
                       t.havraa_days,
                       t.sum_bigud,
                       t.ramat_bigud,
                       t.is_maanak_yovel
                  from netuney_sachar t
                  left join chinuch_reforma t1
                    on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
                 where t.seq_bakasha = p_seq_bakasha_for_insert
                   and (p_seq_bakasha_for_compare <> p_seq_bakasha_for_insert or
                       t.mispar_misra = 0)
                   and (t.code_sug_maskoret <> 14)
                
                );
            if nvl(v_count_rows_new, 0) > 0 then
               v_is_get_new_salary:=2;
            end if;
        --check odef
          if v_odef>0 then
          select count(*)
            into v_count_rows_new
            from (select t1.code_reforma, t.maskoret_kovaat
                    from netuney_sachar t
                    left join chinuch_reforma t1
                      on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
                   where t.seq_bakasha = p_seq_bakasha_for_compare
                     and (p_seq_bakasha_for_compare <> p_seq_bakasha_for_insert or
                         t.mispar_misra = 99)
                        
                     and (t.code_sug_maskoret = 14)
                  minus
                  select t1.code_reforma, t.maskoret_kovaat
                    from netuney_sachar t
                    left join chinuch_reforma t1
                      on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
                   where t.seq_bakasha = p_seq_bakasha_for_insert
                     and (p_seq_bakasha_for_compare <> p_seq_bakasha_for_insert or
                         t.mispar_misra = 0)
                     and (t.code_sug_maskoret = 14)
                  
                  );
           if v_count_rows_new > 0 then
             v_is_get_new_salary:=3;
            end if;
       end if;
       
      end if;
        
                

    
    if nvl(v_is_get_new_salary, 0) = 0 then
      return 0;
    else
      return v_is_get_new_salary;
    end if;
  end;

  --------------------------------------------------------
  procedure fix_hachshara(p_seq_bakasha number) is
    v_seq_tosefot_hachshara number;
  begin
    select t.seq_tosefot
      into v_seq_tosefot_hachshara
      from tosefot t
      left join netuney_sachar n
        on t.seq_netuney_sachar = n.seq_netuney_sachar
     where n.seq_bakasha = p_seq_bakasha
       and t.code_semel_tosefet = 865
       and n.code_sug_maskoret = 1;
  
    update tosefot t
       set t.amount = 100
     where t.seq_tosefot = v_seq_tosefot_hachshara;
    commit;
  exception
    when others then
      return;
  end;
  --------------------------------------------------------
  procedure fix_hadracha(p_seq_bakasha number) is
    v_amount_tosefet_hadracha_ofek number;
    v_years_vetek_hadracha_ofek    number;
    v_percent_by_years_vetek       number;
    v_percent_by_amount_tosefet    number;
  
    v_seq_tosefet_old_world number;
  begin
    select t1.amount, v.years
      into v_amount_tosefet_hadracha_ofek, v_years_vetek_hadracha_ofek
      from tosefot t1
      left join netuney_sachar n1
        on t1.seq_netuney_sachar = n1.seq_netuney_sachar
      left join vetek_detail v
        on n1.seq_netuney_sachar = v.seq_netuney_sachar
          --vetek hadracha
       and v.code_type_vetek = 9
     where n1.seq_bakasha = p_seq_bakasha
          --tosefet hadracha
       and t1.code_semel_tosefet = 524
          --maskoret ofek
       and n1.code_sug_maskoret = 3;
  
    --Get percent by years vetek
    select v.percent
      into v_percent_by_years_vetek
      from perm_guidance_vetek_years v
     where v.years_in_ofek = case
             when v_years_vetek_hadracha_ofek > 13 then
              13
             else
              v_years_vetek_hadracha_ofek
           end;
  
    --Get multiplication by amount tosefet
    select t.multiplication
      into v_percent_by_amount_tosefet
      from perm_guidance_tosefet_amount t
     where t.amount_in_ofek = v_amount_tosefet_hadracha_ofek;
  
    --Get seq_tosefet old_world
    select t1.seq_tosefot
      into v_seq_tosefet_old_world
      from tosefot t1
      left join netuney_sachar n1
        on t1.seq_netuney_sachar = n1.seq_netuney_sachar
     where n1.seq_bakasha = p_seq_bakasha
          --hadracha
       and t1.code_semel_tosefet = 524
       and n1.code_sug_maskoret = 1;
  
    --Update new amount in old world
    update tosefot t
       set t.amount = round(v_percent_by_years_vetek *
                            v_percent_by_amount_tosefet / 100,
                            2)
     where t.seq_tosefot = v_seq_tosefet_old_world;
    commit;
  
    fix_hachshara(p_seq_bakasha);
  exception
    when others then
      return;
  end;

  --------------------------------------------------------
  procedure fix_Special_Education(p_seq_bakasha number) is
    v_fix_amount_old_world  number := 0;
    v_seq_tosefet_old_world number;
  begin
    --Loop over additions new world
    for r in (select n.schar_ysod, t.sum
                from tosefot t
                left join netuney_sachar n
                  on t.seq_netuney_sachar = n.seq_netuney_sachar
               where n.seq_bakasha = p_seq_bakasha
                 and t.code_semel_tosefet in (133, 134, 135, 136)
                 and n.code_sug_maskoret = 3) loop
      v_fix_amount_old_world := v_fix_amount_old_world +
                                (r.sum / r.schar_ysod * 100);
    end loop;
  
    begin
      --Get seq_tosefet old_world
      select t1.seq_tosefot
        into v_seq_tosefet_old_world
        from tosefot t1
        left join netuney_sachar n1
          on t1.seq_netuney_sachar = n1.seq_netuney_sachar
       where n1.seq_bakasha = p_seq_bakasha
         and t1.code_semel_tosefet = 28
         and n1.code_sug_maskoret = 1;
    
      --Update Special Education in old world addition
      update tosefot t
         set t.amount = round(v_fix_amount_old_world, 2)
       where t.seq_tosefot = v_seq_tosefet_old_world;
    
      commit;
    exception
      when others then
        return;
    end;
  end;
  --------------------------------------------------------
  procedure fix_tosafot_old_world(p_seq_bakasha number) is
  begin
    fix_Special_Education(p_seq_bakasha);
    fix_hadracha(p_seq_bakasha);
  end;
  --------------------------------------------------------
  procedure update_mispar_misra(p_seq_bakasha number) is
  begin
    update netuney_sachar n
       set n.mispar_misra = 0
     where n.mispar_misra = 99
       and n.seq_bakasha = p_seq_bakasha;
  end;
  --------------------------------------------------------
  function update_netuney_sachar(p_seq_ld_chinuch_salary_01 number,
                                 p_seq_bakasha_for_compare  number,
                                 p_seq_bakasha_for_insert   number)
    return number is
  v_is_get_new_salary number;
  v_mispar_zehut number;
  begin
    update_reforma(p_seq_bakasha_for_insert,
                   p_seq_ld_chinuch_salary_01);
    update_mitve_nur(p_seq_bakasha_for_insert,
                   p_seq_ld_chinuch_salary_01);         
    update_chinuch_salary(p_seq_ld_chinuch_salary_01,
                              p_seq_bakasha_for_insert);
   
      --update mispar misra
      update_mispar_misra(p_seq_bakasha_for_insert);
      --Fix tosafot old world
     -- fix_tosafot_old_world(p_seq_bakasha_for_insert);
     select to_number(t.b) into v_mispar_zehut
     from ld_chinuch_salary_01 t
     where t.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01;
     old_world(p_seq_bakasha_for_insert,v_mispar_zehut);
  --  end if;
  
    return v_is_get_new_salary;
  end;
  -------------------------------------------------
procedure old_world(p_seq_bakasha number, p_mispar_zehut number) is
  v_seq_netuney_sachar    number;
  code_semel_hamara       number;
  v_is_old_world          number;
  v_extra_tosefet_chinuch number;
  v_seq_tosefet           number;
  v_sum_tosefet_chinuch   number;
  v_code_seif_prisha      number;
  v_taarich_tokef         date;
begin
  begin
    select max(cr.code_reforma) code_reforma
      into v_is_old_world
      from CHINUCH_REFORMA cr
      join bakasha b
        on b.seq_bakasha = cr.seq_bakasha
     where cr.seq_bakasha = p_seq_bakasha
     group by cr.seq_bakasha
    having count(*) = 1;
  
    if v_is_old_world = 4 then
      begin
      
        update netuney_sachar ns
           set ns.seq_chinuch_reforma = null
         where ns.seq_bakasha = p_seq_bakasha;
      
        delete from chinuch_reforma cr
         where cr.seq_bakasha = p_seq_bakasha;
      
        delete from CHINUCH_MITVE_NUR mn
         where mn.seq_bakasha = p_seq_bakasha;
      
        update netuney_sachar ns
           set ns.code_sug_maskoret = case ns.code_sug_maskoret
                                        when 5 then
                                         1
                                        when 6 then
                                         2
                                      end
         where ns.seq_bakasha = p_seq_bakasha
           and ns.code_sug_maskoret in (5, 6);
        v_seq_netuney_sachar := null;
        /* select max(ns.seq_netuney_sachar)
          into v_seq_netuney_sachar
          from netuney_sachar ns
         where ns.seq_bakasha = p_seq_bakasha
           and ns.code_sug_maskoret = 14;
        if v_seq_netuney_sachar is not null then
          update netuney_sachar n
             set n.kovaat_161 =
                 (select ns.maskoret_kovaat
                    from netuney_sachar ns
                   where ns.seq_bakasha = p_seq_bakasha
                     and ns.code_sug_maskoret = 14)
           where n.seq_bakasha = p_seq_bakasha
             and n.code_sug_maskoret = 1;
        
          delete from vetek_detail v
           where v.seq_netuney_sachar = v_seq_netuney_sachar;
          delete from tosefot t
           where t.seq_netuney_sachar = v_seq_netuney_sachar;
          delete from netuney_sachar t
           where t.seq_netuney_sachar = v_seq_netuney_sachar;
          v_seq_netuney_sachar := null;
        end if;*/
      
        select (v.TAARICH_PRISHA), (v.code_seif_prisha)
          into v_taarich_tokef, v_code_seif_prisha
          from v_bakasha_last_status v
         where v.mispar_zehut = p_mispar_zehut
           and v.code_sug_bakasha in (1, 3, 5)
           and v.code_action <> 17
         order by v.SEQ_BAKASHA desc
         fetch first 1 rows only;
        if v_code_seif_prisha in (171, 317, 117) then
          select t.date_start_zakaut - 1
            into v_taarich_tokef
            from netuney_tik_mechushavim t
            left join v_bakasha_last_status v
              on t.seq_bakasha = v.seq_bakasha
           where v.mispar_zehut = p_mispar_zehut
             and v.code_sug_bakasha in (1, 3, 5)
             and v.code_action <> 17
             and t.code_department = 2
             and t.mispar_misra = 0
           order by t.seq_bakasha desc
           fetch first 1 rows only;
        end if;
      
        if v_taarich_tokef >= to_date('31082020', 'ddmmyyyy') then
        
          for s in (select ns.seq_netuney_sachar, ns.code_sug_maskoret
                    --into v_seq_netuney_sachar
                      from netuney_sachar ns
                     where ns.seq_bakasha = p_seq_bakasha
                       and ns.code_sug_maskoret in (1, 2)) loop
          
            update tosefot t
               set t.code_semel_tosefet =
                   (select st.code_semel_hamara
                      from code_semel_tosefet st
                     where st.code_semel_tosefet = t.code_semel_tosefet
                       and st.sug_natun = 182
                       and st.code_reforma = 4
                       and st.code_chinuch_alterntive = 1)
             where t.seq_netuney_sachar = s.seq_netuney_sachar;
          
            if s.code_sug_maskoret = 2 then
              for tt in (select n.code_sug_maskoret,
                                t.seq_tosefot,
                                t.sum sum_tosefet_chinuch
                         --into v_code_sug_maskoret, v_seq_tosefet, v_sum_tosefet_chinuch
                           from tosefot t
                           left join netuney_sachar n
                             on t.seq_netuney_sachar = n.seq_netuney_sachar
                          where t.seq_netuney_sachar = s.seq_netuney_sachar
                            and t.code_semel_tosefet in (859, 1123)) loop
                --Calc extra tosefet chinuch
                v_extra_tosefet_chinuch := Calc_extra_addition_education(s.seq_netuney_sachar,
                                                                         tt.sum_tosefet_chinuch);
                --update tosefet chinuch
                insert_extra_to_addition_chinuch(tt.seq_tosefot,
                                                 v_extra_tosefet_chinuch);
              
                --update maskoret  
                insert_extra_to_maskoret_kovaat(s.seq_netuney_sachar,
                                                v_extra_tosefet_chinuch);
              end loop;
            end if;
          end loop;
        end if;
      end;
    end if;
  exception
    when no_data_found then
      return;
  end;
end;
  ------------------------------------------------
  procedure update_reforma(p_seq_bakasha              number,
                           p_seq_ld_chinuch_salary_01 number) is
    v_seq_chinuch_reforma number;
    v_code_derug          number;
    v_code_darga          number;
    v_code_darga_mimshak          number;
    v_exist_ofek number;
  begin
  
    for r in (select s.*,case when s.c in (3,4) then s1.p when s1.c=2then s1.q else null end gmulim_before_prisha,case when s.c=1 then s1.o else null end as mikdama,s1.r as darga_mimshak
                from ld_chinuch_salary_03 s
                left join ld_chinuch_salary_01 s1
                  on s.b = s1.b
                 and trunc(s1.load_date) = trunc(s.load_date)
               where s1.seq_ld_chinuch_salary_01 =
                     p_seq_ld_chinuch_salary_01
                     order by s.c) loop
  
      if r.c = 1 then
      v_exist_ofek :=1;  
      end if;
      
      v_seq_chinuch_reforma := chinuch_reforma_seq.nextval;  
    
    
     insert into chinuch_reforma
        (seq_chinuch_reforma,
       seq_bakasha,
       code_reforma,
       begin_date,
       factor,
       is_last_year,
       code_chinuch_alterntive,
       max_sum,
       months_a,
       months_b,
       gmulim_before_reforma_f,
       gmulim_before_prisha,
       mekadem_2_3,
       mispar_kidumim,
       murkavut,
       shanim_reforma,
       chodashim_mikdama,
       shem_meadken_acharon
       )
      values
        (v_seq_chinuch_reforma,
         p_seq_bakasha,
         r.c,
         case when r.z > 0 then to_date(r.z,'ddmmyyyy')else null end,
         get_decimal_number(r.q,4),
         case when nvl(r.ad,0)>0 then 1 else 0 end,
         case when to_number(r.c)=4 then 1 else to_number(r.d) end,
         get_decimal_number(r.p,2),
         case when r.c=1 or r.c=2 and v_exist_ofek = 1 then r.an else r.e end,
         case when r.c=1 or r.c=2 and v_exist_ofek = 1 then r.ao else r.f end,
         r.s,
         r.gmulim_before_prisha,
         r.t,
         get_decimal_number(r.u,1),
         r.ag,
         get_decimal_number(r.v,2),
         r.mikdama,
         'aa'/*SYS_CONTEXT('USERENV','OS_USER')*/);
    
      --derug and darga 
    /*if r.c <>1 or r.d = 2 then*/
    v_code_darga_mimshak:=r.af;
    if r.c = 1  then
      v_code_darga_mimshak:=r.darga_mimshak;
    end if;
      select dc.code_darge, dc.code_derug
        into v_code_darga, v_code_derug
        from code_darga_chinuch_salary dc
       where dc.code_derug_chinuch_salary = 41
         and dc.code_darga_chinuch_salary = v_code_darga_mimshak;
     /*else--derug for ofek sachar acharon, alays begin 99
       select dc.code_darga, dc.code_derug
         into v_code_darga, v_code_derug
         from code_darga dc
        where dc.code_derug = r.ae + 99000
          and dc.code_darga = r.af;
     end if;*/
      update_netuney_sachar_for_rfrm(p_seq_ld_chinuch_salary_01,
                                     r.seq_ld_chinuch_salary_03,
                                     v_seq_chinuch_reforma,
                                     p_seq_bakasha,
                                     v_code_darga,
                                     v_code_derug,
                                     r.c,
                                     r.d,
                                     v_exist_ofek);
                                     
    update_bakarot(p_seq_bakasha,
                   p_seq_ld_chinuch_salary_01,
                   v_seq_chinuch_reforma,
                   r.c)  ;  
                   old_world(p_seq_bakasha,to_number(r.b));                                  
    end loop;
  end;
  --------------------------------------------------------
  procedure update_netuney_sachar_for_rfrm(p_seq_ld_chinuch_salary_01 number,
                                           p_seq_ld_chinuch_salary_03 number,
                                           p_seq_chinuch_reforma      number,
                                           p_seq_bakasha              number,
                                           p_code_darga               number,
                                           p_code_derug               number,
                                           p_code_reforma             number,
                                           p_code_chosen_alterntive   number,
                                           p_exists_ofek              number) is
    v_seq_netuney_sachar    number;
    v_seq_netuney_sachar_60 number;
    v_seq_netuney_sachar_pizuim number;
    v_date_start_zakaut     date;
    v_code_sug_maskoret     number;
    v_sum_havraa            number;
    v_sum_bigud             number;
    v_is_maanak_yovel       number;
    v_havraa_days           number;
    v_ramat_bigud           number;
    v_maskoret_gil_60       number;
    v_sug_maskoret_gil_60   number;
    v_maskoret_pizuim   number;
    v_chodashim_gil_60      number;
    v_exists_pizuim         number;
    v_vetek_horaa number;
    v_vetek_gil_60          number;
    v_vetek_ofek_gil_60          number;
    v_derug_ofek                 number;
    v_darga_ofek                 number;
    cursor r1 is
      select *
        from ld_chinuch_salary_01 t
       where t.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01;
  
    r r1%ROWTYPE;
  
  
  begin
  
   
    select r.e, r.f, r.g, r.l, r.m,r.c,r.k,r.j
      into v_sum_havraa,
           v_sum_bigud,
           v_is_maanak_yovel,
           v_havraa_days,
           v_ramat_bigud,
           v_vetek_horaa,
           v_vetek_gil_60,
           v_vetek_ofek_gil_60
      from ld_chinuch_salary_01 r
     where r.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01;
  
  
  v_date_start_zakaut := pk_salary_base.get_start_zakaut(p_seq_bakasha);
  
    for c in(select *
        from ld_chinuch_salary_03 t
       where t.seq_ld_chinuch_salary_03 = p_seq_ld_chinuch_salary_03
         and t.c = p_code_reforma)loop
    
  
    --sachar acharon kizba
    if nvl(c.m, 0) <> 0 then
    if p_code_reforma = 1 then
      select dc.code_darga, dc.code_derug
         into v_darga_ofek, v_derug_ofek
         from code_darga dc
        where dc.code_derug = c.ae + 99000
          and dc.code_darga = c.af;
    end if;
      v_seq_netuney_sachar := netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01,
                                                             p_seq_bakasha,
                                                             v_date_start_zakaut,
                                                             5,
                                                             v_sum_havraa,
                                                             v_sum_bigud,
                                                             v_is_maanak_yovel,
                                                             case when c.c=1 or c.c=2 and p_exists_ofek = 1 then c.ao else c.f end, --chodashim reforma b
                                                             get_decimal_number(c.m,2), --maskoret kovaat reforma chalufa 2 tkufot
                                                             case when p_code_reforma <> 1 then p_code_derug else v_derug_ofek end,
                                                             case when p_code_reforma <> 1 then p_code_darga else v_darga_ofek end,
                                                             v_havraa_days,
                                                             v_ramat_bigud,
                                                             p_seq_chinuch_reforma
                                                             );
    end if;
  
    update netuney_sachar t
       set t.maskoret_kovaat_sum            = get_decimal_number(c.j,2),
           t.maskoret_kovaat_percent        = get_decimal_number(c.k,2),
           t.maskoret_kovaat_shiur_miztaber = get_decimal_number(c.l,2)
     where t.seq_netuney_sachar = v_seq_netuney_sachar;
  
    ---vetek
    if nvl(v_seq_netuney_sachar, 0) <> 0 then
      --vetek not for ofek
      
        update_vetek_detail_maskoret_1(p_seq_ld_chinuch_salary_01,
                                       p_seq_bakasha,
                                       v_seq_netuney_sachar);
     if p_code_reforma = 1 then 
        --vetek for 
        update_vetek_maskrt_ofek_kizba(p_seq_ld_chinuch_salary_01,
                                       p_seq_bakasha,
                                      v_seq_netuney_sachar);
      end if;
    end if;
  
    --reshet bitachon
    if nvl(c.o, 0) <> 0 then
      --maskoret kovaat chalufa
      v_seq_netuney_sachar := netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01,
                                                             p_seq_bakasha,
                                                             v_date_start_zakaut,
                                                             8,
                                                             v_sum_havraa,
                                                             v_sum_bigud,
                                                             v_is_maanak_yovel,
                                                             case when c.c=1 or c.c=2 and p_exists_ofek = 1 then c.ao else c.f end, --chodashim reforma b
                                                             get_decimal_number(c.o,2), --maskoret kovaat reforma chalufa reshet bitachon
                                                             p_code_derug,
                                                             p_code_darga,
                                                             v_havraa_days,
                                                             v_ramat_bigud,
                                                             p_seq_chinuch_reforma);
      if v_seq_netuney_sachar is not null then
        update netuney_sachar t
           set t.maskoret_kovaat_tosefet = get_decimal_number(c.n,2)
         where t.seq_netuney_sachar = v_seq_netuney_sachar;
      
        
          update_vetek_detail_maskoret_1(p_seq_ld_chinuch_salary_01,
                                         p_seq_bakasha,
                                         v_seq_netuney_sachar);
        
        if p_code_reforma = 1 then
        
          --vetek for 
          update_vetek_maskrt_ofek_kizba(p_seq_ld_chinuch_salary_01,
                                         p_seq_bakasha,
                                         v_seq_netuney_sachar);
        end if;
      end if;
    end if;
  
    --maskoret gil 60 by alternative
    if p_code_chosen_alterntive = 1 or p_code_reforma = 4 then
      v_sug_maskoret_gil_60 := 6;
      v_maskoret_gil_60 := get_decimal_number(c.ak,2);
    elsif p_code_chosen_alterntive = 2 then
      v_sug_maskoret_gil_60 := 9;
      v_maskoret_gil_60 := get_decimal_number(c.al,2);
    end if;
  
    if nvl(c.ac, 0) <> 0 then
      v_seq_netuney_sachar_60 := netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01,
                                                                p_seq_bakasha,
                                                                v_date_start_zakaut,
                                                                v_sug_maskoret_gil_60,
                                                                v_sum_havraa,
                                                                v_sum_bigud,
                                                                v_is_maanak_yovel,
                                                                c.aj , --chodashim reforma gil 60
                                                                v_maskoret_gil_60, --maskoret kovaat gil 60 
                                                                case when p_code_reforma <> 1 or p_code_chosen_alterntive <> 1 then p_code_derug else v_derug_ofek end,
                                                                case when p_code_reforma <> 1 or p_code_chosen_alterntive <> 1 then p_code_darga else v_darga_ofek end,
                                                                v_havraa_days,
                                                             v_ramat_bigud,
                                                                p_seq_chinuch_reforma);
    
      if v_seq_netuney_sachar_60 is not null then      
          update netuney_sachar t
       set t.maskoret_kovaat_percent            = get_decimal_number(c.ai,2)
     where t.seq_netuney_sachar = v_seq_netuney_sachar_60;
          
          --vetek gil 60
          pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                             6,
                                             case when p_code_reforma <> 1 then v_vetek_gil_60 else v_vetek_ofek_gil_60 end,
                                             v_seq_netuney_sachar_60);
                       --vetek mukdam
      if p_code_chosen_alterntive = 1 and nvl(c.aa,0) > 0 then                                   
             pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                             10,
                                             c.aa,
                                             v_seq_netuney_sachar_60); 
          end if;
      end if;
    end if;
 
   
  v_maskoret_pizuim := c.ah;
    
  end loop;
  
  if nvl(v_maskoret_pizuim, 0) <> 0 then
    
   --maskoret pitzuim by alternative
   /* if p_code_chosen_alterntive = 1 then
      v_sug_maskoret_gil_pizuim := 7;
    elsif p_code_chosen_alterntive = 2 then
      v_sug_maskoret_gil_pizuim := 10;
    end if;*/
  select count(*)
    into v_exists_pizuim
    from netuney_sachar t
    where t.seq_bakasha = p_seq_bakasha
    and t.code_sug_maskoret = 14
    and t.mispar_misra = 99;
    
    if v_exists_pizuim = 0 then
      v_seq_netuney_sachar_pizuim := netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01,
                                                                p_seq_bakasha,
                                                                v_date_start_zakaut,
                                                                14,
                                                                v_sum_havraa,
                                                                v_sum_bigud,
                                                                v_is_maanak_yovel,
                                                               null,
                                                                get_decimal_number(v_maskoret_pizuim,2),
                                                                p_code_derug,
                                                                p_code_darga,
                                                                v_havraa_days,
                                                                v_ramat_bigud,
                                                                null);
    
      if v_seq_netuney_sachar_pizuim is not null  then
        
          --vetek pizuim
          update_vetek_detail_maskoret_1(p_seq_ld_chinuch_salary_01,
                                       p_seq_bakasha,
                                       v_seq_netuney_sachar_pizuim);
      end if;
      end if;
    end if;
  
  end;
  ------------------------------------------------
  procedure update_mitve_nur(p_seq_bakasha              number,
                             p_seq_ld_chinuch_salary_01 number) is
    v_seq_mitve_nur number;
  begin
  
    for r in (select s.*
                from ld_chinuch_salary_04 s
                left join ld_chinuch_salary_01 s1
                  on to_number(s.b) = to_number(s1.b)
                 and trunc(s1.load_date) = trunc(s.load_date)
               where s1.seq_ld_chinuch_salary_01 =
                     p_seq_ld_chinuch_salary_01) loop
      v_seq_mitve_nur := chinuch_reforma_seq.nextval;
      insert into chinuch_mitve_nur
        (seq_bakasha,
         chodesh_sachar,
         shach_mekadem_misra,
         sug_zchut,
         is_mashpia,
         is_factor,
         factor_olam_yashan,
         factor_ofek,
         factor_oz,
         factor_michlala,
         seq_mitve_nur)
      values
        (p_seq_bakasha,
         to_date(r.c, 'yyyymm'),
         get_decimal_number(r.d,5),
         r.e,
         r.f,
         r.g,
         get_decimal_number(r.h,5),
         get_decimal_number(r.i,5),
         get_decimal_number(r.j,5),
         get_decimal_number(r.k,5),
         CHINUCH_MITVE_NUR_SEQ.NEXTVAL);
    END LOOP;
  end;
  -------------------------------------------------
  
  procedure update_bakarot(p_seq_bakasha              number,
                           p_seq_ld_chinuch_salary_01 number,
                           p_seq_reforma              number,
                           p_code_reforma             number) is
    v_seq_bakara                    number;
    v_code_bakara                   number;
    v_taarich                       date;
    v_amount                   number;
    v_indication                    number;
    v_grira                         number;
    v_code_tafkid                   number;
    v_mispar_kitot_yesodi           number;
    v_mispar_kitot_al_yesodi        number;
    v_mispar_kitot_yesodi_chanam    number;
    v_mispar_kitot_al_yesodi_chanam number;
    v_ramat_murkavut                number;
    v_godel_matya                   number;
    v_code_mosad                     number;  
    v_ramat_murkavut_before          number;
    v_tafkid_acharon                 number;
    v_semel_mosad                    number;                 
  begin
  
    for r in (select s.*
                from ld_chinuch_salary_bakarot s
                left join ld_chinuch_salary_01 s1
                  on s.b = s1.b
                 and trunc(s1.load_date) = trunc(s.load_date)
               where s1.seq_ld_chinuch_salary_01 =
                     p_seq_ld_chinuch_salary_01
                 and s.a in ('5', '6', '7', '8', '9', '10')
                 and s.c = p_code_reforma) loop
      v_seq_bakara  := chinuch_bakara_seq.nextval;
      v_taarich     := case when r.a not in (5,10) then to_date(r.d, 'yyyymm') else null end;
      v_code_bakara := case when r.a = 5 then 1 when r.a = 6then 2when r.a = 7then 3when r.a = 8then 4when r.a = 9then 5when r.a = 10then 6 else null end;
      v_indication  := case when r.a = 5 then r.g when  r.a =8 then r.e when  r.a =10 then r.d else  0 end;
      v_grira       := case when r.a = 5 then r.f when  r.a =9 then r.e else 0 end;
      v_amount := case when r.a =6 then r.e when  r.a =7 then r.e when  r.a =9 then r.f else null end;
      if r.a = 5 then
        v_code_tafkid                     := CASE WHEN r.d=0 THEN NULL ELSE R.d END;
        v_code_mosad                      := CASE WHEN r.e=0 THEN NULL ELSE R.E END;
        v_mispar_kitot_yesodi           := r.h;
        v_mispar_kitot_al_yesodi        := r.i;
        v_mispar_kitot_yesodi_chanam    := r.j;
        v_mispar_kitot_al_yesodi_chanam := r.k;
        v_ramat_murkavut                := r.l;
        v_godel_matya                   := r.m;
         v_ramat_murkavut_before          := r.n;
    v_tafkid_acharon                 := r.o;
    v_semel_mosad                    := r.p;     
      else
        v_code_tafkid                   := null;
        v_mispar_kitot_yesodi           := null;
        v_mispar_kitot_al_yesodi        := null;
        v_mispar_kitot_yesodi_chanam    := null;
        v_mispar_kitot_al_yesodi_chanam := null;
        v_ramat_murkavut                := null;
        v_godel_matya                   := null;
        v_code_mosad                    :=null;
         v_ramat_murkavut_before          := null;
    v_tafkid_acharon                 := null;
    v_semel_mosad                    := null;    
      end if;
    
      insert into chinuch_bakara
        (seq_chinuch_bakara,
         seq_chinuch_reforma,
         code_bakara,
         taarich,
         amount,
         indication,
         grira,
         code_tafkid,
         mispar_kitot_yesodi,
         mispar_kitot_al_yesodi,
         mispar_kitot_yesodi_chanam,
         mispar_kitot_al_yesodi_chanam,
         ramat_murkavut,
         godel_matya,
         code_chinuch_mosad,
         ramat_murkavut_before,
         tafkid_acharon,
         semel_mosad
         )
      values
        (v_seq_bakara,
         p_seq_reforma,
         v_code_bakara,
         v_taarich,
         v_amount,
         v_indication,
         v_grira,
         v_code_tafkid,
         v_mispar_kitot_yesodi,
         v_mispar_kitot_al_yesodi,
         v_mispar_kitot_yesodi_chanam,
         v_mispar_kitot_al_yesodi_chanam,
         v_ramat_murkavut,
         v_godel_matya,
         v_code_mosad,
         v_ramat_murkavut_before,
         v_tafkid_acharon,
         v_semel_mosad);
    END LOOP;
  end;
  -------------------------------------------------
  function update_sachar_for_bakasha(p_seq_bakasha number) return number is
    v_result number;
  begin
  
    for r in (select max(s.seq_ld_chinuch_salary_01) seq_ld_chinuch_salary
                from v_bakasha v
                left join ld_chinuch_salary_01 s
                  on s.b = v.MISPAR_ZEHUT
               where v.SEQ_BAKASHA = p_seq_bakasha
                 and v.code_makor = 3) loop
    
      if r.seq_ld_chinuch_salary is null then
        return 0;
      end if;
    
      v_result := update_netuney_sachar(r.seq_ld_chinuch_salary,
                                        p_seq_bakasha,
                                        p_seq_bakasha);
    
      /*if v_result = 0 then
        rollback;
      else*/
      --delete_old_data(p_seq_bakasha);
        commit;
     -- end if;
    
      pk_salary_base.update_ld_salary_base(null,
                                           null,
                                           r.seq_ld_chinuch_salary,
                                           1,
                                           p_seq_bakasha);
    end loop;
    return 1;
  
  end;
  --------------------------------------------------------
  procedure delete_old_data(p_seq_bakasha number) is
    pragma autonomous_transaction;
  begin
  begin
    for r in (select *
                from netuney_sachar t
               where t.seq_bakasha = p_seq_bakasha
               ) loop
    if r.seq_netuney_sachar is not null then
      delete from vetek_detail v
       where v.seq_netuney_sachar = r.seq_netuney_sachar;
    
      delete from tosefot t
       where t.seq_netuney_sachar = r.seq_netuney_sachar;
    
      delete from netuney_sachar n
       where n.seq_netuney_sachar = r.seq_netuney_sachar and r.mispar_misra<>99;
       end if;
    end loop;
    delete from chinuch_bakara t
     where t.seq_chinuch_reforma in
           (select t1.seq_chinuch_reforma
              from chinuch_reforma t1
             where t1.seq_bakasha = p_seq_bakasha);
  
    delete from chinuch_reforma t where t.seq_bakasha = p_seq_bakasha;
  
    delete from chinuch_mitve_nur t where t.seq_bakasha = p_seq_bakasha;
  
    commit;
  exception
    when others then
      rollback;
  end;
  
  end;
  --------------------------------------------------------
  function main_chinuch(p_ld_protocol number) return clob is
    v_seq_bakasha number;
    v_code_status_get number;
  begin
  
    for r in (select a.b,
       a.seq_ld_chinuch_salary_01,
       a.max_seq
                from (select
                      --Id
                       t.b,
                       t.seq_ld_chinuch_salary_01,
                       --Get the last load for every id
                       first_value(t.seq_ld_chinuch_salary_01) over(partition by t.b order by t.seq_ld_chinuch_salary_01 desc) max_seq
                        from ld_chinuch_salary_01 t
                        left join ld_salary_base l
                          on t.seq_ld_chinuch_salary_01 =
                             l.seq_ld_chinuch_salary_01
) a
left join ld_salary_base ll
                          on a.seq_ld_chinuch_salary_01 =
                             ll.seq_ld_chinuch_salary_01
              --Filer: get the last rows for every id
               where a.seq_ld_chinuch_salary_01 = trunc(a.max_seq)
             and nvl(ll.code_status_get, 0) in (0, 3) 
  -- and a.b in(22543730  )       
                     -- and t.seq_ld_chinuch_salary_01 in (7399,7399)
                    ) loop
                    dbms_output.put_line(r.b);
       pk_salary_base.load_managment_id(p_ld_protocol,
                                       null,
                                       r.seq_ld_chinuch_salary_01,
                                       
                                       --Id
                                       r.b,
                                       --code_misrad_maskret of chinuch
                                       150,
                                       'pk_chinuch_salary');
    
      select b.seq_bakasha,b.code_status_get
        into v_seq_bakasha,v_code_status_get
        from ld_salary_base b
       where r.seq_ld_chinuch_salary_01 = b.seq_ld_chinuch_salary_01;
    
      --Transaction by id
      if v_code_status_get <> 5 then
      pk_salary_base.chinuch_manage_actions(p_ld_protocol, v_seq_bakasha);
      else
        commit;
    end  if;
    end loop;
    return pk_salary_base.get_report(p_ld_protocol);
  end;
   --------------------------------------------------------
function is_get_new_salary_1(p_seq_bakasha_for_compare number,
                             p_seq_chinuch_salary_01   number)
  return number is
  v_is_get_new_salary        number := 1;
  v_count_rows_new           number;
  v_exists_netuney_sachar    number;
  v_odef                     number;
  v_zehut                    number;
  v_load_date                date;
  v_reforma                  number;
  v_alternative              number;
  v_maskoret                 number;
  v_maskoret_gil_60          number;
  v_code_sug_maskoret        number;
  v_code_sug_maskoret_gil_60 number;
  v_nigzeret                 number;
  v_nigzeret_gil_60          number;
  v_maskoret_pizuim          number;
  v_choose_alternative       number;
  v_temp                     number;
  v_tkufa_mezaka             number;
  v_exists_ofek              number;
  v_code_derug               number;
  v_code_darga               number;
  v_code_darga_mimshak       number;
  v_darga_ofek               number;
  v_derug_ofek               number;
  v_change_derug             number;
  v_change_darga             number;
  v_mishkolet                number;
  v_only_old_world           number;
  v_tosefet_2023             number;
begin

  --get zehut and load date
  select t.b, t.load_date
    into v_zehut, v_load_date
    from ld_chinuch_salary_01 t
   where t.seq_ld_chinuch_salary_01 = p_seq_chinuch_salary_01;

  --there is no netuney sachar in p_seq_bakasha_for_compare
  select count(*)
    into v_exists_netuney_sachar
    from netuney_sachar n
   where n.seq_bakasha = p_seq_bakasha_for_compare;
   --there is no netuney reforma in p_seq_bakasha_for_compare
select count(*)
    into v_exists_netuney_sachar
    from chinuch_reforma n
   where n.seq_bakasha = p_seq_bakasha_for_compare;
  --if there is odef-check maskoret pizuim
  select nvl(sum(nvl(v.odef_sherut_chodashim, 0) +
                 nvl(v.odef_sherut_yamim, 0)),
             0),
         sum(v.tkufa_mezaka_sherut)
    into v_odef, v_tkufa_mezaka
    from bakasha b
    left join v_prisha_last_zakaut tt
      on b.seq_prisha = tt."SEQ_PRISHA"
    left join netuney_tik_mechushavim v
      on v.seq_bakasha = tt."SEQ_BAKASHA_ZAKAUT"
   where b.seq_bakasha = p_seq_bakasha_for_compare
     and v.mispar_misra = 0
     and v.code_department = 2;

  v_is_get_new_salary := 0;
  if v_exists_netuney_sachar = 0 then
    v_is_get_new_salary := 1;
    return v_is_get_new_salary;
  end if;
  --compare maskoret_kovaat

  select count(*)
    into v_exists_ofek
    from ld_chinuch_salary_03 t
   where t.b = v_zehut
     and trunc(t.load_date) = trunc(v_load_date)
     and t.c = 1;
    begin
      select max(t.c)
        into v_only_old_world
        from ld_chinuch_salary_03 t
       where t.b = v_zehut
         and trunc(t.load_date) = trunc(v_load_date)
       group by t.b, trunc(t.load_date)
      having count(*) = 1;
    exception
      when no_data_found then
        v_only_old_world := 0;
    end;

  for r in (select t.*, s1.r as darga_mimshak
              from ld_chinuch_salary_03 t
              left join ld_chinuch_salary_01 s1
                on t.b = s1.b
               and trunc(s1.load_date) = trunc(t.load_date)
             where t.b = v_zehut
               and trunc(t.load_date) = trunc(v_load_date)) loop
  
  
   select cr.code_chinuch_alterntive
        into v_choose_alternative
        from chinuch_reforma cr
       where cr.seq_bakasha = p_seq_bakasha_for_compare
         and cr.code_reforma = r.c;
  
    --mishkolet
    select nvl(t1.factor, 0)
      into v_mishkolet
      from chinuch_reforma t1
     where t1.seq_bakasha = p_seq_bakasha_for_compare
       and t1.code_reforma = r.c;
    if get_decimal_number(r.q, 4) <> v_mishkolet then
      v_is_get_new_salary := 9;
      --return v_is_get_new_salary;
    end if;
  
  
   if v_only_old_world = 4 then 
     v_code_sug_maskoret        := 1;
      v_code_sug_maskoret_gil_60 := 2;
      v_maskoret                 := get_decimal_number(r.m, 2);
      v_maskoret_gil_60 := get_decimal_number(r.ak, 2);
                             
     elsif r.d = 1 or r.c = 4 then
      v_maskoret                 := get_decimal_number(r.m, 2);
      v_maskoret_gil_60 := CASE
                             WHEN v_choose_alternative = r.d or r.c = 4 then
                              get_decimal_number(r.ak, 2)
                             else
                              0
                           end;
      v_nigzeret                 := nvl(get_decimal_number(r.k, 2), 0) +
                                    nvl(get_decimal_number(r.l, 2), 0);
      v_code_sug_maskoret        := 5;
      v_code_sug_maskoret_gil_60 := 6;
    else
      v_maskoret                 := get_decimal_number(r.o, 2);
      v_maskoret_gil_60 := CASE
                             WHEN v_choose_alternative = r.d and r.c <> 4 then
                              get_decimal_number(r.al, 2)
                             else
                              0
                           end;
      v_nigzeret_gil_60          := nvl(get_decimal_number(r.k, 2), 0) +
                                    nvl(get_decimal_number(r.l, 2), 0);
      v_code_sug_maskoret        := 8;
      v_code_sug_maskoret_gil_60 := 9;
    
    end if;
  
  
    --derug darga from mimshak
    v_code_darga_mimshak := r.af;
    if r.c = 1 then
      v_code_darga_mimshak := r.darga_mimshak;
      select dc.code_darga, dc.code_derug
        into v_darga_ofek, v_derug_ofek
        from code_darga dc
       where dc.code_derug = r.ae + 99000
         and dc.code_darga = r.af;
    end if;
    select dc.code_darge, dc.code_derug
      into v_code_darga, v_code_derug
      from code_darga_chinuch_salary dc
     where dc.code_derug_chinuch_salary = 41
       and dc.code_darga_chinuch_salary = v_code_darga_mimshak;
  
    
     --derug darga
    begin
      select nvl(t.code_derug, 0) - nvl(case
                                          when v_code_sug_maskoret = 5 and r.c = 1 then
                                           v_derug_ofek
                                          else
                                           v_code_derug
                                        end,
                                        0),
             nvl(t.code_darga, 0) - nvl(case
                                          when v_code_sug_maskoret = 5 and r.c = 1 then
                                           v_darga_ofek
                                          else
                                           v_code_darga
                                        end,
                                        0)
        into v_change_derug, v_change_darga
        from netuney_sachar t
        left join chinuch_reforma t1
          on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
       where t.seq_bakasha = p_seq_bakasha_for_compare
         and t.code_sug_maskoret = v_code_sug_maskoret
         and (t1.code_reforma = r.c or v_only_old_world = 4);
    
      if v_change_darga <> 0 or v_change_derug <> 0 then
        v_is_get_new_salary := 7;
        return v_is_get_new_salary;
      
      end if;
    exception
      when others then
        v_is_get_new_salary := 7;
        return v_is_get_new_salary;
    end;
    
  
    --check maanak_yovel
    begin
      select count(*)
        into v_count_rows_new
        from (select t.is_maanak_yovel
                from netuney_sachar t
               where t.seq_bakasha = p_seq_bakasha_for_compare
                 and (t.code_sug_maskoret <> 14)
                 and rownum = 1
              minus
              select to_number(r.g)
                from ld_chinuch_salary_01 r
               where r.seq_ld_chinuch_salary_01 = p_seq_chinuch_salary_01);
      if nvl(v_count_rows_new, 0) > 0 then
        v_is_get_new_salary := 10;
        return v_is_get_new_salary;
      end if;
    exception
      when no_data_found then
        v_is_get_new_salary := 10;
        return v_is_get_new_salary;
    end;
    
    
    if r.c <> 4 then
   
  --chodashim  
      if case
           when r.c = 1 or r.c = 2 and v_exists_ofek = 1 then
            r.an
           else
            r.e
         end + case
           when r.c = 1 or r.c = 2 and v_exists_ofek = 1 then
            r.ao
           else
            r.f
         end <> v_tkufa_mezaka then
        v_is_get_new_salary := 6;
        return v_is_get_new_salary;
      end if;
    
  --diff alternative
 
      if v_choose_alternative <> to_number(r.d) and r.c <> 4 then
        v_is_get_new_salary := 5;
        return v_is_get_new_salary;
      end if;
    
    end if;
    
    /*
  
    if r.d = 1 or r.c = 4 then
      v_maskoret                 := get_decimal_number(r.m, 2);
      v_maskoret_gil_60 := CASE
                             WHEN v_choose_alternative = r.d or r.c = 4 then
                              get_decimal_number(r.ak, 2)
                             else
                              0
                           end;
      v_nigzeret                 := nvl(get_decimal_number(r.k, 2), 0) +
                                    nvl(get_decimal_number(r.l, 2), 0);
      v_code_sug_maskoret        := 5;
      v_code_sug_maskoret_gil_60 := 6;
    else
      v_maskoret                 := get_decimal_number(r.o, 2);
      v_maskoret_gil_60 := CASE
                             WHEN v_choose_alternative = r.d and r.c <> 4 then
                              get_decimal_number(r.al, 2)
                             else
                              0
                           end;
      v_nigzeret_gil_60          := nvl(get_decimal_number(r.k, 2), 0) +
                                    nvl(get_decimal_number(r.l, 2), 0);
      v_code_sug_maskoret        := 8;
      v_code_sug_maskoret_gil_60 := 9;
    
    end if;*/
  
    --begin
    --choose alternative details(maskoret and nigzeret)
    select nvl(t.maskoret_kovaat, 0) - nvl(v_maskoret, 0)
      into v_maskoret
      from netuney_sachar t
      left join chinuch_reforma t1
        on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
     where t.seq_bakasha = p_seq_bakasha_for_compare
       and t.code_sug_maskoret = v_code_sug_maskoret
       and (t1.code_reforma = r.c or v_only_old_world = 4);
  
    select t.maskoret_kovaat_percent - nvl(v_nigzeret, 0)
      into v_nigzeret
      from netuney_sachar t
      left join chinuch_reforma t1
        on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
     where t.seq_bakasha = p_seq_bakasha_for_compare
       and t.code_sug_maskoret = v_code_sug_maskoret
       and (t1.code_reforma = r.c or v_only_old_world = 4);
  
    v_temp := 1;
    if r.c=2 and r.d=1 then
       select sum(get_decimal_number(t.i,2))*(nvl(get_decimal_number(r.k, 2), 0) +
                                    nvl(get_decimal_number(r.l, 2), 0))/100
       into v_tosefet_2023
       from ld_chinuch_salary_02 t
       where t.b=r.b
       and trunc(t.load_date)=trunc(r.load_date)
       and t.c=2
       and t.e=0 
       and t.f=5832;
    end if;   
    
    if r.c=2 and r.d=1 and abs(v_maskoret)-v_tosefet_2023<1 then
      v_is_get_new_salary := 13;
    elsif abs(v_maskoret) > 20 then
      v_is_get_new_salary := 1;
      return v_is_get_new_salary;
    elsif abs(v_maskoret) <> 0 then
      v_is_get_new_salary := 11;
    end if;
  
    v_maskoret_pizuim := get_decimal_number(r.ah, 2);
  
    --gil 60
    begin
      select nvl(t.maskoret_kovaat, 0) - nvl(v_maskoret_gil_60, 0) 
        into v_maskoret_gil_60 
        from netuney_sachar t
        left join chinuch_reforma t1
          on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
       where t.seq_bakasha = p_seq_bakasha_for_compare
         and t.code_sug_maskoret = v_code_sug_maskoret_gil_60
         and (t1.code_reforma = r.c or v_only_old_world = 4);
    
      if r.c=2 and r.d=1 then
       select sum(get_decimal_number(t.i,2))*(nvl(get_decimal_number(r.ai, 2), 0))/100
       into v_tosefet_2023
       from ld_chinuch_salary_02 t
       where t.b=r.b
       and trunc(t.load_date)=trunc(r.load_date)
       and t.c=2
       and t.e=2 
       and t.f=5832;
    end if;   
    
    if r.c=2 and r.d=1 and abs(v_maskoret_gil_60)-v_tosefet_2023<1 then
      v_is_get_new_salary := 13;
    elsif abs(v_maskoret) > 20 or abs(v_maskoret_gil_60) > 20 then
        v_is_get_new_salary := 1;
        return v_is_get_new_salary;
      elsif /*v_maskoret <> 0 or */v_maskoret_gil_60 <> 0 then
        v_is_get_new_salary := 12;
       --return v_is_get_new_salary;
      end if;
    
    exception
      when no_data_found then
        begin
          if nvl(v_maskoret_gil_60, 0) = 0 then
            v_temp := 1;
          else
            v_is_get_new_salary := 1;
            return v_is_get_new_salary;
          end if;
        end;
      when others then
        v_is_get_new_salary := 1;
        return v_is_get_new_salary;
    end;
    
  --check maskoret other alternative
    v_maskoret := case
                    when r.d = 1 then
                     r.o
                    else
                     r.m
                  end;
    v_maskoret_gil_60 := case
                           when r.d = 1 then
                            r.al
                           else
                            r.ak
                         end;
    v_maskoret        := get_decimal_number(v_maskoret, 2);
    v_maskoret_gil_60 := get_decimal_number(v_maskoret_gil_60, 2);
  
    
    if r.c <> 4 then
      select nvl(t.maskoret_kovaat, 0) - v_maskoret
        into v_maskoret
        from netuney_sachar t
        left join chinuch_reforma t1
          on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
       where t.seq_bakasha = p_seq_bakasha_for_compare
         and t.code_sug_maskoret = decode(r.d, 1, 8, 5)
         and t1.code_reforma = to_number(r.c);
    
      begin
        select nvl(t.maskoret_kovaat, 0) - v_maskoret_gil_60
          into v_maskoret_gil_60
          from netuney_sachar t
          left join chinuch_reforma t1
            on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
         where t.seq_bakasha = p_seq_bakasha_for_compare
           and t.code_sug_maskoret = decode(r.d, 1, 9, 6)
           and t1.code_reforma = to_number(r.c);
      
        if v_maskoret_gil_60 <> 0 then
          v_is_get_new_salary := 4;
         -- return v_is_get_new_salary;
        end if;
      exception
        when no_data_found then
          begin
            if nvl(v_maskoret_gil_60, 0) = 0 and nvl(v_maskoret, 0) = 0 then
              v_temp := 1;
            else
              v_is_get_new_salary := 4;
              --return v_is_get_new_salary;
            end if;
          end;
        when others then
          v_is_get_new_salary := 4;
          --return v_is_get_new_salary;
      end;
    
  
    --derug darga
    begin
      select nvl(t.code_derug, 0) - nvl(case
                                          when t.code_sug_maskoret = 5 and t1.code_reforma = 1 then
                                           v_derug_ofek
                                          else
                                           v_code_derug
                                        end,
                                        0),
             nvl(t.code_darga, 0) - nvl(case
                                          when t.code_sug_maskoret = 5 and t1.code_reforma = 1 then
                                           v_darga_ofek
                                          else
                                           v_code_darga
                                        end,
                                        0)
        into v_change_derug, v_change_darga
        from netuney_sachar t
        left join chinuch_reforma t1
          on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
       where t.seq_bakasha = p_seq_bakasha_for_compare
         and t.code_sug_maskoret = decode(r.d, 1, 8, 5)
         and t1.code_reforma = r.c;
    
      if v_change_darga <> 0 or v_change_derug <> 0 then
        v_is_get_new_salary := 8;
        --return v_is_get_new_salary;
      
      end if;
    exception
      when others then
        v_is_get_new_salary := 8;
        --return v_is_get_new_salary;
    end;
  end if;   
  end loop;

  --check havara bigud
  begin
    select count(*)
      into v_count_rows_new
      from (select t.sum_havraa,
                   t.sum_bigud,
                   t.is_maanak_yovel,
                   t.havraa_days,
                   t.ramat_bigud
              from netuney_sachar t
             where t.seq_bakasha = p_seq_bakasha_for_compare
               and (t.code_sug_maskoret <> 14)
               and rownum = 1
            minus
            select to_number(r.e),
                   to_number(r.f),
                   to_number(r.g),
                   to_number(r.l),
                   to_number(r.m)
              from ld_chinuch_salary_01 r
             where r.seq_ld_chinuch_salary_01 = p_seq_chinuch_salary_01);
    if nvl(v_count_rows_new, 0) > 0 then
      v_is_get_new_salary := 2;
      --return v_is_get_new_salary;
    end if;
  exception
    when no_data_found then
      v_is_get_new_salary := 2;
      --return v_is_get_new_salary;
  end;

  --check odef
  if v_odef > 0 then
    --pizuim
    begin
      select nvl(t.maskoret_kovaat, 0) - nvl(v_maskoret_pizuim, 0)
        into v_maskoret_pizuim
        from netuney_sachar t
       where t.seq_bakasha = p_seq_bakasha_for_compare
         and t.code_sug_maskoret = 14;
    
      if v_maskoret_pizuim <> 0 then
        v_is_get_new_salary := 3;
        --return v_is_get_new_salary;
      end if;
    exception
      when no_data_found then
        v_is_get_new_salary := 3;
        --return v_is_get_new_salary;
    end;
  end if;

  if nvl(v_is_get_new_salary, 0) = 0 then
    return 0;
  else
    return v_is_get_new_salary;
  end if;
end;


  --------------------------------------------------------
 
  --------------------------------------------------------
end;
/

create or replace package body prm_system_copy.pk_chinuch_salary_old is
  --------------------------------------------------------
  procedure update_vetek_detail_60(p_seq_chinuch_salary_01 number,
                                   p_seq_bakasha           number,
                                   p_seq_netuney_sachar    number) is
  begin
    for r in (select
              --horaha
               t.c,
               --zahahl
               Get_zahal_vetek_by_years(t.g) zahal,
               --age 60 addition
               t.ab
                from ld_chinuch_salary_01 t
               where t.seq_ld_chinuch_salary_01 = p_seq_chinuch_salary_01) loop

      --age_60_seniority
      pk_salary_base_old.insert_vetek_detail(p_seq_bakasha,
                                         6,
                                         r.c + r.zahal + r.ab,
                                         p_seq_netuney_sachar);
    end loop;
  end;
  --------------------------------------------------------
  function Get_zahal_vetek_by_years(p_zahal_vetek number) return number is
    v_vetek number;
  begin
    if p_zahal_vetek is not null then
      -- Divide months to years
      v_vetek := p_zahal_vetek / 12;
      --Round quarterly
      v_vetek := round(v_vetek / 25, 2) * 25;
    end if;

    return v_vetek;
  end;
  --------------------------------------------------------
  procedure update_vetek_detail_maskoret_3(p_seq_chinuch_salary_01 number,
                                           p_seq_bakasha           number,
                                           p_seq_netuney_sachar    number) is
  begin
    for r in (select t.*
                from ld_chinuch_salary_01 t
               where t.seq_ld_chinuch_salary_01 = p_seq_chinuch_salary_01) loop

      --nihol_seniority
      pk_salary_base_old.insert_vetek_detail(p_seq_bakasha,
                                         7,
                                         r.d,
                                         p_seq_netuney_sachar);
      --yeuz_seniority
      pk_salary_base_old.insert_vetek_detail(p_seq_bakasha,
                                         8,
                                         r.e,
                                         p_seq_netuney_sachar);
      --hadracha_seniority
      pk_salary_base_old.insert_vetek_detail(p_seq_bakasha,
                                         9,
                                         r.f,
                                         p_seq_netuney_sachar);

      --salary seniority
      pk_salary_base_old.insert_vetek_detail(p_seq_bakasha,
                                         6,
                                         r.af,
                                         p_seq_netuney_sachar);

    end loop;
  end;

  --------------------------------------------------------
  procedure update_vetek_detail_maskoret_1(p_seq_chinuch_salary_01 number,
                                           p_seq_bakasha           number,
                                           p_seq_netuney_sachar    number) is
  begin
    for r in (select t.*
                from ld_chinuch_salary_01 t
               where t.seq_ld_chinuch_salary_01 = p_seq_chinuch_salary_01) loop

      --salary seniority
      pk_salary_base_old.insert_vetek_detail(p_seq_bakasha,
                                         6,
                                         r.c +
                                         Get_zahal_vetek_by_years(r.g),
                                         p_seq_netuney_sachar);

      --horaha_seniority
      pk_salary_base_old.insert_vetek_detail(p_seq_bakasha,
                                         1,
                                         r.c,
                                         p_seq_netuney_sachar);

      --zahal_seniority
      pk_salary_base_old.insert_vetek_detail(p_seq_bakasha,
                                         2,
                                         Get_zahal_vetek_by_years(r.g),
                                         p_seq_netuney_sachar);

    end loop;
  end;
  --------------------------------------------------------
  procedure insert_tosefot(p_seq_netuney_sachar number,
                           p_code_semel_tosefet number,
                           p_sum                number,
                           p_amount             number) is
  begin
    if nvl(p_sum, 0) > 0 then

      --Insert to tosefot table
      insert into tosefot
        (seq_tosefot,
         seq_netuney_sachar,
         code_semel_tosefet,
         sum,
         amount,
         date_update,
         user_update)
      values
        (tosefot_seq.nextval,
         p_seq_netuney_sachar,
         p_code_semel_tosefet,
         p_sum,
         p_amount,
         sysdate,
         0);

    end if;
  end;
  --------------------------------------------------------
  procedure update_chinuch_salary(p_seq_ld_chinuch_salary_01 number,
                                  p_seq_bakasha              number) is
    v_date_begin_ofek date;
  begin
    for r in (select t.*
                from ld_chinuch_salary_01 t
               where t.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01) loop

      if nvl(r.v, 0) <> 0 then
        v_date_begin_ofek := to_date(r.v, 'yyyymm');
      end if;

      merge into chinuch_salary l
      using dual
      on (l.seq_bakasha = p_seq_bakasha)
      when matched then
        update
           set l.maskoret_kovaat_meshuklelet    = r.o,
               l.mkadem_misra_klali             = r.p,
               l.mkadem_misra                   = r.r,
               l.gmuley_hishtalmut              = r.s,
               l.kefel_toar                     = r.t,
               l.date_begin_ofek                = v_date_begin_ofek,
               l.kidum_darga_ofek               = r.w,
               l.hekef_misra_ofek               = r.aa,
               l.maskoret_kovaat_meshuklelet_60 = r.ae,
               l.tosefet_vetek_horah            = r.ab


      when not matched then
        insert
          (l.maskoret_kovaat_meshuklelet,
           l.mkadem_misra_klali,
           l.mkadem_misra,
           l.gmuley_hishtalmut,
           l.kefel_toar,
           l.date_begin_ofek,
           l.kidum_darga_ofek,
           l.hekef_misra_ofek,
           l.maskoret_kovaat_meshuklelet_60,
           l.tosefet_vetek_horah,
           l.seq_bakasha)
        values
          (r.o,
           r.p,
           r.r,
           r.s,
           r.t,
           v_date_begin_ofek,
           r.w,
           r.aa,
           r.ae,
           r.ab,
           p_seq_bakasha);

    end loop;
  end;
  --------------------------------------------------------
  function Get_code_semel_tosefet(v_mispar_zehut       number,
                                  v_code_semel_chinuch number) return number is
    v_taarich_prisha     date;
    v_code_semel_tosefet number;
  begin
    select max(v.TAARICH_PRISHA)
      into v_taarich_prisha
      from v_bakasha_last_status v
     where v.mispar_zehut = v_mispar_zehut;

    --Get semel tosefet by date prisha
    if v_taarich_prisha >= to_date('31082020', 'ddmmyyyy') then
      select max(s.code_semel_tosefet)
        into v_code_semel_tosefet
        from code_semel_tosefet s
       where s.semel_chinuch = v_code_semel_chinuch;
    else
      select min(s.code_semel_tosefet)
        into v_code_semel_tosefet
        from code_semel_tosefet s
       where s.semel_chinuch = v_code_semel_chinuch;
    end if;

    return v_code_semel_tosefet;
  end;
  --------------------------------------------------------
  procedure update_tosafot(p_seq_ld_chinuch_salary_01 number,
                           p_seq_netuney_sachar       number,
                           p_type_prisha              number,
                           p_type_reforma             number) is
    v_code_semel_tosefet number;
  begin
    --Loop over all additions
    for r in (select t1.b, t2.h, t2.i, t2.j, t2.f
                from ld_chinuch_salary_02 t2
                left join ld_chinuch_salary_01 t1
                  on t2.b = t1.b
                 and trunc(t2.load_date) = trunc(t1.load_date)
               where t1.seq_ld_chinuch_salary_01 =
                     p_seq_ld_chinuch_salary_01
                 and t2.c = p_type_prisha
                 and t2.d = p_type_reforma
                    --Without base salary
                 and t2.f not in (1, 10)) loop

      --Get code_semel_tosefet
      v_code_semel_tosefet := Get_code_semel_tosefet(r.b, r.f);

      --When code_semel_tosefet is null
      if v_code_semel_tosefet is null then
        pk_salary_base_old.code_addition_not_exist(r.f, p_seq_netuney_sachar);
        --Continue to the next addition
        continue;
      end if;

      --Insert to tosefot table
      insert_tosefot(p_seq_netuney_sachar, v_code_semel_tosefet, r.i, r.j);

    end loop;
  end;
  -------------------------------------------------------
  function netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01 number,
                                          p_seq_bakasha_for_insert   number,
                                          p_date_start_zakaut        date,
                                          p_code_sug_maskoret        number,
                                          p_sum_havraa               number,
                                          p_sum_bigud                number,
                                          p_is_maanak_yovel          number,
                                          p_chodashim                number,
                                          p_maskoret_kovaat          number,
                                          p_code_derug               number,
                                          p_code_darga               number,
                                          p_havraa_days              number,
                                          p_ramat_bigud              number)
    return number is
    v_seq_netuney_sachar number;
    v_type_prisha        number;
    v_type_reforma       number;
    v_count_derug_darga  number;
    v_base_salary        number;
  begin
    if nvl(p_maskoret_kovaat, 0) = 0 then
      return null;
    end if;

    v_seq_netuney_sachar := netuney_sachar_seq.nextval;

    v_type_prisha := case
                       when p_code_sug_maskoret in (1, 3) then
                        1 -- prisha
                       when p_code_sug_maskoret in (2, 4) then
                        2 -- age 60
                     end;

    v_type_reforma := case
                        when p_code_sug_maskoret in (1, 2) then
                         4 -- olam yashan
                        when p_code_sug_maskoret in (3, 4) then
                         1 -- ofek chadash
                      end;

    begin
      select t2.i
        into v_base_salary
        from ld_chinuch_salary_02 t2
        left join ld_chinuch_salary_01 t1
          on t2.b = t1.b
         and trunc(t2.load_date) = trunc(t1.load_date)
       where t1.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01
         and t2.c = v_type_prisha
         and t2.d = v_type_reforma
            --Get base salary
         and t2.f in (1, 10);
    exception
      when others then
        v_base_salary := null;
    end;

    --select from code_darge in order to check that we have the codes
    --and when the codes is not exist, set null.
    select count(*)
      into v_count_derug_darga
      from code_darga d
     where d.code_derug = p_code_derug
       and d.code_darga = p_code_darga;

    insert into netuney_sachar
      (seq_netuney_sachar,
       seq_bakasha,
       mispar_misra,
       code_sug_maskoret,
       sum_havraa,
       sum_bigud,
       is_maanak_yovel,
       chodashim,
       maskoret_kovaat,
       code_derug,
       code_darga,
       date_update,
       user_update,
       from_date,
       schar_ysod,
       havraa_days,
       ramat_bigud)
    values
      (v_seq_netuney_sachar,
       p_seq_bakasha_for_insert,
       --The next value is temp in order to compare 2 same rows
       --And will updated in end
       99,
       p_code_sug_maskoret,
       p_sum_havraa,
       p_sum_bigud,
       p_is_maanak_yovel,
       p_chodashim,
       p_maskoret_kovaat,
       case when v_count_derug_darga > 0 then p_code_derug else null end,
       case when v_count_derug_darga > 0 then p_code_darga else null end,
       sysdate,
       0,
       p_date_start_zakaut,
       v_base_salary,
       p_havraa_days,
       p_ramat_bigud);

    update_tosafot(p_seq_ld_chinuch_salary_01,
                   v_seq_netuney_sachar,
                   v_type_prisha,
                   v_type_reforma);

    return v_seq_netuney_sachar;
  end;
  --------------------------------------------------------
  procedure insert_extra_to_maskoret_kovaat(p_seq_netuney_sachar number,
                                            p_sum_to_add         number) is
  begin
    update netuney_sachar n
       set n.maskoret_kovaat = round(n.maskoret_kovaat + p_sum_to_add, 2)
     where n.seq_netuney_sachar = p_seq_netuney_sachar;
  end;
  --------------------------------------------------------
  procedure insert_extra_to_addition_chinuch(p_seq_tosefet number,
                                             p_sum_to_add  number) is
  begin
    update tosefot n
       set n.sum = round(n.sum + p_sum_to_add, 2)
     where n.seq_tosefot = p_seq_tosefet;
  end;
  --------------------------------------------------------
  function Calc_extra_addition_education(p_seq_netuney_sachar number,
                                         p_orginal_sum        number)
    return number is
    v_factor            number;
    v_achuz_kizba       number;
    v_chelkiyut_sofit   number;
    v_code_sug_maskoret number;
  begin
    select n.code_sug_maskoret
      into v_code_sug_maskoret
      from netuney_sachar n
     where n.seq_netuney_sachar = p_seq_netuney_sachar;

    if v_code_sug_maskoret = 1 then

      select n2.achuz_kizba_sofi, n2.chelkiyut_sofit
        into v_achuz_kizba, v_chelkiyut_sofit
        from netuney_sachar n
        left join (select max(v.seq_bakasha) seq_bakasha,
                          v.current_seq_bakasha
                     from v_mechushavim_2_curnt_and_prev v
                    where v.code_department = 2
                    group by v.current_seq_bakasha) v
          on v.current_seq_bakasha = n.seq_bakasha
        left join netuney_tik_mechushavim n2
          on v.seq_bakasha = n2.seq_bakasha
         and n2.code_department = 2
         and n2.mispar_misra = 0
       where n.seq_netuney_sachar = p_seq_netuney_sachar;

    elsif v_code_sug_maskoret = 2 then

      select n2.achuz_kizba_gil_60,
             --Get chelkiyut
             case
               when n2.code_group_prisha = 2 and n2.is_zakai_lmaanak = 1 then
                n2.chelkiyut_meshuklelet_sherut
               else
                n2.chelkiyut_sofit
             end
        into v_achuz_kizba, v_chelkiyut_sofit
        from netuney_sachar n
        left join (select max(v.seq_bakasha) seq_bakasha,
                          v.current_seq_bakasha
                     from v_mechushavim_2_curnt_and_prev v
                    where v.code_department = 2
                    group by v.current_seq_bakasha) v
          on v.current_seq_bakasha = n.seq_bakasha
        left join netuney_tik_mechushavim n2
          on v.seq_bakasha = n2.seq_bakasha
         and n2.code_department = 2
         and n2.mispar_misra = 0
       where n.seq_netuney_sachar = p_seq_netuney_sachar;
    end if;

    v_factor := least(greatest(nvl(v_achuz_kizba, 0), 70) / 70 *
                      nvl(v_chelkiyut_sofit, 0),
                      1);

    if v_factor = 0 then
      return 0;
    end if;

    return(p_orginal_sum / round(v_factor, 4))
    --Get only the extra
    - p_orginal_sum;
  end;

  --------------------------------------------------------
  function calc_complement_ofek_a(p_maskoret_kovaat_meshukll_old number,
                                  p_maskoret_kovaat_old          number)
    return number is
  begin
    return nvl(p_maskoret_kovaat_meshukll_old, 0) - nvl(p_maskoret_kovaat_old,
                                                        0);
  end;

  --------------------------------------------------------
  function calc_complement_ofek_b(p_seq_netuney_sachar   number,
                                  p_orginal_sum_tosefet  number,
                                  p_maskoret_kovaat_old  number,
                                  p_chodashim_old        number,
                                  p_maskoret_kovaat_ofek number,
                                  p_chodashim_ofek       number)
    return number is
    v_calc_maskoret_kovaat_old number;
    v_total_chodashim          number;
    v_partial_maskoret_old     number;
    v_partial_maskoret_ofek    number;
    v_total_maskoret           number;
    v_extra_addition           number;
  begin
    v_extra_addition := Calc_extra_addition_education(p_seq_netuney_sachar,
                                                      p_orginal_sum_tosefet);

    v_calc_maskoret_kovaat_old := nvl(v_extra_addition, 0) +
                                  nvl(p_maskoret_kovaat_old, 0);

    v_total_chodashim := nvl(p_chodashim_old, 0) + nvl(p_chodashim_ofek, 0);

    v_partial_maskoret_old := v_calc_maskoret_kovaat_old * p_chodashim_old /
                              v_total_chodashim;

    v_partial_maskoret_ofek := p_maskoret_kovaat_ofek * p_chodashim_ofek /
                               v_total_chodashim;

    v_total_maskoret := v_partial_maskoret_old + v_partial_maskoret_ofek;

    return round(v_total_maskoret - v_calc_maskoret_kovaat_old, 2);
  end;

  --------------------------------------------------------
  procedure insert_tosefot_complement_ofek(p_seq_netuney_sachar           number,
                                           p_maskoret_kovaat_meshukll_old number,
                                           p_maskoret_kovaat_old          number,
                                           p_chodashim_old                number,
                                           p_maskoret_kovaat_ofek         number,
                                           p_chodashim_ofek               number) is
    v_sum_tosefet_chinuch           number;
    v_extra_tosefet_complement_ofek number;
    v_extra_tosefet_chinuch         number;
    v_seq_tosefet                   number;
    v_code_sug_maskoret             number;
  begin

    begin
      select n.code_sug_maskoret, t.seq_tosefot, t.sum
        into v_code_sug_maskoret, v_seq_tosefet, v_sum_tosefet_chinuch
        from tosefot t
        left join netuney_sachar n
          on t.seq_netuney_sachar = n.seq_netuney_sachar
       where t.seq_netuney_sachar = p_seq_netuney_sachar
         and t.code_semel_tosefet in (3073, 3074);
    exception
      when others then
        v_sum_tosefet_chinuch := null;
    end;

    if v_sum_tosefet_chinuch is null then
      v_extra_tosefet_complement_ofek := calc_complement_ofek_a(p_maskoret_kovaat_meshukll_old,
                                                                p_maskoret_kovaat_old);
    else
      v_extra_tosefet_complement_ofek := calc_complement_ofek_b(p_seq_netuney_sachar,
                                                                v_sum_tosefet_chinuch,
                                                                p_maskoret_kovaat_old,
                                                                p_chodashim_old,
                                                                p_maskoret_kovaat_ofek,
                                                                p_chodashim_ofek);

      if v_code_sug_maskoret = 2 then
        --Calc extra tosefet chinuch
        v_extra_tosefet_chinuch := Calc_extra_addition_education(p_seq_netuney_sachar,
                                                                 v_sum_tosefet_chinuch);
        --update tosefet chinuch
        insert_extra_to_addition_chinuch(v_seq_tosefet,
                                         v_extra_tosefet_chinuch);

        --update maskoret
        insert_extra_to_maskoret_kovaat(p_seq_netuney_sachar,
                                        v_extra_tosefet_chinuch);
      end if;
    end if;

    --insert tosefet
    insert_tosefot(p_seq_netuney_sachar,
                   879,
                   v_extra_tosefet_complement_ofek,
                   null);
    --update maskoret
    insert_extra_to_maskoret_kovaat(p_seq_netuney_sachar,
                                    v_extra_tosefet_complement_ofek);
  end;
  --------------------------------------------------------
  function is_get_new_salary(p_seq_bakasha_for_compare number,
                             p_seq_bakasha_for_insert  number,
                             v_seq_netuney_sachar_1    number,
                             v_seq_netuney_sachar_2    number,
                             v_seq_netuney_sachar_3    number,
                             v_seq_netuney_sachar_4    number) return number is
    v_is_get_new_salary_1 number;
    v_is_get_new_salary_2 number;
    v_is_get_new_salary_3 number;
    v_is_get_new_salary_4 number;
  begin
    v_is_get_new_salary_1 := pk_salary_base_old.compare_versions(p_seq_bakasha_for_compare,
                                                             p_seq_bakasha_for_insert,
                                                             v_seq_netuney_sachar_1);

    v_is_get_new_salary_2 := pk_salary_base_old.compare_versions(p_seq_bakasha_for_compare,
                                                             p_seq_bakasha_for_insert,
                                                             v_seq_netuney_sachar_2);

    v_is_get_new_salary_3 := pk_salary_base_old.compare_versions(p_seq_bakasha_for_compare,
                                                             p_seq_bakasha_for_insert,
                                                             v_seq_netuney_sachar_3);

    v_is_get_new_salary_4 := pk_salary_base_old.compare_versions(p_seq_bakasha_for_compare,
                                                             p_seq_bakasha_for_insert,
                                                             v_seq_netuney_sachar_4);
    if nvl(v_is_get_new_salary_1, 0) = 0 and
       nvl(v_is_get_new_salary_2, 0) = 0 and
       nvl(v_is_get_new_salary_3, 0) = 0 and
       nvl(v_is_get_new_salary_4, 0) = 0 then
      return 0;
    else
      return 1;
    end if;
  end;

  --------------------------------------------------------
  procedure fix_hachshara(p_seq_bakasha number) is
    v_seq_tosefot_hachshara number;
  begin
    select t.seq_tosefot
      into v_seq_tosefot_hachshara
      from tosefot t
      left join netuney_sachar n
        on t.seq_netuney_sachar = n.seq_netuney_sachar
     where n.seq_bakasha = p_seq_bakasha
       and t.code_semel_tosefet = 865
       and n.code_sug_maskoret = 1;

    update tosefot t
       set t.amount = 100
     where t.seq_tosefot = v_seq_tosefot_hachshara;
    commit;
  exception
    when others then
      return;
  end;
  --------------------------------------------------------
  procedure fix_hadracha(p_seq_bakasha number) is
    v_amount_tosefet_hadracha_ofek number;
    v_years_vetek_hadracha_ofek    number;
    v_percent_by_years_vetek       number;
    v_percent_by_amount_tosefet    number;

    v_seq_tosefet_old_world number;
  begin
    select t1.amount, v.years
      into v_amount_tosefet_hadracha_ofek, v_years_vetek_hadracha_ofek
      from tosefot t1
      left join netuney_sachar n1
        on t1.seq_netuney_sachar = n1.seq_netuney_sachar
      left join vetek_detail v
        on n1.seq_netuney_sachar = v.seq_netuney_sachar
          --vetek hadracha
       and v.code_type_vetek = 9
     where n1.seq_bakasha = p_seq_bakasha
          --tosefet hadracha
       and t1.code_semel_tosefet = 524
          --maskoret ofek
       and n1.code_sug_maskoret = 3;

    --Get percent by years vetek
    select v.percent
      into v_percent_by_years_vetek
      from perm_guidance_vetek_years v
     where v.years_in_ofek = case
             when v_years_vetek_hadracha_ofek > 13 then
              13
             else
              v_years_vetek_hadracha_ofek
           end;

    --Get multiplication by amount tosefet
    select t.multiplication
      into v_percent_by_amount_tosefet
      from perm_guidance_tosefet_amount t
     where t.amount_in_ofek = v_amount_tosefet_hadracha_ofek;

    --Get seq_tosefet old_world
    select t1.seq_tosefot
      into v_seq_tosefet_old_world
      from tosefot t1
      left join netuney_sachar n1
        on t1.seq_netuney_sachar = n1.seq_netuney_sachar
     where n1.seq_bakasha = p_seq_bakasha
          --hadracha
       and t1.code_semel_tosefet = 524
       and n1.code_sug_maskoret = 1;

    --Update new amount in old world
    update tosefot t
       set t.amount = round(v_percent_by_years_vetek *
                            v_percent_by_amount_tosefet / 100,
                            2)
     where t.seq_tosefot = v_seq_tosefet_old_world;
    commit;

    fix_hachshara(p_seq_bakasha);
  exception
    when others then
      return;
  end;

  --------------------------------------------------------
  procedure fix_Special_Education(p_seq_bakasha number) is
    v_fix_amount_old_world  number := 0;
    v_seq_tosefet_old_world number;
  begin
    --Loop over additions new world
    for r in (select n.schar_ysod, t.sum
                from tosefot t
                left join netuney_sachar n
                  on t.seq_netuney_sachar = n.seq_netuney_sachar
               where n.seq_bakasha = p_seq_bakasha
                 and t.code_semel_tosefet in (133, 134, 135, 136)
                 and n.code_sug_maskoret = 3) loop
      v_fix_amount_old_world := v_fix_amount_old_world +
                                (r.sum / r.schar_ysod * 100);
    end loop;

    begin
      --Get seq_tosefet old_world
      select t1.seq_tosefot
        into v_seq_tosefet_old_world
        from tosefot t1
        left join netuney_sachar n1
          on t1.seq_netuney_sachar = n1.seq_netuney_sachar
       where n1.seq_bakasha = p_seq_bakasha
         and t1.code_semel_tosefet = 28
         and n1.code_sug_maskoret = 1;

      --Update Special Education in old world addition
      update tosefot t
         set t.amount = round(v_fix_amount_old_world, 2)
       where t.seq_tosefot = v_seq_tosefet_old_world;

      commit;
    exception
      when others then
        return;
    end;
  end;
  --------------------------------------------------------
  procedure fix_tosafot_old_world(p_seq_bakasha number) is
  begin
    fix_Special_Education(p_seq_bakasha);
    fix_hadracha(p_seq_bakasha);
  end;
  --------------------------------------------------------
  procedure update_mispar_misra(p_seq_bakasha number) is
  begin
    update netuney_sachar n
       set n.mispar_misra = 0
     where n.mispar_misra = 99
       and n.seq_bakasha = p_seq_bakasha;
  end;
  --------------------------------------------------------
  function update_netuney_sachar(p_seq_ld_chinuch_salary_01 number,
                                 p_seq_bakasha_for_compare  number,
                                 p_seq_bakasha_for_insert   number)
    return number is
    v_seq_netuney_sachar_1 number;
    v_seq_netuney_sachar_2 number;
    v_seq_netuney_sachar_3 number;
    v_seq_netuney_sachar_4 number;
    v_date_start_zakaut    date;
    v_code_darga_horah     number;

    v_is_get_new_salary number;
  begin

    v_date_start_zakaut := pk_salary_base_old.get_start_zakaut(p_seq_bakasha_for_compare);

    for r in (select t.*
                from ld_chinuch_salary_01 t
               where t.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01) loop
      --Update chinuch salary table
      update_chinuch_salary(p_seq_ld_chinuch_salary_01,
                            p_seq_bakasha_for_insert);

      -- 1
      select dc.code_darge
        into v_code_darga_horah
        from code_darga_chinuch_salary dc
       where dc.code_derug_chinuch_salary = 41
         and dc.code_darga_chinuch_salary = r.q;

      v_seq_netuney_sachar_1 := netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01,
                                                               p_seq_bakasha_for_insert,
                                                               v_date_start_zakaut,
                                                               1,
                                                               r.h,
                                                               r.i,
                                                               r.j,
                                                               r.k,
                                                               r.l,
                                                               41,
                                                               v_code_darga_horah,
                                                               r.ai,
                                                               r.aj);

      if nvl(v_seq_netuney_sachar_1, 0) <> 0 then
        update_vetek_detail_maskoret_1(p_seq_ld_chinuch_salary_01,
                                       p_seq_bakasha_for_insert,
                                       v_seq_netuney_sachar_1);

        insert_tosefot_complement_ofek(v_seq_netuney_sachar_1,
                                       r.o,
                                       r.l,
                                       r.k,
                                       r.n,
                                       r.m);
      end if;

      -- 2
      v_seq_netuney_sachar_2 := netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01,
                                                               p_seq_bakasha_for_insert,
                                                               v_date_start_zakaut,
                                                               2,
                                                               null,
                                                               null,
                                                               null,
                                                               r.k,
                                                               r.ac,
                                                               41,
                                                               v_code_darga_horah,
                                                               null,
                                                               null);

      if nvl(v_seq_netuney_sachar_2, 0) <> 0 then
        --vetek
        pk_salary_base_old.insert_vetek_detail(p_seq_bakasha_for_insert,
                                           6,
                                           r.ah,
                                           v_seq_netuney_sachar_2);

        insert_tosefot_complement_ofek(v_seq_netuney_sachar_2,
                                       r.ae,
                                       r.ac,
                                       r.k,
                                       r.ad,
                                       r.ak);

      end if;

      -- 3
      v_seq_netuney_sachar_3 := netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01,
                                                               p_seq_bakasha_for_insert,
                                                               v_date_start_zakaut,
                                                               3,
                                                               null,
                                                               null,
                                                               null,
                                                               r.m,
                                                               r.n,
                                                               --Code derug ofek is seved whith '99'
                                                               --because it is not a regular derug
                                                               r.x + 99000,
                                                               r.y,
                                                               null,
                                                               null);

      if nvl(v_seq_netuney_sachar_3, 0) <> 0 then
        --vetek
        update_vetek_detail_maskoret_3(p_seq_ld_chinuch_salary_01,
                                       p_seq_bakasha_for_insert,
                                       v_seq_netuney_sachar_3);
      end if;

      -- 4
      v_seq_netuney_sachar_4 := netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01,
                                                               p_seq_bakasha_for_insert,
                                                               v_date_start_zakaut,
                                                               4,
                                                               null,
                                                               null,
                                                               null,
                                                               r.ak,
                                                               r.ad,
                                                               --Code derug ofek is seved whith '99'
                                                               --because it is not a regular derug
                                                               r.x + 99000,
                                                               r.y,
                                                               null,
                                                               null);

      if nvl(v_seq_netuney_sachar_4, 0) <> 0 then
        --vetek
        pk_salary_base_old.insert_vetek_detail(p_seq_bakasha_for_insert,
                                           6,
                                           r.ag,
                                           v_seq_netuney_sachar_4);
      end if;

    end loop;

    v_is_get_new_salary := is_get_new_salary(p_seq_bakasha_for_compare,
                                             p_seq_bakasha_for_insert,
                                             v_seq_netuney_sachar_1,
                                             v_seq_netuney_sachar_2,
                                             v_seq_netuney_sachar_3,
                                             v_seq_netuney_sachar_4);

    if v_is_get_new_salary = 1 then
      --update mispar misra
      update_mispar_misra(p_seq_bakasha_for_insert);
      --Fix tosafot old world
      fix_tosafot_old_world(p_seq_bakasha_for_insert);
    end if;

    return v_is_get_new_salary;
  end;
  ------------------------------------------------
  function update_sachar_for_bakasha(p_seq_bakasha number) return number is
    v_result number;
  begin

    for r in (select max(s.seq_ld_chinuch_salary_01) seq_ld_chinuch_salary
                from v_bakasha v
                left join ld_chinuch_salary_01 s
                  on s.b = v.MISPAR_ZEHUT
               where v.SEQ_BAKASHA = p_seq_bakasha
                 and v.code_makor = 3) loop

      if r.seq_ld_chinuch_salary is null then
        return 0;
      end if;

      v_result := update_netuney_sachar(r.seq_ld_chinuch_salary,
                                        p_seq_bakasha,
                                        p_seq_bakasha);

      if v_result = 0 then
        rollback;
      else
        commit;
      end if;

      pk_salary_base_old.update_ld_salary_base(null,
                                           null,
                                           r.seq_ld_chinuch_salary,
                                           1,
                                           p_seq_bakasha);
    end loop;
    return 1;

  end;
  --------------------------------------------------------
  function main_chinuch(p_ld_protocol number) return clob is
    v_seq_bakasha number;
  begin

    for r in (select *
                from (select
                      --Id
                       t.b,
                       t.seq_ld_chinuch_salary_01,
                       --Get the last load for every id
                       first_value(t.seq_ld_chinuch_salary_01) over(partition by t.b order by t.seq_ld_chinuch_salary_01 desc) max_seq
                        from ld_chinuch_salary_01 t
                        left join ld_salary_base l
                          on t.seq_ld_chinuch_salary_01 =
                             l.seq_ld_chinuch_salary_01
                       where nvl(l.code_status_get, 0) in (0, 3)
                       and t.b in (13588553,
22595771,
24042145,
25706474,
27720143,
51971232,
52000866,
52066636,
52272234,
52278082,
52284197,
52585056,
52626025,
54705892,
55004444,
56253099,
56582554,
56680440,
57667404,
57826190,
58191214,
58444787,
58730573,
58816638,
58977042,
64459498,
67595769,
80497555,
306067711,
12640447,
22769004,
58328121
)
                       ) a
              --Filer: get the last rows for every id
               where a.seq_ld_chinuch_salary_01 = trunc(a.max_seq)) loop
      pk_salary_base_old.load_managment_id(p_ld_protocol,
                                       null,
                                       r.seq_ld_chinuch_salary_01,
                                       --Id
                                       r.b,
                                       --code_misrad_maskret of chinuch
                                       150,
                                       'pk_chinuch_salary_old');

      select b.seq_bakasha
        into v_seq_bakasha
        from ld_salary_base b
       where r.seq_ld_chinuch_salary_01 = b.seq_ld_chinuch_salary_01;

      --Transaction by id
      pk_salary_base_old.manage_actions(p_ld_protocol, v_seq_bakasha);

    end loop;
    return pk_salary_base_old.get_report(p_ld_protocol);
  end;
  --------------------------------------------------------
end;
/

create or replace package body prm_system_copy.pk_chinuch_salary_temp is
----------------------------------------------------------
function get_decimal_number(p_num number, p_digit_size number)
  return number is
begin
  if nvl(p_num, 0) > 0 then
    return p_num / power(10, p_digit_size);
  end if;
  return null;
end;
  --------------------------------------------------------
  procedure update_vetek_maskrt_ofek_kizba(p_seq_chinuch_salary_01 number,
                                           p_seq_bakasha           number,
                                           p_seq_netuney_sachar    number) is
  begin
    for r in (select t.*,t1.w nihul,t1.x yeutz,t1.y hadracha
                from ld_chinuch_salary_01 t
                left join ld_chinuch_salary_03 t1
                  on t.b = t1.b
                 and trunc(t1.load_date) = trunc(t.load_date)
                 and t1.c = 1
               where t.seq_ld_chinuch_salary_01 = p_seq_chinuch_salary_01) loop
    
      --nihol_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         7,
                                         r.nihul,
                                         p_seq_netuney_sachar);
      --yeuz_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         8,
                                         r.yeutz,
                                         p_seq_netuney_sachar);
      --hadracha_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         9,
                                         r.hadracha,
                                         p_seq_netuney_sachar);
    
      --salary seniority
     /* pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         6,
                                         r.c +
                                         Get_zahal_vetek_by_years(r.d),
                                         p_seq_netuney_sachar);*/
    
    end loop;
  end;

  --------------------------------------------------------

  function Get_zahal_vetek_by_years(p_zahal_vetek number) return number is
    v_vetek number;
  begin
    if p_zahal_vetek is not null then
      -- Divide months to years
      v_vetek := p_zahal_vetek / 12;
      --Round quarterly
      v_vetek := round(v_vetek / 25, 2) * 25;
    end if;
  
    return v_vetek;
  end;
  --------------------------------------------------------
  procedure update_vetek_detail_maskoret_1(p_seq_chinuch_salary_01 number,
                                           p_seq_bakasha           number,
                                           p_seq_netuney_sachar    number) is
  begin
    for r in (select t.*
                from ld_chinuch_salary_01 t
               where t.seq_ld_chinuch_salary_01 = p_seq_chinuch_salary_01) loop
    
      --salary seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         6,
                                         r.c +
                                         Get_zahal_vetek_by_years(r.d),
                                         p_seq_netuney_sachar);
    
      --horaha_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         1,
                                         r.c,
                                         p_seq_netuney_sachar);
    
      --zahal_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         2,
                                         Get_zahal_vetek_by_years(r.d),
                                         p_seq_netuney_sachar);
    
    end loop;
  end;
  --------------------------------------------------------
  procedure insert_tosefot(p_seq_netuney_sachar number,
                           p_code_semel_tosefet number,
                           p_sum                number,
                           p_amount             number,
                            p_percent             number) is
  begin
    if nvl(p_sum, 0) > 0 then
    
      --Insert to tosefot table
      insert into tosefot
        (seq_tosefot,
         seq_netuney_sachar,
         code_semel_tosefet,
         sum,
         amount,
         date_update,
         user_update)
      values
        (tosefot_seq.nextval,
         p_seq_netuney_sachar,
         p_code_semel_tosefet,
         get_decimal_number(p_sum,2),
         get_decimal_number(p_amount,2),
         sysdate,
         0);
    
    end if;
  end;
  --------------------------------------------------------
  procedure update_chinuch_salary(p_seq_ld_chinuch_salary_01 number,
                                  p_seq_bakasha              number) is
    v_date_begin_ofek date;
  begin
    for r in (select t1.*,t.r maskoret_kovaat_meshuklelet,t.ac maskoret_meshuklelet_gil_60
                from ld_chinuch_salary_03 t
                left join ld_chinuch_salary_01 t1
                 on t.b = t1.b
                 and trunc(t.load_date) = trunc(t1.load_date)
               where t1.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01
               ) loop
    
    
      merge into chinuch_salary l
      using dual
      on (l.seq_bakasha = p_seq_bakasha)
      when matched then
        update
           set l.maskoret_kovaat_meshuklelet    = get_decimal_number(r.maskoret_kovaat_meshuklelet,2),
           l.shaot_yeutz_chodesh_acharon = r.h,
           l.hekef_chanam = r.o,
           l.maskoret_kovaat_meshuklelet_60 = get_decimal_number(r.maskoret_meshuklelet_gil_60,2)
           /*,
              l.mkadem_misra_klali             = r.p,
               l.mkadem_misra                   = r.r,
               l.gmuley_hishtalmut              = r.s,
               l.kefel_toar                     = r.t,
               l.date_begin_ofek                = v_date_begin_ofek,
               l.kidum_darga_ofek               = r.w,
               l.hekef_misra_ofek               = r.aa,
               l.maskoret_kovaat_meshuklelet_60 = r.ae,
               l.tosefet_vetek_horah            = r.ab*/
        
      
      when not matched then
        insert
          ( l.maskoret_kovaat_meshuklelet,
          l.shaot_yeutz_chodesh_acharon,
          l.hekef_chanam,
          l.maskoret_kovaat_meshuklelet_60,
           /*l.mkadem_misra_klali,
           l.mkadem_misra,
           l.gmuley_hishtalmut,
           l.kefel_toar,
           l.date_begin_ofek,
           l.kidum_darga_ofek,
           l.hekef_misra_ofek,
           l.maskoret_kovaat_meshuklelet_60,
           l.tosefet_vetek_horah,*/
           l.seq_bakasha)
        values
          (get_decimal_number(r.maskoret_kovaat_meshuklelet,2),
          r.h,
          r.o,
          get_decimal_number(r.maskoret_meshuklelet_gil_60,2),
           /*r.p,
           r.r,
           r.s,
           r.t,
           v_date_begin_ofek,
           r.w,
           r.aa,
           r.ae,
           r.ab,*/
           p_seq_bakasha);
    
    end loop;
  end;
  --------------------------------------------------------
  function Get_code_semel_tosefet(v_mispar_zehut       number,
                                  v_code_semel_chinuch number,
                                  p_code_chinuch_reforma number,
                                  p_code_chinuch_alterntive number) return number is
    v_taarich_prisha     date;
    v_code_semel_tosefet number;
  begin
    select max(v.TAARICH_PRISHA)
      into v_taarich_prisha
      from v_bakasha_last_status v
     where v.mispar_zehut = v_mispar_zehut;
  
    --Get semel tosefet by date prisha 
    if v_taarich_prisha >= to_date('31082020', 'ddmmyyyy') then
      select max(s.code_semel_tosefet)
        into v_code_semel_tosefet
        from code_semel_tosefet s
       where (s.semel_sikum =p_code_chinuch_alterntive||'0'||p_code_chinuch_reforma ||lpad(v_code_semel_chinuch,4,'0') and p_code_chinuch_reforma is not null
             or p_code_chinuch_reforma is null and s.code_semel_tosefet = v_code_semel_chinuch)
       and s.sug_natun = 182
       fetch first 1 rows only;
    else
      select min(s.code_semel_tosefet)
        into v_code_semel_tosefet
        from code_semel_tosefet s
       where s.semel_chinuch = v_code_semel_chinuch
       and s.sug_natun = 106;
    end if;
  
    return v_code_semel_tosefet;
  end;
  --------------------------------------------------------
  procedure update_tosafot(p_seq_ld_chinuch_salary_01 number,
                           p_seq_netuney_sachar       number,
                           p_type_prisha              number,
                           p_type_reforma             number,
                           p_code_alternative         number,
                           p_code_sug_maskoret number) is
    v_code_semel_tosefet number;
    v_amount             number;
   
  begin
    --Loop over all additions
    for r in (select t2.*
                from ld_chinuch_salary_02 t2
                left join ld_chinuch_salary_01 t1
                  on to_number(t2.b) = to_number(t1.b)
                 and trunc(t2.load_date) = trunc(t1.load_date)
               where t1.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01
       --for maskoret kizba chinuch sends sug_maskoret = 0
         and (t2.e) = to_char(decode(p_type_prisha,1,0,p_type_prisha))
         --for maskoret pizuim chinuch sends reforma 0
         and (t2.c) = decode(p_code_sug_maskoret,14,00,10,00, p_type_reforma)
         --for maskoret pizuim chinuch sends alterntive 0
         and (t2.d) = decode(p_code_sug_maskoret,14,0,10,0, p_code_alternative)
         and (t2.f) not in (1, 10,102)) loop
    
      --Get code_semel_tosefet
      v_code_semel_tosefet := Get_code_semel_tosefet(r.b, r.f,p_type_reforma,p_code_alternative);
    
      --When code_semel_tosefet is null
      if v_code_semel_tosefet is null then
        pk_salary_base.code_addition_not_exist(r.f, p_seq_netuney_sachar);
        --Continue to the next addition
        continue;
      end if;
      
      --tosefet hishtalmut-nipuach amount with 1.2
    if r.f in (39,249) then
       v_amount := r.j * 1.2;
       else 
         v_amount := r.j;
    end if;
      --Insert to tosefot table
      insert_tosefot(p_seq_netuney_sachar, v_code_semel_tosefet, r.i, v_amount, r.h);
    
    end loop;
  end;
  -------------------------------------------------------
  function netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01 number,
                                          p_seq_bakasha_for_insert   number,
                                          p_date_start_zakaut        date,
                                          p_code_sug_maskoret        number,
                                          p_sum_havraa               number,
                                          p_sum_bigud                number,
                                          p_is_maanak_yovel          number,
                                          p_chodashim                number,
                                          p_maskoret_kovaat          number,
                                          p_code_derug               number,
                                          p_code_darga               number,
                                          p_havraa_days              number,
                                          p_ramat_bigud              number,
                                          p_seq_reforma              number
                                          )
    return number is
    v_seq_netuney_sachar      number;
    v_type_prisha             number;
    v_type_reforma            number;
    v_count_derug_darga       number;
    v_base_salary             number;
    v_code_chinuch_alterntive number;
  begin
    if nvl(p_maskoret_kovaat, 0) = 0 then
      return null;
    end if;
  
    v_seq_netuney_sachar := netuney_sachar_seq.nextval;
  
    select nvl(t.code_chinuch_alterntive,0), t.code_chinuch_sug_maskoret
      into v_code_chinuch_alterntive, v_type_prisha
      from code_sug_maskoret t
     where t.code_sug_maskoret = p_code_sug_maskoret
    and t.code_makor=3;
  
    if p_seq_reforma is not null then
       select t.code_reforma
      into v_type_reforma
      from chinuch_reforma t
     where t.seq_chinuch_reforma = p_seq_reforma;
     end if;
  
    begin
      select sum(get_decimal_number(t2.i,2))
        into v_base_salary
        from ld_chinuch_salary_02 t2
        left join ld_chinuch_salary_01 t1
          on to_number(t2.b) = to_number(t1.b)
         and trunc(t2.load_date) = trunc(t1.load_date)
       where t1.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01
       --for maskoret kizba chinuch sends sug_maskoret = 0
         and to_number(t2.e) = to_char(decode(v_type_prisha,1,0,v_type_prisha))
         --for maskoret pizuim chinuch sends reforma 0
         and to_number(t2.c) = decode(p_code_sug_maskoret,14,00,10,00, v_type_reforma)
         --for maskoret pizuim chinuch sends alterntive 0
         and to_number(t2.d) = decode(p_code_sug_maskoret,14,0,10,0, v_code_chinuch_alterntive)
            --Get base salary
         and (t2.f) in ('0001','0010','0102');
    exception
      when others then
        v_base_salary := null;
    end;
  
    --select from code_darge in order to check that we have the codes
    --and when the codes is not exist, set null.
    select count(*)
      into v_count_derug_darga
      from code_darga d
     where d.code_derug = p_code_derug
       and d.code_darga = p_code_darga;
  
    insert into netuney_sachar
      (seq_netuney_sachar,
       seq_bakasha,
       mispar_misra,
       code_sug_maskoret,
       sum_havraa,
       sum_bigud,
       is_maanak_yovel,
       chodashim,
       maskoret_kovaat,
       code_derug,
       code_darga,
       date_update,
       user_update,
       from_date,
       schar_ysod,
       havraa_days,
       ramat_bigud,
       seq_chinuch_reforma)
    values
      (v_seq_netuney_sachar,
       p_seq_bakasha_for_insert,
       --The next value is temp in order to compare 2 same rows
       --And will updated in end
       99,
       p_code_sug_maskoret,
       p_sum_havraa,
       p_sum_bigud,
       p_is_maanak_yovel,
       p_chodashim,
       p_maskoret_kovaat,
       case when v_count_derug_darga > 0 then p_code_derug else null end,
       case when v_count_derug_darga > 0 then p_code_darga else null end,
       sysdate,
       0,
       p_date_start_zakaut,
       v_base_salary,
       p_havraa_days,
       p_ramat_bigud,p_seq_reforma);
  
    update_tosafot(p_seq_ld_chinuch_salary_01,
                   v_seq_netuney_sachar,
                   v_type_prisha,
                   v_type_reforma,
                   v_code_chinuch_alterntive,
                   p_code_sug_maskoret);
  
    return v_seq_netuney_sachar;
  end;
  --------------------------------------------------------
  procedure insert_extra_to_maskoret_kovaat(p_seq_netuney_sachar number,
                                            p_sum_to_add         number) is
  begin
    update netuney_sachar n
       set n.maskoret_kovaat = round(n.maskoret_kovaat + p_sum_to_add, 2)
     where n.seq_netuney_sachar = p_seq_netuney_sachar;
  end;
  --------------------------------------------------------
  procedure insert_extra_to_addition_chinuch(p_seq_tosefet number,
                                             p_sum_to_add  number) is
  begin
    update tosefot n
       set n.sum = round(n.sum + p_sum_to_add, 2)
     where n.seq_tosefot = p_seq_tosefet;
  end;
  --------------------------------------------------------
  function Calc_extra_addition_education(p_seq_netuney_sachar number,
                                         p_orginal_sum        number)
    return number is
    v_factor            number;
    v_achuz_kizba       number;
    v_chelkiyut_sofit   number;
    v_code_sug_maskoret number;
  begin
    select n.code_sug_maskoret
      into v_code_sug_maskoret
      from netuney_sachar n
     where n.seq_netuney_sachar = p_seq_netuney_sachar;
  
    if v_code_sug_maskoret = 1 then
    
      select n2.achuz_kizba_sofi, n2.chelkiyut_sofit
        into v_achuz_kizba, v_chelkiyut_sofit
        from netuney_sachar n
        left join (select max(v.seq_bakasha) seq_bakasha,
                          v.current_seq_bakasha
                     from v_mechushavim_2_curnt_and_prev v
                    where v.code_department = 2
                    group by v.current_seq_bakasha) v
          on v.current_seq_bakasha = n.seq_bakasha
        left join netuney_tik_mechushavim n2
          on v.seq_bakasha = n2.seq_bakasha
         and n2.code_department = 2
         and n2.mispar_misra = 0
       where n.seq_netuney_sachar = p_seq_netuney_sachar;
    
    elsif v_code_sug_maskoret = 2 then
    
      select n2.achuz_kizba_gil_60,
             --Get chelkiyut
             case
               when n2.code_group_prisha = 2 and n2.is_zakai_lmaanak = 1 then
                n2.chelkiyut_meshuklelet_sherut
               else
                n2.chelkiyut_sofit
             end
        into v_achuz_kizba, v_chelkiyut_sofit
        from netuney_sachar n
        left join (select max(v.seq_bakasha) seq_bakasha,
                          v.current_seq_bakasha
                     from v_mechushavim_2_curnt_and_prev v
                    where v.code_department = 2
                    group by v.current_seq_bakasha) v
          on v.current_seq_bakasha = n.seq_bakasha
        left join netuney_tik_mechushavim n2
          on v.seq_bakasha = n2.seq_bakasha
         and n2.code_department = 2
         and n2.mispar_misra = 0
       where n.seq_netuney_sachar = p_seq_netuney_sachar;
    end if;
  
    v_factor := least(greatest(nvl(v_achuz_kizba, 0), 70) / 70 *
                      nvl(v_chelkiyut_sofit, 0),
                      1);
  
    if v_factor = 0 then
      return 0;
    end if;
  
    return(p_orginal_sum / round(v_factor, 4))
    --Get only the extra
    - p_orginal_sum;
  end;

  --------------------------------------------------------
  function calc_complement_ofek_a(p_maskoret_kovaat_meshukll_old number,
                                  p_maskoret_kovaat_old          number)
    return number is
  begin
    return nvl(p_maskoret_kovaat_meshukll_old, 0) - nvl(p_maskoret_kovaat_old,
                                                        0);
  end;

  --------------------------------------------------------
  function calc_complement_ofek_b(p_seq_netuney_sachar   number,
                                  p_orginal_sum_tosefet  number,
                                  p_maskoret_kovaat_old  number,
                                  p_chodashim_old        number,
                                  p_maskoret_kovaat_ofek number,
                                  p_chodashim_ofek       number)
    return number is
    v_calc_maskoret_kovaat_old number;
    v_total_chodashim          number;
    v_partial_maskoret_old     number;
    v_partial_maskoret_ofek    number;
    v_total_maskoret           number;
    v_extra_addition           number;
  begin
    v_extra_addition := Calc_extra_addition_education(p_seq_netuney_sachar,
                                                      p_orginal_sum_tosefet);
  
    v_calc_maskoret_kovaat_old := nvl(v_extra_addition, 0) +
                                  nvl(p_maskoret_kovaat_old, 0);
  
    v_total_chodashim := nvl(p_chodashim_old, 0) + nvl(p_chodashim_ofek, 0);
  
    v_partial_maskoret_old := v_calc_maskoret_kovaat_old * p_chodashim_old /
                              v_total_chodashim;
  
    v_partial_maskoret_ofek := p_maskoret_kovaat_ofek * p_chodashim_ofek /
                               v_total_chodashim;
  
    v_total_maskoret := v_partial_maskoret_old + v_partial_maskoret_ofek;
  
    return round(v_total_maskoret - v_calc_maskoret_kovaat_old, 2);
  end;

  --------------------------------------------------------
  procedure insert_tosefot_complement_ofek(p_seq_netuney_sachar           number,
                                           p_maskoret_kovaat_meshukll_old number,
                                           p_maskoret_kovaat_old          number,
                                           p_chodashim_old                number,
                                           p_maskoret_kovaat_ofek         number,
                                           p_chodashim_ofek               number) is
    v_sum_tosefet_chinuch           number;
    v_extra_tosefet_complement_ofek number;
    v_extra_tosefet_chinuch         number;
    v_seq_tosefet                   number;
    v_code_sug_maskoret             number;
  begin
  
    begin
      select n.code_sug_maskoret, t.seq_tosefot, t.sum
        into v_code_sug_maskoret, v_seq_tosefet, v_sum_tosefet_chinuch
        from tosefot t
        left join netuney_sachar n
          on t.seq_netuney_sachar = n.seq_netuney_sachar
       where t.seq_netuney_sachar = p_seq_netuney_sachar
         and t.code_semel_tosefet in (3073, 3074);
    exception
      when others then
        v_sum_tosefet_chinuch := null;
    end;
  
    if v_sum_tosefet_chinuch is null then
      v_extra_tosefet_complement_ofek := calc_complement_ofek_a(p_maskoret_kovaat_meshukll_old,
                                                                p_maskoret_kovaat_old);
    else
      v_extra_tosefet_complement_ofek := calc_complement_ofek_b(p_seq_netuney_sachar,
                                                                v_sum_tosefet_chinuch,
                                                                p_maskoret_kovaat_old,
                                                                p_chodashim_old,
                                                                p_maskoret_kovaat_ofek,
                                                                p_chodashim_ofek);
    
      if v_code_sug_maskoret = 2 then
        --Calc extra tosefet chinuch
        v_extra_tosefet_chinuch := Calc_extra_addition_education(p_seq_netuney_sachar,
                                                                 v_sum_tosefet_chinuch);
        --update tosefet chinuch
        insert_extra_to_addition_chinuch(v_seq_tosefet,
                                         v_extra_tosefet_chinuch);
      
        --update maskoret  
        insert_extra_to_maskoret_kovaat(p_seq_netuney_sachar,
                                        v_extra_tosefet_chinuch);
      end if;
    end if;
  
    --insert tosefet
    insert_tosefot(p_seq_netuney_sachar,
                   879,
                   v_extra_tosefet_complement_ofek,
                   null,
                   null);
    --update maskoret  
    insert_extra_to_maskoret_kovaat(p_seq_netuney_sachar,
                                    v_extra_tosefet_complement_ofek);
  end;
  --------------------------------------------------------
  function is_get_new_salary(p_seq_bakasha_for_compare number,
                             p_seq_bakasha_for_insert  number) return number is
    v_is_get_new_salary number :=1;
    v_count_rows_new number;
    v_exists_netuney_sachar number;
    v_odef                  number;
  
  begin
    
  --there is no netuney sachar in p_seq_bakasha_for_compare
  select count(*)
  into v_exists_netuney_sachar 
  from netuney_sachar n
  where n.seq_bakasha=p_seq_bakasha_for_compare;
  
  --if there is odef-check maskoret pizuim
 select nvl(sum( nvl(v.odef_sherut_chodashim,0)+nvl(v.odef_sherut_yamim,0)),0)
 into v_odef
 from bakasha b
 left join v_prisha_last_zakaut tt
 on b.seq_prisha=tt."SEQ_PRISHA"
 left join netuney_tik_mechushavim v
 on v.seq_bakasha=tt."SEQ_BAKASHA_ZAKAUT"
 where b.seq_bakasha=p_seq_bakasha_for_insert
 and v.mispar_misra=0 and v.code_department=2;
 
 
 v_is_get_new_salary:=0;
 --compare maskoret_kovaat
 
    select count(*)
      into v_count_rows_new
      from (select t1.code_reforma, t.maskoret_kovaat
              from netuney_sachar t
              left join chinuch_reforma t1
                on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
             where t.seq_bakasha = p_seq_bakasha_for_compare
               and (p_seq_bakasha_for_compare <> p_seq_bakasha_for_insert or
                   t.mispar_misra = 99)
                  
               and (t.code_sug_maskoret <> 14)
            minus
            select t1.code_reforma, t.maskoret_kovaat
              from netuney_sachar t
              left join chinuch_reforma t1
                on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
             where t.seq_bakasha = p_seq_bakasha_for_insert
               and (p_seq_bakasha_for_compare <> p_seq_bakasha_for_insert or
                   t.mispar_misra = 0)
               and (t.code_sug_maskoret <> 14)
            
            );
   
    if v_exists_netuney_sachar = 0 or nvl(v_count_rows_new, 0) > 0 then
        v_is_get_new_salary:=1;
    else 
      --check havara bigud
        select count(*)
          into v_count_rows_new
          from (select t1.code_reforma,
                       t.havraa_days,
                       t.sum_bigud,
                       t.ramat_bigud,
                       t.is_maanak_yovel
                  from netuney_sachar t
                  left join chinuch_reforma t1
                    on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
                 where t.seq_bakasha = p_seq_bakasha_for_compare
                   and (p_seq_bakasha_for_compare <> p_seq_bakasha_for_insert or
                       t.mispar_misra = 99)
                   and (t.code_sug_maskoret <> 14)
                minus
                select t1.code_reforma,
                       t.havraa_days,
                       t.sum_bigud,
                       t.ramat_bigud,
                       t.is_maanak_yovel
                  from netuney_sachar t
                  left join chinuch_reforma t1
                    on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
                 where t.seq_bakasha = p_seq_bakasha_for_insert
                   and (p_seq_bakasha_for_compare <> p_seq_bakasha_for_insert or
                       t.mispar_misra = 0)
                   and (t.code_sug_maskoret <> 14)
                
                );
            if nvl(v_count_rows_new, 0) > 0 then
               v_is_get_new_salary:=2;
            end if;
        --check odef
          if v_odef>0 then
          select count(*)
            into v_count_rows_new
            from (select t1.code_reforma, t.maskoret_kovaat
                    from netuney_sachar t
                    left join chinuch_reforma t1
                      on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
                   where t.seq_bakasha = p_seq_bakasha_for_compare
                     and (p_seq_bakasha_for_compare <> p_seq_bakasha_for_insert or
                         t.mispar_misra = 99)
                        
                     and (t.code_sug_maskoret = 14)
                  minus
                  select t1.code_reforma, t.maskoret_kovaat
                    from netuney_sachar t
                    left join chinuch_reforma t1
                      on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
                   where t.seq_bakasha = p_seq_bakasha_for_insert
                     and (p_seq_bakasha_for_compare <> p_seq_bakasha_for_insert or
                         t.mispar_misra = 0)
                     and (t.code_sug_maskoret = 14)
                  
                  );
           if v_count_rows_new > 0 then
             v_is_get_new_salary:=3;
            end if;
       end if;
       
      end if;
        
                

    
    if nvl(v_is_get_new_salary, 0) = 0 then
      return 0;
    else
      return v_is_get_new_salary;
    end if;
  end;

  --------------------------------------------------------
  procedure fix_hachshara(p_seq_bakasha number) is
    v_seq_tosefot_hachshara number;
  begin
    select t.seq_tosefot
      into v_seq_tosefot_hachshara
      from tosefot t
      left join netuney_sachar n
        on t.seq_netuney_sachar = n.seq_netuney_sachar
     where n.seq_bakasha = p_seq_bakasha
       and t.code_semel_tosefet = 865
       and n.code_sug_maskoret = 1;
  
    update tosefot t
       set t.amount = 100
     where t.seq_tosefot = v_seq_tosefot_hachshara;
    commit;
  exception
    when others then
      return;
  end;
  --------------------------------------------------------
  procedure fix_hadracha(p_seq_bakasha number) is
    v_amount_tosefet_hadracha_ofek number;
    v_years_vetek_hadracha_ofek    number;
    v_percent_by_years_vetek       number;
    v_percent_by_amount_tosefet    number;
  
    v_seq_tosefet_old_world number;
  begin
    select t1.amount, v.years
      into v_amount_tosefet_hadracha_ofek, v_years_vetek_hadracha_ofek
      from tosefot t1
      left join netuney_sachar n1
        on t1.seq_netuney_sachar = n1.seq_netuney_sachar
      left join vetek_detail v
        on n1.seq_netuney_sachar = v.seq_netuney_sachar
          --vetek hadracha
       and v.code_type_vetek = 9
     where n1.seq_bakasha = p_seq_bakasha
          --tosefet hadracha
       and t1.code_semel_tosefet = 524
          --maskoret ofek
       and n1.code_sug_maskoret = 3;
  
    --Get percent by years vetek
    select v.percent
      into v_percent_by_years_vetek
      from perm_guidance_vetek_years v
     where v.years_in_ofek = case
             when v_years_vetek_hadracha_ofek > 13 then
              13
             else
              v_years_vetek_hadracha_ofek
           end;
  
    --Get multiplication by amount tosefet
    select t.multiplication
      into v_percent_by_amount_tosefet
      from perm_guidance_tosefet_amount t
     where t.amount_in_ofek = v_amount_tosefet_hadracha_ofek;
  
    --Get seq_tosefet old_world
    select t1.seq_tosefot
      into v_seq_tosefet_old_world
      from tosefot t1
      left join netuney_sachar n1
        on t1.seq_netuney_sachar = n1.seq_netuney_sachar
     where n1.seq_bakasha = p_seq_bakasha
          --hadracha
       and t1.code_semel_tosefet = 524
       and n1.code_sug_maskoret = 1;
  
    --Update new amount in old world
    update tosefot t
       set t.amount = round(v_percent_by_years_vetek *
                            v_percent_by_amount_tosefet / 100,
                            2)
     where t.seq_tosefot = v_seq_tosefet_old_world;
    commit;
  
    fix_hachshara(p_seq_bakasha);
  exception
    when others then
      return;
  end;

  --------------------------------------------------------
  procedure fix_Special_Education(p_seq_bakasha number) is
    v_fix_amount_old_world  number := 0;
    v_seq_tosefet_old_world number;
  begin
    --Loop over additions new world
    for r in (select n.schar_ysod, t.sum
                from tosefot t
                left join netuney_sachar n
                  on t.seq_netuney_sachar = n.seq_netuney_sachar
               where n.seq_bakasha = p_seq_bakasha
                 and t.code_semel_tosefet in (133, 134, 135, 136)
                 and n.code_sug_maskoret = 3) loop
      v_fix_amount_old_world := v_fix_amount_old_world +
                                (r.sum / r.schar_ysod * 100);
    end loop;
  
    begin
      --Get seq_tosefet old_world
      select t1.seq_tosefot
        into v_seq_tosefet_old_world
        from tosefot t1
        left join netuney_sachar n1
          on t1.seq_netuney_sachar = n1.seq_netuney_sachar
       where n1.seq_bakasha = p_seq_bakasha
         and t1.code_semel_tosefet = 28
         and n1.code_sug_maskoret = 1;
    
      --Update Special Education in old world addition
      update tosefot t
         set t.amount = round(v_fix_amount_old_world, 2)
       where t.seq_tosefot = v_seq_tosefet_old_world;
    
      commit;
    exception
      when others then
        return;
    end;
  end;
  --------------------------------------------------------
  procedure fix_tosafot_old_world(p_seq_bakasha number) is
  begin
    fix_Special_Education(p_seq_bakasha);
    fix_hadracha(p_seq_bakasha);
  end;
  --------------------------------------------------------
  procedure update_mispar_misra(p_seq_bakasha number) is
  begin
    update netuney_sachar n
       set n.mispar_misra = 0
     where n.mispar_misra = 99
       and n.seq_bakasha = p_seq_bakasha;
  end;
  --------------------------------------------------------
  function update_netuney_sachar(p_seq_ld_chinuch_salary_01 number,
                                 p_seq_bakasha_for_compare  number,
                                 p_seq_bakasha_for_insert   number)
    return number is
  v_is_get_new_salary number;
  begin
    update_reforma(p_seq_bakasha_for_insert,
                   p_seq_ld_chinuch_salary_01);
    update_mitve_nur(p_seq_bakasha_for_insert,
                   p_seq_ld_chinuch_salary_01);         
    update_chinuch_salary(p_seq_ld_chinuch_salary_01,
                              p_seq_bakasha_for_insert);
   
   /* v_is_get_new_salary := is_get_new_salary(p_seq_bakasha_for_compare,
                                             p_seq_bakasha_for_insert);
  
    if v_is_get_new_salary > 0 then
      
    if p_seq_bakasha_for_compare = p_seq_bakasha_for_insert then
     delete_old_data(p_seq_bakasha_for_insert);  
    end if;  */
    
      --update mispar misra
      update_mispar_misra(p_seq_bakasha_for_insert);
      --Fix tosafot old world
      fix_tosafot_old_world(p_seq_bakasha_for_insert);
  --  end if;
  
    return v_is_get_new_salary;
  end;
  ------------------------------------------------
  procedure update_reforma(p_seq_bakasha              number,
                           p_seq_ld_chinuch_salary_01 number) is
    v_seq_chinuch_reforma number;
    v_code_derug          number;
    v_code_darga          number;
    v_code_darga_mimshak          number;
    v_exist_ofek number;
  begin
  
    for r in (select s.*,case when s.c in (3,4) then s1.p when s1.c=2then s1.q else null end gmulim_before_prisha,case when s.c=1 then s1.o else null end as mikdama,s1.r as darga_mimshak
                from ld_chinuch_salary_03 s
                left join ld_chinuch_salary_01 s1
                  on s.b = s1.b
                 and trunc(s1.load_date) = trunc(s.load_date)
               where s1.seq_ld_chinuch_salary_01 =
                     p_seq_ld_chinuch_salary_01
                     order by s.c) loop
  
      if r.c = 1 then
      v_exist_ofek :=1;  
      end if;
      
      v_seq_chinuch_reforma := chinuch_reforma_seq.nextval;  
    
    
     insert into chinuch_reforma
        (seq_chinuch_reforma,
       seq_bakasha,
       code_reforma,
       begin_date,
       factor,
       is_last_year,
       code_chinuch_alterntive,
       max_sum,
       months_a,
       months_b,
       gmulim_before_reforma_f,
       gmulim_before_prisha,
       mekadem_2_3,
       mispar_kidumim,
       murkavut,
       shanim_reforma,
       chodashim_mikdama
       )
      values
        (v_seq_chinuch_reforma,
         p_seq_bakasha,
         r.c,
         case when r.z > 0 then to_date(r.z,'ddmmyyyy')else null end,
         get_decimal_number(r.q,4),
         case when nvl(r.ad,0)>0 then 1 else 0 end,
         case when to_number(r.c)=4 then 1 else to_number(r.d) end,
         get_decimal_number(r.p,2),
         case when r.c=1 or r.c=2 and v_exist_ofek = 1 then r.an else r.e end,
         case when r.c=1 or r.c=2 and v_exist_ofek = 1 then r.ao else r.f end,
         r.s,
         r.gmulim_before_prisha,
         r.t,
         get_decimal_number(r.u,1),
         r.ag,
         get_decimal_number(r.v,2),
         r.mikdama);
    
      --derug and darga 
    /*if r.c <>1 or r.d = 2 then*/
    v_code_darga_mimshak:=r.af;
    if r.c = 1  then
      v_code_darga_mimshak:=r.darga_mimshak;
    end if;
      select dc.code_darge, dc.code_derug
        into v_code_darga, v_code_derug
        from code_darga_chinuch_salary dc
       where dc.code_derug_chinuch_salary = 41
         and dc.code_darga_chinuch_salary = v_code_darga_mimshak;
     /*else--derug for ofek sachar acharon, alays begin 99
       select dc.code_darga, dc.code_derug
         into v_code_darga, v_code_derug
         from code_darga dc
        where dc.code_derug = r.ae + 99000
          and dc.code_darga = r.af;
     end if;*/
      update_netuney_sachar_for_rfrm(p_seq_ld_chinuch_salary_01,
                                     r.seq_ld_chinuch_salary_03,
                                     v_seq_chinuch_reforma,
                                     p_seq_bakasha,
                                     v_code_darga,
                                     v_code_derug,
                                     r.c,
                                     r.d,
                                     v_exist_ofek);
                                     
    update_bakarot(p_seq_bakasha,
                   p_seq_ld_chinuch_salary_01,
                   v_seq_chinuch_reforma,
                   r.c)  ;                                    
    end loop;
  end;
  --------------------------------------------------------
  procedure update_netuney_sachar_for_rfrm(p_seq_ld_chinuch_salary_01 number,
                                           p_seq_ld_chinuch_salary_03 number,
                                           p_seq_chinuch_reforma      number,
                                           p_seq_bakasha              number,
                                           p_code_darga               number,
                                           p_code_derug               number,
                                           p_code_reforma             number,
                                           p_code_chosen_alterntive   number,
                                           p_exists_ofek              number) is
    v_seq_netuney_sachar    number;
    v_seq_netuney_sachar_60 number;
    v_seq_netuney_sachar_pizuim number;
    v_date_start_zakaut     date;
    v_code_sug_maskoret     number;
    v_sum_havraa            number;
    v_sum_bigud             number;
    v_is_maanak_yovel       number;
    v_havraa_days           number;
    v_ramat_bigud           number;
    v_maskoret_gil_60       number;
    v_sug_maskoret_gil_60   number;
    v_maskoret_pizuim   number;
    v_chodashim_gil_60      number;
    v_exists_pizuim         number;
    v_vetek_horaa number;
    v_vetek_gil_60          number;
    v_vetek_ofek_gil_60          number;
    v_derug_ofek                 number;
    v_darga_ofek                 number;
    cursor r1 is
      select *
        from ld_chinuch_salary_01 t
       where t.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01;
  
    r r1%ROWTYPE;
  
  
  begin
  
   
    select r.e, r.f, r.g, r.l, r.m,r.c,r.k,r.j
      into v_sum_havraa,
           v_sum_bigud,
           v_is_maanak_yovel,
           v_havraa_days,
           v_ramat_bigud,
           v_vetek_horaa,
           v_vetek_gil_60,
           v_vetek_ofek_gil_60
      from ld_chinuch_salary_01 r
     where r.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01;
  
  
  v_date_start_zakaut := pk_salary_base.get_start_zakaut(p_seq_bakasha);
  
    for c in(select *
        from ld_chinuch_salary_03 t
       where t.seq_ld_chinuch_salary_03 = p_seq_ld_chinuch_salary_03
         and t.c = p_code_reforma)loop
    
  
    --sachar acharon kizba
    if nvl(c.m, 0) <> 0 then
    if p_code_reforma = 1 then
      select dc.code_darga, dc.code_derug
         into v_darga_ofek, v_derug_ofek
         from code_darga dc
        where dc.code_derug = c.ae + 99000
          and dc.code_darga = c.af;
    end if;
      v_seq_netuney_sachar := netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01,
                                                             p_seq_bakasha,
                                                             v_date_start_zakaut,
                                                             5,
                                                             v_sum_havraa,
                                                             v_sum_bigud,
                                                             v_is_maanak_yovel,
                                                             case when c.c=1 or c.c=2 and p_exists_ofek = 1 then c.ao else c.f end, --chodashim reforma b
                                                             get_decimal_number(c.m,2), --maskoret kovaat reforma chalufa 2 tkufot
                                                             case when p_code_reforma <> 1 then p_code_derug else v_derug_ofek end,
                                                             case when p_code_reforma <> 1 then p_code_darga else v_darga_ofek end,
                                                             v_havraa_days,
                                                             v_ramat_bigud,
                                                             p_seq_chinuch_reforma
                                                             );
    end if;
  
    update netuney_sachar t
       set t.maskoret_kovaat_sum            = get_decimal_number(c.j,2),
           t.maskoret_kovaat_percent        = get_decimal_number(c.k,2),
           t.maskoret_kovaat_shiur_miztaber = get_decimal_number(c.l,2)
     where t.seq_netuney_sachar = v_seq_netuney_sachar;
  
    ---vetek
    if nvl(v_seq_netuney_sachar, 0) <> 0 then
      --vetek not for ofek
      
        update_vetek_detail_maskoret_1(p_seq_ld_chinuch_salary_01,
                                       p_seq_bakasha,
                                       v_seq_netuney_sachar);
     if p_code_reforma = 1 then 
        --vetek for 
        update_vetek_maskrt_ofek_kizba(p_seq_ld_chinuch_salary_01,
                                       p_seq_bakasha,
                                      v_seq_netuney_sachar);
      end if;
    end if;
  
    --reshet bitachon
    if nvl(c.o, 0) <> 0 then
      --maskoret kovaat chalufa
      v_seq_netuney_sachar := netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01,
                                                             p_seq_bakasha,
                                                             v_date_start_zakaut,
                                                             8,
                                                             v_sum_havraa,
                                                             v_sum_bigud,
                                                             v_is_maanak_yovel,
                                                             case when c.c=1 or c.c=2 and p_exists_ofek = 1 then c.ao else c.f end, --chodashim reforma b
                                                             get_decimal_number(c.o,2), --maskoret kovaat reforma chalufa reshet bitachon
                                                             p_code_derug,
                                                             p_code_darga,
                                                             v_havraa_days,
                                                             v_ramat_bigud,
                                                             p_seq_chinuch_reforma);
      if v_seq_netuney_sachar is not null then
        update netuney_sachar t
           set t.maskoret_kovaat_tosefet = get_decimal_number(c.n,2)
         where t.seq_netuney_sachar = v_seq_netuney_sachar;
      
        
          update_vetek_detail_maskoret_1(p_seq_ld_chinuch_salary_01,
                                         p_seq_bakasha,
                                         v_seq_netuney_sachar);
        
        if p_code_reforma = 1 then
        
          --vetek for 
          update_vetek_maskrt_ofek_kizba(p_seq_ld_chinuch_salary_01,
                                         p_seq_bakasha,
                                         v_seq_netuney_sachar);
        end if;
      end if;
    end if;
  
    --maskoret gil 60 by alternative
    if p_code_chosen_alterntive = 1 or p_code_reforma = 4 then
      v_sug_maskoret_gil_60 := 6;
      v_maskoret_gil_60 := get_decimal_number(c.ak,2);
    elsif p_code_chosen_alterntive = 2 then
      v_sug_maskoret_gil_60 := 9;
      v_maskoret_gil_60 := get_decimal_number(c.al,2);
    end if;
  
    if nvl(c.ac, 0) <> 0 then
      v_seq_netuney_sachar_60 := netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01,
                                                                p_seq_bakasha,
                                                                v_date_start_zakaut,
                                                                v_sug_maskoret_gil_60,
                                                                v_sum_havraa,
                                                                v_sum_bigud,
                                                                v_is_maanak_yovel,
                                                                c.aj , --chodashim reforma gil 60
                                                                v_maskoret_gil_60, --maskoret kovaat gil 60 
                                                                case when p_code_reforma <> 1 or p_code_chosen_alterntive <> 1 then p_code_derug else v_derug_ofek end,
                                                                case when p_code_reforma <> 1 or p_code_chosen_alterntive <> 1 then p_code_darga else v_darga_ofek end,
                                                                v_havraa_days,
                                                             v_ramat_bigud,
                                                                p_seq_chinuch_reforma);
    
      if v_seq_netuney_sachar_60 is not null then      
          update netuney_sachar t
       set t.maskoret_kovaat_percent            = get_decimal_number(c.ai,2)
     where t.seq_netuney_sachar = v_seq_netuney_sachar_60;
          
          --vetek gil 60
          pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                             6,
                                             case when p_code_reforma <> 1 then v_vetek_gil_60 else v_vetek_ofek_gil_60 end,
                                             v_seq_netuney_sachar_60);
                       --vetek mukdam
      if p_code_chosen_alterntive = 1 and nvl(c.aa,0) > 0 then                                   
             pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                             10,
                                             c.aa,
                                             v_seq_netuney_sachar_60); 
          end if;
      end if;
    end if;
 
   
  v_maskoret_pizuim := c.ah;
    
  end loop;
  
  if nvl(v_maskoret_pizuim, 0) <> 0 then
    
   --maskoret pitzuim by alternative
   /* if p_code_chosen_alterntive = 1 then
      v_sug_maskoret_gil_pizuim := 7;
    elsif p_code_chosen_alterntive = 2 then
      v_sug_maskoret_gil_pizuim := 10;
    end if;*/
  select count(*)
    into v_exists_pizuim
    from netuney_sachar t
    where t.seq_bakasha = p_seq_bakasha
    and t.code_sug_maskoret = 14
    and t.mispar_misra = 99;
    
    if v_exists_pizuim = 0 then
      v_seq_netuney_sachar_pizuim := netuney_sachar_by_sug_maskoret(p_seq_ld_chinuch_salary_01,
                                                                p_seq_bakasha,
                                                                v_date_start_zakaut,
                                                                14,
                                                                v_sum_havraa,
                                                                v_sum_bigud,
                                                                v_is_maanak_yovel,
                                                               null,
                                                                get_decimal_number(v_maskoret_pizuim,2),
                                                                p_code_derug,
                                                                p_code_darga,
                                                                v_havraa_days,
                                                                v_ramat_bigud,
                                                                null);
    
      if v_seq_netuney_sachar_pizuim is not null  then
        
          --vetek pizuim
          update_vetek_detail_maskoret_1(p_seq_ld_chinuch_salary_01,
                                       p_seq_bakasha,
                                       v_seq_netuney_sachar_pizuim);
      end if;
      end if;
    end if;
  
  end;
  ------------------------------------------------
  procedure update_mitve_nur(p_seq_bakasha              number,
                             p_seq_ld_chinuch_salary_01 number) is
    v_seq_mitve_nur number;
  begin
  
    for r in (select s.*
                from ld_chinuch_salary_04 s
                left join ld_chinuch_salary_01 s1
                  on to_number(s.b) = to_number(s1.b)
                 and trunc(s1.load_date) = trunc(s.load_date)
               where s1.seq_ld_chinuch_salary_01 =
                     p_seq_ld_chinuch_salary_01) loop
      v_seq_mitve_nur := chinuch_reforma_seq.nextval;
      insert into chinuch_mitve_nur
        (seq_bakasha,
         chodesh_sachar,
         shach_mekadem_misra,
         sug_zchut,
         is_mashpia,
         is_factor,
         factor_olam_yashan,
         factor_ofek,
         factor_oz,
         factor_michlala,
         seq_mitve_nur)
      values
        (p_seq_bakasha,
         to_date(r.c, 'yyyymm'),
         get_decimal_number(r.d,5),
         r.e,
         r.f,
         r.g,
         get_decimal_number(r.h,5),
         get_decimal_number(r.i,5),
         get_decimal_number(r.j,5),
         get_decimal_number(r.k,5),
         CHINUCH_MITVE_NUR_SEQ.NEXTVAL);
    END LOOP;
  end;
  -------------------------------------------------
  
  procedure update_bakarot(p_seq_bakasha              number,
                           p_seq_ld_chinuch_salary_01 number,
                           p_seq_reforma              number,
                           p_code_reforma             number) is
    v_seq_bakara                    number;
    v_code_bakara                   number;
    v_taarich                       date;
    v_amount                   number;
    v_indication                    number;
    v_grira                         number;
    v_code_tafkid                   number;
    v_mispar_kitot_yesodi           number;
    v_mispar_kitot_al_yesodi        number;
    v_mispar_kitot_yesodi_chanam    number;
    v_mispar_kitot_al_yesodi_chanam number;
    v_ramat_murkavut                number;
    v_godel_matya                   number;
    v_code_mosad                     number;  
    v_ramat_murkavut_before          number;
    v_tafkid_acharon                 number;
    v_semel_mosad                    number;                 
  begin
  
    for r in (select s.*
                from ld_chinuch_salary_bakarot s
                left join ld_chinuch_salary_01 s1
                  on s.b = s1.b
                 and trunc(s1.load_date) = trunc(s.load_date)
               where s1.seq_ld_chinuch_salary_01 =
                     p_seq_ld_chinuch_salary_01
                 and s.a in ('5', '6', '7', '8', '9', '10')
                 and s.c = p_code_reforma) loop
      v_seq_bakara  := chinuch_bakara_seq.nextval;
      v_taarich     := case when r.a not in (5,10) then to_date(r.d, 'yyyymm') else null end;
      v_code_bakara := case when r.a = 5 then 1 when r.a = 6then 2when r.a = 7then 3when r.a = 8then 4when r.a = 9then 5when r.a = 10then 6 else null end;
      v_indication  := case when r.a = 5 then r.g when  r.a =8 then r.e when  r.a =10 then r.d else  0 end;
      v_grira       := case when r.a = 5 then r.f when  r.a =9 then r.e else 0 end;
      v_amount := case when r.a =6 then r.e when  r.a =7 then r.e when  r.a =9 then r.f else null end;
      if r.a = 5 then
        v_code_tafkid                     := CASE WHEN r.d=0 THEN NULL ELSE R.d END;
        v_code_mosad                      := CASE WHEN r.e=0 THEN NULL ELSE R.E END;
        v_mispar_kitot_yesodi           := r.h;
        v_mispar_kitot_al_yesodi        := r.i;
        v_mispar_kitot_yesodi_chanam    := r.j;
        v_mispar_kitot_al_yesodi_chanam := r.k;
        v_ramat_murkavut                := r.l;
        v_godel_matya                   := r.m;
         v_ramat_murkavut_before          := r.n;
    v_tafkid_acharon                 := r.o;
    v_semel_mosad                    := r.p;     
      else
        v_code_tafkid                   := null;
        v_mispar_kitot_yesodi           := null;
        v_mispar_kitot_al_yesodi        := null;
        v_mispar_kitot_yesodi_chanam    := null;
        v_mispar_kitot_al_yesodi_chanam := null;
        v_ramat_murkavut                := null;
        v_godel_matya                   := null;
        v_code_mosad                    :=null;
         v_ramat_murkavut_before          := null;
    v_tafkid_acharon                 := null;
    v_semel_mosad                    := null;    
      end if;
    
      insert into chinuch_bakara
        (seq_chinuch_bakara,
         seq_chinuch_reforma,
         code_bakara,
         taarich,
         amount,
         indication,
         grira,
         code_tafkid,
         mispar_kitot_yesodi,
         mispar_kitot_al_yesodi,
         mispar_kitot_yesodi_chanam,
         mispar_kitot_al_yesodi_chanam,
         ramat_murkavut,
         godel_matya,
         code_chinuch_mosad,
         ramat_murkavut_before,
         tafkid_acharon,
         semel_mosad)
      values
        (v_seq_bakara,
         p_seq_reforma,
         v_code_bakara,
         v_taarich,
         v_amount,
         v_indication,
         v_grira,
         v_code_tafkid,
         v_mispar_kitot_yesodi,
         v_mispar_kitot_al_yesodi,
         v_mispar_kitot_yesodi_chanam,
         v_mispar_kitot_al_yesodi_chanam,
         v_ramat_murkavut,
         v_godel_matya,
         v_code_mosad,
         v_ramat_murkavut_before,
         v_tafkid_acharon,
         v_semel_mosad);
    END LOOP;
  end;
  -------------------------------------------------
  function update_sachar_for_bakasha(p_seq_bakasha number) return number is
    v_result number;
  begin
  
    for r in (select max(s.seq_ld_chinuch_salary_01) seq_ld_chinuch_salary
                from v_bakasha v
                left join ld_chinuch_salary_01 s
                  on s.b = v.MISPAR_ZEHUT
               where v.SEQ_BAKASHA = p_seq_bakasha
                 and v.code_makor = 3) loop
    
      if r.seq_ld_chinuch_salary is null then
        return 0;
      end if;
    
      v_result := update_netuney_sachar(r.seq_ld_chinuch_salary,
                                        p_seq_bakasha,
                                        p_seq_bakasha);
    
      /*if v_result = 0 then
        rollback;
      else*/
      --delete_old_data(p_seq_bakasha);
        commit;
     -- end if;
    
      pk_salary_base.update_ld_salary_base(null,
                                           null,
                                           r.seq_ld_chinuch_salary,
                                           1,
                                           p_seq_bakasha);
    end loop;
    return 1;
  
  end;
  --------------------------------------------------------
  procedure delete_old_data(p_seq_bakasha number) is
    pragma autonomous_transaction;
  begin
  begin
    for r in (select *
                from netuney_sachar t
               where t.seq_bakasha = p_seq_bakasha
               ) loop
    if r.seq_netuney_sachar is not null then
      delete from vetek_detail v
       where v.seq_netuney_sachar = r.seq_netuney_sachar;
    
      delete from tosefot t
       where t.seq_netuney_sachar = r.seq_netuney_sachar;
    
      delete from netuney_sachar n
       where n.seq_netuney_sachar = r.seq_netuney_sachar and r.mispar_misra<>99;
       end if;
    end loop;
    delete from chinuch_bakara t
     where t.seq_chinuch_reforma in
           (select t1.seq_chinuch_reforma
              from chinuch_reforma t1
             where t1.seq_bakasha = p_seq_bakasha);
  
    delete from chinuch_reforma t where t.seq_bakasha = p_seq_bakasha;
  
    delete from chinuch_mitve_nur t where t.seq_bakasha = p_seq_bakasha;
  
    commit;
  exception
    when others then
      rollback;
  end;
  
  end;
  --------------------------------------------------------
  function main_chinuch(p_ld_protocol number) return clob is
    v_seq_bakasha number;
  begin
  
    for r in (select a.b,
       a.seq_ld_chinuch_salary_01,
       a.max_seq
                from (select
                      --Id
                       t.b,
                       t.seq_ld_chinuch_salary_01,
                       --Get the last load for every id
                       first_value(t.seq_ld_chinuch_salary_01) over(partition by t.b order by t.seq_ld_chinuch_salary_01 desc) max_seq
                        from ld_chinuch_salary_01 t
                        left join ld_salary_base l
                          on t.seq_ld_chinuch_salary_01 =
                             l.seq_ld_chinuch_salary_01
) a
left join ld_salary_base ll
                          on a.seq_ld_chinuch_salary_01 =
                             ll.seq_ld_chinuch_salary_01
              --Filer: get the last rows for every id
               where a.seq_ld_chinuch_salary_01 = trunc(a.max_seq)
             and nvl(ll.code_status_get, 0) in (0, 3)
            and a.b in(304707649)       
                     -- and t.seq_ld_chinuch_salary_01 in (7399,7399)
                    ) loop
                    dbms_output.put_line(r.b);
      pk_salary_base.load_managment_id(p_ld_protocol,
                                       null,
                                       r.seq_ld_chinuch_salary_01,
                                       --Id
                                       r.b,
                                       --code_misrad_maskret of chinuch
                                       150,
                                       'pk_chinuch_salary');
    
      select b.seq_bakasha
        into v_seq_bakasha
        from ld_salary_base b
       where r.seq_ld_chinuch_salary_01 = b.seq_ld_chinuch_salary_01;
    
      --Transaction by id
      pk_salary_base.chinuch_manage_actions(p_ld_protocol, v_seq_bakasha);
    
    end loop;
    return pk_salary_base.get_report(p_ld_protocol);
  end;
   --------------------------------------------------------
  function is_get_new_salary_1(p_seq_bakasha_for_compare number,
                             p_seq_chinuch_salary_01  number) return number is
    v_is_get_new_salary number :=1;
    v_count_rows_new number;
    v_exists_netuney_sachar number;
    v_odef                  number;
    v_zehut                 number;
    v_load_date             date;
    v_reforma               number;
    v_alternative           number;
    v_maskoret                number;
    v_maskoret_gil_60         number;
    v_code_sug_maskoret       number;
    v_code_sug_maskoret_gil_60       number;
    v_nigzeret                       number;
    v_nigzeret_gil_60                number;
    v_maskoret_pizuim                number;
    v_choose_alternative                    number;
    v_temp                                  number;
    v_tkufa_mezaka      number;
    v_exists_ofek       number;
    v_code_derug             number;
    v_code_darga             number;
    v_code_darga_mimshak                    number;
    v_darga_ofek                            number;
    v_derug_ofek number;
    v_change_derug                          number;
    v_change_darga                          number;
    v_mishkolet number;
  begin
    
  --get zehut and load date
  select t.b,t.load_date
  into v_zehut,v_load_date
  from ld_chinuch_salary_01 t
  where t.seq_ld_chinuch_salary_01=p_seq_chinuch_salary_01;
  
  --there is no netuney sachar in p_seq_bakasha_for_compare
  select count(*)
  into v_exists_netuney_sachar 
  from netuney_sachar n
  where n.seq_bakasha=p_seq_bakasha_for_compare;
  
  --if there is odef-check maskoret pizuim
 select nvl(sum( nvl(v.odef_sherut_chodashim,0)+nvl(v.odef_sherut_yamim,0)),0),sum(v.tkufa_mezaka_sherut)
 into v_odef,v_tkufa_mezaka
 from bakasha b
 left join v_prisha_last_zakaut tt
 on b.seq_prisha=tt."SEQ_PRISHA"
 left join netuney_tik_mechushavim v
 on v.seq_bakasha=tt."SEQ_BAKASHA_ZAKAUT"
 where b.seq_bakasha=p_seq_bakasha_for_compare
 and v.mispar_misra=0 and v.code_department=2;
 
 
 v_is_get_new_salary:=0;
 if v_exists_netuney_sachar=0 then v_is_get_new_salary:=1; return v_is_get_new_salary; end if;
 --compare maskoret_kovaat
 
 
 
 select count(*)
   into v_exists_ofek
   from ld_chinuch_salary_03 t
  where t.b = v_zehut
    and trunc(t.load_date) = trunc(v_load_date)
    and t.c = 1;
 
 for r in (select t.* ,s1.r as darga_mimshak
          from ld_chinuch_salary_03 t 
          left join ld_chinuch_salary_01 s1
                  on t.b = s1.b
                 and trunc(s1.load_date) = trunc(t.load_date)
          where t.b=v_zehut 
          and trunc(t.load_date)=trunc(v_load_date))loop
          
   --mishkolet
   select nvl(t1.factor,0)
   into v_mishkolet
   from chinuch_reforma t1
   where t1.seq_bakasha = p_seq_bakasha_for_compare
   and t1.code_reforma=r.c;  
  if get_decimal_number(r.q,4) <> v_mishkolet then   
         v_is_get_new_salary:=9; return v_is_get_new_salary;
 end if;
          
 --derug darga from mimshak
 v_code_darga_mimshak:=r.af;
 if r.c = 1  then
      v_code_darga_mimshak:=r.darga_mimshak;
      select dc.code_darga, dc.code_derug
      into v_darga_ofek, v_derug_ofek
      from code_darga dc
      where dc.code_derug = r.ae + 99000
      and dc.code_darga = r.af;
   end if;
  select dc.code_darge, dc.code_derug
  into v_code_darga, v_code_derug
  from code_darga_chinuch_salary dc
  where dc.code_derug_chinuch_salary = 41
  and dc.code_darga_chinuch_salary = v_code_darga_mimshak;
 
 
 
  if r.d=1 or r.c = 4 then 
   v_maskoret:=get_decimal_number(r.m,2) ;
   v_maskoret_gil_60:= CASE WHEN v_choose_alternative = r.d or r.c=4 then get_decimal_number(r.ak,2)else 0 end;
   v_nigzeret:=nvl(get_decimal_number(r.k,2),0)+nvl(get_decimal_number(r.l,2),0);
   v_code_sug_maskoret:=5;
   v_code_sug_maskoret_gil_60:=6; 
 else
   v_maskoret:=get_decimal_number(r.o,2) ;
   v_maskoret_gil_60:= CASE WHEN v_choose_alternative = r.d and r.c<>4 then get_decimal_number(r.al,2)else 0 end;
   v_nigzeret_gil_60:=nvl(get_decimal_number(r.k,2),0)+nvl(get_decimal_number(r.l,2),0);
   v_code_sug_maskoret:=8;
   v_code_sug_maskoret_gil_60:=9; 
   
 end if;
  
  --derug darga
 begin
 select nvl(t.code_derug,0)-nvl(case when v_code_sug_maskoret=5 and r.c=1 then v_derug_ofek else v_code_derug end,0),
 nvl(t.code_darga,0)-nvl(case when v_code_sug_maskoret=5 and r.c=1 then v_darga_ofek else v_code_darga end,0)
   into v_change_derug,v_change_darga
   from netuney_sachar t
   left join chinuch_reforma t1
   on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
   where t.seq_bakasha = p_seq_bakasha_for_compare
   and t.code_sug_maskoret=v_code_sug_maskoret
   and t1.code_reforma=r.c; 
   
   if v_change_darga<>0 or v_change_derug<>0 then
     v_is_get_new_salary :=7;return v_is_get_new_salary;
     
     end if;
 exception 
   when others then 
     v_is_get_new_salary :=7;return v_is_get_new_salary;
  end;
        
    
 if r.c<>4 then
 
 --chodashim  
 if case when r.c=1 or r.c=2 and v_exists_ofek = 1 then r.an else r.e end+
         case when r.c=1 or r.c=2 and v_exists_ofek = 1 then r.ao else r.f end<>v_tkufa_mezaka 
   then
   v_is_get_new_salary:=6; return v_is_get_new_salary;
 end if;
 
 --diff alternative
 
   select  cr.code_chinuch_alterntive
   into v_choose_alternative
   from chinuch_reforma cr
   where cr.seq_bakasha=p_seq_bakasha_for_compare 
   and cr.code_reforma=r.c;
   
 if v_choose_alternative<> to_number(r.d) and r.c<>4 then
     v_is_get_new_salary:=5; return v_is_get_new_salary;
  end if;  
  
  end if; 
 if r.d=1 or r.c = 4 then 
   v_maskoret:=get_decimal_number(r.m,2) ;
   v_maskoret_gil_60:= CASE WHEN v_choose_alternative = r.d or r.c=4 then get_decimal_number(r.ak,2)else 0 end;
   v_nigzeret:=nvl(get_decimal_number(r.k,2),0)+nvl(get_decimal_number(r.l,2),0);
   v_code_sug_maskoret:=5;
   v_code_sug_maskoret_gil_60:=6; 
 else
   v_maskoret:=get_decimal_number(r.o,2) ;
   v_maskoret_gil_60:= CASE WHEN v_choose_alternative = r.d and r.c<>4 then get_decimal_number(r.al,2)else 0 end;
   v_nigzeret_gil_60:=nvl(get_decimal_number(r.k,2),0)+nvl(get_decimal_number(r.l,2),0);
   v_code_sug_maskoret:=8;
   v_code_sug_maskoret_gil_60:=9; 
   
 end if;
 
    --gil 60
   begin
     select nvl(t.maskoret_kovaat,0)-nvl(v_maskoret_gil_60,0)--,nvl(t.maskoret_kovaat_percent,0)+nvl(t.maskoret_kovaat_shiur_miztaber,0)-nvl(v_nigzeret_gil_60,0)
     into v_maskoret_gil_60--,v_nigzeret_gil_60
     from netuney_sachar t
     left join chinuch_reforma t1
     on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
     where t.seq_bakasha = p_seq_bakasha_for_compare
     and t.code_sug_maskoret=v_code_sug_maskoret_gil_60
     and t1.code_reforma=to_number(r.c);
     
     
     if abs(v_maskoret)>10 or abs(v_maskoret_gil_60)>10  then
        v_is_get_new_salary :=1; return v_is_get_new_salary;
     elsif v_maskoret<>0 or v_maskoret_gil_60 <>0  then
        v_is_get_new_salary :=12; return v_is_get_new_salary;
     end if;
  
   exception when no_data_found then
     begin
       if nvl(v_maskoret_gil_60,0)=0 then 
     v_temp:=1;
     else
       v_is_get_new_salary :=1;return v_is_get_new_salary;
       end if;
     end;
   when others then 
     v_is_get_new_salary :=1;return v_is_get_new_salary;
  end;
  
 
   --choose alternative details(maskoret and nigzeret)
   select nvl(t.maskoret_kovaat,0)-nvl(v_maskoret,0)
   into v_maskoret
   from netuney_sachar t
   left join chinuch_reforma t1
   on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
   where t.seq_bakasha = p_seq_bakasha_for_compare
   and t.code_sug_maskoret=v_code_sug_maskoret
   and t1.code_reforma=r.c;
   
  select t.maskoret_kovaat_percent-nvl(v_nigzeret,0)
   into v_nigzeret
   from netuney_sachar t
   left join chinuch_reforma t1
   on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
   where t.seq_bakasha = p_seq_bakasha_for_compare
   and t.code_sug_maskoret=v_code_sug_maskoret
   and t1.code_reforma=r.c;
   
   v_temp:=1;
   if abs(v_maskoret)>10 then
          v_is_get_new_salary :=1; return v_is_get_new_salary;
    elsif  abs(v_maskoret)<>0 then
            v_is_get_new_salary :=11; return v_is_get_new_salary;
     end if;   
   --exception when no_data_found then
   --v_is_get_new_salary :=1;return v_is_get_new_salary;--end;
   
   v_maskoret_pizuim:=get_decimal_number(r.ah,2); 
   
/*   --gil 60
   begin
     select nvl(t.maskoret_kovaat,0)-nvl(v_maskoret_gil_60,0)--,nvl(t.maskoret_kovaat_percent,0)+nvl(t.maskoret_kovaat_shiur_miztaber,0)-nvl(v_nigzeret_gil_60,0)
     into v_maskoret_gil_60--,v_nigzeret_gil_60
     from netuney_sachar t
     left join chinuch_reforma t1
     on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
     where t.seq_bakasha = p_seq_bakasha_for_compare
     and t.code_sug_maskoret=v_code_sug_maskoret_gil_60
     and t1.code_reforma=to_number(r.c);
     
     
     if abs(v_maskoret)>10 or abs(v_maskoret_gil_60)>10  then
        v_is_get_new_salary :=1; return v_is_get_new_salary;
     elsif v_maskoret<>0 or v_maskoret_gil_60 <>0  then
        v_is_get_new_salary :=12; return v_is_get_new_salary;
     end if;
  
   exception when no_data_found then
     begin
       if nvl(v_maskoret_gil_60,0)=0 then 
     v_temp:=1;
     else
       v_is_get_new_salary :=1;return v_is_get_new_salary;
       end if;
     end;
   when others then 
     v_is_get_new_salary :=1;return v_is_get_new_salary;
  end;*/
  begin
        select count(*)
          into v_count_rows_new
          from (select t.is_maanak_yovel
                  from netuney_sachar t
                   where t.seq_bakasha = p_seq_bakasha_for_compare
                   and (t.code_sug_maskoret <> 14) and rownum=1
                minus
                   select  to_number(r.g) from ld_chinuch_salary_01 r
     where r.seq_ld_chinuch_salary_01 = p_seq_chinuch_salary_01);
            if nvl(v_count_rows_new, 0) > 0 then
               v_is_get_new_salary:=10;return v_is_get_new_salary;
            end if;
 exception when no_data_found then
   v_is_get_new_salary :=10;return v_is_get_new_salary;end;
 
 
 
  v_maskoret:=case when r.d=1 then r.o else r.m end;
  v_maskoret_gil_60:=case when r.d=1 then r.al else r.ak end;
  v_maskoret:=get_decimal_number(v_maskoret,2);
  v_maskoret_gil_60:=get_decimal_number(v_maskoret_gil_60,2);

--other alternative
  if r.c<>4 then
  select nvl(t.maskoret_kovaat,0)-v_maskoret
   into v_maskoret 
   from netuney_sachar t
   left join chinuch_reforma t1
   on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
   where t.seq_bakasha = p_seq_bakasha_for_compare
   and t.code_sug_maskoret=decode(r.d,1,8,5)
   and t1.code_reforma=to_number(r.c);
     
  
  begin
   select nvl(t.maskoret_kovaat,0)-v_maskoret_gil_60
   into v_maskoret_gil_60 
   from netuney_sachar t
   left join chinuch_reforma t1
   on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
   where t.seq_bakasha = p_seq_bakasha_for_compare
   and t.code_sug_maskoret=decode(r.d,1,9,6)
   and t1.code_reforma=to_number(r.c);
   
   if  v_maskoret_gil_60 <>0 then
        v_is_get_new_salary :=4; return v_is_get_new_salary;
     end if;
      exception when no_data_found then
     begin
       if nvl(v_maskoret_gil_60,0)=0 and nvl(v_maskoret,0)=0 then 
     v_temp:=1;
     else
       v_is_get_new_salary :=4;return v_is_get_new_salary;
       end if;
     end;
   when others then 
     v_is_get_new_salary :=4;return v_is_get_new_salary;
  end; 
  end if;
   

--derug darga
 begin
 select nvl(t.code_derug,0)-nvl(case when t.code_sug_maskoret=5 and t1.code_reforma=1 then v_derug_ofek else v_code_derug end,0),
 nvl(t.code_darga,0)-nvl(case when t.code_sug_maskoret=5 and t1.code_reforma=1 then v_darga_ofek else v_code_darga end,0)
   into v_change_derug,v_change_darga
   from netuney_sachar t
   left join chinuch_reforma t1
   on t.seq_chinuch_reforma = t1.seq_chinuch_reforma
   where t.seq_bakasha = p_seq_bakasha_for_compare
   and t.code_sug_maskoret=decode(r.d,1,8,5)
   and t1.code_reforma=r.c; 
   
   if v_change_darga<>0 or v_change_derug<>0 then
     v_is_get_new_salary :=8;return v_is_get_new_salary;
     
     end if;
 exception 
   when others then 
     v_is_get_new_salary :=8;return v_is_get_new_salary;
  end;
 
 


 end loop;
 
 
      --check havara bigud
      begin
        select count(*)
          into v_count_rows_new
          from (select t.sum_havraa,
                       t.sum_bigud,
                     --  t.is_maanak_yovel,
                       t.havraa_days,
                       t.ramat_bigud
                  from netuney_sachar t
                   where t.seq_bakasha = p_seq_bakasha_for_compare
                   and (t.code_sug_maskoret <> 14) and rownum=1
                minus
                   select to_number(r.e), to_number(r.f),/* to_number(r.g),*/ to_number(r.l), to_number(r.m) from ld_chinuch_salary_01 r
     where r.seq_ld_chinuch_salary_01 = p_seq_chinuch_salary_01);
            if nvl(v_count_rows_new, 0) > 0 then
               v_is_get_new_salary:=2;return v_is_get_new_salary;
            end if;
 exception when no_data_found then
   v_is_get_new_salary :=2;return v_is_get_new_salary;end;
 
                           
        --check odef
  if v_odef>0 then
            --pizuim
   begin
    select nvl(t.maskoret_kovaat,0)-nvl(v_maskoret_pizuim,0)
    into v_maskoret_pizuim
              from netuney_sachar t
             where t.seq_bakasha = p_seq_bakasha_for_compare
             and t.code_sug_maskoret=14;
   
    if v_maskoret_pizuim<>0 then
        v_is_get_new_salary:=3;return v_is_get_new_salary;end if;
        exception when no_data_found then
        v_is_get_new_salary :=3;return v_is_get_new_salary;end; 
            end if;
       
        
                

    
    if nvl(v_is_get_new_salary, 0) = 0 then
      return 0;
    else
      return v_is_get_new_salary;
    end if;
  end;

  --------------------------------------------------------
 
  --------------------------------------------------------
end;
/

create or replace package body prm_system_copy.pk_compare_before_prod is

  procedure compare_participation is
  
    v_db_name varchar2(50);
  
    cursor c_bakasha_seq is
      select distinct b.seq_bakasha
        from v_bakasha_last_status b
        left join participation t
          on t.seq_bakasha = b.seq_bakasha
         and (t.code_participation = 1 or b.code_sug_bakasha in (7, 23))
       where b.code_sug_bakasha in (7, 8, 9, 23)
            
         and (t.date_answer is not null or b.code_sug_bakasha in (8, 9))
         and b.code_action in
             (SELECT W.Next_Action
                FROM WORKFLOW W
               WHERE W.CODE_SUG_WORKFLOW IN (8, 11, 12, 13, 14, 22) --14 meguf
                 AND W.ORDER_WF >=
                     (SELECT W1.ORDER_WF
                        FROM WORKFLOW W1
                       WHERE W1.CODE_SUG_WORKFLOW = W.CODE_SUG_WORKFLOW
                         AND W1.CODE_ACTION = 64));
  
  begin
    v_db_name := sys_context('userenv', 'DB_NAME');
  
    if v_db_name = 'xt1' then
      return;
    end if;
  
    for rec_bakasha_seq in c_bakasha_seq loop
      begin
        pk_participation_2_guff.insert_calc_data_2_table(rec_bakasha_seq.seq_bakasha);
        --dbms_output.put_line(rec_bakasha_seq.seq_bakasha);
      exception
        when others then
          dbms_output.put_line('Exception:' || rec_bakasha_seq.seq_bakasha);
          continue;
      end;
    end loop;
  end;
  --create table  netuney_tik_mechushavim_1 as (select * from netuney_tik_mechushavim);
  --create table  participation_1 as (select * from participation);
  --\\mgdev12\projects\PRM\sql\השוואת השתתפיות.sql
  -----------------------------------------------------------------------

  procedure compare_zakaut is
    v_db_name varchar2(50);
  
    cursor c_coppy_seq is
    /* select distinct b.seq_bakasha
                                                                                                                                                                                                                                                                                                                                  from v_bakasha_last_status b
                                                                                                                                                                                                                                                                                                                                  left join bakasha b1
                                                                                                                                                                                                                                                                                                                                    on b.seq_bakasha = b1.seq_bakasha
                                                                                                                                                                                                                                                                                                                                 where b.code_sug_bakasha in (1, 3, 5)
                                                                                                                                                                                                                                                                                                                                   and b1.date_bakasha > to_date('01/01/2017', 'dd/mm/yyyy')
                                                                                                                                                                                                                                                                                                                                   and b.code_action in
                                                                                                                                                                                                                                                                                                                                       (SELECT W.CODE_ACTION
                                                                                                                                                                                                                                                                                                                                          FROM WORKFLOW W
                                                                                                                                                                                                                                                                                                                                         WHERE W.CODE_SUG_WORKFLOW IN (1, 3, 4, 7, 9, 10, 13, 15)
                                                                                                                                                                                                                                                                                                                                           AND W.ORDER_WF >=
                                                                                                                                                                                                                                                                                                                                               (SELECT W1.ORDER_WF
                                                                                                                                                                                                                                                                                                                                                  FROM WORKFLOW W1
                                                                                                                                                                                                                                                                                                                                                 WHERE W1.CODE_SUG_WORKFLOW = W.CODE_SUG_WORKFLOW
                                                                                                                                                                                                                                                                                                                                                   AND W1.CODE_ACTION = 12))*/
      select distinct b.seq_bakasha
        from v_bakasha_last_status b
        left join bakasha b1
          on b.seq_bakasha = b1.seq_bakasha
        left join poresh p
          on b.seq_porshim = p.porshim_seq
        left join code_seif_prisha s
          on s.code_seif_prisha = b.code_seif_prisha
       where b.code_sug_bakasha in (1, 3, 5, 13)
         and b1.date_bakasha > to_date('01/01/2017', 'dd/mm/yyyy')
         and exists
       (SELECT b.code_action
                FROM action_log a
               WHERE a.seq_bakasha = b.seq_bakasha
                 AND a.CODE_ACTION = 12)
         and (p.taarich_ptira is null or s.code_group_prisha = 4);
  
  begin
  
    v_db_name := sys_context('userenv', 'DB_NAME');
  
    if v_db_name = 'xt1' then
      return;
    end if;
  
    for rec_coppy_seq in c_coppy_seq loop
      begin
        pk_zakaut.main(rec_coppy_seq.seq_bakasha, 2);
      exception
        when others then
          dbms_output.put_line('Exception:' || rec_coppy_seq.seq_bakasha);
          --continue;
      end;
    end loop;
  end;
  --create table  netuney_tik_mechushavim_1 as (select * from netuney_tik_mechushavim);
--\\mgdev12\projects\PRM\sql\השוואת זכאות מעודכן.sql
end pk_compare_before_prod;

