function get_telephone(v_telephone varchar2, v_sf number default 0) return varchar2 is
  -- נרמול מספר טלפון
  v_phone varchar2(20);
   begin
    if v_telephone is null or instr(v_telephone,'@')>0 then
      v_phone := lpad_zeroez(0,10);
    else
      v_phone := replace(v_telephone,' ','');
      v_phone := replace(v_phone,'-',''); 
      --if substr(v_phone,1,2) = '00' then v_phone := replace(v_phone,'00','0'); end if;
      if v_phone is null or instr(v_telephone,'@')>0 then
        v_phone := lpad_zeroez(0,10);   
        --v_phone := rpad_blanks(' ',10);
      elsif length(v_phone)>10 then
        if v_sf = 0 then            v_phone := '0000000000';
                    else /*sf = 1*/ v_phone :=  v_phone;
        end if; 
      else
        v_phone := lpad_zeroez(to_number(v_phone),10);
        if substr(v_phone,1,3)='000' then v_phone := '0000000000'; end if;
      end if;
    end if;
-- לשלוח קידומת 053 במקום 057 
    if v_sf = 0 then 
      if substr(v_phone,1,3) = '057' then v_phone := '053' || substr(v_phone,4,7); end if;  
      if substr(v_phone,1,3) = '000' then v_phone := '0000000000'; end if;
      if substr(v_phone,1,1) <> '0' then v_phone := '0000000000'; end if;
    end if;
    return v_phone;
    exception
    when others then      
       return 'e' || v_phone;
   end;
