  ------------------------------------  
   procedure prepare_trigger_0(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_is_minui_merube boolean,
                          v_date_report date,
                          v_record varchar2 default '') is
   begin
    ld_log_events_record.seq_ld_log_events := ld_log_events_seq.nextval;
    ld_log_events_record.seq_ld_protocol := v_seq_ld_protocol;
    ld_log_events_record.seq_ld_protocol_hilan := v_seq_ld_protocol_hilan;
    ld_log_events_record.date_create := sysdate;
    ld_log_events_record.mispar_zehut := v_mispar_zehut;
    ld_log_events_record.code_trigger := 0;
    ld_log_events_record.gorem_medaveach := 2292;
    ld_log_events_record.seq_bakasha := v_seq_bakasha;
    ld_log_events_record.mispar_gimla := v_gimla_number;
    ld_log_events_record.date_report := v_date_report;
    ld_log_events_record.seq_ld_log_events := ld_log_events_seq.nextval;
    if v_is_minui_merube then
       if ld_log_events_record.code_event = 315 --and ld_log_events_record.code_event_semel = '0567','0412'
       then
          ld_log_events_record.record_hilan := v_record ||
                                            lpad_zeroez(v_gimla_number,9) ||
                                            lpad_zeroez(ld_log_events_record.seq_ld_log_events,9);
       else
          ld_log_events_record.record_hilan := rpad_blanks(' ',10) || 
                                            lpad_zeroez(v_gimla_number,9) ||
                                            lpad_zeroez(ld_log_events_record.seq_ld_log_events,9);
       end if;
    else
       ld_log_events_record.record_hilan := rpad_blanks(' ',19) || 
                                            lpad_zeroez(ld_log_events_record.seq_ld_log_events,9); 
    end if;                                                 
    end ;
  ------------------------------------  
  --גימלה חדשה
  function insert_event_237(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
  v_achuz_misra float;
  v_code_misrad_maskret number;
  v_code_ezor_ovdim number; 
  v_mispar_zehut_sheer_benzug number :=0;
  v_mispar_misra number;
  
   begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    
    begin
    select nvl(t.code_misrad_maskret,0), t.code_ezor_ovdim
            into v_code_misrad_maskret, v_code_ezor_ovdim
                from code_ezor_ovdim t
                where t.seq_ezor_ovdim = v_seq_ezor_ovdim
                and t.pail = 1; --???
    exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_237: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_237: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;   
    end;
   
    for r in (select 0 sug, n.mispar_misra, n.chelkiyut_sofit
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      /*union 
      select 24, 0, 0 from dual --עבור בקשת מקדמה 
      order by 1,2*/
      )
    loop
          
    v_mispar_misra := r.mispar_misra;
    
    ld_log_events_record.code_event := 237;
    ld_log_events_record.code_event_semel := 0;
  
    if r.sug = 24 and v_code_sug_bakasha <> 24 then continue; end if;
    if r.sug = 0 and  v_code_sug_bakasha = 24 then continue; end if;
    
    if v_code_sug_bakasha <> 12 and v_code_sug_bakasha <> 24 then           
      v_achuz_misra := nvl(r.chelkiyut_sofit,0);
    else
      v_achuz_misra := 0;
    end if;
                 
    prepare_trigger_0(v_seq_ld_protocol,
                      v_seq_ld_protocol_hilan,
                      v_seq_bakasha,
                      case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug else v_mispar_zehut end,
                      case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                      else 
                                v_gimla_number
                      end,
                      true,
                      case when v_code_sug_bakasha = 12 then v_hp_date_haavara
                           when v_code_sug_bakasha = 24 then sysdate
                           else v_date_start_zakaut end);
    if not insert_event then return false; end if;
     ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
     '0' ||                                                                                   --MINUI
     to_char(case when v_code_sug_bakasha = 12 then v_hp_date_haavara
                  when v_code_sug_bakasha = 24 then sysdate
                  else v_date_start_zakaut end,date_format_d8) ||                             --TAARICH
     lpad_zeroez(0,8) ||                                                                      --GNARTOKEF
     lpad_zeroez(nvl(v_code_misrad_maskret,0),3) || lpad_zeroez(nvl(v_code_ezor_ovdim,0),4) || '99' || --SEIF
     lpad_zeroez(0,9) ||                                                                      --TEKEN
     lpad_zeroez(replace(to_char(nvl(nvl(v_achuz_misra,9),0),'0.9999'),'.',''),5) ||          --AHUSMISRA
     lpad_zeroez(0,9) ||                                                                      --SEIF                                                                   
     lpad_zeroez(0,9) ||                                                                      --TEKEN
     lpad_zeroez(0,5) ||                                                                      --AHUSMISRA
     lpad_zeroez(0,9) ||                                                                      --SEIF                                                                   
     lpad_zeroez(0,9) ||                                                                      --TEKEN
     lpad_zeroez(0,5) ||                                                                      --AHUSMISRA
     lpad_zeroez(0,9) ||                                                                      --SEIF                                                                   
     lpad_zeroez(0,9) ||                                                                      --TEKEN
     lpad_zeroez(0,5);                                                                        --AHUSMISRA
     --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
     if not insert_event then return false; end if;
    end loop;
    return true;
    exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_237: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_237: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
      return false;   
  end;                          
  ------------------------------------
  --גימלה חדשה
  function check_event_237(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
  v_achuz_misra float;
  v_code_misrad_maskret number;
  v_code_ezor_ovdim number; 
  v_mispar_misra number;
  
   begin
     
   v_code_misrad_maskret := null;
   v_code_ezor_ovdim := null;

   begin
     
    --if v_code_sug_bakasha = 24 then return true; end if;

    select t.code_misrad_maskret, t.code_ezor_ovdim
            into v_code_misrad_maskret, v_code_ezor_ovdim
                from code_ezor_ovdim t
                where t.seq_ezor_ovdim = v_seq_ezor_ovdim
                and t.pail = 1; --???
    exception
    when others then
       message := sqlerrm;
       build_check_message(1,'0237','0000',1,': ' || to_char(v_seq_ezor_ovdim),message);
    end;
    if v_code_misrad_maskret is null then
       build_check_message(1,'0237','0000',2,': ' || to_char(v_seq_ezor_ovdim));
    end if;
    if v_code_ezor_ovdim is null then
       build_check_message(1,'0237','0000',3,': ' || to_char(v_seq_ezor_ovdim));
    end if;
    
    if v_code_sug_bakasha = 24 then return true; end if;

    
    for r in (select n.*
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      order by n.mispar_misra)
      --for i in 1 .. v_mispar_misrot_leprisha
    loop
      
    v_mispar_misra := r.mispar_misra;
         
    begin
    if v_code_sug_bakasha <> 12 then           
       select t.chelkiyut_sofit
            into v_achuz_misra
                from netuney_tik_mechushavim t
                where t.seq_bakasha = v_seq_bakasha
                and t.code_department = 2              
                and t.mispar_misra = v_mispar_misra;
    else
      v_achuz_misra := 0;
    end if;                
    exception
    when others then
       message := sqlerrm;
       build_check_message(1,'0237','0000',4,'',message);
    end;
    if v_achuz_misra is null then
       build_check_message(1,'0237','0000',5,'');
    end if;
    end loop;
   return true; 
  end;                          
  ------------------------------------
  -- נתונים שונים למילוי
   function insert_event_312(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_erech number;
   v_erech2 number := 0;
   v_erech3 number;
   v_erech_str varchar2(9);
   v_teur varchar2(15);
   v_mispar_zehut_sheer_benzug number := 0;
   v_is_gimlat_kefel boolean := false;
   v_times number := 1;
   v_mi_taarich date;
   v_insert_event_status boolean;
   v_mispar_misra number;
   v_mispar_prishot_lesheer number;
   begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    
      /*if (v_mispar_zehut_sheer_benzug <> 0  and v_semel_hilan <> '0410' or
        v_mispar_zehut_sheer_benzug = 0  and v_semel_hilan = '0410') then
        return true;
      end if;*/


     --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    /* if v_code_sug_bakasha = 13 
       and not v_ptira_besherut_gimlat_chesed 
       and not v_semel_hilan = '0410'
       then return true; end if; */
            
      ld_log_events_record.code_event := 312;
      ld_log_events_record.code_event_semel := v_semel_hilan;

     for r in (select n.*
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      order by n.mispar_misra)
      --for i in 1 .. v_mispar_misrot_leprisha
     loop
      
      v_mispar_misra := r.mispar_misra;
       
      if v_semel_hilan <> '0112' then 
   
      if  v_semel_hilan = '0100'    --מספר גימלה
         then v_erech :=  case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                          else 
                                v_gimla_number
                          end;
              v_teur := 'מספר גימלה';
      elsif  v_semel_hilan = '0102' --סעיף חוק 
         then select t.code_seif_prisha
                into v_erech
                from  bakasha_regila t
                where t.seq_bakasha = v_seq_bakasha;
              v_teur := 'סעיף חוק';
      elsif  v_semel_hilan = '0971' --פרוד/ה 
         then select t.mispar_zehut_ben_mishpacha
                into v_erech
                from  bney_mishpacha t, poresh p
                where p.mispar_zehut = v_mispar_zehut
                and t.seq_porshim = p.porshim_seq
                and t.code_kirva = 1
                and t.seq_bney_mishpacha =
                (select max(b.seq_bney_mishpacha)
                from bney_mishpacha b
                where b.seq_porshim = p.porshim_seq
                and b.code_kirva = 1);
              v_teur := 'ת.ז. של בן זוג פרוד';
      elsif  v_semel_hilan = '0410' --תעודת זהות אב 
         then v_erech := v_mispar_zehut;
              v_teur := 'תעודת זהות אב';
         select count(*)
         into v_mispar_prishot_lesheer
         from v_bakasha_last_status t
         where t.mispar_zehut = v_mispar_zehut_sheer_benzug
         and t.gimla_number <> v_gimla_number
         and t.code_action<>17;
         if v_mispar_prishot_lesheer > 0 then
           v_erech2 := 2; -- שאר קיים
         else
           v_erech2 := 1; -- שאר חדש
         end if;
      end if;
      
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug else v_mispar_zehut end,
                        case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                             else 
                                v_gimla_number
                             end,
                        true,
                        v_date_start_zakaut);                      
       if not insert_event then return false; end if;   
           
       ld_log_events_record.code_trigger := 2;
       ld_log_events_record.record_hilan := 
       '0' ||                                                                                            --MINUI
       lpad_zeroez(v_erech,9) ||                                                                         --ERECH                       
       lpad_zeroez(v_erech2,9) ||                                                                               --ERECH_2
       lpad_zeroez(0,9) ||                                                                               --ERECH_3
       rpad_blanks(v_teur,15) ||                                                                         --TEUR
       to_char(v_date_start_zakaut,date_format_d8) ||                                                    --TAARICH
       lpad_zeroez(0,8);                                                                                 --GMATROKEF
       --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
       if not insert_event then return false; end if;
       
     else --v_semel_hilan = '0112'  -  גמלאות כפל
     v_teur := 'גמלאות כפל';
     select min(t.date_payment)
                 into v_mi_taarich
                 from participation t
                 where t.seq_bakasha = v_seq_bakasha
                 and t.code_participation = 6;
     for r in          
            (select /*t.sum_participation, */t.kizba_chodshit,
             /*t.percent_participate, *//*t.percent_participate_calc,*/t.ACHUZ_GUF_FINAL,
            t.partial_period, t.date_payment
                 from participation t
                 where t.seq_bakasha = v_seq_bakasha
                 and t.code_participation = 6) loop
     begin
     if v_times = 1 then
     prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        v_mispar_zehut,
                        case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                             else 
                                v_gimla_number
                             end,
                        true,
                        v_mi_taarich);
     if not insert_event then return false; end if;
       ld_log_events_record.code_trigger := 2;
       /*v_erech := r.sum_participation * 100;
       
       v_erech2 := case when not r.percent_participate_calc is null and r.percent_participate_calc<>0 then
                        r.percent_participate_calc * 100
                   else
                        r.percent_participate * 100
                   end; */
       v_erech := nvl(r.kizba_chodshit,0) * 100;
       v_erech2 := nvl(r.ACHUZ_GUF_FINAL,0) * 100;
       v_erech3 := nvl(r.partial_period,0) * 10000;     --אחוזים * 100
       ld_log_events_record.record_hilan := 
       '0' ||                                                                                            --MINUI
       lpad_zeroez(nvl(v_erech,0),9) ||                                             --ERECH                                                                      --ERECH                       
       lpad_zeroez(nvl(v_erech2,0),9) ||                                            --ERECH2                                                                  --ERECH_2
       lpad_zeroez(nvl(v_erech3,0),9) ||                                            --ERECH3                                                                      --ERECH_3
       rpad_blanks(v_teur,15) ||                                                                         --TEUR
       to_char(r.date_payment,date_format_d8) ||                                                         --TAARICH
       lpad_zeroez(0,8);                                                                                 --GMATROKEF
       --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
       v_times := v_times + 1;       
       if insert_event then continue; else return false; end if;
       end if;         
     end;     
     end loop;
     end if;     
     end loop;
     return true;
    
     exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_312: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_312: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;  
  ------------------------------------  
  -- נתונים שונים למילוי
   function check_event_312(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_erech number;
   v_mispar_zehut_sheer_benzug number := 0;
   v_times number := 1;
   v_mi_taarich date;
   v_mispar_misra number;
   begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;

     --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
     /*if v_code_sug_bakasha = 13 
       and not v_ptira_besherut_gimlat_chesed 
       and not v_semel_hilan = '0410'
       then return true;
     end if; */
     
     for r in (select n.*
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      order by n.mispar_misra)
      --for i in 1 .. v_mispar_misrot_leprisha
    loop
      
    v_mispar_misra := r.mispar_misra;
 
       if v_semel_hilan = '0102' then--סעיף חוק 
       begin
       select t.code_seif_prisha
                into v_erech
                from  bakasha_regila t
                where t.seq_bakasha = v_seq_bakasha;
       exception
       when others then
       message := sqlerrm;
       build_check_message(1,'0312','0102',6,'',message);
       end;
       if v_erech is null then
         build_check_message(1,'0312','0102',7,'');
       end if;
      elsif  v_semel_hilan = '0971' then --פרוד/ה
      begin  
       select t.mispar_zehut_ben_mishpacha
                into v_erech
                from  bney_mishpacha t, poresh p
                where p.mispar_zehut = v_mispar_zehut
                and t.seq_porshim = p.porshim_seq
                and t.code_kirva = 1
                and t.seq_bney_mishpacha =
                (select max(b.seq_bney_mishpacha)
                from bney_mishpacha b
                where b.seq_porshim = p.porshim_seq
                and b.code_kirva = 1);
      exception
       when others then
       message := sqlerrm;
       --build_check_message('0312','0971',8,'');
      end;
      elsif v_semel_hilan = '0112' then  --  גמלאות כפל
      begin
      select min(t.date_payment)
                 into v_mi_taarich
                 from participation t
                 where t.seq_bakasha = v_seq_bakasha
                 and t.code_participation = 6;
      exception
      when others then
       if v_code_sug_bakasha = 18 then
          build_check_message(1,'0312','0112',8,'',message);
        end if;  
      end;
      v_times := 0;
      for r in          
            (select t.kizba_chodshit, t.percent_participate_calc,
            t.partial_period, t.date_payment
                 from participation t
                 where t.seq_bakasha = v_seq_bakasha
                 and t.code_participation = 6) loop
      if r.kizba_chodshit is null or
         r.percent_participate_calc is null or
         r.partial_period is null or
         r.date_payment is null then
               check_message := check_message || ' event_312; semel_0112 ' ||  '<br />';
      end if;         
      v_times :=  v_times + 1;              
      end loop;
      if v_times = 0 and v_code_sug_bakasha = 18 then
          build_check_message(1,'0312','0112',8,'');
      end if;     
     end if;
    end loop;
    return true;
    end;  
  ------------------------------------  
  --פרטי פורש
  function insert_event_200(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
  v_shem_mishpacha varchar2(50);
  v_shem_prati varchar2(50);
  v_shem_nosaf varchar2(50); 
  v_taarich_leida  date;
  v_taarich_aliya  date;
  is_passport number;
  --v_mispar_mofaim_p  number;
  --v_mispar_mofaim_b  number;
  v_mispar_zehut_sheer_benzug number :=0;
  begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
  
    /*select count(*)
    into v_mispar_mofaim_p
    from poresh t
    left join prisha p on
    p.seq_poresh = t.porshim_seq
    where t.mispar_zehut = case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut else v_mispar_zehut_sheer_benzug end
    and p.gimla_number <> v_gimla_number;

    select count(*)
    into v_mispar_mofaim_b
    from bney_mishpacha b
    left join poresh t on
    b.seq_porshim = t.porshim_seq
    left join prisha p on
    p.seq_poresh = t.porshim_seq
    where b.mispar_zehut_ben_mishpacha = case when v_mispar_zehut_sheer_benzug = 0  then v_mispar_zehut else v_mispar_zehut_sheer_benzug end
    and not b.code_relative is null
    and p.gimla_number <> v_gimla_number;

    
    if (v_mispar_mofaim_p > 0 or v_mispar_mofaim_b > 0) then --לא מדווחים אותו בן אדם פעמיים
      return true;
    else -- לא שאר ולא גמלה נוספת */ 
    ld_log_events_record.code_event := 200;
    ld_log_events_record.code_event_semel := 0;
    prepare_trigger_0(v_seq_ld_protocol,
                      v_seq_ld_protocol_hilan,
                      v_seq_bakasha,
                      case when v_mispar_zehut_sheer_benzug = 0  then v_mispar_zehut else v_mispar_zehut_sheer_benzug end,
                      v_gimla_number,
                      false,
                      sysdate);   
    if insert_event then
    if v_mispar_zehut_sheer_benzug = 0 then
    select p.shem_mishpacha, p.shem_prati, p.taarich_leda, p.taarich_aliya,
           case when nvl(p.sug_zihuy,0) = 1 then 0 else 1 end
            into v_shem_mishpacha, v_shem_prati, v_taarich_leida, v_taarich_aliya, is_passport
                from v_bakasha_last_status t
                left join poresh p on
                p.porshim_seq = t.seq_porshim
                where t.seq_bakasha = v_seq_bakasha;
    else
    select b.shem_mishpacha, b.shem_prati, b.taarich_leda,
           case when nvl(b.sug_zihuy,0) = 1 then 0 else 1 end
            into v_shem_mishpacha, v_shem_prati, v_taarich_leida, is_passport
                from v_bakasha_last_status t
                left join bney_mishpacha b on
                b.seq_porshim = t.seq_porshim                
                where t.seq_bakasha = v_seq_bakasha
                and b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
                and (v_code_sug_bakasha = 12 and b.code_kirva = 10 or v_code_sug_bakasha <> 12);
    end if;
           
    if length(trim(v_shem_prati)) > 10 and instr(trim(v_shem_prati),' ') > 0 then
      v_shem_prati := replace(v_shem_prati,'-',' ');
      v_shem_prati := replace(v_shem_prati,'(',' ');
      v_shem_prati := replace(v_shem_prati,')',' ');
      v_shem_prati := replace(v_shem_prati,'  ',' ');
      v_shem_nosaf := substr(trim(v_shem_prati),instr(trim(v_shem_prati),' '),100);
      v_shem_prati := substr(trim(v_shem_prati),1,instr(trim(v_shem_prati),' ')-1);
      v_shem_prati := substr(v_shem_prati,1,10);
      v_shem_nosaf := substr(trim(v_shem_nosaf),1,10);
    else
      v_shem_nosaf := ' ';
    end if;

    ld_log_events_record.code_trigger := 2;
    ld_log_events_record.record_hilan := 
           lpad_zeroez(case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut else v_mispar_zehut_sheer_benzug end,9) ||           --MIUN
           lpad_zeroez(case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut else v_mispar_zehut_sheer_benzug end,9) ||           --ZEUT
           rpad_blanks(v_shem_mishpacha,10) ||                                                                             --MISHPAHA 
           rpad_blanks(v_shem_prati,7) ||                                                                                  --SHEM 
           rpad_blanks(' ',10) ||                                                                                          --SHEMAV
           to_char(v_taarich_leida,date_format_d8) ||                                                                      --LEIDA
           lpad_zeroez(is_passport,1) ||                                                                                   --DARKON
           rpad_blanks(v_shem_mishpacha,20) ||                                                                             --MISHPAHA_MALE
           rpad_blanks(v_shem_prati,10) ||                                                                                 --SHEM_MALE
           rpad_blanks(v_shem_nosaf,10) ||                                                                                 --SHEM_NOSAF
           rpad_blanks(' ',10) ||                                                                                          --FIRSTN                                                                                      
           rpad_blanks(' ',10) ||                                                                                          --MIDDLEN
           rpad_blanks(' ',14) ||                                                                                          --FAMILYN
           rpad_blanks(' ',5) ||                                                                                           --USER
           rpad_blanks(' ',1) ||                                                                                           --FILLER
           (case when v_taarich_aliya is null then lpad_zeroez(0,8) else to_char(v_taarich_aliya,date_format_d8) end) ||    --ALIADT
           lpad_zeroez(0,3) ||                                                                                             --BIRTH_COUNTRY                                                                                      --
           lpad_zeroez(0,3) ||                                                                                             --ALIA_COUNTRY
           lpad_zeroez(0,3) ||                                                                                             --NETINUT
           lpad_zeroez(0,3) ||                                                                                             --NETINUT_B
           rpad_blanks(' ',1);                                                                                             --LEOM
           --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
      return insert_event;
    else
      return false;
    end if;
    --end if;
    exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_200: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_200: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;
  ------------------------------------
  --פרטי פורש
  function check_event_200(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
  v_shem_mishpacha varchar2(50);
  v_shem_prati varchar2(50);
  v_shem_nosaf varchar2(50); 
  v_taarich_leida  date;
  v_taarich_aliya  date;
  v_mispar_mofaim_p  number;
  v_mispar_mofaim_b  number;
  v_mispar_zehut_sheer_benzug number :=0;
  begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
  
    if v_mispar_zehut_sheer_benzug = 0 then
    begin
    select p.shem_mishpacha, p.shem_prati, p.taarich_leda, p.taarich_aliya
            into v_shem_mishpacha, v_shem_prati, v_taarich_leida, v_taarich_aliya
                from v_bakasha_last_status t
                left join poresh p on
                p.porshim_seq = t.seq_porshim
                where t.seq_bakasha = v_seq_bakasha;
    exception
    when others then
      message := sqlerrm;
      build_check_message(1,'0200','0000',9,': ' || to_char(v_mispar_zehut),message);
    end;         
    else
    begin
    select b.shem_mishpacha, b.shem_prati, b.taarich_leda
            into v_shem_mishpacha, v_shem_prati, v_taarich_leida
                from v_bakasha_last_status t
                left join bney_mishpacha b on
                b.seq_porshim = t.seq_porshim                
                where t.seq_bakasha = v_seq_bakasha
                and b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
                and (v_code_sug_bakasha = 12 and b.code_kirva = 10 or v_code_sug_bakasha <> 12);
    exception
    when others then
       message := sqlerrm;
       build_check_message(1,'0200','0000',10,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
    end;
    end if;
           
    
    if length(trim(v_shem_prati)) > 10 and instr(trim(v_shem_prati),' ') > 0 then
      v_shem_prati := replace(v_shem_prati,'-',' ');
      v_shem_prati := replace(v_shem_prati,'(',' ');
      v_shem_prati := replace(v_shem_prati,')',' ');
      v_shem_prati := replace(v_shem_prati,'  ',' ');
      v_shem_nosaf := substr(trim(v_shem_prati),instr(trim(v_shem_prati),' '),100);
      v_shem_prati := substr(trim(v_shem_prati),1,instr(trim(v_shem_prati),' ')-1);
      v_shem_prati := substr(v_shem_prati,1,10);
      v_shem_nosaf := substr(trim(v_shem_nosaf),1,10);
    else
      v_shem_nosaf := ' ';
    end if;
    
    if v_shem_mishpacha is null then
      build_check_message(1,'0200','0000',11,'');
    end if;
    if v_shem_prati is null then
      build_check_message(1,'0200','0000',12,'');
    end if;
    if v_taarich_leida is null then
      build_check_message(1,'0200','0000',13,'');
    end if;
    return true;
    end;
  ------------------------------------
  --מצב משפחתי
   function insert_event_205(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_code_mazav_mishpachti number;
   v_date_mazav_mishpachti date;
   v_date_update date;
   v_code_min number;
   v_code_mazav_mishpachti_hilan number;
   v_mispar_zehut_sheer_benzug number :=0;
  begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    
    if v_mispar_zehut_sheer_benzug = 0 then  
        select mishp.code_mazav_mishpachti, mishp.date_mazav_mishpachti, mishp.code_min, mishp.date_update
        into v_code_mazav_mishpachti, v_date_mazav_mishpachti, v_code_min, v_date_update
        from (select m.code_mazav_mishpachti, m.date_mazav_mishpachti,p.code_min, m.date_update
                  from poresh p, mazav_mishpachti m
                  where p.mispar_zehut = v_mispar_zehut
                  and m.seq_poresh = p.porshim_seq
                  --order by (case when m.date_mazav_mishpachti is null then m.date_update else m.date_mazav_mishpachti end) desc
                  order by m.seq_mazav_mishpachti desc
                  nulls last) mishp
                  where rownum = 1;
     else
        select mishp.code_mazav_mishpachti, mishp.date_mazav_mishpachti, mishp.code_min, mishp.date_update
        into v_code_mazav_mishpachti, v_date_mazav_mishpachti, v_code_min, v_date_update
        from (select m.code_mazav_mishpachti, m.date_mazav_mishpachti,b.code_min, m.date_update
                  from bney_mishpacha b, mazav_mishpachti m
                  where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
                  and m.seq_bney_mishpacha = b.seq_bney_mishpacha
                  --order by (case when m.date_mazav_mishpachti is null then m.date_update else m.date_mazav_mishpachti end) desc
                  order by m.seq_mazav_mishpachti desc
                  nulls last) mishp
                  where rownum = 1;
     end if;
     if v_mispar_zehut_sheer_benzug=0 and v_code_mazav_mishpachti = 4 then --פרוד/ה 
             insert_or_check_event_dynamic(312,
                                  '0971',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  0,
                                  0,
                                  v_code_seif_prisha,
                                  0);
            if not if_commit then return false; end if;
     end if;
          
    if v_code_mazav_mishpachti is null then v_code_mazav_mishpachti := 0; end if;
    if v_code_min is null then v_code_min := 0;  end if;
    v_code_mazav_mishpachti_hilan := get_mazav_mishpachti_hilan(v_code_mazav_mishpachti,v_code_min);
    if (v_date_mazav_mishpachti is null or to_char(v_date_mazav_mishpachti,'DD/MM/YYYY') = '00/00/0000') then
      v_date_mazav_mishpachti := case when v_date_update is not null then v_date_update 
                                      when v_code_sug_bakasha = 1 then v_date_start_zakaut
                                       else sysdate end;
    end if;
    if v_code_mazav_mishpachti_hilan <> 0 then
      ld_log_events_record.code_event := 205;
      ld_log_events_record.code_event_semel := 0;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut else v_mispar_zehut_sheer_benzug end,
                        v_gimla_number,
                        false,
                        v_date_mazav_mishpachti);
      if insert_event then   
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             lpad(v_code_mazav_mishpachti_hilan,1) ||                                                    --MATZAV
             (case when v_code_mazav_mishpachti_hilan in(2,6) then --נשוי/נשואה                          --TOKEF
                   to_char(case when v_code_sug_bakasha = 12 then v_hp_date_haavara
                                when v_code_sug_bakasha = 24 then sysdate  
                                else v_date_start_zakaut end,date_format_d6) else
                   lpad_zeroez(0,6) end) ||  --חודש טוקף
             to_char(v_date_mazav_mishpachti,date_format_d8) ||                                          --MITAARICH
             lpad_zeroez(0,6);                                                                           --GMARTOKEF
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
       return insert_event;
       else
         return false;
       end if;
    end if;
    return true;
    exception
     when no_data_found then
       return true;
     when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_205: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_205: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;
  ------------------------------------  
  --מצב משפחתי
   function check_event_205(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_code_mazav_mishpachti number;
   v_date_mazav_mishpachti date;
   v_date_update date;
   v_code_min number;
   v_code_mazav_mishpachti_hilan number;
   v_mispar_zehut_sheer_benzug number :=0;
  begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then
       return true;
    end if;
    
    if v_mispar_zehut_sheer_benzug = 0 then
      begin  
        select mishp.code_mazav_mishpachti, mishp.date_mazav_mishpachti, mishp.code_min, mishp.date_update
        into v_code_mazav_mishpachti, v_date_mazav_mishpachti, v_code_min, v_date_update
        from (select m.code_mazav_mishpachti, m.date_mazav_mishpachti,p.code_min, m.date_update
                  from poresh p, mazav_mishpachti m
                  where p.mispar_zehut = v_mispar_zehut
                  and m.seq_poresh = p.porshim_seq
                  --order by (case when m.date_mazav_mishpachti is null then m.date_update else m.date_mazav_mishpachti end) desc
                  order by m.seq_mazav_mishpachti desc
                  nulls last) mishp
                  where rownum = 1;
     exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0205','0000',14,': ' || to_char(v_mispar_zehut),message);
     end;
    else
      begin
        select mishp.code_mazav_mishpachti, mishp.date_mazav_mishpachti, mishp.code_min, mishp.date_update
        into v_code_mazav_mishpachti, v_date_mazav_mishpachti, v_code_min, v_date_update
        from (select m.code_mazav_mishpachti, m.date_mazav_mishpachti,b.code_min, m.date_update
                  from bney_mishpacha b, mazav_mishpachti m
                  where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
                  and m.seq_bney_mishpacha = b.seq_bney_mishpacha
                  --order by (case when m.date_mazav_mishpachti is null then m.date_update else m.date_mazav_mishpachti end) desc
                  order by m.seq_mazav_mishpachti desc
                  nulls last) mishp
                  where rownum = 1;
     exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0205','0000',14,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
     end;
    end if;
          
    if v_code_mazav_mishpachti is null then v_code_mazav_mishpachti := 0; end if;
    if v_code_min is null then v_code_min := 0;  end if;
    v_code_mazav_mishpachti_hilan := get_mazav_mishpachti_hilan(v_code_mazav_mishpachti,v_code_min);
    if v_code_mazav_mishpachti_hilan is null then
      build_check_message(1,'0205','0000',15,'');
    end if;
    
    return true;
    end;
  ------------------------------------  
  --כתובת
  function insert_event_218(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                         ) return boolean is
  v_city_code number;
  v_city varchar2(30);
  v_street varchar2(100);
  v_house number;
  v_appartment number;
  v_entrance varchar2(10);
  v_mikud varchar2(10);
  v_telephon varchar2(30);
  v_telephon2 varchar2(30);
  v_pelephon varchar2(30);
  v_email varchar2(50);
  v_update_date date;
  v_mispar_zehut_sheer_benzug number :=0;
  v_exists_sheer_address number;
  v_mispar_zehut_bakasha number := 0;
  v_td varchar2(6);
  
  begin
    if v_mistz_almana_benzug_sheer <> 0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan <> 0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    
    if v_mispar_zehut_sheer_benzug <>0 then 
        select 
        case when exists(select b.mispar_zehut_ben_mishpacha
        from bney_mishpacha b, address a
        where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
        and a.seq_bney_mishpacha = b.seq_bney_mishpacha
        and not a.code_city is null) then 1 else 0 end
        into v_exists_sheer_address
        from dual t;
    end if;
        
    if v_code_sug_bakasha <> 21 then --לא בקשת שינוי כתובת
    if v_mispar_zehut_sheer_benzug = 0 or v_exists_sheer_address = 0 then
    select  distinct a.code_city, a.street, a.house, a.apartment, a.entrance,
            a.mikud, a.date_update,
            p.telephon, p.telephon2, p.pelephon, p.email
            into v_city_code, v_street, v_house, v_appartment, v_entrance,
            v_mikud, v_update_date,
            v_telephon, v_telephon2, v_pelephon, v_email
            from poresh p, address a
            where p.mispar_zehut = v_mispar_zehut
            and a.seq_poresh = p.porshim_seq
            and a.seq_bney_mishpacha is null
            and (a.code_address = 1
            and (not exists (select *
            from address a1
            where a1.seq_poresh = p.porshim_seq
            and a1.seq_bney_mishpacha is null
            and a1.code_address = 2))
            or
            (a.code_address = 2
            and a.seq_address = 
            (select max(a1.seq_address)
            from address a1
            where a1.seq_poresh = p.porshim_seq
            and a1.seq_bney_mishpacha is null
            and a1.code_address = 2)));
    else
    select  a.code_city, a.street, a.house, a.apartment, a.entrance,
            a.mikud, a.date_update,
            b.telephone, null, b.pelephone, b.email
            into v_city_code, v_street, v_house, v_appartment, v_entrance,
            v_mikud, v_update_date,
            v_telephon, v_telephon2, v_pelephon, v_email
            from bney_mishpacha b, address a, poresh p
            where not b.code_kirva is null
            and b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
            and a.seq_poresh is null
            and a.seq_bney_mishpacha = b.seq_bney_mishpacha
            and p.porshim_seq = b.seq_porshim
            and p.mispar_zehut = v_mispar_zehut
            and (a.code_address = 1
            and (not exists (select *
            from address a1
            where a1.seq_poresh is null
            and a1.seq_bney_mishpacha = b.seq_bney_mishpacha
            and a1.code_address = 2))
            or
            (a.code_address = 2
            and a.seq_address = 
            (select max(a1.seq_address)
            from address a1
            where a1.seq_poresh is null
            and a1.seq_bney_mishpacha = b.seq_bney_mishpacha
            and a1.code_address = 2)));
    end if;
    else
    select distinct a.code_city, a.street, a.house, a.apartment, a.entrance,
           a.mikud, a.date_update,
           case when not a.seq_poresh is null then p.telephon else b.telephone end,
           case when not a.seq_poresh is null then p.telephon2 else null end,
           case when not a.seq_poresh is null then p.pelephon else b.pelephone end,
           case when not a.seq_poresh is null then p.email else b.email end,
           case when not a.seq_poresh is null then p.mispar_zehut else b.mispar_zehut_ben_mishpacha end
           into v_city_code, v_street, v_house, v_appartment, v_entrance,
           v_mikud, v_update_date,
           v_telephon, v_telephon2, v_pelephon, v_email,
           v_mispar_zehut_bakasha           
    from address a, poresh p, bney_mishpacha b
    where a.seq_bakasha = v_seq_bakasha
    and p.mispar_zehut = v_mispar_zehut
    and (a.seq_bney_mishpacha is null
         and a.seq_poresh = p.porshim_seq   
    or not a.seq_bney_mishpacha is null
        and a.seq_bney_mishpacha = b.seq_bney_mishpacha
        and b.seq_porshim = p.porshim_seq);
    end if;
   
    v_city := substr(get_yishuv(v_city_code),1,13);
    if not v_street is null then 
       v_street := replace(v_street,'כניסה',' ');
       v_street := replace(replace(v_street,'  ',' '),'  ',' ');
    end if;
    if instr(v_street,'ת.ד',
      1) > 0 or 
      instr(v_street,'ת"ד',
      1) >0 then
      v_td := get_ta_doar(v_street);
    else
      v_td := lpad_zeroez(0,6);
    end if;
    if v_house is null then v_house := 0; end if;
    if v_appartment is null then v_appartment := 0; end if;
    if v_entrance is null then v_entrance := ' '; end if;
    if v_mikud is null then v_mikud := ' '; end if;
    --v_street := reverse_mispar(v_street);
  
    ld_log_events_record.code_event := 218;
    ld_log_events_record.code_event_semel := 0;
    prepare_trigger_0(v_seq_ld_protocol,
                      v_seq_ld_protocol_hilan,
                      v_seq_bakasha,
                      case when v_mispar_zehut_bakasha = 0 then
                        case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut else v_mispar_zehut_sheer_benzug end
                        else v_mispar_zehut_bakasha end,
                      v_gimla_number,
                      false,
                      nvl(v_update_date,sysdate));          
    if insert_event then
    ld_log_events_record.code_trigger := 2;
    ld_log_events_record.record_hilan :=    
           lpad_zeroez(v_city_code,4) ||                                                                                     --SEMEL_YISHUV
           rpad_blanks(v_city,13) ||                                                                                         --YISHUV
           case when v_house is null then
                rpad_blanks(trim(v_street),28)                                                                               --address
           else
                rpad_blanks(trim(v_street),17) ||                                                                            --REHOV
                lpad_zeroez(v_house,5) ||                                                                                    --BAIT
                lpad_zeroez(v_appartment,4) ||                                                                               --DIRA
                rpad_blanks(v_entrance,2) end  ||                                                                            --KNISA
           rpad_blanks(' ',2) ||                                                                                             --FILLER
          (case when v_mikud = ' ' then lpad_zeroez(0,7) else lpad_zeroez(to_number(v_mikud),7) end) ||                       --MIKUD
           case when v_code_sug_bakasha <> 21 then get_telephone(v_pelephon) else lpad_zeroez(0,10) end ||                                                                                     --TELEFON
           v_td ||                                                                                                           --TA_DOAR
           lpad_zeroez(0,7) ||                                                                                               --MIKUD_TA_DOAR
           lpad_zeroez(0,4) ||                                                                                               --YISHUV_TA_DOAR
           case when v_code_sug_bakasha <> 21 then get_telephone(v_telephon) else lpad_zeroez(0,10) end ||                                                                                      --TELEFON_2
           case when v_code_sug_bakasha <> 21 then get_telephone(v_telephon2) else lpad_zeroez(0,10) end ||                                                                                     --TELEFON_3
           lpad_zeroez(0,10) ||                                                                                              --FAX
           rpad_blanks(v_email,30) ||                                                                                        --E_MAIL
           rpad_blanks(' ',7);                                                                                               --FILLER
           --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
       return insert_event;
    else
      return false;
    end if;
    exception
    when others then
      status  := 0;
      message := sqlerrm;
      clob_log := clob_log ||('insert_event_218: ' || message) ||  '<br />';
      v_error_172_message := 'insert_event_218: ' || message;
      v_error_172_seq_bakasha := v_seq_bakasha;
      v_error_172_mispar_zehut := v_mispar_zehut;
      return false;
    end;
  ------------------------------------  
   --כתובת
  function check_event_218(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                         ) return boolean is
  v_city_code number;
  v_city varchar2(30);
  v_street varchar2(100);
  v_house number;
  v_appartment number;
  v_entrance varchar2(10);
  v_mikud varchar2(10);
  v_telephon varchar2(30);
  v_telephon2 varchar2(30);
  v_pelephon varchar2(30);
  v_email varchar2(50);
  v_update_date date;
  v_mispar_zehut_sheer_benzug number :=0;
  v_exists_sheer_address number;
  v_mispar_zehut_bakasha number := 0;
  
  begin
    if v_mistz_almana_benzug_sheer <> 0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan <> 0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    
    if v_mispar_zehut_sheer_benzug = 0 and v_code_sug_bakasha = 21 then
      select b.mispar_zehut_ben_mishpacha
      into v_mispar_zehut_sheer_benzug
      from address a
      left join bney_mishpacha b
      on b.seq_bney_mishpacha = nvl(a.seq_bney_mishpacha,0)
      and b.code_relative = 6
      where a.seq_bakasha = v_seq_bakasha;
      if v_mispar_zehut_sheer_benzug is null then
        v_mispar_zehut_sheer_benzug := 0;
      end if;   
    end if;

    if v_mispar_zehut_sheer_benzug <>0 then
        select 
        case when exists(select b.mispar_zehut_ben_mishpacha
        from bney_mishpacha b, address a
        where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
        and a.seq_bney_mishpacha = b.seq_bney_mishpacha
        and not a.code_city is null) then 1 else 0 end
        into v_exists_sheer_address
        from dual t;
    end if;
        
    if v_code_sug_bakasha <> 21 then --לא בקשת שינוי כתובת
    if v_mispar_zehut_sheer_benzug = 0 or v_exists_sheer_address = 0 then
    begin
      v_mispar_zehut_bakasha := v_mispar_zehut;
    select  distinct a.code_city, a.street, a.house, a.apartment, a.entrance,
            a.mikud, a.date_update,
            p.telephon, p.telephon2, p.pelephon, p.email
            into v_city_code, v_street, v_house, v_appartment, v_entrance,
            v_mikud, v_update_date,
            v_telephon, v_telephon2, v_pelephon, v_email
            from poresh p, address a
            where p.mispar_zehut = v_mispar_zehut
            and a.seq_poresh = p.porshim_seq
            and a.seq_bney_mishpacha is null
            and (a.code_address = 1
            and (not exists (select *
            from address a1
            where a1.seq_poresh = p.porshim_seq
            and a1.seq_bney_mishpacha is null
            and a1.code_address = 2))
            or
            (a.code_address = 2
            and a.seq_address = 
            (select max(a1.seq_address)
            from address a1
            where a1.seq_poresh = p.porshim_seq
            and a1.seq_bney_mishpacha is null
            and a1.code_address = 2)));
      exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0218','0000',16,': ' || to_char(v_mispar_zehut),message);
      end;
    else
      begin
      v_mispar_zehut_bakasha := v_mispar_zehut_sheer_benzug;
      select  a.code_city, a.street, a.house, a.apartment, a.entrance,
            a.mikud, a.date_update,
            b.telephone, null, b.pelephone, b.email
            into v_city_code, v_street, v_house, v_appartment, v_entrance,
            v_mikud, v_update_date,
            v_telephon, v_telephon2, v_pelephon, v_email
            from bney_mishpacha b, address a, poresh p
            where not b.code_kirva is null
            and p.porshim_seq = b.seq_porshim
            and p.mispar_zehut = v_mispar_zehut
            and b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
            and a.seq_poresh is null
            and a.seq_bney_mishpacha = b.seq_bney_mishpacha
            and (a.code_address = 1
            and (not exists (select *
            from address a1
            where a1.seq_poresh is null
            and a1.seq_bney_mishpacha = b.seq_bney_mishpacha
            and a1.code_address = 2))
            or
            (a.code_address = 2
            and a.seq_address = 
            (select max(a1.seq_address)
            from address a1
            where a1.seq_poresh is null
            and a1.seq_bney_mishpacha = b.seq_bney_mishpacha
            and a1.code_address = 2)));
      exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0218','0000',16,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
      end;
    end if;
    else
      begin
      select distinct a.code_city, a.street, a.house, a.apartment, a.entrance,
           a.mikud, a.date_update,
           case when not a.seq_poresh is null then p.telephon else b.telephone end,
           case when not a.seq_poresh is null then p.telephon2 else null end,
           case when not a.seq_poresh is null then p.pelephon else b.pelephone end,
           case when not a.seq_poresh is null then p.email else b.email end,
           case when not a.seq_poresh is null then p.mispar_zehut else b.mispar_zehut_ben_mishpacha end
           into v_city_code, v_street, v_house, v_appartment, v_entrance,
           v_mikud, v_update_date,
           v_telephon, v_telephon2, v_pelephon, v_email,
           v_mispar_zehut_bakasha           
      from address a, poresh p, bney_mishpacha b
      where a.seq_bakasha = v_seq_bakasha
      and p.mispar_zehut = v_mispar_zehut
      and (a.seq_bney_mishpacha is null
         and a.seq_poresh = p.porshim_seq   
      or not 
        a.seq_bney_mishpacha is null
        and a.seq_bney_mishpacha = b.seq_bney_mishpacha
        and b.seq_porshim = p.porshim_seq);
      exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0218','0000',16,': ' || to_char(v_mispar_zehut_bakasha),message); 
      end;
    end if;
   
    v_city := substr(get_yishuv(v_city_code),1,13);
    if not v_street is null then 
       v_street := replace(replace(v_street,'  ',' '),'  ',' ');
    end if;
    if v_appartment is null then v_appartment := 0; end if;
    if v_entrance is null then v_entrance := ' '; end if;
    --v_street := reverse_mispar(v_street);
    
    if v_city_code is null then
       build_check_message(1,'0218','0000',17,': ' || to_char(v_mispar_zehut_bakasha),message);
    end if;   
    if v_street is null then
       build_check_message(2,'0218','0000',18,': ' || to_char(v_mispar_zehut_bakasha),message);
    end if;
    if v_mikud is null then
       build_check_message(2,'0218','0000',19,': ' || to_char(v_mispar_zehut_bakasha),message);
    end if;
    return true;
    end;
  ------------------------------------  
  -- קרובי משפחה
  function insert_event_219(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
  v_mispar_zehut_ben_mishpacha number;
  v_shem_mishpacha varchar2(50);
  v_shem_prati varchar2(50);
  v_taarich_leida  date;
  v_code_kirva number;
  v_code_kirva_hilan varchar2(1);
  v_code_min number;
  return_code boolean := true;
  is_first boolean := true;
  
begin
    for r in 
            (select distinct b.mispar_zehut_ben_mishpacha, b.shem_prati, b.shem_mishpacha, 
                     b.code_kirva, b.taarich_leda, b.code_min
            from poresh p
            left join  bney_mishpacha b on
            b.seq_porshim = p.porshim_seq
            left join  mazav_mishpachti m on
            m.seq_poresh = p.porshim_seq
            where p.mispar_zehut = v_mispar_zehut
            and m.seq_bney_mishpacha is null
            and (b.code_kirva = 1 
            and (m.code_mazav_mishpachti = 6 --פוליגם
            or (m.code_mazav_mishpachti <> 6 or m.code_mazav_mishpachti is null)
            and b.seq_bney_mishpacha = (select max(b1.seq_bney_mishpacha)
                                                             from bney_mishpacha b1
                                                             where b1.seq_porshim = p.porshim_seq
                                                             and b1.code_kirva = 1))
            or ((b.code_kirva = 2 or b.code_kirva = 23)
            and b.taarich_leda is null
            or sysdate - b.taarich_leda < 365*21)))     
    loop
    begin
           
    if is_first then
      is_first := false;
      ld_log_events_record.code_event := 219;
      ld_log_events_record.code_event_semel := 0;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        v_mispar_zehut,
                        v_gimla_number,
                        false,
                        sysdate);
       return_code := insert_event;
    end if;
    if return_code then
    v_mispar_zehut_ben_mishpacha := r.mispar_zehut_ben_mishpacha;
    v_shem_mishpacha := r.shem_mishpacha;
    v_shem_prati := r.shem_prati;
    v_code_kirva := r.code_kirva;
    v_code_min := r.code_min;                            
    v_code_kirva_hilan := get_code_kirva_hilan(nvl(v_code_kirva,0),nvl(v_code_min,1));
    v_taarich_leida := r.taarich_leda;
    ld_log_events_record.code_trigger := 2;
    ld_log_events_record.record_hilan :=    
           rpad_blanks(v_shem_prati,10) ||                                     --SHEM
           lpad_zeroez(v_mispar_zehut_ben_mishpacha,9) ||                      --ZEHUT
           to_char(v_taarich_leida,date_format_d8) ||                          --LEIDA
           v_code_kirva_hilan ||                                               --KOD
           lpad_zeroez(0,8) ||                                                 --TAARICH
           lpad_zeroez(0,8) ||                                                 --GMARTOKEF
           lpad_zeroez(0,8) ||                                                 --TAARICH1
           lpad_zeroez(0,8);                                                   --TAARICH2
           --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
           return_code := insert_event;
     else
       return false;
     end if;
   end;
   end loop;
   return return_code;
   exception
    when others then
      status  := 0;
      message := sqlerrm;
      clob_log := clob_log ||('insert_event_219: ' || message) ||  '<br />';
      v_error_172_message := 'insert_event_219: ' || message;
      v_error_172_seq_bakasha := v_seq_bakasha;
      v_error_172_mispar_zehut := v_mispar_zehut;
      return false;
    end;
  ------------------------------------  
  -- קרובי משפחה
  function check_event_219(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
  v_mispar_zehut_ben_mishpacha number;
  v_shem_mishpacha varchar2(50);
  v_shem_prati varchar2(50);
  v_taarich_leida  date;
  v_code_kirva number;
  v_code_kirva_hilan varchar2(1);
  v_code_min number;
  return_code boolean := true;
  is_first boolean := true;
  
begin
    for r in 
            (select distinct b.mispar_zehut_ben_mishpacha, b.shem_prati, b.shem_mishpacha, 
                     b.code_kirva, b.taarich_leda, b.code_min
            from poresh p
            left join  bney_mishpacha b on
            b.seq_porshim = p.porshim_seq
            left join  mazav_mishpachti m on
            m.seq_poresh = p.porshim_seq
            where p.mispar_zehut = v_mispar_zehut
            and m.seq_bney_mishpacha is null
            and (b.code_kirva = 1 
            and (m.code_mazav_mishpachti = 6 --פוליגם
            or (m.code_mazav_mishpachti <> 6 or m.code_mazav_mishpachti is null)
            and b.seq_bney_mishpacha = (select max(b1.seq_bney_mishpacha)
                                                             from bney_mishpacha b1
                                                             where b1.seq_porshim = p.porshim_seq
                                                             and b1.code_kirva = 1))
            or ((b.code_kirva = 2 or b.code_kirva = 23)
            and b.taarich_leda is null
            or sysdate - b.taarich_leda < 365*21)))     
    loop
    begin           
    v_mispar_zehut_ben_mishpacha := r.mispar_zehut_ben_mishpacha;
    v_shem_mishpacha := r.shem_mishpacha;
    v_shem_prati := r.shem_prati;
    v_code_kirva := r.code_kirva;
    v_code_min := r.code_min;                            
    v_code_kirva_hilan := get_code_kirva_hilan(nvl(v_code_kirva,0),nvl(v_code_min,1));
    v_taarich_leida := r.taarich_leda;
    if v_mispar_zehut_ben_mishpacha is null then
      build_check_message(1,'0219','0000',20,'');
    end if;
    if v_shem_mishpacha is null then
      build_check_message(1,'0219','0000',21,'');
    end if;
    if v_shem_prati is null then
      build_check_message(1,'0219','0000',22,'');
    end if;
    if v_code_min is null then
      build_check_message(2,'0219','0000',23,'');
    end if;                            
    if v_code_kirva_hilan is null then
      build_check_message(1,'0219','0000',24,'');
    end if;
    end;
    end loop;
   return true;
   end;
  ------------------------------------  
  --דואר אלקטרוני
  function insert_event_298(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
    v_email varchar2(50);
    v_mispar_zehut_sheer_benzug number :=0;
  begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
 
     if (v_code_sug_bakasha = 12) then
     select b.email
            into v_email
            from bney_mishpacha b
            where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
            and not b.email is null;
     end if;
     if (v_code_sug_bakasha <> 12) or
        (v_code_sug_bakasha = 12) and v_email is null then
     select p.email
            into v_email
            from poresh p
            where p.mispar_zehut = v_mispar_zehut
            and not p.email is null;
     end if;
      
      ld_log_events_record.code_event := 298;
      ld_log_events_record.code_event_semel := v_semel_hilan;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut else v_mispar_zehut_sheer_benzug end,
                        v_gimla_number,
                        false,
                        sysdate);                      
      if insert_event then   
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             rpad_blanks(v_email,66) ||                       --E_MAIL
             to_char(sysdate,date_format_d8) ||               --TAARICH
             '00000000';                                      --GMARTOKEF
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
      return insert_event;
      else
        return false;
      end if;
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_298: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_298: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
      return false;
    end;
  ------------------------------------  
  --דואר אלקטרוני
  function check_event_298(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
    v_email varchar2(50);
    v_mispar_zehut_sheer_benzug number :=0;
  begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
 
     if (v_code_sug_bakasha = 12) then
     begin
     select b.email
            into v_email
            from bney_mishpacha b
            where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
            and not b.email is null;
       exception
      when others then
      message := sqlerrm;
      build_check_message(2,'0298','0001',25,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
      end;
     end if;     
     if (v_code_sug_bakasha <> 12) or
        (v_code_sug_bakasha = 12) and v_email is null then
     begin
     select p.email
            into v_email
            from poresh p
            where p.mispar_zehut = v_mispar_zehut
            and not p.email is null;
      exception
      when others then
      message := sqlerrm;
      build_check_message(2,'0298','0001',25,': ' || to_char(v_mispar_zehut),message);
      end;
      end if;     
     return true;
  end;
  ------------------------------------  
  --פרטי בנק
   function insert_event_303(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_code_bank number;
   v_code_snif number;
   v_heshbon number;
   v_date_update date;
   v_mispar_zehut_sheer_benzug number :=0;
   v_exists_sheer_cheshbon number;
   v_mispar_zehut_bakasha number := 0;
  begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
 
    if v_mispar_zehut_sheer_benzug <>0 then 
        select 
        case when exists(select b.mispar_zehut_ben_mishpacha
        from bney_mishpacha b, bank_account a
        where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
        and a.seq_bney_mishpacha = b.seq_bney_mishpacha) then 1 else 0 end
        into v_exists_sheer_cheshbon
        from dual t;
    end if;
    
    if v_code_sug_bakasha <> 15 then
    if v_mispar_zehut_sheer_benzug <> 0 and v_exists_sheer_cheshbon = 1  then
      select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update
      into v_code_bank, v_code_snif, v_heshbon, v_date_update
      from
      (select a.*
      from bney_mishpacha b, bank_account a
      where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
      and a.seq_bney_mishpacha = b.seq_bney_mishpacha
      and a.seq_bakasha = v_seq_bakasha
      order by a.seq_bank_account desc) aa
      where rownum = 1;
    else    
      select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update
      into v_code_bank, v_code_snif, v_heshbon, v_date_update
      from
      (select a.*
      from poresh p, bank_account a
      where p.mispar_zehut = v_mispar_zehut
      and a.seq_bakasha = v_seq_bakasha
      order by a.seq_bank_account desc) aa
      where rownum = 1;
    end if;
    else
      /*select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update
      into v_code_bank, v_code_snif, v_heshbon, v_date_update, v_mispar_zehut_bakasha         
      from v_bank_account aa, poresh p, bney_mishpacha b
      where aa.seq_bakasha = v_seq_bakasha
      and p.mispar_zehut = v_mispar_zehut
      and (aa.seq_bney_mishpacha is null
      and aa.seq_porshim = p.porshim_seq
      or not aa.seq_bney_mishpacha is null
      and aa.seq_bney_mishpacha = b.seq_bney_mishpacha
      and p.porshim_seq = b.seq_porshim);*/
      select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update, p.mispar_zehut
      into v_code_bank, v_code_snif, v_heshbon, v_date_update, v_mispar_zehut_bakasha         
      from v_bank_account aa, poresh p
      where aa.seq_bakasha = v_seq_bakasha
      and p.mispar_zehut = v_mispar_zehut
      and aa.seq_bney_mishpacha is null
      and aa.seq_porshim = p.porshim_seq
      union
      select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update, b.mispar_zehut_ben_mishpacha
      from v_bank_account aa, poresh p, bney_mishpacha b
      where aa.seq_bakasha = v_seq_bakasha
      and p.mispar_zehut = v_mispar_zehut 
      and not aa.seq_bney_mishpacha is null
      and aa.seq_bney_mishpacha = b.seq_bney_mishpacha
      and p.porshim_seq = b.seq_porshim;
     end if;
    
    if v_code_bank <> 0 and not v_code_bank is null then
      ld_log_events_record.code_event := 303;
      ld_log_events_record.code_event_semel := 0;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_bakasha = 0 then
                        case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut else v_mispar_zehut_sheer_benzug end
                        else v_mispar_zehut_bakasha end,
                        v_gimla_number,
                        false,
                        case when v_date_update is not null then v_date_update else sysdate end);                      
      if insert_event then   
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             lpad_zeroez(v_code_bank,3) ||                    --MISPBANK
             lpad_zeroez(v_code_snif,3) ||                    --SNIF
             lpad_zeroez(v_heshbon,9);                        --HESHBON
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
       return insert_event;
      else
       return false;
      end if;
    end if;
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_303: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_303: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;
  ------------------------------------  
  --פרטי בנק
  function check_event_303(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_code_bank number;
   v_code_snif number;
   v_heshbon number;
   v_date_update date;
   v_mispar_zehut_sheer_benzug number :=0;
   v_exists_sheer_cheshbon number;
   v_mispar_zehut_bakasha number := 0;
   v_code_relative number;
   
  begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
  
    if v_mispar_zehut_sheer_benzug = 0 and v_code_sug_bakasha = 15 then
      select b.mispar_zehut_ben_mishpacha
      into v_mispar_zehut_sheer_benzug
      from bank_account ba
      left join bney_mishpacha b
      on b.seq_bney_mishpacha = nvl(ba.seq_bney_mishpacha,0)
      and b.code_relative = 6
      where ba.seq_bakasha = v_seq_bakasha;
      if v_mispar_zehut_sheer_benzug is null then
        v_mispar_zehut_sheer_benzug := 0;
      end if;   
    end if;

    if v_mispar_zehut_sheer_benzug <>0 then 
     select b.code_relative
        into v_code_relative
        from bney_mishpacha b, poresh p
        where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
        and p.mispar_zehut = v_mispar_zehut
        and b.seq_porshim = p.porshim_seq;
     select 
        case when exists(select b.mispar_zehut_ben_mishpacha
        from bney_mishpacha b, v_bank_account a, v_bakasha_last_status v
        where  b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug 
               and a.seq_bney_mishpacha = b.seq_bney_mishpacha
               and (a.seq_bakasha = v_seq_bakasha or
               a.seq_bakasha < v_seq_bakasha and 
               a.seq_bakasha = v.seq_bakasha and
               v.gimla_number = v_gimla_number and
               v.code_action = 98)
        ) then 1 else 0 end
        into v_exists_sheer_cheshbon
        from dual t;
    end if;
  
    
    if v_code_sug_bakasha <> 15 then
       if v_mispar_zehut_sheer_benzug <> 0 then
        if v_exists_sheer_cheshbon = 0  then
        if (v_mistz_almana_benzug_sheer <> 0 or v_mispar_zehut_ben_katan <> 0 and v_code_relative <> 2)    then
          build_check_message(1,'0303','0000',26,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
          return true;
        elsif v_mispar_zehut_ben_katan <> 0 and v_code_relative = 2 then
          begin
          select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update
          into v_code_bank, v_code_snif, v_heshbon, v_date_update
          from
          (select a.*
          from bney_mishpacha b, v_bank_account a, poresh p
          where b.code_relative = 1
          and p.porshim_seq = b.seq_porshim
          and p.mispar_zehut = v_mispar_zehut
          and a.seq_bney_mishpacha = b.seq_bney_mishpacha
          and a.seq_bakasha = ( 
/*              select max(v.seq_bakasha)
                from v_bakasha_last_status v
                where v.seq_bakasha <= v_seq_bakasha and 
                v.gimla_number = v_gimla_number and
                (v.code_action = 98 or v.seq_bakasha=v_seq_bakasha)*/
                select max(v.seq_bakasha)
                from v_bakasha_last_status v
                where (v.seq_bakasha < v_seq_bakasha and 
                v.gimla_number = v_gimla_number and
                v.code_action = 98  
                or v.seq_bakasha=v_seq_bakasha)             
                and exists (select a1.seq_bakasha
                from bank_account a1, v_bakasha_last_status v1
                where a1.seq_bakasha = v1.seq_bakasha
                and v1.seq_bakasha = v.seq_bakasha
                and v1.gimla_number = v_gimla_number
                and a1.seq_bney_mishpacha = b.seq_bney_mishpacha))                
          order by a.seq_bank_account desc) aa
          where rownum = 1;
         exception
         when others then
          message := sqlerrm;
          build_check_message(1,'0303','0000',26,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
          return true;
         end;
        end if;
        else
          begin
          select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update
          into v_code_bank, v_code_snif, v_heshbon, v_date_update
          from
          (select a.*
          from bney_mishpacha b, v_bank_account a
          where a.seq_bney_mishpacha = b.seq_bney_mishpacha
          and b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
          and a.seq_bakasha = ( 
              /*select max(v.seq_bakasha)
               from v_bakasha_last_status v
               where v.seq_bakasha <= v_seq_bakasha and 
                v.gimla_number = v_gimla_number and
                (v.code_action = 98 or v.seq_bakasha=v_seq_bakasha)*/
                 select max(v.seq_bakasha)
                from v_bakasha_last_status v
                where (v.seq_bakasha < v_seq_bakasha and 
                v.gimla_number = v_gimla_number and
                v.code_action = 98  
                or v.seq_bakasha=v_seq_bakasha)             
                and exists (select a1.seq_bakasha
                from bank_account a1, v_bakasha_last_status v1
                where a1.seq_bakasha = v1.seq_bakasha
                and v1.seq_bakasha = v.seq_bakasha
                and v1.gimla_number = v_gimla_number
                and a1.seq_bney_mishpacha = b.seq_bney_mishpacha))
          order by a.seq_bank_account desc) aa
          where rownum = 1;
      
         exception
         when others then
          message := sqlerrm;
          build_check_message(1,'0303','0000',26,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
          return true;
         end;
        end if;
       else
        begin
          select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update
          into v_code_bank, v_code_snif, v_heshbon, v_date_update
          from
          (select a.*
          from v_bank_account a, poresh p
          where a.seq_porshim = p.porshim_seq
                and nvl(a.seq_bney_mishpacha,0) = 0
          and a.seq_bakasha = ( 
              select max(v.seq_bakasha)
               from v_bakasha_last_status v
               where v.seq_bakasha <= v_seq_bakasha and 
                v.gimla_number = v_gimla_number and
                (v.code_action = 98 or v.seq_bakasha=v_seq_bakasha))
          order by a.seq_bank_account desc
          ) aa
          where rownum = 1;
         exception
         when others then
          message := sqlerrm;
          build_check_message(1,'0303','0000',26,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
          return true;
        end;
       end if;
    else
      begin
      if v_mispar_zehut_sheer_benzug = 0 then
      select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update, p.mispar_zehut
      into v_code_bank, v_code_snif, v_heshbon, v_date_update, v_mispar_zehut_bakasha         
      from v_bank_account aa, poresh p
      where aa.seq_bakasha = v_seq_bakasha
      and p.mispar_zehut = v_mispar_zehut
      and aa.seq_bney_mishpacha is null
      and aa.seq_porshim = p.porshim_seq;
      else
      select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update, b.mispar_zehut_ben_mishpacha
      into v_code_bank, v_code_snif, v_heshbon, v_date_update, v_mispar_zehut_bakasha         
      from v_bank_account aa, poresh p, bney_mishpacha b
      where aa.seq_bakasha = v_seq_bakasha
      and p.mispar_zehut = v_mispar_zehut 
      and not aa.seq_bney_mishpacha is null
      and aa.seq_bney_mishpacha = b.seq_bney_mishpacha
      and p.porshim_seq = b.seq_porshim
      and b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug;
      end if;
      exception
      when others then
      message := sqlerrm;
       /*  build_check_message(1,'0303','0000',26,': ' || 
         case when v_mispar_zehut_sheer_benzug<>0 then to_char(v_mispar_zehut_sheer_benzug)
                                                  else to_char(v_mispar_zehut) end || ' - ' ||
         message);*/
      end;
    end if;
    if v_code_bank is null then
      if v_code_sug_bakasha<>15  then
      build_check_message(1,'0303','0000',26,': ' || 
         case when v_mispar_zehut_sheer_benzug<>0 then to_char(v_mispar_zehut_sheer_benzug)
                                                  else to_char(v_mispar_zehut) end);
      end if;
      return true;
    end if;
    if v_code_snif is null then
      if v_code_sug_bakasha<>15  then
      build_check_message(1,'0303','0000',26,': ' || 
         case when v_mispar_zehut_sheer_benzug<>0 then to_char(v_mispar_zehut_sheer_benzug)
                                                  else to_char(v_mispar_zehut) end);
      end if;
      return true;
    end if;
    if v_heshbon is null then
      if v_code_sug_bakasha<>15 then
      build_check_message(1,'0303','0000',26,': ' || 
         case when v_mispar_zehut_sheer_benzug<>0 then to_char(v_mispar_zehut_sheer_benzug)
                                                  else to_char(v_mispar_zehut) end);
      end if;
      return true;
    end if;
    v_is_heshbon_bank := 2; --תקין

   return true;
   end;
  ------------------------------------  
  --פרטי דירוג דרגה
   function insert_event_535(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_taarich_me date;
   v_taarich_me_report date;
   v_taarich_me_str varchar2(8);
   v_taarich_ad date;                            
   v_code_derug number;
   v_code_darga varchar2(4);
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_misra number;
   
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;

    --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    --if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 
   
    for r in (select n.*
      from netuney_sachar n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_sug_maskoret = 1
      order by n.mispar_misra) loop
      
    v_mispar_misra := r.mispar_misra;
    v_taarich_me := r.from_date;
    
    select cd.derug_hilan, cd.darga_hilan
    into v_code_derug, v_code_darga
    from code_derug_darga_hilan cd
    where cd.derug_malam = r.code_derug
    and cd.darga_malam = r.code_darga;
 
    if v_code_derug <> 0 and not v_code_derug is null then
      ld_log_events_record.code_event := 535;
      ld_log_events_record.code_event_semel := '0000';
      v_taarich_me_str := case when v_taarich_me is null then to_char(sysdate,date_format_d6) || '01' 
                                          else to_char(v_taarich_me,date_format_d6) || '01' end;
      v_taarich_me_report := to_date(v_taarich_me_str,date_format_d8);
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug else v_mispar_zehut end,
                        case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                        else 
                                v_gimla_number
                        end,
                        true,
                        v_taarich_me_report);                      
      if not insert_event then return false; end if;
       
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                          --MINUI
             lpad_zeroez(v_code_derug,2) ||                                                                                  --DERUG
             lpad_zeroez(v_code_darga,4) ||                                                                                  --DARGA
             (case when v_taarich_me is null then lpad_zeroez(0,8) else to_char(v_taarich_me,date_format_d8) end) ||         --TAARICH                                                                                      
             lpad_zeroez(0,8);                                                                                               --GMARTOKEF
             /*(case when v_taarich_ad is null then lpad_zeroez(0,8)                                                         
                   when v_taarich_ad = to_date('31/12/9999','DD/MM/YYYY') then lpad_zeroez(0,8)
                   else to_char(v_taarich_me,date_format_d8) end);*/
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
             if not insert_event then return false; end if;
    end if;
    end loop;
    return true;
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_535: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_535: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;
  ------------------------------------
  --פרטי דירוג דרגה
   function check_event_535(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_taarich_me date;
   v_taarich_me_report date;
   v_taarich_me_str varchar2(8);
   v_taarich_ad date;                            
   v_code_derug number;
   v_code_darga varchar2(4);
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_misra number;
   v_times number := 0;
   
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;

    --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    --if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 
    
    for r in (select n.*
      from netuney_sachar n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_sug_maskoret = 1
      order by n.mispar_misra) loop
      
    v_mispar_misra := r.mispar_misra;
    v_taarich_me := r.from_date;
    
    select cd.derug_hilan, cd.darga_hilan
    into v_code_derug, v_code_darga
    from code_derug_darga_hilan cd
    where cd.derug_malam = r.code_derug
    and cd.darga_malam = r.code_darga;
 
    if v_code_derug is null then
       build_check_message(1,'0535','0000',27,'');
    end if;
    if v_code_darga is null then
       build_check_message(1,'0535','0000',27,'');
    end if;
    v_times := v_times + 1;    
    end loop;
    if v_times = 0 then
       build_check_message(1,'0535','0000',27,'');
    end if;
    
    return true;
    end;
  ------------------------------------
  -- הפסקת / חידוש תשלטמים
  function insert_event_221(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_taarich_me date;
   v_taarich_ad date;                            
   v_code_matzav number;
   v_code_matzav_hidush number;
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_zehut_sheer_benzug_amiti number :=0;
   v_ld_log_events_seq_cur_value number;
   v_hafsakat_ben_zug boolean;
   v_mispar_misra number;
   v_mistz_almana_benzug_sheer1 number := 0;
   v_mispar_zehut_ben_katan1 number := 0;
   v_mispar_zehut_sheer number := 0;
   v_seq_bney_mishpacha number;


    begin      
      
       select t.from_date, nvl(c.code_bakasha_hilan,0), c.code_bakasha_detail, t.seq_bney_mishpacha
           into v_taarich_me, v_code_matzav, v_code_matzav_hidush, v_seq_bney_mishpacha
           from bakasha t, code_bakasha_detail c
           where t.seq_bakasha = v_seq_bakasha
           and t.code_bakasha_detail = c.code_bakasha_detail;
       if v_seq_bney_mishpacha is not null and v_seq_bney_mishpacha <> 0 then
         select b.mispar_zehut_ben_mishpacha
         into v_mispar_zehut_sheer
         from bney_mishpacha b 
         where b.seq_bney_mishpacha = v_seq_bney_mishpacha;
        -- v_mispar_zehut_sheer := get_mispar_zehut_fictivi(v_mispar_zehut_sheer,v_gimla_number);
       end if;
      v_count_221 := v_count_221 + 1;
      if v_count_221 > 1 then return true; end if;

      if v_mispar_zehut_sheer <>0 then
        v_ld_log_events_seq_cur_value := ld_log_events_seq.currval;
        update ld_log_events t
               set t.mispar_zehut = v_mispar_zehut_sheer
               where t.seq_ld_protocol_hilan = v_seq_ld_protocol_hilan
               and t.mispar_zehut = v_mispar_zehut
               and t.seq_ld_log_events = v_ld_log_events_seq_cur_value;   
      end if;         

   
      for i in 1 .. v_mispar_misrot_sach_hakol
      loop
      v_mispar_misra := i;  
      ld_log_events_record.code_event := 221;
      ld_log_events_record.code_event_semel := 0;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer <>0 then v_mispar_zehut_sheer
                                                           else v_mispar_zehut end,
                        case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra,1))
                             else 
                                v_gimla_number
                             end,
                        true,
                        v_taarich_me);                      
      if insert_event then   
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                            --MINUI
             lpad_zeroez(v_code_matzav,2) ||                   --MATZAV
             to_char(v_taarich_me,date_format_d8) ||           --MITAARICH
             lpad_zeroez(0,8);                                 --ADTAARICH
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
            if insert_event then
              continue;
            else
              return false;
            end if;
        else 
             return false;
        end if;
      end loop;
         if v_code_matzav = 44 then --נישואין שניים  
             insert_or_check_event_dynamic(527,
                                  '0245',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mispar_zehut_sheer,
                                  0,
                                  v_code_seif_prisha,
                                  1,
                                  v_mispar_misra,
                                  1);  
             if not if_commit then return false; end if;
             insert_or_check_event_dynamic(527,
                                  '0246',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mispar_zehut_sheer,
                                  0,
                                  v_code_seif_prisha,
                                  1,
                                  v_mispar_misra,
                                  1);  
              if not if_commit then return false; end if;            
        end if; 
    return true;
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_221: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_221: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;

  ------------------------------------  
  -- הפסקת / חידוש תשלומים
  function check_event_221(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_taarich_me date;
   v_taarich_ad date;                            
   v_code_matzav number;
   v_mispar_zehut_sheer_benzug number :=0;
   v_code_matzav_hidush number;
   v_seq_bney_mishpacha number :=0;
   v_taarich_ptirat_sheer date;
   v_mispar_zehut_sheer number;
   begin
   
       select t.from_date, nvl(c.code_bakasha_hilan,0), c.code_bakasha_detail, t.seq_bney_mishpacha
           into v_taarich_me, v_code_matzav, v_code_matzav_hidush, v_seq_bney_mishpacha
           from bakasha t, code_bakasha_detail c
           where t.seq_bakasha = v_seq_bakasha
           and t.code_bakasha_detail = c.code_bakasha_detail;
           
      
       if nvl(v_seq_bney_mishpacha,0) <> 0 then
         select b.mispar_zehut_ben_mishpacha
         into v_mispar_zehut_sheer
         from bney_mishpacha b 
         where b.seq_bney_mishpacha = v_seq_bney_mishpacha;
       end if;       

       if  v_seq_bney_mishpacha is not null then    
         select b.taarich_ptira
         into v_taarich_ptirat_sheer 
         from bney_mishpacha b
         where b.seq_bney_mishpacha = v_seq_bney_mishpacha;
       end if;
      
       if (v_ptira_besherut_gimlat_chesed or v_ptirat_poresh or v_taarich_ptirat_poresh is not null)
        --and v_seq_bney_mishpacha is not null
        and v_code_sug_bakasha = 20 --חידוש תשלום
        and v_seq_bney_mishpacha is null  then 
            build_check_message(1,'0221','0000',51,''); 
            return true;                    
        end if;
       
      if v_code_sug_bakasha = 19 and v_code_matzav_hidush = 6 and v_taarich_ptirat_poresh is null
        then  build_check_message(1,'0221','0000',52,''); 
            return true;                    
        end if;

      if v_seq_bney_mishpacha is not null and 
       v_code_sug_bakasha = 19 and v_code_matzav_hidush = 19 
       and (v_mispar_zehut_sheer = v_mistz_almana_benzug_sheer  or v_mispar_zehut_sheer = v_mispar_zehut_ben_katan)
       and v_taarich_ptirat_sheer is null
        then  build_check_message(1,'0221','0000',53,''); 
            return true;                    
        end if;
      
       if v_taarich_me is null or 
         nvl(v_code_matzav_hidush,0) = 0 and v_code_sug_bakasha = 20 then
        build_check_message(1,'0221','0000',28,'');
        return true;
       end if;
       select t.from_date, nvl(c.code_bakasha_hilan,0), c.code_bakasha_detail, t.seq_bney_mishpacha
           into v_taarich_me, v_code_matzav, v_code_matzav_hidush, v_seq_bney_mishpacha
           from bakasha t, code_bakasha_detail c
           where t.seq_bakasha = v_seq_bakasha
           and t.code_bakasha_detail = c.code_bakasha_detail;
       if nvl(v_seq_bney_mishpacha,0) = 0 and v_code_matzav_hidush in (7,8,19) then
               build_check_message(1,'0221','0000',49,'');                
       end if;
    exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0221','0000',28,'',message);
      return true;
    end;
   ------------------------------------  
   --נתוני היוון
   function insert_event_315(v_semel_hilan varchar2,                --567
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_date_hivun date;
   v_seq_hivun number;
   v_achuz_hivun float;
   v_hp_sheur_havara float;
   v_date_gmar_tokef_hivun date;

    begin 
  
    ld_log_events_record.code_event := 315;
    ld_log_events_record.code_event_semel := v_semel_hilan;
   
    if v_semel_hilan = '0567' then --היוון
      
    select t.seq_hivun, t.date_bakasha, t.achuz_hivun
    into v_seq_hivun, v_date_hivun, v_achuz_hivun
    from hivun t, v_bakasha_last_status v
    where t.seq_bakasha = v.seq_bakasha
    and (v.code_sug_bakasha=16 and v.code_bakasha_detail = 2 or v.code_sug_bakasha<>16)
    and t.seq_bakasha = v_seq_bakasha;
  
    --תאריך תחילת ההיוון לא יהיה לפני תאריך תחילת הזכאות
    if v_date_hivun < v_date_start_zakaut then v_date_hivun := v_date_start_zakaut; end if; 
    
    --select last_day(add_months(min(t.date_bakasha),71))
    select last_day(add_months(v_date_hivun,71))
    into v_date_gmar_tokef_hivun
    from dual;
    
    /*from hivun t, v_bakasha_last_status v
    where t.seq_bakasha = v.seq_bakasha
    v.gimla_number = 308651
    and v.code_sug_bakasha = 16;
    and t.seq_bakasha = v.seq_bakasha
    and t.code_hivun = 2;*/
       
    if not v_seq_hivun is null then
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        v_mispar_zehut,
                        v_gimla_number,
                        true,
                        v_date_hivun,
                        '  ' || lpad_zeroez(v_seq_hivun,9));                      
      if insert_event then   
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                          --MINUI
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(v_seq_hivun,9) ||                                                                                   --ERECH
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(replace(to_char(v_achuz_hivun,'0000000.99'),'.',''),9) ||                                           --ERECH_2
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(0,9) ||                                                                                             --ERECH_3
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(0,9) ||                                                                                             --ERECH_4
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(0,9) ||                                                                                             --ERECH_5
             rpad_blanks(' ',15) ||                                                                                          --TEUR
             (case when v_date_hivun is null then lpad_zeroez(0,8) else to_char(v_date_hivun,date_format_d8) end) ||         --TAARICH
             lpad_zeroez(0,8);                                                                                               --GMARTOKEF
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
            return insert_event;
      else
        return false;
      end if;
    end if;
    
    elsif v_semel_hilan = '0412' and v_code_sug_bakasha = 12 then --חיסכון פנסיוני
      
    select t.hp_sheur_havara
    into v_hp_sheur_havara
    from bakasha_regila t
    where t.seq_bakasha = v_seq_bakasha;
    
    if not v_hp_sheur_havara is null then
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        v_mispar_zehut,
                        v_gimla_number,
                        true,
                        v_hp_date_haavara,
                        '  ' || rpad_blanks(' ',9));                      
      if insert_event then   
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                          --MINUI
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(v_mistz_almana_benzug_sheer,9) ||                                                                  --ERECH
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(replace(to_char(v_hp_sheur_havara,'0000000.99'),'.',''),9) ||                                       --ERECH_2
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(0,9) ||                                                                                             --ERECH_3
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(0,9) ||                                                                                             --ERECH_4
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(0,9) ||                                                                                             --ERECH_5
             rpad_blanks(' ',15) ||                                                                                          --TEUR
             to_char(v_hp_date_haavara,date_format_d8) ||                                                                    --TAARICH
             lpad_zeroez(0,8);                                                                                               --GMARTOKEF
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
            return insert_event;
      else
        return false;
      end if;
    end if; 
    end if;
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_237' || v_semel_hilan || ': ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_237: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
        return false;
    end;
  ------------------------------------  
   --נתוני היוון
   function check_event_315(v_semel_hilan varchar2,                --567
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_date_hivun date;
   v_seq_hivun number;
   v_achuz_hivun float;
   v_hp_sheur_havara float;
   v_date_gmar_tokef_hivun date;
   v_code_bakasha_detail number;

    begin 
   
    if v_semel_hilan = '0567' then --היוון
    begin  
    select t.seq_hivun, t.date_bakasha, t.achuz_hivun, v.code_bakasha_detail
    into v_seq_hivun, v_date_hivun, v_achuz_hivun, v_code_bakasha_detail
    from hivun t, v_bakasha_last_status v
    where t.seq_bakasha = v.seq_bakasha
    --and (v.code_sug_bakasha=16 and v.code_bakasha_detail = 2 or v.code_sug_bakasha<>16)
    and t.seq_bakasha = v_seq_bakasha;

    --if v_date_hivun < v_date_start_zakaut then v_date_hivun := v_date_start_zakaut; end if; --מייל מדבורה מתאריך 05/06/2019
    
    if v_date_hivun is null or 
      ((v_achuz_hivun is null or v_achuz_hivun = 0) and v_code_bakasha_detail <> 3 ) or
       to_char(v_date_hivun,'DD/MM/YYYY') = '00/00/0000' then
      build_check_message(1,'0315','0567',48,'',message);
    end if;
    exception
     when others then
      if v_code_sug_bakasha = 16 then
      message := sqlerrm;
      build_check_message(1,'0315','0567',29,'',message);
      end if;
    end;
   
    begin
    select last_day(add_months(min(t.date_bakasha),71))
    into v_date_gmar_tokef_hivun
    from hivun t, v_bakasha_last_status v
    where v.gimla_number = v_gimla_number
    and t.seq_bakasha = v.seq_bakasha;
    --and t.code_hivun = 2
    --and v.code_sug_bakasha = 16;
    exception
     when others then
     --if v_code_sug_bakasha = 16 then
     message := sqlerrm;
     build_check_message(1,'0315','0567',29,'',message);
     --end if;
    end; 
   
    elsif v_semel_hilan = '0412' and v_code_sug_bakasha = 12 then --חיסכון פנסיוני
    begin  
    select t.hp_sheur_havara
    into v_hp_sheur_havara
    from bakasha_regila t
    where t.seq_bakasha = v_seq_bakasha;
    exception
     when others then
      message := sqlerrm;
      build_check_message(1,'0315','0412',30,'',message);
    end;
    end if;
    return true;
    end;
  ------------------------------------  
   function insert_event_539_1_9(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mispar_zehut_sheer_benzug number,
                          v_code_seif_prisha number,
                          v_mispar_misra number
                          ) return boolean is
   v_code_vetek number;
   v_taarich_prisha date;
   v_vetek_hatchala_kolel number;
   v_vetek_hatchala_kolel_shanim number;
   v_vetek_hatchala_kolel_hodashim number;
   v_vetek_hatchala_zahal number;
   v_vetek_hatchala_zahal_shanim number;
   v_vetek_hatchala_zahal_hodashim number;
   v_insert_event boolean;
   is_vetek_colel number; 
   is_vetek_zahal number;
 
   begin                         
    ld_log_events_record.code_event_semel := v_semel_hilan;
           prepare_trigger_0(v_seq_ld_protocol,
                             v_seq_ld_protocol_hilan,
                             v_seq_bakasha,
                             case when v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug else v_mispar_zehut end,
                             case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                             else 
                                v_gimla_number
                             end,
                             true,
                             case when v_code_sug_bakasha <> 12 then 
                               to_date(to_char(v_date_start_zakaut,date_format_d6) || '01',date_format_d8)                               
                             else
                               to_date(to_char(v_hp_date_haavara,date_format_d6) || '01',date_format_d8) end
                             );
                             
           if not insert_event then return false; end if;
           
           ld_log_events_record.code_trigger := 2;
           ld_log_events_record.record_hilan :=  '0' ||                                                        --MINUI                                                                                                                                                                                                       
             case when v_code_sug_bakasha <> 12 then                                                           --TAARICH  
               case when v_semel_hilan = '0001' then to_char(v_date_start_zakaut,date_format_d6) || '01'
                    when v_semel_hilan = '0009' then to_char(v_date_start_zakaut_poresh_niftar,date_format_d6) || '01' end
                                                else to_char(v_hp_date_haavara,date_format_d6)|| '01' end ||                         
             lpad_zeroez(0,8) ||                                                                               --GMARTOKEF
             case when v_code_sug_bakasha <> 12 then                                                           --TAARICH  
               case when v_semel_hilan = '0001' then to_char(v_date_start_zakaut,date_format_d6) || '01'
                    when v_semel_hilan = '0009' then to_char(v_date_start_zakaut_poresh_niftar,date_format_d6) || '01' end
                                                else to_char(v_hp_date_haavara,date_format_d6)|| '01' end ||                         
             ' ' ||                                                                                                                           --מינוס
             lpad_zeroez(0,5) ||                                                                               --HAFCHATA
             lpad_zeroez(0,4);                                                                                 --VETEK_HATHALA
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';                         
 
           if not insert_event then return false; end if;
           return true;        
   exception
       when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_539: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_539: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
   end; 
     
  ------------------------------------  
  --וותקים למינוי
   function insert_event_539(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_code_vetek number;
   v_taarich_prisha date;
   v_vetek_hatchala_kolel number;
   v_vetek_hatchala_kolel_shanim number;
   v_vetek_hatchala_kolel_hodashim number;
   v_vetek_hatchala_zahal number;
   v_vetek_hatchala_zahal_shanim number;
   v_vetek_hatchala_zahal_hodashim number;
   v_insert_event boolean;
   is_vetek_colel number; 
   is_vetek_zahal number;
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_misra number := 0;
   v_cnt_539 number;
   v_result boolean;
   
  begin
    if v_mistz_almana_benzug_sheer <> 0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan <> 0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
       
       if v_code_sug_bakasha = 13 then
       begin
           v_date_start_zakaut_poresh_niftar := null;
/*             select z."DATE_START_ZAKAUT"
            into v_date_start_zakaut_poresh_niftar
            from v_bakasha_last_status v1, v_bakasha_last_zakaut z
            where v1.gimla_number = 
            (select v2.gimla_number
            from v_bakasha_last_status v2
            where v2.seq_bakasha = v_seq_bakasha
            )
            and z."DATE_START_ZAKAUT" is not null
            and v1.code_sug_bakasha in (1,5)
            and v1.code_action = 98
            and v1.seq_bakasha = z.seq_bakasha
            and v1.seq_bakasha = 
            (select max(v3.seq_bakasha)
            from v_bakasha_last_status v3
            where v3.gimla_number = v1.gimla_number
            and v3.code_sug_bakasha in (1,5));
*/     
            select z."DATE_START_ZAKAUT"
            into v_date_start_zakaut_poresh_niftar
            from v_bakasha_last_status v1, v_bakasha_last_zakaut z
            where v1.gimla_number = 
            (select v2.gimla_number
            from v_bakasha_last_status v2
            where v2.seq_bakasha = 303975 
            )
            and v1.code_sug_bakasha in (1,5)
            and v1.code_action = 98
            and v1.seq_bakasha = z.seq_bakasha
            and v1.seq_bakasha = 
            (select max(v3.seq_bakasha)
            from v_bakasha_last_status v3
            where v3.gimla_number = v1.gimla_number
            and v3.code_sug_bakasha in (1,5)
            and v3.code_action = 98);
       exception
       when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_539: ' || 'אין תאריך זכאות של הפורש הנפטר' || ' ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_539: '|| 'אין תאריך זכאות של הפורש הנפטר' || ' ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut_sheer_benzug;
       return false;
       end;
       end if; 
 
       ld_log_events_record.code_event := 539;

       if not v_netuney_sachar_kayamim  then --לשלוח רק סמל 0001/0009
        --const_seq_ezor_ovdim_chinuch = v_seq_ezor_ovdim 
 
        for i in 1 .. v_mispar_misrot_sach_hakol
        loop
        v_result := insert_event_539_1_9('0001',
                          v_seq_ld_protocol,
                          v_seq_ld_protocol_hilan,
                          v_seq_bakasha,
                          v_mispar_zehut,
                          v_gimla_number,
                          v_seq_ezor_ovdim,
                          v_code_sug_bakasha,
                          v_mispar_zehut_sheer_benzug,
                          v_code_seif_prisha,
                          i-1
                          );
       if not v_result then return false; end if;
       if v_code_sug_bakasha = 13 then
       v_result := insert_event_539_1_9('0009',
                          v_seq_ld_protocol,
                          v_seq_ld_protocol_hilan,
                          v_seq_bakasha,
                          v_mispar_zehut,
                          v_gimla_number,
                          v_seq_ezor_ovdim,
                          v_code_sug_bakasha,
                          v_mispar_zehut_sheer_benzug,
                          v_code_seif_prisha,
                          i-1
                          );
       if not v_result then return false; end if;
       end if;
       end loop;
       return true;
       end if;
   
  
    for r in (select n.*
      from netuney_sachar n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_sug_maskoret = 1
      order by n.mispar_misra) loop
      
    v_mispar_misra := r.mispar_misra;
  
     v_result := insert_event_539_1_9('0001',
                          v_seq_ld_protocol,
                          v_seq_ld_protocol_hilan,
                          v_seq_bakasha,
                          v_mispar_zehut,
                          v_gimla_number,
                          v_seq_ezor_ovdim,
                          v_code_sug_bakasha,
                          v_mispar_zehut_sheer_benzug,
                          v_code_seif_prisha,
                          v_mispar_misra
                          );
    if not v_result then return false; end if;
    
    if v_code_sug_bakasha = 12 then continue; end if;
    
    if v_code_sug_bakasha = 13 then
     v_result := insert_event_539_1_9('0009',
                          v_seq_ld_protocol,
                          v_seq_ld_protocol_hilan,
                          v_seq_bakasha,
                          v_mispar_zehut,
                          v_gimla_number,
                          v_seq_ezor_ovdim,
                          v_code_sug_bakasha,
                          v_mispar_zehut_sheer_benzug,
                          v_code_seif_prisha,
                          v_mispar_misra
                          );
      if not v_result then return false;
      else continue;
      end if;
    end if;
    

    select count(*)
            into is_vetek_colel
                from vetek_detail t
                where t.seq_bakasha = v_seq_bakasha
                and (t.seq_netuney_sachar = r.seq_netuney_sachar or t.seq_netuney_sachar is null)
                and t.code_type_vetek = 6;
                
    if is_vetek_colel > 0 then
      select max(t.years)
            into v_vetek_hatchala_kolel
                from vetek_detail t
                where t.seq_bakasha = v_seq_bakasha
                and (t.seq_netuney_sachar = r.seq_netuney_sachar or t.seq_netuney_sachar is null)
                and t.code_type_vetek = 6;
      v_vetek_hatchala_kolel_shanim := (v_vetek_hatchala_kolel * 100 - mod((v_vetek_hatchala_kolel*100),100))/100;
      v_vetek_hatchala_kolel_hodashim := v_vetek_hatchala_kolel - v_vetek_hatchala_kolel_shanim;
      v_vetek_hatchala_kolel_hodashim := 
      case when v_vetek_hatchala_kolel_hodashim >=0 and v_vetek_hatchala_kolel_hodashim < 0.25 then 0.00
           when v_vetek_hatchala_kolel_hodashim >=0.25 and v_vetek_hatchala_kolel_hodashim < 0.5 then 0.03
           when v_vetek_hatchala_kolel_hodashim >=0.5 and v_vetek_hatchala_kolel_hodashim < 0.75 then 0.06
           when v_vetek_hatchala_kolel_hodashim >=0.75 and v_vetek_hatchala_kolel_hodashim < 1.00 then 0.09
      end;
       v_vetek_hatchala_kolel := v_vetek_hatchala_kolel_shanim + v_vetek_hatchala_kolel_hodashim;
    else
       v_vetek_hatchala_kolel := 0;
    end if;
    
    select count(*)
            into is_vetek_zahal
                from vetek_detail t
                where t.seq_bakasha = v_seq_bakasha
                and (t.seq_netuney_sachar = r.seq_netuney_sachar or t.seq_netuney_sachar is null)
                and t.code_type_vetek = 2;
               
    if is_vetek_zahal > 0 then
      select max(t.years)
            into v_vetek_hatchala_zahal
                from vetek_detail t
                where t.seq_bakasha = v_seq_bakasha
                and (t.seq_netuney_sachar = r.seq_netuney_sachar or t.seq_netuney_sachar is null)
                and t.code_type_vetek = 2;
                
      v_vetek_hatchala_zahal_shanim := (v_vetek_hatchala_zahal * 100 - mod((v_vetek_hatchala_zahal*100),100))/100;
      v_vetek_hatchala_zahal_hodashim := v_vetek_hatchala_zahal - v_vetek_hatchala_zahal_shanim;
      v_vetek_hatchala_zahal_hodashim := 
      case when v_vetek_hatchala_zahal_hodashim >=0 and v_vetek_hatchala_zahal_hodashim < 0.25 then 0.00
           when v_vetek_hatchala_zahal_hodashim >=0.25 and v_vetek_hatchala_zahal_hodashim < 0.5 then 0.03
           when v_vetek_hatchala_zahal_hodashim >=0.5 and v_vetek_hatchala_zahal_hodashim < 0.75 then 0.06
           when v_vetek_hatchala_zahal_hodashim >=0.75 and v_vetek_hatchala_zahal_hodashim < 1.00 then 0.09
      end;
       v_vetek_hatchala_zahal := v_vetek_hatchala_zahal_shanim + v_vetek_hatchala_zahal_hodashim;
    else
       v_vetek_hatchala_zahal := 0;
    end if;
     
           ld_log_events_record.code_event_semel := '0002';
           prepare_trigger_0(v_seq_ld_protocol,
                             v_seq_ld_protocol_hilan,
                             v_seq_bakasha,
                             case when v_mispar_zehut_sheer_benzug <> 0  then v_mispar_zehut_sheer_benzug else v_mispar_zehut end,
                             case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                             else 
                                v_gimla_number
                             end,
                             true,
                             to_date(to_char(v_date_start_zakaut,date_format_d6) || '01',date_format_d8));
                                                   
           if not insert_event then return false; end if;

           ld_log_events_record.code_trigger := 2;
           ld_log_events_record.record_hilan := 
             '0' ||
             (case when v_date_start_zakaut is null then lpad_zeroez(0,8) else to_char(v_date_start_zakaut,date_format_d6) || '01' end) ||
             lpad_zeroez(0,8) ||
             lpad_zeroez(0,8) ||
             ' ' ||
             lpad_zeroez(0,5) ||
             trim(replace(to_char(nvl(v_vetek_hatchala_kolel,0),'00.99'),'.',''));
             --clob_log := clob_log || replace(to_char(nvl(v_vetek_hatchala_kolel,0),'00.99'),'.','') ||  '<br />';
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
           if not insert_event then return false; end if;
           
           if v_vetek_hatchala_zahal > 0 then
             ld_log_events_record.code_event_semel := '0005';
             prepare_trigger_0(v_seq_ld_protocol,
                               v_seq_ld_protocol_hilan,
                               v_seq_bakasha,
                               case when v_mispar_zehut_sheer_benzug <> 0  then v_mispar_zehut_sheer_benzug else v_mispar_zehut end,
                               case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                               else 
                                v_gimla_number
                               end,
                               true,
                               to_date(to_char(v_date_start_zakaut,date_format_d6) || '01',date_format_d8));                      
           if not insert_event then return false; end if;
 
           ld_log_events_record.code_trigger := 2;
           ld_log_events_record.record_hilan := 
               '0' ||
               (case when v_date_start_zakaut is null then lpad_zeroez(0,8) else to_char(v_date_start_zakaut,date_format_d6) || '01' end) ||
               lpad_zeroez(0,8) ||
               lpad_zeroez(0,8) ||
               ' ' ||
               lpad_zeroez(0,5) ||
               trim(replace(to_char(nvl(v_vetek_hatchala_zahal,0),'00.99'),'.',''));
               --clob_log := clob_log || replace(to_char(nvl(v_vetek_hatchala_zahal,0),'00.99'),'.','') ||  '<br />';
               --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
              if not insert_event then return false; end if;
           end if;
           end loop;
           return true;
    exception
/*    when no_data_found then
       return true;
*/  
       when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_539: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_539: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
      return false;
    end;  
  ------------------------------------  
  --וותקים למינוי
   function check_event_539(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_code_vetek number;
   v_taarich_prisha date;
   v_vetek_hatchala_kolel number;
   v_vetek_hatchala_zahal number;
   v_insert_event boolean;
   is_vetek_colel number; 
   is_vetek_zahal number;
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_misra number := 0;
   v_times number := 0;
   
  begin
    if v_mistz_almana_benzug_sheer <> 0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan <> 0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
       
    --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    --if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 

       if v_code_sug_bakasha = 13 then
       begin
           v_date_start_zakaut_poresh_niftar := null;
            select z."DATE_START_ZAKAUT"
            into v_date_start_zakaut_poresh_niftar
            from v_bakasha_last_status v1, v_bakasha_last_zakaut z
            where v1.gimla_number = 
            (select v2.gimla_number
            from v_bakasha_last_status v2
            where v2.seq_bakasha = v_seq_bakasha 
            )
            and v1.code_sug_bakasha in (1,5)
            and v1.code_action = 98
            and v1.seq_bakasha = z.seq_bakasha
            and v1.seq_bakasha = 
            (select max(v3.seq_bakasha)
            from v_bakasha_last_status v3
            where v3.gimla_number = v1.gimla_number
            and v3.code_sug_bakasha in (1,5)
            and v3.code_action = 98);
       exception
       when others then
               build_check_message(1,'0539','0009',50,'',message);
       end;
      end if;
       
    if not v_netuney_sachar_kayamim and v_seq_ezor_ovdim = const_seq_ezor_ovdim_chinuch then return true; end if;
    
    for r in (select n.*
      from netuney_sachar n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_sug_maskoret = 1
      order by n.mispar_misra) loop
      
    v_mispar_misra := r.mispar_misra;
      
    select count(*)
            into is_vetek_colel
                from vetek_detail t
                where t.seq_bakasha = v_seq_bakasha
                and (t.seq_netuney_sachar = r.seq_netuney_sachar or t.seq_netuney_sachar is null)
                and t.code_type_vetek = 6;
                
    if is_vetek_colel > 0 then
       select t.years
            into v_vetek_hatchala_kolel
                from vetek_detail t
                where t.seq_bakasha = v_seq_bakasha
                and (t.seq_netuney_sachar = r.seq_netuney_sachar or t.seq_netuney_sachar is null)
                and t.code_type_vetek = 6;
    end if;
  
    if is_vetek_colel is null or v_vetek_hatchala_kolel is null then
      build_check_message(1,'0539','0002',31,'',message);
    end if;

    select count(*)
            into is_vetek_zahal
                from vetek_detail t
                where t.seq_bakasha = v_seq_bakasha
                and (t.seq_netuney_sachar = r.seq_netuney_sachar or t.seq_netuney_sachar is null)
                and t.code_type_vetek = 2;
                
    if is_vetek_zahal > 0 then
       select t.years
            into v_vetek_hatchala_zahal
                from vetek_detail t
                where t.seq_bakasha = v_seq_bakasha
                and (t.seq_netuney_sachar = r.seq_netuney_sachar or t.seq_netuney_sachar is null)
                and t.code_type_vetek = 2;
    end if;
    
    if is_vetek_zahal>0 and v_vetek_hatchala_zahal is null then
      build_check_message(1,'0539','0005',32,'');
    end if;
    
    v_times := v_times + 1;
    end loop;
    
    if v_times = 0 then
       build_check_message(1,'0539','0002',31,'');
    end if;
    
    return true;
  end;   
   ------------------------------------  
   -- נתוני גמלה למינוי
   function insert_event_567(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
    v_achuz_gimla number;
    v_times number := 0; --כמה פעמים להפעיל אירוע
    v_code_sug_gimla number;
    v_mispar_zehut_sheer_benzug number :=0;
    v_mispar_misra number := 0;
   
  begin
    for r in (select n.*
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      order by n.mispar_misra)
    loop
      
    v_mispar_misra := r.mispar_misra;
      
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer;
     select nvl(b.achuz_kizba,0) + nvl(b.achuz_tosefet,0) achuz_kizba
         into v_achuz_gimla
         from bney_mishpacha b, poresh p
         where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
         and b.seq_porshim = p.porshim_seq
         and p.mispar_zehut = v_mispar_zehut
         and b.taarich_ptira is null;
    elsif v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan;
      select sum(nvl(b.achuz_kizba,0)) + sum(nvl(b.achuz_tosefet,0)) achuz_kizba
         into v_achuz_gimla
         from bney_mishpacha b
         left join poresh p on
         p.porshim_seq = b.seq_porshim
         where b.code_relative in (2,3) and 
         (b.to_date_sium_zakaut is not null and b.to_date_sium_zakaut > sysdate 
         or b.to_date_sium_zakaut is null)
         and b.taarich_ptira is null
         and p.mispar_zehut = v_mispar_zehut;
    else
         if v_code_sug_bakasha = 7 and 
             not(pk_participation_2_guff.is_overlap_from_guf(v_seq_bakasha) = 1 
             and r.tkufa_overlap_kizba > 0) then
            return true;
         end if;  
         v_achuz_gimla := r.achuz_kizba_sofi;
    end if;
    select t.sug_gimla_hilan
    into v_code_sug_gimla
    from code_seif_prisha t
    where t.code_seif_prisha = v_code_seif_prisha;
    
    ld_log_events_record.code_event := 567;
    ld_log_events_record.code_event_semel := 0;
         
    prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug<>0 then v_mispar_zehut_sheer_benzug  else v_mispar_zehut end,
                        case when v_mispar_misrot_sach_hakol > 1 then 
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                        else 
                                v_gimla_number
                        end,
                        true,
                        v_date_start_zakaut);                                             
      if not insert_event then return false; end if;         
  
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                                --MINUI
             (case when v_date_start_zakaut is null then lpad_zeroez(0,8) else to_char(v_date_start_zakaut,date_format_d8) end) || --TAATICH 
             lpad_zeroez(0,8) ||                                                                                                   --GMARTOKEF
             lpad_zeroez(replace(to_char(nvl(v_achuz_gimla,0),'000.99'),'.',''),5) ||                                              --AHUZ_GIMLA 
             ' ' ||                                                                                                                --KOD_B_PENSIA
             ' ' ||                                                                                                                --KOD_B_HIVUN
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ_HIVUN
             rpad_blanks(' ',8) ||                                                                                                 --HATHALA
             rpad_blanks(' ',8) ||                                                                                                 --SOF
             lpad_zeroez(0,9) ||                                                                                                   --SCHUM_MEKORI                                                                                    --
             case when v_code_sug_gimla is null then ' ' else v_code_sug_gimla end ||                                                                                                   --MUASAK
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL1
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ1
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL2
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ2
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL3
             lpad_zeroez(0,4);                                                                                                     --AHUZ3
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
      if not insert_event then return false; end if;         
      if v_code_sug_bakasha = 7 then return true; end if;
    end loop;
    return true;
    exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_567: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_567: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;   
   ------------------------------------  
   -- נתוני גמלה למינוי
   function check_event_567(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
    v_achuz_gimla number;
    v_times number := 0; --כמה פעמים להפעיל אירוע
    v_code_sug_gimla number;
    v_mispar_zehut_sheer_benzug number :=0;
    v_mispar_misra number;
    
  begin
    for r in (select n.*
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      order by n.mispar_misra)
      --for i in 1 .. v_mispar_misrot_leprisha
    loop
      
    v_mispar_misra := r.mispar_misra;
    
    if v_mistz_almana_benzug_sheer<>0 then
     begin
     v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer;
     select nvl(b.achuz_kizba,0) + nvl(b.achuz_tosefet,0) achuz_kizba
         into v_achuz_gimla
         from bney_mishpacha b
         where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug;
     exception
     when others then
      message := sqlerrm;
      build_check_message(1,'0567','0000',33,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
     end;
    elsif v_mispar_zehut_ben_katan<>0 then
     begin
      v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan;
      select sum(nvl(b.achuz_kizba,0)) + sum(nvl(b.achuz_tosefet,0)) achuz_kizba
         into v_achuz_gimla
         from bney_mishpacha b
         left join poresh p on
         p.porshim_seq = b.seq_porshim
         where b.code_relative in (2,3) and 
         ((b.to_date_sium_zakaut is not null and b.to_date_sium_zakaut > sysdate 
         or b.to_date_sium_zakaut is null) or v_code_sug_bakasha = 19)         
         and b.taarich_ptira is null
         and p.mispar_zehut = v_mispar_zehut;
     exception
     when others then
      message := sqlerrm;
      build_check_message(1,'0567','0000',33,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
     end;
    else
     begin
      select t.achuz_kizba_sofi
           into v_achuz_gimla
                from netuney_tik_mechushavim t
                where t.seq_bakasha = v_seq_bakasha
                and t.code_department = 2                
                /*and t.mispar_misra = v_mispar_misra*/;

     exception
     when others then
      message := sqlerrm;
      build_check_message(1,'0567','0000',33,': ' || to_char(v_mispar_zehut),message);
     end;
    end if;
    
    begin
      select t.sug_gimla_hilan
      into v_code_sug_gimla
      from code_seif_prisha t
      where t.code_seif_prisha = v_code_seif_prisha;
      exception
       when others then
      message := sqlerrm;
      build_check_message(1,'0567','0000',34,'',message);
    end;
    end loop;
    return true;
    end;   
  ------------------------------------  
   -- נתוני גמלה למינוי
   function insert_event_591(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_toar_misra varchar2(100);
   v_code_mikzoa number;
   v_mispar_zehut_sheer_benzug number :=0;
   
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    if v_seq_ezor_ovdim = 206 then
    select c.teur_chinuch_mikzoa, decode(c.code_chinuch_mikzoa,0,910,c.code_chinuch_mikzoa)
           into v_toar_misra, v_code_mikzoa
                from bakasha_regila t, code_chinuch_mikzoa c
                where t.seq_bakasha = v_seq_bakasha
                and t.chinuch_mikzoa = c.code_chinuch_mikzoa;
    
                
    ld_log_events_record.code_event := 591;
    ld_log_events_record.code_event_semel := 0;
           
    prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug<>0 then v_mispar_zehut_sheer_benzug  else v_mispar_zehut end,
                        v_gimla_number,
                        true,
                        v_date_start_zakaut);
                                              
    if insert_event then   
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                                   --MINUI
             lpad_zeroez(v_code_mikzoa,6) ||                                                                                          --HAGDARA
             rpad_blanks(v_toar_misra,25) ||                                                                                          --TOAR_MISRA
             (case when v_date_start_zakaut is null then lpad_zeroez(0,8) else to_char(v_date_start_zakaut,date_format_d8) end) ||    --TAARICH
             lpad_zeroez(0,8);                                                                                                        --GMARTOKEF
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
      return insert_event;
      else
        return false;
     end if;
    else
      return true;
    end if;
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_591: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_591: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;
  ------------------------------------  
   -- נתוני גמלה למינוי
   function check_event_591(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_toar_misra varchar2(100);
   v_code_mikzoa number;
   v_mispar_zehut_sheer_benzug number :=0;
   
    begin  
    if v_seq_ezor_ovdim = 206 then
    begin
    select c.teur_chinuch_mikzoa, decode(c.code_chinuch_mikzoa,0,910,c.code_chinuch_mikzoa)
           into v_toar_misra, v_code_mikzoa
                from bakasha_regila t, code_chinuch_mikzoa c
                where t.seq_bakasha = v_seq_bakasha
                and t.chinuch_mikzoa = c.code_chinuch_mikzoa;
    exception
      when others then
      message := sqlerrm;
      build_check_message(2,'0591','0000',35,'',message);
   end;
    end if;    
       return true;
    end;
  ------------------------------------  
  --מעמד למינוי 
  function insert_event_538(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
                          
    v_mispar_zehut_sheer_benzug number :=0;
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    ld_log_events_record.code_event := 538;
    ld_log_events_record.code_event_semel := 0;
  
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug else v_mispar_zehut end,
                        v_gimla_number,
                        true,
                        v_hp_date_haavara);                      
      if insert_event then   
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                --MINUI
             '03' ||                                                                                               --MAAMAD
             to_char(v_hp_date_haavara,date_format_d8) ||                                                          --TAARICH                                                                                      
             lpad_zeroez(0,8);                                                                                     --GMARTOKEF           
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
             return insert_event;
       else
         return false;
       end if;
    exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_538: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_538: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;  
   ------------------------------------
   -- מרכיבי שכר אישיים למינוי 
   function insert_event_527_sachar(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number,
                          v_code_hishuv number,
                          v_mispar_misra_last number default 0
                          ) return boolean is
   
   v_yamei_havraa number;                          --234 V
   v_zakaut_le_maanak_prisha number;               --242 V
   v_zakaut_lemaanak_yovel number;                 --235 V
   v_maskoret_kovaat_lepitzuim float;              --280 V
   v_zakaut_lehistakrut number;                    --261 V
   v_zakaut_legimlaot_kefel number;                --260 V
   v_maskoret_legil_60 float;                      --244 V 
   v_date_start_zakaut_histakrut date;  
   v_date_start_gimlaot_kefel date;
   v_achuz_kefel float;         
   v_date_end_zakaut   date := null;
   v_schum float := 0;
   v_min_poresh number;
   v_min_benzug number;
   v_hp_code_chayav_retro number;
   v_mispar_zehut_sheer_benzug number := 0 ;
   v_mispar_misra number := 0;   
   
   v_teur_ezor_ovdim varchar2(50);                        
  
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    
      ld_log_events_record.code_event := 527;
      ld_log_events_record.code_event_semel := v_semel_hilan;
      
    --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 
       
     for r in (select n.seq_netuney_sachar, n.mispar_misra
      from netuney_sachar n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_sug_maskoret = 
          (case when v_semel_hilan = '0244' then 2 else 1 end)
      --and (v_mispar_misra_last = 0 or v_mispar_misra_last<>0 and n.mispar_misra = v_mispar_misra_last - 1)
      union
      select 0 seq_netuney_sachar, 0 mispar_misra from dual
      where v_code_sug_bakasha in (17,18,12) or v_code_sug_bakasha in (1,5) and v_semel_hilan = '0260' --גמלאות כפל או השתכרות
      order by mispar_misra) loop
      
      v_mispar_misra := r.mispar_misra;
      
      /*if v_mispar_misra_last <>0  then
        v_mispar_misra := v_mispar_misra_last - 1;
      else
        v_mispar_misra := r.mispar_misra;
      end if;*/
    
       if v_semel_hilan in ('0260','3036') then -- זכאות שכר קובע ממקור נוסף (גמלאות כפל)
         select kefel.date_payment, kefel.percent_participate
         into v_date_start_gimlaot_kefel, v_achuz_kefel
         from (select t.date_payment,t.percent_participate
                 from participation t
                 where t.seq_bakasha = v_seq_bakasha
                 and t.code_participation = 6
                 order by t.date_payment)kefel
         where rownum = 1;             
         if v_date_start_gimlaot_kefel is null then
          if v_code_sug_bakasha = 18 then
             clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
              'לא נשלח: לא מוגדר תאריך זכאות לגמלאות כפל') ||  '<br />';
             return false;
          else 
             return true;
          end if;
        else 
          v_zakaut_legimlaot_kefel := 1;
        end if;
      elsif v_semel_hilan in ('0261','0284') then -- להשתכרות
        if v_code_sug_bakasha = 17 then
          v_zakaut_lehistakrut := 1;
          select  case when v_semel_hilan = '0261' then 0 else t.sum end,
          t.from_date, t.to_date
          into v_schum, v_date_start_zakaut_histakrut, v_date_end_zakaut
          from hachnasot t
          where t.seq_bakasha = v_seq_bakasha;
        if v_date_start_zakaut_histakrut is null then
             clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
              'לא נשלח: לא מוגדר תאריך זכאות להשתכרות') ||  '<br />';
             return false; 
        end if;
        else return true;
        end if;
      elsif v_semel_hilan in ('0244') then -- משכורת לגיל 60
          select t.maskoret_kovaat                         
          into v_maskoret_legil_60        
          from netuney_sachar t
          where t.seq_bakasha = v_seq_bakasha        
          and t.seq_netuney_sachar =  r.seq_netuney_sachar
          and t.code_sug_maskoret = 2;
          v_schum := v_maskoret_legil_60;   
      elsif v_semel_hilan = '0630' then --חיסכון פנסיוני
        if v_code_sug_bakasha = 12 then
          select t.hp_code_chayav_retro
          into v_hp_code_chayav_retro
          from bakasha_regila t
          where t.seq_bakasha = v_seq_bakasha;
          select t.code_min
          into v_min_poresh
          from poresh t
          where t.mispar_zehut = v_mispar_zehut;
          select t.code_min
          into v_min_benzug
          from bney_mishpacha t
          where t.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
          and t.code_kirva = 10;
         else return true;
        end if;
        if v_hp_code_chayav_retro = 2 then   --שיעור חישוב הפחטה
          if v_min_benzug = 1
            then v_schum := 1.2;
          else 
            v_schum := 2.8;
          end if;
       elsif v_hp_code_chayav_retro = 1 then
          if v_min_poresh = 1
            then v_schum := 1.2;
          else 
            v_schum := 2.8;
          end if;
       elsif v_hp_code_chayav_retro = 3 then
            v_schum := 2.8;
       else v_schum := 0;
       end if;
        if v_schum = 0 then return true; end if;
      else        
         select t.havraa_days,
               /*t.sum_havraa,
               t.bigud,*/
               t.is_maanak_yovel,
               t.kovaat_161            
        into v_yamei_havraa,
             /*v_schum_leyom,
             v_kzuvat_bigud,*/
             v_zakaut_lemaanak_yovel,
             v_maskoret_kovaat_lepitzuim            
        from netuney_sachar t
        where t.seq_bakasha = v_seq_bakasha        
        and (t.seq_netuney_sachar =  r.seq_netuney_sachar and t.code_sug_maskoret = 1
        or t.seq_netuney_sachar is null);
        
     if      v_semel_hilan = '0234' then                               --ימי הבראה)
             v_schum := v_yamei_havraa;
             if v_schum = 0 or v_schum is null then continue; end if;
             --v_code_hishuv := 4;       
     elsif   v_semel_hilan = '0235' then                               --זכאות למענק יובל
          if v_zakaut_lemaanak_yovel <> 1 then
             continue;
          end if;
     elsif   v_semel_hilan = '0280' then                               --משכורת אחרונה לפיצויים
             v_schum := v_maskoret_kovaat_lepitzuim;
             --v_code_hishuv := 0;
     elsif v_semel_hilan = '0000' and v_code_sug_bakasha in (1,14) /*or (v_code_sug_bakasha = 13 and v_ptira_besherut_gimlat_chesed)*/ then
     for r1 in 
            (select c.semel_hilan, c.code_event_hilan, t.seq_tosefot
            from netuney_sachar s, tosefot t, code_semel_tosefet c
            where s.seq_bakasha = v_seq_bakasha
            and s.mispar_misra = v_mispar_misra
            and s.seq_netuney_sachar = r.seq_netuney_sachar
            and s.seq_netuney_sachar = t.seq_netuney_sachar
            and t.code_semel_tosefet = c.code_semel_tosefet
            and s.code_sug_maskoret = 1
            and c.semel_hilan <> 99999 --תוספת לא ידועה
            )     
     loop
     begin
             v_seq_tosefot := r1.seq_tosefot;
             insert_or_check_event_dynamic(309,
                                  lpad_zeroez(to_char(r1.semel_hilan),4),
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mistz_almana_benzug_sheer,
                                  v_mispar_zehut_ben_katan,
                                  v_code_seif_prisha,
                                  0,
                                  v_mispar_misra);  
             if not if_commit then return false; end if;
     end;
     end loop;
     end if;
     end if;
     if v_semel_hilan = '0000' then continue; end if;
     prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug = 0 or
                                (v_mispar_zehut_sheer_benzug<>0 and v_code_sug_bakasha = 12 and v_semel_hilan = '0630') then
                                v_mispar_zehut
                             else
                                v_mispar_zehut_sheer_benzug end,
                        case when v_mispar_misrot_sach_hakol > 1 then
                        case when v_mispar_zehut_sheer_benzug<>0 and v_code_sug_bakasha = 12 and v_semel_hilan = '0630' then                              
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
                               else
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                               end
                        else 
                        case when v_mispar_zehut_sheer_benzug<>0 and v_code_sug_bakasha = 12 and v_semel_hilan = '0630' then
                                v_gimla_number
                             else
                                v_gimla_number 
                             end
                        end,                            
                        true,
                        case when v_code_sug_bakasha = 12 then v_hp_date_haavara 
                             when v_code_sug_bakasha = 17 then to_date(to_char(v_date_start_zakaut_histakrut,date_format_d6) || '01', date_format_d8)
                             when v_code_sug_bakasha = 18 or v_code_sug_bakasha in (1,5) and v_semel_hilan = '0260'
                                then to_date(to_char(v_date_start_gimlaot_kefel,date_format_d6) || '01', date_format_d8)
                             else v_date_start_zakaut end);
                                                
     if not insert_event then return false; end if;  
        
     ld_log_events_record.code_trigger := 2;
     ld_log_events_record.record_hilan := 
     '0' ||        
     case when v_code_sug_bakasha = 12 then to_char(v_hp_date_haavara,date_format_d8) 
          when v_code_sug_bakasha = 17 then to_char(v_date_start_zakaut_histakrut,date_format_d6) || '01'
           when v_code_sug_bakasha = 18 or v_code_sug_bakasha in (1,5) and v_semel_hilan = '0260' 
             then to_char(v_date_start_gimlaot_kefel,date_format_d6) || '01'                  
          else to_char(v_date_start_zakaut, date_format_d8) end ||                                                            --TAARICH
     (case when v_date_end_zakaut is null then lpad_zeroez(0,8) else to_char(v_date_end_zakaut,date_format_d8) end) ||       --GMARTOKEF
     lpad_zeroez(v_code_hishuv,1) ||                                                                                         --KODISHI
     ' ' ||                                                                                                                  --מינוס
     lpad_zeroez(replace(to_char(nvl(v_schum,0),'0000000.99'),'.',''),9) ||                                                  --SUM 
     lpad_zeroez(0,3);                                                                                                       --TAARIF
     --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
     if not insert_event then return false; end if;     
     end loop;
     return true;
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_527_sachar: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_527_sachar: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;
   ------------------------------------
   -- מרכיבי שכר אישיים למינוי 
   function check_event_527_sachar(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number,
                          v_code_hishuv number,
                          v_mispar_misra_last number default 0
                          ) return boolean is
   
   v_zakaut_le_maanak_prisha number;               --242
   v_yamei_havraa number;                          --234 V
   v_zakaut_lemaanak_yovel number;                 --235 V
   v_maskoret_kovaat_lepitzuim float;              --280 V
   v_zakaut_lehistakrut number;                    --261 V
   v_zakaut_legimlaot_kefel number;                --260 V
   v_maskoret_legil_60 float;                      --244 V 
   v_achuz_kizva_zfuya_legil_60_59 float;          --239
   v_date_start_zakaut_histakrut date;  
   v_date_start_gimlaot_kefel date;          
   v_date_end_zakaut   date := null;
   v_schum float := 0;
   v_min_poresh number;
   v_min_benzug number;
   v_hp_code_chayav_retro number;
   v_mispar_zehut_sheer_benzug number := 0 ;
   v_mispar_misra number := 0;     
   v_teur_ezor_ovdim varchar2(50);
   v_times number := 0;
   
    begin
   
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    
    --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    --if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 
       
     for r in (select n.seq_netuney_sachar, n.mispar_misra
      from netuney_sachar n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_sug_maskoret = 
          (case when v_semel_hilan = '0244' then 2 else 1 end)
      --and (v_mispar_misra_last = 0 or v_mispar_misra_last<>0 and n.mispar_misra = v_mispar_misra_last - 1)
      union
      select 0 seq_netuney_sachar, 0 mispar_misra from dual
      where v_code_sug_bakasha in (17,18,12) or v_code_sug_bakasha in (1,5) and v_semel_hilan = '0260' --גמלאות כפל או השתכרות
      order by mispar_misra) loop
      
      v_times := v_times + 1;
      
      /*if v_mispar_misra_last <>0  then
        v_mispar_misra := v_mispar_misra_last - 1;
      else
        v_mispar_misra := r.mispar_misra;
      end if;*/
    
       if v_semel_hilan = '0260' then -- זכאות שכר קובע ממקור נוסף (גמלאות כפל)
         begin
         select min(t.date_payment)
                 into v_date_start_gimlaot_kefel
                 from participation t
                 where t.seq_bakasha = v_seq_bakasha
                 and t.code_participation = 6;             
         if v_date_start_gimlaot_kefel is null then
          if v_code_sug_bakasha = 18 then
             build_check_message(1,'0527','0260',36,'') ;
          end if;
         else 
             v_zakaut_legimlaot_kefel := 1;
         end if;
         exception
         when others then
         message := sqlerrm;
         check_message := check_message || ' event_527; semel_260 - ' || message ||  '<br />';
         end;
      elsif v_semel_hilan in ('0261','0284') then -- להשתכרות
        begin
        if v_code_sug_bakasha = 17 then
          v_zakaut_lehistakrut := 1;
          select  case when v_semel_hilan = '0261' then 0 else t.sum end,
          t.from_date, t.to_date
          into v_schum, v_date_start_zakaut_histakrut, v_date_end_zakaut
          from hachnasot t
          where t.seq_bakasha = v_seq_bakasha;
          if v_date_start_zakaut_histakrut is null then
             build_check_message(1,'0527',v_semel_hilan,37,'') ;
          end if;
        end if;
        exception
        when others then
        message := sqlerrm;
        build_check_message(1,'0527',v_semel_hilan,37,'',message) ;
        end;
      elsif v_semel_hilan in ('0244') then -- משכורת לגיל 60
        select t.is_zakai_lmaanak,
               t.achuz_kizba_gil_60           
        into v_zakaut_le_maanak_prisha,
             v_achuz_kizva_zfuya_legil_60_59             
        from netuney_tik_mechushavim t
        where t.seq_bakasha = v_seq_bakasha
        and t.code_department = 2
        /*and t.mispar_misra = v_mispar_misra*/;
        if   v_zakaut_le_maanak_prisha = 1 and v_achuz_kizva_zfuya_legil_60_59 is not null then         
        begin
          select t.maskoret_kovaat                         
          into v_maskoret_legil_60        
          from netuney_sachar t
          where t.seq_bakasha = v_seq_bakasha        
          and t.seq_netuney_sachar =  r.seq_netuney_sachar
          and t.code_sug_maskoret = 2;
          v_schum := v_maskoret_legil_60; 
        exception
          when others then
          message := sqlerrm;
          build_check_message(2,'0527','0244',38,'',message) ;
        end;
          if v_maskoret_legil_60 is null then
          build_check_message(2,'0527','0244',38,'') ;
          end if;                                                  
        end if;
        elsif v_semel_hilan = '0630' then --חיסכון פנסיוני
        if v_code_sug_bakasha = 12 then
          begin
          select t.hp_code_chayav_retro
          into v_hp_code_chayav_retro
          from bakasha_regila t
          where t.seq_bakasha = v_seq_bakasha;
          exception
          when others then
          message := sqlerrm;
          build_check_message(1,'0527','0630',6,'',message) ;
          end; 
          begin
          select t.code_min
          into v_min_poresh
          from poresh t
          where t.mispar_zehut = v_mispar_zehut;
          select t.code_min
          into v_min_benzug
          from bney_mishpacha t
          where t.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
          and t.code_kirva = 10;
          exception
          when others then
          message := sqlerrm;
          build_check_message(1,'0527','0630',9,'',message) ;
          end;
          if v_min_poresh is null then
          build_check_message(1,'0527','0630',39,'') ;
          end if;           
        else return true;
        end if;
        if v_hp_code_chayav_retro = 2 then   --שיעור חישוב הפחטה
          if v_min_benzug = 1
            then v_schum := 1.2;
          else 
            v_schum := 2.8;
          end if;
        elsif v_hp_code_chayav_retro = 1 then
          if v_min_poresh = 1
            then v_schum := 1.2;
          else 
            v_schum := 2.8;
          end if;
       elsif v_hp_code_chayav_retro = 3 then
            v_schum := 2.8;
       else v_schum := 0;
       end if;
        --if v_schum = 0 then return true; end if;
    else
        begin      
        select t.havraa_days,
               /*t.sum_havraa,
               t.bigud,*/
               t.is_maanak_yovel,
               t.kovaat_161            
        into v_yamei_havraa,
             /*v_schum_leyom,
             v_kzuvat_bigud,*/
             v_zakaut_lemaanak_yovel,
             v_maskoret_kovaat_lepitzuim            
        from netuney_sachar t
        where t.seq_bakasha = v_seq_bakasha        
        and (t.seq_netuney_sachar =  r.seq_netuney_sachar and t.code_sug_maskoret = 1
        or t.seq_netuney_sachar is null);
          exception
          when others then
          message := sqlerrm;
          build_check_message(1,'0527','0630',40,'',message) ;
        end;      
        if v_semel_hilan = '0234' then                               --ימי הבראה)
             v_schum := v_yamei_havraa;
             if v_schum is null  then
             build_check_message(1,'0527','0630',41,'') ;
             end if;
            --v_code_hishuv := 4;       
     elsif   v_semel_hilan = '0235' then                               --זכאות למענק יובל
             if v_zakaut_lemaanak_yovel is null  then
             build_check_message(1,'0527','0630',42,'') ;
             end if;
     elsif   v_semel_hilan = '0280' then                               --משכורת אחרונה לפיצויים
             v_schum := v_maskoret_kovaat_lepitzuim;
             if v_schum is null  then
             build_check_message(1,'0527','0630',43,'') ;
             end if;
            --v_code_hishuv := 0;
     elsif v_semel_hilan = '0000' and v_code_sug_bakasha in (1,14) /*or (v_code_sug_bakasha = 13 and v_ptira_besherut_gimlat_chesed)*/ then
     for r1 in 
            (select c.semel_hilan, c.code_event_hilan
            from netuney_sachar s, tosefot t, code_semel_tosefet c
            where s.seq_bakasha = v_seq_bakasha
            and s.seq_netuney_sachar = r.seq_netuney_sachar
            and s.seq_netuney_sachar = t.seq_netuney_sachar
            and t.code_semel_tosefet = c.code_semel_tosefet
            and s.code_sug_maskoret = 1
            )     
     loop
     begin
             insert_or_check_event_dynamic(309,
                                  lpad_zeroez(to_char(r1.semel_hilan),4),
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mistz_almana_benzug_sheer,
                                  v_mispar_zehut_ben_katan,
                                  v_code_seif_prisha,
                                  0,
                                  v_mispar_misra);  
             if not if_commit then return false; end if;
     end;
     end loop;
     end if;
     end if;
     end loop;
     if v_times = 0 then
        build_check_message(1,'0527',v_semel_hilan,40,'') ;
     end if;
     return true;
    end;
   ------------------------------------
   --  זכאויות למינוי  
   function insert_event_527_zakaut(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number,
                          v_code_hishuv number,
                          v_mispar_misra_last number default 0
                          ) return boolean is
   
   v_hodashim_mezakim_be_maanak_prisha number;     --243 V
   v_zakaut_le_maanak_prisha number;               --242 V
   v_zakaut_leshanim_odfot number;                 --240 V
   v_achuz_kizva_zfuya_legil_60_59 float;          --239 V
   v_hodashim_odfim number;                        --241 V
   v_yamei_havraa number;                          --234 V
   v_zakaut_lemaanak_yovel number;                 --235 V
   v_maskoret_kovaat_lepitzuim float;              --280 V
   v_prisha_lefi_seif_57_62 number;                --250
   v_zakaut_lemaanak_nisuin_1 number;              --245
   v_zakaut_lemaanak_nisuin_2 number;              --246
   v_bitul_maanak number;                          --247
   v_zakaut_lemaanak_had_paami_1 number;           --248
   v_zakaut_lemaanak_had_paami_2 number;           --249
   v_date_end_zakaut date := null;
   v_is_salary_up_70 number;
   v_schum float := 0;
   v_min_poresh number;
   v_min_benzug number;
   v_hp_code_chayav_retro number;
   v_mispar_zehut_sheer_benzug number := 0 ;
   v_mispar_misra number := 0;   
   
   v_teur_ezor_ovdim varchar2(50);                        
  
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;

    for r in (select n.*
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      order by n.mispar_misra)
      --for i in 1 .. v_mispar_misrot_leprisha
    loop
      
    if v_code_sug_bakasha = 7 and r.is_salary_up_70 <> 1 then return true; end if;
      
    v_mispar_misra := r.mispar_misra;
   
      ld_log_events_record.code_event := 527;
      ld_log_events_record.code_event_semel := v_semel_hilan;
      
    --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    --if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 
       v_hodashim_mezakim_be_maanak_prisha := r.tkufa_mezaka_sherut;
       v_zakaut_le_maanak_prisha := r.is_zakai_lmaanak;
       v_zakaut_leshanim_odfot := case when  r.odef_sherut_chodashim>0 or r.odef_sherut_yamim>0 
                 then 1 
                 else 0 end;
       v_hodashim_odfim := r.odef_sherut_chodashim + r.odef_sherut_yamim / (30.41);
       v_achuz_kizva_zfuya_legil_60_59 := r.achuz_kizba_gil_60;       
     
 /*      select t.tkufa_mezaka_sherut,
               t.is_zakai_lmaanak,
               case when  t.odef_sherut_chodashim>0 or t.odef_sherut_yamim>0 
                 then 1 
                 else 0 end as is_zakai_lmaanak_shanim_odfot,
               t.odef_sherut_chodashim + t.odef_sherut_yamim / (30.41) odef_sherut_chodashim_esroni,
               t.achuz_kizba_gil_60           
        into v_hodashim_mezakim_be_maanak_prisha,
             v_zakaut_le_maanak_prisha,
             v_zakaut_leshanim_odfot,
             v_hodashim_odfim,
             v_achuz_kizva_zfuya_legil_60_59             
        from netuney_tik_mechushavim t
        where t.seq_bakasha = v_seq_bakasha
        and t.code_department = 2
        and t.mispar_misra = v_mispar_misra;*/
        
/*        select t.teur_ezor_ovdim
        into v_teur_ezor_ovdim
        from code_ezor_ovdim t
        where t.seq_ezor_ovdim = v_seq_ezor_ovdim
        and t.pail = 1;
        if instr(v_teur_ezor_ovdim,'רוה"מ')  
          > 0  then v_zakaut_le_maanak_prisha := 0;         --רוה"מ ת"א לא יועבר לחילן זכאות למענק פרישה.
        end if;                                             --(גם אם יש להם זכאות) כי המשרד משלם את המענק
                                                            --בעצמו.*/
                                                            
     if   v_semel_hilan = '0243' then                               --חודשים מזכים במענק פרישה
         if v_zakaut_le_maanak_prisha = 1 then
             v_schum := v_hodashim_mezakim_be_maanak_prisha;
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             --v_code_hishuv := 4;
         else
             --continue;
             return true;
         end if; 
     elsif  v_semel_hilan = '0242' then                                --זכאות למענק פרישה
          if v_zakaut_le_maanak_prisha = 1 then
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             --v_code_hishuv := 1;
          else
             --continue;
             return true;
          end if;
     elsif  v_semel_hilan = '0239' then                               --קצבה צפויה לגיל 60/59 
          /*begin
          select n1.achuz_kizba_gil_60
          into v_achuz_kizva_zfuya_legil_60_59
          from netuney_tik_mechushavim n1
          where n1.seq_bakasha = v_seq_bakasha
          and n1.code_department = 2
          \*and n1.mispar_misra = v_mispar_misra*\;
          exception
               when no_data_found then
               v_achuz_kizva_zfuya_legil_60_59 := null;
          end;*/ 
           if v_zakaut_le_maanak_prisha = 1 then
            if not v_achuz_kizva_zfuya_legil_60_59 is null and  
                   v_achuz_kizva_zfuya_legil_60_59 <> 0 then
             v_schum := v_achuz_kizva_zfuya_legil_60_59;
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             --v_code_hishuv := 0;
            else
             --continue;
             return true;
            end if;
          else
              --continue;
             return true;
          end if; 
     elsif  v_semel_hilan = '0240' then                               --זכאות למענק שנים עודפות
          if v_zakaut_leshanim_odfot = 1 then
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             --v_code_hishuv := 1;
          else
              --continue;
             return true;
          end if;
     elsif  v_semel_hilan = '0241' then                               --חודשים עודפים
          if v_zakaut_leshanim_odfot = 1 then
             v_schum := v_hodashim_odfim;
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             --v_code_hishuv := 4;
          else
             --continue;
             return true;
          end if;
     end if;
     prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug=0 or
                               (v_mispar_zehut_sheer_benzug<>0 and v_code_sug_bakasha = 12 and v_semel_hilan = '0630') then
                                v_mispar_zehut
                        else
                               v_mispar_zehut_sheer_benzug end,
                        case when v_mispar_misrot_sach_hakol > 1 then 
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                        else 
                               v_gimla_number
                        end,                            
                        true,
                        case when v_code_sug_bakasha = 12 then v_hp_date_haavara 
                             else v_date_start_zakaut end);
                                                
     if not insert_event then return false; end if;  
        
     ld_log_events_record.code_trigger := 2;
     ld_log_events_record.record_hilan := 
     '0' ||        
     case when v_code_sug_bakasha = 12 then to_char(v_hp_date_haavara,date_format_d8) 
          else to_char(v_date_start_zakaut, date_format_d8) end ||                                                            --TAARICH
     (case when v_date_end_zakaut is null then lpad_zeroez(0,8) else to_char(v_date_end_zakaut,date_format_d8) end) ||       --GMARTOKEF
     lpad_zeroez(v_code_hishuv,1) ||                                                                                         --KODISHI
     ' ' ||                                                                                                                  --מינוס
     lpad_zeroez(replace(to_char(nvl(v_schum,0),'0000000.99'),'.',''),9) ||                                                  --SUM 
     lpad_zeroez(0,3);                                                                                                       --TAARIF
     --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
     if not insert_event then return false; end if;     
     end loop;
     return true;
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_527_zakaut: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_527_zakaut: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
      return false;
    end;
  ------------------------------------  
  --הוראות קבע 
  --  זכאויות למינוי  
   function check_event_527_zakaut(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number,
                          v_code_hishuv number,
                          v_mispar_misra_last number default 0
                          ) return boolean is
   
   v_hodashim_mezakim_be_maanak_prisha number;     --243 V
   v_zakaut_le_maanak_prisha number;               --242 V
   v_zakaut_leshanim_odfot number;                 --240 V
   v_achuz_kizva_zfuya_legil_60_59 float;          --239 V
   v_hodashim_odfim number;                        --241 V
   v_yamei_havraa number;                          --234 V
   v_zakaut_lemaanak_yovel number;                 --235 V
   v_maskoret_kovaat_lepitzuim float;              --280 V
   v_prisha_lefi_seif_57_62 number;                --250
   v_zakaut_lemaanak_nisuin_1 date;              --245
   v_zakaut_lemaanak_nisuin_2 date;              --246
   v_bitul_maanak number;                          --247
   v_zakaut_lemaanak_had_paami_1 number;           --248
   v_zakaut_lemaanak_had_paami_2 number;           --249
   v_date_end_zakaut date := null;
   v_schum float := 0;
   v_min_poresh number;
   v_min_benzug number;
   v_hp_code_chayav_retro number;
   v_mispar_zehut_sheer_benzug number := 0 ;
   v_mispar_misra number := null;   
   
   v_teur_ezor_ovdim varchar2(50);                        
  
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
         
    --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    --if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 
       
    for r in (select n.*
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      order by n.mispar_misra)
      --for i in 1 .. v_mispar_misrot_leprisha
    loop
      
    v_mispar_misra := r.mispar_misra;
       
      begin
      select t.tkufa_mezaka_sherut,
               t.is_zakai_lmaanak,
               case when  t.odef_sherut_chodashim>0 or t.odef_sherut_yamim>0 
                 then 1 
                 else 0 end as is_zakai_lmaanak_shanim_odfot,
               t.odef_sherut_chodashim + t.odef_sherut_yamim / (30.41) odef_sherut_chodashim_esroni,
               t.achuz_kizba_gil_60,
               t.is_maanak_nisuin1,
               t.is_maanak_nisuin2
        into v_hodashim_mezakim_be_maanak_prisha,
             v_zakaut_le_maanak_prisha,
             v_zakaut_leshanim_odfot,
             v_hodashim_odfim,
             v_achuz_kizva_zfuya_legil_60_59,
             v_zakaut_lemaanak_nisuin_1,
             v_zakaut_lemaanak_nisuin_2            
        from netuney_tik_mechushavim t
        where t.seq_bakasha = v_seq_bakasha
        and t.code_department = 2
        /*and t.mispar_misra = v_mispar_misra*/;
       exception
         when others then
         message := sqlerrm;
         build_check_message(1,'0527',v_semel_hilan,4,'',message) ;
       end;
         
      begin
        select t.teur_ezor_ovdim
        into v_teur_ezor_ovdim
        from code_ezor_ovdim t
        where t.seq_ezor_ovdim = v_seq_ezor_ovdim
        and t.pail = 1;
        if instr(v_teur_ezor_ovdim,'רוה"מ') 
          > 0  then v_zakaut_le_maanak_prisha := 0;         --רוה"מ ת"א לא יועבר לחילן זכאות למענק פרישה.
        end if;                                             --(גם אם יש להם זכאות) כי המשרד משלם את המענק
                                                            --בעצמו
      exception
         when others then
         message := sqlerrm;
         build_check_message(1,'0527',v_semel_hilan,1,'',message) ;
     end;
 
     if   v_semel_hilan = '0243' then                               --חודשים מזכים במענק פרישה
         if v_zakaut_le_maanak_prisha = 1 then
             v_schum := v_hodashim_mezakim_be_maanak_prisha;
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             if v_schum is null  then
              check_message := check_message || ' event_527; semel_243' ||  '<br />';
             end if;
            --v_code_hishuv := 4;
         end if; 
         if v_zakaut_le_maanak_prisha =1 and v_hodashim_mezakim_be_maanak_prisha is null then
          build_check_message(1,'0527','0243',43,'') ;
         end if;
     elsif  v_semel_hilan = '0242' then                                --זכאות למענק פרישה
          if v_zakaut_le_maanak_prisha = 1 then
             v_date_end_zakaut := last_day(v_date_start_zakaut);
          end if;
     elsif  v_semel_hilan = '0244' then                               --קצבה צפויה לגיל 60/59 
          begin
          select n1.achuz_kizba_gil_60
          into v_achuz_kizva_zfuya_legil_60_59
          from netuney_tik_mechushavim n1
          where n1.seq_bakasha = v_seq_bakasha
          and n1.code_department = 2
          /*and n1.mispar_misra = v_mispar_misra*/;
          exception
               when no_data_found then
               v_achuz_kizva_zfuya_legil_60_59 := null;
          end;                       
          if v_zakaut_le_maanak_prisha = 1 then
            if not v_achuz_kizva_zfuya_legil_60_59 is null then
             v_schum := v_achuz_kizva_zfuya_legil_60_59;
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             if v_schum is null then
              check_message := check_message || ' event_527; semel_244' ||  '<br />';
             end if;
            end if;
          end if;       
     elsif  v_semel_hilan = '0240' then                               --זכאות למענק שנים עודפות
          if v_zakaut_leshanim_odfot = 1 then
             v_date_end_zakaut := last_day(v_date_start_zakaut);
          end if;
     elsif  v_semel_hilan = '0241' then                               --חודשים עודפים
          if v_zakaut_leshanim_odfot = 1 then
             v_schum := v_hodashim_odfim;
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             if v_schum is null  then
              check_message := check_message || ' event_527; semel_241' ||  '<br />';
             end if;
          end if;
          if v_zakaut_leshanim_odfot = 1 and v_hodashim_odfim is null then
             build_check_message(1,'0527','0241',44,'') ;
          end if;
     end if;
    end loop;
    if v_mispar_misra is null then
       build_check_message(1,'0527','0241',4,'') ;
    end if;
    return true;
   exception
   when others then
    build_check_message(1,'0527','0241',4,'') ;
    return true;
    end;
  ------------------------------------  
    function insert_event_413(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
    v_schum float;                             --תוספות
    --v_amount float;                          --תוספות
    v_achuz float;
    v_code_ezor_ovdim number;
    v_is_keren number;
    v_seif_takzivi varchar2(6);
    is_first boolean := true;
 
    v_mispar_zehut_sheer_benzug number :=0;
    
    v_date_payment date;
    v_date_end date;
    v_achuz_mimaskoret_kovaat_leeynam_kranot float;           --287
    v_achuz_maskoret_kovaat_lekranot float;                   --288
    v_hishtatfut_beschum_lekranot float;                      --284
    v_hishtatfut_beschum_leeynam_kranot float;                --291
    v_hishtatfut_beschum_letkufa_arait float;                 --292
    v_hishtatfut_beschum_heskem_meyuhad float;                --293
    v_tosefet_actuarit float;                                 --296
    v_tosefet_dchiat float;                                   --298
    v_part_code_seif_prisha number;
    
    begin     
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;

    for r in (select distinct t.*
                from participation t
                where t.seq_bakasha = v_seq_bakasha
                ) loop
    begin 
    v_achuz_mimaskoret_kovaat_leeynam_kranot := null;
    v_achuz_maskoret_kovaat_lekranot := null;
    v_hishtatfut_beschum_lekranot := null;
    v_hishtatfut_beschum_leeynam_kranot := null;
    v_hishtatfut_beschum_letkufa_arait := null;
    v_hishtatfut_beschum_heskem_meyuhad := null;
    v_tosefet_actuarit := null;
    v_tosefet_dchiat := null;
    


    select  nvl(c.code_ezor_ovdim_hilan,0), decode(c.code_sug_ezor_ovdim,5,1,0) is_keren
    into v_code_ezor_ovdim, v_is_keren
    from code_ezor_ovdim c
    where c.seq_ezor_ovdim = r.seq_guf;
    
    if v_code_ezor_ovdim = 0 then
           if is_check_running = 0 then
               clob_log := clob_log || v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
               'אין קוד גוף בחילן שתואם לקוד מפם' || ' ' || 
               r.seq_guf || '<br />';
            return false;
            else
              check_message_error := 'אין קוד גוף בחילן שתואם לקוד מפם' || ' ' || 
               r.seq_guf || chr_10;
              check_message_error_short := check_message_error;
              check_count_error := check_count_error + 1;
            end if;
            return false;
    end if;
     
    begin
    select p.sum_participation
    into v_hishtatfut_beschum_heskem_meyuhad
    from bakasha_regila t, participation p
    where t.code_seif_prisha = 415
    and t.code_sub_seif_prisha = 990
    and t.seq_bakasha = v_seq_bakasha
    and t.seq_bakasha = p.seq_bakasha
    and p.seq_guf = r.seq_guf;
    exception
    when no_data_found then
      v_hishtatfut_beschum_heskem_meyuhad := null;
    end;

    begin
      select v.code_seif_prisha
      into v_part_code_seif_prisha
      from v_bakasha_last_status v
      where v.seq_bakasha = v_seq_bakasha;
    end;


    if v_is_keren = 1 then
       select t.date_payment,
       t.date_end,
       --t.percent_participate,
       t.achuz_guf_final,
       case when not v_hishtatfut_beschum_heskem_meyuhad is null then null 
            when v_part_code_seif_prisha <> 215 then t.sum_participation
            else 0 end,
       case when seq_guf = 8 then t.tosefet_actuarit else null end, -- 8 - קרן גלעד
       case when seq_guf = 8 then t.tosefet_dchiat else null end,
       case when v_part_code_seif_prisha <> 215 then t.sum_arai else
            nvl(t.sum_participation,0) + nvl(t.sum_arai,0) end
       into v_date_payment, v_date_end,
            v_achuz_maskoret_kovaat_lekranot,
            v_hishtatfut_beschum_lekranot,
            v_tosefet_actuarit,
            v_tosefet_dchiat,
            v_hishtatfut_beschum_letkufa_arait
       from participation t
       where t.seq_bakasha = v_seq_bakasha
       and t.seq_guf = r.seq_guf;
     else
       select t.date_payment,t.date_end,
       --t.percent_participate,
       t.achuz_guf_final,
       case when not v_hishtatfut_beschum_heskem_meyuhad is null then null 
            when v_part_code_seif_prisha <> 215 then t.sum_participation
            else 0 end,
       case when v_part_code_seif_prisha <> 215 then t.sum_arai else
            nvl(t.sum_participation,0) + nvl(t.sum_arai,0) end
       into v_date_payment,v_date_end,
            v_achuz_mimaskoret_kovaat_leeynam_kranot,
            v_hishtatfut_beschum_leeynam_kranot,
            v_hishtatfut_beschum_letkufa_arait
       from participation t
       where t.seq_bakasha = v_seq_bakasha
       and t.seq_guf = r.seq_guf;
    end if;
    
    if v_date_payment is null then
       message := v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' || 'לא נשלח: לא מוגדר תאריך זכאות'; 
       clob_log := clob_log ||('insert_event_413: ' || message) ||  '<br />';
       continue;
    elsif is_check_running = 0 and v_date_payment >= to_date('01/06/2019','DD/MM/YYYY') then continue; --לא לשלוח 06/2019     
    end if;

      v_schum := null;
      v_achuz := null;

      if v_semel_hilan = '0290' then
        v_schum := v_hishtatfut_beschum_lekranot;
      elsif v_semel_hilan = '0291' then
        v_schum := v_hishtatfut_beschum_leeynam_kranot;
      elsif v_semel_hilan = '0292' then
        v_schum := v_hishtatfut_beschum_letkufa_arait;
      elsif v_semel_hilan = '0293' then
        v_schum := v_hishtatfut_beschum_heskem_meyuhad;
      elsif v_semel_hilan = '0296' then
        v_schum := v_tosefet_actuarit;
      elsif v_semel_hilan = '0298' then     
        v_schum := v_tosefet_dchiat;
       end if;

      if v_semel_hilan = '0287' then
        v_achuz := v_achuz_mimaskoret_kovaat_leeynam_kranot;
      elsif v_semel_hilan = '0288' then
        v_achuz := v_achuz_maskoret_kovaat_lekranot;
      end if;
     
     if v_achuz = 0 then v_achuz := null; end if;
     if v_schum = 0 then v_schum := null; end if;
     
     if v_semel_hilan in (292,290) and v_schum is null then v_schum := 0; end if;
    
     if (v_semel_hilan in (/*'0290',*/'0291',/*'0292',*/'0293','0296','0298') and v_schum is null) then continue; end if;
     if (v_semel_hilan in ('0287','0288') and v_achuz is null) then continue; end if;
     
      ld_log_events_record.code_event := 413;
      ld_log_events_record.code_event_semel := v_semel_hilan;
      
      if is_first then
      ld_log_events_record.code_trigger := 0;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug<>0 then v_mispar_zehut_sheer_benzug  else v_mispar_zehut end,
                        v_gimla_number,
                        true,
                        to_date(to_char(v_date_payment,date_format_d6) || '01',date_format_d8));
      is_first := false;
      if not insert_event then return false; end if;
      end if;
                         
      if (v_schum is not null and v_schum<>0) or (v_achuz is not null and v_achuz<>0) then
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                         --MINUI
             to_char(v_date_payment,date_format_d6) || '01' ||                              --TAARICH
             case when v_date_end is not null then 
               to_char(v_date_end,date_format_d8) else lpad_zeroez(0,8) end ||     --GMATTOKEF                                                                        
             '0' ||                                                                         --KODISHI
             ' ' ||                                                                         --מינוס
             case when v_schum is null                                                      --TASHLUM
                       then lpad_zeroez(0,9)
                       else lpad_zeroez(replace(to_char(nvl(v_schum,0),'9999999.99'),'.',''),9)
             end ||                                                                         
             lpad_zeroez(0,3) ||                                                            --TAARIF???
             ' ' ||                                                                         --מינוס                             
             --case when not v_achuz is null then '0000100' else lpad_zeroez(0,7) end ||    --KAMUT
             case when v_achuz is null                                                      --AHUZ
                       then lpad_zeroez(0,7)
                       else lpad_zeroez(replace(to_char(nvl(v_achuz,0),'99999.99'),'.',''),7)
             end ||                                                                         
             lpad_zeroez(0,3) || lpad_zeroez(v_code_ezor_ovdim/100,4) || '99' ||            --SEIF
             lpad_zeroez(0,11) ||                                                           --MEKORI
             lpad_zeroez(0,11) ||                                                           --MITZTABER
             lpad_zeroez(0,3) ||                                                            --MISPAR
             lpad_zeroez(0,3) ||                                                            --BUTZU
             lpad_zeroez(0,9) ||                                                            --ASMACTA
             lpad_zeroez(0,5) ||                                                            --AHUZ
             lpad_zeroez(0,6);                                                              --ערך
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || '413' ||  '<br />';
      if insert_event then 
        continue; 
      else
        return false;
      end if;
      end if;
     end;
   end loop;
    return true;
    exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_413: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_413: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;   
  ------------------------------------  
  --הוראות קבע 
    function check_event_413(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
    v_schum float;                             --תוספות
    --v_amount float;                            --תוספות
    v_achuz float;
    v_code_ezor_ovdim number;
    v_is_keren number;
    v_seif_takzivi varchar2(6);
    is_first boolean := true;
 
    v_mispar_zehut_sheer_benzug number :=0;
    
    v_date_payment date;
    v_achuz_mimaskoret_kovaat_leeynam_kranot float;           --287
    v_achuz_maskoret_kovaat_lekranot float;                   --288
    v_hishtatfut_beschum_lekranot float;                      --284
    v_hishtatfut_beschum_leeynam_kranot float;                --291
    v_hishtatfut_beschum_letkufa_arait float;                 --292
    v_hishtatfut_beschum_heskem_meyuhad float;                --293
    v_tosefet_actuarit float;                                 --296
    v_tosefet_dchiat float;                                   --298
    
    begin     

 for r in (select distinct t.*
                from participation t
                where t.seq_bakasha = v_seq_bakasha
                ) loop
   begin 
    v_achuz_mimaskoret_kovaat_leeynam_kranot := null;
    v_achuz_maskoret_kovaat_lekranot := null;
    v_hishtatfut_beschum_lekranot := null;
    v_hishtatfut_beschum_leeynam_kranot := null;
    v_hishtatfut_beschum_letkufa_arait := null;
    v_hishtatfut_beschum_heskem_meyuhad := null;
    v_tosefet_actuarit := null;
    v_tosefet_dchiat := null;
 
    begin
    select  c.code_ezor_ovdim_hilan, decode(c.code_sug_ezor_ovdim,5,1,0) is_keren
    into v_code_ezor_ovdim, v_is_keren
    from code_ezor_ovdim c
    where c.seq_ezor_ovdim = r.seq_guf;
    if v_code_ezor_ovdim is null then
       check_message := check_message || ' event_413; semel_' ||  v_semel_hilan ||  '<br />';
    end if;
     exception
      when others then
      message := sqlerrm;
      check_message := check_message || ' event_413; semel_' || v_semel_hilan || ' - ' || message ||  '<br />';
    end;
         
    begin
    select p.sum_participation
    into v_hishtatfut_beschum_heskem_meyuhad
    from bakasha_regila t, participation p
    where t.code_seif_prisha = 415
    and t.code_sub_seif_prisha = 990
    and t.seq_bakasha = v_seq_bakasha
    and t.seq_bakasha = p.seq_bakasha;
    exception
    when no_data_found then
      v_hishtatfut_beschum_heskem_meyuhad := null;
    end;

    begin
    if v_is_keren = 1 then
       select t.date_payment,
       --t.percent_participate,
       t.achuz_guf_final,
       case when not v_hishtatfut_beschum_heskem_meyuhad is null then null else t.sum_participation end,
       case when seq_guf = 8 then t.tosefet_actuarit else null end, -- 8 - קרן גלעד
       case when seq_guf = 8 then t.tosefet_dchiat else null end,
       t.sum_participation                                          -- !!!!!!!!!!!!!!!!! לא נכון לתקופה ארעית
       into v_date_payment,
            v_achuz_maskoret_kovaat_lekranot,
            v_hishtatfut_beschum_lekranot,
            v_tosefet_actuarit,
            v_tosefet_dchiat,
            v_hishtatfut_beschum_letkufa_arait
       from participation t
       where t.seq_bakasha = v_seq_bakasha
       and t.seq_guf = r.seq_guf;
     else
       select t.date_payment,
       --t.percent_participate,
       t.achuz_guf_final,
       case when not v_hishtatfut_beschum_heskem_meyuhad is null then null else t.sum_participation end,
       t.sum_participation                                          -- !!!!!!!!!!!!!!!!! לא נכון לתקופה ארעית
       into v_date_payment,
            v_achuz_mimaskoret_kovaat_leeynam_kranot,
            v_hishtatfut_beschum_lekranot,
            v_hishtatfut_beschum_letkufa_arait
       from participation t
       where t.seq_bakasha = v_seq_bakasha
       and t.seq_guf = r.seq_guf;
    end if;
    if v_date_payment is null then
       check_message := check_message || ' event_413; semel_' ||  v_semel_hilan || ' - ' || 'לא מוגדר תאריך זכאות' || '<br />';
    end if;
     exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0527',v_semel_hilan,45,'',message) ;
    end;
 
      v_schum := null;
      v_achuz := null;

      if v_semel_hilan = '0290' then
        v_schum := v_hishtatfut_beschum_lekranot;
      elsif v_semel_hilan = '0291' then
        v_schum := v_hishtatfut_beschum_leeynam_kranot;
      elsif v_semel_hilan = '0292' then
        v_schum := v_hishtatfut_beschum_letkufa_arait;
      elsif v_semel_hilan = '0293' then
        v_schum := v_hishtatfut_beschum_heskem_meyuhad;
      elsif v_semel_hilan = '0296' then
        v_schum := v_tosefet_actuarit;
      elsif v_semel_hilan = '0298' then     
        v_schum := v_tosefet_dchiat;
       end if;

      if v_semel_hilan = '0287' then
        v_achuz := v_achuz_mimaskoret_kovaat_leeynam_kranot;
      elsif v_semel_hilan = '0288' then
        v_achuz := v_achuz_maskoret_kovaat_lekranot;
      end if;
      
     if (v_semel_hilan in ('0290','0291','0292','0293','0296','0298') and v_schum is null) then
       --check_message := check_message || ' event_413; semel_' ||  v_semel_hilan ||  '<br />';
       continue;
     end if;
     if (v_semel_hilan in ('0287','0288') and v_achuz is null) then
       --check_message := check_message || ' event_413; semel_' ||  v_semel_hilan ||  '<br />';     
       continue;
     end if;
   end;
   end loop;   
   return true;
   end;
  ------------------------------------  
  -- נתוני גמלה למינוי
    function insert_event_309(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number,
                          v_mispar_misra_last number default 0
                          ) return boolean is
    v_schum float;                              --תוספות
    v_amount float;                            --תוספות
    v_mispar_zehut_sheer_benzug number :=0;
    v_mispar_misra number := 0;
    
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    
      ld_log_events_record.code_event := 309;
      ld_log_events_record.code_event_semel := v_semel_hilan;
      
     --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
     if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 

     for r in (select n.*
      from netuney_sachar n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_sug_maskoret = 1
      --n.mispar_misra = v_mispar_misra_last; 
      --and (v_mispar_misra_last = 0 or v_mispar_misra_last<>0 and n.mispar_misra = v_mispar_misra_last)
      order by n.mispar_misra) loop
      
      v_mispar_misra := r.mispar_misra;
      
      if v_semel_hilan not in ('0001','2004','2005') and r.mispar_misra <> v_mispar_misra_last then continue; end if;

      if v_semel_hilan = '0001' then           --שכר יסוד
        select t.schar_ysod, 0
        into v_schum, v_amount
        from netuney_sachar t
        where t.seq_bakasha = v_seq_bakasha
        and t.seq_netuney_sachar =  r.seq_netuney_sachar;
      elsif v_semel_hilan = '2004' then        --1/12 מההבראה
        select t.sum_havraa, 0
        into v_schum, v_amount
        from netuney_sachar t
        where t.seq_bakasha = v_seq_bakasha
        and t.seq_netuney_sachar =  r.seq_netuney_sachar;
         if v_schum = 0 or v_schum is null then continue; end if;
     elsif v_semel_hilan = '2005' then        --1/12 מהביגוד
        select t.sum_bigud, 0
        into v_schum, v_amount
        from netuney_sachar t
        where t.seq_bakasha = v_seq_bakasha
        and t.seq_netuney_sachar =  r.seq_netuney_sachar;
        if v_schum = 0 or v_schum is null then continue; end if;
      else                                     --תוספות בפועל
        select t.sum, t.amount      
        into v_schum, v_amount    
        from tosefot t, netuney_sachar s, code_semel_tosefet c
        where s.seq_netuney_sachar = t.seq_netuney_sachar
        and s.code_sug_maskoret = 1
        and s.seq_bakasha = v_seq_bakasha
        and t.code_semel_tosefet = c.code_semel_tosefet
        and s.mispar_misra = v_mispar_misra
        and c.semel_hilan = v_semel_hilan
        and t.seq_tosefot = v_seq_tosefot
        and c.code_event_hilan = 309;
      end if;
                                              
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug<>0 then v_mispar_zehut_sheer_benzug  else v_mispar_zehut end,
                              case when v_mispar_misrot_sach_hakol > 1 then 
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                              else 
                                v_gimla_number
                              end,
                        true,
                        to_date(to_char(v_date_start_zakaut,date_format_d6) || '01',date_format_d8));                    
      if not insert_event then return false; end if;
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                 --MINUI                                                
             to_char(v_date_start_zakaut,date_format_d6) || '01' ||                                 --TAARICH
             lpad_zeroez(0,8) ||                                                                    --GMATROKEF
             '0' ||                                                                                 --KODISHI
             ' ' ||                                                                                 --מינוס
             lpad_zeroez(replace(to_char(nvl(v_schum,0),'0000000.99'),'.',''),9) ||                 --TASHLUM
             lpad_zeroez(0,3) ||                                                                    --TAARIF
             ' ' ||                                                                                 --מינוס
             '0' ||                                                                                 --פילר
             lpad_zeroez(replace(to_char(nvl(v_amount,0),'000.999'),'.',''),6) ||                   --KAMUT
             lpad_zeroez(0,9) ||                                                                    --SEIF
             lpad_zeroez(0,11) ||                                                                   --MEKORI
             lpad_zeroez(0,11) ||                                                                   --MITZTABER
             lpad_zeroez(0,3) ||                                                                    --MISPAR
             lpad_zeroez(0,3) ||                                                                    --BUTZU
             '229230900' ||                                                                         --ASMACTA
             lpad_zeroez(0,9);                                                                      --פילר
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || '309' ||  '<br />';
       if not insert_event then return false; end if;
    end loop;
    return true;
    exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_309: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_309: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;   
   ------------------------------------  
   -- נתוני גמלה למינוי
   function check_event_309(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number,
                          v_mispar_misra_last number default 0
                          ) return boolean is
    v_schum float;                              --תוספות
    v_amount float;                            --תוספות
    v_mispar_zehut_sheer_benzug number :=0;
    v_mispar_misra number := 0;
    
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
       
     --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
     if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 

     for r in (select n.*
      from netuney_sachar n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_sug_maskoret = 1
      --and (v_mispar_misra_last = 0 or v_mispar_misra_last<>0 and n.mispar_misra = v_mispar_misra_last - 1)
      order by n.mispar_misra) loop
      
      /*if v_mispar_misra_last <>0  then
        v_mispar_misra := v_mispar_misra_last - 1;
      else
        v_mispar_misra := r.mispar_misra;
      end if;*/

      if v_semel_hilan = '0001' then           --שכר יסוד
        begin
        select t.schar_ysod, 0
        into v_schum, v_amount
        from netuney_sachar t
        where t.seq_bakasha = v_seq_bakasha
        and t.seq_netuney_sachar =  r.seq_netuney_sachar;
        exception
        when others then
        message := sqlerrm;
        build_check_message(1,'0309','0001',40,'',message) ;
        end;
      elsif v_semel_hilan = '2004' then        --1/12 מההבראה
        begin
        select t.sum_havraa, 0
        into v_schum, v_amount
        from netuney_sachar t
        where t.seq_bakasha = v_seq_bakasha
        and t.seq_netuney_sachar =  r.seq_netuney_sachar;
        exception
        when others then
        message := sqlerrm;
        build_check_message(1,'0309',2004,4,'',message) ;
        end;
      elsif v_semel_hilan = '2005' then        --1/12 מהביגוד
        begin
        select t.ramat_bigud, 0
        into v_schum, v_amount
        from netuney_sachar t
        where t.seq_bakasha = v_seq_bakasha
        and t.seq_netuney_sachar =  r.seq_netuney_sachar;
        exception
        when others then
        message := sqlerrm;
        build_check_message(1,'0309','2005',40,'',message) ;
        end;
      else
        begin                                    --תוספות בפועל
        select t.sum, t.amount      
        into v_schum, v_amount    
        from tosefot t, netuney_sachar s, code_semel_tosefet c
        where s.seq_netuney_sachar = t.seq_netuney_sachar
        and s.seq_bakasha = v_seq_bakasha
        and t.code_semel_tosefet = c.code_semel_tosefet
        and s.mispar_misra = v_mispar_misra
        and c.semel_hilan = v_semel_hilan
        and c.code_event_hilan = 309;
        exception
        when others then
        message := sqlerrm;
        build_check_message(1,'0309',v_semel_hilan,46,'',message) ;
        end;
      end if;
      if v_schum is null then
         build_check_message(1,'0309',v_semel_hilan,46,'',message) ;
      end if;
                                             
    end loop;
    return true;
    end;   
  ------------------------------------  
  function build_out_file(v_seq_ld_protocol number, v_seq_ld_protocol_hilan number) return clob is
   v_record varchar2(185);
   result_clob clob;
   v_code_event_prev number := 0;
   v_code_semel_prev number := 0;
   v_code_trigger_prev number := 0;
   begin
   v_record := rpad_blanks(lpad_zeroez(v_seq_ld_protocol_hilan,8),185);
   --clob_log := clob_log ||(v_record) ||  '<br />';
   result_clob := v_record;
   
   for r in (select distinct t.*
                from ld_log_events t, perm_sug_bakasha_event_hilan thh, v_bakasha_last_status v
                where v.seq_bakasha = t.seq_bakasha
                and v.code_sug_bakasha = thh.code_sug_bakasha
                and t.seq_ld_protocol = v_seq_ld_protocol
                and v.code_sug_bakasha = thh.code_sug_bakasha
                and (t.code_event = thh.code_event_hilan
                 and t.code_event_semel = thh.code_semel_hilan
                 and thh.pail > 0  
                or             
                 t.code_event in (539,309,527) and
                 not exists
                     (select thh1.seq_perm_sug_bakasha_event_hil
                     from perm_sug_bakasha_event_hilan thh1
                     where thh1.code_event_hilan = t.code_event
                       and thh1.code_semel_hilan = t.code_event_semel
                       and thh1.code_sug_bakasha = v.code_sug_bakasha)
                )
                order by t.mispar_zehut,
                      t.code_event,
                      t.code_event_semel,
                      t.mispar_gimla,
                      --t.seq_ld_log_events,
                      t.code_trigger,
                      t.date_report,
                case when t.code_event = 219 then substr(t.record_hilan,11,9) end asc,      
                      t.seq_ld_protocol
                     ) loop
    begin 
    if r.code_event = 413 and r.code_trigger = 0
      and v_code_event_prev = r.code_event
      and v_code_semel_prev = r.code_event_semel
      and v_code_trigger_prev = 0
    then continue;
    else
      v_code_event_prev := r.code_event;
      v_code_semel_prev := r.code_event_semel;
      v_code_trigger_prev := r.code_trigger;
    end if;
   
    v_record := lpad_zeroez(r.code_event,3) ||
                lpad_zeroez(r.code_event_semel,4) ||
                lpad_zeroez(r.mispar_zehut,9) ||
                lpad_zeroez(r.code_trigger,1) ||
                to_char(r.date_report,date_format_d8) ||
                '2292' || 
                r.record_hilan;-- || chr_13 || chr_10;
    v_record :=  rpad_blanks(v_record,185);               
    --clob_log := clob_log ||(v_record) ||  '<br />';
    --clob_log := clob_log ||(to_char(length(v_record)));
    result_clob := result_clob || v_record;         
     end;                                      
    end loop;
    v_record := '99900009999999990' ||
                to_char(sysdate,date_format_d8) ||
                ' ' || to_char(v_seq_ld_protocol)||
                ' ' || to_char(v_seq_ld_protocol_hilan);
    v_record :=  rpad_blanks(v_record,185);               
    --clob_log := clob_log ||(v_record) ||  '<br />';
    result_clob := result_clob || v_record;
   return result_clob;
   
    end;
 ------------------------------------  
   function insert_porshim_events_out (v_seq_ld_protocol number,
                                       v_seq_ld_protocol_hilan number) return clob is
   --v_seq_ld_protocol number :=  ld_protocol_seq.nextval;
   v_count_id_to_send number;
   v_mispar_zehut number;
   v_mistz_almana_benzug_sheer number := 0;
   v_mispar_zehut_ben_katan number := 0;
   v_taarich_leda_ben_katan date;
   v_seq_bakasha number;
   v_code_sug_bakasha number;
   v_code_source number;
   v_gimla_number number;
   v_seq_ezor_ovdim number;
   result_clob clob;
   v_event_hilan varchar2(3);
   v_semel_hilan varchar2(4);
   v_code_hishuv number;
   v_code_natun number;
   v_code_seif_prisha number;
   --v_ptirat_poresh  boolean := false;     
   if_commit_bakasha boolean := true;
   v_remainder number;
   --v_taarich_ptirat_poresh date;
   v_mispar_misrot_leprisha number;
   v_mispar_misrot_netuney_sachar number;
   --v_tosefet_gimla_lesheerim number;
   v_aaa number;
   v_mispar_shlichot_le_hilan number;
   v_code_group_prisha number;

   begin
   v_error_172_message := '';
   v_error_172_seq_bakasha := 0;
   v_error_172_mispar_zehut := 0;
   /*if v_count_id_to_send = 0 then
     clob_log := clob_log ||(get_hilan_file_name(v_seq_ld_protocol,v_seq_ld_protocol_hilan)) ||  '<br />' ; 
     select t.date_close_chodesh
