        clob_log := 'הממשק לא יצא בגלל יום מיכון.';
        return null;            -- לא לשלוח ממשק קרוב ל יום מיכון
       -- באמת כמה ימים מראש
     end if;
   end if;*/
   if is_check_running = 0 then
   select count(*)
            into v_count_id_to_send
            from v_bakasha_last_status v
            where v.code_action = 134;
   else
   select count(*)
            into v_count_id_to_send
            from v_bakasha_last_status v
            where v.seq_bakasha = v_seq_bakasha_check;
   end if;
   if v_count_id_to_send > 0 then
   if is_check_running = 0 then
     if_commit := insert_begin_protocol(v_seq_ld_protocol, v_seq_ld_protocol_hilan);
     if not if_commit then if_commit_bakasha := if_commit; end if;
   end if;
   if  if_commit_bakasha then
   for r in (select t.*, e.seq_ezor_ovdim seq_ezor_ovdim1
                from v_bakasha_last_status t, code_ezor_ovdim e
                 where (
                 (is_check_running = 0 
                  and t.code_action in (134)


/*                  select distinct v.seq_bakasha
from action_log a, v_bakasha_last_status v
where a.seq_bakasha = v.seq_bakasha
and a.code_action = 134
and a.date_action >= to_date('01/04/2019','DD/MM/YYYY')
and v.code_action <> 17
and v.code_sug_bakasha = 7
and exists
(select w.order_wf
from workflow w
where w.code_sug_workflow = v.code_sug_workflow
and w.next_action = 134)*/
)

                 or (is_check_running = 1  and
                 t.seq_bakasha = v_seq_bakasha_check))
                 and t.seq_ezor_ovdim = e.seq_ezor_ovdim --and e.pail = 1
                 order by t.mispar_zehut, t.gimla_number, t.seq_bakasha) loop                
    begin
     if v_error_172_seq_bakasha > 0 then
        pk_prm_utils.insert_action_log_row(172,sysdate,0,0,'ת.ז.:' || ' ' || v_error_172_mispar_zehut || ' - ' || v_error_172_message,
                                null,null,null,v_error_172_seq_bakasha,null); 
     commit;                                        
     end if;
     v_error_172_message := '';
     v_error_172_seq_bakasha := 0;
     if_commit := true;
     if_commit_bakasha := true;
     v_mispar_zehut := r.mispar_zehut;
     v_seq_bakasha := r.seq_bakasha;
     v_events_count_for_bakasha := 0;
     v_code_sug_bakasha := r.code_sug_bakasha;
     v_code_source := r.code_source;
     v_code_bakasha_detail := r.code_bakasha_detail;
     if v_code_sug_bakasha in (19,20) then v_count_221 := 0; end if;
     v_gimla_number := nvl(r.gimla_number,0);
     if is_check_running = 1 then v_is_heshbon_bank := 0;/*לא נכנס לאירוע*/ end if;
     
/*     if v_code_sug_bakasha = 13 --and r.date_action < to_date('13/06/2019','DD/MM/YYYY')
       then  continue; 
     end if;  */                                             --זמנית לא לשלוח בקשות שארים בכלל
/*select count(v.seq_bakasha)
into v_mispar_shlichot_le_hilan
from ld_protocol l, ld_log_events t, v_bakasha_last_status v, v_bakasha_last_zakaut z
where l.seq_ld_protocol = t.seq_ld_protocol
and l.message like '%ontrol%'
and l.source_mimshak_number = t.seq_ld_protocol_hilan
and t.seq_bakasha = v.seq_bakasha
and z."SEQ_BAKASHA" = v.seq_bakasha
and v.code_sug_bakasha = 13
and v.seq_bakasha = v_seq_bakasha
and z."DATE_START_ZAKAUT" >= to_date('01/04/2019','DD/MM/YYYY') and z."DATE_START_ZAKAUT" < sysdate;
if v_mispar_shlichot_le_hilan > 0 then                          --זמנית לא לשלוח בקשות שארים ישנות עד ההודעה החדשה
  continue;
end if;
     end if;
*/   

    
    --if v_code_sug_bakasha= 24 then continue; end if;
             
     --if v_code_sug_bakasha = 12 then v_gimla_number := 700000000 + v_gimla_number; end if;
       
     v_seq_ezor_ovdim := r.seq_ezor_ovdim1;
     v_code_seif_prisha := r.code_seif_prisha;
     v_mistz_almana_benzug_sheer := 0;
     v_mispar_zehut_ben_katan := 0;    

        if v_code_sug_bakasha in (1,3,5,13) then 
        begin
        select distinct t.date_start_zakaut, t.code_group_prisha                 --לא שולחים אירעוי פורש בלי תאריך זכאות
        into v_date_start_zakaut, v_code_group_prisha
             from netuney_tik_mechushavim t
             where t.seq_bakasha = v_seq_bakasha
             and t.code_department = 2;
        if v_date_start_zakaut is null then
          if is_check_running = 0 then
             clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח: לא מוגדר תאריך זכאות') ||  '<br />';
             v_error_172_message := v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח: לא מוגדר תאריך זכאות';
             v_error_172_seq_bakasha := v_seq_bakasha;
            continue; 
          else
            check_message_error := 'לא מוגדר תאריך זכאות' || '<br />';
            check_message_error_short := check_message_error;
            check_count_error := check_count_error + 1;
          end if;
        elsif is_check_running = 0 and v_date_start_zakaut >= to_date('01/06/2019','DD/MM/YYYY') then continue; --לא לשלוח 06/2019
        end if;
      exception
       when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_porshim_events_out: ' || message) || ' - ' || to_char(v_mispar_zehut) || ' - netuney_tik_mechushavim' ||  '<br />';
       v_error_172_message := 'insert_porshim_events_out: ' || message || ' - ' || to_char(v_mispar_zehut) || ' - netuney_tik_mechushavim';
       v_error_172_seq_bakasha := v_seq_bakasha;
       continue;
        end;  
       elsif v_code_sug_bakasha in (14) then                       -- שינוי שכר
        begin
          select t.from_date
          into v_date_start_zakaut
          from netuney_sachar t
          where t.seq_bakasha = v_seq_bakasha
          and rownum = 1;
          if v_date_start_zakaut is null then
          select t."DATE_START_ZAKAUT"
          into v_date_start_zakaut
          from v_bakasha_last_zakaut t
          where t.seq_bakasha = v_seq_bakasha;
          end if;
          if v_date_start_zakaut is null then
          if is_check_running = 0 then
             clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח: לא מוגדר תאריך זכאות') ||  '<br />';
             v_error_172_message := v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח: לא מוגדר תאריך זכאות';
             v_error_172_seq_bakasha := v_seq_bakasha;
             continue; 
          else
            check_message_error := 'לא מוגדר תאריך זכאות' || '<br />';
            check_message_error_short := check_message_error;
            check_count_error := check_count_error + 1;
          end if;
        elsif is_check_running = 0 and v_date_start_zakaut >= to_date('01/06/2019','DD/MM/YYYY') then continue; --לא לשלוח 06/2019
        end if;
       exception
       when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_porshim_events_out: ' || message) || ' - ' || to_char(v_mispar_zehut) || ' - netuney_sachar' ||  '<br />';
       v_error_172_message := 'insert_porshim_events_out: ' || message || ' - ' || to_char(v_mispar_zehut) || ' - netuney_sachar';
       v_error_172_seq_bakasha := v_seq_bakasha;
       continue;
       end;
      elsif v_code_sug_bakasha in (7) then                       -- השתתפות מגוף
        begin
          select t.date_payment
          into v_date_start_zakaut
          from participation t
          where t.seq_bakasha = v_seq_bakasha
          and rownum = 1;
          if v_date_start_zakaut is null then
          if is_check_running = 0 then
             clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח: לא מוגדר תאריך זכאות') ||  '<br />';
             v_error_172_message := v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח: לא מוגדר תאריך זכאות';
             v_error_172_seq_bakasha := v_seq_bakasha;
             continue; 
          else
            check_message_error := 'לא מוגדר תאריך זכאות' || '<br />';
            check_message_error_short := check_message_error;
            check_count_error := check_count_error + 1;
          end if;
        elsif is_check_running = 0 and v_date_start_zakaut >= to_date('01/06/2019','DD/MM/YYYY') then continue; --לא לשלוח 06/2019
        end if;
       exception
       when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_porshim_events_out: ' || message) || ' - ' || to_char(v_mispar_zehut) || ' - participation' ||  '<br />';
       v_error_172_message := 'insert_porshim_events_out: ' || message || ' - ' || to_char(v_mispar_zehut) || ' - participation';
       v_error_172_seq_bakasha := v_seq_bakasha;
       continue;
       end;
       elsif v_code_sug_bakasha in (/*24,*/16) then                       --מקדמה, היוון 
        begin
/*        select distinct t.date_start_zakaut                             --לא שולחים אירעוי פורש בלי תאריך זכאות
        into v_date_start_zakaut
             from v_bakasha_last_zakaut t
             where t.seq_bakasha = v_seq_bakasha;
*/        
          select h.date_bakasha
          into v_date_start_zakaut
          from hivun h
          where h.seq_bakasha = v_seq_bakasha;       

          if v_date_start_zakaut is null and v_seq_bakasha <> 574136 then
          if is_check_running = 0 then
             clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח: לא מוגדר תאריך זכאות') ||  '<br />';
             v_error_172_message := v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח: לא מוגדר תאריך זכאות';
             v_error_172_seq_bakasha := v_seq_bakasha;
             continue; 
          else
            if v_seq_bakasha <> 579367 then
              check_message_error := 'לא מוגדר תאריך זכאות' || '<br />';
              check_message_error_short := check_message_error;
              check_count_error := check_count_error + 1;
            end if;
          end if;
        elsif is_check_running = 0 and v_date_start_zakaut >= to_date('01/06/2019','DD/MM/YYYY') then continue; --לא לשלוח 06/2019
        end if;
      exception
       when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_porshim_events_out: ' || message) || ' - ' || to_char(v_mispar_zehut) || ' - v_bakasha_last_zakaut' ||  '<br />';
       v_error_172_message := 'insert_porshim_events_out: ' || message || ' - ' || to_char(v_mispar_zehut) || ' - v_bakasha_last_zakaut';
       v_error_172_seq_bakasha := v_seq_bakasha;
       continue;
        end;  
        elsif v_code_sug_bakasha = 12 then
        begin
        select t.hp_date_haavara
        into v_hp_date_haavara
        from netuney_tik_mechushavim t
        where t.code_department = 2
        and t.seq_bakasha = v_seq_bakasha;
        if v_hp_date_haavara is null then                     --לא שולחים אירעוי חיסכון פנסיוני בלי תאריך העברה  
           if is_check_running = 0 then
            clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח: לא מוגדר תאריך העברה') ||  '<br />';
             v_error_172_message := v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח: לא מוגדר תאריך העברה';
             v_error_172_seq_bakasha := v_seq_bakasha;
           continue;
           else
             check_message_error := 'לא מוגדר תאריך העברה' || '<br />';
             check_message_error_short := check_message_error;
             check_count_error := check_count_error + 1;
          end if;  
        elsif is_check_running = 0 and v_hp_date_haavara >= to_date('01/06/2019','DD/MM/YYYY') then continue; --לא לשלוח 06/2019
        end if;
      exception
       when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_porshim_events_out: ' || message) || ' - ' || to_char(v_mispar_zehut) || ' - netuney_tik_mechushavim' ||  '<br />';
       v_error_172_message := 'insert_porshim_events_out: ' || message || ' - ' || to_char(v_mispar_zehut) || ' - netuney_tik_mechushavim';
       v_error_172_seq_bakasha := v_seq_bakasha;
       continue;
        end;
        end if;
    
       select count(*)
       into v_mispar_misrot_leprisha
       from netuney_tik_mechushavim t
       where t.seq_bakasha = v_seq_bakasha
       and t.code_department = 2;
       
       select count(*)
       into v_mispar_misrot_netuney_sachar
       from netuney_sachar t
       where t.seq_bakasha = v_seq_bakasha
       and t.code_sug_maskoret = 1;    
 
       if v_mispar_misrot_leprisha >1 or v_mispar_misrot_netuney_sachar >1 then
         v_mispar_misrot_sach_hakol := 
         case when v_mispar_misrot_leprisha > v_mispar_misrot_netuney_sachar then v_mispar_misrot_leprisha
         else v_mispar_misrot_netuney_sachar
         end;
       else
         v_mispar_misrot_sach_hakol := 1;
       end if;
               
       if v_mispar_misrot_netuney_sachar = 0 then v_netuney_sachar_kayamim := false;
                                             else v_netuney_sachar_kayamim := true;
       end if;
       
       if v_seq_ezor_ovdim <> const_seq_ezor_ovdim_chinuch or 
          v_seq_ezor_ovdim = const_seq_ezor_ovdim_chinuch and v_netuney_sachar_kayamim
       then --אין נתוני שכר לחינוך
       if v_code_sug_bakasha in (1/*,14*/) then --לבדוק תאום מספר משרות בין נתוני שכר וזכאות 
       
       if v_mispar_misrot_leprisha <> v_mispar_misrot_netuney_sachar then
            if is_check_running = 0 then
               clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
               'אין תאום בין נתוני שכר וזכאות (מספר משרות שונה)') || '<br />';
             --continue; 
             else
              check_message_error := 'אין תאום בין נתוני שכר וזכאות (מספר משרות שונה)' || chr_10;
              check_message_error_short := check_message_error;
              check_count_error := check_count_error + 1;
            end if;
       end if;
       end if;
       end if;
     
     
     v_ptira_besherut_gimlat_chesed := false;
     v_ptirat_poresh := false;
     v_taarich_ptirat_poresh := null;
 
     
     begin
       select p.taarich_ptira
     into v_taarich_ptirat_poresh
     from poresh p
     where p.mispar_zehut = v_mispar_zehut
     --and p.taarich_ptira < to_date('01/04/2019','DD/MM/YYYY')
     and (nvl(v_code_group_prisha,0) = 4 and v_code_sug_bakasha = 1 or v_code_sug_bakasha <> 1);
     exception
       when others then
         v_taarich_ptirat_poresh := null;
     end;   
          
     v_remainder := mod(v_code_seif_prisha,100);
     if v_remainder = 26 then v_ptira_besherut_gimlat_chesed := true; end if; 
     if v_remainder = 28 or v_taarich_ptirat_poresh is not null then v_ptirat_poresh := true; end if; 
     
     if v_code_sug_bakasha = 13 and v_code_bakasha_detail = 35 then --גימלת חסד
       v_ptira_besherut_gimlat_chesed := true;
     end if;
 
         
     if v_ptira_besherut_gimlat_chesed or v_ptirat_poresh  then --שאר פנסיוני
       for b in (select * from bney_mishpacha b1
         where b1.seq_porshim = r.seq_porshim
         and not b1.code_relative is null) loop
       begin
         if b.code_relative in (2,3) and 
           ((b.to_date_sium_zakaut is not null and b.to_date_sium_zakaut>sysdate
            or b.to_date_sium_zakaut is null) or v_code_sug_bakasha in (19,20))
           and b.taarich_ptira is null then
           if v_mispar_zehut_ben_katan = 0 then
              v_taarich_leda_ben_katan := b.taarich_leda;
              v_mispar_zehut_ben_katan := b.mispar_zehut_ben_mishpacha;
           elsif (not v_taarich_leda_ben_katan is null) and (not b.taarich_leda is null) then
               if v_taarich_leda_ben_katan < b.taarich_leda then
                 v_taarich_leda_ben_katan := b.taarich_leda;
                 v_mispar_zehut_ben_katan := b.mispar_zehut_ben_mishpacha;
               end if;
           end if;
          end if;
        end;    
     end loop;
    end if;
         
     if v_code_sug_bakasha = 12 then    --חיסכון פנסיוני- פרטי בן זוג לשעבר
        select b.mispar_zehut_ben_mishpacha
        into v_mistz_almana_benzug_sheer
        from bney_mishpacha b
        where b.seq_porshim = r.seq_porshim
        and b.code_kirva = 10;
     end if;
     
     if is_check_running = 0 then
     clob_log := clob_log ||(v_mispar_zehut || ' - begin')  || '<br/>' ;
      if if_commit_bakasha then
       if not (v_ptira_besherut_gimlat_chesed or v_ptirat_poresh) /*and
         not(v_taarich_ptirat_poresh is not null and v_code_sug_bakasha in (7,23))*/
         and v_code_sug_bakasha <> 12 then
       if_commit := insert_begin_bakasha(v_seq_ld_protocol,
                                         v_seq_ld_protocol_hilan,
                                         v_seq_bakasha,
                                         v_mispar_zehut, 
                                         v_gimla_number);
       if not if_commit then if_commit_bakasha := if_commit; end if;
       end if;
 
       if v_code_sug_bakasha = 12 and v_mistz_almana_benzug_sheer <> 0 then
       if_commit := insert_begin_bakasha(v_seq_ld_protocol,
                                         v_seq_ld_protocol_hilan,
                                         v_seq_bakasha,
                                         v_mistz_almana_benzug_sheer, 
                                         v_gimla_number);
       if not if_commit then if_commit_bakasha := if_commit; end if;
       end if;
      
       if v_ptirat_poresh or v_ptira_besherut_gimlat_chesed /*or
         v_taarich_ptirat_poresh is not null and v_code_sug_bakasha in (7,23)*/ then
       for b in (select * from bney_mishpacha b1  --אלמנ/ה, תלוי, צבא 
         where b1.seq_porshim = r.seq_porshim
         and not b1.code_relative is null
         and not b1.code_relative = 9
         and (b1.code_relative not in (2,3) 
         or b1.code_relative in (2,3) and b1.own_bank_account = 1 and b1.mispar_zehut_ben_mishpacha <> v_mispar_zehut_ben_katan))
       loop
       begin
       v_mistz_almana_benzug_sheer := b.mispar_zehut_ben_mishpacha;
       if (v_ptira_besherut_gimlat_chesed or v_ptirat_poresh) and v_mistz_almana_benzug_sheer <> 0 then
       if_commit := insert_begin_bakasha(v_seq_ld_protocol,
                                         v_seq_ld_protocol_hilan,
                                         v_seq_bakasha,
                                         v_mistz_almana_benzug_sheer,
                                         v_gimla_number);
       if not if_commit then if_commit_bakasha := if_commit; end if;
       end if;
       end;
       end loop;
       end if;      
       
       if (v_ptira_besherut_gimlat_chesed or v_ptirat_poresh/*
         or v_taarich_ptirat_poresh is not null and v_code_sug_bakasha in (7,23)*/)
         and v_mispar_zehut_ben_katan <> 0 then
       if_commit := insert_begin_bakasha(v_seq_ld_protocol,
                                         v_seq_ld_protocol_hilan,
                                         v_seq_bakasha,
                                         v_mispar_zehut_ben_katan, 
                                         v_gimla_number);
       if not if_commit then if_commit_bakasha := if_commit; end if;
       end if;
     end if; 
     end if;
 
    for e in (select t.code_event_hilan, t.code_semel_hilan, c.code_hishuv, c.code_natun
                      from perm_sug_bakasha_event_hilan t
                      left join code_event_hilan c on
                      c.code_event = t.code_event_hilan
                      and c.code_semel = t.code_semel_hilan
                      where t.code_sug_bakasha = r.code_sug_bakasha
                      and t.pail = 1
                      and (is_check_running = 0
                      or is_check_running = 1 and is_message_full = 0 and t.is_must = 1
                      or is_check_running = 1 and is_message_full = 1)
                      order by t.code_event_hilan, t.code_semel_hilan asc) loop
     begin
      --לבקשת שארים מפגי תוקף לשלוח רק אחוז קצבה
--      if v_code_sug_bakasha = 13  and e.code_event_hilan <> 567 and v_code_source = 17 then continue; end if;
       
       --אין נתוני שכר לחינוך
       if (v_seq_ezor_ovdim = const_seq_ezor_ovdim_chinuch and not v_netuney_sachar_kayamim and
       (e.code_event_hilan = 527 and e.code_semel_hilan in (234,235,280,244,0)
        or e.code_event_hilan in (309,535))) then continue;
       end if;
         
            v_event_hilan := to_char(e.code_event_hilan);
            v_semel_hilan := lpad_zeroez(to_char(e.code_semel_hilan),4);
            v_code_hishuv := e.code_hishuv;
            v_code_natun := nvl(e.code_natun,0);        
                        
            if v_ptira_besherut_gimlat_chesed and v_event_hilan in (219) then continue; end if;
                      
            if not(v_ptira_besherut_gimlat_chesed or v_ptirat_poresh) and 
               /*not (v_taarich_ptirat_poresh is not null and v_code_sug_bakasha in (7,23,19)) and */      
               not v_code_sug_bakasha in (12,19,20) then
               insert_or_check_event_dynamic(v_event_hilan,
                                v_semel_hilan,
                                v_seq_ld_protocol,
                                v_seq_ld_protocol_hilan,
                                v_seq_bakasha,
                                v_mispar_zehut,
                                v_gimla_number,
                                v_seq_ezor_ovdim,
                                v_code_sug_bakasha,
                                0,
                                0,
                                v_code_seif_prisha,
                                v_code_hishuv,
                                0,
                                v_code_natun);
              if not if_commit=true and is_check_running <> 1 then    
               if_commit_bakasha := false;
              exit;
            end if; 
            end if;
 
            if v_code_sug_bakasha = 12 and v_mistz_almana_benzug_sheer <> 0 then
               insert_or_check_event_dynamic(v_event_hilan,
                                v_semel_hilan,
                                v_seq_ld_protocol,
                                v_seq_ld_protocol_hilan,
                                v_seq_bakasha,
                                v_mispar_zehut,
                                v_gimla_number,
                                v_seq_ezor_ovdim,
                                v_code_sug_bakasha,
                                v_mistz_almana_benzug_sheer,
                                0,
                                v_code_seif_prisha,
                                v_code_hishuv,
                                0,
                                v_code_natun);
            if not if_commit=true and is_check_running <> 1 then  
               if_commit_bakasha := false;
               exit;
              end if;            
            end if;
                     
            if v_ptira_besherut_gimlat_chesed or v_ptirat_poresh or  v_code_sug_bakasha in (19,20) /* or
               v_taarich_ptirat_poresh is not null and v_code_sug_bakasha in (7,23,19)*/ then
               for b in (select * from bney_mishpacha b1  --אלמנ/ה, תלוי, צבא 
               where b1.seq_porshim = r.seq_porshim
               and not b1.code_relative is null
               and not b1.code_relative = 9
               and (b1.code_relative not in (2,3)
                   or b1.code_relative in (2,3) and b1.own_bank_account = 1
                   and b1.mispar_zehut_ben_mishpacha<>v_mispar_zehut_ben_katan)
               and ((b1.to_date_sium_zakaut is not null and b1.to_date_sium_zakaut > sysdate 
                    or b1.to_date_sium_zakaut is null) or nvl(b1.achuz_kizba,0) > 0 or v_code_sug_bakasha in (19,20))
               and (b1.taarich_ptira is null or v_code_sug_bakasha in (19))) loop
             begin
             v_mistz_almana_benzug_sheer := b.mispar_zehut_ben_mishpacha;
             if (v_ptira_besherut_gimlat_chesed or v_ptirat_poresh) and v_mistz_almana_benzug_sheer <> 0 or v_code_sug_bakasha in (19,20) then
                   if v_mistz_almana_benzug_sheer <> 0 then
                   insert_or_check_event_dynamic(v_event_hilan,
                                      v_semel_hilan,
                                      v_seq_ld_protocol,
                                      v_seq_ld_protocol_hilan,
                                      v_seq_bakasha,
                                      v_mispar_zehut,
                                      --case when not v_code_sug_bakasha <> 12 then v_gimla_number*10 + v_tosefet_gimla_lesheerim
                                      v_gimla_number,                              
                                      v_seq_ezor_ovdim,
                                      v_code_sug_bakasha,
                                      v_mistz_almana_benzug_sheer,
                                      0,
                                      v_code_seif_prisha,
                                      v_code_hishuv,
                                      0,
                                      v_code_natun);
                     if not if_commit=true and is_check_running <> 1 then  
                     if_commit_bakasha := false;
                     exit;
                    end if;            
                  end if;
             end if;
             end;
             end loop;
             end if;
 
             if v_mispar_zehut_ben_katan <> 0 or v_code_sug_bakasha in (19,20) then --גם לשלוח בקשה להפסקת תשלומים לעובד בלי קשר לשארים
            --v_tosefet_gimla_lesheerim := v_tosefet_gimla_lesheerim + 1;   
             insert_or_check_event_dynamic(v_event_hilan,
                                v_semel_hilan,
                                v_seq_ld_protocol,
                                v_seq_ld_protocol_hilan,
                                v_seq_bakasha,
                                v_mispar_zehut,
                                v_gimla_number,
                                --v_gimla_number*10 + v_tosefet_gimla_lesheerim,
                                v_seq_ezor_ovdim,
                                v_code_sug_bakasha,
                                0,
                                v_mispar_zehut_ben_katan,
                                v_code_seif_prisha,
                                v_code_hishuv,
                                0,
                                v_code_natun);
               if not if_commit and is_check_running <> 1 then  
               if_commit_bakasha := false;
               exit;
              end if;            
            end if;
            
           if v_code_sug_bakasha in (19,20) and v_count_221 = 0 then
            if is_check_running = 0 then
             clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח: אין אפשרות לשלוח בקשה להפסקת/חידוש תשלום') ||  '<br />';
             v_error_172_message := v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'אין אפשרות לשלוח בקשה להפסקת/חידוש תשלום';
              v_error_172_seq_bakasha := v_seq_bakasha;
              v_error_172_mispar_zehut := v_mispar_zehut;
              v_error_number := v_error_number + 1;
            else           
             --check_message_error := 'אין אפשרות לשלוח בקשה להפסקת/חידוש תשלום';
             --check_message_error_short := check_message_error;
             check_count_error := check_count_error + 1;
            end if;
          end if;



    exception
     when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_porshim_events_out: ' || message) || ' - ' || to_char(v_mispar_zehut) || '<br />';       
       continue;
      end;
    end loop;
    if is_check_running = 0 then
    if v_events_count_for_bakasha = 0 then
       clob_log := clob_log ||(v_mispar_zehut || 'אין אירועים לשליחה לחילן, נא לבדוק שלמות נתונים של הבקשה') ||  '<br />';     
    v_error_172_seq_bakasha := v_seq_bakasha;
    v_error_172_mispar_zehut := v_mispar_zehut;
    v_error_172_message := 'אין אירועים לשליחה לחילן, נא לבדוק שלמות נתונים של הבקשה';
    v_error_number := v_error_number + 1;
    continue;
    end if;
    if if_commit_bakasha then
      
       if r.code_action = 134 then
         v_aaa := v_seq_bakasha;
         --pk_prm_utils.insert_actions_for_bakasha(v_seq_bakasha); 
       end if;
       
       commit;
       
       v_success_number := v_success_number + 1;
       clob_log := clob_log ||(v_mispar_zehut || ' - success') ||  '<br />';
    else
      rollback;
      v_error_number := v_error_number + 1;
      clob_log := clob_log ||(v_mispar_zehut || ' - error') ||  '<br />';
    end if;
    else
      if v_is_heshbon_bank not in (0,2) then 
        message := ' '; 
        build_check_message(1,'0303','0000',26,'',message);
      end if;
      --end if; 
      if is_message_full = 1 then
      check_message := 
      case when check_count_error > 0 then '1'
           when check_count_warning > 0 then '2'
           else '0' end || chr_10 ||
                       case when check_count_error > 0 then 'שגיאות חמורות' else '' end || chr_10 ||
                       trim(check_message_error) ||
                       case when check_count_warning > 0 then 'אזהרות' else '' end || chr_10 ||
                       trim(check_message_warning);
      else
          check_message := case when check_count_error > 0 then '1' || chr_10 ||
                        trim(check_message_error_short)
                        else '0'|| chr_10
                        end;
      end if;
      return check_message;
    end if;
   end;
     clob_log := clob_log ||(v_mispar_zehut || ' - end') ||  '<br />';
    end loop;
     if v_error_172_seq_bakasha > 0 then
        pk_prm_utils.insert_action_log_row(172,sysdate,0,0,'ת.ז.:' || ' ' || v_error_172_mispar_zehut || ' - ' || v_error_172_message,
                                null,null,null,v_error_172_seq_bakasha,null); 
        commit;                                        
     end if;
      return build_out_file(v_seq_ld_protocol, v_seq_ld_protocol_hilan);
     --end if;
  else
     return null;
  end if;
  else return null;
  end if;
    exception
     when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_porshim_events_out: ' || message) || to_char(v_mispar_zehut) || '<br />';       
       return null;
   end;
  ------------------------------------
  function get_hilan_file_name (v_seq_ld_protocol number,
                                v_seq_ld_protocol_hilan number
) return varchar2 is
  v_mispar_mana varchar2(100);
  v_count_id_to_send number;
  v_userenv varchar2(10);
  begin
   select sys_context('userenv', 'DB_NAME') into v_userenv from dual;
   select count(*)
            into v_count_id_to_send
            from v_bakasha_last_status v
            where v.code_action in (134)
            ;
   if v_count_id_to_send > 0 then     
      v_mispar_mana := to_char(v_seq_ld_protocol_hilan);
      v_mispar_mana := substr(trim(v_mispar_mana),length(trim(v_mispar_mana)) - 2,3);
      v_mispar_mana := lpad_zeroez(v_mispar_mana,3);
      return case when v_userenv='xt1' /*prd*/ then 'MPMOA' else 'MPMTA' end ||
                       v_mispar_mana || '.TXT'; --'.ORC';
  else
     return null;
  end if;
    exception
     when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_porshim_events_out: ' || message) ||  '<br />';
  end;
  ------------------------------------
  function check_hilan_out (v_seq_bakasha number,is_full number /*1-full;0-short*/) return varchar2 is
    v_message varchar2(2000) := ' ';
    begin
      is_message_full := is_full;
      check_message_error := '';
      check_message_error_short := '';
      check_message_warning := '';
      check_count_error := 0;
      check_count_warning := 0;
      check_message := '';
      is_check_running := 1;
      v_seq_bakasha_check := v_seq_bakasha;
      v_message := insert_porshim_events_out(0,0);
      return v_message;
     end;
  ------------------------------------
  procedure run_hilan_out (v_seq_ld_protocol number,
                           v_seq_ld_protocol_hilan number,
                           hilan_clob out clob,
                           v_must_send boolean,
                           v_tikim_number out number) is
    v_report             clob;
    v_title              clob;
    begin
    if v_must_send then
        hilan_clob := insert_porshim_events_out(v_seq_ld_protocol, v_seq_ld_protocol_hilan);
    else
        clob_log := 'הקובץ לא נשלח; עדיין לא התקבל קובץ היזון חוזר אחרון';
    end if;
    v_tikim_number := v_success_number;
    v_title := 'total success tikim: ' || v_success_number || chr_10 ||
               'total errors tikim: ' || v_error_number || chr_10;
  
    v_report := '<html><body>' || '<h1>' ||
                'The hilan out interface finished' || '</h1>' ||
                '<h1>' || 'total success rows: ' || v_success_number || '<h1/>' ||
                '<h1>' || 'total errors rows: '  || v_error_number   || '<h1/>' ||
                '<h4><html/><body/>' || clob_log || '<html/><body/><h4/>';

    pk_prm_utils.send_attach('liba@mof.gov.il',
                               'The hilan_out interface finished',
                               v_title,
                               v_report,
                               'html',
                               'hilan_interface.htm');
   
   end;
   ------------------------------------
   function run_hilan_in return number is
    v_report clob;
    v_title  clob;
    v_seq_ld_protocol_hilan number;
    begin
    v_seq_ld_protocol_hilan := get_pirtei_hizun;
    v_title := 'total success tikim: ' || v_success_number || chr_10 ||
               'total errors tikim: ' || v_error_number || chr_10;
  
    v_report := '<html><body>' || '<h1>' ||
                'The hilan in interface finished' || '</h1>' ||
                '<h1>' || 'total success rows: ' || v_success_number || '<h1/>' ||
                '<h1>' || 'total errors rows: '  || v_error_number   || '<h1/>' ||
                '<h4><html/><body/>' || clob_log || '<html/><body/><h4/>';

    pk_prm_utils.send_attach('liba@mof.gov.il',
                               'The hilan_in interface finished',
                               v_title,
                               v_report,
                               'html',
                               'hilan_interface.htm');
    return v_seq_ld_protocol_hilan;                               
   
   end;
   ------------------------------------
   function get_pirtei_hizun return number is
   v_seq_ld_protocol_hilan number;
   v_mispar_zehut number;
   v_mispar_zehut_old number := 0;
   v_seq_bakasha number;
   v_seq_bakasha_old number;
   v_record_type_old number;
   v_gimla_number number;
   v_seq_ld_log_events number;
   v_hilan_recode_level_message1 varchar2(200);
   v_hilan_recode_level_message2 varchar2(200);
   v_hilan_recode_level_message3 varchar2(200);
   v_error_level number := 0;
   v_user number;
   v_status_acharon number;
   v_error_number_leporesh number :=0;
   v_code_event varchar2(3);
   v_semel_event varchar2(4);
   v_hodaa varchar2(4000);
   v_record_type varchar2(2);
   v_seq_bakasha_21 number;
   v_error_number_current number;
   v_code_current_action number;
   v_mispar_minuim number;
   v_mispar_bakashot_for_event number;
   v_seq_bakasha_for_event number;
   v_mispar_shlichot_michtav number;
   v_next_action number;
   
   procedure get_next_action(v_seq_bakasha number) is
   begin                     
             select count(*)
                   into v_mispar_shlichot_michtav
                   from action_log t
                   where t.seq_bakasha = v_seq_bakasha
                   and t.code_action = 129;
             select w.next_action
                   into v_next_action
                   from v_bakasha_last_status v, workflow w
                   where v.seq_bakasha = v_seq_bakasha
                   and w.code_sug_workflow = v.code_sug_workflow
                   and w.code_action = 136;
                   return;
    end;
   
    begin
     clob_log := '';
     v_hilan_recode_level_message1 := '';
     v_success_number := 0;
     v_error_number := 0;
     
       for r in (select t.*
                from ld_hilan t/*,v_bakasha_last_status v
                where t.mispar_teudat_zehut = v.mispar_zehut
                and v.code_action = 135*/
                /*where exists (select t1.mispar_teudat_zehut
                                  from ld_hilan t1
                                  where t.mispar_teudat_zehut = t1.mispar_teudat_zehut
                                  and t1.record_type = 21)*/
                 order by t.mispar_teudat_zehut, t.code_event,t.SEMEL_event,t.record_type) loop
       
       v_code_event := case when r.code_event=537 then 237 else r.code_event end;
       v_semel_event := r.semel_event;
       v_record_type := r.record_type;
       
       if r.record_type = '20' then continue; end if;
       
       if r.record_type <> '21' then
        v_mispar_zehut := to_number(r.mispar_teudat_zehut);
     
       if v_mispar_zehut_old = 0 then 
          clob_log := 'protocol_hilan_number: ' ||  to_char(v_seq_ld_protocol_hilan) || '<br />';
       end if;
       
       --חתון בשימוש בחישוב מספר משרה(חשוב במקרה של כמה משרות)
       if v_mispar_zehut <> 0 then       
         select count(cnt.minuy) 
         into v_mispar_minuim
         from 
         (select t.minuy
         from ld_hilan t
         where to_number(t.mispar_teudat_zehut) = v_mispar_zehut
         and t.minuy <> 0
         group by t.minuy
         order by t.minuy) cnt;
       end if;
       
        if r.mispar_teudat_zehut <> 0  and r.record_type in ('30','31') then
            v_mispar_bakashot_for_event := 0;
            --if r.minuy = 1 then
            for b in   
                (select distinct t.seq_bakasha, t.mispar_gimla
                 from ld_log_events t
                 where t.seq_ld_protocol_hilan = r.Seq_Ld_Protocol_Hilan
                 and t.mispar_zehut = r.mispar_teudat_zehut
                 --and (t.seq_ld_log_events = r.seq_ld_log_events or r.seq_ld_log_events is null)
                 and (r.record_type = '30' and t.code_trigger = 0
                      or r.record_type = '31' and t.code_trigger = 2)
                 and t.code_event = to_number(v_code_event)          
                 and t.code_event_semel = to_number(r.semel_event)                 
                 and (r.minuy = 0
                      or r.minuy > 1 and v_mispar_minuim >=2 and t.mispar_gimla > 1000000 and r.minuy = to_number(substr(to_char(t.mispar_gimla),1,1)) + 1
                      or r.minuy = 1 and v_mispar_minuim >=2 and t.mispar_gimla < 1000000
                      or r.minuy = 1 and v_mispar_minuim < 2 and t.mispar_gimla < 1000000
                      or r.minuy = 2 and v_mispar_minuim < 2 and t.mispar_gimla < 1000000)) loop
                 begin
                 v_mispar_bakashot_for_event := v_mispar_bakashot_for_event + 1;
                 v_seq_bakasha_for_event := b.seq_bakasha;
                 end;
            end loop;
            
            if v_mispar_bakashot_for_event > 1 then
            for b in
              (select distinct t.seq_bakasha
                 from ld_log_events t
                 where t.seq_ld_protocol_hilan = r.Seq_Ld_Protocol_Hilan
                 and t.mispar_zehut = r.mispar_teudat_zehut
                 and t.code_event = to_number(v_code_event)          
                 and t.code_event_semel = to_number(r.semel_event)) loop
            begin
            v_seq_bakasha_for_event := b.seq_bakasha;
            v_hodaa := 'לפורש ' || r.mispar_teudat_zehut || ' (בקשה: ' || v_seq_bakasha_for_event || ' )'  || ' אירוע '
            || v_code_event || ', ' || v_semel_event  || ' נשלח יותר  מפעם אחת בשליחה' || ' ' || r.Seq_Ld_Protocol_Hilan  ;
            v_error_number := v_error_number + 1;
            clob_log := clob_log || 'error - ' || v_code_event || ', ' || v_semel_event  || ', ' || v_mispar_zehut  || ' - ' || v_hodaa || '<br/>' ;
            pk_prm_utils.insert_action_log_row(172,sysdate,0,0,'היזון חוזר: ' || v_hodaa,null,null,null,v_seq_bakasha_for_event,null);
            commit;
            end;
            end loop;        
            continue;
            else
              v_seq_bakasha := v_seq_bakasha_for_event;
            end  if;
            end if;

       if not v_seq_bakasha_old  is null and v_seq_bakasha_old <> v_seq_bakasha then
            v_hodaa := trim(get_hodaot(v_seq_ld_protocol_hilan,v_seq_bakasha_old));
               if v_error_number_leporesh = 0 then
                 v_success_number := v_success_number + 1;
        --------------------------
        
        --begin
        select t.code_action
        into v_code_current_action
        from v_bakasha_last_status t
        where t.seq_bakasha = v_seq_bakasha_old;
/*exception
    when others then
        v_code_current_action := null;
        status  := 0;
        message := sqlerrm;
        clob_log := clob_log || 'error - ' || v_code_event || ', ' || v_semel_event  || ', ' || v_mispar_zehut  || ' - ' || message || '<br/>' ;
        --v_seq_bakasha_old := v_seq_bakasha;        
        --continue;        
        end;*/
        --------------------------
                 if v_code_current_action = 135 then
                   pk_prm_utils.insert_action_log_row(136,sysdate,0,0,v_hodaa,null,null,null,v_seq_bakasha_old,null);                           
                   --לא לשלוח מכתב פעמים
                   get_next_action(v_seq_bakasha_old);
                   if v_mispar_shlichot_michtav > 0 and v_next_action = 129 --ממתין לשליחת מכתב
