        if substr(v_phone,1,3)='000' then v_phone := '0000000000'; end if;
      end if;
    end if;
-- לשלוח קידומת 053 במקום 057  
    if substr(v_phone,1,3) = '057' then v_phone := '053' || substr(v_phone,4,7); end if;  
    if substr(v_phone,1,3) = '000' then v_phone := '0000000000'; end if;
    if substr(v_phone,1,1) <> '0' then v_phone := '0000000000'; end if;
