                          v_mispar_misra number
                          ) return boolean is
   v_code_vetek number;
   v_taarich_prisha date;
   v_vetek_hatchala_kolel number;
   v_vetek_hatchala_kolel_shanim number;
   v_vetek_hatchala_kolel_hodashim number;
   v_vetek_hatchala_zahal number;
   v_vetek_hatchala_zahal_shanim number;
   v_vetek_hatchala_zahal_hodashim number;
   v_insert_event boolean;
   is_vetek_colel number; 
   is_vetek_zahal number;
   v_hefresh_zakaut_prisha number;
   v_seq_sheer number;
   v_bakashot_sheerim number;
   v_sheer_pensioner_count number;
 
   begin
   
   --05/05/2026 *******************
   /*if v_code_sug_bakasha = 13 then
     select b.seq_bney_mishpacha
           into v_seq_sheer
    from bney_mishpacha b*/
    /*left join poresh p on p.porshim_seq = b.seq_porshim
    where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
    and   p.mispar_zehut = v_mispar_zehut;
         select count(*)
         into v_bakashot_sheerim
         from v_bakasha_last_status v
         left join netuney_tik_mechushavim n on n.seq_bakasha = v.seq_bakasha 
                                             and n.code_department = 2
                                             and n.code_group_prisha = 4
         left join netuney_tik_ben_mishpacha nb on nb.seq_bney_mishpacha = v_seq_sheer
                                               and nb.seq_netuney_tik_mechushavim = n.seq_netuney_tik_mechushavim
         left join ld_log_events l on l.mispar_zehut = v_mispar_zehut_sheer_benzug
                                  and l.mispar_gimla = v.gimla_number
                                  and l.code_event = 539
                                  and l.code_event_semel = 1
                                  and l.code_trigger = 0
                                  and l.hilan_recode_level_message = 'הצלחה'                                                                                    
         where v.seq_bakasha < v_seq_bakasha
         and v.code_action not in (17,100)
         and nb.seq_bney_mishpacha is not null;*/
    /*select b.seq_bney_mishpacha
           into v_seq_sheer
    from bney_mishpacha b
    left join poresh p on p.porshim_seq = b.seq_porshim
