     if v_code_sug_bakasha = 13 and v_semel_hilan in ('0001','0009') then
       select count(*)
       into v_sheer_pensioner_count
       from v_bakasha_last_status v539
       left join netuney_tik_mechushavim n539 on n539.seq_bakasha = v539.seq_bakasha
                                             and n539.code_group_prisha = 4
                                             and n539.code_department = 2
       left join netuney_tik_ben_mishpacha nb539 on nb539.seq_netuney_tik_mechushavim = n539.seq_netuney_tik_mechushavim
       left join bney_mishpacha bm on bm.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
       left join temp_porshim_hilan_30092020 tph on to_number(tph.a) = v_mispar_zehut_sheer_benzug
       where v539.seq_prisha = v_seq_prisha
       and v539.code_action = 98
       and n539.seq_bakasha is not null
       and v539.seq_bakasha < v_seq_bakasha
       and (nb539.seq_bney_mishpacha = bm.seq_bney_mishpacha or
            to_number(tph.ab) in (v_gimla_number, v_gimla_number * 10 + 1, v_gimla_number * 10 + 2) );
       if v_sheer_pensioner_count >= 1 then return true; end if;
     end if;
