   if v_semel_hilan = '0009' and v_code_sug_bakasha = 13 /*and v_seq_bakasha <> 455567\*463828*\\*374462*\*/ then
     begin
      select case when nvl(n.code_group_prisha,0) = 3 then v.taarich_prisha
                  when nvl(n.code_group_prisha,0) = 4 then p.taarich_ptira 
