       v_taarich_prisha := null;
      end;
      if v_taarich_prisha is null then return true; end if;
   end if;

   if v_semel_hilan = '0009' and v_code_sug_bakasha = 9 then
        return true;
   end if;
    
   if v_mispar_zehut_sheer_benzug = 0
     and v_code_sug_bakasha <> 1 
