     and v_seq_bakasha <> 649801 /*643026*/ /*583499*/ /*564530*//*348198*/ /*502261*/
     /*494911*/ /*490044*/ /*475261*/ /*480460*/
     /*474730*/ /*481428*/ /*476142*/ 
     /*458824*/ /*450369*/ /*462949*/ /*450253*/ /*428432*/ then
   begin
