           ld_log_events_record.code_trigger := 2;
           ld_log_events_record.record_hilan :=  '0' ||                                                        --MINUI                                                                                                                                                                                                       
             case when v_code_sug_bakasha <> 12 then to_char(v_date_start_zakaut,date_format_d6) || '01'       --TAARICH  
