           when v_vetek_hatchala_kolel_hodashim >=0.25 and v_vetek_hatchala_kolel_hodashim < 0.5 then 0.03
           when v_vetek_hatchala_kolel_hodashim >=0.5 and v_vetek_hatchala_kolel_hodashim < 0.75 then 0.06
           when v_vetek_hatchala_kolel_hodashim >=0.75 and v_vetek_hatchala_kolel_hodashim < 1.00 then 0.09
      end;
       v_vetek_hatchala_kolel := v_vetek_hatchala_kolel_shanim + v_vetek_hatchala_kolel_hodashim;
    else
       v_vetek_hatchala_kolel := 0;
    end if;
    
           ld_log_events_record.code_event_semel := '0002';
