            v_vetek_hatchala_zahal_hodashim := v_vetek_hatchala_zahal_lo_igul - v_vetek_hatchala_zahal_shanim;
            if v_vetek_hatchala_zahal_hodashim <= v_vetek_hatchala_kolel_hodashim then
