   -- נתוני גמלה למינוי
   function insert_event_567(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
    v_achuz_gimla number;
    v_times number := 0; --כמה פעמים להפעיל אירוע
    v_code_sug_gimla number;
    v_mispar_zehut_sheer_benzug number :=0;
    v_mispar_zehut_sheer_benzug_amiti number :=0;
    v_mispar_misra number := 0;
    v_achuz_gimla_kodem number;
    v_achuz_gimla_legil60_kodem number;
    v_date_end_zakaut date;
    --v_is_participation_hilan number;
   
  begin
    
    if v_mistz_almana_benzug_sheer<>0 then 
            if v_seq_bakasha = 653451 then return true ; end if;
            v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer;
            v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number);
    elsif v_mispar_zehut_ben_katan<>0 then
            --if v_seq_bakasha = 394507 and v_mispar_zehut_ben_katan <> 326498334 then return true; end if;
            v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan;
            v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number);
    end if;    
    if v_code_sug_bakasha in (10,11) then
          ld_log_events_record.code_event := 567;
          ld_log_events_record.code_event_semel := 0;
         
    prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        v_mispar_zehut,
                        v_gimla_number,
                        true,
                        v_date_start_zakaut);                                             
      if not insert_event then return false; end if;         
  
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                                --MINUI
             to_char(v_date_start_zakaut,date_format_d8) ||                                                                        --TAATICH 
             lpad_zeroez(0,8) ||                                                                                                   --GMARTOKEF 
             '10000' ||        --100%                                                                                              --AHUZ_GIMLA 
             ' ' ||                                                                                                                --KOD_B_PENSIA
             ' ' ||                                                                                                                --KOD_B_HIVUN
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ_HIVUN
             rpad_blanks(' ',8) ||                                                                                                 --HATHALA
             rpad_blanks(' ',8) ||                                                                                                 --SOF
             lpad_zeroez(0,9) ||                                                                                                   --SCHUM_MEKORI                                                                                    --
             '5' ||                                                                                                                --MUASAK
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL1
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ1
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL2
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ2
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL3
             lpad_zeroez(0,4);                                                                                                     --AHUZ3
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
      if not insert_event then return false; end if; 
       
/*     if not v_2218 or
       check_mz_exists_in_varray(case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug 
                                      else v_mispar_zehut end,
                                 case when v_mispar_misrot_sach_hakol > 1 then to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))                
                                      else v_gimla_number end
                                        ) = false then
       insert_or_check_event_dynamic(527,
                                  '2218',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mistz_almana_benzug_sheer,
                                  v_mispar_zehut_ben_katan,
                                  v_code_seif_prisha,
                                  1,                               
                                  v_mispar_misra,
                                  1);  
    v_2218 := true;
    if check_mz_exists_in_varray(case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug 
                                      else v_mispar_zehut end,
                                 case when v_mispar_misrot_sach_hakol > 1 then to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))                
                                      else v_gimla_number end
                                        ) = false then
        v_cnt_2218 := v_cnt_2218 + 1; 
                     mispar_zehut_2218.extend; 
                     mispar_zehut_2218(v_cnt_2218) := 
