         and p.mispar_zehut = v_mispar_zehut_amiti
         and (b.taarich_ptira is null or b.taarich_ptira is not null and b.taarich_ptira>v_date_start_zakaut)
         and n1.seq_bakasha = v_seq_bakasha
         and n1.code_department = 2
         and n1.mispar_misra = v_mispar_misra
         and n2.seq_netuney_tik_mechushavim = n1.seq_netuney_tik_mechushavim
         and n2.seq_bney_mishpacha = b.seq_bney_mishpacha;
         if v_4248 then v_achuz_gimla := 0; end if;
     elsif v_mispar_zehut_ben_katan<>0  and v_code_sug_bakasha<>9 then
/*      v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan;
      v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
*//*      select sum(nvl(b.achuz_kizba,0)) + sum(nvl(b.achuz_tosefet,0)) achuz_kizba
         into v_achuz_gimla
         from bney_mishpacha b
         left join poresh p on
         p.porshim_seq = b.seq_porshim
         where b.code_relative in (2,3) and
         (b.to_date_sium_zakaut is not null and b.to_date_sium_zakaut > sysdate 
         or b.to_date_sium_zakaut is null)
         and b.taarich_ptira is null
         and p.mispar_zehut = v_mispar_zehut_amiti;*/
      select sum(nvl(n2.achuz_kizba,0)) + sum(nvl(n2.achuz_tosefet,0)) achuz_kizba
         into v_achuz_gimla
         from bney_mishpacha b
         left join poresh p on
