         and n1.code_department = 2
         and n1.mispar_misra = v_mispar_misra
         left join netuney_tik_ben_mishpacha n2 on
         n2.seq_netuney_tik_mechushavim = n1.seq_netuney_tik_mechushavim
         and n2.seq_bney_mishpacha = b.seq_bney_mishpacha
         where (b.code_relative in (2,3) and (b.own_bank_account<>1 or b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti))
         and ((b.to_date_sium_zakaut is not null and b.to_date_sium_zakaut > sysdate 
         or b.to_date_sium_zakaut is null) /*or v_seq_bakasha=357684*/)
         and (b.taarich_ptira is null or b.taarich_ptira is not null and b.taarich_ptira>v_date_start_zakaut)
