      if not insert_event then return false; end if;         
  
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                                --MINUI
             (case when v_date_start_zakaut is null then lpad_zeroez(0,8) else to_char(v_date_start_zakaut,date_format_d8) end) || --TAATICH 
             (case when v_date_end_zakaut is null then lpad_zeroez(0,8) else /*seif 57*/ to_char(v_date_end_zakaut,date_format_d8) end) ||     ----GMARTOKEF 
             lpad_zeroez(replace(to_char(nvl(v_achuz_gimla,0),'000.99'),'.',''),5) ||                                              --AHUZ_GIMLA 
             ' ' ||                                                                                                                --KOD_B_PENSIA
             ' ' ||                                                                                                                --KOD_B_HIVUN
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ_HIVUN
             rpad_blanks(' ',8) ||                                                                                                 --HATHALA
             rpad_blanks(' ',8) ||                                                                                                 --SOF
             lpad_zeroez(0,9) ||                                                                                                   --SCHUM_MEKORI                                                                                    --
             case when v_code_sug_gimla is null then 5 else v_code_sug_gimla end ||                                                                                                   --MUASAK
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL1
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ1
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL2
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ2
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL3
             lpad_zeroez(0,4);                                                                                                     --AHUZ3
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';      if not insert_event then return false; end if;         

     if not insert_event then return false; end if;
             
 /*    if not v_2218 or
     check_mz_exists_in_varray(case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug 
                                      else v_mispar_zehut end,
                                 case when v_mispar_misrot_sach_hakol > 1 then to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))                
                                      else v_gimla_number end
                                        ) = false then
       insert_or_check_event_dynamic(527,
                                  '2218',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mistz_almana_benzug_sheer,
                                  v_mispar_zehut_ben_katan,
                                  v_code_seif_prisha,
                                  1,                               
                                  v_mispar_misra,
                                  1);  
    v_2218 := true;
    if check_mz_exists_in_varray(case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug 
                                      else v_mispar_zehut end,
                                 case when v_mispar_misrot_sach_hakol > 1 then to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))                
                                      else v_gimla_number end
                                        ) = false then
        v_cnt_2218 := v_cnt_2218 + 1; 
                     mispar_zehut_2218.extend; 
                     mispar_zehut_2218(v_cnt_2218) := 
                     case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug else v_mispar_zehut end;
                     mispar_gimla_2218.extend; 
                     mispar_gimla_2218(v_cnt_2218) := 
                     case when v_mispar_misrot_sach_hakol > 1 then to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))                
                          else v_gimla_number end;
    end if;                     
    if not if_commit then return false; end if;
   end if; 
*/ 
    if v_code_sug_bakasha in (7,23) then return true; end if;
      
    end loop;
    return true;
    exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_567: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_567: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;   
   ------------------------------------  
   -- נתוני גמלה למינוי
   function check_event_567(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
    v_achuz_gimla number;
    v_times number := 0; --כמה פעמים להפעיל אירוע
    v_code_sug_gimla number;
    v_mispar_zehut_sheer_benzug number :=0;
    v_mispar_zehut_sheer_benzug_amiti number :=0;
    v_mispar_misra number;
    
  begin
    for r in (select n.*
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      order by n.mispar_misra)
      --for i in 1 .. v_mispar_misrot_leprisha
    loop
      
    v_mispar_misra := r.mispar_misra;
    
    if v_mistz_almana_benzug_sheer<>0 then
     begin
     v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer;
     v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
     select nvl(b.achuz_kizba,0) + nvl(b.achuz_tosefet,0) achuz_kizba
         into v_achuz_gimla
         from bney_mishpacha b
         where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti;
     exception
     when others then
      message := sqlerrm;
      build_check_message(1,'0567','0000',33,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
     end;
    elsif v_mispar_zehut_ben_katan<>0 then
     begin
      v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan;
      v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
      select sum(nvl(b.achuz_kizba,0)) + sum(nvl(b.achuz_tosefet,0)) achuz_kizba
         into v_achuz_gimla
         from bney_mishpacha b
         left join poresh p on
         p.porshim_seq = b.seq_porshim
         where b.code_relative in (2,3) and 
         ((b.to_date_sium_zakaut is not null and b.to_date_sium_zakaut > sysdate 
         or b.to_date_sium_zakaut is null) or v_code_sug_bakasha = 19)         
         and b.taarich_ptira is null
         and p.mispar_zehut = v_mispar_zehut;
     exception
     when others then
      message := sqlerrm;
      build_check_message(1,'0567','0000',33,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
     end;
    else
     begin
      select t.achuz_kizba_sofi
           into v_achuz_gimla
                from netuney_tik_mechushavim t
                where t.seq_bakasha = v_seq_bakasha
                and t.code_department = 2                
                /*and t.mispar_misra = v_mispar_misra*/;

     exception
     when others then
      message := sqlerrm;
      build_check_message(1,'0567','0000',33,': ' || to_char(v_mispar_zehut),message);
     end;
    end if;
    
    begin
      select t.sug_gimla_hilan
      into v_code_sug_gimla
      from code_seif_prisha t
      where t.code_seif_prisha = v_code_seif_prisha;
      exception
       when others then
      message := sqlerrm;
      build_check_message(1,'0567','0000',34,'',message);
    end;
    end loop;
    return true;
    end;   
  ------------------------------------  
   -- נתוני גמלה למינוי
   function insert_event_591(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_toar_misra varchar2(100);
   v_code_mikzoa number;
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_zehut_sheer_benzug_amiti number :=0;
   
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 

    if v_seq_ezor_ovdim = 206 then
    select c.teur_chinuch_mikzoa, decode(c.code_chinuch_mikzoa,0,910,c.code_chinuch_mikzoa)
           into v_toar_misra, v_code_mikzoa
                from bakasha_regila t, code_chinuch_mikzoa c
                where t.seq_bakasha = v_seq_bakasha
                and t.chinuch_mikzoa = c.code_chinuch_mikzoa;
    
                
    ld_log_events_record.code_event := 591;
    ld_log_events_record.code_event_semel := 0;
           
    prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug<>0 then v_mispar_zehut_sheer_benzug  else v_mispar_zehut end,
                        v_gimla_number,
                        true,
                        v_date_start_zakaut);
                                              
    if insert_event then   
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                                   --MINUI
             lpad_zeroez(v_code_mikzoa,6) ||                                                                                          --HAGDARA
             rpad_blanks(v_toar_misra,25) ||                                                                                          --TOAR_MISRA
             (case when v_date_start_zakaut is null then lpad_zeroez(0,8) else to_char(v_date_start_zakaut,date_format_d8) end) ||    --TAARICH
             lpad_zeroez(0,8);                                                                                                        --GMARTOKEF
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
      return insert_event;
      else
        return false;
     end if;
    else
      return true;
    end if;
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_591: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_591: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;
  ------------------------------------  
   -- נתוני גמלה למינוי
   function check_event_591(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_toar_misra varchar2(100);
   v_code_mikzoa number;
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_zehut_sheer_benzug_amiti number :=0;
   
    begin  
    if v_seq_ezor_ovdim = 206 then
    begin
    select c.teur_chinuch_mikzoa, decode(c.code_chinuch_mikzoa,0,910,c.code_chinuch_mikzoa)
           into v_toar_misra, v_code_mikzoa
                from bakasha_regila t, code_chinuch_mikzoa c
                where t.seq_bakasha = v_seq_bakasha
                and t.chinuch_mikzoa = c.code_chinuch_mikzoa;
    exception
      when others then
      message := sqlerrm;
      build_check_message(2,'0591','0000',35,'',message);
   end;
    end if;    
       return true;
    end;
  ------------------------------------  
  --מעמד למינוי 
  function insert_event_538(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
                          
    v_mispar_zehut_sheer_benzug number :=0;
    v_mispar_zehut_sheer_benzug_amiti number :=0;
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; 
       v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number);     
    end if;
    ld_log_events_record.code_event := 538;
    ld_log_events_record.code_event_semel := 0;
  
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug else v_mispar_zehut end,
                        v_gimla_number,
                        true,
                        v_hp_taarich_tokef_haavara);                      
      if insert_event then   
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                --MINUI
             '03' ||                                                                                               --MAAMAD
             to_char(v_hp_taarich_tokef_haavara,date_format_d8) ||                                                          --TAARICH                                                                                      
             lpad_zeroez(0,8);                                                                                     --GMARTOKEF           
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
             return insert_event;
       else
         return false;
       end if;
    exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_538: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_538: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;  
   ------------------------------------								   
function sachar_reforma (v_semel_hilan varchar2,                                            
                         v_seq_ld_protocol number,
                         v_seq_ld_protocol_hilan number,
                         v_seq_bakasha number,
                         v_mispar_zehut number,
                         v_gimla_number number,
                         v_seq_ezor_ovdim number,
                         v_code_sug_bakasha number,
                         v_mistz_almana_benzug_sheer number,
                         v_mispar_zehut_ben_katan number,
                         v_code_seif_prisha number,
                         v_code_hishuv number,
                         v_mispar_misra_last number default 0
                         ) return boolean is  
                          
    v_schum float;                              --תוספות
    v_amount float;                             --תוספות
    v_schum_ysod float;
    v_mispar_zehut_sheer_benzug number :=0;
    v_mispar_zehut_sheer_benzug_amiti number :=0;
    v_mispar_misra number := 0;
    v_code_derug number;
    v_code_darga number;
    v_code_misrad_maskoret number := 0;
    v_code_event_tosefet number;
    v_code_reforma number:= 0;
    v_code_chinuch_alterntive number := 0;
    v_semel_sikum varchar2(9);
    v_semel_hilan_leshlicha number;
    v_is_first boolean := true;
    v_code_chinuch_sug_maskoret number;
    v_JK float;
    v_JK2 float;
    v_312_589 boolean := false;
    v_not_olam_yashan number := 0;
        
    begin
      
    
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
    
    if  v_mispar_zehut_sheer_benzug = 0 then   --פורש
     if v_315_181_buza then
         return true;
     else
        v_315_181_buza  := true;
     end if;
    end if;

    
/*      if v_semel_hilan = 2025 then
      select nvl(c.code_misrad_maskret,0)
        into v_code_misrad_maskoret
        from code_ezor_ovdim c
        where c.seq_ezor_ovdim = v_seq_ezor_ovdim;
      end if;
*/         
      v_dargat_doctor_ofek := false;
        
      for r in (
      select t.seq_netuney_sachar,
      cr.code_reforma,
      cr.code_chinuch_alterntive,
      cr.factor,
      cr.begin_date,
      cr.shanim_reforma,
      t.mispar_misra,
      m.code_chinuch_sug_maskoret,
      t.from_date,
      t.maskoret_kovaat_percent,
      t.maskoret_kovaat_shiur_miztaber
      from netuney_sachar t
      left join chinuch_reforma cr on
      cr.seq_chinuch_reforma = t.seq_chinuch_reforma
      and cr.seq_bakasha = t.seq_bakasha
      left join code_sug_maskoret m on
      m.code_chinuch_alterntive = cr.code_chinuch_alterntive
      where t.seq_bakasha = v_seq_bakasha
      and m.code_sug_maskoret = t.code_sug_maskoret
      union
      select t.seq_netuney_sachar,
      null,--cr.code_reforma,
      null,--cr.code_chinuch_alterntive,
      null,--cr.factor,
      null,--cr.begin_date,
      null,--cr.shanim_reforma
      t.mispar_misra,
      3 code_chinuch_sug_maskoret,
      t.from_date,
      t.maskoret_kovaat_percent,
      t.maskoret_kovaat_shiur_miztaber
      from netuney_sachar t
      where t.seq_bakasha = v_seq_bakasha
      and t.code_sug_maskoret = 14
      and exists
      (select cr.seq_bakasha
      from chinuch_reforma cr
      where cr.seq_bakasha = t.seq_bakasha)
      ) loop
      
        v_code_chinuch_sug_maskoret := nvl(r.code_chinuch_sug_maskoret,0);
        v_code_reforma := nvl(r.code_reforma,0);
        v_code_chinuch_alterntive := nvl(r.code_chinuch_alterntive,0);

     if r.from_date >= to_date('01/01/2021','dd/mm/yyyy') and v_code_chinuch_sug_maskoret = 1 and v_312_589 = false then --תלוש מפורט
     v_312_589 := true;
     
      --if v_code_reforma = 4 then
             select count(*)
             into v_not_olam_yashan
             from chinuch_reforma cr
              where cr.seq_bakasha = v_seq_bakasha
             and cr.code_reforma <> 4;
      --end if;
      
      if v_not_olam_yashan > 0  then 
     
      ld_log_events_record.code_event := 312;
      ld_log_events_record.code_event_semel := '0589';
      
      if v_mispar_zehut_sheer_benzug = 0
        or (v_mispar_zehut_sheer_benzug <> 0 and not check_mz_exists_in_varr_reform(v_mispar_zehut_sheer_benzug,312,589,null)) then 
      
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug<>0 then v_mispar_zehut_sheer_benzug  else v_mispar_zehut end,
                              case when v_mispar_misrot_sach_hakol > 1 then 
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
                              else 
                                v_gimla_number
                              end,
                        true,
                        to_date(to_char(r.from_date,date_format_d6) || '01',date_format_d8),                    
                        '  ' || lpad_zeroez(0,9));                  
      if not insert_event then return false; end if;
           ld_log_events_record.code_trigger := 2;
           ld_log_events_record.record_hilan := 
           '0' ||                                                                                            --MINUI
           lpad_zeroez(case when v_code_chinuch_alterntive = 1 then r.shanim_reforma * 100 else 0 end, 9) ||   --ERECH                       
           lpad_zeroez(0,9) ||                                                                               --ERECH_2
           lpad_zeroez(0,9) ||                                                                               --ERECH_3
           rpad_blanks(case when v_code_chinuch_alterntive = 1 then
           'שנות וותק לאחוז'
           else ' ' end,15) ||                                                                               --TEUR
           to_char(r.from_date,date_format_d8) ||                                                            --TAARICH
           lpad_zeroez(0,8);                                                                                 --GMATROKEF
           --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
           if not insert_event then return false; 
           end if;
      end if;
      end if;
      end if;
      
      if v_code_chinuch_alterntive = 1 then
       v_JK := nvl(r.maskoret_kovaat_percent,0) + nvl(r.maskoret_kovaat_shiur_miztaber,0);
      end if;      
      if v_code_chinuch_sug_maskoret = 2 then
       v_JK2 := nvl(r.maskoret_kovaat_percent,0);
      end if;      

       --if v_event_hilan_source = 309 then
/*       if (v_code_reforma <> r.code_reforma
        or v_code_chinuch_alterntive <> r.code_chinuch_alterntive) then
*/       -- v_semel_hilan = '0004' then          -- (שכר משולב (4 
       --begin
/*        v_code_chinuch_sug_maskoret := r.code_chinuch_sug_maskoret;
        v_code_reforma := r.code_reforma;
        v_code_chinuch_alterntive := r.code_chinuch_alterntive;
*/         
        select case when v_code_chinuch_sug_maskoret = 1 then t.schar_ysod
                    when v_code_chinuch_sug_maskoret = 2 then t.maskoret_kovaat 
                    when v_code_chinuch_sug_maskoret = 3 then t.maskoret_kovaat end,
               case when v_code_chinuch_sug_maskoret = 1 then 0
                    when v_code_chinuch_sug_maskoret = 2 then t.schar_ysod 
                    when v_code_chinuch_sug_maskoret = 3 then 0 end,             
               0
        into v_schum, v_schum_ysod, v_amount
        from netuney_sachar t
        where t.seq_bakasha = v_seq_bakasha
        and t.seq_netuney_sachar =  r.seq_netuney_sachar;
        
      if v_code_chinuch_sug_maskoret in (1,2) then                   --שכר משולב
          select t.semel_sikum, t.semel_hilan
          into v_semel_sikum, v_semel_hilan_leshlicha
          from code_semel_tosefet t
          where substr(t.semel_sikum,1,3) = lpad_zeroez(v_code_chinuch_alterntive,1) || lpad_zeroez (v_code_reforma,2) 
          and t.teur_tosefet_unique like '%משולב%'
          and t.sug_natun = 182
          and rownum < 2;
                   
          --if v_code_sug_bakasha <> 14 then 
             
             if  v_code_chinuch_sug_maskoret = 2 then
               
             ld_log_events_record.code_event := 315;
             ld_log_events_record.code_event_semel := '0576';
                  
      if v_mispar_zehut_sheer_benzug = 0
        or (v_mispar_zehut_sheer_benzug <> 0 and not check_mz_exists_in_varr_reform(v_mispar_zehut_sheer_benzug,315,576,v_semel_sikum)) then 
              prepare_trigger_0(v_seq_ld_protocol,
                              v_seq_ld_protocol_hilan,
                              v_seq_bakasha,
                              case when v_mispar_zehut_sheer_benzug<>0 then v_mispar_zehut_sheer_benzug  else v_mispar_zehut end,
                                    case when v_mispar_misrot_sach_hakol > 1 then 
                                     to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
                                    else 
                                      v_gimla_number
                                    end,
                              true,
                              to_date(to_char(r.from_date, date_format_d6) || '01',date_format_d8),
                              '  ' || lpad_zeroez(0,9));                    
              if not insert_event then return false; end if;
              
              ld_log_events_record.code_trigger := 2;
             
              ld_log_events_record.record_hilan := 
                '0' ||                                                                                                          --MINUI
                   ' ' ||                                                                                                          --מינוס
                   lpad_zeroez(case when v_code_chinuch_sug_maskoret = 2 then /*'2' ||*/ v_semel_sikum else v_semel_sikum end ,9) ||                                                                                --ERECH
                   case when nvl(
                     case when v_code_chinuch_sug_maskoret = 1 then v_schum else v_schum_ysod end
                  
                   ,0) < 0 then '-' else ' ' end ||                                                                                                          --מינוס
                   lpad_zeroez(replace(to_char(nvl(abs(
                   case when v_code_chinuch_sug_maskoret = 1 then v_schum else v_schum_ysod end
                   ),0),'0000000.99'),'.',''),9) ||                                                                                --ERECH_2
                   ' ' ||                                                                                                          --מינוס
                   lpad_zeroez(replace(to_char(nvl(v_amount,0),'0000000.99'),'.',''),9) ||                                                                                            --ERECH_3
                   ' ' ||                                                                                                          --מינוס
                   lpad_zeroez(0,9) ||                                                                                             --ERECH_4
                   ' ' ||                                                                                                          --מינוס
                   lpad_zeroez(0,9) ||                                                                                             --ERECH_5
                   rpad_blanks(' ',15) ||                                                                                          --TEUR
                   to_char(r.from_date, date_format_d6) || '01' ||                                                                 --TAARICH
                   lpad_zeroez(0,8);
                   if not insert_event then return false; end if; 
      end if;             
             else  --v_code_chinuch_sug_maskoret = 1   
      if v_mispar_zehut_sheer_benzug = 0
