    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
   
      ld_log_events_record.code_event := 527;
      ld_log_events_record.code_event_semel := v_semel_hilan;

      if v_semel_hilan = '0630' and v_code_sug_bakasha = 19 then
       select b.from_date
        into v_from_date_bakasha
        from bakasha b
        where b.seq_bakasha = v_seq_bakasha;
       /*select Last_Day(ADD_MONTHS(v_from_date_bakasha,-1)) 
         into v_last_date_of_prev_month
         from dual;*/

 /*        if to_char(f_get_taarich_tchula(v_seq_bakasha),'YYYYMM') < to_char(sysdate,'YYYYMM') then
            select Last_Day(ADD_MONTHS(sysdate,-1)) 
             into v_last_date_of_prev_month
            from dual;
        else
            select Last_Day(sysdate) 
             into v_last_date_of_prev_month
            from dual;
        end if;*/
       prepare_trigger_0(v_seq_ld_protocol,
