                end,      
                case when t.code_event = 315 and t.code_event_semel in (184,576) and v.code_sug_bakasha = 14 then
                       case when t.code_trigger = 0 then record_hilan  end 
                end \*desc*\,   --21/02/2024  
                      t.date_report,
                case when not(t.code_event = 315 and t.code_event_semel in (184,576) and v.code_sug_bakasha = 14) then
                      t.code_trigger
                end,      
                      t.code_trigger,
                case when t.code_event = 219 then substr(t.record_hilan,11,9) end asc,      
                      t.seq_ld_protocol
                     ) loop
    begin 
    --if r.mispar_zehut <> 324868751 then continue; end if;
\*    if not (r.code_event_semel = 312 and r.code_event_semel=535)
         then continue; end if;
*\
\*    if r.seq_bakasha in (383745,383760)  r.code_event = 527  r.code_event_semel = 242
         then continue; end if;
*\    
    if r.code_trigger = 0
      and not (r.code_event = 413) 
      and not (r.code_event = 315 and r.code_sug_bakasha = 14 and v_record_hilan_prev <> '  0000000') \*or
               r.code_event = 315 and r.code_sug_bakasha = 14 and v_record_hilan_prev = '  0000000')*\
      and v_code_event_prev = r.code_event
      and v_code_semel_prev = r.code_event_semel
      and v_code_trigger_prev = 0
      then continue;
    else
      v_code_event_prev := r.code_event;
      v_code_semel_prev := r.code_event_semel;
      v_code_trigger_prev := r.code_trigger;
      v_record_hilan_prev := substr(r.record_hilan,1,9);
    end if;
   
    --if r.mispar_zehut = 022253702 then
    --if r.code_event = 535 then
    v_record := lpad_zeroez(r.code_event,3) ||
                lpad_zeroez(r.code_event_semel,4) ||
                lpad_zeroez(r.mispar_zehut,9) ||
                lpad_zeroez(r.code_trigger,1) ||
                to_char(r.date_report,date_format_d8) ||
                '2292' || 
                r.record_hilan;-- || chr_13 || chr_10;
