    --end if;
           
     end;                                      
    end loop;
*/ 
   for r in (select distinct t.*, v.code_sug_bakasha, v.seq_prisha, v.remarks, v.seq_ezor_ovdim
                from ld_log_events t, perm_sug_bakasha_event_hilan thh, v_bakasha_last_status v
                where v.seq_bakasha = t.seq_bakasha
                and v.code_sug_bakasha = thh.code_sug_bakasha
                and t.seq_ld_protocol = v_seq_ld_protocol
                and v.code_sug_bakasha = thh.code_sug_bakasha
                and (t.code_event = thh.code_event_hilan
                 and t.code_event_semel = thh.code_semel_hilan
                 and thh.pail > 0  
                or             
                 t.code_event in (539,309,527,315,312,237,221) and
                 not exists
                     (select thh1.seq_perm_sug_bakasha_event_hil
                     from perm_sug_bakasha_event_hilan thh1
                     where thh1.code_event_hilan = t.code_event
                       and thh1.code_semel_hilan = t.code_event_semel
                       and thh1.code_sug_bakasha = v.code_sug_bakasha)
                )
                order by t.mispar_zehut,
                      t.code_event,
                      t.mispar_gimla,
                      t.code_event_semel,
                      --t.seq_ld_log_events,
                case when (t.code_event = 413 and t.code_event_semel not in (601,604)) then
                       case when t.code_trigger = 0 then substr(t.record_hilan,5,4)
                       else /*t.code_trigger = 2*/  substr(t.record_hilan,43,4) end
                end,
                case when t.code_event = 315 and t.code_event_semel in (184,576) /*and v.code_sug_bakasha = 14*/ then
                       t.code_trigger
                end,      
                case when t.code_event = 315 and t.code_event_semel in (184,576) /*and v.code_sug_bakasha = 14*/
                          and t.code_trigger = 2  
                          then t.record_hilan
                end,      
               /* case when t.code_event = 315 and t.code_event_semel in (184,576) and v.code_sug_bakasha = 14 then
                       case when t.code_trigger = 0 then record_hilan  end 
                end \*desc*\,   --21/02/2024  */
                      t.date_report,
                case when not(t.code_event = 315 and t.code_event_semel in (184,576) /*and v.code_sug_bakasha = 14*/) then
                      t.code_trigger
                end,      
                      t.code_trigger,
                case when t.code_event = 219 then substr(t.record_hilan,11,9) end asc,      
