         then continue; end if;
*/
/*    if r.seq_bakasha in (383745,383760)  r.code_event = 527  r.code_event_semel = 242
         then continue; end if;
*/    
    if r.code_trigger = 0
      and not (r.code_event = 413) 
      --and not (r.code_event = 315 and r.code_sug_bakasha = 14 and v_record_hilan_prev <> '  0000000') /*or
               --r.code_event = 315 and r.code_sug_bakasha = 14 and v_record_hilan_prev = '  0000000')*/
      and v_code_event_prev = r.code_event
      and v_code_semel_prev = r.code_event_semel
      and v_code_trigger_prev = 0
      then continue;
    else
      v_code_event_prev := r.code_event;
      v_code_semel_prev := r.code_event_semel;
      v_code_trigger_prev := r.code_trigger;
      v_record_hilan_prev := substr(r.record_hilan,1,9);
    end if;
   
    if r.seq_ezor_ovdim = 191 and r.code_sug_bakasha = 14 
       and ( r.code_event = 309 and r.code_event_semel in (2004,2005)
       or   r.code_event = 527 and r.code_event_semel = 235) then
          select min(z.date_start_zakaut)
          into v_date_zakaut_doar
          from v_bakasha_last_zakaut z
          left join v_bakasha_last_status v on v.seq_bakasha = z."SEQ_BAKASHA"
          where z."SEQ_PRISHA" = r.seq_prisha
          and v.code_action not in(17,100);
      if  v_date_zakaut_doar < to_date('01/10/2024','dd/mm/yyyy') then continue; end if;
      --if  v_date_zakaut_doar < to_date('01/03/2025','dd/mm/yyyy') then continue; end if;
    end if;
  
/*    if not (r.code_sug_bakasha = 14
         and  r.seq_ezor_ovdim = 191
         and v_date_zakaut_doar < to_date('01/10/2024','dd/mm/yyyy')
         and ( r.code_event = 309 and r.code_event_semel in (2004,2005)
         or   r.code_event = 527 and r.code_event_semel = 235)) then */
    v_record := lpad_zeroez(r.code_event,3) ||
                lpad_zeroez(r.code_event_semel,4) ||
                lpad_zeroez(r.mispar_zehut,9) ||
                lpad_zeroez(r.code_trigger,1) ||
                to_char(r.date_report,date_format_d8) ||
                '2292' || 
                r.record_hilan;-- || chr_13 || chr_10;
    v_record :=  rpad_blanks(v_record,185);
    --clob_log := clob_log ||(v_record) ||  '<br />';
    --clob_log := clob_log ||(to_char(length(v_record)));
    result_clob := result_clob || v_record;
    /*end if;*/
           
     end;                                      
    end loop;


   v_record := '99900009999999990' ||
                to_char(sysdate,date_format_d8) ||
                ' ' || to_char(v_seq_ld_protocol)||
                ' ' || to_char(v_seq_ld_protocol_hilan);
    v_record :=  rpad_blanks(v_record,185);               
    --clob_log := clob_log ||(v_record) ||  '<br />';
    result_clob := result_clob || v_record;
   return result_clob;
   
    end;
 
