   function insert_porshim_events_out (v_seq_ld_protocol number,
                                       v_seq_ld_protocol_hilan number) return clob is
   --v_seq_ld_protocol number :=  ld_protocol_seq.nextval;
   v_count_id_to_send number;
   v_mispar_zehut number;
   v_mistz_almana_benzug_sheer number := 0;
   v_mispar_zehut_ben_katan number := 0;
