   v_seq_bakasha number;
   v_code_sug_bakasha number;
   v_gimla_number number;
   v_seq_ezor_ovdim number;
   result_clob clob;
   v_event_hilan varchar2(3);
   v_semel_hilan varchar2(4);
   v_code_hishuv number;
   v_code_natun number;
   v_code_seif_prisha number;
   --v_ptirat_poresh  boolean := false;     
   if_commit_bakasha boolean := true;
   v_remainder number;
   --v_taarich_ptirat_poresh date;
   v_mispar_misrot_leprisha number;
   v_mispar_misrot_netuney_sachar number;
   --v_tosefet_gimla_lesheerim number;
   v_aaa number;
   v_mispar_shlichot_le_hilan number;
   v_kayemet_bakashat_gimlaot number;
   v_cnt_bakashot_im_date_zakaut_gvoha number;
   v_cnt_bakashot_shinuy_sachar number;
   --v_code_bakasha_detail number;
   v_gimla_number_hishtatfut number;
   bakashot bakashot_array := bakashot_array();
   v_cnt_bakashot number;
   v_date_start_zakaut_14 date;
   v_heskem_hadash number;
   v_prishat_reforma number;
   v_is_sachar_reforma number := 0;
   v_mispar_hakpaot number;
   v_33_35_count number;   
   v_is_hishtatfut_le_guf number;
   v_exists_bakashat_telephone number;
   v_bakasha_from_date date;
   v_par_id_hilan_parameters number;
   v_par_taarich_me date;
   v_par_taarich_ad date;
   v_par_code_sug_bakasha number;
   v_par_code_bakasha_detail number;
   v_par_seq_bakasha number;
   v_par_mispar_zehut number;
   v_par_sug_gimlay number;
   v_par_seq_bakasha_list varchar2(1000);
   v_par_mispar_zehut_list varchar2(1000);
   v_par_code_sug_bakasha_list varchar2(1000);
   v_par_code_event number;
   v_par_code_semel number;
   
   begin
   v_error_172_message := '';
   v_error_172_seq_bakasha := 0;
   v_error_172_mispar_zehut := 0;
   --if v_count_id_to_send = 0 then
     clob_log := clob_log ||(get_hilan_file_name(v_seq_ld_protocol,v_seq_ld_protocol_hilan)) ||  '<br />' ; 
     select t.date_close_test1,
            t.date_close_test2,
            t.date_close_chodesh,
            t.date_open_chodesh
     into v_date_close_test1, v_date_close_test2 ,v_date_close_chodesh, v_date_open_chodesh
     from date_close_report t
     where to_char(t.date_close_test1,'YYYYMM') = to_char(sysdate,'YYYYMM');           
     /*if extract(year from sysdate) = extract(year from v_date_close) and
        extract(month from sysdate) = extract(month from v_date_close) and
        extract(day from sysdate) = extract(day from v_date_close) then
        clob_log := 'הממשק לא יצא בגלל יום מיכון.';
