            then return null;    --אין פרמטרים לבחירה
     end if;*/
     
            for g in( select t.gimla_number, count(*)
                from v_bakasha_last_status t, code_ezor_ovdim e
                --,simun_bakashot_leshlicha_lehilan s ---פינצטה
                where t.gimla_number is not null
                and t.code_action in (134)
                and t.code_sug_bakasha in (7,23)
                --and s.seq_bakasha = t.seq_bakasha   ---פינצטה
                --and s.simun = 1                     ---פינצטה
                and t.seq_ezor_ovdim = e.seq_ezor_ovdim --and e.pail = 1
                group by t.gimla_number
                having count(*)>1) loop
                v_gimla_number_hishtatfut := g.gimla_number;
                for bh in (
                  select t.seq_bakasha
                  from v_bakasha_last_status t
