                 end loop;


FOR r IN (
    WITH bakashot_le_shlicha AS (
        SELECT t.*, e.seq_ezor_ovdim seq_ezor_ovdim1
                FROM v_bakasha_last_status t, code_ezor_ovdim e, code_sug_bakasha cb
                WHERE t.gimla_number is not null
            AND (v_par_seq_bakasha IS NULL OR t.seq_bakasha = v_par_seq_bakasha)
            -- ממתין לשליחה לחילן (קוד 134)
            AND t.code_action = 134 
            --and t.seq_bakasha = 663116
             
            -- סינון לפי חלונות זמן וסוגי בקשות
            AND (
                -- קבוצה מיוחדת: הפסקות תשלום בגין אי המצאת אישור תשלום
                (
                    t.code_sug_bakasha = 19 
                    AND t.code_bakasha_detail = 12
                    AND EXISTS (
                        SELECT 1
                        FROM simun_bakashot_leshlicha_lehilan s  
                        WHERE s.seq_bakasha = t.seq_bakasha        
                          AND s.simun = 1
                    )
                    AND SYSDATE >= v_date_open_chodesh
                    AND SYSDATE <  v_date_close_chodesh
                )
                
                -- קבוצה 1: ריצה רגילה - עד סגירת טסט ראשון
                OR (
                    SYSDATE <= v_date_close_test1 
                    AND NOT (t.code_sug_bakasha = 19 AND t.code_bakasha_detail = 12)
                )
                
                -- קבוצה 2: חלון הזמנים מטסט ראשון ועד סוף חודש עיבוד
                OR (
                    -- תוקנה קדימות האופרטורים (סוגריים עוטפים סביב ה-OR)
                    (
                        EXISTS (
                            SELECT 1
                            FROM simun_bakashot_leshlicha_lehilan s  
                            WHERE s.seq_bakasha = t.seq_bakasha        
                              AND s.simun = 1
                        )
                        AND (
                            TRUNC(SYSDATE) < TRUNC(v_date_close_chodesh)
                            OR (TRUNC(SYSDATE) = TRUNC(v_date_close_chodesh) AND t.code_sug_bakasha = 15)
                        )
                        OR 
                        (t.code_sug_bakasha = 19 AND t.code_bakasha_detail IN (19, 6))
                    )
                    AND SYSDATE >= v_date_close_test1
                    AND SYSDATE <= v_date_close_chodesh
              )
          )             
                 --***********   
                 and t.seq_ezor_ovdim = e.seq_ezor_ovdim --and e.pail = 1
                 and cb.code_sug_bakasha = t.code_sug_bakasha
                 order by t.code_sug_bakasha
             ),
    with_calculated_date AS (
        -- שלב ב': חישוב תאריך תחולה
        SELECT 
            b.*, 
            f_get_taarich_tchula(b.seq_bakasha) AS taarich_tchula,
            0 is_mikdama
        FROM 
            bakashot_le_shlicha b
    )
    -- שלב ג': סינון סופי
    SELECT cd.*
    FROM with_calculated_date cd
    WHERE (
            cd.taarich_tchula < LAST_DAY(TRUNC(SYSDATE)) + 1
            OR (cd.code_sug_bakasha = 19 AND cd.code_bakasha_detail IN (6, 19))
          )
      AND ROWNUM < 250

    UNION ALL

    -- חלק ב': ממשק מקדמות
    SELECT 
        t.*, 
        e.seq_ezor_ovdim AS seq_ezor_ovdim1,
        CAST(NULL AS DATE) AS taarich_tchula,
        1 is_mikdama
        FROM v_bakasha_last_status t, code_ezor_ovdim e
        WHERE t.gimla_number IS NOT NULL
        AND t.seq_bakasha IN (
(select v.seq_bakasha--,'poresh' sug_gimlay, p.mispar_zehut, null mispar_zehut_manoach, p.shem_mishpacha, p.shem_prati,
/*case when p.telephon = '000000000' then null else p.telephon end telephone, p.pelephon pelephone, p.email,
v.teur_action, v.taarich_prisha,
n.date_start_zakaut, nvl(n.is_zakai_lmaanak,0) is_zakai_lmaanak,
case  when nvl(n.odef_sherut_chodashim,0) > 0 or nvl(n.odef_sherut_yamim,0) > 0 then 1 else 0 end is_odef_shanim,
ba.CODE_BANK, ba.CODE_SNIF, ba.ACCOUNT_NUMBER,null teur_relative,p.taarich_leda, nvl(n.code_group_prisha,0) code_group_prisha
*/
from poresh p
left join v_bakasha_last_status v on v.seq_porshim = p.porshim_seq
--and v.seq_ezor_ovdim = 206
left join netuney_tik_mechushavim n on n.seq_bakasha = v.seq_bakasha
left join prisha pr on pr.seq_prisha = v.seq_prisha
--left join v_bank_account ba on ba.seq_porshim = p.porshim_seq
left join pk_hilan_prd_mikdamot mk on mk.mispar_zehut = v.mispar_zehut
                                   and mk.seq_bakasha = v.seq_bakasha

where n.date_start_zakaut <= last_day(sysdate) + 1 --< to_date('01/04/2026','dd/mm/yyyy')
and n.code_department = 2
and v.code_sug_bakasha = 1
and v.code_action <> 17
and mk.code_status_mikdama = 1 
and t.seq_ezor_ovdim = e.seq_ezor_ovdim --and e.pail = 1
--and rownum <= 10
)
)
order by 1
)
