           where t.seq_bakasha = v_seq_bakasha
           and t.mispar_misra = 0;
           if v_mispar_misrot_netuney_sachar > 0 then
           v_mispar_misrot_netuney_sachar := 1;
           end if;
       end if;

       if v_mispar_misrot_leprisha > 1 or v_mispar_misrot_netuney_sachar > 1 then
         v_mispar_misrot_sach_hakol := 
         case when v_mispar_misrot_leprisha > v_mispar_misrot_netuney_sachar then v_mispar_misrot_leprisha
         else v_mispar_misrot_netuney_sachar
         end;
       else
         v_mispar_misrot_sach_hakol := 1;
       end if;
         
         
         ----!!!!!!!!!!!!!!!!!! זמני
         if v_mispar_misrot_sach_hakol > 2 then v_mispar_misrot_sach_hakol := 2; end if;
         ----!!!!!!!!!!!!!!!!!! זמני   
         
              
               
       if v_mispar_misrot_netuney_sachar = 0 then v_netuney_sachar_kayamim := false;
                                             else v_netuney_sachar_kayamim := true;
       end if;
       
  v_is_sachar_reforma := 0;
  v_sachar_reforma := 0;
  if v_seq_ezor_ovdim = const_seq_ezor_ovdim_chinuch then
    select count(*)
    into v_is_sachar_reforma
    from chinuch_reforma t
    where t.seq_bakasha = v_seq_bakasha
    --and nvl(t.code_chinuch_alterntive,0) > 0
    ;
    
    if v_is_sachar_reforma > 0 then   --שכר מורים - רפורמה
      v_is_sachar_reforma := 1;
      v_sachar_reforma := 1;
    else
      v_sachar_reforma := 0;
    end if;
  end if;
 
      if v_seq_ezor_ovdim <> const_seq_ezor_ovdim_chinuch or 
          v_seq_ezor_ovdim = const_seq_ezor_ovdim_chinuch and v_netuney_sachar_kayamim and
          v_sachar_reforma <> 1
       then --אין נתוני שכר לחינוך
      if v_code_sug_bakasha = 1  or 
          v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25
           or v_code_sug_bakasha = 13 and v_netuney_sachar_kayamim then --לבדוק תאום מספר משרות בין נתוני שכר וזכאות 
       
       if v_mispar_misrot_leprisha <> v_mispar_misrot_netuney_sachar then
            if is_check_running = 0 then
               clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
               'אין תאום בין נתוני שכר וזכאות (מספר משרות שונה)') || '<br />';
             --continue; 
             else
              check_message_error := 'אין תאום בין נתוני שכר וזכאות (מספר משרות שונה)' || chr_10;
              check_message_error_short := check_message_error;
              check_count_error := check_count_error + 1;
            end if;
       end if;
       end if;
       end if;
    
     v_ptira_besherut_gimlat_chesed := false;
     v_ptirat_poresh := false;
  
     if v_seq_bakasha in (562878,562880,612021) then 
            v_ptira_besherut_gimlat_chesed := true;
     end if;
     /*begin
     select p.taarich_ptira
     into v_taarich_ptirat_poresh
     from poresh p
     where p.mispar_zehut = v_mispar_zehut
      v_seq_bakasha <>  439030--427939--407862--401580 --395802
     -- p.taarich_ptira < to_date('01/04/2019','DD/MM/YYYY')
      (nvl(v_code_group_prisha,0) = 4  v_code_sug_bakasha = 1 or v_code_sug_bakasha <> 1);
     exception
       when others then
         v_taarich_ptirat_poresh := null;
     end;   */
     
     begin
     v_hisachon_pensioni := 0;
     select p.taarich_ptira
     into v_taarich_ptirat_poresh
     from poresh p
     where p.mispar_zehut = v_mispar_zehut
     and v_seq_bakasha <>  439030--427939--407862--401580 --395802
     --and p.taarich_ptira < to_date('01/04/2019','DD/MM/YYYY')
     and (nvl(v_code_group_prisha,0) = 4 and v_code_sug_bakasha = 1 or v_code_sug_bakasha <> 1);
      exception
       when others then
         v_taarich_ptirat_poresh := null;
     end;
     begin
     if v_taarich_ptirat_poresh is not  null and v_code_sug_bakasha = 37 then
       select 1,
       (b.code_kirva -  25),
       b.mispar_zehut_ben_mishpacha,
       trim(both from b.shem_prati) || ' ' || trim(both from b.shem_mishpacha)
       into v_yorshim,
       v_code_kirva_yoresh,
       v_mispar_zehut_yoresh,
       v_shem_yoresh
       from bney_mishpacha b
       where b.seq_porshim = r.seq_porshim
       and b.code_kirva in (26,27,28,29,30)
       group by b.code_kirva - 25,
       b.mispar_zehut_ben_mishpacha,
       trim(both from b.shem_prati) || ' ' || trim(both from b.shem_mishpacha);
       if v_bakasha_seq_bney_mishpacha is not null then
         select b.mispar_zehut_ben_mishpacha
         into v_bakasha_mispar_zehut_ben_mishp
         from bney_mishpacha b
           where b.seq_bney_mishpacha = v_bakasha_seq_bney_mishpacha
           and  b.taarich_ptira is not null;
       end if;
     else
       v_yorshim := 0;
     end if;
      exception
       when others then
            v_yorshim := 0;
            v_code_kirva_yoresh := null;
            v_mispar_zehut_yoresh := null;            
            v_shem_yoresh := null;
     end;
     if v_taarich_ptirat_poresh is null and v_code_sug_bakasha = 26 then          
          select case when hp.cnt > 0 then 1 else 0 end,
            hp.mispar_zehut_ben_mishpacha
            into v_hisachon_pensioni , v_mistz_almana_benzug_sheer
            from poresh p
            left join
                  (select count(*) cnt, b.mispar_zehut_ben_mishpacha, b.seq_porshim
                  from bney_mishpacha b
                  where b.code_kirva = 10 or b.code_relative = 6
                  group by b.mispar_zehut_ben_mishpacha, b.seq_porshim) hp on
           hp.seq_porshim = p.porshim_seq
           where p.mispar_zehut = v_mispar_zehut;
     end if;
     --end; 
    
     v_remainder := mod(nvl(v_code_seif_prisha,0),100);
     if v_remainder = 26 then v_ptira_besherut_gimlat_chesed := true;  end if; 
     if v_remainder = 28 or v_taarich_ptirat_poresh is not null then v_ptirat_poresh := true; end if; 
     
     if v_seq_bakasha = 567082 then 
         v_ptira_besherut_gimlat_chesed := false;
         v_ptirat_poresh := false;
     end if;

     if v_seq_bakasha in (599758,599757,610450) then 
         v_ptira_besherut_gimlat_chesed := true;
         v_ptirat_poresh := false;
     end if;

     if v_code_sug_bakasha = 13 and nvl(v_code_bakasha_detail,0) = 35 /*or v_seq_bakasha = 398913*/ then --גימלת חסד
       v_ptira_besherut_gimlat_chesed := true;
     end if;
     
     if v_code_sug_bakasha = 12 or v_hisachon_pensioni = 1
            /*or v_seq_bakasha = 356732.000*/  then
       --חיסכון פנסיוני - לא להתיחס לעבדת פטירת פורש
      v_ptira_besherut_gimlat_chesed := false;
      v_ptirat_poresh := false;
      v_taarich_ptirat_poresh := null; 
      end if;
      
     /*--שליחת הגדלה 
     if v_seq_bakasha in (562878,562880) then     
      v_ptira_besherut_gimlat_chesed := false;
      v_ptirat_poresh := false;
      v_taarich_ptirat_poresh := null;      
     end if;*/
          
     if v_ptira_besherut_gimlat_chesed or v_ptirat_poresh   then --שאר פנסיוני
       v_code_seif_prisha_leben_katan := 0;
       for b in (select b1.*, n1.date_end_zakaut, n1.achuz_kizba ak
         from bney_mishpacha b1,
         netuney_tik_ben_mishpacha n1 --***************
         where b1.seq_porshim = r.seq_porshim
         and n1.seq_bney_mishpacha = b1.seq_bney_mishpacha
         and n1.seq_netuney_tik_ben_mishpacha =
         (select max (n2.seq_netuney_tik_ben_mishpacha)
         from netuney_tik_ben_mishpacha n2
         left join netuney_tik_mechushavim n3 on
         n3.seq_netuney_tik_mechushavim = n2.seq_netuney_tik_mechushavim
         left join v_bakasha_last_status v on
         v.seq_bakasha = n3.seq_bakasha
         where v.gimla_number = v_gimla_number
         and n2.seq_bney_mishpacha = b1.seq_bney_mishpacha)  --***************  
         and not b1.code_relative is null) loop
       begin
         if b.code_relative in (2,3) and 
            ((b.to_date_sium_zakaut is not null and b.to_date_sium_zakaut>sysdate
            or b.to_date_sium_zakaut is null) or nvl(b.ak,0) > 0 or v_code_sug_bakasha in (19,20))
           and (b.taarich_ptira is null or b.taarich_ptira is not null and b.taarich_ptira > v_date_start_zakaut) then         
 /*        (b.to_date_sium_zakaut is not null and b.to_date_sium_zakaut > sysdate
           or b.to_date_sium_zakaut is null and b.taarich_ptira > v_date_start_zakaut)
           \*((b.to_date_sium_zakaut is not null and b.to_date_sium_zakaut>sysdate
            or b.to_date_sium_zakaut is null) or nvl(b.achuz_kizba,0) > 0 or v_code_sug_bakasha in (19,20))*\
           and (b.taarich_ptira is null or b.taarich_ptira is not null and b.taarich_ptira > v_date_start_zakaut) then*/
           if v_mispar_zehut_ben_katan = 0 then
              v_taarich_leda_ben_katan := b.taarich_leda;
              v_mispar_zehut_ben_katan := b.mispar_zehut_ben_mishpacha;
              v_code_seif_prisha_leben_katan := to_number(to_char(b.code_relative) || substr(to_char(v_code_seif_prisha),2,2));           
          elsif (not v_taarich_leda_ben_katan is null) and (not b.taarich_leda is null) then
               if v_taarich_leda_ben_katan < b.taarich_leda then
                 v_taarich_leda_ben_katan := b.taarich_leda;
                 v_mispar_zehut_ben_katan := b.mispar_zehut_ben_mishpacha;
                 v_code_seif_prisha_leben_katan := to_number(to_char(b.code_relative) || substr(to_char(v_code_seif_prisha),2,2));           
               elsif v_taarich_leda_ben_katan = b.taarich_leda then
                 if v_mispar_zehut_ben_katan < b.mispar_zehut_ben_mishpacha
                    then v_mispar_zehut_ben_katan := b.mispar_zehut_ben_mishpacha;
                         v_code_seif_prisha_leben_katan := to_number(to_char(b.code_relative) || substr(to_char(v_code_seif_prisha),2,2));           
                 end if;
               end if;
           end if;
          end if;
        end;    
     end loop;
     --if v_seq_bakasha = 366147.000 then v_mispar_zehut_ben_katan := 0; end if;
     if v_seq_prisha = 34260 and v_mispar_zehut_ben_katan = 322546821  then 
        v_mispar_zehut_ben_katan := 322546813;
     end if;
     if v_seq_prisha = 130586 and v_mispar_zehut_ben_katan = 329433890  then 
        v_mispar_zehut_ben_katan := 329433882;
     end if;
     if v_seq_prisha = 185254 and v_mispar_zehut_ben_katan = 331485698  then 
        v_mispar_zehut_ben_katan := 331485680;
     end if;
     if v_seq_prisha = 81336 and v_mispar_zehut_ben_katan = 215858713  then 
        v_mispar_zehut_ben_katan := 215858721;
     end if;

        
    end if;
         
   if v_code_sug_bakasha = 12 then    --חיסכון פנסיוני- פרטי בן זוג לשעבר
    begin
       select b.mispar_zehut_ben_mishpacha
        into v_mistz_almana_benzug_sheer
        from bney_mishpacha b
        where b.seq_porshim = r.seq_porshim
        and b.code_kirva = 10;
    exception
     when others then
             clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח:   לא מוגדר בן זוג לשעבר ') ||  '<br />';
             v_error_172_message := v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח:   לא מוגדר בן זוג לשעבר ';
             v_error_172_seq_bakasha := v_seq_bakasha;
       continue;
    end;

     end if;
     
     if is_check_running = 0 then
     clob_log := clob_log ||(v_mispar_zehut || ' - begin')  || '<br/>' ;
      if if_commit_bakasha then
       if (not (v_ptira_besherut_gimlat_chesed or v_ptirat_poresh) /*and
         not(v_taarich_ptirat_poresh is not null and v_code_sug_bakasha in (7,23))*/
         and v_code_sug_bakasha <> 12 and v_hisachon_pensioni = 0)
         or v_yorshim = 1 then
       if_commit := insert_begin_bakasha(v_seq_ld_protocol,
                                         v_seq_ld_protocol_hilan,
                                         v_seq_bakasha,
                                         case when v_yorshim = 1 and v_bakasha_mispar_zehut_ben_mishp is not null then
                                           get_mispar_zehut_fictivi(v_bakasha_mispar_zehut_ben_mishp,v_gimla_number)
                                              else 
                                           get_mispar_zehut_fictivi(v_mispar_zehut,v_gimla_number)
                                         end,
                                         v_gimla_number);
       if not if_commit then if_commit_bakasha := if_commit; end if;
       end if;
 
       if (v_code_sug_bakasha = 12 or v_hisachon_pensioni = 1) and v_mistz_almana_benzug_sheer <> 0 then
       if_commit := insert_begin_bakasha(v_seq_ld_protocol,
                                         v_seq_ld_protocol_hilan,
                                         v_seq_bakasha,
                                         get_mispar_zehut_fictivi(v_mistz_almana_benzug_sheer,v_gimla_number),
                                         v_gimla_number);
       if not if_commit then if_commit_bakasha := if_commit; end if;
         
       end if;
      
       if v_ptirat_poresh or v_ptira_besherut_gimlat_chesed /*or
         v_taarich_ptirat_poresh is not null and v_code_sug_bakasha in (7,23)*/ then
/*       for b in (select * from bney_mishpacha b1  --אלמנ/ה, תלוי, צבא 
         where b1.seq_porshim = r.seq_porshim
         and not b1.code_relative is null
         and b1.code_relative not in (2,3)) loop
*/    
       for b in (select * from bney_mishpacha b1  --אלמנ/ה, תלוי, צבא 
         where b1.seq_porshim = r.seq_porshim
         and not b1.code_relative is null
         and (b1.code_relative not in (2,3,9)
         or (b1.code_relative = 9 and b1.code_kirva = 24 and v_code_sug_bakasha = 26)
         --or (v_code_sug_bakasha = 37 and b1.code_relative = 26 and v_yorshim = 1)
         or b1.code_relative in (2,3) and b1.own_bank_account = 1 and b1.mispar_zehut_ben_mishpacha <> v_mispar_zehut_ben_katan))
       loop
       begin
 
    /*   if v_seq_bakasha = 154344  then 
          if b.mispar_zehut_ben_mishpacha = 067228411 then 
            v_mistz_almana_benzug_sheer := b.mispar_zehut_ben_mishpacha;
          else
            v_mistz_almana_benzug_sheer := 0;
          end if;
       else*/
       v_mistz_almana_benzug_sheer := b.mispar_zehut_ben_mishpacha;
       --end if;
	   --end if;
       
       
       if (v_ptira_besherut_gimlat_chesed or v_ptirat_poresh) and v_mistz_almana_benzug_sheer <> 0 then
       if not(v_code_sug_bakasha =  13 and (v_code_source = 17 and v_code_bakasha_detail <> 37
              or nvl(v_code_bakasha_detail,0) = 37 and b.code_relative = 1)) then --לא לשלוח אחוז קצבה עבור שאר-בן זוג לפגי תוקף
         if_commit := insert_begin_bakasha(v_seq_ld_protocol,
                                           v_seq_ld_protocol_hilan,
                                           v_seq_bakasha,
                                           get_mispar_zehut_fictivi(v_mistz_almana_benzug_sheer,v_gimla_number),
                                           v_gimla_number);
         if not if_commit then if_commit_bakasha := if_commit; end if;
       end if;
       end if;
       end;
       end loop;
       end if;      

       --if v_seq_bakasha = 154344 then v_mispar_zehut_ben_katan := 0; end if;
       
       if (v_ptira_besherut_gimlat_chesed or v_ptirat_poresh/*
         or v_taarich_ptirat_poresh is not null and v_code_sug_bakasha in (7,23)*/)
         and v_mispar_zehut_ben_katan <> 0 then
       if_commit := insert_begin_bakasha(v_seq_ld_protocol,
                                         v_seq_ld_protocol_hilan,
                                         v_seq_bakasha,
                                         get_mispar_zehut_fictivi(v_mispar_zehut_ben_katan,v_gimla_number),
                                         v_gimla_number);
       if not if_commit then if_commit_bakasha := if_commit; end if;
       end if;
     end if; 
     end if;
 
    for e in (select t.code_event_hilan, t.code_semel_hilan, c.code_hishuv, c.code_natun
                      from perm_sug_bakasha_event_hilan t
                      left join code_event_hilan c on
                      c.code_event = t.code_event_hilan
                      and c.code_semel = t.code_semel_hilan
                      where t.code_sug_bakasha = r.code_sug_bakasha
                      and t.pail = 1
                      and (is_check_running = 0
                      or is_check_running = 1 and is_message_full = 0 and t.is_must = 1
                      or is_check_running = 1 and is_message_full = 1)
                      order by 
                      case when v_code_sug_bakasha in (7,23) then t.code_event_hilan end desc,
                      case when v_code_sug_bakasha not in (7,23) then t.code_event_hilan end asc,
                      t.code_semel_hilan  
                      ) loop
     begin
     
     v_code_seif_prisha_lesheer := 0;
     
      if (v_par_code_event is not null and e.code_event_hilan = nvl(v_par_code_event,0) and 
             (v_par_code_semel is null or
             v_par_code_semel is not null and nvl(e.code_semel_hilan,0) = v_par_code_semel)) 
             then continue; end if;
      --if not(e.code_event_hilan = 312 and e.code_semel_hilan=102) then continue; end if;      
      --if  v_seq_bakasha = 44017.000 and e.code_event_hilan <> 218 then continue; end if;
      --if  v_seq_bakasha = 359499 and e.code_event_hilan <> 539 then continue; end if;
      --if  v_seq_bakasha = 338350.000 and e.code_event_hilan <> 567 then continue; end if;
      --if e.code_event_hilan <> 527 and e.code_semel_hilan <> 242 then continue; end if;      
      --if e.code_event_hilan <> 218 and v_seq_bakasha = 355546 then continue; end if;
      --if not(e.code_event_hilan = 527 and e.code_semel_hilan = 240) then continue; end if;      
      --if e.code_event_hilan <> 218 /*and v_seq_bakasha <> 361032*/ then continue; end if;
      --if not(e.code_event_hilan = 303)  then continue; end if;
      --if  not (e.code_event_hilan = 539 /*and e.code_semel_hilan = 1*/)  then continue; end if;
      --if not((e.code_event_hilan = 413 and e.code_semel_hilan in(1443,1445)) or (e.code_event_hilan=527 and e.code_semel_hilan=244)) then continue; end if;
      --if not(e.code_event_hilan = 527 and e.code_semel_hilan = 244) then continue; end if;
      --if (e.code_event_hilan <> 312 or e.code_semel_hilan<> 407) then continue; end if;  
      --if e.code_event_hilan not in (237,567,309)  then continue; end if;
      --if e.code_event_hilan not in (527,309)  then continue; end if;
      --if e.code_semel_hilan not in (2131,2132) then continue; end if; 
      --if e.code_event_hilan not in (205,219)  then continue; end if;
      --if not (e.code_event_hilan = 527 and (e.code_semel_hilan= 242 or e.code_semel_hilan = 239)) then continue; end if; 
       
      --לבקשת שארים מפגי תוקף לשלוח רק אחוז קצבה
      if v_code_sug_bakasha = 13  and v_code_source = 17  and  
        not(e.code_event_hilan = 567 or e.code_event_hilan = 312 and e.code_semel_hilan = 102 and v_code_bakasha_detail = 37)
      then continue; end if;
      
      --TFS 97107 שינוי זכאות עקב הקדמת הקפאה
      if v_seq_bakasha <> 381595 /*תום תקופת פסילה*/ then 
      --if v_code_sug_bakasha = 5 and nvl(v_code_bakasha_detail,0) <> 25 
      if v_code_sug_bakasha = 5 and not (nvl(v_code_bakasha_detail,0) = 25 or v_seq_bakasha = 392484)
        and  (e.code_event_hilan in (200,205,218,219,298,303,535,309,591,413,315) and v_seq_bakasha <> 382004
              or e.code_event_hilan in (200,218,219,298,303,535,309,591,413,315) and v_seq_bakasha = 382004) then continue; end if; --TFS 97107
      end if;
           --אין נתוני שכר לחינוך
       if v_code_sug_bakasha not in (9,10,11) then
