          select count(*)
          into v_mispar_hakpaot
          from v_bakasha_last_status v
          where v.seq_prisha = v_seq_prisha
          and v.code_sug_bakasha = 1
          and v.code_action = 132;
          if v_mispar_hakpaot > 0 then
             pk_prm_utils.insert_action_log_row(210,sysdate,0,const_user_le_berur_shlicha_le_hilan,'ת.ז.:' || ' ' || v_mispar_zehut
             || ' CRM  - הקפאה ',
             null,null,null,v_error_172_seq_bakasha,null);

             pk_prm_utils.insert_action_log_row(98,sysdate,0,const_user_le_berur_shlicha_le_hilan,'ת.ז.:' || ' ' || v_mispar_zehut
             || ' CRM  - הקפאה ',
             null,null,null,v_error_172_seq_bakasha,null);
          elsif v_code_sug_bakasha in(33,35) then
            select count(*)
            into v_33_35_count
            from v_bakasha_last_status v
            where v.code_action in (134,172)
            and v.code_sug_bakasha = v_code_sug_bakasha
            and v.seq_prisha = v_seq_prisha
            and v.seq_bakasha <> v_seq_bakasha;
            if v_33_35_count = 0 then
                           pk_prm_utils.insert_action_log_row(210,sysdate,0,const_user_le_berur_shlicha_le_hilan,'ת.ז.:' || ' ' || v_mispar_zehut
             || ' CRM  - בטיפול ',
             null,null,null,v_error_172_seq_bakasha,null);

             pk_prm_utils.insert_action_log_row(98,sysdate,0,const_user_le_berur_shlicha_le_hilan,'ת.ז.:' || ' ' || v_mispar_zehut
             || ' CRM  - בטיפול ',
             null,null,null,v_error_172_seq_bakasha,null);
           end if;  
          end if;
        end if;
      commit;                                        
      end if;
      return build_out_file(v_seq_ld_protocol, v_seq_ld_protocol_hilan);
     --end if;
  else
     return null;
  end if;
   else return null;
   end if;
    exception
     when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_porshim_events_out: ' || message) || to_char(v_mispar_zehut) || '<br />';       
       return null;
   end;
  ------------------------------------
  function get_hilan_file_name (v_seq_ld_protocol number,
                                v_seq_ld_protocol_hilan number
) return varchar2 is
  v_mispar_mana varchar2(100);
  v_count_id_to_send number;
  v_userenv varchar2(10);
  begin
   select sys_context('userenv', 'DB_NAME') into v_userenv from dual;
   select count(*)
            into v_count_id_to_send
            from v_bakasha_last_status v
            where v.code_action in (134)
            ;
   if v_count_id_to_send > 0 then     
      v_mispar_mana := to_char(v_seq_ld_protocol_hilan);
      v_mispar_mana := substr(trim(v_mispar_mana),length(trim(v_mispar_mana)) - 2,3);
      v_mispar_mana := lpad_zeroez(v_mispar_mana,3);
      return case when v_userenv='xt1' /*prd*/ then 'MPMOA' else 'MPMTA' end ||
                       v_mispar_mana || '.TXT'; --'.ORC';
  else
     return null;
  end if;
    exception
     when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_porshim_events_out: ' || message) ||  '<br />';
  end;
  ------------------------------------
  function check_hilan_out (v_seq_bakasha number,is_full number /*1-full;0-short*/) return varchar2 is
    v_message varchar2(2000) := ' ';
    begin
      is_message_full := is_full;
      check_message_error := '';
      check_message_error_short := '';
      check_message_warning := '';
      check_count_error := 0;
      check_count_warning := 0;
      check_message := '';
      is_check_running := 1;
      v_seq_bakasha_check := v_seq_bakasha;
      v_message := insert_porshim_events_out(0,0);
      return v_message;
     end;
  ------------------------------------
  procedure run_hilan_out (v_seq_ld_protocol number,
                           v_seq_ld_protocol_hilan number,
                           hilan_clob out clob,
                           v_must_send boolean,
                           v_tikim_number out number) is
    v_report  clob;
    v_title   clob;
    v_userenv varchar2(10);
    begin
    if v_must_send then
        hilan_clob := insert_porshim_events_out(v_seq_ld_protocol, v_seq_ld_protocol_hilan);
    else
        clob_log := 'הקובץ לא נשלח; עדיין לא התקבל קובץ היזון חוזר אחרון';
    end if;
    v_tikim_number := v_success_number;
    v_title := 'total success tikim: ' || v_success_number || chr_10 ||
               'total errors tikim: ' || v_error_number || chr_10;
  
    v_report := '<html><body>' || '<h1>' ||
                'The hilan out interface finished' || '</h1>' ||
                '<h1>' || 'total success rows: ' || v_success_number || '<h1/>' ||
                '<h1>' || 'total errors rows: '  || v_error_number   || '<h1/>' ||
                '<h4><html/><body/>' || clob_log || '<html/><body/><h4/>';

    select sys_context('userenv', 'DB_NAME') into v_userenv from dual;
    pk_prm_utils.send_attach(
    case when v_userenv='xt1' then 'liba@mof.gov.il,chavak@mof.gov.il' --prod
                              else 'liba@mof.gov.il' end,
                               'The hilan_out interface finished',
                               v_title,
                               v_report,
                               'html',
                               'hilan_interface.htm');
   
   end;
   ------------------------------------
   function run_hilan_in return number is
    v_report clob;
    v_title  clob;
    v_seq_ld_protocol_hilan number;
    v_userenv varchar2(10);
    begin
    v_seq_ld_protocol_hilan := get_pirtei_hizun;
    v_title := 'total success tikim: ' || v_success_number || chr_10 ||
               'total errors tikim: ' || v_error_number || chr_10;
  
    v_report := '<html><body>' || '<h1>' ||
                'The hilan in interface finished' || '</h1>' ||
                '<h1>' || 'total success rows: ' || v_success_number || '<h1/>' ||
                '<h1>' || 'total errors rows: '  || v_error_number   || '<h1/>' ||
                '<h4><html/><body/>' || clob_log || '<html/><body/><h4/>';

   select sys_context('userenv', 'DB_NAME') into v_userenv from dual;
   pk_prm_utils.send_attach(
   case when v_userenv='xt1' then 'liba@mof.gov.il,chavak@mof.gov.il' --prod
                             else 'liba@mof.gov.il' end,
                               'The hilan_in interface finished',
                               v_title,
                               v_report,
                               'html',
                               'hilan_interface.htm');
    return v_seq_ld_protocol_hilan;                               
   
   end;
   ------------------------------------
   function get_pirtei_hizun return number is
   v_seq_ld_protocol_hilan number;
   v_mispar_zehut number;
   v_mispar_zehut_21 number;
   v_mispar_zehut_old number := 0;
   v_seq_bakasha number;
   v_seq_bakasha_old number;
   v_record_type_old number;
   v_gimla_number number;
   v_seq_ld_log_events number;
   v_hilan_recode_level_message1 varchar2(200);
   v_hilan_recode_level_message2 varchar2(200);
   v_hilan_recode_level_message3 varchar2(200);
   v_error_level number := 0;
   v_user number;
   v_status_acharon number;
   v_error_number_leporesh number :=0;
   v_code_event varchar2(3);
   v_semel_event varchar2(4);
   v_hodaa varchar2(900);
   v_record_type varchar2(2);
   v_seq_bakasha_21 number;
   v_error_number_current number;
   v_code_current_action number;
   v_mispar_minuim number;
   v_mispar_bakashot_for_event number;
   v_seq_bakasha_for_event number;
   v_mispar_shlichot_michtav number;
   v_next_action number;
   cnt number := 0;
   v_code_sug_bakasha number;
   cnt_12_errors number;
   v_is_reforma number;
   v_seq_bakasha_1 number;
   v_seq_bakasha_2 number;
   v_cnt_211 number; 
   v_seq_ezor_ovdim number;
   v_cnt_nispach_maskoret_kovaat number;
   v_2131 number;
   v_2132 number;
   v_hodaa_reversed varchar(900);

   
   procedure get_next_action(v_seq_bakasha number) is
   begin                     
             select count(*)
                   into v_mispar_shlichot_michtav
                   from action_log t
                   where t.seq_bakasha = v_seq_bakasha
                   and t.code_action = 131;
             select w.next_action
                   into v_next_action
                   from v_bakasha_last_status v, workflow w
                   where v.seq_bakasha = v_seq_bakasha
                   and w.code_sug_workflow = v.code_sug_workflow
                   and w.code_action = 136;
                   return;
    end;
   
    begin
     clob_log := '';
     v_hilan_recode_level_message1 := '';
     v_success_number := 0;
     v_error_number := 0;
     
       for r in (select t.record_type,
       t.seq_ld_protocol_hilan,
       t.passport,
       t.mispar_teudat_zehut,
       t.date_hilan,
       t.status,
       t.code_action,
       t.user_name,
       t.code_event,
       t.semel_event,
       t.minuy,
       reverse(t.melel) melel,
       t.gimla_number,
       t.seq_ld_log_events,
       t.mispar_teudat_zehut_ben_mishpa,
       t.load_date,
       t.seq
                 from ld_hilan t
                /*,v_bakasha_last_status v
                where t.mispar_teudat_zehut = v.mispar_zehut
                and v.code_action = 135*/
                /*where exists (select t1.mispar_teudat_zehut
                                  from ld_hilan t1
                                  where t.mispar_teudat_zehut = t1.mispar_teudat_zehut
                                  and t1.record_type = 21)*/
                                  /*where t.mispar_teudat_zehut = '012262655'*/
                 order by t.mispar_teudat_zehut, t.code_event,t.SEMEL_event,t.record_type) loop      
 
       --if r.mispar_teudat_zehut not in (327051975,303831077) then continue; end if;
       v_code_event := case when r.code_event='537' then '237' 
                            when r.code_event = '312' and r.semel_event = '0322' then '303'
                            else r.code_event end;
       v_semel_event := case when r.code_event = '312' and r.semel_event = '0322' then '0000'
                             else r.semel_event end;
                             
       if v_code_event = '312' and v_semel_event = '0565' then continue; end if;  
                                  
       if v_code_event = '539' and v_semel_event not in ('0001','0009') then
         select count(*)
         into v_is_reforma
         from ld_log_events l
         where l.mispar_zehut = to_number(r.mispar_teudat_zehut)
         and l.seq_ld_protocol_hilan = r.seq_ld_protocol_hilan
         and l.code_event = 312
         and l.code_event_semel = 589;
         if v_is_reforma > 0 then continue; end if;
       end if;
         
       v_record_type := r.record_type;
       
       if v_record_type = '20' then continue; end if;
 /*      
       if to_number(r.mispar_teudat_zehut) <> 11303096  
         then continue; end if;
*/        
       --if to_number(r.mispar_teudat_zehut) < 9666470 then continue; end if;
       --12447439
       --12618021 - 51249035
       --51251676 - 57146912
       --57170375
       --<>58188020 
 
       if v_record_type = '31' and 
/*         (r.melel like '%סעיף תקציב אינו נמצא בטבלת סעיפי תקציב%'  and r.melel like '%000000000%' --שליחת קוד אוכלוסיה 00
                                                                --לקוד אוכלוסיה לא ידוע לבקשות שומות מבקשת פרישה לגמלאות ו שארים
          or */
          r.melel like '%לשאר בוצעה העתקת רכיבי שכר בעבר%' --) 
          then v_record_type := '32';    --הודעות אזהרה ולא שגיאה     
       end if;
       
       if v_record_type = '21' then 
         v_mispar_zehut_21 := to_number(r.mispar_teudat_zehut);
         
       else v_mispar_zehut := to_number(r.mispar_teudat_zehut);
       
       if   v_mispar_zehut_old <> to_number(r.mispar_teudat_zehut) then  
         cnt := cnt + 1;
/*         if cnt = 440 then
           cnt := cnt;
         end if;          
*/       end if;
        
       if v_mispar_zehut_old = 0 then 
          clob_log := 'protocol_hilan_number: ' ||  to_char(v_seq_ld_protocol_hilan) || '<br />';
       end if;
       
       --חתון בשימוש בחישוב מספר משרה(חשוב במקרה של כמה משרות)
       if v_mispar_zehut <> 0 then       
         select count(cnt.minuy) 
         into v_mispar_minuim
         from 
         (select t.minuy
         from ld_hilan t
         where to_number(t.mispar_teudat_zehut) = v_mispar_zehut
         and t.minuy <> 0
         group by t.minuy
         order by t.minuy) cnt;
       end if;
       
        if r.mispar_teudat_zehut <> 0  and v_record_type in ('30','31') then
            v_mispar_bakashot_for_event := 0;
            v_seq_bakasha_for_event := 0;
            --if r.minuy = 1 then
            for b in   
                (select distinct t.seq_bakasha, t.mispar_gimla, v.code_sug_bakasha
                 from ld_log_events t, v_bakasha_last_status v
                 where t.seq_ld_protocol_hilan = r.Seq_Ld_Protocol_Hilan
                 and t.mispar_zehut = r.mispar_teudat_zehut
                 and v.seq_bakasha = t.seq_bakasha
                 --and (t.seq_ld_log_events = r.seq_ld_log_events or r.seq_ld_log_events is null)
                 and (v_record_type = '30' and t.code_trigger = 0
                      or v_record_type = '31' and t.code_trigger = 2)
                 and t.code_event = to_number(v_code_event)          
                 and t.code_event_semel = to_number(v_semel_event)                 
                 and (r.minuy = 0 or r.minuy > 0 and t.mispar_gimla = to_number(r.gimla_number))
                 )loop
                 begin
                 if v_seq_bakasha_for_event <> b.seq_bakasha then
                    v_mispar_bakashot_for_event := v_mispar_bakashot_for_event + 1;
                 end if;
                 v_seq_bakasha_for_event := b.seq_bakasha;
                 end;
            end loop;
            
            if v_mispar_bakashot_for_event > 1 then
/*            if v_mispar_bakashot_for_event = 2 then
            end if;
*/            for b in
              (select distinct t.seq_bakasha
                 from ld_log_events t
                 where t.seq_ld_protocol_hilan = r.Seq_Ld_Protocol_Hilan
                 and t.mispar_zehut = r.mispar_teudat_zehut
                 and t.code_event = to_number(v_code_event)          
                 and t.code_event_semel = to_number(v_semel_event)
                 and (r.minuy = 0 or r.minuy > 0 and t.mispar_gimla = to_number(r.gimla_number))) loop
            begin
            v_seq_bakasha_for_event := b.seq_bakasha;
            v_hodaa := 'לפורש ' || r.mispar_teudat_zehut || ' (בקשה: ' || v_seq_bakasha_for_event || ' )'  || ' אירוע '
            || v_code_event || ', ' || v_semel_event  || ' נשלח יותר  מפעם אחת בשליחה' || ' ' || r.Seq_Ld_Protocol_Hilan  ;
            v_error_number := v_error_number + 1;
            clob_log := clob_log || 'error - ' || v_code_event || ', ' || v_semel_event  || ', ' || v_mispar_zehut  || ' - ' || v_hodaa || '<br/>' ;
            pk_prm_utils.insert_action_log_row(172,sysdate,0,const_user_le_berur_shlicha_le_hilan,'היזון חוזר: ' || v_hodaa,null,null,null,v_seq_bakasha_for_event,null);
            commit;
            end;
            end loop;        
            continue;
            else
              v_seq_bakasha := v_seq_bakasha_for_event;
            end  if;
            end if;

       if not v_seq_bakasha_old  is null and v_seq_bakasha_old <> v_seq_bakasha then
            v_hodaa := trim(get_hodaot(v_seq_ld_protocol_hilan,v_seq_bakasha_old));
               if v_error_number_leporesh = 0 then
                 v_success_number := v_success_number + 1;
        select count(*) 
        into v_is_mikdama
        from pk_hilan_prd_mikdamot t
        where t.seq_bakasha = v_seq_bakasha_old 
        and t.code_status_mikdama = 2;
        if v_is_mikdama > 0 then 
          select t.m_2131, t.m_2132
            into v_2131, v_2132
            from pk_hilan_prd_mikdamot t
            where t.seq_bakasha = v_seq_bakasha_old 
            and t.code_status_mikdama = 2;
          update pk_hilan_prd_mikdamot t
           set t.code_status_mikdama = 3,
               t.date_status_mikdama = sysdate
               where t.seq_bakasha = v_seq_bakasha_old 
               and t.code_status_mikdama = 2;       
          pk_prm_utils.insert_action_log_row(233,sysdate,0,0,get_teur_action(233),null,null,null,v_seq_bakasha_old,null);
          pk_prm_utils.insert_action_log_row
             (45, sysdate, 0, null, 
             'הנ"ל '
             ||
             'קבל/ה'
             ||      
             ' מקדמה בגין קצבה בסה"כ 6000 ¤ '
             || ' ' ||
             case when v_2132 <> 0 then 'ומקדמה בגין מענק בסה"כ 10,000 ¤' end,
             null, null, null, v_seq_bakasha_old, null);          
        end if;
         --------------------------
        
        --begin
        select t.code_action
        into v_code_current_action
        from v_bakasha_last_status t
        where t.seq_bakasha = v_seq_bakasha_old;
/*exception
    when others then
        v_code_current_action := null;
        status  := 0;
        message := sqlerrm;
        clob_log := clob_log || 'error - ' || v_code_event || ', ' || v_semel_event  || ', ' || v_mispar_zehut  || ' - ' || message || '<br/>' ;
        --v_seq_bakasha_old := v_seq_bakasha;        
        --continue;        
        end;*/
        --------------------------
                 if v_code_current_action = 135 then
                   
                  cnt_12_errors := 0;                         --TFS 103553 - BEGIN
                  select v.code_sug_bakasha, v.seq_ezor_ovdim
                  into v_code_sug_bakasha, v_seq_ezor_ovdim
                  from v_bakasha_last_status v
                  where v.seq_bakasha = v_seq_bakasha_old;
                  if v_code_sug_bakasha = 12 then  --חיסכון פנסיוני - 2 ת.ז.
                    select count(*)
                    into cnt_12_errors
                    from ld_log_events t, ld_hilan l
                    where t.seq_bakasha = v_seq_bakasha_old
                    and t.mispar_zehut <> v_mispar_zehut
                    and l.seq_ld_protocol_hilan = v_seq_ld_protocol_hilan
                    and t.seq_ld_protocol_hilan = v_seq_ld_protocol_hilan
                    and t.mispar_zehut = to_number(l.mispar_teudat_zehut)
                    and mod(l.record_type,10) = 1;                 
                  end if;
                  
                  if cnt_12_errors = 0 then                 --TFS 103553 - END
                   v_cnt_211 := 0;
                   if v_seq_ezor_ovdim in (206,43) then
                     select count(*)
                     into v_cnt_211
                     from action_log a
                     where a.seq_bakasha = v_seq_bakasha_old
                     and a.code_action = 211;
                   end if;

                  pk_prm_utils.insert_action_log_row(136,sysdate,0,0,v_hodaa,null,null,null,v_seq_bakasha_old,null);                           
                   --לא לשלוח מכתב פעמים
                   get_next_action(v_seq_bakasha_old);
/*                   if v_mispar_shlichot_michtav > 0 and v_next_action = 129 --אישור שליחת מכתב
                     then pk_prm_utils.insert_action_log_row(98,sysdate,0,0,null,null,null,null,v_seq_bakasha_old,null);
                   elsif v_cnt_211 = 0 then pk_prm_utils.insert_actions_for_bakasha(v_seq_bakasha_old);
                   else pk_prm_utils.insert_action_log_row(212,sysdate,0,0,null,null,null,null,v_seq_bakasha_old,null);
                   end if;
*/              
                   if v_mispar_shlichot_michtav = 0 and v_code_sug_bakasha = 14 and v_next_action = 129 then
                      select count(*)
                      into v_cnt_nispach_maskoret_kovaat
                      from document_bakasha db
                      left join document d on
                      d.seq_document = db.seq_document
                      where db.seq_bakasha = v_seq_bakasha_old
                      and d.seq_document_type = 156
                      and db.pail = 1;
                      if v_cnt_nispach_maskoret_kovaat = 0 then
                        pk_prm_utils.insert_action_log_row(98,sysdate,0,0,null,null,null,null,v_seq_bakasha_old,null);
                      else
                        pk_prm_utils.insert_actions_for_bakasha(v_seq_bakasha_old);
                      end if;
                   elsif v_mispar_shlichot_michtav > 0 and v_next_action = 129 --אישור שליחת מכתב
                     then pk_prm_utils.insert_action_log_row(98,sysdate,0,0,null,null,null,null,v_seq_bakasha_old,null);
                   elsif v_cnt_211 = 0 then pk_prm_utils.insert_actions_for_bakasha(v_seq_bakasha_old);
                   else pk_prm_utils.insert_action_log_row(212,sysdate,0,0,null,null,null,null,v_seq_bakasha_old,null);
                   end if;

                   end if;
                end if;
              else 
 /*                  select count(*) 
                  into v_is_mikdama
                  from pk_hilan_prd_mikdamot t
                  where t.seq_bakasha = v_seq_bakasha_old
                  and t.code_status_mikdama in (2,4);
                  if v_is_mikdama = 1 then
                     update pk_hilan_prd_mikdamot t
                     set t.code_status_mikdama = 4,
                         t.date_status_mikdama = sysdate
                         where t.seq_bakasha = v_seq_bakasha_old
                         and t.code_status_mikdama in (2,4);     
                    pk_prm_utils.insert_action_log_row(234,sysdate,0,0,get_teur_action(234),null,null,null,v_seq_bakasha_old,null);       
                  end if;
