                   else pk_prm_utils.insert_action_log_row(212,sysdate,0,0,null,null,null,null,v_seq_bakasha_old,null);
                   end if;
               end if;
               else
               
               v_error_number := v_error_number + 1;
/*                  select count(*) 
                  into v_is_mikdama
                  from pk_hilan_prd_mikdamot t
                  where t.seq_bakasha = v_seq_bakasha_old
                  and t.code_status_mikdama in (2,4);
                  if v_is_mikdama > 0 then
                  update pk_hilan_prd_mikdamot t                
                     set t.code_status_mikdama = 4,
                         t.date_status_mikdama = sysdate
                         where t.seq_bakasha = v_seq_bakasha_old
                         and t.code_status_mikdama in (2,4);       
                     pk_prm_utils.insert_action_log_row(234,sysdate,0,0,get_teur_action(234),null,null,null,v_seq_bakasha_old,null);
                  end if;*/

              if v_code_current_action = 135 then
               if instr(v_hodaa,'חסרים ארועי חובה',
