                   pk_prm_utils.insert_action_log_row(172,sysdate,0,const_user_le_berur_shlicha_le_hilan,'היזון חוזר: ' || v_hodaa,null,null,null,v_seq_bakasha,null);         
                else
                   pk_prm_utils.insert_action_log_row(172,sysdate,0,const_user_le_berur_shlicha_le_hilan,'היזון חוזר: ' || v_hodaa,null,null,null,v_seq_bakasha,null);         
/*                 pk_prm_utils.insert_action_log_row(137,sysdate,0,0,v_hodaa,null,null,null,v_seq_bakasha,null);         
                 if (not v_user is null) then
                 pk_prm_utils.insert_action_log_row(49,sysdate,0,v_user,'הוחזר לטיפול אחרי כשלון קליטה בחילן' || v_hodaa,null,null,null,v_seq_bakasha,null);         
                 pk_prm_utils.insert_action_log_row(v_status_acharon,sysdate,0,v_user,'הוחזר לטיפול אחרי כשלון קליטה בחילן' || v_hodaa,null,null,null,v_seq_bakasha,null);         
               end if;
*/              end if;
              else
