/*--בדיקת תיקים תקועים במצב 135 - נשלח לחילו
       clob_log := clob_log ||  '<br/>' ;
       clob_log := clob_log || 'בדיקת תיקים תקועים במצב 135 - נשלח לחילו' || '<br/>' ;       
          (select distinct t.seq_bakasha
