       return 0;   
   end;
   
procedure test_name(v_seq_bakasha number) is
  v_shem_mishpacha varchar2(50);
  v_shem_prati varchar2(50);
  v_shem_nosaf varchar2(50); 
  begin  
    select  p.shem_mishpacha, p.shem_prati
            into v_shem_mishpacha, v_shem_prati
                from v_bakasha_last_status t
                left join poresh p on
                p.porshim_seq = t.seq_porshim
                where t.seq_bakasha = v_seq_bakasha;
    if length(trim(v_shem_prati)) > 10 and instr(trim(v_shem_prati),' ') > 0 then
      v_shem_prati := replace(v_shem_prati,'-',' ');
      v_shem_prati := replace(v_shem_prati,'(',' ');
      v_shem_prati := replace(v_shem_prati,')',' ');
      v_shem_prati := replace(v_shem_prati,'  ',' ');    
      v_shem_nosaf := substr(trim(v_shem_prati),instr(trim(v_shem_prati),' '),100);
      v_shem_prati := substr(trim(v_shem_prati),1,instr(trim(v_shem_prati),' ')-1);
    end if;
    exception
    when others then
       status  := 0;
       message := sqlerrm;
    end;
-- end;
 
procedure reverse_address is
    str_reversed varchar2(1000) := '';
    is_number    boolean := false;
    str_mispar   varchar2(20);
    cnt number;
  begin
    cnt := 0;
    --dbms_output.enable(9999999999999999999999999999999999999999999999999999999999999999999);
    for r in (/*(select distinct b.mispar_zehut, a.street, a.Seq_Address, a.date_update
                from v_bakasha_last_status b
                left join address a
                  on a.Seq_Bakasha = b.seq_bakasha
               where (nvl(a.street, '*') not like '*')
                 \*and b.mispar_zehut not in
                     (select distinct bb.mispar_zehut
                        from v_bakasha_by_zheut bb
                       where bb.date_bakasha >
                             to_date('08042019', 'ddmmyyyy'))*\
                 and exists
               (select *
                        from action_log al
                       where al.code_action = 145
                         and al.Seq_Bakasha = b.seq_bakasha)
               and a.date_update is not null
               and a.date_update <  to_date('02052019', 'ddmmyyyy'))
minus               
(select distinct b.mispar_zehut, a.street, a.Seq_Address, a.date_update
                from v_bakasha_last_status b
                left join address a
                  on a.Seq_Bakasha = b.seq_bakasha
               where (nvl(a.street, '*') not like '*')
                 and b.mispar_zehut not in
                     (select distinct bb.mispar_zehut
                        from v_bakasha_by_zheut bb
                       where bb.date_bakasha >
                             to_date('08042019', 'ddmmyyyy'))
                 and exists
               (select *
                        from action_log al
                       where al.code_action = 145
                         and al.Seq_Bakasha = b.seq_bakasha))
               */
                              select a.street, a.seq_address from address a
               where a.seq_address in(
528994
)) loop
      str_reversed := '';
      str_reversed := reverse_mispar(r.street);
   
      update address a
         set a.Street = str_reversed
       where a.Seq_Address = r.Seq_Address;
       cnt := cnt +1;
    end loop;
  commit;
  end;
  end;
/

create or replace package body prm_system_copy.pk_hilan_prd_sachar_reforma is

  const_seq_ezor_ovdim_chinuch constant number := 206;
