   function check_mz_exists_in_varray (/*mispar_zehut_2218 mispar_zehut_2218_array, */
     v_mispar_zehut number,
     v_mispar_gimla number) return boolean is
   begin
     for i in 1..mispar_zehut_2218.count
     loop
       if v_mispar_zehut = mispar_zehut_2218(i) and v_mispar_gimla = mispar_gimla_2218(i) then
           return true;
       end if;      
     end loop;
     return false;
    end;
  ------------------------------------ 
    function eraze_event_315 (v_seq_ld_protocol number,
                         v_seq_ld_protocol_hilan number,
                         v_seq_bakasha number,
                         v_mispar_zehut number,
                         v_gimla_number number,
                         v_seq_ezor_ovdim number,
                         v_code_sug_bakasha number,
                         v_mispar_zehut_sheer_benzug number) return boolean is
      v_date_report_current date;
      begin
         for r in (
         select distinct t.mispar_zehut, t.code_trigger, t.code_event, t.code_event_semel, t.date_report, 
         substr(t.record_hilan,3,9) semel_unique
         from ld_log_events t
         left join v_bakasha_last_status v on
         v.seq_bakasha = t.seq_bakasha
         where /*t.seq_bakasha <> v_seq_bakasha
         and */t.seq_ld_protocol_hilan < v_seq_ld_protocol_hilan
         and t.code_event = 315
         and t.code_event_semel in (576,184)
         and t.code_trigger = 2
         and v.seq_prisha = 
         (select v1.seq_prisha   
         from v_bakasha_last_status v1
         where v1.seq_bakasha = v_seq_bakasha
         )
         and t.seq_ld_protocol_hilan = 
         (select max(t1.seq_ld_protocol_hilan)
         from ld_log_events t1
         where t1.seq_bakasha = t.seq_bakasha
         and t1.code_record_level is not null
         --and t1.seq_ld_protocol_hilan = t.seq_ld_protocol_hilan
         )
         and t.date_report >= 
         (select max(t1.date_report)
         from ld_log_events t1
         where t1.seq_bakasha = t.seq_bakasha
         and t1.seq_ld_protocol_hilan = t.seq_ld_protocol_hilan
         and t1.code_event = 315
         and t1.code_event_semel in (576,184)
         and t1.code_trigger = 2
         )
         minus
         select  t.mispar_zehut, t.code_trigger, t.code_event, t.code_event_semel, t.date_report,
         substr(t.record_hilan,3,9)
         from ld_log_events t
         where t.seq_bakasha = v_seq_bakasha
         and t.seq_ld_protocol_hilan = v_seq_ld_protocol_hilan
         and t.code_event = 315
         and t.code_event_semel in (576,184)
         and t.code_trigger = 2
         )
         loop
           
         select max(t2.date_report)
         into v_date_report_current
         from ld_log_events t2
         where t2.seq_bakasha = v_seq_bakasha
         and t2.seq_ld_protocol_hilan = v_seq_ld_protocol_hilan
         and t2.code_event = 315
         and t2.code_event_semel in (576,184)
         and t2.code_trigger = 2;
         
         --if v_date_report_current > r.date_report then return false; end if;
         
           ld_log_events_record.code_event := r.code_event;
           ld_log_events_record.code_event_semel := r.code_event_semel;
 
           prepare_trigger_0(v_seq_ld_protocol,
                      v_seq_ld_protocol_hilan,
                      v_seq_bakasha,
                      case when v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug else v_mispar_zehut end,
                      v_gimla_number,
                      true,
                      v_date_report_current,--r.date_report,
                      '  ' || rpad_blanks(r.semel_unique,9));
         if not insert_event then return false; end if;
         end loop;
         return true;
      end;
  ------------------------------------ 
  function check_mz_exists_in_varr_reform (/*mispar_zehut_2218 mispar_zehut_2218_array, */
     v_mispar_zehut number,
     v_code_event number,
     v_code_semel number,
     v_semel_unique varchar2) return boolean is
     begin
      for i in 1..sheer_reforma_mispar_zehut.count
     loop
       if  v_mispar_zehut = sheer_reforma_mispar_zehut(i)
       and v_code_event   = sheer_reforma_code_event(i)
       and v_code_semel   = sheer_reforma_code_semel(i)
       and (v_semel_unique is null or
            v_semel_unique is not null and v_semel_unique = sheer_reforma_semel_unique(i))
       then
           return true;
       end if;      
     end loop; 
     sheer_reforma_mispar_zehut.extend();
     sheer_reforma_mispar_zehut(v_cnt_events) := v_mispar_zehut;
     sheer_reforma_code_event.extend();
     sheer_reforma_code_event(v_cnt_events) := v_code_event;
     sheer_reforma_code_semel.extend();
     sheer_reforma_code_semel(v_cnt_events) := v_code_semel;
     sheer_reforma_semel_unique.extend();
     sheer_reforma_semel_unique(v_cnt_events) := v_semel_unique;
     v_cnt_events := v_cnt_events + 1;
     return false;   
   end;
