   function check_bakasha_exists_in_varray (bakashot bakashot_array, v_seq_bakasha number) return boolean is
   begin
     for i in 1..bakashot.count
     loop
       if v_seq_bakasha = bakashot(i) then
           return true;
       end if;      
     end loop;
     return false;
    end;
  ------------------------------------ 
  function check_hatama_laheskem (v_mispar_zehut number,
                                  v_seq_bakasha number,
                                  v_seq_prisha number,
                                  v_code_sug_bakasha number) return number is
   v_is_bakashat_reforma number := 0;
   v_is_prishat_reforma number := 0;
   v_count number;
   begin
     v_taarich_312_180 := null;
     if v_code_sug_bakasha = 14 then
       select count(*)
       into v_count
       from chinuch_reforma r
       where r.seq_bakasha = v_seq_bakasha;
       if v_count > 0 then
         v_is_bakashat_reforma := 1;
       end if; 
               
       select count(*)
       into v_count
       from v_bakasha_last_status v, chinuch_reforma r
       where v.seq_prisha = v_seq_prisha
       and r.seq_bakasha = v.seq_bakasha
       and v.seq_bakasha <> v_seq_bakasha
       and v.code_action = 98;
       if v_count > 0 then
         v_is_prishat_reforma := 1;
       end if;
     end if;
     if v_is_bakashat_reforma = v_is_prishat_reforma then
       return 1;
     else
       if v_is_bakashat_reforma = 1 then
         select max(l.date_report)
         into v_taarich_312_180
         from v_bakasha_last_status vs
         left join ld_log_events l
         on l.seq_bakasha = vs.seq_bakasha
         left join chinuch_reforma cr on
         cr.seq_bakasha = vs.seq_bakasha
         where vs.seq_prisha = v_seq_prisha
         and cr.seq_bakasha is null
         and l.code_event = 312
         and l.code_event_semel = 180
         and l.code_trigger = 2;
       end if;
       return 0;
     end if;
   end;
  ------------------------------------ 
  procedure is_heskem_hadash(v_seq_bakasha number,
                          v_mispar_zehut_amiti number,
                          v_gimla_number number,
                          v_code_sug_bakasha number,
                          v_mispar_zehut_sheer_benzug_amiti number
                          ) is
    v_is_butal_event3120180 number;
    v_is_event3120180_sachar number;
 
    begin
      select count(*) 
        into v_is_event3120180
        from porshim_not_send_to_hilan ph, poresh p
        where ph.taarich_yetzira is null --מופסק זמנית
        and p.mispar_zehut = v_mispar_zehut_amiti
        and (ph.mispar_zehut = v_mispar_zehut_amiti and p.taarich_ptira is null
        or ph.mispar_zehut_manoah = v_mispar_zehut_amiti and p.taarich_ptira is not null
        and ph.mispar_zehut = v_mispar_zehut_sheer_benzug_amiti);
      if v_is_event3120180 > 0 then
          if v_mispar_zehut_sheer_benzug_amiti <> 0 then
            update porshim_not_send_to_hilan ph
              set ph.taarich_yetzira = trunc(sysdate),
              ph.remarks = ph.remarks || '---' || 'חזר לפעילות'
            where ph.taarich_yetzira is null
            and ph.mispar_zehut_manoah = v_mispar_zehut_amiti
            and ph.mispar_zehut = v_mispar_zehut_sheer_benzug_amiti;
          else
            update porshim_not_send_to_hilan ph
              set ph.taarich_yetzira = trunc(sysdate),
              ph.remarks = ph.remarks || '---' || 'חזר לפעילות'
            where ph.taarich_yetzira is null
            and ph.mispar_zehut_manoah = 0
            and ph.mispar_zehut = v_mispar_zehut_amiti;
          end if;
          return;           --מופסק זמנית - להחזיר לפעילות
      end if;
      select count(*)
        into v_is_event3120180
        from porshim_not_send_to_hilan ph, poresh p
        where ph.taarich_yetzira is not null
        and p.mispar_zehut = v_mispar_zehut_amiti
        and (ph.mispar_zehut = v_mispar_zehut_amiti and p.taarich_ptira is null
        or ph.mispar_zehut_manoah = v_mispar_zehut_amiti and p.taarich_ptira is not null
        and ph.mispar_zehut = v_mispar_zehut_sheer_benzug_amiti);
     if v_is_event3120180 = 0  then
      if v_taarich_ptirat_poresh is null or v_ptira_besherut_gimlat_chesed then      
       select count(*)
       into v_is_event3120180
       from v_bakasha_last_status v, prisha pr
       where pr.gimla_number = v_gimla_number
       and v.seq_prisha = pr.seq_prisha
       and v.code_sug_bakasha = 1
       and v.taarich_prisha >= to_date('31/08/2020','DD/MM/YYYY');
       if v_is_event3120180 > 0 then
         insert into porshim_not_send_to_hilan ph
         (ph.mispar_zehut,
          ph.mispar_zehut_manoah,
          ph.taarich_yetzira,
          ph.taarich_bitul,
          ph.id_user,
          ph.remarks)
         values
         (case when v_mispar_zehut_sheer_benzug_amiti = 0 then 
               v_mispar_zehut_amiti
          else 
               v_mispar_zehut_sheer_benzug_amiti end,
          case when v_mispar_zehut_sheer_benzug_amiti = 0 then 0
          else
               v_mispar_zehut_amiti end,
          trunc(sysdate),
          null,
          0,
          'התווסף בממשק')
          ;
          v_is_event3120180 := 1;
          return;
        end if;
      end if;
      if v_ptira_besherut_gimlat_chesed and v_is_event3120180 = 0 or v_ptirat_poresh then
          select count(*)
          into v_is_event3120180
          from porshim_not_send_to_hilan ph, poresh p
          where p.mispar_zehut = v_mispar_zehut_amiti
          and ph.mispar_zehut = v_mispar_zehut_amiti and p.taarich_ptira is not null
          and ph.taarich_bitul is null;
          if v_is_event3120180 > 0 then
           insert into porshim_not_send_to_hilan ph
           (ph.mispar_zehut,
            ph.mispar_zehut_manoah,
            ph.taarich_yetzira,
            ph.taarich_bitul,
            ph.id_user,
            ph.remarks)
           values
           (v_mispar_zehut_sheer_benzug_amiti,
            v_mispar_zehut_amiti,          
            trunc(sysdate),
            null,
            0,
            'התווסף בממשק')
            ; 
       end if;
       end if;
     else
        select count(*)
          into v_is_event3120180_sachar
          from netuney_sachar n
          where n.seq_bakasha = v_seq_bakasha
          and n.code_sug_maskoret = 1;
          -- לא לשלוח אירוע 312/0180 עבור גמלאי מסומן אם אין נתוני שכר בבקשה
          if v_is_event3120180_sachar = 0 then 
            v_is_event3120180 := 0; 
            return;
          end if;  
        select count(*)
         into v_is_butal_event3120180
         from porshim_not_send_to_hilan ph, poresh p
         where p.mispar_zehut = v_mispar_zehut_amiti
         and (ph.mispar_zehut = v_mispar_zehut_amiti and p.taarich_ptira is null
         or ph.mispar_zehut_manoah = v_mispar_zehut_amiti and p.taarich_ptira is not null) 
         and ph.taarich_bitul is not null;
        if v_is_butal_event3120180 > 0 then v_is_event3120180 := 0; end if;     
     end if;
   end;
  ------------------------------------ 
  procedure build_check_message(v_severe_level number, -- 1-error; 2--warning;
                                v_event_hilan varchar2,
                                v_semel_hilan varchar2,
                                v_code_remark number,
                                v_message varchar2,
                                v_ora_error_message varchar2  default '') is
  v_teur_remark varchar2(100);
  v_teur_semel varchar2(100);
  v_teur_event varchar2(100);
  begin
       select t.teur_remark
       into v_teur_remark
       from check_hilan_remarks t               
       where t.code_remark = v_code_remark;
       
       begin
       select t.teur_semel, t.teur_event
       into v_teur_semel, v_teur_event
       from code_event_hilan t
       where t.code_event = to_number(v_event_hilan)
       and t.code_semel = to_number(v_semel_hilan);
       exception
         when others then
           select t.teur_event
           into v_teur_semel
           from code_event_hilan t
           where t.code_event = to_number(v_event_hilan);
       end;     
       
       if v_severe_level = 1 then
         check_message_error := trim(check_message_error) || 'event_hilan: ' || v_event_hilan ||
                                '; semel_hilan: ' || v_semel_hilan ||
                                '---' || case when trim(v_teur_semel) is not null then v_teur_semel else v_teur_event end || '---;' ||
                                trim(v_teur_remark) || '  -  ' ||
                                v_message;
         check_message_error_short := trim(check_message_error_short) || trim(v_teur_remark) || chr_10;
         if v_ora_error_message is not null then
              check_message_error := trim(check_message_error) || '  -  ' || v_ora_error_message;
         end if;
         check_message_error := trim(check_message_error) || chr_10;
         check_count_error := check_count_error + 1;
       else
         check_message_warning := trim(check_message_warning) || 'event_hilan: ' || v_event_hilan ||
                                '; semel_hilan: ' || v_semel_hilan ||
                               '---' || case when trim(v_teur_semel) is not null then v_teur_semel else v_teur_event end || '---;' ||
                                  trim(v_teur_remark) || '  -  ' ||
                                  v_message;
         if v_ora_error_message is not null then
              check_message_warning := trim(check_message_warning) || '  -  ' || v_ora_error_message;
         end if;
         check_message_warning := trim(check_message_warning) || chr_10;
         check_count_warning := check_count_warning + 1;
      end if;
  end;                                                    
    
  ------------------------------------
  --הוספת אירוע חדש
  function insert_event return boolean is
    begin
    if ld_log_events_record.code_trigger <> 0 or ld_log_events_record.code_event = 0 then
       ld_log_events_record.seq_ld_log_events := ld_log_events_seq.nextval;
    end if;
    insert into ld_log_events t
     (  t.seq_ld_protocol,
        t.seq_ld_protocol_hilan,
        t.seq_ld_log_events,
        t.date_create,
        t.mispar_zehut,
        t.code_trigger,
        t.code_event,
        t.code_event_semel,
        t.gorem_medaveach,
        t.seq_bakasha,
        t.mispar_gimla,
        t.date_report,
        t.record_hilan )
     values ( ld_log_events_record.seq_ld_protocol,
        ld_log_events_record.seq_ld_protocol_hilan,
        ld_log_events_record.seq_ld_log_events,
        ld_log_events_record.date_create,
        ld_log_events_record.mispar_zehut,
        ld_log_events_record.code_trigger,
        ld_log_events_record.code_event,
        ld_log_events_record.code_event_semel,
        ld_log_events_record.gorem_medaveach,
        ld_log_events_record.seq_bakasha,
        ld_log_events_record.mispar_gimla,
        ld_log_events_record.date_report,
        ld_log_events_record.record_hilan );
        v_events_count_for_bakasha := v_events_count_for_bakasha + 1;
    return true;
    exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event: ' || message) ||  '<br />';
      return false;
   end;

  ------------------------------------
  function insert_begin_protocol(v_seq_ld_protocol number, v_seq_ld_protocol_hilan number) return boolean is
  begin
    ld_log_events_record.seq_ld_protocol := v_seq_ld_protocol;
    ld_log_events_record.seq_ld_protocol_hilan := v_seq_ld_protocol_hilan;
    ld_log_events_record.date_create := sysdate;
    ld_log_events_record.mispar_zehut := 0;
    ld_log_events_record.code_trigger := 0;
    ld_log_events_record.code_event := 0;
    ld_log_events_record.code_event_semel := 0; 
    ld_log_events_record.gorem_medaveach := 2292;
    ld_log_events_record.seq_bakasha := 0;
    ld_log_events_record.mispar_gimla := 0;
    ld_log_events_record.date_report := sysdate;
    ld_log_events_record.record_hilan := ' ';
   
    return insert_event;
  end;
  ------------------------------------  
  function insert_begin_bakasha(v_seq_ld_protocol number,
                             v_seq_ld_protocol_hilan number,
                             v_seq_bakasha number,                  
                             v_mispar_zehut number,
                             v_gimla_number number) return boolean is
    begin
    ld_log_events_record.seq_ld_protocol := v_seq_ld_protocol;
    ld_log_events_record.seq_ld_protocol_hilan := v_seq_ld_protocol_hilan;
    ld_log_events_record.date_create := sysdate;
    ld_log_events_record.mispar_zehut := v_mispar_zehut;
    ld_log_events_record.code_trigger := 0;
    ld_log_events_record.code_event := 0;
    ld_log_events_record.code_event_semel := 1;
    ld_log_events_record.gorem_medaveach := 2292;
    ld_log_events_record.seq_bakasha := v_seq_bakasha;
    ld_log_events_record.mispar_gimla := v_gimla_number;
    ld_log_events_record.date_report := sysdate;
    ld_log_events_record.record_hilan := ' ';
    return insert_event;
  end;
  ------------------------------------  
   procedure prepare_trigger_0(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_is_minui_merube boolean,
                          v_date_report date,
                          v_record varchar2 default '') is
   begin
    ld_log_events_record.seq_ld_log_events := ld_log_events_seq.nextval;
    ld_log_events_record.seq_ld_protocol := v_seq_ld_protocol;
    ld_log_events_record.seq_ld_protocol_hilan := v_seq_ld_protocol_hilan;
    ld_log_events_record.date_create := sysdate;
    ld_log_events_record.mispar_zehut := v_mispar_zehut;
    ld_log_events_record.code_trigger := 0;
    ld_log_events_record.gorem_medaveach := 2292;
    ld_log_events_record.seq_bakasha := v_seq_bakasha;
    ld_log_events_record.mispar_gimla := v_gimla_number;
    ld_log_events_record.date_report := v_date_report;
    ld_log_events_record.seq_ld_log_events := ld_log_events_seq.nextval;
    if v_is_minui_merube then
       if ld_log_events_record.code_event = 315 --and ld_log_events_record.code_event_semel = '0567','0412'
       then
          ld_log_events_record.record_hilan := v_record ||
                                            lpad_zeroez(v_gimla_number,9) ||
                                            lpad_zeroez(ld_log_events_record.seq_ld_log_events,9);
       elsif ld_log_events_record.code_event = 413 and ld_log_events_record.code_event_semel not in (1443,1445,1116)
       then
          ld_log_events_record.record_hilan := v_record ||
                                            lpad_zeroez(v_gimla_number,9) ||
                                            lpad_zeroez(ld_log_events_record.seq_ld_log_events,9);
       else
          ld_log_events_record.record_hilan := rpad_blanks(' ',10) || 
                                            lpad_zeroez(v_gimla_number,9) ||
                                            lpad_zeroez(ld_log_events_record.seq_ld_log_events,9);
       end if;
    else
       ld_log_events_record.record_hilan := rpad_blanks(' ',19) || 
                                            lpad_zeroez(ld_log_events_record.seq_ld_log_events,9); 
    end if;                                                 
    end ;
  ------------------------------------  
  --גימלה חדשה
  function insert_event_237(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
  v_achuz_misra float;
  v_code_misrad_maskret number;
  v_code_ezor_ovdim number; 
  v_mispar_zehut_sheer_benzug number :=0;
  v_mispar_zehut_sheer_benzug_amiti number :=0;
  v_mispar_misra number;
  v_code_uchlusia number;
  
   begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
    
    begin
    select nvl(t.code_misrad_maskret,0), t.code_ezor_ovdim
            into v_code_misrad_maskret, v_code_ezor_ovdim
                from code_ezor_ovdim t
                where t.seq_ezor_ovdim = v_seq_ezor_ovdim
                and (t.pail = 1 or
                not(v_code_sug_bakasha = 1 or v_code_sug_bakasha = 5 and nvl(v_code_bakasha_detail,0) = 25));
    exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_237: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_237: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;   
    end;
   
    for r in (select 0 sug, n.mispar_misra, n.chelkiyut_sofit
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      union 
      select 24, 0, 0 from dual --עבור בקשת מקדמה 
      union 
/*      select 9, 0, 0 from dual  --השתתפות גוף שארים 
      union 
*/    select 10, 0, 0 from dual --עבור קפם חדשות 
      union 
      select 11, 0, 0 from dual --עבור קפמ חדשות שינוים
      order by 1,2)
    loop
          
    v_mispar_misra := r.mispar_misra;
    
    if v_code_sug_bakasha not  in (/*9,*/10,11) then 
    begin
      select n.code_uchlusia
      into v_code_uchlusia
      from netuney_sachar n
      where n.mispar_misra = v_mispar_misra
      and n.code_sug_maskoret = 1
      and (n.seq_bakasha = v_seq_bakasha and v_code_sug_bakasha = 1 or
      v_code_sug_bakasha <> 1 and
      n.seq_bakasha =
      (select max(v.seq_bakasha)
      from v_bakasha_last_status v, netuney_sachar n1
      where v.gimla_number = v_gimla_number
      --and v.mispar_zehut = v_mispar_zehut          -- !!!10/10/19
      and v.code_action = 98
      and v.code_sug_bakasha in (1,14)
      and v.seq_bakasha = n1.seq_bakasha
      and n1.code_sug_maskoret = 1
      and n1.mispar_misra = n.mispar_misra) );
      if v_code_uchlusia is null then v_code_uchlusia := 99; end if;
    exception
    when others then
      --if v_code_sug_bakasha  not in (1,13,12,5,3) then
      --      v_code_uchlusia := 0;
      --else 
            v_code_uchlusia := 99;
      --end if;
    end;
    end if;
    
    ld_log_events_record.code_event := 237;
    ld_log_events_record.code_event_semel := 0;
  
    if r.sug = 0 and  v_code_sug_bakasha in(10,11,24) then continue; end if;
    if r.sug = 24 and v_code_sug_bakasha <> 24 then continue; end if;
    --if r.sug = 9  and v_code_sug_bakasha <> 9  then continue; end if;
    if r.sug = 10 and v_code_sug_bakasha <> 10 then continue; end if;
    if r.sug = 11 and v_code_sug_bakasha <> 11 then continue; end if;

    if v_code_sug_bakasha in (10,11) then
          v_achuz_misra := 1;
    elsif v_code_sug_bakasha <> 12 and v_code_sug_bakasha <> 24 then           
      v_achuz_misra := nvl(r.chelkiyut_sofit,0);
    else
      v_achuz_misra := 0;
    end if;
                     
    prepare_trigger_0(v_seq_ld_protocol,
                      v_seq_ld_protocol_hilan,
                      v_seq_bakasha,
                      case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug else v_mispar_zehut end,
                      case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                      else 
                                v_gimla_number
                      end,
                      true,
                      case when v_code_sug_bakasha = 12 then v_hp_taarich_tokef_haavara
                           when v_code_sug_bakasha = 24 then sysdate
                           else v_date_start_zakaut end);
    if not insert_event then return false; end if;
     ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
     '0' ||                                                                                   --MINUI
     to_char(case when v_code_sug_bakasha = 12 then v_hp_taarich_tokef_haavara
                  when v_code_sug_bakasha = 24 then sysdate
                  else v_date_start_zakaut end,date_format_d8) ||                             --TAARICH
     lpad_zeroez(0,8) ||                                                                      --GNARTOKEF
     /*case when v_code_sug_bakasha in (10,11) then  '404950099'
          when v_code_sug_bakasha = 1 or v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25 then                                       
                lpad_zeroez(nvl(v_code_misrad_maskret,0),3) ||
                lpad_zeroez(nvl(v_code_ezor_ovdim,0),4) || 
                lpad_zeroez(v_code_uchlusia,2) 
          else  rpad_blanks(' ',9) end ||  */                                                   --SEIF  
     case when v_code_sug_bakasha not in (10,11) then                                         
     lpad_zeroez(nvl(v_code_misrad_maskret,0),3) || lpad_zeroez(nvl(v_code_ezor_ovdim,0),4) || 
                                                    lpad_zeroez(v_code_uchlusia,2) 
                                                 else '404950099'  end ||                     --SEIF    
     lpad_zeroez(0,9) ||                                                                      --TEKEN
     lpad_zeroez(replace(to_char(nvl(nvl(v_achuz_misra,9),0),'0.9999'),'.',''),5) ||          --AHUSMISRA
     lpad_zeroez(0,9) ||                                                                      --SEIF                                                                   
     lpad_zeroez(0,9) ||                                                                      --TEKEN
     lpad_zeroez(0,5) ||                                                                      --AHUSMISRA
     lpad_zeroez(0,9) ||                                                                      --SEIF                                                                   
     lpad_zeroez(0,9) ||                                                                      --TEKEN
     lpad_zeroez(0,5) ||                                                                      --AHUSMISRA
     lpad_zeroez(0,9) ||                                                                      --SEIF                                                                   
     lpad_zeroez(0,9) ||                                                                      --TEKEN
     lpad_zeroez(0,5);                                                                        --AHUSMISRA
     --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
     if not insert_event then return false; end if;
     
 /*    if not v_2218 or
       check_mz_exists_in_varray(case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug 
                                      else v_mispar_zehut end,
                                 case when v_mispar_misrot_sach_hakol > 1 then to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))                
                                      else v_gimla_number end
                                        ) = false then
       insert_or_check_event_dynamic(527,
                                  '2218',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mistz_almana_benzug_sheer,
                                  v_mispar_zehut_ben_katan,
                                  v_code_seif_prisha,
                                  1,                               
                                  v_mispar_misra,
                                  1);  
    v_2218 := true;
    if check_mz_exists_in_varray(case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug 
                                      else v_mispar_zehut end,
                                 case when v_mispar_misrot_sach_hakol > 1 then to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))                
                                      else v_gimla_number end
                                        ) = false then
        v_cnt_2218 := v_cnt_2218 + 1; 
                     mispar_zehut_2218.extend; 
                     mispar_zehut_2218(v_cnt_2218) := 
                     case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug else v_mispar_zehut end;
                     mispar_gimla_2218.extend; 
                     mispar_gimla_2218(v_cnt_2218) := 
                     case when v_mispar_misrot_sach_hakol > 1 then to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))                
                          else v_gimla_number end;
    end if;                     
    if not if_commit then return false; end if;
   end if; 
 */  
    end loop;

    
    return true;
    exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_237: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_237: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
      return false;   
  end;                          
  ------------------------------------
  --גימלה חדשה
  function check_event_237(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
  v_achuz_misra float;
  v_code_misrad_maskret number;
  v_code_ezor_ovdim number; 
  v_mispar_misra number;
  
   begin
     
   v_code_misrad_maskret := null;
   v_code_ezor_ovdim := null;

   begin
    select t.code_misrad_maskret, t.code_ezor_ovdim
            into v_code_misrad_maskret, v_code_ezor_ovdim
                from code_ezor_ovdim t
                where t.seq_ezor_ovdim = v_seq_ezor_ovdim
                and t.pail = 1; --???
    exception
    when others then
       message := sqlerrm;
       build_check_message(1,'0237','0000',1,': ' || to_char(v_seq_ezor_ovdim),message);
    end;
    if v_code_misrad_maskret is null then
       build_check_message(1,'0237','0000',2,': ' || to_char(v_seq_ezor_ovdim));
    end if;
    if v_code_ezor_ovdim is null then
       build_check_message(1,'0237','0000',3,': ' || to_char(v_seq_ezor_ovdim));
    end if;
    
    if v_code_sug_bakasha = 24 then return true; end if;

    
    for r in (select n.*
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      order by n.mispar_misra)
      --for i in 1 .. v_mispar_misrot_leprisha
    loop
      
    v_mispar_misra := r.mispar_misra;
         
    begin
    if v_code_sug_bakasha <> 12 then           
       select t.chelkiyut_sofit
            into v_achuz_misra
                from netuney_tik_mechushavim t
                where t.seq_bakasha = v_seq_bakasha
                and t.code_department = 2              
                and t.mispar_misra = v_mispar_misra;
    else
      v_achuz_misra := 0;
    end if;                
    exception
    when others then
       message := sqlerrm;
       build_check_message(1,'0237','0000',4,'',message);
    end;
    if v_achuz_misra is null then
       build_check_message(1,'0237','0000',5,'');
    end if;
    end loop;
   return true; 
  end;                          
  ------------------------------------
  -- נתונים שונים למילוי
   function insert_event_312(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_erech number;
   v_erech2 number := 0;
   v_erech3 number;
   v_erech_str varchar2(9);
   v_teur varchar2(15);
   v_mispar_zehut_sheer_benzug number := 0;
   v_mispar_zehut_sheer_benzug_amiti number := 0;
   v_is_gimlat_kefel boolean := false;
   v_times number := 1;
   v_mi_taarich date;
   v_insert_event_status boolean;
   v_mispar_misra number;
   v_mispar_prishot_lesheer number;
   v_ramat_bigud number;
   v_ramat_bigud_first0 boolean := true;
   v_ramat_bigud_first1 boolean := true;
   v_is_netuney_sachar number;
   v_code_derug number;
   v_code_darga number;
   v_ramat_murkavut number;
   v_from_date date;
   
   begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
    
      /*if (v_mispar_zehut_sheer_benzug <> 0  and v_semel_hilan <> '0410' or
        v_mispar_zehut_sheer_benzug = 0  and v_semel_hilan = '0410') then
        return true;
      end if;*/


     --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    /* if v_code_sug_bakasha = 13 
       and not v_ptira_besherut_gimlat_chesed 
       and not v_semel_hilan = '0410'
       then return true; end if; */
            
      ld_log_events_record.code_event := 312;
      ld_log_events_record.code_event_semel := v_semel_hilan;

      if v_semel_hilan not in('0112','0407') then
       
      if v_semel_hilan = '0180'  then
       if v_sachar_reforma = 1 /*and v_code_sug_bakasha <> 14*/ then return true; end if;
		   v_netuney_sachar_leporesh := false;								  
       if v_seq_ezor_ovdim = 206 then
