               v_erech3 := v_mispar_zehut;
           else
               v_erech := 99999;
               v_erech2 := v_mispar_zehut;
           end if;
         end if;    
         v_teur := 'מנה של הסכם חדש';
       
         prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug = 0 then
                                 v_mispar_zehut                      
                             else
                                 v_mispar_zehut_sheer_benzug
                             end,                                 
                        case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra + 1,1))
                             else 
                                v_gimla_number
                             end,
                        true,
                        --to_date('01/09/2007','DD/MM/YYYY'));
                        to_date(to_char(v_date_start_zakaut,date_format_d6) || '01',date_format_d8));                   
           if not insert_event then return false; end if;   
               
           ld_log_events_record.code_trigger := 2;
           ld_log_events_record.record_hilan := 
           '0' ||                                                                                            --MINUI
           lpad_zeroez(v_erech,9) ||                                                                         --ERECH                       
           lpad_zeroez(v_erech2,9) ||                                                                        --ERECH_2
           lpad_zeroez(v_erech3,9) ||                                                                        --ERECH_3
           rpad_blanks(v_teur,15) ||                                                                         --TEUR
           to_char(v_date_start_zakaut,date_format_d8) ||  
           --'20070901'  ||                                                                                    --TAARICH
           lpad_zeroez(0,8);                                                                                 --GMATROKEF
