             where cr.code_reforma = 1
             --and cr.code_chinuch_alterntive = 1
             and m.code_chinuch_sug_maskoret = 1
             and n.seq_bakasha = v_seq_bakasha
             and rownum < 2;

                    v_mispar_misra := 0;
                    prepare_trigger_0(v_seq_ld_protocol,
