         where t.mispar_zehut = v_mispar_zehut_sheer_benzug_amiti
         and t.gimla_number <> v_gimla_number
         and t.code_action<>17;
         if v_mispar_prishot_lesheer > 0 then
           v_erech2 := 2; -- שאר קיים
         else
           v_erech2 := 1; -- שאר חדש
         end if;
      end if;
      
      prepare_trigger_0(v_seq_ld_protocol,
