       /*v_erech := r.sum_participation * 100;
       
       v_erech2 := case when not r.percent_participate_calc is null and r.percent_participate_calc<>0 then
                        r.percent_participate_calc * 100
                   else
                        r.percent_participate * 100
                   end; */
       v_erech := lpad_zeroez(replace(to_char(nvl(r.kizba_chodshit,0),'9999999.99'),'.',''),9);
       v_erech2 := lpad_zeroez(replace(to_char(nvl(r.ACHUZ_GUF_FINAL,0),'9999999.99'),'.',''),9);
       v_erech3 := nvl(r.partial_period,0) * 10000;     --אחוזים * 100
       ld_log_events_record.record_hilan := 
       '0' ||                                                                                            --MINUI
       lpad_zeroez(nvl(v_erech,0),9) ||                                             --ERECH                                                                      --ERECH                       
       lpad_zeroez(nvl(v_erech2,0),9) ||                                            --ERECH2                                                                  --ERECH_2
       lpad_zeroez(nvl(v_erech3,0),9) ||                                            --ERECH3                                                                      --ERECH_3
       rpad_blanks(v_teur,15) ||                                                                         --TEUR
