      where n.seq_bakasha = v_seq_bakasha
      and (v_sachar_reforma <> 1 and n.code_sug_maskoret = 1
      or v_sachar_reforma = 1 and n.code_sug_maskoret =
      (select c.code_sug_maskoret
      from code_sug_maskoret c
      where c.code_sug_maskoret = n.code_sug_maskoret
      and c.code_chinuch_sug_maskoret = 1))
      order by n.mispar_misra)
      --for i in 1 .. v_mispar_misrot_leprisha
     loop
      
      v_mispar_misra := r.mispar_misra;
      
      if nvl(r.ramat_bigud,0) = 0 then continue; end if;
      if v_sachar_reforma <> 0 then
        if r.mispar_misra = 0 and v_ramat_bigud_first0 = false then continue; end if;
        if r.mispar_misra = 1 and v_ramat_bigud_first1 = false then continue; end if;
      end if;
      v_ramat_bigud := r.ramat_bigud;
      v_erech := v_ramat_bigud;
      v_teur := 'רמת ביגוד';
      if v_sachar_reforma <> 0 then
        if r.mispar_misra = 0 then v_ramat_bigud_first0 := false; end if;
        if r.mispar_misra = 1 then v_ramat_bigud_first1 := false; end if;
      end if;
           
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
