       lpad_zeroez(v_erech,9) ||                                                                         --ERECH                       
       lpad_zeroez(v_erech2,9) ||                                                                               --ERECH_2
       lpad_zeroez(0,9) ||                                                                               --ERECH_3
       rpad_blanks(v_teur,15) ||                                                                         --TEUR
       --to_char(v_date_start_zakaut,date_format_d8) ||  
       to_char(v_date_start_zakaut,date_format_d6) || '01' ||                                                 --TAARICH
       lpad_zeroez(0,8);                                                                                 --GMATROKEF
       --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
       v_times := v_times + 1;       
       if insert_event then continue; else return false; end if;
     end loop;
     return true;
     end if;
     exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_312: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_312: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;  
  ------------------------------------  
  -- נתונים שונים למילוי
   function check_event_312(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_erech number;
   v_mispar_zehut_sheer_benzug number := 0;
   v_mispar_zehut_sheer_benzug_amiti number := 0;
   v_times number := 1;
   v_mi_taarich date;
   v_mispar_misra number;
   begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 

     --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
     /*if v_code_sug_bakasha = 13 
       and not v_ptira_besherut_gimlat_chesed 
       and not v_semel_hilan = '0410'
       then return true;
     end if; */
     
     for r in (select n.*
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      order by n.mispar_misra)
      --for i in 1 .. v_mispar_misrot_leprisha
    loop
      
    v_mispar_misra := r.mispar_misra;
 
       if v_semel_hilan = '0102' then--סעיף חוק 
       begin
       select t.code_seif_prisha
                into v_erech
                from  bakasha_regila t
                where t.seq_bakasha = v_seq_bakasha;
       exception
       when others then
       message := sqlerrm;
       build_check_message(1,'0312','0102',6,'',message);
       end;
       if v_erech is null then
         build_check_message(1,'0312','0102',7,'');
       end if;
      elsif  v_semel_hilan = '0971' then --פרוד/ה
      begin  
       select t.mispar_zehut_ben_mishpacha
                into v_erech
                from  bney_mishpacha t, poresh p
                where p.mispar_zehut = v_mispar_zehut_amiti
                and t.seq_porshim = p.porshim_seq
                and t.code_kirva = 1
                and t.seq_bney_mishpacha =
                (select max(b.seq_bney_mishpacha)
                from bney_mishpacha b
                where b.seq_porshim = p.porshim_seq
                and b.code_kirva = 1);
      exception
       when others then
       message := sqlerrm;
       --build_check_message('0312','0971',8,'');
      end;
      elsif v_semel_hilan = '0112' then  --  גמלאות כפל
      begin
      select min(t.date_payment)
                 into v_mi_taarich
                 from participation t
                 where t.seq_bakasha = v_seq_bakasha
                 and t.code_participation = 6;
      exception
      when others then
       if v_code_sug_bakasha = 18 then
          build_check_message(1,'0312','0112',8,'',message);
        end if;  
      end;
      v_times := 0;
      for r in          
            (select t.kizba_chodshit, t.percent_participate_calc,
            t.partial_period, t.date_payment
                 from participation t
                 where t.seq_bakasha = v_seq_bakasha
                 and t.code_participation = 6) loop
      if r.kizba_chodshit is null or
         r.percent_participate_calc is null or
         r.partial_period is null or
         r.date_payment is null then
               check_message := check_message || ' event_312; semel_0112 ' ||  '<br />';
      end if;         
      v_times :=  v_times + 1;              
      end loop;
      if v_times = 0 and v_code_sug_bakasha = 18 then
          build_check_message(1,'0312','0112',8,'');
      end if;     
     end if;
    end loop;
    return true;
    end;  
  ------------------------------------  
  --פרטי פורש
  function insert_event_200(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
  v_shem_mishpacha varchar2(50);
  v_shem_prati varchar2(50);
  v_shem_nosaf varchar2(50); 
  v_taarich_leida  date;
  v_taarich_aliya  date;
  is_passport number;
  --v_mispar_mofaim_p  number;
  --v_mispar_mofaim_b  number;
  v_mispar_zehut_sheer_benzug number :=0;
  v_mispar_zehut_sheer_benzug_amiti number :=0;
   begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
 
    /*select count(*)
    into v_mispar_mofaim_p
    from poresh t
    left join prisha p on
    p.seq_poresh = t.porshim_seq
    where t.mispar_zehut = case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut else v_mispar_zehut_sheer_benzug end
    and p.gimla_number <> v_gimla_number;

    select count(*)
    into v_mispar_mofaim_b
    from bney_mishpacha b
    left join poresh t on
    b.seq_porshim = t.porshim_seq
    left join prisha p on
    p.seq_poresh = t.porshim_seq
    where b.mispar_zehut_ben_mishpacha = case when v_mispar_zehut_sheer_benzug = 0  then v_mispar_zehut else v_mispar_zehut_sheer_benzug end
    and not b.code_relative is null
    and p.gimla_number <> v_gimla_number;

    
    if (v_mispar_mofaim_p > 0 or v_mispar_mofaim_b > 0) then --לא מדווחים אותו בן אדם פעמיים
      return true;
    else -- לא שאר ולא גמלה נוספת */
    v_sug_zihuy_lo_tikni := false;  
     
    ld_log_events_record.code_event := 200;
    ld_log_events_record.code_event_semel := 0;
    
    if v_mispar_zehut_sheer_benzug = 0 then
    select p.shem_mishpacha, p.shem_prati, p.taarich_leda, p.taarich_aliya,
           case when nvl(p.sug_zihuy,0) in (1,4) then 0
                when nvl(p.sug_zihuy,0) in (2,3) then 1
                else 2
           end
            into v_shem_mishpacha, v_shem_prati, v_taarich_leida, v_taarich_aliya, is_passport
                from v_bakasha_last_status t
                left join poresh p on
                p.porshim_seq = t.seq_porshim
                where t.seq_bakasha = v_seq_bakasha;
                --and p.sug_zihuy not in (5,6);
    else
    select b.shem_mishpacha, b.shem_prati, b.taarich_leda,
           case when nvl(b.sug_zihuy,0) in (1,4) then 0
                when nvl(b.sug_zihuy,0) in (2,3) then 1
                else 2
           end
            into v_shem_mishpacha, v_shem_prati, v_taarich_leida, is_passport
                from v_bakasha_last_status t
                left join bney_mishpacha b on
                b.seq_porshim = t.seq_porshim                
                where t.seq_bakasha = v_seq_bakasha
                and b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug
                and (v_code_sug_bakasha = 12 and (b.code_kirva = 10 or b.code_relative=6) or v_code_sug_bakasha <> 12);
                --and b.sug_zihuy not in (5,6);
   end if;
    
    if is_passport = 2 then
      v_sug_zihuy_lo_tikni := true;
      return true;
    end if;    
  
   prepare_trigger_0(v_seq_ld_protocol,
                      v_seq_ld_protocol_hilan,
                      v_seq_bakasha,
                      case when v_mispar_zehut_sheer_benzug = 0  then v_mispar_zehut else v_mispar_zehut_sheer_benzug end,
                      v_gimla_number,
                      false,
                      sysdate);  
                       
    if insert_event then    
    if length(trim(v_shem_prati)) > 10 and instr(trim(v_shem_prati),' ') > 0 then
      v_shem_prati := replace(v_shem_prati,'-',' ');
      v_shem_prati := replace(v_shem_prati,'(',' ');
      v_shem_prati := replace(v_shem_prati,')',' ');
      v_shem_prati := replace(v_shem_prati,'  ',' ');
      v_shem_nosaf := substr(trim(v_shem_prati),instr(trim(v_shem_prati),' '),100);
      v_shem_prati := substr(trim(v_shem_prati),1,instr(trim(v_shem_prati),' ')-1);
      v_shem_prati := substr(v_shem_prati,1,10);
      v_shem_nosaf := substr(trim(v_shem_nosaf),1,10);
    else
      v_shem_nosaf := ' ';
    end if;

    ld_log_events_record.code_trigger := 2;
    ld_log_events_record.record_hilan := 
           lpad_zeroez(case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut else v_mispar_zehut_sheer_benzug end,9) || --MIUN
           lpad_zeroez(case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut                                       --ZEUT
                            when v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug end,9) ||
           rpad_blanks(v_shem_mishpacha,10) ||                                                                             --MISHPAHA 
           rpad_blanks(v_shem_prati,7) ||                                                                                  --SHEM 
           rpad_blanks(' ',10) ||                                                                                          --SHEMAV
           to_char(v_taarich_leida,date_format_d8) ||                                                                      --LEIDA
           lpad_zeroez(is_passport,1) ||                                                                                   --DARKON
           rpad_blanks(v_shem_mishpacha,20) ||                                                                             --MISHPAHA_MALE
           rpad_blanks(v_shem_prati,10) ||                                                                                 --SHEM_MALE
           rpad_blanks(v_shem_nosaf,10) ||                                                                                 --SHEM_NOSAF
           rpad_blanks(' ',10) ||                                                                                          --FIRSTN                                                                                      
           rpad_blanks(' ',10) ||                                                                                          --MIDDLEN
           rpad_blanks(' ',14) ||                                                                                          --FAMILYN
           rpad_blanks(' ',5) ||                                                                                           --USER
           rpad_blanks(' ',1) ||                                                                                           --FILLER
           (case when v_taarich_aliya is null then lpad_zeroez(0,8) else to_char(v_taarich_aliya,date_format_d8) end) ||    --ALIADT
           lpad_zeroez(0,3) ||                                                                                             --BIRTH_COUNTRY                                                                                      --
           lpad_zeroez(0,3) ||                                                                                             --ALIA_COUNTRY
           lpad_zeroez(0,3) ||                                                                                             --NETINUT
           lpad_zeroez(0,3) ||                                                                                             --NETINUT_B
           rpad_blanks(' ',1);                                                                                             --LEOM
           --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
      return insert_event;
    else
      return false;
    end if;
    --end if;
    exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_200: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_200: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;
  ------------------------------------
  --פרטי פורש
  function check_event_200(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
  v_shem_mishpacha varchar2(50);
  v_shem_prati varchar2(50);
  v_shem_nosaf varchar2(50); 
  v_taarich_leida  date;
  v_taarich_aliya  date;
  v_mispar_mofaim_p  number;
  v_mispar_mofaim_b  number;
  v_mispar_zehut_sheer_benzug number :=0;
  v_mispar_zehut_sheer_benzug_amiti number :=0;
  begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
  
    if v_mispar_zehut_sheer_benzug = 0 then
    begin
    select p.shem_mishpacha, p.shem_prati, p.taarich_leda, p.taarich_aliya
            into v_shem_mishpacha, v_shem_prati, v_taarich_leida, v_taarich_aliya
                from v_bakasha_last_status t
                left join poresh p on
                p.porshim_seq = t.seq_porshim
                where t.seq_bakasha = v_seq_bakasha;
    exception
    when others then
      message := sqlerrm;
      build_check_message(1,'0200','0000',9,': ' || to_char(v_mispar_zehut),message);
    end;         
    else
    begin
    select b.shem_mishpacha, b.shem_prati, b.taarich_leda
            into v_shem_mishpacha, v_shem_prati, v_taarich_leida
                from v_bakasha_last_status t
                left join bney_mishpacha b on
                b.seq_porshim = t.seq_porshim                
                where t.seq_bakasha = v_seq_bakasha
                and b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
                and (v_code_sug_bakasha = 12 and (b.code_kirva = 10 or b.code_relative=6) or v_code_sug_bakasha <> 12);
    exception
    when others then
       message := sqlerrm;
       build_check_message(1,'0200','0000',10,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
    end;
    end if;
           
    
    if length(trim(v_shem_prati)) > 10 and instr(trim(v_shem_prati),' ') > 0 then
      v_shem_prati := replace(v_shem_prati,'-',' ');
      v_shem_prati := replace(v_shem_prati,'(',' ');
      v_shem_prati := replace(v_shem_prati,')',' ');
      v_shem_prati := replace(v_shem_prati,'  ',' ');
      v_shem_nosaf := substr(trim(v_shem_prati),instr(trim(v_shem_prati),' '),100);
      v_shem_prati := substr(trim(v_shem_prati),1,instr(trim(v_shem_prati),' ')-1);
      v_shem_prati := substr(v_shem_prati,1,10);
      v_shem_nosaf := substr(trim(v_shem_nosaf),1,10);
    else
      v_shem_nosaf := ' ';
    end if;
    
    if v_shem_mishpacha is null then
      build_check_message(1,'0200','0000',11,'');
    end if;
    if v_shem_prati is null then
      build_check_message(1,'0200','0000',12,'');
    end if;
    if v_taarich_leida is null then
      build_check_message(1,'0200','0000',13,'');
    end if;
    return true;
    end;
  ------------------------------------
  --מצב משפחתי
  function insert_event_205(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_code_mazav_mishpachti number;
   v_date_mazav_mishpachti date;
   v_date_mazav_mishpachti_true date;
   v_date_update date;
   v_code_min number;
   v_code_mazav_mishpachti_hilan number;
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_zehut_sheer_benzug_amiti number :=0;
   v_date_start_zakaut_max date;
   begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
     
    if v_mispar_zehut_sheer_benzug = 0 then
        select max(n.date_start_zakaut)
        into  v_date_start_zakaut_max
        from v_bakasha_last_status v
         left join netuney_tik_mechushavim n on
        n.seq_bakasha = v.seq_bakasha
        where v.gimla_number = v_gimla_number
        and v.mispar_zehut = v_mispar_zehut
        and n.code_department = 2
        and n.code_group_prisha <> 4
        and v.code_action not in (17,100);       
        select mishp.code_mazav_mishpachti, mishp.date_mazav_mishpachti, mishp.code_min, mishp.date_update, mishp.date_mazav_mishpachti_true
        into v_code_mazav_mishpachti, v_date_mazav_mishpachti, v_code_min, v_date_update, v_date_mazav_mishpachti_true
        from (select m.code_mazav_mishpachti, 
                case when (v_code_sug_bakasha = 1
                  or v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25) then v_date_start_zakaut
                  else 
                        case when m.date_mazav_mishpachti > v_date_start_zakaut_max then m.date_mazav_mishpachti
                                                                              else v_date_start_zakaut_max end 
                  end date_mazav_mishpachti,
                  p.code_min, m.date_update, m.date_mazav_mishpachti date_mazav_mishpachti_true
                  from poresh p, mazav_mishpachti m
                  where p.mispar_zehut = v_mispar_zehut_amiti
                  and m.seq_poresh = p.porshim_seq
                  --order by (case when m.date_mazav_mishpachti is null then m.seq_mazav_mishpachti else m.date_mazav_mishpachti end) desc
                  order by m.date_mazav_mishpachti desc nulls last, 
                  m.seq_mazav_mishpachti desc
                  ) mishp
                  where rownum = 1;
     else
        select max(n.date_start_zakaut)
        into  v_date_start_zakaut_max
        from v_bakasha_last_status v
         left join netuney_tik_mechushavim n on
        n.seq_bakasha = v.seq_bakasha
        where v.gimla_number = v_gimla_number
        and v.mispar_zehut = v_mispar_zehut
        and n.code_department = 2
        and n.code_group_prisha = 4;       
        select mishp.code_mazav_mishpachti, mishp.date_mazav_mishpachti, mishp.code_min, mishp.date_update, mishp.date_mazav_mishpachti_true
        into v_code_mazav_mishpachti, v_date_mazav_mishpachti, v_code_min, v_date_update, v_date_mazav_mishpachti_true 
        from (select m.code_mazav_mishpachti,
                case when (v_code_sug_bakasha = 1
                  or v_code_sug_bakasha = 13
                  and (select count(*)
                        from v_bakasha_last_status b, netuney_tik_mechushavim n
                        where b.gimla_number = v_gimla_number
                        and b.mispar_zehut = v_mispar_zehut
                        and n.seq_bakasha = b.seq_bakasha
                        and b.seq_bakasha < v_seq_bakasha
                        and n.code_group_prisha = 4) = 0) then v_date_start_zakaut
                  else 
                        case when m.date_mazav_mishpachti > v_date_start_zakaut_max then m.date_mazav_mishpachti
                                                                              else v_date_start_zakaut_max end 
                  end date_mazav_mishpachti,
                  b.code_min, m.date_update, m.date_mazav_mishpachti date_mazav_mishpachti_true
                  from bney_mishpacha b, mazav_mishpachti m
                  where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
                  and m.seq_bney_mishpacha = b.seq_bney_mishpacha
                  --order by (case when m.date_mazav_mishpachti is null then m.seq_mazav_mishpachti else m.date_mazav_mishpachti end) desc
                  order by m.date_mazav_mishpachti desc nulls last,
                  m.seq_mazav_mishpachti desc
                  nulls last) mishp
                  where rownum = 1;
        if v_date_mazav_mishpachti is null and v_date_update is null and v_code_mazav_mishpachti = 2 then
          v_date_mazav_mishpachti := v_taarich_ptirat_poresh;
        end if;
     end if;
     
     if v_mispar_zehut_sheer_benzug=0 and v_code_mazav_mishpachti = 4 then --פרוד/ה 
        v_taarich_leparud :=
        case when v_date_mazav_mishpachti is not null and
          (v_code_sug_bakasha in (1,13,26) or v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25) then v_date_mazav_mishpachti
             when v_date_mazav_mishpachti is null and
          (v_code_sug_bakasha in (1,13,26) or v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25)  and v_date_start_zakaut is not null then v_date_start_zakaut                 
                             when v_code_sug_bakasha = 12 then v_hp_taarich_tokef_haavara
                             when v_date_update is not null and v_code_sug_bakasha not in(1,12,13,26) then v_date_update 
                             else sysdate end;
             insert_or_check_event_dynamic(312,
                                  '0971',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  0,
                                  0,
                                  v_code_seif_prisha,
                                  0);
            if not if_commit then return false; end if;
    end if;


               
    if v_code_mazav_mishpachti is null then v_code_mazav_mishpachti := 0; end if;
    if v_code_min is null then v_code_min := 0;  end if;
    v_code_mazav_mishpachti_hilan := get_mazav_mishpachti_hilan(v_code_mazav_mishpachti,v_code_min);
    if (v_date_mazav_mishpachti is null or to_char(v_date_mazav_mishpachti,'DD/MM/YYYY') = '00/00/0000') then
      v_date_mazav_mishpachti := case when v_date_update is not null then v_date_update
                                      else sysdate end;
    end if;
    if v_code_mazav_mishpachti_hilan <> 0 then
      ld_log_events_record.code_event := 205;
      ld_log_events_record.code_event_semel := 0;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut else v_mispar_zehut_sheer_benzug end,
                        v_gimla_number,
                        false,
                        case when v_date_mazav_mishpachti is not null and 
                          (v_code_sug_bakasha in (1,13,26) or v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25) then v_date_mazav_mishpachti
                             when v_date_mazav_mishpachti is null and v_code_sug_bakasha in (1,13,26) and v_date_start_zakaut is not null then v_date_start_zakaut                 
                             when v_code_sug_bakasha = 12 then v_hp_taarich_tokef_haavara
                             when v_date_update is not null and v_code_sug_bakasha not in(1,12,13,26) then v_date_update 
                             else sysdate end);
      if insert_event then   
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             lpad(v_code_mazav_mishpachti_hilan,1) ||                                                    --MATZAV
             (case when v_code_mazav_mishpachti_hilan in(2,6) then --נשוי/נשואה                          --TOKEF
                   to_char(case when v_code_sug_bakasha = 12 then v_hp_taarich_tokef_haavara
                                when v_date_mazav_mishpachti is not null and 
                                (v_code_sug_bakasha in (1,13,26) or v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25) then v_date_mazav_mishpachti
                                when v_date_mazav_mishpachti is null and(v_code_sug_bakasha in (1,13,26) or v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25) then v_date_start_zakaut
                                when v_date_update is not null and v_code_sug_bakasha not in(1,5,12,13,26) then v_date_update     
                                else sysdate end,date_format_d6) else
                   lpad_zeroez(0,6) end) ||  --חודש טוקף
             to_char(v_date_mazav_mishpachti_true,date_format_d8) ||                                          --MITAARICH
             lpad_zeroez(0,6);                                                                           --GMARTOKEF
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
       return insert_event;
       else
         return false;
       end if;
    end if;
    return true;
    exception
     when no_data_found then
       return true;
     when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_205: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_205: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;
   ------------------------------------  
  --מצב משפחתי
   function check_event_205(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_code_mazav_mishpachti number;
   v_date_mazav_mishpachti date;
   v_date_update date;
   v_code_min number;
   v_code_mazav_mishpachti_hilan number;
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_zehut_sheer_benzug_amiti number :=0;
  begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
     v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
   
    if v_mispar_zehut_sheer_benzug = 0 then
      begin  
        select mishp.code_mazav_mishpachti, mishp.date_mazav_mishpachti, mishp.code_min, mishp.date_update
        into v_code_mazav_mishpachti, v_date_mazav_mishpachti, v_code_min, v_date_update
        from (select m.code_mazav_mishpachti, m.date_mazav_mishpachti,p.code_min, m.date_update
                  from poresh p, mazav_mishpachti m
                  where p.mispar_zehut = v_mispar_zehut_amiti
                  and m.seq_poresh = p.porshim_seq
                  --order by (case when m.date_mazav_mishpachti is null then m.date_update else m.date_mazav_mishpachti end) desc
                  order by m.seq_mazav_mishpachti desc
                  nulls last) mishp
                  where rownum = 1;
     exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0205','0000',14,': ' || to_char(v_mispar_zehut),message);
     end;
    else
      begin
        select mishp.code_mazav_mishpachti, mishp.date_mazav_mishpachti, mishp.code_min, mishp.date_update
        into v_code_mazav_mishpachti, v_date_mazav_mishpachti, v_code_min, v_date_update
        from (select m.code_mazav_mishpachti, m.date_mazav_mishpachti,b.code_min, m.date_update
                  from bney_mishpacha b, mazav_mishpachti m
                  where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
                  and m.seq_bney_mishpacha = b.seq_bney_mishpacha
                  --order by (case when m.date_mazav_mishpachti is null then m.date_update else m.date_mazav_mishpachti end) desc
                  order by m.seq_mazav_mishpachti desc
                  nulls last) mishp
                  where rownum = 1;
     exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0205','0000',14,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
     end;
    end if;
          
    if v_code_mazav_mishpachti is null then v_code_mazav_mishpachti := 0; end if;
    if v_code_min is null then v_code_min := 0;  end if;
    v_code_mazav_mishpachti_hilan := get_mazav_mishpachti_hilan(v_code_mazav_mishpachti,v_code_min);
    if v_code_mazav_mishpachti_hilan is null then
      build_check_message(1,'0205','0000',15,'');
    end if;
    
    return true;
    end;
  ------------------------------------  
  --כתובת
  function insert_event_218(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                         ) return boolean is
  v_city_code number;
  v_city varchar2(30);
  v_street varchar2(100);
  v_house number;
  v_appartment number;
  v_entrance varchar2(10);
  v_mikud varchar2(10);
  v_telephon varchar2(30);
  v_telephon2 varchar2(30);
  v_pelephon varchar2(30);
  v_email varchar2(50);
  v_update_date date;
  v_mispar_zehut_sheer_benzug number :=0;
  v_mispar_zehut_sheer_benzug_amiti number :=0;
  v_exists_sheer_address number;
  v_mispar_zehut_bakasha number := 0;
  v_td varchar2(6);
  v_code_relative number;
  
  begin
    
--  if v_seq_bakasha = 348353 then return true; end if;
    if v_mistz_almana_benzug_sheer <> 0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan <> 0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
    
    if v_mispar_zehut_sheer_benzug = 0 and v_code_sug_bakasha = 21 then
      select b.mispar_zehut_ben_mishpacha
      into v_mispar_zehut_sheer_benzug
      from address a
      left join bney_mishpacha b
      on b.seq_bney_mishpacha = nvl(a.seq_bney_mishpacha,0)
      and b.code_relative = 6
      where a.seq_bakasha = v_seq_bakasha;
      if v_mispar_zehut_sheer_benzug is null then
        v_mispar_zehut_sheer_benzug := 0;
      else
        v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
      end if;   
    end if;
       
    if v_mispar_zehut_sheer_benzug <>0 then 
        select 
        case when exists(select b.mispar_zehut_ben_mishpacha
        from bney_mishpacha b, address a
        where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
        and a.seq_bney_mishpacha = b.seq_bney_mishpacha
        and not a.code_city is null) then 1 else 0 end
        into v_exists_sheer_address
        from dual t;
    end if;
    
    if v_code_sug_bakasha in(33,35) then 
      if v_mispar_zehut_sheer_benzug = 0 /* פורש */ then 
            select p.telephon, p.telephon2, p.pelephon
            into v_telephon, v_telephon2, v_pelephon
            from poresh p
            where p.mispar_zehut = v_mispar_zehut_amiti;
      else
             --בינתיים נשלחים טלפונים של פורש גם לשאר בן זוג
             --מפני שהמערכת מעדכנת טלפונים של הפורש  אפילן אחרי פטירתו
            select p.telephon, null, p.pelephon, b.code_relative
            into v_telephon, v_telephon2, v_pelephon, v_code_relative
            from poresh p, bney_mishpacha b
            where p.mispar_zehut = v_mispar_zehut_amiti
            and b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti;
            if v_code_relative not in (1,5) then --כרגע אין עדכון מספרי טלפון עבור שארים אחרים
              return true;
            end if;            
 /*    select b.telephone, null, b.pelephone
            into v_telephon, v_telephon2, v_pelephon
            from bney_mishpacha b
            where b.mispar_zehut_ben_mishpacha =  v_mispar_zehut_sheer_benzug_amiti;*/
     end if;
    elsif v_code_sug_bakasha <> 21 then --לא בקשת שינוי כתובת
    if v_mispar_zehut_sheer_benzug = 0 or v_exists_sheer_address = 0 then
    select  a.code_city, a.street, a.house, a.apartment, a.entrance,
            a.mikud, a.date_update,
            p.telephon, p.telephon2, p.pelephon, p.email
            into v_city_code, v_street, v_house, v_appartment, v_entrance,
            v_mikud, v_update_date,
            v_telephon, v_telephon2, v_pelephon, v_email
            from poresh p, address a
            where p.mispar_zehut = v_mispar_zehut_amiti
            and a.seq_poresh = p.porshim_seq
            and a.seq_bney_mishpacha is null
            and (a.code_address = 1
            and a.seq_address = 
            (select max(a1.seq_address)
            from address a1
            where a1.seq_poresh = p.porshim_seq
            and a1.code_address = 1)
            and a.seq_address = 
            (select max(a1.seq_address)
            from address a1
            where a1.seq_poresh = p.porshim_seq
            and a1.seq_bney_mishpacha is null
            and a1.code_address = 1)
            and (not exists (select *
            from address a1
            where a1.seq_poresh = p.porshim_seq
            and a1.seq_bney_mishpacha is null
            and a1.code_address = 2))
            or
            (a.code_address = 2
            and a.seq_address = 
            (select max(a1.seq_address)
            from address a1
            where a1.seq_poresh = p.porshim_seq
            and a1.seq_bney_mishpacha is null
            and a1.code_address = 2)));
    else
    select  a.code_city, a.street, a.house, a.apartment, a.entrance,
            a.mikud, a.date_update,
            b.telephone, null, b.pelephone, b.email
            into v_city_code, v_street, v_house, v_appartment, v_entrance,
            v_mikud, v_update_date,
            v_telephon, v_telephon2, v_pelephon, v_email
            from bney_mishpacha b, address a, poresh p
            where not b.code_kirva is null
            and b.mispar_zehut_ben_mishpacha =  v_mispar_zehut_sheer_benzug_amiti
            and a.seq_poresh is null
            and a.seq_bney_mishpacha = b.seq_bney_mishpacha
            and p.porshim_seq = b.seq_porshim
            and p.mispar_zehut = v_mispar_zehut_amiti
            and (a.code_address = 1
            and a.seq_address = 
            (select max(a1.seq_address)
            from address a1
            where a1.seq_bney_mishpacha = b.seq_bney_mishpacha
            and a1.code_address = 1)
            and a.seq_address = 
            (select max(a1.seq_address)
            from address a1
            where a1.seq_poresh is null
            and a1.seq_bney_mishpacha = b.seq_bney_mishpacha
            and a1.code_address = 1)
            and (not exists (select *
            from address a1
            where a1.seq_poresh is null
            and a1.seq_bney_mishpacha = b.seq_bney_mishpacha
            and a1.code_address = 2))
            or
            (a.code_address = 2
            and a.seq_address = 
            (select max(a1.seq_address)
            from address a1
            where a1.seq_poresh is null
            and a1.seq_bney_mishpacha = b.seq_bney_mishpacha
            and a1.code_address = 2)));
    end if;
    else
    select distinct a.code_city, a.street, a.house, a.apartment, a.entrance,
           a.mikud, a.date_update,
           case when not a.seq_poresh is null then p.telephon else b.telephone end,
           case when not a.seq_poresh is null then p.telephon2 else null end,
           case when not a.seq_poresh is null then p.pelephon else b.pelephone end,
           case when not a.seq_poresh is null then p.email else b.email end,
           case when not a.seq_poresh is null then p.mispar_zehut else b.mispar_zehut_ben_mishpacha end
           into v_city_code, v_street, v_house, v_appartment, v_entrance,
           v_mikud, v_update_date,
           v_telephon, v_telephon2, v_pelephon, v_email,
           v_mispar_zehut_bakasha           
    from address a, poresh p, bney_mishpacha b
    where a.seq_bakasha = v_seq_bakasha
    and p.mispar_zehut = v_mispar_zehut_amiti
    and (a.seq_bney_mishpacha is null
         and a.seq_poresh = p.porshim_seq   
    or not a.seq_bney_mishpacha is null
        and a.seq_bney_mishpacha = b.seq_bney_mishpacha
        and b.seq_porshim = p.porshim_seq);
    end if;
    
 if v_code_sug_bakasha in (33,35) then
    v_city_code := 0;
    v_city := ' ';
    v_street := ' ';
    v_house := 0;
    v_appartment := 0;
    v_entrance := ' ';  
    v_mikud := 0;
    v_td := '000000';                                                                                                          --TA_DOAR
    v_email := ' ';
 else    
    v_city := substr(get_yishuv(v_city_code),1,13);
    if not v_street is null then 
       v_street := replace(v_street,'כניסה',' ');
       v_street := replace(replace(v_street,'  ',' '),'  ',' ');
    end if;
    if instr(v_street,'ת.ד',
      1) > 0 or 
      instr(v_street,'ת"ד',
      1) >0 then
      v_td := get_ta_doar(v_street);
      --if v_code_sug_bakasha = 21 or v_code_sug_bakasha = 1 and mod(v_code_seif_prisha,100) not in(26,28) then
         v_street := reverse_mispar(v_street);
      --end if;
    else
       v_td := lpad_zeroez(0,6);
       if(instr(v_street,'1') >0
       or instr(v_street,'2') >0
       or instr(v_street,'3') >0
       or instr(v_street,'4') >0
       or instr(v_street,'5') >0
       or instr(v_street,'6') >0
       or instr(v_street,'7') >0
       or instr(v_street,'8') >0
       or instr(v_street,'9') >0
       or instr(v_street,'0') >0) then
        if v_street not like '% /%' then
          v_street := reverse_mispar(v_street);
        else
          v_street := reverse_mispar(reverse_mispar(v_street));
        end if;     
       end if;
   end if;
    if v_house is null then v_house := 0; end if;
    if v_appartment is null then v_appartment := 0; end if;
    if v_entrance is null then v_entrance := ' '; end if;
    if v_mikud is null then v_mikud := ' '; end if;
  end if;
  
    ld_log_events_record.code_event := 218;
    ld_log_events_record.code_event_semel := 0;
    prepare_trigger_0(v_seq_ld_protocol,
                      v_seq_ld_protocol_hilan,
                      v_seq_bakasha,
                      case when v_mispar_zehut_bakasha = 0 then
                        case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut else v_mispar_zehut_sheer_benzug end
                        else get_mispar_zehut_fictivi(v_mispar_zehut_bakasha,v_gimla_number) end,
                      v_gimla_number,
                      false,
                      case when v_code_sug_bakasha = 1 or v_code_sug_bakasha = 5 and nvl(v_code_bakasha_detail,0) = 25 then v_date_start_zakaut
                           when v_code_sug_bakasha = 12 then v_hp_date_start_zakaut
                           /*when v_update_date is not null then
                             to_date(to_char(v_update_date,date_format_d6) || '01',date_format_d8)  */   
                           else to_date(to_char(sysdate,date_format_d6) || '01',date_format_d8) end                                          
                      );    
                       
    if insert_event then
    ld_log_events_record.code_trigger := 2;
    ld_log_events_record.record_hilan :=    
           lpad_zeroez(v_city_code,4) ||                                                                                     --SEMEL_YISHUV
           rpad_blanks(v_city,13) ||                                                                                         --YISHUV
           case when v_house is null or v_code_sug_bakasha in (33,35) then
                rpad_blanks(trim(v_street),28)                                                                               --address
           else
                rpad_blanks(trim(v_street),17) ||                                                                            --REHOV
                lpad_zeroez(v_house,5) ||                                                                                    --BAIT
                lpad_zeroez(v_appartment,4) ||                                                                               --DIRA
                rpad_blanks(v_entrance,2) end  ||                                                                            --KNISA
           rpad_blanks(' ',2) ||                                                                                             --FILLER
          (case when v_mikud = ' ' then lpad_zeroez(0,7) else lpad_zeroez(to_number(v_mikud),7) end) ||                       --MIKUD
           case when v_code_sug_bakasha <> 21 then get_telephone(v_telephon) else  lpad_zeroez(0,10) end ||                                                     --TELEFON
           v_td ||                                                                                                           --TA_DOAR
           lpad_zeroez(0,7) ||                                                                                               --MIKUD_TA_DOAR
           lpad_zeroez(0,4) ||                                                                                               --YISHUV_TA_DOAR
           case when v_code_sug_bakasha <> 21 then get_telephone(v_pelephon) else lpad_zeroez(0,10) end ||                                                                                      --TELEFON_2
           case when v_code_sug_bakasha <> 21 then get_telephone(v_telephon2) else lpad_zeroez(0,10) end ||                                                                                     --TELEFON_3
           lpad_zeroez(0,10) ||                                                                                              --FAX
           rpad_blanks(v_email,30) ||                                                                                        --E_MAIL
           rpad_blanks(' ',7);   
           --18/06/2020 - טיפול חדש בשליחת בקשות שינוי כתובת וטלפון                                                                                            --FILLER
           ld_log_events_record.record_hilan := rpad(ld_log_events_record.record_hilan,155) ||
            case when v_code_sug_bakasha in (33,35) then '1'
                 when v_code_sug_bakasha = 21 then '2'
                 else ' ' end;
           --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
       return insert_event;
    else
      return false;
    end if;
    exception
    when others then
      status  := 0;
      message := sqlerrm;
      clob_log := clob_log ||('insert_event_218: ' || message) ||  '<br />';
      v_error_172_message := 'insert_event_218: ' || message;
      v_error_172_seq_bakasha := v_seq_bakasha;
      v_error_172_mispar_zehut := v_mispar_zehut;
      return false;
    end;
  ------------------------------------  
   --כתובת
  function check_event_218(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                         ) return boolean is
  v_city_code number;
  v_city varchar2(30);
  v_street varchar2(100);
  v_house number;
  v_appartment number;
  v_entrance varchar2(10);
  v_mikud varchar2(10);
  v_telephon varchar2(30);
  v_telephon2 varchar2(30);
  v_pelephon varchar2(30);
  v_email varchar2(50);
  v_update_date date;
  v_mispar_zehut_sheer_benzug number :=0;
  v_mispar_zehut_sheer_benzug_amiti number :=0;
  v_exists_sheer_address number;
  v_mispar_zehut_bakasha number := 0;
  
  begin
    if v_mistz_almana_benzug_sheer <> 0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan <> 0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    
    if v_mispar_zehut_sheer_benzug <>0 then
        select 
        case when exists(select b.mispar_zehut_ben_mishpacha
        from bney_mishpacha b, address a
        where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
        and a.seq_bney_mishpacha = b.seq_bney_mishpacha
        and not a.code_city is null) then 1 else 0 end
        into v_exists_sheer_address
        from dual t;
    end if;
        
    if v_code_sug_bakasha <> 21 then --לא בקשת שינוי כתובת
    if v_mispar_zehut_sheer_benzug = 0 or v_exists_sheer_address = 0 then
    begin
      v_mispar_zehut_bakasha := v_mispar_zehut_amiti;
    select  a.code_city, a.street, a.house, a.apartment, a.entrance,
            a.mikud, a.date_update,
            p.telephon, p.telephon2, p.pelephon, p.email
            into v_city_code, v_street, v_house, v_appartment, v_entrance,
            v_mikud, v_update_date,
            v_telephon, v_telephon2, v_pelephon, v_email
            from poresh p, address a
            where p.mispar_zehut = v_mispar_zehut_amiti
            and a.seq_poresh = p.porshim_seq
            and a.seq_bney_mishpacha is null
            and (a.code_address = 1
            and a.seq_address = 
            (select max(a1.seq_address)
            from address a1
            where a1.seq_poresh = p.porshim_seq
            and a1.seq_bney_mishpacha is null
            and a1.code_address = 1)
            and (not exists (select *
            from address a1
            where a1.seq_poresh = p.porshim_seq
            and a1.seq_bney_mishpacha is null
            and a1.code_address = 2))
            or
            (a.code_address = 2
            and a.seq_address = 
            (select max(a1.seq_address)
            from address a1
            where a1.seq_poresh = p.porshim_seq
            and a1.seq_bney_mishpacha is null
            and a1.code_address = 2)));      exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0218','0000',16,': ' || to_char(v_mispar_zehut),message);
      end;
    else
      begin
      v_mispar_zehut_bakasha := v_mispar_zehut_sheer_benzug_amiti;
      select  a.code_city, a.street, a.house, a.apartment, a.entrance,
            a.mikud, a.date_update,
            b.telephone, null, b.pelephone, b.email
            into v_city_code, v_street, v_house, v_appartment, v_entrance,
            v_mikud, v_update_date,
            v_telephon, v_telephon2, v_pelephon, v_email
            from bney_mishpacha b, address a
            where not b.code_kirva is null
            and b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
            and a.seq_poresh is null
            and a.seq_bney_mishpacha = b.seq_bney_mishpacha
            and (a.code_address = 1
            and a.seq_address = 
            (select max(a1.seq_address)
            from address a1
            where a1.seq_bney_mishpacha = b.seq_bney_mishpacha
            and a1.code_address = 1)
            and (not exists (select *
            from address a1
            where a1.seq_poresh is null
            and a1.seq_bney_mishpacha = b.seq_bney_mishpacha
            and a1.code_address = 2))
            or
            (a.code_address = 2
            and a.seq_address = 
            (select max(a1.seq_address)
            from address a1
            where a1.seq_poresh is null
            and a1.seq_bney_mishpacha = b.seq_bney_mishpacha
            and a1.code_address = 2)));
      exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0218','0000',16,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
      end;
    end if;
    else
      begin
      select distinct a.code_city, a.street, a.house, a.apartment, a.entrance,
           a.mikud, a.date_update,
           case when not a.seq_poresh is null then p.telephon else b.telephone end,
           case when not a.seq_poresh is null then p.telephon2 else null end,
           case when not a.seq_poresh is null then p.pelephon else b.pelephone end,
           case when not a.seq_poresh is null then p.email else b.email end,
           case when not a.seq_poresh is null then p.mispar_zehut else b.mispar_zehut_ben_mishpacha end
           into v_city_code, v_street, v_house, v_appartment, v_entrance,
           v_mikud, v_update_date,
           v_telephon, v_telephon2, v_pelephon, v_email,
           v_mispar_zehut_bakasha           
      from address a, poresh p, bney_mishpacha b
      where a.seq_bakasha = v_seq_bakasha
      and p.mispar_zehut = v_mispar_zehut_amiti
      and (a.seq_bney_mishpacha is null
         and a.seq_poresh = p.porshim_seq   
      or not 
        a.seq_bney_mishpacha is null
        and a.seq_bney_mishpacha = b.seq_bney_mishpacha
        and b.seq_porshim = p.porshim_seq);
      exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0218','0000',16,': ' || to_char(v_mispar_zehut_bakasha),message); 
      end;
    end if;
   
    v_city := substr(get_yishuv(v_city_code),1,13);
    if not v_street is null then 
       v_street := replace(replace(v_street,'  ',' '),'  ',' ');
    end if;
    if v_appartment is null then v_appartment := 0; end if;
    if v_entrance is null then v_entrance := ' '; end if;
    --v_street := reverse_mispar(v_street);
    
    if v_city_code is null then
       build_check_message(1,'0218','0000',17,': ' || to_char(v_mispar_zehut_bakasha),message);
    end if;   
    if v_street is null then
       build_check_message(2,'0218','0000',18,': ' || to_char(v_mispar_zehut_bakasha),message);
    end if;
    if v_mikud is null then
       build_check_message(2,'0218','0000',19,': ' || to_char(v_mispar_zehut_bakasha),message);
    end if;
    return true;
    end;
  ------------------------------------  
  -- קרובי משפחה
  function insert_event_219(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
  v_mispar_zehut_ben_mishpacha number;
  v_shem_mishpacha varchar2(50);
  v_shem_prati varchar2(50);
  v_taarich_leida  date;
  v_code_kirva number;
  v_code_kirva_hilan varchar2(1);
  v_code_min number;
  return_code boolean := true;
  is_first boolean := true;
  
begin
    for r in 
            (select distinct b.mispar_zehut_ben_mishpacha, b.shem_prati, b.shem_mishpacha, 
                     b.code_kirva, b.taarich_leda, b.code_min
            from poresh p
            left join  bney_mishpacha b on
            b.seq_porshim = p.porshim_seq
            left join  mazav_mishpachti m on
            m.seq_poresh = p.porshim_seq
            where p.mispar_zehut = v_mispar_zehut_amiti
            and m.seq_bney_mishpacha is null
            and b.taarich_ptira is null
            and (b.code_kirva = 1 
            and (m.code_mazav_mishpachti = 6 --פוליגם
            or (m.code_mazav_mishpachti <> 6 or m.code_mazav_mishpachti is null)
            and b.seq_bney_mishpacha = (select max(b1.seq_bney_mishpacha)
                                                             from bney_mishpacha b1
                                                             where b1.seq_porshim = p.porshim_seq
                                                             and b1.code_kirva = 1))
            or ((b.code_kirva = 2 or b.code_kirva = 23)
            and b.taarich_leda is null
            or sysdate - b.taarich_leda < 365*21)))     
    loop
    begin
           
    if is_first then
      is_first := false;
      ld_log_events_record.code_event := 219;
      ld_log_events_record.code_event_semel := 0;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        v_mispar_zehut,
                        v_gimla_number,
                        false,
                        sysdate);
       return_code := insert_event;
    end if;
    if return_code then
    v_mispar_zehut_ben_mishpacha := r.mispar_zehut_ben_mishpacha;
    v_shem_mishpacha := r.shem_mishpacha;
    v_shem_prati := r.shem_prati;
    v_code_kirva := r.code_kirva;
    v_code_min := r.code_min;                            
    v_code_kirva_hilan := get_code_kirva_hilan(nvl(v_code_kirva,0),nvl(v_code_min,1));
    v_taarich_leida := r.taarich_leda;
    ld_log_events_record.code_trigger := 2;
    ld_log_events_record.record_hilan :=    
           rpad_blanks(v_shem_prati,10) ||                                     --SHEM
           lpad_zeroez(v_mispar_zehut_ben_mishpacha,9) ||                      --ZEHUT
           to_char(v_taarich_leida,date_format_d8) ||                          --LEIDA
           v_code_kirva_hilan ||                                               --KOD
           lpad_zeroez(0,8) ||                                                 --TAARICH
           lpad_zeroez(0,8) ||                                                 --GMARTOKEF
           lpad_zeroez(0,8) ||                                                 --TAARICH1
           lpad_zeroez(0,8);                                                   --TAARICH2
           --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
           return_code := insert_event;
     else
       return false;
     end if;
   end;
   end loop;
   return return_code;
   exception
    when others then
      status  := 0;
      message := sqlerrm;
      clob_log := clob_log ||('insert_event_219: ' || message) ||  '<br />';
      v_error_172_message := 'insert_event_219: ' || message;
      v_error_172_seq_bakasha := v_seq_bakasha;
      v_error_172_mispar_zehut := v_mispar_zehut;
      return false;
    end;
  ------------------------------------  
  -- קרובי משפחה
  function check_event_219(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
  v_mispar_zehut_ben_mishpacha number;
  v_shem_mishpacha varchar2(50);
  v_shem_prati varchar2(50);
  v_taarich_leida  date;
  v_code_kirva number;
  v_code_kirva_hilan varchar2(1);
  v_code_min number;
  return_code boolean := true;
  is_first boolean := true;
  
begin
    for r in 
            (select distinct b.mispar_zehut_ben_mishpacha, b.shem_prati, b.shem_mishpacha, 
                     b.code_kirva, b.taarich_leda, b.code_min
            from poresh p
            left join  bney_mishpacha b on
            b.seq_porshim = p.porshim_seq
            left join  mazav_mishpachti m on
            m.seq_poresh = p.porshim_seq
            where p.mispar_zehut = v_mispar_zehut_amiti
            and m.seq_bney_mishpacha is null
            and b.taarich_ptira is null
            and (b.code_kirva = 1 
            and (m.code_mazav_mishpachti = 6 --פוליגם
            or (m.code_mazav_mishpachti <> 6 or m.code_mazav_mishpachti is null)
            and b.seq_bney_mishpacha = (select max(b1.seq_bney_mishpacha)
                                                             from bney_mishpacha b1
                                                             where b1.seq_porshim = p.porshim_seq
                                                             and b1.code_kirva = 1))
            or ((b.code_kirva = 2 or b.code_kirva = 23)
            and b.taarich_leda is null
            or sysdate - b.taarich_leda < 365*21)))     
    loop
    begin           
    v_mispar_zehut_ben_mishpacha := r.mispar_zehut_ben_mishpacha;
    v_shem_mishpacha := r.shem_mishpacha;
    v_shem_prati := r.shem_prati;
    v_code_kirva := r.code_kirva;
    v_code_min := r.code_min;                            
    v_code_kirva_hilan := get_code_kirva_hilan(nvl(v_code_kirva,0),nvl(v_code_min,1));
    v_taarich_leida := r.taarich_leda;
    if v_mispar_zehut_ben_mishpacha is null then
      build_check_message(1,'0219','0000',20,'');
    end if;
    if v_shem_mishpacha is null then
      build_check_message(1,'0219','0000',21,'');
    end if;
    if v_shem_prati is null then
      build_check_message(1,'0219','0000',22,'');
    end if;
    if v_code_min is null then
      build_check_message(2,'0219','0000',23,'');
    end if;                            
    if v_code_kirva_hilan is null then
      build_check_message(1,'0219','0000',24,'');
    end if;
    end;
    end loop;
   return true;
   end;
  ------------------------------------  
  --דואר אלקטרוני
  function insert_event_298(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
    v_email varchar2(50);
    v_mispar_zehut_sheer_benzug number :=0;
    v_mispar_zehut_sheer_benzug_amiti number :=0;
    v_code_relative number;
    
  begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
 
     if v_code_sug_bakasha = 12 or v_code_sug_bakasha in (1,13) and v_mispar_zehut_sheer_benzug <> 0 then
            select b.email
            into v_email
            from bney_mishpacha b, poresh p
            where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
            and p.mispar_zehut = v_mispar_zehut_amiti
            and b.seq_porshim = p.porshim_seq;
     elsif v_mispar_zehut_sheer_benzug = 0 /* פורש */ then 
            select p.email
            into v_email
            from poresh p
            where p.mispar_zehut = v_mispar_zehut_amiti;
     elsif v_code_sug_bakasha = 33 and v_mispar_zehut_sheer_benzug <> 0 then
             --בינתיים נשלחים מיילים של פורש גם לשאר בן זוג
             --מפני שהמערכת מעדכנת טלפונים של הפורש  אפילן אחרי פטירתו
            select p.email
            into v_email
            from poresh p, bney_mishpacha b
            where p.mispar_zehut = v_mispar_zehut_amiti
            and b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti;
            if v_code_relative not in (1,5) then --כרגע אין עדכון מספרי מייל עבור שארים אחרים
              return true;
            end if;
      end if;           

      if v_email is null then  return true; end if;
      
      ld_log_events_record.code_event := 298;
      ld_log_events_record.code_event_semel := v_semel_hilan;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut else v_mispar_zehut_sheer_benzug end,
                        v_gimla_number,
                        false,
                        sysdate);
                      
      if insert_event then   
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             rpad_blanks(v_email,66) ||                       --E_MAIL
             to_char(sysdate,date_format_d8) ||               --TAARICH
             '00000000';                                      --GMARTOKEF
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
      return insert_event;
      else
        return false;
      end if;
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_298: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_298: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
      return false;
    end;
  ------------------------------------  
  --דואר אלקטרוני
  function check_event_298(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
    v_email varchar2(50);
    v_mispar_zehut_sheer_benzug number :=0;
    v_mispar_zehut_sheer_benzug_amiti number :=0;
  begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
 
     if (v_code_sug_bakasha = 12) then
     begin
     select b.email
            into v_email
            from bney_mishpacha b
            where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
            and not b.email is null;
       exception
      when others then
      message := sqlerrm;
      build_check_message(2,'0298','0001',25,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
      end;
     end if;     
     if (v_code_sug_bakasha <> 12) or
        (v_code_sug_bakasha = 12) and v_email is null then
     begin
     select p.email
            into v_email
            from poresh p
            where p.mispar_zehut = v_mispar_zehut_amiti
            and not p.email is null;
      exception
      when others then
      message := sqlerrm;
      build_check_message(2,'0298','0001',25,': ' || to_char(v_mispar_zehut),message);
      end;
      end if;     
     return true;
  end;
  ------------------------------------  
  --פרטי בנק
  --פרטי בנק
   function insert_event_303(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_code_bank number;
   v_code_snif number;
   v_heshbon number;
   v_date_update date;
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_zehut_sheer_benzug_amiti number :=0;
   v_exists_sheer_cheshbon number;
   v_mispar_zehut_bakasha number := 0;
   v_code_relative number;
   v_erech number;
   v_erech2 number;
   
 begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 

    if v_mispar_zehut_sheer_benzug = 0 and v_code_sug_bakasha = 15 then
      select b.mispar_zehut_ben_mishpacha
      into v_mispar_zehut_sheer_benzug
      from bank_account ba
      left join bney_mishpacha b
      on b.seq_bney_mishpacha = nvl(ba.seq_bney_mishpacha,0)
      and b.code_relative = 6
      where ba.seq_bakasha = v_seq_bakasha;
      if v_mispar_zehut_sheer_benzug is null then
        v_mispar_zehut_sheer_benzug := 0;
      else
        v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
      end if;   
    end if;
 
    if v_mispar_zehut_sheer_benzug <>0 then 
     select b.code_relative
        into v_code_relative
        from bney_mishpacha b, poresh p
        where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
        and p.mispar_zehut = v_mispar_zehut
        and b.seq_porshim = p.porshim_seq;
     select 
        case when exists(select b.mispar_zehut_ben_mishpacha
        from bney_mishpacha b, v_bank_account a, v_bakasha_last_status v
        where  b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
               and a.seq_bney_mishpacha = b.seq_bney_mishpacha
               and (a.seq_bakasha = v_seq_bakasha or
               a.seq_bakasha < v_seq_bakasha and 
               a.seq_bakasha = v.seq_bakasha and
               v.gimla_number = v_gimla_number and
               v.code_action = 98)
        ) then 1 else 0 end
        into v_exists_sheer_cheshbon
        from dual t;
    end if;
  
    
    if v_code_sug_bakasha <> 15 then
       if v_mispar_zehut_sheer_benzug <> 0 then
        if v_exists_sheer_cheshbon = 0  then
        if (v_mistz_almana_benzug_sheer <> 0 or v_mispar_zehut_ben_katan <> 0 and v_code_relative <> 2)    then
          --build_check_message(1,'0303','0000',26,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
          return true;
        elsif v_mispar_zehut_ben_katan <> 0 and v_code_relative = 2 then
          select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update
          into v_code_bank, v_code_snif, v_heshbon, v_date_update
          from
          (select a.*
          from bney_mishpacha b, v_bank_account a
          where b.code_relative = 1
          and a.seq_bney_mishpacha = b.seq_bney_mishpacha
          and a.seq_bakasha = ( 
              select max(v.seq_bakasha)
               from v_bakasha_last_status v
               where v.seq_bakasha <= v_seq_bakasha and 
                v.gimla_number = v_gimla_number and
                (v.code_action = 98 or v.seq_bakasha=v_seq_bakasha))
          order by a.seq_bank_account desc) aa
          where rownum = 1;
        end if;
        else
          select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update
          into v_code_bank, v_code_snif, v_heshbon, v_date_update
          from
          (select a.*
          from bney_mishpacha b, v_bank_account a
          where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
          and a.seq_bney_mishpacha = b.seq_bney_mishpacha
          and a.seq_bakasha = ( 
              select max(v.seq_bakasha)
               from v_bakasha_last_status v
               where v.seq_bakasha <= v_seq_bakasha and 
                v.gimla_number = v_gimla_number and
                (v.code_action = 98 or v.seq_bakasha=v_seq_bakasha))
          order by a.seq_bank_account desc) aa
          where rownum = 1;           
        end if;
       else
          select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update
          into v_code_bank, v_code_snif, v_heshbon, v_date_update
          from
          (select a.*
          from v_bank_account a, poresh p
          where a.seq_porshim = p.porshim_seq
                and nvl(a.seq_bney_mishpacha,0) = 0
          and a.seq_bakasha = ( 
              select max(v.seq_bakasha)
               from v_bakasha_last_status v
               where v.seq_bakasha <= v_seq_bakasha and 
                v.gimla_number = v_gimla_number and
                (v.code_action = 98 or v.seq_bakasha=v_seq_bakasha))
          order by a.seq_bank_account desc
          ) aa
          where rownum = 1;
       end if;
    else
      if v_mispar_zehut_sheer_benzug = 0 then
      select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update, p.mispar_zehut
      into v_code_bank, v_code_snif, v_heshbon, v_date_update, v_mispar_zehut_bakasha         
      from v_bank_account aa, poresh p
      where aa.seq_bakasha = v_seq_bakasha
      and p.mispar_zehut = v_mispar_zehut_amiti
      and aa.seq_bney_mishpacha is null
      and aa.seq_porshim = p.porshim_seq;
      else
      select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update, b.mispar_zehut_ben_mishpacha
      into v_code_bank, v_code_snif, v_heshbon, v_date_update, v_mispar_zehut_bakasha         
      from v_bank_account aa, poresh p, bney_mishpacha b
      where aa.seq_bakasha = v_seq_bakasha
      and p.mispar_zehut = v_mispar_zehut_amiti
      and not aa.seq_bney_mishpacha is null
      and aa.seq_bney_mishpacha = b.seq_bney_mishpacha
      and p.porshim_seq = b.seq_porshim
      and b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti;
      end if;
     end if;  
      
     if v_code_bank <> 0 and not v_code_bank is null then
      if not v_3120322 then
      ld_log_events_record.code_event := 303;
      ld_log_events_record.code_event_semel := 0;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_bakasha = 0 then
                        case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut else v_mispar_zehut_sheer_benzug end
                        else get_mispar_zehut_fictivi(v_mispar_zehut_bakasha,v_gimla_number) end,
                        case when v_mispar_misrot_sach_hakol = 1 then v_gimla_number
                                  else v_gimla_number * 10 + 1 end,
                        true,
                        --false,
                        case when v_date_update is not null then
                          case when v_code_sug_bakasha = 1 and v_date_update < v_date_start_zakaut then v_date_start_zakaut
                               else v_date_update end
                        else sysdate end);                      
      if insert_event then   
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             lpad_zeroez(v_code_bank,3) ||                    --MISPAR BANK
             lpad_zeroez(v_code_snif,3) ||                    --SNIF
             lpad_zeroez(v_heshbon,9);                        --HESHBON
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
       return insert_event;
      else
       return false;
      end if;
      else
      ld_log_events_record.code_event := 312;
      ld_log_events_record.code_event_semel := 322;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_bakasha = 0 then
                        case when v_mispar_zehut_sheer_benzug = 0 then v_mispar_zehut else v_mispar_zehut_sheer_benzug end
                        else get_mispar_zehut_fictivi(v_mispar_zehut_bakasha,v_gimla_number) end,
                        case when v_mispar_misrot_sach_hakol = 1 then v_gimla_number
                                  else v_gimla_number * 10 + 1 end,
                        true,
                        --false,
                        case when v_date_update is not null then
                          case when v_code_sug_bakasha = 1 and v_date_update < v_date_start_zakaut then v_date_start_zakaut
                               else v_date_update end
                        else sysdate end);                      
      if insert_event then   
      ld_log_events_record.code_trigger := 2;
           v_erech := v_code_bank * 1000 + v_code_snif;
           v_erech2 := v_heshbon;                       
           ld_log_events_record.record_hilan := 
           '0' ||                                                                                            --MINUI
           lpad_zeroez(v_erech,9) ||                                                                         --ERECH                       
           lpad_zeroez(v_erech2,9) ||                                                                        --ERECH_2
           lpad_zeroez(0,9) ||                                                                               --ERECH_3
           rpad_blanks(' ',15) ||                                                                            --TEUR
           to_char(case when v_date_update is not null then
                          case when v_code_sug_bakasha = 1 and v_date_update < v_date_start_zakaut then v_date_start_zakaut
                               else v_date_update end
                        else sysdate end,date_format_d6) ||  '01' ||
           --'20070901'  ||                                                                                  --TAARICH
           lpad_zeroez(0,8);                                                                                 --GMATROKEF
       return insert_event;
      else
       return false;
      end if;
      end if;
     end if;
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_303: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_303: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;
  ------------------------------------  
  --פרטי בנק
    function check_event_303(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_code_bank number;
   v_code_snif number;
   v_heshbon number;
   v_date_update date;
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_zehut_sheer_benzug_amiti number :=0;
   v_exists_sheer_cheshbon number;
   v_mispar_zehut_bakasha number := 0;
  begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
 
    if v_mispar_zehut_sheer_benzug <>0 then 
        select 
        case when exists(select b.mispar_zehut_ben_mishpacha
        from bney_mishpacha b, bank_account a
        where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
        and a.seq_bney_mishpacha = b.seq_bney_mishpacha) then 1 else 0 end
        into v_exists_sheer_cheshbon
        from dual t;
    end if;
    
    if v_code_sug_bakasha <> 15 then
    if v_mispar_zehut_sheer_benzug <> 0 and v_exists_sheer_cheshbon = 1  then
      begin
      select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update
      into v_code_bank, v_code_snif, v_heshbon, v_date_update
      from
      (select a.*
      from bney_mishpacha b, bank_account a
      where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
      and a.seq_bney_mishpacha = b.seq_bney_mishpacha
      and a.seq_bakasha = v_seq_bakasha
      order by a.seq_bank_account desc) aa
      where rownum = 1;
     exception
      when no_data_found then
      return true;
      when others then
      message := sqlerrm;
      build_check_message(1,'0303','0000',26,': ' || to_char(v_mispar_zehut_sheer_benzug),message);
      return true;
     end;
    else
      begin    
      select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update
      into v_code_bank, v_code_snif, v_heshbon, v_date_update
      from
      (select a.*
      from poresh p, bank_account a
      where p.mispar_zehut = v_mispar_zehut_amiti
      and a.seq_bakasha = v_seq_bakasha
      order by a.seq_bank_account desc) aa
      where rownum = 1;
      exception
      when no_data_found then
      return true;
      when others then
      message := sqlerrm;
      build_check_message(1,'0303','0000',26,': ' || to_char(v_mispar_zehut),message);
      return true;
      end;
    end if;
    else
      begin
      select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update, p.mispar_zehut
      into v_code_bank, v_code_snif, v_heshbon, v_date_update, v_mispar_zehut_bakasha         
      from v_bank_account aa, poresh p
      where aa.seq_bakasha = v_seq_bakasha
      and p.mispar_zehut = v_mispar_zehut_amiti
      and aa.seq_bney_mishpacha is null
      and aa.seq_porshim = p.porshim_seq
      union
      select aa.code_bank, aa.code_snif, aa.account_number, aa.date_update, b.mispar_zehut_ben_mishpacha
      from v_bank_account aa, poresh p, bney_mishpacha b
      where aa.seq_bakasha = v_seq_bakasha
      and p.mispar_zehut = v_mispar_zehut_amiti 
      and not aa.seq_bney_mishpacha is null
      and aa.seq_bney_mishpacha = b.seq_bney_mishpacha
      and p.porshim_seq = b.seq_porshim;
      exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0303','0000',26,'',message);
      return true;
      end;
    end if;
     if v_code_bank is null then
      build_check_message(1,'0303','0000',26,'');
      return true;
     end if;
     if v_code_snif is null then
      build_check_message(1,'0303','0000',26,'');
      return true;
     end if;
     if v_heshbon is null then
      build_check_message(1,'0303','0000',26,'');
      return true;
     end if;
     v_is_heshbon_bank := 2; --תקין
   return true;
   end;
  ------------------------------------  
  --פרטי דירוג דרגה
   function insert_event_535(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_taarich_me date;
   v_taarich_me_report date;
   v_taarich_me_str varchar2(8);
   v_taarich_ad date;                            
   v_code_derug number;
   v_code_darga varchar2(4);
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_zehut_sheer_benzug_amiti number :=0;
   v_mispar_misra number;
   v_derug_first0 boolean := true;
   v_derug_first1 boolean := true;
   v_ofek_first0 boolean := true;
   v_ofek_first1 boolean := true;
  
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 

    --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    --if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 
    
     if v_sachar_reforma <> 0 then
       select count(*)  --שכר אחרון , האם יש אופק חדש?
       into v_derug_ofek
       from netuney_sachar n
       left join chinuch_reforma cr on
       cr.seq_chinuch_reforma = n.seq_chinuch_reforma
       left join code_sug_maskoret m on
       m.code_sug_maskoret = n.code_sug_maskoret
       and m.code_chinuch_alterntive = cr.code_chinuch_alterntive
       where cr.code_reforma = 1
       and cr.code_chinuch_alterntive = 1
       and m.code_chinuch_sug_maskoret = 1
       and n.seq_bakasha = v_seq_bakasha;
     end if;
     
     --if v_derug_ofek > 0 then

     for r in (/*select n.*
      from netuney_sachar n
      where n.seq_bakasha = v_seq_bakasha
      and (v_sachar_reforma <> 1 and n.code_sug_maskoret = 1
      or v_sachar_reforma = 1 and n.code_sug_maskoret =
      (select c.code_sug_maskoret
      from code_sug_maskoret c
      where c.code_sug_maskoret = n.code_sug_maskoret
      and c.code_chinuch_sug_maskoret = 1))
      order by n.mispar_misra)*/
      select n.*, cr.code_reforma, cr.code_chinuch_alterntive
      from netuney_sachar n
      left join chinuch_reforma cr on
      cr.seq_chinuch_reforma = n.seq_chinuch_reforma
      left join code_sug_maskoret c1 on                                                                                                                                               
      c1.code_sug_maskoret = n.code_sug_maskoret
      and c1.code_chinuch_alterntive = cr.code_chinuch_alterntive
      left join code_chinuch_sug_maskoret c2 on
      c2.code_chinuch_sug_maskoret = c1.code_chinuch_sug_maskoret
      and c2.code_chinuch_sug_maskoret = 1
      where n.seq_bakasha = v_seq_bakasha
      and (cr.code_reforma is not null or
      cr.code_reforma is null and n.code_sug_maskoret = 1)
      --and cr.code_chinuch_alterntive is not null      
      --and not (cr.code_reforma = 1 and cr.code_chinuch_alterntive = 1)
      )
      --for i in 1 .. v_mispar_misrot_leprisha
     loop
            
    v_mispar_misra := r.mispar_misra;
    v_taarich_me := r.from_date;
    
    if  v_sachar_reforma <> 0  and r.code_reforma = 1 and r.code_chinuch_alterntive = 1 then
              if r.mispar_misra = 0 and v_ofek_first0 = false then continue; end if; 
              if r.mispar_misra = 0 then v_ofek_first0 := false; end if;
              if r.mispar_misra = 10 and v_ofek_first1 = false then continue; end if; 
              if r.mispar_misra = 1 then v_ofek_first1 := false; end if;
                   insert_or_check_event_dynamic(312,
                                  '0535',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mistz_almana_benzug_sheer,
                                  v_mispar_zehut_ben_katan,
                                  v_code_seif_prisha,
                                  0);
             if not if_commit then return false; else continue; end if;
    end if;

    
    begin
    select cd.derug_hilan, cd.darga_hilan
    into v_code_derug, v_code_darga
    from code_derug_darga_hilan cd
    where cd.derug_malam = r.code_derug
    and cd.darga_malam = r.code_darga;
    
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_535: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_535: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;
 
    if v_sachar_reforma <> 0 and v_code_derug >= 100 then continue; end if;
 
    if v_sachar_reforma <> 0 and v_code_derug < 100 then
        if r.mispar_misra = 0 and v_derug_first0 = false then continue; end if;
        if r.mispar_misra = 0 and v_derug_first1 = false then continue; end if;
        if r.mispar_misra = 0 then v_derug_first0 := false; end if;
        if r.mispar_misra = 1 then v_derug_first1 := false; end if;
    end if;

   if v_code_derug <> 0 and not v_code_derug is null then
      ld_log_events_record.code_event := 535;
      ld_log_events_record.code_event_semel := '0000';
      v_taarich_me_str := case when v_taarich_me is null then to_char(sysdate,date_format_d6) || '01' 
                                          else to_char(v_taarich_me,date_format_d6) || '01' end;
      v_taarich_me_report := to_date(v_taarich_me_str,date_format_d8);
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug else v_mispar_zehut end,
                        case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                        else 
                                v_gimla_number
                        end,
                        true,
                        v_taarich_me_report);                      
      if not insert_event then return false; end if;
       
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                          --MINUI
             lpad_zeroez(v_code_derug,2) ||                                                                                  --DERUG
             lpad_zeroez(v_code_darga,4) ||                                                                                  --DARGA
             (case when v_taarich_me is null then lpad_zeroez(0,8) else to_char(v_taarich_me,date_format_d8) end) ||         --TAARICH                                                                                      
             lpad_zeroez(0,8);                                                                                               --GMARTOKEF
             /*(case when v_taarich_ad is null then lpad_zeroez(0,8)                                                         
                   when v_taarich_ad = to_date('31/12/9999','DD/MM/YYYY') then lpad_zeroez(0,8)
                   else to_char(v_taarich_me,date_format_d8) end);*/
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
             if not insert_event then return false; end if;
    end if;
    end loop;
    return true;
    exception
/*    when no_data_found then
       return true;*/
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_535: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_535: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;
  ------------------------------------
  --פרטי דירוג דרגה
   function check_event_535(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_taarich_me date;
   v_taarich_me_report date;
   v_taarich_me_str varchar2(8);
   v_taarich_ad date;                            
   v_code_derug number;
   v_code_darga varchar2(4);
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_zehut_sheer_benzug_amiti number :=0;
   v_mispar_misra number;
   v_times number := 0;
   
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 

    --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    --if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 
    
    for r in (select n.*
      from netuney_sachar n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_sug_maskoret = 1
      order by n.mispar_misra) loop
      
    v_mispar_misra := r.mispar_misra;
    v_taarich_me := r.from_date;
    
    select cd.derug_hilan, cd.darga_hilan
    into v_code_derug, v_code_darga
    from code_derug_darga_hilan cd
    where cd.derug_malam = r.code_derug
    and cd.darga_malam = r.code_darga;
 
    if v_code_derug is null then
       build_check_message(1,'0535','0000',27,'');
    end if;
    if v_code_darga is null then
       build_check_message(1,'0535','0000',27,'');
    end if;
    v_times := v_times + 1;    
    end loop;
    if v_times = 0 then
       build_check_message(1,'0535','0000',27,'');
    end if;
    
    return true;
    end;
  ------------------------------------
  -- הפסקת / חידוש תשלטמים
   function insert_event_221(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_taarich_me date;
   v_taarich_ad date;                            
   v_code_matzav number;
   v_code_matzav_hidush number;
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_zehut_sheer_benzug_amiti number :=0;
   v_ld_log_events_seq_cur_value number;
   v_hafsakat_ben_zug boolean;
   v_mispar_misra number;
   v_mistz_almana_benzug_sheer1 number := 0;
   v_mispar_zehut_ben_katan1 number := 0;
   v_mispar_zehut_sheer number := 0;
   v_seq_bney_mishpacha number;
   v_code_relative number;

    begin
       if v_code_sug_bakasha = 5 then
         --if v_code_bakasha_detail <> 25 then return true; end if;
         if v_code_group_prisha = 4 and v_seq_bakasha <> 380670 then return true; end if;
         v_taarich_me := v_date_start_zakaut;
         v_code_matzav := 0;
       else
       select t.from_date, nvl(c.code_bakasha_hilan,0), c.code_bakasha_detail, t.seq_bney_mishpacha
           into v_taarich_me, v_code_matzav, v_code_matzav_hidush, v_seq_bney_mishpacha
           from bakasha t, code_bakasha_detail c
           where t.seq_bakasha = v_seq_bakasha
           and t.code_bakasha_detail = c.code_bakasha_detail;
     -- if v_taarich_me >=trunc(Last_Day(sysdate) + 1) then return true; end if;
      if v_seq_bney_mishpacha is not null and v_seq_bney_mishpacha <> 0 then
         select b.mispar_zehut_ben_mishpacha, b.code_relative
         into v_mispar_zehut_sheer, v_code_relative
         from bney_mishpacha b 
         where b.seq_bney_mishpacha = v_seq_bney_mishpacha;
         v_mispar_zehut_sheer := get_mispar_zehut_fictivi(v_mispar_zehut_sheer,v_gimla_number);
       end if;
      v_count_221 := v_count_221 + 1;
      if v_count_221 > 1 then return true; end if;
 
      if v_mispar_zehut_sheer <>0 then
        v_ld_log_events_seq_cur_value := ld_log_events_seq.currval;
        update ld_log_events t
               set t.mispar_zehut = v_mispar_zehut_sheer
               where t.seq_ld_protocol_hilan = v_seq_ld_protocol_hilan
               and t.mispar_zehut = v_mispar_zehut
               and t.seq_ld_log_events = v_ld_log_events_seq_cur_value;   
      end if;
      end if;        

   
      for i in 1 .. v_mispar_misrot_sach_hakol
      loop
      v_mispar_misra := i;  
      ld_log_events_record.code_event := 221;
      ld_log_events_record.code_event_semel := 0;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer <>0 then v_mispar_zehut_sheer
                             when v_seq_bakasha = 380670 then v_mistz_almana_benzug_sheer
                                                         else v_mispar_zehut end,
                        case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra,1))
                             else 
                                v_gimla_number
                             end,
                        true,
                        v_taarich_me);                      
      if insert_event then 
 
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                            --MINUI
             lpad_zeroez(v_code_matzav,2) ||                   --MATZAV
             to_char(v_taarich_me,date_format_d8) ||           --MITAARICH
             lpad_zeroez(0,8);                                 --ADTAARICH
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
            if insert_event then
              continue;
            else
              return false;
            end if;
        else 
             return false;
        end if;
      end loop;
         if v_code_sug_bakasha = 19 and v_code_relative = 6 then --בן זוג לשעבר
           --ביטול אירוע 315/0412 אצל הפורש
              insert_or_check_event_dynamic(315,
                                  '0412',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mispar_zehut_sheer,
                                  0,
                                  v_code_seif_prisha,
                                  1,
                                  v_mispar_misra,
                                  1);     
         end if;
         if v_code_sug_bakasha = 20 and v_code_relative = 6 then --בן זוג לשעבר
           --ביטול אירוע 315/0412 אצל הפורש
              insert_or_check_event_dynamic(315,
                                  '0412',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mispar_zehut_sheer,
                                  0,
                                  v_code_seif_prisha,
                                  1,
                                  v_mispar_misra,
                                  1);     
         end if;
         if v_code_sug_bakasha = 20 and v_seq_ezor_ovdim = 206 then
             v_date_start_zakaut := v_taarich_me; 
              insert_or_check_event_dynamic(312,
                                  '0180',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mispar_zehut_sheer,
                                  0,
                                  v_code_seif_prisha,
                                  1,
                                  v_mispar_misra,
                                  1);     
         end if;
         if v_code_matzav = 44 then --נישואין שניים  
             insert_or_check_event_dynamic(527,
                                  '0245',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mispar_zehut_sheer,
                                  0,
                                  v_code_seif_prisha,
                                  1,
                                  v_mispar_misra,
                                  1);  
             if not if_commit then return false; end if;
             insert_or_check_event_dynamic(527,
                                  '0246',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  get_mispar_zehut_amiti(v_mispar_zehut_sheer,v_gimla_number),
                                  0,
                                  v_code_seif_prisha,
                                  1,
                                  v_mispar_misra,
                                  1);  
              if not if_commit then return false; end if;            
        end if; 
    return true;
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_221: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_221: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;

  ------------------------------------  
  -- הפסקת / חידוש תשלומים
  function check_event_221(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_taarich_me date;
   v_taarich_ad date;                            
   v_code_matzav number;
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_zehut_sheer_benzug_amiti number :=0;

    begin
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 

     begin
      select t.from_date,
           t.code_bakasha_detail
           into v_taarich_me, v_code_matzav
           from bakasha t
           where t.seq_bakasha = v_seq_bakasha;
      if not v_code_matzav is null and not v_taarich_me is null then
      if v_code_sug_bakasha = 19 then  --הפסקת תשלומים
       v_code_matzav := v_code_matzav + 40;
       if v_mispar_zehut_ben_katan = 0 and v_code_matzav = 47  then  --תום זכאות יתום
               build_check_message(1,'0221','0000',49,'');
       end if;
      end if;
      end if;
      exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0221','0000',28,'',message);
      end;
      if v_taarich_me is null or v_code_matzav is null then
      build_check_message(1,'0221','0000',28,'');
      end if;
     return true;
    end;
   ------------------------------------  
   --נתוני היוון
    function insert_event_315(v_semel_hilan varchar2,                --567
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_date_hivun date;
   v_seq_hivun number;
   v_achuz_hivun float;
   v_hp_sheur_havara float;
   v_date_gmar_tokef_hivun date;
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_zehut_sheer_benzug_amiti number :=0;
   v_is_bitul_hivun number;
   v_mispar_misrot number;
   v_mispar_misra number;
   v_last_date_of_prev_month date;

    begin 
  
    ld_log_events_record.code_event := 315;
    ld_log_events_record.code_event_semel := v_semel_hilan;
   
    if v_semel_hilan = '0567' then --היוון

    if v_mistz_almana_benzug_sheer <> 0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if; 
    if v_mispar_zehut_ben_katan <> 0 or v_mispar_zehut_sheer_benzug <> 0
      then return true;
    end if;    
    
   select count(*)
   into v_mispar_misrot
      from netuney_tik_mechushavim n, v_bakasha_last_status v
      where v.gimla_number = v_gimla_number
      and v.code_sug_bakasha = 1
      and n.seq_bakasha = v.seq_bakasha
      and v.mispar_zehut = v_mispar_zehut
      and n.code_department = 2
      and v.code_action not in (17,100);
      
      
    select t.seq_hivun, t.date_bakasha, t.achuz_hivun, v.code_bakasha_detail
    into v_seq_hivun, v_date_hivun, v_achuz_hivun, v_is_bitul_hivun
    from hivun t, v_bakasha_last_status v
    where t.seq_bakasha = v.seq_bakasha
    and (v.code_sug_bakasha=16 and v.code_bakasha_detail in (2,3) or v.code_sug_bakasha<>16)
    and t.seq_bakasha = v_seq_bakasha;
  
    --תאריך תחילת ההיוון לא יהיה לפני תאריך תחילת הזכאות
    if v_date_hivun < v_date_start_zakaut then v_date_hivun := v_date_start_zakaut; end if; 
    
    --select last_day(add_months(min(t.date_bakasha),71))
    select last_day(add_months(v_date_hivun,71))
    into v_date_gmar_tokef_hivun
    from dual;
    
    /*from hivun t, v_bakasha_last_status v
    where t.seq_bakasha = v.seq_bakasha
    v.gimla_number = 308651
    and v.code_sug_bakasha = 16;
    and t.seq_bakasha = v.seq_bakasha
    and t.code_hivun = 2;*/
    
    for v_mispar_misra in 1 .. v_mispar_misrot loop

    if not v_seq_hivun is null then
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug <> 0  then v_mispar_zehut_sheer_benzug else v_mispar_zehut end,
                        case when v_mispar_misrot > 1  then v_gimla_number*10 + v_mispar_misra
                             else v_gimla_number end,
                        true,
                        v_date_hivun,
                        '  ' || lpad_zeroez(v_seq_hivun,9));                      
      if insert_event then  
      if v_is_bitul_hivun = 3 then continue;
      else
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                          --MINUI
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(v_seq_hivun,9) ||                                                                                   --ERECH
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(replace(to_char(v_achuz_hivun,'0000000.99'),'.',''),9) ||                                           --ERECH_2
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(0,9) ||                                                                                             --ERECH_3
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(0,9) ||                                                                                             --ERECH_4
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(0,9) ||                                                                                             --ERECH_5
             rpad_blanks(' ',15) ||                                                                                          --TEUR
             (case when v_date_hivun is null then lpad_zeroez(0,8) else to_char(v_date_hivun,date_format_d8) end) ||         --TAARICH
             lpad_zeroez(0,8);                                                                                               --GMARTOKEF
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
             if insert_event then continue; end if;
       end if;
      else
        return false;
      end if;
     end if;
     end loop;
     return true;
    elsif v_semel_hilan = '0412' and v_code_sug_bakasha = 19 then --ביטול חיסכון פנסיוני

        if to_char(f_get_taarich_tchula(v_seq_bakasha),'YYYYMM') < to_char(sysdate,'YYYYMM') then
            select Last_Day(ADD_MONTHS(sysdate,-1)) 
             into v_last_date_of_prev_month
            from dual;
        else
            select Last_Day(sysdate) 
             into v_last_date_of_prev_month
            from dual;
        end if;
       prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        v_mispar_zehut,
                        case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
                             else
                               v_gimla_number end,
                        true,
                        v_last_date_of_prev_month,
                        '  ' || rpad_blanks(' ',9));                      
      if insert_event then
        return true;
      else
        return false;
      end if; 
      
    elsif v_semel_hilan = '0412' and v_code_sug_bakasha = 12 then --חיסכון פנסיוני
      
    if v_mispar_misra = 1  then return true; end if;

      
    select t.hp_sheur_havara
    into v_hp_sheur_havara
    from bakasha_regila t
    where t.seq_bakasha = v_seq_bakasha;
    
    
    --SELECT to_date(LAST_DAY(ADD_MONTHS(sysdate,-1))) FROM DUAL    
    if not v_hp_sheur_havara is null then
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        v_mispar_zehut,
                        --'000000000',
                        case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
                             else
                               v_gimla_number end,
                        true,
                        v_hp_taarich_tokef_haavara,
                        '  ' || rpad_blanks(' ',9));                      
      if insert_event then   
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                          --MINUI
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(v_mistz_almana_benzug_sheer,9) ||                                                                  --ERECH
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(replace(to_char(v_hp_sheur_havara,'0000000.99'),'.',''),9) ||                                       --ERECH_2
             ' ' ||                                                                                                          --מינוס
             '0' ||  to_char(v_hp_date_start_zakaut,date_format_d8_reversed) ||                                                       --ERECH_3
             ' ' ||                                                                                                          --מינוס
             '0' ||  to_char(v_hp_date_haavara,date_format_d8_reversed) ||                                                            --ERECH_4
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(0,9) ||                                                                                             --ERECH_5
             rpad_blanks(' ',15) ||                                                                                          --TEUR
             to_char(v_hp_taarich_tokef_haavara,date_format_d8) ||                                                              --TAARICH
             lpad_zeroez(0,8);                                                                                               --GMARTOKEF
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';        
      else
        return false;
