             '0' ||                                                                                                          --MINUI
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(v_mispar_zehut,9) ||                                                                  --ERECH
             ' ' ||                                                                                                          --מינוס
             --lpad_zeroez(replace(to_char(v_hp_sheur_havara,'0000000.99'),'.',''),9) ||                                     --ERECH_2
             lpad_zeroez(0,9) ||                                                                                            --ERECH_2
             ' ' ||                                                                                                          --מינוס
             '0' ||  to_char(v_hp_date_start_zakaut,date_format_d8_reversed) ||                                                       --ERECH_3
             ' ' ||                                                                                                          --מינוס
             '0' ||  to_char(v_hp_date_haavara,date_format_d8_reversed) ||                                                            --ERECH_4
             ' ' ||                                                                                                          --מינוס
             lpad_zeroez(0,9) ||                                                                                             --ERECH_5
             rpad_blanks(' ',15) ||                                                                                          --TEUR
             to_char(v_hp_taarich_tokef_haavara,date_format_d8) ||                                                              --TAARICH
             lpad_zeroez(0,8);                                                                                               --GMARTOKEF
