      else return false;
      end if;            
*/   
       return insert_event;   
      else
        return false;
      end if;
    end if; 
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_237' || v_semel_hilan || ': ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_237: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
        return false;
    end;
  ------------------------------------  
   --נתוני היוון
   function check_event_315(v_semel_hilan varchar2,                --567
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_date_hivun date;
   v_seq_hivun number;
   v_achuz_hivun float;
   v_hp_sheur_havara float;
   v_date_gmar_tokef_hivun date;

    begin 
   
    if v_semel_hilan = '0567' then --היוון
    begin  
    select t.seq_hivun, t.date_bakasha, t.achuz_hivun
    into v_seq_hivun, v_date_hivun, v_achuz_hivun
    from hivun t, v_bakasha_last_status v
    where t.seq_bakasha = v.seq_bakasha
    --and (v.code_sug_bakasha=16 and v.code_bakasha_detail = 2 or v.code_sug_bakasha<>16)
    and t.seq_bakasha = v_seq_bakasha;

    if v_date_hivun < v_date_start_zakaut then v_date_hivun := v_date_start_zakaut; end if; --מייל מדבורה מתאריך 05/06/2019
    
    if v_date_hivun is null or v_achuz_hivun is null or
       to_char(v_date_hivun,'DD/MM/YYYY') = '00/00/0000' or v_achuz_hivun = 0 then
      build_check_message(1,'0315','0567',48,'',message);
    end if;
    exception
     when others then
      if v_code_sug_bakasha = 16 then
      message := sqlerrm;
      build_check_message(1,'0315','0567',29,'',message);
      end if;
    end;
   
    begin
    select last_day(add_months(min(t.date_bakasha),71))
    into v_date_gmar_tokef_hivun
    from hivun t, v_bakasha_last_status v
    where v.gimla_number = v_gimla_number
    and t.seq_bakasha = v.seq_bakasha;
    --and t.code_hivun = 2
    --and v.code_sug_bakasha = 16;
    exception
     when others then
     --if v_code_sug_bakasha = 16 then
     message := sqlerrm;
     build_check_message(1,'0315','0567',29,'',message);
     --end if;
    end; 
   
    elsif v_semel_hilan = '0412' and v_code_sug_bakasha = 12 then --חיסכון פנסיוני
    begin  
    select t.hp_sheur_havara
    into v_hp_sheur_havara
    from bakasha_regila t
    where t.seq_bakasha = v_seq_bakasha;
    exception
     when others then
      message := sqlerrm;
      build_check_message(1,'0315','0412',30,'',message);
    end;
    end if;
    return true;
    end;
