   begin
    select  n.date_start_zakaut - v.taarich_prisha hefresh_new
        into v_hefresh_zakaut_prisha
        from v_bakasha_last_status v, netuney_tik_mechushavim n,
             v_bakasha_last_status v1, netuney_tik_mechushavim n1
        where n.seq_bakasha = v.seq_bakasha
        and n.code_department = 2
        and n.mispar_misra = 0
        and n.code_group_prisha <> 4
        and v1.seq_prisha = v.seq_prisha
        and v1.code_sug_bakasha = 1
        and n1.seq_bakasha = v1.seq_bakasha
        and n1.code_department = 2
        and n1.mispar_misra = 0
        and v1.code_action = 98
        and n1.date_start_zakaut <= n.date_start_zakaut
        and v.seq_bakasha = v_seq_bakasha;
        if  nvl(v_hefresh_zakaut_prisha,0) > 5 and  v_semel_hilan = '0001' then return true; end if;
     exception
     when others then
       status  := 0;
       message := 'לבדוק תאריכי זכאות ופרישה';
       clob_log := clob_log ||('insert_event_539_1_9: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_237: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return true;   
     end;
     end if;
 
                      
    ld_log_events_record.code_event_semel := v_semel_hilan;
           prepare_trigger_0(v_seq_ld_protocol,
                             v_seq_ld_protocol_hilan,
                             v_seq_bakasha,
                             case when v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug else v_mispar_zehut end,
                             case when v_mispar_misrot_sach_hakol > 1 then
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                             else 
                                v_gimla_number
                             end,
                             true,
                             case when v_code_sug_bakasha <> 12 then 
                               to_date(to_char(v_date_start_zakaut,date_format_d6) || '01',date_format_d8)                               
                             else
                               to_date(to_char(v_hp_taarich_tokef_haavara,date_format_d6) || '01',date_format_d8) end
                             );
                             
           if not insert_event then return false; end if;
           
           
--***********************תיקון מתראיך 07/06/2020           
/*           ld_log_events_record.code_trigger := 2;
           ld_log_events_record.record_hilan :=  '0' ||                                                        --MINUI                                                                                                                                                                                                       
             case when v_code_sug_bakasha <> 12 then                                                           --TAARICH  
               case when v_semel_hilan = '0001' then to_char(v_date_start_zakaut,date_format_d6) || '01'
                    when v_semel_hilan = '0009' and v_code_sug_bakasha = 13 then to_char(v_date_start_zakaut_poresh_niftar,date_format_d6) || '01'
                    when v_semel_hilan = '0009' and v_code_sug_bakasha in(1,5)
                       then to_char(v_date_prishat_poresh,date_format_d8) end
               else to_char(v_hp_taarich_tokef_haavara,date_format_d6)|| '01' end ||                         
             lpad_zeroez(0,8) ||                                                                               --GMARTOKEF
             case when v_code_sug_bakasha <> 12 then                                                           --TAARICH  
               case when v_semel_hilan = '0001' then to_char(v_date_start_zakaut,date_format_d6) || '01'
                    when v_semel_hilan = '0009' and v_code_sug_bakasha = 13 then to_char(v_date_start_zakaut_poresh_niftar,date_format_d6) || '01'
                    when v_semel_hilan = '0009' and v_code_sug_bakasha in(1,5)
                       then to_char(v_date_prishat_poresh,date_format_d8) end
               else to_char(v_hp_taarich_tokef_haavara,date_format_d6)|| '01' end ||                         
