                    when v_semel_hilan = '0009' and v_code_sug_bakasha in (9,13) then to_char(v_date_start_zakaut_poresh_niftar,date_format_d8)
                 --to_char(v_date_start_zakaut_poresh_niftar,date_format_d6) || '01'
