  ------------------------------------  
  --וותקים למינוי
   function insert_event_539(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_code_vetek number;
   v_taarich_prisha date;
   v_vetek_hatchala_kolel number;
   v_vetek_hatchala_kolel_shanim number;
   v_vetek_hatchala_kolel_hodashim number;
   v_vetek_hatchala_zahal number;
   v_vetek_hatchala_zahal_lo_igul number;
   v_vetek_hatchala_zahal_shanim number;
   v_vetek_hatchala_zahal_hodashim number;
   v_insert_event boolean;
   is_vetek_colel number; 
   is_vetek_zahal number;
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_zehut_sheer_benzug_amiti number :=0;
   v_mispar_misra number := 0;
   v_cnt_539 number;
   v_result boolean;
   v_misra_first0 boolean := true;
   v_misra_first1 boolean := true;
   v_zahal_first0 boolean := true;
   v_zahal_first1 boolean := true;
   
  begin
    if v_mistz_almana_benzug_sheer <> 0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan <> 0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
   
    if v_code_sug_bakasha = 5 and v_code_group_prisha = 4 /*שינוי זכאות שארים*/ then return true; end if;
    
       if v_code_sug_bakasha in (9,13) then
       begin
            select z."DATE_START_ZAKAUT"
            into v_date_start_zakaut_poresh_niftar
            from v_bakasha_last_status v1, v_bakasha_last_zakaut z
            where v1.gimla_number = 
            (select v2.gimla_number
            from v_bakasha_last_status v2
            where v2.seq_bakasha = v_seq_bakasha 
            )
            and v1.code_sug_bakasha in (1,5,8)
            and v1.code_action = 98
            and v1.seq_bakasha = z.seq_bakasha
            and v1.seq_bakasha = 
            (select max(v3.seq_bakasha)
            from v_bakasha_last_status v3
            where v3.gimla_number = v1.gimla_number
            and v3.code_sug_bakasha in (1,5)
            and v3.code_action = 98);
       if v_date_start_zakaut_poresh_niftar > v_date_start_zakaut then
         v_date_start_zakaut_poresh_niftar := v_date_start_zakaut; /*הקפאה*/
       end if;
       exception
       when no_data_found then
          v_date_start_zakaut_poresh_niftar := null;
          when  others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_539: ' || 'אין תאריך זכאות של הפורש הנפטר' || ' ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_539: '|| 'אין תאריך זכאות של הפורש הנפטר' || ' ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut_sheer_benzug;
       return false;
       end;
       end if; 
 
       if v_code_sug_bakasha in (1,5,10,11) then
       begin
            if v_code_sug_bakasha in (1,5) then
            select v.taarich_prisha
            into v_date_prishat_poresh
            from v_bakasha_last_status v
            where v.seq_bakasha = v_seq_bakasha;
            if  v_date_prishat_poresh is null then
              select nvl(v.taarich_prisha,to_date('19100101','YYYYMMDD'))
              into v_date_prishat_poresh
              from v_bakasha_last_status v
              where v.gimla_number = v_gimla_number
              and v.seq_bakasha = 
              (select max(v1.seq_bakasha)
              from v_bakasha_last_status v1
              where v1.seq_prisha = v.seq_prisha
              and v1.code_sug_bakasha in (1,5)
              and v1.code_action = 98
              and v1.seq_bakasha <> v_seq_bakasha);
            end if;
            else
            select v.taarich_prisha
            into v_date_prishat_poresh
            from bakasha_regila v
            where v.seq_bakasha = v_seq_bakasha;
            end if;
           if v_date_prishat_poresh = to_date('19100101','YYYYMMDD') then v_date_prishat_poresh := null; end if;
       exception
       when no_data_found then
          v_date_prishat_poresh := null;
       when  others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_539: ' || 'אין תאריך פרישה של הפורש' || ' ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_539: '|| 'אין תאריך פרישה של הפורש' || ' ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
       end;
       end if;
       
       ld_log_events_record.code_event := 539;

       if not v_netuney_sachar_kayamim then --לשלוח רק סמל 0001/0009
        --const_seq_ezor_ovdim_chinuch = v_seq_ezor_ovdim 
 
       for i in 1 .. v_mispar_misrot_sach_hakol
        loop
          v_result := insert_event_539_1_9('0001',
                          v_seq_ld_protocol,
                          v_seq_ld_protocol_hilan,
