           if r.mispar_misra = 0 then v_zahal_first0 := false; end if;
           if r.mispar_misra = 1 then v_zahal_first1 := false; end if;
           end if;
           
           end loop;
    end if;
           return true;
    exception
/*    when no_data_found then
       return true;
*/  
       when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_539: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_539: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
      return false;
    end;  
  ------------------------------------  
  --וותקים למינוי
   function check_event_539(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
   v_code_vetek number;
   v_taarich_prisha date;
   v_vetek_hatchala_kolel number;
   v_vetek_hatchala_zahal number;
   v_insert_event boolean;
   is_vetek_colel number; 
   is_vetek_zahal number;
   v_mispar_zehut_sheer_benzug number :=0;
   v_mispar_zehut_sheer_benzug_amiti number :=0;
   v_mispar_misra number := 0;
   v_times number := 0;
   
  begin
    if v_mistz_almana_benzug_sheer <> 0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan <> 0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
       
    --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    --if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 

       if v_code_sug_bakasha = 13 then
       begin
           v_date_start_zakaut_poresh_niftar := null;
            select z."DATE_START_ZAKAUT"
            into v_date_start_zakaut_poresh_niftar
            from v_bakasha_last_status v1, v_bakasha_last_zakaut z
            where v1.gimla_number = 
            (select v2.gimla_number
            from v_bakasha_last_status v2
            where v2.seq_bakasha = v_seq_bakasha 
            )
            and v1.code_sug_bakasha in (1,5)
            and v1.code_action = 98
            and v1.seq_bakasha = z.seq_bakasha
            and v1.seq_bakasha = 
            (select max(v3.seq_bakasha)
            from v_bakasha_last_status v3
            where v3.gimla_number = v1.gimla_number
            and v3.code_sug_bakasha in (1,5)
            and v3.code_action = 98);
       exception
       when others then
               build_check_message(1,'0539','0009',50,'',message);
       end;
      end if;
       
    if not v_netuney_sachar_kayamim and 
      (v_seq_ezor_ovdim = const_seq_ezor_ovdim_chinuch or v_code_sug_bakasha = 13) then return true; end if;
    
    for r in (select n.*
      from netuney_sachar n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_sug_maskoret = 1
      order by n.mispar_misra) loop
      
    v_mispar_misra := r.mispar_misra;
      
    select count(*)
            into is_vetek_colel
                from vetek_detail t
                where t.seq_bakasha = v_seq_bakasha
                and (t.seq_netuney_sachar = r.seq_netuney_sachar or t.seq_netuney_sachar is null)
                and t.code_type_vetek = 6;
                
    if is_vetek_colel > 0 then
       select t.years
            into v_vetek_hatchala_kolel
                from vetek_detail t
                where t.seq_bakasha = v_seq_bakasha
                and (t.seq_netuney_sachar = r.seq_netuney_sachar or t.seq_netuney_sachar is null)
                and t.code_type_vetek = 6;
    end if;
  
    if is_vetek_colel is null or v_vetek_hatchala_kolel is null then
      build_check_message(1,'0539','0002',31,'',message);
    end if;

    select count(*)
            into is_vetek_zahal
                from vetek_detail t
                where t.seq_bakasha = v_seq_bakasha
                and (t.seq_netuney_sachar = r.seq_netuney_sachar or t.seq_netuney_sachar is null)
                and t.code_type_vetek = 2;
                
    if is_vetek_zahal > 0 then
       select t.years
            into v_vetek_hatchala_zahal
                from vetek_detail t
                where t.seq_bakasha = v_seq_bakasha
                and (t.seq_netuney_sachar = r.seq_netuney_sachar or t.seq_netuney_sachar is null)
                and t.code_type_vetek = 2;
    end if;
    
    if is_vetek_zahal>0 and v_vetek_hatchala_zahal is null then
      build_check_message(1,'0539','0005',32,'');
    end if;
    
    v_times := v_times + 1;
    end loop;
    
    if v_times = 0 then
       build_check_message(1,'0539','0002',31,'');
    end if;
    
    return true;
  end;   
   ------------------------------------  
   -- נתוני גמלה למינוי
   function insert_event_567(v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
    v_achuz_gimla number;
    v_times number := 0; --כמה פעמים להפעיל אירוע
    v_code_sug_gimla number;
    v_mispar_zehut_sheer_benzug number :=0;
    v_mispar_zehut_sheer_benzug_amiti number :=0;
    v_mispar_misra number := 0;
    v_achuz_gimla_kodem number;
    v_achuz_gimla_legil60_kodem number;
    v_date_end_zakaut date;
    v_is_participation_hilan number;
   
  begin
    
    if v_mistz_almana_benzug_sheer<>0 then 
            --if v_seq_bakasha = 394507 then return true ; end if;
            v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer;
            v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number);
    elsif v_mispar_zehut_ben_katan<>0 then
            --if v_seq_bakasha = 394507 and v_mispar_zehut_ben_katan <> 326498334 then return true; end if;
            v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan;
            v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number);
    end if;    
    if v_code_sug_bakasha in (10,11) then
          ld_log_events_record.code_event := 567;
          ld_log_events_record.code_event_semel := 0;
         
    prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        v_mispar_zehut,
                        v_gimla_number,
                        true,
                        v_date_start_zakaut);                                             
      if not insert_event then return false; end if;         
  
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                                --MINUI
             to_char(v_date_start_zakaut,date_format_d8) ||                                                                        --TAATICH 
             lpad_zeroez(0,8) ||                                                                                                   --GMARTOKEF 
             '10000' ||        --100%                                                                                              --AHUZ_GIMLA 
             ' ' ||                                                                                                                --KOD_B_PENSIA
             ' ' ||                                                                                                                --KOD_B_HIVUN
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ_HIVUN
             rpad_blanks(' ',8) ||                                                                                                 --HATHALA
             rpad_blanks(' ',8) ||                                                                                                 --SOF
             lpad_zeroez(0,9) ||                                                                                                   --SCHUM_MEKORI                                                                                    --
             '5' ||                                                                                                                --MUASAK
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL1
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ1
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL2
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ2
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL3
             lpad_zeroez(0,4);                                                                                                     --AHUZ3
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
      if not insert_event then return false; end if; 
       
/*     if not v_2218 or
       check_mz_exists_in_varray(case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug 
                                      else v_mispar_zehut end,
                                 case when v_mispar_misrot_sach_hakol > 1 then to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))                
                                      else v_gimla_number end
                                        ) = false then
       insert_or_check_event_dynamic(527,
                                  '2218',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mistz_almana_benzug_sheer,
                                  v_mispar_zehut_ben_katan,
                                  v_code_seif_prisha,
                                  1,                               
                                  v_mispar_misra,
                                  1);  
    v_2218 := true;
    if check_mz_exists_in_varray(case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug 
                                      else v_mispar_zehut end,
                                 case when v_mispar_misrot_sach_hakol > 1 then to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))                
                                      else v_gimla_number end
                                        ) = false then
        v_cnt_2218 := v_cnt_2218 + 1; 
                     mispar_zehut_2218.extend; 
                     mispar_zehut_2218(v_cnt_2218) := 
                     case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug else v_mispar_zehut end;
                     mispar_gimla_2218.extend; 
                     mispar_gimla_2218(v_cnt_2218) := 
                     case when v_mispar_misrot_sach_hakol > 1 then to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))                
                          else v_gimla_number end;
   end if;                     
    if not if_commit then return false; end if;
    end if; 
*/      return true;     
    end if;
 
   for r in (select n.*
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      order by n.mispar_misra)
    loop
      
    v_mispar_misra := r.mispar_misra;

    if v_code_sug_bakasha not in (7,23) then
     if v_mistz_almana_benzug_sheer<>0 and v_code_sug_bakasha<>9 then 
/*      v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer;
      v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
*/      
      select nvl(n2.achuz_kizba,0) + nvl(n2.achuz_tosefet,0) achuz_kizba
/*      case when n2.code_maanak_almana is null
           then nvl(n2.achuz_kizba,0) + nvl(n2.achuz_tosefet,0) 
      else
           0 end
*/      
         into v_achuz_gimla
         from bney_mishpacha b, poresh p,
         netuney_tik_mechushavim n1,
         netuney_tik_ben_mishpacha n2
         where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
         and b.seq_porshim = p.porshim_seq
         and p.mispar_zehut = v_mispar_zehut_amiti
         and (b.taarich_ptira is null or b.taarich_ptira is not null and b.taarich_ptira>v_date_start_zakaut)
         and n1.seq_bakasha = v_seq_bakasha
         and n1.code_department = 2
         and n1.mispar_misra = v_mispar_misra
         and n2.seq_netuney_tik_mechushavim = n1.seq_netuney_tik_mechushavim
         and n2.seq_bney_mishpacha = b.seq_bney_mishpacha;
         if v_4248 then v_achuz_gimla := 0; end if;
     elsif v_mispar_zehut_ben_katan<>0  and v_code_sug_bakasha<>9 then
/*      v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan;
      v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
*//*      select sum(nvl(b.achuz_kizba,0)) + sum(nvl(b.achuz_tosefet,0)) achuz_kizba
         into v_achuz_gimla
         from bney_mishpacha b
         left join poresh p on
         p.porshim_seq = b.seq_porshim
         where b.code_relative in (2,3) and 
         (b.to_date_sium_zakaut is not null and b.to_date_sium_zakaut > sysdate 
         or b.to_date_sium_zakaut is null)
         and b.taarich_ptira is null
         and p.mispar_zehut = v_mispar_zehut_amiti;*/
      select sum(nvl(n2.achuz_kizba,0)) + sum(nvl(n2.achuz_tosefet,0)) achuz_kizba
         into v_achuz_gimla
         from bney_mishpacha b
         left join poresh p on
         p.porshim_seq = b.seq_porshim
         left join netuney_tik_mechushavim n1 on
         n1.seq_bakasha = v_seq_bakasha
         and n1.code_department = 2
         and n1.mispar_misra = v_mispar_misra
         left join netuney_tik_ben_mishpacha n2 on
         n2.seq_netuney_tik_mechushavim = n1.seq_netuney_tik_mechushavim
         and n2.seq_bney_mishpacha = b.seq_bney_mishpacha
         where (b.code_relative in (2,3) and (b.own_bank_account<>1 or b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti))
         and ((b.to_date_sium_zakaut is not null and b.to_date_sium_zakaut > sysdate 
         or b.to_date_sium_zakaut is null) /*or v_seq_bakasha=357684*/)
         and (b.taarich_ptira is null or b.taarich_ptira is not null and b.taarich_ptira>v_date_start_zakaut)
         and p.mispar_zehut = v_mispar_zehut_amiti;
     else
         v_achuz_gimla := r.achuz_kizba_sofi;
         if nvl(r.is_seif_57,0) <> 0 then
         --else
            --v_achuz_gimla := 0;        --לפי מכתב של גיא: אבקש אחוז גמלה 0.00 לתקופה הזו                
            --לשלוח אחוז קצבה בכל מקרה (לפי הוראה של שני פסטמן)
            v_date_end_zakaut := r.date_end_zakaut; 
         end if;
     end if;
    else 
         --if nvl(r.tkufa_overlap_kizba,0) > 0 then
/*             not(pk_participation_2_guff.is_overlap_from_guf(v_seq_bakasha) = 1 
             and r.tkufa_overlap_kizba > 0) then
*/       
       begin
         v_kayam_hishtatfut_567 := false;
         begin
         select p.is_hilan
         into v_is_participation_hilan
         from participation_hilan p
         where p.seq_bakasha = v_seq_bakasha;
         exception
         when others then
           v_is_participation_hilan := 0;
         end;
/*         if v_mistz_almana_benzug_sheer<>0 then 
            v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer;
            v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number);
         elsif v_mispar_zehut_ben_katan<>0 then
            v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan;
            v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number);
         end if;    
*/       select distinct t.achuz_kizba_sofi
         into v_achuz_gimla_kodem
          from V_MECHUSHAVIM_2_CURNT_AND_PREV t
         where t.current_seq_bakasha = v_seq_bakasha
         and t.code_department=2
         and t.seq_bakasha < v_seq_bakasha
         and t.seq_bakasha =
         (select max(t1.seq_bakasha)
         from V_MECHUSHAVIM_2_CURNT_AND_PREV t1
         where t1.current_seq_bakasha = v_seq_bakasha
         and t1.code_department=2
         and t1.seq_bakasha < v_seq_bakasha
         );
         if v_achuz_gimla_legil60_kodem <> r.achuz_kizba_gil_60 --27/10/2020
           or (v_mispar_gufim_mesumanin = 0 and v_is_participation_hilan = 1)  
         then 
           insert_or_check_event_dynamic(527,
                                  '0239',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mistz_almana_benzug_sheer,
                                  v_mispar_zehut_ben_katan,
                                  v_code_seif_prisha,
                                  4,                          
                                  0,
                                  1);
             if not if_commit then return false; end if;
         end if;
         if v_achuz_gimla_kodem <> r.achuz_kizba_sofi--20/02/2020 לפי בקשה של נעמה
           or (v_mispar_gufim_mesumanin = 0 and v_is_participation_hilan = 1) --10/09/2020
         then          
           /*if v_code_sug_bakasha = 23 or
              v_code_sug_bakasha = 7 and (r.tkufa_overlap_kizba > 0  or r.is_salary_up_70 = 1) then*/
                      v_achuz_gimla := r.achuz_kizba_sofi;
                      v_kayam_hishtatfut_567 := true;
           /*else
              return true;
           end if;*/
         else return true;
         end if;
     exception
     when others then
       return true;
     end;
 /*        else
          return true;
          --v_achuz_gimla := r.achuz_kizba_sofi;
         end if;*/
    end if;
    select t.sug_gimla_hilan
    into v_code_sug_gimla
    from code_seif_prisha t
    where t.code_seif_prisha = v_code_seif_prisha;

    if v_code_sug_bakasha = 9 then v_code_sug_gimla := 2; end if;
    
    if v_date_end_zakaut is not null then v_date_end_zakaut := last_day(v_date_end_zakaut); end if;
    
    ld_log_events_record.code_event := 567;
    ld_log_events_record.code_event_semel := 0;
         
    prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug<>0 then v_mispar_zehut_sheer_benzug  else v_mispar_zehut end,
                        case when v_mispar_misrot_sach_hakol > 1 then 
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                        else 
                                v_gimla_number
                        end,
                        true,
                        to_date(to_char(v_date_start_zakaut,date_format_d6) || '01',date_format_d8));                                             
      if not insert_event then return false; end if;         
  
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                                                --MINUI
             (case when v_date_start_zakaut is null then lpad_zeroez(0,8) else to_char(v_date_start_zakaut,date_format_d8) end) || --TAATICH 
             (case when v_date_end_zakaut is null then lpad_zeroez(0,8) else /*seif 57*/ to_char(v_date_end_zakaut,date_format_d8) end) ||     ----GMARTOKEF 
             lpad_zeroez(replace(to_char(nvl(v_achuz_gimla,0),'000.99'),'.',''),5) ||                                              --AHUZ_GIMLA 
             ' ' ||                                                                                                                --KOD_B_PENSIA
             ' ' ||                                                                                                                --KOD_B_HIVUN
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ_HIVUN
             rpad_blanks(' ',8) ||                                                                                                 --HATHALA
             rpad_blanks(' ',8) ||                                                                                                 --SOF
             lpad_zeroez(0,9) ||                                                                                                   --SCHUM_MEKORI                                                                                    --
             case when v_code_sug_gimla is null then 5 else v_code_sug_gimla end ||                                                                                                   --MUASAK
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL1
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ1
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL2
             lpad_zeroez(0,4) ||                                                                                                   --AHUZ2
             lpad_zeroez(0,3) ||                                                                                                   --SEMEL3
             lpad_zeroez(0,4);                                                                                                     --AHUZ3
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';      if not insert_event then return false; end if;         

