   v_teur_ezor_ovdim varchar2(50);
   v_zakaut_lemaanak_yovel_first0 boolean := true;
   v_yamei_havraa_first0 boolean := true;                    
   v_zakaut_lemaanak_yovel_first1 boolean := true;
   v_yamei_havraa_first1 boolean := true;                    
   v_260_first boolean := true;               
  
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
   
      ld_log_events_record.code_event := 527;
      ld_log_events_record.code_event_semel := v_semel_hilan;
      
       if v_semel_hilan in ('0000','0244','0280') then
               if v_sachar_reforma = 1 and 
               (v_code_sug_bakasha = 1
               or v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25
               or v_code_sug_bakasha = 13 and v_netuney_sachar_kayamim
               or v_code_sug_bakasha = 14) then
               insert_or_check_event_dynamic(315,
                                   '0181',
                                   v_seq_ld_protocol,
                                   v_seq_ld_protocol_hilan,
                                   v_seq_bakasha,
                                   v_mispar_zehut,
                                   v_gimla_number,
                                   v_seq_ezor_ovdim,
                                   v_code_sug_bakasha,
                                   v_mistz_almana_benzug_sheer,
                                   v_mispar_zehut_ben_katan,
                                   v_code_seif_prisha,
                                   0,
                                   v_mispar_misra_last);         
                if not if_commit then return false; else return true; end if;
                end if;
      end if;
 
       if v_semel_hilan in('2131','2132') then

         if v_seq_ezor_ovdim <> 206 then return true; end if;
         if v_mispar_mikdamot = 0 then return true; end if;
         if v_code_sug_bakasha not in (1,14) then return true; end if;
         --elsif sysdate < to_date('01/10/2021') then
/*          if v_semel_hilan = '2131' then
             v_schum := 6000;
          elsif v_semel_hilan = '2132' then
            select nvl(n.is_zakai_lmaanak,0),
            case when  nvl(n.odef_sherut_chodashim,0) > 0 or nvl(n.odef_sherut_yamim,0) > 0 
                       then 1 
                       else 0 end
            into v_zakaut_le_maanak_prisha,	v_zakaut_leshanim_odfot
            from netuney_tik_mechushavim n
            where n.seq_bakasha = v_seq_bakasha
            and n.code_department = 2
            and n.mispar_misra = 0;
            if v_zakaut_le_maanak_prisha > 0  or v_zakaut_leshanim_odfot > 0 then
              v_schum := 10000;
            else
              return true; --אין זכאות למענק
            end if;
          end if;
*/
         prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        v_mispar_zehut,                   
                        case when v_mispar_misrot_sach_hakol > 1 then  
                             to_number(lpad(v_gimla_number,8) || '1') 
                        else
                             v_gimla_number 
                        end,                            
                        true,
                        to_date(to_char(v_date_start_zakaut,date_format_d6) || '01', date_format_d8)
                        );                                                
/*     if not insert_event then return false; end if;
     ld_log_events_record.code_trigger := 2;
     ld_log_events_record.date_report := v_date_start_zakaut;
     ld_log_events_record.record_hilan := 
     '0' ||        
     to_char(v_date_start_zakaut, date_format_d8) ||                                                         --TAARICH
     lpad_zeroez(0,8) ||                                                                                     --GMARTOKEF
     v_code_hishuv ||                                                                                        --KODISHI
     ' ' ||                                                                                                  --מינוס
     lpad_zeroez(replace(to_char(v_schum,'0000000.99'),'.',''),9) ||                                         --SUM 
     lpad_zeroez(0,3);                                                                                       --TAARIF
*/   
     if not insert_event then return false; end if;
     return true;
     end if;

   if v_semel_hilan in ('0261','0284') then -- להשתכרות
          v_zakaut_lehistakrut := 1;
          for r1 in
          (select case when v_semel_hilan = '0261' then 0 else t.sum end sum,
          t.from_date, t.to_date
          from hachnasot t
          where t.seq_bakasha = v_seq_bakasha
          order by t.from_date
          ) loop
        if r1.from_date is null then
             clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
              'לא נשלח: לא מוגדר תאריך זכאות להשתכרות') ||  '<br />';
             return false; 
        end if;
        if v_first_time = 1 then
        prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        v_mispar_zehut,                   
                        case when v_mispar_misrot_sach_hakol > 1 then  
                             to_number(lpad(v_gimla_number,8) || '1') 
                        else
                             v_gimla_number 
                        end,                            
                        true,
                        to_date(to_char(r1.from_date,date_format_d6) || '01', date_format_d8)
                        );                                                
       if not insert_event then return false; end if;
       v_first_time := 0;
     end if;
     ld_log_events_record.code_trigger := 2;
     ld_log_events_record.date_report := r1.from_date;
     ld_log_events_record.record_hilan := 
     '0' ||        
     to_char(r1.from_date, date_format_d8) ||                                                            --TAARICH
     case when r1.to_date is null then lpad_zeroez(0,8) else to_char(r1.to_date,date_format_d8) end ||       --GMARTOKEF
     v_code_hishuv ||                                                                                        --KODISHI
     ' ' ||                                                                                                                  --מינוס
     lpad_zeroez(replace(to_char(nvl(r1.sum,0),'0000000.99'),'.',''),9) ||                                                  --SUM 
     lpad_zeroez(0,3);                                                                                                       --TAARIF
     if not insert_event then return false; end if;
     end loop;
     return true;
     end if;  
      
    --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    --if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 
       
     for r in (select n.seq_netuney_sachar, n.mispar_misra
      from netuney_sachar n
      where n.seq_bakasha = v_seq_bakasha
      and (v_sachar_reforma <> 1 and v_semel_hilan  = '0244' and n.code_sug_maskoret = 2 or
           v_sachar_reforma <> 1 and v_semel_hilan <> '0244' and n.code_sug_maskoret = 1 or
           v_sachar_reforma =  1 and n.code_sug_maskoret = 
      (select m.code_sug_maskoret
      from code_sug_maskoret m
      where m.code_chinuch_sug_maskoret = 1
      and m.code_sug_maskoret = n.code_sug_maskoret
      and n.seq_bakasha = v_seq_bakasha
      /*and rownum < 2*/))
      union
      select 0 seq_netuney_sachar, 0 mispar_misra from dual
      where v_code_sug_bakasha in (17,18,12) or 
            v_code_sug_bakasha in (1,5) 
            and not exists 
            (select n.seq_netuney_sachar, n.mispar_misra
              from netuney_sachar n
              where n.seq_bakasha = v_seq_bakasha
              and n.code_sug_maskoret = 1)
            and v_semel_hilan = '0260' --גמלאות כפל או השתכרות
      order by mispar_misra) loop
      
      v_mispar_misra := r.mispar_misra;
      v_code_hishuv_bitul := 0;
      
      /*if v_mispar_misra_last <>0  then
        v_mispar_misra := v_mispar_misra_last - 1;
      else
        v_mispar_misra := r.mispar_misra;
      end if;*/
    
       if v_semel_hilan in ('0260','3036')  then -- זכאות שכר קובע ממקור נוסף (גמלאות כפל)
        if v_260_first then v_260_first := false; else return true; end if;
        select kefel.date_payment, kefel.achuz_guf_final, kefel.seq_guf
         into v_date_start_gimlaot_kefel, v_achuz_kefel, v_guf_kefel
         from (select t.date_payment,t.achuz_guf_final, t.seq_guf
                 from participation t
                 where t.seq_bakasha = v_seq_bakasha
                 and t.code_participation = 6
                 order by t.date_payment)kefel
         --where rownum = 1
         ;
         if v_guf_kefel = 165 and v_seq_bakasha <> 400658 then continue; end if; --בפרישה לגמלאות/גוף = צה"ל לא מעבירים את גמלאת הכפל לחילן TFS 91501
          if v_semel_hilan = '3036' then           
            if v_achuz_kefel <= 70 then
              continue;
            else
              v_schum := v_achuz_kefel;
            end if;
         end if;                      
         if v_date_start_gimlaot_kefel is null then
          if v_code_sug_bakasha = 18 then
             clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
              'לא נשלח: לא מוגדר תאריך זכאות לגמלאות כפל') ||  '<br />';
             return false;
          else 
             return true;
          end if;
        else 
          v_zakaut_legimlaot_kefel := 1;
        end if;
      elsif v_semel_hilan in ('0244') then -- משכורת לגיל 60
          /*select t.maskoret_kovaat, tos.sum                    
          into v_maskoret_legil_60, v_tosefet_ofek_legil_60    
          from netuney_sachar t
          left join tosefot tos on
          tos.seq_netuney_sachar = t.seq_netuney_sachar
          and tos.code_semel_tosefet = 879
          where t.seq_bakasha = v_seq_bakasha        
          and t.seq_netuney_sachar =  r.seq_netuney_sachar
          and t.code_sug_maskoret = 2;
          if nvl(v_tosefet_ofek_legil_60,0)>0  then 
            v_schum := v_maskoret_legil_60 + v_tosefet_ofek_legil_60;
          else*/
          select t.maskoret_kovaat                   
          into v_maskoret_legil_60
          from netuney_sachar t
          where t.seq_bakasha = v_seq_bakasha        
          and t.seq_netuney_sachar =  r.seq_netuney_sachar
          and t.code_sug_maskoret = 2;
          v_schum := v_maskoret_legil_60;   
          --end if;
      elsif v_semel_hilan = '0630' then --חיסכון פנסיוני
        --if v_seq_bakasha in (380469,381707,382840) then return true; end if;
        select nvl(b.hp_llo_hafchata,0)
        into v_hp_llo_hafchata
        from bakasha_regila b
        where b.seq_bakasha = v_seq_bakasha;
        if v_hp_llo_hafchata = 1 then return true; end if; --לא לשלוח אחוז הפחתה
        if v_mispar_misra = 1 then return true; end if;
        
        if v_code_sug_bakasha = 12 then
         /* select t.hp_code_chayav_retro
          into v_hp_code_chayav_retro
          from bakasha_regila t
          where t.seq_bakasha = v_seq_bakasha;*/
          select t.code_min
          into v_min_poresh
          from poresh t
          where t.mispar_zehut = v_mispar_zehut_amiti;
          /*select t.code_min
          into v_min_benzug
          from bney_mishpacha t
          where t.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
          and t.code_kirva = 10;*/
         else return true;
        end if;
        
      if v_min_poresh = 1
        then v_schum := 2.8;
        else v_schum := 1.2;
      end if;
      /*if v_hp_code_chayav_retro = 2 then   --שיעור חישוב הפחטה
          if v_min_benzug = 1
            then v_schum := 1.2;
          else 
            v_schum := 2.8;
          end if;
       elsif v_hp_code_chayav_retro = 1 then
          if v_min_poresh = 1
            then v_schum := 1.2;
          else 
            v_schum := 2.8;
          end if;
       elsif v_hp_code_chayav_retro = 3 then
            v_schum := 2.8;
       else v_schum := 0;
       end if;
        if v_schum = 0 then return true; end if;*/
      else        
         select t.havraa_days,
               /*t.sum_havraa,
               t.bigud,*/
               t.is_maanak_yovel,
               t.kovaat_161            
        into v_yamei_havraa,
             /*v_schum_leyom,
             v_kzuvat_bigud,*/
             v_zakaut_lemaanak_yovel,
             v_maskoret_kovaat_lepitzuim            
        from netuney_sachar t
        where t.seq_bakasha = v_seq_bakasha        
        and t.seq_netuney_sachar =  r.seq_netuney_sachar;
        
     if      v_semel_hilan = '0234' then  --ימי הבראה
             if v_sachar_reforma =1 and
               (r.mispar_misra = 0 and  v_yamei_havraa_first0 = false or
                r.mispar_misra = 1 and  v_yamei_havraa_first1 = false)
             then continue; end if;
             v_schum := v_yamei_havraa;
             if v_schum = 0 or v_schum is null then continue; end if;
             if v_sachar_reforma = 1 then 
                if r.mispar_misra = 0 then v_yamei_havraa_first0 := false; end if;
                if r.mispar_misra = 1 then v_yamei_havraa_first1 := false; end if;
             end if; 
             --v_code_hishuv := 4;       
     elsif   v_semel_hilan = '0235' then                               --זכאות למענק יובל
             if v_sachar_reforma = 1 then
               if r.mispar_misra = 0 and v_zakaut_lemaanak_yovel_first0 = false or
                  r.mispar_misra = 1 and v_zakaut_lemaanak_yovel_first1 = false then 
                 continue;
               else 
                 select max(n.is_maanak_yovel)
                  into v_zakaut_lemaanak_yovel
                  from netuney_sachar n
                  left join code_sug_maskoret c on
                  c.code_sug_maskoret = n.code_sug_maskoret
                  where n.seq_bakasha = v_seq_bakasha
                  and c.code_chinuch_sug_maskoret = 1
                  and n.mispar_misra = r.mispar_misra;
                  if v_sachar_reforma = 1 then 
                      if r.mispar_misra = 0 then v_zakaut_lemaanak_yovel_first0 := false; end if;
                      if r.mispar_misra = 1 then v_zakaut_lemaanak_yovel_first1 := false; end if;
                  end if; 
               end if;
             end if;
             if v_zakaut_lemaanak_yovel <> 1 then
                if v_code_sug_bakasha = 1 then continue;                
                else v_code_hishuv_bitul := 2;
              end if;
             end if;
     elsif   v_semel_hilan = '0280' then                               --משכורת אחרונה לפיצויים
             v_schum := v_maskoret_kovaat_lepitzuim;
             --v_code_hishuv := 0;
     elsif v_semel_hilan = '0000' then
/*      (v_code_sug_bakasha in (1,14)
       or v_code_sug_bakasha = 5 and nvl(v_code_bakasha_detail,0)  = 25 \*or (v_code_sug_bakasha = 13 and v_ptira_besherut_gimlat_chesed)*\
       or v_code_sug_bakasha = 13 and v_netuney_sachar_kayamim) then																	
 */ 
     /*for r1 in 
            (select c.semel_hilan, c.code_event_hilan, t.seq_tosefot
            from netuney_sachar s, tosefot t, code_semel_tosefet c
            where s.seq_bakasha = v_seq_bakasha
            and s.mispar_misra = v_mispar_misra
            and s.seq_netuney_sachar = r.seq_netuney_sachar
            and s.seq_netuney_sachar = t.seq_netuney_sachar
            and t.code_semel_tosefet = c.code_semel_tosefet
            and s.code_sug_maskoret = 1
            and c.semel_hilan <> 99999 --תוספת לא ידועה
            )  */   
     for r1 in 
       (select case when c.semel_hilan is not null then c.semel_hilan else
              (select c1.semel_hilan
              from code_semel_tosefet c1
              where c1.semel_chinuch = t.code_semel_tosefet) end semel_hilan,
              t.seq_tosefot, t.code_semel_tosefet, s.seq_netuney_sachar
            from netuney_sachar s
            left join tosefot t on 
            t.seq_netuney_sachar = s.seq_netuney_sachar
            left join code_semel_tosefet c on
            t.code_semel_tosefet = c.code_semel_tosefet
            where s.seq_bakasha = v_seq_bakasha
            and s.mispar_misra = v_mispar_misra
            and s.seq_netuney_sachar = r.seq_netuney_sachar
            and s.code_sug_maskoret = 1 
            and c.sug_natun = 106
            and c.semel_hilan <> 99999 --תוספת לא ידועה
            ) loop
     begin
             v_seq_tosefot := r1.seq_tosefot;
             insert_or_check_event_dynamic(309,
                                  lpad_zeroez(to_char(r1.semel_hilan),4),
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mistz_almana_benzug_sheer,
                                  v_mispar_zehut_ben_katan,
                                  v_code_seif_prisha,
                                  0,
                                  v_mispar_misra);  
             if not if_commit then return false; end if;
     end;
     end loop;
     end if;
     end if;
     if v_semel_hilan = '0000' then continue; end if;
     prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug = 0 or
                                (v_mispar_zehut_sheer_benzug<>0 and v_code_sug_bakasha = 12 and v_semel_hilan = '0630') then
                                v_mispar_zehut
                             else
                                v_mispar_zehut_sheer_benzug end,
                        case when v_mispar_misrot_sach_hakol > 1 then
                        case when v_mispar_zehut_sheer_benzug<>0 and v_code_sug_bakasha = 12 and v_semel_hilan = '0630' then                              
                               to_number(lpad(v_gimla_number,8) || '1')/* - 700000000*/
                               else
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                               end
                        else 
                        case when v_mispar_zehut_sheer_benzug<>0 and v_code_sug_bakasha = 12 and v_semel_hilan = '0630' then
                                v_gimla_number/* - 700000000*/
                             else
                                v_gimla_number 
                             end
                        end,                            
                        true,
/*                        case when v_code_sug_bakasha = 12 then v_hp_date_haavara 
                             when v_code_sug_bakasha = 17 then v_date_start_zakaut_histakrut
                             when v_code_sug_bakasha = 18 or v_code_sug_bakasha in (1,5) and v_semel_hilan = '0260' then v_date_start_gimlaot_kefel
                             else v_date_start_zakaut end);*/
                        case when v_code_sug_bakasha = 12 then to_date(to_char(v_hp_taarich_tokef_haavara,date_format_d6) || '01', date_format_d8)
                             when v_code_sug_bakasha = 17 then to_date(to_char(v_date_start_zakaut_histakrut,date_format_d6) || '01', date_format_d8)
                             when v_code_sug_bakasha = 18 or v_code_sug_bakasha in (1,5) and v_semel_hilan in ('0260','3036')
                                then to_date(to_char(v_date_start_gimlaot_kefel,date_format_d6) || '01', date_format_d8)
                             when v_semel_hilan = 2218 then
                                 case when v_code_sug_bakasha = 1 or 
                                  (v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25) or
                                  (v_code_sug_bakasha = 13 and v_code_source <> 17) then
                                      to_date(to_char(v_date_start_zakaut,date_format_d6) || '01', date_format_d8)
                                      else to_date(to_char(sysdate,date_format_d6) || '01', date_format_d8) end
                             else to_date(to_char(v_date_start_zakaut,date_format_d6) || '01', date_format_d8) end);
                                                
     if not insert_event then return false; end if;  
        
     ld_log_events_record.code_trigger := 2;
     if v_semel_hilan <> 2218 then
     ld_log_events_record.record_hilan := 
     '0' ||        
/*     case when v_code_sug_bakasha = 12 then to_char(v_hp_date_haavara,date_format_d8) 
          when v_code_sug_bakasha = 17 then to_char(v_date_start_zakaut_histakrut,date_format_d8)
          when v_code_sug_bakasha = 18 or v_code_sug_bakasha in (1,5) and v_semel_hilan = '0260' then to_char(v_date_start_gimlaot_kefel,date_format_d8)                 
          else to_char(v_date_start_zakaut, date_format_d8) end ||                                                            --TAARICH
*/ 
     case when v_code_sug_bakasha = 12 then to_char(v_hp_taarich_tokef_haavara,date_format_d8) 
          when v_code_sug_bakasha = 17 then to_char(v_date_start_zakaut_histakrut,date_format_d6) || '01'
          when v_code_sug_bakasha = 18 or v_code_sug_bakasha in (1,5) and v_semel_hilan in ('0260','3036')
             then to_char(v_date_start_gimlaot_kefel,date_format_d6) || '01'                  
          else to_char(v_date_start_zakaut, date_format_d8) end ||                                                            --TAARICH
     (case when v_date_end_zakaut is null then lpad_zeroez(0,8) else to_char(v_date_end_zakaut,date_format_d8) end) ||       --GMARTOKEF
     lpad_zeroez(case when v_code_hishuv_bitul <>2 then v_code_hishuv else v_code_hishuv_bitul end,1) /*end */||                                                                                         --KODISHI
     ' ' ||                                                                                                                  --מינוס
     lpad_zeroez(replace(to_char(nvl(v_schum,0),'0000000.99'),'.',''),9) ||                                                  --SUM 
     lpad_zeroez(0,3);                                                                                                       --TAARIF
     --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
     if not insert_event then return false; end if;
     if v_code_sug_bakasha = 12 and v_semel_hilan = '0630' then return true;  end if; 
     else
     ld_log_events_record.record_hilan := 
     '0' ||        
     case when v_code_sug_bakasha = 1 or 
       (v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25) or
       (v_code_sug_bakasha = 13 and v_code_source <> 17)
          then to_char(v_date_start_zakaut,date_format_d6) || '01'
          else 
               to_char(sysdate,date_format_d6) || '01' end ||
     lpad_zeroez(0,8) ||                                                                                                     --GMARTOKEF
     '1' ||                                                                                                                  --KODISHI
     ' ' ||                                                                                                                  --מינוס
     lpad_zeroez(0,9) ||                                                                                                      --SUM 
     lpad_zeroez(0,3);                                                                                                       --TAARIF
     --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
     if not insert_event then return false; end if;  
     end if;    
     end loop;
     return true;
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_527_sachar: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_527_sachar: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;
   ------------------------------------
   -- מרכיבי שכר אישיים למינוי 
   function check_event_527_sachar(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number,
                          v_code_hishuv number,
                          v_mispar_misra_last number default 0
                          ) return boolean is
   
   v_zakaut_le_maanak_prisha number;               --242
   v_yamei_havraa number;                          --234 V
   v_zakaut_lemaanak_yovel number;                 --235 V
   v_maskoret_kovaat_lepitzuim float;              --280 V
   v_zakaut_lehistakrut number;                    --261 V
   v_zakaut_legimlaot_kefel number;                --260 V
   v_maskoret_legil_60 float;                      --244 V 
   v_achuz_kizva_zfuya_legil_60_59 float;          --239
   v_date_start_zakaut_histakrut date;  
   v_date_start_gimlaot_kefel date;          
   v_date_end_zakaut   date := null;
   v_schum float := 0;
   v_min_poresh number;
   v_min_benzug number;
   v_hp_code_chayav_retro number;
   v_mispar_zehut_sheer_benzug number := 0 ;
   v_mispar_zehut_sheer_benzug_amiti number := 0 ;
   v_mispar_misra number := 0;     
   v_teur_ezor_ovdim varchar2(50);
   v_times number := 0;
   
    begin
   
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
    
    --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    --if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 
       
     for r in (select n.seq_netuney_sachar, n.mispar_misra
      from netuney_sachar n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_sug_maskoret = 
          (case when v_semel_hilan = '0244' then 2 else 1 end)
      --and (v_mispar_misra_last = 0 or v_mispar_misra_last<>0 and n.mispar_misra = v_mispar_misra_last - 1)
      union
      select 0 seq_netuney_sachar, 0 mispar_misra from dual
      where v_code_sug_bakasha in (17,18,12) or v_code_sug_bakasha in (1,5) and v_semel_hilan = '0260' --גמלאות כפל או השתכרות
      order by mispar_misra) loop
      
      v_times := v_times + 1;
      
      /*if v_mispar_misra_last <>0  then
        v_mispar_misra := v_mispar_misra_last - 1;
      else
        v_mispar_misra := r.mispar_misra;
      end if;*/
    
       if v_semel_hilan = '0260' then -- זכאות שכר קובע ממקור נוסף (גמלאות כפל)
         begin
         select min(t.date_payment)
                 into v_date_start_gimlaot_kefel
                 from participation t
                 where t.seq_bakasha = v_seq_bakasha
                 and t.code_participation = 6;             
         if v_date_start_gimlaot_kefel is null then
          if v_code_sug_bakasha = 18 then
             build_check_message(1,'0527','0260',36,'') ;
          end if;
         else 
             v_zakaut_legimlaot_kefel := 1;
         end if;
         exception
         when others then
         message := sqlerrm;
         check_message := check_message || ' event_527; semel_260 - ' || message ||  '<br />';
         end;
      elsif v_semel_hilan in ('0261','0284') then -- להשתכרות
        begin
        if v_code_sug_bakasha = 17 then
          v_zakaut_lehistakrut := 1;
          select  case when v_semel_hilan = '0261' then 0 else t.sum end,
          t.from_date, t.to_date
          into v_schum, v_date_start_zakaut_histakrut, v_date_end_zakaut
          from hachnasot t
          where t.seq_bakasha = v_seq_bakasha;
          if v_date_start_zakaut_histakrut is null then
             build_check_message(1,'0527',v_semel_hilan,37,'') ;
          end if;
        end if;
        exception
        when others then
        message := sqlerrm;
        build_check_message(1,'0527',v_semel_hilan,37,'',message) ;
        end;
      elsif v_semel_hilan in ('0244') then -- משכורת לגיל 60
        select t.is_zakai_lmaanak,
               t.achuz_kizba_gil_60           
        into v_zakaut_le_maanak_prisha,
             v_achuz_kizva_zfuya_legil_60_59             
        from netuney_tik_mechushavim t
        where t.seq_bakasha = v_seq_bakasha
        and t.code_department = 2
        /*and t.mispar_misra = v_mispar_misra*/;
        if   v_zakaut_le_maanak_prisha = 1 and v_achuz_kizva_zfuya_legil_60_59 is not null then         
        begin
          select t.maskoret_kovaat                         
          into v_maskoret_legil_60        
          from netuney_sachar t
          where t.seq_bakasha = v_seq_bakasha        
          and t.seq_netuney_sachar =  r.seq_netuney_sachar
          and t.code_sug_maskoret = 2;
          v_schum := v_maskoret_legil_60; 
        exception
          when others then
          message := sqlerrm;
          build_check_message(2,'0527','0244',38,'',message) ;
        end;
          if v_maskoret_legil_60 is null then
          build_check_message(2,'0527','0244',38,'') ;
          end if;                                                  
        end if;
        elsif v_semel_hilan = '0630' then --חיסכון פנסיוני
        if v_code_sug_bakasha = 12 then
          begin
          select t.hp_code_chayav_retro
          into v_hp_code_chayav_retro
          from bakasha_regila t
          where t.seq_bakasha = v_seq_bakasha;
          exception
          when others then
          message := sqlerrm;
          build_check_message(1,'0527','0630',6,'',message) ;
          end; 
          begin
          select t.code_min
          into v_min_poresh
          from poresh t
          where t.mispar_zehut = v_mispar_zehut;
          select t.code_min
          into v_min_benzug
          from bney_mishpacha t
          where t.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
          and t.code_kirva = 10;
          exception
          when others then
          message := sqlerrm;
          build_check_message(1,'0527','0630',9,'',message) ;
          end;
          if v_min_poresh is null then
          build_check_message(1,'0527','0630',39,'') ;
          end if;           
        else return true;
        end if;
        if v_hp_code_chayav_retro = 2 then   --שיעור חישוב הפחטה
          if v_min_benzug = 1
            then v_schum := 1.2;
          else 
            v_schum := 2.8;
          end if;
        elsif v_hp_code_chayav_retro = 1 then
          if v_min_poresh = 1
            then v_schum := 1.2;
          else 
            v_schum := 2.8;
          end if;
       elsif v_hp_code_chayav_retro = 3 then
            v_schum := 2.8;
       else v_schum := 0;
       end if;
        --if v_schum = 0 then return true; end if;
    else
        begin      
        select t.havraa_days,
               /*t.sum_havraa,
               t.bigud,*/
               t.is_maanak_yovel,
               t.kovaat_161            
        into v_yamei_havraa,
             /*v_schum_leyom,
             v_kzuvat_bigud,*/
             v_zakaut_lemaanak_yovel,
             v_maskoret_kovaat_lepitzuim            
        from netuney_sachar t
        where t.seq_bakasha = v_seq_bakasha        
        and (t.seq_netuney_sachar =  r.seq_netuney_sachar and t.code_sug_maskoret = 1
        or t.seq_netuney_sachar is null);
          exception
          when others then
          message := sqlerrm;
          build_check_message(1,'0527','0630',40,'',message) ;
        end;      
        if v_semel_hilan = '0234' then                               --ימי הבראה)
             v_schum := v_yamei_havraa;
             if v_schum is null  then
             build_check_message(1,'0527','0630',41,'') ;
             end if;
            --v_code_hishuv := 4;       
     elsif   v_semel_hilan = '0235' then                               --זכאות למענק יובל
             if v_zakaut_lemaanak_yovel is null  then
             build_check_message(1,'0527','0630',42,'') ;
             end if;
     elsif   v_semel_hilan = '0280' then                               --משכורת אחרונה לפיצויים
             v_schum := v_maskoret_kovaat_lepitzuim;
             if v_schum is null  then
             build_check_message(1,'0527','0630',43,'') ;
             end if;
            --v_code_hishuv := 0;
     elsif v_semel_hilan = '0000' and v_code_sug_bakasha in (1,14) /*or (v_code_sug_bakasha = 13 and v_ptira_besherut_gimlat_chesed)*/ then
     for r1 in 
            (select c.semel_hilan, c.code_event_hilan
            from netuney_sachar s, tosefot t, code_semel_tosefet c
            where s.seq_bakasha = v_seq_bakasha
            and s.seq_netuney_sachar = r.seq_netuney_sachar
            and s.seq_netuney_sachar = t.seq_netuney_sachar
            and t.code_semel_tosefet = c.code_semel_tosefet
            and s.code_sug_maskoret = 1
            )     
     loop
     begin
             insert_or_check_event_dynamic(309,
                                  lpad_zeroez(to_char(r1.semel_hilan),4),
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mistz_almana_benzug_sheer,
                                  v_mispar_zehut_ben_katan,
                                  v_code_seif_prisha,
                                  0,
                                  v_mispar_misra);  
             if not if_commit then return false; end if;
     end;
     end loop;
     end if;
     end if;
     end loop;
     if v_times = 0 then
        build_check_message(1,'0527',v_semel_hilan,40,'') ;
     end if;
     return true;
    end;
   ------------------------------------
   --  זכאויות למינוי  
   function insert_event_527_zakaut(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number,
                          v_code_hishuv number,
                          v_mispar_misra_last number default 0
                          ) return boolean is
   
   v_hodashim_mezakim_be_maanak_prisha number;     --243 V
   v_zakaut_le_maanak_prisha number;               --242 V
   v_zakaut_leshanim_odfot number;                 --240 V
   v_achuz_kizva_zfuya_legil_60_59 float;          --239 V
   v_chelkiyut_legil_60 float;                     --238 V
   v_hodashim_odfim number;                        --241 V
   v_yamei_havraa number;                          --234 V
   v_zakaut_lemaanak_yovel number;                 --235 V
   v_maskoret_kovaat_lepitzuim float;              --280 V
   v_prisha_lefi_seif_57_62 number;                --250 V
   v_zakaut_lemaanak_nisuin_1 number;              --245 V
   v_zakaut_lemaanak_nisuin_2 number;              --246 V
   v_bitul_maanak number;                          --247
   v_zakaut_lemaanak_had_paami number;             --248 V
   --v_zakaut_lemaanak_had_paami_2 number;         --249 V
   v_date_end_zakaut date := null;
   v_is_salary_up_70 number;
   v_schum float := 0;
   v_min_poresh number;
   v_min_benzug number;
   v_hp_code_chayav_retro number;
   v_mispar_zehut_sheer_benzug number := 0 ;
   v_mispar_zehut_sheer_benzug_amiti number := 0 ;
   v_mispar_misra number := 0;   
   v_code_hishuv_bitul number;
   v_date_start_zakaut_first date;
   v_date_start_zakaut_nisuin_1 date;
   v_date_start_zakaut_nisuin_2 date;
   v_teur_ezor_ovdim varchar2(50);
   v_code_relative number;
   v_seq_bney_mishpacha number;
   v_code_maaanak_almana number;
   v_semel_maaanak_almana number;
   v_achuz_kizva_almana number;
   v_date_zakaut_maanak_almana date;
   
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 

    if v_mispar_zehut_sheer_benzug <> 0 then
      select b.code_relative, b.seq_bney_mishpacha
      into v_code_relative, v_seq_bney_mishpacha
      from bney_mishpacha b
      left join poresh p on
      p.porshim_seq = b.seq_porshim      
      where b.mispar_zehut_ben_mishpacha = v_mispar_zehut_sheer_benzug_amiti
      and p.mispar_zehut = v_mispar_zehut_amiti;
      if v_code_relative not in (1,5) and v_semel_hilan in (240,242,248,249) then
        return true; --לשלוח זכאות למענקים רק לבני זוג 
      end if; 
    end if;  
  
    for r in (select n.*
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      order by n.mispar_misra)
      --for i in 1 .. v_mispar_misrot_leprisha
    loop
      
    if v_code_sug_bakasha in (7,23) and r.is_salary_up_70 <> 1 and v_semel_hilan <> '0239'
      then return true; end if;
      
    v_mispar_misra := r.mispar_misra;
    v_code_hishuv_bitul := 0;
   
      ld_log_events_record.code_event := 527;
      ld_log_events_record.code_event_semel := v_semel_hilan;
      
     
    --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    --if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 
       v_hodashim_mezakim_be_maanak_prisha := nvl(r.tkufa_mezaka_sherut,0);
       v_zakaut_le_maanak_prisha := r.is_zakai_lmaanak;
       v_zakaut_leshanim_odfot := case when  nvl(r.odef_sherut_chodashim,0)>0 or nvl(r.odef_sherut_yamim,0)>0 
                 then 1 
                 else 0 end;
       v_hodashim_odfim := nvl(r.odef_sherut_chodashim,0) + nvl(r.odef_sherut_yamim,0) / (30.44);
       v_achuz_kizva_zfuya_legil_60_59 := r.achuz_kizba_gil_60;
       v_chelkiyut_legil_60 := r.chelkiyut_meshuklelet_sherut;
       v_prisha_lefi_seif_57_62 := r.is_seif_57;
       
       --*********** 01/03/2021       
       if v_mispar_zehut_sheer_benzug <> 0 then 
         select case when nb.date_maanak_nisuin1 is not null then 1 else 0 end,
         case when nb.date_maanak_nisuin2 is not null then 1 else 0 end,
         nb.date_maanak_nisuin1, nb.date_maanak_nisuin2, nb.code_maanak_almana,
         nb.achuz_kizba, nb.date_zakaut_maanak_almana
         into v_zakaut_lemaanak_nisuin_1,
         v_zakaut_lemaanak_nisuin_2,
         v_date_start_zakaut_nisuin_1,
         v_date_start_zakaut_nisuin_2,
         v_code_maaanak_almana,
         v_achuz_kizva_almana,
         v_date_zakaut_maanak_almana
         from netuney_tik_ben_mishpacha nb
         where nb.seq_netuney_tik_mechushavim = r.seq_netuney_tik_mechushavim
         and nb.seq_bney_mishpacha = v_seq_bney_mishpacha;
       else
         v_zakaut_lemaanak_nisuin_1 := 0;
         v_zakaut_lemaanak_nisuin_2 := 0;
         v_date_start_zakaut_nisuin_1 := null;
         v_date_start_zakaut_nisuin_2 := null;
         v_code_maaanak_almana := null;
         v_date_zakaut_maanak_almana := null;
       end if;
       --***********
       
       /*v_zakaut_lemaanak_nisuin_1 := case when r.is_maanak_nisuin1 is not null then 1 else 0 end;
       v_zakaut_lemaanak_nisuin_2 := case when r.is_maanak_nisuin2 is not null then 1 else 0 end;
       v_date_start_zakaut_nisuin_1 :=  r.is_maanak_nisuin1;
       v_date_start_zakaut_nisuin_2 :=  r.is_maanak_nisuin2;
       v_code_maaanak_almana := r.code_maanak_almana;*/
      /* if nvl(r.code_maanak_almana,0) = 1 then     --23/09/2020
         v_zakaut_lemaanak_had_paami_2 := 1;
       elsif nvl(r.code_maanak_almana,0) = 2 then
         v_zakaut_lemaanak_had_paami_1 := 1;
       end if;*/

        
     
 /*      select t.tkufa_mezaka_sherut,
               t.is_zakai_lmaanak,
               case when  t.odef_sherut_chodashim>0 or t.odef_sherut_yamim>0 
                 then 1 
                 else 0 end as is_zakai_lmaanak_shanim_odfot,
               t.odef_sherut_chodashim + t.odef_sherut_yamim / (30.41) odef_sherut_chodashim_esroni,
               t.achuz_kizba_gil_60           
        into v_hodashim_mezakim_be_maanak_prisha,
             v_zakaut_le_maanak_prisha,
             v_zakaut_leshanim_odfot,
             v_hodashim_odfim,
             v_achuz_kizva_zfuya_legil_60_59             
        from netuney_tik_mechushavim t
        where t.seq_bakasha = v_seq_bakasha
        and t.code_department = 2
        and t.mispar_misra = v_mispar_misra;*/
        
     if v_semel_hilan = '0238' then                                    --חלקיות לגיל 60
         if v_chelkiyut_legil_60 <> r.chelkiyut_sofit and v_code_seif_prisha = 215
           then v_schum := v_chelkiyut_legil_60 * 100;
         else
             if v_code_sug_bakasha = 1 and v_seq_bakasha <> 381343 then continue;
             else v_code_hishuv_bitul := 2;
             end if;
         end if;
     elsif   v_semel_hilan = '0243' then                               --חודשים מזכים במענק פרישה
         if v_zakaut_le_maanak_prisha = 1 then
             v_schum := v_hodashim_mezakim_be_maanak_prisha;
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             --v_code_hishuv := 4;
         else
             v_schum := v_hodashim_mezakim_be_maanak_prisha;            
             v_date_end_zakaut := last_day(v_date_start_zakaut);       --30/04/2020 - חבה לסגור
              --return true;
         end if; 
     elsif   v_semel_hilan = '0245' then                               --חודשים מזכים במענק נישואין 1
         if v_zakaut_lemaanak_nisuin_1 = 1 then           
             v_date_end_zakaut := last_day(v_date_start_zakaut_nisuin_1);
         else
             continue;
         end if; 
     elsif   v_semel_hilan = '0246' then                               --חודשים מזכים במענק נישואין 2
         if v_zakaut_lemaanak_nisuin_2 = 1 then
             v_date_end_zakaut := last_day(v_date_start_zakaut_nisuin_2);
         else
             continue;
         end if;
     ---------------21/02/2021
     elsif   v_semel_hilan in ('0248','0249') then
          /*if nvl(v_zakaut_lemaanak_had_paami,0) <>  0 then*/
             select c.code_hilan
             into v_semel_maaanak_almana
             from code_maanak_almana c
             where c.code_maanak_almana = v_code_maaanak_almana;
             if to_number(v_semel_hilan) = v_semel_maaanak_almana then
               v_date_end_zakaut := last_day(v_date_zakaut_maanak_almana);
             else continue;
             end if;
          /*end if;*/
     ---------------
     elsif  v_semel_hilan = '4248' then
         v_date_end_zakaut := last_day(v_date_zakaut_maanak_almana);
         v_schum := v_achuz_kizva_almana * r.chelkiyut_sofit;
         v_4248 := true;
     ---------------
     elsif  v_semel_hilan = '0250' then                                --זכאות לפי סעיף 57
         if v_prisha_lefi_seif_57_62 = 1
             then v_date_end_zakaut := r.date_end_zakaut;
         else
            continue;
         end if;
      elsif  v_semel_hilan = '0242' then                                --זכאות למענק פרישה
          if v_code_sug_bakasha <> 1 then
               /*select min(z.date_start_zakaut)
               into v_date_start_zakaut_first
               from v_bakasha_last_status v, v_bakasha_last_zakaut z
               where v.gimla_number = v_gimla_number
               and v.mispar_zehut = v_mispar_zehut_amiti
               and v.seq_bakasha = z.seq_bakasha;*/
           select z.date_start_zakaut
               into v_date_start_zakaut_first
               from v_bakasha_last_status v, v_bakasha_last_zakaut z
               where v.gimla_number = v_gimla_number
               and v.mispar_zehut = v_mispar_zehut_amiti 
               and v.seq_bakasha = z.seq_bakasha
               and z.seq_bakasha = 
               (select min(z1."SEQ_BAKASHA")
               from v_bakasha_last_zakaut z1
               left join v_bakasha_last_status v1
               on v1.seq_bakasha = z1."SEQ_BAKASHA"
               where z1.seq_prisha = v.seq_prisha
               and v1.code_action not in (17,100))
               and v.code_action not in (17,100);
               if v_date_start_zakaut <> v_date_start_zakaut_first then continue; end if; 
                                                                                  --לא לשלוח זכאות / ביטול זכאות 
                                                                                 -- לתאריך שונה מהזכאות הראשונה
                                                                                 --(TFS 94942)                                                                                
          end if;       
          if v_zakaut_le_maanak_prisha = 1 then
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             --v_code_hishuv := 1;
          else
             if v_code_sug_bakasha = 1 then continue;
             else v_code_hishuv_bitul := 2;
             end if;
             --continue;
          end if;
     elsif  v_semel_hilan = '0239' then                               --קצבה צפויה לגיל 60/59 
          /*begin
          select n1.achuz_kizba_gil_60
          into v_achuz_kizva_zfuya_legil_60_59
          from netuney_tik_mechushavim n1
          where n1.seq_bakasha = v_seq_bakasha
          and n1.code_department = 2
          \*and n1.mispar_misra = v_mispar_misra*\;
          exception
               when no_data_found then
               v_achuz_kizva_zfuya_legil_60_59 := null;
          end;*/ 
           --if v_zakaut_le_maanak_prisha = 1 then
            if not v_achuz_kizva_zfuya_legil_60_59 is null and  
                   v_achuz_kizva_zfuya_legil_60_59 <> 0 then
             v_schum := v_achuz_kizva_zfuya_legil_60_59;
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             --v_code_hishuv := 0;
            else
             continue;  
            end if;
           --else
             --continue;
             --return true;
           --end if; 
     elsif  v_semel_hilan = '0240' then                               --זכאות למענק שנים עודפות
          if v_zakaut_leshanim_odfot = 1 then
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             --v_code_hishuv := 1;
          else
              if v_code_sug_bakasha =  1 then continue;
              else v_code_hishuv_bitul := 2;
              end if;
          end if;
     elsif  v_semel_hilan = '0241' then                               --חודשים עודפים
          if v_zakaut_leshanim_odfot = 1 then
             v_schum := v_hodashim_odfim;
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             --v_code_hishuv := 4;
          else
             continue;
             --return true;
          end if;
     end if;
     prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug=0 or
                               (v_mispar_zehut_sheer_benzug<>0 and v_code_sug_bakasha = 12 and v_semel_hilan = '0630') then
                                v_mispar_zehut
                        else
                               v_mispar_zehut_sheer_benzug end,
                        case when v_mispar_misrot_sach_hakol > 1 then 
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                        else 
                               v_gimla_number
                        end,                            
                        true,
                        case when v_code_sug_bakasha = 12 then v_hp_taarich_tokef_haavara
                             when v_semel_hilan in ('0248','0249','4248') then v_date_zakaut_maanak_almana
                             when v_semel_hilan = '0245' then v_date_start_zakaut_nisuin_1
                             when v_semel_hilan = '0246' then v_date_start_zakaut_nisuin_2
                              when v_semel_hilan = 2218 then
                             case when v_code_sug_bakasha = 1 or 
                                  (v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25) or
                                  (v_code_sug_bakasha = 13 and v_code_source <> 17) then
                                      to_date(to_char(v_date_start_zakaut,date_format_d6) || '01', date_format_d8)
                                      else to_date(to_char(sysdate,date_format_d6) || '01', date_format_d8) end
                             else to_date(to_char(v_date_start_zakaut,date_format_d6) || '01', date_format_d8) end);
                                                
     if not insert_event then return false; end if;  
        
     ld_log_events_record.code_trigger := 2;
     ld_log_events_record.record_hilan := 
     '0' ||        
     case when v_code_sug_bakasha = 12 then to_char(v_hp_taarich_tokef_haavara,date_format_d8) 
          when v_semel_hilan in ('0248','0249','4248') then to_char(v_date_zakaut_maanak_almana,date_format_d8)         
          when v_semel_hilan = '0245' then to_char(v_date_start_zakaut_nisuin_1,date_format_d8)
          when v_semel_hilan = '0246' then to_char(v_date_start_zakaut_nisuin_2,date_format_d8)
          when v_semel_hilan ='2218' then
            case when v_code_sug_bakasha = 1 or 
           (v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25) or
           (v_code_sug_bakasha = 13 and v_code_source <> 17)
              then to_char(v_date_start_zakaut,date_format_d6) || '01'
              else 
                   to_char(sysdate,date_format_d6) || '01' end       
          else to_char(v_date_start_zakaut, date_format_d8) end ||                                                            --TAARICH
     (case when v_date_end_zakaut is null then lpad_zeroez(0,8) else to_char(v_date_end_zakaut,date_format_d8) end) ||       --GMARTOKEF
     lpad_zeroez(case when v_code_hishuv_bitul<>2 then v_code_hishuv else v_code_hishuv_bitul end, 1) ||                                                                                         --KODISHI
     ' ' ||                                                                                                                  --מינוס
     lpad_zeroez(replace(to_char(nvl(v_schum,0),'0000000.99'),'.',''),9) ||                                                  --SUM 
     lpad_zeroez(0,3);                                                                                                       --TAARIF
     --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || v_event_hilan_current ||  '<br />';
     if not insert_event then return false; end if;   
     if v_semel_hilan in ('0248','0249') then
               insert_or_check_event_dynamic(527,
                                  '4248',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mistz_almana_benzug_sheer,
                                  0,
                                  v_code_seif_prisha,
                                  1,                               
                                  v_mispar_misra,
                                  1);
                if not if_commit then return false; end if;
         end if;       
     end loop;
     return true;
    exception
    when no_data_found then
       return true;
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_527_zakaut: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_527_zakaut: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
      return false;
    end;
  ------------------------------------  
  --הוראות קבע 
  --  זכאויות למינוי  
   function check_event_527_zakaut(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number,
                          v_code_hishuv number,
                          v_mispar_misra_last number default 0
                          ) return boolean is
   
   v_hodashim_mezakim_be_maanak_prisha number;     --243 V
   v_zakaut_le_maanak_prisha number;               --242 V
   v_zakaut_leshanim_odfot number;                 --240 V
   v_achuz_kizva_zfuya_legil_60_59 float;          --239 V
   v_hodashim_odfim number;                        --241 V
   v_yamei_havraa number;                          --234 V
   v_zakaut_lemaanak_yovel number;                 --235 V
   v_maskoret_kovaat_lepitzuim float;              --280 V
   v_prisha_lefi_seif_57_62 number;                --250
   v_zakaut_lemaanak_nisuin_1 number;              --245
   v_zakaut_lemaanak_nisuin_2 number;              --246
   v_bitul_maanak number;                          --247
   v_zakaut_lemaanak_had_paami_1 number;           --248
   v_zakaut_lemaanak_had_paami_2 number;           --249
   v_date_end_zakaut date := null;
   v_schum float := 0;
   v_min_poresh number;
   v_min_benzug number;
   v_hp_code_chayav_retro number;
   v_mispar_zehut_sheer_benzug number := 0 ;
   v_mispar_zehut_sheer_benzug_amiti number := 0 ;
   v_mispar_misra number := null;   
   
   v_teur_ezor_ovdim varchar2(50);                        
  
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
        
    --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
    --if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 
       
    for r in (select n.*
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2
      order by n.mispar_misra)
      --for i in 1 .. v_mispar_misrot_leprisha
    loop
      
    v_mispar_misra := r.mispar_misra;
       
      begin
      select t.tkufa_mezaka_sherut,
               t.is_zakai_lmaanak,
               case when  t.odef_sherut_chodashim>0 or t.odef_sherut_yamim>0 
                 then 1 
                 else 0 end as is_zakai_lmaanak_shanim_odfot,
               t.odef_sherut_chodashim + t.odef_sherut_yamim / (30.41) odef_sherut_chodashim_esroni,
               t.achuz_kizba_gil_60
               --t.is_maanak_nisuin1,
               --t.is_maanak_nisuin2
        into v_hodashim_mezakim_be_maanak_prisha,
             v_zakaut_le_maanak_prisha,
             v_zakaut_leshanim_odfot,
             v_hodashim_odfim,
             v_achuz_kizva_zfuya_legil_60_59
             --v_zakaut_lemaanak_nisuin_1,
             --v_zakaut_lemaanak_nisuin_2            
        from netuney_tik_mechushavim t
        where t.seq_bakasha = v_seq_bakasha
        and t.code_department = 2
        /*and t.mispar_misra = v_mispar_misra*/;
       exception
         when others then
         message := sqlerrm;
         build_check_message(1,'0527',v_semel_hilan,4,'',message) ;
       end;
         
      begin
        select t.teur_ezor_ovdim
        into v_teur_ezor_ovdim
        from code_ezor_ovdim t
        where t.seq_ezor_ovdim = v_seq_ezor_ovdim
        and t.pail = 1;
        if instr(v_teur_ezor_ovdim,'רוה"מ') 
          > 0  then v_zakaut_le_maanak_prisha := 0;         --רוה"מ ת"א לא יועבר לחילן זכאות למענק פרישה.
        end if;                                             --(גם אם יש להם זכאות) כי המשרד משלם את המענק
                                                            --בעצמו
      exception
         when others then
         message := sqlerrm;
         build_check_message(1,'0527',v_semel_hilan,1,'',message) ;
     end;
 
     if   v_semel_hilan = '0243' then                               --חודשים מזכים במענק פרישה
         if v_zakaut_le_maanak_prisha = 1 then
             v_schum := v_hodashim_mezakim_be_maanak_prisha;
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             if v_schum is null  then
              check_message := check_message || ' event_527; semel_243' ||  '<br />';
             end if;
            --v_code_hishuv := 4;
         end if; 
         if v_zakaut_le_maanak_prisha =1 and v_hodashim_mezakim_be_maanak_prisha is null then
          build_check_message(1,'0527','0243',43,'') ;
         end if;
     elsif  v_semel_hilan = '0242' then                                --זכאות למענק פרישה
          if v_zakaut_le_maanak_prisha = 1 then
             v_date_end_zakaut := last_day(v_date_start_zakaut);
          end if;
     elsif  v_semel_hilan = '0244' then                               --קצבה צפויה לגיל 60/59 
          begin
          select n1.achuz_kizba_gil_60
          into v_achuz_kizva_zfuya_legil_60_59
          from netuney_tik_mechushavim n1
          where n1.seq_bakasha = v_seq_bakasha
          and n1.code_department = 2
          /*and n1.mispar_misra = v_mispar_misra*/;
          exception
               when no_data_found then
               v_achuz_kizva_zfuya_legil_60_59 := null;
          end;                       
          if v_zakaut_le_maanak_prisha = 1 then
            if not v_achuz_kizva_zfuya_legil_60_59 is null then
             v_schum := v_achuz_kizva_zfuya_legil_60_59;
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             if v_schum is null then
              check_message := check_message || ' event_527; semel_244' ||  '<br />';
             end if;
            end if;
          end if;       
     elsif  v_semel_hilan = '0240' then                               --זכאות למענק שנים עודפות
          if v_zakaut_leshanim_odfot = 1 then
             v_date_end_zakaut := last_day(v_date_start_zakaut);
          end if;
     elsif  v_semel_hilan = '0241' then                               --חודשים עודפים
          if v_zakaut_leshanim_odfot = 1 then
             v_schum := v_hodashim_odfim;
             v_date_end_zakaut := last_day(v_date_start_zakaut);
             if v_schum is null  then
              check_message := check_message || ' event_527; semel_241' ||  '<br />';
             end if;
          end if;
          if v_zakaut_leshanim_odfot = 1 and v_hodashim_odfim is null then
             build_check_message(1,'0527','0241',44,'') ;
          end if;
     end if;
    end loop;
    if v_mispar_misra is null then
       build_check_message(1,'0527','0241',4,'') ;
    end if;
    return true;
   exception
   when others then
    build_check_message(1,'0527','0241',4,'') ;
    return true;
    end;
  ------------------------------------  
   function insert_event_413(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
    v_schum float;                             --תוספות
    --v_amount float;                          --תוספות
    v_achuz float;
    v_kamut float;
    v_code_ezor_ovdim number;
    v_is_keren number;
    v_seif_takzivi varchar2(6);
    --is_first boolean := true;
 
    v_mispar_zehut_sheer_benzug number :=0;
    v_mispar_zehut_sheer_benzug_amiti number :=0;
   
    v_date_payment date;
    v_date_end date;
    v_achuz_mimaskoret_kovaat_leeynam_kranot float;           --287
    v_achuz_maskoret_kovaat_lekranot float;                   --288
    v_hishtatfut_beschum_lekranot float;                      --284
    v_hishtatfut_beschum_leeynam_kranot float;                --291
    v_hishtatfut_beschum_letkufa_arait float;                 --292
    v_hishtatfut_beachuz_letkufa_arait float;
    v_hishtatfut_beschum_heskem_meyuhad float;                --293
    v_hishtatfut_beachuz_heskem_meyuhad float;                --215
    v_is_heskem_meyuhad boolean;
    v_tosefet_actuarit float;                                 --296
    v_tosefet_dchiat float;                                   --298
    v_hizoni float;                                           --285
    v_schum_maanak  float;                                    --217   --295
    v_chodshey_guf_be_pizuy_odef_shanim  float;               --210
    v_hefresh_chodshey_guf_be_pizuy_odef_shanim  float;       --211                  
    v_part_code_seif_prisha number;
/*    v_maskoret_kovaat_ofek float;
    v_maskoret_kovaat_horaa float;
    v_chodashim_ofek number;
    v_chodashim_horaa number;*/
    v_maskoret_kovaat float;                                  --1443,1445
    v_chodashim number;
    v_ribit_hazmada_al_cheshbon_haguf float;                 --1126
    v_tosefet_ofek float;
    v_nikuy_karit_bitachon float;
    begin

    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 

    ld_log_events_record.code_event := 413;
    ld_log_events_record.code_event_semel := v_semel_hilan;
    
    if  v_semel_hilan in (1443,1445)
           and v_seq_ezor_ovdim = 206 and
           v_code_sug_bakasha = 14
           and v_sachar_reforma = 1 
           and check_hatama_laheskem
                (v_mispar_zehut,
                v_seq_bakasha,
                v_seq_prisha,
                v_code_sug_bakasha) = 0 then
      ld_log_events_record.code_trigger := 0;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug<>0 then v_mispar_zehut_sheer_benzug  else v_mispar_zehut end,
                        case when v_mispar_misrot_sach_hakol > 1 then
                                v_gimla_number * 10 + 1
                             else 
                                v_gimla_number
                             end,
                        true,
                        to_date(to_char(v_date_start_zakaut,date_format_d6) || '01',date_format_d8)); 
      --is_first := false;
      if not insert_event then return false; end if;
   end if;

      
    if (v_code_sug_bakasha in (1,14) or v_code_sug_bakasha = 5 and nvl(v_code_bakasha_detail,0) = 25) and
       v_semel_hilan in (1443,1445) and v_sachar_reforma <> 1 then
     begin
       select n.maskoret_kovaat, n.chodashim
       into  v_maskoret_kovaat, v_chodashim
       from netuney_sachar n, v_bakasha_last_status v
            where v.seq_bakasha = v_seq_bakasha
            and v.seq_bakasha = n.seq_bakasha
            and v.code_makor = 3
            and n.code_sug_maskoret = case when v_semel_hilan = 1443 then 3 else 1 end;
       v_schum := v_maskoret_kovaat;
       if v_semel_hilan = 1445 then
        select tos.sum                    
          into v_tosefet_ofek  
          from netuney_sachar t
          left join tosefot tos on
          tos.seq_netuney_sachar = t.seq_netuney_sachar
          where t.seq_bakasha = v_seq_bakasha        
          and t.code_sug_maskoret = 1
          and tos.code_semel_tosefet = 879;      
        if nvl(v_tosefet_ofek,0)>0  then 
            v_schum := v_schum - v_tosefet_ofek;
        end if;
       end if;
       v_kamut := v_chodashim;
/*       select cs.maskoret_kovaat_ofek,cs.maskoret_kovaat_horaa, cs.chodashim_ofek, cs.chodashim_horaa
       into  v_maskoret_kovaat_ofek, v_maskoret_kovaat_horaa, v_chodashim_ofek, v_chodashim_horaa
       from chinuch_salary cs
       where cs.seq_bakasha = v_seq_bakasha;
       if v_semel_hilan = 1443 then
         v_schum := v_maskoret_kovaat_ofek;
         v_kamut := v_chodashim_ofek;
       else
         v_schum := v_maskoret_kovaat_horaa;
         v_kamut := v_chodashim_horaa;
       end if;*/
       if nvl(v_schum,0) = 0 and nvl(v_kamut,0) = 0 then return true; end if;
       exception
       when others then
       return true;
     end;
      ld_log_events_record.code_trigger := 0;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug<>0 then v_mispar_zehut_sheer_benzug  else v_mispar_zehut end,
                        case when v_mispar_misrot_sach_hakol > 1 then
                                v_gimla_number * 10 + 1
                             else 
                                v_gimla_number
                             end,
                        true,
                        to_date(to_char(v_date_start_zakaut,date_format_d6) || '01',date_format_d8)); 
      --is_first := false;
      if not insert_event then return false; end if;

      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                         --MINUI
             to_char(v_date_start_zakaut,date_format_d6) || '01' ||                         --TAARICH
             lpad_zeroez(0,8) ||                                                            --GMATTOKEF                                                                        
             '0' ||                                                                         --KODISHI
             ' ' ||                                                                         --מינוס
             case when v_schum is null                                                      --TASHLUM
                       then lpad_zeroez(0,9)
                       else lpad_zeroez(replace(to_char(nvl(v_schum,0),'9999999.99'),'.',''),9)
             end ||                                                                         
             lpad_zeroez(0,3) ||                                                            --TAARIF???
             ' '  ||                                                                          --מינוס                                                                                  
             case when v_kamut is not null and v_kamut <> 0 then
                          lpad_zeroez(replace(to_char(nvl(v_kamut,0),'99999.99'),'.',''),7)  
                  else lpad_zeroez(0,7) end ||                                              --KAMUT
             lpad_zeroez(0,9) ||                                                            --SEIF
             lpad_zeroez(0,11) ||                                                           --MEKORI
             lpad_zeroez(0,11) ||                                                           --MITZTABER
             lpad_zeroez(0,3) ||                                                            --MISPAR
             lpad_zeroez(0,3) ||                                                            --BUTZU
             lpad_zeroez(0,9) ||                                                            --ASMACTA
             lpad_zeroez(0,5) ||                                                            --AHUZ
             lpad_zeroez(0,6);                                                              --ערך
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || '413' ||  '<br />';
      if insert_event then
        return true;
      else
        return false;
      end if;
    end if;
      
    v_kayam_mispar_guf_behilan := true;
    

    for r in (select distinct t.*
                from participation t
                where t.seq_bakasha = v_seq_bakasha
                and t.is_hilan = 1
                ) loop
    begin 
        
    if v_semel_hilan = 1116 then
      begin
      select nvl(n.interest_linkage,0)
      into v_schum
      from netuney_tik_mechushavim n
      where n.seq_bakasha = v_seq_bakasha
      and n.code_department = 2;
      if nvl(v_schum,0) = 0 then
        return true;
      end if;
      exception
       when others then
       return true;
      end;
    else
    
    if v_code_sug_bakasha in (7,23) then v_mispar_gufim_mesumanin := v_mispar_gufim_mesumanin + 1; end if;
    v_kamut := 0;
    
    v_achuz_mimaskoret_kovaat_leeynam_kranot := null;
    v_achuz_maskoret_kovaat_lekranot := null;
    v_hishtatfut_beschum_lekranot := null;
    v_hishtatfut_beschum_leeynam_kranot := null;
    v_hishtatfut_beschum_letkufa_arait := null;
    v_hishtatfut_beschum_heskem_meyuhad := null;
    v_hizoni := null;
    v_tosefet_actuarit := null;
    v_tosefet_dchiat := null;
    v_schum_maanak := null;
    v_ribit_hazmada_al_cheshbon_haguf := null;
    v_nikuy_karit_bitachon := null;
    
    select  nvl(c.code_ezor_ovdim_hilan,0), decode(c.code_sug_ezor_ovdim,5,1,0) is_keren
    into v_code_ezor_ovdim, v_is_keren
    from code_ezor_ovdim c
    where c.seq_ezor_ovdim = r.seq_guf;

/*    if v_code_sug_bakasha = 7 and v_semel_hilan not in(285,287,295)
       and v_code_ezor_ovdim not in (727800,727900,728000) then continue; end if;*/

     if v_code_ezor_ovdim = 0 then
           if is_check_running = 0 then
               /*clob_log := clob_log || to_char(v_mispar_zehut) || ' - ' || to_char(v_seq_bakasha) || ' - ' ||
               'אין קוד גוף בחילן שתואם לקוד מפם' || ' ' || 
               to_char(r.seq_guf) || '<br />';*/
            v_kayam_mispar_guf_behilan := false;
            return true;
            /*else
              check_message_error := 'אין קוד גוף בחילן שתואם לקוד מפם' || ' ' || 
               r.seq_guf || chr_10;
              check_message_error_short := check_message_error;
              check_count_error := check_count_error + 1;*/
            end if;
            --return false;
    end if;
    
    begin
     if v_semel_hilan = '0237' then
        if v_code_sug_bakasha = 7 and v_code_bakasha_detail = 43 then --מעבר מנכות לאורך שירות
                      insert_or_check_event_dynamic(237,
                                   '0000',
                                   v_seq_ld_protocol,
                                   v_seq_ld_protocol_hilan,
                                   v_seq_bakasha,
                                   v_mispar_zehut,
                                   v_gimla_number,
                                   v_seq_ezor_ovdim,
                                   v_code_sug_bakasha,
                                   v_mistz_almana_benzug_sheer,
                                   v_mispar_zehut_ben_katan,
                                   v_code_seif_prisha,
                                   0);         
                if not if_commit then return false; else return true; end if;
         else
           return true;
         end if;      
     end if;
                
     if v_semel_hilan = '0210' then
      select nvl(p.odef_sherut_baguf,0)
        into v_chodshey_guf_be_pizuy_odef_shanim
        from v_bakasha_last_status v, participation p, bakasha_regila b
        where v.seq_bakasha = v_seq_bakasha
        and v.seq_bakasha = p.seq_bakasha
        and p.seq_guf = r.seq_guf
        and v.seq_bakasha = b.seq_bakasha
        and nvl(p.odef_sherut_baguf,0) > 0
        and p.sum = b.maskoret_kovaat;
        v_kamut := v_chodshey_guf_be_pizuy_odef_shanim;
     end if;
     exception
     when no_data_found then
      continue;
     end;
     
     begin
     if v_semel_hilan = '0211' then
     select distinct nvl(nm_new.chodshey_pizuy,0) - nvl(nm_old.chodshey_pizuy,0)
        into v_hefresh_chodshey_guf_be_pizuy_odef_shanim
        from v_bakasha_last_status v1,
        v_mechushavim_2_curnt_and_prev m,
        netuney_tik_mechushavim nm_new,
        netuney_tik_mechushavim nm_old
        where v1.seq_bakasha = v_seq_bakasha
        and m.code_department = 2
        and m.current_seq_bakasha = v1.seq_bakasha
        and m.seq_bakasha < m.current_seq_bakasha
        and m.current_seq_bakasha = nm_new.seq_bakasha
        and nm_new.code_department = 2
        and m.seq_bakasha = nm_old.seq_bakasha
        and nm_old.code_department = 2
        and m.seq_bakasha = 
        (select max(m1.seq_bakasha)
        from v_mechushavim_2_curnt_and_prev m1
        where m1.current_seq_bakasha = m.current_seq_bakasha
        and m1.seq_bakasha < m.current_seq_bakasha)
        and nvl(nm_new.chodshey_pizuy,0) <> nvl(nm_old.chodshey_pizuy,0);
      if v_hefresh_chodshey_guf_be_pizuy_odef_shanim = 0 then continue; end if;
      v_kamut := v_hefresh_chodshey_guf_be_pizuy_odef_shanim;
      if v_kamut < 0.005 then v_kamut := 0; end if; --עיגול עד 0.99 
     end if;
     exception
     when no_data_found then
      continue;
     end;
     
   begin
    v_is_heskem_meyuhad := true;
    select p.sum_participation,
    p.achuz_guf_final * p.partial_period,
    p.interest_linkage
    into v_hishtatfut_beschum_heskem_meyuhad,
    v_hishtatfut_beachuz_heskem_meyuhad,
    v_ribit_hazmada_al_cheshbon_haguf
    from bakasha_regila t, participation p
    where t.code_seif_prisha = 415
    and t.code_sub_seif_prisha = 990
    and t.seq_bakasha = v_seq_bakasha
    and t.seq_bakasha = p.seq_bakasha
    and p.seq_guf = r.seq_guf;
    exception
    when no_data_found then
      v_is_heskem_meyuhad := false;
      v_hishtatfut_beschum_heskem_meyuhad := null;
    end;

     begin
      if v_code_sug_bakasha = 7 then 
        select v.code_seif_prisha
        into v_part_code_seif_prisha
        from v_bakasha_last_status v
        where v.seq_bakasha = v_seq_bakasha;
      else --v_code_sug_bakasha = 23
        select v2.code_seif_prisha
        into v_part_code_seif_prisha
        from v_bakasha_last_status v1
        left join v_bakasha_last_status v2 on
        v1.seq_prisha = v2.seq_prisha
        where v1.code_sug_bakasha = 23
        and v1.code_seif_prisha = 128
        and v1.seq_bakasha = v_seq_bakasha
        and v2.code_sug_bakasha = 1
        and v2.code_seif_prisha = 215;
      end if;
      exception
      when no_data_found then
      v_part_code_seif_prisha := 0;
    end;

    if v_is_keren = 1 then
       select t.date_payment,
       t.date_end,
       --t.percent_participate,
       --t.achuz_guf_final,
       t.achuz_guf_final * t.partial_period,
       t.achuz_arai,
       case when not v_hishtatfut_beschum_heskem_meyuhad is null then null 
            when v_part_code_seif_prisha <> 215 then t.sum_participation
            else 0 end,
       case when seq_guf = 8 then t.tosefet_actuarit else null end, -- 8 - קרן גלעד
       case when seq_guf = 8 then t.tosefet_dchiat else null end,
       case when v_part_code_seif_prisha <> 215 then t.sum_arai else
            nvl(t.sum_participation,0) + nvl(t.sum_arai,0) end,
       t.schum_maanak_baguf,
       t.interest_linkage,
       t.nikuy_karit_bitachon    
       into v_date_payment, v_date_end,
            v_hizoni,
            v_hishtatfut_beachuz_letkufa_arait,
            v_hishtatfut_beschum_lekranot,
            v_tosefet_actuarit,
            v_tosefet_dchiat,
            v_hishtatfut_beschum_letkufa_arait,
            v_schum_maanak,
            v_ribit_hazmada_al_cheshbon_haguf,
            v_nikuy_karit_bitachon
       from participation t
       where t.seq_bakasha = v_seq_bakasha
       and t.seq_guf = r.seq_guf;
     else
       select t.date_payment,t.date_end,
       --t.percent_participate,
       --t.achuz_guf_final,
       t.achuz_guf_final * t.partial_period,
       t.achuz_arai,
       case when not v_hishtatfut_beschum_heskem_meyuhad is null then null 
            when v_part_code_seif_prisha <> 215 then t.sum_participation
            else 0 end,
       case when v_part_code_seif_prisha <> 215 then t.sum_arai else
            nvl(t.sum_participation,0) + nvl(t.sum_arai,0) end,
       t.schum_maanak_baguf,
       t.interest_linkage
       into v_date_payment,v_date_end,
            v_hizoni,
            v_hishtatfut_beachuz_letkufa_arait,
            v_hishtatfut_beschum_leeynam_kranot,
            v_hishtatfut_beschum_letkufa_arait,
            v_schum_maanak,
            v_ribit_hazmada_al_cheshbon_haguf
       from participation t
       where t.seq_bakasha = v_seq_bakasha
       and t.seq_guf = r.seq_guf;
    end if;
    
    if v_date_payment is null then
       message := v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' || 'לא נשלח: לא מוגדר תאריך זכאות'; 
       clob_log := clob_log ||('insert_event_413: ' || message) ||  '<br />';
       continue;
    elsif is_check_running = 0 and v_date_payment >=trunc(Last_Day(sysdate) + 1) then continue; --לא לשלוח 06/2019     
    end if;

      if (v_semel_hilan = '0285'
      and not (nvl(v_hishtatfut_beschum_lekranot,0) = 0
           and nvl(v_hishtatfut_beschum_leeynam_kranot,0) = 0
           and nvl(v_hishtatfut_beschum_letkufa_arait,0) = 0  
           and nvl(v_tosefet_actuarit,0) = 0  
           and nvl(v_tosefet_dchiat,0) = 0)
      or (v_semel_hilan = '0215'
         and nvl(v_hishtatfut_beschum_heskem_meyuhad,0) <> 0 ))
       then     
          continue; --לא לשלוח 215,285 אם יש סכום
      end if;     
     
      v_schum := null;
      v_achuz := null;
     
      if v_semel_hilan = '0290' then
        v_schum := v_hishtatfut_beschum_lekranot;
      elsif v_semel_hilan = '0291' then
        v_schum := v_hishtatfut_beschum_leeynam_kranot;
      elsif v_semel_hilan = '0292' then
        v_schum := v_hishtatfut_beschum_letkufa_arait;
      elsif v_semel_hilan = '0293' then
        v_schum := v_hishtatfut_beschum_heskem_meyuhad;
      elsif v_semel_hilan = '0296' then
        v_schum := v_tosefet_actuarit;
      elsif v_semel_hilan = '0298' then     
        v_schum := v_tosefet_dchiat;     
 /*     elsif v_semel_hilan = '0295' then     
        v_schum := v_schum_maanak;
*/     
      elsif v_semel_hilan = '0217' then     
        v_schum := v_schum_maanak;
      elsif v_semel_hilan = '1126' then
        v_schum := v_ribit_hazmada_al_cheshbon_haguf;
        v_achuz := null;
        v_kamut := null;
      elsif v_semel_hilan = '1290' then
        v_schum := v_nikuy_karit_bitachon;
        v_achuz := null;
        v_kamut := null;
     end if;

      if v_semel_hilan = '0285' and not v_is_heskem_meyuhad then
        v_achuz := v_hizoni;
      elsif
        v_semel_hilan = '0215' and v_is_heskem_meyuhad then
        v_achuz := v_hishtatfut_beachuz_heskem_meyuhad;
      end if;
     
     if v_achuz = 0 then v_achuz := null; end if;
     if v_schum = 0 then v_schum := null; end if;
     
     --if v_semel_hilan in (290,291,292,293,296,298) and v_schum is null then v_schum := 0; end if;
     if v_semel_hilan in (287,288) and v_achuz is null then v_achuz := 0; end if;
    
     if (v_semel_hilan in ('0290','0291','0292','0293','0296','0298',/*'0295'*/'0217') and v_schum is null) then continue; end if;
     if (v_semel_hilan in ('0215','0285') and v_achuz is null) then continue; end if;
     if (v_semel_hilan in ('0210','0211') and (v_kamut is null or v_kamut = 0)) then continue; end if;
     if (v_semel_hilan in ('1126','1290') and v_schum is null) then continue; end if;
     if v_semel_hilan in ('0210','0211',/*'0295'*/'0217') then
        v_date_end := last_day(v_date_payment);
     end if;
     if v_semel_hilan = '1290' and v_date_payment < to_date('01/01/2021','dd/mm/yyyy') then
        v_date_payment := to_date('01/01/2021','dd/mm/yyyy');
     end if;
         
    end if;
      --end if;
      --if is_first then
      
      if v_semel_hilan in(1116,1126) then
        v_date_payment := trunc(sysdate);
        v_date_end := last_day(v_date_payment);
      end if;      

      
      ld_log_events_record.code_trigger := 0;
      prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug<>0 then v_mispar_zehut_sheer_benzug  else v_mispar_zehut end,
                        case when v_mispar_misrot_sach_hakol > 1 then
                                v_gimla_number * 10 + 1
                             else 
                                v_gimla_number
                             end,
                        true,
                        to_date(to_char(v_date_payment,date_format_d6) || '01',date_format_d8),
                        case when v_semel_hilan not in ('0211','1116') then
                          ' ' || lpad_zeroez(0,3) || lpad_zeroez(v_code_ezor_ovdim/100,4) || '99'
                        else rpad_blanks(' ',10)
                        end);
      --is_first := false;
      if not insert_event then return false; end if;
      --end if;
                         
      if nvl(v_schum,0) <> 0
      or nvl(v_achuz,0) <> 0
      or nvl(v_kamut,0) <> 0 then
        
      --if (v_schum is not null and v_schum<>0) then  v_achuz := v_hizoni; end if;
 
      if nvl(v_schum,0) <> 0 then  
        if v_semel_hilan ='0292' then v_achuz := v_hishtatfut_beachuz_letkufa_arait;
        elsif v_semel_hilan not in ('1116', '1126', '1290') then v_achuz := v_hizoni;
        end if;
      end if;
      
      --if v_semel_hilan ='0295' then
      if v_semel_hilan ='0217' then
        v_achuz := 0;
        v_kamut := 0;
      end if;
         
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                         --MINUI
             to_char(v_date_payment,date_format_d6) || '01' ||                              --TAARICH
             case when v_date_end is not null then 
               to_char(v_date_end,date_format_d8) else lpad_zeroez(0,8) end ||              --GMATTOKEF                                                                        
             '0' ||                                                                         --KODISHI
             case when v_semel_hilan = '1290' then '-' else ' ' end ||                       --מינוס
             case when v_schum is null                                                      --TASHLUM
                       then lpad_zeroez(0,9)
                       else lpad_zeroez(replace(to_char(nvl(v_schum,0),'9999999.99'),'.',''),9)
             end ||                                                                         
             lpad_zeroez(0,3) ||                                                            --TAARIF???
             case when v_semel_hilan = '0211' and v_kamut < 0 then  '-'  else  ' '  end ||  --מינוס                                                                                  
             --case when not v_achuz is null then '0000100' else lpad_zeroez(0,7) end ||    --KAMUT
             case when nvl(v_achuz,0) <> 0 then                                             --AHUZ
                          lpad_zeroez(replace(to_char(nvl(v_achuz,0),'99999.99'),'.',''),7)  
                  when nvl(v_kamut,0) <> 0 then
                          lpad_zeroez(replace(to_char(nvl(v_kamut,0),'99999.99'),'.',''),7)  
                  else lpad_zeroez(0,7) end ||                                                                         
             case when v_semel_hilan in ('0211','1116') then                                 --SEIF
                          lpad_zeroez(0,9)
                  else lpad_zeroez(0,3) || lpad_zeroez(v_code_ezor_ovdim/100,4) || '99' end || 
             lpad_zeroez(0,11) ||                                                           --MEKORI
             lpad_zeroez(0,11) ||                                                           --MITZTABER
             lpad_zeroez(0,3) ||                                                            --MISPAR
             lpad_zeroez(0,3) ||                                                            --BUTZU
             lpad_zeroez(0,9) ||                                                            --ASMACTA
             lpad_zeroez(0,5) ||                                                            --AHUZ
             lpad_zeroez(0,6);                                                              --ערך
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || '413' ||  '<br />';
      if insert_event then
        if v_semel_hilan in ('0211','1116') then
          return true;
        else
          continue; 
        end if;
      else
        return false;
      end if;
      end if;
     end;
   
   end loop;
   
   return true;
    exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_event_413: ' || message) ||  '<br />';
       v_error_172_message := 'insert_event_413: ' || message;
       v_error_172_seq_bakasha := v_seq_bakasha;
       v_error_172_mispar_zehut := v_mispar_zehut;
       return false;
    end;   
  ------------------------------------  
  --הוראות קבע 
    function check_event_413(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number
                          ) return boolean is
    v_schum float;                             --תוספות
    --v_amount float;                            --תוספות
    v_achuz float;
    v_code_ezor_ovdim number;
    v_is_keren number;
    v_seif_takzivi varchar2(6);
    is_first boolean := true;
 
    v_mispar_zehut_sheer_benzug number :=0;
    v_mispar_zehut_sheer_benzug_amiti number :=0;
    
    v_date_payment date;
    v_achuz_mimaskoret_kovaat_leeynam_kranot float;           --287
    v_achuz_maskoret_kovaat_lekranot float;                   --288
    v_hishtatfut_beschum_lekranot float;                      --284
    v_hishtatfut_beschum_leeynam_kranot float;                --291
    v_hishtatfut_beschum_letkufa_arait float;                 --292
    v_hishtatfut_beschum_heskem_meyuhad float;                --293
    v_tosefet_actuarit float;                                 --296
    v_tosefet_dchiat float;                                   --298
    
    begin     

 for r in (select distinct t.*
                from participation t
                where t.seq_bakasha = v_seq_bakasha
                ) loop
   begin 
    v_achuz_mimaskoret_kovaat_leeynam_kranot := null;
    v_achuz_maskoret_kovaat_lekranot := null;
    v_hishtatfut_beschum_lekranot := null;
    v_hishtatfut_beschum_leeynam_kranot := null;
    v_hishtatfut_beschum_letkufa_arait := null;
    v_hishtatfut_beschum_heskem_meyuhad := null;
    v_tosefet_actuarit := null;
    v_tosefet_dchiat := null;
 
    begin
    select  c.code_ezor_ovdim_hilan, decode(c.code_sug_ezor_ovdim,5,1,0) is_keren
    into v_code_ezor_ovdim, v_is_keren
    from code_ezor_ovdim c
    where c.seq_ezor_ovdim = r.seq_guf;
    if v_code_ezor_ovdim is null then
       check_message := check_message || ' event_413; semel_' ||  v_semel_hilan ||  '<br />';
    end if;
     exception
      when others then
      message := sqlerrm;
      check_message := check_message || ' event_413; semel_' || v_semel_hilan || ' - ' || message ||  '<br />';
    end;
         
    begin
    select p.sum_participation
    into v_hishtatfut_beschum_heskem_meyuhad
    from bakasha_regila t, participation p
    where t.code_seif_prisha = 415
    and t.code_sub_seif_prisha = 990
    and t.seq_bakasha = v_seq_bakasha
    and t.seq_bakasha = p.seq_bakasha;
    exception
    when no_data_found then
      v_hishtatfut_beschum_heskem_meyuhad := null;
    end;

    begin
    if v_is_keren = 1 then
       select t.date_payment,
       --t.percent_participate,
       t.achuz_guf_final,
       case when not v_hishtatfut_beschum_heskem_meyuhad is null then null else t.sum_participation end,
       case when seq_guf = 8 then t.tosefet_actuarit else null end, -- 8 - קרן גלעד
       case when seq_guf = 8 then t.tosefet_dchiat else null end,
       t.sum_participation                                          -- !!!!!!!!!!!!!!!!! לא נכון לתקופה ארעית
       into v_date_payment,
            v_achuz_maskoret_kovaat_lekranot,
            v_hishtatfut_beschum_lekranot,
            v_tosefet_actuarit,
            v_tosefet_dchiat,
            v_hishtatfut_beschum_letkufa_arait
       from participation t
       where t.seq_bakasha = v_seq_bakasha
       and t.seq_guf = r.seq_guf;
     else
       select t.date_payment,
       --t.percent_participate,
       t.achuz_guf_final,
       case when not v_hishtatfut_beschum_heskem_meyuhad is null then null else t.sum_participation end,
       t.sum_participation                                          -- !!!!!!!!!!!!!!!!! לא נכון לתקופה ארעית
       into v_date_payment,
            v_achuz_mimaskoret_kovaat_leeynam_kranot,
            v_hishtatfut_beschum_lekranot,
            v_hishtatfut_beschum_letkufa_arait
       from participation t
       where t.seq_bakasha = v_seq_bakasha
       and t.seq_guf = r.seq_guf;
    end if;
    if v_date_payment is null then
       check_message := check_message || ' event_413; semel_' ||  v_semel_hilan || ' - ' || 'לא מוגדר תאריך זכאות' || '<br />';
    end if;
     exception
      when others then
      message := sqlerrm;
      build_check_message(1,'0527',v_semel_hilan,45,'',message) ;
    end;
 
      v_schum := null;
      v_achuz := null;

      if v_semel_hilan = '0290' then
        v_schum := v_hishtatfut_beschum_lekranot;
      elsif v_semel_hilan = '0291' then
        v_schum := v_hishtatfut_beschum_leeynam_kranot;
      elsif v_semel_hilan = '0292' then
        v_schum := v_hishtatfut_beschum_letkufa_arait;
      elsif v_semel_hilan = '0293' then
        v_schum := v_hishtatfut_beschum_heskem_meyuhad;
      elsif v_semel_hilan = '0296' then
        v_schum := v_tosefet_actuarit;
      elsif v_semel_hilan = '0298' then     
        v_schum := v_tosefet_dchiat;
       end if;

      if v_semel_hilan = '0287' then
        v_achuz := v_achuz_mimaskoret_kovaat_leeynam_kranot;
      elsif v_semel_hilan = '0288' then
        v_achuz := v_achuz_maskoret_kovaat_lekranot;
      end if;
      
     if (v_semel_hilan in ('0290','0291','0292','0293','0296','0298') and v_schum is null) then
       --check_message := check_message || ' event_413; semel_' ||  v_semel_hilan ||  '<br />';
       continue;
     end if;
     if (v_semel_hilan in ('0287','0288') and v_achuz is null) then
       --check_message := check_message || ' event_413; semel_' ||  v_semel_hilan ||  '<br />';     
       continue;
     end if;
   end;
   end loop;   
   return true;
   end;
  ------------------------------------  
  -- נתוני גמלה למינוי
    function insert_event_309(v_semel_hilan varchar2,
                          v_seq_ld_protocol number,
                          v_seq_ld_protocol_hilan number,
                          v_seq_bakasha number,
                          v_mispar_zehut number,
                          v_gimla_number number,
                          v_seq_ezor_ovdim number,
                          v_code_sug_bakasha number,
                          v_mistz_almana_benzug_sheer number,
                          v_mispar_zehut_ben_katan number,
                          v_code_seif_prisha number,
                          v_mispar_misra_last number default 0
                          ) return boolean is
    v_schum float;                              --תוספות
    v_amount float;                            --תוספות
    v_mispar_zehut_sheer_benzug number :=0;
    v_mispar_zehut_sheer_benzug_amiti number :=0;
    v_mispar_misra number := 0;
    v_code_derug number;
    v_code_darga number;
    v_code_misrad_maskoret number := 0;
    v_code_event_tosefet number;
    v_havraa_first0 boolean := true;
    v_bigud_first0 boolean := true;
    v_havraa_first1 boolean := true;
    v_bigud_first1 boolean := true;
    
    begin  
    if v_mistz_almana_benzug_sheer<>0 then v_mispar_zehut_sheer_benzug := v_mistz_almana_benzug_sheer; end if;
    if v_mispar_zehut_ben_katan<>0 then v_mispar_zehut_sheer_benzug := v_mispar_zehut_ben_katan; end if;
    v_mispar_zehut_sheer_benzug_amiti := get_mispar_zehut_amiti(v_mispar_zehut_sheer_benzug, v_gimla_number); 
 
      if v_sachar_reforma = 1 and v_semel_hilan not in (2004,2005) then
               if (v_code_sug_bakasha = 1
               or v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25
               or v_code_sug_bakasha = 13 and v_netuney_sachar_kayamim 
               or v_code_sug_bakasha = 14) then
               insert_or_check_event_dynamic(315,
                                  '0181',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mistz_almana_benzug_sheer,
                                  v_mispar_zehut_ben_katan,
                                  v_code_seif_prisha,
                                  0,
                                  v_mispar_misra);  
             if not if_commit then return false; else return true; end if;
           end if;
      end if;
 
    
      if v_semel_hilan = 2025 then
      select nvl(c.code_misrad_maskret,0)
        into v_code_misrad_maskoret
        from code_ezor_ovdim c
        where c.seq_ezor_ovdim = v_seq_ezor_ovdim;
      end if;
     
      ld_log_events_record.code_event := 309;
      ld_log_events_record.code_event_semel := 
           case when v_semel_hilan = 2025 and v_code_misrad_maskoret <> 401
                then 2073
                else v_semel_hilan end;
      
     --לשארים מעבירים נתוני שכר וזכאות רק במקרה של פטירה בשירות של הפורש
     --if v_code_sug_bakasha = 13 and not v_ptira_besherut_gimlat_chesed then return true; end if; 

      if v_code_sug_bakasha in (10,11) and v_semel_hilan = '0004' then -- (שכר משולב (4 
         select sum(p.kizba_chodshit),0                   
            into v_schum, v_amount
            from participation p
            where p.seq_bakasha = v_seq_bakasha
            group by p.seq_bakasha;
            prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        v_mispar_zehut,
                        v_gimla_number,
                        true,
                        --v_date_start_zakaut);
                        to_date(to_char(v_date_start_zakaut,date_format_d6) || '01',date_format_d8));                    
      if not insert_event then return false; end if;
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                 --MINUI
             --to_char(v_date_start_zakaut,date_format_d8)    ||                                      --TAARICH                                                                                     
             to_char(v_date_start_zakaut,date_format_d6) || '01' ||                                 --TAARICH
             lpad_zeroez(0,8) ||                                                                    --GMATROKEF
             '0' ||                                                                                 --KODISHI
             ' ' ||                                                                                 --מינוס
             lpad_zeroez(replace(to_char(nvl(v_schum,0),'0000000.99'),'.',''),9) ||                 --TASHLUM
             lpad_zeroez(0,3) ||                                                                    --TAARIF
             ' ' ||                                                                                 --מינוס
             '0' ||                                                                                 --פילר
             lpad_zeroez(0,6) ||                                                                    --KAMUT
             lpad_zeroez(0,9) ||                                                                    --SEIF
             lpad_zeroez(0,11) ||                                                                   --MEKORI
             lpad_zeroez(0,11) ||                                                                   --MITZTABER
             lpad_zeroez(0,3) ||                                                                    --MISPAR
             lpad_zeroez(0,3) ||                                                                    --BUTZU
             '229230900' ||                                                                         --ASMACTA
             lpad_zeroez(0,9);                                                                      --פילר
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || '309' ||  '<br />';
        if not insert_event then return false; else return true; end if; -----??????????????????? else?
    else
    for r in (select n.*/*, 
      max(nvl(n.sum_bigud,0)) sum_bigud_all,
      max(nvl(n.sum_havraa,0)) sum_havraa_all*/
      from netuney_sachar n
      where n.seq_bakasha = v_seq_bakasha
      and (v_sachar_reforma <> 1 and n.code_sug_maskoret = 1 or
           v_sachar_reforma = 1 and n.code_sug_maskoret = 
      (select m.code_sug_maskoret
      from code_sug_maskoret m
      where m.code_chinuch_sug_maskoret = 1
      and m.code_sug_maskoret = n.code_sug_maskoret
      and n.seq_bakasha = v_seq_bakasha
      /*and rownum < 2*/))
      --n.mispar_misra = v_mispar_misra_last; 
      --and (v_mispar_misra_last = 0 or v_mispar_misra_last<>0 and n.mispar_misra = v_mispar_misra_last)
      order by n.mispar_misra) loop
      
      if v_sachar_reforma <> 1 then
      v_mispar_misra := r.mispar_misra;
      select cd.derug_hilan, cd.darga_hilan
      into v_code_derug, v_code_darga
      from code_derug_darga_hilan cd
      where cd.derug_malam = r.code_derug
      and cd.darga_malam = r.code_darga;
      
      if (v_code_derug in (4,5,6,15,23,42,44,45,57,58,59,74,78,/*82,*/83,84,85) or
        v_code_derug = 82 and v_code_darga not in ('0032','0042','0052'))
        and (r.code_uchlusia is null or r.code_uchlusia = 99)
        and v_semel_hilan not in ('2004','2005')
        --and v_semel_hilan = '0004'
        then continue; --לא לדווח שכר משולב לאוכלוסיות מיוחדות
      end if;
      end if;
        
      if v_semel_hilan not in ('0004','2004','2005') and r.mispar_misra <> v_mispar_misra_last then continue; end if;
      

      if v_semel_hilan = '0004' then          -- (שכר משולב (4 
        select t.schar_ysod, 0
        into v_schum, v_amount
        from netuney_sachar t
        where t.seq_bakasha = v_seq_bakasha
        and t.seq_netuney_sachar =  r.seq_netuney_sachar;
      elsif v_semel_hilan = '2004' then        --1/12 מההבראה
        if  v_sachar_reforma = 1
          and r.mispar_misra = 0 and v_havraa_first0 = false 
          or  r.mispar_misra = 1 and v_havraa_first1 = false 
        then continue;
        else
          select t.sum_havraa, 0
          into v_schum, v_amount
          from netuney_sachar t
          where t.seq_bakasha = v_seq_bakasha
          and t.seq_netuney_sachar =  r.seq_netuney_sachar;
          v_schum := v_schum;
        end if;
          if v_schum = 0 or v_schum is null then continue; end if;
        if  v_sachar_reforma = 1 then
          if r.mispar_misra = 0 then v_havraa_first0 := false; end if;
          if r.mispar_misra = 0 then v_havraa_first1 := false; end if;
        end if;
      elsif v_semel_hilan = '2005' then        --1/12 מהביגוד
        if  v_sachar_reforma = 1
          and r.mispar_misra = 0 and v_bigud_first0 = false 
          or  r.mispar_misra = 1 and v_bigud_first1 = false 
        then continue;
        else
          select t.sum_bigud, 0
          into v_schum, v_amount
          from netuney_sachar t
          where t.seq_bakasha = v_seq_bakasha
          and t.seq_netuney_sachar =  r.seq_netuney_sachar;
          v_schum := v_schum;
        end if;
          if v_schum = 0 or v_schum is null then continue; end if;        
        if  v_sachar_reforma = 1 then
          if r.mispar_misra = 0 then v_bigud_first0 := false; end if;
          if r.mispar_misra = 0 then v_bigud_first1 := false; end if;
        end if;
      else 
        begin                                    --תוספות בפועל
        select t.sum, t.amount, c.code_event_hilan     
        into v_schum, v_amount, v_code_event_tosefet 
        from tosefot t, netuney_sachar s, code_semel_tosefet c
        where s.seq_netuney_sachar = t.seq_netuney_sachar
        and s.code_sug_maskoret = 1
        and s.seq_bakasha = v_seq_bakasha
        and t.code_semel_tosefet = c.code_semel_tosefet
        and s.mispar_misra = v_mispar_misra
        and c.semel_hilan = v_semel_hilan
        and t.seq_tosefot = v_seq_tosefot
        and c.sug_natun = 106;
        exception
         when others then
         continue;
        end;   

         --and c.code_event_hilan = 309;
        if v_code_event_tosefet = 527 then return true; end if; --לא צריך לדווח לחילן. מחושב בחילן אוטומטית
        
      end if;
      
      /*if v_seq_bakasha = 371662 and v_semel_hilan = 1096 then
        v_schum := v_schum * (-1);
      end if;*/
 
     ld_log_events_record.code_event := 309;
     ld_log_events_record.code_event_semel := 
           case when v_semel_hilan = 2025 and v_code_misrad_maskoret <> 401
                then 2073
                else v_semel_hilan end;
     prepare_trigger_0(v_seq_ld_protocol,
                        v_seq_ld_protocol_hilan,
                        v_seq_bakasha,
                        case when v_mispar_zehut_sheer_benzug<>0 then v_mispar_zehut_sheer_benzug  else v_mispar_zehut end,
                              case when v_mispar_misrot_sach_hakol > 1 then 
                               to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))
/*                             to_number(substr(lpad_zeroez(v_gimla_number,9),1,2) ||
                               lpad_zeroez(v_mispar_misra,1) ||
                               substr(lpad_zeroez(v_gimla_number,9),4,6))
*/                 
                              else 
                                v_gimla_number
                              end,
                        true,
                        --v_date_start_zakaut);
                        to_date(to_char(v_date_start_zakaut,date_format_d6) || '01',date_format_d8));                    
      if not insert_event then return false; end if;
      ld_log_events_record.code_trigger := 2;
      ld_log_events_record.record_hilan := 
             '0' ||                                                                                 --MINUI
             --to_char(v_date_start_zakaut,date_format_d8)    ||                                    --TAARICH                                                                                     
             to_char(v_date_start_zakaut,date_format_d6) || '01' ||                                 --TAARICH
             lpad_zeroez(0,8) ||                                                                    --GMATROKEF
             '0' ||                                                                                 --KODISHI
             case when nvl(v_schum,0) < 0 then '-' else ' ' end ||                                  --מינוס
             lpad_zeroez(replace(to_char(nvl(abs(v_schum),0),'0000000.99'),'.',''),9) ||            --TASHLUM
             lpad_zeroez(0,3) ||                                                                    --TAARIF
             ' ' ||                                                                                 --מינוס
             '0' ||                                                                                 --פילר
             lpad_zeroez(replace(to_char(nvl(v_amount,0),'000.999'),'.',''),6) ||                   --KAMUT
             lpad_zeroez(0,9) ||                                                                    --SEIF
             lpad_zeroez(0,11) ||                                                                   --MEKORI
             lpad_zeroez(0,11) ||                                                                   --MITZTABER
             lpad_zeroez(0,3) ||                                                                    --MISPAR
             lpad_zeroez(0,3) ||                                                                    --BUTZU
             '229230900' ||                                                                         --ASMACTA
             lpad_zeroez(0,9);                                                                      --פילר
             --clob_log := clob_log || to_char(length(ld_log_events_record.record_hilan)) || 'length' || '309' ||  '<br />';
       if not insert_event then return false; end if;
       
 /*     if not v_2218 or
      check_mz_exists_in_varray(case when  v_mispar_zehut_sheer_benzug <> 0 then v_mispar_zehut_sheer_benzug 
                                      else v_mispar_zehut end,
                                 case when v_mispar_misrot_sach_hakol > 1 then to_number(lpad(v_gimla_number,8) || lpad_zeroez(v_mispar_misra+1,1))                
                                      else v_gimla_number end
                                        ) = false then
       insert_or_check_event_dynamic(527,
                                  '2218',
                                  v_seq_ld_protocol,
                                  v_seq_ld_protocol_hilan,
                                  v_seq_bakasha,
                                  v_mispar_zehut,
                                  v_gimla_number,
                                  v_seq_ezor_ovdim,
                                  v_code_sug_bakasha,
                                  v_mistz_almana_benzug_sheer,
                                  v_mispar_zehut_ben_katan,
                                  v_code_seif_prisha,
                                  1,                               
                                  v_mispar_misra,
                                  6);  
