               and (b1.taarich_ptira is null or v_code_sug_bakasha in (19))) loop
*/  
            for b in (select * from bney_mishpacha b1  --אלמנ/ה, תלוי, צבא 
               where b1.seq_porshim = r.seq_porshim
               and not b1.code_relative is null
               and (b1.code_relative not in (2,3,9)
                   or b1.code_relative in (2,3) and b1.own_bank_account = 1
                   and b1.mispar_zehut_ben_mishpacha<>v_mispar_zehut_ben_katan)
               and ((b1.to_date_sium_zakaut is not null and b1.to_date_sium_zakaut > sysdate 
                    or b1.to_date_sium_zakaut is null) /*or nvl(b1.achuz_kizba,0) > 0*/ or v_code_sug_bakasha in (19,20))
               and ((b1.taarich_ptira is null or b1.taarich_ptira is not null and b1.taarich_ptira > v_date_start_zakaut) or v_code_sug_bakasha in (19))) loop
        
 /*           for b in (select b1.*, n1.date_end_zakaut, n1.achuz_kizba ak
               from bney_mishpacha b1,  --אלמנ/ה, תלוי, צבא 
               netuney_tik_ben_mishpacha n1 --***************
               where b1.seq_porshim = r.seq_porshim
               and n1.seq_bney_mishpacha = b1.seq_bney_mishpacha
               and n1.seq_netuney_tik_ben_mishpacha =
               (select max (n2.seq_netuney_tik_ben_mishpacha)
               from netuney_tik_ben_mishpacha n2
               left join netuney_tik_mechushavim n3 on
               n3.seq_netuney_tik_mechushavim = n2.seq_netuney_tik_mechushavim
               left join v_bakasha_last_status v on
               v.seq_bakasha = n3.seq_bakasha
               where v.gimla_number = v_gimla_number
               and n1.seq_bney_mishpacha = b1.seq_bney_mishpacha)  --***************  
               and not b1.code_relative is null
               and (b1.code_relative not in (2,3)
                   or b1.code_relative in (2,3) and b1.own_bank_account = 1
                   and b1.mispar_zehut_ben_mishpacha<>v_mispar_zehut_ben_katan)
               and ((b1.to_date_sium_zakaut is not null and b1.to_date_sium_zakaut > sysdate 
                    or b1.to_date_sium_zakaut is null) or nvl(n1.achuz_kizba,0) > 0 or v_code_sug_bakasha in (19,20))
               and ((b1.taarich_ptira is null or b1.taarich_ptira is not null and b1.taarich_ptira > v_date_start_zakaut) or v_code_sug_bakasha in (19))) loop
*/           begin
         /*if v_seq_bakasha = 154344  then 
          if b.mispar_zehut_ben_mishpacha = 067228411 then 
            v_mistz_almana_benzug_sheer := b.mispar_zehut_ben_mishpacha;
          else
            v_mistz_almana_benzug_sheer := 0;
          end if;
         else*/
         if v_code_sug_bakasha = 13 and nvl(v_code_bakasha_detail,0) = 35 then
          v_code_seif_prisha_lesheer := v_code_seif_prisha;
         else
          v_mistz_almana_benzug_sheer := b.mispar_zehut_ben_mishpacha;
          v_code_seif_prisha_lesheer := 
                      to_number(to_char(case b.code_relative when 6 then 1
                                                             when 7 then 1
                                                             when 8 then 2
                                                             else b.code_relative end) ||
                               substr(to_char(v_code_seif_prisha),2,2));
          end if;                                                                                 
         --end if;
            
            
             if (v_ptira_besherut_gimlat_chesed or v_ptirat_poresh) and v_mistz_almana_benzug_sheer <> 0 or v_code_sug_bakasha in (19,20) then
               if not(v_code_sug_bakasha =  13 and (v_code_source = 17 or nvl(v_code_bakasha_detail,0) = 37)) --לא לשלוח אחוז קצבה עבור שאר-בן זוג לפגי תוקף
                 and not(v_code_sug_bakasha = 18 and b.code_relative <> 1) --לשלוח גמלאות כפל רק לבן זוג
                 then 
                   if v_mistz_almana_benzug_sheer <> 0 then
                   insert_or_check_event_dynamic(v_event_hilan,
                                      v_semel_hilan,
                                      v_seq_ld_protocol,
                                      v_seq_ld_protocol_hilan,
                                      v_seq_bakasha,
                                      get_mispar_zehut_fictivi(v_mispar_zehut,v_gimla_number),
                                      --case when not v_code_sug_bakasha <> 12 then v_gimla_number*10 + v_tosefet_gimla_lesheerim
                                      v_gimla_number,                              
                                      v_seq_ezor_ovdim,
                                      v_code_sug_bakasha,
                                      get_mispar_zehut_fictivi(v_mistz_almana_benzug_sheer,v_gimla_number),
                                      0,
                                      v_code_seif_prisha,
                                      v_code_hishuv,
                                      0,
                                      v_code_natun);
                     if not if_commit=true and is_check_running <> 1 then  
                     if_commit_bakasha := false;
                     exit;
                     end if;
                  end if;            
               end if;
             end if;
             end;
             end loop;
             end if;
 
            if (v_mispar_zehut_ben_katan <> 0 /*and v_seq_bakasha <> 366147.000*/) or v_code_sug_bakasha in (19,20) then --גם לשלוח בקשה להפסקת תשלומים לעובד בלי קשר לשארים
            --v_tosefet_gimla_lesheerim := v_tosefet_gimla_lesheerim + 1;
              if not(v_code_sug_bakasha = 13 and nvl(v_code_bakasha_detail,0) = 35) then --גמלת חסד
               v_code_seif_prisha_lesheer := v_code_seif_prisha_leben_katan;
              else
           --v_code_seif_prisha_lesheer := v_code_seif_prisha;             
              select v.code_seif_prisha
               into v_code_seif_prisha_lesheer
               from v_bakasha_last_status v
               where v.seq_prisha = v_seq_prisha
               and v.code_sug_bakasha = 1
               and v.code_action = 98;
               if v_code_seif_prisha_lesheer is null then v_code_seif_prisha_lesheer := v_code_seif_prisha; end if;
               end if;
              insert_or_check_event_dynamic(v_event_hilan,
                                v_semel_hilan,
                                v_seq_ld_protocol,
                                v_seq_ld_protocol_hilan,
                                v_seq_bakasha,
                                get_mispar_zehut_fictivi(v_mispar_zehut,v_gimla_number),
                                v_gimla_number,
                                --v_gimla_number*10 + v_tosefet_gimla_lesheerim,
                                v_seq_ezor_ovdim,
                                v_code_sug_bakasha,
                                0,
                                get_mispar_zehut_fictivi(v_mispar_zehut_ben_katan,v_gimla_number),
                                v_code_seif_prisha_lesheer,
                                v_code_hishuv,
                                0,
                                v_code_natun);
              if not if_commit and is_check_running <> 1 then  
               if_commit_bakasha := false;
               exit;
              end if;            
            end if;

           if v_code_sug_bakasha in (19,20) and v_count_221 = 0 then
            if is_check_running = 0 then
             clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח: אין אפשרות לשלוח בקשה להפסקת תשלום') ||  '<br />';
             v_error_172_message := v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'אין אפשרות לשלוח בקשה להפסקת תשלום';
              v_error_172_seq_bakasha := v_seq_bakasha;
              v_error_172_mispar_zehut := v_mispar_zehut;
              v_error_number := v_error_number + 1;
            else
             check_message_error := 'אין אפשרות לשלוח בקשה להפסקת תשלום' || '<br />';
             check_message_error_short := check_message_error;
             check_count_error := check_count_error + 1;
            end if;
          end if;
          if v_event_hilan = 200 and v_sug_zihuy_lo_tikni = true then
            if is_check_running = 0 then
             clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'לא נשלח: סוג זיהוי לא תיקני     ') ||  '<br />';
             v_error_172_message := v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
             'אין אפשרות לשלוח בקשה  : סוג זיהוי לא תקני';
              v_error_172_seq_bakasha := v_seq_bakasha;
              v_error_172_mispar_zehut := v_mispar_zehut;
              v_error_number := v_error_number + 1;
             end if;
             exit;
          end if;
    exception
     when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_porshim_events_out: ' || message) || ' - ' || to_char(v_mispar_zehut) || '<br />';       
       continue;
      end;
    end loop;
    if is_check_running = 0 then
       if  v_code_sug_bakasha in (7,23) and not v_kayam_hishtatfut_567 and
           v_mispar_gufim_mesumanin = 0 /*and v_semel_hilan <> '1116'*/ then
           clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
                 'אין גופים מסומנים לשליחה לחילן') ||  '<br />';
           v_error_172_message := 'insert_event_413: ' || 'אין גופים מסומנים לשליחה לחילן';
           v_error_172_seq_bakasha := v_seq_bakasha;
           v_error_172_mispar_zehut := v_mispar_zehut;
           v_error_number := v_error_number + 1;
       elsif v_kayam_mispar_guf_behilan = false and v_code_sug_bakasha in (7,23) then
           clob_log := clob_log ||(v_mispar_zehut || ' - ' || v_seq_bakasha || ' - ' ||
                 'אין קוד גוף בחילן שתואם לקוד מפם') ||  '<br />';
           v_error_172_message := 'insert_event_413: ' || 'אין קוד גוף בחילן שתואם לקוד מפם';
           v_error_172_seq_bakasha := v_seq_bakasha;
           v_error_172_mispar_zehut := v_mispar_zehut;
           v_error_number := v_error_number + 1;
      elsif v_code_sug_bakasha = 18 and not v_netuney_gimlaot_kefel then
           clob_log := clob_log ||('insert_event_312: ' || 'אין נתונים לבקשת גמלאות כפל') ||  '<br />';
           v_error_172_message := 'insert_event_312: ' || 'אין נתונים לבקשת גמלאות כפל';
           v_error_172_seq_bakasha := v_seq_bakasha;
           v_error_172_mispar_zehut := v_mispar_zehut;
      end if;
      if v_events_count_for_bakasha = 0 then
         clob_log := clob_log ||(v_mispar_zehut || 'אין אירועים לשליחה לחילן, נא לבדוק שלמות נתונים של הבקשה') ||  '<br />';     
      v_error_172_seq_bakasha := v_seq_bakasha;
      v_error_172_mispar_zehut := v_mispar_zehut;
      v_error_172_message := 'אין אירועים לשליחה לחילן, נא לבדוק שלמות נתונים של הבקשה';
      v_error_number := v_error_number + 1;
      continue;
      end if;
      
    if if_commit_bakasha then
      
       if r.code_action = 134 then
         v_aaa := v_seq_bakasha;
         pk_prm_utils.insert_actions_for_bakasha(v_seq_bakasha); 
       end if;      
      commit;
              if v_netuney_sachar_leporesh = true and v_seq_ezor_ovdim = 206 then
                 for r in (select t1.*
                 from ld_log_events t1
                 where t1.seq_ld_protocol_hilan = v_seq_ld_protocol_hilan
                       and t1.mispar_zehut <> v_mispar_zehut
                       and t1.seq_bakasha = v_seq_bakasha
                       and t1.code_event = 309) loop                
                 update ld_log_events t2
                 set t2.mispar_zehut = v_mispar_zehut
                 where t2.seq_ld_log_events = r.seq_ld_log_events;
                 end loop;
                 
                 for r in (select t1.*
                 from ld_log_events t1
                 where t1.seq_ld_protocol_hilan = v_seq_ld_protocol_hilan
                       and t1.mispar_zehut <> v_mispar_zehut
                       and t1.seq_bakasha = v_seq_bakasha
                       and (t1.code_event = 527 and t1.code_event_semel in (234,235)
                       or  t1.code_event = 539 and t1.code_event_semel in (2,5)
                       or  t1.code_event = 535
                       or  t1.code_event = 312 and t1.code_event_semel = 407
                       --or  t1.code_event = 413
                       ))
                 loop
                 insert into ld_log_events t2
      (t2.seq_ld_protocol,
       t2.seq_ld_log_events,
       t2.date_create,
       t2.mispar_zehut,
       t2.code_trigger,
       t2.code_event,
       t2.code_event_semel,
       t2.gorem_medaveach,
       t2.seq_bakasha,
       t2.mispar_gimla,
       t2.date_report,
       t2.record_hilan,
       t2.seq_ld_protocol_hilan)
                 values
       (r.seq_ld_protocol,
        ld_log_events_seq.nextval,
        sysdate,
        v_mispar_zehut,
        r.code_trigger,
        r.code_event,
        r.code_event_semel,
        r.gorem_medaveach,
        r.seq_bakasha,
        r.mispar_gimla,
        r.date_report,
        r.record_hilan,
        r.seq_ld_protocol_hilan);
                 end loop;
        --v_netuney_sachar_leporesh := false;
      end if;       
       commit;
       
       v_success_number := v_success_number + 1;
       clob_log := clob_log ||(v_mispar_zehut || ' - success') ||  '<br />';
     else
      rollback;
      v_error_number := v_error_number + 1;
      clob_log := clob_log ||(v_mispar_zehut || ' - error') ||  '<br />';
     end if;
     
     else
      if v_event_hilan = 303 then
      if v_is_heshbon_bank = 1 then 
        message := ' '; 
        build_check_message(1,'0303','0000',26,'',message);
      end if;
      end if;
      if is_message_full = 1 then
      check_message := 
      case when check_count_error > 0 then '1'
           when check_count_warning > 0 then '2'
           else '0' end || chr_10 ||
                       case when check_count_error > 0 then 'שגיאות חמורות' else '' end || chr_10 ||
                       trim(check_message_error) ||
                       case when check_count_warning > 0 then 'אזהרות' else '' end || chr_10 ||
                       trim(check_message_warning);
      else
          check_message := case when check_count_error > 0 then '1' || chr_10 ||
                        trim(check_message_error_short)
                        else '0'|| chr_10
                        end;
      end if;
      return check_message;
    end if;
   end;
     clob_log := clob_log ||(v_mispar_zehut || ' - end') ||  '<br />';
   end loop;
      if v_error_172_seq_bakasha > 0 then
        pk_prm_utils.insert_action_log_row(172,sysdate,0,const_user_le_berur_shlicha_le_hilan,'ת.ז.:' || ' ' || v_error_172_mispar_zehut || ' - ' || v_error_172_message,
                                null,null,null,v_error_172_seq_bakasha,null); 
        commit;                                        
      end if;
      --return build_out_file(v_seq_ld_protocol, v_seq_ld_protocol_hilan);
      return null;
     --end if;
  else
     return null;
  end if;
  else return null;
  end if;
    exception
     when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_porshim_events_out: ' || message) || to_char(v_mispar_zehut) || '<br />';       
       return null;
   end;
  ------------------------------------
  function get_hilan_file_name (v_seq_ld_protocol number,
                                v_seq_ld_protocol_hilan number
) return varchar2 is
  v_mispar_mana varchar2(100);
  v_count_id_to_send number;
  v_userenv varchar2(10);
  begin
   select sys_context('userenv', 'DB_NAME') into v_userenv from dual;
   select count(*)
            into v_count_id_to_send
            from v_bakasha_last_status v
            where v.code_action in (134)
            ;
   if v_count_id_to_send > 0 then     
      v_mispar_mana := to_char(v_seq_ld_protocol_hilan);
      v_mispar_mana := substr(trim(v_mispar_mana),length(trim(v_mispar_mana)) - 2,3);
      v_mispar_mana := lpad_zeroez(v_mispar_mana,3);
      return case when v_userenv='xt1' /*prd*/ then 'MPMOA' else 'MPMTA' end ||
                       v_mispar_mana || '.TXT'; --'.ORC';
  else
     return null;
  end if;
    exception
     when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log ||('insert_porshim_events_out: ' || message) ||  '<br />';
  end;
