       --57170375
       --<>58188020 
 
       if v_record_type = '31' and 
/*         (r.melel like '%סעיף תקציב אינו נמצא בטבלת סעיפי תקציב%'  and r.melel like '%000000000%' --שליחת קוד אוכלוסיה 00
                                                                --לקוד אוכלוסיה לא ידוע לבקשות שומות מבקשת פרישה לגמלאות ו שארים
          or */
          r.melel like '%לשאר בוצעה העתקת רכיבי שכר בעבר%' --) 
          then v_record_type := '32';    --הודעות אזהרה ולא שגיאה     
       end if;
       
       if v_record_type = '21' then 
         v_mispar_zehut_21 := to_number(r.mispar_teudat_zehut);
         
       else v_mispar_zehut := to_number(r.mispar_teudat_zehut);
       
       if   v_mispar_zehut_old <> to_number(r.mispar_teudat_zehut) then  
