                 )loop
                 begin
                 if v_seq_bakasha_for_event <> b.seq_bakasha then
                    v_mispar_bakashot_for_event := v_mispar_bakashot_for_event + 1;
                 end if;
                 v_seq_bakasha_for_event := b.seq_bakasha;
                 end;
            end loop;
            
