               where m.code_record_level = to_number(substr(v_record_type,1,1))
               and m.code_record_level_message = to_number(substr(v_record_type,2,1));
               
               update ld_log_events t
               set t.date_hilan = to_date(r.date_hilan,'YYYYMMDD'),
                   t.code_record_level = to_number(substr(v_record_type,1,1)),
                   t.code_recode_level_message = to_number(substr(v_record_type,2,1)),
                   t.hilan_recode_level_message = v_hilan_recode_level_message3
               where t.seq_ld_protocol_hilan = r.seq_ld_protocol_hilan
               and t.code_event = to_number(v_code_event)
               and t.code_event_semel = to_number(v_semel_event)
               and t.mispar_zehut = r.mispar_teudat_zehut
               /*and (to_number(r.minuy)>=1 and (to_number(v_gimla_number) + (to_number(r.minuy)-1)*1000000 = t.mispar_gimla) and
                     not t.code_event in (200,205,218,219,303,298)
                     or t.code_event in (200,205,218,219,303,298))*/
               and (r.minuy = 0 or r.minuy > 0 and t.mispar_gimla = to_number(r.gimla_number))
               and (v_code_event <> 219 or v_code_event = 219  and not r.status is null)
               and t.code_trigger = 0;
               --clob_log := clob_log || to_number(v_code_event) || ' '  || to_number(r.semel_event) || ' ' || v_hilan_recode_level_message3 || '<br />';
             
        elsif   v_record_type = '31' then
          
               v_error_level := 1;
               select m.teur_record_level_message
               into v_hilan_recode_level_message3
               from code_hilan_record_level_message m
               where m.code_record_level = to_number(substr(v_record_type,1,1))
               and m.code_record_level_message = to_number(substr(v_record_type,2,1));
               v_hilan_recode_level_message3 := v_hilan_recode_level_message3 || '---' || trim(nvl(r.melel,' '));        
        
               update ld_log_events t
               set t.date_hilan = to_date(r.date_hilan,'YYYYMMDD'),
                   t.code_record_level = to_number(substr(v_record_type,1,1)),
                   t.code_recode_level_message = to_number(substr(v_record_type,2,1)),
                   t.hilan_recode_level_message = 
                   substr(decode(trim(t.hilan_recode_level_message),null,trim(v_hilan_recode_level_message3),
                   trim(t.hilan_recode_level_message) || '---' || trim(v_hilan_recode_level_message3)),3500),
                   t.hilan_recode_error_message =                    
                   substr(decode(trim(t.hilan_recode_error_message),null,trim(v_hilan_recode_level_message3),
                   trim(t.hilan_recode_error_message) || '---' || trim(v_hilan_recode_level_message3)),1,3500)                   
               where t.seq_ld_protocol_hilan = r.seq_ld_protocol_hilan
               and t.code_event = to_number(v_code_event)
               and t.code_event_semel = to_number(v_semel_event)
               and t.mispar_zehut = r.mispar_teudat_zehut
/*               and \*(to_number(r.minuy)>=1 and *\(to_number(v_gimla_number) + (to_number(r.minuy)-1)*1000000 = t.mispar_gimla\*)*\ and
                     not t.code_event in (200,205,218,219,303,298)
                     or t.code_event in (200,205,218,219,303,298))
*/            
               and (r.minuy = 0 or r.minuy > 0 and t.mispar_gimla = to_number(r.gimla_number))
               and (v_code_event <> 219 or 
                   v_code_event = 219  and trim(r.mispar_teudat_zehut_ben_mishpa) = substr(t.record_hilan,11,9) and r.date_hilan is null)
               and t.code_trigger <> 0;
               clob_log := clob_log || to_number(v_code_event) || ' '  || to_number(v_semel_event) || ' ' || v_hilan_recode_level_message3 || '<br />';
               v_error_number_leporesh := 1;               
              
        elsif   v_record_type = '32' then
 
               select m.teur_record_level_message
               into v_hilan_recode_level_message3
               from code_hilan_record_level_message m
               where m.code_record_level = to_number(substr(v_record_type,1,1))
               and m.code_record_level_message = to_number(substr(v_record_type,2,1));
               v_hilan_recode_level_message3 := trim(v_hilan_recode_level_message3) || '---' || trim(nvl(r.melel,' '));
               
               update ld_log_events t
               set t.code_record_level = to_number(substr(v_record_type,1,1)),
                   t.code_recode_level_message = to_number(substr(v_record_type,2,1)),
                   t.hilan_recode_level_message = 
                   substr(decode(trim(t.hilan_recode_level_message),null,trim(v_hilan_recode_level_message3),
                   trim(t.hilan_recode_level_message) || '---' || trim(v_hilan_recode_level_message3)),1,3500)
               where t.seq_ld_protocol_hilan = r.seq_ld_protocol_hilan
               and t.code_event = to_number(v_code_event)
               and t.code_event_semel = to_number(v_semel_event)
               and t.mispar_zehut = r.mispar_teudat_zehut
 /*            and (to_number(r.minuy)>=1 and (to_number(v_gimla_number) + (to_number(r.minuy)-1)*1000000 = t.mispar_gimla) and
                     not t.code_event in (200,205,218,219,303,298)
                     or t.code_event in (200,205,218,219,303,298))*/
               and (r.minuy = 0 or r.minuy > 0 and t.mispar_gimla = to_number(r.gimla_number))
               and (v_code_event <> 219 or 
                   v_code_event = 219  and trim(r.mispar_teudat_zehut_ben_mishpa) = substr(t.record_hilan,11,9) and r.date_hilan is null)
               and t.code_trigger <> 0;
               --clob_log := clob_log || to_number(v_code_event) || ' '  || to_number(r.semel_event) || ' ' || v_hilan_recode_level_message3 || '<br />';
               
        end if;
      --end;
      begin
      v_record_type_old := v_record_type;     
exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log || 'error - ' || v_code_event || ', ' || v_semel_event  || ', ' || v_mispar_zehut  || ' - ' || message || '<br/>' ;
       rollback;
       continue;
      end; 
      end loop;          
            --לקדם תיק לפי המסלול
              v_hodaa := trim(get_hodaot(v_seq_ld_protocol_hilan,v_seq_bakasha));
              if v_error_number_leporesh = 0 then
               v_success_number := v_success_number + 1;             
        --------------------------
        
        select t.code_action
        into v_code_current_action
        from v_bakasha_last_status t
        where t.seq_bakasha = v_seq_bakasha;
        
        --------------------------
               if v_code_current_action = 135 then
                 pk_prm_utils.insert_action_log_row(136,sysdate,0,0,v_hodaa,null,null,null,v_seq_bakasha,null);         
                    --לא לשלוח מכתב פעמים
                   get_next_action(v_seq_bakasha);
                   if v_mispar_shlichot_michtav > 0 and v_next_action = 129 --אישור שליחת מכתב
                     then pk_prm_utils.insert_action_log_row(98,sysdate,0,0,null,null,null,null,v_seq_bakasha,null);
                     else pk_prm_utils.insert_actions_for_bakasha(v_seq_bakasha);
                   end if;
               end if;
               else
               
               v_error_number := v_error_number + 1;
               if v_code_current_action = 135 then
               if instr(v_hodaa,'חסרים ארועי חובה',
                 1) > 0 
                 or instr(v_hodaa,'סעיף תקציב',
                 1) > 0 
                 or instr(v_hodaa,'לשאר בוצעה העתקת רכיבי שכר בעבר',
                 1) > 0 
                 or instr(v_hodaa,'לא קיים מינו',
                 1) > 0 
                then 
                   pk_prm_utils.insert_action_log_row(172,sysdate,0,const_user_le_berur_shlicha_le_hilan,'היזון חוזר: ' || v_hodaa,null,null,null,v_seq_bakasha,null);         
                 else
                   pk_prm_utils.insert_action_log_row(172,sysdate,0,const_user_le_berur_shlicha_le_hilan,'היזון חוזר: ' || v_hodaa,null,null,null,v_seq_bakasha,null);         
/*                 pk_prm_utils.insert_action_log_row(137,sysdate,0,0,v_hodaa,null,null,null,v_seq_bakasha,null);         
                 if (not v_user is null) then
                 pk_prm_utils.insert_action_log_row(49,sysdate,0,v_user,'הוחזר לטיפול אחרי כשלון קליטה בחילן' || v_hodaa,null,null,null,v_seq_bakasha,null);         
                 pk_prm_utils.insert_action_log_row(v_status_acharon,sysdate,0,v_user,'הוחזר לטיפול אחרי כשלון קליטה בחילן' || v_hodaa,null,null,null,v_seq_bakasha,null);         
               end if;
*/               end if;
               end if;
              end if;
              clob_log := clob_log ||(v_mispar_zehut || ' - end')  || '<br/>' ;
              clob_log := clob_log ||(v_seq_bakasha || ' - end')  || '<br/>' ;
              commit;
/*--בדיקת תיקים תקועים במצב 135 - נשלח לחילו
       clob_log := clob_log ||  '<br/>' ;
       clob_log := clob_log || 'בדיקת תיקים תקועים במצב 135 - נשלח לחילו' || '<br/>' ;       
          (select distinct t.seq_bakasha
          from ld_log_events t, v_bakasha_last_status v
          where t.seq_bakasha = v.seq_bakasha
          and t.seq_baksha <> 0
          and v.code_action = 135) loop
       begin
       end;
       end loop*/
              
      return v_seq_ld_protocol_hilan;
exception
    when others then
       status  := 0;
       message := sqlerrm;
       clob_log := clob_log || 'error - ' || v_code_event || ', ' || v_semel_event  || ', ' || v_mispar_zehut  || ' - ' || message || '<br/>' ;
       rollback;
       return 0;   
   end;
   
procedure test_name(v_seq_bakasha number) is
  v_shem_mishpacha varchar2(50);
  v_shem_prati varchar2(50);
  v_shem_nosaf varchar2(50); 
  begin  
    select  p.shem_mishpacha, p.shem_prati
            into v_shem_mishpacha, v_shem_prati
                from v_bakasha_last_status t
                left join poresh p on
                p.porshim_seq = t.seq_porshim
                where t.seq_bakasha = v_seq_bakasha;
    if length(trim(v_shem_prati)) > 10 and instr(trim(v_shem_prati),' ') > 0 then
      v_shem_prati := replace(v_shem_prati,'-',' ');
      v_shem_prati := replace(v_shem_prati,'(',' ');
      v_shem_prati := replace(v_shem_prati,')',' ');
      v_shem_prati := replace(v_shem_prati,'  ',' ');    
      v_shem_nosaf := substr(trim(v_shem_prati),instr(trim(v_shem_prati),' '),100);
      v_shem_prati := substr(trim(v_shem_prati),1,instr(trim(v_shem_prati),' ')-1);
    end if;
    exception
    when others then
       status  := 0;
       message := sqlerrm;
    end;
-- end;
 
