create or replace package body prm_system_copy.pk_hisachon_pensyoni is

  --------------------------------------------
  procedure main(p_seq_bakasha number) is
    v_marriage_date            date;
    v_divorce_date             date;
    v_start_work_date          date;
    v_prisha_date              date;
    v_shiur_haavara            number;
    v_shiur_haavara_calc       number;
    v_code_e_zakaut            number;
    v_date_start_zakaut        date;
    v_tkufa_meshutefet         number;
    v_code_seif_prisha         number;
    v_code_group_prisha        number;
    v_birth_date               date;
    v_seq_prisha               number;
    v_seq_bakasha_zakaut       number;
    v_zakaut_code_group_prisha number;
    v_code_yadani              number;
  begin
  
    v_code_yadani := pk_zakaut.get_code_yadani(p_seq_bakasha);
    if nvl(v_code_yadani, 0) > 0 then
      return;
    end if;
    select v.taarich_prisha,
           bm.taarich_nisuin,
           bm.taarich_preida,
           b.hp_sheur_havara,
           v.code_seif_prisha,
           sp.code_group_prisha,
           p.taarich_leda,
           v.seq_prisha,
           b.hp_zakaut
      into v_prisha_date,
           v_marriage_date,
           v_divorce_date,
           v_shiur_haavara,
           v_code_seif_prisha,
           v_code_group_prisha,
           v_birth_date,
           v_seq_prisha,
           v_date_start_zakaut
      from v_bakasha_last_status v
      left join bakasha_regila b
        on b.seq_bakasha = v.seq_bakasha
      left join poresh p
        on p.porshim_seq = v.seq_porshim
      left join bney_mishpacha bm
        on bm.seq_porshim = v.seq_porshim
       and bm.code_kirva = 10
       and bm.taarich_preida is not null
      left join code_seif_prisha sp
        on v.code_seif_prisha = sp.code_seif_prisha
     where v.seq_bakasha = p_seq_bakasha;
  
    select min(t.taarich_me)
      into v_start_work_date
      from tkufot_avoda_mechushv t
      left join code_sug_zchuyot_mechushavim t1
        on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
     where t.seq_bakasha = p_seq_bakasha
       and t.code_sugey_tkufot = 3
       and t1.haim_nirkash = 1;
  
    begin
      select max(v.seq_bakasha)
        into v_seq_bakasha_zakaut
        from v_bakasha_last_status v
       where v.seq_prisha = v_seq_prisha
         and v.code_merge_bakasha = 1
         and v.code_action <> 17;
    
    exception
      when no_data_found then
        v_seq_bakasha_zakaut := null;
    end;
  
    calc_max_shiur_haavara(p_seq_bakasha,
                           v_marriage_date,
                           v_divorce_date,
                           v_start_work_date,
                           v_prisha_date,
                           v_shiur_haavara_calc,
                           v_date_start_zakaut,
                           v_tkufa_meshutefet,
                           v_code_seif_prisha,
                           v_code_group_prisha,
                           v_birth_date,
                           v_seq_bakasha_zakaut);
  
    if v_shiur_haavara_calc < v_shiur_haavara then
      v_code_e_zakaut     := 7;
      v_date_start_zakaut := null;
    end if;
    merge into netuney_tik_mechushavim t
    using dual
    on (seq_bakasha = p_seq_bakasha and code_department = 2)
    when matched then
      update
         set t.hp_sheur_havara_max     = v_shiur_haavara_calc,
             t.code_e_zakaut           = v_code_e_zakaut,
             t.hp_date_start_zakaut    = v_date_start_zakaut,
             t.date_update             = sysdate,
             t.hp_tkufa_mshutefet_calc = v_tkufa_meshutefet
    when not matched then
      insert
        (seq_netuney_tik_mechushavim,
         seq_bakasha,
         code_department,
         hp_sheur_havara_max,
         code_e_zakaut,
         hp_date_start_zakaut,
         date_update,
         hp_tkufa_mshutefet_calc)
      values
        (netuney_tik_mechushavim_seq.nextval,
         p_seq_bakasha,
         2,
         v_shiur_haavara_calc,
         v_code_e_zakaut,
         v_date_start_zakaut,
         sysdate,
         v_tkufa_meshutefet); --log errors into err_netuney_tik_mechushavim REJECT LIMIT UNLIMITED
    commit;
  
    if v_prisha_date is not null then
      /* select v."SEQ_BAKASHA_ZAKAUT"
      into v_seq_bakasha_zakaut
      from table(fn_obj_prisha_last_zakaut_arr(pk_select_function.fn_prisha_poresh_header(v_seq_prisha))) v;*/
      begin
        select max(v.seq_bakasha)
          into v_seq_bakasha_zakaut
          from v_bakasha_last_status v
         where v.seq_prisha = v_seq_prisha
           and v.code_merge_bakasha = 1
           and v.code_action <> 17;
      
      exception
        when no_data_found then
          return;
      end;
    
      if v_seq_bakasha_zakaut is not null then
        select t.code_group_prisha
          into v_zakaut_code_group_prisha
          from netuney_tik_mechushavim t
         where t.seq_bakasha = v_seq_bakasha_zakaut
           and t.code_department = 2
           and t.mispar_misra = 0;
      
        update bakasha_regila b
           set b.hp_status_prisha = v_zakaut_code_group_prisha
         where b.seq_bakasha = p_seq_bakasha;
      end if;
    end if;
  
    commit;
  exception
    when others then
      update netuney_tik_mechushavim n
         set n.code_e_zakaut = 999, n.date_update = sysdate
       where n.seq_bakasha = p_seq_bakasha
         and n.code_department = 2;
      commit;
  end;
  ---------------------------------------------
  function get_tkufa_mezaka_all(p_seq_bakasha        in number,
                                p_end_period         date,
                                p_seq_bakasha_zakaut number,
                                p_start_period       date default null)
    return number is
    v_peroid                 number;
    v_peroid_keva            number;
    v_first_peroid_from_date date;
    v_hagdala                number;
  begin
  
    select min(t.taarich_me)
      into v_first_peroid_from_date
      from tkufot_avoda_mechushv t
      left join code_sug_zchuyot_mechushavim t1
        on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
     where t.seq_bakasha = p_seq_bakasha
       and t1.haim_nirkash = 1;
  
    with a as
     (select greatest(months_between(least(t.taarich_ad, p_end_period) + 1,
                                     greatest(t.taarich_me,
                                              nvl(p_start_period,
                                                  v_first_peroid_from_date))) -
                      nvl(t.except_from_tkufa, 0),
                      0) peroid
        from tkufot_avoda_mechushv t
        left join code_sug_zchuyot_mechushavim t1
          on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
       where t.seq_bakasha = p_seq_bakasha
         and t1.haim_nirkash = 1
         and (t.achuz_chelkyut >= 0.333 or
             t.taarich_ad < to_date('01/01/1967', 'dd/mm/yyyy'))
         and (t.code_sugey_tkufot <> 5 and
             (p_start_period is null or p_start_period <= t.taarich_ad)))
    select sum(peroid) into v_peroid from a;
    with b as
     (select greatest(months_between(least(t.taarich_ad, p_end_period) + 1,
                                     greatest(t.taarich_me,
                                              nvl(p_start_period,
                                                  v_first_peroid_from_date))) -
                      nvl(t.except_from_tkufa, 0),
                      0) peroid
        from tkufot_avoda_mechushv t
        left join code_sug_zchuyot_mechushavim t1
          on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
       where t.seq_bakasha = p_seq_bakasha
         and t1.haim_nirkash = 1
         and (t.achuz_chelkyut >= 0.333 or
             t.taarich_ad < to_date('01/01/1967', 'dd/mm/yyyy'))
         and (t.code_sugey_tkufot = 5 and
             v_first_peroid_from_date < to_date('01/01/2001', 'dd/mm/yyyy'))
         and (p_start_period is null or p_start_period <= t.taarich_ad))
    select sum(peroid) into v_peroid_keva from b;
    if p_seq_bakasha_zakaut is not null then
      select sum(t.achuz_meushar)
        into v_hagdala
        from hagdala_nimuk t
       where t.seq_bakasha = p_seq_bakasha_zakaut
         and t.code_hagdala_status_nimuk = 3;
    end if;
    if v_peroid_keva is not null then
      return least(v_peroid, 420) + nvl(v_peroid_keva, 0) + round(nvl(v_hagdala,
                                                                      0) * 6);
    else
      return v_peroid + round(nvl(v_hagdala, 0) * 6);
    end if;
  end;
  ---------------------------------------------
  function get_tkufa_mezaka(p_seq_bakasha        in number,
                            p_end_period         date,
                            p_start_period       date default null,
                            p_seq_bakasha_zakaut number) return number is
    v_peroid                 number;
    v_first_peroid_from_date date;
    v_hagdala                number;
  begin
  
    select min(t.taarich_me)
      into v_first_peroid_from_date
      from tkufot_avoda_mechushv t
      left join code_sug_zchuyot_mechushavim t1
        on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
     where t.seq_bakasha = p_seq_bakasha
       and t1.haim_nirkash = 1;
  
    with a as
     (select greatest(months_between(least(t.taarich_ad, p_end_period) + 1,
                                     greatest(t.taarich_me,
                                              nvl(p_start_period,
                                                  v_first_peroid_from_date))) -
                      nvl(t.except_from_tkufa, 0),
                      0) peroid
        from tkufot_avoda_mechushv t
        left join code_sug_zchuyot_mechushavim t1
          on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
       where t.seq_bakasha = p_seq_bakasha
         and t1.haim_nirkash = 1
         and (t.achuz_chelkyut >= 0.333 or
             t.taarich_ad < to_date('01/01/1967', 'dd/mm/yyyy'))
         and (t.code_sugey_tkufot <> 5 or
             v_first_peroid_from_date < to_date('01/01/2001', 'dd/mm/yyyy'))
         and (p_start_period is null or p_start_period <= t.taarich_ad))
    select sum(peroid) into v_peroid from a;
  
    if p_seq_bakasha_zakaut is not null then
      select sum(t.achuz_meushar)
        into v_hagdala
        from hagdala_nimuk t
       where t.seq_bakasha = p_seq_bakasha_zakaut
         and t.code_hagdala_status_nimuk = 3;
    end if;
  
    return v_peroid + round(nvl(v_hagdala, 0) * 6);
  end;
  ---------------------------------------------
  procedure calc_max_shiur_haavara(p_seq_bakasha        number,
                                   p_marriage_date      date,
                                   p_divorce_date       date,
                                   p_start_work_date    date,
                                   p_prisha_date        date,
                                   p_shiur_haavara_calc in out number,
                                   p_date_start_zakaut  in out date,
                                   p_tkufa_meshutefet   out number,
                                   p_code_seif_prisha   number,
                                   p_code_group_prisha  number,
                                   p_birth_date         date,
                                   v_seq_bakasha_zakaut number) is
    v_shiur_meshutaf             number;
    v_tkufa_mezaka_up_to_divorce number;
    v_tkufa_mezaka_meshutefet    number;
  begin
    v_tkufa_mezaka_meshutefet := nvl(get_tkufa_mezaka(p_seq_bakasha,
                                                      p_divorce_date,
                                                      p_marriage_date,
                                                      v_seq_bakasha_zakaut),
                                     0);
  
    v_tkufa_mezaka_up_to_divorce := get_tkufa_mezaka_all(p_seq_bakasha,
                                                         p_divorce_date,
                                                         v_seq_bakasha_zakaut);
  
    v_shiur_meshutaf := v_tkufa_mezaka_meshutefet /
                        v_tkufa_mezaka_up_to_divorce;
  
    p_tkufa_meshutefet := round(v_tkufa_mezaka_meshutefet / 12, 2);
  
    p_shiur_haavara_calc := round(v_shiur_meshutaf / 2 * 100, 2);
    if (p_code_seif_prisha in (215, 315) or p_code_group_prisha = 3) then
      p_date_start_zakaut := greatest(last_day(add_months(p_birth_date,
                                                          12 * 67)) + 1,
                                      last_day(p_divorce_date) + 1);
    
    else
      --calc date_start_zakaut only for future 
      if p_date_start_zakaut is null then
        if p_prisha_date > sysdate then
          p_date_start_zakaut := greatest(last_day(p_prisha_date) + 1,
                                          last_day(p_divorce_date) + 1);
        
          /*if (p_code_seif_prisha in (215, 315) or p_code_group_prisha = 3) then
            p_date_start_zakaut := greatest(last_day(add_months(p_birth_date,
                                                                12 * 67)) + 1,
                                            last_day(p_divorce_date) + 1);
          
          end if;*/
        else
          p_date_start_zakaut := last_day(sysdate) + 1;
        end if;
      end if;
    end if;
  
  end;
  -------------------------------------------
  procedure set_defuat_value_retro(p_pniya_date   date,
                                   p_confirm_date date,
                                   p_divorce_date date,
                                   p_prisha_date  date,
                                   p_seq_bakasha  number) is
  
  begin
    --until pniya
    insert_value_retro_row(greatest(p_divorce_date, p_prisha_date),
                           p_pniya_date - 1,
                           1,
                           p_seq_bakasha);
    --since pniya
    insert_value_retro_row(p_pniya_date,
                           p_confirm_date + 45,
                           2,
                           p_seq_bakasha);
  
  end;

  -------------------------------------------
  procedure insert_value_retro_row(p_from_date   date,
                                   p_to_date     date,
                                   p_retro_type  number,
                                   p_seq_bakasha number) is
  
  begin
  
    merge into retro t
    using dual
    on (seq_bakasha = p_seq_bakasha and code_sug_retro = p_retro_type)
    when matched then
      update set t.from_date = p_from_date, t.to_date = p_to_date
    when not matched then
      insert
        (t.seq_retro,
         t.seq_bakasha,
         t.code_sug_retro,
         t.from_date,
         t.to_date)
      values
        (retro_seq.nextval,
         p_seq_bakasha,
         p_retro_type,
         p_from_date,
         p_to_date) --log errors into err_netuney_tik_mechushavim REJECT LIMIT UNLIMITED
      ;
    commit;
  
  end;
end;
/

create or replace package body prm_system_copy.pk_hisachon_pensyoni_1 is

  --------------------------------------------
  procedure main(p_seq_bakasha number) is
    v_marriage_date            date;
    v_divorce_date             date;
    v_start_work_date          date;
    v_prisha_date              date;
    v_shiur_haavara            number;
    v_shiur_haavara_calc       number;
    v_code_e_zakaut            number;
    v_date_start_zakaut        date;
    v_tkufa_meshutefet         number;
    v_code_seif_prisha         number;
    v_code_group_prisha        number;
    v_birth_date               date;
    v_seq_prisha               number;
    v_seq_bakasha_zakaut       number;
    v_zakaut_code_group_prisha number;
  begin
    select v.taarich_prisha,
           bm.taarich_nisuin,
           bm.taarich_preida,
           b.hp_sheur_havara,
           v.code_seif_prisha,
           sp.code_group_prisha,
           p.taarich_leda,
           v.seq_prisha,
           b.hp_zakaut
      into v_prisha_date,
           v_marriage_date,
           v_divorce_date,
           v_shiur_haavara,
           v_code_seif_prisha,
           v_code_group_prisha,
           v_birth_date,
           v_seq_prisha,
           v_date_start_zakaut
      from v_bakasha_last_status v
      left join bakasha_regila b
        on b.seq_bakasha = v.seq_bakasha
      left join poresh p
        on p.porshim_seq = v.seq_porshim
      left join bney_mishpacha bm
        on bm.seq_porshim = v.seq_porshim
       and bm.code_kirva = 10
       and bm.taarich_preida is not null
      left join code_seif_prisha sp
        on v.code_seif_prisha = sp.code_seif_prisha
     where v.seq_bakasha = p_seq_bakasha;
  
    select min(t.taarich_me)
      into v_start_work_date
      from tkufot_avoda_mechushv t
      left join code_sug_zchuyot_mechushavim t1
        on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
     where t.seq_bakasha = p_seq_bakasha
       and t.code_sugey_tkufot = 3
       and t1.haim_nirkash = 1;
  
    calc_max_shiur_haavara(p_seq_bakasha,
                           v_marriage_date,
                           v_divorce_date,
                           v_start_work_date,
                           v_prisha_date,
                           v_shiur_haavara_calc,
                           v_date_start_zakaut,
                           v_tkufa_meshutefet,
                           v_code_seif_prisha,
                           v_code_group_prisha,
                           v_birth_date);
  
    if v_shiur_haavara_calc < v_shiur_haavara then
      v_code_e_zakaut     := 7;
      v_date_start_zakaut := null;
    end if;
    merge into netuney_tik_mechushavim t
    using dual
    on (seq_bakasha = p_seq_bakasha and code_department = 2)
    when matched then
      update
         set t.hp_sheur_havara_max     = v_shiur_haavara_calc,
             t.code_e_zakaut           = v_code_e_zakaut,
             t.hp_date_start_zakaut    = v_date_start_zakaut,
             t.date_update             = sysdate,
             t.hp_tkufa_mshutefet_calc = v_tkufa_meshutefet
    when not matched then
      insert
        (seq_netuney_tik_mechushavim,
         seq_bakasha,
         code_department,
         hp_sheur_havara_max,
         code_e_zakaut,
         hp_date_start_zakaut,
         date_update,
         hp_tkufa_mshutefet_calc)
      values
        (netuney_tik_mechushavim_seq.nextval,
         p_seq_bakasha,
         2,
         v_shiur_haavara_calc,
         v_code_e_zakaut,
         v_date_start_zakaut,
         sysdate,
         v_tkufa_meshutefet); --log errors into err_netuney_tik_mechushavim REJECT LIMIT UNLIMITED
    commit;
  
    if v_prisha_date is not null then
      /* select v."SEQ_BAKASHA_ZAKAUT"
      into v_seq_bakasha_zakaut
      from table(fn_obj_prisha_last_zakaut_arr(pk_select_function.fn_prisha_poresh_header(v_seq_prisha))) v;*/
      begin
        select max(v.seq_bakasha)
          into v_seq_bakasha_zakaut
          from v_bakasha_last_status v
         where v.seq_prisha = v_seq_prisha
           and v.code_merge_bakasha = 1
           and v.code_action <> 17;
      
      exception
        when no_data_found then
          return;
      end;
    
      if v_seq_bakasha_zakaut is not null then
        select t.code_group_prisha
          into v_zakaut_code_group_prisha
          from netuney_tik_mechushavim t
         where t.seq_bakasha = v_seq_bakasha_zakaut
           and t.code_department = 2
           and t.mispar_misra = 0;
      
        update bakasha_regila b
           set b.hp_status_prisha = v_zakaut_code_group_prisha
         where b.seq_bakasha = p_seq_bakasha;
      end if;
    end if;
  
    commit;
  exception
    when others then
      update netuney_tik_mechushavim n
         set n.code_e_zakaut = 999, n.date_update = sysdate
       where n.seq_bakasha = p_seq_bakasha
         and n.code_department = 2;
      commit;
  end;
  ---------------------------------------------
  function get_tkufa_mezaka(p_seq_bakasha  in number,
                            p_end_period   date,
                            p_start_period date default null) return number is
    v_peroid                 number;
    v_first_peroid_from_date date;
  begin
  
    select min(t.taarich_me)
      into v_first_peroid_from_date
      from tkufot_avoda_mechushv t
      left join code_sug_zchuyot_mechushavim t1
        on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
     where t.seq_bakasha = p_seq_bakasha
       and t1.haim_nirkash = 1;
  
    with a as
     (select months_between(least(t.taarich_ad, p_end_period) + 1,
                            greatest(t.taarich_me,
                                     nvl(p_start_period,
                                         v_first_peroid_from_date))) -
             nvl(t.except_from_tkufa, 0) peroid
        from tkufot_avoda_mechushv t
        left join code_sug_zchuyot_mechushavim t1
          on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
       where t.seq_bakasha = p_seq_bakasha
         and t1.haim_nirkash = 1
         and (t.achuz_chelkyut >= 0.333 or
             t.taarich_ad < to_date('01/01/1967', 'dd/mm/yyyy'))
         and (t.code_sugey_tkufot <> 5 or
             v_first_peroid_from_date < to_date('01/01/2001', 'dd/mm/yyyy'))
         and (p_start_period is null or p_start_period <= t.taarich_ad))
    select sum(peroid) into v_peroid from a;
  
    return v_peroid;
  end;
  ---------------------------------------------
  procedure calc_max_shiur_haavara(p_seq_bakasha        number,
                                   p_marriage_date      date,
                                   p_divorce_date       date,
                                   p_start_work_date    date,
                                   p_prisha_date        date,
                                   p_shiur_haavara_calc in out number,
                                   p_date_start_zakaut  in out date,
                                   p_tkufa_meshutefet   out number,
                                   p_code_seif_prisha   number,
                                   p_code_group_prisha  number,
                                   p_birth_date         date) is
    v_shiur_meshutaf             number;
    v_tkufa_mezaka_up_to_divorce number;
    v_tkufa_mezaka_meshutefet    number;
  begin
    v_tkufa_mezaka_meshutefet := get_tkufa_mezaka(p_seq_bakasha,
                                                  p_divorce_date,
                                                  p_marriage_date);
  
    v_tkufa_mezaka_up_to_divorce := get_tkufa_mezaka(p_seq_bakasha,
                                                     p_divorce_date);
  
    v_shiur_meshutaf := v_tkufa_mezaka_meshutefet /
                        v_tkufa_mezaka_up_to_divorce;
  
    p_tkufa_meshutefet := round(v_tkufa_mezaka_meshutefet / 12, 2);
  
    p_shiur_haavara_calc := round(v_shiur_meshutaf / 2 * 100, 2);
    --calc date_start_zakaut only for future 
    if p_date_start_zakaut is null then
      if p_prisha_date > sysdate then
        p_date_start_zakaut := greatest(last_day(p_prisha_date) + 1,
                                        last_day(p_divorce_date) + 1);
      
        if (p_code_seif_prisha in (215, 315) or p_code_group_prisha = 3) then
          p_date_start_zakaut := greatest(last_day(add_months(p_birth_date,
                                                              12 * 67)) + 1,
                                          last_day(p_divorce_date) + 1);
        
        end if;
      else
        p_date_start_zakaut := last_day(sysdate) + 1;
      end if;
    end if;
  
  end;
  -------------------------------------------
  procedure set_defuat_value_retro(p_pniya_date   date,
                                   p_confirm_date date,
                                   p_divorce_date date,
                                   p_prisha_date  date,
                                   p_seq_bakasha  number) is
  
  begin
    --until pniya
    insert_value_retro_row(greatest(p_divorce_date, p_prisha_date),
                           p_pniya_date - 1,
                           1,
                           p_seq_bakasha);
    --since pniya
    insert_value_retro_row(p_pniya_date,
                           p_confirm_date + 45,
                           2,
                           p_seq_bakasha);
  
  end;

  -------------------------------------------
  procedure insert_value_retro_row(p_from_date   date,
                                   p_to_date     date,
                                   p_retro_type  number,
                                   p_seq_bakasha number) is
  
  begin
  
    merge into retro t
    using dual
    on (seq_bakasha = p_seq_bakasha and code_sug_retro = p_retro_type)
    when matched then
      update set t.from_date = p_from_date, t.to_date = p_to_date
    when not matched then
      insert
        (t.seq_retro,
         t.seq_bakasha,
         t.code_sug_retro,
         t.from_date,
         t.to_date)
      values
        (retro_seq.nextval,
         p_seq_bakasha,
         p_retro_type,
         p_from_date,
         p_to_date) --log errors into err_netuney_tik_mechushavim REJECT LIMIT UNLIMITED
      ;
    commit;
  
  end;
end;
/

create or replace package body prm_system_copy.pk_hp_convert_data_mgl_2_mpm is
  -----------------------------------------------------------
  procedure update_bakasha_regila(p_err_bakasha_regila in out err_bakasha_regila%rowtype,
                                  p_code_seif_prisha   number,
                                  p_seq_bakasha        number) is
  begin
    p_err_bakasha_regila.seq_bakasha := p_seq_bakasha;
  
    if p_err_bakasha_regila.code_seif_prisha is null then
      --update seif prisha
      p_err_bakasha_regila.code_seif_prisha := p_code_seif_prisha;
    
    elsif p_code_seif_prisha = 118 and
          p_err_bakasha_regila.taarich_prisha < trunc(sysdate) then
      --update hp status prisha
      select s.code_group_prisha
        into p_err_bakasha_regila.hp_status_prisha
        from code_seif_prisha s
       where s.code_seif_prisha = p_err_bakasha_regila.code_seif_prisha;
    end if;
  
    delete from bakasha_regila b where b.seq_bakasha = p_seq_bakasha;
  
    pk_load_mimshak.insert_bakasha_regila_table(p_err_bakasha_regila);
  
  end update_bakasha_regila;
  -----------------------------------------------------------
  function get_mpm_bakasha_regila(p_seq_bakasha      number,
                                  p_seq_bakasha_old  number,
                                  p_code_seif_prisha number)
    return err_bakasha_regila%rowtype is
    v_err_bakasha_regila err_bakasha_regila%rowtype;
  begin
    if p_code_seif_prisha = 118 then
      for r in (select *
                  from bakasha_regila b
                 where b.seq_bakasha = p_seq_bakasha_old) loop
        v_err_bakasha_regila.code_seif_prisha := r.code_seif_prisha;
        v_err_bakasha_regila.taarich_prisha   := r.taarich_prisha;
        v_err_bakasha_regila.seq_bakasha      := p_seq_bakasha;
      end loop;
    elsif p_code_seif_prisha = 128 then
      v_err_bakasha_regila                        := pk_load_mimshak.get_bakasha_regila_by_previous(p_seq_bakasha_old);
      v_err_bakasha_regila.taarich_chatimat_tofes := null;
    end if;
    return v_err_bakasha_regila;
  end;
  -----------------------------------------------------------
  procedure insert_mpm_tkufot_mehushv(p_seq_bakasha     number,
                                      p_seq_bakasha_old number) is
  begin
    insert into tkufot_avoda_mechushv
      select t.taarich_me,
             t.taarich_ad,
             t.achuz_chelkyut,
             t.praklit,
             t.sach_chodeshim,
             t.haim_kana_zchuyot,
             t.code_sugey_tkufot,
             t.code_sugey_haasaka,
             t.code_sugey_zchuyot,
             tkufot_avoda_mechushav_seq.nextval,
             t.ezor_ovdim_be_tkufa,
             t.shanim,
             t.chodashim,
             t.yamim,
             t.seq_tkufot_avoda_golmi,
             t.seq_tkufot_michutz_lasharut,
             t.seq_tkufot_sherut_tsvaii,
             p_seq_bakasha,
             t.except_from_tkufa,
             t.achuz_mugdal,
             t.code_achuz_mugdal,
             t.kd_takanon,
             t.code_takanon_magal,
             t.is_took_money_m_keren
        from tkufot_avoda_mechushv t
       where t.seq_bakasha = p_seq_bakasha_old log errors into
       err_tkufot_avoda_mechushv reject limit unlimited;
  end;
  ---------------------------------------------------------
  function Get_prev_seq_bakasha(p_seq_bakasha number, p_id number)
    return number is
    v_seq_bakasha_old number;
  begin
    --Get previous seq bakasha with date zakaut
    select max(v.SEQ_BAKASHA)
      into v_seq_bakasha_old
    
      from v_bakasha v
      left join code_sug_bakasha t
        on v.code_sug_bakasha = t.code_sug_bakasha
    
     where v.MISPAR_ZEHUT = p_id
       and v.SEQ_BAKASHA < p_seq_bakasha
       and t.code_merge_bakasha = 1;
  
    return v_seq_bakasha_old;
  end;

  ---------------------------------------------------------
  procedure main(p_seq_bakasha number, p_code_seif_prisha number) is
  
    v_err_bakasha_regila err_bakasha_regila%rowtype;
    v_id                 number;
    v_seq_bakasha_prev   number;
  begin
    delete from err_tkufot_avoda_mechushv;
  
    delete from tkufot_avoda_mechushv t
     where t.seq_bakasha = p_seq_bakasha;
  
    --Get id
    select v1.MISPAR_ZEHUT
      into v_id
      from v_bakasha v1
     where v1.SEQ_BAKASHA = p_seq_bakasha;
  
    v_seq_bakasha_prev := Get_prev_seq_bakasha(p_seq_bakasha, v_id);
  
    if v_seq_bakasha_prev is not null then
      --mpm  
      v_err_bakasha_regila := get_mpm_bakasha_regila(p_seq_bakasha,
                                                     v_seq_bakasha_prev,
                                                     p_code_seif_prisha);
      --update bakasha regila
      update_bakasha_regila(v_err_bakasha_regila,
                            p_code_seif_prisha,
                            p_seq_bakasha);
      --insert tkufot
      insert_mpm_tkufot_mehushv(p_seq_bakasha, v_seq_bakasha_prev);
    
      commit;
    end if;
  end;
  ---------------------------------------------------------
end;
/

create or replace package body prm_system_copy.pk_interior is

  ----------------------------------------
  chr_10      constant varchar2(2) := chr(10);
  date_format constant varchar2(8) := 'yyyymmdd';
  ------------------------------------
  function get_header_file_name return varchar2 is
  begin
    return 'l000058_0058is_07_02_' || to_char(sysdate, 'yymmdd') || '.config';
  end;
  ------------------------------------
  function get_content_file_name return varchar2 is
  begin
    return 'eim_l000058_0058is_07_02_' || to_char(sysdate, 'yymmdd') || '_i.dat';
  end;
  ------------------------------------
  function create_header_output return clob is
  begin
    return '000058' || '031040' || lpad(1, 200, 1) || '00000001' || 1 || to_char(sysdate,
                                                                                 'yyyymmdd') || rpad('0058is_07',
                                                                                                     20,
                                                                                                     ' ') || rpad('0058is_07_02',
                                                                                                                  20,
                                                                                                                  ' ') || rpad(' ',
                                                                                                                               50,
                                                                                                                               ' ');
  end;
  ------------------------------------------------------
  function get_last_address(p_seq_poresh         number,
                            p_seq_bney_mishpacha number) return varchar2 is
    v_last_zip        number;
    v_length_last_zip number;
    v_last_city       number;
  begin
    begin
      if p_seq_bney_mishpacha is not null then
        select a.code_city, a.mikud, length(a.mikud)
          into v_last_city, v_last_zip, v_length_last_zip
          from address a
         where a.seq_bney_mishpacha = p_seq_bney_mishpacha
           and a.code_address = 1
         order by a.seq_address desc fetch first 1 rows only;
      
      elsif p_seq_poresh is not null then
        select a.code_city, a.mikud, length(a.mikud)
          into v_last_city, v_last_zip, v_length_last_zip
          from address a
         where a.seq_poresh = p_seq_poresh
           and a.code_address = 1
         order by a.seq_address desc fetch first 1 rows only;
      end if;
    
    exception
      when others then
        v_last_zip  := null;
        v_last_city := null;
    end;
  
    return pk_create_mimshak_out.substr_lpad_nvl_zero(v_last_city,
                                                      
                                                      4) || rpad(' ',
                                                                 50,
                                                                 ' ') || lpad(0,
                                                                              4,
                                                                              0) || rpad(' ',
                                                                                         50,
                                                                                         ' ') || lpad(0,
                                                                                                      4,
                                                                                                      0) || rpad(' ',
                                                                                                                 1,
                                                                                                                 ' ') || lpad(0,
                                                                                                                              2,
                                                                                                                              0) || lpad(0,
                                                                                                                                         4,
                                                                                                                                         0) || pk_create_mimshak_out.substr_lpad_nvl_zero(case when
                                                                                                                                                                                          v_length_last_zip = 5 then
                                                                                                                                                                                          v_last_zip else null end,
                                                                                                                                                                                          5) || pk_create_mimshak_out.substr_lpad_nvl_zero(case when
                                                                                                                                                                                                                                           v_length_last_zip = 7 then
                                                                                                                                                                                                                                           v_last_zip else null end,
                                                                                                                                                                                                                                           7);
  
  end;
  ------------------------------------------------------
  function create_content_output(p_is_all_persons        number,
                                 p_is_payment_in_advance number,
                                 p_count_rowes           in out number)
    return clob is
    result clob;
  
  begin
    --truncate 'ld_interior_out' table
    execute immediate 'truncate table ld_interior_out';
  
    for r in (with a as
                 (select p.porshim_seq,
                        null as seq_bney_mishpacha,
                        pk_create_mimshak_out.substr_lpad_nvl_zero(p.mispar_zehut,
                                                                   9) id_number,
                        pk_create_mimshak_out.substr_rpad_nvl_pad_char(p.shem_mishpacha,
                                                                       20) last_name,
                        pk_create_mimshak_out.substr_rpad_nvl_pad_char(p.shem_prati,
                                                                       20) first_name,
                        to_char(p.taarich_leda, date_format) birth_date,
                        p.taarich_ptira,
                        p1.is_payment_in_advance
                   from poresh p
                   left join prisha p1
                     on p.porshim_seq = p1.seq_poresh
                 --sug_zihuy
                  where nvl(p.sug_zihuy, 0) not in (5, 6)),
                b as
                 (select null,
                        b.seq_bney_mishpacha,
                        pk_create_mimshak_out.substr_lpad_nvl_zero(b.mispar_zehut_ben_mishpacha,
                                                                   9) id_number,
                        pk_create_mimshak_out.substr_rpad_nvl_pad_char(b.shem_mishpacha,
                                                                       20) last_name,
                        pk_create_mimshak_out.substr_rpad_nvl_pad_char(b.shem_prati,
                                                                       20) first_name,
                        to_char(b.taarich_leda, date_format) birth_date,
                        null as taarich_ptira,
                        p1.is_payment_in_advance
                   from bney_mishpacha b
                   left join poresh p
                     on b.seq_porshim = p.porshim_seq
                   left join prisha p1
                     on p.porshim_seq = p1.seq_poresh
                  where /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                



                 
                 
                 
                                                                                                      
                                                                                                                                                                                                                                                                                                                               We send the id also if it's exist in porshim
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                



                 
                 
                 
                                                                                                      
                                                                                                                                                                                                                                                                                                                               because it is not always updated in the two tables
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                



                 
                 
                 
                                                                                                      
                                                                                                                                                                                                                                                                                                                               p.mispar_zehut is null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                



                 
                 
                 
                                                                                                      
                                                                                                                                                                                                                                                                                                                                                  and*/
                  b.taarich_ptira is null
              and b.code_kirva in (1, 2, 14, 10, 24)
              and (b.code_kirva <> 2 or (add_months(b.taarich_leda, 252) >
                  sysdate or b.is_taluy = 1))
                 --sug_zihuy
              and nvl(b.sug_zihuy, 0) not in (5, 6)),
                c as
                 (select v.mispar_zehut, v.seq_bakasha, v.code_action
                   from v_bakasha_last_status v
                  where v.code_action in (86, 26))
                select *
                  from (select a.*, c.seq_bakasha, c.code_action
                          from a
                          left join c
                            on a.id_number = c.mispar_zehut
                         where c.mispar_zehut is not null
                            or (p_is_all_persons = 1 and
                               a.taarich_ptira is null)
                            or (p_is_payment_in_advance = 1 and
                               a.is_payment_in_advance = 1)
                        union
                        select b.*, null, null
                          from b
                         where (p_is_all_persons = 1)
                            or (p_is_payment_in_advance = 1 and
                               b.is_payment_in_advance = 1))
                -- week day
                 where to_char(sysdate, 'd') not in (6, 7)) loop
    
      --Insert into ld_interior_out
      insert into ld_interior_out values (r.id_number);
    
      if result is not null then
        result := result || chr_10;
      end if;
    
      result := result || r.id_number || r.last_name || r.first_name ||
                rpad(' ', 20, ' ') || rpad(' ', 20, ' ') || r.birth_date ||
                get_last_address(r.porshim_seq, r.seq_bney_mishpacha) ||
                lpad(0, 9, 0) || rpad(' ', 10, ' ');
    
      if r.code_action = 86 then
        pk_prm_utils.insert_actions_for_bakasha(r.seq_bakasha, 0);
      elsif r.code_action = 26 then
        --when the bakasha in status 'sended to interior' and it's stopped.
        pk_prm_utils.insert_action_log_row(26,
                                           sysdate,
                                           0,
                                           null,
                                           'לא התקבל משוב ולכן נשלח שוב לאימות',
                                           null,
                                           null,
                                           null,
                                           r.seq_bakasha,
                                           null);
      end if;
    
      commit;
    end loop;
  
    --save count rows
    select count(distinct id) into p_count_rowes from ld_interior_out;
  
    return trim(result);
  end;
  --------------------------------------------------
  function get_mpm_code_mazav_mishpachti(v_code_mazav_mishpachti number)
    return number is
  begin
    return case when v_code_mazav_mishpachti = 10 then 0 when v_code_mazav_mishpachti = 20 then 1 when v_code_mazav_mishpachti = 21 then 6 when v_code_mazav_mishpachti = 22 then 7 when v_code_mazav_mishpachti = 30 then 3 when v_code_mazav_mishpachti = 31 then 0 when v_code_mazav_mishpachti = 40 then 2 when v_code_mazav_mishpachti = 66 then 999 when v_code_mazav_mishpachti = 77 then 999 when v_code_mazav_mishpachti = 99 then 999 else null end;
  end;
  --------------------------------------------------
  function get_mpm_code_kirva(v_code_kirva number) return number is
  begin
    return case when v_code_kirva = 3 then 2 when v_code_kirva = 4 then 1 else null end;
  end;
  ------------------------------------
  procedure Insert_invalid_date(p_mispar_zehut in number,
                                p_taarich_leda in varchar2,
                                v_remark       in out varchar2) is
  begin
    v_remark := 'תאריך לידה שגוי התקבל בממשק משרד הפנים ' || v_remark;
  
    v_remark := v_remark || '(' || p_taarich_leda || ')';
    insert_action_letipuly(v_remark, p_mispar_zehut);
  
  end Insert_invalid_date;
  ------------------------------------
  procedure calc_date_birth(p_mispar_zehut               number,
                            p_taarich_leda               in out varchar2,
                            p_mpm_taarich_leda           date,
                            p_mispar_zehut_ben_mishpacha number default null)
  
   is
    pragma autonomous_transaction;
    v_remark              varchar2(1000) := '';
    v_low_year_date_birth number;
    v_up_year_date_birth  number;
    v_year                number;
  begin
    begin
      if p_mispar_zehut_ben_mishpacha is not null then
        v_remark := v_remark || ' לבן משפחה - ' ||
                    to_char(p_mispar_zehut_ben_mishpacha);
      end if;
      --Try to convert taarich_leda to date format
      p_taarich_leda := to_date(p_taarich_leda, date_format);
    
      v_remark := 'תאריך לידה במפמ ' || v_remark;
    
      if nvl(p_taarich_leda, to_date('01010001', 'ddmmyyyy')) <>
         nvl(p_mpm_taarich_leda, to_date('01010001', 'ddmmyyyy')) then
        v_remark := v_remark || ' (' ||
                    to_char(p_mpm_taarich_leda, 'dd/mm/yyyy') ||
                    ') שונה מתאריך לידה במשרד הפנים (' || p_taarich_leda || ')';
        insert_action_letipuly(v_remark, to_number(p_mispar_zehut));
      end if;
    exception
      when others then
      
        if to_number(substr(p_taarich_leda, 5)) <> 0 and
           to_number(substr(p_taarich_leda, 7)) = 0 then
          begin
            p_taarich_leda := to_date(substr(p_taarich_leda, 1, 6) || '01',
                                      date_format);
          exception
            when others then
              Insert_invalid_date(p_mispar_zehut, p_taarich_leda, v_remark);
          end;
        else
        
          --Get min date from date_birth table
          select extract(year from min(t.date_nisan))
            into v_low_year_date_birth
            from date_birth t;
          --Get max date from date_birth table
          select extract(year from max(t.date_nisan))
            into v_up_year_date_birth
            from date_birth t;
        
          v_year := to_number(substr(p_taarich_leda, 1, 4));
        
          --when the taarich_leda was get from interior only with year
          if (v_year between v_low_year_date_birth and v_up_year_date_birth) and
             to_number(substr(p_taarich_leda, 5)) = 0 then
            begin
              v_remark := 'תאריך לידה שגוי התקבל בממשק משרד הפנים ' ||
                          v_remark;
              v_remark := v_remark || '(' || p_taarich_leda || ')';
            
              select t.date_nisan
                into p_taarich_leda
                from date_birth t
               where extract(year from t.date_nisan) = v_year;
            
              v_remark := v_remark || ' ושונה ל ' || p_taarich_leda;
              insert_action_letipuly(v_remark, p_mispar_zehut);
            
            exception
              when others then
                Insert_invalid_date(p_mispar_zehut,
                                    p_taarich_leda,
                                    v_remark);
            end;
          
          else
          
            Insert_invalid_date(p_mispar_zehut, p_taarich_leda, v_remark);
          end if;
        end if;
    end;
    commit;
  end;
  ------------------------------------
  procedure check_poresh(err_poresh_row in out err_porshim%rowtype) is
    pragma autonomous_transaction;
    v_remark           varchar2(1000);
    v_mpm_taarich_leda date;
  begin
    begin
      err_poresh_row.taarich_ptira := to_date(err_poresh_row.taarich_ptira,
                                              date_format);
    exception
      when others then
        v_remark := 'תאריך פטירה שגוי התקבל בממשק משרד הפנים (' ||
                    err_poresh_row.taarich_ptira || ')';
        insert_action_letipuly(v_remark, err_poresh_row.mispar_zehut);
        pk_load_mimshak.add_row_to_err_porshim('poresh',
                                               err_poresh_row,
                                               sqlerrm,
                                               sqlcode,
                                               'taarich_ptira');
    end;
  
    begin
      select p.taarich_leda
        into v_mpm_taarich_leda
        from poresh p
       where p.mispar_zehut = err_poresh_row.mispar_zehut;
    exception
      when no_data_found then
        v_mpm_taarich_leda := null;
    end;
  
    calc_date_birth(err_poresh_row.mispar_zehut,
                    err_poresh_row.taarich_leda,
                    v_mpm_taarich_leda);
  
    commit;
  end;
  ------------------------------------------------
  procedure insert_action_letipuly(v_remark       varchar2,
                                   v_mispar_zehut number) is
    v_code_user    number;
    v_next_status  number;
    v_is_automatic number;
  begin
    for r in (select v.seq_bakasha,
                     v.code_sug_workflow,
                     v.code_action,
                     v.code_user_update,
                     pk_load_mimshak.Get_user_id_by_category(v.seq_ezor_ovdim) nashm_category
                from v_bakasha_last_status v
               where v.mispar_zehut = v_mispar_zehut
                 and (v.code_action = 86 or
                     (v.code_sug_workflow = 5 and
                     v.seq_bakasha not in
                     (select a.seq_bakasha
                          from action_log a
                         where a.code_action = 98)))) loop
    
      if r.code_sug_workflow in (5, 8) then
        --When there is kpm/participation_to
        v_code_user := r.code_user_update;
      else
        pk_prm_utils.Find_next_action(r.code_sug_workflow,
                                      r.code_action,
                                      v_next_status,
                                      v_is_automatic);
      
        v_code_user := pk_prm_utils.get_next_user_for_bakasha(v_next_status,
                                                              r.seq_bakasha);
      end if;
      pk_prm_utils.insert_action_log_row(2,
                                         sysdate,
                                         0,
                                         v_code_user,
                                         v_remark,
                                         null,
                                         null,
                                         null,
                                         r.seq_bakasha,
                                         null);
    end loop;
  end;
  ------------------------------------------------
  procedure load_address(p_id_number          number,
                         p_seq_poresh         number,
                         p_seq_bakasha        number,
                         p_seq_bney_mishpacha number) is
  begin
  
    for r in
    --Get interior data
     (select distinct get_only_if_value(l.city_code_o) city_code_o,
                      get_only_if_value(l.street_name_o) street_name_o,
                      get_only_if_value(l.house_number_o) house_number_o,
                      get_only_if_value(l.house_letter_o) house_letter_o,
                      get_only_if_value(l.entrance_number_o) entrance_number_o,
                      get_only_if_value(l.apartment_number_o) apartment_number_o,
                      get_only_if_value(l.zip_code_7_o) zip_code_7_o
      
        from ld_interior l
       where l.id_number = p_id_number
         and nvl(l.city_code_o, 0) <> 0) loop
    
      for r2 in
      --Get mpm data  
       (select a.code_city,
               a.mikud,
               a.street,
               a.house,
               a.apartment,
               a.entrance,
               a.house_letter
        
          from address a
         where ((p_seq_poresh is not null and a.seq_poresh = p_seq_poresh) or
               (p_seq_bney_mishpacha is not null and
               a.seq_bney_mishpacha = p_seq_bney_mishpacha))
              -- Type address: from interior
           and a.code_address = 1
        -- Get the last address in mpm
         order by a.seq_address desc fetch first 1 rows only) loop
      
        if nvl(r2.code_city, 0) = nvl(r.city_code_o, 0) and
           nvl(r2.mikud, 0) = nvl(r.zip_code_7_o, 0) and
           nvl(r2.street, 0) = nvl(r.street_name_o, 0) and
           nvl(r.house_number_o, 0) = nvl(r2.house, 0) and
           nvl(r2.apartment, 0) = nvl(r.apartment_number_o, 0) and
           nvl(r2.entrance, 0) = nvl(r.entrance_number_o, 0) and
           nvl(r2.house_letter, 0) = nvl(r.house_letter_o, 0) then
          --Don't insert same row to table
          return;
        end if;
      end loop;
    
      --insert new row to address table
      insert into address
        (code_address,
         code_city,
         mikud,
         date_update,
         code_user_update,
         seq_address,
         seq_poresh,
         seq_bney_mishpacha,
         street,
         house,
         apartment,
         entrance,
         house_letter,
         seq_bakasha,
         shem_meadken_acharon)
      values
        (1,
         r.city_code_o,
         r.zip_code_7_o,
         sysdate,
         0,
         address_seq.nextval,
         p_seq_poresh,
         p_seq_bney_mishpacha,
         r.street_name_o,
         r.house_number_o,
         r.apartment_number_o,
         r.entrance_number_o,
         r.house_letter_o,
         p_seq_bakasha,
         SYS_CONTEXT('USERENV','OS_USER'));
    
    end loop;
  
  end;
  ------------------------------------------------
  function convert_string_to_date(p_value varchar2) return date is
    v_string_day   varchar2(2) := substr(p_value, 7, 2);
    v_string_month varchar2(2) := substr(p_value, 5, 2);
    v_string_year  varchar2(4) := substr(p_value, 0, 4);
  
  begin
    if v_string_year <> 0 then
      return to_date(v_string_year || get_first_when_zero(v_string_month) ||
                     get_first_when_zero(v_string_day),
                     'yyyymmdd');
    else
      return null;
    end if;
  exception
    when others then
      return null;
  end;
  ------------------------------------------------
  function get_first_when_zero(p_value varchar2) return varchar2 is
  begin
    if to_number(p_value) = 0 then
      return '01';
    else
      return p_value;
    end if;
  exception
    when others then
      return null;
  end;

  ------------------------------------------------
  procedure load_mazav_mishpachti(p_id_number          number,
                                  p_seq_poresh         number,
                                  p_seq_bney_mishpacha number) is
  begin
  
    for r in
    --Get interior data
     (select distinct get_mpm_code_mazav_mishpachti(l.marital_status) marital_status,
                      convert_string_to_date(l.marital_date) marital_date
        from ld_interior l
       where l.id_number = p_id_number
         and l.marital_status <> 0) loop
    
      for r2 in
      --Get mpm data  
       (select a.code_mazav_mishpachti, a.date_mazav_mishpachti
          from mazav_mishpachti a
         where (p_seq_poresh is not null and a.seq_poresh = p_seq_poresh)
            or (p_seq_bney_mishpacha is not null and
               a.seq_bney_mishpacha = p_seq_bney_mishpacha)
        -- Get the last mazav_mishpachti in mpm
         order by nvl(a.date_mazav_mishpachti,
                      to_date('01011000', 'ddmmyyyy')) desc,
                  a.seq_mazav_mishpachti desc fetch first 1 rows only) loop
        if
        --When the ststus already updated in mpm
         r2.code_mazav_mishpachti = r.marital_status
        --When MPM updated more than INTERIOR, 
         or r2.date_mazav_mishpachti > r.marital_date then
          --Don't insert row to table
          return;
        end if;
      
      end loop;
    
      --insert new row to mazav_mishpachti table
      insert into mazav_mishpachti
        (seq_mazav_mishpachti,
         seq_poresh,
         seq_bney_mishpacha,
         code_mazav_mishpachti,
         date_mazav_mishpachti,
         date_update,
         code_user,
         shem_meadken_acharon)
      values
        (mazav_mishpachti_seq.nextval,
         p_seq_poresh,
         p_seq_bney_mishpacha,
         r.marital_status,
         r.marital_date,
         sysdate,
         0,
         SYS_CONTEXT('USERENV','OS_USER'));
    
    end loop;
  
  end;
