  procedure open_stop_bakasha(p_seq_prisha              number,
                              p_code_bakasha_detail     number,
                              p_date_stop               date,
                              p_seq_bney_mishpacha      number,
                              p_is_exist_bakasha_zakaut number,
                              p_code_source             number default 16) is
    v_seq_bakasha             number;
    v_is_exist_stop_bakasha   number;
    v_is_exist_bakasha_zakaut number;
  begin
  
    select count(*)
      into v_is_exist_stop_bakasha
      from bakasha b
      left join v_bakasha_last_status v
        on b.seq_bakasha = v.seq_bakasha
     where b.seq_prisha = p_seq_prisha
       and b.code_sug_bakasha = 19
       and b.code_bakasha_detail = p_code_bakasha_detail
       and nvl(b.seq_bney_mishpacha, 0) = nvl(p_seq_bney_mishpacha, 0)
       and v.code_action <> 17;
  
    if v_is_exist_stop_bakasha = 0 then
    
      v_seq_bakasha := bakasha_seq.nextval();
    
      insert into bakasha
        (seq_bakasha,
         seq_prisha,
         code_sug_bakasha,
         code_bakasha_detail,
         date_bakasha,
         code_source,
         date_update,
         from_date,
         seq_bney_mishpacha,
         shem_meadken_acharon)
      values
        (v_seq_bakasha,
         p_seq_prisha,
         19,
         p_code_bakasha_detail,
         sysdate,
         p_code_source,
         sysdate,
         trunc(add_months(p_date_stop, 1), 'MONTH'),
         p_seq_bney_mishpacha,
         SYS_CONTEXT('USERENV','OS_USER'));
    
      pk_zakaut_stop_payment.main(v_seq_bakasha);
    
      if p_is_exist_bakasha_zakaut = 0 then
        pk_prm_utils.insert_action_log_row(98,
                                           sysdate,
                                           0,
                                           null,
                                           'נפתחה בקשה לידיעה בלבד',
                                           null,
                                           null,
                                           null,
                                           v_seq_bakasha,
                                           null);
      
      elsif p_code_bakasha_detail in (6, 19) then
        pk_prm_utils.insert_action_log_row(134,
                                           sysdate,
                                           0,
                                           null,
                                           null,
                                           null,
                                           null,
                                           null,
                                           v_seq_bakasha,
                                           null);
      else
        pk_prm_utils.insert_actions_for_bakasha(v_seq_bakasha, 0);
      end if;
    
    end if;
  end;
