  ------------------------------------------------
  procedure load_bney_mishpacha(v_id                     number,
                                v_seq_poresh             number,
                                v_do_commit              in out boolean,
                                v_report_for_tik         in out clob,
                                v_report_for_tik_varchar in out varchar2,
                                v_count_success          in out number,
                                v_count_errors           in out number) is
    err_bney_mishpacha_row  err_bney_mishpacha%rowtype;
    v_21_years_acharei_leda date;
    v_mpm_taarich_leda      date;
    v_year_leda             number;
    v_month_leda            number;
    v_day_leda              number;
    v_seq_bney_mishpacha    number;
  begin
  
    for r in (select t.* from ld_interior t where t.id_number = v_id) loop
    
      if r.fm_id_number <> '000000000' and
         r.fm_relationship_type not in (11, 12) then
        err_bney_mishpacha_row.mispar_zehut_ben_mishpacha := r.fm_id_number;
        err_bney_mishpacha_row.shem_mishpacha             := r.fm_last_name;
        err_bney_mishpacha_row.shem_prati                 := r.fm_first_name;
        err_bney_mishpacha_row.taarich_leda               := r.fm_birth_date;
        err_bney_mishpacha_row.code_kirva                 := get_mpm_code_kirva(r.fm_relationship_type);
        err_bney_mishpacha_row.sug_zihuy                  := 1;
        if not err_bney_mishpacha_row.code_kirva is null then
          begin
            select distinct p.taarich_leda
              into v_mpm_taarich_leda
              from bney_mishpacha p
             where p.mispar_zehut_ben_mishpacha =
                   err_bney_mishpacha_row.mispar_zehut_ben_mishpacha
               and p.seq_porshim = v_seq_poresh;
          exception
            when no_data_found then
              v_mpm_taarich_leda := null;
          end;
        
          calc_date_birth(r.id_number,
                          err_bney_mishpacha_row.taarich_leda,
                          v_mpm_taarich_leda,
                          err_bney_mishpacha_row.mispar_zehut_ben_mishpacha);
        
          v_year_leda  := to_number(substr(err_bney_mishpacha_row.taarich_leda,
                                           7,
                                           4));
          v_month_leda := to_number(substr(err_bney_mishpacha_row.taarich_leda,
                                           4,
                                           2));
          v_day_leda   := to_number(substr(err_bney_mishpacha_row.taarich_leda,
                                           1,
                                           2));
          if v_month_leda = 2 and v_day_leda = 29 and
             mod(v_year_leda + 21, 4) <> 0 then
            v_day_leda := 28;
          end if;
          v_21_years_acharei_leda := to_date(to_char(v_day_leda, '99') || '/' ||
                                             to_char(v_month_leda, '99') || '/' ||
                                             to_char(v_year_leda + 21,
                                                     '9999'),
                                             'dd/mm/yyyy');
          --לא למחוק בני משפחה קודמים (זה יכול להשפיע על הפרישות הקודמות!!!!!         
          if err_bney_mishpacha_row.code_kirva = '1' or
             v_21_years_acharei_leda > sysdate and
             err_bney_mishpacha_row.code_kirva = '2' then
          
            begin
              select b.seq_bney_mishpacha
                into v_seq_bney_mishpacha
                from bney_mishpacha b
               where b.mispar_zehut_ben_mishpacha = r.fm_id_number
                 and b.seq_porshim = v_seq_poresh;
            exception
              when no_data_found then
                v_seq_bney_mishpacha := bney_mishpacha_seq.nextval;
            end;
            --merge into bney_mishpacha
            merge into bney_mishpacha b
            using dual
            on (b.seq_bney_mishpacha = v_seq_bney_mishpacha)
            when matched then
              update
                 set b.shem_mishpacha = err_bney_mishpacha_row.shem_mishpacha,
                     b.shem_prati     = err_bney_mishpacha_row.shem_prati,
                     b.taarich_leda   = err_bney_mishpacha_row.taarich_leda,
                     b.code_kirva     = err_bney_mishpacha_row.code_kirva,
                     b.sug_zihuy      = b.sug_zihuy
            when not matched then
              insert
                (mispar_zehut_ben_mishpacha,
                 shem_mishpacha,
                 shem_prati,
                 taarich_leda,
                 code_kirva,
                 seq_porshim,
                 seq_bney_mishpacha,
                 sug_zihuy)
              values
                (err_bney_mishpacha_row.mispar_zehut_ben_mishpacha,
                 err_bney_mishpacha_row.shem_mishpacha,
                 err_bney_mishpacha_row.shem_prati,
                 err_bney_mishpacha_row.taarich_leda,
                 err_bney_mishpacha_row.code_kirva,
                 v_seq_poresh,
                 v_seq_bney_mishpacha,
                 err_bney_mishpacha_row.sug_zihuy) log errors into err_bney_mishpacha reject limit unlimited;
          end if;
        end if;
      end if;
    
      if r.fm_id_number <> '000000000' and
        
         not err_bney_mishpacha_row.code_kirva is null then
        pk_load_mimshak.get_erorr_from_table(v_do_commit,
                                             v_report_for_tik,
                                             v_report_for_tik_varchar,
                                             'err_bney_mishpacha');
      end if;
    
      if v_do_commit = true then
        commit;
      
        if r.fm_id_number <> '000000000' and
          
           not err_bney_mishpacha_row.code_kirva is null then
          if err_bney_mishpacha_row.code_kirva = '1' or
             v_21_years_acharei_leda > sysdate and
             err_bney_mishpacha_row.code_kirva = '2' then
            v_report_for_tik := '<h3 style="font-weight: normal">' ||
                                '*** ID: ' || r.id_number ||
                                ' - ID family: ' || r.fm_id_number ||
                                ' ***' || '<h3/>' ||
                                '<h3  style="font-weight: normal">' ||
                                'updated. ' || '<h3/>';
          else
            v_report_for_tik := '<h3 style="font-weight: normal">' ||
                                '*** ID: ' || r.id_number ||
                                ' - ID family: ' || r.fm_id_number ||
                                ' ***' || '<h3/>' ||
                                '<h3  style="font-weight: normal">' ||
                                'age > 21 years  -  no updated. ' ||
                                '<h3/>';
          end if;
          v_count_success := v_count_success + 1;
        end if;
      else
        rollback;
        if r.fm_id_number <> '000000000' and
           not err_bney_mishpacha_row.code_kirva is null then
          v_report_for_tik := '<h2 font-weight: normal>' || '*** ID: ' ||
                              r.id_number || ' - ID family: ' ||
                              r.fm_id_number || ' ***' || '<h2/>' ||
                              '<h3 font-weight: normal>' || 'no updated. ' ||
                              '<h3/>' || chr(13) || chr(10) ||
                              v_report_for_tik_varchar;
          v_count_errors   := v_count_errors + 1;
        end if;
      end if;
    end loop;
  end;
