  procedure update_new_younges is
    v_death_date             date;
    v_do_commit              boolean := true;
    v_report_for_tik         clob;
    v_report_for_tik_varchar varchar2(32767);
    v_count_success          number := 0;
    v_count_errors           number := 0;
    i                        number := 0;
  begin
    for r in (select distinct p.mispar_zehut,
                              t.id_number,
                              b.seq_bney_mishpacha,
                              p.porshim_seq,
                              b.code_relative,
                              nvl(b.is_taluy, 0) is_taluy
                from LD_INTERIOR_all t
                left join bney_mishpacha b
                  on t.id_number = b.mispar_zehut_ben_mishpacha
                left join poresh p
                  on b.seq_porshim = p.porshim_seq
               where nvl(b.code_relative, 0) in (1, 5, 7)
                    
                 and b.mispar_zehut_ben_mishpacha is not null
                 and b.taarich_ptira is null
                 and p.taarich_ptira is not null
              --and t.id_number=23012024
              ) loop
    
      --update bney_mishpacha
      load_bney_mishpacha_ben_zug_from_all(r.id_number,
                                           r.porshim_seq,
                                           v_do_commit,
                                           v_report_for_tik,
                                           v_report_for_tik_varchar,
                                           v_count_success,
                                           v_count_errors);
    
    end loop;
    commit;
  end;

  --------------------------------------------------------------
  procedure update_sex_for_all_persons is
  begin
  
    for r in (select p.porshim_seq, l.sex
                from poresh p
                left join ld_interior l
                  on l.id_number = p.mispar_zehut
               where p.code_min is null
                 and nvl(l.sex, 0) <> 0) loop
      update poresh p
         set p.code_min = r.sex
       where p.porshim_seq = r.porshim_seq;
    end loop;
  
    for r1 in (select b.seq_bney_mishpacha, l.sex
                 from bney_mishpacha b
                 left join ld_interior l
                   on l.id_number = b.mispar_zehut_ben_mishpacha
                where b.code_min is null
                  and nvl(l.sex, 0) <> 0) loop
      update bney_mishpacha b
         set b.code_min = r1.sex
       where b.seq_bney_mishpacha = r1.seq_bney_mishpacha;
    end loop;
  
    commit;
  end;
  ------------------------------------------------
  procedure update_movement is
  begin
    for r1 in (select a.id_number_o, a.last_arrival_date
                 from (select l.id_number_o,
                              max(pk_interior.convert_string_to_date(l.last_arrival_date)) last_arrival_date
                         from ld_interior l
                        group by l.id_number_o) a
                 left join poresh p
                   on a.id_number_o = p.mispar_zehut
                where p.porshim_seq is not null
                  and nvl(a.last_arrival_date, sysdate) < sysdate
                  and (p.last_arrival_date is null or
                      a.last_arrival_date <> p.last_arrival_date)) loop
      update poresh p
         set p.last_arrival_date = r1.last_arrival_date
       where p.mispar_zehut = r1.id_number_o;
    end loop;
    commit;
  
    for r2 in (select a.*
                 from (select l.id_number_o,
                              max(pk_interior.convert_string_to_date(l.last_arrival_date)) last_arrival_date
                         from ld_interior l
                        group by l.id_number_o) a
                 left join bney_mishpacha b
                   on a.id_number_o = b.mispar_zehut_ben_mishpacha
                where b.seq_bney_mishpacha is not null
                  and nvl(a.last_arrival_date, sysdate) < sysdate
                  and (b.last_arrival_date is null or
                      a.last_arrival_date <> b.last_arrival_date)) loop
      update bney_mishpacha b
         set b.last_arrival_date = r2.last_arrival_date
       where b.mispar_zehut_ben_mishpacha = r2.id_number_o;
    end loop;
    commit;
  
    for r3 in (select a.*
                 from (select l.id_number_o,
                              max(pk_interior.convert_string_to_date(l.last_departure_date)) last_departure_date
                         from ld_interior l
                        group by l.id_number_o) a
                 left join poresh p
                   on a.id_number_o = p.mispar_zehut
                where p.porshim_seq is not null
                  and nvl(a.last_departure_date, sysdate) < sysdate
                  and (p.last_departure_date is null or
                      a.last_departure_date <> p.last_departure_date)) loop
      update poresh p
         set p.last_departure_date = r3.last_departure_date
       where p.mispar_zehut = r3.id_number_o;
    end loop;
    commit;
  
    for r4 in (select a.*
                 from (select l.id_number_o,
                              max(pk_interior.convert_string_to_date(l.last_departure_date)) last_departure_date
                         from ld_interior l
                        group by l.id_number_o) a
                 left join bney_mishpacha b
                   on a.id_number_o = b.mispar_zehut_ben_mishpacha
                where b.seq_bney_mishpacha is not null
                  and nvl(a.last_departure_date, sysdate) < sysdate
                  and (b.last_departure_date is null or
                      a.last_departure_date <> b.last_departure_date)) loop
      update bney_mishpacha b
         set b.last_departure_date = r4.last_departure_date
       where b.mispar_zehut_ben_mishpacha = r4.id_number_o;
    end loop;
  
    commit;
  end;
  ------------------------------------------------
  function count_ld_interior return number is
    v_count_rows number;
  begin
    select count(distinct t.id_number)
      into v_count_rows
      from ld_interior t;
  
    return v_count_rows;
  end;
  ------------------------------------------------
  procedure save_ld_interior_all is
    v_message varchar2(1000);
  
  begin
    select l.message
      into v_message
      from ld_protocol l
     where l.seq_ld_protocol in
           (select max(l.seq_ld_protocol)
              from ld_protocol l
             where l.code_process = 5
               and l.code_sub_process = 1);
    if v_message = 'include all' then
    
      delete from ld_interior_all;
    
      insert into ld_interior_all
        select * from ld_interior;
    
      commit;
    end if;
  
  end;
  ------------------------------------------------
  function Load_porshim_detailes_input(p_count_rows out number) return clob is
  
    v_seq_poresh             number;
    v_do_commit              boolean;
    v_report                 clob;
    v_report_for_tik         clob;
    v_report_for_tik_varchar varchar2(1000);
    v_title                  clob;
    v_recipient              varchar2(100);
    err_poresh_row           err_porshim%rowtype;
    count_errors             number;
    count_success            number;
  begin
    --save backup all data
    p_count_rows := count_ld_interior;
  
    save_ld_interior_all;
  
    execute immediate 'alter session set NLS_LANGUAGE= ''AMERICAN''';
    execute immediate 'alter session set NLS_DATE_LANGUAGE=''ENGLISH''';
    execute immediate 'alter session set NLS_DATE_FORMAT=''dd/mm/yyyy''';
  
    update_sex_for_all_persons;
  
    update_movement;
  
    --validation all persons
    Validation_for_all_persons;
  
    count_errors  := 0;
    count_success := 0;
    for r in (select distinct t.id_number,
                              t.id_number_o,
                              t.last_name_o,
                              t.first_name_o,
                              t.birth_date_o,
                              t.sex,
                              decode(t.death_ind, 2, t.death_ind_date, null) date_ptira,
                              v.seq_bakasha
                from ld_interior t
                left join v_bakasha_last_status v
                  on v.mispar_zehut = t.id_number
               where t.id_number is not null
                 and v.code_action = 26
               order by t.id_number) loop
      v_do_commit              := true;
      v_report_for_tik         := null;
      v_report_for_tik_varchar := null;
    
      --truncate 'err' tables
      execute immediate 'truncate table err_porshim';
      execute immediate 'truncate table err_bney_mishpacha';
      execute immediate 'truncate table err_participation';
    
      if r.id_number_o = '000000000' then
        v_report_for_tik := '<h2>' || '*** ID: ' || r.id_number ||
                            ' record not identify' || '<h2/>';
        count_errors     := count_errors + 1;
        v_do_commit      := false;
        v_report         := v_report || v_report_for_tik;
      elsif r.id_number <> r.id_number_o then
        v_report_for_tik := '<h2>' || '*** ID: ' || r.id_number ||
                            ' record with error id' || '<h2/>';
        count_errors     := count_errors + 1;
        v_do_commit      := false;
        v_report         := v_report || v_report_for_tik;
      elsif r.id_number = r.id_number_o then
      
        --get seq_poresh
        select p.porshim_seq
          into v_seq_poresh
          from poresh p
         where p.mispar_zehut = r.id_number;
      
        err_poresh_row.shem_prati     := r.first_name_o;
        err_poresh_row.shem_mishpacha := r.last_name_o;
        err_poresh_row.taarich_leda   := r.birth_date_o;
      
        err_poresh_row.code_min      := r.sex;
        err_poresh_row.taarich_ptira := r.date_ptira;
      
        err_poresh_row.mispar_zehut := r.id_number;
      
        check_poresh(err_poresh_row);
      
        update poresh
           set shem_prati     = err_poresh_row.shem_prati,
               shem_mishpacha = err_poresh_row.shem_mishpacha,
               taarich_leda   = err_poresh_row.taarich_leda,
               code_min       = err_poresh_row.code_min,
               taarich_ptira  = err_poresh_row.taarich_ptira
         where poresh.mispar_zehut = err_poresh_row.mispar_zehut log errors into
         err_porshim reject limit unlimited;
      
        --address
        load_address(r.id_number, v_seq_poresh, r.seq_bakasha, null);
      
        --mazav_mishpachti
        load_mazav_mishpachti(r.id_number, v_seq_poresh, null);
      
        --bney_mishpacha
        load_bney_mishpacha(r.id_number,
                            v_seq_poresh,
                            v_do_commit,
                            v_report_for_tik,
                            v_report_for_tik_varchar,
                            count_success,
                            count_errors);
      
        pk_load_mimshak.get_erorr_from_table(v_do_commit,
                                             v_report_for_tik,
                                             v_report_for_tik_varchar,
                                             'err_porshim');
      
        v_report := v_report || v_report_for_tik;
      
      end if;
    
      if v_do_commit = false then
        rollback;
      
      elsif v_do_commit = true then
        pk_prm_utils.insert_actions_for_bakasha(r.seq_bakasha);
        commit;
      end if;
    
    end loop;
  
    -- add to the repport summary rowes  as title.
    v_title := 'The interior interface finished' || chr(10) ||
               'total success rows: ' || count_success || chr(10) ||
               'total errors rows: ' || count_errors || chr(10);
  
    v_report := '<html><body>' || '<h1>' ||
                'The interior interface finished' || '</h1>' || '<h1>' ||
                'total success rows: ' || count_success || '<h1/>' ||
                '<h1>' || 'total errors rows: ' || count_errors ||
                '<h1/><html/><body/>' || v_report || '<html/><body/>';
  
    if count_errors > 0 then
      v_recipient := 'dvora@mof.gov.il';
      pk_prm_utils.send_attach(v_recipient,
                               'The interior interface finished',
                               v_title,
                               v_report,
                               'htm',
                               to_char(sysdate, 'dd_mm_yyyy') ||
                               'interior_interface.htm');
    end if;
    return v_report;
  
  end;
  ------------------------------------------------
  procedure send_mail_to_hp(count_porshim number) is
    mail_recipient varchar2(100) := 'SigalHe@piba.gov.il,AvivLH@piba.gov.il';
  
    v_report  clob;
    v_subject varchar2(1000) := 'Ministry of Finance - Gimlaot 58';
    v_message varchar2(1000) := 'Hello,
  Please confirm a verification service of family members in a batch file id 0058is_07_02:
  The batch file will contain ' ||
                                count_porshim || ' records.
  Best Regards';
  begin
    if count_porshim > 0 then
      v_report := v_message;
      --Send in mail
      pk_prm_utils.send_attach(mail_recipient,
                               v_subject,
                               v_message,
                               v_report,
                               'txt',
                               'Ministry_of_Finance' ||
                               to_char(sysdate, 'dd_mm_yyyy') || '.txt');
    end if;
  end;
  ------------------------------------------------
end;
/

create or replace package body prm_system_copy.pk_interior_nisuy_prd is

  ------------------------------------
  chr_10      constant varchar2(2) := chr(10);
  date_format constant varchar2(8) := 'yyyymmdd';
  ------------------------------------
  function get_header_file_name return varchar2 is
  begin
    return 'l000058_0058is_07_02_' || to_char(sysdate, 'yymmdd') || '.config';
  end;
  ------------------------------------
  function get_content_file_name return varchar2 is
  begin
    return 'eim_l000058_0058is_07_02_' || to_char(sysdate, 'yymmdd') || '_i.dat';
  end;
  ------------------------------------
  function create_header_output return clob is
  begin
    return '000058' || '031040' || lpad(1, 200, 1) || '00000001' || 1 || to_char(sysdate,
                                                                                 'yyyymmdd') || rpad('0058is_07',
                                                                                                     20,
                                                                                                     ' ') || rpad('0058is_07_02',
                                                                                                                  20,
                                                                                                                  ' ') || rpad(' ',
                                                                                                                               50,
                                                                                                                               ' ');
  end;
  ------------------------------------------------------
  function get_last_address(p_seq_poresh         number,
                            p_seq_bney_mishpacha number) return varchar2 is
    v_last_zip        number;
    v_length_last_zip number;
    v_last_city       number;
  begin
    begin
      if p_seq_bney_mishpacha is not null then
        select a.code_city, a.mikud, length(a.mikud)
          into v_last_city, v_last_zip, v_length_last_zip
          from address a
         where a.seq_bney_mishpacha = p_seq_bney_mishpacha
           and a.code_address = 1
         order by a.seq_address desc
         fetch first 1 rows only;
      
      elsif p_seq_poresh is not null then
        select a.code_city, a.mikud, length(a.mikud)
          into v_last_city, v_last_zip, v_length_last_zip
          from address a
         where a.seq_poresh = p_seq_poresh
           and a.code_address = 1
         order by a.seq_address desc
         fetch first 1 rows only;
      end if;
    
    exception
      when others then
        v_last_zip  := null;
        v_last_city := null;
    end;
  
    return pk_create_mimshak_out.substr_lpad_nvl_zero(v_last_city,
                                                      
                                                      4) || rpad(' ',
                                                                 50,
                                                                 ' ') || lpad(0,
                                                                              4,
                                                                              0) || rpad(' ',
                                                                                         50,
                                                                                         ' ') || lpad(0,
                                                                                                      4,
                                                                                                      0) || rpad(' ',
                                                                                                                 1,
                                                                                                                 ' ') || lpad(0,
                                                                                                                              2,
                                                                                                                              0) || lpad(0,
                                                                                                                                         4,
                                                                                                                                         0) || pk_create_mimshak_out.substr_lpad_nvl_zero(case when
                                                                                                                                                                                          v_length_last_zip = 5 then
                                                                                                                                                                                          v_last_zip else null end,
                                                                                                                                                                                          5) || pk_create_mimshak_out.substr_lpad_nvl_zero(case when
                                                                                                                                                                                                                                           v_length_last_zip = 7 then
                                                                                                                                                                                                                                           v_last_zip else null end,
                                                                                                                                                                                                                                           7);
  
  end;
  ------------------------------------------------------
  function create_content_output(p_is_all_persons        number,
                                 p_is_payment_in_advance number,
                                 p_count_rowes           in out number)
    return clob is
    result clob;
  
  begin
    --truncate 'ld_interior_out' table
    execute immediate 'truncate table ld_interior_out';
  
    for r in (with a as
                 (select p.porshim_seq,
                        null as seq_bney_mishpacha,
                        pk_create_mimshak_out.substr_lpad_nvl_zero(p.mispar_zehut,
                                                                   9) id_number,
                        pk_create_mimshak_out.substr_rpad_nvl_pad_char(p.shem_mishpacha,
                                                                       20) last_name,
                        pk_create_mimshak_out.substr_rpad_nvl_pad_char(p.shem_prati,
                                                                       20) first_name,
                        to_char(p.taarich_leda, date_format) birth_date,
                        p.taarich_ptira,
                        p1.is_payment_in_advance
                   from poresh p
                   left join prisha p1
                     on p.porshim_seq = p1.seq_poresh
                 --sug_zihuy
                  where nvl(p.sug_zihuy, 0) not in (5, 6)),
                b as
                 (select null,
                        b.seq_bney_mishpacha,
                        pk_create_mimshak_out.substr_lpad_nvl_zero(b.mispar_zehut_ben_mishpacha,
                                                                   9) id_number,
                        pk_create_mimshak_out.substr_rpad_nvl_pad_char(b.shem_mishpacha,
                                                                       20) last_name,
                        pk_create_mimshak_out.substr_rpad_nvl_pad_char(b.shem_prati,
                                                                       20) first_name,
                        to_char(b.taarich_leda, date_format) birth_date,
                        null as taarich_ptira,
                        p1.is_payment_in_advance
                   from bney_mishpacha b
                   left join poresh p
                     on b.seq_porshim = p.porshim_seq
                   left join prisha p1
                     on p.porshim_seq = p1.seq_poresh
                  where /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                          We send the id also if it's exist in porshim
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                          because it is not always updated in the two tables
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                          p.mispar_zehut is null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                             and*/
                  b.taarich_ptira is null
              and b.code_kirva in (1, 2, 14, 10, 24)
              and (b.code_kirva <> 2 or (add_months(b.taarich_leda, 252) >
                  sysdate or b.is_taluy = 1))
                 --sug_zihuy
              and nvl(b.sug_zihuy, 0) not in (5, 6)),
                c as
                 (select v.mispar_zehut, v.seq_bakasha, v.code_action
                   from v_bakasha_last_status v
                  where v.code_action in (86, 26))
                select *
                  from (select a.*, c.seq_bakasha, c.code_action
                          from a
                          left join c
                            on a.id_number = c.mispar_zehut
                         where c.mispar_zehut is not null
                            or (p_is_all_persons = 1 and
                               a.taarich_ptira is null)
                            or (p_is_payment_in_advance = 1 and
                               a.is_payment_in_advance = 1)
                        union
                        select b.*, null, null
                          from b
                         where (p_is_all_persons = 1)
                            or (p_is_payment_in_advance = 1 and
                               b.is_payment_in_advance = 1))
                -- week day
                 where to_char(sysdate, 'd') not in (6, 7)) loop
    
      --Insert into ld_interior_out
      insert into ld_interior_out values (r.id_number);
    
      if result is not null then
        result := result || chr_10;
      end if;
    
      result := result || r.id_number || r.last_name || r.first_name ||
                rpad(' ', 20, ' ') || rpad(' ', 20, ' ') || r.birth_date ||
                get_last_address(r.porshim_seq, r.seq_bney_mishpacha) ||
                lpad(0, 9, 0) || rpad(' ', 10, ' ');
    
      if r.code_action = 86 then
        pk_prm_utils.insert_actions_for_bakasha(r.seq_bakasha, 0);
      elsif r.code_action = 26 then
        --when the bakasha in status 'sended to interior' and it's stopped.
        pk_prm_utils.insert_action_log_row(26,
                                           sysdate,
                                           0,
                                           null,
                                           'לא התקבל משוב ולכן נשלח שוב לאימות',
                                           null,
                                           null,
                                           null,
                                           r.seq_bakasha,
                                           null);
      end if;
    
      commit;
    end loop;
  
    --save count rows
    select count(distinct id) into p_count_rowes from ld_interior_out;
  
    return trim(result);
  end;
  --------------------------------------------------
  function get_mpm_code_mazav_mishpachti(v_code_mazav_mishpachti number)
    return number is
  begin
    return case when v_code_mazav_mishpachti = 10 then 0 when v_code_mazav_mishpachti = 20 then 1 when v_code_mazav_mishpachti = 21 then 6 when v_code_mazav_mishpachti = 22 then 7 when v_code_mazav_mishpachti = 30 then 3 when v_code_mazav_mishpachti = 31 then 0 when v_code_mazav_mishpachti = 40 then 2 when v_code_mazav_mishpachti = 66 then 999 when v_code_mazav_mishpachti = 77 then 999 when v_code_mazav_mishpachti = 99 then 999 else null end;
  end;
  --------------------------------------------------
  function get_mpm_code_kirva(v_code_kirva number) return number is
  begin
    return case when v_code_kirva = 3 then 2 when v_code_kirva = 4 then 1 else null end;
  end;
  ------------------------------------
  procedure Insert_invalid_date(p_mispar_zehut in number,
                                p_taarich_leda in varchar2,
                                v_remark       in out varchar2) is
  begin
    v_remark := 'תאריך לידה שגוי התקבל בממשק משרד הפנים ' || v_remark;
  
    v_remark := v_remark || '(' || p_taarich_leda || ')';
    insert_action_letipuly(v_remark, p_mispar_zehut);
  
  end Insert_invalid_date;
  ------------------------------------
  procedure calc_date_birth(p_mispar_zehut               number,
                            p_taarich_leda               in out varchar2,
                            p_mpm_taarich_leda           date,
                            p_mispar_zehut_ben_mishpacha number default null)
  
   is
    pragma autonomous_transaction;
    v_remark              varchar2(1000) := '';
    v_low_year_date_birth number;
    v_up_year_date_birth  number;
    v_year                number;
  begin
    begin
      if p_mispar_zehut_ben_mishpacha is not null then
        v_remark := v_remark || ' לבן משפחה - ' ||
                    to_char(p_mispar_zehut_ben_mishpacha);
      end if;
      --Try to convert taarich_leda to date format
      p_taarich_leda := to_date(p_taarich_leda, date_format);
    
      v_remark := 'תאריך לידה במפמ ' || v_remark;
    
      if nvl(p_taarich_leda, to_date('01010001', 'ddmmyyyy')) <>
         nvl(p_mpm_taarich_leda, to_date('01010001', 'ddmmyyyy')) then
        v_remark := v_remark || ' (' ||
                    to_char(p_mpm_taarich_leda, 'dd/mm/yyyy') ||
                    ') שונה מתאריך לידה במשרד הפנים (' || p_taarich_leda || ')';
        insert_action_letipuly(v_remark, to_number(p_mispar_zehut));
      end if;
    exception
      when others then
      
        if to_number(substr(p_taarich_leda, 5)) <> 0 and
           to_number(substr(p_taarich_leda, 7)) = 0 then
          begin
            p_taarich_leda := to_date(substr(p_taarich_leda, 1, 6) || '01',
                                      date_format);
          exception
            when others then
              Insert_invalid_date(p_mispar_zehut, p_taarich_leda, v_remark);
          end;
        else
        
          --Get min date from date_birth table
          select extract(year from min(t.date_nisan))
            into v_low_year_date_birth
            from date_birth t;
          --Get max date from date_birth table
          select extract(year from max(t.date_nisan))
            into v_up_year_date_birth
            from date_birth t;
        
          v_year := to_number(substr(p_taarich_leda, 1, 4));
        
          --when the taarich_leda was get from interior only with year
          if (v_year between v_low_year_date_birth and v_up_year_date_birth) and
             to_number(substr(p_taarich_leda, 5)) = 0 then
            begin
              v_remark := 'תאריך לידה שגוי התקבל בממשק משרד הפנים ' ||
                          v_remark;
              v_remark := v_remark || '(' || p_taarich_leda || ')';
            
              select t.date_nisan
                into p_taarich_leda
                from date_birth t
               where extract(year from t.date_nisan) = v_year;
            
              v_remark := v_remark || ' ושונה ל ' || p_taarich_leda;
              insert_action_letipuly(v_remark, p_mispar_zehut);
            
            exception
              when others then
                Insert_invalid_date(p_mispar_zehut,
                                    p_taarich_leda,
                                    v_remark);
            end;
          
          else
          
            Insert_invalid_date(p_mispar_zehut, p_taarich_leda, v_remark);
          end if;
        end if;
    end;
    commit;
  end;
  ------------------------------------
  procedure check_poresh(err_poresh_row in out err_porshim%rowtype) is
    pragma autonomous_transaction;
    v_remark           varchar2(1000);
    v_mpm_taarich_leda date;
  begin
    begin
      err_poresh_row.taarich_ptira := to_date(err_poresh_row.taarich_ptira,
                                              date_format);
    exception
      when others then
        v_remark := 'תאריך פטירה שגוי התקבל בממשק משרד הפנים (' ||
                    err_poresh_row.taarich_ptira || ')';
        insert_action_letipuly(v_remark, err_poresh_row.mispar_zehut);
        pk_load_mimshak.add_row_to_err_porshim('poresh',
                                               err_poresh_row,
                                               sqlerrm,
                                               sqlcode,
                                               'taarich_ptira');
    end;
  
    begin
      select p.taarich_leda
        into v_mpm_taarich_leda
        from poresh p
       where p.mispar_zehut = err_poresh_row.mispar_zehut;
    exception
      when no_data_found then
        v_mpm_taarich_leda := null;
    end;
  
    calc_date_birth(err_poresh_row.mispar_zehut,
                    err_poresh_row.taarich_leda,
                    v_mpm_taarich_leda);
  
    commit;
  end;
  ------------------------------------------------
  procedure insert_action_letipuly(v_remark       varchar2,
                                   v_mispar_zehut number) is
    v_code_user    number;
    v_next_status  number;
    v_is_automatic number;
  begin
    for r in (select v.seq_bakasha,
                     v.code_sug_workflow,
                     v.code_action,
                     v.code_user_update,
                     pk_load_mimshak.Get_user_id_by_category(v.seq_ezor_ovdim) nashm_category
                from v_bakasha_last_status v
               where v.mispar_zehut = v_mispar_zehut
                 and (v.code_action = 86 or
                     (v.code_sug_workflow = 5 and
                     v.seq_bakasha not in
                     (select a.seq_bakasha
                          from action_log a
                         where a.code_action = 98)))) loop
    
      if r.code_sug_workflow in (5, 8) then
        --When there is kpm/participation_to
        v_code_user := r.code_user_update;
      else
        pk_prm_utils.Find_next_action(r.code_sug_workflow,
                                      r.code_action,
                                      v_next_status,
                                      v_is_automatic);
      
        v_code_user := pk_prm_utils.get_next_user_for_bakasha(v_next_status,
                                                              r.seq_bakasha);
      end if;
      pk_prm_utils.insert_action_log_row(2,
                                         sysdate,
                                         0,
                                         v_code_user,
                                         v_remark,
                                         null,
                                         null,
                                         null,
                                         r.seq_bakasha,
                                         null);
    end loop;
  end;
  ------------------------------------------------
  procedure load_address(p_id_number          number,
                         p_seq_poresh         number,
                         p_seq_bakasha        number,
                         p_seq_bney_mishpacha number) is
  begin
  
    for r in
    --Get interior data
     (select distinct get_only_if_value(l.city_code_o) city_code_o,
                      get_only_if_value(l.street_name_o) street_name_o,
                      get_only_if_value(l.house_number_o) house_number_o,
                      get_only_if_value(l.house_letter_o) house_letter_o,
                      get_only_if_value(l.entrance_number_o) entrance_number_o,
                      get_only_if_value(l.apartment_number_o) apartment_number_o,
                      get_only_if_value(l.zip_code_7_o) zip_code_7_o
      
        from ld_interior l
       where l.id_number = p_id_number
         and nvl(l.city_code_o, 0) <> 0) loop
    
      for r2 in
      --Get mpm data  
       (select a.code_city,
               a.mikud,
               a.street,
               a.house,
               a.apartment,
               a.entrance,
               a.house_letter
        
          from address a
         where ((p_seq_poresh is not null and a.seq_poresh = p_seq_poresh) or
               (p_seq_bney_mishpacha is not null and
               a.seq_bney_mishpacha = p_seq_bney_mishpacha))
              -- Type address: from interior
           and a.code_address = 1
        -- Get the last address in mpm
         order by a.seq_address desc
         fetch first 1 rows only) loop
      
        if nvl(r2.code_city, 0) = nvl(r.city_code_o, 0) and
           nvl(r2.mikud, 0) = nvl(r.zip_code_7_o, 0) and
           nvl(r2.street, 0) = nvl(r.street_name_o, 0) and
           nvl(r.house_number_o, 0) = nvl(r2.house, 0) and
           nvl(r2.apartment, 0) = nvl(r.apartment_number_o, 0) and
           nvl(r2.entrance, 0) = nvl(r.entrance_number_o, 0) and
           nvl(r2.house_letter, 0) = nvl(r.house_letter_o, 0) then
          --Don't insert same row to table
          return;
        end if;
      end loop;
    
      --insert new row to address table
      insert into address
        (code_address,
         code_city,
         mikud,
         date_update,
         code_user_update,
         seq_address,
         seq_poresh,
         seq_bney_mishpacha,
         street,
         house,
         apartment,
         entrance,
         house_letter,
         seq_bakasha)
      values
        (1,
         r.city_code_o,
         r.zip_code_7_o,
         sysdate,
         0,
         address_seq.nextval,
         p_seq_poresh,
         p_seq_bney_mishpacha,
         r.street_name_o,
         r.house_number_o,
         r.apartment_number_o,
         r.entrance_number_o,
         r.house_letter_o,
         p_seq_bakasha);
    
    end loop;
  
  end;
  ------------------------------------------------
  function convert_string_to_date(p_value varchar2) return date is
    v_string_day   varchar2(2) := substr(p_value, 7, 2);
    v_string_month varchar2(2) := substr(p_value, 5, 2);
    v_string_year  varchar2(4) := substr(p_value, 0, 4);
  
  begin
    if v_string_year <> 0 then
      return to_date(v_string_year || get_first_when_zero(v_string_month) ||
                     get_first_when_zero(v_string_day),
                     'yyyymmdd');
    else
      return null;
    end if;
  exception
    when others then
      return null;
  end;
  ------------------------------------------------
  function get_first_when_zero(p_value varchar2) return varchar2 is
  begin
    if to_number(p_value) = 0 then
      return '01';
    else
      return p_value;
    end if;
  exception
    when others then
      return null;
  end;

  ------------------------------------------------
  procedure load_mazav_mishpachti(p_id_number          number,
                                  p_seq_poresh         number,
                                  p_seq_bney_mishpacha number) is
  begin
  
    for r in
    --Get interior data
     (select distinct get_mpm_code_mazav_mishpachti(l.marital_status) marital_status,
                      convert_string_to_date(l.marital_date) marital_date
        from ld_interior l
       where l.id_number = p_id_number
         and l.marital_status <> 0) loop
    
      for r2 in
      --Get mpm data  
       (select a.code_mazav_mishpachti, a.date_mazav_mishpachti
          from mazav_mishpachti a
         where (p_seq_poresh is not null and a.seq_poresh = p_seq_poresh)
            or (p_seq_bney_mishpacha is not null and
               a.seq_bney_mishpacha = p_seq_bney_mishpacha)
        -- Get the last mazav_mishpachti in mpm
         order by nvl(a.date_mazav_mishpachti,
                      to_date('01011000', 'ddmmyyyy')) desc,
                  a.seq_mazav_mishpachti desc
         fetch first 1 rows only) loop
        if
        --When the ststus already updated in mpm
         r2.code_mazav_mishpachti = r.marital_status
        --When MPM updated more than INTERIOR, 
         or r2.date_mazav_mishpachti > r.marital_date then
          --Don't insert row to table
          return;
        end if;
      
      end loop;
    
      --insert new row to mazav_mishpachti table
      insert into mazav_mishpachti
        (seq_mazav_mishpachti,
         seq_poresh,
         seq_bney_mishpacha,
         code_mazav_mishpachti,
         date_mazav_mishpachti,
         date_update,
         code_user)
      values
        (mazav_mishpachti_seq.nextval,
         p_seq_poresh,
         p_seq_bney_mishpacha,
         r.marital_status,
         r.marital_date,
         sysdate,
         0);
    
    end loop;
  
  end;
