  ---=====================================--------
  procedure open_pniya_gimlai_bakasha(p_seq_poresh         number,
                                      p_seq_prisha         number,
                                      p_date_ptira         date,
                                      p_seq_bney_mishpacha number) is
    v_is_exist_pniya_gimlai_bakasha number;
    v_is_exist_sheer_bakasha        number;
    v_count_relatives               number(1) := 0;
    v_seq_bakasha                   number;
    v_code_sug_bakasha              number := 25;
    v_code_bakasha_detail           number := 20;
  begin
  
    select count(*)
      into v_count_relatives
      from bney_mishpacha b
     where b.seq_porshim = p_seq_poresh
       and (b.code_kirva in (1, 13, 14) or
           (b.code_kirva = 2 and
           add_months(b.taarich_leda, 12 * 21) > trunc(sysdate)) and
           b.taarich_ptira is null);
  
    select count(*)
      into v_is_exist_sheer_bakasha
      from bakasha b
      left join netuney_tik_mechushavim n
        on b.seq_bakasha = n.seq_bakasha
       and n.code_department = 2
       and n.mispar_misra = 0
       and n.code_group_prisha = 4
     where b.seq_prisha = p_seq_prisha
       and n.seq_netuney_tik_mechushavim is not null;
  
    select count(*)
      into v_is_exist_pniya_gimlai_bakasha
      from bakasha b
      left join v_bakasha_last_status v
        on b.seq_bakasha = v.seq_bakasha
     where b.seq_prisha = p_seq_prisha
       and b.code_sug_bakasha = v_code_sug_bakasha
       and b.code_bakasha_detail = v_code_bakasha_detail
       and nvl(b.seq_bney_mishpacha, 0) = nvl(p_seq_bney_mishpacha, 0)
       and v.code_action <> 17;
  
    if v_is_exist_pniya_gimlai_bakasha = 0 and v_count_relatives > 0
      --There is not exist bakashat sheer
       and v_is_exist_sheer_bakasha = 0 then
    
      v_seq_bakasha := bakasha_seq.nextval();
    
      insert into bakasha
        (seq_bakasha,
         seq_prisha,
         code_sug_bakasha,
         code_bakasha_detail,
         date_bakasha,
         code_source,
         date_update,
         from_date,
         seq_bney_mishpacha)
      values
        (v_seq_bakasha,
         p_seq_prisha,
         v_code_sug_bakasha,
         v_code_bakasha_detail,
         sysdate,
         16,
         sysdate,
         trunc(add_months(p_date_ptira, 1), 'MONTH'),
         p_seq_bney_mishpacha);
    
      pk_prm_utils.insert_actions_for_bakasha(v_seq_bakasha, 0);
    
    end if;
  end;
