  procedure update_date_end_zakaut_bney_mishpacha(p_seq_bney_mishpacha number,
                                                  p_date_end           date) is
  begin
    update bney_mishpacha b
       set b.to_date_sium_zakaut = p_date_end
     where b.seq_bney_mishpacha = p_seq_bney_mishpacha;
  
  end;

  ------------------------------------------------
  procedure open_special_bakasha(p_id_number           number,
                                 p_code_sug_bakasha    number,
                                 p_code_bakasha_detail number,
                                 p_date_expired        date,
                                 p_seq_bney_mishpacha  number) is
    v_is_exist_bakasha_zakaut number;
  begin
    for r1 in (select distinct v.seq_prisha, v.seq_porshim
                 from v_bakasha_last_status v
                 left join netuney_tik_mechushavim n
                   on v.seq_bakasha = n.seq_bakasha
                  and n.code_department = 2
                  and n.mispar_misra = 0
                where v.mispar_zehut = p_id_number
                  and n.date_start_zakaut is not null
                  and n.date_end_zakaut is null
                  and (v.seq_ezor_ovdim not in
                      (select c.seq_ezor_ovdim
                          from ezor_ovdim_category c
                        --all security
                         where c.code_sug_ezor_ovdim = 8) or
                      v.seq_ezor_ovdim in
                      (select c.seq_ezor_ovdim
                          from ezor_ovdim_category c
                        --security that his payment in hilan
                         where c.code_sug_ezor_ovdim = 14))
               
               ) loop
    
      select count(*)
        into v_is_exist_bakasha_zakaut
        from bakasha b
       where b.seq_prisha = r1.seq_prisha
         and b.code_sug_bakasha in (1, 3, 5);
    
      if p_code_sug_bakasha = 19 then
        --open stop bakasha
        open_stop_bakasha(r1.seq_prisha,
                          p_code_bakasha_detail,
                          p_date_expired,
                          p_seq_bney_mishpacha,
                          v_is_exist_bakasha_zakaut);
      
      elsif p_code_sug_bakasha = 25 and v_is_exist_bakasha_zakaut > 0 then
        --open pniya gimlai
        open_pniya_gimlai_bakasha(r1.seq_porshim,
                                  r1.seq_prisha,
                                  p_date_expired,
                                  p_seq_bney_mishpacha);
      
      end if;
    
    end loop;
  end;
  ------------------------------------------------
  procedure update_kpm_date_end(v_seq_bakasha number, date_ptira date) is
  begin
    update participation p
       set p.date_end = date_ptira, p.code_hafsaka = 5
     where date_ptira is not null
       and p.seq_bakasha = v_seq_bakasha;
  end;

  ------------------------------------------------
  procedure update_data_for_died is
    v_do_commit              boolean := true;
    v_report_for_tik         clob;
    v_report_for_tik_varchar varchar2(1000);
    v_count_success          number := 0;
    v_count_errors           number := 0;
  begin
    for r in (select distinct b.mispar_zehut_ben_mishpacha,
                              b.seq_bney_mishpacha,
                              b.code_kirva,
                              p.taarich_ptira,
                              p.mispar_zehut,
                              p.porshim_seq,
                              t.first_name_o,
                              t.last_name_o,
                              t.sex,
                              convert_string_to_date(t.birth_date_o) date_birth
                from LD_INTERIOR t
                left join bney_mishpacha b
                  on t.id_number_o = b.mispar_zehut_ben_mishpacha
                left join poresh p
                  on b.seq_porshim = p.porshim_seq
                left join v_bakasha_last_status v
                  on p.mispar_zehut = v.mispar_zehut
                 and v.code_sug_bakasha = 25
                 and v.code_bakasha_detail = 20
               where b.seq_bney_mishpacha is not null
                 and p.taarich_ptira is not null
                    --Don't open new bakasha for history
                 and p.taarich_ptira > to_date('15062019', 'ddmmyyyy')
                 and v.seq_bakasha is null
                 and (b.code_kirva in (1, 13, 14) or
                     ( --when there is a child, check that his age is less than 21
                      b.code_kirva = 2 and
                      add_months(convert_string_to_date(t.birth_date_o),
                                  12 * 21) >= trunc(sysdate)))
                 and b.taarich_ptira is null) loop
    
      --update bney_mishpacha
      update bney_mishpacha b
         set b.shem_mishpacha = r.last_name_o,
             b.shem_prati     = r.first_name_o,
             b.code_min       = r.sex,
             b.taarich_leda   = r.date_birth
       where b.seq_bney_mishpacha = r.seq_bney_mishpacha;
    
      --load_address
      load_address(r.mispar_zehut_ben_mishpacha,
                   null,
                   null,
                   r.seq_bney_mishpacha);
    
      if r.code_kirva = 1 then
        -- When the relative is spouse, update marital status
        load_mazav_mishpachti(r.mispar_zehut_ben_mishpacha,
                              null,
                              r.seq_bney_mishpacha);
      end if;
    
      open_special_bakasha(r.mispar_zehut,
                           25,
                           20,
                           r.taarich_ptira,
                           r.seq_bney_mishpacha);
    
    end loop;
    commit;
  end;
  ------------------------------------------------
  -----=======האם משרדים מדווחים לחילן
  function is_to_hilan(p_seq_poresh number) return number is
    v_to_hilan              number;
   
  begin
     select count(*) into v_to_hilan
          from prisha pr    
         where pr.seq_poresh = p_seq_poresh
           and pr.seq_ezor_ovdim not in (155,
                                      163,
                                      164,
                                      225,
                                      10150,
                                      10152,
                                      10155,
                                      10156,
                                      10157,
                                      10153,
                                      10151,
                                      10149) ;
    
    return v_to_hilan;
  end;
  --==========================================
  procedure update_mazav_mishpachti_porshim is
    int_date date;
    to_hilan number;
  begin
    for r in (select distinct t.id_number,
                              p.mispar_zehut,
                              p.porshim_seq,
                              bm.seq_bney_mishpacha,
                              t.marital_status,
                              t.marital_date,
                              pk_interior.convert_string_to_date(t.marital_date)
                from ld_interior_all t
                left join poresh p
                  on p.mispar_zehut = t.id_number
              
                left join (select seq_poresh,
                                 date_mazav_mishpachti,
                                 seq_mazav_mishpachti,
                                 code_mazav_mishpachti
                            from (select seq_poresh,
                                         date_mazav_mishpachti,
                                         seq_mazav_mishpachti,
                                         code_mazav_mishpachti,
                                         row_number() over(partition by seq_poresh order by nvl(date_mazav_mishpachti, to_date('01/01/1900', 'dd/mm/yyyy')) desc, seq_mazav_mishpachti desc) as rn
                                    from mazav_mishpachti mm1)
                           where rn = 1) a
                  on a.seq_poresh = p.porshim_seq
              
                left join bney_mishpacha bm
                  on bm.mispar_zehut_ben_mishpacha = t.id_number
                 and bm.code_relative is not null
                 and bm.code_relative <> 99
                 and (bm.to_date_sium_zakaut is null or
                     bm.to_date_sium_zakaut > sysdate)
              
               where t.id_number is not null
                 and PK_INTERIOR.get_mpm_code_mazav_mishpachti(t.marital_status) <>
                     a.code_mazav_mishpachti
                 and a.code_mazav_mishpachti not in (8, 4)
                 and p.taarich_ptira is null
                 and pk_interior.convert_string_to_date(t.marital_date) >=
                     to_date('01012022', 'ddmmyyyy')
                 and pk_interior.convert_string_to_date(t.marital_date) >
                     a.date_mazav_mishpachti
               order by t.id_number) loop
      int_date := pk_interior.convert_string_to_date(r.marital_date);
      if r.id_number is not null then
        load_mazav_mishpachti_all(r.porshim_seq,
                                  null,
                                  int_date,
                                  PK_INTERIOR.get_mpm_code_mazav_mishpachti(r.marital_status));
       
        ---------===============
       if  is_to_hilan(r.porshim_seq)>0 then
         open_bakasha_shinuy_mazav_mishpachti(r.porshim_seq, null);
       end if;  
      end if;
      ----פורש קיים גם כבן משפחה
      if r.seq_bney_mishpacha is not null then
        load_mazav_mishpachti_all(null,
                                  r.seq_bney_mishpacha,
                                  int_date,
                                  PK_INTERIOR.get_mpm_code_mazav_mishpachti(r.marital_status));
      end if;
    
    end loop;
    commit;
  
  end;
