  ------------------------------------------------
  --==========================================
  procedure update_mazav_mishpachti_bney_mispacha is
    int_date date;
  begin
    for r in (select distinct t.id_number,
                              p.mispar_zehut_ben_mishpacha,
                              p.seq_bney_mishpacha,
                              t.marital_status,
                              p.seq_porshim,
                              t.marital_date
                from LD_INTERIOR_all t
                left join bney_mishpacha p
                  on p.mispar_zehut_ben_mishpacha = t.id_number
              
                left join (select seq_bney_mishpacha,
                                 date_mazav_mishpachti,
                                 seq_mazav_mishpachti,
                                 code_mazav_mishpachti
                            from (select seq_bney_mishpacha,
                                         date_mazav_mishpachti,
                                         seq_mazav_mishpachti,
                                         code_mazav_mishpachti,
                                         row_number() over(partition by seq_bney_mishpacha order by nvl(date_mazav_mishpachti, to_date('01/01/1900', 'dd/mm/yyyy')) desc, seq_mazav_mishpachti desc) as rn
                                    from mazav_mishpachti mm1)
                           where rn = 1) a
                  on a.seq_bney_mishpacha = p.seq_bney_mishpacha
              -- left join poresh po on p.mispar_zehut_ben_mishpacha=po.mispar_zehut
               where t.id_number is not null
                    -- and po.mispar_zehut is null   -- לא קיים כפורש 
                 and PK_INTERIOR.get_mpm_code_mazav_mishpachti(t.marital_status) <>
                     a.code_mazav_mishpachti
                 and a.code_mazav_mishpachti not in (8, 4)
                 and p.taarich_ptira is null
                 and p.code_relative is not null
                 and p.code_relative <> 99
                 and (p.to_date_sium_zakaut is null or
                     p.to_date_sium_zakaut > sysdate)
                    
                 and pk_interior.convert_string_to_date(t.marital_date) >
                     to_date('01012022', 'ddmmyyyy')
                 and pk_interior.convert_string_to_date(t.marital_date) >
                     a.date_mazav_mishpachti
               order by t.id_number) loop
      int_date := pk_interior.convert_string_to_date(r.marital_date);
      load_mazav_mishpachti_all(null,
                                r.seq_bney_mishpacha,
                                int_date,
                                PK_INTERIOR.get_mpm_code_mazav_mishpachti(r.marital_status));
      if  is_to_hilan(r.seq_porshim)>0 then
        open_bakasha_shinuy_mazav_mishpachti(r.seq_porshim,
                                             r.seq_bney_mishpacha);
     end if;
    end loop;
    commit;
  end;
