        ir.teur_ir || ' ' || adp.mikud as IrMikudPorsh
     into taarich, mispar_gimla,mispar_zehut,Shem_poresh,AddressPoresh,IrMikudPorsh
       from bakasha bb
        left join prisha pr  on pr.seq_prisha=bb.seq_prisha
        left join poresh p on p.porshim_seq=pr.seq_poresh
        left join v_last_address adp on adp.seq_poresh=p.porshim_seq and adp.seq_bakasha=bb.seq_bakasha
        left join code_ir ir on ir.code_ir=adp.code_city
      where bb.seq_bakasha=P_seq_bakasha;
end ishur_chaim;
------------------------------------------------------------------------------------------------
