create or replace package body prm_system_copy.pk_load is
  ------------------------------------------------
  function Get_count_errors(p_seq_ld_log number) return number is
    v_count_errors number;
  begin
    select count(*)
      into v_count_errors
      from ld_log_Details l
     where l.seq_ld_log = p_seq_ld_log
       and l.code_load_type_info = 1;
  
    return v_count_errors;
  end;

  ------------------------------------------------
  function Get_p_id(p_id varchar2, need_sheer boolean := false)
    return varchar2 is
    v_id number;
  begin
    if need_sheer then
      v_id := to_number(p_id);
      begin
        select p.mispar_zehut
          into v_id
          from poresh p
         where p.mispar_zehut = v_id;
      exception
        when no_data_found then
          select p.mispar_zehut
            into v_id
            from bney_mishpacha b
            left join poresh p
              on p.porshim_seq = b.seq_porshim
           where b.mispar_zehut_ben_mishpacha = v_id;
      end;
    
      return to_number(v_id);
    else
      return to_number(p_id);
    end if;
  exception
    when others then
      return to_number(p_id);
  end;

  ------------------------------------------------
  function Get_max_ld_log_for_id(p_id varchar2) return number is
    v_seq_ld_log number;
    v_id         varchar2(100);
  begin
    --begin
    v_id := Get_p_id(p_id); -- to_number(p_id);
    /*exception
      when others then
        v_id := p_id;
    end;*/
    --Get max seq_ld_log for id
    select max(l.seq_ld_log)
      into v_seq_ld_log
      from ld_log l
     where trim(l.id) = trim(v_id) or trim(l.id)=lpad(v_id,9,'0');
  
    return v_seq_ld_log;
  end;
  -----------------------------------------------
  procedure ld_log_details(p_code_load_msg       number,
                           p_more_details        varchar2,
                           p_table_name          varchar2,
                           p_field_name          varchar2,
                           p_value               varchar2,
                           p_seq_ld_log          number,
                           p_code_load_type_info number) is
    pragma autonomous_transaction;
  begin
    insert into ld_log_Details
      (seq_ld_log,
       table_name,
       field_name,
       value,
       code_load_msg,
       more_details,
       code_load_type_info,
       seq_ld_log_Details,
       date_create)
    values
      (p_seq_ld_log,
       p_table_name,
       p_field_name,
       p_value,
       p_code_load_msg,
       p_more_details,
       p_code_load_type_info,
       ld_log_Details_seq.nextval,
       sysdate);
    commit;
  end;
  ------------------------------------------------
  procedure Insert_error_by_system(p_seq_bakasha   number,
                                   p_code_load_msg number,
                                   p_more_details  varchar2) is
    v_seq_ld_log           number;
    v_teur_load_msg_timing number;
    v_more_detailes        varchar2(1000);
    v_mimshak_number       varchar2(1000);
  begin
    select max(l.seq_ld_log)
      into v_seq_ld_log
      from ld_log l
     where l.seq_bakasha = p_seq_bakasha;
  
    if v_seq_ld_log is null then
      --insert ld log
      v_seq_ld_log := ld_log_Details_seq.nextval;
    
      insert into ld_log
        (id,
         seq_bakasha,
         seq_ld_log,
         is_valid_finish_load,
         is_valid_finish_process)
        select v.mispar_zehut, p_seq_bakasha, v_seq_ld_log, 1, 1
          from v_bakasha v
         where v.SEQ_BAKASHA = p_seq_bakasha;
    
    else
      select '(mimshak number: ' || to_char(p.source_mimshak_number) || ')'
        into v_mimshak_number
        from ld_log l
        left join ld_protocol p
          on l.seq_ld_protokol_get - 1 = p.seq_ld_protocol
       where l.seq_ld_log = v_seq_ld_log;
    end if;
  
    select case t.code_load_msg
             when 2 then
              t2.teur_load_msg_timing || ', '
             else
              null
           end
      into v_teur_load_msg_timing
      from code_load_msg t
      left join code_load_msg_timing t2
        on t.code_load_msg_timing = t2.code_load_msg_timing
     where t.code_load_msg = p_code_load_msg;
  
    v_more_detailes := v_teur_load_msg_timing || p_more_details ||
                       v_mimshak_number;
  
    insert into ld_log_Details
      (seq_ld_log,
       code_load_msg,
       more_details,
       code_load_type_info,
       seq_ld_log_Details,
       date_create)
    values
      (v_seq_ld_log,
       p_code_load_msg,
       p_more_details,
       1,
       ld_log_Details_seq.nextval,
       sysdate);
    commit;
  end;
  ------------------------------------------------
  function Add_row_ld_log(p_seq_ld_protocol number, p_id varchar2)
    return number is
    pragma autonomous_transaction;
    v_id         varchar2(100);
    v_ld_log_seq number := ld_log_seq.nextval;
  begin
    v_id := Get_p_id(p_id);
    /*begin
      v_id := to_number(p_id);
    exception
      when others then
        v_id := p_id;
    end;*/
    insert into ld_log
      (id, seq_ld_protokol_get, seq_ld_log)
    values
      (v_id, p_seq_ld_protocol, v_ld_log_seq);
    commit;
    return v_ld_log_seq;
  end;
  ------------------------------------------------
  procedure restart_system_tables is
  begin
    --Truncate tables
    execute immediate 'Truncate table ld_temp_tkufot_avoda_golmi';
    execute immediate 'Truncate table ERR_Porshim';
    execute immediate 'Truncate table ERR_tkufot_sherut_tsvaii';
    execute immediate 'Truncate table err_bakasha_regila';
    execute immediate 'Truncate table ERR_tkufot_avoda_golmi';
    execute immediate 'Truncate table err_bney_mishpacha';
    execute immediate 'Truncate table err_tkufot_michutz_lasharut';
    execute immediate 'Truncate table err_action_log';
    execute immediate 'Truncate table err_hagdala_nimuk';
    execute immediate 'Truncate table err_netuney_tik_mechushavim';
    execute immediate 'Truncate table err_tkufot_avoda_mechushv';
    execute immediate 'Truncate table err_darga_vederug_tik';
    execute immediate 'Truncate table err_bakasha';
    execute immediate 'Truncate table err_prisha';
    execute immediate 'Truncate table err_chinuch_salary';
    execute immediate 'Truncate table err_vetek_detail';
  end;
  -----------------------------------------------------------
  procedure Update_seq_bakasha(p_old_seq_bakasha number, p_id number) is
    pragma autonomous_transaction;
    v_seq_ld_log number;
  begin
    v_seq_ld_log := Get_max_ld_log_for_id(p_id);
    --update seq_bakasha
    update ld_log l
       set seq_bakasha = p_old_seq_bakasha
     where l.seq_ld_log = v_seq_ld_log;
    commit;
  end;
  -----------------------------------------------------------
  procedure Insert_errors(p_id            varchar2,
                          p_code_load_msg number,
                          p_more_details  varchar2 default null,
                          p_table_name    varchar2 default null,
                          p_field_name    varchar2 default null,
                          p_value         varchar2 default null) is
    v_seq_ld_log number;
  begin
    --Get max seq_ld_log for id
    v_seq_ld_log := Get_max_ld_log_for_id(p_id);
  
    ld_log_details(p_code_load_msg,
                   p_more_details,
                   p_table_name,
                   p_field_name,
                   p_value,
                   v_seq_ld_log,
                   1);
  end;
