  end;
  -----------------------------------------------
  function Check_previos_bakasha(v_mispar_zehut        number,
                                 p_seq_ezor_ovdim      number,
                                 p_code_merge_bakasha  number,
                                 p_code_sug_bakasha    number default null,
                                 p_seq_beny_mishpacha  number default null,
                                 p_code_bakasha_detail number default null)
    return number is
    v_seq_bakasha_previos number;
  begin
    select max(v.seq_bakasha)
      into v_seq_bakasha_previos
      from v_bakasha_last_status v
      left join bakasha b
        on v.seq_bakasha = b.seq_bakasha
      left join code_sug_bakasha sb
        on sb.code_sug_bakasha = b.code_sug_bakasha
     where v.MISPAR_ZEHUT = v_mispar_zehut
       and v.seq_ezor_ovdim = p_seq_ezor_ovdim
          --seq_bney_mishpacha
       and nvl(b.seq_bney_mishpacha, 0) = nvl(p_seq_beny_mishpacha, 0)
          --consider bakasha details
       and (nvl(b.code_bakasha_detail, 0) = nvl(p_code_bakasha_detail, 0) or
           sb.consider_bakasha_details = 0)
          ---by code_merge_bakasha
       and (v.code_merge_bakasha = p_code_merge_bakasha
           --when code_merge_bakasha by code
           or (p_code_merge_bakasha is null and
           v.code_sug_bakasha = p_code_sug_bakasha)
           
           --for netuney_sachar
           or (p_code_sug_bakasha = 14 and v.code_sug_bakasha in (14, 1)))
          --when new bakasha is regila, not copy
       and nvl(p_code_sug_bakasha, 0) <> 1
          --not canceled bakasha          
       and v.code_action <> 17;
  
    return v_seq_bakasha_previos;
  exception
    when no_data_found then
      return null;
  end;
  -----------------------------------------------
  procedure merge_when_filter_is_not_get(p_old_seq_bakasha number,
                                         p_new_seq_bakasha number) is
  begin
  
    -- Tkufot_Avoda_Mechushv
    delete from Tkufot_Avoda_Mechushv
     where seq_bakasha = p_old_seq_bakasha;
  
    update Tkufot_Avoda_Mechushv
       set seq_bakasha = p_old_seq_bakasha
     where seq_bakasha = p_new_seq_bakasha;
  
    --tkufot_sherut_tsvaii
    delete from tkufot_sherut_tsvaii where seq_bakasha = p_old_seq_bakasha;
  
    update tkufot_sherut_tsvaii
       set seq_bakasha = p_old_seq_bakasha
     where seq_bakasha = p_new_seq_bakasha;
  
    --tkufot_sherut_tsvaii
    delete from tkufot_michutz_lasharut
     where seq_bakasha = p_old_seq_bakasha;
  
    update tkufot_michutz_lasharut
       set seq_bakasha = p_old_seq_bakasha
     where seq_bakasha = p_new_seq_bakasha;
  
    --Tkufot_Avoda_Golmi
    delete from Tkufot_Avoda_Golmi where seq_bakasha = p_old_seq_bakasha;
  
    update Tkufot_Avoda_Golmi
       set seq_bakasha = p_old_seq_bakasha
     where seq_bakasha = p_new_seq_bakasha;
  
    --hagdalot
    delete from hagdala_nimuk where seq_bakasha = p_old_seq_bakasha;
  
    update hagdala_nimuk
       set seq_bakasha = p_old_seq_bakasha
     where seq_bakasha = p_new_seq_bakasha;
  
    --darga_vederug_tik
    delete from darga_vederug_tik where seq_bakasha = p_old_seq_bakasha;
  
    update darga_vederug_tik
       set seq_bakasha = p_old_seq_bakasha
     where seq_bakasha = p_new_seq_bakasha;
  
    -- bakasha regila
    update bakasha_regila r
       set (r.chinuch_mikzoa, r.vetek) =
           (select chinuch_mikzoa, vetek
              from bakasha_regila
             where seq_bakasha = p_new_seq_bakasha)
     where r.seq_bakasha = p_old_seq_bakasha;
    --add remark
    pk_prm_utils.insert_action_log_row(31,
                                       sysdate,
                                       0,
                                       null,
                                       'התקבל ממשק חדש אך חישובי הזכאות זהים, עודכנו תקופות ודרוגים',
                                       null,
                                       null,
                                       null,
                                       p_old_seq_bakasha,
                                       null);
  
    -- run zakaut
    pk_zakaut.main(p_old_seq_bakasha);
  
    commit;
  end;
  ------------------------------------------------
  function is_difference_value(p_old_value  varchar2,
                               p_new_value  varchar2,
                               p_name_field varchar2,
                               p_difference number default null)
    return varchar2 is
  begin
    if p_old_value <> p_new_value then
      if p_difference is null or
         abs(p_old_value - p_new_value) > p_difference then
        return ' * ''' || p_name_field || ''' - ערך קודם: ' || p_old_value || ' ערך חדש: ' || p_new_value;
      end if;
    end if;
    return null;
  end;
  ------------------------------------------------
  function is_new_in_mechushavim(p_old_seq_bakasha number,
                                 p_new_seq_bakasha number,
                                 v_comments        out varchar2)
    return number is
    --chavi
    l_old_date_prisha     date;
    l_new_date_prisha     date;
    l_old_seif_prisha     number;
    l_new_seif_prisha     number;
    l_old_taarich_me      date;
    l_old_taarich_ad      date;
    l_old_code_sug_darga  number;
    l_old_code_darga      number;
    l_old_code_derug      number;
    l_old_code_darga_ofek number;
    l_old_code_derug_ofek number;
    l_new_taarich_me      date;
    l_new_taarich_ad      date;
    l_new_code_sug_darga  number;
    l_new_code_darga      number;
    l_new_code_derug      number;
    l_new_code_darga_ofek number;
    l_new_code_derug_ofek number;
    --
  begin
    --
    select br1.taarich_prisha,
           br2.taarich_prisha,
           br1.code_seif_prisha,
           br2.code_seif_prisha
      into l_old_date_prisha,
           l_new_date_prisha,
           l_old_seif_prisha,
           l_new_seif_prisha
      from bakasha_regila br1, bakasha_regila br2
     where br1.seq_bakasha = p_old_seq_bakasha
       and br2.seq_bakasha = p_new_seq_bakasha;
  begin
    select taarich_me,
           taarich_ad,
           code_sug_darga,
           code_darga,
           code_derug,
           code_darga_ofek,
           code_derug_ofek
      into l_old_taarich_me,
           l_old_taarich_ad,
           l_old_code_sug_darga,
           l_old_code_darga,
           l_old_code_derug,
           l_old_code_darga_ofek,
           l_old_code_derug_ofek
      from darga_vederug_tik
     where seq_bakasha = p_old_seq_bakasha
       and taarich_me =
           (select max(taarich_me)
              from darga_vederug_tik
             where seq_bakasha = p_old_seq_bakasha);
  
    select taarich_me,
           taarich_ad,
           code_sug_darga,
           code_darga,
           code_derug,
           code_darga_ofek,
           code_derug_ofek
      into l_new_taarich_me,
           l_new_taarich_ad,
           l_new_code_sug_darga,
           l_new_code_darga,
           l_new_code_derug,
           l_new_code_darga_ofek,
           l_new_code_derug_ofek
      from darga_vederug_tik
     where seq_bakasha = p_new_seq_bakasha
       and taarich_me =
           (select max(taarich_me)
              from darga_vederug_tik
             where seq_bakasha = p_new_seq_bakasha);
    --
    
    exception when no_data_found then
  l_old_code_sug_darga  :=0;
    l_old_code_darga     :=0;
    l_old_code_derug    :=0;
    l_old_code_darga_ofek :=0;
    l_old_code_derug_ofek :=0;

end;  
  
    for r in (select t1.code_group_prisha     old_code_group_prisha,
                     t1.achuz_kizba_sofi      old_achuz_kizba_sofi,
                     t1.chelkiyut_sofit       old_chelkiyut_sofit,
                     t1.is_zakai_lmaanak      old_is_zakai_lmaanak,
                     t1.odef_sherut_chodashim old_odef_sherut_chodashim,
                     t1.odef_sherut_yamim     old_odef_sherut_yamim,
                     t1.date_start_zakaut     old_date_start_zakaut,
                     t1.date_end_zakaut       old_date_end_zakaut,
                     t1.tkufa_mezaka_sherut   old_tkufa_mezaka_sherut,
                     t2.code_group_prisha     new_code_group_prisha,
                     t2.achuz_kizba_sofi      new_achuz_kizba_sofi,
                     t2.chelkiyut_sofit       new_chelkiyut_sofit,
                     t2.is_zakai_lmaanak      new_is_zakai_lmaanak,
                     t2.odef_sherut_chodashim new_odef_sherut_chodashim,
                     t2.odef_sherut_yamim     new_odef_sherut_yamim,
                     t2.date_start_zakaut     new_date_start_zakaut,
                     t2.date_end_zakaut       new_date_end_zakaut,
                     t2.tkufa_mezaka_sherut   new_tkufa_mezaka_sherut
                from netuney_tik_mechushavim t1, netuney_tik_mechushavim t2
               where t1.code_department = 2
                 and t1.mispar_misra = 0
                 and t2.code_department = 2
                 and t2.mispar_misra = 0
                 and t1.seq_bakasha = p_old_seq_bakasha
                 and t2.seq_bakasha = p_new_seq_bakasha) loop
    
      v_comments := is_difference_value(r.old_code_group_prisha,
                                        r.new_code_group_prisha,
                                        'סוג פרישה');
    
      v_comments := v_comments ||
                    is_difference_value(r.old_achuz_kizba_sofi,
                                        r.new_achuz_kizba_sofi,
                                        'אחוז קיצבה סופי');
    
      v_comments := v_comments ||
                    is_difference_value(r.old_chelkiyut_sofit,
                                        r.new_chelkiyut_sofit,
                                        'חלקיות סופית');
    
      v_comments := v_comments ||
                    is_difference_value(r.old_is_zakai_lmaanak,
                                        r.new_is_zakai_lmaanak,
                                        'האם זכאי למענק');
    
      v_comments := v_comments ||
                    is_difference_value(r.old_odef_sherut_chodashim,
                                        r.new_odef_sherut_chodashim,
                                        'עודף שרות חודשים');
    
      v_comments := v_comments ||
                    is_difference_value(r.old_odef_sherut_yamim,
                                        r.new_odef_sherut_yamim,
                                        'עודף שרות ימים');
    
      v_comments := v_comments ||
                    is_difference_value(r.old_date_start_zakaut,
                                        r.new_date_start_zakaut,
                                        'תאריך תחילת זכאות');
      v_comments := v_comments ||
                    is_difference_value(r.old_tkufa_mezaka_sherut,
                                        r.new_tkufa_mezaka_sherut,
                                        'תאריך מזכה בשירות');
    
    end loop;
    --
    v_comments := v_comments ||
                  is_difference_value(l_old_date_prisha,
                                      l_new_date_prisha,
                                      'תאריך פרישה');
  
    v_comments := v_comments ||
                  is_difference_value(l_old_seif_prisha,
                                      l_new_seif_prisha,
                                      'סעיף פרישה');
  
    v_comments := v_comments ||
                  is_difference_value(l_old_taarich_me,
                                      l_new_taarich_me,
                                      'תאריך מ');
  
    v_comments := v_comments ||
                  is_difference_value(l_old_taarich_ad,
                                      l_new_taarich_ad,
                                      'תאריך עד');
  
    v_comments := v_comments ||
                  is_difference_value(l_old_code_sug_darga,
                                      l_new_code_sug_darga,
                                      'קוד סוג דרגה');
  
    v_comments := v_comments ||
                  is_difference_value(l_old_code_darga,
                                      l_new_code_darga,
                                      'קוד דרגה');
  
    v_comments := v_comments ||
                  is_difference_value(l_old_code_derug,
                                      l_new_code_derug,
                                      'קוד דירוג');
  
    v_comments := v_comments ||
                  is_difference_value(l_old_code_darga_ofek,
                                      l_new_code_darga_ofek,
                                      'קוד דרגה אופק');
  
    v_comments := v_comments ||
                  is_difference_value(l_old_code_derug_ofek,
                                      l_new_code_derug_ofek,
                                      'קוד דירוג אופק');
  
    --                                    
    if v_comments is not null then
      return 1;
    else
      return 0;
    end if;
  
  end;
