  ------------------------------------------------
  function is_exist_participation_documnt(p_id number) return number is
    v_count_participation_documnt number;
    v_id                          varchar2(200);
  begin
    v_id := to_number(Get_p_id(to_char(p_id)));
    select count(*)
      into v_count_participation_documnt
      from ld_chinuch_document t
     where
    -- type document
     substr(t.document_name, instr(t.document_name, '_', 1, 3) + 1, 3) = 52
    -- id
     and substr(t.document_name, instr(t.document_name, '_', 1, 2) + 1, 9) = v_id
    
     and is_document_not_exist_to_id(v_id,
                                 52,
                                 --source number
                                 substr(t.document_name,
                                        instr(t.document_name, '_', 1, 4) + 1,
                                        8)) = 1;
  
    return v_count_participation_documnt;
  end;
  ------------------------------------------------
  function is_open_new_participation(p_id number, p_seq_bakasha number)
    return number is
    v_is_exist_zakaut             number := 0;
    v_is_exist_open_zakaut        number := 0;
    v_is_exist_open_participation number := 0;
    v_id                          number;
  begin
    v_id := to_number(Get_p_id(to_char(p_id)));
    for r in (select v2.*
                from v_bakasha_last_status v1
                left join v_bakasha_last_status v2
                  on v1.seq_prisha = v2.seq_prisha
               where v1.seq_bakasha = p_seq_bakasha
                 and v2.seq_bakasha <> p_seq_bakasha) loop
      if r.code_sug_bakasha in (1, 3, 5) then
        --There is exist zakaut
        v_is_exist_zakaut := 1;
        if pk_prm_utils.is_bakasha_was_not_confirmed(r.seq_bakasha, 1) = 1 then
          -- There is open zakaut
          v_is_exist_open_zakaut := 1;
        end if;
      elsif r.code_sug_bakasha = 7 and
            pk_prm_utils.is_bakasha_was_not_confirmed(r.seq_bakasha, 1) = 1 then
        -- There is open participation
        v_is_exist_open_participation := 1;
      end if;
      --04-08-2025 insert if into loop
      if is_exist_participation_documnt(v_id) = 1 and v_is_exist_zakaut = 1 and
         v_is_exist_open_zakaut = 0 and v_is_exist_open_participation = 0 then
        return 1;
      
      end if;
    end loop;
    return 0;
  end;

  ------------------------------------------------
  procedure Filter_By_compare_versions(new_seq_bakasha number,
                                       old_seq_bakasha number,
                                       p_id            varchar2,
                                       p_seq_ld_log    number) is
  
    v_is_new_in_mechushavim   number;
    v_is_open_participation   number;
    v_is_prev_open_in_gimlaot number;
    v_is_new_darga_derug_vetek number :=0;
    v_seq_ezor_ovdim           number;
    v_comment_mechushavim     varchar2(1000);
    v_comment_derug           varchar2(1000);
    v_id                      varchar2(100);
  begin
    v_id := Get_p_id(to_char(p_id));
  
    v_is_new_in_mechushavim := is_new_in_mechushavim(old_seq_bakasha,
                                                     new_seq_bakasha,
                                                     v_comment_mechushavim);
     select pr.seq_ezor_ovdim into v_seq_ezor_ovdim 
     from bakasha bk
     left join prisha pr
     on pr.seq_prisha=bk.seq_prisha
     where bk.seq_bakasha=new_seq_bakasha;
     if v_seq_ezor_ovdim<> 206 then 
       --לא משרד החינוך
      v_is_new_darga_derug_vetek := is_new_in_derug(old_seq_bakasha,
                                                     new_seq_bakasha,
                                                    v_comment_derug);
     end if;
  
  
    v_is_open_participation := is_open_new_participation(v_id,
                                                         new_seq_bakasha);
  
    --If all the comparisons is equals yet
    if v_is_new_in_mechushavim = 0 and v_is_open_participation = 0 and v_is_new_darga_derug_vetek =0 then
      --update seq bakasha
      Update_seq_bakasha(old_seq_bakasha, v_id);
      --insert error
      Insert_errors(v_id, 20008);
      --merge when filter is not get
      merge_when_filter_is_not_get(old_seq_bakasha, new_seq_bakasha);
    
    elsif Get_count_errors(p_seq_ld_log) = 0 then
    
      if v_is_new_in_mechushavim = 1 then
        --insert comment
        Insert_comments(v_id, 20011, v_comment_mechushavim);
      elsif  
        v_is_new_darga_derug_vetek = 1 then
        --insert comment
        Insert_comments(v_id, 20011, v_comment_derug);  
      elsif v_is_open_participation = 1 then
        --insert comment
        Insert_comments(v_id, 20015);
        
      
        --Update 
        update bakasha b
           set b.code_sug_bakasha = 7
         where b.seq_bakasha = new_seq_bakasha;
      
      end if;
    
    end if;
  
  end;
  ----------------------------------------------------------
  procedure add_err_table(p_table_name varchar2, p_id varchar2) is
  
    type typ_num_list is table of number;
  
    v_num_list typ_num_list;
  
    type typ_var_list is table of varchar2(2000);
    v_rowid_list typ_var_list;
    v_var_list   typ_var_list;
  
    v_cmd varchar2(1000);
  
    v_field varchar2(1000);
    v_mesg  varchar2(2000);
  
    v_first_position  number;
    v_second_position number;
  
    v_is_exist_mesg_in_table number;
  
    v_search_condition_long long;
    v_columns               varchar2(1000);
  
    v_sql_get_value varchar2(4000);
    v_value         varchar2(4000);
    v_values        varchar2(4000);
    v_id            varchar2(100);
  begin
    v_id := Get_p_id(p_id);
    --get the errors from the table
    v_cmd := 'select rowid ,ora_err_number$,ora_err_mesg$ from ' ||
             p_table_name;
  
    execute immediate v_cmd bulk collect
      into v_rowid_list, v_num_list, v_var_list;
  
    for i in 1 .. v_num_list.count() loop
    
      select count(*)
        into v_is_exist_mesg_in_table
        from code_load_msg t
       where t.code_load_msg = v_num_list(i);
    
      if v_is_exist_mesg_in_table > 0 then
        -- when is exist mesg in table, get the translate mesg from the table
        v_mesg   := null;
        v_values := null;
        --get the field from the orginal mesg
        v_field := v_var_list(i);
      
        v_first_position  := instr(v_field, '(') + 1;
        v_second_position := instr(v_field, ')');
      
        --get only specific detailes, not general mesg
        v_field := substr(v_field,
                          v_first_position,
                          v_second_position - v_first_position);
      
        --remove schema name and table name
        v_field := substr(v_field, instr(v_field, '.', -1) + 1);
      
        v_field   := replace(v_field, '"');
        v_columns := null;
      
        -- get check constaint detailes
        if v_num_list(i) = 2290 then
          select t.SEARCH_CONDITION
            into v_search_condition_long
            from user_constraints t
           where t.CONSTRAINT_NAME = v_field;
        
          v_field := substr(v_search_condition_long, 1, 2000) || ' [' ||
                     v_field || ']';
        
          -- get foreign key and primary key detailes
        elsif v_num_list(i) = 2291 or v_num_list(i) = 1 then
          for r in (select t.column_name
                      from user_cons_columns t
                     where t.constraint_name = v_field) loop
            select decode(v_columns,
                          null,
                          r.column_name,
                          v_columns || ',' || r.column_name)
              into v_columns
              from dual;
          end loop;
          v_field := v_columns || ' [' || v_field || ']';
        
          --get field name when numeric error
        elsif v_num_list(i) = 01722 then
          v_field := pk_load_mimshak.get_numeric_error(v_rowid_list(i),
                                                       p_table_name);
          --get field name when date error
        elsif v_num_list(i) = 01840 or v_num_list(i) = 01847 or
              v_num_list(i) = 01858 then
          v_field := pk_load_mimshak.get_date_error(v_rowid_list(i),
                                                    p_table_name);
        
        end if;
      
      else
        v_mesg := v_var_list(i);
      end if;
    
      --Get column name (without other expression)
      for r in (select t.COLUMN_NAME
                  from user_tab_cols t
                 where t.TABLE_NAME = p_table_name
                   and lower(nvl(v_field, v_var_list(i))) like
                       '%' || lower(t.COLUMN_NAME) || '%') loop
        --Get value
        v_sql_get_value := 'select ' || r.column_name || ' from ' ||
                           p_table_name || ' where rowid = ''' ||
                           v_rowid_list(i) || '''';
        execute immediate v_sql_get_value
          into v_value;
      
        select v_values || decode(v_values, null, '', v_values || ',') ||
               v_value
          into v_values
          from dual;
      end loop;
    
      --save the edited error in table 
      Insert_errors(v_id,
                    v_num_list(i),
                    v_mesg,
                    p_table_name => replace(upper(p_table_name),
                                            upper('ERR_')),
                    p_field_name => v_field,
                    p_value => v_values);
    end loop;
  
  end;
