  -----------------------------------------------
  procedure finish_load_and_commit(p_seq_ld_log  number,
                                   p_seq_bakasha number) is
    v_is_delete_bakasha varchar2(1000);
    v_final_seq_bakasha number;
  begin
    if Get_count_errors(p_seq_ld_log) = 0 then
      --update seq bakasha
      update ld_log l
         set seq_bakasha = p_seq_bakasha
       where l.seq_ld_log = p_seq_ld_log;
      --Insert action and commit
      pk_prm_utils.insert_actions_for_bakasha(p_seq_bakasha, 0);
    
    else
      --delete the new bakasha 
      --(and its include commit to update the old bakasha with tkufot and etc...)
      v_is_delete_bakasha := pk_prm_utils.delete_bakasha_without_commit(p_seq_bakasha);
      commit;
    end if;
  
    --update is_valid_finish_load
    update ld_log l
       set l.is_valid_finish_load = 1
     where l.seq_ld_log = p_seq_ld_log;
  
    commit;
  end;

  ----------------------------------------------------------
  function get_date_enter(v_seq_bakasha number) return date is
    v_date_min_from date;
  begin
    --Get the date
    select min(t.taarich_me)
      into v_date_min_from
      from tkufot_avoda_mechushv t
      left join code_sug_zchuyot_mechushavim z
        on t.code_sugey_zchuyot = z.code_sugey_zchuyot
     where t.seq_bakasha = v_seq_bakasha
       and z.haim_nirkash = 1
          --not 'chova' and 'tetzifut'
       and t.code_sugey_tkufot not in (5, 7);
  
    return v_date_min_from;
  end;
  ----------------------------------------------------------
  procedure compare_calculation_field(p_id          number,
                                      chinuch_value number,
                                      logist_value  number,
                                      field_name    varchar2
                                      --The balance field is the valid value that allowed between the values
                                      --of chinuch and logist
                                     ,
                                      balance number default 0) is
    final_chinuch_value number := nvl(chinuch_value, 0);
    final_logist_value  number := nvl(logist_value, 0);
    v_id                number;
  begin
    v_id := to_number(Get_p_id(p_id));
    if abs(final_chinuch_value - final_logist_value) > balance then
      Insert_warning(v_id,
                     20091,
                     p_more_details => 'Mapam:' || final_logist_value,
                     p_field_name   => field_name,
                     p_value        => final_chinuch_value);
    end if;
  end;
  ------------------------------------------------
  procedure Compare_calculation_data(p_seq_bakasha number) is
  begin
    --Compare  the fields from table:'Netuney_Tik_Mchushvim'  between the mpm calaulated
    -- and the data from 'chinuch'.
    for r in (select v.MISPAR_ZEHUT,
                     t3.seq_bakasha                  seq_bakasha_t3,
                     t2.achuz_kizba_kafuf_chelkiyut  achuz_kizba_kafuf_chelkiyut_1,
                     t3.achuz_kizba_kafuf_chelkiyut  achuz_kizba_kafuf_chelkiyut_2,
                     t2.tkufa_mezaka_sherut          tkufa_mezaka_sherut_1,
                     t3.tkufa_mezaka_sherut          tkufa_mezaka_sherut_2,
                     t2.chelkiyut_meshuklelet_sherut chelkiyut_meshuklelet_sherut_1,
                     t3.chelkiyut_meshuklelet_sherut chelkiyut_meshuklelet_sherut_2
              
                from netuney_tik_mechushavim t2
                left join netuney_tik_mechushavim t3
                  on t2.SEQ_BAKASHA = t3.seq_bakasha
                 and t3.code_department = 2
                 and t3.mispar_misra = 0
                left join v_bakasha v
                  on v.SEQ_BAKASHA = t2.seq_bakasha
               where t2.seq_bakasha = p_seq_bakasha
                 and t2.code_department = 1) loop
    
      -- No data found for this tik in 'netuney_tik_mechushavim' table.  
      if r.seq_bakasha_t3 is null then
        Insert_warning(r.mispar_zehut, 20090);
      
        -- This tik have a data 
      elsif r.seq_bakasha_t3 is not null then
      
        compare_calculation_field(r.mispar_zehut,
                                  r.achuz_kizba_kafuf_chelkiyut_1,
                                  r.achuz_kizba_kafuf_chelkiyut_2,
                                  'achuz_kizba_kafuf_chelkiyut');
      
        compare_calculation_field(r.mispar_zehut,
                                  r.tkufa_mezaka_sherut_1,
                                  r.tkufa_mezaka_sherut_2,
                                  'tkufa_mezaka_sherut');
      
        compare_calculation_field(r.mispar_zehut,
                                  r.chelkiyut_meshuklelet_sherut_1,
                                  r.chelkiyut_meshuklelet_sherut_2,
                                  'chelkiyut_meshuklelet_sherut');
      
      end if;
    
    end loop;
  end;
  -----------------------------------------------
  procedure calculation_data(p_seq_bakasha number) is
  
  begin
    --tkufot mechushavot
    calc_tkufot_mechushav(p_seq_bakasha);
    --ntuny_tik_mchshvim
    pk_zakaut.internal_main(p_seq_bakasha);
    --compare
    Compare_calculation_data(p_seq_bakasha);
  
  end;
  ------------------------------------------------
  function is_document_not_exist_to_id(p_id                 number,
                                       P_Document_Type      number,
                                       p_source_document_id number)
    return number is
    p_is_active number;
    v_id        number;
  begin
    v_id := to_number(Get_p_id(p_id));
    --When there is already exist same document,
    -- the new document is not active.
    select case
             when count(*) = 0 then
              1
             else
              0
           end
      into p_is_active
      from document_bakasha db
      left join document d
        on d.seq_document = db.seq_document
      left join v_bakasha v
        on db.seq_bakasha = v.SEQ_BAKASHA
     where v.MISPAR_ZEHUT = p_Id
       and d.seq_document_type = P_Document_Type
       and d.source_document_id = p_source_document_id
       and db.pail = 1;
    return p_is_active;
  end;
  ------------------------------------------------
  procedure document_detailes_befor_save(p_id                 number,
                                         p_document_name      varchar2,
                                         P_Document_Type      number,
                                         p_source_document_id number,
                                         P_Subject            out varchar2,
                                         p_maor_folder        out varchar2,
                                         p_is_active          out number) is
    v_id number;
  begin
    v_id := to_number(get_p_id(p_id));
    --Check if exist bakasha to the id.
    select decode(max(v.seq_bakasha), null, 0, 1)
      into p_is_active
      from v_bakasha v
     where v.mispar_zehut = v_id
    /*or v.mispar_zehut =
    (select p.mispar_zehut
    from bney_mishpacha b
    left join poresh p on p.porshim_seq = b.seq_porshim
    where b.mispar_zehut_ben_mishpacha = p_id
    and b.code_relative is not null)*/
    ;
  
    if p_is_active = 1 then
      begin
        select g.teur_document_type, g.maor_folder
          into P_Subject, p_maor_folder
          from code_document_type g
         where g.seq_document_type = P_Document_Type;
      exception
        when no_data_found then
          if p_source_document_id is not null then
            --save the edited error in table 
            Insert_warning(v_id, 20051, p_value => p_document_name);
          end if;
      end;
      if p_source_document_id is not null then
        p_is_active := is_document_not_exist_to_id(v_id,
                                                   P_Document_Type,
                                                   p_source_document_id);
      end if;
    end if;
  end;
  
