  procedure Add_document_not_absorbe_chinuch_salary is
    begin
        for rec in (
            select l.seq_ld_chinuch_salary_doc,
                   l.p_id,
                   l.p_date_create,
                   l.p_document_url
            from ld_chinuch_salary_documents l 
            where l.status = 3
        ) loop
            Add_document_chinuch_salary(
                rec.p_id,
                rec.p_date_create,
                rec.p_document_url,
                rec.seq_ld_chinuch_salary_doc
            );
        end loop;
    end;
  ----------------------------------------------------------
  procedure Add_document_chinuch_salary(p_id number,
                                      p_date_create  date,
                                      p_document_url varchar2,
                                       p_seq_doc_row  number default null) is
  v_seq_document         number;
  v_seq_document_bakasha number;
  v_seq_bakasha          number;
  v_code_merge_bakasha   number;
  v_count_action_log     number;
  v_id                   number;
begin

  begin
    v_id := to_number(get_p_id(p_id));

    -- Get the last bakasha by code_sug_bakasha in (14,1) and id_poresh
    select max(b.seq_bakasha)
      into v_seq_bakasha
      from poresh p
      left join prisha pr
        on pr.seq_poresh = p.porshim_seq
      left join bakasha b
        on b.seq_prisha = pr.seq_prisha
      left join v_bakasha_last_status v
        on v.seq_bakasha = b.seq_bakasha
     where b.code_sug_bakasha in (14, 1)
       and p.mispar_zehut = v_id
       and v.code_action <> 17;
  exception
    when others then
      v_seq_bakasha := null;
  end;

  -- אם לא נמצאה בקשה  שמירה בטבלת ld_chinuch_salary_documents בלבד, ויציאה
  if v_seq_bakasha is null then
    if p_seq_doc_row is null then
      -- הכנסת רשומה חדשה רק אם לא קיים seq קודם
      insert into ld_chinuch_salary_documents (
        seq_ld_chinuch_salary_doc,
        p_id,
        p_date_create,
        p_document_url,
        status
      ) values (
        ld_chinuch_salary_documents_seq.nextval,
        p_id,
        sysdate,
        p_document_url,
        3
      );
      commit;
    end if;
    return;
  end if;

  -- המשך רגיל אם נמצאה בקשה
  v_seq_document         := document_seq.nextval;
  v_seq_document_bakasha := document_bakasha_seq.nextval;

  insert into document
    (seq_document,
     seq_document_type,
     document_url,
     teur,
     date_update,
     code_user,
     date_create,
     code_department)
  values
    (v_seq_document,
     34,
     p_document_url,
     'תלוש משכורת משרד',
     sysdate,
     0,
     p_date_create,
     3);

  insert into document_bakasha
    (seq_document_bakasha, seq_document, seq_bakasha, pail)
  values
    (v_seq_document_bakasha, v_seq_document, v_seq_bakasha, 1);

  -- הוספת הערה
  pk_prm_utils.insert_action_log_row(300,
                                     sysdate,
                                     0,
                                     null,
                                     null,
                                     null,
                                     null,
                                     null,
                                     v_seq_bakasha,
                                     null);
                                     
  if p_seq_doc_row is not null then
    update ld_chinuch_salary_documents
       set status = 1
     where seq_ld_chinuch_salary_doc = p_seq_doc_row;
  end if;

  commit;

exception
  when others then
    rollback;
end;



  ----------------------------------------------------------
  procedure Add_document_Hilan(p_id            number,
                               p_date_create   date,
                               P_Document_Type number,
                               p_document_url  varchar2,
                               p_Subject       varchar2,
                               p_is_active     number,
                               p_mis_gimla     number) is
    v_seq_document         number;
    v_seq_document_bakasha number;
    v_seq_bakasha          number;
    v_code_merge_bakasha   number;
    v_count_action_log     number;
    v_id                   number;
  begin
  
    begin
      v_id := to_number(get_p_id(p_id, true));
      select s.code_merge_bakasha
        into v_code_merge_bakasha
        from perm_document_by_bakasha p
        left join code_sug_bakasha s
          on s.code_sug_bakasha = case
               when p.code_sug_bakasha = 99 then
                1
               else
                p.code_sug_bakasha
             end
       where p.seq_document_type = P_Document_Type;
    
      --Get the last bakasha by code merge bakasha to the id
      select max(v.seq_bakasha)
        into v_seq_bakasha
        from v_bakasha_last_status v
       where v.gimla_number = nvl(nullif(p_mis_gimla, 0), v.gimla_number)
         and (v.mispar_zehut = v_id
             /*or v.mispar_zehut =
             (select p.mispar_zehut
             from bney_mishpacha b
             left join poresh p on p.porshim_seq = b.seq_porshim
             where b.mispar_zehut_ben_mishpacha = p_id
             and b.code_relative is not null)*/
             )
         and v.code_merge_bakasha = v_code_merge_bakasha
         and nvl(v.code_department_action, 0) <> 1;
    exception
      when others then
        v_seq_bakasha := null;
    end;
  
    --When no exist specific code merge bakasha to the id,
    --Save in the last bakasha.
    if v_seq_bakasha is null then
      select max(v.seq_bakasha)
        into v_seq_bakasha
        from v_bakasha_last_status v
       where (v.mispar_zehut = v_id
             /*or v.mispar_zehut =
             (select p.mispar_zehut
             from bney_mishpacha b
             left join poresh p on p.porshim_seq = b.seq_porshim
             where b.mispar_zehut_ben_mishpacha = p_id
             and b.code_relative is not null)*/
             )
         and v.gimla_number = nvl(p_mis_gimla, v.gimla_number);
    end if;
  
    --When no exist specific code merge bakasha to the id,
    --Save in the last bakasha.
    if v_seq_bakasha is null then
      select max(v.seq_bakasha)
        into v_seq_bakasha
        from v_bakasha_last_status v
       where (v.mispar_zehut = v_id
             /*or v.mispar_zehut =
             (select p.mispar_zehut
             from bney_mishpacha b
             left join poresh p on p.porshim_seq = b.seq_porshim
             where b.mispar_zehut_ben_mishpacha = p_id
             and b.code_relative is not null)*/
             );
    end if;
  
    v_seq_document         := document_seq.nextval;
    v_seq_document_bakasha := document_bakasha_seq.nextval;
  
    insert into document
      (seq_document,
       seq_document_type,
       document_url,
       teur,
       date_update,
       code_user,
       date_create,
       code_department)
    values
      (v_seq_document,
       P_Document_Type,
       p_document_url,
       p_Subject,
       sysdate,
       0,
       p_date_create,
       3);
  
    insert into document_bakasha
      (seq_document_bakasha, seq_document, seq_bakasha, pail)
    values
      (v_seq_document_bakasha, v_seq_document, v_seq_bakasha, p_is_active);
  
    select count(*)
      into v_count_action_log
      from action_log a
     where a.code_action = 176
       and a.seq_bakasha = v_seq_bakasha
       and a.date_action = trunc(sysdate);
  
    if v_count_action_log = 0 then
      --add remark
      pk_prm_utils.insert_action_log_row(176,
                                         sysdate,
                                         0,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha,
                                         null);
    
    end if;
    commit;
  
  exception
    when others then
      rollback;
    
  end;
  ----------------------------------------------------------
  procedure Add_document_electronic(p_id                 number,
                                    p_document_name      varchar2,
                                    p_date_create        date,
                                    p_page_count         number,
                                    P_Document_Type      number,
                                    p_Full_Path          varchar2,
                                    p_Subject            varchar2,
                                    p_source_document_id number,
                                    p_is_active          number) is
    v_seq_document                   number;
    v_seq_document_bakasha           number;
    v_seq_bakasha                    number;
    v_code_sug_bakasha               number;
    v_code_sug_workflow              number;
    v_seq_ld_log                     number;
    v_count_msg_20008                number;
    v_last_action_in_first_step_2_wf number;
    v_current_action                 number;
    v_seq_ezor_ovdim                 number;
    v_code_action_prev               number;
    v_is_hazlava                      number;
  begin
    -- get the last open bakasha
    -- Preference for participation
    with t as
     (select /*+materialize */
       v.code_sug_bakasha,
       v.seq_bakasha,
       v.code_sug_workflow,
       v.code_action,
       pk_prm_utils.is_bakasha_was_not_confirmed(v.seq_bakasha, 1) not_confirmed
        from v_bakasha_last_status v
       where v.mispar_zehut = p_id
         and v.code_sug_bakasha in (1, 3, 5, 7))
    select code_sug_bakasha, seq_bakasha, code_sug_workflow, code_action
      into v_code_sug_bakasha,
           v_seq_bakasha,
           v_code_sug_workflow,
           v_current_action
      from t
     order by not_confirmed    desc,
              code_sug_bakasha desc fetch first 1 rows only;
  
    if trim(p_Full_Path) is null then
      --save the edited error in table 
      Insert_warning(p_id, 20052, p_value => p_document_name);
    end if;
  
    v_seq_document         := document_seq.nextval;
    v_seq_document_bakasha := document_bakasha_seq.nextval;
  
    insert into document
      (seq_document,
       seq_document_type,
       document_url,
       teur,
       date_update,
       code_user,
       page_count,
       date_create,
       source_document_id,
       code_role,
       code_department)
    values
      (v_seq_document,
       P_Document_Type,
       p_Full_Path,
       p_Subject,
       sysdate,
       0,
       p_page_count,
       p_date_create,
       p_source_document_id,
       15,
       3);
  
    insert into document_bakasha
      (seq_document_bakasha, seq_document, seq_bakasha, pail)
    values
      (v_seq_document_bakasha, v_seq_document, v_seq_bakasha, p_is_active);
  
    v_seq_ld_log := Get_max_ld_log_for_id(p_id);
  
    --Check If the id have an error : 'it is same data as previous version'
    select count(*)
      into v_count_msg_20008
      from ld_log_details t
     where t.seq_ld_log = v_seq_ld_log
       and t.code_load_msg = 20008;
  
    if v_count_msg_20008 > 0 then
      --change the error to comment.
      update ld_log_details t
         set t.code_load_msg = 20013, t.code_load_type_info = 2
       where t.seq_ld_log = v_seq_ld_log
         and t.code_load_msg = 20008;
    
      --add remark
      pk_prm_utils.insert_action_log_row(31,
                                         sysdate,
                                         0,
                                         null,
                                         'התקבל מסמך חדש - ' || p_Subject,
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha,
                                         null);
    
    end if;
  
    --12/01/2023                             שחרור בקשה של חינוך מורים מהדחיה בהגעת מסמך חדש 
    --new documents for education
    --if v_current_action_in_out in () then
    select v.seq_ezor_ovdim
      into v_seq_ezor_ovdim
      from v_bakasha_last_status v
     where v.seq_bakasha = v_seq_bakasha; --v_seq_bakasha_in_out;
    select a.code_action
      into v_code_action_prev
      from action_log a
     where a.seq_action_log = (select max(a1.seq_action_log)
                                 from action_log a1
                                 left join code_action c1
                                   on c1.code_action = a1.code_action
                                where a1.seq_bakasha = v_seq_bakasha --v_seq_bakasha_in_out
                                     --and a1.code_action <> v_current_action_in_out
                                  and c1.is_status = 1);
    if v_seq_ezor_ovdim = 206 and v_code_action_prev = 100 then
      select count(*) into v_is_hazlava from action_log a
      where a.seq_bakasha= v_seq_bakasha and a.code_action = 27; 
      if v_is_hazlava > 0 then    
            pk_prm_utils.insert_action_log_row(19,
                                         sysdate,
                                         null,
                                         null,
                                         'לשחחר את הבקשה מהמצב דחיה',
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha /*_in_out*/,
                                         null);
      commit;
      else
         pk_prm_utils.insert_action_log_row(86,
                                         sysdate,
                                         null,
                                         null,
                                         'לשחחר את הבקשה מהמצב דחיה',
                                         null,
                                         null,
                                         null,
                                         v_seq_bakasha /*_in_out*/,
                                         null);
      end if;
    end if;
    --12/01/2023     
    --end if;
  
    select w.code_action
      into v_last_action_in_first_step_2_wf
      from workflow w
     where w.code_sug_workflow = v_code_sug_workflow
       and w.is_automatic = 0
     order by w.order_wf fetch first 1 rows only;
  
    if v_code_sug_bakasha <> 7 and P_Document_Type = 52 and
       v_current_action not in (v_last_action_in_first_step_2_wf, 98) then
      --When the bakasha is zakaut, restore the workflow to the begin
      pk_prm_utils.Add_next_action(v_seq_bakasha,
                                   0,
                                   v_code_sug_workflow,
                                   null);
    end if;
  
    commit;
  
  exception
    when others then
      rollback;
    
      --save the edited error in table 
      Insert_errors(p_id, sqlcode, sqlerrm, p_value => p_document_name);
    
  end;
  --------------------------------------------------
  procedure Check_missing_document is
  begin
  
    for r1 in (select l.seq_bakasha, l.id
                 from ld_log l
                where l.is_valid_finish_process = 0
                  and (select count(*)
                         from ld_log_Details ld
                        where ld.seq_ld_log = l.seq_ld_log
                          and ld.code_load_type_info = 1) = 0) loop
    
      for r in (select distinct t.seq_document_type, d.teur_document_type
                  from v_bakasha_last_status v
                  left join code_seif_prisha s
                    on v.code_seif_prisha = s.code_seif_prisha
                  left join perm_document_by_bakasha t
                    on (t.code_group_prisha = s.code_group_prisha or
                       t.code_group_prisha is null)
                  left join code_document_type d
                    on t.seq_document_type = d.seq_document_type
                --Checking required documents only regular bakasha
                 where v.code_sug_bakasha = 1
                      --when there is a new data
                   and v.code_action = 122
                   and t.is_must = 1
                   and t.code_department = 3
                   and v.seq_bakasha = r1.seq_bakasha
                   and t.seq_document_type not in
                       (select distinct d.seq_document_type
                          from v_documents_2_current_and_prev vd
                          left join document d
                            on vd.seq_document = d.seq_document
                         where vd.current_seq_bakasha = v.seq_bakasha
                           and vd."SEQ_DOCUMENT" is not null)) loop
      
        --save the edited error in table 
        Insert_errors(r1.id,
                      20050,
                      p_value        => r.seq_document_type,
                      p_more_details => r.teur_document_type);
      end loop;
    end loop;
  end;
  -----------------------------------------------
  function get_edit_log_row(p_is_html_format     number,
                            p_seq_ld_log_Details number) return varchar2 is
    v_log_edited  varchar2(4000);
    v_msg_details varchar2(4000);
  begin
    for t in (select *
                from ld_log_Details l
               where l.seq_ld_log_Details = p_seq_ld_log_Details) loop
    
      if t.table_name is not null then
        v_log_edited := t.table_name || '.';
      end if;
      if t.field_name is not null then
        v_log_edited := v_log_edited || t.field_name || ': ';
      end if;
      if t.value is not null and p_is_html_format = 1 then
        v_log_edited := v_log_edited || '<b>' || t.value || '</b>';
      end if;
    
      if t.code_load_msg is not null then
        begin
          --Get err mesg by num
          select decode(t2.code_load_msg_timing,
                        1,
                        '',
                        t2.teur_load_msg_timing || ': ') ||
                 t1.teur_load_msg ||
                 decode(t.more_details, null, '', ' - ' || t.more_details)
            into v_msg_details
            from code_load_msg t1
            left join code_load_msg_timing t2
              on t1.code_load_msg_timing = t2.code_load_msg_timing
           where t1.code_load_msg = t.code_load_msg;
        exception
          when no_data_found then
            --when the code is not exist in the table
            v_msg_details := t.more_details;
        end;
      
      end if;
    
      if v_msg_details is not null then
        v_log_edited := v_log_edited ||
                       --When it is for html, add html tag
                        case
                          when p_is_html_format = 1 then
                           '<br/>'
                        end || v_msg_details;
      end if;
    
    end loop;
    return lower(v_log_edited);
  end;
  ----------------------------------------------------------
  function Get_merge_log_for_subject(p_is_html_format        number,
                                     p_seq_ld_log            number,
                                     p_code_load_info_type   number,
                                     p_code_load_subject     number default null,
                                     p_is_send_internal_mail number default 0)
    return varchar2 is
    v_merge_log varchar2(32767);
  begin
    for r in (select max(ld.seq_ld_log_Details) seq_ld_log_Details
                from ld_log_Details ld
                left join ld_log l
                  on ld.seq_ld_log = l.seq_ld_log
                left join code_load_msg m
                  on ld.code_load_msg = m.code_load_msg
               where ld.seq_ld_log = p_seq_ld_log
                 and ld.seq_ld_protokol_send_log is null
                 and ld.code_load_type_info = p_code_load_info_type
                 and (p_code_load_subject is null or
                     --when it is ora error (and not in the code_load_msg table), there is data error (1)
                     nvl(m.code_load_subject, 1) = p_code_load_subject)
                 and (p_is_send_internal_mail = 0 or
                     m.is_send_when_internal_mail = 1)
               group by ld.table_name,
                        ld.field_name,
                        ld.value,
                        ld.code_load_msg,
                        ld.more_details,
                        ld.code_load_type_info) loop
      if v_merge_log is not null then
        begin
          v_merge_log := v_merge_log ||
                        --When it is for html, add html tag
                         case
                           when p_is_html_format = 1 then
                            '<br/><br/>'
                           else
                            ', '
                         end;
        exception
          when others then
            v_merge_log := v_merge_log;
        end;
      end if;
      begin
        v_merge_log := v_merge_log ||
                       get_edit_log_row(p_is_html_format,
                                        r.seq_ld_log_Details);
      exception
        when others then
          v_merge_log := v_merge_log;
      end;
    end loop;
  
    return v_merge_log;
  
    /* dbms_output.put_line(to_char(p_seq_ld_log));
    dbms_output.put_line(to_char(p_code_load_info_type));
    dbms_output.put_line(to_char(p_code_load_subject));
    dbms_output.put_line(to_char(p_is_send_internal_mail));*/
  
  end;
  ----------------------------------------------------------
  procedure Insert_action_End_process(p_seq_ld_log  number,
                                      p_seq_bakasha number,
                                      p_load        varchar2,
                                      p_documents   varchar2) is
    v_code_action_bakasha       number;
    v_code_action_rejected      number := 100;
    v_code_action_regular       number := 122;
    v_teur_remark               varchar2(1000);
    v_is_zakaut_change          number := 0;
    v_is_action_bfor_wat_gmlaot number := 0;
  begin
    --The new bakasha no have errors
    if p_load is null and p_documents is null then
      --add remark
      select string_agg(m.teur_load_msg || ' ' || d.more_details)
        into v_teur_remark
        from ld_log_details d
        left join code_load_msg m
          on d.code_load_msg = m.code_load_msg
       where d.seq_ld_log = p_seq_ld_log
         and d.code_load_msg in (20011, 20014);
    
      if v_teur_remark is not null then
        v_teur_remark := 'התקבל מידע חדש ' || ' - ' || v_teur_remark;
        pk_prm_utils.insert_action_log_row(31,
                                           sysdate,
                                           0,
                                           null,
                                           v_teur_remark,
                                           null,
                                           null,
                                           null,
                                           p_seq_bakasha,
                                           null);
      end if;
    
      --Check old status bakasha
      select s.code_action
        into v_code_action_bakasha
        from v_bakasha_last_status s
       where s.seq_bakasha = p_seq_bakasha;
    
      --When the action is regular
      if v_code_action_bakasha = v_code_action_regular then
        --Add next action as 
        pk_prm_utils.insert_actions_for_bakasha(p_seq_bakasha);
      else
        select count(*)
          into v_is_zakaut_change
          from ld_log_details d
         where d.seq_ld_log = p_seq_ld_log
           and d.code_load_msg = 20011;
      
        v_is_action_bfor_wat_gmlaot := pk_prm_utils.is_action_bakash_bfor_specific(p_seq_bakasha,
                                                                                   19);
      
        if v_is_zakaut_change > 0 and v_is_action_bfor_wat_gmlaot = 0 then
          --Return the bakasha to the regular WF.
          pk_prm_utils.insert_action_log_row(19,
                                             sysdate,
                                             0,
                                             null,
                                             null,
                                             null,
                                             null,
                                             null,
                                             p_seq_bakasha,
                                             null);
        end if;
      end if;
    elsif p_load is null and p_documents is not null then
      --There is error when save documents only.
      pk_prm_utils.insert_action_log_row(v_code_action_rejected,
                                         sysdate,
                                         0,
                                         null,
                                         p_documents,
                                         null,
                                         null,
                                         null,
                                         p_seq_bakasha,
                                         null);
    
    end if;
    commit;
  end;
  -----------------------------------------------
  procedure update_end_in_DB(p_seq_ld_protocol number,
                             p_seq_bakasha     number,
                             p_load            varchar2,
                             p_documents       varchar2,
                             p_seq_ld_log      number) is
  begin
    --insert action
    Insert_action_End_process(p_seq_ld_log,
                              p_seq_bakasha,
                              p_load,
                              p_documents);
  
    -- update is send log to source
    update ld_log_Details t
       set t.seq_ld_protokol_send_log = p_seq_ld_protocol
     where t.seq_ld_log = p_seq_ld_log
       and t.seq_ld_protokol_send_log is null;
  
    update ld_log l
       set l.is_valid_finish_process = 1
     where l.seq_ld_log = p_seq_ld_log;
  
    commit;
  end update_end_in_DB;
  -----------------------------------------------
  function Get_report(p_seq_ld_protocol       number,
                      p_count_success         out NUMBER,
                      p_count_warnings        out number,
                      p_count_errors          out NUMBER,
                      p_log                   out clob,
                      p_is_send_internal_mail number,
                      p_code_process          number) return clob is
  
    v_html_body clob;
    v_ok_icon   varchar2(1000) := '<center><span class="glyphicon glyphicon-ok" aria-hidden="true"></span></center>';
  begin
    p_count_success  := 0;
    p_count_warnings := 0;
    p_count_errors   := 0;
  
    for t1 in (select *
                 from (select l.id id,
                              l.seq_ld_log,
                              l.seq_bakasha,
                              Get_merge_log_for_subject(1,
                                                        l.seq_ld_log,
                                                        1,
                                                        1,
                                                        p_is_send_internal_mail) load,
                              Get_merge_log_for_subject(1,
                                                        l.seq_ld_log,
                                                        1,
                                                        2,
                                                        p_is_send_internal_mail) documents,
                              Get_merge_log_for_subject(0,
                                                        l.seq_ld_log,
                                                        1,
                                                        2,
                                                        p_is_send_internal_mail) documets_not_html,
                              Get_merge_log_for_subject(1,
                                                        l.seq_ld_log,
                                                        2,
                                                        null,
                                                        p_is_send_internal_mail) warnings,
                              Get_merge_log_for_subject(1,
                                                        l.seq_ld_log,
                                                        3,
                                                        null,
                                                        p_is_send_internal_mail) comments
                       
                         from ld_log l
                         left join ld_protocol p
                           on l.seq_ld_protokol_get = p.seq_ld_protocol
                        where l.date_delete is null
                             
                          and p.code_process is not null
                          and p_code_process is not null
                          and p.code_process = p_code_process
                             
                          and (l.is_valid_finish_process = 0 or
                              (p_code_process = 2 and
                              (select count(*)
                                   from ld_log_Details t
                                  where t.seq_ld_log = l.seq_ld_log
                                    and t.seq_ld_protokol_send_log is null) > 0)))
                where p_is_send_internal_mail = 0
                   or (load is not null or documents is not null)) loop
    
      --Add row to log
      p_log := p_log ||
               pk_create_mimshak_out.create_mimshak_log_load_1(t1.seq_ld_log);
    
      --Add row to HTML
    
      if t1.load is not null or t1.documents is not null then
        --Add to errors counter
        p_count_errors := p_count_errors + 1;
        --Define danger view row
        v_html_body := v_html_body || '<tr class="danger">';
      elsif t1.warnings is not null then
        --Add to warning counter
        p_count_warnings := p_count_warnings + 1;
        --Define warning view row
        v_html_body := v_html_body || '<tr class="warning">';
      else
        --Add to success counter
        p_count_success := p_count_success + 1;
        --Define success view row
        v_html_body := v_html_body || '<tr>';
      end if;
    
      -- Id
      v_html_body := v_html_body || '<td><strong>' || t1.id ||
                     '</strong></td>';
      --load_data_errors
    
      v_html_body := v_html_body || '<td>' || nvl(t1.load, v_ok_icon) ||
                     '</td>';
      --documents             
      v_html_body := v_html_body || '<td>';
      if t1.load is null and t1.documents is null then
        v_html_body := v_html_body || v_ok_icon;
      else
        v_html_body := v_html_body || t1.documents;
      end if;
      v_html_body := v_html_body || '</td>';
      --warnings
      v_html_body := v_html_body || '<td>' || t1.warnings || '</td>';
      --comments
      v_html_body := v_html_body || '<td>' || t1.comments || '</td>';
    
      v_html_body := v_html_body || '</tr>';
    
      if p_is_send_internal_mail = 0 then
      
        update_end_in_DB(p_seq_ld_protocol,
                         t1.seq_bakasha,
                         t1.load,
                         t1.documents,
                         t1.seq_ld_log);
      end if;
    
    end loop;
  
    return v_html_body;
  end;
  -----------------------------------------------
  function End_process(p_seq_ld_protocol       number,
                       p_count_success         OUT NUMBER,
                       p_count_warnings        out number,
                       p_count_errors          OUT NUMBER,
                       p_log                   out clob,
                       v_html_body_only_errors out clob) return clob is
    v_html_body    clob := '';
    v_code_process number;
  begin
    p_count_success  := 0;
    p_count_warnings := 0;
    p_count_errors   := 0;
  
    if p_seq_ld_protocol is not null then
      --Get code process by ld_protocol
      select l.code_process
        into v_code_process
        from ld_protocol l
       where l.seq_ld_protocol = p_seq_ld_protocol;
    end if;
  
    for v in (select *
                from ld_log l
               where l.is_valid_finish_process = 0
                 and nvl(l.is_valid_finish_load, 0) = 0) loop
      Insert_errors(v.id, 20012);
    end loop;
  
    v_html_body_only_errors := Get_report(p_seq_ld_protocol,
                                          p_count_success,
                                          p_count_warnings,
                                          p_count_errors,
                                          p_log,
                                          1,
                                          v_code_process);
  
    v_html_body := Get_report(p_seq_ld_protocol,
                              p_count_success,
                              p_count_warnings,
                              p_count_errors,
                              p_log,
                              0,
                              v_code_process);
    return v_html_body;
  
  end;
  -----------------------------------------------
  function convert_code_sugey_zchuyot(p_code_sugey_zchuyot number)
    return number is
  begin
  
    return case p_code_sugey_zchuyot when 1 then 2 when 2 then 7 when 3 then 13 when 6 then 4 when 7 then 8 when 10 then 5 when 13 then 15 when 67 then 16 when 68 then 1 when 69 then 18 when 70 then 3 when 71 then 19 when 72 then 20 end;
  
  end;
  -----------------------------------------------
  procedure Insert_tkufot_mechushav(p_taarich_me                  date,
                                    p_taarich_ad                  date,
                                    p_achuz_chelkyut              number,
                                    p_praklit                     number,
                                    p_haim_kana_zchuyot           number,
                                    p_code_sugey_tkufot           number,
                                    p_code_sugey_haasaka          number,
                                    p_code_sugey_zchuyot          number,
                                    p_seq_tkufot_avoda_mechushv   number,
                                    p_ezor_ovdim_be_tkufa         number,
                                    p_seq_tkufot_avoda_golmi      number,
                                    p_seq_bakasha                 number,
                                    p_seq_tkufot_michutz_lasharut number,
                                    p_seq_tkufot_sherut_tsvaii    number) is
    v_is_exist_same_row   number;
    v_ezor_ovdim_be_tkufa number;
  begin
    select count(*)
      into v_is_exist_same_row
      from tkufot_avoda_mechushv m
     where m.taarich_me = p_taarich_me
       and m.taarich_ad = p_taarich_ad
       and m.seq_bakasha = p_seq_bakasha
       and m.achuz_chelkyut = 1;
  
    if v_is_exist_same_row > 0 then
      return;
    end if;
  
    select v.seq_ezor_ovdim
      into v_ezor_ovdim_be_tkufa
      from v_bakasha_last_status v
     where v.seq_bakasha = p_seq_bakasha;
  
    insert into tkufot_avoda_mechushv
      (taarich_me,
       taarich_ad,
       achuz_chelkyut,
       praklit,
       sach_chodeshim,
       haim_kana_zchuyot,
       code_sugey_tkufot,
       code_sugey_haasaka,
       code_sugey_zchuyot,
       seq_tkufot_avoda_mechushv,
       ezor_ovdim_be_tkufa,
       seq_tkufot_avoda_golmi,
       seq_bakasha,
       seq_tkufot_michutz_lasharut,
       seq_tkufot_sherut_tsvaii)
    values
      (p_taarich_me,
       p_taarich_ad,
       p_achuz_chelkyut,
       p_praklit,
       round(months_between(p_taarich_ad + 1, p_taarich_me), 2),
       p_haim_kana_zchuyot,
       p_code_sugey_tkufot,
       p_code_sugey_haasaka,
       p_code_sugey_zchuyot,
       p_seq_tkufot_avoda_mechushv,
       nvl(p_ezor_ovdim_be_tkufa, v_ezor_ovdim_be_tkufa),
       p_seq_tkufot_avoda_golmi,
       p_seq_bakasha,
       p_seq_tkufot_michutz_lasharut,
       p_seq_tkufot_sherut_tsvaii);
  
  end;
  -----------------------------------------------
  function convert_code_sugey_tkufot(p_code_sugey_tkufot  number,
                                     p_code_sugey_zchuyot number)
    return number is
  begin
    if p_code_sugey_tkufot = 2 then
      if p_code_sugey_zchuyot = 67 then
        return 20;
      else
        return 4;
      end if;
    else
      return case p_code_sugey_tkufot when 3 then 11 when 3 then 11 when 9998 then 2 when 9999 then 3 when 1 then 3 when 5 then 4 when 6 then 9 end;
    end if;
  end;
  -----------------------------------------------
  function convert_code_sherut_tsvaii(p_code_sherut_tsvaii number)
    return number is
  begin
    return case p_code_sherut_tsvaii when 90 then 5 when 91 then 6 end;
  end;
  -----------------------------------------------
  procedure calc_tkufot_mechushav(p_seq_bakasha number) is
  begin
    --Tkufot_avoda_golmi
    for g in (select *
                from Tkufot_Avoda_Golmi g
               where g.seq_bakasha = p_seq_bakasha
                 and g.code_sugey_tkufot <> 4) loop
      Insert_tkufot_mechushav(g.taarich_me,
                              g.taarich_ad,
                              g.achuz_chelkyut,
                              g.praklit,
                              
                              g.haim_kana_zchuyot,
                              convert_code_sugey_tkufot(g.code_sugey_tkufot,
                                                        g.code_sugey_zchuyot),
                              g.code_sugey_haasaka,
                              convert_code_sugey_zchuyot(g.code_sugey_zchuyot),
                              tkufot_avoda_mechushav_seq.nextval,
                              g.ezor_ovdim_be_tkufa,
                              g.seq_tkufot_avoda_golmi,
                              g.seq_bakasha,
                              null,
                              null);
    end loop;
  
    --Tkufot_michutz_lasharut
    for m in (select *
                from tkufot_michutz_lasharut m
               where m.seq_bakasha = p_seq_bakasha) loop
      Insert_tkufot_mechushav(m.taarich_me,
                              m.taarich_ad,
                              0,
                              null,
                              
                              null,
                              7,
                              null,
                              convert_code_sugey_zchuyot(m.code_sugey_zchuyot),
                              tkufot_avoda_mechushav_seq.nextval,
                              null,
                              null,
                              m.seq_bakasha,
                              m.seq_tkufot_michutz_lasharut,
                              null);
    
    end loop;
  
    --Tkufot_sherut_tsvaii 
    for s in (select *
                from tkufot_sherut_tsvaii s
               where s.seq_bakasha = p_seq_bakasha
                 and s.code_sug_sherut_tzaii in (90, 91)) loop
      Insert_tkufot_mechushav(s.taarich_me,
                              s.taarich_ad,
                              1,
                              null,
                              
                              null,
                              convert_code_sherut_tsvaii(s.code_sug_sherut_tzaii),
                              null,
                              4,
                              tkufot_avoda_mechushav_seq.nextval,
                              null,
                              null,
                              
                              s.seq_bakasha,
                              null,
                              s.seq_tkufot_sherut_tsvaii);
    end loop;
  end;
  ------------------------------------------------
  procedure In_end_load(p_seq_bakasha_previos number,
                        p_seq_bakasha         number,
                        p_id                  varchar2,
                        p_seq_ld_log          number) is
    v_id varchar2(100);
  begin
    v_id := Get_p_id(p_id);
    --update misra in tkufot table  
    pk_prm_utils.update_misra_when_choze_bchirim(p_seq_bakasha);
  
    add_err_tables_to_log(v_id);
  
    if Get_count_errors(p_seq_ld_log) = 0 and
       p_seq_bakasha_previos is not null then
      Filter_By_compare_versions(p_seq_bakasha,
                                 p_seq_bakasha_previos,
                                 v_id,
                                 p_seq_ld_log);
    end if;
  
    finish_load_and_commit(p_seq_ld_log, p_seq_bakasha);
  end;
  -----------------------------------------------
end;
/

create or replace package body prm_system_copy.pk_load_magal is
  ------------------------------------------------
  type type_confirm_ozar is record(
    seq_prisha        number,
    zehut             number,
    porshim_seq       number,
    kd_misrad         char(4),
    kd_yehida         char(4),
    teur_yechida      varchar2(30),
    achuz_kitzba      number,
    date_tashlum      date,
    helkiut           number,
    mis_gimla         number,
    date_haavara_hash date,
    seq_bakasha       number,
    code_action       number,
    seq_ezor_ovdim    number,
    kd_city           char(5),
    adress            varchar2(30),
    tel               varchar2(11),
    code_department   number);
  ------------------------------------------------
  procedure send_mail_not_update_tikim is
    mail_recipient constant varchar2(250) := 'sharong@mof.gov.il';
    mail_recipient_wait           varchar2(250);
    message                       varchar2(100) := '(by process: update from magal)';
    attach_nasham_other_ministry  clob;
    attach_nasham_health_ministry clob;
    attach_chinuch                clob;
    attach_merkava                clob;
    code_ezor_ovdim_categoty      number;
  begin
    --tikim that was not confirmed 'nshm'
    for r in (select t.*
                from ld_not_updt_frm_mgl_tkim t
               where trunc(t.date_not_update) = trunc(sysdate)) loop
      -- nasham
      if
      --code reason not update: other status
       r.code_reason_not_updt = 2
      --status: wait for nasham
       and r.code_status_tik_in_mpm = 6
      --only merkava tikim
       and r.code_misrad not in (250, 210) then
        --Get code ezor ovdim categoty
        code_ezor_ovdim_categoty := pk_load_mimshak.Get_ezor_ovdim_category(r.seq_ezor_ovdim_mpm);
        if code_ezor_ovdim_categoty = 114 then
          --Add to the list attach_nasham_other_ministry
          attach_nasham_other_ministry := attach_nasham_other_ministry ||
                                          r.zehut || chr(10);
        elsif code_ezor_ovdim_categoty = 115 then
          --Add to the list attach_nasham_health_ministry
          attach_nasham_health_ministry := attach_nasham_health_ministry ||
                                           r.zehut || chr(10);
        end if;
      
      end if;
    
      --chinuch
      if
      --only chinuch tikim
       r.code_misrad in (250, 210) and
       ((
       --code reason not update: other status
        r.code_reason_not_updt = 2
       --status: rejected tikim
        and r.code_status_tik_in_mpm = 15) or ( --code reason not update: not exist 
        r.code_reason_not_updt = 1)) then
        --Add to the list attach_nasham
        attach_chinuch := attach_chinuch || r.zehut || ',' ||
                          r.teur_yechida || chr(10);
      end if;
    
      --merkava
      if
      --only merkava tikim
       r.code_misrad not in (250, 210) and
       ((
       --code reason not update: other status
        r.code_reason_not_updt = 2
       --status: rejected tikim
        and r.code_status_tik_in_mpm = 15) or ( --code reason not update: not exist 
        r.code_reason_not_updt = 1)) then
        --Add to the list attach_nasham
        attach_merkava := attach_merkava || r.zehut || chr(10);
      end if;
    
    end loop;
  
    if attach_nasham_other_ministry is not null then
      --Add title
      attach_nasham_other_ministry := 'Id numbers' || chr(10) ||
                                      attach_nasham_other_ministry;
    
      --Send in mail
      pk_prm_utils.send_attach(mail_recipient ||
                               ',perlako@civil-service.gov.il',
                               'Please confirm the next tikim other ministry',
                               message,
                               attach_nasham_other_ministry,
                               'csv',
                               'Tikim_waiting' ||
                               to_char(sysdate, 'dd_mm_yyyy') || '.csv');
    end if;
  
    if attach_nasham_health_ministry is not null then
      --Add title
      attach_nasham_health_ministry := 'Id numbers' || chr(10) ||
                                       attach_nasham_health_ministry;
    
      --Send in mail
      pk_prm_utils.send_attach(mail_recipient ||
                               ',ritakr@Civil-Service.gov.il',
                               'Please confirm the next tikim  ministry of health',
                               message,
                               attach_nasham_health_ministry,
                               'csv',
                               'Tikim_waiting' ||
                               to_char(sysdate, 'dd_mm_yyyy') || '.csv');
    end if;
  
    if attach_chinuch is not null then
      --Add title
      attach_chinuch := 'Id numbers , machoz' || chr(10) || attach_chinuch;
      --Send in mail
      pk_prm_utils.send_attach(mail_recipient ||
                               ',LillySa@education.gov.il',
                               'Please send to mapam the next tikim',
                               message,
                               attach_chinuch,
                               'csv',
                               'Missing_tikim_' ||
                               to_char(sysdate, 'dd_mm_yyyy') || '.csv');
    end if;
  
    if attach_merkava is not null then
      --Add title
      attach_merkava := 'Id numbers' || chr(10) || attach_merkava;
      --Send in mail
      pk_prm_utils.send_attach(mail_recipient || ',mirid@mof.gov.il',
                               'Please send to mapam the next tikim',
                               message,
                               attach_merkava,
                               'csv',
                               'Missing_tikim_' ||
                               to_char(sysdate, 'dd_mm_yyyy') || '.csv');
    end if;
  end;
  ------------------------------------------------  
  -- Previous tik version 
  function Found_previous_tik_version(p_seq_porshim    number,
                                      p_seq_ezor_ovdim number,
                                      p_seq_bakasha    in out number,
                                      p_status_tik     in out number)
    return boolean is
    pragma autonomous_transaction;
    v_code_department number;
  begin
    for r_girsa in (select t.*, c.code_department
                      from v_regila_last_status_versions t
                      left join code_action c
                        on t.code_action = c.code_action
                     where t.seq_porshim = p_seq_porshim
                       and t.seq_ezor_ovdim = p_seq_ezor_ovdim
                     order by t.seq_bakasha desc) loop
      p_seq_bakasha     := r_girsa.seq_bakasha;
      p_status_tik      := r_girsa.code_action;
      v_code_department := r_girsa.code_department;
    
      if (v_code_department = 1) then
        update bakasha_regila tikim
           set tikim.seq_bakasha = tikim.seq_bakasha * (-1)
         where tikim.seq_bakasha = r_girsa.seq_bakasha;
      
        commit;
      else
        exit;
      end if;
    end loop;
  
    if v_code_department = 1 then
      return false;
    else
      return true;
    end if;
  
  end;
  ------------------------------------------------
  procedure merge_ld_not_updt_frm_mgl_tkim(p_zehut          number,
                                           p_seq_ezor_ovdim number,
                                           p_kd_misrad      number,
                                           p_kd_yehida      number,
                                           p_teur_yechida   varchar2,
                                           p_code_reason    number,
                                           p_teur_reason    varchar2,
                                           p_status_tik     number default null) is
  begin
    -- merge into ld_not_updt_frm_mgl_tkim
    merge into ld_not_updt_frm_mgl_tkim l
    using dual
    on (l.zehut = p_zehut)
    when matched then
      update
         set l.code_misrad            = p_kd_misrad,
             l.code_yechida           = p_kd_yehida,
             l.teur_yechida           = p_teur_yechida,
             l.date_not_update        = sysdate,
             l.code_reason_not_updt   = p_code_reason,
             l.teur_reason_not_updt   = p_teur_reason,
             l.code_status_tik_in_mpm = p_status_tik,
             l.seq_ezor_ovdim_mpm     = p_seq_ezor_ovdim
    when not matched then
      insert
        (zehut,
         code_misrad,
         code_yechida,
         teur_yechida,
         date_not_update,
         code_reason_not_updt,
         teur_reason_not_updt,
         code_status_tik_in_mpm,
         seq_ezor_ovdim_mpm)
      values
        (p_zehut,
         p_kd_misrad,
         p_kd_yehida,
         p_teur_yechida,
         sysdate,
         p_code_reason,
         p_teur_reason,
         p_status_tik,
         p_seq_ezor_ovdim);
  end;
  ------------------------------------------------
  function Updae_5_fields(count_success in out number,
                          count_errores in out number)
  
   return clob is
    old_date_warning clob := chr(10) ||
                             '#Only Warning# ID numbers that their ''date_haavara_hash'' is old: ';
    v_seq_bakasha    number;
  
    v_cursor sys_refcursor;
    v_row    type_confirm_ozar;
  
  begin
    count_success := 0;
  
    Get_ozar_confirm_list(v_cursor);
    loop
      fetch v_cursor
        into v_row;
      EXIT WHEN v_Cursor%NOTFOUND;
      v_seq_bakasha := v_row.seq_bakasha;
    
      -- Add 1 to the count numerator
      count_success := count_success + 1;
    
      -- merge row to netuney_tik_meushar_ozar
      merge into netuney_tik_meushar_ozar n
      using dual
      on (n.seq_bakasha = v_seq_bakasha)
      when matched then
        update
           set n.achuz_kizba_sofi      = v_row.achuz_kitzba,
               n.taarich_tashlum_kizba = v_row.date_tashlum,
               -- n.mispar_gimla          = v_row.mis_gimla,
               n.chelkiyut_misra_sofit = pk_load_mimshak.Convert_number_to_Decimal(v_row.helkiut),
               n.taarich_ishur_ozar    = v_row.date_haavara_hash
      when not matched then
        insert
          (achuz_kizba_sofi,
           taarich_tashlum_kizba,
           -- mispar_gimla,
           chelkiyut_misra_sofit,
           taarich_ishur_ozar,
           seq_bakasha)
        values
          (v_row.achuz_kitzba,
           v_row.date_tashlum,
           --  v_row.mis_gimla,
           pk_load_mimshak.Convert_number_to_Decimal(v_row.helkiut),
           v_row.date_haavara_hash,
           v_seq_bakasha);
    
      --update mispar_gimla
      update prisha p
         set p.gimla_number = v_row.mis_gimla
       where p.seq_prisha = v_row.seq_prisha;
    
      --Update Status to the tik: 'confirmed magal'
      pk_prm_utils.insert_actions_for_bakasha(v_seq_bakasha, 0);
      commit;
    end loop;
  
    close v_cursor;
    --send mail not update tikim; 
  
    return old_date_warning;
  end;
  -----------------------------------------------------------
  procedure Get_ozar_confirm_list(cur out sys_refcursor) is
  begin
    open cur for
      select distinct t4.seq_prisha,
                      t2.zehut,
                      t3.porshim_seq,
                      t2.kd_misrad,
                      t2.kd_yehida,
                      tg_system.convert_hebrew_to_ascii(t6.teur) as teur_yechida,
                      case t4.CODE_SEIF_PRISHA
                        when 15 then
                         40
                        else
                         first_value(t1.achuz_kitzba)
                         over(partition by t1.zehut order by
                              nvl(t1.index_decision, 0) desc)
                      end as achuz_kitzba,
                      case t4.CODE_SEIF_PRISHA
                        when 15 then
                         t2.date_ptira + 1
                        else
                         first_value(t1.date_prisha + 1)
                         over(partition by t1.zehut order by
                              nvl(t1.index_decision, 0) desc)
                      end as date_tashlum,
                      first_value(t1.helkiut * 100) over(partition by t1.zehut order by nvl(t1.index_decision, 0) desc) as helkiut,
                      t2.mis_gimla,
                      t2.date_haavara_hash,
                      t4.seq_bakasha,
                      t4.CODE_ACTION,
                      T4.SEQ_EZOR_OVDIM,
                      t2.kd_city,
                      tg_system.convert_hebrew_to_ascii(t2.adress) adress,
                      t2.tel,
                      c.code_department
      
        from tg_system.tg_poresh t2
        left join poresh t3
          on t2.zehut = t3.mispar_zehut
        left join v_regila_last_status_versions t4
          on t3.porshim_seq = t4.seq_porshim
        left join tg_system.tg_p_decision t1
          on t1.zehut = t2.zehut
         and t1.nosaf = t2.nosaf
        left join tg_system.tg_k_yehida t6
          on t2.kd_misrad = t6.kod1
         and t2.kd_yehida = t6.kod
        left join code_action c
          on t4.CODE_ACTION = c.code_action
      
       where t2.nosaf = 0
            --Get only tikim from 'nasham' (not from security - 'Bitachon')  
         and t2.kd_makor = '03'
            --The status in mpm is: 'transfer to magal'
         and t4.CODE_ACTION = 46
         and t2.date_haavara_hash is not null
      
      /*--The next condition is unable because magal is not always update date_haavara_hash to 
      
      --the second bakasha or higher...
      and trunc(t2.date_haavara_hash) >= trunc(t4.date_action) */
      ;
  
  end;

end;
/

create or replace package body prm_system_copy.pk_load_merkava is
  ------------------------------------------------
  count_success_tikim number;
  count_errors_tikim  number;
  ------------------------------------------------
  procedure add_row_misra_lebitul(v_seq_bakasha varchar2,
                                  rowindata_seq varchar2,
                                  rowindata_1   varchar2,
                                  rowindata_2   varchar2,
                                  rowindata_3   varchar2,
                                  rowindata_4   varchar2,
                                  rowindata_5   varchar2,
                                  rowindata_6   varchar2) is
    tikim_mukdmt_misrt_lebitul_row err_tikim_mukdmt_misrt_lebitul%rowtype;
  begin
    --check if row exist 
    --temporary by the first field.
    if nvl(rowindata_1, 0) <> 0 then
      tikim_mukdmt_misrt_lebitul_row                 := null;
      tikim_mukdmt_misrt_lebitul_row.ora_err_tag$    := rowindata_seq;
      tikim_mukdmt_misrt_lebitul_row.mispar_misra    := rowindata_1;
      tikim_mukdmt_misrt_lebitul_row.toar_misra      := rowindata_2;
      tikim_mukdmt_misrt_lebitul_row.code_derug      := rowindata_3;
      tikim_mukdmt_misrt_lebitul_row.code_darga_me   := rowindata_4;
      tikim_mukdmt_misrt_lebitul_row.code_darga_ad   := rowindata_5;
      tikim_mukdmt_misrt_lebitul_row.achuz_chelkiyut := rowindata_6;
    
      --insert into tikim_mukdemet_misrot_lebitul
      insert into tikim_mukdemet_misrot_lebitul
        (toar_misra,
         mispar_misra,
         code_derug,
         code_darga_me,
         code_darga_ad,
         achuz_chelkiyut,
         seq_bakasha,
         seq_tik_mukdemet_misra_lebitul)
      values
        (tikim_mukdmt_misrt_lebitul_row.toar_misra,
         tikim_mukdmt_misrt_lebitul_row.mispar_misra,
         tikim_mukdmt_misrt_lebitul_row.code_derug,
         tikim_mukdmt_misrt_lebitul_row.code_darga_me,
         tikim_mukdmt_misrt_lebitul_row.code_darga_ad,
