  function check_9017_tkufot_mechshv(err_tkufot_avoda_mechushv_r err_tkufot_avoda_mechushv%rowtype,
                                     v_seq_bakasha               number)
    return boolean is
    pragma autonomous_transaction;
    err_tkufot_avoda_mechushv_row err_tkufot_avoda_mechushv%rowtype;
    tkufa_is_not_overlapping      varchar(1);
    taarich_me                    date;
    taarich_ad                    date;
  begin
    err_tkufot_avoda_mechushv_row := err_tkufot_avoda_mechushv_r;
    --check required fields.
    --the next fields is defined in the db.
    --err_tkufot_avoda_mechushv_row.taarich_me 
    --err_tkufot_avoda_mechushv_row.taarich_ad
  
    --if code_sugey_tkufot different from the codes:5,6,7
    --we can check two fields addinal.       
    if err_tkufot_avoda_mechushv_row.code_sugey_tkufot not in (5, 6, 7) then
      --check required ezor_ovdim_be_tkufa
      if err_tkufot_avoda_mechushv_row.ezor_ovdim_be_tkufa is null then
        pk_load_mimshak.add_row_err_tkufot_avda_mchshv('9017',
                                                       err_tkufot_avoda_mechushv_row,
                                                       null,
                                                       20001,
                                                       'אזור עובדים בתקופה');
      end if;
      --check required code_sugey_haasaka
      if err_tkufot_avoda_mechushv_row.code_sugey_haasaka is null then
        pk_load_mimshak.add_row_err_tkufot_avda_mchshv('9017',
                                                       err_tkufot_avoda_mechushv_row,
                                                       null,
                                                       20001,
                                                       'קוד סוגי העסקה');
      end if;
    end if;
  
    if err_tkufot_avoda_mechushv_row.code_sugey_tkufot is null then
      pk_load_mimshak.add_row_err_tkufot_avda_mchshv('9017',
                                                     err_tkufot_avoda_mechushv_row,
                                                     null,
                                                     20001,
                                                     'קוד סוגי תקופות');
    end if;
    if err_tkufot_avoda_mechushv_row.sach_chodeshim is null then
      pk_load_mimshak.add_row_err_tkufot_avda_mchshv('9017',
                                                     err_tkufot_avoda_mechushv_row,
                                                     null,
                                                     20001,
                                                     'סך חודשים');
    end if;
    if err_tkufot_avoda_mechushv_row.code_sugey_zchuyot is null then
      pk_load_mimshak.add_row_err_tkufot_avda_mchshv('9017',
                                                     err_tkufot_avoda_mechushv_row,
                                                     null,
                                                     20001,
                                                     'קוד סוגי זכויות');
    end if;
    if err_tkufot_avoda_mechushv_row.achuz_chelkyut is null then
      pk_load_mimshak.add_row_err_tkufot_avda_mchshv('9017',
                                                     err_tkufot_avoda_mechushv_row,
                                                     null,
                                                     20001,
                                                     'אחוז חלקיות');
    end if;
  
    begin
      taarich_me := to_date(err_tkufot_avoda_mechushv_row.taarich_me,
                            'yyyymmdd');
    exception
      when others then
        pk_load_mimshak.add_row_err_tkufot_avda_mchshv('9017',
                                                       err_tkufot_avoda_mechushv_row,
                                                       sqlerrm,
                                                       sqlcode,
                                                       'תאריך מ');
        commit;
        return false;
    end;
  
    begin
      taarich_ad := to_date(err_tkufot_avoda_mechushv_row.taarich_ad,
                            'yyyymmdd');
    exception
      when others then
        pk_load_mimshak.add_row_err_tkufot_avda_mchshv('9017',
                                                       err_tkufot_avoda_mechushv_row,
                                                       sqlerrm,
                                                       sqlcode,
                                                       'תאריך עד');
        commit;
        return false;
    end;
  
    --check overlapping dates between the row 
    --and tkufot avoda mechushav table for this 'tik'. 
    select case
             when count(*) > 0 then
              'n'
             else
              'y'
           end
      into tkufa_is_not_overlapping
      from ld_temp_tkufot_avoda_mechushav temp
    /*  where temp.taarich_me <= taarich_ad
    and temp.taarich_ad >= taarich_me */
     where temp.taarich_me <=
           to_date(err_tkufot_avoda_mechushv_row.taarich_ad, 'yyyymmdd')
       and temp.taarich_ad >=
           to_date(err_tkufot_avoda_mechushv_row.taarich_me, 'yyyymmdd')
          
       and case
             when err_tkufot_avoda_mechushv_row.code_sugey_tkufot in
                  (1, 2, 3, 4, 8, 9, 10, 11, 12, 20) then
              -1
             when err_tkufot_avoda_mechushv_row.code_sugey_tkufot in (5, 6) then
              -2
           end = case
             when temp.code_sugey_tkufot in
                  (1, 2, 3, 4, 8, 9, 10, 11, 12, 20) then
              -1
             when temp.code_sugey_tkufot in (5, 6) then
              -2
           end;
    if tkufa_is_not_overlapping = 'n' then
      pk_load_mimshak.add_row_err_tkufot_avda_mchshv('9017',
                                                     err_tkufot_avoda_mechushv_row,
                                                     null,
                                                     20002,
                                                     null);
    end if;
    --insert into ld_temp_tkufot_avoda_mechushav
    insert into ld_temp_tkufot_avoda_mechushav
      (taarich_me, taarich_ad, seq_bakasha, code_sugey_tkufot)
    values
      (taarich_me,
       taarich_ad,
       v_seq_bakasha,
       err_tkufot_avoda_mechushv_row.code_sugey_tkufot);
    commit;
    return true;
  end;
