  function check_0552_tkufot_avoda_golmi(err_tkufot_avoda_golmi_r err_tkufot_avoda_golmi%rowtype,
                                         v_seq_bakasha            number)
    return boolean is
    pragma autonomous_transaction;
    err_tkufot_avoda_golmi_row err_tkufot_avoda_golmi%rowtype;
    continuous_period          varchar2(1);
    max_taarich_ad             date;
    taarich_ad                 date;
    taarich_me                 date;
  begin
    err_tkufot_avoda_golmi_row := err_tkufot_avoda_golmi_r;
    --check required fields.
    --the next fields is defined in the db.
    --  err_tkufot_avoda_golmi_row.taarich_me 
    --  err_tkufot_avoda_golmi_row.taarich_ad
    if err_tkufot_avoda_golmi_row.code_sugey_tkufot is null then
      pk_load_mimshak.add_row_err_tkufot_avoda_golmi('0552',
                                                     err_tkufot_avoda_golmi_row,
                                                     null,
                                                     20001,
                                                     'קוד סוגי תקופות');
    end if;
    if err_tkufot_avoda_golmi_row.ezor_ovdim_be_tkufa is null then
      pk_load_mimshak.add_row_err_tkufot_avoda_golmi('0552',
                                                     err_tkufot_avoda_golmi_row,
                                                     null,
                                                     20001,
                                                     'אזור עובדים בתקופה');
    end if;
    if err_tkufot_avoda_golmi_row.code_sugey_haasaka is null then
      pk_load_mimshak.add_row_err_tkufot_avoda_golmi('0552',
                                                     err_tkufot_avoda_golmi_row,
                                                     null,
                                                     20001,
                                                     'קוד סוגי העסקה');
    end if;
    if err_tkufot_avoda_golmi_row.achuz_chelkyut is null then
      pk_load_mimshak.add_row_err_tkufot_avoda_golmi('0552',
                                                     err_tkufot_avoda_golmi_row,
                                                     null,
                                                     20001,
                                                     'אחוז חלקיות');
    end if;
  
    begin
      taarich_me := to_date(err_tkufot_avoda_golmi_row.taarich_me,
                            'yyyymmdd');
    exception
      when others then
        pk_load_mimshak.add_row_err_tkufot_avoda_golmi('0552',
                                                       err_tkufot_avoda_golmi_row,
                                                       sqlerrm,
                                                       sqlcode,
                                                       'תאריך מ');
        commit;
        return false;
    end;
    begin
      taarich_ad := to_date(err_tkufot_avoda_golmi_row.taarich_ad,
                            'yyyymmdd');
    exception
      when others then
        pk_load_mimshak.add_row_err_tkufot_avoda_golmi('0552',
                                                       err_tkufot_avoda_golmi_row,
                                                       sqlerrm,
                                                       sqlcode,
                                                       'תאריך עד');
        commit;
        return false;
    end;
  
    select max(ld_temp_tkufot_avoda_golmi.taarich_ad)
      into max_taarich_ad
      from ld_temp_tkufot_avoda_golmi
     where ld_temp_tkufot_avoda_golmi.seq_bakasha = v_seq_bakasha;
  
    if max_taarich_ad is not null then
      if max_taarich_ad = taarich_me - 1 then
        continuous_period := 'y';
      else
        continuous_period := 'n';
      end if;
    end if;
    if continuous_period = 'n' then
      pk_load_mimshak.add_row_err_tkufot_avoda_golmi('0552',
                                                     err_tkufot_avoda_golmi_row,
                                                     null,
                                                     20002,
                                                     null);
    end if;
    --insert into ld_temp_tkufot_avoda_golmi
    insert into ld_temp_tkufot_avoda_golmi
    values
      (taarich_me, taarich_ad, v_seq_bakasha);
  
    commit;
    return true;
  end;
