  procedure check_0006_porshim(err_porshim_r err_porshim%rowtype) is
    pragma autonomous_transaction;
    err_porshim_row err_porshim%rowtype;
  begin
    err_porshim_row := err_porshim_r;
    --check required fields.
  
    if err_porshim_row.city_code is null then
