  ------------------------------------------------
  function get_seq_contact(p_contact_string varchar2,
                           p_seq_ezor_ovdim number) return number is
    pragma autonomous_transaction;
    v_contact_string varchar2(1000);
    type t_array_of_varchar is table of varchar2(2000) index by binary_integer;
    v_array                   t_array_of_varchar;
    v_seq_contacts_ministries number;
  begin
    -- cut the first char - '~'
    v_contact_string := substr(p_contact_string, 2);
    -- convert delimited string to array
    for current_row in (with test as
                           (select v_contact_string from dual)
                          select regexp_substr(v_contact_string,
                                               '[^~]+',
                                               1,
                                               rownum) split
                            from test
                          connect by level <=
                                     length(regexp_replace(v_contact_string,
                                                           '[^~]+')) + 1) loop
      if v_array.count = 0 then
        v_array(v_array.count) := current_row.split;
      else
        v_array(v_array.count) := nullif(current_row.split, '0');
      end if;
    end loop;
  
    if not regexp_like(v_array(0), '^\d+$') then
      return null;
    end if;
  
    --merge into porshim
    --028782886~divish~miri~02-5012369~054-4861634~mirid@mof.gov.il
    merge into contacts_ministries
    using dual
    on (id = v_array(0))
    when matched then
      update
         set first_name     = v_array(2),
             last_name      = v_array(1),
             mail           = v_array(5),
             phone          = v_array(3),
             cell_phone     = v_array(4),
             seq_ezor_ovdim = p_seq_ezor_ovdim
    when not matched then
      insert
        (seq_contacts_ministries,
         first_name,
         last_name,
         id,
         mail,
         phone,
         cell_phone,
         seq_ezor_ovdim)
      values
        (contacts_ministries_seq.nextval,
         v_array(2),
         v_array(1),
         v_array(0),
         v_array(5),
         v_array(3),
         v_array(4),
         p_seq_ezor_ovdim) log errors into err_contacts_ministries reject limit unlimited;
    commit;
    --get seq contacts_ministries
    select t.seq_contacts_ministries
      into v_seq_contacts_ministries
      from contacts_ministries t
     where t.id = v_array(0);
  
    return v_seq_contacts_ministries;
  end;

  ------------------------------------------------
  procedure delete_from_ld_merkava(p_do_commit  boolean,
                                   p_main_title varchar2) is
    v_first_seq_number number;
    v_last_seq_number  number;
  begin
    --first seq number
    select min(l.seq)
      into v_first_seq_number
      from ld_merkava l
     where l.a = p_main_title;
    --last seq number
    select min(seq)
      into v_last_seq_number
      from (select last_value(case
                              --get main title row
                                when regexp_like(a,
                                                 '^~.{0,100}~.{0,100}~.{0,100}~.{0,1}~.{0,1}~') then
                                 a
                                else
                                 null
                              end ignore nulls) over(order by seq asc rows between unbounded preceding and 1 preceding) as main_title
                   
                  ,
                   a,
                   seq
              from ld_merkava) internal
     where a = '#'
       and main_title = p_main_title;
  
    if p_do_commit = true then
      delete from ld_merkava l
       where l.seq between v_first_seq_number and v_last_seq_number;
    
      commit;
    end if;
  end;
  ------------------------------------------------
  function loop_over_all_tikim(count_success_tikim_out out number,
                               count_errors_tikim_out  out number)
    return clob is
    report         clob;
    report_for_tik clob;
    --v_blob blob;
  begin
    execute immediate 'alter session set nls_language= ''american''';
    execute immediate 'alter session set nls_date_language=''english''';
    execute immediate 'alter session set nls_date_format=''dd/mm/yyyy''';
    count_success_tikim := 0;
    count_errors_tikim  := 0;
  
    --get main titles and contacts
    for row_tik in (select *
                      from (select last_value(case
                                              --get main title row
                                                when regexp_like(a,
                                                                 '^~.{0,100}~.{0,100}~.{0,100}~.{0,1}~.{0,1}~') then
                                                 a
                                                else
                                                 null
                                              end ignore nulls) over(order by seq asc rows between unbounded preceding and 1 preceding) as main_title
                                   
                                  ,
                                   replace(a, '~~', '~0~') as contact
                              from ld_merkava
                            --include main title row and contact title row
                             where regexp_like(a,
                                               '^~.{0,100}~.{0,100}~.{0,100}~.{0,100}~.{0,100}~.{0,100}')) internal
                    --filter only contact title rowes
                     where not
                            regexp_like(contact,
                                        '^~.{0,100}~.{0,100}~.{0,100}~.{0,100}~.{0,100}~.{0,100}~')) loop
      --truncate table err_porshim 
      execute immediate 'truncate table err_porshim';
      --truncate table err_action_log 
      execute immediate 'truncate table err_action_log';
      --truncate table err_tikim
      execute immediate 'truncate table err_bakasha_regila';
      --truncate table err_tikim_mukdemet
      execute immediate 'truncate table err_bakasha_mukdemet';
      --truncate table err_tikim_mukdmt_misrt_lebitul
      execute immediate 'truncate table err_tikim_mukdmt_misrt_lebitul';
      --truncate table err_netuney_tik_mechushavim
      execute immediate 'truncate table err_netuney_tik_mechushavim';
      --truncate table err_bney_mishpacha
      execute immediate 'truncate table err_bney_mishpacha';
      --truncate table err_tkufot_avoda_golmi
      execute immediate 'truncate table err_tkufot_avoda_golmi';
      --truncate table err_tkufot_michutz_lasharut
      execute immediate 'truncate table err_tkufot_michutz_lasharut';
      --truncate table err_darga_vederug_tik
      execute immediate 'truncate table err_darga_vederug_tik';
      --truncate table err_tkufot_sherut_tsvaii
      execute immediate 'truncate table err_tkufot_sherut_tsvaii';
      --truncate table err_tkufot_avoda_mechushv
      execute immediate 'truncate table err_tkufot_avoda_mechushv';
      --truncate table ld_temp_merkava_per_tik
      execute immediate 'truncate table ld_temp_merkava_per_tik';
      --truncate table ld_temp_tkufot_avoda_golmi 
      execute immediate 'truncate table ld_temp_tkufot_avoda_golmi';
      --truncate table ld_temp_tkufot_avoda_mechushav
      execute immediate 'truncate table ld_temp_tkufot_avoda_mechushav';
      --truncate table err_contacts_ministries
      execute immediate 'truncate table err_contacts_ministries';
    
      report         := report || chr(10) || '<h2>' || 'tik: ' ||
                        row_tik.main_title || '<h2/>';
      report_for_tik := fill_prisha_tables(row_tik.main_title,
                                           row_tik.contact);
      report         := report || chr(10) || report_for_tik;
      if report_for_tik like '%>Loaded%' then
        count_success_tikim := count_success_tikim + 1;
      elsif report_for_tik like '%>Unloaded%' then
        count_errors_tikim := count_errors_tikim + 1;
      end if;
      commit;
    end loop;
    count_success_tikim_out := count_success_tikim;
    count_errors_tikim_out  := count_errors_tikim;
    report                  := '<html><body>' || '<h1>' ||
                               'total success tikim: ' ||
                               count_success_tikim || '<h1/>' || '<h1>' ||
                               'total errors tikim: ' || count_errors_tikim ||
                               '<h1/>' || report || '<html/><body/>';
  
    commit;
    return report;
  end;
  ------------------------------------------------   
  function fill_prisha_tables(p_main_title varchar2, p_contact varchar2)
    return clob is
    v_taarich_prisha             date;
    v_seif_prisha                number;
    v_mispar_oved                number;
    v_zeut                       number;
    v_ezor_ovdim                 number;
    v_porshim_seq                number;
    v_seq_ezor_ovdim             number;
    v_seq_bakasha                number;
    v_report                     clob;
    v_report_varchar             varchar2(20000);
    i                            number;
    old_version_seq_bakasha      number;
    old_version_seq_bakasha_save number;
    is_delete_old_version        number;
    v_is_exist_netuney_sachar    number;
    is_bakasha_regila            number(1);
    --##
    porshim_row                 err_porshim%rowtype;
    tikim_row                   err_bakasha_regila%rowtype;
    netuney_tik_mechushavim_row err_netuney_tik_mechushavim%rowtype;
    tikim_mukdemet_row          err_bakasha_mukdemet%rowtype;
    bney_mishpacha_row          err_bney_mishpacha%rowtype;
    tkufot_avoda_golmi_row      err_tkufot_avoda_golmi%rowtype;
    tkufot_michutz_lasharut_row err_tkufot_michutz_lasharut%rowtype;
    darga_vederug_tik_row       err_darga_vederug_tik%rowtype;
    tkufot_sherut_tsvaii_row    err_tkufot_sherut_tsvaii%rowtype;
    tkufot_avoda_mechushv_row   err_tkufot_avoda_mechushv%rowtype;
    --##
    receivedmusttables     varchar2(100);
    recivednustdataintitle varchar2(100);
    --##
    docommit                 boolean;
    must_info_type           varchar2(1000) := '0001,0002,0006,0552,0008,9015,9015A,9017,';
    v_seq_contact            number;
    v_code_sug_bakasha       number;
    count_regila_as_mukdemet number := 0;
    v_result_delete_bakasha  varchar2(1000);
  begin
    receivedmusttables     := null;
    recivednustdataintitle := null;
    docommit               := true;
  
    --##################
    --fill the temp table for tik
    insert into ld_temp_merkava_per_tik
      select a,
             b,
             c,
             d,
             e,
             f,
             g,
             h,
             i,
             j,
             k,
             l,
             m,
             n,
             o,
             p,
             q,
             r,
             s,
             t,
             u,
             v,
             w,
             x,
             y,
             z,
             aa,
             ab,
             ac,
             ad,
             ae,
             af,
             ag,
             ah,
             ai,
             aj,
             ak,
             al,
             am,
             an,
             seq,
             load_date,
             table_name
        from (select case table_name
                       when '0002' then
                        1
                       when '9015' then
                        2
                       when '9015A' then
                        3
                     end as ordertable,
                     internal.*
                from (select
                      /*table name  
                      find the table name of the row  by :
                      search in rows above the current row,
                      the nearest line with ~ character in a column .
                      and cut 4 charcters after the ~.*/
                       case
                         when regexp_like(a, '~') then
                          null
                         else
                          last_value(case
                                       when regexp_like(a, '^~[0-9]{4}[A]?~') then
                                       --substr(regexp_substr(a,'~.{4}~'),2,4)
                                        regexp_substr(a, '[0-9]{4}[A]?')
                                       else
                                        null
                                     end ignore nulls)
                          over(order by seq asc rows between unbounded
                               preceding and 1 preceding)
                       end as table_name,
                       last_value(case
                                    when regexp_like(a,
                                                     '^~\d+~\d+~.{0,100}~.{0,1}~.{0,1}~') then
                                     a
                                    else
                                     null
                                  end ignore nulls) over(order by seq asc rows between unbounded preceding and 1 preceding) as main_title
                       
                      ,
                       ld_merkava.*
                        from ld_merkava ld_merkava
                      
                      ) internal
               where table_name is not null
                 and main_title = p_main_title
                 and (case
                       when a is null then
                        ' '
                       else
                        a
                     end) <> '#' --the character "#" is in the last line, which is not normal and ilegal row.
               order by ordertable, seq asc) internal_2;
    --##################
    select case
             when regexp_like(p_main_title,
                              '^~[0-9]{1,100}~[0-9]{1,100}~[0-9]{1,100}~') then
              null
             else
              'the title is not contain nust valid data'
           end
      into recivednustdataintitle
      from dual;
  
    if recivednustdataintitle is not null then
      v_report := '<h4 background-color:yellow>' || recivednustdataintitle ||
                  '<h4/>';
      docommit := false;
    end if;
  
    if docommit then
      --update variable
      select regexp_substr(p_main_title, '\d+', 1, 1) as mispar_oved,
             regexp_substr(p_main_title, '\d+', 1, 2) as zeut,
             regexp_substr(p_main_title, '\d+', 1, 3) as ezor_ovdim
        into v_mispar_oved, v_zeut, v_ezor_ovdim
        from dual;
    
      v_zeut := case
                  when length(v_zeut) <= 20 and length(v_zeut) > 9 then
                   substr(v_zeut, length(v_zeut) - 8)
                  else
                   v_zeut
                end;
    
      --update v_seq_ezor_ovdim
      begin
        select e.seq_ezor_ovdim
          into v_seq_ezor_ovdim
          from code_ezor_ovdim e
         where e.code_makor in (1, 2, 3)
           and e.code_ezor_ovdim = v_ezor_ovdim
           and e.pail = 1;
      exception
        when others then
          v_report := '<h4 background-color:yellow>' || 'code_ezor_ovdim: ' ||
                      sqlerrm || '<h4/>';
          docommit := false;
      end;
    end if;
    --##################
    --check before start insert to a regular tables:
    --if the next nust tables is exist.
    for r in (select table_name
                from ld_temp_merkava_per_tik
               group by table_name) loop
      if must_info_type like '%' || r.table_name || ',%' then
        if r.table_name = '9015A' then
          is_bakasha_regila := 0;
          must_info_type    := replace(must_info_type, '9015,9015A,9017,');
        elsif r.table_name = '9015' then
          is_bakasha_regila := 1;
          must_info_type    := replace(must_info_type, '9015,9015A,');
        else
          must_info_type := replace(must_info_type, r.table_name || ',');
        end if;
      end if;
    end loop;
  
    if trim(must_info_type) is not null then
      receivedmusttables := 'לא נשלח סוג מידע חובה: ' || must_info_type;
      v_report           := '<h4 background-color:yellow>' ||
                            receivedmusttables || '<h4/>';
      docommit           := false;
    end if;
  
    --get seq contact 
    v_seq_contact := get_seq_contact(p_contact, v_seq_ezor_ovdim);
  
    --get old_version_tik
    if is_bakasha_regila = 1 then
      begin
        select v.seq_bakasha
               --if the status is before 'nasham management confirm',
               --it's ok to delete the old version and get the new versin .
              ,
               case
                 when c.CODE_DEPARTMENT = 1 then
                  1
                 else
                  0
               end
          into old_version_seq_bakasha, is_delete_old_version
          from v_regila_last_status v
          left join code_action c
            on v.CODE_ACTION = c.code_action
         where v.mispar_zehut = v_zeut
           and v.seq_ezor_ovdim = v_seq_ezor_ovdim
           and v.CODE_SUG_BAKASHA in (1, 5);
      exception
        when no_data_found then
          old_version_seq_bakasha := null;
      end;
    
      --bakasha mukdemet
    elsif is_bakasha_regila = 0 then
      begin
        --if the status is before 'nasham management confirm',
        --it's ok to delete the old version and get the new versin .
        select v.seq_bakasha,
               case
                 when c.CODE_DEPARTMENT = 1 then
                  1
                 else
                  0
               end
          into old_version_seq_bakasha, is_delete_old_version
          from v_mukdemet_last_status v
          left join code_action c
            on v.CODE_ACTION = c.code_action
         where v.mispar_zehut = v_zeut
           and v.seq_ezor_ovdim = v_seq_ezor_ovdim;
      exception
        when no_data_found then
          old_version_seq_bakasha := null;
      end;
    end if;
  
    if is_delete_old_version = 1 then
    
      select count(*)
        into v_is_exist_netuney_sachar
        from netuney_sachar t
       where t.seq_bakasha = old_version_seq_bakasha;
    
      if v_is_exist_netuney_sachar > 0 then
        --insert bitul action
        pk_prm_utils.insert_action_log_row(17,
                                           sysdate,
                                           0,
                                           null,
                                           'התקבל לתיק נתונים חדשים ממרכבה, יש לבדוק בבקשה החדשה',
                                           null,
                                           null,
                                           null,
                                           old_version_seq_bakasha,
                                           null);
        old_version_seq_bakasha_save := old_version_seq_bakasha;
        old_version_seq_bakasha      := null;
      else
        v_result_delete_bakasha := pk_prm_utils.delete_bakasha(old_version_seq_bakasha);
        old_version_seq_bakasha := null;
      end if;
    end if;
  
    --*************************************************************   
    for rowindata in (select * from ld_temp_merkava_per_tik) loop
      --*********************
      --rowes with table name 0002
      if docommit and rowindata.table_name = '0002' then
        --fill porshim_row
        porshim_row                     := null;
        porshim_row.ora_err_tag$        := rowindata.seq;
        porshim_row.shem_mishpacha      := rowindata.a;
        porshim_row.shem_prati          := rowindata.b;
        porshim_row.mispar_oved_merkava := rowindata.c;
        porshim_row.sug_zihuy           := 1; --  temp
        porshim_row.mispar_zehut        := v_zeut;
        porshim_row.taarich_aliya       := rowindata.e;
        porshim_row.code_min            := rowindata.f;
        porshim_row.taarich_leda        := rowindata.g;
        porshim_row.toar                := rowindata.i;
        porshim_row.shem_kodem          := rowindata.j;
        --check_fields
        if (check_0002_porshim(porshim_row)) then
          --merge into porshim
          merge into poresh porshim
          using dual
          on (porshim.mispar_zehut = porshim_row.mispar_zehut)
          when matched then
            update
               set porshim.shem_mishpacha      = porshim_row.shem_mishpacha,
                   porshim.shem_prati          = porshim_row.shem_prati,
                   porshim.mispar_oved_merkava = porshim_row.mispar_oved_merkava,
                   porshim.taarich_aliya       = to_date(porshim_row.taarich_aliya,
                                                         'yyyymmdd'),
                   porshim.code_min            = porshim_row.code_min,
                   porshim.taarich_leda        = to_date(porshim_row.taarich_leda,
                                                         'yyyymmdd'),
                   porshim.toar                = porshim_row.toar,
                   porshim.shem_kodem          = porshim_row.shem_kodem
          when not matched then
            insert
              (shem_mishpacha,
               shem_prati,
               mispar_oved_merkava,
               mispar_zehut,
               taarich_aliya,
               code_min,
               taarich_leda,
               toar,
               shem_kodem,
               porshim_seq)
            values
              (porshim_row.shem_mishpacha,
               porshim_row.shem_prati,
               porshim_row.mispar_oved_merkava,
               porshim_row.mispar_zehut,
               to_date(porshim_row.taarich_aliya, 'yyyymmdd'),
               porshim_row.code_min,
               to_date(porshim_row.taarich_leda, 'yyyymmdd'),
               porshim_row.toar,
               porshim_row.shem_kodem,
               porshim_seq.nextval) log errors into err_porshim
              (rowindata.seq) reject limit unlimited;
        end if;
        --##################
        --update v_porshim_seq
        begin
          select p.porshim_seq
            into v_porshim_seq
            from poresh p
           where p.mispar_zehut = v_zeut;
        exception
          when no_data_found then
            docommit := false;
            v_report := '<h4>' || 'not found in porshim table' || '<h4/>';
        end;
        --##################
        --rowes with table name 9015
      elsif docommit and rowindata.table_name = '9015' then
      
        v_seq_bakasha := pk_load_mimshak.add_main_tables(v_porshim_seq,
                                                         v_seq_ezor_ovdim,
                                                         1);
        if v_is_exist_netuney_sachar > 0 then
          --duplicate netuney sachar for new bakasha
          pk_prm_utils.duplicate_netuney_sachar_data(v_seq_bakasha,
                                                     old_version_seq_bakasha_save);
        end if;
      
        --fill tikim_row
        tikim_row              := null;
        tikim_row.ora_err_tag$ := rowindata.seq;
        begin
          select code_seif_prisha.code_seif_prisha
            into tikim_row.code_seif_prisha
            from code_seif_prisha
           where code_seif_prisha.code_seif_markava like
                 '%' || rowindata.a || '%';
        exception
          when no_data_found then
            if rowindata.a is not null then
              --set invalid value (convert the orginal value to negative)
              --in order to get an error message from the system.
              tikim_row.code_seif_prisha := - (rowindata.a);
            else
              null;
            end if;
        end;
        tikim_row.taarich_prisha                 := rowindata.b;
        tikim_row.chisuv_lefy_sheerut            := rowindata.c;
        tikim_row.chisuv_lefy_nechut             := rowindata.d;
        tikim_row.ishur_prisha_lo_sof_hodesh     := rowindata.f;
        tikim_row.ishur_prisha_al_af_tik_mishmat := rowindata.g;
        tikim_row.such_yemey_headrut             := rowindata.h;
        tikim_row.such_yemey_headrut_shnirkshu   := rowindata.i;
        tikim_row.nechut_achuz_nechut_leprisha   := rowindata.j;
      
        --check_fields
        if (check_9015_tikim(tikim_row,
                             porshim_row.taarich_leda,
                             rowindata.e)) then
        
          insert into bakasha_regila
            (code_seif_prisha,
             taarich_prisha,
             chisuv_lefy_sheerut,
             chisuv_lefy_nechut,
             ishur_prisha_lo_sof_hodesh,
             ishur_prisha_al_af_tik_mishmat,
             such_yemey_headrut,
             such_yemey_headrut_shnirkshu,
             seq_bakasha,
             nechut_achuz_nechut_leprisha,
             seq_contacts_ministries)
          values
            (tikim_row.code_seif_prisha,
             to_date(tikim_row.taarich_prisha, 'yyyymmdd'),
             tikim_row.chisuv_lefy_sheerut,
             tikim_row.chisuv_lefy_nechut,
             tikim_row.ishur_prisha_lo_sof_hodesh,
             tikim_row.ishur_prisha_al_af_tik_mishmat,
             tikim_row.such_yemey_headrut,
             tikim_row.such_yemey_headrut_shnirkshu,
             v_seq_bakasha,
             tikim_row.nechut_achuz_nechut_leprisha,
             v_seq_contact) log errors into err_bakasha_regila
            (rowindata.seq) reject limit unlimited;
        end if;
        --##################
        v_seif_prisha    := tikim_row.code_seif_prisha;
        v_taarich_prisha := to_date(tikim_row.taarich_prisha, 'yyyymmdd');
        if pk_load_mimshak.count_rowes('err_bakasha_regila') > 0 then
          docommit := false;
          v_report := '<h4>' || 'not found in tikim table' || '<h4/>';
        end if;
      
        --##################  
        if docommit then
          update poresh porshim
             set porshim.taarich_ptira = to_date(rowindata.e, 'yyyymmdd')
           where porshim.porshim_seq = v_porshim_seq log errors into
           err_porshim(rowindata.seq) reject limit unlimited;
        
          --fill netuney_tik_mechushavim_row
          netuney_tik_mechushavim_row                                := null;
          netuney_tik_mechushavim_row.ora_err_tag$                   := rowindata.seq;
          netuney_tik_mechushavim_row.achuz_kizba_chelkiyut_melea    := rowindata.k;
          netuney_tik_mechushavim_row.tikun_27                       := rowindata.l;
          netuney_tik_mechushavim_row.achuz_kizba_kafuf_chelkiyut    := rowindata.m;
          netuney_tik_mechushavim_row.keren_mezaka_shana             := rowindata.n;
          netuney_tik_mechushavim_row.keren_mezaka_chodesh           := rowindata.o;
          netuney_tik_mechushavim_row.keren_mezaka_yamim             := rowindata.p;
          netuney_tik_mechushavim_row.odef_sherut_shanim             := rowindata.q;
          netuney_tik_mechushavim_row.odef_sherut_chodashim          := rowindata.r;
          netuney_tik_mechushavim_row.odef_sherut_yamim              := rowindata.s;
          netuney_tik_mechushavim_row.chodshim_mezkim_achary_hagdala := rowindata.t;
          netuney_tik_mechushavim_row.ahuz_kizb_achry_hagdl_kaf_chel := rowindata.u;
          netuney_tik_mechushavim_row.achuz_kizb_achry_hagdl_chl_mla := rowindata.v;
          netuney_tik_mechushavim_row.chodeshim_mezkim_out_of_srv_y  := rowindata.w;
          netuney_tik_mechushavim_row.chodeshim_mezkim_out_of_srv_m  := rowindata.x;
          netuney_tik_mechushavim_row.chodeshim_mezkim_out_of_srv_d  := rowindata.y;
          netuney_tik_mechushavim_row.chelkiyut_lefi_sherut          := rowindata.z;
          netuney_tik_mechushavim_row.chelkiyut_meshuklelet_sherut   := pk_load_mimshak.Convert_number_to_Decimal(rowindata.aa);
          netuney_tik_mechushavim_row.tkufa_mezaka_sherut            := rowindata.ab;
          netuney_tik_mechushavim_row.tkufa_lo_mezaka_sherut         := rowindata.ac;
          netuney_tik_mechushavim_row.shnot_hagdala_sofi             := rowindata.ad;
          netuney_tik_mechushavim_row.chodshey_hagdala_sofi          := rowindata.ae;
          netuney_tik_mechushavim_row.code_department                := 1;
          netuney_tik_mechushavim_row.seq_bakasha                    := v_seq_bakasha;
          --check_fields
          check_9015_ntny_tik_mechushvm(netuney_tik_mechushavim_row);
          --insert into  netuney_tik_mechushavim              
          insert into netuney_tik_mechushavim
            (achuz_kizba_chelkiyut_melea
             /*  ,tikun_27*/,
             achuz_kizba_kafuf_chelkiyut,
             keren_mezaka_shana,
             keren_mezaka_chodesh,
             keren_mezaka_yamim,
             odef_sherut_shanim,
             odef_sherut_chodashim,
             odef_sherut_yamim,
             chodshim_mezkim_achary_hagdala,
             ahuz_kizb_achry_hagdl_kaf_chel,
             achuz_kizb_achry_hagdl_chl_mla,
             chodeshim_mezkim_out_of_srv_y,
             chodeshim_mezkim_out_of_srv_m,
             chodeshim_mezkim_out_of_srv_d,
             chelkiyut_lefi_sherut,
             chelkiyut_meshuklelet_sherut,
             tkufa_mezaka_sherut,
             tkufa_lo_mezaka_sherut,
             shnot_hagdala_sofi,
             chodshey_hagdala_sofi,
             seq_bakasha,
             seq_netuney_tik_mechushavim,
             code_department)
          values
            (netuney_tik_mechushavim_row.achuz_kizba_chelkiyut_melea
             /* ,netuney_tik_mechushavim_row.tikun_27*/,
             netuney_tik_mechushavim_row.achuz_kizba_kafuf_chelkiyut,
             netuney_tik_mechushavim_row.keren_mezaka_shana,
             netuney_tik_mechushavim_row.keren_mezaka_chodesh,
             netuney_tik_mechushavim_row.keren_mezaka_yamim,
             netuney_tik_mechushavim_row.odef_sherut_shanim,
             netuney_tik_mechushavim_row.odef_sherut_chodashim,
             netuney_tik_mechushavim_row.odef_sherut_yamim,
             netuney_tik_mechushavim_row.chodshim_mezkim_achary_hagdala,
             netuney_tik_mechushavim_row.ahuz_kizb_achry_hagdl_kaf_chel,
             netuney_tik_mechushavim_row.achuz_kizb_achry_hagdl_chl_mla,
             netuney_tik_mechushavim_row.chodeshim_mezkim_out_of_srv_y,
             netuney_tik_mechushavim_row.chodeshim_mezkim_out_of_srv_m,
             netuney_tik_mechushavim_row.chodeshim_mezkim_out_of_srv_d,
             netuney_tik_mechushavim_row.chelkiyut_lefi_sherut,
             netuney_tik_mechushavim_row.chelkiyut_meshuklelet_sherut,
             netuney_tik_mechushavim_row.tkufa_mezaka_sherut,
             netuney_tik_mechushavim_row.tkufa_lo_mezaka_sherut,
             netuney_tik_mechushavim_row.shnot_hagdala_sofi,
             netuney_tik_mechushavim_row.chodshey_hagdala_sofi,
             netuney_tik_mechushavim_row.seq_bakasha,
             netuney_tik_mechushavim_seq.nextval,
             netuney_tik_mechushavim_row.code_department) log errors into err_netuney_tik_mechushavim
            (rowindata.seq) reject limit unlimited;
        end if;
        --*************************************************************
        --rowes with table name 9015A
      elsif docommit and rowindata.table_name = '9015A' then
        --if the tik is 'prisha mukdemet', get the new version anyway.
        v_report := v_report || '<h4>' || ' bakasha mukdemet.' || '<h4/>';
      
        /*    select count(*)
          into count_regila_as_mukdemet
          from v_regila v
         where v.mispar_zehut = v_zeut
           and v.SEQ_EZOR_OVDIM = v_seq_ezor_ovdim;
        if count_regila_as_mukdemet > 0 then
          v_report := v_report || '<h4>' ||
                      'there is exist bakasha regila.' || '<h4/>';
          docommit := false;
        end if;*/
      
        v_seq_bakasha := pk_load_mimshak.add_main_tables(v_porshim_seq,
                                                         v_seq_ezor_ovdim,
                                                         1,
                                                         v_code_sug_bakasha => 2);
      
        --fill tikim_mukdemet_row
        tikim_mukdemet_row              := null;
        tikim_mukdemet_row.ora_err_tag$ := rowindata.seq;
        begin
          select code_seif_prisha.code_seif_prisha
            into tikim_mukdemet_row.code_seif_prisha
            from code_seif_prisha
           where code_seif_prisha.code_seif_markava like
                 '%' || rowindata.a || '%';
        exception
          when no_data_found then
            if rowindata.a is not null then
              --set invalid value (convert the orginal value to negative)
              --in order to get an error message from the system.
              tikim_mukdemet_row.code_seif_prisha := - (rowindata.a);
            else
              null;
            end if;
        end;
        tikim_mukdemet_row.taarich_siyum_sherut         := rowindata.b;
        tikim_mukdemet_row.code_sug_tochnit_prisha      := rowindata.c;
        tikim_mukdemet_row.taarich_bakasha              := rowindata.d;
        tikim_mukdemet_row.code_sug_misra_lebitul       := rowindata.e;
        tikim_mukdemet_row.maskoret_kovaat              := rowindata.x;
        tikim_mukdemet_row.chelkiyut_hasaka_meshuklelet := pk_load_mimshak.Convert_number_to_Decimal(rowindata.y);
        tikim_mukdemet_row.shnot_sherut_bamedina        := rowindata.z;
        tikim_mukdemet_row.taarich_knisa                := rowindata.aa;
        --check_fields
        if (check_9015A_tikim_mukdemet(tikim_mukdemet_row)) then
          insert into bakasha_mukdemet
            (code_seif_prisha,
             taarich_siyum_sherut,
             code_sug_tochnit_prisha,
             taarich_bakasha,
             code_sug_misra_lebitul,
             maskoret_kovaat,
             chelkiyut_hasaka_meshuklelet,
             shnot_sherut_bamedina,
             taarich_knisa,
             seq_bakasha)
          values
            (tikim_mukdemet_row.code_seif_prisha,
             to_date(tikim_mukdemet_row.taarich_siyum_sherut, 'yyyymmdd'),
             tikim_mukdemet_row.code_sug_tochnit_prisha,
             to_date(tikim_mukdemet_row.taarich_bakasha, 'yyyymmdd'),
             tikim_mukdemet_row.code_sug_misra_lebitul,
             tikim_mukdemet_row.maskoret_kovaat,
             tikim_mukdemet_row.chelkiyut_hasaka_meshuklelet,
             tikim_mukdemet_row.shnot_sherut_bamedina,
             to_date(tikim_mukdemet_row.taarich_knisa, 'yyyymmdd'),
             v_seq_bakasha) log errors into err_bakasha_mukdemet
            (rowindata.seq) reject limit unlimited;
        end if;
        --##################
        --update fields
        begin
          select t.code_seif_prisha, t.taarich_siyum_sherut
            into v_seif_prisha, v_taarich_prisha
            from bakasha_mukdemet t
           where t.seq_bakasha = v_seq_bakasha;
        exception
          when no_data_found then
            docommit := false;
            v_report := '<h4>' || 'not found in tikim mukdemet table' ||
                        '<h4/>';
        end;
        --##################
        if docommit then
        
          --delete from misra_lebitul table 
          delete from tikim_mukdemet_misrot_lebitul a
           where a.seq_bakasha = v_seq_bakasha;
        
          add_row_misra_lebitul(v_seq_bakasha,
                                rowindata.seq,
                                rowindata.f,
                                rowindata.g,
                                rowindata.h,
                                rowindata.i,
                                rowindata.j,
                                rowindata.k);
        
          add_row_misra_lebitul(v_seq_bakasha,
                                rowindata.seq,
                                rowindata.l,
                                rowindata.m,
                                rowindata.n,
                                rowindata.o,
                                rowindata.p,
                                rowindata.q);
        
          add_row_misra_lebitul(v_seq_bakasha,
                                rowindata.seq,
                                rowindata.r,
                                rowindata.s,
                                rowindata.t,
                                rowindata.u,
                                rowindata.v,
                                rowindata.w);
        
        end if;
        --*************************************************************
        --rowes with table name 0001
      elsif docommit and rowindata.table_name = '0001' then
        if is_bakasha_regila = 1 then
          --fill tikim_row
          tikim_row                      := null;
          tikim_row.ora_err_tag$         := rowindata.seq;
          tikim_row.misrad_maskoret      := rowindata.a;
          tikim_row.mispar_misra_acharon := rowindata.c;
          tikim_row.teur_misra_acharon   := rowindata.d;
          tikim_row.seq_bakasha          := v_seq_bakasha;
          --check_fields
          check_0001_tikim(tikim_row, v_seq_ezor_ovdim);
          merge into bakasha_regila tikim
          using dual
          on (tikim.seq_bakasha = v_seq_bakasha)
          when matched then
            update
               set tikim.misrad_maskoret      = tikim_row.misrad_maskoret,
                   tikim.mispar_misra_acharon = tikim_row.mispar_misra_acharon,
                   tikim.teur_misra_acharon   = tikim_row.teur_misra_acharon log
                                                errors into err_bakasha_regila(rowindata.seq) reject limit unlimited;
          --************************************************
        elsif is_bakasha_regila = 0 then
          --fill tikim_mukdemet_row
          tikim_mukdemet_row                 := null;
          tikim_mukdemet_row.ora_err_tag$    := rowindata.seq;
          tikim_mukdemet_row.misrad_maskoret := rowindata.a;
          tikim_mukdemet_row.mispar_misra    := rowindata.c;
          tikim_mukdemet_row.toar_misra      := rowindata.d;
          tikim_mukdemet_row.code_derug      := rowindata.e;
          tikim_mukdemet_row.code_darga_me   := rowindata.f;
          tikim_mukdemet_row.code_darga_ad   := rowindata.g;
          tikim_mukdemet_row.seq_bakasha     := v_seq_bakasha;
        
          --check_fields
          check_0001_tikim_mukdemet(tikim_mukdemet_row, v_seq_ezor_ovdim);
          merge into bakasha_mukdemet tikim_mukdemet
          using dual
          on (tikim_mukdemet.seq_bakasha = v_seq_bakasha)
          when matched then
            update
               set tikim_mukdemet.misrad_maskoret = tikim_mukdemet_row.misrad_maskoret,
                   tikim_mukdemet.mispar_misra    = tikim_mukdemet_row.mispar_misra,
                   tikim_mukdemet.toar_misra      = tikim_mukdemet_row.toar_misra,
                   tikim_mukdemet.code_derug      = tikim_mukdemet_row.code_derug,
                   tikim_mukdemet.code_darga_me   = tikim_mukdemet_row.code_darga_me,
                   tikim_mukdemet.code_darga_ad   = tikim_mukdemet_row.code_darga_ad log
                                                    errors into err_bakasha_mukdemet(rowindata.seq) reject limit unlimited;
        end if;
      
        --*************************************************************
        --rowes with table name 0105
      elsif docommit and rowindata.table_name = '0105' then
        update poresh porshim
           set porshim.telephon  = rowindata.a,
               porshim.pelephon  = rowindata.b,
               porshim.telephon2 = rowindata.c
         where porshim.porshim_seq = v_porshim_seq log errors into
         err_porshim(rowindata.seq) reject limit unlimited;
        --************************************************************* 
        --rowes with table name 0552
      elsif docommit and rowindata.table_name = '0552' then
        --fill tkufot_avoda_golmi_row
        tkufot_avoda_golmi_row                   := null;
        tkufot_avoda_golmi_row.ora_err_tag$      := rowindata.seq;
        tkufot_avoda_golmi_row.taarich_me        := rowindata.a;
        tkufot_avoda_golmi_row.taarich_ad        := rowindata.b;
        tkufot_avoda_golmi_row.code_sugey_tkufot := rowindata.c;
        begin
          select max(ezor_ovdim_be_tkufa.seq_ezor_ovdim)
            into tkufot_avoda_golmi_row.ezor_ovdim_be_tkufa
            from code_ezor_ovdim ezor_ovdim_be_tkufa
           where ezor_ovdim_be_tkufa.code_ezor_ovdim = rowindata.d
             and ezor_ovdim_be_tkufa.code_makor in (1, 2, 3)
             and ezor_ovdim_be_tkufa.pail = 1;
        exception
          when no_data_found then
            if rowindata.d is not null then
              --set invalid value (convert the orginal value to negative)
              --in order to get an error message from the system.
              tkufot_avoda_golmi_row.ezor_ovdim_be_tkufa := - (rowindata.d);
            else
              null;
            end if;
          when others then
            tkufot_avoda_golmi_row.ezor_ovdim_be_tkufa := sqlcode || ': ' ||
                                                          sqlerrm;
        end;
        tkufot_avoda_golmi_row.code_sugey_haasaka     := rowindata.e;
        tkufot_avoda_golmi_row.code_sugey_zchuyot     := rowindata.f;
        tkufot_avoda_golmi_row.except_from_tkufa :=
                                    CASE
                                      WHEN rowindata.h IS NULL THEN NULL
                                      ELSE round(TO_NUMBER(rowindata.h) / 30.44, 2)
                                    END;
        tkufot_avoda_golmi_row.achuz_chelkyut         := pk_load_mimshak.Convert_number_to_Decimal(rowindata.g);
        tkufot_avoda_golmi_row.seq_tkufot_avoda_golmi := tkufot_avoda_golmi_seq.nextval;
        tkufot_avoda_golmi_row.seq_bakasha            := v_seq_bakasha;
        --check_fields
        if (check_0552_tkufot_avoda_golmi(tkufot_avoda_golmi_row,
                                          v_seq_bakasha)) then
          -- insert into  tkufot_avoda_golmi
          insert into tkufot_avoda_golmi
            (taarich_me,
             taarich_ad,
             code_sugey_tkufot,
             ezor_ovdim_be_tkufa,
             code_sugey_haasaka,
             code_sugey_zchuyot,
             achuz_chelkyut,
             seq_tkufot_avoda_golmi,
             seq_bakasha,
             EXCEPT_FROM_TKUFA
             )
          values
            (to_date(tkufot_avoda_golmi_row.taarich_me, 'yyyymmdd'),
             to_date(tkufot_avoda_golmi_row.taarich_ad, 'yyyymmdd'),
             tkufot_avoda_golmi_row.code_sugey_tkufot,
             tkufot_avoda_golmi_row.ezor_ovdim_be_tkufa,
             tkufot_avoda_golmi_row.code_sugey_haasaka,
             tkufot_avoda_golmi_row.code_sugey_zchuyot,
             tkufot_avoda_golmi_row.achuz_chelkyut,
             tkufot_avoda_golmi_row.seq_tkufot_avoda_golmi,
             tkufot_avoda_golmi_row.seq_bakasha,
             tkufot_avoda_golmi_row.except_from_tkufa
             ) log errors into err_tkufot_avoda_golmi
            (rowindata.seq) reject limit unlimited;
        end if;
        --*************************************************************   
        --rowes with table name  0023
      elsif docommit and rowindata.table_name = '0023' then
        --fill tkufot_michutz_lasharut_row
        tkufot_michutz_lasharut_row                      := null;
        tkufot_michutz_lasharut_row.ora_err_tag$         := rowindata.seq;
        tkufot_michutz_lasharut_row.taarich_me           := rowindata.a;
        tkufot_michutz_lasharut_row.taarich_ad           := rowindata.b;
        tkufot_michutz_lasharut_row.code_sug_makom_avoda := rowindata.c;
        tkufot_michutz_lasharut_row.code_sugey_zchuyot   := rowindata.d;
        tkufot_michutz_lasharut_row.code_keren_pensia    := rowindata.e;
        tkufot_michutz_lasharut_row.taarich_heskem       := rowindata.g;
        --check_fields
        if (check_0023_michutz_lasharut(tkufot_michutz_lasharut_row)) then
          -- insert into  tkufot_michutz_lasharut
          insert into tkufot_michutz_lasharut
            (taarich_me,
             taarich_ad,
             code_sug_makom_avoda,
             code_sugey_zchuyot,
             code_keren_pensia,
             taarich_heskem,
             seq_tkufot_michutz_lasharut,
             seq_bakasha)
          values
            (to_date(tkufot_michutz_lasharut_row.taarich_me, 'yyyymmdd'),
             to_date(tkufot_michutz_lasharut_row.taarich_ad, 'yyyymmdd'),
             tkufot_michutz_lasharut_row.code_sug_makom_avoda,
             tkufot_michutz_lasharut_row.code_sugey_zchuyot,
             tkufot_michutz_lasharut_row.code_keren_pensia,
             to_date(tkufot_michutz_lasharut_row.taarich_heskem, 'yyyymmdd'),
             tkufot_michutz_lasharut_seq.nextval,
             v_seq_bakasha) log errors into err_tkufot_michutz_lasharut
            (rowindata.seq) reject limit unlimited;
        end if;
        --*************************************************************    
        --rowes with table name 0008
      elsif docommit and rowindata.table_name = '0008' then
        --fill darga_vederug_tik_row
        darga_vederug_tik_row                := null;
        darga_vederug_tik_row.ora_err_tag$   := rowindata.seq;
        darga_vederug_tik_row.taarich_me     := rowindata.a;
        darga_vederug_tik_row.taarich_ad     := rowindata.b;
        darga_vederug_tik_row.code_derug     := rowindata.c;
        darga_vederug_tik_row.code_darga     := rowindata.d;
        darga_vederug_tik_row.code_sug_darga := rowindata.e;
        --check_fields
        if (check_0008_darga_vederug(darga_vederug_tik_row)) then
          --insert into  darga_vederug_tik
          insert into darga_vederug_tik
            (taarich_me,
             taarich_ad,
             code_derug,
             code_darga,
             code_sug_darga,
             seq_dargot_vederug_tik,
             seq_bakasha)
          values
            (to_date(darga_vederug_tik_row.taarich_me, 'yyyymmdd'),
             to_date(darga_vederug_tik_row.taarich_ad, 'yyyymmdd'),
             darga_vederug_tik_row.code_derug,
             darga_vederug_tik_row.code_darga,
             darga_vederug_tik_row.code_sug_darga,
             darga_vederug_tik_seq.nextval,
             v_seq_bakasha) log errors into err_darga_vederug_tik
            (rowindata.seq) reject limit unlimited;
        end if;
        --************************************************************* 
        --rowes with table name 0081
      elsif docommit and rowindata.table_name = '0081' then
        --fill tkufot_sherut_tsvaii_row
        tkufot_sherut_tsvaii_row                          := null;
        tkufot_sherut_tsvaii_row.ora_err_tag$             := rowindata.seq;
        tkufot_sherut_tsvaii_row.taarich_me               := rowindata.a;
        tkufot_sherut_tsvaii_row.taarich_ad               := rowindata.b;
        tkufot_sherut_tsvaii_row.code_sug_sherut_tzaii    := rowindata.c;
        tkufot_sherut_tsvaii_row.taarich_zchuyot          := rowindata.d;
        tkufot_sherut_tsvaii_row.seq_tkufot_sherut_tsvaii := tkufot_sherut_tsvaii_seq.nextval;
        tkufot_sherut_tsvaii_row.seq_bakasha              := v_seq_bakasha;
        --check required fields.
        if (check_0081_sherut_svaii(tkufot_sherut_tsvaii_row)) then
          --insert into  tkufot_sherut_tsvaii
          insert into tkufot_sherut_tsvaii
            (taarich_me,
             taarich_ad,
             code_sug_sherut_tzaii,
             taarich_zchuyot,
             seq_tkufot_sherut_tsvaii,
             seq_bakasha)
          values
            (to_date(tkufot_sherut_tsvaii_row.taarich_me, 'yyyymmdd'),
             to_date(tkufot_sherut_tsvaii_row.taarich_ad, 'yyyymmdd'),
             tkufot_sherut_tsvaii_row.code_sug_sherut_tzaii,
             to_date(tkufot_sherut_tsvaii_row.taarich_zchuyot, 'yyyymmdd'),
             tkufot_sherut_tsvaii_row.seq_tkufot_sherut_tsvaii,
             tkufot_sherut_tsvaii_row.seq_bakasha) log errors into err_tkufot_sherut_tsvaii
            (rowindata.seq) reject limit unlimited;
        end if;
        --*************************************************************
        --rowes with table name 0004
        --now, 0004 is loaded only for regular tikim
        --in the future, we will load it also for tikim_mukdemet.
      elsif docommit and is_bakasha_regila = 1 and
            rowindata.table_name = '0004' then
        --fill tikim_row
        tikim_row                                := null;
        tikim_row.ora_err_tag$                   := rowindata.seq;
        tikim_row.nechut_achuz                   := rowindata.a;
        tikim_row.nechut_migbala_bknisa_lesherut := rowindata.b;
        tikim_row.nechut_taarich_hamigbala       := rowindata.c;
      
        --check required fields.
        if (check_0004_tikim(tikim_row)) then
          -- merge into tikim
          merge into bakasha_regila tikim
          using dual
          on (tikim.seq_bakasha = v_seq_bakasha)
          when matched then
            update
               set tikim.nechut_migbala_bknisa_lesherut = tikim_row.nechut_migbala_bknisa_lesherut,
                   tikim.nechut_achuz                   = tikim_row.nechut_achuz,
                   tikim.nechut_taarich_hamigbala       = to_date(tikim_row.nechut_taarich_hamigbala,
                                                                  'yyyymmdd')
            -- add insert part because of the bug of oracle.
            -- in order to consider in the check constraints.
            
          
          when not matched then
            insert
              (seq_bakasha)
            values
              (999999) log errors into err_bakasha_regila
              (rowindata.seq) reject limit unlimited;
        end if;
        --*************************************************************
        --rowes with table name 9017
      elsif docommit and rowindata.table_name = '9017' then
        --fill tkufot_avoda_mechushv_row
        tkufot_avoda_mechushv_row                    := null;
        tkufot_avoda_mechushv_row.ora_err_tag$       := rowindata.seq;
        tkufot_avoda_mechushv_row.taarich_me         := rowindata.a;
        tkufot_avoda_mechushv_row.taarich_ad         := rowindata.b;
        tkufot_avoda_mechushv_row.code_sugey_tkufot  := rowindata.c;
        tkufot_avoda_mechushv_row.sach_chodeshim     := rowindata.d;
        tkufot_avoda_mechushv_row.code_sugey_zchuyot := rowindata.e;
        tkufot_avoda_mechushv_row.achuz_chelkyut     := pk_load_mimshak.Convert_number_to_Decimal(rowindata.f);
        begin
          select max(ezor_ovdim_be_tkufa.seq_ezor_ovdim)
            into tkufot_avoda_mechushv_row.ezor_ovdim_be_tkufa
            from code_ezor_ovdim ezor_ovdim_be_tkufa
           where ezor_ovdim_be_tkufa.code_ezor_ovdim = rowindata.g
             and ezor_ovdim_be_tkufa.code_makor in (1, 2, 3);
        exception
          when no_data_found then
            if rowindata.g is not null then
              --set invalid value (convert the orginal value to negative)
              --in order to get an error message from the system.
              tkufot_avoda_mechushv_row.ezor_ovdim_be_tkufa := - (rowindata.g);
            else
              null;
            end if;
        end;
        tkufot_avoda_mechushv_row.code_sugey_haasaka := rowindata.h;
        tkufot_avoda_mechushv_row.praklit            := rowindata.i;
        tkufot_avoda_mechushv_row.except_from_tkufa  := 
                                                     CASE
                                                        WHEN rowindata.j IS NULL THEN NULL
                                                        ELSE round(TO_NUMBER(rowindata.j) / 30.44, 2)
                                                      END;
        --check required fields.
        if (check_9017_tkufot_mechshv(tkufot_avoda_mechushv_row,
                                      v_seq_bakasha)) then
          --insert into  tkufot_avoda_mechushv
          insert into tkufot_avoda_mechushv
            (taarich_me,
             taarich_ad,
             code_sugey_tkufot,
             sach_chodeshim,
             code_sugey_zchuyot,
             achuz_chelkyut,
             ezor_ovdim_be_tkufa,
             code_sugey_haasaka,
             praklit,
             EXCEPT_FROM_TKUFA,
             seq_tkufot_avoda_mechushv,
             seq_bakasha)
          values
            (to_date(tkufot_avoda_mechushv_row.taarich_me, 'yyyymmdd'),
             to_date(tkufot_avoda_mechushv_row.taarich_ad, 'yyyymmdd'),
             tkufot_avoda_mechushv_row.code_sugey_tkufot,
             tkufot_avoda_mechushv_row.sach_chodeshim,
             tkufot_avoda_mechushv_row.code_sugey_zchuyot,
             tkufot_avoda_mechushv_row.achuz_chelkyut,
             tkufot_avoda_mechushv_row.ezor_ovdim_be_tkufa,
             tkufot_avoda_mechushv_row.code_sugey_haasaka,
             tkufot_avoda_mechushv_row.praklit,
             tkufot_avoda_mechushv_row.except_from_tkufa,
             tkufot_avoda_mechushav_seq.nextval,
             v_seq_bakasha ) log errors into err_tkufot_avoda_mechushv
            (rowindata.seq) reject limit unlimited;
        end if;
        --*************************************************************  
      end if;
    end loop;
  
    --update misra
    pk_prm_utils.update_misra_when_choze_bchirim(v_seq_bakasha);
  
    if docommit then
      if is_bakasha_regila = 1 then
        --update code sug bakasha
        v_code_sug_bakasha := pk_prm_utils.get_sug_bakasha(v_seq_bakasha);
      end if;
    
      pk_zakaut.internal_main(v_seq_bakasha, 2);
    
    end if;
  
    v_report := v_report ||
                pk_load_mimshak.info_about_errors_and_commit(docommit,
                                                             1,
                                                             v_seq_ezor_ovdim,
                                                             v_zeut,
                                                             v_report_varchar,
                                                             v_mispar_oved,
                                                             v_seq_bakasha,
                                                             old_version_seq_bakasha);
    delete_from_ld_merkava(docommit, p_main_title);
    return v_report;
  end;
  ------------------------------------------------
end;
/

