       regila_row.kizba_after_hagdala,
       regila_row.is_hitzhir_eino_oved,
       regila_row.is_sheer_chose_pitzuim,
       regila_row.is_lo_hotzi_pitzuim,
       regila_row.vetek,
       regila_row.date_end_work,
       regila_row.makor_gimla_nosefet,
       regila_row.is_mevutach_beguf,
       regila_row.has_another_income,
       regila_row.psul_histakrut,
       regila_row.date_bakasha_hivun,
       regila_row.maskoret_kovaat,
       regila_row.code_sub_seif_prisha,
       regila_row.seq_baalut,
       regila_row.code_chavra,
       regila_row.date_payment,
