  ----------------------------------------------------------
  function Convert_number_to_Decimal(p_number number) return number is
  begin
    if p_number > 0 and p_number < 2 then
      return p_number;
    else
      return p_number / 100;
    end if;
  end;
  ----------------------------------------------------------
  function get_new_code_seif_prisha(p_old_code_seif_prisha number)
    return number is
  begin
    return case p_old_code_seif_prisha when 015 then 126 when 018 then 118 when 417 then 92 when 517 then 92 when 717 then 92 when 617 then 92 when 817 then 92 when 915 then 415 when 126 then 126 when 128 then 128 when 415 then 415 when 117 then 117 when 118 then 118 when 138 then 138 when 162 then 162 when 171 then 171 when 215 then 215 when 217 then 217 when 226 then 226 when 228 then 228 when 315 then 315 when 317 then 317 when 326 then 326 when 328 then 328 when 92 then 92 when 426 then 426 when 428 then 428 when 526 then 526 when 528 then 528 when 815 then 415 when 915 then 415 end;
  end;
  ----------------------------------------------------------
  function get_new_code_sub_seif_prisha(p_old_code_seif_prisha number)
    return number is
  begin
    if p_old_code_seif_prisha in (417, 517, 617, 717, 817) then
      return p_old_code_seif_prisha;
    else
      return null;
    end if;
  end;
  ---------------------------------------------------
  function is_exist_poresh(v_mispar_zehut varchar2,
                           v_seq_poresh   out number) return boolean is
  begin
    begin
      select p.porshim_seq
        into v_seq_poresh
        from poresh p
       where p.mispar_zehut = v_mispar_zehut;
    exception
      when no_data_found then
        v_seq_poresh := null;
        return false;
    end;
    return true;
  end;
  --------------------------------------------------
  function is_exist_prisha(v_porshim_seq    number,
                           v_seq_ezor_ovdim number,
                           v_seq_prisha     out number) return boolean is
  begin
    /*begin*/
    --Add the word 'max()' until fix the problem:
    --It is not true - duplicate 'prisha' in same key of :seq_poresh,seq_ezor_ovdim
    select max(t.seq_prisha)
      into v_seq_prisha
      from prisha t
     where t.seq_poresh = v_porshim_seq
       and t.seq_ezor_ovdim = v_seq_ezor_ovdim;
  
    if v_seq_prisha is null then
      return false;
    end if;
    /*  exception
      when no_data_found then
        v_seq_prisha := null;
        return false;
    end;*/
    return true;
  end;
  --------------------------------------------------
  function is_exist_previous_regila(v_seq_poresh          number,
                                    v_seq_ezor_ovdim      number,
                                    v_code_sug_bakasha    number,
                                    v_seq_previous_regila out number)
    return boolean is
  begin
    begin
      select t.seq_bakasha
        into v_seq_previous_regila
        from v_regila_last_status_versions t
       where t.seq_porshim = v_seq_poresh
         and t.seq_ezor_ovdim = v_seq_ezor_ovdim
         and t.code_sug_bakasha = v_code_sug_bakasha;
    exception
      when no_data_found then
        v_seq_previous_regila := null;
        return false;
    end;
    return true;
  end;
  --------------------------------------------------
  function get_bakasha_regila_by_previous(v_seq_regila_previous number)
    return err_bakasha_regila%rowtype is
    v_err_regila err_bakasha_regila%rowtype;
  begin
    begin
      select null, null, null, null, null, b.*
        into v_err_regila
        from bakasha_regila b
       where b.seq_bakasha = v_seq_regila_previous;
    exception
      when no_data_found then
        v_err_regila := null;
    end;
    return v_err_regila;
  end;
  -----------------------------------------------
  function insert_bakasha_regila(v_code_source      number,
                                 regila_row         in out err_bakasha_regila%rowtype,
                                 v_seq_poresh       number,
                                 v_seq_ezor_ovdim   number,
                                 v_date_bakasha     date,
                                 v_code_sug_bakasha number,
                                 p_code_unit        number default null)
    return number is
    v_seq_bakasha number;
  begin
    v_seq_bakasha          := add_main_tables(v_seq_poresh,
                                              v_seq_ezor_ovdim,
                                              v_code_source,
                                              v_date_bakasha     => v_date_bakasha,
                                              v_code_sug_bakasha => v_code_sug_bakasha,
                                              v_code_unit        => p_code_unit);
    regila_row.seq_bakasha := v_seq_bakasha;
    insert_bakasha_regila_table(regila_row);
    return v_seq_bakasha;
  end;
  ----------------------------------------------------------
  procedure duplicate_bakasha(v_seq_regila_previous number,
                              v_date_bakasha        date,
                              v_code_sug_bakasha    number) is
    v_err_regila     err_bakasha_regila%rowtype;
    v_seq_bakasha    number;
    v_seq_poresh     number;
    v_seq_ezor_ovdim number;
    v_code_source    number;
  begin
    select t.seq_porshim, t.SEQ_EZOR_OVDIM, b.code_source
      into v_seq_poresh, v_seq_ezor_ovdim, v_code_source
      from v_regila_last_status_versions t
      left join bakasha b
        on t.seq_bakasha = b.seq_bakasha
     where t.seq_bakasha = v_seq_regila_previous;
    --get_bakasha_regila_by_previous
    v_err_regila := get_bakasha_regila_by_previous(v_seq_regila_previous);
    --insert_bakasha_regila
    v_seq_bakasha := insert_bakasha_regila(v_code_source,
                                           v_err_regila,
                                           v_seq_poresh,
                                           v_seq_ezor_ovdim,
                                           v_date_bakasha,
                                           v_code_sug_bakasha);
  
    commit;
  
  end;
  ------------------------------------------------
  procedure Add_main_tables_internal(v_seq_bakasha         number,
                                     v_porshim_seq         number,
                                     v_seq_ezor_ovdim      number,
                                     v_code_source         number,
                                     v_code_sug_bakasha    number default null,
                                     v_date_bakasha        date default sysdate,
                                     v_code_unit           number default null,
                                     p_seq_beny_mishpacha  number default null,
                                     p_code_bakasha_detail number default null) is
    v_seq_prisha             number;
    v_final_code_sug_bakasha number;
    v_code_source_1          number;
  begin
    if pk_load_mimshak.is_exist_prisha(v_porshim_seq,
                                       v_seq_ezor_ovdim,
                                       v_seq_prisha) = false then
      v_seq_prisha := prisha_seq.nextval;
    end if;
  
    --merge into prisha table
    merge into prisha
    using dual
    on (prisha.seq_prisha = v_seq_prisha)
    when matched then
      update set seq_code_unit = v_code_unit
    when not matched then
      insert
        (seq_poresh, seq_ezor_ovdim, seq_prisha, seq_code_unit)
      values
        (V_porshim_seq, V_seq_ezor_ovdim, v_seq_prisha, v_code_unit) log errors into err_prisha reject limit unlimited;
  
    --update gimla number
    pk_prm_utils.Get_gimla_without_commit(v_seq_prisha, 0);
  
    --insert into bakasha table
    if v_code_sug_bakasha is null then
      v_final_code_sug_bakasha := 99;
    else
      v_final_code_sug_bakasha := v_code_sug_bakasha;
    end if;
    
    --bitachon rashi-change code source for specific wf
    if v_seq_ezor_ovdim = 10149 and v_code_sug_bakasha = 1 then
      v_code_source_1 := 26;
    end if;
  
    insert into bakasha
      (seq_bakasha,
       seq_prisha,
       code_sug_bakasha,
       date_bakasha,
       code_source,
       SEQ_BNEY_MISHPACHA,
       
       code_bakasha_detail,
       shem_meadken_acharon)
    values
      (v_seq_bakasha,
       v_seq_prisha,
       v_final_code_sug_bakasha,
       v_date_bakasha,
       nvl(v_code_source_1,v_code_source),
       p_seq_beny_mishpacha,
       p_code_bakasha_detail,
       SYS_CONTEXT('USERENV','OS_USER')) log errors into err_bakasha reject limit unlimited;
  end;
  ------------------------------------------------
  procedure Add_details_tables(p_seq_bakasha      number,
                               p_code_sug_bakasha number) is
    v_is_exists_participation number;
  begin
    --add participation if not exsits record
    if p_code_sug_bakasha in (7, 8) then
      select count(*)
        into v_is_exists_participation
        from participation
       where seq_bakasha = p_seq_bakasha;
      if v_is_exists_participation = 0 then
        insert into participation
          (seq_participation, code_participation, seq_bakasha,shem_meadken_acharon)
        values
          (participation_seq.nextval,
           case when p_code_sug_bakasha = 8 then 1 when
           p_code_sug_bakasha = 7 then 2 else null end,
           p_seq_bakasha,
           SYS_CONTEXT('USERENV','OS_USER'));
      end if;
    end if;
    --sheer pensyoni seif 128
    if p_code_sug_bakasha = 13 then
      merge into bakasha_regila
      using dual
      on (seq_bakasha = p_seq_bakasha)
      when matched then
        update set code_seif_prisha = 128, code_sub_seif_prisha = null
      when not matched then
        insert
          (seq_bakasha, code_seif_prisha, code_sub_seif_prisha)
        values
          (p_seq_bakasha, 128, null);
    
    end if;
  end;
  ------------------------------------------------
  function Add_main_tables(v_porshim_seq         number,
                           v_seq_ezor_ovdim      number,
                           v_code_source         number,
                           v_code_sug_bakasha    number default null,
                           v_date_bakasha        date default sysdate,
                           v_code_unit           number default null,
                           p_seq_beny_mishpacha  number default null,
                           p_code_bakasha_detail number default null)
    return varchar2 is
    v_seq_bakasha number;
  begin
    v_seq_bakasha := bakasha_seq.nextval;
    Add_main_tables_internal(v_seq_bakasha,
                             v_porshim_seq,
                             v_seq_ezor_ovdim,
                             v_code_source,
                             v_code_sug_bakasha,
                             v_date_bakasha,
                             v_code_unit,
                             p_seq_beny_mishpacha,
                             p_code_bakasha_detail);
    ---when ezor_ovdim=doar, send mail to menahel gvia
    if v_seq_ezor_ovdim in (191, 194) and v_code_sug_bakasha in (3, 5, 14) then
      send_mail_to_menahel_gvia(v_porshim_seq);
    end if;
  
    return v_seq_bakasha;
  
  end;
  ------------------------------------------------
  procedure send_mail_to_menahel_gvia(v_porshim_seq number) is
    v_mispar_zehut number;
    v_shem         nvarchar2(100);
    v_mail         nvarchar2(100);
    v_file         clob;
  begin
    select p.mispar_zehut, p.shem_prati || ' ' || p.shem_mishpacha
      into v_mispar_zehut, v_shem
      from poresh p
     where p.porshim_seq = v_porshim_seq;
  
    select u.email
      into v_mail
      from code_user u
      left join perm_user_role r
        on u.id_user = r.code_user
      left join perm_user_role_chelkiut c
        on r.seq_perm_user_role = c.seq_perm_user_role
       and c.chelkiut = 1
     where r.code_role = 12
       and u.sign_img_path is not null
       and rownum = 1;
    v_file := '';
    pk_prm_utils.send_attach('naamaba@mof.gov.il',
                             'New bakasha from Doar Ministery',
                             'ID: ' || v_mispar_zehut,
                             v_file,
                             'txt',
                             '');
  end;

  ------------------------------------------------
  function compare_fields_betwn_versions(new_seq_bakasha        number,
                                         old_seq_bakasha        number,
                                         get_new_version_tik    in number,
                                         get_new_version_reason in out varchar2)
    return number is
    count_merge_versions number;
  begin
    select count(*)
      into count_merge_versions
      from (select distinct t1.taarich_prisha,
                            --  t1.code_seif_prisha,
                            t1.Nechut_achuz_nechut_leprisha,
                            t1.chinuch_mikzoa
              from bakasha_regila t1
             where t1.seq_bakasha in (new_seq_bakasha, old_seq_bakasha)) base;
  
    if count_merge_versions <> 1 then
      get_new_version_reason := get_new_version_reason || ' שדות פרישה';
      return 1;
    end if;
    return get_new_version_tik;
  end;
  ------------------------------------------------
  function compr_hagdalot_betwn_versions(new_seq_bakasha        number,
                                         old_seq_bakasha        number,
                                         get_new_version_tik    in number,
                                         get_new_version_reason in out varchar2)
    return number is
    v_count_different_rows number;
  begin
    with a as
     (select t1.code_nimuk, t1.achuz_meushar
        from hagdala_nimuk t1
       where t1.seq_bakasha = old_seq_bakasha),
    b as
     (select t1.code_nimuk, t1.achuz_meushar
        from hagdala_nimuk t1
       where t1.seq_bakasha = new_seq_bakasha)
    select count(*)
      into v_count_different_rows
      from ((select * from a minus select * from b) union all
            (select * from b minus select * from a));
  
    if v_count_different_rows > 0 then
      get_new_version_reason := get_new_version_reason || ' הגדלות';
      return 1;
    end if;
    return get_new_version_tik;
  end;
  ------------------------------------------------
  function compare_netunim_mechushav(new_seq_bakasha        number,
                                     old_seq_bakasha        number,
                                     get_new_version_tik    in number,
                                     get_new_version_reason in out varchar2)
    return number is
    count_merge_versions number;
  begin
    select count(*)
      into count_merge_versions
      from (select distinct t1.tkufa_mezaka_sherut,
                            t1.tkufa_lo_mezaka_sherut,
                            t1.chelkiyut_meshuklelet_sherut,
                            t1.achuz_kizba_kafuf_chelkiyut,
                            t1.achuz_kizba_chelkiyut_melea
            
              from netuney_tik_mechushavim t1
             where t1.code_department = 2
               and t1.mispar_misra = 0
               and t1.seq_bakasha in (new_seq_bakasha, old_seq_bakasha)) base;
  
    if count_merge_versions <> 1 then
      get_new_version_reason := get_new_version_reason ||
                                ' נתונים מחושבים ';
      return 1;
    end if;
    return get_new_version_tik;
  end;
  ------------------------------------------------
  function compare_tkufot_betwn_versions(new_seq_bakasha        number,
                                         old_seq_bakasha        number,
                                         get_new_version_tik    in number,
                                         get_new_version_reason in out varchar2)
    return number is
    v_count_different_rows number;
  begin
    with a as
     (select t1.taarich_me,
             t1.taarich_ad,
             t1.achuz_chelkyut,
             t1.code_sugey_zchuyot,
             t1.code_sugey_tkufot
        from tkufot_avoda_golmi t1
       where t1.seq_bakasha = old_seq_bakasha),
    b as
     (select t1.taarich_me,
             t1.taarich_ad,
             t1.achuz_chelkyut,
             t1.code_sugey_zchuyot,
             t1.code_sugey_tkufot
        from tkufot_avoda_golmi t1
       where t1.seq_bakasha = new_seq_bakasha)
    select count(*)
      into v_count_different_rows
      from ((select * from a minus select * from b) union all
            (select * from b minus select * from a));
  
    if v_count_different_rows > 0 then
      get_new_version_reason := get_new_version_reason || ' tkufot golmi';
      return 1;
    end if;
    return get_new_version_tik;
  end;
