  ------------------------------------------------

  --This function return :
  -- 1 - other ministries.
  -- 2 - health ministry.

  function Get_ezor_ovdim_category(p_seq_ezor_ovdim number) return number is
    v_code_ezor_ovdim number;
    v_code_makor      number;
  begin
    select t.code_ezor_ovdim, t.code_makor
      into v_code_ezor_ovdim, v_code_makor
      from CODE_EZOR_OVDIM t
     where t.seq_ezor_ovdim = p_seq_ezor_ovdim;
    if v_code_makor in (1, 2) then
      if v_code_ezor_ovdim between 2400 and 2499 then
        return 2;
      else
        return 1;
      end if;
    else
      return 0;
    end if;
  
  end;
  ------------------------------------------------

  --This function return :
  -- 114 - other ministries.
  -- 115 - health ministry.

  function Get_user_id_by_category(p_seq_ezor_ovdim number) return number is
    v_user_id number;
  begin
    v_user_id := Get_ezor_ovdim_category(p_seq_ezor_ovdim);
  
    return case v_user_id when 1 then 2215 else 115 end;
  
  end;
  ------------------------------------------------
  function exist_rowes_with_condition(tbl_name        varchar2,
                                      field_name      varchar2,
                                      value_condition number) return varchar2 is
    is_exist varchar2(1);
  begin
    execute immediate 'select case when count(*) > 0 then ''Y'' else  ''N'' end from ' ||
                      tbl_name || ' where ' || field_name || ' = ' ||
                      value_condition
      into is_exist;
    return is_exist;
  end;
  ------------------------------------------------
  function count_rowes(tbl varchar2, p_where varchar2 default null)
    return varchar2 is
    i varchar2(100);
  begin
    execute immediate 'select count(*) from ' || tbl || p_where
      into i;
    return i;
  end;
  ------------------------------------------------
  function convert_clob_to_blob(v_clob clob) return blob is
    v_blob    blob;
    v_in      Pls_Integer := 1;
    v_out     Pls_Integer := 1;
    v_lang    Pls_Integer := 0;
    v_warning Pls_Integer := 0;
  begin
    --convert report to blob
    dbms_lob.createtemporary(v_blob, TRUE);
    DBMS_LOB.convertToBlob(v_blob,
                           v_clob,
                           DBMS_lob.getlength(v_clob),
                           v_in,
                           v_out,
                           DBMS_LOB.default_csid,
                           v_lang,
                           v_warning);
    return v_blob;
  end;
  ------------------------------------------------
  function get_seq_bakasha(makor          number,
                           seq_ezor_ovdim number,
                           seq_porshim    number) return number is
    i number;
  begin
    execute immediate 'select seq_bakasha from tikim where code_makor = ' ||
                      makor || ' and seq_ezor_ovdim = ' || seq_ezor_ovdim ||
                      ' and seq_porshim = ' || seq_porshim || ';'
      into i;
    return i;
  end;
  ------------------------------------------------
  function get_date_error(r rowid, v_err_table varchar2) return varchar2 is
    s varchar2(30000);
  begin
    for c in (select column_name, t.data_length, t.data_precision
                from user_tab_cols t
               where table_name = upper(trim(substr(v_err_table, 5)))
                 and data_type = 'DATE') loop
      s := 'declare ' || chr(10) || '  d date;' || chr(10) || 'begin ' ||
           chr(10) || '  select TO_DATE(' || c.column_name ||
           ',''yyyymmdd''
             ,''NLS_DATE_LANGUAGE = American'') ' || chr(10) ||
           '  into d' || chr(10) || '  from ' || v_err_table || chr(10) ||
           '  where rowid = :1' || chr(10) || '  ;' || chr(10) ||
           ' exception ' || chr(10) || ' when others then ' || chr(10) ||
           ' raise_application_error(-20000,''' || c.column_name || ''');' ||
           chr(10) || 'end;';
      -- dbms_output.put_line(s);
      --  dbms_output.put_line(c.column_name);
      execute immediate s
        using r;
    end loop;
    return 'Unknown erorr';
  exception
    when others then
      return replace(SQLERRM, 'ORA-20000: ');
  end;

  ------------------------------------------------
  function get_numeric_error(r rowid, v_err_table varchar2) return varchar2 is
    s varchar2(30000);
  begin
    for c in (select column_name, t.data_length, t.data_precision
                from user_tab_cols t
               where table_name = upper(trim(substr(v_err_table, 5)))
                 and data_type = 'NUMBER') loop
      s := 'declare ' || chr(10) || '  i number(' || c.data_length || case
             when c.data_precision is null then
              ''
             else
              ',' || c.data_precision
           end || ');' || chr(10) || 'begin ' || chr(10) || '  select ' ||
           c.column_name || chr(10) || '  into i' || chr(10) || '  from ' ||
           v_err_table || chr(10) || '  where rowid = :1' || chr(10) || '  ;' ||
           chr(10) || ' exception ' || chr(10) || ' when others then ' ||
           chr(10) || ' raise_application_error(-20000,''' || c.column_name ||
           ''');' || chr(10) || 'end;';
      --  dbms_output.put_line(s);
      --  dbms_output.put_line(c.column_name);
      execute immediate s
        using r;
    end loop;
    return 'Unknown erorr';
  exception
    when others then
      return replace(SQLERRM, 'ORA-20000: ');
  end;
  ------------------------------------------------
  function create_sql_clob_format_html(p_table varchar2,
                                       p_where varchar2 default null)
    return clob is
    -- Local variables here
    p_Query       clob;
    l_theCursor   INTEGER;
    l_columnValue varchar2(4000);
    l_columnName  clob;
    l_status      INTEGER;
    l_colCnt      NUMBER;
    rec_tab       DBMS_SQL.DESC_TAB;
    l_sql_res     clob;
    l_add_color   number(1);
    l_index       number(2);
    s             clob;
    row_id        clob;
    message_edit  long;
    TYPE fields_name_array IS VARRAY(10) OF varchar2(200);
    fields_name fields_name_array := fields_name_array(10);
  begin
    p_Query   := 'select rowid,t.* from ' || p_table || ' t' || p_where;
    l_sql_res := '<table border="1">';
    -- parse given query
    l_theCursor := dbms_sql.open_cursor;
    dbms_sql.parse(l_theCursor, p_Query, DBMS_SQL.NATIVE);
    l_status := dbms_sql.execute(l_theCursor);
    -- Get columns description
    dbms_sql.describe_columns(l_theCursor, l_colCnt, rec_tab);
    -- Get columns definition
    l_sql_res := l_sql_res || '<tr>';
    for i in 1 .. l_colCnt loop
      dbms_sql.define_column(l_theCursor, i, l_columnValue, 2000);
      l_sql_res := l_sql_res || '<th>' || rec_tab(i).col_name || '<th/>';
    end loop;
    l_sql_res := l_sql_res || '<tr/>';
    l_sql_res := l_sql_res || chr(10);
    -- Fetch new row from query
    while (dbms_sql.fetch_rows(l_theCursor) > 0) loop
      l_sql_res := l_sql_res || '<tr>';
      fields_name.delete;
      -- Write all column's value
      for i in 1 .. l_colCnt loop
        dbms_sql.column_value(l_theCursor, i, l_columnValue);
        l_columnName := rec_tab(i).col_name;
        l_add_color  := 0;
        --Get the value from the ORA_ERR_MESG$ column
        if l_columnName = 'ROWID' then
          row_id := l_columnValue;
        elsif l_columnName = 'ORA_ERR_MESG$' then
          --check constraint error
          if l_columnValue like 'ORA-02290%' then
            select t.SEARCH_CONDITION
              into message_edit
              from user_constraints t
             where l_columnValue like '%' || t.CONSTRAINT_NAME || '%';
            l_columnValue := l_columnValue || ' == ' ||
                             (substr(message_edit, 1, 2000));
            --constraint error
          elsif l_columnValue like 'ORA-02291%' then
            for r in (select t.column_name
                        from user_cons_columns t
                       where t.constraint_name =
                             regexp_substr(l_columnValue,
                                           '(\(PRM_SYSTEM\.)(.{0,100})(\))',
                                           1,
                                           1,
                                           'i',
                                           2)) loop
              fields_name.extend(1);
              --add the column name to the array
              if fields_name.count > 0 then
                l_index := 1;
              else
                l_index := fields_name.last + 1;
              end if;
              fields_name(l_index) := r.column_name;
            end loop;
            --numeric error
          elsif l_columnValue like 'ORA-01722%' then
            s := 'select pk_load_mimshak.get_numeric_error(rowid,''' ||
                 p_table || ''')
            from ' || p_table || ' where rowid =''' ||
                 row_id || '''';
            fields_name.extend(1);
            --Temp, I set it in remark because iis is failed.
            execute immediate s
              into fields_name(1);
            --date error
          elsif l_columnValue like 'ORA-01840%' then
            s := 'select pk_load_mimshak.get_date_error(rowid,''' ||
                 p_table || ''')
            from ' || p_table || ' where rowid =''' ||
                 row_id || '''';
            fields_name.extend(1);
            --Temp, I set it in remark because iis is not true.
            -----------execute immediate s into fields_name(1);
          elsif l_columnValue like 'ORA-20001%' then
            fields_name.extend(1);
            fields_name(1) := regexp_substr(l_columnValue,
                                            '(ORA-20001 חובה להזין ערך בשדה: )(.{1,100})',
                                            1,
                                            1,
                                            'i',
                                            2);
          end if;
        elsif fields_name.count > 0 then
          FOR i IN fields_name.FIRST .. fields_name.LAST LOOP
            if l_columnName = fields_name(i) then
              l_add_color := 1;
            end if;
          END LOOP;
        end if;
        --Get the column that its value is invalid
        if l_add_color = 1 then
          l_sql_res := l_sql_res || '<td bgcolor=''#FFFF00''>';
          if l_columnName = 'EZOR_OVDIM_BE_TKUFA'
            --check if its a negative number
             and l_columnValue < 0 then
            l_sql_res := l_sql_res || - (l_columnValue);
          else
            l_sql_res := l_sql_res || l_columnValue;
          end if;
        else
          l_sql_res := l_sql_res || '<td>' || l_columnValue;
        end if;
        l_sql_res := l_sql_res || '<td/>';
      end loop;
      l_sql_res := l_sql_res || '<tr/>';
      l_sql_res := l_sql_res || chr(10);
    end loop;
    dbms_sql.close_cursor(l_theCursor);
    l_sql_res := l_sql_res || '</table>';
    return l_sql_res;
  end;
  ----------------------------------------------------------
  function Get_error_format_varchar(p_table varchar2) return clob is
    -- Local variables here
    p_Query       clob;
    l_theCursor   INTEGER;
    l_columnValue varchar2(4000);
    l_columnName  clob;
    l_status      INTEGER;
    l_colCnt      NUMBER;
    rec_tab       DBMS_SQL.DESC_TAB;
    l_sql_res     clob;
  
    l_index number(2);
    s       clob;
    row_id  clob;
    TYPE fields_name_array IS VARRAY(10) OF varchar2(200);
    fields_name fields_name_array := fields_name_array(10);
  
  begin
    p_Query := 'select rowid,t.ORA_ERR_MESG$ from ' || p_table || ' t';
    -- parse given query
    l_theCursor := dbms_sql.open_cursor;
    dbms_sql.parse(l_theCursor, p_Query, DBMS_SQL.NATIVE);
    l_status := dbms_sql.execute(l_theCursor);
    -- Get columns description
    dbms_sql.describe_columns(l_theCursor, l_colCnt, rec_tab);
    -- Get columns definition
    for i in 1 .. l_colCnt loop
      dbms_sql.define_column(l_theCursor, i, l_columnValue, 2000);
    end loop;
    -- Fetch new row from query
    while (dbms_sql.fetch_rows(l_theCursor) > 0) loop
      fields_name.delete;
      -- Write all column's value
      for i in 1 .. l_colCnt loop
        dbms_sql.column_value(l_theCursor, i, l_columnValue);
        l_columnName := rec_tab(i).col_name;
      
        --Get the value from the ORA_ERR_MESG$ column
        if l_columnName = 'ROWID' then
          row_id := l_columnValue;
        elsif l_columnName = 'ORA_ERR_MESG$' then
        
          BEGIN
            select l_sql_res || m.translate_to_hebrew_error
              into l_sql_res
              from ld_translate_error_message m
             where m.code_error = substr(l_columnValue, 5, 5);
          exception
            WHEN OTHERS THEN
              l_sql_res := l_columnValue;
              /*      if to_number(substr(l_columnValue,5,5)) < 20000
              then*/
            --send mail:
            /* pk_prm_utils.send_attach
            ('Mapam'
            ,'rivkas@mof.gov.il'
            ,'message in english'
            , l_columnValue
            , l_sql_res
            ,'txt'
            ,'message_in_english.txt');*/
            -- end if;
          end;
        
          --check constraint error
          if l_columnValue like 'ORA-02290%' then
          
            select t1.condition_translate
              into l_columnValue
              from user_constraints t
              left join ld_translate_constraint t1
                on t.table_name = t1.table_name
               and t.constraint_name = t1.constraint_name
             where l_columnValue like '%' || t.CONSTRAINT_NAME || '%';
          
            l_sql_res := l_sql_res || ': ' || l_columnValue;
          
            --constraint error
          elsif l_columnValue like 'ORA-02291%' then
            for r in (select t.column_name
                        from user_cons_columns t
                       where t.constraint_name =
                             regexp_substr(l_columnValue,
                                           '(\(PRM_SYSTEM\.)(.{0,100})(\))',
                                           1,
                                           1,
                                           'i',
                                           2)) loop
              fields_name.extend(1);
              --add the column name to the array
              if fields_name.count > 0 then
                l_index := 1;
              else
                l_index := fields_name.last + 1;
              end if;
              fields_name(l_index) := r.column_name;
            end loop;
            --numeric error
          elsif l_columnValue like 'ORA-01722%' then
            s := 'select pk_load_mimshak.get_numeric_error(rowid,''' ||
                 p_table || ''')
            from ' || p_table || ' where rowid =''' ||
                 row_id || '''';
            fields_name.extend(1);
            execute immediate s
              into fields_name(1);
            --date error
          elsif l_columnValue like 'ORA-01840%' then
            s := 'select pk_load_mimshak.get_date_error(rowid,''' ||
                 p_table || ''')
            from ' || p_table || ' where rowid =''' ||
                 row_id || '''';
            fields_name.extend(1);
            execute immediate s
              into fields_name(1);
          
          end if;
        
          l_sql_res := l_sql_res;
        
          if fields_name.count > 0 then
            l_sql_res := l_sql_res || 'בשדה: ';
            FOR i IN fields_name.FIRST .. fields_name.LAST LOOP
              l_sql_res := l_sql_res || fields_name(i) || ' ';
            END LOOP;
          end if;
        
        end if;
      end loop;
      --Get the column that its value is invalid
    end loop;
    dbms_sql.close_cursor(l_theCursor);
    return l_sql_res;
  end;
  ----------------------------------------------------------
  procedure Get_Erorr_from_Table(DoCommit         in out boolean,
                                 v_report         in out clob,
                                 v_report_varchar in out varchar2,
                                 v_table_name     in varchar2) is
  begin
    if count_rowes(v_table_name) > 0 then
      DoCommit         := false;
      v_REPORT         := v_REPORT || '<h4>' || v_table_name || ' count ' ||
                          count_rowes(v_table_name) || '.' || '<h4/>' ||
                          CHR(10);
      v_REPORT         := v_REPORT ||
                          create_sql_clob_format_html(v_table_name);
      v_report_varchar := v_report_varchar ||
                          Get_error_format_varchar(v_table_name);
    end if;
  end Get_Erorr_from_Table;
  ----------------------------------------------------------
  function Info_About_Errors_and_commit(p_DoCommit            boolean,
                                        v_code_makor          number,
                                        p_seq_ezor_ovdim      number,
                                        p_zehut               number,
                                        v_report_varchar      in out varchar2,
                                        p_oved_merkava_number number,
                                        new_seq_bakasha       number,
                                        old_seq_bakasha       number)
    return clob is
    DoCommit                   boolean;
    v_report                   clob;
    v_count_zehut_in_rejected  number;
    v_mail_recipient           varchar2(100);
    attach                     clob;
    v_user                     number;
    v_comment                  varchar2(1000);
    v_is_new_in_mechushavim    number;
    v_is_action_before_gimlaot number;
  
    v_is_delete varchar2(1000);
  
    v_code_sug_bakasha number;
  begin
    begin
    
      select b.code_sug_bakasha
        into v_code_sug_bakasha
        from bakasha b
       where b.seq_bakasha = new_seq_bakasha;
    exception
      when others then
        v_code_sug_bakasha := null;
    end;
  
    if nvl(v_code_sug_bakasha, 0) <> 2 and old_seq_bakasha is not null then
    
      --check if get the new version
      v_is_new_in_mechushavim := pk_load.is_new_in_mechushavim(old_seq_bakasha,
                                                               new_seq_bakasha,
                                                               v_comment);
      --If all the comparisons is equals yet
      if v_is_new_in_mechushavim = 0 then
        --merge when filter is not get
        pk_load.merge_when_filter_is_not_get(old_seq_bakasha,
                                             new_seq_bakasha);
      
        v_is_delete := pk_prm_utils.delete_bakasha(new_seq_bakasha);
      
        v_report_varchar := '<h3>' || 'Unloaded. ' || '<h3/>' || CHR(13) ||
                            CHR(10) ||
                            'Same version already exists in mapam system.';
      
        v_report := v_report_varchar;
      
        attach := to_char(p_zehut);
      
        /*    pk_prm_utils.send_attach('rivkas@mof.gov.il,dvora@mof.gov.il',
        'Unloaded same version merkava to id - ' ||
        attach,
        null,
        attach,
        'txt',
        'Unloaded_same_version_merkava' ||
        to_char(sysdate, 'dd_mm_yyyy') || '.txt');*/
      
        return v_report;
      
      end if;
    end if;
  
    DoCommit := p_DoCommit;
  
    --Add to the report info about the error tables.
    Get_Erorr_from_Table(DoCommit,
                         v_report,
                         v_report_varchar,
                         'err_porshim');
    Get_Erorr_from_Table(DoCommit,
                         v_report,
                         v_report_varchar,
                         'err_bney_mishpacha');
    Get_Erorr_from_Table(DoCommit,
                         v_report,
                         v_report_varchar,
                         'err_bakasha_regila');
    Get_Erorr_from_Table(DoCommit,
                         v_report,
                         v_report_varchar,
                         'err_tkufot_avoda_golmi');
    Get_Erorr_from_Table(DoCommit,
                         v_report,
                         v_report_varchar,
                         'err_tkufot_michutz_lasharut');
    Get_Erorr_from_Table(DoCommit,
                         v_report,
                         v_report_varchar,
                         'err_tkufot_sherut_tsvaii');
    Get_Erorr_from_Table(DoCommit,
                         v_report,
                         v_report_varchar,
                         'err_action_log');
    Get_Erorr_from_Table(DoCommit,
                         v_report,
                         v_report_varchar,
                         'err_darga_vederug_tik');
    Get_Erorr_from_Table(DoCommit,
                         v_report,
                         v_report_varchar,
                         'err_netuney_tik_mechushavim');
    Get_Erorr_from_Table(DoCommit,
                         v_report,
                         v_report_varchar,
                         'err_tkufot_avoda_mechushv');
    if v_code_makor = 1 then
      Get_Erorr_from_Table(DoCommit,
                           v_report,
                           v_report_varchar,
                           'err_bakasha_mukdemet');
      Get_Erorr_from_Table(DoCommit,
                           v_report,
                           v_report_varchar,
                           'err_tikim_mukdmt_misrt_lebitul');
    end if;
    if v_code_makor = 3 then
      Get_Erorr_from_Table(DoCommit,
                           v_report,
                           v_report_varchar,
                           'err_netuny_tik_mechshv_chinuch');
      Get_Erorr_from_Table(DoCommit,
                           v_report,
                           v_report_varchar,
                           'err_hagdala_nimuk');
    end if;
    --##################
    if DoCommit = false then
      rollback;
      v_REPORT := '<h3>' || 'Unloaded. ' || '<h3/>' || CHR(13) || CHR(10) ||
                  v_REPORT;
    
    elsif DoCommit = true then
      pk_prm_utils.insert_actions_for_bakasha(new_seq_bakasha, 0);
    
      v_REPORT := '<h3>' || 'Loaded. ' || v_comment || '<h3/>' || CHR(13) ||
                  CHR(10) || v_REPORT;
    end if;
  
    commit;
    --##################
    return v_REPORT;
  end;
  ----------------------------------------------------------
  function get_message_according_code(info_type    varchar2,
                                      code         number,
                                      field_name   varchar2,
                                      field_name_2 varchar2 default null)
    return varchar2 is
    v_info_type varchar2(100) := '';
    result      varchar2(250);
  begin
    if (info_type is not null) then
      v_info_type := 'סוג מידע: ' || info_type || ',' || chr(10);
    end if;
    case code
      when 20001 then
        result := v_info_type || 'לא קיים ערך בשדה: ' || field_name;
      when 20002 then
        result := v_info_type || 'התקופה אינה רציפה לתקופה קודמת';
      when 20003 then
        result := v_info_type ||
                  'משרד משכורת אינו תואם לקוד משרד משכורת הרשום במפ"מ';
      when 20004 then
        result := v_info_type || field_name_2 ||
                  ' אינו יכול להיות גדול מ: ' || field_name;
      when 20005 then
        result := v_info_type || 'חובה להזין תאריך בפורמט 8 ספרות: ' ||
                  field_name;
      when 20006 then
        result := v_info_type || 'אורך שדה גדול מהצפוי בשדה: ' ||
                  field_name;
      when 20007 then
        result := v_info_type || 'פורמט שגוי בשדה:  ' || field_name;
      when 20008 then
        result := v_info_type || 'ערך שגוי בשדה:  ' || field_name;
      else
        result := '';
    end case;
  
    return(result);
  end;
  ------------------------------------------------
  procedure add_row_to_err_porshim(info_type     varchar2,
                                   err_porshim_r err_porshim%rowtype,
                                   err_mesg      varchar2,
                                   err_number    number,
                                   field_name    varchar2) is
    err_porshim_row err_porshim%rowtype;
  begin
    err_porshim_row := err_porshim_r;
  
    err_porshim_row.ora_err_number$ := err_number;
    if err_mesg is not null then
      err_porshim_row.ora_err_mesg$ := field_name || ': ' || err_mesg;
    else
      err_porshim_row.ora_err_mesg$ := get_message_according_code(info_type,
                                                                  err_number,
                                                                  field_name);
    end if;
    insert into err_porshim values err_porshim_row;
  
  end;
