  procedure check_bakasha_regila(p_mispar_zehut         varchar2,
                                 err_bakasha_regila_row in out err_bakasha_regila%rowtype) is
    pragma autonomous_transaction;
  begin
    --is_tvia_zad_gimel
    begin
      if err_bakasha_regila_row.is_tvia_zad_gimel not in (0, 1) then
        pk_load.Insert_errors(p_mispar_zehut,
                              20007,
                              p_table_name   => '01',
                              p_field_name   => 'is_tvia_zad_gimel',
                              p_value        => err_bakasha_regila_row.is_tvia_zad_gimel);
      end if;
    end;
    -- check date fields format.
    begin
      err_bakasha_regila_row.taarich_prisha := to_date(err_bakasha_regila_row.taarich_prisha,
                                                       date_format);
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '01',
                              p_field_name   => 'taarich_prisha',
                              p_value        => err_bakasha_regila_row.taarich_prisha);
      
    end;
  
    begin
      err_bakasha_regila_row.taarich_chatimat_tofes := to_date(err_bakasha_regila_row.taarich_chatimat_tofes,
                                                               date_format);
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '01',
                              p_field_name   => 'taarich_chatimat_tofes',
                              p_value        => err_bakasha_regila_row.taarich_chatimat_tofes);
    end;
  
    begin
      err_bakasha_regila_row.date_freeze_haskem := to_date(err_bakasha_regila_row.date_freeze_haskem,
                                                           date_format);
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '01',
                              p_field_name   => 'date_freeze_haskem',
                              p_value        => err_bakasha_regila_row.date_freeze_haskem);
    end;
  
    begin
      err_bakasha_regila_row.hivun_percent := get_float_number(err_bakasha_regila_row.hivun_percent,
                                                               100);
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '01',
                              p_field_name   => 'hivun_percent',
                              p_value        => err_bakasha_regila_row.hivun_percent);
    end;
    begin
      err_bakasha_regila_row.kizba_after_hagdala := get_float_number(err_bakasha_regila_row.kizba_after_hagdala,
                                                                     100);
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '01',
                              p_field_name   => 'kizba_after_hagdala',
                              p_value        => err_bakasha_regila_row.kizba_after_hagdala);
    end;
    commit;
  end;

  -----------------------------------------------
  function get_bakasha_regila(p_seq_previous   number,
                              v_mispar_zehut   varchar2,
                              p_seq_poresh     number,
                              v_seq_ezor_ovdim number) return number is
    v_seq_bakasha number;
    regila_row    err_bakasha_regila%rowtype;
  begin
    for r in (select t.b || t.c mispar_zehut,
                     t.d date_bakasha,
                     t.x code_unit,
                     t.ag taarich_prisha,
                     t.ah taarich_chatima_tofes,
                     t.at code_seif_prisha,
                     t.ba hivun_percent,
                     t.bb is_tvia_zad_gimel,
                     t.bc kizba_after_hagdala,
                     t.bd enter,
                     t.be date_freeze_haskem,
                     t.bm mdina_vshikum,
                     t.bn shikum,
                     poresh.porshim_seq
                from ld_security_01 t
                left join poresh
                  on t.b || t.c = poresh.mispar_zehut
               where t.b || t.c = v_mispar_zehut) loop
    
      if p_seq_previous is not null then
        -----------------------Get previous bakasha---------------------------------
        regila_row := pk_load_mimshak.get_bakasha_regila_by_previous(p_seq_previous);
        ----------------------------------------------------------------------------
      else
        regila_row := null;
      end if;
      regila_row.taarich_prisha         := r.taarich_prisha;
      regila_row.taarich_chatimat_tofes := r.taarich_chatima_tofes;
      if v_code_misrad <> 164 then
        regila_row.code_seif_prisha := get_mpm_code_seif_prisha(r.code_seif_prisha);
      else
        regila_row.code_seif_prisha := r.code_seif_prisha;
      end if;
      regila_row.code_sub_seif_prisha := pk_load_mimshak.get_new_code_sub_seif_prisha(r.code_seif_prisha);
      regila_row.hivun_percent        := r.hivun_percent;
      regila_row.is_tvia_zad_gimel    := r.is_tvia_zad_gimel;
      regila_row.kizba_after_hagdala  := r.kizba_after_hagdala;
    
      regila_row.date_freeze_haskem := r.date_freeze_haskem;
      regila_row.is_contract_shikum := r.shikum;
    
      --check_fields
    
      check_bakasha_regila(v_mispar_zehut, regila_row);
    
      -------insert new data with data from previous bakasha--------
      v_seq_bakasha := pk_load_mimshak.insert_bakasha_regila(4,
                                                             regila_row,
                                                             p_seq_poresh,
                                                             v_seq_ezor_ovdim,
                                                             sysdate,
                                                             null);
      ----------------------------------------------------------------
    end loop;
    return v_seq_bakasha;
  end;
