  --------------------------------------------------
  procedure load_darga_vederug_tik(v_mispar_zehut varchar2,
                                   v_seq_regila   number) is
    darga_vederug_row err_darga_vederug_tik%rowtype;
  
  begin
    for r in (select t.ao code_derug, t.ap taarich_me
                from ld_security_01 t
               where t.b || t.c = v_mispar_zehut
                 and nvl(t.ao, 0) <> 0) loop
      darga_vederug_row            := null;
      darga_vederug_row.code_darga := -1;
      darga_vederug_row.code_derug := r.code_derug;
      darga_vederug_row.taarich_me := r.taarich_me;
    
      --check_fields
      check_darga_vederug_tik(v_mispar_zehut, darga_vederug_row);
    
      insert into darga_vederug_tik
        (taarich_me,
         code_darga,
         code_derug,
         seq_bakasha,
         seq_dargot_vederug_tik)
      values
        (darga_vederug_row.taarich_me,
         darga_vederug_row.code_darga,
         darga_vederug_row.code_derug,
         v_seq_regila,
         darga_vederug_tik_seq.nextval) log errors into err_darga_vederug_tik reject limit unlimited;
    
    end loop;
  end;
