  procedure check_bney_mishpacha(p_mispar_zehut         varchar2,
                                 err_bney_mishpacha_row in out err_bney_mishpacha%rowtype) is
    pragma autonomous_transaction;
    v_city_name varchar2(100);
  begin
    -- check fields format
  
    begin
      err_bney_mishpacha_row.taarich_leda := to_date(err_bney_mishpacha_row.taarich_leda,
                                                     date_format);
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '03',
                              p_field_name   => 'taarich_leda',
                              p_value        => err_bney_mishpacha_row.taarich_leda);
    end;
  
    begin
      err_bney_mishpacha_row.date_sign_tvia_form := to_date(err_bney_mishpacha_row.date_sign_tvia_form,
                                                            date_format);
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '03',
                              p_field_name   => 'date_sign_tvia_form',
                              p_value        => err_bney_mishpacha_row.date_sign_tvia_form);
    end;
  
    if err_bney_mishpacha_row.date_separated is not null then
      begin
        err_bney_mishpacha_row.date_separated := to_date(err_bney_mishpacha_row.date_separated,
                                                         date_format);
      exception
        when others then
          pk_load.Insert_errors(p_mispar_zehut,
                                sqlcode,
                                sqlerrm,
                                p_table_name   => '03',
                                p_field_name   => 'date_separated',
                                p_value        => err_bney_mishpacha_row.date_separated);
      end;
    end if;
    begin
      err_bney_mishpacha_row.month_salary := get_float_number(err_bney_mishpacha_row.month_salary,
                                                              100);
    exception
      when others then
        pk_load.Insert_errors(p_mispar_zehut,
                              sqlcode,
                              sqlerrm,
                              p_table_name   => '03',
                              p_field_name   => 'month_salary',
                              p_value        => err_bney_mishpacha_row.month_salary);
    end;
    if err_bney_mishpacha_row.code_city is not null then
      if not regexp_like(err_bney_mishpacha_row.code_city, '\d+') then
        pk_load.Insert_errors(p_mispar_zehut,
                              20007,
                              p_table_name   => '03',
                              p_field_name   => 'code_city',
                              p_value        => err_bney_mishpacha_row.code_city);
      else
        begin
          err_bney_mishpacha_row.code_city := to_number(err_bney_mishpacha_row.code_city);
          select t.teur_ir
            into v_city_name
            from code_ir t
           where t.code_ir = err_bney_mishpacha_row.code_city;
        exception
          when others then
            pk_load.Insert_errors(p_mispar_zehut,
                                  20007,
                                  null,
                                  p_table_name   => '03',
                                  p_field_name   => 'code_city',
                                  p_value        => err_bney_mishpacha_row.code_city);
          
        end;
      end if;
    end if;
  
    if err_bney_mishpacha_row.haim_oved not in (1, 0) then
      pk_load.Insert_errors(p_mispar_zehut,
                            sqlcode,
                            sqlerrm,
                            p_table_name   => '03',
                            p_field_name   => 'haim_oved',
                            p_value        => err_bney_mishpacha_row.haim_oved);
    
    end if;
  
    commit;
  end;
