  procedure load_bney_mishpacha(v_mispar_zehut   varchar2,
                                v_report_for_tik in out clob,
                                v_do_commit      in out boolean) is
    bney_mishpacha_row err_bney_mishpacha%rowtype;
  begin
    for r in (select poresh.porshim_seq,
                     t.d                mispar_zehut_ben_mishpacha,
                     t.e                shem_mishpacha,
                     t.f                shem_prati,
                     t.g                taarich_leda,
                     t.h                is_get_social_security,
                     t.i                haim_oved,
                     t.j                makom_avoda,
                     t.k                haim_mistaker,
                     t.l                is_learn,
                     t.q                code_relative,
                     t.r                is_bank_form_signed,
                     t.t                date_sign_tvia_form,
                     t.u                is_serve_in_army,
                     t.v                is_army_ishur,
                     t.w                is_owner_tzav_imutz,
                     t.x                month_salary,
                     t.y                date_separated,
                     t.z                address,
                     t.aa               code_city,
                     t.ab               zone,
                     t.ac               code_min
                from ld_security_03 t
                left join poresh
                  on t.b || t.c = poresh.mispar_zehut
               where t.b || t.c = v_mispar_zehut) loop
      bney_mishpacha_row                            := null;
      bney_mishpacha_row.mispar_zehut_ben_mishpacha := r.mispar_zehut_ben_mishpacha;
      bney_mishpacha_row.shem_mishpacha             := r.shem_mishpacha;
      bney_mishpacha_row.shem_prati                 := r.shem_prati;
      bney_mishpacha_row.taarich_leda               := r.taarich_leda;
      bney_mishpacha_row.is_get_social_security     := r.is_get_social_security;
      bney_mishpacha_row.haim_oved                  := r.haim_oved;
      bney_mishpacha_row.makom_avoda                := r.makom_avoda;
      if r.haim_mistaker not in (1, 0) then
        v_report_for_tik := v_report_for_tik || chr(10) ||
                            'haim_mistaker value in bney_mishpacha table is ' ||
                            r.haim_mistaker ||
                            ' and it must be 1 or 0. (ben_mishpacha id: ' ||
                            r.mispar_zehut_ben_mishpacha || ')';
        v_do_commit      := false;
      elsif r.haim_mistaker = 1 then
        bney_mishpacha_row.haim_oved := 1;
      end if;
      bney_mishpacha_row.is_learn            := r.is_learn;
      bney_mishpacha_row.code_relative       := r.code_relative;
      bney_mishpacha_row.is_bank_form_signed := r.is_bank_form_signed;
      bney_mishpacha_row.date_sign_tvia_form := r.date_sign_tvia_form;
      bney_mishpacha_row.is_serve_in_army    := r.is_serve_in_army;
      bney_mishpacha_row.is_army_ishur       := r.is_army_ishur;
      bney_mishpacha_row.is_owner_tzav_imutz := r.is_owner_tzav_imutz;
      bney_mishpacha_row.month_salary        := r.month_salary;
      bney_mishpacha_row.date_separated      := r.date_separated;
      bney_mishpacha_row.address             := r.address;
      bney_mishpacha_row.code_city           := r.code_city;
      bney_mishpacha_row.zone                := r.zone;
      bney_mishpacha_row.code_min            := r.code_min;
      bney_mishpacha_row.seq_porshim         := r.porshim_seq;
      bney_mishpacha_row.seq_bney_mishpacha  := bney_mishpacha_seq.nextval;
    
      --check fields
      check_bney_mishpacha(bney_mishpacha_row);
    
      insert into bney_mishpacha
        (mispar_zehut_ben_mishpacha,
         shem_mishpacha,
         shem_prati,
         taarich_leda,
         is_get_social_security,
         haim_oved,
         makom_avoda,
         is_learn,
         code_relative,
         is_bank_form_signed,
         date_sign_tvia_form,
         is_serve_in_army,
         is_army_ishur,
         is_owner_tzav_imutz,
         month_salary,
         date_separated,
         address,
         code_city,
         zone,
         code_min,
         seq_porshim,
         seq_bney_mishpacha)
      values
        (bney_mishpacha_row.mispar_zehut_ben_mishpacha,
         bney_mishpacha_row.shem_mishpacha,
         bney_mishpacha_row.shem_prati,
         bney_mishpacha_row.taarich_leda,
         bney_mishpacha_row.is_get_social_security,
         bney_mishpacha_row.haim_oved,
         bney_mishpacha_row.makom_avoda,
         bney_mishpacha_row.is_learn,
         bney_mishpacha_row.code_relative,
         bney_mishpacha_row.is_bank_form_signed,
         bney_mishpacha_row.date_sign_tvia_form,
         bney_mishpacha_row.is_serve_in_army,
         bney_mishpacha_row.is_army_ishur,
         bney_mishpacha_row.is_owner_tzav_imutz,
         bney_mishpacha_row.month_salary,
         bney_mishpacha_row.date_separated,
         bney_mishpacha_row.address,
         bney_mishpacha_row.code_city,
         bney_mishpacha_row.zone,
         bney_mishpacha_row.code_min,
         bney_mishpacha_row.seq_porshim,
         bney_mishpacha_row.seq_bney_mishpacha)
      
      log errors into err_bney_mishpacha reject limit unlimited;
    end loop;
  end;
