  --------------------------------------------------
  procedure load_medical_vaada(v_mispar_zehut number) is
    medical_vaada_row err_medical_vaada%rowtype;
  begin
    for r1 in (select poresh.porshim_seq,
                      t.d                code_timing,
                      t.e                date_decision,
                      t.f                dargat_nechut,
                      t.g                dargat_nechut_lchishuv,
                      t.h                is_permanent_nechut,
                      t.i                tkufa_nechut,
                      t.j                date_start_nechut,
                      t.k                is_accident,
                      t.l                accident_percent,
                      t.m                is_migbala_ba_knisa
                 from ld_security_04 t
                 left join poresh
                   on t.b || t.c = poresh.mispar_zehut
                where t.b || t.c = v_mispar_zehut) loop
      medical_vaada_row                        := null;
      medical_vaada_row.code_timinig           := r1.code_timing;
      medical_vaada_row.date_decision          := r1.date_decision;
      medical_vaada_row.dargat_nechut          := r1.dargat_nechut;
      medical_vaada_row.dargat_nechut_lchishuv := r1.dargat_nechut_lchishuv;
      medical_vaada_row.is_permanent_nechut    := r1.is_permanent_nechut;
      medical_vaada_row.tkufa_nechut           := r1.tkufa_nechut;
      medical_vaada_row.date_start_nechut      := r1.date_start_nechut;
      medical_vaada_row.is_accident            := r1.is_accident;
      medical_vaada_row.accident_percent       := r1.accident_percent;
      medical_vaada_row.seq_poresh             := r1.porshim_seq;
    
      if r1.is_migbala_ba_knisa = 1 then
        medical_vaada_row.code_timinig := 1;
      end if;
    
      --check fields
      check_medical_vaada(medical_vaada_row);
    
      insert into medical_vaada
        (seq_medical_vaada,
         seq_poresh,
         code_timinig,
         date_decision,
         dargat_nechut,
         dargat_nechut_lchishuv,
         is_permanent_nechut,
         tkufa_nechut,
         date_start_nechut,
         is_accident,
         accident_percent)
      values
        (medical_vaada_seq.nextval,
         medical_vaada_row.seq_poresh,
         medical_vaada_row.code_timinig,
         medical_vaada_row.date_decision,
         medical_vaada_row.dargat_nechut,
         medical_vaada_row.dargat_nechut_lchishuv,
         medical_vaada_row.is_permanent_nechut,
         medical_vaada_row.tkufa_nechut,
         medical_vaada_row.date_start_nechut,
         medical_vaada_row.is_accident,
         medical_vaada_row.accident_percent) log errors into err_medical_vaada reject limit unlimited;
    end loop;
  end;
