  procedure check_hagdala_nimuk(err_hagdala_nimuk_row in out err_hagdala_nimuk%rowtype) is
    pragma autonomous_transaction;
  begin
    --check required fields.
    begin
      err_hagdala_nimuk_row.me_taarich := to_date(err_hagdala_nimuk_row.me_taarich,
                                                  date_format);
    exception
      when others then
        pk_load_mimshak.add_row_err_hagdala_nimuk('05',
                                                  err_hagdala_nimuk_row,
                                                  sqlerrm,
                                                  sqlcode,
                                                  'me_taarich');
    end;
  
    begin
      err_hagdala_nimuk_row.achuz_meushar := get_float_number(err_hagdala_nimuk_row.achuz_meushar,
                                                              100);
    exception
      when others then
        pk_load_mimshak.add_row_err_hagdala_nimuk('05',
                                                  err_hagdala_nimuk_row,
                                                  sqlerrm,
                                                  sqlcode,
                                                  'achuz_meushar');
    end;
  
    begin
      err_hagdala_nimuk_row.code_nimuk := get_mpm_code_nimuk(to_number(trim(err_hagdala_nimuk_row.code_nimuk)));
    exception
      when others then
        pk_load_mimshak.add_row_err_hagdala_nimuk('05',
                                                  err_hagdala_nimuk_row,
