  -----------------------------------------------
  function get_hagdala_nimuk(v_mispar_zehut number)
    return hagdala_nimuk_table is
    hagdala_nimuk_t   hagdala_nimuk_table := hagdala_nimuk_table();
    hagdala_nimuk_row err_hagdala_nimuk%rowtype;
    v_count           number := 0;
  begin
    for r2 in (select t.d me_taarich,
                      t.e months_hagdala,
                      t.f achuz_meushar,
                      t.h code_nimuk
                 from ld_security_05 t
                where t.b || t.c = v_mispar_zehut) loop
      hagdala_nimuk_row                := null;
      hagdala_nimuk_row.me_taarich     := r2.me_taarich;
      hagdala_nimuk_row.months_hagdala := r2.months_hagdala;
      hagdala_nimuk_row.achuz_meushar  := r2.achuz_meushar;
      hagdala_nimuk_row.code_nimuk     := r2.code_nimuk;
    
      --check fields
      check_hagdala_nimuk(hagdala_nimuk_row);
    
      hagdala_nimuk_t.extend(1);
      v_count := v_count + 1;
      hagdala_nimuk_t(v_count) := hagdala_nimuk_row;
    end loop;
  
    return hagdala_nimuk_t;
  end;
  --------------------------------------------------
  procedure insert_hagdala_nimuk(hagdala_nimuk_t hagdala_nimuk_table,
                                 v_seq_regila    number,
                                 v_date_bakasha  date) is
    hagdala_nimuk_row err_hagdala_nimuk%rowtype;
  begin
  
    if hagdala_nimuk_t.count() = 0 then
      return;
    end if;
  
    for i in hagdala_nimuk_t.first .. hagdala_nimuk_t.last loop
      hagdala_nimuk_row := hagdala_nimuk_t(i);
    
      insert into hagdala_nimuk
        (me_taarich,
         months_hagdala,
         achuz_meushar,
         code_nimuk,
         seq_hagdala_nimuk,
         seq_bakasha)
      values
        (hagdala_nimuk_row.me_taarich,
         hagdala_nimuk_row.months_hagdala,
         hagdala_nimuk_row.achuz_meushar,
         hagdala_nimuk_row.code_nimuk,
         hagdala_nimuk_seq.nextval,
         v_seq_regila) log errors into err_hagdala_nimuk reject limit unlimited;
    end loop;
  
    --todo: add action log?            
  end;
