  ------------------------------------------------
  function get_tkufot_avoda_mechushv(v_mispar_zehut number)
    return tkufot_avoda_mechushv_table is
    tkufot_avoda_mechushv_t   tkufot_avoda_mechushv_table := tkufot_avoda_mechushv_table();
    tkufot_avoda_mechushv_row err_tkufot_avoda_mechushv%rowtype;
    v_count                   number := 0;
  begin
    for r3 in (select t.b || t.c mispar_zehut,
                      t.d taarich_me,
                      t.e taarich_ad,
                      t.g code_sugey_tkufot,
                      t.i code_sugey_zchuyot,
                      t.j || '.' || t.k achuz_chelkiut,
                      t.l praklit,
                      t.m keren,
                      t.n haim_kana_zchuyot,
                      t.o except_from_tkufa,
                      t.p achuz_mugdal,
                      t.q code_achuz_mugdal
                 from ld_security_06 t
                where t.b || t.c = v_mispar_zehut) loop
      tkufot_avoda_mechushv_row                       := null;
      tkufot_avoda_mechushv_row.taarich_me            := r3.taarich_me;
      tkufot_avoda_mechushv_row.taarich_ad            := r3.taarich_ad;
      tkufot_avoda_mechushv_row.code_sugey_tkufot     := r3.code_sugey_tkufot;
      tkufot_avoda_mechushv_row.code_sugey_zchuyot    := r3.code_sugey_zchuyot;
      tkufot_avoda_mechushv_row.achuz_chelkyut        := r3.achuz_chelkiut;
      tkufot_avoda_mechushv_row.praklit               := get_mpm_praklit(r3.praklit);
      tkufot_avoda_mechushv_row.is_took_money_m_keren := r3.keren;
      tkufot_avoda_mechushv_row.haim_kana_zchuyot     := r3.haim_kana_zchuyot;
      tkufot_avoda_mechushv_row.except_from_tkufa     := r3.except_from_tkufa;
      tkufot_avoda_mechushv_row.achuz_mugdal          := r3.achuz_mugdal;
      tkufot_avoda_mechushv_row.code_achuz_mugdal     := r3.code_achuz_mugdal;
    
      --check fields
      check_tkufot_avoda_mechushv(tkufot_avoda_mechushv_row);
    
      tkufot_avoda_mechushv_t.extend(1);
      v_count := v_count + 1;
      tkufot_avoda_mechushv_t(v_count) := tkufot_avoda_mechushv_row;
    end loop;
  
    return tkufot_avoda_mechushv_t;
  end;
  --------------------------------------------------
  procedure insert_tkufot_avoda_mechushv(tkufot_avoda_mechushv_t tkufot_avoda_mechushv_table,
                                         v_seq_regila            number) is
    tkufot_avoda_mechushv_row err_tkufot_avoda_mechushv%rowtype;
  begin
    for i in tkufot_avoda_mechushv_t.first .. tkufot_avoda_mechushv_t.last loop
      tkufot_avoda_mechushv_row := tkufot_avoda_mechushv_t(i);
    
      insert into tkufot_avoda_mechushv
        (taarich_me,
         taarich_ad,
         code_sugey_tkufot,
         code_sugey_zchuyot,
         achuz_chelkyut,
         praklit,
         IS_TOOK_MONEY_M_KEREN,
         haim_kana_zchuyot,
         except_from_tkufa,
         achuz_mugdal,
         code_achuz_mugdal,
         seq_tkufot_avoda_mechushv,
         seq_bakasha)
      values
        (tkufot_avoda_mechushv_row.taarich_me,
         tkufot_avoda_mechushv_row.taarich_ad,
         tkufot_avoda_mechushv_row.code_sugey_tkufot,
         tkufot_avoda_mechushv_row.code_sugey_zchuyot,
         tkufot_avoda_mechushv_row.achuz_chelkyut,
         tkufot_avoda_mechushv_row.praklit,
         tkufot_avoda_mechushv_row.is_took_money_m_keren,
         tkufot_avoda_mechushv_row.haim_kana_zchuyot,
         tkufot_avoda_mechushv_row.except_from_tkufa,
         tkufot_avoda_mechushv_row.achuz_mugdal,
         tkufot_avoda_mechushv_row.code_achuz_mugdal,
         tkufot_avoda_mechushav_seq.nextval,
         v_seq_regila) log errors into err_tkufot_avoda_mechushv reject limit unlimited;
    end loop;
  end;
  ----------------------------------------------------------
  function info_about_errors_and_commit(v_mispar_zehut number,
                                        v_do_commit    in out boolean,
                                        v_report       in out clob)
    return clob is
    v_report_varchar varchar2(1000);
  begin
    --add to the report info about the error tables.
    pk_load_mimshak.get_erorr_from_table(v_do_commit,
                                         v_report,
                                         v_report_varchar,
                                         'err_porshim');
    pk_load_mimshak.get_erorr_from_table(v_do_commit,
                                         v_report,
                                         v_report_varchar,
                                         'err_bney_mishpacha');
    pk_load_mimshak.get_erorr_from_table(v_do_commit,
                                         v_report,
                                         v_report_varchar,
                                         'err_bakasha_regila');
    pk_load_mimshak.get_erorr_from_table(v_do_commit,
                                         v_report,
                                         v_report_varchar,
                                         'err_darga_vederug_tik');
    pk_load_mimshak.get_erorr_from_table(v_do_commit,
                                         v_report,
                                         v_report_varchar,
                                         'err_medical_vaada');
    pk_load_mimshak.get_erorr_from_table(v_do_commit,
                                         v_report,
                                         v_report_varchar,
                                         'err_hagdala_nimuk');
    pk_load_mimshak.get_erorr_from_table(v_do_commit,
                                         v_report,
                                         v_report_varchar,
                                         'err_tkufot_avoda_mechushv');
    pk_load_mimshak.get_erorr_from_table(v_do_commit,
                                         v_report,
                                         v_report_varchar,
                                         'err_bakasha');
    pk_load_mimshak.get_erorr_from_table(v_do_commit,
                                         v_report,
                                         v_report_varchar,
                                         'err_prisha');
    --##################
  
    if v_do_commit = false then
      rollback;
      v_report := '<h2>' || '********** zeut: ' || v_mispar_zehut ||
                  ' **********' || '<h2/>' || '<h3>' || 'unloaded. ' ||
                  '<h3/>' || chr(13) || chr(10) || v_report;
    
    elsif v_do_commit = true then
      v_report := '<h2>' || '********** zeut: ' || v_mispar_zehut ||
                  ' **********' || '<h2/>' || '<h3>' || 'loaded. ' ||
                  '<h3/>' || chr(13) || chr(10) || v_report;
    end if;
  
    commit;
    --##################
    return v_report;
  end;
  --------------------------------------------------
  function loop_over_all_tikim return clob is
    v_is_exist_poresh             boolean;
    v_seq_poresh                  number;
    v_is_exist_previous_regila    boolean;
    v_seq_previous_regila         number;
    v_seq_previous_hagdala        number;
    v_bakasha_regila_row          err_bakasha_regila%rowtype;
    v_tkufot_avoda_mechushv_t     tkufot_avoda_mechushv_table;
    v_hagdala_nimuk_t             hagdala_nimuk_table;
    v_is_important_fields_changed boolean;
    v_code_department             number;
    v_taarich_bakasha             date;
    v_seq_regila                  number;
    v_seq_ezor_ovdim              number;
    v_report                      clob;
    v_report_for_tik              clob;
    v_do_commit                   boolean;
    v_count_success               number := 0;
    v_count_errors                number := 0;
    v_update_sug_bakasha          boolean := false;
    v_code_sug_bakasha            number;
  begin
    execute immediate 'alter session set nls_language= ''american''';
    execute immediate 'alter session set nls_date_language=''english''';
    execute immediate 'alter session set nls_date_format=''dd-mon-yyyy''';
  
    for r in (select t.b || t.c mispar_zehut,
                     ezor_ovdim.seq_ezor_ovdim,
                     t.d taarich_bakasha
                from ld_security_01 t
                left join code_ezor_ovdim ezor_ovdim
                  on t.v = ezor_ovdim.code_ezor_ovdim
                 and code_makor = 4) loop
      v_report_for_tik := null;
      v_do_commit      := true;
      v_seq_ezor_ovdim := r.seq_ezor_ovdim;
    
      --truncate 'err' tables
      execute immediate 'truncate table err_porshim';
      execute immediate 'truncate table err_bakasha_regila';
      execute immediate 'truncate table err_prisha';
      execute immediate 'truncate table err_bakasha';
      execute immediate 'truncate table err_darga_vederug_tik';
      execute immediate 'truncate table err_bney_mishpacha';
      execute immediate 'truncate table err_medical_vaada';
      execute immediate 'truncate table err_hagdala_nimuk';
      execute immediate 'truncate table err_tkufot_avoda_mechushv';
    
      v_is_exist_poresh := pk_load_mimshak.is_exist_poresh(r.mispar_zehut,
                                                           v_seq_poresh);
      --If poresh is not exist , Add 'pratim ishyim' tables.
      if not (v_is_exist_poresh) then
        load_poresh(r.mispar_zehut, v_seq_poresh);
        if pk_load_mimshak.count_rowes('err_porshim') > 0 then
          v_do_commit := false;
        end if;
        if v_do_commit = true then
          load_bney_mishpacha(r.mispar_zehut,
                              v_report_for_tik,
                              v_do_commit);
          delete from medical_vaada m where m.seq_poresh = v_seq_poresh;
        end if;
      end if;
    
      if v_do_commit = true then
        v_hagdala_nimuk_t          := get_hagdala_nimuk(r.mispar_zehut);
        v_tkufot_avoda_mechushv_t  := get_tkufot_avoda_mechushv(r.mispar_zehut);
        v_is_exist_previous_regila := pk_load_mimshak.is_exist_previous_regila(v_seq_poresh,
                                                                               v_seq_ezor_ovdim,
                                                                               1,
                                                                               v_seq_previous_regila);
        --check if  exist  previous regila
        if (v_is_exist_previous_regila) then
          v_bakasha_regila_row := get_bakasha_regila_by_previous(r.mispar_zehut,
                                                                 v_seq_previous_regila,
                                                                 v_bakasha_regila_row,
                                                                 v_seq_ezor_ovdim,
                                                                 v_taarich_bakasha,
                                                                 v_report_for_tik,
                                                                 v_do_commit);
        
          --Get department of previous regila 
          select action.code_department
            into v_code_department
          --from v_regila_last_status  v  hana_f changed 13/11/2014
            from v_bakasha_last_status v
            left join code_action action
              on v.code_action = action.code_action
           where v.seq_bakasha = v_seq_previous_regila;
        
          --check if the previous regila is  in gimlaot department
          if (v_code_department = 2) then
            --set seq_bakasha
            v_bakasha_regila_row.seq_bakasha := v_seq_previous_regila;
            v_seq_regila                     := v_seq_previous_regila;
          
            --delete sub tables
            delete from darga_vederug_tik d
             where d.seq_bakasha = v_seq_regila;
            delete from tkufot_avoda_mechushv a
             where a.seq_bakasha = v_seq_regila;
            delete from hagdala_nimuk h where h.seq_bakasha = v_seq_regila;
          
            --update bakasha_regila
            update_bakasha_regila(v_bakasha_regila_row, v_taarich_bakasha);
          else
            v_seq_regila         := insert_bakasha_regila(v_bakasha_regila_row,
                                                          v_seq_poresh,
                                                          v_seq_ezor_ovdim,
                                                          v_taarich_bakasha);
            v_update_sug_bakasha := true;
          end if;
        
        else
          -- if not exist previous regila
          v_bakasha_regila_row := get_bakasha_regila(r.mispar_zehut,
                                                     v_bakasha_regila_row,
                                                     v_seq_ezor_ovdim,
                                                     v_taarich_bakasha,
                                                     v_report_for_tik,
                                                     v_do_commit);
          v_seq_regila         := insert_bakasha_regila(v_bakasha_regila_row,
                                                        v_seq_poresh,
                                                        v_seq_ezor_ovdim,
                                                        v_taarich_bakasha);
          v_update_sug_bakasha := true;
        end if;
      
        if pk_load_mimshak.count_rowes('err_bakasha_regila') > 0 or
           pk_load_mimshak.count_rowes('err_prisha') > 0 or
           pk_load_mimshak.count_rowes('err_bakasha') > 0 then
          v_do_commit := false;
        end if;
        if v_do_commit = true then
          --load other tables
          insert_tkufot_avoda_mechushv(v_tkufot_avoda_mechushv_t,
                                       v_seq_regila);
          insert_hagdala_nimuk(v_hagdala_nimuk_t,
                               v_seq_regila,
                               v_taarich_bakasha);
          load_darga_vederug_tik(r.mispar_zehut, v_seq_regila);
          load_medical_vaada(r.mispar_zehut);
        
          --Update sug bakasha
          if v_update_sug_bakasha = true then
            v_code_sug_bakasha := pk_prm_utils.get_sug_bakasha(v_seq_regila);
          end if;
        end if;
      end if;
    
      --add to action log table
    
      /*   v_is_important_fields_changed :=
      is_important_fields_changed
         (v_seq_previous_regila
         ,v_seq_previous_hagdala
         ,r.mispar_zehut
         ,v_bakasha_regila_row
         ,v_tkufot_avoda_mechushv_t
         ,v_hagdala_nimuk_t);
         
         --check if important  fields was changed
         if (v_is_important_fields_changed)
           then
         --write to log
        \*temp action*\   v_seq_regila := v_seq_regila;
          else*/
    
      --get information about errors on the tik.
      --and do commit if it is not have errors
      --or do rollback if it is have errors.
      v_report_for_tik := info_about_errors_and_commit(r.mispar_zehut,
                                                       v_do_commit,
                                                       v_report_for_tik);
    
      if v_do_commit = true
      --if it is no have errors
       then
        v_count_success := v_count_success + 1;
      elsif v_do_commit = false
      --if it is have errors
       then
        v_count_errors := v_count_errors + 1;
      end if;
    
      v_report := v_report || v_report_for_tik;
    end loop;
  
    -- add to the repport summary rowes  as title.
    v_report := '<html><body>' || '<h1>' || 'total success tikim: ' ||
                v_count_success || '<h1/>' || '<h1>' ||
                'total errors tikim: ' || v_count_errors || '<h1/>' ||
                v_report || '<html/><body/>';
    return v_report;
  end;
  --------------------------------------------------
  procedure delete_security_tik(zeut number) is
    v_seq_poresh number;
  begin
    begin
      select p.porshim_seq
        into v_seq_poresh
        from poresh p
       where p.mispar_zehut = zeut;
    exception
      when others then
        v_seq_poresh := null;
    end;
  
    --delete tkufot avoda mechushv
    delete tkufot_avoda_mechushv
     where seq_bakasha in (select t2.seq_bakasha
                             from bakasha t2
                             left join prisha t3
                               on t2.seq_prisha = t3.seq_prisha
                             left join poresh t4
                               on t3.seq_poresh = t4.porshim_seq
                            where t4.mispar_zehut = zeut);
  
    --delete darga vederug tik
    delete darga_vederug_tik
     where seq_bakasha in (select t2.seq_bakasha
                             from bakasha t2
                             left join prisha t3
                               on t2.seq_prisha = t3.seq_prisha
                             left join poresh t4
                               on t3.seq_poresh = t4.porshim_seq
                            where t4.mispar_zehut = zeut);
  
    --delete hagdala nimuk
    delete hagdala_nimuk
     where seq_bakasha in (select t2.seq_bakasha
                             from bakasha t2
                             left join prisha t3
                               on t2.seq_prisha = t3.seq_prisha
                             left join poresh t4
                               on t3.seq_poresh = t4.porshim_seq
                            where t4.mispar_zehut = zeut);
  
    --delete bakasha regila row
    delete bakasha_regila
     where seq_bakasha in (select t2.seq_bakasha
                             from bakasha t2
                             left join prisha t3
                               on t2.seq_prisha = t3.seq_prisha
                             left join poresh t4
                               on t3.seq_poresh = t4.porshim_seq
                            where t4.mispar_zehut = zeut);
  
    --delete action log
    delete action_log
     where seq_bakasha in (select t2.seq_bakasha
                             from bakasha t2
                             left join prisha t3
                               on t2.seq_prisha = t3.seq_prisha
                             left join poresh t4
                               on t3.seq_poresh = t4.porshim_seq
                            where t4.mispar_zehut = zeut);
    --delete porshim achronim
    delete porshim_achronim
     where seq_prisha in (select t2.seq_prisha
                            from bakasha t2
                            left join prisha t3
                              on t2.seq_prisha = t3.seq_prisha
                            left join poresh t4
                              on t3.seq_poresh = t4.porshim_seq
                           where t4.mispar_zehut = zeut);
  
    --delete bakasha
    delete bakasha
     where seq_bakasha in (select t2.seq_bakasha
                             from bakasha t2
                             left join prisha t3
                               on t2.seq_prisha = t3.seq_prisha
                             left join poresh t4
                               on t3.seq_poresh = t4.porshim_seq
                            where t4.mispar_zehut = zeut);
  
    --delete prisha
    delete prisha where SEQ_PORESH = v_seq_poresh;
  
    --delete bney mishpacha
    delete bney_mishpacha where seq_porshim = v_seq_poresh;
  
    --delete medical vaada 
    delete medical_vaada where seq_poresh = v_seq_poresh;
  
    --delete poresh
    delete poresh where porshim_seq = v_seq_poresh;
  
    commit;
  end;
  --------------------------------------------------
  procedure Get_department_for_bakasha(v_mispar_zehut    in number,
                                       v_code_ezor_ovdim in number,
                                       cur               out sys_refcursor) is
  begin
    open cur for
      select distinct t1.seq_bakasha,
                      first_value(t6.code_action) over(partition by t1.seq_bakasha order by t6.date_action desc) code_action,
                      first_value(t7.teur_action) over(partition by t1.seq_bakasha order by t6.date_action desc) teur_action,
                      first_value(t7.code_department) over(partition by t1.seq_bakasha order by t6.date_action desc) code_department
        from bakasha_regila t1
        left join action_log t6
          on t1.seq_bakasha = t6.seq_bakasha
        left join code_action t7
          on t6.code_action = t7.code_action
       where t7.is_status = 1
         and t1.seq_bakasha =
             (select max(t.seq_bakasha)
                from bakasha_regila t
                left join bakasha t2
                  on t.seq_bakasha = t2.seq_bakasha
                left join prisha t3
                  on t2.seq_prisha = t3.seq_prisha
                left join poresh t4
                  on t3.seq_poresh = t4.porshim_seq
                left join code_ezor_ovdim t5
                  on t3.seq_ezor_ovdim = t5.seq_ezor_ovdim
               where t4.mispar_zehut = v_mispar_zehut
                 and t5.code_ezor_ovdim = v_code_ezor_ovdim);
  
  end;
  --------------------------------------------------
  procedure Add_gimlaot_status(v_mispar_zehut    in number,
                               v_code_ezor_ovdim in number) is
    v_seq_bakasha number;
  begin
    select max(t.seq_bakasha)
      into v_seq_bakasha
      from bakasha_regila t
      left join bakasha t2
        on t.seq_bakasha = t2.seq_bakasha
      left join prisha t3
        on t2.seq_prisha = t3.seq_prisha
      left join poresh t4
        on t3.seq_poresh = t4.porshim_seq
      left join code_ezor_ovdim t5
        on t3.seq_ezor_ovdim = t5.seq_ezor_ovdim
     where t4.mispar_zehut = v_mispar_zehut
       and t5.code_ezor_ovdim = v_code_ezor_ovdim;
  
    --add code_action: 19
    pk_prm_utils.insert_actions_for_bakasha(v_seq_bakasha, 0);
  
    commit;
  end;
  --------------------------------------------------
  procedure Add_malam_status(v_mispar_zehut    in number,
                             v_code_ezor_ovdim in number) is
    v_seq_bakasha number;
  begin
    select max(t.seq_bakasha)
      into v_seq_bakasha
      from bakasha_regila t
      left join bakasha t2
        on t.seq_bakasha = t2.seq_bakasha
      left join prisha t3
        on t2.seq_prisha = t3.seq_prisha
      left join poresh t4
        on t3.seq_poresh = t4.porshim_seq
      left join code_ezor_ovdim t5
        on t3.seq_ezor_ovdim = t5.seq_ezor_ovdim
     where t4.mispar_zehut = v_mispar_zehut
       and t5.code_ezor_ovdim = v_code_ezor_ovdim;
  
    --add code_action: 22
    pk_prm_utils.insert_actions_for_bakasha(v_seq_bakasha, 0);
    commit;
  end;
  --------------------------------------------------
  procedure Get_bakasha(v_mispar_zehut    in number,
                        v_code_ezor_ovdim in number,
                        cur               out sys_refcursor) is
  begin
    open cur for
      select t2.*
        from bakasha t2
        left join prisha t3
          on t2.seq_prisha = t3.seq_prisha
        left join poresh t4
          on t3.seq_poresh = t4.porshim_seq
        left join code_ezor_ovdim t5
          on t3.seq_ezor_ovdim = t5.seq_ezor_ovdim
       where t4.mispar_zehut = v_mispar_zehut
         and t5.code_ezor_ovdim = v_code_ezor_ovdim;
  
  end;
  --------------------------------------------------
end;
/

