          exception
            WHEN OTHERS THEN
              l_sql_res := l_columnValue;
    
          end;
    
          --check constraint error
          if l_columnValue like 'ORA-02290%' then
    
            select t1.condition_translate
              into l_columnValue
              from user_constraints t
              left join ld_translate_constraint t1
