create or replace package body prm_system_copy.pk_LOAD_WS_BK is
  v_max_achuz_kizba number := 70;
  procedure test is
    v_clob_return clob;
  
    v_clob clob;
  begin
    delete from tbl_LD_WS;
  
    v_clob        := '<WsdlRequest xmlns="http://www.example.org/ProcessSchema"><InputId><RecordNumber>055522569</RecordNumber><BirthDate>1958-10-28</BirthDate></InputId><PensionDetails><GroupType>1</GroupType><RetirementDate>2025-10-31</RetirementDate><RetirementClause>118</RetirementClause><RateType>1</RateType><RankType>212</RankType><Seniority>46.25</Seniority><DisciplineAct>0</DisciplineAct><AbsentDays>0</AbsentDays><AcquiredAbsentDays>0</AcquiredAbsentDays><MinistryCode>560</MinistryCode></PensionDetails><DisabilityDetails><RetirementDisability>0.0</RetirementDisability></DisabilityDetails><WorkPeriodInService><Sequence>1</Sequence><PeriodType>1</PeriodType><FromDate>1977-05-03</FromDate><ToDate>1978-02-03</ToDate><EmploymentType>6</EmploymentType><Partiality>1.0</Partiality><OfficeId>9403</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>2</Sequence><PeriodType>4</PeriodType><FromDate>1978-02-04</FromDate><ToDate>1978-09-11</ToDate><EmploymentType>6</EmploymentType><Partiality>1.0</Partiality><OfficeId>9403</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>3</Sequence><PeriodType>1</PeriodType><FromDate>1978-09-12</FromDate><ToDate>1978-12-31</ToDate><EmploymentType>31</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>4</Sequence><PeriodType>1</PeriodType><FromDate>1979-01-01</FromDate><ToDate>1981-05-24</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>5</Sequence><PeriodType>3</PeriodType><FromDate>1981-05-25</FromDate><ToDate>1981-08-16</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>6</Sequence><PeriodType>1</PeriodType><FromDate>1981-08-17</FromDate><ToDate>1983-12-16</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>7</Sequence><PeriodType>3</PeriodType><FromDate>1983-12-17</FromDate><ToDate>1984-03-09</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>8</Sequence><PeriodType>2</PeriodType><FromDate>1984-03-10</FromDate><ToDate>1984-03-12</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>9</Sequence><PeriodType>1</PeriodType><FromDate>1984-03-13</FromDate><ToDate>1987-05-11</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>10</Sequence><PeriodType>3</PeriodType><FromDate>1987-05-12</FromDate><ToDate>1987-08-03</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>11</Sequence><PeriodType>1</PeriodType><FromDate>1987-08-04</FromDate><ToDate>1991-03-31</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>12</Sequence><PeriodType>3</PeriodType><FromDate>1991-04-01</FromDate><ToDate>1991-06-23</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>13</Sequence><PeriodType>1</PeriodType><FromDate>1991-06-24</FromDate><ToDate>1995-07-18</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><S

equence>14</Sequence><PeriodType>3</PeriodType><FromDate>1995-07-19</FromDate><ToDate>1995-10-10</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>15</Sequence><PeriodType>1</PeriodType><FromDate>1995-10-11</FromDate><ToDate>2003-08-10</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>16</Sequence><PeriodType>2</PeriodType><FromDate>2003-08-11</FromDate><ToDate>2003-09-14</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>17</Sequence><PeriodType>1</PeriodType><FromDate>2003-09-15</FromDate><ToDate>9999-12-31</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService></WsdlRequest>';
    v_clob_return := ws_main(v_clob);
    dbms_output.put_line(v_clob_return);
  end;
  --------------------------------------------------------------------
  function ws_main(p_xml_str clob) return clob is
    v_output        clob;
    v_seq_bakasha   number := -1;
    v_record_number number;
    v_code_e_zakaut number;
    v_teur_e_zakaut varchar(100);
    v_error_region  clob;
  
    cXSL xmltype := xmltype('<xsl:stylesheet version="1.0"  xmlns:xsl="http://www.w3.org/1999/XSL/Transform">' ||
                            '<xsl:output method="xml" indent="yes"/>' ||
                            '<xsl:template match="*">' ||
                            '  <xsl:element name="{local-name()}">' ||
                            '    <xsl:apply-templates select="node()|@*" />' ||
                            '  </xsl:element>' || '</xsl:template>' ||
                            '<xsl:template match="@*">' ||
                            '  <xsl:attribute name="{local-name()}"><xsl:value-of select="."/></xsl:attribute>' ||
                            '</xsl:template>' ||
                            '<xsl:template match="processing-instruction()|comment()">' ||
                            '  <xsl:copy>' ||
                            '    <xsl:apply-templates select="node()"/>' ||
                            '  </xsl:copy>' || '</xsl:template>   ' ||
                            '</xsl:stylesheet>');
    vXml xmltype;
  begin
    clear_err_tables;
    begin
    
      select xmltransform(xmltype(p_xml_str), cXSL) into vXml from dual;
    
      -- v_result := load_ld_ws(p_xml_str);
      delete from tbl_LD_WS;
      --pk_prm_utils.delete_bakasha_without_result(v_seq_bakasha);
      insert into tbl_LD_WS values (vXml);
    
    exception
      when others then
        dbms_output.put_line(Sqlerrm);
        return create_error_output(5, 'שגיאה במבנה XML', Sqlerrm);
    end;
    --insert data
    insert_xml_data(v_error_region);
  
    if v_error_region is not null then
    
      v_output := create_error_output(2,
                                      'שגיאה בשלב הקליטה',
                                      trim(v_error_region));
    
      /********************************************/
      /*       cancel all commands                */
      /*                                          */
      rollback;
      /*                                          */
      /*                                          */
      /********************************************/
      return v_output;
    end if;
  
    --calc data
    begin
      pk_convert_golmi_2_mechushav.main(v_seq_bakasha, 1);
    
      pk_zakaut.publc_insrt_ntuny_tik_mchshvim(v_seq_bakasha, 1, 1);
      pk_zakaut.internal_main(v_seq_bakasha, 1);
    
      select t.code_e_zakaut, t1.teur_e_zakaut
        into v_code_e_zakaut, v_teur_e_zakaut
        from netuney_tik_mechushavim t
        left join code_e_zakaut t1
          on t.code_e_zakaut = t1.code_e_zakaut
       where t.seq_bakasha = v_seq_bakasha
         and t.code_department = 1
         and t.mispar_misra = 0;
    
      if v_code_e_zakaut is not null then
        v_output := create_error_output(3,
                                        'שגיאה בשלב העיבוד',
                                        v_teur_e_zakaut);
        /********************************************/
        /*       cancel all commands                */
        /*                                          */
        rollback;
        /*                                          */
        /*                                          */
        /********************************************/
        return v_output;
      end if;
    
      insert_ws_calc_data(v_seq_bakasha);
    exception
      when others then
        v_output := create_error_output(3,
                                        'שגיאה בשלב העיבוד',
                                        sqlerrm);
      
        /********************************************/
        /*       cancel all commands                */
        /*                                          */
        rollback;
        /*                                          */
        /*                                          */
        /********************************************/
        return v_output;
      
    end;
    --create xml result
  
    begin
      select extractValue(value(e), '/InputId/RecordNumber') as "RecordNumber"
        into v_record_number
        from tbl_LD_WS x,
             table(xmlSequence(extract(xml_str, '/WsdlRequest/InputId'))) e;
    
      v_output := create_output(v_record_number);
    exception
      when others then
        v_output := create_error_output(4,
                                        'שגיאה בשלב יצירת הפלט',
                                        sqlerrm);
      
        /********************************************/
        /*       cancel all commands                */
        /*                                          */
        rollback;
        /*                                          */
        /*                                          */
        /********************************************/
        return v_output;
    end;
    --dbms_output.put_line(v_output);
  
    /********************************************/
    /*       cancel all commands                */
    /*                                          */
    rollback;
    /*                                          */
    /*                                          */
    /********************************************/
    return v_output;
  end;
  ----------------------------------------------------------------------------
  procedure insert_xml_data(p_error_region in out clob) is
    v_seq_ezor_ovdim        number;
    v_seq_bakasha           number := -1;
    v_seq_bakasha_previos   number;
    v_seq_poresh            number := -1;
    v_seq_darga_vderug      number := -1;
    v_seq_prisha            number := -1;
    v_record_number         number;
    v_ministry_code         number;
    v_birth_date            varchar2(10);
    v_death_date            varchar2(10);
    v_group_type            number;
    v_rate_type             number;
    v_rank_type             number;
    v_retirement_date       varchar2(10);
    v_retirement_clause     number;
    v_code_seif_prisha      number;
    v_discipline_act        number := null;
    v_seniority             number;
    v_absent_days           number;
    v_acquired_absent_days  number;
    v_retirement_disability number;
    v_retirement_from_date  varchar2(10);
    v_code_sug_bakasha      number;
    v_test                  nvarchar2(1000);
  
  begin
    --exists poresh?
    --begin
    select extractValue(value(e), '/InputId/RecordNumber') as "RecordNumber",
           extractValue(value(e), '/InputId/BirthDate') as "BirthDate",
           extractValue(value(e), '/InputId/DeathDate') as "DeathDate"
      into v_record_number, v_birth_date, v_death_date
      from tbl_LD_WS x,
           table(xmlSequence(extract(xml_str, '/WsdlRequest/InputId'))) e;
  
    select extractValue(value(e), '/PensionDetails/MinistryCode') as "MinistryCode",
           extractValue(value(e), '/PensionDetails/GroupType') as "GroupType",
           extractValue(value(e), '/PensionDetails/RetirementDate') as "RetirementDate",
           extractValue(value(e), '/PensionDetails/RetirementClause') as "RetirementClause",
           extractValue(value(e), '/PensionDetails/RateType') as "RateType",
           extractValue(value(e), '/PensionDetails/RankType') as "RankType",
           extractValue(value(e), '/PensionDetails/DisciplineAct') as "DisciplineAct",
           extractValue(value(e), '/PensionDetails/Seniority') as "Seniority",
           extractValue(value(e), '/PensionDetails/AbsentDays') as "AbsentDays",
           extractValue(value(e), '/PensionDetails/AcquiredAbsentDays') as "AcquiredAbsentDays"
      into v_ministry_code,
           v_group_type,
           v_retirement_date,
           v_retirement_clause,
           v_rate_type,
           v_rank_type,
           v_discipline_act,
           v_seniority,
           v_absent_days,
           v_acquired_absent_days
      from tbl_LD_WS x,
           table(xmlSequence(extract(xml_str, '/WsdlRequest/PensionDetails'))) e;
    begin
      select extractValue(value(e),
                          '/DisabilityDetails/RetirementDisability') as "RetirementDisability",
             extractValue(value(e), '/DisabilityDetails/RetirementFromDate') as "RetirementFromDate"
        into v_retirement_disability, v_retirement_from_date
        from tbl_LD_WS x,
             table(xmlSequence(extract(xml_str,
                                       '/WsdlRequest/DisabilityDetails'))) e;
    exception
      when no_data_found then
        null;
    end;
  
    begin
      select e.seq_ezor_ovdim
        into v_seq_ezor_ovdim
        from code_ezor_ovdim e
       where e.code_makor in (1, 2, 3)
         and e.code_ezor_ovdim = v_ministry_code
         and e.pail = 1;
    exception
      when no_data_found then
        p_error_region := 'error ministry code';
    end;
    v_seq_bakasha_previos := pk_load.Check_previos_bakasha(v_record_number,
                                                           v_seq_ezor_ovdim,
                                                           1);
  
    if v_seq_bakasha_previos is null then
      v_code_sug_bakasha := 1;
      begin
        select sum(t.porshim_seq)
          into v_seq_poresh
          from poresh t
         where t.mispar_zehut = v_record_number;
      
      exception
        when no_data_found then
          v_seq_poresh := -1;
      end;
    
      if v_seq_poresh is null then
        v_seq_poresh := -1;
        insert into poresh
          (mispar_zehut,
           porshim_seq,
           shem_prati,
           shem_mishpacha,
           taarich_leda,
           taarich_ptira)
        values
          (v_record_number,
           v_seq_poresh,
           'WS',
           'WS',
           to_date(v_birth_date, 'yyyy-mm-dd'),
           to_date(v_death_date, 'yyyy-mm-dd')) log errors into err_porshim reject limit unlimited;
      elsif v_death_date is not null then
        update poresh p
           set p.taarich_ptira = to_date(v_death_date, 'yyyy-mm-dd')
         where p.porshim_seq = v_seq_poresh;
      end if;
      insert into prisha
        (seq_prisha, seq_poresh, seq_ezor_ovdim)
      values
        (v_seq_prisha, v_seq_poresh, v_seq_ezor_ovdim) log errors into err_prisha reject limit unlimited;
    else
      v_code_sug_bakasha := 5;
      select p.seq_prisha, p.seq_poresh
        into v_seq_prisha, v_seq_poresh
        from bakasha b
        left join prisha p
          on b.seq_prisha = p.seq_prisha
       where b.seq_bakasha = v_seq_bakasha_previos;
    end if;
    insert into bakasha
      (seq_bakasha,
       seq_prisha,
       code_sug_bakasha,
       date_bakasha,
       code_source)
    values
      (v_seq_bakasha, v_seq_prisha, v_code_sug_bakasha, sysdate, 99) log errors into err_bakasha reject limit unlimited;
  
    /*   begin
      select e.code_seif_prisha
        into v_code_seif_prisha
        from code_seif_prisha e
       where instr(e.code_seif_markava, v_retirement_clause) > 0;
    exception
      when no_data_found then
        p_error_region := 'error Retirement Clause';
    end;*/
    insert into bakasha_regila
      (seq_bakasha,
       taarich_prisha,
       code_seif_prisha,
       vetek,
       is_din_mishmaati,
       nechut_achuz,
       nechut_taarich_hamigbala,
       such_yemey_headrut,
       such_yemey_headrut_shnirkshu)
    values
      (v_seq_bakasha,
       to_date(v_retirement_date, 'yyyy-mm-dd'),
       zero_to_null(v_retirement_clause),
       zero_to_null(v_seniority),
       zero_to_null(v_discipline_act),
       zero_to_null(v_retirement_disability),
       to_date(v_retirement_from_date, 'yyyy-mm-dd'),
       v_absent_days,
       v_acquired_absent_days) log errors into err_bakasha_regila reject limit unlimited;
  
    insert into darga_vederug_tik
      (seq_dargot_vederug_tik, seq_bakasha, code_derug, code_darga)
    values
      (v_seq_darga_vderug, v_seq_bakasha, v_rate_type, v_rank_type) log errors into err_darga_vederug_tik reject limit unlimited;
    --concat error table
    --  select from --tkufot golmi
    insert_tkufot(v_seq_bakasha, p_error_region);
    insert_out_service_tkufot(v_seq_bakasha);
    insert_army_tkufot(v_seq_bakasha);
  
    add_err_tables_to_log(p_error_region);
  
  end;
  -------------------------------------------------------------------------------------
  procedure insert_tkufot(p_seq_bakasha number, p_error_region in out clob) is
    v_seq_ezor_ovdim number;
    v_test           nvarchar2(10);
    l_xml            XMLTYPE;
  
  begin
    select t.xml_str into l_xml from tbl_ld_ws t;
    for r in (SELECT xt.*
                FROM XMLTABLE('WsdlRequest/WorkPeriodInService' PASSING
                              l_xml COLUMNS OfficeId VARCHAR2(4) PATH
                              'OfficeId',
                              PeriodType VARCHAR2(4) PATH 'PeriodType',
                              FromDate VARCHAR2(10) PATH 'FromDate',
                              ToDate VARCHAR2(10) PATH 'ToDate',
                              EmploymentType VARCHAR2(4) PATH
                              'EmploymentType',
                              Partiality VARCHAR2(5) PATH 'Partiality',
                              RightType VARCHAR2(4) PATH 'RightType',
                              Sequence VARCHAR2(4) PATH 'Sequence') xt) loop
      begin
        if r.OfficeId is not null then
          select e.seq_ezor_ovdim
            into v_seq_ezor_ovdim
            from code_ezor_ovdim e
           where e.code_makor in (1, 2, 3)
             and e.code_ezor_ovdim = r.OfficeId
             and e.pail = 1;
        end if;
      exception
        when no_data_found then
          p_error_region := 'error ministry code';
      end;
    
      insert into tkufot_avoda_golmi
        (seq_bakasha,
         seq_tkufot_avoda_golmi,
         taarich_me,
         taarich_ad,
         achuz_chelkyut,
         code_sugey_tkufot,
         code_sugey_zchuyot,
         code_sugey_haasaka,
         ezor_ovdim_be_tkufa)
      values
        (p_seq_bakasha,
         r.sequence * -1,
         to_date(r.fromdate, 'yyyy-mm-dd'),
         to_date(r.todate, 'yyyy-mm-dd'),
         r.partiality,
         r.periodtype,
         zero_to_null(r.righttype),
         zero_to_null(r.EmploymentType),
         v_seq_ezor_ovdim) log errors into err_tkufot_avoda_golmi reject limit unlimited;
    
    --dbms_output.put_line(r.OfficeId || r.Sequence);
    end loop;
  end;
  -------------------------------------------------------------------------------------
  procedure insert_army_tkufot(p_seq_bakasha number) is
    v_seq_ezor_ovdim number;
    v_test           nvarchar2(10);
    l_xml            XMLTYPE;
  
  begin
    select t.xml_str into l_xml from tbl_ld_ws t;
    begin
      for r in (SELECT xt.*
                  FROM XMLTABLE('WsdlRequest/WorkPeriodInArmy' PASSING l_xml
                                COLUMNS PeriodType VARCHAR2(4) PATH
                                'PeriodType',
                                FromDate VARCHAR2(10) PATH 'FromDate',
                                ToDate VARCHAR2(10) PATH 'ToDate',
                                EligibleDate VARCHAR2(10) PATH 'EligibleDate',
                                Sequence VARCHAR2(4) PATH 'Sequence') xt) loop
      
        insert into tkufot_sherut_tsvaii
          (seq_bakasha,
           seq_tkufot_sherut_tsvaii,
           taarich_me,
           taarich_ad,
           taarich_zchuyot,
           code_sug_sherut_tzaii)
        values
          (p_seq_bakasha,
           r.sequence * -1,
           to_date(r.fromdate, 'yyyy-mm-dd'),
           to_date(r.todate, 'yyyy-mm-dd'),
           to_date(r.EligibleDate, 'yyyy-mm-dd'),
           r.periodtype) log errors into err_tkufot_sherut_tsvaii reject limit unlimited;
      
      end loop;
    exception
      when no_data_found then
        null;
    end;
  end;
  -------------------------------------------------------------------------------------
  procedure insert_out_service_tkufot(p_seq_bakasha number) is
    v_seq_ezor_ovdim number;
    v_test           nvarchar2(10);
    l_xml            XMLTYPE;
    v_sum_peroids    number;
  begin
    select t.xml_str into l_xml from tbl_ld_ws t;
    begin
      for r in (SELECT xt.*
                  FROM XMLTABLE('WsdlRequest/WorkPeriodOutofService' PASSING
                                l_xml COLUMNS WorkType VARCHAR2(4) PATH
                                'WorkType',
                                FromDate VARCHAR2(10) PATH 'FromDate',
                                ToDate VARCHAR2(10) PATH 'ToDate',
                                AgreementDate VARCHAR2(10) PATH
                                'AgreementDate',
                                Sequence VARCHAR2(4) PATH 'Sequence') xt) loop
      
        insert into tkufot_michutz_lasharut
          (seq_bakasha,
           seq_tkufot_michutz_lasharut,
           taarich_me,
           taarich_ad,
           taarich_heskem,
           code_sug_makom_avoda)
        values
          (p_seq_bakasha,
           r.sequence * -1,
           to_date(r.fromdate, 'yyyy-mm-dd'),
           to_date(r.todate, 'yyyy-mm-dd'),
           to_date(r.AgreementDate, 'yyyy-mm-dd'),
           zero_to_null(r.WorkType)) log errors into err_tkufot_michutz_lasharut reject limit unlimited;
      
      end loop;
    
      select sum(months_between(t.taarich_ad + 1, t.taarich_me))
        into v_sum_peroids
        from tkufot_michutz_lasharut t
       where t.seq_bakasha = p_seq_bakasha;
    
      update netuney_tik_mechushavim t
         set t.chodeshim_mezkim_out_of_srv_y = floor(v_sum_peroids / 12),
             t.chodeshim_mezkim_out_of_srv_m = floor(mod(v_sum_peroids, 12)),
             t.chodeshim_mezkim_out_of_srv_d = round((v_sum_peroids -
                                                     floor(v_sum_peroids)) *
                                                     30.44)
       where t.seq_bakasha = p_seq_bakasha;
    exception
      when no_data_found then
        null;
    end;
  
  end;
  ---------------------------------------------------------------------------
  procedure Insert_tkufot_mechushav(p_taarich_me                  date,
                                    p_taarich_ad                  date,
                                    p_achuz_chelkyut              number,
                                    p_praklit                     number,
                                    p_haim_kana_zchuyot           number,
                                    p_code_sugey_tkufot           number,
                                    p_code_sugey_haasaka          number,
                                    p_code_sugey_zchuyot          number,
                                    p_seq_tkufot_avoda_mechushv   number,
                                    p_ezor_ovdim_be_tkufa         number,
                                    p_seq_tkufot_avoda_golmi      number,
                                    p_seq_bakasha                 number,
                                    p_seq_tkufot_michutz_lasharut number,
                                    p_seq_tkufot_sherut_tsvaii    number) is
    v_is_exist_same_row   number;
    v_ezor_ovdim_be_tkufa number;
  begin
    select count(*)
      into v_is_exist_same_row
      from tkufot_avoda_mechushv m
     where m.taarich_me = p_taarich_me
       and m.taarich_ad = p_taarich_ad
       and m.seq_bakasha = p_seq_bakasha
       and m.achuz_chelkyut = 1;
  
    if v_is_exist_same_row > 0 then
      return;
    end if;
  
    insert into tkufot_avoda_mechushv
      (taarich_me,
       taarich_ad,
       achuz_chelkyut,
       praklit,
       sach_chodeshim,
       haim_kana_zchuyot,
       code_sugey_tkufot,
       code_sugey_haasaka,
       code_sugey_zchuyot,
       seq_tkufot_avoda_mechushv,
       ezor_ovdim_be_tkufa,
       seq_tkufot_avoda_golmi,
       seq_bakasha,
       seq_tkufot_michutz_lasharut,
       seq_tkufot_sherut_tsvaii)
    values
      (p_taarich_me,
       p_taarich_ad,
       p_achuz_chelkyut,
       p_praklit,
       round(months_between(p_taarich_ad + 1, p_taarich_me), 2),
       p_haim_kana_zchuyot,
       p_code_sugey_tkufot,
       p_code_sugey_haasaka,
       p_code_sugey_zchuyot,
       p_seq_tkufot_avoda_mechushv,
       p_ezor_ovdim_be_tkufa,
       p_seq_tkufot_avoda_golmi,
       p_seq_bakasha,
       p_seq_tkufot_michutz_lasharut,
       p_seq_tkufot_sherut_tsvaii);
  
  end;
  --------------------------------------------------------------------------
  procedure insert_ws_calc_data(p_seq_bakasha number) is
    v_sum_peroids number;
    v_odef_months number;
  begin
    --keren peroids
    select sum(months_between(t.taarich_ad + 1, t.taarich_me))
      into v_sum_peroids
      from tkufot_avoda_mechushv t
     where t.seq_bakasha = p_seq_bakasha
       and t.code_sugey_zchuyot = 8;
  
    update netuney_tik_mechushavim t
       set t.Keren_Mezaka_Shana   = floor(v_sum_peroids / 12),
           t.keren_mezaka_chodesh = floor(mod(v_sum_peroids, 12)),
           t.keren_mezaka_yamim   = round((v_sum_peroids -
                                          floor(v_sum_peroids)) * 30.44)
     where t.seq_bakasha = p_seq_bakasha;
  
    --part odef between years and month
    /* update netuney_tik_mechushavim t
      set t.odef_sherut_chodashim = mod(nvl(t.odef_sherut_chodashim, 0), 12),
          t.odef_sherut_shanim    = floor(nvl(t.odef_sherut_chodashim, 0) / 12)
    where t.seq_bakasha = p_seq_bakasha;*/
    select sum(months_between(t.taarich_ad + 1, t.taarich_me))
      into v_sum_peroids
      from tkufot_michutz_lasharut t
     where t.seq_bakasha = p_seq_bakasha;
  
    update netuney_tik_mechushavim t
       set t.chodeshim_mezkim_out_of_srv_y = floor(v_sum_peroids / 12),
           t.chodeshim_mezkim_out_of_srv_m = floor(mod(v_sum_peroids, 12)),
           t.chodeshim_mezkim_out_of_srv_d = round((v_sum_peroids -
                                                   floor(v_sum_peroids)) *
                                                   30.44)
     where t.seq_bakasha = p_seq_bakasha;
  end;

  ---------------------------------------------------------------------------
  function create_output(p_id_number number) return clob is
    v_record_id                   clob;
    v_calc_peroids                clob;
    v_result                      clob;
    v_output                      clob;
    v_achuz_kizba_kafuf_chelkiyut number;
    v_chelkiyut_lefi_sherut       number;
  begin
    SELECT XMLELEMENT("OutputId", XMLELEMENT("IdentityNumber", p_id_number), XMLELEMENT("ErrorType", nvl(t.code_e_zakaut, 0)))
           .getclobval() AS ID_Record
      into v_record_id
      FROM netuney_tik_mechushavim t
     where t.seq_bakasha = -1
       and t.code_department = 1
       and t.mispar_misra = 0;
  
    SELECT XMLELEMENT("Results", XMLELEMENT("RetirementType", t.code_group_prisha),
           
           XMLELEMENT("TotalMonths", nvl(t.tkufa_mezaka_sherut, 0) /* - nvl(t.chodeshim_mezkim_out_of_srv_m, 0)*/),
           
           XMLELEMENT("NonEntitlingMonths", nvl(t.tkufa_lo_mezaka_sherut, 0)),
           
           XMLELEMENT("Percentage", get_achuz_kizba_lefi_shert(t.achuz_kizba_kafuf_chelkiyut, t.chelkiyut_meshuklelet_sherut)),
           
           XMLELEMENT("Partiality", /*get_chelkiyut_lefi_shert(t.achuz_kizba_kafuf_chelkiyut,*/ t.chelkiyut_meshuklelet_sherut /*)*/),
           
           XMLELEMENT("PercentagePartial", round(get_achuz_kizba_lefi_shert(t.achuz_kizba_kafuf_chelkiyut, t.chelkiyut_meshuklelet_sherut) * get_chelkiyut_lefi_shert(t.achuz_kizba_kafuf_chelkiyut, t.chelkiyut_meshuklelet_sherut), 2)),
           
           XMLELEMENT("DisabilityPercentage", nvl(achuz_kizba_nechut, 0)),
           
           XMLELEMENT("DisabilityPartiality", nvl(t.chelkiut_lefi_nechut, 0)),
           
           XMLELEMENT("YearCompensation", floor(nvl(t.odef_sherut_chodashim, 0) / 12)),
           
           XMLELEMENT("MonthCompensation", mod(nvl(t.odef_sherut_chodashim, 0), 12)),
           
           XMLELEMENT("DayCompensation", mod(nvl(t.odef_sherut_yamim, 0), 12)),
           
           XMLELEMENT("YearsKeren", nvl(t.keren_mezaka_shana, 0)),
           
           XMLELEMENT("MonthsKeren", nvl(t.keren_mezaka_chodesh, 0)),
           
           XMLELEMENT("DaysKeren", nvl(t.keren_mezaka_yamim, 0)),
           
           XMLELEMENT("YearsOutofService", nvl(floor(nvl(t.chodeshim_mezkim_out_of_srv_m, 0) / 12), 0)),
           
           XMLELEMENT("MonthsOutofService", floor(mod(nvl(t.chodeshim_mezkim_out_of_srv_m, 0), 12))),
           
           XMLELEMENT("DaysOutofService", round(mod(nvl(t.chodeshim_mezkim_out_of_srv_m, 0), 1) * 30.44)),
           
           XMLELEMENT("EgibilityDate", t.date_start_zakaut), XMLELEMENT("AbsentDays", nvl(t1.such_yemey_headrut, 0)),
           
           XMLELEMENT("AcquiredAbsentDays", nvl(t1.such_yemey_headrut_shnirkshu, 0)),
           
           XMLELEMENT("GrantEgibility", nvl(t.is_zakai_lmaanak, 0)))
           .getClobVal() AS Result
      into v_result
      FROM netuney_tik_mechushavim t
      left join bakasha_regila t1
        on t.seq_bakasha = t1.seq_bakasha
     where t.seq_bakasha = -1
       and t.code_department = 1
       and t.mispar_misra = 0;
  
    SELECT XMLAGG(XMLELEMENT("WorkPeriodAll",
           
           XMLFOREST(e.seq_tkufot_avoda_mechushv as "Sequence", nvl(e.code_sugey_tkufot, 0) as "PeriodType", e.taarich_me as "FromDate", e.taarich_ad as "ToDate", nvl(e.code_sugey_haasaka, 0) as "EmploymentType", nvl(e.achuz_chelkyut, 0) as "Partial", nvl(convert_ezor_ovdim_to_mekava(e.ezor_ovdim_be_tkufa), 0) as "OfficeId", nvl(e.code_sugey_zchuyot, 0) as "RightType", round(months_between(e.taarich_ad + 1, e.taarich_me), 2) as "TotalMonths")))
           .getClobVal() as TotalMonths
      into v_calc_peroids
      FROM tkufot_avoda_mechushv e
     WHERE e.seq_bakasha = -1;
    v_output := '<?xml version="1.0" encoding="utf-8"?> <WsdlResponse xmlns="http://www.example.org/ProcessSchema">' ||
                create_error_output(0, '', '') || '<OutputResults>' ||
                v_record_id || v_result || v_calc_peroids ||
                '</OutputResults></WsdlResponse>';
    return v_output;
  
  end;
  ----------------------------------------------------------------------------------
  function get_achuz_kizba_lefi_shert(p_achuz_kizba_kafuf_chelkiyut number,
                                      p_chelkiyut_lefi_sherut       number)
    return number is
  begin
    if p_achuz_kizba_kafuf_chelkiyut * p_chelkiyut_lefi_sherut >
       v_max_achuz_kizba then
      return v_max_achuz_kizba;
    else
      return nvl(p_achuz_kizba_kafuf_chelkiyut, 0);
    end if;
  end;
  ----------------------------------------------------------------------------------
  function get_chelkiyut_lefi_shert(p_achuz_kizba_kafuf_chelkiyut number,
                                    p_chelkiyut_lefi_sherut       number)
    return number is
  begin
    if p_achuz_kizba_kafuf_chelkiyut * p_chelkiyut_lefi_sherut >
       v_max_achuz_kizba then
      return 1;
    else
      return nvl(p_chelkiyut_lefi_sherut, 0);
    end if;
  end;
  ---------------------------------------------------------------------------------
  function convert_ezor_ovdim_to_mekava(v_seq_ezor_ovdim number)
    return number is
    v_code_ezor_ovdim_merkava number;
  begin
    begin
      select e.code_ezor_ovdim
        into v_code_ezor_ovdim_merkava
        from code_ezor_ovdim e
       where e.code_makor in (1, 2, 3)
         and e.seq_ezor_ovdim = v_seq_ezor_ovdim
         and e.pail = 1;
    exception
      when no_data_found then
        return null;
    end;
    return v_code_ezor_ovdim_merkava;
  end;
  ----------------------------------------------------------------------------------
  function load_ld_ws(p_xml_str clob) return varchar is
  begin
    insert into tbl_LD_WS values (sys.xmltype.createXML(p_xml_str));
  
  exception
    when others then
      return 'error in xml structure';
      return 'XML inserted';
  end;
  --------------------------------------------------------------------
  function zero_to_null(p_value number) return number is
  begin
    if p_value <> 0 then
      return p_value;
    else
      return null;
    end if;
  end;
  ----------------------------------------------------------
  procedure add_err_table(p_table_name varchar2) is
  
    type typ_num_list is table of number;
  
    v_num_list typ_num_list;
  
    type typ_var_list is table of varchar2(2000);
    v_rowid_list typ_var_list;
    v_var_list   typ_var_list;
  
    v_cmd varchar2(1000);
  
    v_field varchar2(1000);
    v_mesg  varchar2(2000);
  
    v_first_position  number;
    v_second_position number;
  
    v_is_exist_mesg_in_table number;
  
    v_search_condition_long long;
    v_columns               varchar2(1000);
  
    v_sql_get_value varchar2(4000);
    v_value         varchar2(4000);
    v_values        varchar2(4000);
  begin
    --get the errors from the table
    v_cmd := 'select rowid ,ora_err_number$,ora_err_mesg$ from ' ||
             p_table_name;
  
    execute immediate v_cmd bulk collect
      into v_rowid_list, v_num_list, v_var_list;
  
    for i in 1 .. v_num_list.count() loop
    
      select count(*)
        into v_is_exist_mesg_in_table
        from code_load_msg t
       where t.code_load_msg = v_num_list(i);
    
      if v_is_exist_mesg_in_table > 0 then
        -- when is exist mesg in table, get the translate mesg from the table
        v_mesg   := null;
        v_values := null;
        --get the field from the orginal mesg
        v_field := v_var_list(i);
      
        v_first_position  := instr(v_field, '(') + 1;
        v_second_position := instr(v_field, ')');
      
        --get only specific detailes, not general mesg
        v_field := substr(v_field,
                          v_first_position,
                          v_second_position - v_first_position);
      
        --remove schema name and table name
        v_field := substr(v_field, instr(v_field, '.', -1) + 1);
      
        v_field   := replace(v_field, '"');
        v_columns := null;
      
        -- get check constaint detailes
        if v_num_list(i) = 2290 then
          select t.SEARCH_CONDITION
            into v_search_condition_long
            from user_constraints t
           where t.CONSTRAINT_NAME = v_field;
        
          v_field := substr(v_search_condition_long, 1, 2000) || ' [' ||
                     v_field || ']';
        
          -- get foreign key and primary key detailes
        elsif v_num_list(i) = 2291 or v_num_list(i) = 1 then
          for r in (select t.column_name
                      from user_cons_columns t
                     where t.constraint_name = v_field) loop
            select decode(v_columns,
                          null,
                          r.column_name,
                          v_columns || ',' || r.column_name)
              into v_columns
              from dual;
          end loop;
          v_field := v_columns || ' [' || v_field || ']';
        
          --get field name when numeric error
        elsif v_num_list(i) = 01722 then
          v_field := pk_load_mimshak.get_numeric_error(v_rowid_list(i),
                                                       p_table_name);
          --get field name when date error
        elsif v_num_list(i) = 01840 or v_num_list(i) = 01847 or
              v_num_list(i) = 01858 then
          v_field := pk_load_mimshak.get_date_error(v_rowid_list(i),
                                                    p_table_name);
        
        end if;
      
      else
        v_mesg := v_var_list(i);
      end if;
    
      --Get column name (without other expression)
      for r in (select t.COLUMN_NAME
                  from user_tab_cols t
                 where t.TABLE_NAME = p_table_name
                   and lower(nvl(v_field, v_var_list(i))) like
                       '%' || lower(t.COLUMN_NAME) || '%') loop
        --Get value
        v_sql_get_value := 'select ' || r.column_name || ' from ' ||
                           p_table_name || ' where rowid = ''' ||
                           v_rowid_list(i) || '''';
        execute immediate v_sql_get_value
          into v_value;
      
        select v_values || decode(v_values, null, '', v_values || ',') ||
               v_value
          into v_values
          from dual;
      end loop;
    
    --save the edited error in table
    
    end loop;
  
  end;
  ----------------------------------------------------------
  procedure add_err_tables_to_log(p_error_log in out clob) is
  begin
    --Add to the report info about the error tables.
    Get_error_format_varchar('ERR_PORSHIM',
                             'porshim_seq',
                             -1,
                             null,
                             p_error_log);
    Get_error_format_varchar('ERR_BAKASHA_REGILA',
                             'seq_bakasha',
                             -1,
                             null,
                             p_error_log);
    Get_error_format_varchar('ERR_TKUFOT_AVODA_GOLMI',
                             'seq_bakasha',
                             -1,
                             'seq_tkufot_avoda_golmi',
                             p_error_log);
    Get_error_format_varchar('ERR_TKUFOT_MICHUTZ_LASHARUT',
                             'seq_bakasha',
                             -1,
                             'seq_tkufot_michutz_lasharut',
                             p_error_log);
    Get_error_format_varchar('ERR_TKUFOT_SHERUT_TSVAII',
                             'seq_bakasha',
                             -1,
                             'seq_tkufot_sherut_tsvaii',
                             p_error_log);
    Get_error_format_varchar('ERR_DARGA_VEDERUG_TIK',
                             'seq_bakasha',
                             -1,
                             null,
                             p_error_log);
    Get_error_format_varchar('ERR_PRISHA',
                             'seq_prisha',
                             -1,
                             null,
                             p_error_log);
    Get_error_format_varchar('ERR_BAKASHA',
                             'seq_bakasha',
                             -1,
                             null,
                             p_error_log);
  end;
  -----------------------------------------------
  procedure clear_err_tables is
  begin
    --Add to the report info about the error tables.
  
    delete from ERR_BAKASHA_REGILA where seq_bakasha = -1;
    delete from ERR_TKUFOT_AVODA_GOLMI where seq_bakasha = -1;
    delete from ERR_TKUFOT_MICHUTZ_LASHARUT where seq_bakasha = -1;
    delete from ERR_TKUFOT_SHERUT_TSVAII where seq_bakasha = -1;
    delete from ERR_DARGA_VEDERUG_TIK where seq_bakasha = -1;
    delete from ERR_BAKASHA where seq_bakasha = -1;
    delete from ERR_PRISHA where seq_prisha = -1;
    delete from ERR_PORSHIM where porshim_seq = -1;
    commit;
  end;
  -----------------------------------------------
  procedure Get_error_format_varchar(p_table           varchar2,
                                     p_column_pk_name  varchar2,
                                     p_column_pk_value varchar2,
                                     p_column_seq      varchar2,
                                     p_error_log       in out clob) is
    p_Query     clob;
    p_query_seq clob;
    l_sql_res   clob;
  begin
    p_Query := 'select string_agg(t.ORA_ERR_MESG$)from ' || p_table ||
               ' t where ' || p_column_pk_name || ' = ' ||
               p_column_pk_value;
  
    execute immediate p_Query
      into l_sql_res;
    if l_sql_res is not null then
      p_Query := 'select ''table: ' || p_table || '~''||' || case
                   when p_column_seq is null then
                   
                    'string_agg(t.ORA_ERR_MESG$)'
                   else
                    'string_agg(''line:''|| ' || p_column_seq ||
                    '||''~''||t.ORA_ERR_MESG$) '
                 end || ' from ' || p_table || ' t where ' || p_column_pk_name ||
                 ' = ' || p_column_pk_value;
      execute immediate p_Query
        into l_sql_res;
      p_error_log := trim(p_error_log) || trim(l_sql_res);
    end if;
  end;

  -----------------------------------------------
  procedure Get_error_format_varchar_1(p_table     varchar2,
                                       p_error_log in out clob) is
