    l_status      INTEGER;
    l_colCnt      NUMBER;
    rec_tab       DBMS_SQL.DESC_TAB;
    l_sql_res     clob;
  
    l_index number(2);
    s       clob;
    row_id  clob;
    TYPE fields_name_array IS VARRAY(10) OF varchar2(200);
    fields_name fields_name_array := fields_name_array(10);
  
  begin
  
    p_Query := ' select rowid, t.ORA_ERR_MESG$ from ' || p_table || ' t ';
    /*-- parse given query
