              end if;
              fields_name(l_index) := r.column_name;
            end loop;
            --numeric error
          elsif l_columnValue like 'ORA-01722%' then
            s := 'select pk_load_mimshak.get_numeric_error(rowid,''' ||
                 p_table || ''')
              from ' || p_table || ' where rowid =''' || row_id || '''';
            fields_name.extend(1);
            execute immediate s
              into fields_name(1);
            --date error
          elsif l_columnValue like 'ORA-01840%' then
            s := 'select pk_load_mimshak.get_date_error(rowid,''' || p_table || ''')
              from ' || p_table || ' where rowid =''' || row_id || '''';
            fields_name.extend(1);
            execute immediate s
              into fields_name(1);
    
          end if;
    
          l_sql_res := l_sql_res;
    
          if fields_name.count > 0 then
            l_sql_res := l_sql_res || 'בשדה: ';
            FOR i IN fields_name.FIRST .. fields_name.LAST LOOP
              l_sql_res := l_sql_res || fields_name(i) || ' ';
            END LOOP;
          end if;
    
        end if;
      end loop;
      --Get the column that its value is invalid
    end loop;
    dbms_sql.close_cursor(l_theCursor);
    p_error_log           := trim(p_error_log) || trim(l_sql_res);*/
  end;
  -----------------------------------------------------------------------------
  function create_error_output(p_error_code   number,
                               p_error_desc   varchar,
                               p_error_dtails clob) return clob is
    v_error_str clob;
  begin
    v_error_str := '<ResponseStatus>
                            <Response_Code>' ||
                   p_error_code ||
                   '</Response_Code>
                            <Response_Desc>' ||
                   trim(p_error_desc) ||
                   '</Response_Desc>
                            <Response_Details>' ||
                   trim(p_error_dtails) ||
                   '</Response_Details>
                  </ResponseStatus>';
    if nvl(p_error_code, 0) <> 0 then
      v_error_str := '<WsdlResponse xmlns="http://www.example.org/ProcessSchema">' ||
                     trim(v_error_str) || '</WsdlResponse>';
    end if;
    return v_error_str;
  end;
end;
/

