><ToDate>1983-12-16</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>7</Sequence><PeriodType>3</PeriodType><FromDate>1983-12-17</FromDate><ToDate>1984-03-09</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>8</Sequence><PeriodType>2</PeriodType><FromDate>1984-03-10</FromDate><ToDate>1984-03-12</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>9</Sequence><PeriodType>1</PeriodType><FromDate>1984-03-13</FromDate><ToDate>1987-05-11</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>10</Sequence><PeriodType>3</PeriodType><FromDate>1987-05-12</FromDate><ToDate>1987-08-03</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>11</Sequence><PeriodType>1</PeriodType><FromDate>1987-08-04</FromDate><ToDate>1991-03-31</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>12</Sequence><PeriodType>3</PeriodType><FromDate>1991-04-01</FromDate><ToDate>1991-06-23</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>13</Sequence><PeriodType>1</PeriodType><FromDate>1991-06-24</FromDate><ToDate>1995-07-18</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><S



equence>14</Sequence><PeriodType>3</PeriodType><FromDate>1995-07-19</FromDate><ToDate>1995-10-10</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>15</Sequence><PeriodType>1</PeriodType><FromDate>1995-10-11</FromDate><ToDate>2003-08-10</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>16</Sequence><PeriodType>2</PeriodType><FromDate>2003-08-11</FromDate><ToDate>2003-09-14</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService><WorkPeriodInService><Sequence>17</Sequence><PeriodType>1</PeriodType><FromDate>2003-09-15</FromDate><ToDate>9999-12-31</ToDate><EmploymentType>4</EmploymentType><Partiality>1.0</Partiality><OfficeId>560</OfficeId><RightType>0</RightType></WorkPeriodInService></WsdlRequest>';
    v_clob_return := ws_main(v_clob);
    dbms_output.put_line(v_clob_return);
  end;
  --------------------------------------------------------------------
  function ws_main(p_xml_str clob) return clob is
    v_output        clob;
    v_seq_bakasha   number := -1;
    v_record_number number;
    v_code_e_zakaut number;
    v_teur_e_zakaut varchar(100);
    v_error_region  clob;
  
    cXSL xmltype := xmltype('<xsl:stylesheet version="1.0"  xmlns:xsl="http://www.w3.org/1999/XSL/Transform">' ||
                            '<xsl:output method="xml" indent="yes"/>' ||
                            '<xsl:template match="*">' ||
                            '  <xsl:element name="{local-name()}">' ||
                            '    <xsl:apply-templates select="node()|@*" />' ||
                            '  </xsl:element>' || '</xsl:template>' ||
                            '<xsl:template match="@*">' ||
                            '  <xsl:attribute name="{local-name()}"><xsl:value-of select="."/></xsl:attribute>' ||
                            '</xsl:template>' ||
                            '<xsl:template match="processing-instruction()|comment()">' ||
                            '  <xsl:copy>' ||
                            '    <xsl:apply-templates select="node()"/>' ||
                            '  </xsl:copy>' || '</xsl:template>   ' ||
                            '</xsl:stylesheet>');
    vXml xmltype;
  begin
    clear_err_tables;
    begin
    
      select xmltransform(xmltype(p_xml_str), cXSL) into vXml from dual;
    
      -- v_result := load_ld_ws(p_xml_str);
      delete from tbl_LD_WS;
      --pk_prm_utils.delete_bakasha_without_result(v_seq_bakasha);
      insert into tbl_LD_WS values (vXml);
    
    exception
      when others then
        dbms_output.put_line(Sqlerrm);
        return create_error_output(5, 'שגיאה במבנה XML', Sqlerrm);
    end;
    --insert data
    insert_xml_data(v_error_region);
  
    if v_error_region is not null then
    
      v_output := create_error_output(2,
                                      'שגיאה בשלב הקליטה',
                                      trim(v_error_region));
    
      /********************************************/
      /*       cancel all commands                */
      /*                                          */
      rollback;
      /*                                          */
      /*                                          */
      /********************************************/
      return v_output;
    end if;
  
    --calc data
    begin
      pk_convert_golmi_2_mechushav.main(v_seq_bakasha, 1);
    
      pk_zakaut.publc_insrt_ntuny_tik_mchshvim(v_seq_bakasha, 1, 1);
      pk_zakaut.internal_main(v_seq_bakasha, 1);
    
      select t.code_e_zakaut, t1.teur_e_zakaut
        into v_code_e_zakaut, v_teur_e_zakaut
        from netuney_tik_mechushavim t
        left join code_e_zakaut t1
          on t.code_e_zakaut = t1.code_e_zakaut
       where t.seq_bakasha = v_seq_bakasha
         and t.code_department = 1
         and t.mispar_misra = 0;
    
      if v_code_e_zakaut is not null then
        v_output := create_error_output(3,
                                        'שגיאה בשלב העיבוד',
                                        v_teur_e_zakaut);
        /********************************************/
        /*       cancel all commands                */
        /*                                          */
        rollback;
        /*                                          */
        /*                                          */
        /********************************************/
        return v_output;
      end if;
    
      insert_ws_calc_data(v_seq_bakasha);
    exception
      when others then
        v_output := create_error_output(3,
                                        'שגיאה בשלב העיבוד',
                                        sqlerrm);
      
        /********************************************/
        /*       cancel all commands                */
        /*                                          */
        rollback;
        /*                                          */
        /*                                          */
        /********************************************/
        return v_output;
      
    end;
    --create xml result
  
    begin
      select extractValue(value(e), '/InputId/RecordNumber') as "RecordNumber"
        into v_record_number
        from tbl_LD_WS x,
             table(xmlSequence(extract(xml_str, '/WsdlRequest/InputId'))) e;
    
      v_output := create_output(v_record_number);
    exception
      when others then
        v_output := create_error_output(4,
                                        'שגיאה בשלב יצירת הפלט',
                                        sqlerrm);
      
        /********************************************/
        /*       cancel all commands                */
        /*                                          */
        rollback;
        /*                                          */
        /*                                          */
        /********************************************/
        return v_output;
    end;
    --dbms_output.put_line(v_output);
  
    /********************************************/
    /*       cancel all commands                */
    /*                                          */
    rollback;
    /*                                          */
    /*                                          */
    /********************************************/
    return v_output;
  end;
  ----------------------------------------------------------------------------
  procedure insert_xml_data(p_error_region in out clob) is
    v_seq_ezor_ovdim        number;
    v_seq_bakasha           number := -1;
    v_seq_bakasha_previos   number;
    v_seq_poresh            number := -1;
    v_seq_darga_vderug      number := -1;
    v_seq_prisha            number := -1;
    v_record_number         number;
    v_ministry_code         number;
    v_birth_date            varchar2(10);
    v_death_date            varchar2(10);
    v_group_type            number;
    v_rate_type             number;
    v_rank_type             number;
    v_retirement_date       varchar2(10);
    v_retirement_clause     number;
    v_code_seif_prisha      number;
    v_discipline_act        number := null;
    v_seniority             number;
    v_absent_days           number;
    v_acquired_absent_days  number;
    v_retirement_disability number;
    v_retirement_from_date  varchar2(10);
    v_code_sug_bakasha      number;
    v_test                  nvarchar2(1000);
  
  begin
    --exists poresh?
    --begin
    select extractValue(value(e), '/InputId/RecordNumber') as "RecordNumber",
           extractValue(value(e), '/InputId/BirthDate') as "BirthDate",
           extractValue(value(e), '/InputId/DeathDate') as "DeathDate"
      into v_record_number, v_birth_date, v_death_date
      from tbl_LD_WS x,
           table(xmlSequence(extract(xml_str, '/WsdlRequest/InputId'))) e;
  
    select extractValue(value(e), '/PensionDetails/MinistryCode') as "MinistryCode",
           extractValue(value(e), '/PensionDetails/GroupType') as "GroupType",
           extractValue(value(e), '/PensionDetails/RetirementDate') as "RetirementDate",
           extractValue(value(e), '/PensionDetails/RetirementClause') as "RetirementClause",
           extractValue(value(e), '/PensionDetails/RateType') as "RateType",
           extractValue(value(e), '/PensionDetails/RankType') as "RankType",
           extractValue(value(e), '/PensionDetails/DisciplineAct') as "DisciplineAct",
           extractValue(value(e), '/PensionDetails/Seniority') as "Seniority",
           extractValue(value(e), '/PensionDetails/AbsentDays') as "AbsentDays",
           extractValue(value(e), '/PensionDetails/AcquiredAbsentDays') as "AcquiredAbsentDays"
      into v_ministry_code,
           v_group_type,
           v_retirement_date,
           v_retirement_clause,
           v_rate_type,
           v_rank_type,
           v_discipline_act,
           v_seniority,
           v_absent_days,
           v_acquired_absent_days
      from tbl_LD_WS x,
           table(xmlSequence(extract(xml_str, '/WsdlRequest/PensionDetails'))) e;
    begin
      select extractValue(value(e),
                          '/DisabilityDetails/RetirementDisability') as "RetirementDisability",
             extractValue(value(e), '/DisabilityDetails/RetirementFromDate') as "RetirementFromDate"
        into v_retirement_disability, v_retirement_from_date
        from tbl_LD_WS x,
             table(xmlSequence(extract(xml_str,
                                       '/WsdlRequest/DisabilityDetails'))) e;
    exception
      when no_data_found then
        null;
    end;
  
    begin
      select e.seq_ezor_ovdim
        into v_seq_ezor_ovdim
        from code_ezor_ovdim e
       where e.code_makor in (1, 2, 3)
         and e.code_ezor_ovdim = v_ministry_code
         and e.pail = 1;
    exception
      when no_data_found then
        p_error_region := 'error ministry code';
    end;
    v_seq_bakasha_previos := pk_load.Check_previos_bakasha(v_record_number,
                                                           v_seq_ezor_ovdim,
                                                           1);
  
    if v_seq_bakasha_previos is null then
      v_code_sug_bakasha := 1;
      begin
        select sum(t.porshim_seq)
          into v_seq_poresh
          from poresh t
         where t.mispar_zehut = v_record_number;
      
      exception
        when no_data_found then
          v_seq_poresh := -1;
      end;
    
      if v_seq_poresh is null then
        v_seq_poresh := -1;
        insert into poresh
          (mispar_zehut,
           porshim_seq,
           shem_prati,
           shem_mishpacha,
           taarich_leda,
           taarich_ptira)
        values
          (v_record_number,
           v_seq_poresh,
           'WS',
           'WS',
           to_date(v_birth_date, 'yyyy-mm-dd'),
           to_date(v_death_date, 'yyyy-mm-dd')) log errors into err_porshim reject limit unlimited;
      elsif v_death_date is not null then
        update poresh p
           set p.taarich_ptira = to_date(v_death_date, 'yyyy-mm-dd')
         where p.porshim_seq = v_seq_poresh;
      end if;
      insert into prisha
        (seq_prisha, seq_poresh, seq_ezor_ovdim)
      values
        (v_seq_prisha, v_seq_poresh, v_seq_ezor_ovdim) log errors into err_prisha reject limit unlimited;
    else
      v_code_sug_bakasha := 5;
      select p.seq_prisha, p.seq_poresh
        into v_seq_prisha, v_seq_poresh
        from bakasha b
        left join prisha p
          on b.seq_prisha = p.seq_prisha
       where b.seq_bakasha = v_seq_bakasha_previos;
    end if;
    insert into bakasha
      (seq_bakasha,
       seq_prisha,
       code_sug_bakasha,
       date_bakasha,
       code_source)
    values
      (v_seq_bakasha, v_seq_prisha, v_code_sug_bakasha, sysdate, 99) log errors into err_bakasha reject limit unlimited;
  
    /*   begin
      select e.code_seif_prisha
        into v_code_seif_prisha
        from code_seif_prisha e
       where instr(e.code_seif_markava, v_retirement_clause) > 0;
    exception
      when no_data_found then
        p_error_region := 'error Retirement Clause';
    end;*/
    insert into bakasha_regila
      (seq_bakasha,
       taarich_prisha,
       code_seif_prisha,
       vetek,
       is_din_mishmaati,
       nechut_achuz,
       nechut_taarich_hamigbala,
       such_yemey_headrut,
       such_yemey_headrut_shnirkshu)
    values
      (v_seq_bakasha,
       to_date(v_retirement_date, 'yyyy-mm-dd'),
       zero_to_null(v_retirement_clause),
       zero_to_null(v_seniority),
       zero_to_null(v_discipline_act),
       zero_to_null(v_retirement_disability),
       to_date(v_retirement_from_date, 'yyyy-mm-dd'),
       v_absent_days,
       v_acquired_absent_days) log errors into err_bakasha_regila reject limit unlimited;
  
    insert into darga_vederug_tik
      (seq_dargot_vederug_tik, seq_bakasha, code_derug, code_darga)
    values
      (v_seq_darga_vderug, v_seq_bakasha, v_rate_type, v_rank_type) log errors into err_darga_vederug_tik reject limit unlimited;
    --concat error table
    --  select from --tkufot golmi
    insert_tkufot(v_seq_bakasha, p_error_region);
    insert_out_service_tkufot(v_seq_bakasha);
    insert_army_tkufot(v_seq_bakasha);
  
    add_err_tables_to_log(p_error_region);
  
  end;
  -------------------------------------------------------------------------------------
  procedure insert_tkufot(p_seq_bakasha number, p_error_region in out clob) is
    v_seq_ezor_ovdim number;
    v_test           nvarchar2(10);
    l_xml            XMLTYPE;
  
  begin
    select t.xml_str into l_xml from tbl_ld_ws t;
    for r in (SELECT xt.*
                FROM XMLTABLE('WsdlRequest/WorkPeriodInService' PASSING
                              l_xml COLUMNS OfficeId VARCHAR2(4) PATH
                              'OfficeId',
                              PeriodType VARCHAR2(4) PATH 'PeriodType',
                              FromDate VARCHAR2(10) PATH 'FromDate',
                              ToDate VARCHAR2(10) PATH 'ToDate',
                              EmploymentType VARCHAR2(4) PATH
                              'EmploymentType',
                              Partiality VARCHAR2(5) PATH 'Partiality',
                              RightType VARCHAR2(4) PATH 'RightType',
                              Sequence VARCHAR2(4) PATH 'Sequence') xt) loop
      begin
        if r.OfficeId is not null then
          select e.seq_ezor_ovdim
            into v_seq_ezor_ovdim
            from code_ezor_ovdim e
           where e.code_makor in (1, 2, 3)
             and e.code_ezor_ovdim = r.OfficeId
             and e.pail = 1;
        end if;
      exception
        when no_data_found then
          p_error_region := 'error ministry code';
      end;
    
      insert into tkufot_avoda_golmi
        (seq_bakasha,
         seq_tkufot_avoda_golmi,
         taarich_me,
         taarich_ad,
         achuz_chelkyut,
         code_sugey_tkufot,
         code_sugey_zchuyot,
         code_sugey_haasaka,
         ezor_ovdim_be_tkufa)
      values
        (p_seq_bakasha,
         r.sequence * -1,
         to_date(r.fromdate, 'yyyy-mm-dd'),
         to_date(r.todate, 'yyyy-mm-dd'),
         r.partiality,
         r.periodtype,
         zero_to_null(r.righttype),
         zero_to_null(r.EmploymentType),
         v_seq_ezor_ovdim) log errors into err_tkufot_avoda_golmi reject limit unlimited;
    
    --dbms_output.put_line(r.OfficeId || r.Sequence);
    end loop;
  end;
  -------------------------------------------------------------------------------------
  procedure insert_army_tkufot(p_seq_bakasha number) is
    v_seq_ezor_ovdim number;
    v_test           nvarchar2(10);
    l_xml            XMLTYPE;
  
  begin
    select t.xml_str into l_xml from tbl_ld_ws t;
    begin
      for r in (SELECT xt.*
                  FROM XMLTABLE('WsdlRequest/WorkPeriodInArmy' PASSING l_xml
                                COLUMNS PeriodType VARCHAR2(4) PATH
                                'PeriodType',
                                FromDate VARCHAR2(10) PATH 'FromDate',
                                ToDate VARCHAR2(10) PATH 'ToDate',
                                EligibleDate VARCHAR2(10) PATH 'EligibleDate',
                                Sequence VARCHAR2(4) PATH 'Sequence') xt) loop
      
        insert into tkufot_sherut_tsvaii
          (seq_bakasha,
           seq_tkufot_sherut_tsvaii,
           taarich_me,
           taarich_ad,
           taarich_zchuyot,
           code_sug_sherut_tzaii)
        values
          (p_seq_bakasha,
           r.sequence * -1,
           to_date(r.fromdate, 'yyyy-mm-dd'),
           to_date(r.todate, 'yyyy-mm-dd'),
           to_date(r.EligibleDate, 'yyyy-mm-dd'),
           r.periodtype) log errors into err_tkufot_sherut_tsvaii reject limit unlimited;
      
      end loop;
    exception
      when no_data_found then
        null;
    end;
  end;
  -------------------------------------------------------------------------------------
  procedure insert_out_service_tkufot(p_seq_bakasha number) is
    v_seq_ezor_ovdim number;
    v_test           nvarchar2(10);
    l_xml            XMLTYPE;
    v_sum_peroids    number;
  begin
    select t.xml_str into l_xml from tbl_ld_ws t;
    begin
      for r in (SELECT xt.*
                  FROM XMLTABLE('WsdlRequest/WorkPeriodOutofService' PASSING
                                l_xml COLUMNS WorkType VARCHAR2(4) PATH
                                'WorkType',
                                FromDate VARCHAR2(10) PATH 'FromDate',
                                ToDate VARCHAR2(10) PATH 'ToDate',
                                AgreementDate VARCHAR2(10) PATH
                                'AgreementDate',
                                Sequence VARCHAR2(4) PATH 'Sequence') xt) loop
      
        insert into tkufot_michutz_lasharut
          (seq_bakasha,
           seq_tkufot_michutz_lasharut,
           taarich_me,
           taarich_ad,
           taarich_heskem,
           code_sug_makom_avoda)
        values
          (p_seq_bakasha,
           r.sequence * -1,
           to_date(r.fromdate, 'yyyy-mm-dd'),
           to_date(r.todate, 'yyyy-mm-dd'),
           to_date(r.AgreementDate, 'yyyy-mm-dd'),
           zero_to_null(r.WorkType)) log errors into err_tkufot_michutz_lasharut reject limit unlimited;
      
      end loop;
    
      select sum(months_between(t.taarich_ad + 1, t.taarich_me))
        into v_sum_peroids
        from tkufot_michutz_lasharut t
       where t.seq_bakasha = p_seq_bakasha;
    
      update netuney_tik_mechushavim t
         set t.chodeshim_mezkim_out_of_srv_y = floor(v_sum_peroids / 12),
             t.chodeshim_mezkim_out_of_srv_m = floor(mod(v_sum_peroids, 12)),
             t.chodeshim_mezkim_out_of_srv_d = round((v_sum_peroids -
                                                     floor(v_sum_peroids)) *
                                                     30.44)
       where t.seq_bakasha = p_seq_bakasha;
    exception
      when no_data_found then
        null;
    end;
  
  end;
  ---------------------------------------------------------------------------
  procedure Insert_tkufot_mechushav(p_taarich_me                  date,
                                    p_taarich_ad                  date,
                                    p_achuz_chelkyut              number,
                                    p_praklit                     number,
                                    p_haim_kana_zchuyot           number,
                                    p_code_sugey_tkufot           number,
                                    p_code_sugey_haasaka          number,
                                    p_code_sugey_zchuyot          number,
                                    p_seq_tkufot_avoda_mechushv   number,
                                    p_ezor_ovdim_be_tkufa         number,
                                    p_seq_tkufot_avoda_golmi      number,
                                    p_seq_bakasha                 number,
                                    p_seq_tkufot_michutz_lasharut number,
                                    p_seq_tkufot_sherut_tsvaii    number) is
    v_is_exist_same_row   number;
    v_ezor_ovdim_be_tkufa number;
  begin
    select count(*)
      into v_is_exist_same_row
      from tkufot_avoda_mechushv m
     where m.taarich_me = p_taarich_me
       and m.taarich_ad = p_taarich_ad
       and m.seq_bakasha = p_seq_bakasha
       and m.achuz_chelkyut = 1;
  
    if v_is_exist_same_row > 0 then
      return;
    end if;
  
    insert into tkufot_avoda_mechushv
      (taarich_me,
       taarich_ad,
       achuz_chelkyut,
       praklit,
       sach_chodeshim,
       haim_kana_zchuyot,
       code_sugey_tkufot,
       code_sugey_haasaka,
       code_sugey_zchuyot,
       seq_tkufot_avoda_mechushv,
       ezor_ovdim_be_tkufa,
       seq_tkufot_avoda_golmi,
       seq_bakasha,
       seq_tkufot_michutz_lasharut,
       seq_tkufot_sherut_tsvaii)
    values
      (p_taarich_me,
       p_taarich_ad,
       p_achuz_chelkyut,
       p_praklit,
       round(months_between(p_taarich_ad + 1, p_taarich_me), 2),
       p_haim_kana_zchuyot,
       p_code_sugey_tkufot,
       p_code_sugey_haasaka,
       p_code_sugey_zchuyot,
       p_seq_tkufot_avoda_mechushv,
       p_ezor_ovdim_be_tkufa,
       p_seq_tkufot_avoda_golmi,
       p_seq_bakasha,
       p_seq_tkufot_michutz_lasharut,
       p_seq_tkufot_sherut_tsvaii);
  
  end;
  --------------------------------------------------------------------------
  procedure insert_ws_calc_data(p_seq_bakasha number) is
    v_sum_peroids number;
    v_odef_months number;
  begin
    --keren peroids
    select sum(months_between(t.taarich_ad + 1, t.taarich_me))
      into v_sum_peroids
      from tkufot_avoda_mechushv t
     where t.seq_bakasha = p_seq_bakasha
       and t.code_sugey_zchuyot = 8;
  
    update netuney_tik_mechushavim t
       set t.Keren_Mezaka_Shana   = floor(v_sum_peroids / 12),
           t.keren_mezaka_chodesh = floor(mod(v_sum_peroids, 12)),
           t.keren_mezaka_yamim   = round((v_sum_peroids -
                                          floor(v_sum_peroids)) * 30.44)
     where t.seq_bakasha = p_seq_bakasha;
  
    --part odef between years and month
    /* update netuney_tik_mechushavim t
      set t.odef_sherut_chodashim = mod(nvl(t.odef_sherut_chodashim, 0), 12),
          t.odef_sherut_shanim    = floor(nvl(t.odef_sherut_chodashim, 0) / 12)
    where t.seq_bakasha = p_seq_bakasha;*/
    select sum(months_between(t.taarich_ad + 1, t.taarich_me))
      into v_sum_peroids
      from tkufot_michutz_lasharut t
     where t.seq_bakasha = p_seq_bakasha;
  
    update netuney_tik_mechushavim t
       set t.chodeshim_mezkim_out_of_srv_y = floor(v_sum_peroids / 12),
           t.chodeshim_mezkim_out_of_srv_m = floor(mod(v_sum_peroids, 12)),
           t.chodeshim_mezkim_out_of_srv_d = round((v_sum_peroids -
                                                   floor(v_sum_peroids)) *
                                                   30.44)
     where t.seq_bakasha = p_seq_bakasha;
  end;

  ---------------------------------------------------------------------------
  function create_output(p_id_number number) return clob is
    v_record_id                   clob;
    v_calc_peroids                clob;
    v_result                      clob;
    v_output                      clob;
    v_achuz_kizba_kafuf_chelkiyut number;
    v_chelkiyut_lefi_sherut       number;
  begin
    SELECT XMLELEMENT("OutputId", XMLELEMENT("IdentityNumber", p_id_number), XMLELEMENT("ErrorType", nvl(t.code_e_zakaut, 0)))
           .getclobval() AS ID_Record
      into v_record_id
      FROM netuney_tik_mechushavim t
     where t.seq_bakasha = -1
       and t.code_department = 1
       and t.mispar_misra = 0;
  
    SELECT XMLELEMENT("Results", XMLELEMENT("RetirementType", t.code_group_prisha),
           
           XMLELEMENT("TotalMonths", nvl(t.tkufa_mezaka_sherut, 0) /* - nvl(t.chodeshim_mezkim_out_of_srv_m, 0)*/),
           
           XMLELEMENT("NonEntitlingMonths", nvl(t.tkufa_lo_mezaka_sherut, 0)),
           
           XMLELEMENT("Percentage", get_achuz_kizba_lefi_shert(t.achuz_kizba_kafuf_chelkiyut, t.chelkiyut_meshuklelet_sherut)),
           
           XMLELEMENT("Partiality", /*get_chelkiyut_lefi_shert(t.achuz_kizba_kafuf_chelkiyut,*/ t.chelkiyut_meshuklelet_sherut /*)*/),
           
           XMLELEMENT("PercentagePartial", round(get_achuz_kizba_lefi_shert(t.achuz_kizba_kafuf_chelkiyut, t.chelkiyut_meshuklelet_sherut) * get_chelkiyut_lefi_shert(t.achuz_kizba_kafuf_chelkiyut, t.chelkiyut_meshuklelet_sherut), 2)),
           
           XMLELEMENT("DisabilityPercentage", nvl(achuz_kizba_nechut, 0)),
           
           XMLELEMENT("DisabilityPartiality", nvl(t.chelkiut_lefi_nechut, 0)),
           
           XMLELEMENT("YearCompensation", floor(nvl(t.odef_sherut_chodashim, 0) / 12)),
           
           XMLELEMENT("MonthCompensation", mod(nvl(t.odef_sherut_chodashim, 0), 12)),
           
           XMLELEMENT("DayCompensation", mod(nvl(t.odef_sherut_yamim, 0), 12)),
           
           XMLELEMENT("YearsKeren", nvl(t.keren_mezaka_shana, 0)),
           
           XMLELEMENT("MonthsKeren", nvl(t.keren_mezaka_chodesh, 0)),
           
           XMLELEMENT("DaysKeren", nvl(t.keren_mezaka_yamim, 0)),
           
           XMLELEMENT("YearsOutofService", nvl(floor(nvl(t.chodeshim_mezkim_out_of_srv_m, 0) / 12), 0)),
           
           XMLELEMENT("MonthsOutofService", floor(mod(nvl(t.chodeshim_mezkim_out_of_srv_m, 0), 12))),
           
           XMLELEMENT("DaysOutofService", round(mod(nvl(t.chodeshim_mezkim_out_of_srv_m, 0), 1) * 30.44)),
           
           XMLELEMENT("EgibilityDate", t.date_start_zakaut), XMLELEMENT("AbsentDays", nvl(t1.such_yemey_headrut, 0)),
           
           XMLELEMENT("AcquiredAbsentDays", nvl(t1.such_yemey_headrut_shnirkshu, 0)),
           
           XMLELEMENT("GrantEgibility", nvl(t.is_zakai_lmaanak, 0)))
           .getClobVal() AS Result
      into v_result
      FROM netuney_tik_mechushavim t
      left join bakasha_regila t1
        on t.seq_bakasha = t1.seq_bakasha
     where t.seq_bakasha = -1
       and t.code_department = 1
       and t.mispar_misra = 0;
  
    SELECT XMLAGG(XMLELEMENT("WorkPeriodAll",
           
           XMLFOREST(e.seq_tkufot_avoda_mechushv as "Sequence", nvl(e.code_sugey_tkufot, 0) as "PeriodType", e.taarich_me as "FromDate", e.taarich_ad as "ToDate", nvl(e.code_sugey_haasaka, 0) as "EmploymentType", nvl(e.achuz_chelkyut, 0) as "Partial", nvl(convert_ezor_ovdim_to_mekava(e.ezor_ovdim_be_tkufa), 0) as "OfficeId", nvl(e.code_sugey_zchuyot, 0) as "RightType", round(months_between(e.taarich_ad + 1, e.taarich_me), 2) as "TotalMonths")))
           .getClobVal() as TotalMonths
      into v_calc_peroids
      FROM tkufot_avoda_mechushv e
     WHERE e.seq_bakasha = -1;
    v_output := '<?xml version="1.0" encoding="utf-8"?> <WsdlResponse xmlns="http://www.example.org/ProcessSchema">' ||
                create_error_output(0, '', '') || '<OutputResults>' ||
                v_record_id || v_result || v_calc_peroids ||
                '</OutputResults></WsdlResponse>';
    return v_output;
  
  end;
  ----------------------------------------------------------------------------------
  function get_achuz_kizba_lefi_shert(p_achuz_kizba_kafuf_chelkiyut number,
                                      p_chelkiyut_lefi_sherut       number)
    return number is
  begin
    if p_achuz_kizba_kafuf_chelkiyut * p_chelkiyut_lefi_sherut >
       v_max_achuz_kizba then
      return v_max_achuz_kizba;
    else
      return nvl(p_achuz_kizba_kafuf_chelkiyut, 0);
    end if;
  end;
  ----------------------------------------------------------------------------------
  function get_chelkiyut_lefi_shert(p_achuz_kizba_kafuf_chelkiyut number,
                                    p_chelkiyut_lefi_sherut       number)
    return number is
  begin
    if p_achuz_kizba_kafuf_chelkiyut * p_chelkiyut_lefi_sherut >
       v_max_achuz_kizba then
      return 1;
    else
      return nvl(p_chelkiyut_lefi_sherut, 0);
    end if;
  end;
  ---------------------------------------------------------------------------------
  function convert_ezor_ovdim_to_mekava(v_seq_ezor_ovdim number)
    return number is
    v_code_ezor_ovdim_merkava number;
  begin
    begin
      select e.code_ezor_ovdim
        into v_code_ezor_ovdim_merkava
        from code_ezor_ovdim e
       where e.code_makor in (1, 2, 3)
         and e.seq_ezor_ovdim = v_seq_ezor_ovdim
         and e.pail = 1;
    exception
      when no_data_found then
        return null;
    end;
    return v_code_ezor_ovdim_merkava;
  end;
  ----------------------------------------------------------------------------------
  function load_ld_ws(p_xml_str clob) return varchar is
  begin
    insert into tbl_LD_WS values (sys.xmltype.createXML(p_xml_str));
  
  exception
    when others then
      return 'error in xml structure';
      return 'XML inserted';
  end;
  --------------------------------------------------------------------
  function zero_to_null(p_value number) return number is
  begin
    if p_value <> 0 then
      return p_value;
    else
      return null;
    end if;
  end;
  ----------------------------------------------------------
  procedure add_err_table(p_table_name varchar2) is
  
    type typ_num_list is table of number;
  
    v_num_list typ_num_list;
  
    type typ_var_list is table of varchar2(2000);
    v_rowid_list typ_var_list;
    v_var_list   typ_var_list;
  
    v_cmd varchar2(1000);
  
    v_field varchar2(1000);
    v_mesg  varchar2(2000);
  
    v_first_position  number;
    v_second_position number;
  
    v_is_exist_mesg_in_table number;
  
    v_search_condition_long long;
    v_columns               varchar2(1000);
  
    v_sql_get_value varchar2(4000);
    v_value         varchar2(4000);
    v_values        varchar2(4000);
  begin
    --get the errors from the table
    v_cmd := 'select rowid ,ora_err_number$,ora_err_mesg$ from ' ||
             p_table_name;
  
    execute immediate v_cmd bulk collect
      into v_rowid_list, v_num_list, v_var_list;
  
    for i in 1 .. v_num_list.count() loop
    
      select count(*)
        into v_is_exist_mesg_in_table
        from code_load_msg t
       where t.code_load_msg = v_num_list(i);
    
      if v_is_exist_mesg_in_table > 0 then
        -- when is exist mesg in table, get the translate mesg from the table
        v_mesg   := null;
        v_values := null;
        --get the field from the orginal mesg
        v_field := v_var_list(i);
      
        v_first_position  := instr(v_field, '(') + 1;
        v_second_position := instr(v_field, ')');
      
        --get only specific detailes, not general mesg
        v_field := substr(v_field,
                          v_first_position,
                          v_second_position - v_first_position);
      
        --remove schema name and table name
        v_field := substr(v_field, instr(v_field, '.', -1) + 1);
      
        v_field   := replace(v_field, '"');
        v_columns := null;
      
        -- get check constaint detailes
        if v_num_list(i) = 2290 then
          select t.SEARCH_CONDITION
            into v_search_condition_long
            from user_constraints t
           where t.CONSTRAINT_NAME = v_field;
        
          v_field := substr(v_search_condition_long, 1, 2000) || ' [' ||
                     v_field || ']';
        
          -- get foreign key and primary key detailes
        elsif v_num_list(i) = 2291 or v_num_list(i) = 1 then
          for r in (select t.column_name
                      from user_cons_columns t
                     where t.constraint_name = v_field) loop
            select decode(v_columns,
                          null,
                          r.column_name,
                          v_columns || ',' || r.column_name)
              into v_columns
              from dual;
          end loop;
          v_field := v_columns || ' [' || v_field || ']';
        
          --get field name when numeric error
        elsif v_num_list(i) = 01722 then
          v_field := pk_load_mimshak.get_numeric_error(v_rowid_list(i),
                                                       p_table_name);
          --get field name when date error
        elsif v_num_list(i) = 01840 or v_num_list(i) = 01847 or
              v_num_list(i) = 01858 then
          v_field := pk_load_mimshak.get_date_error(v_rowid_list(i),
                                                    p_table_name);
        
        end if;
      
      else
        v_mesg := v_var_list(i);
      end if;
    
      --Get column name (without other expression)
      for r in (select t.COLUMN_NAME
                  from user_tab_cols t
                 where t.TABLE_NAME = p_table_name
                   and lower(nvl(v_field, v_var_list(i))) like
                       '%' || lower(t.COLUMN_NAME) || '%') loop
        --Get value
        v_sql_get_value := 'select ' || r.column_name || ' from ' ||
                           p_table_name || ' where rowid = ''' ||
                           v_rowid_list(i) || '''';
        execute immediate v_sql_get_value
          into v_value;
      
        select v_values || decode(v_values, null, '', v_values || ',') ||
               v_value
          into v_values
          from dual;
      end loop;
    
    --save the edited error in table
    
    end loop;
  
  end;
  ----------------------------------------------------------
  procedure add_err_tables_to_log(p_error_log in out clob) is
  begin
    --Add to the report info about the error tables.
    Get_error_format_varchar('ERR_PORSHIM',
                             'porshim_seq',
                             -1,
                             null,
                             p_error_log);
    Get_error_format_varchar('ERR_BAKASHA_REGILA',
                             'seq_bakasha',
                             -1,
                             null,
                             p_error_log);
    Get_error_format_varchar('ERR_TKUFOT_AVODA_GOLMI',
                             'seq_bakasha',
                             -1,
                             'seq_tkufot_avoda_golmi',
                             p_error_log);
    Get_error_format_varchar('ERR_TKUFOT_MICHUTZ_LASHARUT',
                             'seq_bakasha',
                             -1,
                             'seq_tkufot_michutz_lasharut',
                             p_error_log);
    Get_error_format_varchar('ERR_TKUFOT_SHERUT_TSVAII',
                             'seq_bakasha',
                             -1,
                             'seq_tkufot_sherut_tsvaii',
                             p_error_log);
    Get_error_format_varchar('ERR_DARGA_VEDERUG_TIK',
                             'seq_bakasha',
                             -1,
                             null,
                             p_error_log);
    Get_error_format_varchar('ERR_PRISHA',
                             'seq_prisha',
                             -1,
                             null,
                             p_error_log);
    Get_error_format_varchar('ERR_BAKASHA',
                             'seq_bakasha',
                             -1,
                             null,
                             p_error_log);
  end;
  -----------------------------------------------
  procedure clear_err_tables is
  begin
    --Add to the report info about the error tables.
  
    delete from ERR_BAKASHA_REGILA where seq_bakasha = -1;
    delete from ERR_TKUFOT_AVODA_GOLMI where seq_bakasha = -1;
    delete from ERR_TKUFOT_MICHUTZ_LASHARUT where seq_bakasha = -1;
    delete from ERR_TKUFOT_SHERUT_TSVAII where seq_bakasha = -1;
    delete from ERR_DARGA_VEDERUG_TIK where seq_bakasha = -1;
    delete from ERR_BAKASHA where seq_bakasha = -1;
    delete from ERR_PRISHA where seq_prisha = -1;
    delete from ERR_PORSHIM where porshim_seq = -1;
    commit;
  end;
  -----------------------------------------------
  procedure Get_error_format_varchar(p_table           varchar2,
                                     p_column_pk_name  varchar2,
                                     p_column_pk_value varchar2,
                                     p_column_seq      varchar2,
                                     p_error_log       in out clob) is
    p_Query     clob;
    p_query_seq clob;
    l_sql_res   clob;
  begin
    p_Query := 'select string_agg(t.ORA_ERR_MESG$)from ' || p_table ||
               ' t where ' || p_column_pk_name || ' = ' ||
               p_column_pk_value;
  
    execute immediate p_Query
      into l_sql_res;
    if l_sql_res is not null then
      p_Query := 'select ''table: ' || p_table || '~''||' || case
                   when p_column_seq is null then
                   
                    'string_agg(t.ORA_ERR_MESG$)'
                   else
                    'string_agg(''line:''|| ' || p_column_seq ||
                    '||''~''||t.ORA_ERR_MESG$) '
                 end || ' from ' || p_table || ' t where ' || p_column_pk_name ||
                 ' = ' || p_column_pk_value;
      execute immediate p_Query
        into l_sql_res;
      p_error_log := trim(p_error_log) || trim(l_sql_res);
    end if;
  end;

  -----------------------------------------------
  procedure Get_error_format_varchar_1(p_table     varchar2,
                                       p_error_log in out clob) is
    -- Local variables here
    p_Query       clob;
    l_theCursor   INTEGER;
    l_columnValue varchar2(4000);
    l_columnName  clob;
    l_status      INTEGER;
    l_colCnt      NUMBER;
    rec_tab       DBMS_SQL.DESC_TAB;
    l_sql_res     clob;
  
    l_index number(2);
    s       clob;
    row_id  clob;
    TYPE fields_name_array IS VARRAY(10) OF varchar2(200);
    fields_name fields_name_array := fields_name_array(10);
  
  begin
  
    p_Query := ' select rowid, t.ORA_ERR_MESG$ from ' || p_table || ' t ';
    /*-- parse given query
      l_theCursor := dbms_sql.open_cursor;
      dbms_sql.parse(l_theCursor, p_Query, DBMS_SQL.NATIVE);
      l_status := dbms_sql.execute(l_theCursor);
      -- Get columns description
      dbms_sql.describe_columns(l_theCursor, l_colCnt, rec_tab);
      -- Get columns definition
      for i in 1 .. l_colCnt loop
        dbms_sql.define_column(l_theCursor, i, l_columnValue, 2000);
      end loop;
      -- Fetch new row from query
      while (dbms_sql.fetch_rows(l_theCursor) > 0) loop
        fields_name.delete;
        -- Write all column' s value for i in 1 .. l_colCnt loop dbms_sql.column_value(l_theCursor, i, l_columnValue);
    
        l_columnName := rec_tab(i).col_name;
    
        --Get the value from the ORA_ERR_MESG$ column
        if l_columnName = 'ROWID' then
          row_id := l_columnValue;
        elsif l_columnName = 'ORA_ERR_MESG$' then
    
          BEGIN
            select l_sql_res || m.translate_to_hebrew_error
              into l_sql_res
              from ld_translate_error_message m
             where m.code_error = substr(l_columnValue, 5, 5);
          exception
            WHEN OTHERS THEN
              l_sql_res := l_columnValue;
    
          end;
    
          --check constraint error
          if l_columnValue like 'ORA-02290%' then
    
            select t1.condition_translate
              into l_columnValue
              from user_constraints t
              left join ld_translate_constraint t1
                on t.table_name = t1.table_name
               and t.constraint_name = t1.constraint_name
             where l_columnValue like '%' || t.CONSTRAINT_NAME || '%';
    
            l_sql_res := l_sql_res || ': ' || l_columnValue;
    
            --constraint error
          elsif l_columnValue like 'ORA-02291%' then
            for r in (select t.column_name
                        from user_cons_columns t
                       where t.constraint_name =
                             regexp_substr(l_columnValue,
                                           '(\(PRM_SYSTEM\.)(.{0,100})(\))',
                                           1,
                                           1,
                                           'i',
                                           2)) loop
              fields_name.extend(1);
              --add the column name to the array
              if fields_name.count > 0 then
                l_index := 1;
              else
                l_index := fields_name.last + 1;
              end if;
              fields_name(l_index) := r.column_name;
            end loop;
            --numeric error
          elsif l_columnValue like 'ORA-01722%' then
            s := 'select pk_load_mimshak.get_numeric_error(rowid,''' ||
                 p_table || ''')
              from ' || p_table || ' where rowid =''' || row_id || '''';
            fields_name.extend(1);
            execute immediate s
              into fields_name(1);
            --date error
          elsif l_columnValue like 'ORA-01840%' then
            s := 'select pk_load_mimshak.get_date_error(rowid,''' || p_table || ''')
              from ' || p_table || ' where rowid =''' || row_id || '''';
            fields_name.extend(1);
            execute immediate s
              into fields_name(1);
    
          end if;
    
          l_sql_res := l_sql_res;
    
          if fields_name.count > 0 then
            l_sql_res := l_sql_res || 'בשדה: ';
            FOR i IN fields_name.FIRST .. fields_name.LAST LOOP
              l_sql_res := l_sql_res || fields_name(i) || ' ';
            END LOOP;
          end if;
    
        end if;
      end loop;
      --Get the column that its value is invalid
    end loop;
    dbms_sql.close_cursor(l_theCursor);
    p_error_log           := trim(p_error_log) || trim(l_sql_res);*/
  end;
  -----------------------------------------------------------------------------
  function create_error_output(p_error_code   number,
                               p_error_desc   varchar,
                               p_error_dtails clob) return clob is
    v_error_str clob;
  begin
    v_error_str := '<ResponseStatus>
                            <Response_Code>' ||
                   p_error_code ||
                   '</Response_Code>
                            <Response_Desc>' ||
                   trim(p_error_desc) ||
                   '</Response_Desc>
                            <Response_Details>' ||
                   trim(p_error_dtails) ||
                   '</Response_Details>
                  </ResponseStatus>';
    if nvl(p_error_code, 0) <> 0 then
      v_error_str := '<WsdlResponse xmlns="http://www.example.org/ProcessSchema">' ||
                     trim(v_error_str) || '</WsdlResponse>';
    end if;
    return v_error_str;
  end;
end;
/

create or replace package body prm_system_copy.pk_logist is
  ---------------------------------------
  function sug_prisha(p_code_sug_prisha number) return varchar2 is
  begin
    return case p_code_sug_prisha when 1 then 'ש' when 2 then 'נ' else null end;
  end;
  ---------------------------------------
  function Family_Status(v_code_min                  number,
                         v_orginal_matzav_mishpachti number) return varchar2 is
    v_Family_Status varchar2(100);
  begin
    v_Family_Status := case
                         when v_code_min = 1 and
                              v_orginal_matzav_mishpachti = 0 then
                          'רווק'
                         when v_code_min = 1 and
                              v_orginal_matzav_mishpachti = 1 then
                          'נשוי'
                         when v_code_min = 1 and
                              v_orginal_matzav_mishpachti = 2 then
                          'אלמן'
                         when v_code_min = 1 and
                              v_orginal_matzav_mishpachti = 3 then
                          'גרוש'
                         when v_code_min = 1 and
                              v_orginal_matzav_mishpachti = 4 then
                          'פרוד'
                         when v_code_min = 1 and
                              v_orginal_matzav_mishpachti = 6 then
                          'פוליגם'
                         when v_code_min = 1 and
                              v_orginal_matzav_mishpachti = 7 then
                          'בת זוג בברית הזוגיות'
                       
                         when v_code_min = 2 and
                              v_orginal_matzav_mishpachti = 0 then
                          'רווקה'
                         when v_code_min = 2 and
                              v_orginal_matzav_mishpachti = 1 then
                          'נשואה'
                         when v_code_min = 2 and
                              v_orginal_matzav_mishpachti = 2 then
                          'אלמנה'
                         when v_code_min = 2 and
                              v_orginal_matzav_mishpachti = 3 then
                          'גרושה'
                         when v_code_min = 2 and
                              v_orginal_matzav_mishpachti = 4 then
                          'פרוד'
                         when v_code_min = 2 and
                              v_orginal_matzav_mishpachti = 6 then
                          'פוליגם'
                         when v_code_min = 2 and
                              v_orginal_matzav_mishpachti = 7 then
                          'בן זוג בברית הזוגיות'
                         else
                          null
                       end;
    return varchar2_val(v_Family_Status);
  end;
  ---------------------------------------
  function Relation(v_code_min     number,
                    v_code_kirva   number,
                    v_haim_oved    number,
                    v_taarich_leda date) return varchar2 is
    v_age      number;
    v_Relation varchar2(100);
  begin
    v_age      := floor(months_between(sysdate, v_taarich_leda) / 12);
    v_Relation := case
                    when v_code_min = 1 and v_code_kirva = 1 then
                     'בן זוג'
                    when v_code_min = 1 and v_haim_oved = 0 then
                     'בת זוג שניה לא עובדת'
                    when v_code_min = 1 and v_haim_oved = 1 then
                     'בת זוג שניה עובדת'
                  
                    when v_code_min = 2 and v_code_kirva = 1 and
                         v_haim_oved = 0 then
                     'בת זוג לא עובדת'
                    when v_code_min = 2 and v_code_kirva = 1 and
                         v_haim_oved = 1 then
                     'בת זוג עובדת'
                    when v_code_min = 2 and v_code_kirva = 14 then
                     'ידועה בצבור'
                    when v_code_min = 2 then
                     'מפרנסת יחידה'
                  
                    when v_code_kirva = 2 and v_age < 12 then
                     'ילד עד גיל 12'
                    when v_code_kirva = 2 and v_age < 18 then
                     'ילד עד גיל 18'
                    when v_code_kirva = 2 and v_age >= 18 and v_age < 25 then
                     'ילד נכה 18 עד 25'
                    when v_code_kirva = 2 then
                     'ילד (לא לחשב)'
                    when v_code_kirva = 2 then
                     'תלוי אחר'
                  
                    when v_code_kirva = 9 and v_age >= 25 then
                     'ילד נכה מעל גיל 25'
                    else
                     null
                  end;
    return v_Relation;
  end;
  ---------------------------------------
  function Relation_To_Dead(v_code_kirva number, v_code_min number)
    return varchar2 is
    v_Relation_To_Dead varchar2(100);
  begin
    v_Relation_To_Dead := case
                            when v_code_kirva = 1 and v_code_min = 1 then
                             'בעל'
                            when v_code_kirva = 2 and v_code_min = 1 then
                             'בן'
                            when v_code_kirva = 3 and v_code_min = 1 then
                             'אח'
                            when v_code_kirva = 4 and v_code_min = 1 then
                             'גיס '
                            when v_code_kirva = 5 and v_code_min = 1 then
                             'דוד  ???'
                            when v_code_kirva = 6 and v_code_min = 1 then
                             'אחיין ????'
                            when v_code_kirva = 7 and v_code_min = 1 then
                             'חם'
                            when v_code_kirva = 8 and v_code_min = 1 then
                             'חתן ????'
                            when v_code_kirva = 9 and v_code_min = 1 then
                             'נכד'
                            when v_code_kirva = 10 and v_code_min = 1 then
                             'גרוש'
                            when v_code_kirva = 11 and v_code_min = 1 then
                             'הורה'
                            when v_code_kirva = 12 and v_code_min = 1 then
                             'שגוי'
                            when v_code_kirva = 13 and v_code_min = 1 then
                             'בן זוג פרוד ????'
                            when v_code_kirva = 14 and v_code_min = 1 then
                             'ידוע בצבור'
                            when v_code_kirva = 20 and v_code_min = 1 then
                             'סב'
                            when v_code_kirva = 1 and v_code_min = 2 then
                             'אישה'
                            when v_code_kirva = 2 and v_code_min = 2 then
                             'בת'
                            when v_code_kirva = 3 and v_code_min = 2 then
                             'אחות'
                            when v_code_kirva = 4 and v_code_min = 2 then
                             'גיסה'
                            when v_code_kirva = 5 and v_code_min = 2 then
                             'דודה ????'
                            when v_code_kirva = 6 and v_code_min = 2 then
                             'אחיינית ???'
                            when v_code_kirva = 7 and v_code_min = 2 then
                             'חמה'
                            when v_code_kirva = 8 and v_code_min = 2 then
                             'כלה ????'
                            when v_code_kirva = 9 and v_code_min = 2 then
                             'נכדה'
                            when v_code_kirva = 10 and v_code_min = 2 then
                             'גרושה'
                            when v_code_kirva = 11 and v_code_min = 2 then
                             'שגוי'
                            when v_code_kirva = 12 and v_code_min = 2 then
                             'הורה'
                            when v_code_kirva = 13 and v_code_min = 2 then
                             'בת זוג פרודה ???'
                            when v_code_kirva = 14 and v_code_min = 2 then
                             'ידועה בצבור'
                            else
                             null
                          end;
    return v_Relation_To_Dead;
  end;
  ---------------------------------------
  function Date_val(v_date date) return varchar2 is
  begin
    return to_char(nvl(v_date, to_date('1850-01-01', 'yyyy-mm-dd')),
                   'yyyy-mm-dd');
  end;
  ---------------------------------------
  function varchar2_val(v_varchar2 varchar2) return varchar2 is
    final_v varchar2(1000);
  begin
    select reverse(v_varchar2) into final_v from dual;
    return final_v;
  end;
  ---------------------------------------
end;
/

create or replace package body prm_system_copy.pk_mlm_salary is
  --------------------------------------------------------
  procedure update_vetek_detail(p_seq                number,
                                p_seq_bakasha        number,
                                p_seq_netuney_sachar number) is
  begin
    for r in (select t.*
                from ld_mlm_salary t
               where t.seq_ld_mlm_salary = p_seq) loop
    
      --regular_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         1,
                                         r.regular_seniority / 100,
                                         p_seq_netuney_sachar);
      --m_a_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         3,
                                         r.m_a_seniority / 100,
                                         p_seq_netuney_sachar);
      --zahal_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         2,
                                         r.zahal_seniority / 100,
                                         p_seq_netuney_sachar);
      --national_service_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         4,
                                         r.national_service_seniority / 100,
                                         p_seq_netuney_sachar);
      --maslul_nimratz_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         33,
                                         r.maslul_nimratz_seniority / 100,
                                         p_seq_netuney_sachar);
      --bkmm_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         5,
                                         r.bkmm_seniority / 100,
                                         p_seq_netuney_sachar);
      --nurses_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         34,
                                         r.nurses_seniority / 100,
                                         p_seq_netuney_sachar);
      --salary_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         6,
                                         r.salary_seniority / 100,
                                         p_seq_netuney_sachar);
    end loop;
  end;
  --------------------------------------------------------
  procedure update_tosafot(p_seq_ld_mlm_salary  number,
                           p_seq_netuney_sachar number) is
    v_addition_type          number;
    v_sum                    number;
    v_quantity               number;
    v_is_exist_addition_type number;
  
  begin
    --Loop over all additions
    for i in 1 .. 20 loop
      execute immediate 'SELECT addition_type_' || to_char(i) || ', sum_' ||
                        to_char(i) || ', quantity_' || to_char(i) ||
                        ' FROM ld_mlm_salary where seq_ld_mlm_salary = ' ||
                        to_char(p_seq_ld_mlm_salary)
        into v_addition_type, v_sum, v_quantity;
    
      if v_addition_type <> 0 then
      
        select count(*)
          into v_is_exist_addition_type
          from code_semel_tosefet t
         where t.code_semel_tosefet = v_addition_type;
      
        if v_is_exist_addition_type = 0 then
          pk_salary_base.code_addition_not_exist(v_addition_type,
                                                 p_seq_netuney_sachar);
          --Continue to the next addition
          continue;
        end if;
      
        --Insert to tosefot table
        insert into tosefot
          (seq_tosefot,
           seq_netuney_sachar,
           code_semel_tosefet,
           sum,
           percent,
           amount,
           date_update,
           user_update)
        values
          (tosefot_seq.nextval,
           p_seq_netuney_sachar,
           v_addition_type,
           v_sum / 100,
           100,
           v_quantity / 100,
           sysdate,
           0);
      else
        --Stop the loop
        exit;
      end if;
    end loop;
  end;
  --------------------------------------------------------
  function update_netuney_sachar(p_seq_ld_mlm_salary       number,
                                 p_seq_bakasha_for_compare number,
                                 p_seq_bakasha_for_insert  number)
    return number is
    v_seq_netuney_sachar number;
    v_is_get_new_salary  number;
    v_date_start_zakaut  date;
  begin
    v_is_get_new_salary := 0;
    for r in (select t.*,
                     d.code_derug,
                     d.code_darga,
                     case t.type_record
                       when '60' then
                        2
                       when '02' then
                        14
                       else
                        1
                     end as code_sug_maskoret,
                     t.salary / 100 salary_N,
                     t.base_salary / 100 base_salary_N,
                     t.recuperation_1_12 / 100 recuperation_1_12_N,
                     t.closing_1_12 / 100 closing_1_12_N,
                     t.salary_161_form / 100 salary_161_form_N,
                     decode(t.job_number, 0, 0, 1) job_number_N
                from ld_mlm_salary t
              --join to code_darge in order to check that we have the codes
              --and when the codes is not exist, set null.
                left join code_darga d
                  on t.rate = d.code_derug
                 and t.rank = d.code_darga
               where t.seq_ld_mlm_salary = p_seq_ld_mlm_salary) loop
    
      if v_is_get_new_salary = 0 then
        v_is_get_new_salary := pk_salary_base.Before_insert_salary_data(p_seq_bakasha_for_compare,
                                                                        p_seq_bakasha_for_insert,
                                                                        r.job_number_n,
                                                                        r.code_sug_maskoret,
                                                                        r.salary_n,
                                                                        to_number(r.recuperation_days),
                                                                        r.closing_1_12_n,
                                                                        to_number(r.closing_level),
                                                                        to_number(r.yovel_grant_eligible));
      
      end if;
      v_seq_netuney_sachar := netuney_sachar_seq.nextval;
      v_date_start_zakaut  := pk_salary_base.get_start_zakaut(p_seq_bakasha_for_compare);
    
      --update netuney_sachar
      insert into netuney_sachar
        (seq_netuney_sachar,
         seq_bakasha,
         mispar_misra,
         code_sug_maskoret,
         code_derug,
         code_darga,
         maskoret_kovaat,
         havraa_days,
         sum_havraa,
         sum_bigud,
         ramat_bigud,
         is_maanak_yovel,
         schar_ysod,
         kovaat_161,
         date_update,
         user_update,
         from_date)
      values
        (v_seq_netuney_sachar,
         p_seq_bakasha_for_insert,
         r.job_number_N,
         r.code_sug_maskoret,
         r.code_derug,
         r.code_darga,
         r.salary_n,
         r.recuperation_days,
         r.recuperation_1_12_n,
         r.closing_1_12_n,
         r.closing_level,
         r.yovel_grant_eligible,
         r.base_salary_N,
         r.salary_161_form_n,
         sysdate,
         0,
         v_date_start_zakaut);
    end loop;
  
    update_tosafot(p_seq_ld_mlm_salary, v_seq_netuney_sachar);
  
    update_vetek_detail(p_seq_ld_mlm_salary,
                        p_seq_bakasha_for_insert,
                        v_seq_netuney_sachar);
  
    return v_is_get_new_salary;
  end;

  -----------------------------------------------------
  procedure load_by_id(p_ld_protocol     number,
                       p_identity_number varchar2,
                       p_office          varchar2) is
    v_seq_bakasha number;
  begin
    for r in (select *
                from table(get_mlm_salary_array()) t2
               where t2.identity_number = p_identity_number
                 and t2.office = p_office) loop
      pk_salary_base.load_managment_id(p_ld_protocol,
                                       r.seq_ld_mlm_salary,
                                       null,
                                       r.identity_number,
                                       r.office,
                                       'pk_mlm_salary');
    
    end loop;
  
    select max(b.seq_bakasha)
      into v_seq_bakasha
      from ld_mlm_salary l
      left join ld_salary_base b
        on l.seq_ld_mlm_salary = b.seq_ld_mlm_salary
     where l.identity_number = p_identity_number
       and l.office = p_office;
  
    pk_salary_base.manage_actions(p_ld_protocol, v_seq_bakasha);
  
  end;

  --------------------------------------------------------
  function update_sachar_for_bakasha(p_seq_bakasha number) return number is
    v_result      number;
    v_seq_bakasha number;
  begin
  
    for r in (select distinct s.identity_number, s.office
                from v_bakasha v
                left join code_ezor_ovdim c
                  on v.seq_ezor_ovdim = c.seq_ezor_ovdim
                left join ld_mlm_salary s
                  on s.identity_number = to_char(v.MISPAR_ZEHUT)
                 and s.office = to_char(c.code_misrad_maskret)
               where v.SEQ_BAKASHA = p_seq_bakasha) loop
    
      if r.identity_number is null then
        return 0;
      end if;
    
      --load by id      
      load_by_id(null, r.identity_number, r.office);
    
    end loop;
    return 1;
  
  end;
  -------------------------------------------------------
  function get_mlm_salary_array return mlm_salary_type_Array
    pipelined is
  begin
    for r in (select a.seq_ld_mlm_salary, a.identity_number, a.office
                from (select t.*,
                             l.code_status_get,
                             --Get the last load date for every id
                             first_value(t.load_date) over(partition by t.identity_number, t.office order by t.load_date desc) max_load_date,
                             first_value(t.seq_ld_mlm_salary) over(partition by t.identity_number order by t.seq_ld_mlm_salary desc) max_seq
                        from ld_mlm_salary t
                        left join ld_salary_base l
                          on t.seq_ld_mlm_salary = l.seq_ld_mlm_salary
                      
                      --where t.identity_number like '%16844920%'
                      ) a
              --Filer: get the last rows for every id
               where trunc(a.load_date) = trunc(a.max_load_date)
                 and nvl(a.code_status_get, 0) in (0, 3)
              --  and a.seq_ld_mlm_salary = trunc(a.max_seq)
              ) loop
      pipe row(mlm_salary_type(r.seq_ld_mlm_salary,
                               r.identity_number,
                               r.office));
    end loop;
  end;
  --------------------------------------------------------
  function main_mlm(p_ld_protocol number) return clob is
  
  begin
    for r1 in (select distinct t.identity_number, t.office
                 from table(get_mlm_salary_array()) t) loop
      --load by id      
      load_by_id(p_ld_protocol, r1.identity_number, r1.office);
    
    end loop;
  
    return pk_salary_base.get_report(p_ld_protocol);
  end;
  ---------------------------------------- ----------------
end;
/

create or replace package body prm_system_copy.pk_mlm_salary_196 is
  --------------------------------------------------------
  procedure update_vetek_detail(p_seq                number,
                                p_seq_bakasha        number,
                                p_seq_netuney_sachar number) is
  begin
    for r in (select t.*
                from ld_mlm_salary t
               where t.seq_ld_mlm_salary = p_seq) loop
    
      --regular_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         1,
                                         r.regular_seniority / 100,
                                         p_seq_netuney_sachar);
      --m_a_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         3,
                                         r.m_a_seniority / 100,
                                         p_seq_netuney_sachar);
      --zahal_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         2,
                                         r.zahal_seniority / 100,
                                         p_seq_netuney_sachar);
      --national_service_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         4,
                                         r.national_service_seniority / 100,
                                         p_seq_netuney_sachar);
      --maslul_nimratz_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         33,
                                         r.maslul_nimratz_seniority / 100,
                                         p_seq_netuney_sachar);
      --bkmm_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         5,
                                         r.bkmm_seniority / 100,
                                         p_seq_netuney_sachar);
      --nurses_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         34,
                                         r.nurses_seniority / 100,
                                         p_seq_netuney_sachar);
      --salary_seniority
      pk_salary_base.insert_vetek_detail(p_seq_bakasha,
                                         6,
                                         r.salary_seniority / 100,
                                         p_seq_netuney_sachar);
    end loop;
  end;
  --------------------------------------------------------
  procedure update_tosafot(p_seq_ld_mlm_salary  number,
                           p_seq_netuney_sachar number) is
    v_addition_type          number;
    v_sum                    number;
    v_quantity               number;
    v_is_exist_addition_type number;
  
  begin
    --Loop over all additions
    for i in 1 .. 20 loop
      execute immediate 'SELECT addition_type_' || to_char(i) || ', sum_' ||
                        to_char(i) || ', quantity_' || to_char(i) ||
                        ' FROM ld_mlm_salary where seq_ld_mlm_salary = ' ||
                        to_char(p_seq_ld_mlm_salary)
        into v_addition_type, v_sum, v_quantity;
    
      if v_addition_type <> 0 then
      
        select count(*)
          into v_is_exist_addition_type
          from code_semel_tosefet t
         where t.code_semel_tosefet = v_addition_type;
      
        if v_is_exist_addition_type = 0 then
          pk_salary_base.code_addition_not_exist(v_addition_type,
                                                 p_seq_netuney_sachar);
          --Continue to the next addition
          continue;
        end if;
      
        --Insert to tosefot table
        insert into tosefot
          (seq_tosefot,
           seq_netuney_sachar,
           code_semel_tosefet,
           sum,
           percent,
           amount,
           date_update,
           user_update)
        values
          (tosefot_seq.nextval,
           p_seq_netuney_sachar,
           v_addition_type,
           v_sum / 100,
           100,
           v_quantity / 100,
           sysdate,
           0);
      else
        --Stop the loop
        exit;
      end if;
    end loop;
  end;
  --------------------------------------------------------
  function update_netuney_sachar(p_seq_ld_mlm_salary       number,
                                 p_seq_bakasha_for_compare number,
                                 p_seq_bakasha_for_insert  number)
    return number is
    v_seq_netuney_sachar number;
    v_is_get_new_salary  number;
    v_date_start_zakaut  date;
  begin
    v_is_get_new_salary := 0;
    for r in (select t.*,
                     d.code_derug,
                     d.code_darga,
                     case t.type_record
                       when '60' then
                        2
                       when '02' then
                        14
                       else
                        1
                     end as code_sug_maskoret,
                     t.salary / 100 salary_N,
                     t.base_salary / 100 base_salary_N,
                     t.recuperation_1_12 / 100 recuperation_1_12_N,
                     t.closing_1_12 / 100 closing_1_12_N,
                     t.salary_161_form / 100 salary_161_form_N,
                     decode(t.job_number, 0, 0, 1) job_number_N
                from ld_mlm_salary t
              --join to code_darge in order to check that we have the codes
              --and when the codes is not exist, set null.
                left join code_darga d
                  on t.rate = d.code_derug
                 and t.rank = d.code_darga
               where t.seq_ld_mlm_salary = p_seq_ld_mlm_salary) loop
    
      if v_is_get_new_salary = 0 then
        v_is_get_new_salary := pk_salary_base.Before_insert_salary_data(p_seq_bakasha_for_compare,
                                                                        p_seq_bakasha_for_insert,
                                                                        r.job_number_n,
                                                                        r.code_sug_maskoret,
                                                                        r.salary_n,
                                                                        to_number(r.recuperation_days),
                                                                        r.closing_1_12_n,
                                                                        to_number(r.closing_level),
                                                                        to_number(r.yovel_grant_eligible));
      
      end if;
      v_seq_netuney_sachar := netuney_sachar_seq.nextval;
      v_date_start_zakaut  := pk_salary_base.get_start_zakaut(p_seq_bakasha_for_compare);
    
      --update netuney_sachar
      insert into netuney_sachar
        (seq_netuney_sachar,
         seq_bakasha,
         mispar_misra,
         code_sug_maskoret,
         code_derug,
         code_darga,
         maskoret_kovaat,
         havraa_days,
         sum_havraa,
         sum_bigud,
         ramat_bigud,
         is_maanak_yovel,
         schar_ysod,
         kovaat_161,
         date_update,
         user_update,
         from_date)
      values
        (v_seq_netuney_sachar,
         p_seq_bakasha_for_insert,
         r.job_number_N,
         r.code_sug_maskoret,
         r.code_derug,
         r.code_darga,
         r.salary_n,
         r.recuperation_days,
         r.recuperation_1_12_n,
         r.closing_1_12_n,
         r.closing_level,
         r.yovel_grant_eligible,
         r.base_salary_N,
         r.salary_161_form_n,
         sysdate,
         0,
         v_date_start_zakaut);
    end loop;
  
    update_tosafot(p_seq_ld_mlm_salary, v_seq_netuney_sachar);
  
    update_vetek_detail(p_seq_ld_mlm_salary,
                        p_seq_bakasha_for_insert,
                        v_seq_netuney_sachar);
  
    return v_is_get_new_salary;
  end;

  -----------------------------------------------------
  procedure load_by_id(p_ld_protocol     number,
                       p_identity_number varchar2,
                       p_office          varchar2) is
    v_seq_bakasha number;
  begin
    for r in (select *
                from table(get_mlm_salary_array()) t2
               where t2.identity_number = p_identity_number
                 and t2.office = p_office) loop
      pk_salary_base.load_managment_id(p_ld_protocol,
                                       r.seq_ld_mlm_salary,
                                       null,
                                       r.identity_number,
                                       r.office,
                                       'pk_mlm_salary');
    
    end loop;
  
    select max(b.seq_bakasha)
      into v_seq_bakasha
      from ld_mlm_salary l
      left join ld_salary_base b
        on l.seq_ld_mlm_salary = b.seq_ld_mlm_salary
     where l.identity_number = p_identity_number
       and l.office = p_office;
  
    pk_salary_base.manage_actions(p_ld_protocol, v_seq_bakasha);
  
  end;

  --------------------------------------------------------
  function update_sachar_for_bakasha(p_seq_bakasha number) return number is
    v_result      number;
    v_seq_bakasha number;
  begin
  
    for r in (select distinct s.identity_number, s.office
                from v_bakasha v
                left join code_ezor_ovdim c
                  on v.seq_ezor_ovdim = c.seq_ezor_ovdim
                left join ld_mlm_salary s
                  on s.identity_number = to_char(v.MISPAR_ZEHUT)
                 and s.office = to_char(c.code_misrad_maskret)
               where v.SEQ_BAKASHA = p_seq_bakasha) loop
    
      if r.identity_number is null then
        return 0;
      end if;
    
      --load by id      
      load_by_id(null, r.identity_number, r.office);
    
    end loop;
    return 1;
  
  end;
  -------------------------------------------------------
  function get_mlm_salary_array return mlm_salary_type_Array
    pipelined is
  begin
    for r in (select a.seq_ld_mlm_salary, a.identity_number, a.office
                from (select t.*,
                             l.code_status_get,
                             --Get the last load date for every id
                             first_value(t.load_date) over(partition by t.identity_number, t.office order by t.load_date desc) max_load_date,
                             first_value(t.seq_ld_mlm_salary) over(partition by t.identity_number order by t.seq_ld_mlm_salary desc) max_seq
                        from ld_mlm_salary t
                        left join ld_salary_base l
                          on t.seq_ld_mlm_salary = l.seq_ld_mlm_salary
                      
                      -- and t.identity_number like '%314415324%'
                      ) a
              --Filer: get the last rows for every id
               where trunc(a.load_date) = trunc(a.max_load_date)
                 and nvl(a.code_status_get, 0) in (0, 3)
                  --and office=196 and load_date > sysdate-1
              --  and a.seq_ld_mlm_salary = trunc(a.max_seq)
              ) loop
      pipe row(mlm_salary_type(r.seq_ld_mlm_salary,
                               r.identity_number,
                               r.office));
    end loop;
  end;
  --------------------------------------------------------
  function main_mlm(p_ld_protocol number) return clob is
  
  begin
    for r1 in (select distinct t.identity_number, t.office
                 from table(get_mlm_salary_array()) t) loop
      --load by id      
      load_by_id(p_ld_protocol, r1.identity_number, r1.office);
    
    end loop;
  
    return pk_salary_base.get_report(p_ld_protocol);
  end;
  ---------------------------------------- ----------------
end;
/

create or replace package body prm_system_copy.pk_participation_2_guff is
  ---------------------------------------------
  v_max_achuz_kizba             number := 70 / 100;
  v_minimal_age                 number := 0;
  v_max_achuz_kizba_sheer       number := 0;
  v_sum_achuz_kizba_sheer_chuka number := 0;
  ---------------------------------------------
  procedure insert_calc_data_2_table(p_seq_bakasha number) is
    v_sug_bakasha               number; --7
    v_seq_guf                   number := 0;
    v_maskoret_kizba            number := 0;
    v_makor_maskoret_kizba      number := 0;
    v_maskoret_tikra            number := 0;
    v_tkufot_medina             number := 0;
    v_tkufot_guf                number := 0;
    v_tkufot_overlapping_kizba  number := 0;
    v_tkufot_overlapping_maanak number := 0;
    v_tkufot_medina_final       number := 0;
    v_is_up_70                  number := 0;
    v_is_complete_salary        number := 0;
    v_kizba_tashlum             number := 0;
    v_is_zakay_maanak           number := 0;
    v_months_extra              number := 0;
    v_achuz_pizuy_medina        number := 0; --7
    v_months_pizuy_guf          number := 0;
    v_schum_pizuy_guf           number := 0;
    v_schum_maanak              number := 0;
    v_achuz_medina_final        number; --7
    v_achuz_medina_fixed        number; --7
    v_achuz_medina_yachasi      number; --7
    v_achuz_guf_final           number; --7
    v_achuz_guf_fixed           number; --7
    v_achuz_guf_yachasi         number; --7
    v_seq_participation_2_guf   number;
    v_seq_ezor_ovdim            number;
    --to calc_ntuny_tik_mchshvim_guf, is not used
    v_chelkyut_zvura_guf number;
    --to calc_ntuny_tik_mchshvim_guf, is not used
    v_achuz_kizba_guf number;
    --to Get_data_for_medina_and_guf, is not used
    v_temp_schum_kizba_medina number;
    --to Get_data_for_medina_and_guf, is not used
    v_temp_schum_kizba_guf number;
    --to Get_data_for_medina_and_guf, is not used
    v_maskoret_kovvat_medina number;
    --to Get_data_for_medina_and_guf, is not used
    v_maskoret_kovvat_guf number;
    --to Get_data_for_medina_and_guf, is not used
    v_achuz_kizba_medina number;
    v_chodshey_maanak    number := 0;
    v_schum_maanak_baguf number := 0;
    --v_minimal_age        number;
    v_poresh_age                 number;
    v_pniya_poresh_age           number;
    v_sub_seif_prisha            number;
    v_seif_prisha                number;
    v_group_prisha               number;
    v_code_e_zakaut              number;
    v_chinuch_mikzoa             number;
    v_chodshey_arai              number := 0;
    v_achuz_kizba_guf_lmaanak    number;
    v_achuz_kizba_hagdala        number := 0;
    v_is_sheerim_sheer_fake      number;
    v_is_zakai_maanak_fake       number;
    v_sum_achuz_kizba_sheer_fake number;
    v_code_e_zakaut_fake         number;
    v_chelkiyut                  number;
    v_achuz_kizba_sofi           number;
    v_date_start_zakaut          date;
    v_achuz_kizba_gil_60         number;
    v_code_yadani                number;
  
    v_percent_participate         number;
    v_seq_bakasha_zakaut_prev     number;
    v_code_bakasha_detail         number;
    v_achuz_kizba_medin_porprtion number := null;
  begin
  
    ---if chuka yadanit- return!!
    v_code_yadani := pk_zakaut.get_code_yadani(p_seq_bakasha);
    if nvl(v_code_yadani, 0) > 0 then
      return;
    end if;
  
    for par in (select p.achuz_arai, p.seq_participation
                  from participation p
                 where p.seq_bakasha = p_seq_bakasha
                   and p.achuz_arai is not null) loop
      update participation t
         set t.achuz_arai = null
       where t.seq_participation = par.seq_participation;
    end loop;
    ------------------------------------ Rivka 24/06/2020
    select b.code_bakasha_detail,p.seq_ezor_ovdim
      into v_code_bakasha_detail,v_seq_ezor_ovdim
      from bakasha b left join prisha p on b.seq_prisha=p.seq_prisha
     where b.seq_bakasha = p_seq_bakasha;
  
    --When 'transfer_money' - run 'zakaut' only
    if v_code_bakasha_detail in (26, 40) then
      v_seq_bakasha_zakaut_prev := pk_zakaut.exists_confirmed_bakasha(p_seq_bakasha,
                                                                      case
                                                                        when v_code_bakasha_detail = 26 then
                                                                         7
                                                                        else
                                                                         23
                                                                      end);
      if v_seq_bakasha_zakaut_prev is not null then
        for r in (select n.seq_netuney_tik_mechushavim
                    from netuney_tik_mechushavim n
                   where n.seq_bakasha = p_seq_bakasha) loop
          delete from netuney_tik_ben_mishpacha t
           where t.seq_netuney_tik_mechushavim =
                 r.seq_netuney_tik_mechushavim;
        end loop;
        delete from netuney_tik_mechushavim n
         where n.seq_bakasha = p_seq_bakasha;
        pk_prm_utils.duplicate_netuney_tik_mechushavim(p_seq_bakasha,
                                                       v_seq_bakasha_zakaut_prev,
                                                       1);
        update netuney_tik_mechushavim t
           set t.date_update = sysdate,
           t.code_e_zakaut=decode(t.code_e_zakaut,11,null,t.code_e_zakaut)
         where t.seq_bakasha = p_seq_bakasha
           and t.code_department = 2
           and t.mispar_misra = 0;
      else
        pk_zakaut.main(p_seq_bakasha);
      end if;
      return;
    end if;
    select b.code_sug_bakasha
      into v_sug_bakasha
      from bakasha b
     where b.seq_bakasha = p_seq_bakasha;
     --mayors
    if v_code_bakasha_detail in (47,48) then 
     calc_mayors(p_seq_bakasha,v_sug_bakasha); 
    return;
    end if;
    
    for par in (select p.achuz_arai, p.seq_participation
                  from participation p
                 where p.seq_bakasha = p_seq_bakasha
                   and p.achuz_arai is not null) loop
      update participation t
         set t.achuz_arai = null
       where t.seq_participation = par.seq_participation;
    end loop;
  
    -----------------------------------End Rivka 24/06/2020
    v_max_achuz_kizba             := 70 / 100;
    v_sum_achuz_kizba_sheer_chuka := 0;
  
    
  
    select *
      into v_poresh_age,
           v_seq_participation_2_guf,
           v_seq_guf,
           v_minimal_age,
           v_seif_prisha,
           v_sub_seif_prisha,
           v_group_prisha,
           v_chelkiyut,
           v_pniya_poresh_age
      from (select months_between(t.date_payment + 1, p.taarich_leda) / 12,
                   t.seq_participation,
                   t.seq_guf,
                   d.age,
                   r.code_seif_prisha,
                   r.code_sub_seif_prisha,
                   n.code_group_prisha,
                   n.chelkiyut_meshuklelet_sherut,
                   months_between(t.date_pniya + 1, p.taarich_leda) / 12
              from v_bakasha_last_status v
              left join poresh p
                on v.seq_porshim = p.porshim_seq
              left join bakasha_regila r
                on v.seq_bakasha = r.seq_bakasha
              left join participation t
                on t.seq_bakasha = v.seq_bakasha
               and (t.code_participation = 1 or v_sug_bakasha in (7, 23))
              left join ezor_ovdim_category e
                on t.seq_guf = e.seq_ezor_ovdim
               and e.code_sug_ezor_ovdim in (3, 5, 6)
              left join netuney_tik_mechushavim n
                on n.seq_bakasha = p_seq_bakasha
               and n.code_department = 2
              left join perm_decision_participation_to d
                on (d.code_sug_ezor_ovdim = e.code_sug_ezor_ovdim or
                   d.seq_ezor_ovdim = e.seq_ezor_ovdim)
               and d.code_min = p.code_min
               and d.code_sug_bakasha =
                   decode(v_sug_bakasha, 9, 8, v_sug_bakasha)
               and nvl(d.code_job, 0) = decode(r.chinuch_mikzoa, 911, 2, 0)
               and ((trunc(d.taarich_leda, 'year') =
                   trunc(p.taarich_leda, 'year') or
                   trunc(p.taarich_leda, 'year') <
                   to_date('01/01/1960', 'dd/mm/yyyy') and
                   d.taarich_leda is null) or d.code_sug_ezor_ovdim <> 5)
             where v.seq_bakasha = p_seq_bakasha
               and (t.date_answer is not null or v_sug_bakasha in (8, 9))
               and (t.code_participation in (2, 5) or
                   v_sug_bakasha not in (7, 23))
             order by d.seq_ezor_ovdim)
     where rownum = 1;
  
    if (v_poresh_age < v_minimal_age and nvl(v_sub_seif_prisha, 0) <> 991) and
       v_seif_prisha <> 315 and v_seif_prisha <> 215 and
       v_group_prisha <> 4 and
       (v_sub_seif_prisha <> 990 or v_sub_seif_prisha is null) then
    
      v_code_e_zakaut := 1;
    
    else
      if v_sug_bakasha in (7, 23) then
        pk_zakaut.main(p_seq_bakasha);      
      end if;
    
      if pk_zakaut.get_sheer_group(p_seq_bakasha) in (1, 2) then
        pk_zakaut.sheerim_calc_achuz_kizba(p_seq_bakasha,
                                           v_is_sheerim_sheer_fake,
                                           v_sum_achuz_kizba_sheer_fake,
                                           v_max_achuz_kizba_sheer,
                                           v_is_zakai_maanak_fake,
                                           v_code_e_zakaut_fake,
                                           0,
                                           null,
                                           v_sum_achuz_kizba_sheer_chuka);
      
        v_makor_maskoret_kizba := Get_makor_maskoret_kovat_kizba(p_seq_bakasha,
                                                               v_sug_bakasha,
                                                               0);
                                                               
        if is_municipal(p_seq_bakasha) = 1 or v_makor_maskoret_kizba = 2 or v_sug_bakasha = 23 then
          v_max_achuz_kizba := 40 / 100;
        end if;
        if v_seq_guf = 197 and v_sug_bakasha = 9 then 
          --rashut hanemelim-only 60%
          
           select max(t1.seq_bakasha)
            into v_seq_bakasha_zakaut_prev
            from v_bakasha_last_status t
            join v_bakasha_last_status t1
              on t.seq_prisha = t1.seq_prisha
             and t1.seq_bakasha < t.seq_bakasha
             and t1.code_sug_bakasha in( 1,8)
            where t.seq_bakasha = p_seq_bakasha
             and t1.code_action in(42, 98);   
                                                                      
           if v_seq_bakasha_zakaut_prev is not null then
            delete from netuney_tik_mechushavim n
             where n.seq_bakasha = p_seq_bakasha;
            pk_prm_utils.duplicate_netuney_tik_mechushavim(p_seq_bakasha,
                                                           v_seq_bakasha_zakaut_prev,
                                                           1);
            v_maskoret_kizba := Get_maskoret_kovvat_kizba(p_seq_bakasha,v_sug_bakasha,0);
            update netuney_tik_mechushavim t
               set t.date_update = sysdate,
                   t.achuz_kizba_sofi = t.achuz_kizba_sofi * v_sum_achuz_kizba_sheer_chuka / 100,
                   t.schum_kizba = v_maskoret_kizba * t.achuz_kizba_sofi / 100 * v_sum_achuz_kizba_sheer_chuka /100,
                   t.maskoret_kizba = v_maskoret_kizba
             where t.seq_bakasha = p_seq_bakasha
               and t.code_department = 2
               and t.mispar_misra = 0;
               return;
          end if;
        end if;
      end if;
      
      v_maskoret_kizba       := Get_maskoret_kovvat_kizba(p_seq_bakasha,
                                                          v_sug_bakasha,
                                                          0);
      v_maskoret_tikra       := Get_maskoret_kovvat_tikra(p_seq_bakasha,
                                                          v_sug_bakasha,
                                                          0);
    --tkufa medina
      select t1.tkufa_mezaka_sherut
        into v_tkufot_medina
        from netuney_tik_mechushavim t1
       where t1.seq_bakasha = p_seq_bakasha
         and t1.code_department = 2;
    
     -- tkufa guf 
      select sum(months_between(t.date_to + 1, t.date_from)) months
        into v_tkufot_guf
        from participation_tkufot t
        left join participation t1
          on t.seq_participation = t1.seq_participation
        left join ezor_ovdim_category t2
          on t1.seq_guf = t2.seq_ezor_ovdim
         and t2.code_sug_ezor_ovdim in (3, 5, 6)
       where t1.seq_bakasha = p_seq_bakasha
         and nvl(t.code_sug_tkufa, 0) <> 1
         and (t1.date_answer is not null or v_sug_bakasha in (8, 9));
    
      --overlap
      v_tkufot_overlapping_kizba := Get_overlapping_months(p_seq_bakasha,
                                                           v_sug_bakasha,
                                                           1);
    
      v_tkufot_medina_final := v_tkufot_medina - v_tkufot_overlapping_kizba;
    
      Get_data_for_medina(p_seq_bakasha,
                          v_sug_bakasha, --7
                          v_temp_schum_kizba_medina,
                          v_maskoret_kovvat_medina,
                          v_achuz_kizba_medina,
                          v_achuz_kizba_medin_porprtion,
                          1);
    
      Get_data_guf(p_seq_bakasha,
                   v_temp_schum_kizba_guf,
                   v_maskoret_kovvat_guf,
                   v_achuz_kizba_guf,
                   v_seq_guf,
                   v_chodshey_maanak,
                   v_schum_maanak_baguf,
                   0);
      v_is_up_70           := is_the_salary_up_70(p_seq_bakasha,
                                                  v_sug_bakasha, --7
                                                  0,
                                                  v_achuz_kizba_medina,
                                                  v_temp_schum_kizba_medina,
                                                  v_temp_schum_kizba_guf);
      v_is_complete_salary := is_salary_complete(v_seq_guf,
                                                 v_maskoret_kovvat_medina,
                                                 v_maskoret_kovvat_guf);
        --rashut nemelim    
    
      Get_final_achuz_kizba(p_seq_bakasha,
                            v_sug_bakasha,
                            v_achuz_medina_final,
                            v_achuz_medina_fixed,
                            v_achuz_medina_yachasi,
                            v_achuz_guf_final,
                            v_achuz_guf_fixed,
                            v_achuz_guf_yachasi,
                            v_tkufot_overlapping_kizba); --7 end
      v_achuz_medina_final   := round(v_achuz_medina_final, 2);
      v_achuz_medina_fixed   := round(v_achuz_medina_fixed, 2);
      v_achuz_medina_yachasi := round(v_achuz_medina_yachasi, 2);
    
      v_kizba_tashlum := Get_maskoret_kovvat_kizba(p_seq_bakasha,
                                                   v_sug_bakasha,
                                                   0) *
                         v_achuz_medina_final / 100;
      if is_municipal(p_seq_bakasha) = 1 then
        v_kizba_tashlum := v_kizba_tashlum * v_chelkiyut;
      end if;
           --sheerim muliple by sum achuz kizba sheer
   if v_sum_achuz_kizba_sheer_chuka <> 0 and
   (((v_sug_bakasha = 23 or v_max_achuz_kizba = 0.7) and is_municipal(p_seq_bakasha) = 0) or v_is_up_70 = 0) then
         
    if v_sug_bakasha = 9 and (v_max_achuz_kizba = 0.7 or v_is_up_70 = 0) then
        
        -- לגוף קרנות להגביל ל-40%
        if is_municipal(p_seq_bakasha) = 0 and (v_sum_achuz_kizba_sheer_chuka * v_achuz_medina_final / 100) > 40 then
            v_sum_achuz_kizba_sheer_chuka := (40 / v_achuz_medina_final) * 100; 
        end if;
        
        -- עדכון זה מתבצע תמיד אם נכנסנו לתנאי של סוג בקשה 9 (אחרי העדכון האפשרי של האחוז למעלה)
        v_achuz_medina_final := v_achuz_medina_final * (v_sum_achuz_kizba_sheer_chuka / 100);
        
    end if;
    
    -- עדכון הקצבה מתבצע בכל תרחיש בו נכנסנו לתנאי הראשי (בסוף כל התהליך)
    v_kizba_tashlum := v_kizba_tashlum * (v_sum_achuz_kizba_sheer_chuka / 100);
    
end if;
--הכפלה השתתפות באחוז שאר אם לא עובר 40 בעיריות
 if v_sug_bakasha = 23 and is_municipal(p_seq_bakasha) = 1 and v_is_up_70 = 0 then
        update participation p set p.achuz_guf_final = achuz_guf_final * (60 / 100)where p.seq_bakasha = p_seq_bakasha;
      end if;




   --achuz_kizba_gil_60
      if v_sug_bakasha = 7 then
        achuz_kizba_gil_60(p_seq_bakasha,
                           v_tkufot_overlapping_kizba / 6,
                           v_achuz_kizba_gil_60,
                           v_group_prisha);
      end if;
      --maanak- not in sheerim
      if v_sug_bakasha in (7, 8) then
        v_is_zakay_maanak := Is_zakai_lmaanak(p_seq_bakasha, v_sug_bakasha);
      
        v_tkufot_overlapping_maanak := Get_overlapping_months(p_seq_bakasha,
                                                              v_sug_bakasha,
                                                              0);
      end if;
      --maanak leguf only 3 months before gilprisha taknoni
      if v_is_zakay_maanak = 1 and
         (v_sug_bakasha = 7 or v_pniya_poresh_age > v_minimal_age - 0.25 or v_seq_ezor_ovdim=10153) then
        v_schum_maanak := Calc_schum_maanak(p_seq_bakasha,
                                            v_sug_bakasha, --7
                                            v_months_extra,
                                            v_achuz_pizuy_medina,
                                            v_months_pizuy_guf,
                                            v_schum_pizuy_guf);
      
      end if;
    
        
      if v_sug_bakasha = 7 and (v_is_zakay_maanak = 0 or v_schum_maanak = 0) then
        select sum(chodshey_pizuy)
          into v_months_extra
          from  (select * from v_mechushavim_2_curnt_and_prev t
         where t.current_seq_bakasha = p_seq_bakasha
           and t.seq_bakasha <> p_seq_bakasha
         order by t.seq_bakasha desc fetch first 1 rows only);
        
      end if;
      
    
      if v_tkufot_medina_final + nvl(v_tkufot_guf, 0) < case when
       v_seif_prisha = 215 then 60 else 120
       end and v_sug_bakasha in (7, 8, 9) --months
       then
        v_code_e_zakaut      := 3;
        v_kizba_tashlum      := 0;
        v_schum_maanak       := 0;
        v_is_up_70           := 0;
        v_is_complete_salary := 0;
        v_achuz_medina_final := 0;
        v_months_extra       := 0;
      
      elsif v_achuz_medina_final = 0 then
        v_code_e_zakaut := 2;
      end if;
    end if;
  
    select t.achuz_kizba_sofi, t.date_start_zakaut
      into v_achuz_kizba_sofi, v_date_start_zakaut
      from netuney_tik_mechushavim t
     where t.seq_bakasha = p_seq_bakasha
       and t.code_department = 2
       and t.mispar_misra = 0;
       
       
    if ((v_is_up_70 = 0 and is_municipal(p_seq_bakasha)=1)or v_seq_ezor_ovdim=10153) or v_sug_bakasha <> 23 then
      select round_percent_by_months(nvl(sum(t.achuz_meushar), 0))
        into v_achuz_kizba_hagdala
        from hagdala_nimuk t
       where t.seq_bakasha = p_seq_bakasha
         and t.code_hagdala_status_nimuk = 3;

      if v_sug_bakasha in (23, 9) then
        v_achuz_kizba_hagdala := v_achuz_kizba_hagdala *
                                 v_sum_achuz_kizba_sheer_chuka / 100;
      end if;
      if v_sug_bakasha = 8 then
        v_kizba_tashlum := v_kizba_tashlum + (Get_maskoret_kovvat_kizba(p_seq_bakasha,
                                                                        v_sug_bakasha,
                                                                        0) *
                           v_achuz_kizba_hagdala * 0.01);
      end if;
      if v_sug_bakasha = 9 then
        v_kizba_tashlum := v_kizba_tashlum + (Get_maskoret_kovvat_kizba(p_seq_bakasha,
                                                                        v_sug_bakasha,
                                                                        0) *
                           v_achuz_kizba_hagdala * 0.01);
      end if;
    end if;
    
     if v_is_up_70 = 0 and v_tkufot_overlapping_kizba = 0 and v_sug_bakasha = 23 and nvl(v_achuz_kizba_hagdala,0)=0 then
       v_achuz_medina_final := v_achuz_kizba_sofi;
     end if;
    
    
    
    --במידה ויש הפחתה , תאריך תחילת זכאות הוא המקסימלי מתאריכי התחולה בגופים
    if v_sug_bakasha in (7, 23) and
       v_achuz_kizba_sofi >
       round(v_achuz_medina_final + v_achuz_kizba_hagdala, 2) then
      select max(p.date_payment)
        into v_date_start_zakaut
        from participation p
       where p.seq_bakasha = p_seq_bakasha
         and p.date_answer is not null;
    end if;
  
    if v_sug_bakasha = 7 and
       v_achuz_medina_final =
       pk_zakaut.round_percent_by_months(v_achuz_medina_final) then
      v_achuz_kizba_sofi := pk_zakaut.round_percent_by_months(v_achuz_medina_final +
                                                              v_achuz_kizba_hagdala);
    else
      v_achuz_kizba_sofi := round(v_achuz_medina_final +
                                  v_achuz_kizba_hagdala,
                                  2);
    end if;
  
 --maanay yovel, only meguf' muncipial
    if v_sug_bakasha = 7 and
      is_municipal(p_seq_bakasha) = 1 then
  for r in (select t.seq_participation, 
       t.salary_maanak_yovel, 
       t.achuz_guf_final, 
       t.partial_period from participation t
    inner join ezor_ovdim_category e
    on t.seq_guf = e.seq_ezor_ovdim
    where t.seq_bakasha = p_seq_bakasha
    and e.code_sug_ezor_ovdim in (6)) loop
    if nvl(r.salary_maanak_yovel,0)>0 then
         update participation p
         set p.schum_maanak_yovel = p.salary_maanak_yovel * nvl(p.achuz_guf_final, 0) * nvl(p.partial_period, 0) * 0.6 * 0.01
         where p.seq_participation = r.seq_participation; 
         end if;        
         end loop;
      end if;


    merge into netuney_tik_mechushavim tt
    using dual
    on (seq_bakasha = p_seq_bakasha and code_department = 2 and mispar_misra = 0)
    when matched then
      update
         set maskoret_kizba        = v_maskoret_kizba,
             achuz_pizuy           = v_achuz_pizuy_medina,
             schum_kizba           = v_kizba_tashlum,
             schum_maanak_pizuy    = v_schum_maanak,
             TKUFA_OVERLAP_KIZBA   = v_tkufot_overlapping_kizba,
             TKUFA_OVERLAP_MAANAK  = v_tkufot_overlapping_maanak,
             is_salary_up_70       = v_is_up_70,
             is_complete_salary    = v_is_complete_salary,
             achuz_kizba_sofi      = v_achuz_kizba_sofi,
             chodshey_pizuy        = v_months_extra,
             date_update           = sysdate,
             MAKOR_MASKORET_KOVAAT = v_makor_maskoret_kizba,
             code_e_zakaut         = v_code_e_zakaut,
             achuz_kizba_fixed     = v_achuz_medina_fixed, --7
             achuz_kizba_yechasi   = v_achuz_medina_yachasi, --7
             odef_sherut_chodashim = floor(v_months_extra),
             odef_sherut_yamim     = round(mod(v_months_extra, 1) * 30.44, 2),
             date_start_zakaut     = v_date_start_zakaut,
             achuz_kizba_gil_60    = v_achuz_kizba_gil_60
      
    
    when not matched then
      insert
        (seq_netuney_tik_mechushavim,
         seq_bakasha,
         code_department,
         maskoret_kizba,
         achuz_pizuy,
         schum_kizba,
         schum_maanak_pizuy,
         TKUFA_OVERLAP_KIZBA,
         is_salary_up_70,
         is_complete_salary,
         achuz_kizba_sofi,
         chodshey_pizuy,
         TKUFA_OVERLAP_MAANAK,
         date_update,
         MAKOR_MASKORET_KOVAAT,
         code_e_zakaut,
         achuz_kizba_fixed, --7
         achuz_kizba_yechasi,
         mispar_misra,
         date_start_zakaut,
         achuz_kizba_gil_60) --7
      values
        (netuney_tik_mechushavim_seq.nextval,
         p_seq_bakasha,
         2,
         v_maskoret_kizba,
         v_achuz_pizuy_medina,
         v_kizba_tashlum,
         v_schum_maanak,
         v_tkufot_overlapping_kizba,
         v_is_up_70,
         v_is_complete_salary,
         v_achuz_kizba_sofi,
         v_months_extra,
         v_tkufot_overlapping_maanak,
         sysdate,
         v_makor_maskoret_kizba,
         v_code_e_zakaut,
         v_achuz_medina_fixed, --7
         v_achuz_medina_yachasi,
         0,
         v_date_start_zakaut,
         v_achuz_kizba_gil_60); --7
    commit;
  
    if v_sug_bakasha in (7, 23) then
      compare_gufim_current_and_prev(p_seq_bakasha);
    end if;
  exception
    when others then
      update netuney_tik_mechushavim n
         set n.code_e_zakaut = 999, n.date_update = sysdate
       where seq_bakasha = p_seq_bakasha
         and code_department = 2;
      commit;
  end;
   ---------------------------------------------
  procedure calc_mayors(p_seq_bakasha number,p_code_sug_bakasha           number) is    
    v_chelkiyut_meshuklelet number;
    v_maskoret_kovvat number;
    v_mikdemet_yoker number;
    v_achuz_kizba number;
    v_schum_kizba number;
    v_tkufa_mezaka_media number;
    v_date_start_zakaut date;
    v_code_derug_sachar number;
    v_is_sheerim_sheer_fake      number;
    v_is_zakai_maanak_fake       number;
    v_sum_achuz_kizba_sheer_fake number;
    v_code_e_zakaut_fake         number;
                                   
  begin
 
     pk_zakaut.calc_data_tkufa_mezaka(p_seq_bakasha,
                                     0,
                                     v_chelkiyut_meshuklelet,
                                     v_achuz_kizba,
                                     v_tkufa_mezaka_media);
                                     --get by prev bakasha
     if nvl(v_chelkiyut_meshuklelet,0) = 0 or nvl(v_achuz_kizba,0) = 0 then
       with a as
       (select v.*
          from bakasha t
          left join v_bakasha_last_status v
            on t.seq_prisha = v.seq_prisha
         where t.seq_bakasha = p_seq_bakasha)
      
      select n.chelkiyut_meshuklelet_sherut,
      n.achuz_kizba_kafuf_chelkiyut,
      n.tkufa_mezaka_sherut      
        into v_chelkiyut_meshuklelet,
                                     v_achuz_kizba,
                                     v_tkufa_mezaka_media
        from bakasha t1
        left join a t2
          on t1.seq_prisha = t2.seq_prisha
         and t2.seq_bakasha < t1.seq_bakasha
         and t1.code_sug_bakasha = 8 
        left join netuney_tik_mechushavim n
          on n.seq_bakasha = t2.seq_bakasha
         and n.code_department = 2
         and n.mispar_misra = 0
        where t1.seq_bakasha = p_seq_bakasha
         and t2.code_action <> 17
       order by t2.seq_bakasha desc fetch first 1 rows only;
     end if;
                                     
     if p_code_sug_bakasha = 9 then
     /*pk_zakaut.sheerim_calc_achuz_kizba(p_seq_bakasha,
                                           v_is_sheerim_sheer_fake,
                                           v_sum_achuz_kizba_sheer_fake,
                                           v_max_achuz_kizba_sheer,
                                           v_is_zakai_maanak_fake,
                                           v_code_e_zakaut_fake,
                                           0,
                                           null,
                                           v_sum_achuz_kizba_sheer_chuka);*/
                                           v_sum_achuz_kizba_sheer_chuka:=100;
     v_achuz_kizba := v_achuz_kizba * v_sum_achuz_kizba_sheer_chuka * 0.01;
                                           
     end if;      
     select b.code_derug_sganei_arim
     into v_code_derug_sachar
     from bakasha_regila b
     where b.seq_bakasha=p_seq_bakasha;     
     
     select p.date_payment
     into v_date_start_zakaut
     from participation p
     where p.seq_bakasha = p_seq_bakasha
     and p.code_participation = 1;
     
     select nvl(t.schum,0) , nvl(t.mikdamat_yoker,0)
     into v_maskoret_kovvat,v_mikdemet_yoker
     from maskorot_le_sganei_arim t
     where t.from_date <= v_date_start_zakaut
     and t.code_ramat_rashut = v_code_derug_sachar
     order by t.from_date desc
     fetch first 1 rows only;
     
     
     update bakasha_regila br
     set maskoret_kovaat = v_maskoret_kovvat,
     mikdmat_yoker = v_mikdemet_yoker
     where seq_bakasha=p_seq_bakasha;
     
     v_schum_kizba := v_achuz_kizba*0.01*(v_maskoret_kovvat+v_mikdemet_yoker)*v_chelkiyut_meshuklelet;
     
     merge into netuney_tik_mechushavim tt
    using dual
    on (seq_bakasha = p_seq_bakasha and code_department = 2 and mispar_misra = 0)
    when matched then
      update
         set maskoret_kizba        = round(v_maskoret_kovvat + v_mikdemet_yoker,2),
             schum_kizba           = round(v_schum_kizba,2),
             achuz_kizba_sofi      = round(v_achuz_kizba,2), 
             chelkiyut_sofit       = v_chelkiyut_meshuklelet, 
             achuz_kizba_kafuf_chelkiyut = round(v_achuz_kizba,2),
              chelkiyut_meshuklelet_sherut = v_chelkiyut_meshuklelet,
               tkufa_mezaka_sherut =      round( v_tkufa_mezaka_media),
             date_update           = sysdate,
             date_start_zakaut     = v_date_start_zakaut,
             code_e_zakaut         = null
      
    
    when not matched then
      insert
        (seq_netuney_tik_mechushavim,
         seq_bakasha,
         code_department,
         maskoret_kizba,
             schum_kizba,
             achuz_kizba_sofi, 
             chelkiyut_sofit,            
             date_update,
             date_start_zakaut,
             code_e_zakaut,
             tkufa_mezaka_sherut,
             chelkiyut_meshuklelet_sherut,
             achuz_kizba_kafuf_chelkiyut) --7
      values
        (netuney_tik_mechushavim_seq.nextval,
         p_seq_bakasha,
         2,
         round(v_maskoret_kovvat + v_mikdemet_yoker,2),
         round(v_schum_kizba,2),
         round(v_achuz_kizba,2), 
         v_chelkiyut_meshuklelet            ,
         sysdate,
         v_date_start_zakaut,
         null,
         round(v_tkufa_mezaka_media),
         v_chelkiyut_meshuklelet,
         v_achuz_kizba); --7
    commit;
       
  end;
  ---------------------------------------------
  procedure achuz_kizba_gil_60(p_seq_bakasha           number,
                               p_percent_overlap_kizba number,
                               p_achuz_kizba_gil_60    out number,
                               p_group_prisha          number) is
    v_date_start_zakaut date;
    v_date_payment      date;
    v_chelkiyut_sofit   number;
  begin
    select t.achuz_kizba_gil_60, t.date_start_zakaut, t.chelkiyut_sofit
      into p_achuz_kizba_gil_60, v_date_start_zakaut, v_chelkiyut_sofit
      from netuney_tik_mechushavim t
     where t.seq_bakasha = p_seq_bakasha
       and t.code_department = 2
       and t.mispar_misra = 0;
  
    select max(p.date_payment)
      into v_date_payment
      from participation p
     where p.seq_bakasha = p_seq_bakasha
       and p.date_answer is not null;
  
    if v_date_start_zakaut = v_date_payment and
       nvl(p_percent_overlap_kizba, 0) > 0 and p_group_prisha in (1, 3) then
      p_achuz_kizba_gil_60 := p_achuz_kizba_gil_60 -
                              round_percent_by_months(p_percent_overlap_kizba /
                                                      v_chelkiyut_sofit);
    end if;
  end;
  ----------------------------------------------
  procedure compare_gufim_current_and_prev(p_seq_bakasha number) is
    v_prev_bakasha     number;
    v_mispar_zehut     number;
    v_seq_ezor_ovdim   number;
    v_code_sug_bakasha number;
  begin
  
    update participation p
       set p.is_hilan = 0
     where p.seq_bakasha = p_seq_bakasha;
  
    select v.mispar_zehut, v.seq_ezor_ovdim, v.code_sug_bakasha
      into v_mispar_zehut, v_seq_ezor_ovdim, v_code_sug_bakasha
      from v_bakasha_last_status v
     where v.seq_bakasha = p_seq_bakasha;
    begin
      select *
        into v_prev_bakasha
        from (select b2.seq_bakasha
                from bakasha b1
                left join code_sug_bakasha s1
                  on b1.code_sug_bakasha = s1.code_sug_bakasha
                left join v_bakasha_last_status b2
                  on b1.seq_prisha = b2.seq_prisha
                left join code_sug_bakasha s2
                  on b1.code_sug_bakasha = s2.code_sug_bakasha
               where b1.seq_bakasha = p_seq_bakasha
                 and b2.seq_bakasha < b1.seq_bakasha
                 and s1.code_merge_bakasha = s2.code_merge_bakasha
                 and b2.code_action <> 17
               order by b2.seq_bakasha desc)
       where rownum = 1;
    
    exception
      when no_data_found then
        update participation p
           set p.is_hilan = 1
         where p.seq_bakasha = p_seq_bakasha;
    end;
  
    for r in (select t.seq_guf,
                     t.date_payment,
                     t.achuz_guf_final,
                     t.schum_maanak_baguf,
                     t.sum_participation,
                     t.sum_arai,
                     t.partial_period,
                     t.odef_sherut_baguf
                from participation t
               where t.seq_bakasha = p_seq_bakasha
              minus
              select t.seq_guf,
                     t.date_payment,
                     t.achuz_guf_final,
                     t.schum_maanak_baguf,
                     t.sum_participation,
                     t.sum_arai,
                     t.partial_period,
                     t.odef_sherut_baguf
                from participation t
               where t.seq_bakasha = v_prev_bakasha) loop
      update participation p
         set p.is_hilan = 1
       where p.seq_bakasha = p_seq_bakasha
         and p.seq_guf = r.seq_guf;
    
    end loop;
    commit;
  end;
  ---------------------------------------------
  function Get_maskoret_after_chelkyut(p_maskoret         number,
                                       p_seq_bakasha      number,
                                       p_code_sug_bakasha number)
    return number is
    v_chelkiyut    number;
    v_is_municipal number;
  begin
    select case
             when p_code_sug_bakasha in (7, 23) then
              t.chelkiyut_sofit
             else
              t.chelkiyut_meshuklelet_sherut
           end
      into v_chelkiyut
      from netuney_tik_mechushavim t
     where t.seq_bakasha = p_seq_bakasha
       and t.code_department = 2;
  
    v_is_municipal := is_municipal(p_seq_bakasha);
  
    if v_is_municipal = 1 or p_code_sug_bakasha=23 then
      return p_maskoret;
    else
      return v_chelkiyut * p_maskoret /*/ 100*/
      ;
    end if;
  
  end;
  ---------------------------------------------
  function is_municipal(p_seq_bakasha number) return number is
    v_is_municipal       number;
    v_is_exists_guf_iria number;
    v_code_sug_bakasha   number;
  begin
  
    select case
             when (t1.code_sug_ezor_ovdim = 3 or t1.code_sug_ezor_ovdim = 6) then
              1
             else
              0
           end,
           b.code_sug_bakasha
      into v_is_municipal, v_code_sug_bakasha
      from participation t
      left join bakasha b
        on t.seq_bakasha = b.seq_bakasha
      left join ezor_ovdim_category t1
        on t.seq_guf = t1.seq_ezor_ovdim
       and t1.code_sug_ezor_ovdim in (3, 5, 6)
     where t.seq_bakasha = p_seq_bakasha
       and (t.code_participation in (1, 2, 6) or
           (t.code_participation = 5 and b.code_sug_bakasha in (7, 23)))
       and rownum = 1
     order by t.code_participation;
  
    if v_code_sug_bakasha in (7, 23) then
      select count(*)
        into v_is_exists_guf_iria
        from participation t
        join ezor_ovdim_category e
          on t.seq_guf = e.seq_ezor_ovdim
         and e.code_sug_ezor_ovdim in (3, 6)
       where t.seq_bakasha = p_seq_bakasha
         and (t.date_answer is not null);
      if v_is_exists_guf_iria > 0 then
        v_is_municipal := 1;
      end if;
    end if;
    if v_is_municipal = 1 then
      return 1;
    else
      return 0;
    end if;
  end;
  ---------------------------------------------
  function is_overlap_from_guf(p_seq_bakasha number) return number is
    v_is_overlap_from_guf number := 0;
  begin
  
    select case
             when (t.seq_guf = 10465 or t1.code_sug_ezor_ovdim = 6) and
                  b.code_sug_bakasha in (8, 9)  then
              1
             else
              0
           end
      into v_is_overlap_from_guf
      from participation t
      left join bakasha b
        on t.seq_bakasha = b.seq_bakasha
      left join ezor_ovdim_category t1
        on t.seq_guf = t1.seq_ezor_ovdim
       and t1.code_sug_ezor_ovdim in (3, 5, 6)
     where t.seq_bakasha = p_seq_bakasha
       and (t.code_participation in (1, 2, 6) or
           (t.code_participation = 5 and b.code_sug_bakasha in (7, 23)))
       and rownum = 1
     order by t.code_participation;
  
    if v_is_overlap_from_guf = 1 then
      return 1;
    else
      return 0;
    end if;
  end;
  ---------------------------------------------
  function round_months(p_months_number number, p_days_number number)
    return number is
  
    v_complete_months number;
    v_remainder_days  number;
    v_addinal_months  number;
  begin
    v_addinal_months  := trunc(p_days_number / 30);
    v_complete_months := p_months_number + v_addinal_months;
    v_remainder_days  := mod(p_days_number, 30);
    --round by law
    if v_remainder_days > 15 then
      return v_complete_months + 1;
    else
      return v_complete_months;
    end if;
  end;
  ---------------------------------------------
  function Get_maskoret_kovvat_tikra(p_seq_bakasha number,
                                     p_sug_bakasha number,
                                     p_maanak      number) return number is
    v_maskoret        number;
    v_maskoret_maavar number;
  begin
  
    select r.maskoret_maavar
      into v_maskoret_maavar
      from bakasha_regila r
     where r.seq_bakasha = p_seq_bakasha;
    if p_sug_bakasha in (8, 9) then
      --leguf --7
      select case
               when v_maskoret_maavar >
                    max(GetSumGuf(p.seq_participation, p_maanak, 0)) then
                Get_maskoret_after_chelkyut(v_maskoret_maavar,
                                            p_seq_bakasha,
                                            p_sug_bakasha)
               else
                max(GetSumGuf(p.seq_participation, p_maanak))
             
             end
        into v_maskoret
        from participation p
        left join bakasha_regila r
          on r.seq_bakasha = p.seq_bakasha
       where p.seq_bakasha = p_seq_bakasha
         and p.code_participation = 1;
    elsif --7-
     p_sug_bakasha in (7, 23) then
      --meguf
      select case
               when max(GetSumGuf(p.seq_participation, p_maanak, 0)) >
                    max(/*decode(p_maanak,
                    1,
                    nvl(r.MASKORET_LEMAANAK, r.maskoret_kovaat),
                    r.maskoret_kovaat)*/  r.maskoret_kovaat) then --guf > medina
                max(GetSumGuf(p.seq_participation, p_maanak, 0))
               else
                max(/*decode(p_maanak,
                    1,
                    nvl(r.MASKORET_LEMAANAK, r.maskoret_kovaat),
                    r.maskoret_kovaat)*/r.maskoret_kovaat)
             end
        into v_maskoret
        from participation p
        left join bakasha_regila r
          on r.seq_bakasha = p.seq_bakasha
       where p.seq_bakasha = p_seq_bakasha
         and p.code_participation in (2, 5)
         and (p.date_answer is not null)
       group by p.seq_bakasha;
    
    else
      select greatest(p.sum, r.maskoret_kovaat)
        into v_maskoret
        from participation p
        left join bakasha_regila r
          on r.seq_bakasha = p.seq_bakasha
       where p.seq_bakasha = p_seq_bakasha
         and p.code_participation = 6;
    end if; --7 end
    return v_maskoret;
  end;
  ---------------------------------------------
  function Get_makor_maskoret_kovat_kizba(p_seq_bakasha number,
                                          p_sug_bakasha number,
                                          p_is_maanak   number,
                                          p_is_overlap  number default 0)
    return number is
    v_makor number;
  begin
    if p_sug_bakasha in (7, 23) then
      v_makor := 1;
    elsif p_sug_bakasha in (8, 9) then
      --7-
      select case
               when r.code_seif_prisha = 215 and
                    t2.code_sug_ezor_ovdim in (3, 6) then
                2
               when GetSumGuf(p.seq_participation, p_is_maanak) <
                    Get_maskoret_after_chelkyut(r.maskoret_kovaat,
                                                p_seq_bakasha,
                                                p_sug_bakasha) and
                    r.maskoret_maavar >
                    GetSumGuf(p.seq_participation, 0, p_is_overlap) then
                3
             --chinuch azmai always p.sum
               when p.seq_guf = 10465 then
                2
               when GetSumGuf(p.seq_participation, p_is_maanak, p_is_overlap) <
                    Get_maskoret_after_chelkyut(r.maskoret_kovaat,
                                                p_seq_bakasha,
                                                p_sug_bakasha) and
                    nvl(r.maskoret_maavar, 0) <
                    GetSumGuf(p.seq_participation, p_is_maanak, p_is_overlap) then
                2
               when r.code_seif_prisha = 215 and
                    t2.code_sug_ezor_ovdim in (3, 6) then
                2
               when r.maskoret_kovaat > 0 then
                1
               else
                null
             end
      
        into v_makor
        from participation p
        left join bakasha_regila r
          on r.seq_bakasha = p.seq_bakasha
        left join ezor_ovdim_category t2
          on p.seq_guf = t2.seq_ezor_ovdim
         and t2.code_sug_ezor_ovdim in (3, 5, 6)
       where p.seq_bakasha = p_seq_bakasha
            -- participation 2 guf
         and p.code_participation = 1;
    end if;
    return v_makor;
  end;
  ---------------------------------------------
  function Get_maskoret_kovvat_kizba(p_seq_bakasha number,
                                     p_sug_bakasha number,
                                     p_is_maanak   number,
                                     p_is_overlap  number default 0)
    return number is
    v_maskoret number;
  begin
    if p_sug_bakasha in (8, 9) then
      --leguf --7
      select case
               when Get_makor_maskoret_kovat_kizba(p_seq_bakasha,
                                                   p_sug_bakasha,
                                                   p_is_maanak,
                                                   p_is_overlap) = 3 then
                Get_maskoret_after_chelkyut(r.maskoret_maavar,
                                            p_seq_bakasha,
                                            p_sug_bakasha)
               when Get_makor_maskoret_kovat_kizba(p_seq_bakasha,
                                                   p_sug_bakasha,
                                                   p_is_maanak,
                                                   p_is_overlap) = 2 then
                GetSumGuf(p.seq_participation, p_is_maanak, p_is_overlap)
               else
                Get_maskoret_after_chelkyut(r.maskoret_kovaat,
                                            p_seq_bakasha,
                                            p_sug_bakasha)
             end
      
        into v_maskoret
        from participation p
        left join bakasha_regila r
          on r.seq_bakasha = p.seq_bakasha
      
       where p.seq_bakasha = p_seq_bakasha
            -- participation 2 guf
         and p.code_participation = 1;
    elsif p_sug_bakasha in (7, 23) then
      --meguf
      select /*case when p_is_maanak=
                    1 and nvl(p_is_overlap,0) = 0 then
                    nvl(r.MASKORET_LEMAANAK, r.maskoret_kovaat)else
                    r.maskoret_kovaat end*/r.maskoret_kovaat
        into v_maskoret
        from bakasha_regila r
       where r.seq_bakasha = p_seq_bakasha;
      --and p.code_participation = 1;
    
    else
      --gimlaot_kefel
      select max(greatest(p.sum, r.maskoret_kovaat))
        into v_maskoret
        from participation p
        left join bakasha_regila r
          on r.seq_bakasha = p.seq_bakasha
       where p.seq_bakasha = p_seq_bakasha
         and p.code_participation = 6;
    end if;
  
    return v_maskoret;
  end;
  ---------------------------------------------
  function Get_maskoret_kovvat_maanak(p_seq_bakasha number,
                                     p_sug_bakasha number,
                                     p_is_maanak   number,
                                     p_is_overlap  number default 0)
    return number is
    v_maskoret number;
  begin
    if p_sug_bakasha in (8, 9) then
      --leguf --7
      select case
               when Get_makor_maskoret_kovat_kizba(p_seq_bakasha,
                                                   p_sug_bakasha,
                                                   p_is_maanak,
                                                   p_is_overlap) = 3 then
                Get_maskoret_after_chelkyut(r.maskoret_maavar,
                                            p_seq_bakasha,
                                            p_sug_bakasha)
               when Get_makor_maskoret_kovat_kizba(p_seq_bakasha,
                                                   p_sug_bakasha,
                                                   p_is_maanak,
                                                   p_is_overlap) = 2 then
                GetSumGuf(p.seq_participation, p_is_maanak, p_is_overlap)
               else
                Get_maskoret_after_chelkyut(r.maskoret_kovaat,
                                            p_seq_bakasha,
                                            p_sug_bakasha)
             end
      
        into v_maskoret
        from participation p
        left join bakasha_regila r
          on r.seq_bakasha = p.seq_bakasha
      
       where p.seq_bakasha = p_seq_bakasha
            -- participation 2 guf
         and p.code_participation = 1;
    elsif p_sug_bakasha in (7, 23) then
      --meguf
      select case when p_is_maanak=
                    1 and nvl(p_is_overlap,0) = 0 then
                      case when nvl(r.MASKORET_LEMAANAK,0)>0 
                        then  r.MASKORET_LEMAANAK else
                      r.maskoret_kovaat 
                      end
                    else r.maskoret_kovaat end
        into v_maskoret
        from bakasha_regila r
       where r.seq_bakasha = p_seq_bakasha;
      --and p.code_participation = 1;
    
    else
      --gimlaot_kefel
      select max(greatest(p.sum, r.maskoret_kovaat))
        into v_maskoret
        from participation p
        left join bakasha_regila r
          on r.seq_bakasha = p.seq_bakasha
       where p.seq_bakasha = p_seq_bakasha
         and p.code_participation = 6;
    end if;
  
    return v_maskoret;
  end;
  ---------------------------------------------
  procedure insrt_ntuny_tik_mchshvim_guf(p_seq_participation number) is
  
    v_total_months    number;
    v_chelkyut_zvura  number;
    v_achuz_kizba     number;
    v_chodshey_maanak number := 0;
    v_chodshey_arai   number := 0;
    v_public_monthes  number;
    --for gimlat kefel
    v_achuz_final    number;
    v_kizba_chodshit number;
  begin
  
    calc_ntuny_tik_mchshvim_guf(p_seq_participation,
                                v_total_months,
                                v_chelkyut_zvura,
                                v_achuz_kizba,
                                v_chodshey_maanak,
                                v_chodshey_arai,
                                v_public_monthes,
                                v_achuz_final,
                                v_kizba_chodshit);
  
    update participation
       set tkufa_mezaka             = round(v_total_months, 0),
           partial_period_calc      = round(v_chelkyut_zvura, 3),
           percent_participate_calc = round(v_achuz_kizba, 2),
           chodshey_maanak_calc     = round(v_chodshey_maanak, 3),
           chodshey_arai_calc       = round(v_chodshey_arai, 3),
           public_tkufa_mezaka      = round(v_public_monthes, 3),
           achuz_guf_final          = round(v_achuz_final, 2),
           kizba_chodshit           = round(v_kizba_chodshit, 2)
     where seq_participation = p_seq_participation;
  
    commit;
  
  end;
  ---------------------------------------------
  procedure calc_ntuny_tik_mchshvim_guf(p_seq_participation number,
                                        p_total_months      out number,
                                        p_chelkyut_zvura    out number,
                                        p_achuz_kizba       out number,
                                        p_chodshey_maanak   out number,
                                        p_chodshey_arai     out number,
                                        p_public_monthes    out number,
                                        p_achuz_final       out number,
                                        p_kizba_chodshit    out number) is
    v_code_participation  number;
    v_percent_participate number;
    v_sum_participation   number;
    v_partial_period      number;
    /*v_seq_guf             number;
    v_is_public           number;*/
    v_count_peroid number;
  begin
  
    select sum(months) total_months,
           sum(achuz_chelkyut * months) / sum(months) chelkyut_zvura,
           sum(months) / 6 achuz_kizba,
           sum(months_maanak) as months_maanak
      into p_total_months,
           p_chelkyut_zvura,
           p_achuz_kizba,
           p_chodshey_maanak
      from (select months_between(t.date_to + 1, t.date_from) months,
                   decode(code_sug_ezor_ovdim,
                          3,
                          t.achuz_chelkiut,
                          6,
                          t.achuz_chelkiut,
                          1) achuz_chelkyut,
                   months_between(t.date_to + 1, t.date_from) *
                   --least(nvl(t.achuz_chelkiut, 1), 1) *
                    decode(t.code_sug_pensia, 1, 0.625, 3, 1.25, 1) months_maanak
              from participation_tkufot t
              left join participation t1
                on t.seq_participation = t1.seq_participation
              left join bakasha b
                on b.seq_bakasha = t1.seq_bakasha
              left join ezor_ovdim_category t2
                on t1.seq_guf = t2.seq_ezor_ovdim
               and t2.code_sug_ezor_ovdim in (3, 5, 6)
             where t.seq_participation = p_seq_participation
               and (t1.date_answer is not null or
                   b.code_sug_bakasha not in (7, 23))
               and nvl(t.code_sug_tkufa, 0) <> 1) base;
  
    --arai monthes
    select sum(months_between(t.date_to + 1, t.date_from) *
               decode(code_sug_ezor_ovdim,
                      3,
                      t.achuz_chelkiut,
                      6,
                      t.achuz_chelkiut,
                      1)) months_arai_calc
      into p_chodshey_arai
      from participation_tkufot t
      left join participation t1
        on t.seq_participation = t1.seq_participation
      left join bakasha b
        on b.seq_bakasha = t1.seq_bakasha
      left join ezor_ovdim_category t2
        on t1.seq_guf = t2.seq_ezor_ovdim
       and t2.code_sug_ezor_ovdim in (3, 5, 6)
     where t.seq_participation = p_seq_participation
       and (t1.date_answer is not null or b.code_sug_bakasha not in (7, 23))
       and nvl(t.code_sug_tkufa, 0) = 1;
    p_achuz_kizba := p_achuz_kizba + nvl(p_chodshey_arai, 0) / 6;
  
    select p.code_participation,
           p.percent_participate,
           p.achuz_guf_final,
           p.kizba_chodshit,
           p.sum_participation,
           p.partial_period /*,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               p.seq_guf*/
      into v_code_participation,
           v_percent_participate,
           p_achuz_final,
           p_kizba_chodshit,
           v_sum_participation,
           v_partial_period /*,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               v_seq_guf*/
      from participation p
     where p.seq_participation = p_seq_participation;
  
    --public_months
  
    select sum(months_between(pt.date_to + 1,
                              case
                                when pt.seq_public_guf is not null and
                                    -- if the public_guf was be active-public after the date_from,
                                    --the rellevant date is the date_active from the public_guf
                                     g.date_active > pt.date_from then
                                 g.date_active
                                else
                                 pt.date_from
                              end))
    
      into p_public_monthes
      from participation_tkufot pt
      left join participation p
        on pt.seq_participation = p.seq_participation
      left join code_public_guf g
        on pt.seq_public_guf = g.code_public_guf
      left join ezor_ovdim_category t2
        on p.seq_guf = t2.seq_ezor_ovdim
       and t2.code_sug_ezor_ovdim in (3, 5, 6)
     where p.seq_participation = p_seq_participation
          --if there is a public guf
          --and the guf was be active-public before the end of the participation period.
       and ((pt.seq_public_guf is not null and g.date_active < pt.date_to) or
           t2.code_sug_ezor_ovdim <> 5);
  
    /*select count(*)
     into v_is_public
     from ezor_ovdim_category e
    where e.seq_ezor_ovdim = v_seq_guf
      and e.code_sug_ezor_ovdim in (1, 3, 6);*/
  
    -- if all the months are public
    --the user not needs to enter all the periods
    select count(*) count_peroid
      into v_count_peroid
      from participation_tkufot pt
     where pt.seq_participation = p_seq_participation;
  
    if v_count_peroid = 0 then
      p_public_monthes := 1;
      p_total_months   := 1;
    end if;
  
    if v_code_participation = 6 then
      if nvl(p_public_monthes, 0) > 0 then
        p_achuz_final    := nvl(v_percent_participate, 0) *
                            nvl(v_partial_period, 1) *
                            nvl(p_public_monthes, 0) /
                            nvl(p_total_months, 0);
        p_kizba_chodshit := nvl(v_sum_participation, 0) *
                            nvl(v_partial_period, 1) *
                            nvl(p_public_monthes, 0) /
                            nvl(p_total_months, 0);
      else
        p_achuz_final    := 0;
        p_kizba_chodshit := 0;
      end if;
    
    end if;
  
  end;
  -------------------------------------------
  function Get_overlapping_months(p_seq_bakasha number,
                                  p_sug_bakasha number,
                                  p_only_public number) return number is
    pragma autonomous_transaction;
    v_overlpping_months   number := 0;
    v_code_sug_ezor_ovdim number;
    v_maskoret_kovaat     number;
    v_seq_participation   number;
  begin
    begin
    
      --delete old data
      delete from participation_tkufot_overlap p
       where p.seq_bakasha = p_seq_bakasha
         and p.only_public = p_only_public;
    select b.maskoret_kovaat-case when p_only_public=1 then 0 else nvl(b.mikdmat_yoker,0)end
    into v_maskoret_kovaat
    from bakasha_regila b
    where b.seq_bakasha=p_seq_bakasha;
    
      for r in (with with_participation_tkufot as
                   (select case
                            when pt.seq_public_guf is not null and
                                 p_only_public = 1 and
                                -- if the public_guf was be active-public after the date_from,
                                --the rellevant date is the date_active from the public_guf
                                 g.date_active > pt.date_from then
                             g.date_active
                            else
                             pt.date_from
                          end as date_from,
                          pt.date_to,
                          pt.code_sug_pensia,
                          /*case
                            when p_sug_bakasha in (7, 8, 9) then
                             pt.achuz_chelkiut
                            else
                             p.partial_period
                          end achuz_chelkiut*/
                          p.partial_period as achuz_chelkiut,
                          GetSumGuf(p.seq_participation,
                                    decode(p_only_public, 0, 1, 1, 0),
                                    1) as sum
                     from participation_tkufot pt
                     left join participation p
                       on pt.seq_participation = p.seq_participation
                     left join code_public_guf g
                       on pt.seq_public_guf = g.code_public_guf
                     left join (select max(seq_ezor_ovdim) seq_ezor_ovdim,
                               max(ec.code_sug_ezor_ovdim) keep(dense_rank first order by ec.code_sug_ezor_ovdim)code_sug_ezor_ovdim
                               from ezor_ovdim_category ec
                               where ec.code_sug_ezor_ovdim in (1,3,5,6)
                               group by seq_ezor_ovdim) t1
                       on p.seq_guf = t1.seq_ezor_ovdim
                      /*and (t1.code_sug_ezor_ovdim in (3, 5, 6)
                      --and p.code_participation <> 6 
                      or
                          t1.code_sug_ezor_ovdim = 1 and
                          p.code_participation = 6 and
                          p_sug_bakasha not in (7, 23, 9, 8))*/
                    where p.seq_bakasha = p_seq_bakasha
                         -------------------------- by rivka 11/05/2020
                      and nvl(pt.code_sug_pensia, 0) <> 4
                         -------------------------- end by rivka 11/05/2020
                      and (p.date_answer is not null or
                          p_sug_bakasha not in (7, 23))
                      and (p.code_participation in (1,5) or
                          is_overlap_from_guf(p_seq_bakasha) = 0)
                      and nvl(pt.code_sug_tkufa, 0) <> 1
                      and (t1.code_sug_ezor_ovdim in (1, 3, 6)/* or
                          p_only_public = 0 or
                          --if there is a public guf
                          --and the guf was be active-public before the end of the participation period.
                          (pt.seq_public_guf is not null and
                          g.date_active < pt.date_to)*/))
                  
                  --Get overlapp periods between 'participation_tkufot' and 'tkufot_avoda_mechushv'
                  --And get achuz_chelkiut to the period.
                  select least(m1.date_to, m2.taarich_ad) date_end,
                         greatest(m2.taarich_me, m1.date_from) date_start,
                         -- Sum of achuz_chelkiut can not be greater than 100%
                         total as total,
                         
                         least(m2.chelkiyut_meshuklelet_sherut, 1) as achuz_chelkyut
                    from ( --Separate periods (only participation_tkufot ) in case of overlaps
                          --and get relevant data for the period (sum of achuz_chelkiut)
                          select lower_boundary as date_from,
                                  case lead(lower_boundary)
                                   over(order by lower_boundary asc)
                                  -- When upper_boundary and next lower_boundary is same date
                                  --Subtract 1 day from upper_boundary
                                    when upper_boundary then
                                     upper_boundary - 1
                                    else
                                     upper_boundary
                                  end as date_to,
                                  sum(achuz_chelkiut * case
                                        when p_only_public = 0 and
                                             pt.code_sug_pensia = 1 then
                                         0.625
                                        else
                                         1
                                      end * pt.sum /
                                      Get_maskoret_kovvat_kizba(p_seq_bakasha,
                                                                p_sug_bakasha,
                                                                decode(p_only_public,1,0,1))) total
                          
                            from ( --Get 2 colums: date, and - the nearst date.
                                   select boundary as lower_boundary,
                                           lead(boundary) over(order by boundary) as upper_boundary
                                     from ( --Get 1 colum that contain 'date_from' and also 'date_to' from participation_tkufot
                                            select case n
                                                      when 1 then
                                                       pt.date_from
                                                      when 2 then
                                                       pt.date_to
                                                    end boundary
                                              from with_participation_tkufot pt,
                                                    (select rownum n
                                                       from dual
                                                     connect by rownum <= 2))
                                    order by boundary asc) l,
                                  --Get participation_tkufot by normal query
                                  with_participation_tkufot pt
                          
                          --Filter: Get participation_tkufot data according to range of dates (from internal query - l)
                           where upper_boundary is not null
                             and pt.date_from < upper_boundary
                             and pt.date_to > lower_boundary
                          
                           group by lower_boundary, upper_boundary
                           order by date_from) m1,
                         --Get periods tkufot_avoda_mechushv
                         (select t.*,
                                 t.seq_bakasha,
                                 t2.chelkiyut_meshuklelet_sherut
                            from tkufot_avoda_mechushv t
                            left join code_sug_zchuyot_mechushavim t1
                              on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
                            left join netuney_tik_mechushavim t2
                              on t.seq_bakasha = t2.seq_bakasha
                             and t2.code_department = 2
                             and t2.mispar_misra = 0
                           where t.seq_bakasha = p_seq_bakasha
                             and t1.haim_nirkash = 1
                             and t.code_sugey_tkufot not in (7, 23)) m2
                  --Filter: Get overlapp periods between 'participation_tkufot' and 'tkufot_avoda_mechushv'
                   where m2.taarich_me <= m1.date_to
                     and m2.taarich_ad >= m1.date_from
                     and m1.date_from <> m1.date_to
                     and m2.taarich_me <> m2.taarich_ad
                   order by 1, 2) loop
      
        --Insert base data
        insert into participation_tkufot_overlap
          (seq_participatn_tkufot_overlap,
           seq_bakasha,
           date_start,
           date_end,
           chelkiyut_guf,
           chelkiyut_medina,
           only_public)
        values
          (participatn_tkufot_overlap_seq.Nextval,
           p_seq_bakasha,
           r.date_start,
           r.date_end,
           r.total,
           r.achuz_chelkyut,
           p_only_public);
      end loop;
    
      begin
        select distinct first_value(t.seq_participation) over(order by nvl(t.sum, 0) desc) seq_participation
          into v_seq_participation
          from participation t
         where t.seq_bakasha = p_seq_bakasha
           and t.code_participation in (1, 2, 6)
           and (t.date_answer is not null or p_sug_bakasha not in (7, 23));
      
      exception
        when no_data_found then
          if v_seq_participation is null and p_sug_bakasha in (7, 23) then
            select distinct first_value(t.seq_participation) over(order by nvl(t.sum, 0) desc) seq_participation
              into v_seq_participation
              from participation t
             where t.seq_bakasha = p_seq_bakasha
               and t.code_participation in (2, 5)
               and (t.date_answer is not null);
          end if;
      end;
    
      --Update other data
      for r2 in (select o.seq_participatn_tkufot_overlap,
                        --!!!!!!!!!!!!!!!excel calculation!!!!!!!!!!!!!!!!!!!!!
                        /*round(round((o.date_end - o.date_start) / 365 * 12,
                              2) / 6,
                        2) kizba_percent,*/
                        months_between(o.date_end + 1, o.date_start) / 6 kizba_percent,
                        o.chelkiyut_guf,
                        o.chelkiyut_medina,
                        GetSumGuf(p.seq_participation,
                                  decode(p_only_public, 0, 1, 1, 0),
                                  1) as sum_participation,
                                  br.maskoret_kovaat
                   from participation_tkufot_overlap o
                   left join netuney_tik_mechushavim n
                     on n.seq_bakasha = o.seq_bakasha
                    and n.code_department = 2
                   left join participation p
                     on p.seq_participation = v_seq_participation
                     left join bakasha_regila br
                     on br.seq_bakasha = o.seq_bakasha
                  where o.seq_bakasha = p_seq_bakasha
                    and (p.date_answer is not null or
                        p_sug_bakasha not in (7, 23))
                    and o.only_public = p_only_public) loop
      
        update participation_tkufot_overlap p
        --kizba_max
           set p.kizba_max = r2.kizba_percent *
                             Get_maskoret_kovvat_tikra(p_seq_bakasha,
                                                       p_sug_bakasha,
                                                       decode(p_only_public,
                                                              0,
                                                              1,
                                                              1,
                                                              0)) * 0.01,
               --kizba_medina
               p.kizba_medina = (r2.kizba_percent * CASE WHEN p_sug_bakasha in (1,3,5)then r2.maskoret_kovaat     else
                                Get_maskoret_kovvat_kizba(p_seq_bakasha,
                                                           p_sug_bakasha,
                                                           decode(p_only_public,
                                                                  0,
                                                                  1,
                                                                  1,
                                                                  0))end 
                                                                  * case
                                  when is_municipal(p_seq_bakasha) = 1 or
                                       p_sug_bakasha not in (8, 9) then
                                   r2.chelkiyut_medina
                                  else
                                   1
                                end) * 0.01,
               --kizba_guf
               -- p.kizba_guf = r2.kizba_percent * r2.sum_participation *
               p.kizba_guf = r2.kizba_percent *
                             Get_maskoret_kovvat_kizba(p_seq_bakasha,
                                                       p_sug_bakasha,
                                                       decode(p_only_public,
                                                              0,
                                                              1,
                                                              1,
                                                              0)) *
                             r2.chelkiyut_guf * 0.01,
               --kizba_sofi
               p.kizba_sofi = r2.chelkiyut_medina
         where p.seq_participatn_tkufot_overlap =
               r2.seq_participatn_tkufot_overlap;
      end loop;
    
      --Get sum overlap
      select sum(months_between(o.date_end + 1, o.date_start))
        into v_overlpping_months
        from participation_tkufot_overlap o
       where o.seq_bakasha = p_seq_bakasha
         and o.only_public = p_only_public;
      if nvl(v_overlpping_months,0) <= 0.5 then
        v_overlpping_months := 0;
      else
      
        select sum((greatest((o.kizba_guf + o.kizba_medina - o.kizba_max),
                             0) / case
                     when p_sug_bakasha in (8, 9) and e.code_sug_ezor_ovdim = 6 then
                      p.sum
                       WHEN p_sug_bakasha in (1,3,5)then v_maskoret_kovaat     
                     else
                      Get_maskoret_kovvat_kizba(p_seq_bakasha,
                                                p_sug_bakasha,
                                                decode(p_only_public, 0, 1, 1, 0))
                   end) * 100 * 6)
          into v_overlpping_months
          from participation_tkufot_overlap o
          left join netuney_tik_mechushavim t
            on o.seq_bakasha = t.seq_bakasha
           and t.code_department = 2
          left join participation p
            on p.seq_participation = v_seq_participation
          left join ezor_ovdim_category E
            ON P.SEQ_GUF = E.SEQ_EZOR_OVDIM
           and e.code_sug_ezor_ovdim in (3, 5, 6)
         where o.seq_bakasha = p_seq_bakasha
           and (p.date_answer is not null or p_sug_bakasha not in (7, 23))
           and o.only_public = p_only_public;
      end if;
      commit;
    exception
      when no_data_found then
        v_overlpping_months := 0;
    end;
  
    /*return case when nvl(v_overlpping_months, 0) < 0.5 then 0 else v_overlpping_months end;*/
    if nvl(v_sum_achuz_kizba_sheer_chuka, 0) <> 0 and p_sug_bakasha = 23 then
      v_overlpping_months := v_overlpping_months *
                             v_sum_achuz_kizba_sheer_chuka * 0.01;
    end if;
  
    return round(nvl(v_overlpping_months, 0), 2);
  end;
  -------------------------------------------
  function Get_achuz_medina_by_maavar(p_seq_bakasha         number,
                                      v_maskoret_kovvat_guf number,
                                      v_achuz_kizba_medina  number,
                                      v_achuz_kizba_guf     number,
                                      p_sug_bakasha         number)
    return number is
    v_maskoret_maavar number;
  
    v_fixed_achuz_medina number;
    v_fixed_total_achuz  number;
  
    v_new_achuz_medina number;
  begin
    --Get maskoret maavar
    select decode(Get_maskoret_after_chelkyut(b.maskoret_maavar,
                                              p_seq_bakasha,
                                              p_sug_bakasha),
                  0,
                  null,
                  Get_maskoret_after_chelkyut(b.maskoret_maavar,
                                              p_seq_bakasha,
                                              p_sug_bakasha))
      into v_maskoret_maavar
      from bakasha_regila b
     where b.seq_bakasha = p_seq_bakasha;
  
    --Fixed achuz guf
    v_fixed_achuz_medina := v_achuz_kizba_medina * v_maskoret_maavar /
                            v_maskoret_kovvat_guf;
    --Fixed total achuz
    v_fixed_total_achuz := v_fixed_achuz_medina + v_achuz_kizba_guf;
    --New achuz medina
    v_new_achuz_medina := v_fixed_achuz_medina * v_max_achuz_kizba /
                          v_fixed_total_achuz;
    --Return total achuz medina
    return v_maskoret_kovvat_guf * v_new_achuz_medina / v_maskoret_maavar;
  end;
  ---------------------------------------------
  procedure Get_data_guf(p_seq_bakasha          in number,
                         v_temp_schum_kizba_guf in out number,
                         v_maskoret_kovvat_guf  in out number,
                         v_achuz_kizba_guf      in out number,
                         v_seq_guf              out number,
                         v_chodshey_maanak      in out number,
                         v_schum_maanak_guf     in out number,
                         v_is_maanak            in number,
                         v_sum_kizba_by_months in number default 0) is
    v_code_sug_bakasha    number := 0;
    v_overlapping_months  number := 0;
    v_code_sug_ezor_ovdim number := 0;
    v_is_overlap_from_guf number;
  begin
  
    --Get data guf
  
    select *
      into v_seq_guf, v_maskoret_kovvat_guf, v_code_sug_bakasha
      from (select t.seq_guf,
                   first_value(pk_participation_2_guff.GetSumGuf(t.seq_participation,
                                                                 v_is_maanak,
                                                                 0)) over(partition by t.seq_bakasha order by t.sum desc) sum_guf,
                   b.code_sug_bakasha
              from participation t
              left join bakasha b
                on t.seq_bakasha = b.seq_bakasha
             where t.seq_bakasha = p_seq_bakasha
               and (t.code_participation = 1 or
                   b.code_sug_bakasha in (7, 23) and
                   t.code_participation in (2, 5))
               and (t.date_answer is not null or
                   b.code_sug_bakasha in (8, 9)))
     where rownum = 1;
  
    select sum(achuz_kizba_guf),
           sum(schum_kizba_guf),
           sum(chodshey_maanak),
           sum(schum_maanak_baguf)
      into v_achuz_kizba_guf,
           v_temp_schum_kizba_guf,
           v_chodshey_maanak,
           v_schum_maanak_guf
      from (select t.percent_participate * t.partial_period *
                   GetSumGuf(t.seq_participation, v_is_maanak, 0) /
                   v_maskoret_kovvat_guf as achuz_kizba_guf,
                   GetSumGuf(t.seq_participation, v_is_maanak, 0) as sum,
                   case
                     when v_sum_kizba_by_months = 0 then
                      t.percent_participate * t.partial_period *
                      GetSumGuf(t.seq_participation, v_is_maanak, 0) / 100
                     else
                      (round((t.chodshey_maanak / 6), 2)) *
                      GetSumGuf(t.seq_participation, v_is_maanak, 0) / 100
                   end as schum_kizba_guf,
                   t.chodshey_maanak,
                   t.schum_maanak_baguf
              from participation t
             where t.seq_bakasha = p_seq_bakasha
               and (t.date_answer is not null or
                   v_code_sug_bakasha in (8, 9))
               and (v_code_sug_bakasha in (8, 9) and
                   t.code_participation in (1, 5) or
                   v_code_sug_bakasha in (7, 23) and
                   t.code_participation in (2, 5) or
                   v_code_sug_bakasha not in (7, 23, 9, 8) and
                   t.code_participation in (6))
            
            );
    v_is_overlap_from_guf := is_overlap_from_guf(p_seq_bakasha);
    if v_is_overlap_from_guf = 1 then
    
      v_overlapping_months   := Get_overlapping_months(p_seq_bakasha,
                                                       v_code_sug_bakasha, --7
                                                       nvl(v_is_maanak, 0));
      v_chodshey_maanak      := v_chodshey_maanak -
                                nvl(v_overlapping_months, 0);
      v_achuz_kizba_guf      := v_achuz_kizba_guf -
                                (nvl(v_overlapping_months, 0) / 6);
      v_temp_schum_kizba_guf := v_temp_schum_kizba_guf -
                                nvl(v_overlapping_months, 0) / 6 * 0.01 *
                                v_maskoret_kovvat_guf;
    end if;
  
  end;
  ---------------------------------------------
  function GetSumGuf(p_seq_participation in number,
                     p_is_maanak         number,
                     p_is_overlap        number default 0) return number is
    v_sum number := 0;
  begin
    select
    --guf = gilaad
    
     case
       when t.seq_guf in (8, 9) then
        case
          when p_is_maanak = 0 then
           case
             when p_is_overlap = 0 then
              nvl(t.sum, 0)--+ nvl(t.tosefet_actuarit, 0) + nvl(t.tosefet_dchiat, 0)
             else
              nvl(nvl(t.overlap_salary, t.sum), 0)
           end 
          else
          -- nvl(nvl(t.maskoret_maanak, t.sum), 0)
          nvl( t.sum, 0)
        end
       else
        case
          when p_is_maanak = 0 then
           case
             when p_is_overlap = 0 then
              nvl(t.sum, 0)
             else
              nvl(nvl(t.overlap_salary, t.sum), 0)
           end
          else
           --nvl(nvl(t.maskoret_maanak, t.sum), 0)
           nvl( t.sum, 0)
        end
     end
      into v_sum
      from participation t
    
     where t.seq_participation = p_seq_participation;
    return v_sum;
  end;
  ---------------------------------------------
  procedure Get_data_for_medina(p_seq_bakasha                 in number,
                                p_sug_bakasha                 in number, --7
                                v_temp_schum_kizba_medina     in out number,
                                v_maskoret_kovvat_medina      in out number,
                                v_achuz_kizba_medina          in out number,
                                v_achuz_kizba_medin_porprtion in out number,
                                p_only_public                 number) is
    v_overlapping_months          number := 0;
    v_is_municipal                number;
    v_code_sug_ezor_ovdim         number := 0;
    v_maskoret_in                 number;
    v_tkufa_mezka_shrut_not_round number := 0;
    v_is_overlap_from_guf         number;
    v_achuz_kizba_hagdala         number;
    v_is_maanak                   number := 0;
    v_code_group_prisha           number;
    v_prev_group_prisha           number;
    v_achuz_kizba_sofi            number;
    v_chelkiyut_sofit             number;
    v_achrey_hagdala              number;

  begin
    if p_only_public = 0 then
      v_is_maanak := 1;
    else
      v_is_maanak := 0;
    end if;
    
    
    select n.achuz_kizb_achry_hagdl_chl_mla,
    n.achuz_kizba_sofi,
    n.chelkiyut_sofit into
    v_achrey_hagdala,
    v_achuz_kizba_sofi,
    v_chelkiyut_sofit
    from netuney_tik_mechushavim n
    where n.seq_bakasha = p_seq_bakasha
    and n.code_department=2;
    
    dbms_output.put_line(v_achrey_hagdala);
    dbms_output.put_line(v_achuz_kizba_sofi);
    dbms_output.put_line(v_chelkiyut_sofit);
  
    v_maskoret_in := Get_maskoret_kovvat_kizba(p_seq_bakasha,
                                               p_sug_bakasha,
                                               v_is_maanak);
  
    v_is_municipal := is_municipal(p_seq_bakasha);
  
    v_is_overlap_from_guf := is_overlap_from_guf(p_seq_bakasha);
  
    if v_is_overlap_from_guf = 1 then
      v_overlapping_months := 0;
    else
      v_overlapping_months := Get_overlapping_months(p_seq_bakasha,
                                                     p_sug_bakasha, --7
                                                     p_only_public);
    
    end if;
    
    
  
    /*  --SUG BAKASHA = 23, GET GROUP PRISHA BY ZAKAUT bakasha
    select t.code_group_prisha
      into v_prev_group_prisha
      from netuney_tik_mechushavim t
     where t.seq_netuney_tik_mechushavim =
           pk_zakaut.sheerin_get_prev_netuney_tik(p_seq_bakasha);*/
    --Get data medina
  
    select final_achuz_medina,
           maskoret,
           final_achuz_medina * maskoret / 100
      into v_achuz_kizba_medina,
           v_maskoret_kovvat_medina,
           v_temp_schum_kizba_medina
      from (select case
                     when p_sug_bakasha = 7 then
                     --check least percent only in prissha by sherut              
                      case
                        when t.code_group_prisha in (1, 3) then
                         least(t.achuz_kizba_sofi * t.chelkiyut_sofit,
                               t.achuz_kizba_chelkiyut_melea -
                               (v_overlapping_months / 6))
                        else
                         t.achuz_kizba_sofi * t.chelkiyut_sofit
                      end
                     when p_sug_bakasha = 23 then
                     
                      case
                        when t.code_group_prisha in (1, 3, 4) then
                         least(t.achuz_kizba_sofi * t.chelkiyut_sofit,
                               (case when  v_is_municipal = 0 then nvl(t.achuz_kizb_achry_hagdl_chl_mla,t.achuz_kizba_chelkiyut_melea) else t.achuz_kizba_chelkiyut_melea end *
                               v_sum_achuz_kizba_sheer_chuka / 100)) -
                               --20-07-2026 כאשר הפחתנו אחוז מקסימלי, לא נוריד שוב חפיפה
                          case when  v_sum_achuz_kizba_sheer_chuka >= 60 then
                         (v_overlapping_months / 6) else 0 end
                        else
                         t.achuz_kizba_sofi * t.chelkiyut_sofit
                      end
                   
                     when v_is_municipal = 1 and p_sug_bakasha in (8, 9) then
                      (t.achuz_kizba_chelkiyut_melea) -
                      (v_overlapping_months / 6)
                     when v_is_municipal = 0 and p_sug_bakasha in (8, 9) then
                      (t.achuz_kizba_kafuf_chelkiyut) -
                      (v_overlapping_months / 6)
                   end final_achuz_medina,
                   /*Get_maskoret_after_chelkyut(decode(t1.maskoret_maavar,
                          null,
                          t1.maskoret_kovaat,
                          t1.maskoret_maavar),
                   p_seq_bakasha)*/
                   
                   Get_maskoret_after_chelkyut(case
                                                 when Get_makor_maskoret_kovat_kizba(p_seq_bakasha,
                                                                                     p_sug_bakasha,
                                                                                     v_is_maanak) = 3 then
                                                  t1.maskoret_maavar
                                                 else
                                                   t1.maskoret_kovaat
                                                  --decode(v_is_maanak,0 ,t1.maskoret_kovaat,nvl(t1.maskoret_lemaanak,t1.maskoret_kovaat))
                                               end,
                                               p_seq_bakasha,
                                               p_sug_bakasha) maskoret
              from netuney_tik_mechushavim t
              left join bakasha_regila t1
                on t.seq_bakasha = t1.seq_bakasha
             where t.seq_bakasha = p_seq_bakasha
               and t.code_department = 2) base;
  
    if p_sug_bakasha in (7,23) then
      select count(*)
          into v_is_municipal
          from participation t
          join ezor_ovdim_category e
            on t.seq_guf = e.seq_ezor_ovdim
           and e.code_sug_ezor_ovdim in (3, 6)
         where t.seq_bakasha = p_seq_bakasha
           and (t.date_answer is not null);  
    
    
      select sum(case when  v_is_municipal = 1 and p_only_public = 1 then
       t.achuz_kizb_achry_hagdl_chl_mla 
       when  v_is_municipal = 1 and p_only_public = 0 then
        t.achuz_kizba_chelkiyut_melea  
       else 
         t.achuz_kizba_kafuf_chelkiyut
        end
        *
        case when p_sug_bakasha=7 then 
          1 
          else/* v_sum_achuz_kizba_sheer_chuka*/100/100 
          end)
	    -(v_overlapping_months / 6)
        into v_achuz_kizba_medin_porprtion
        from netuney_tik_mechushavim t
       where t.seq_bakasha = p_seq_bakasha
         and t.code_department = 2;
      if v_achuz_kizba_medin_porprtion < v_max_achuz_kizba * 100 then
        v_achuz_kizba_medin_porprtion := v_achuz_kizba_medina;
      end if;
      else
        v_achuz_kizba_medin_porprtion := v_achuz_kizba_medina;
    end if;
    -- Get_data_guf(p_seq_bakasha, v_temp_schum_kizba_guf, v_maskoret_kovvat_guf, v_achuz_kizba_guf);
  end;
  ---------------------------------------------
  function is_the_salary_up_70(p_seq_bakasha             number,
                               p_sug_bakasha             number,
                               p_is_maanak               number,
                               v_achuz_kizba_medina      number,
                               v_temp_schum_kizba_medina number,
                               v_temp_schum_kizba_guf    number)
  
   return number is
    v_kovvat number;
    v_tikra  number;
  v_arai number;
  v_dmi_nihul   number;
  begin
  
  if p_sug_bakasha in (23) and is_municipal(p_seq_bakasha) = 0 and
       v_sum_achuz_kizba_sheer_chuka > 0 then
       v_dmi_nihul := v_temp_schum_kizba_guf*0.0175;
   end if;
  select sum(nvl(t.sum_arai,0))
  into v_arai
  from participation t
  where t.seq_bakasha = p_seq_bakasha;
  
    if p_sug_bakasha in (23) and is_municipal(p_seq_bakasha) = 1 and
       v_sum_achuz_kizba_sheer_chuka > 0 then
       --maskoret medina is after sheerim muliple
      v_kovvat := Get_maskoret_kovvat_kizba(p_seq_bakasha, p_sug_bakasha, p_is_maanak) *
                v_achuz_kizba_medina / 100 +
                --multiple by sheer percent only guf 
                v_temp_schum_kizba_guf * v_sum_achuz_kizba_sheer_chuka / 100;
    else
      v_kovvat := Get_maskoret_kovvat_kizba(p_seq_bakasha, p_sug_bakasha, p_is_maanak) *
                v_achuz_kizba_medina / 100 + v_temp_schum_kizba_guf-v_arai-nvl(v_dmi_nihul,0);
        
        if p_sug_bakasha in (9) and (is_municipal(p_seq_bakasha) = 1 or Get_makor_maskoret_kovat_kizba(p_seq_bakasha,p_sug_bakasha,p_is_maanak)=2) and
           v_sum_achuz_kizba_sheer_chuka > 0 then
          v_kovvat := v_kovvat * v_sum_achuz_kizba_sheer_chuka / 100;
        end if;
    
    end if;
    v_tikra := Get_maskoret_kovvat_tikra(p_seq_bakasha,
                                         p_sug_bakasha,
                                         p_is_maanak) * v_max_achuz_kizba;
    if v_kovvat >
       Get_maskoret_kovvat_tikra(p_seq_bakasha, p_sug_bakasha, p_is_maanak) *
       v_max_achuz_kizba then
      return 1;
    else
      return 0;
    end if;
  end;
  --------------------------------------------
  function is_salary_complete(p_seq_guf                number,
                              p_maskoret_kovvat_medina number,
                              p_maskoret_kovvat_guf    number) return number is
    v_is_keren number;
  begin
    select case
             when t.code_sug_ezor_ovdim = 5 then
              1
             else
              0
           end
      into v_is_keren
      from ezor_ovdim_category t
     where t.seq_ezor_ovdim = p_seq_guf
       and t.code_sug_ezor_ovdim in (3, 5, 6);
  
    if v_is_keren = 1 and p_maskoret_kovvat_guf > p_maskoret_kovvat_medina then
      return 1;
    else
      return 0;
    end if;
  end;
  --------------------------------------------
  /*function Get_final_achuz_kizba(p_seq_bakasha number,
  p_sug_bakasha number) return number is*/ --7
  procedure Get_final_achuz_kizba(p_seq_bakasha              number,
                                  p_sug_bakasha              number,
                                  v_achuz_kizba_medina       out number,
                                  v_achuz_fixed              out number,
                                  v_achuz_yachasi            out number,
                                  v_achuz_kizba_guf          out number,
                                  v_achuz_fixed_guf          out number,
                                  v_achuz_yachasi_guf        out number,
                                  v_tkufot_overlapping_kizba number) is
    v_temp_schum_kizba_medina number;
    v_temp_schum_kizba_guf    number;
    v_maskoret_kovvat_medina  number;
    v_maskoret_kovvat_guf     number;
    v_total_achuz_kizba_gufim number;
    v_total_achuz             number;
    v_maskoret_maavar         number;
    v_seq_guf                 number;
    v_is_muncipal             number;
    v_chodshey_maanak              number;
    v_chelkiyut_meshuklelet_sherut number;
    v_schum_maanak_baguf           number;
    v_achuz_kizba_guf_lmaanak      number;
    v_is_exists_guf_iria           number;
    v_is_the_salary_up_70          number;
    v_sum_participation            number;
    v_code_group_prisha            number;
    v_achuz_kizba_medin_porprtion  number;
    v_achuz_kizba_medin_orginaly  number;
    v_overlap_percent              number;
  v_sum_arai                       number;
  v_achuz_kizba_sofi               number;
  begin
    --Get data for medina and guf
    Get_data_for_medina(p_seq_bakasha,
                        p_sug_bakasha, --7
                        v_temp_schum_kizba_medina,
                        v_maskoret_kovvat_medina,
                        v_achuz_kizba_medina,
                        v_achuz_kizba_medin_porprtion,
                        1);
    v_achuz_kizba_medin_orginaly :=  v_achuz_kizba_medina;
  
    Get_data_guf(p_seq_bakasha,
                 v_temp_schum_kizba_guf,
                 v_maskoret_kovvat_guf,
                 v_achuz_kizba_guf,
                 v_seq_guf,
                 v_chodshey_maanak,
                 v_schum_maanak_baguf,
                 0);
  
    v_is_muncipal := is_municipal(p_seq_bakasha);
    
    
    --  the salary up 70
  
    v_is_the_salary_up_70 := is_the_salary_up_70(p_seq_bakasha,
                                                 p_sug_bakasha, --7
                                                 0,
                                                 v_achuz_kizba_medina,
                                                 v_temp_schum_kizba_medina,
                                                 v_temp_schum_kizba_guf);
    
    if v_is_the_salary_up_70 = 1 then
    
      --פרופורציה מאחוז מלא ולא סופי אם גדול מאחוז מקסימלי
    
      
      if p_sug_bakasha in (8, 9) then
        --leguf --
        if v_is_muncipal = 1 then
          if v_maskoret_kovvat_medina >= v_maskoret_kovvat_guf then
            --paragraph 6: Maskoret medina is equal maskoret guf.
            if Get_makor_maskoret_kovat_kizba(p_seq_bakasha,
                                              p_sug_bakasha,
                                              0) = 3 then
              v_achuz_fixed_guf := v_achuz_kizba_guf *
                                   v_maskoret_kovvat_guf /
                                   v_maskoret_kovvat_medina; 
            
              v_total_achuz := v_achuz_kizba_medina + v_achuz_fixed_guf;
            else
              v_total_achuz := v_achuz_kizba_medina + v_achuz_kizba_guf;
            end if;
            
          
            v_achuz_kizba_medina := v_achuz_kizba_medina *
                                    v_max_achuz_kizba / v_total_achuz * 100;
          
          else
            v_achuz_fixed := v_achuz_kizba_medina *
                             v_maskoret_kovvat_medina /
                             v_maskoret_kovvat_guf;
          
            v_achuz_yachasi      := (v_achuz_fixed * v_max_achuz_kizba) * 100 /
                                    (v_achuz_fixed + v_achuz_kizba_guf);
            v_achuz_kizba_medina := v_achuz_yachasi * v_maskoret_kovvat_guf /
                                    v_maskoret_kovvat_medina;
          
            
          end if;
        end if;
        if v_is_muncipal = 0 then
          if is_salary_complete(v_seq_guf,
                                v_maskoret_kovvat_medina,
                                v_maskoret_kovvat_guf) = 1 then
            --paragraph 7: Maskoret medina is different than maskoret guf
            --when guf is keren
            -- if v_is_muncipal = 0 then
            v_achuz_kizba_medina := ((Get_maskoret_kovvat_tikra(p_seq_bakasha,
                                                                p_sug_bakasha,
                                                                0) *
                                    v_max_achuz_kizba * 100) -
                                    (Get_maskoret_kovvat_tikra(p_seq_bakasha,
                                                                p_sug_bakasha,
                                                                0) *
                                    v_achuz_kizba_guf)) /
                                    v_maskoret_kovvat_medina;
                 
                                    
          else
            if v_seq_guf = 10153 or Get_makor_maskoret_kovat_kizba(p_seq_bakasha,p_sug_bakasha,0)=3 then --תעש השלמה השאר פרפורציה
           v_achuz_kizba_medina := ((Get_maskoret_kovvat_tikra(p_seq_bakasha,
                                                                p_sug_bakasha,
                                                                0) *
                                    v_max_achuz_kizba * 100) -
                                    (v_maskoret_kovvat_guf *
                                    v_achuz_kizba_guf)) /
                                    (Get_maskoret_kovvat_kizba(p_seq_bakasha,
                                                               p_sug_bakasha,
                                                               0));
            else                                                   
            v_achuz_fixed := v_achuz_kizba_medina;
          
            v_achuz_yachasi      := (v_achuz_fixed * v_max_achuz_kizba) * 100 /
                                    (v_achuz_fixed + v_achuz_kizba_guf);
            v_achuz_kizba_medina := v_achuz_yachasi;                                                     
            end if;                                                   
            /*old calculation
            v_achuz_fixed := v_achuz_kizba_medina *
                             v_maskoret_kovvat_medina /
                             v_maskoret_kovvat_guf;
            
            v_achuz_yachasi      := (v_achuz_fixed * v_max_achuz_kizba) * 100 /
                                    (v_achuz_fixed + v_achuz_kizba_guf);
            v_achuz_kizba_medina := v_achuz_yachasi * v_maskoret_kovvat_guf /
                                    v_maskoret_kovvat_medina;*/
          
            --Ask dvora what to do in else...
          end if;
        end if;
        --when guf is public
      
      elsif p_sug_bakasha in (7, 23) then
        --meguf--7
        -- when participation from guf - the percent must always be multiplied by partial period
        --v_achuz_kizba_medina := v_achuz_kizba_medina * v_chelkiyut_meshuklelet_sherut;
        select count(*)
          into v_is_exists_guf_iria
          from participation t
          join ezor_ovdim_category e
            on t.seq_guf = e.seq_ezor_ovdim
           and e.code_sug_ezor_ovdim in (3, 6)
         where t.seq_bakasha = p_seq_bakasha
           and (t.date_answer is not null);
        if v_is_exists_guf_iria > 0 then
        
          if v_maskoret_kovvat_medina = v_maskoret_kovvat_guf then
            v_total_achuz := v_achuz_kizba_medin_porprtion +
                             v_achuz_kizba_guf;
          
            v_achuz_kizba_medina := v_achuz_kizba_medin_porprtion *
                                    v_max_achuz_kizba / v_total_achuz * 100;
          elsif v_maskoret_kovvat_medina > v_maskoret_kovvat_guf then
          
            v_achuz_fixed_guf := v_achuz_kizba_guf * v_maskoret_kovvat_guf /
                                 v_maskoret_kovvat_medina; --p --METUKAN
          
            v_total_achuz := v_achuz_kizba_medin_porprtion +
                             v_achuz_fixed_guf;
          
            v_achuz_kizba_medina := v_achuz_kizba_medin_porprtion *
                                    v_max_achuz_kizba / v_total_achuz * 100;
          
          end if;
          elsif p_sug_bakasha=23 then
                   --19/05/2025 הורדת ארעי מחישוב עובר 70
                   --**********
            select sum(schum_arai_guf)
              into v_sum_arai
              from (select round(round((nvl(t.chodshey_arai, 0) / 6), 2) *
                                 nvl(t.maskoret_arai, 0) / 100,
                                 2) schum_arai_guf
                      from participation t
                     where t.seq_bakasha = p_seq_bakasha
                       and (t.date_answer is not null));
                       ---**************************
            v_achuz_kizba_medina := (((Get_maskoret_kovvat_tikra(p_seq_bakasha,
                                                                p_sug_bakasha,
                                                                0) *
                                    v_max_achuz_kizba) -
                                   (v_temp_schum_kizba_guf
                                   -v_temp_schum_kizba_guf*0.0175
                                   -nvl(v_sum_arai,0))) /
                                    v_maskoret_kovvat_medina)*100;
          v_sum_arai := 0;
          end if;
      
        for r in (select t.percent_participate,
                         GetSumGuf(t.seq_participation, 0) as sum,
                         t.seq_guf,
                         t.partial_period,
                         t.seq_participation,
                         t1.code_sug_ezor_ovdim,
                         t.chodshey_arai,
                         t.sum_participation
                    from participation t
                    left join ezor_ovdim_category t1
                      on t.seq_guf = t1.seq_ezor_ovdim
                     and t1.code_sug_ezor_ovdim in (3, 5, 6)
                   where t.seq_bakasha = p_seq_bakasha
                     and (t.date_answer is not null)) loop
        
          if v_maskoret_kovvat_medina = r.sum then
            if r.code_sug_ezor_ovdim <> 5 then
              update participation t
                 set t.achuz_guf_final = round((r.percent_participate *
                                               v_max_achuz_kizba /
                                               v_total_achuz * 100),
                                               2),
                     t.achuz_rezifut   = round((r.percent_participate *
                                               v_max_achuz_kizba /
                                               v_total_achuz * 100),
                                               2)
               where t.seq_participation = r.seq_participation;
              /*commit;*/
            
            end if;
          end if;
          if v_maskoret_kovvat_medina > r.sum then
            if r.code_sug_ezor_ovdim <> 5 then
              v_achuz_fixed_guf   := (r.percent_participate) * r.sum /
                                     v_maskoret_kovvat_medina;
              v_achuz_yachasi_guf := v_achuz_fixed_guf * v_max_achuz_kizba /
                                     v_total_achuz * 100; --p --YECHASI
            
              v_achuz_kizba_guf := v_maskoret_kovvat_medina *
                                   v_achuz_yachasi_guf / r.sum;
            end if;
            if r.code_sug_ezor_ovdim = 5 then
            
              if v_sum_participation is null and
                 v_maskoret_kovvat_medina <> v_maskoret_kovvat_guf then
                v_sum_participation := r.percent_participate * r.sum;
              end if;
              v_achuz_fixed_guf   := 0;
              v_achuz_yachasi_guf := 0;
              v_achuz_kizba_guf   := r.percent_participate;
            
            end if;
            update participation t
               set t.achuz_guf_final   = round(v_achuz_kizba_guf, 2),
                   t.achuz_guf_fixed   = round(v_achuz_fixed_guf, 2),
                   t.achuz_guf_yachasi = round(v_achuz_yachasi_guf, 2),
                   t.achuz_rezifut     = round(v_achuz_kizba_guf, 2)
             where t.seq_participation = r.seq_participation;
            /*commit;*/
          end if;
          /*if nvl(r.chodshey_arai, 0) > 0 then
          update participation t
             set t.achuz_arai    = round((nvl(r.chodshey_arai, 0) / 6), 2),
                 t.achuz_rezifut = greatest(v_achuz_kizba_guf -
                                            round((nvl(r.chodshey_arai, 0) / 6),
                                                  2),
                                            0)
           where t.seq_participation = r.seq_participation;*/
        /*commit;*/
        /*end if;*/
        end loop;
      
      end if; --7 end
    end if;
    ----arai 
    for r in (select t.percent_participate,
                     t.seq_participation,
                     t1.code_sug_ezor_ovdim,
                     t.chodshey_arai,
                     b.maskoret_kovaat,
                     t.sum_arai,
                     t.maskoret_arai
                from participation t
                left join ezor_ovdim_category t1
                  on t.seq_guf = t1.seq_ezor_ovdim
				  and t1.code_sug_ezor_ovdim in (3, 5, 6)
                left join bakasha_regila b
                  on t.seq_bakasha = b.seq_bakasha
                 
               where t.seq_bakasha = p_seq_bakasha
                 and (t.date_answer is not null or p_sug_bakasha in (8, 9))) loop
      --arai
      if nvl(r.chodshey_arai, 0) > 0 then
        if nvl(r.sum_arai ,0) = 0 or p_sug_bakasha <> 23 then
          v_sum_arai:=round(round((nvl(r.chodshey_arai, 0) / 6),
                                             2) * nvl(r.maskoret_arai, 0) / 100,
                                       2);
                                       else
            v_sum_arai := r.sum_arai;
            end if;                             
        update participation t
           set t.achuz_arai    = round((nvl(r.chodshey_arai, 0) / 6), 2),
               t.sum_arai      = v_sum_arai,
               t.achuz_rezifut = greatest(r.percent_participate -
                                          round((nvl(r.chodshey_arai, 0) / 6),
                                                2),
                                          0)
         where t.seq_participation = r.seq_participation;
        /*commit;*/
      else
        update participation t
           set t.achuz_arai    = null,
               t.achuz_rezifut = null,
               t.sum_arai      = null
         where t.seq_participation = r.seq_participation;
        /*commit;*/
      end if;
    
   
      if p_sug_bakasha in (7, 23)  then
        for r1 in (select t.percent_participate,
                         t.seq_participation,
                         t1.code_sug_ezor_ovdim,
                         t.chodshey_arai,
                         t.sum,
                         t.achuz_guf_final
                    from participation t
                    left join ezor_ovdim_category t1
                      on t.seq_guf = t1.seq_ezor_ovdim
                     and t1.code_sug_ezor_ovdim in (3, 5, 6)
                   where t.seq_participation=r.seq_participation) loop
          update participation t

             set t.achuz_guf_final = case when v_is_the_salary_up_70 = 0 or (v_maskoret_kovvat_medina <= r1.sum and r1.code_sug_ezor_ovdim = 5)then r1.percent_participate else r1.achuz_guf_final end
             -
                                     round((nvl(r1.chodshey_arai, 0) / 6), 2)
           where t.seq_participation = r1.seq_participation;
        
        end loop;
      end if;
    
      --     sum_participation
      if p_sug_bakasha <> 23 or r.code_sug_ezor_ovdim <> 5 then
      
        --------------------------temp by rivka 01/06/2020
        --Restart anyway, also when  r.maskoret_kovaat = t.sum
        update participation t
           set t.sum_participation = null
         where t.seq_participation = r.seq_participation;
        -------------------------- End by rivka 01/06/2020
      
        update participation t
           set t.sum_participation = greatest(round(t.sum *
                                                    decode(nvl(t.achuz_rezifut,
                                                               0),
                                                           0,
                                                           t.achuz_guf_final,
                                                           t.achuz_rezifut) * 0.01 *
                                                    t.partial_period,
                                                    2),
                                              0)
         where t.seq_participation = r.seq_participation
           and r.maskoret_kovaat <> t.sum;
      end if;
    end loop;
  
    select case
             when p_sug_bakasha in (7, 23) then
              t.chelkiyut_sofit
             else
              t.chelkiyut_meshuklelet_sherut
           end
      into v_chelkiyut_meshuklelet_sherut
      from netuney_tik_mechushavim t
     where t.seq_bakasha = p_seq_bakasha
       and t.code_department = 2;
  
    if (v_is_muncipal = 1 and v_chelkiyut_meshuklelet_sherut < 1 or
       p_sug_bakasha in (7, 23)) then
      v_achuz_kizba_medina := v_achuz_kizba_medina /
                              v_chelkiyut_meshuklelet_sherut;
    
    end if;
    --sheerim or nechut - not round!!
    select t.code_group_prisha
      into v_code_group_prisha
      from netuney_tik_mechushavim t
     where t.seq_bakasha = p_seq_bakasha
       and t.code_department = 2
       and t.mispar_misra = 0;
  
    if v_is_the_salary_up_70 = 0 and
       (p_sug_bakasha = 8 or p_sug_bakasha = 7 and v_code_group_prisha <> 2) /*and nvl(v_tkufot_overlapping_kizba, 0) > 0 */
     then
       
      v_achuz_kizba_medina := round_percent_by_months(round(v_achuz_kizba_medina,
                                                            2));
    end if;
    
   
  
    --return greatest(v_achuz_kizba_medina, 0); --7
    v_achuz_kizba_medina := greatest(v_achuz_kizba_medina, 0); --7
  end;
  ---------------------------------------------
  /*function Get_schum_kizba(p_seq_bakasha number) return number is
  begin
    return Get_maskoret_kovvat_kizba(p_seq_bakasha) * get_final_achuz_kizba(p_seq_bakasha) / 100;
  end;*/ --7
  ---------------------------------------------
  function Is_zakai_lmaanak(p_seq_bakasha number, p_sug_bakasha number)
    return number is
    v_age                         number;
    v_seif_prisha                 number;
    v_sug_ezor_ovdim              number;
    v_is_the_salary_up_70         number;
    v_temp_schum_kizba_medina     number;
    v_temp_schum_kizba_guf        number;
    v_maskoret_kovvat_medina      number;
    v_maskoret_kovvat_guf         number;
    v_achuz_kizba_medina          number;
    v_achuz_kizba_guf             number;
    v_seq_guf                     number;
    v_overlapping_months          number;
    v_tkufa_mezaka_guf            number;
    v_tkufa_mezaka_medina         number;
    v_is_muncipal                 number;
    v_monthes                     number;
    v_chodshey_maanak             number;
    v_sub_seif_prisha             number;
    v_schum_maanak_baguf          number;
    v_achuz_kizba_guf_lmaanak     number;
    v_min_age                     number;
    v_chelkiyut_meshuklelet_fake  number;
    v_achuz_kizba_fake            number;
    v_achuz_kizba_medin_porprtion number;
  begin
  
    --restart participation maanak fields
    /* update participation t
      set t.odef_sherut_baguf = null, t.schum_maanak_baguf = null
    where t.seq_bakasha = p_seq_bakasha;*/
  
    select months_between(v.TAARICH_PRISHA, p.taarich_leda) / 12,
           v.CODE_SEIF_PRISHA,
           r.code_sub_seif_prisha,
           case
             when r.chinuch_mikzoa = 911 then
              59
             else
              60
           end
      into v_age, v_seif_prisha, v_sub_seif_prisha, v_min_age
      from v_bakasha_last_status v
      left join poresh p
        on v.SEQ_PORSHIM = p.porshim_seq
      left join bakasha_regila r
        on v.seq_bakasha = r.seq_bakasha
     where v.SEQ_BAKASHA = p_seq_bakasha;
  
    select code_sug_ezor_ovdim
      into v_sug_ezor_ovdim
      from (select e.code_sug_ezor_ovdim
              from participation p
              left join ezor_ovdim_category e
                on p.seq_guf = e.seq_ezor_ovdim
               and e.code_sug_ezor_ovdim in (3, 5, 6)
             where p.seq_bakasha = p_seq_bakasha
               and (p.code_participation = 1 or p_sug_bakasha in (7, 23))
               and (p.date_answer is not null or p_sug_bakasha in (8, 9)))
     where rownum = 1;
  
    --Get data for medina and guf
    Get_data_for_medina(p_seq_bakasha,
                        p_sug_bakasha, --7
                        v_temp_schum_kizba_medina,
                        v_maskoret_kovvat_medina,
                        v_achuz_kizba_medina,
                        v_achuz_kizba_medin_porprtion,
                        0);
    Get_data_guf(p_seq_bakasha,
                 v_temp_schum_kizba_guf,
                 v_maskoret_kovvat_guf,
                 v_achuz_kizba_guf,
                 v_seq_guf,
                 v_chodshey_maanak,
                 v_schum_maanak_baguf,
                 0,
                 1);
  
    v_is_the_salary_up_70 := is_the_salary_up_70(p_seq_bakasha,
                                                 p_sug_bakasha, --7
                                                 0,
                                                 v_achuz_kizba_medina,
                                                 v_temp_schum_kizba_medina,
                                                 v_temp_schum_kizba_guf);
  
    v_overlapping_months := Get_overlapping_months(p_seq_bakasha,
                                                   p_sug_bakasha,
                                                   1);
  
    v_is_muncipal := is_municipal(p_seq_bakasha);
  
    pk_zakaut.calc_data_tkufa_mezaka(p_seq_bakasha,
                                     3,
                                     v_chelkiyut_meshuklelet_fake,
                                     v_achuz_kizba_fake,
                                     v_tkufa_mezaka_medina);
    v_tkufa_mezaka_medina := round(v_tkufa_mezaka_medina);
  
    select v_tkufa_mezaka_medina * case
             when p_sug_bakasha in (7, 23) then
              t.chelkiyut_sofit
             when v_is_muncipal = 1 then
              t.chelkiyut_meshuklelet_sherut
             else
              1
           end
      into v_tkufa_mezaka_medina
      from netuney_tik_mechushavim t
     where t.seq_bakasha = p_seq_bakasha
       and t.code_department = 2;
  
    select nvl(sum(p.chodshey_maanak * p.partial_period), 0)
      into v_tkufa_mezaka_guf
      from participation p
     where p.seq_bakasha = p_seq_bakasha
       and (p.date_answer is not null or p_sug_bakasha in (8, 9));
    v_monthes := ((((v_tkufa_mezaka_medina - v_overlapping_months) *
                 Get_maskoret_kovvat_kizba(p_seq_bakasha,
                                              p_sug_bakasha,
                                              0) +
                 (v_tkufa_mezaka_guf) * v_maskoret_kovvat_guf) /
                 Get_maskoret_kovvat_tikra(p_seq_bakasha,
                                             p_sug_bakasha,
                                             0)));
  
    --Check if the age up 60 and  the salary up 70 and more then 420 monthes by terms
    if v_age > v_min_age and v_is_the_salary_up_70 = 1 and v_monthes > 420 and
      --if it's 'kapam' (seif prisha is health and sug_ezor_ovdim is 'keren vatika')- is not get maanak
       (v_sub_seif_prisha <> 990 or v_sub_seif_prisha is null) then
      return 1;
    else
    
      --restart participation maanak fields
      for r in (select t.seq_participation
                  from participation t
                  left join v_bakasha_last_status t1
                    on t.seq_bakasha = t1.seq_bakasha
                  left join ezor_ovdim_category e
                    on t.seq_guf = e.seq_ezor_ovdim
                   and e.code_sug_ezor_ovdim in (3, 5, 6)
                 where t.seq_bakasha = p_seq_bakasha
                   and (t1.code_sug_bakasha not in (7, 23) or
                       e.code_sug_ezor_ovdim <> 5)) loop
        update participation t
           set t.odef_sherut_baguf = null, t.schum_maanak_baguf = null
         where t.seq_participation = r.seq_participation;
      end loop;
      return 0;
    end if;
  end;
  ---------------------------------------------
  function Calc_schum_maanak(p_seq_bakasha         number,
                             p_sug_bakasha         number,
                             v_months_pizuy_medina out number,
                             v_achuz_pizuy_medina  out number, --7
                             v_months_pizuy_guf    out number,
                             v_schum_pizuy_guf     out number) return number is
    v_mikdmat_yoker                number;
    v_is_the_salary_up_70          number;
    v_temp_schum_kizba_medina      number;
    v_temp_schum_kizba_guf         number;
    v_maskoret_kovvat_medina       number;
    v_maskoret_kovvat_guf          number;
    v_achuz_kizba_medina           number;
    v_achuz_kizba_guf              number;
    v_months_pizuy                 number;
    v_tkufa_mezaka_medina          number;
    v_mskrt_multi_tkfa_mezaka_guf  number;
    v_tkufa_mezaka_guf             number;
    v_is_muncipal                  number;
    v_overlapping_months           number;
    v_seq_guf                      number;
    v_chodshey_maanak              number;
    v_chelkiyut_meshuklelet_sherut number;
    v_schum_pizuy_medina           number;
    v_schum_kizba_medina           number;
    v_independent_month            number;
    v_achuz_kizba_guf_lmaanak      number;
    v_code_sug_ezor_ovdim          number;
    v_is_overlap_from_guf          number;
    v_makor_maskoret               number;
    v_chelkiyut_meshuklelet_fake   number;
    v_achuz_kizba_fake             number;
    v_achuz_kizba_medin_porprtion  number;
  begin
  
    --Get data for medina and guf
    Get_data_for_medina(p_seq_bakasha,
                        p_sug_bakasha, --7
                        v_temp_schum_kizba_medina,
                        v_maskoret_kovvat_medina,
                        v_achuz_kizba_medina,
                        v_achuz_kizba_medin_porprtion,
                        0);
    Get_data_guf(p_seq_bakasha,
                 v_temp_schum_kizba_guf,
                 v_maskoret_kovvat_guf,
                 v_achuz_kizba_guf,
                 v_seq_guf,
                 v_chodshey_maanak,
                 v_schum_pizuy_guf,
                 0,
                 1);
  
    -- v_chodshey_maanak := v_chodshey_maanak - nvl(v_chodshey_maanak,0);
  
    v_is_the_salary_up_70 := is_the_salary_up_70(p_seq_bakasha,
                                                 p_sug_bakasha, --7
                                                 0,
                                                 v_achuz_kizba_medina,
                                                 v_temp_schum_kizba_medina,
                                                 v_temp_schum_kizba_guf);
    if v_is_the_salary_up_70 = 0 then
      return 0;
    else
    
      v_is_muncipal := is_municipal(p_seq_bakasha);
    
      pk_zakaut.calc_data_tkufa_mezaka(p_seq_bakasha,
                                       3,
                                       v_chelkiyut_meshuklelet_fake,
                                       v_achuz_kizba_fake,
                                       v_tkufa_mezaka_medina);
      v_tkufa_mezaka_medina := round(v_tkufa_mezaka_medina);
      select v_tkufa_mezaka_medina * case
               when v_is_muncipal = 1 or p_sug_bakasha in (7, 23) then
                t.chelkiyut_meshuklelet_sherut
               else
                1
             end,
             
             chelkiyut_meshuklelet_sherut
        into v_tkufa_mezaka_medina, v_chelkiyut_meshuklelet_sherut
        from netuney_tik_mechushavim t
       where t.seq_bakasha = p_seq_bakasha
         and t.code_department = 2;
    
      v_overlapping_months := Get_overlapping_months(p_seq_bakasha,
                                                     p_sug_bakasha,
                                                     0);
    
      v_is_overlap_from_guf := is_overlap_from_guf(p_seq_bakasha);
    
      if v_is_overlap_from_guf = 1 then
        v_overlapping_months := v_overlapping_months *
                                v_maskoret_kovvat_guf /
                                Get_maskoret_kovvat_kizba(p_seq_bakasha,
                                                          p_sug_bakasha,
                                                          0);
      end if;
      select nvl(sum(p.chodshey_maanak *
                     GetSumGuf(p.seq_participation, 0, 0) *
                     p.partial_period),
                 0),
             nvl(sum(p.chodshey_maanak * p.partial_period), 0)
        into v_mskrt_multi_tkfa_mezaka_guf, v_tkufa_mezaka_guf
        from participation p
       where p.seq_bakasha = p_seq_bakasha
         and (p.date_answer is not null or p_sug_bakasha in (8, 9));
    
      if p_sug_bakasha in (8, 9) then
        v_makor_maskoret := Get_makor_maskoret_kovat_kizba(p_seq_bakasha,
                                                           p_sug_bakasha,
                                                           0);
        if v_makor_maskoret <> 2 then
           select nvl(b.mikdmat_yoker, 0) * case
                  when is_municipal(p_seq_bakasha) = 1 then
                   1
                  else
                   v_chelkiyut_meshuklelet_sherut
                end
           into v_mikdmat_yoker
           from bakasha_regila b
          where b.seq_bakasha = p_seq_bakasha;
--          v_mikdmat_yoker := 0;
        elsif v_makor_maskoret = 2 then
          select nvl(b.mikdemet_yoker_guf, 0)
            into v_mikdmat_yoker
            from participation b
           where b.seq_bakasha = p_seq_bakasha
             and b.code_participation = 1;
        end if;
      else
        select case when b.maskoret_kovaat = b.maskoret_lemaanak or nvl(b.maskoret_lemaanak,0) = 0 then nvl(b.mikdmat_yoker, 0) else 0 end
          into v_mikdmat_yoker
          from bakasha_regila b
         where b.seq_bakasha = p_seq_bakasha;
      end if;
      /*v_months_pizuy := v_achuz_kizba_medina * v_tkufa_mezaka_medina  /
      (v_tkufa_mezaka_medina + v_tkufa_mezaka_guf);*/
    
      v_months_pizuy := (((v_tkufa_mezaka_medina - v_overlapping_months) *
                        Get_maskoret_kovvat_kizba(p_seq_bakasha,
                                                    p_sug_bakasha,
                                                    0) +
                        v_mskrt_multi_tkfa_mezaka_guf) /
                        Get_maskoret_kovvat_tikra(p_seq_bakasha,
                                                   p_sug_bakasha,
                                                   0)) - 420;
    
      v_months_pizuy_medina := round((v_months_pizuy *
                                     (v_tkufa_mezaka_medina)) /
                                     (v_tkufa_mezaka_medina +
                                     v_tkufa_mezaka_guf),
                                     2);
    
      v_achuz_pizuy_medina := v_months_pizuy_medina / 6;
    
      if p_sug_bakasha in (7, 23) then
      
        for r in (select t.percent_participate,
                         GetSumGuf(t.seq_participation, 1, 0) as sum,
                         t.seq_guf,
                         t.chodshey_maanak,
                         t.seq_participation,
                         t1.code_sug_ezor_ovdim,
                         t.schum_maanak_baguf,
                         t.partial_period,
                         t.mikdemet_yoker_guf,
                         t.maskoret_maanak
                    from participation t
                    left join ezor_ovdim_category t1
                      on t.seq_guf = t1.seq_ezor_ovdim
                     and t1.code_sug_ezor_ovdim in (3, 5, 6)
                   where t.seq_bakasha = p_seq_bakasha
                     and (t.date_answer is not null)) loop
        
          v_months_pizuy_guf := round((v_months_pizuy * (r.chodshey_maanak *
                                      r.partial_period)) /
                                      (v_tkufa_mezaka_medina +
                                      v_tkufa_mezaka_guf),
                                      2);
        
          if /*nvl(r.schum_maanak_baguf, 0) <= 0 and*/
           r.code_sug_ezor_ovdim in (3, 6) then
            --if v_maskoret_kovvat_guf <> v_maskoret_kovvat_medina then
              v_schum_pizuy_guf := round(greatest(v_months_pizuy_guf / 12 *
                                                  (/*Get_maskoret_kovvat_maanak(p_seq_bakasha,p_sug_bakasha,1)*/r.maskoret_maanak - nvl(r.mikdemet_yoker_guf,
                                                               0)),
                                                  0),
                                         2);
            --else
              --v_schum_pizuy_guf := 0;
            --end if;
          else
            v_schum_pizuy_guf := r.schum_maanak_baguf;
          
          end if;
          update participation t
             set t.odef_sherut_baguf  = v_months_pizuy_guf,
                 t.schum_maanak_baguf = v_schum_pizuy_guf
           where t.seq_participation = r.seq_participation;
          /*commit;*/
        end loop;
      end if;
      v_schum_pizuy_medina := greatest(v_months_pizuy_medina / 12 *
                                       (Get_maskoret_kovvat_maanak(p_seq_bakasha,
                                                                  p_sug_bakasha,
                                                                  1) -
                                       nvl(v_mikdmat_yoker, 0)),
                                       0);
    
      v_months_pizuy_medina := round(v_months_pizuy_medina, 2);
      v_achuz_pizuy_medina  := round(v_achuz_pizuy_medina, 2);
      v_months_pizuy_guf    := round(v_months_pizuy_guf, 2);
      v_schum_pizuy_guf     := round(v_schum_pizuy_guf, 2);
      return round(nvl(v_schum_pizuy_medina, 0), 2);
    end if;
  end;
  ---------------------------------------------
  function get_schum_maanak(p_seq_bakasha number, p_sug_bakasha number)
    return number is
    v_months_pizuy_medina number;
    v_achuz_pizuy_medina  number;
    v_is_zakay_maanak     number;
    v_months_pizuy_guf    number;
    v_schum_pizuy_guf     number;
  begin
    v_is_zakay_maanak := Is_zakai_lmaanak(p_seq_bakasha, p_sug_bakasha);
    if v_is_zakay_maanak = 1 then
      return Calc_schum_maanak(p_seq_bakasha,
                               p_sug_bakasha, --7
                               v_months_pizuy_medina,
                               v_achuz_pizuy_medina,
                               v_months_pizuy_guf,
                               v_schum_pizuy_guf);
    else
      return 0;
    end if;
  end;

  ------------------------------------------------
  function get_mikdemet_yoker(p_seq_bakasha number, p_sug_bakasha number)
    return number is
    v_maskoert       number;
    v_mikdemet_yoker number;
    p_maskoret_guf   number;
  begin
  
    select case
             when b.maskoret_maavar is not null then
              Get_maskoret_after_chelkyut(b.maskoret_maavar,
                                          p_seq_bakasha,
                                          p_sug_bakasha)
           --chinuch azmai allways p.sum
             when p.seq_guf = 10465 then
              Get_maskoret_after_chelkyut(p.sum,
                                          p_seq_bakasha,
                                          p_sug_bakasha)
             else
              Get_maskoret_after_chelkyut(b.maskoret_kovaat,
                                          p_seq_bakasha,
                                          p_sug_bakasha)
           end as maskoret,
           GetSumGuf(p.seq_participation, 1, 0),
           nvl(b.mikdmat_yoker, 0)
      into v_maskoert, p_maskoret_guf, v_mikdemet_yoker
      from participation p
      left join bakasha_regila b
        on b.seq_bakasha = p.seq_bakasha
     where b.seq_bakasha = p_seq_bakasha
       and (p.date_answer is not null or p_sug_bakasha in (8, 9));
  
    if p_maskoret_guf < v_maskoert then
      return 0;
    else
      return v_mikdemet_yoker;
    end if;
  end;
  ---------------------------------------------------------------
  ---------------------------------------------------------------
  function Get_Tashlum_Retro(p_seq_bakasha number, p_begin_chodesh date)
    return number is
    tashlum_retro      number := 0;
    v_code_sug_bakasha number;
    v_begin_chodesh    date;
    v_seq_guf          number;
  begin
    select b.code_sug_bakasha
      into v_code_sug_bakasha
      from bakasha b
     where b.seq_bakasha = p_seq_bakasha;
     select t.seq_guf
     into v_seq_guf
     from participation t
     where t.seq_bakasha=p_seq_bakasha
     fetch first 1 rows only;
     
     
    select round((nvl(t1.schum_kizba, 0) - nvl(t2.schum_kizba, 0)) *
                 months_between(p_begin_chodesh,nvl(t1.date_start_zakaut, pr.date_payment)),
                 2)
      into tashlum_retro
      from netuney_tik_mechushavim t1
    
      left join participation pr
        on t1.seq_bakasha = pr.seq_bakasha
        
       and pr.code_participation = 1
       and pr.date_payment is not null
       left join bakasha bk
      on t1.seq_bakasha=bk.seq_bakasha  
      left join action_log c
        on c.seq_bakasha = p_seq_bakasha
       and c.code_action = 42,
     (select sum(t.schum_kizba) schum_kizba, max(t.date_end_zakaut)
              from netuney_tik_mechushavim t
             where t.seq_bakasha =
                  --get prev seq_bakasha
                   (select max(b2.seq_bakasha)
                      from bakasha b1
                      left join v_bakasha_last_status b2
                        on b2.seq_prisha = b1.seq_prisha
                       and b2.seq_bakasha < b1.seq_bakasha
                       and b2.code_sug_bakasha = v_code_sug_bakasha
                       and b2.code_action<>17
                     where b1.seq_bakasha = p_seq_bakasha)
               and t.code_department = 2
               and (t.date_end_zakaut is null or
                   t.date_end_zakaut > p_begin_chodesh)) t2
     where t1.seq_bakasha = p_seq_bakasha
       and t1.code_department = 2
          --The bakasha was not in action 'payment' - 'shulam'
       
       and c.seq_action_log is null
       --no bakashat hazmada
       and nvl(bk.code_bakasha_detail,0) not in(192,193)
          --Get only positive sum
       and nvl(t1.schum_kizba, 0) - nvl(t2.schum_kizba, 0) > 0;
  
    return nvl(tashlum_retro, 0);
  
  EXCEPTION
    WHEN others THEN
      return 0;
    
  end Get_Tashlum_Retro;
  -----------------------------------------------------------------------
  function round_percent_by_months(p_percent number) return number is
    v_md_percent number;
    v_percent    number;
  begin
    v_percent    := round(p_percent, 2);
    v_md_percent := mod(v_percent, 2);
    if v_md_percent not in (0, 2) then
      --Round 
      select v_percent - v_md_percent + i.achuz_meugal
        into v_percent
        from igul_chodashim i
       where v_md_percent between i.from_achuz and i.to_achuz;
    end if;
  
    v_percent := round(v_percent, 2);
    return v_percent;
  end;
  ------------------------------------------------------------
  function ht_get_maanak(p_seq_bakasha number) return number is
    v_sum_maanak number;
  
  begin
  
    select round((nvl(t1.schum_maanak_pizuy, 0) -
                 nvl(t2.schum_maanak_pizuy, 0)),
                 2)
      into v_sum_maanak
      from netuney_tik_mechushavim t1
    
      left join participation pr
        on t1.seq_bakasha = pr.seq_bakasha
       and pr.code_participation = 1
       left join bakasha bk
      on t1.seq_bakasha=bk.seq_bakasha  
      left join action_log c
        on c.seq_bakasha = p_seq_bakasha
       and c.code_action = 42,
     (select sum(t.schum_maanak_pizuy) schum_maanak_pizuy
              from netuney_tik_mechushavim t
             where t.seq_bakasha =
                  --get prev seq_bakasha
                   (select max(b2.seq_bakasha)
                      from bakasha b1
                      left join v_bakasha_last_status b2
                        on b2.seq_prisha = b1.seq_prisha
                       and b2.seq_bakasha < b1.seq_bakasha
                       and b2.code_sug_bakasha in (8, 9)
                       and b2.code_action<>17
                     where b1.seq_bakasha = p_seq_bakasha
                     
                     )
               and t.code_department = 2) t2
     where t1.seq_bakasha = p_seq_bakasha
       and t1.code_department = 2
          --The bakasha was not in action 'payment' - 'shulam'
       and c.seq_action_log is null
       --no bakashat hazmada
       and nvl(bk.code_bakasha_detail,0) not in(192,193)
       --and (pr.seq_guf<>10518 or t1.date_start_zakaut<>to_date('01012023','ddmmyyyy'))
          --Get only positive sum
       and nvl(t1.schum_maanak_pizuy, 0) - nvl(t2.schum_maanak_pizuy, 0) > 0;
  
    return nvl(v_sum_maanak, 0);
  
  EXCEPTION
    WHEN others THEN
      return 0;
    
  end;
  ----------------------------------------------------------------
  function ht_get_interest_linkage(p_seq_bakasha number) return number is
    v_interest_linkage number;
  
  begin
  
    select round(nvl(t1.interest_linkage, 0), 2)
      into v_interest_linkage
      from netuney_tik_mechushavim t1
      left join participation pr
        on t1.seq_bakasha = pr.seq_bakasha
       and pr.code_participation = 1
       and pr.date_payment is not null
      left join action_log c
        on c.seq_bakasha = p_seq_bakasha
       and c.code_action = 42
     where t1.seq_bakasha = p_seq_bakasha
       and t1.code_department = 2
       
          --The bakasha was not in action 'payment' - 'shulam'
       and c.seq_action_log is null
  -- and (pr.seq_guf<>10518 or t1.date_start_zakaut<>to_date('01012023','ddmmyyyy'))
  ;
    return nvl(v_interest_linkage, 0);
  
  EXCEPTION
    WHEN others THEN
      return 0;
    
  end;
