procedure hazmadat_kitzba_guf(p_seq_guf number, p_for_month date)is
    i                            number;
  v_prev_bakasha                 number;
  v_new_bakasha                  number;
  v_seq_poresh                   number;
  v_seq_ezor_ovdim               number;
  v_seq_netuney_tik_mechushavm_n number;
  v_code_sug_bakasha             number;
  v_exists_netuney_tik           number;
begin
 --loop over bakashot
 select id_number
 into i from LD_PTRCPN_HZMD
 where rownum=1;
  dbms_output.put_line(i);  
  for z in (select t.seq_guf,
                   t.id_number,
                   replace(t.kizba,',','') as kizba,--t.kizba -----chavi
                   t.retro,
                   --t.seq,
                --   t.load_date,
                   t.from_date from LD_PTRCPN_HZMD t
                   --where t.id_number in (55969547,5295449)
                 --   where t.seq_guf in(10519,10482,13016)
    --where to_number(p_seq_guf)=t.seq_guf and to_date(t.from_date,'yyyymmdd')=p_for_month
    ) loop
    begin
      --get last participation
      select max(v.seq_bakasha) seq_bakasha,
             max(v.seq_porshim) seq_porshim,
             max(v.seq_ezor_ovdim) seq_ezor_ovdim,
             max(v.code_sug_bakasha) code_sug_bakasha
        into v_prev_bakasha,
             v_seq_poresh,
             v_seq_ezor_ovdim,
             v_code_sug_bakasha
        from participation p
        left join v_bakasha_last_status v
          on p.seq_bakasha = v.seq_bakasha
       where v.mispar_zehut = z.id_number
         and v.code_sug_bakasha in (8)
         and v.code_action = 42
         and p.code_participation = 1
         and p.seq_guf = z.seq_guf;
      if v_seq_poresh is null then
        --get_last_sheerim
        select max(v.seq_bakasha) seq_bakasha,
               max(v.seq_porshim) seq_porshim,
               max(v.seq_ezor_ovdim) seq_ezor_ovdim,
               max(v.code_sug_bakasha) code_sug_bakasha
          into v_prev_bakasha,
               v_seq_poresh,
               v_seq_ezor_ovdim,
               v_code_sug_bakasha
          from bney_mishpacha b
          join v_bakasha_last_status v
            on b.seq_porshim = v.seq_porshim
          join participation p
            on v.seq_bakasha = p.seq_bakasha
         where b.mispar_zehut_ben_mishpacha = to_number(z.id_number)
           and v.code_sug_bakasha in (9)
           and v.code_action = 42
           and p.code_participation = 1
           and p.seq_guf = z.seq_guf;
      end if;
      --create and duplicate data
      v_new_bakasha := pk_load_mimshak.Add_main_tables(v_seq_poresh,
                                                       v_seq_ezor_ovdim,
                                                       7,
                                                       v_code_sug_bakasha);
      update bakasha b set                                          
      b.code_bakasha_detail=decode( v_code_sug_bakasha,8,192,193),
      b.remarks = 'בקשה אוטומטית להצמדת סכום הקצבה בלבד'
      where b.seq_bakasha= v_new_bakasha;
       
      pk_prm_utils.duplicate_bakasha_regila(v_new_bakasha, v_prev_bakasha);
      
    --hagdala_nimuk
    insert into hagdala_nimuk
      (select code_nimuk,
              achuz_meushar,
              hearot,
              hagdala_nimuk_seq.nextval,
              taarich_bakashat_nimuk,
              code_hagdala_status_nimuk,
              me_taarich,
              ad_taarich,
              achuz_kodem,
              meushar_natsiv,
              v_new_bakasha,
              months_hagdala,
              years_hagdala,
              shem_meadken_acharon,
              taarich_yetzira              
         from hagdala_nimuk t
        where t.seq_bakasha = v_prev_bakasha);
  
    --tkufot_avoda_mechushv
insert into tkufot_avoda_mechushv
      (select taarich_me,
              taarich_ad,
              achuz_chelkyut,
              praklit,
              sach_chodeshim,
              haim_kana_zchuyot,
              code_sugey_tkufot,
              code_sugey_haasaka,
              code_sugey_zchuyot,
              tkufot_avoda_mechushav_seq.nextval,
              ezor_ovdim_be_tkufa,
              shanim,
              chodashim,
              yamim,
              seq_tkufot_avoda_golmi,
              seq_tkufot_michutz_lasharut,
              seq_tkufot_sherut_tsvaii,
              v_new_bakasha,
              except_from_tkufa,
              achuz_mugdal,
              code_achuz_mugdal,
              kd_takanon,
              code_takanon_magal,
              is_took_money_m_keren,
              mispar_misra,
              shem_meadken_acharon,
              taarich_yetzira    
         from tkufot_avoda_mechushv t
        where t.seq_bakasha = v_prev_bakasha);  

  
    --darga_vederug_tik
    insert into darga_vederug_tik
      (select taarich_me,
              taarich_ad,
              code_sug_darga,
              darga_vederug_tik_seq.nextval,
              code_darga,
              code_derug,
              v_new_bakasha,
              code_darga_ofek,
              code_derug_ofek,
              shem_meadken_acharon,
              taarich_yetzira    
         from darga_vederug_tik t
        where t.seq_bakasha = v_prev_bakasha);
      pk_prm_utils.duplicate_participation_data(v_new_bakasha,
                                                v_prev_bakasha);
                                               -- pk_prm_utils.duplicate_zakaut_data(v_new_bakasha, v_prev_bakasha);
       dbms_output.put_line(v_prev_bakasha);                                         
     for r1 in (select n.seq_netuney_tik_mechushavim
                   from netuney_tik_mechushavim n
                  where n.seq_bakasha = v_prev_bakasha and n.mispar_misra=0 and n.code_department=2) loop
        
      v_seq_netuney_tik_mechushavm_n := netuney_tik_mechushavim_seq.nextval;
        insert into netuney_tik_mechushavim
        
          (select achuz_kizba_nechut,
                  achuz_kizba_chelkiyut_melea,
                  achuz_kizba_kafuf_chelkiyut,
                  keren_mezaka_shana,
                  keren_mezaka_chodesh,
                  keren_mezaka_yamim,
                  odef_sherut_shanim,
                  odef_sherut_chodashim,
                  odef_sherut_yamim,
                  chodshim_mezkim_achary_hagdala,
                  ahuz_kizb_achry_hagdl_kaf_chel,
                  chelkiyut_lefi_sherut,
                  shnot_hagdala_sofi,
                  tkufa_lo_mezaka_sherut,
                  tkufa_mezaka_sherut,
                  chodshey_hagdala_sofi,
                  achuz_kizb_achry_hagdl_chl_mla,
                  chodeshim_mezkim_out_of_srv_y,
                  chodeshim_mezkim_out_of_srv_m,
                  chodeshim_mezkim_out_of_srv_d,
                  chelkiyut_meshuklelet_sherut,
                  v_seq_netuney_tik_mechushavm_n,
                  v_new_bakasha,
                  chelkiut_lefi_nechut,
                  is_zakai_lmaanak,
                  kitzba_medina_hisht_meshukll,
                  to_date(z.from_date,'yyyymmdd'),
                  code_department,
                  is_hachlata_sofit,
                  maskoret_kizba,
                  achuz_pizuy,
                  z.kizba,
                  schum_maanak_pizuy,
                  tkufa_overlap_kizba,
                  tkufa_overlap_maanak,
                  --sysdate, -----chavi
                  to_date(z.from_date,'yyyymmdd'),
                  is_salary_up_70,
                  is_complete_salary,
                  achuz_kizba_sofi,
                  chodshey_pizuy,
                  makor_maskoret_kovaat,
                  is_zakay_kizba,
                  code_group_prisha,
                  chelkiyut_sofit,
                  tkufa_mezaka_sherut_not_round,
                  code_e_zakaut,
                  achuz_kizba_fixed,
                  achuz_kizba_yechasi,
                  date_end_zakaut,
                  achuz_kizba_maximali,
                  hp_sheur_havara_max,
                  hp_tkufa_mshutefet_calc,
                  hp_is_sheerim,
                  hp_date_start_zakaut,
                  achuz_kizba_gil_60,
                  hp_date_haavara,
                  is_seif_57,
                  code_maanak_almana,
                  is_maanak_nisuin1,
                  is_maanak_nisuin2,
                  achuz_lchishuv_hivun,
                  mispar_misra,
                  user_update,
                  yadani,
                  total_child,
                  total_ben_zug,
                  to_number(z.retro),
                  date_zakaut_maanak_almana,
                  calc_as_of_date,
                  tkufa_mezaka_medina_only,
                  shem_meadken_acharon,
              taarich_yetzira    
             from netuney_tik_mechushavim t
            where t.seq_netuney_tik_mechushavim =
                  r1.seq_netuney_tik_mechushavim);
      
        insert into netuney_tik_ben_mishpacha
          (select netuney_tik_ben_mishpacha_seq.nextval,
                  n.seq_bney_mishpacha,
                  v_seq_netuney_tik_mechushavm_n,
                  n.date_start_zakaut,
                  n.date_end_zakaut,
                  n.code_relative,
                  n.achuz_kizba_chuka,
                  n.achuz_kizba,
                  n.achuz_tosefet_chuka,
                  n.achuz_tosefet,
                  n.code_maanak_almana,
                  n.date_maanak_nisuin1,
                  n.date_maanak_nisuin2,
                  n.date_zakaut_maanak_almana,
                  n.seif_relative,
                  shem_meadken_acharon,
              taarich_yetzira    
             from netuney_tik_ben_mishpacha n
            where n.seq_netuney_tik_mechushavim =
                  r1.seq_netuney_tik_mechushavim
           
           );
      end loop;

      
    --action log 41
      pk_prm_utils.insert_action_log_row(41,
                                         sysdate,
                                         0,
                                         0,
                                         'תהליך הצמדות אוטומטי',
                                         null,
                                         null,
                                         null,
                                         v_new_bakasha,
                                         null);
    
    exception
      when no_data_found then
        continue;
    end;
  end loop;
  commit;
end;
