                  calc_as_of_date,
                  tkufa_mezaka_medina_only,
                  shem_meadken_acharon,
              taarich_yetzira    
             from netuney_tik_mechushavim t
            where t.seq_netuney_tik_mechushavim =
                  r1.seq_netuney_tik_mechushavim);
      
        insert into netuney_tik_ben_mishpacha
          (select netuney_tik_ben_mishpacha_seq.nextval,
                  n.seq_bney_mishpacha,
                  v_seq_netuney_tik_mechushavm_n,
                  n.date_start_zakaut,
                  n.date_end_zakaut,
                  n.code_relative,
                  n.achuz_kizba_chuka,
                  n.achuz_kizba,
                  n.achuz_tosefet_chuka,
                  n.achuz_tosefet,
                  n.code_maanak_almana,
                  n.date_maanak_nisuin1,
                  n.date_maanak_nisuin2,
                  n.date_zakaut_maanak_almana,
                  n.seif_relative,
                  shem_meadken_acharon,
              taarich_yetzira    
             from netuney_tik_ben_mishpacha n
            where n.seq_netuney_tik_mechushavim =
                  r1.seq_netuney_tik_mechushavim
           
           );
      end loop;

      
    --action log 41
      pk_prm_utils.insert_action_log_row(41,
                                         sysdate,
                                         0,
                                         0,
                                         'תשלום במפם',
                                         null,
                                         null,
                                         null,
                                         v_new_bakasha,
                                         null);
    
    exception
      when no_data_found then
        continue;
    end;
  end loop;
  commit;
end;
---------------------------------------------------------
procedure duplicate_mayors( p_ramat_rashut number,p_for_month nvarchar2)is
    i                            number;
  v_new_bakasha                  number;
  v_seq_poresh                   number;
  v_seq_ezor_ovdim               number;
  v_seq_netuney_tik_mechushavm_n number;
  v_code_sug_bakasha             number;
  v_exists_netuney_tik number;
  v_ramat_rasht          number;
  v_maskoret_kovvat      number;
  v_paricipation_seq     number;
  v_mikdemet_yoker number;
begin
 --loop over bakashot
 
  for rr in (select ms.code_ramat_rashut,ms.seq_maskorot_le_sganei_arim
            from maskorot_le_sganei_arim ms
            where ms.from_date = to_date(trim(p_for_month),'yyyymmdd')
            and (ms.code_ramat_rashut = p_ramat_rashut or p_ramat_rashut is null)
            and nvl(ms.is_bakashot_created,0)=0)loop
  for z in (select max(v.seq_bakasha)seq_bakasha,v.seq_prisha,v.seq_porshim,v.seq_ezor_ovdim
           from v_bakasha_last_status v
           left join bakasha_regila br
           on br.seq_bakasha= v.seq_bakasha
           where v.code_bakasha_detail in (47,48)
           and v.code_action in (41,42)
           and br.code_derug_sganei_arim = rr.code_ramat_rashut           
           group by v.seq_prisha,v.seq_porshim,v.seq_ezor_ovdim
    ) loop
    begin
    select b.code_sug_bakasha
    into v_code_sug_bakasha
    from bakasha b
    where b.seq_bakasha = z.seq_bakasha;
    
      --create and duplicate data
      v_new_bakasha := pk_load_mimshak.Add_main_tables(z.seq_porshim,
                                                       z.seq_ezor_ovdim,
                                                       7,
                                                       v_code_sug_bakasha);
      update bakasha b set                                          
      b.code_bakasha_detail=decode( v_code_sug_bakasha,8,47,48),
      b.remarks = 'עדכון שכר ראשי וסגני ערים'
      where b.seq_bakasha= v_new_bakasha;
       
      pk_prm_utils.duplicate_bakasha_regila(v_new_bakasha, z.seq_bakasha);
      
    --hagdala_nimuk
    insert into hagdala_nimuk
      (select code_nimuk,
              achuz_meushar,
              hearot,
              hagdala_nimuk_seq.nextval,
              taarich_bakashat_nimuk,
              code_hagdala_status_nimuk,
              me_taarich,
              ad_taarich,
              achuz_kodem,
              meushar_natsiv,
              v_new_bakasha,
              months_hagdala,
              years_hagdala,SHEM_MEADKEN_ACHARON,TAARICH_YETZIRA
         from hagdala_nimuk t
        where t.seq_bakasha = z.seq_bakasha);
  
    --tkufot_avoda_mechushv
insert into tkufot_avoda_mechushv
      (select taarich_me,
              taarich_ad,
              achuz_chelkyut,
              praklit,
              sach_chodeshim,
              haim_kana_zchuyot,
              code_sugey_tkufot,
              code_sugey_haasaka,
              code_sugey_zchuyot,
              tkufot_avoda_mechushav_seq.nextval,
              ezor_ovdim_be_tkufa,
              shanim,
              chodashim,
              yamim,
              seq_tkufot_avoda_golmi,
              seq_tkufot_michutz_lasharut,
              seq_tkufot_sherut_tsvaii,
              v_new_bakasha,
              except_from_tkufa,
              achuz_mugdal,
              code_achuz_mugdal,
              kd_takanon,
              code_takanon_magal,
              is_took_money_m_keren,
              mispar_misra,
              SHEM_MEADKEN_ACHARON,
              TAARICH_YETZIRA
         from tkufot_avoda_mechushv t
        where t.seq_bakasha = z.seq_bakasha);  

  
    --darga_vederug_tik
    insert into darga_vederug_tik
      (select taarich_me,
              taarich_ad,
              code_sug_darga,
              darga_vederug_tik_seq.nextval,
              code_darga,
              code_derug,
              v_new_bakasha,
              code_darga_ofek,
              code_derug_ofek,SHEM_MEADKEN_ACHARON,
              TAARICH_YETZIRA
         from darga_vederug_tik t
        where t.seq_bakasha = z.seq_bakasha);
        
        --participation
      pk_prm_utils.duplicate_participation_data(v_new_bakasha,
                                                z.seq_bakasha);
                                               -- pk_prm_utils.duplicate_zakaut_data(v_new_bakasha, v_prev_bakasha);
      
     update participation p
     set date_payment = to_date(trim(p_for_month),'yyyymmdd')
     where seq_bakasha=v_new_bakasha; 
      
     select nvl(t.schum,0) , nvl(t.mikdamat_yoker,0)
     into v_maskoret_kovvat,v_mikdemet_yoker
     from maskorot_le_sganei_arim t
     where t.from_date = to_date(trim(p_for_month),'yyyymmdd')
     and t.code_ramat_rashut = rr.code_ramat_rashut;
     
     update bakasha_regila br
     set maskoret_kovaat = v_maskoret_kovvat,
     mikdmat_yoker = v_mikdemet_yoker
     where seq_bakasha=v_new_bakasha;
      
      
     for r1 in (select n.seq_netuney_tik_mechushavim
                   from netuney_tik_mechushavim n
                  where n.seq_bakasha = z.seq_bakasha and n.mispar_misra=0 and n.code_department=2) loop
        
        
     
      v_seq_netuney_tik_mechushavm_n := netuney_tik_mechushavim_seq.nextval;
        insert into netuney_tik_mechushavim
        
          (select achuz_kizba_nechut,
                  achuz_kizba_chelkiyut_melea,
                  achuz_kizba_kafuf_chelkiyut,
                  keren_mezaka_shana,
                  keren_mezaka_chodesh,
                  keren_mezaka_yamim,
                  odef_sherut_shanim,
                  odef_sherut_chodashim,
                  odef_sherut_yamim,
                  chodshim_mezkim_achary_hagdala,
                  ahuz_kizb_achry_hagdl_kaf_chel,
                  chelkiyut_lefi_sherut,
                  shnot_hagdala_sofi,
                  tkufa_lo_mezaka_sherut,
                  tkufa_mezaka_sherut,
                  chodshey_hagdala_sofi,
                  achuz_kizb_achry_hagdl_chl_mla,
                  chodeshim_mezkim_out_of_srv_y,
                  chodeshim_mezkim_out_of_srv_m,
                  chodeshim_mezkim_out_of_srv_d,
                  chelkiyut_meshuklelet_sherut,
                  v_seq_netuney_tik_mechushavm_n,
                  v_new_bakasha,
                  chelkiut_lefi_nechut,
                  is_zakai_lmaanak,
                  kitzba_medina_hisht_meshukll,
                  to_date(trim(p_for_month),'yyyymmdd'),
                  code_department,
                  is_hachlata_sofit,
                  v_maskoret_kovvat + v_mikdemet_yoker,
                  achuz_pizuy,
                  (v_maskoret_kovvat + v_mikdemet_yoker) * achuz_kizba_sofi *0.01 * chelkiyut_sofit,
                  schum_maanak_pizuy,
                  tkufa_overlap_kizba,
                  tkufa_overlap_maanak,
                  sysdate,
                  is_salary_up_70,
                  is_complete_salary,
                  achuz_kizba_sofi,
                  chodshey_pizuy,
                  makor_maskoret_kovaat,
                  is_zakay_kizba,
                  code_group_prisha,
                  chelkiyut_sofit,
                  tkufa_mezaka_sherut_not_round,
                  code_e_zakaut,
                  achuz_kizba_fixed,
                  achuz_kizba_yechasi,
                  date_end_zakaut,
                  achuz_kizba_maximali,
                  hp_sheur_havara_max,
                  hp_tkufa_mshutefet_calc,
                  hp_is_sheerim,
                  hp_date_start_zakaut,
                  achuz_kizba_gil_60,
                  hp_date_haavara,
                  is_seif_57,
                  code_maanak_almana,
                  is_maanak_nisuin1,
                  is_maanak_nisuin2,
                  achuz_lchishuv_hivun,
                  mispar_misra,
                  15,
                  null,
                  total_child,
                  total_ben_zug,
                  0,
                  date_zakaut_maanak_almana,
                  calc_as_of_date,
                  tkufa_mezaka_medina_only,
                  shem_meadken_acharon, TAARICH_YETZIRA
             from netuney_tik_mechushavim t
            where t.seq_netuney_tik_mechushavim =
                  r1.seq_netuney_tik_mechushavim);
      
        insert into netuney_tik_ben_mishpacha
          (select netuney_tik_ben_mishpacha_seq.nextval,
                  n.seq_bney_mishpacha,
                  v_seq_netuney_tik_mechushavm_n,
                  n.date_start_zakaut,
                  n.date_end_zakaut,
                  n.code_relative,
                  n.achuz_kizba_chuka,
                  n.achuz_kizba,
                  n.achuz_tosefet_chuka,
                  n.achuz_tosefet,
                  n.code_maanak_almana,
                  n.date_maanak_nisuin1,
                  n.date_maanak_nisuin2,
                  n.date_zakaut_maanak_almana,
                  n.seif_relative,
                  SHEM_MEADKEN_ACHARON,
                  TAARICH_YETZIRA
             from netuney_tik_ben_mishpacha n
            where n.seq_netuney_tik_mechushavim =
                  r1.seq_netuney_tik_mechushavim
           
           );
          
           
           
      end loop;

      
    --action log 41
      pk_prm_utils.insert_action_log_row(41,
                                         sysdate,
                                         0,
                                         0,
                                         'עדכון שכר ממשרד הפנים',
                                         null,
                                         null,
                                         null,
                                         v_new_bakasha,
                                         null);
    
    exception
      when no_data_found then
        continue;
    end;
  end loop;--z
  update maskorot_le_sganei_arim t
  set t.is_bakashot_created = 1
  where t.seq_maskorot_le_sganei_arim = rr.seq_maskorot_le_sganei_arim;
  
  end loop;--rr
  commit;
end;
-------------------------------------------------------------------------------
procedure create_mayors_part(p_for_month date)is
    i                            number;
  v_prev_bakasha                 number;
  v_new_bakasha                  number;
  v_seq_poresh                   number;
  v_seq_ezor_ovdim               number;
  v_seq_netuney_tik_mechushavm_n number;
  v_code_sug_bakasha             number;
  v_exists_netuney_tik number;
  v_ramat_rasht          number;
  v_maskoret_kovvat      number;
  v_mikdemet_yoker       number;
  v_date_death          date;
  v_seq_paricipation    number;
  v_seq_guf             number;
  v_achuz_kizba  float;
  v_chelkiut  float;
begin
 --loop over bakashot
 
  for z in (select max(v.seq_bakasha)seq_bakasha,v.seq_prisha,v.seq_porshim,v.seq_ezor_ovdim,v.mispar_zehut
           from v_bakasha_last_status v
           left join bakasha_regila br
           on br.seq_bakasha= v.seq_bakasha
           where v.mispar_zehut in (select nvl(t.id_poresh,t.id_number)
                                   from ld_ptrcpn_mayor t
                                   where t.seq_guf is not null
                                   )
          and v.code_sug_bakasha in (1,3,5,13,8,9)
          group by v.seq_prisha,v.seq_porshim,v.seq_ezor_ovdim,v.mispar_zehut
    ) loop
    begin
    dbms_output.put_line(z.mispar_zehut);
    v_prev_bakasha := z.seq_bakasha;
    
    select po.taarich_ptira
    into v_date_death
    from poresh po
    where po.porshim_seq = z.seq_porshim;
    
    if v_date_death is null then 
    v_code_sug_bakasha := 8;
    else
      v_code_sug_bakasha := 9;
      end if;
      --create and duplicate data
      v_new_bakasha := pk_load_mimshak.Add_main_tables(z.seq_porshim,
                                                       z.seq_ezor_ovdim,
                                                       8,
                                                       v_code_sug_bakasha);
      update bakasha b set                                          
      b.code_bakasha_detail=decode( b.code_sug_bakasha,8,47,48),
      b.remarks = 'עדכון שכר ראשי וסגני ערים'
      where b.seq_bakasha= v_new_bakasha;
       
      pk_prm_utils.duplicate_bakasha_regila(v_new_bakasha, v_prev_bakasha);
      
      
      
      select t1.code_derug_sganei_arim
      into v_ramat_rasht
      from ld_ptrcpn_mayor t
      left join code_derug_sganei_arim t1
      on trim(t.ramat_rashut) = trim(t1.teur)
      where id_number=z.mispar_zehut or t.id_poresh=z.mispar_zehut;
      
      update bakasha_regila t
      set t.code_derug_sganei_arim = v_ramat_rasht
      where t.seq_bakasha = v_new_bakasha;
      
    --hagdala_nimuk
    insert into hagdala_nimuk
      (select code_nimuk,
              achuz_meushar,
              hearot,
              hagdala_nimuk_seq.nextval,
              taarich_bakashat_nimuk,
              code_hagdala_status_nimuk,
              me_taarich,
              ad_taarich,
              achuz_kodem,
              meushar_natsiv,
              v_new_bakasha,
              months_hagdala,
              years_hagdala,SHEM_MEADKEN_ACHARON,TAARICH_YETZIRA
         from hagdala_nimuk t
        where t.seq_bakasha = v_prev_bakasha);
  
    --tkufot_avoda_mechushv
insert into tkufot_avoda_mechushv
      (select taarich_me,
              taarich_ad,
              achuz_chelkyut,
              praklit,
              sach_chodeshim,
              haim_kana_zchuyot,
              code_sugey_tkufot,
              code_sugey_haasaka,
              code_sugey_zchuyot,
              tkufot_avoda_mechushav_seq.nextval,
              ezor_ovdim_be_tkufa,
              shanim,
              chodashim,
              yamim,
              seq_tkufot_avoda_golmi,
              seq_tkufot_michutz_lasharut,
              seq_tkufot_sherut_tsvaii,
              v_new_bakasha,
              except_from_tkufa,
              achuz_mugdal,
              code_achuz_mugdal,
              kd_takanon,
              code_takanon_magal,
              is_took_money_m_keren,
              mispar_misra,
              SHEM_MEADKEN_ACHARON,TAARICH_YETZIRA
         from tkufot_avoda_mechushv t
        where t.seq_bakasha = v_prev_bakasha);  

  
    --darga_vederug_tik
    insert into darga_vederug_tik
      (select taarich_me,
              taarich_ad,
              code_sug_darga,
              darga_vederug_tik_seq.nextval,
              code_darga,
              code_derug,
              v_new_bakasha,
              code_darga_ofek,
              code_derug_ofek,
              SHEM_MEADKEN_ACHARON,
              TAARICH_YETZIRA
         from darga_vederug_tik t
        where t.seq_bakasha = v_prev_bakasha);
        
     
      pk_prm_utils.duplicate_participation_data(v_new_bakasha,
                                                v_prev_bakasha);
                                               -- pk_prm_utils.duplicate_zakaut_data(v_new_bakasha, v_prev_bakasha);
      --participation
      select max(seq_bakasha)
      into v_seq_paricipation
      from participation 
      where seq_bakasha = v_new_bakasha
      and code_participation = 1;
      
      if v_seq_paricipation is null then 
        
        select t.seq_guf
        into v_seq_guf
        from ld_ptrcpn_mayor t
        where id_number=z.mispar_zehut or t.id_poresh=z.mispar_zehut;
        
        insert into participation
        (
        seq_bakasha,
        seq_participation,
        code_participation,
        seq_guf,
        SHEM_MEADKEN_ACHARON
        )
        values
        (
        v_new_bakasha,
        participation_seq.nextval,
        1,
       v_seq_guf,
       SYS_CONTEXT('USERENV','os_user')
        );
        
      end if;
                                                  
     select to_number(t.percent),to_number(t.partial)/100
        into v_achuz_kizba,v_chelkiut
        from ld_ptrcpn_mayor t
        where t.id_number=z.mispar_zehut or t.id_poresh=z.mispar_zehut;
        
     select br.code_derug_sganei_arim
     into   v_ramat_rasht 
     from bakasha_regila br
     where br.seq_bakasha = v_new_bakasha;
     
     for r1 in (select n.seq_netuney_tik_mechushavim
                   from netuney_tik_mechushavim n
                  where n.seq_bakasha = v_prev_bakasha and n.mispar_misra=0 and n.code_department=2) loop
        
     
     select nvl(t.schum,0) , nvl(t.mikdamat_yoker,0)
     into v_maskoret_kovvat,v_mikdemet_yoker
     from maskorot_le_sganei_arim t
     where t.from_date = 
     (select max (x.from_date) from MASKOROT_LE_SGANEI_ARIM x
     where x.code_ramat_rashut = v_ramat_rasht)
     and t.code_ramat_rashut = v_ramat_rasht;
     
     update bakasha_regila br
     set maskoret_kovaat = v_maskoret_kovvat,
     mikdmat_yoker = v_mikdemet_yoker
     where seq_bakasha=v_new_bakasha;
     
     update participation p
     set date_payment = p_for_month
     where seq_bakasha=v_new_bakasha;
     
     
        
      v_seq_netuney_tik_mechushavm_n := netuney_tik_mechushavim_seq.nextval;
        insert into netuney_tik_mechushavim
        
          (select achuz_kizba_nechut,
                  achuz_kizba_chelkiyut_melea,
                  achuz_kizba_kafuf_chelkiyut,
                  keren_mezaka_shana,
                  keren_mezaka_chodesh,
                  keren_mezaka_yamim,
                  odef_sherut_shanim,
                  odef_sherut_chodashim,
                  odef_sherut_yamim,
                  chodshim_mezkim_achary_hagdala,
                  ahuz_kizb_achry_hagdl_kaf_chel,
                  chelkiyut_lefi_sherut,
                  shnot_hagdala_sofi,
                  tkufa_lo_mezaka_sherut,
                  tkufa_mezaka_sherut,
                  chodshey_hagdala_sofi,
                  achuz_kizb_achry_hagdl_chl_mla,
                  chodeshim_mezkim_out_of_srv_y,
                  chodeshim_mezkim_out_of_srv_m,
                  chodeshim_mezkim_out_of_srv_d,
                  chelkiyut_meshuklelet_sherut,
                  v_seq_netuney_tik_mechushavm_n,
                  v_new_bakasha,
                  chelkiut_lefi_nechut,
                  is_zakai_lmaanak,
                  kitzba_medina_hisht_meshukll,
                  p_for_month,
                  code_department,
                  is_hachlata_sofit,
                  v_maskoret_kovvat + v_mikdemet_yoker,
                  achuz_pizuy,
                  (v_maskoret_kovvat + v_mikdemet_yoker) * v_achuz_kizba *0.01 * v_chelkiut,
                  schum_maanak_pizuy,
                  tkufa_overlap_kizba,
                  tkufa_overlap_maanak,
                  sysdate,
                  is_salary_up_70,
                  is_complete_salary,
                  v_achuz_kizba,
                  chodshey_pizuy,
                  makor_maskoret_kovaat,
                  is_zakay_kizba,
                  code_group_prisha,
                  v_chelkiut,
                  tkufa_mezaka_sherut_not_round,
                  code_e_zakaut,
                  achuz_kizba_fixed,
                  achuz_kizba_yechasi,
                  date_end_zakaut,
                  achuz_kizba_maximali,
                  hp_sheur_havara_max,
                  hp_tkufa_mshutefet_calc,
                  hp_is_sheerim,
                  hp_date_start_zakaut,
                  achuz_kizba_gil_60,
                  hp_date_haavara,
                  is_seif_57,
                  code_maanak_almana,
                  is_maanak_nisuin1,
                  is_maanak_nisuin2,
                  achuz_lchishuv_hivun,
                  mispar_misra,
                  15,
                  null,
                  total_child,
                  total_ben_zug,
                  0,
                  date_zakaut_maanak_almana,
                  calc_as_of_date,
                  tkufa_mezaka_medina_only,
                  shem_meadken_acharon,
                  TAARICH_YETZIRA
             from netuney_tik_mechushavim t
            where t.seq_netuney_tik_mechushavim =
                  r1.seq_netuney_tik_mechushavim);
      
        insert into netuney_tik_ben_mishpacha
          (select netuney_tik_ben_mishpacha_seq.nextval,
                  n.seq_bney_mishpacha,
                  v_seq_netuney_tik_mechushavm_n,
                  n.date_start_zakaut,
                  n.date_end_zakaut,
                  n.code_relative,
                  n.achuz_kizba_chuka,
                  n.achuz_kizba,
                  n.achuz_tosefet_chuka,
                  n.achuz_tosefet,
                  n.code_maanak_almana,
                  n.date_maanak_nisuin1,
                  n.date_maanak_nisuin2,
                  n.date_zakaut_maanak_almana,
                  n.seif_relative,
                  SHEM_MEADKEN_ACHARON,
                  TAARICH_YETZIRA
             from netuney_tik_ben_mishpacha n
            where n.seq_netuney_tik_mechushavim =
                  r1.seq_netuney_tik_mechushavim
           
           );
          
           
           
      end loop;

      
    --action log 41
      pk_prm_utils.insert_action_log_row(41,
                                         sysdate,
                                         0,
                                         0,
                                         'עדכון שכר ממשרד הפנים',
                                         null,
                                         null,
                                         null,
                                         v_new_bakasha,
                                         null);
    
    /*exception
      when no_data_found then
        continue;*/
    end;
  end loop;
  commit;
end;
end;
/

create or replace package body prm_system_copy.pk_prm_utils is
  -------------------------------------------------------------
  v_count_kapam number;
  procedure duplicate_tkufot_avoda_mechushv(p_seq_bakasha_new  number,
                                            p_seq_bakasha_prev number) is
  begin
    --tkufot_avoda_mechushv
    insert into tkufot_avoda_mechushv
      (select taarich_me,
              taarich_ad,
              achuz_chelkyut,
              praklit,
              sach_chodeshim,
              haim_kana_zchuyot,
              code_sugey_tkufot,
              code_sugey_haasaka,
              code_sugey_zchuyot,
              tkufot_avoda_mechushav_seq.nextval,
              ezor_ovdim_be_tkufa,
              shanim,
              chodashim,
              yamim,
              seq_tkufot_avoda_golmi,
              seq_tkufot_michutz_lasharut,
              seq_tkufot_sherut_tsvaii,
              p_seq_bakasha_new,
              except_from_tkufa,
              achuz_mugdal,
              code_achuz_mugdal,
              kd_takanon,
              code_takanon_magal,
              is_took_money_m_keren,
              mispar_misra,
              shem_meadken_acharon,
              taarich_yetzira
         from tkufot_avoda_mechushv t
        where t.seq_bakasha = p_seq_bakasha_prev);
  
  end;
  ------------------------
  procedure update_misra_when_choze_bchirim(p_seq_bakasha number) is
    v_date_from date;
    v_date_to   date;
  begin
    --get dates
    select min(t.taarich_me), max(t.taarich_ad)
      into v_date_from, v_date_to
      from tkufot_avoda_mechushv t
     where t.code_sugey_zchuyot = 10
       and t.seq_bakasha = p_seq_bakasha;
  
    if v_date_from is not null then
      update tkufot_avoda_mechushv t
         set t.mispar_misra = 1
       where t.seq_bakasha = p_seq_bakasha
         and not (t.code_sugey_zchuyot = 10 or
              (t.taarich_me >= v_date_from and t.taarich_ad <= v_date_to and
              t.code_sugey_tkufot = 4 and t.code_sugey_zchuyot = 2));
    end if;
  end;
  -----------------------------------------------------------
  function is_choze_bchurum(p_seq_bakasha number) return number is
    v_choze_bchurum number;
  begin
  
    --get dates
    select count(t.seq_tkufot_avoda_mechushv)
      into v_choze_bchurum
      from tkufot_avoda_mechushv t
     where t.code_sugey_zchuyot = 10
       and t.seq_bakasha = p_seq_bakasha;
  
    return v_choze_bchurum;
  
  end;
  -------------------------------------------------------------
