             keren_mezaka_chodesh,
             keren_mezaka_yamim,
             odef_sherut_shanim,
             odef_sherut_chodashim,
             odef_sherut_yamim,
             chodshim_mezkim_achary_hagdala,
             ahuz_kizb_achry_hagdl_kaf_chel,
             chelkiyut_lefi_sherut,
             shnot_hagdala_sofi,
             tkufa_lo_mezaka_sherut,
             tkufa_mezaka_sherut,
             chodshey_hagdala_sofi,
             achuz_kizb_achry_hagdl_chl_mla,
             chodeshim_mezkim_out_of_srv_y,
             chodeshim_mezkim_out_of_srv_m,
             chodeshim_mezkim_out_of_srv_d,
             chelkiyut_meshuklelet_sherut,
             netuney_tik_mechushavim_seq.nextval,
             n.seq_bakasha,
             chelkiut_lefi_nechut,
             is_zakai_lmaanak,
             kitzba_medina_hisht_meshukll,
             date_start_zakaut,
             2,
             is_hachlata_sofit,
             maskoret_kizba,
             achuz_pizuy,
             schum_kizba,
             schum_maanak_pizuy,
             tkufa_overlap_kizba,
             tkufa_overlap_maanak,
             date_update,
             is_salary_up_70,
             is_complete_salary,
             achuz_kizba_sofi,
             chodshey_pizuy,
             makor_maskoret_kovaat
        from netuney_tik_mechushavim n
       where n.code_department = 1
         and n.seq_bakasha = p_seq_bakasha
         and not exists (select *
                from netuney_tik_mechushavim n1
               where n1.seq_bakasha = n.seq_bakasha
                 and n1.code_department = 2
                 and n1.mispar_misra = 0);
    commit;
