  exception
    when others then
      rollback;
      return sqlerrm;
  end;
  ----------------------------------------------------------
  /*  FUNCTION VARCHAR_WITHOUT_EXTRA_ZEROS(ORGINAL_VARCHAR VARCHAR2)
    RETURN VARCHAR2 IS
    V_ARRAY     APEX_APPLICATION_GLOBAL.VC_ARR2;
    V_TO_NUMBER NUMBER;
    V_FINAL     VARCHAR2(1000);
  BEGIN
    --SPLITT THE STRING TO ARRAY
    V_ARRAY := APEX_UTIL.STRING_TO_TABLE(ORGINAL_VARCHAR, ' ');
  
    FOR I IN 1 .. V_ARRAY.COUNT LOOP
      V_TO_NUMBER := NULL;
      --CHECK IF THE WORD IS NUMBER
      BEGIN
        --CONVERT TO NUMBER WITHOUT THE EXTRA ZEROS
        V_TO_NUMBER := TO_NUMBER(V_ARRAY(I));
        --CHECK IF THE NUMBER IS NOT ZERO.
        IF V_TO_NUMBER <> 0 THEN
          --CHAIN TO FINAL STRING.
          V_FINAL := V_FINAL || ' ' || TO_CHAR(V_TO_NUMBER);
        END IF;
      EXCEPTION
        WHEN VALUE_ERROR THEN
          --IF THE WORD IS NOT NUMBER, CHAIN TO THE FINAL STRING "as is".
          V_FINAL := V_FINAL || ' ' || V_ARRAY(I);
      END;
    END LOOP;
    RETURN TRIM(V_FINAL);
  END;
  ----------------------------------------------------------*/
  procedure Get_must_documents(P_Id_Poresh        number,
                               p_documents_string out varchar2) is
  
  begin
    select string_agg(seq_document_type)
      into p_documents_string
      from (select distinct t.seq_document_type
              from v_bakasha_last_status v
              left join code_seif_prisha s
                on v.code_seif_prisha = s.code_seif_prisha
              left join perm_document_by_bakasha t
                on (t.code_group_prisha = s.code_group_prisha or
                   t.code_group_prisha is null)
             where t.is_must = 1
               and v.mispar_zehut = P_Id_Poresh
               and t.seq_document_type not in
                   (select distinct d.seq_document_type
                      from document_bakasha db
                      left join v_bakasha b
                        on db.seq_bakasha = b.SEQ_BAKASHA
                      left join document d
                        on db.seq_document = d.seq_document
                     where b.SEQ_PRISHA = v.seq_prisha));
  
  end;

  ----------------------------------------------------------
  procedure Get_exist_documents(P_Id_Poresh        number,
                                p_documents_string out varchar2) is
  
  begin
    select string_agg(d.seq_document_type)
    --select string_agg(d.seq_document_type || '(' || t.teur_document_type || ') ')
      into p_documents_string
      from document_bakasha db
      left join v_bakasha b
        on db.seq_bakasha = b.SEQ_BAKASHA
      left join document d
        on db.seq_document = d.seq_document
      left join code_document_type t
        on d.seq_document_type = t.seq_document_type
     where b.MISPAR_ZEHUT = P_Id_Poresh;
  
  end;
  ----------------------------------------------------------
  procedure Add_document_electronic(P_Id_Poresh          number,
                                    p_date_create        date,
                                    p_page_count         number,
                                    p_mimshak_number     number,
                                    p_seq_ezor_ovdim     number,
                                    P_Document_Type      number,
                                    p_Maor_Number        varchar2,
                                    p_Subject            varchar2,
                                    p_source_document_id number,
                                    p_is_active          number,
                                    p_log                out varchar2) is
    v_seq_document         number;
    v_seq_document_bakasha number;
    v_seq_bakasha          number;
    v_seq_action_log       number;
    v_message              varchar2(1000) := null;
    v_is_success           number;
    v_seq_document_general number;
  begin
    begin
      begin
        select g.seq_document_type
          into v_seq_document_general
          from code_document_type g
         where g.seq_document_type = P_Document_Type;
      exception
        when no_data_found then
          raise_application_error(-20000,
                                  'Document Type is not exist in mpm.');
      end;
    
      begin
        select v.seq_bakasha, v.SEQ_ACTION_LOG
          into v_seq_bakasha, v_seq_action_log
          from v_regila_last_status v
         where v.mispar_zehut = P_Id_Poresh
           and v.seq_ezor_ovdim = p_seq_ezor_ovdim;
      exception
        when no_data_found then
          raise_application_error(-20000, 'Id poresh is not exist in mpm.');
      end;
    
      if trim(p_Maor_Number) is null then
        raise_application_error(-20000, 'Document is not exist.');
      end if;
    
      v_seq_document         := document_seq.nextval;
      v_seq_document_bakasha := document_bakasha_seq.nextval;
    
      insert into document
        (seq_document,
         seq_document_type,
         document_url,
         teur,
         date_update,
         code_user,
         page_count,
         date_create,
         source_document_id)
      values
        (v_seq_document,
         P_Document_Type,
         p_Maor_Number,
         p_Subject,
         sysdate,
         0,
         p_page_count,
         p_date_create,
         p_source_document_id);
    
      insert into document_bakasha
        (seq_document_bakasha,
         seq_document,
         seq_bakasha,
         seq_action_log,
         pail)
      values
        (v_seq_document_bakasha,
         v_seq_document,
         v_seq_bakasha,
         v_seq_action_log,
         p_is_active);
    
      commit;
      v_is_success := 1;
    
    exception
      when others then
        rollback;
        v_is_success := 0;
        v_message    := sqlerrm;
    end;
  
    insert into ld_add_document_electronic
      (is_success,
       message,
       id_poresh,
       document_type,
       maor_number,
       subject,
       seq_ezor_ovdim,
       seq_action_log,
       page_count,
       date_create,
       mimshak_number,
       pail,
       source_document_id)
    values
      (v_is_success,
       v_message,
       p_id_poresh,
       p_document_type,
       p_maor_number,
       p_subject,
       p_seq_ezor_ovdim,
       v_seq_action_log,
       p_page_count,
       p_date_create,
       p_mimshak_number,
       p_is_active,
       p_source_document_id);
  
    commit;
    if v_is_success = 1 then
      p_log := ' Saved';
    else
      p_log := ' Unsaved:  ' || v_message;
    end if;
  
  end;
  ----------------------------------------------------------
  procedure delete_bakasha_without_result(p_seq_bakasha number) is
    v_result number;
  begin
    v_result := delete_bakasha_without_commit(p_seq_bakasha);
    if v_result = 1 then
      commit;
    else
      rollback;
    end if;
  end;
  ----------------------------------------------------------
  function delete_bakasha(p_seq_bakasha number) return varchar2 is
    pragma autonomous_transaction;
    v_result number;
  begin
    v_result := delete_bakasha_without_commit(p_seq_bakasha);
    if v_result = 1 then
      commit;
      return 'done!';
    else
      rollback;
      return sqlerrm(v_result);
    end if;
  end;
  ----------------------------------------------------------
  function delete_bakasha_without_commit(p_seq_bakasha number) return number is
    v_cnt_other_bakashot_fr_prisha number;
    v_cnt_other_prishot_for_poresh number;
    v_seq_prisha                   number;
    v_seq_poresh                   number;
  begin
  
    select v.seq_prisha, v.seq_porshim
      into v_seq_prisha, v_seq_poresh
      from v_bakasha_last_status v
     where v.seq_bakasha = p_seq_bakasha;
  
    select count(*)
      into v_cnt_other_bakashot_fr_prisha
      from v_bakasha v
     where v.SEQ_PRISHA = v_seq_prisha
       and v.SEQ_BAKASHA <> p_seq_bakasha;
  
    select count(*)
      into v_cnt_other_prishot_for_poresh
      from v_bakasha_last_status v
     where v.seq_porshim = v_seq_poresh
       and v.seq_prisha <> v_seq_prisha;
  
    delete from tosefot t26
     where t26.seq_netuney_sachar in
           (select t25.seq_netuney_sachar
              from netuney_sachar t25
             where t25.seq_bakasha = p_seq_bakasha);
  
    delete from vetek_detail t31
     where t31.seq_netuney_sachar in
           (select p.seq_netuney_sachar
              from netuney_sachar p
             where p.seq_bakasha = p_seq_bakasha);
  
    delete from vetek_detail t31 where seq_bakasha = p_seq_bakasha;
    delete from chinuch_bakara t
     where t.seq_chinuch_reforma in
           (select t25.seq_chinuch_reforma
              from chinuch_reforma t25
             where t25.seq_bakasha = p_seq_bakasha);
    delete from KAPAM_MESHICHOT t where t.seq_bakasha = p_seq_bakasha;
    delete from netuney_sachar t25 where t25.seq_bakasha = p_seq_bakasha;
    delete from chinuch_reforma t25 where t25.seq_bakasha = p_seq_bakasha;
    delete from chinuch_mitve_nur t25
     where t25.seq_bakasha = p_seq_bakasha;
    ----
  
    delete from document_bakasha t11 where t11.seq_bakasha = p_seq_bakasha;
  
    delete from action_log t17 where t17.seq_bakasha = p_seq_bakasha;
  
    -----
    delete from tikim_mukdemet_hachlatot t16
     where t16.seq_bakasha = p_seq_bakasha;
  
    delete from tikim_mukdemet_misrot_lebitul t15
     where t15.seq_bakasha = p_seq_bakasha;
  
    delete from bakasha_mukdemet t14 where t14.seq_bakasha = p_seq_bakasha;
    -----
  
    delete from HIVUN where seq_bakasha = p_seq_bakasha;
  
    delete from chinuch_salary t24 where t24.seq_bakasha = p_seq_bakasha;
  
    delete from darga_vederug_tik t13
     where t13.seq_bakasha = p_seq_bakasha;
  
    delete from decisions t12 where t12.seq_bakasha = p_seq_bakasha;
  
    delete from hagdala_nimuk t10 where t10.seq_bakasha = p_seq_bakasha;
  
    delete from netuney_tik_mechushavim t9
     where t9.seq_bakasha = p_seq_bakasha;
  
    delete from netuney_tik_mechushav_chnuch t19
     where t19.seq_bakasha = p_seq_bakasha;
  
    delete from netuney_tik_meushar_ozar t8
     where t8.seq_bakasha = p_seq_bakasha;
  
    delete participation_tkufot t19
     where t19.seq_participation in
           (select p.seq_participation
              from participation p
             where p.seq_bakasha = p_seq_bakasha);
  
    delete participation t7 where t7.seq_bakasha = p_seq_bakasha;
  
    delete from tkufot_avoda_mechushv t5
     where t5.seq_bakasha = p_seq_bakasha;
  
    delete from tkufot_avoda_golmi t6 where t6.seq_bakasha = p_seq_bakasha;
  
    delete tkufot_michutz_lasharut t4 where t4.seq_bakasha = p_seq_bakasha;
  
    delete from tkufot_sherut_tsvaii t3
     where t3.seq_bakasha = p_seq_bakasha;
  
    delete from tkufot_sikum t2 where t2.seq_bakasha = p_seq_bakasha;
  
    delete from address where seq_bakasha = p_seq_bakasha;
  
    delete from MAZAV_MISHPACHTI where seq_bakasha = p_Seq_Bakasha;
  
    delete from bank_account where seq_bakasha in p_SEQ_BAKASHA;
  
    delete from bakasha_regila t1 where t1.seq_bakasha = p_seq_bakasha;
  
    -----------------
    update ld_log t18
       set t18.seq_bakasha = null, t18.date_delete = sysdate
     where seq_bakasha = p_seq_bakasha;
  
    update ld_salary_base ls
       set ls.seq_bakasha = null, ls.date_delete = sysdate
     where seq_bakasha = p_seq_bakasha;
    -----------------
    delete from bakasha t where t.seq_bakasha = p_seq_bakasha;
  
    --If there is no other bakashot for the prisha
    if v_cnt_other_bakashot_fr_prisha = 0 then
      delete from porshim_achronim b where b.seq_prisha = v_seq_prisha;
      delete from prisha a where a.seq_prisha = v_seq_prisha;
    
      --If there is no other prishot for the poresh
      if v_cnt_other_prishot_for_poresh = 0 then
        delete from action_log where SEQ_PORESH = v_seq_poresh;
        for r in (select *
                    from bney_mishpacha bm
                   where bm.Seq_Porshim = v_seq_poresh) loop
          delete from MAZAV_MISHPACHTI mm
           where mm.seq_bney_mishpacha = r.seq_bney_mishpacha;
        end loop;
      
        delete from bney_mishpacha where SEQ_PORSHIM = v_seq_poresh;
        delete from medical_vaada where SEQ_PORESH = v_seq_poresh;
        delete from tashlum_guf where SEQ_PORESH = v_seq_poresh;
        delete from tashlum_guf_draft where SEQ_PORESH = v_seq_poresh;
        delete from address where seq_poresh = v_seq_poresh;
        delete from MAZAV_MISHPACHTI where seq_poresh = v_seq_poresh;
        delete from poresh p where p.porshim_seq = v_seq_poresh;
      
      end if;
    
    end if;
  
    return 1;
  exception
    when others then
      return sqlcode;
  end;
  ---------------------------------------------------------------
  procedure Change_to_regular_remarks(p_seq_bakasha number) is
  begin
    update action_log t
       set t.code_action = 31
     where t.seq_bakasha = p_seq_bakasha
       and t.code_action = 45
       and t.code_user_update = 0;
    commit;
  end;
  ----------------------------------------------------------
  function get_sug_bakasha(p_seq_bakasha number) return number is
    v_count_previous_regila number := null;
    v_count_rechishot       number := 0;
    v_count_hagdalot        number := 0;
    v_code_sug_bakasha      number;
    v_code_source           number;
    v_mispar_zehut          number;
  begin
    select b.code_source, b.mispar_zehut
      into v_code_source, v_mispar_zehut
      from v_bakasha_last_status b
     where b.seq_bakasha = p_seq_bakasha;
  
    --get count previous bakasha regila.
    select count(*)
      into v_count_previous_regila
      from bakasha b1
      left join v_bakasha_last_status b2
        on b1.seq_prisha = b2.seq_prisha
     where b1.seq_bakasha = p_seq_bakasha
       and b2.seq_bakasha < p_seq_bakasha
       and b2.code_merge_bakasha = 1
          --code 17 is cancel bakasha
       and b2.code_action <> 17;
  
    --get count hagdalot
    select count(*)
      into v_count_hagdalot
      from hagdala_nimuk h
     where h.seq_bakasha = p_seq_bakasha;
  
    if v_count_previous_regila = 0 then
      --regila
      v_code_sug_bakasha := 1;
      --hagdala in chinuch is as a regular bakasha.
    elsif v_count_hagdalot > 0 and v_code_source <> 3 then
      --hagdalot
      v_code_sug_bakasha := 3;
    else
      --shinuyim
      v_code_sug_bakasha := 5;
    end if;
  
    update bakasha b
       set b.code_sug_bakasha = v_code_sug_bakasha
     where b.seq_bakasha = p_seq_bakasha;
  
    return v_code_sug_bakasha;
  end;
