  function get_next_user_for_bakasha(p_code_action number,
                                     p_seq_bakasha number,
                                     p_code_role   number default null)
    return number is
    v_code_user      number := null;
    v_seq_ezor_ovdim number;
    v_code_role      number;
    v_code_source    number;
    --v_code_role_current number;
    --v_code_sug_workflow number;
    v_sug_action   number;
    v_is_maarechet number;
    cursor sug_bakasha_cur is
      select ca.code_sug_action, ca.is_maarechet
        from code_action ca
       where ca.code_action = p_code_action;
  
  begin
  
    open sug_bakasha_cur;
    fetch sug_bakasha_cur
      into v_sug_action, v_is_maarechet;
    close sug_bakasha_cur;
    --פעולת מערכת
    if nvl(v_is_maarechet, 0) = 1 then
      v_code_user := 0;
      --פעולה סופית
    elsif nvl(v_sug_action, 0) = 5 then
      v_code_user := null;
      --באמצע שלב מחזיר את המטפל הנוכחי
    elsif nvl(v_sug_action, 0) <> 1 then
      begin
        select nvl(a.code_user_to_internal, 0)
          into v_code_user
          from v_bakasha_last_status a
         where a.seq_bakasha = p_seq_bakasha;
      exception
        when no_data_found then
          v_code_user := 0;
      end;
    elsif p_code_action = 148 and p_code_role = 6 then
      --בחתימה מנהל גמלאות, לחפש תמיד משתמש עם חלקיות גבוהה ביותר
      select max(t1.code_user) keep(dense_rank first order by t.chelkiut desc, t.date_from desc) code_user
        into v_code_user
        from perm_user_role_chelkiut t
        left join perm_user_role t1
          on t.seq_perm_user_role = t1.seq_perm_user_role
       where t1.code_role = p_code_role
         and t.date_from < sysdate;
    else
      begin
        -- מוצא את המטפל הראשון מתוך רשימת המטפלים האפשרים לפעולה
        -- העדיפות מטופלת ב-VIEW
        select case au.code_role
               -- בנשם לבדוק לפי גוף
                 when 2 then
                  pk_load_mimshak.Get_user_id_by_category(au.seq_ezor_ovdim)
                 else
                  au.code_user
               end
          into v_code_user
          from v_users_for_actions au
         where au.seq_bakasha = p_seq_bakasha
           and au.code_action = p_code_action
           and rownum = 1;
      exception
        --When the role (v_code_role) was not be in the workflow of the bakasha
        when no_data_found then
          v_code_user := null;
      end;
    end if;
    /*
    -------------- for Electronic Tik -----------------
    --1.
    select v.code_source
      into v_code_source
      from v_bakasha_last_status v
     where v.seq_bakasha = p_seq_bakasha;
    
    if
    --merkava or chinch
     v_code_source in (3)
    --'natav tikim Physically'
     and v_code_user = 168 then
      -- set user: simona
      v_code_user := 118;
    end if;
    
    --2.
    if v_code_source <> 3 and p_code_action = 114 then
      v_code_user := 143;
    end if;
    
    -------------- end for Electronic Tik -----------------
    */
    return v_code_user;
  end;
  ----------------------------------------------------------
  procedure Add_steps(p_seq_bakasha      in out number,
                      p_code_user_update number default null,
                      p_count_steps      number default 1) is
    v_current_action          number;
    v_code_sug_workflow       number;
    v_action_before_next_step number;
    v_max_action_for_wf       number;
    v_recipient               varchar2(1000) := 'zehavas@mof.gov.il, hanafr@mof.gov.il,dvora@mof.gov.il';
    v_Add_steps_was_failed    clob := 'Can not add ' || p_count_steps ||
                                      ' steps to the bakasha: ' ||
                                      p_seq_bakasha;
  begin
    --Get current_action
    select v.code_action, v.code_sug_workflow
      into v_current_action, v_code_sug_workflow
      from v_bakasha_last_status v
     where v.seq_bakasha = p_seq_bakasha;
  
    --Get max action in the workflow
    select *
      into v_max_action_for_wf
      from (select w.code_action
              from workflow w
             where w.code_sug_workflow = v_code_sug_workflow
             order by w.order_wf desc)
     where rownum = 1;
  
    --The group name in the table is not nust order by 'order numbers'
    -- and there for: Group steps and get for them the last action in the step by 'order_wf' field
    with t_with as
     (select step, code_action_step, rownum n
        from (select distinct w.step,
                              first_value(w.order_wf) over(partition by w.step order by w.order_wf desc) order_step,
                              first_value(w.code_action) over(partition by w.step order by w.order_wf desc) code_action_step
                from workflow w
               where w.code_sug_workflow = v_code_sug_workflow
                 and step is not null
               order by order_step)
      
      )
    --Get code action one row before the request step,
    -- In order to send it as parameter to function(Add_next_action)
    select b.code_action_step
      into v_action_before_next_step
      from WORKFLOW t1
      left join t_with a
        on t1.step = a.step
      left join t_with b
        on b.n = a.n + p_count_steps - 1
     where t1.code_sug_workflow = v_code_sug_workflow
       and t1.code_action = v_current_action;
  
    if v_action_before_next_step is null or
       v_action_before_next_step = v_max_action_for_wf then
      --When the requset step is not exist
      --or v_action_before_next_step is last in wf :
      --Send mail
      pk_prm_utils.send_attach(v_recipient,
                               'Add steps was failed',
                               null,
                               v_Add_steps_was_failed,
                               'txt',
                               'Add steps was failed.txt');
    else
      Add_next_action(p_seq_bakasha,
                      p_code_user_update,
                      v_code_sug_workflow,
                      v_action_before_next_step);
    end if;
  end;

  ----------------------------------------------------------
  function insert_action_particiption_frm return number is
    v_count_bakasha number := 0;
  begin
    for r in (select distinct *
                from (select v.seq_bakasha,
                             v.date_action,
                             trunc(add_months(p.taarich_leda, 1), 'month') taarich_zakaut,
                             n.code_group_prisha,
                             (select pd.age
                                from perm_decision_participation_to pd
                               where (nvl(pd.code_sug_ezor_ovdim, 0) =
                                     c.code_sug_ezor_ovdim or
                                     nvl(pd.seq_ezor_ovdim, 0) = pt.seq_guf)
                                 and pd.code_min = p.code_min
                                 and pd.code_sug_bakasha = v.code_sug_bakasha
                                 and nvl(pd.code_job, 0) =
                                     case b.chinuch_mikzoa
                                       when 911 then
                                        2
                                       else
                                        0
                                     end
                               order by pd.seq_ezor_ovdim fetch first 1 rows only) age
                      
                        from v_bakasha_last_status v
                        left join poresh p
                          on v.seq_porshim = p.porshim_seq
                        left join bakasha_regila b
                          on b.seq_bakasha = v.seq_bakasha
                        left join participation pt
                          on v.seq_bakasha = pt.seq_bakasha
                        left join ezor_ovdim_category c
                          on pt.seq_guf = c.seq_ezor_ovdim
                        left join netuney_tik_mechushavim n
                          on n.seq_bakasha = v.seq_bakasha
                         and n.code_department = 2
                         and n.mispar_misra = 0
                      --Wait to retirement age
                       where v.code_action = 132
                         and v.code_sug_bakasha = 7
                         and pk_expiried.is_ezor_ovdim_hilan(v.seq_ezor_ovdim) = 1
                      
                      ) t
               where
              --hakpaa-always 67, else by decision table
               (((months_between(sysdate, taarich_zakaut) + 3) / 12 >= age and
               code_group_prisha <> 3 or
               code_group_prisha = 3 and
               (months_between(sysdate, taarich_zakaut) + 3) / 12 >= 67) and
               to_char(add_months(taarich_zakaut, age * 12), 'YYYY') >
               '2020')) loop
    
      update bakasha b
         set b.code_bakasha_detail = 46
       where b.seq_bakasha = r.seq_bakasha;
    
      insert_action_log_row(186,
                            sysdate,
                            0,
                            null,
                            'תאריך תחילת זכאות בעוד פחות מ 3 חודשים',
                            null,
                            null,
                            null,
                            r.seq_bakasha,
                            null);
      insert_action_log_row(52,
                            sysdate,
                            0,
                            null,
                            null,
                            null,
                            null,
                            null,
                            r.seq_bakasha,
                            null);
    
      v_count_bakasha := v_count_bakasha + 1;
      commit;
    end loop;
    return v_count_bakasha;
  end;
  ----------------------------------------------------------
  function insert_action_Regular return number is
    v_count_bakasha number := 0;
    v_kapam         number := 0;
  begin
    for r in (select v.seq_bakasha,
                     v.seq_prisha,
                     date_start_zakaut,
                     p.taarich_leda
                from v_bakasha_last_status v
                left join netuney_tik_mechushavim n
                  on v.seq_bakasha = n.seq_bakasha
                 and n.code_department = 2
                left join poresh p
                  on p.porshim_seq = v.seq_porshim
              --Wait to retirement age
               where v.code_action = 132
                    --Date start zakaut will be in 1 month
                 and add_months(trunc(sysdate), 1) >=
                     trunc(n.date_start_zakaut)
                    -- and ((months_between(n.date_start_zakaut, p.taarich_leda)) / 12) < 67
                 and v.code_sug_bakasha = 1
                 and pk_expiried.is_ezor_ovdim_hilan(v.seq_ezor_ovdim) = 1) loop
    
      update bakasha b
         set b.code_bakasha_detail = 166
       where b.seq_bakasha = r.seq_bakasha;
    
      insert_action_log_row(173,
                            sysdate,
                            0,
                            null,
                            'תאריך תחילת זכאות בעוד פחות מחודש',
                            null,
                            null,
                            null,
                            r.seq_bakasha,
                            null);
      insert_action_log_row(86,
                            sysdate,
                            0,
                            null,
                            null,
                            null,
                            null,
                            null,
                            r.seq_bakasha,
                            null);
    
      v_count_bakasha := v_count_bakasha + 1;
      if ((months_between(r.date_start_zakaut, r.taarich_leda)) / 12) < 67 then
        v_kapam := insert_new_kapam(r.seq_prisha);
      end if;
      commit;
    end loop;
    return v_count_bakasha;
  end;

  ---        -------------------------------
  ----************************** שליפת בקשת קפמ קיימת    
  function insert_new_kapam(p_seq_prisha number) return number is
    v_seq_bakasha_kapam number := 0;
    v_count_kapam       number := 0;
    v_new_bakasha       number := 0;
  begin
    begin
      select max(kp.seq_bakasha)
        into v_seq_bakasha_kapam
        from v_bakasha_last_status kp
       where kp.seq_prisha = p_seq_prisha
            
         and kp.code_sug_bakasha in (10, 11)
         and kp.code_action <> 17;
    
    exception
      when no_data_found then
        --Not exist kapam bakasha
        v_seq_bakasha_kapam := null;
    end;
  
    if v_seq_bakasha_kapam is null then
      return v_count_kapam;
    else
      --- הוספת בקשה
      v_new_bakasha := duplicate_new_kapam(v_seq_bakasha_kapam);
      insert_action_log_row(38,
                            sysdate,
                            0,
                            get_next_user_for_bakasha(38, v_new_bakasha),
                            'קיימת פרישה לגמלאות יש להפסיק את התשלום',
                            null,
                            null,
                            null,
                            v_new_bakasha,
                            null);
      v_count_kapam := v_count_kapam + 1;
    end if;
  
    return v_count_kapam;
  end;
  -------------------------------

  ----------------------------------------------------------------------------
  function duplicate_new_kapam(p_seq_bakasha_old number) return number is
    v_seq_bakasha_new number;
  begin
    for r in (select *
                from v_bakasha_last_status v
               where v.seq_bakasha = p_seq_bakasha_old) loop
      -- open new participation
      v_seq_bakasha_new := pk_load_mimshak.Add_main_tables(r.seq_porshim,
                                                           r.seq_ezor_ovdim,
                                                           6,
                                                           11,
                                                           sysdate,
                                                           null,
                                                           null,
                                                           null);
      duplicate_bakasha(v_seq_bakasha_new, p_seq_bakasha_old);
    end loop;
    return v_seq_bakasha_new;
  end;
  ----------------------------------------------------------------------------

  ----------------------------------------------------------
  function insert_action_Retirement_age return number is
    v_count_bakasha_regular          number;
    v_count_bakasha_particiption_frm number;
  begin
    v_count_bakasha_regular          := insert_action_Regular;
    v_count_bakasha_particiption_frm := insert_action_particiption_frm;
    return v_count_bakasha_regular + v_count_bakasha_particiption_frm;
  end;
  ----------------------------------------------------------
  procedure insert_action_after_30_days(p_count_bakasha out number) is
  
  begin
    p_count_bakasha := 0;
    for r in (select v.seq_bakasha, v.code_sug_workflow
                from v_bakasha_last_status v
                left join action_log a
                  on v.seq_bakasha = a.seq_bakasha
                 and a.code_action = 55
               where v.code_sug_bakasha = 8
                 and v.code_action in (55, 78)
                 and trunc(a.date_action) < trunc(sysdate) - 29) loop
    
      Add_steps(r.seq_bakasha, 0);
      p_count_bakasha := p_count_bakasha + 1;
    end loop;
    commit;
  end;

  ----------------------------------------------------------
  procedure insert_action_log_row(v_code_action           number,
                                  v_date_action           date,
                                  v_code_user_update      number,
                                  v_code_user_to_internal number,
                                  v_remarks               varchar2,
                                  v_date_to_do            date,
                                  v_date_do               date,
                                  v_code_user_to_external number,
                                  v_seq_bakasha           number,
                                  v_seq_action_log_prev   number) is
    v_code_user_to_internal_final number;
    v_is_status                   number(1);
    v_seq_ezor_ovdim              number;
    v_code_role                   number;
    v_code_department             number;
    v_prev_action                 number;
  begin
    -- delete from err_action_log;
  
    --check if the code action is status
    select ca.is_status
      into v_is_status
      from code_action ca
     where ca.code_action = v_code_action;
  
    --get seq ezor ovdim by seq bakasha
    select p.seq_ezor_ovdim
      into v_seq_ezor_ovdim
      from bakasha b
      left join prisha p
        on p.seq_prisha = b.seq_prisha
     where b.SEQ_BAKASHA = v_seq_bakasha;
  
    begin
      ---מציאת תפקיד ומחלקה ליוזר אליו מעבירים את התיק לפי התהליך
      select w.code_role_to, cr.code_department
        into v_code_role, -- של v_code_user_to_internal
             v_code_department
        from workflow w
        left join workflow_2_sug_bakasha w2b
          on w2b.code_sug_workflow = w.code_sug_workflow
        left join v_bakasha b
          on b.code_sug_bakasha = w2b.code_sug_bakasha
         and b.code_source = w2b.code_source
        left join code_role cr
          on cr.code_role = w.code_role_to
       where b.seq_bakasha = v_seq_bakasha
         and w.next_action = v_code_action;
    exception
      when others then
        v_code_role       := null;
        v_code_department := null;
    end;
    -- במקרה של החזרה שתילה של המחלקה
    -- בהנחה שיש החזרות רק באותה מחלקה
    if (v_code_action = 49) then
      begin
        v_code_role := null;
        select a.code_department
          into v_code_department
          from v_bakasha_last_status b
          left join action_log a
            on a.seq_action_log = b.seq_action_log
         where a.code_user_update = v_code_user_update
           and b.seq_bakasha = v_seq_bakasha;
      exception
        when others then
          v_code_department := null;
      end;
    end if;
  
    if v_code_user_to_internal is not null then
      v_code_user_to_internal_final := v_code_user_to_internal;
    elsif v_is_status = 1 then
      v_code_user_to_internal_final := get_next_user_for_bakasha(v_code_action,
                                                                 v_seq_bakasha,
                                                                 v_code_role);
    end if;
  
    insert into action_log
      (seq_action_log,
       code_action,
       date_action,
       code_user_update,
       code_user_to_internal,
       remarks,
       date_to_do,
       date_do,
       code_user_to_external,
       seq_bakasha,
       seq_action_log_prev,
       code_role,
       code_department)
    values
      (action_log_seq.nextval,
       v_code_action,
       v_date_action,
       v_code_user_update,
       v_code_user_to_internal_final,
       v_remarks,
       v_date_to_do,
       v_date_do,
       v_code_user_to_external,
       v_seq_bakasha,
       v_seq_action_log_prev,
       v_code_role,
       v_code_department) log errors into err_action_log reject limit unlimited;
  
  end;
  -----------------------------------------------------------
  --Find next action
  procedure Find_next_action(v_code_sug_workflow in number,
                             v_current_action    in number,
                             v_next_action       in out number,
                             v_is_automatic      in out number) is
  begin
    --Get 'next action' and 'is automatic'.
    select w1.next_action, w2.is_automatic
      into v_next_action, v_is_automatic
      from workflow w1
      left join workflow w2
        on w1.next_action = w2.code_action
       and w1.code_sug_workflow = w2.code_sug_workflow
     where nvl(w1.code_action, 0) = nvl(v_current_action, 0)
       and w1.code_sug_workflow = v_code_sug_workflow;
  end Find_next_action;
  -----------------------------------------------
  function is_open_bakasha_prev(p_seq_bakasha_previos  number,
                                p_code_department      number,
                                p_code_sug_bakasha_new number default null)
    return number is
    v_is_merge_with_previos  number := 0;
    v_seq_open_bakasha       number;
    v_code_merge_bakasha_new number;
    v_code_sug_bakasha_prev  number;
    v_seq_prisha             number;
  begin
    v_seq_open_bakasha := p_seq_bakasha_previos;
  
    if p_code_department = 6 then
      v_is_merge_with_previos := is_bakasha_was_not_confirmed(v_seq_open_bakasha,
                                                              2);
    
    elsif p_code_department = 1 then
      v_is_merge_with_previos := is_bakasha_was_not_confirmed(v_seq_open_bakasha,
                                                              3);
    else
      v_is_merge_with_previos := is_bakasha_was_not_confirmed(v_seq_open_bakasha,
                                                              1);
    end if;
  
    return v_is_merge_with_previos;
  
  end;
  ----------------------------------------------
  function is_bakasha_was_not_confirmed(v_seq_bakasha_previos    number,
                                        v_code_action_breakpoint number
                                        --1: gimlaot 2: tashlumim 3:nshm
                                        ) return number is
    v_code_action_rejected        number := 100;
    v_code_action_gimla_kfula     number := 95;
    v_code_action_prisha_takanoni number := 132;
    v_is_merge_with_previos       number;
  begin
    begin
      --Check if merge with previos
      select case
             --Last action of bakasha is 'end' - siyum tipul
               when c.code_sug_action = 5 then
                0
             --when the current action is 'rejected'
               when v.code_action in
                    (v_code_action_rejected, v_code_action_gimla_kfula) then
                1
             
             --when the code department of current action is nshm
               when v_code_action_breakpoint = 3 and
                    v.code_department_action = 1 then
                1
               when v_code_action_breakpoint = 3 and
                    v.code_department_action <> 1 then
                0
             --end nshm
             
             --when order of current action less than order of code confirm (by code department)
             -- or order of current action greater than order of code 'siyum tipul' 
               when (nvl(w.order_wf, 0) < nvl(w2.order_wf, 0)) or
                    (nvl(w.order_wf, 0) > nvl(w3.order_wf, 0)) then
                1
               else
                0
             end as is_exist
        into v_is_merge_with_previos
        from v_bakasha_last_status v
        left join code_action c
          on v.code_action = c.code_action
      --Get the order_wf of the bakasha
        left join workflow w
          on w.code_sug_workflow = v.code_sug_workflow
         and w.code_action = v.code_action
      -- get confirm action
        left join code_sug_workflow sw
          on sw.code_sug_workflow = v.code_sug_workflow
      --Get the order_wf of confirm action
        left join workflow w2
          on w2.code_sug_workflow = sw.code_sug_workflow
         and w2.code_action = sw.code_action_lock
      --Get the order_wf of siyum tipul
        left join workflow w3
          on w3.code_sug_workflow = sw.code_sug_workflow
         and w3.code_action = 98
      
       where v.SEQ_BAKASHA = v_seq_bakasha_previos;
    exception
      when others then
        v_is_merge_with_previos := 0;
    end;
    return v_is_merge_with_previos;
  end;

  ----------------------------------------------

  function is_bakasha_in_department(v_seq_bakasha_previos number,
                                    v_department          number)
    return number is
    v_code_action_rejected    number := 100;
    v_code_action_gimla_kfula number := 95;
    v_is_merge_with_previos   number;
  begin
    begin
      --Check if merge with previos
      select case
               when v.code_department_action = v_department
                   -- also when the current action is 'rejected', merge.
                    or v.code_action in
                    (v_code_action_rejected, v_code_action_gimla_kfula) then
                1
               else
                0
             end as is_exist
        into v_is_merge_with_previos
        from v_bakasha_last_status v
       where v.SEQ_BAKASHA = v_seq_bakasha_previos;
    
    exception
      when others then
        v_is_merge_with_previos := 0;
    end;
    return v_is_merge_with_previos;
  end;
  -----------------------------------------------
  function get_previos_bakasha_by_seq(v_seq_bakasha number) return number is
    v_seq_bakasha_previos number;
  begin
    begin
      --Get seq bakasha previos
      select *
        into v_seq_bakasha_previos
        from (select b2.seq_bakasha
                from bakasha b1
                left join code_sug_bakasha s1
                  on b1.code_sug_bakasha = s1.code_sug_bakasha
                left join v_bakasha_last_status b2
                  on b1.seq_prisha = b2.seq_prisha
                left join code_sug_bakasha s2
                  on b2.code_sug_bakasha = s2.code_sug_bakasha
               where b1.seq_bakasha = v_seq_bakasha
                 and b2.seq_bakasha < b1.seq_bakasha
                 and s1.code_merge_bakasha = s2.code_merge_bakasha
                 and b2.code_action <> 17
               order by b2.seq_bakasha desc)
       where rownum = 1;
    exception
      when no_data_found then
        v_seq_bakasha_previos := null;
    end;
    return v_seq_bakasha_previos;
  end;
  -----------------------------------------------
  function check_if_merge_bakashot(v_seq_bakasha         in number,
                                   v_seq_bakasha_previos out number)
    return number is
    v_code_action_breakpoint number;
    v_code_bakasha_detail    number := 0;
  begin
  
    v_seq_bakasha_previos := get_previos_bakasha_by_seq(v_seq_bakasha);
    if v_seq_bakasha_previos is null then
      return 0;
    end if;
  
    --Get code_bakasha_detail  
    select b.code_bakasha_detail
      into v_code_bakasha_detail
      from bakasha b
     where b.seq_bakasha = v_seq_bakasha_previos;
  
    --Check if there is defrost freeze
    if v_code_bakasha_detail = 166 then
      return 0;
    end if;
  
    select decode(v.code_sug_bakasha, 14, 2, 1)
      into v_code_action_breakpoint
      from v_bakasha v
     where v.SEQ_BAKASHA = v_seq_bakasha;
  
    return is_bakasha_was_not_confirmed(v_seq_bakasha_previos,
                                        v_code_action_breakpoint);
  
  end;
  -----------------------------------------------
  --Merge the new bakasha with the previos
  procedure External_Merge_versions(v_seq_bakasha_prev number,
                                    v_seq_bakasha_new  number) is
    v_seq_bakasha_new_in_out number;
    v_temp_add_action        number := 1;
  begin
    v_seq_bakasha_new_in_out := v_seq_bakasha_new;
    Merge_versions(v_seq_bakasha_new_in_out,
                   v_temp_add_action,
                   v_seq_bakasha_prev);
  end;
  -----------------------------------------------
  --Merge the new bakasha with the previos
  procedure Merge_versions(v_seq_bakasha_new  in out number,
                           v_add_action       in out number,
                           v_seq_bakasha_prev number default null) is
    v_next_action_in_merge   number;
    v_code_source            number;
    v_step_number            number;
    v_is_merge_with_previos  number;
    v_seq_bakasha            number;
    v_is_exist_participation number;
  begin
  
    if v_seq_bakasha_prev is null then
      v_is_merge_with_previos := check_if_merge_bakashot(v_seq_bakasha_new,
                                                         v_seq_bakasha);
      if v_is_merge_with_previos <> 1 then
        return;
      end if;
    else
      v_seq_bakasha := v_seq_bakasha_prev;
    end if;
  
    select b.code_source
      into v_code_source
      from bakasha b
     where b.seq_bakasha = v_seq_bakasha_new;
  
    -- netuney tik
    delete from netuney_tik_mechushavim where seq_bakasha = v_seq_bakasha;
  
    update netuney_tik_mechushavim
       set seq_bakasha = v_seq_bakasha
     where seq_bakasha = v_seq_bakasha_new;
  
    --  bakasha regila
    UPDATE bakasha_regila
       SET (chisuv_lefy_nechut,
            ishur_prisha_lo_sof_hodesh,
            taarich_prisha,
            chinuch_mikzoa,
            chisuv_lefy_sheerut,
            code_seif_prisha,
            misrad_maskoret,
            nechut_achuz,
            mispar_misra_acharon,
            teur_misra_acharon,
            nechut_migbala_bknisa_lesherut,
            nechut_taarich_hamigbala,
            ishur_prisha_al_af_tik_mishmat,
            such_yemey_headrut,
            such_yemey_headrut_shnirkshu,
            nechut_achuz_nechut_leprisha,
            seq_contacts_ministries
            -- security fields
          ,
            taarich_chatimat_tofes,
            code_sub_seif_prisha,
            hivun_percent,
            is_tvia_zad_gimel,
            kizba_after_hagdala,
            date_freeze_haskem,
            is_contract_shikum,
            vetek,
            nechut_taarich_end_hamigbala) =
           (SELECT chisuv_lefy_nechut,
                   ishur_prisha_lo_sof_hodesh,
                   taarich_prisha,
                   chinuch_mikzoa,
                   chisuv_lefy_sheerut,
                   code_seif_prisha,
                   misrad_maskoret,
                   nechut_achuz,
                   mispar_misra_acharon,
                   teur_misra_acharon,
                   nechut_migbala_bknisa_lesherut,
                   nechut_taarich_hamigbala,
                   ishur_prisha_al_af_tik_mishmat,
                   such_yemey_headrut,
                   such_yemey_headrut_shnirkshu,
                   nechut_achuz_nechut_leprisha,
                   seq_contacts_ministries
                   -- security fields
                  ,
                   taarich_chatimat_tofes,
                   code_sub_seif_prisha,
                   hivun_percent,
                   is_tvia_zad_gimel,
                   kizba_after_hagdala,
                   date_freeze_haskem,
                   is_contract_shikum,
                   vetek,
                   nechut_taarich_end_hamigbala
              from bakasha_regila
             where seq_bakasha = v_seq_bakasha_new)
     where seq_bakasha = v_seq_bakasha;
  
    delete from bakasha_regila br where br.seq_bakasha = v_seq_bakasha_new;
  
    -- Tkufot_Avoda_Mechushv
    delete from Tkufot_Avoda_Mechushv where seq_bakasha = v_seq_bakasha;
  
    update Tkufot_Avoda_Mechushv
       set seq_bakasha = v_seq_bakasha
     where seq_bakasha = v_seq_bakasha_new;
  
    --tkufot_sherut_tsvaii
    delete from tkufot_sherut_tsvaii where seq_bakasha = v_seq_bakasha;
  
    update tkufot_sherut_tsvaii
       set seq_bakasha = v_seq_bakasha
     where seq_bakasha = v_seq_bakasha_new;
  
    --Tkufot_Avoda_Golmi
    delete from Tkufot_Avoda_Golmi where seq_bakasha = v_seq_bakasha;
  
    update Tkufot_Avoda_Golmi
       set seq_bakasha = v_seq_bakasha
     where seq_bakasha = v_seq_bakasha_new;
  
    --tkufot_michutz_lasharut
    delete from tkufot_michutz_lasharut where seq_bakasha = v_seq_bakasha;
  
    update tkufot_michutz_lasharut
       set seq_bakasha = v_seq_bakasha
     where seq_bakasha = v_seq_bakasha_new;
  
    --vetek_detail
    delete from vetek_detail vv
     where seq_bakasha = v_seq_bakasha
       and vv.seq_netuney_sachar is null;
  
    update vetek_detail
       set seq_bakasha = v_seq_bakasha
     where seq_bakasha = v_seq_bakasha_new;
  
    --hagdala_nimuk
    --chinuch send all the data Every time
    --and in the other sources:
    --delete old hagdale when there is a hagdala in the new bakasha.
    delete from hagdala_nimuk
     where seq_bakasha = v_seq_bakasha
       and (v_code_source = 3 or
           (select count(*)
               from hagdala_nimuk n
              where seq_bakasha = v_seq_bakasha_new) > 0);
  
    update hagdala_nimuk
       set seq_bakasha = v_seq_bakasha
     where seq_bakasha = v_seq_bakasha_new;
  
    --darga_vederug_tik
    delete from darga_vederug_tik where seq_bakasha = v_seq_bakasha;
  
    update darga_vederug_tik
       set seq_bakasha = v_seq_bakasha
     where seq_bakasha = v_seq_bakasha_new;
  
    --document
    update document_bakasha
       set seq_bakasha = v_seq_bakasha
     where seq_bakasha = v_seq_bakasha_new;
  
    select decode(count(w.workflow_seq), 0, 0, 1)
      into v_add_action
      from v_bakasha_last_status v
      left join workflow w
        on w.code_sug_workflow = v.code_sug_workflow
       and w.code_action =
           (select v.code_action
              from v_bakasha_last_status v
             where v.seq_bakasha = v_seq_bakasha)
     where v.SEQ_BAKASHA = v_seq_bakasha_new;
  
    if v_add_action = 1 then
      -- actions log
      select max(a.step_number)
        into v_step_number
        from action_log a
       where a.seq_bakasha = v_seq_bakasha;
    
      update action_log a
         set a.step_number = nvl(v_step_number, 0) + 1
       where a.seq_bakasha = v_seq_bakasha
         and a.step_number is null;
    
      -- actions log
      update action_log a
         set a.seq_bakasha = v_seq_bakasha
       where a.seq_bakasha = v_seq_bakasha_new;
    else
      delete from action_log a where a.seq_bakasha = v_seq_bakasha_new;
    end if;
  
    --address
    update address
       set seq_bakasha = v_seq_bakasha
     where seq_bakasha = v_seq_bakasha_new;
  
    delete from netuney_tik_mechushav_chnuch n
     where n.seq_bakasha = v_seq_bakasha_new;
  
    select count(*)
      into v_is_exist_participation
      from participation p
     where p.seq_bakasha = v_seq_bakasha_new;
  
    if v_is_exist_participation > 0 then
    
      delete from participation_tkufot p
       where p.seq_participation in
             (select p1.seq_participation
                from participation p1
               where p1.seq_bakasha = v_seq_bakasha);
    
      delete from participation p where p.seq_bakasha = v_seq_bakasha;
    
      update participation p
         set p.seq_bakasha = v_seq_bakasha
       where p.seq_bakasha = v_seq_bakasha_new;
    
    end if;
  
    --update the new seq_bakasha if exist in ld_log
    update ld_log l
       set l.seq_bakasha = v_seq_bakasha
     where l.seq_bakasha = v_seq_bakasha_new;
  
    --update to the new source
    update bakasha b
       set b.code_source = v_code_source
     where b.seq_bakasha = v_seq_bakasha;
  
    delete from bakasha b where b.seq_bakasha = v_seq_bakasha_new;
  
    --The new bakasha was deleted, so - the previos is relevant and active.
    v_seq_bakasha_new := v_seq_bakasha;
  
  end;
  -----------------------------------------------
  procedure skip_in_roham_gishur_wf(v_seq_bakasha number,
                                    v_next_action in out number,
                                    v_remarks     in out varchar2) is
    v_seq_ezor_ovdim   number;
    v_code_seif_prisha number;
  begin
    select p.seq_ezor_ovdim, br.code_seif_prisha
      into v_seq_ezor_ovdim, v_code_seif_prisha
      from bakasha b
      left join prisha p
        on b.seq_prisha = p.seq_prisha
      left join bakasha_regila br
        on b.seq_bakasha = br.seq_bakasha
     where b.seq_bakasha = v_seq_bakasha;
    --The v_seq_ezor_ovdim=roham
    if v_seq_ezor_ovdim = 10154 and v_code_seif_prisha = 1 then
      --skip!
      v_next_action := 114;
      v_remarks     := 'אישור תשלומים - רוהמ';
    end if;
  end;
  -----------------------------------------------
  procedure skip_in_hp_roham_wf(v_seq_bakasha number,
                                v_next_action in out number,
                                v_remarks     in out varchar2) is
    v_seq_ezor_ovdim number;
  begin
    select p.seq_ezor_ovdim
      into v_seq_ezor_ovdim
      from bakasha b
      left join prisha p
        on b.seq_prisha = p.seq_prisha
     where b.seq_bakasha = v_seq_bakasha;
    --The v_seq_ezor_ovdim=roham
    if v_seq_ezor_ovdim = 10154 then
      --skip!
      v_next_action := 949;
      v_remarks     := 'אישור תשלומים - רוהמ';
    end if;
  end;
  -----------------------------------------------
  procedure skip_in_hp_wf(v_seq_bakasha number,
                          v_next_action in out number,
                          v_remarks     in out varchar2) is
    v_cnt_document_confirm number;
  begin
    select count(*)
      into v_cnt_document_confirm
      from document_bakasha db
      left join document d
        on db.seq_document = d.seq_document
     where db.seq_bakasha = v_seq_bakasha
       and d.seq_document_type = 82
       and db.pail = 1;
    --The confirm document is exist
    if v_cnt_document_confirm > 0 then
      --skip!
      v_next_action := 33;
      v_remarks     := 'מסמך אישור קבלה קיים';
    end if;
  end;
  -----------------------------------------------
  procedure skip_in_hp_future_and_e_zakaut(p_seq_bakasha number,
                                           v_next_action in out number,
                                           v_remarks     in out varchar2,
                                           v_next_user   in out number) is
    v_code_sug_bakasha       number;
    v_hp_date_start_zakaut   date;
    v_seq_ezor_ovdim         number;
    v_is_ezor_ovdim_relevant number;
    v_code_e_zakaut          number;
  begin
    select v.code_sug_bakasha,
           v.seq_ezor_ovdim,
           n.hp_date_start_zakaut,
           nvl(n.code_e_zakaut, 0)
      into v_code_sug_bakasha,
           v_seq_ezor_ovdim,
           v_hp_date_start_zakaut,
           v_code_e_zakaut
      from v_bakasha_last_status v
      left join netuney_tik_mechushavim n
        on v.seq_bakasha = n.seq_bakasha
       and n.code_department = 2
       and n.mispar_misra = 0
     where v.seq_bakasha = p_seq_bakasha;
    --* 
    if v_code_e_zakaut not in (0,9,10)  and v_code_sug_bakasha <> 12 then
      --Wait to send letter
      v_next_action := 129;
      v_remarks     := 'אין זכאות (מסלול לרוב סוגי הבקשות)';
    end if;
  
    if v_code_sug_bakasha = 12 then
      --E zakaut
      if v_code_e_zakaut > 0 then
        v_next_action := 98;
        v_remarks     := 'אין זכאות';
        return;
      end if;
    
      v_is_ezor_ovdim_relevant := pk_expiried.is_ezor_ovdim_hilan(v_seq_ezor_ovdim);
    
      if v_hp_date_start_zakaut > add_months(sysdate, 3) and
        -- hp future
         v_is_ezor_ovdim_relevant = 1 then
        --skip to 'wait age'!
        v_next_action := 132;
        v_remarks     := 'תאריך תחילת זכאות עתידי יותר מ 3 חודשים';
        v_next_user   := 0;
      end if;
    end if;
  end;
  -----------------------------------------------
  procedure skip_in_freeze(p_current_action number,
                           p_seq_bakasha    number,
                           v_next_action    in out number,
                           v_remarks        in out varchar2,
                           v_next_user      in out number) is
    v_code_sug_bakasha       number;
    v_code_group_prisha      number;
    v_date_start_zakaut      date;
    v_seq_ezor_ovdim         number;
    v_is_ezor_ovdim_relevant number;
    v_code_bakasha_details   number;
  begin
    select v.code_sug_bakasha,
           n.code_group_prisha,
           n.date_start_zakaut,
           v.seq_ezor_ovdim,
           v.code_bakasha_detail
      into v_code_sug_bakasha,
           v_code_group_prisha,
           v_date_start_zakaut,
           v_seq_ezor_ovdim,
           v_code_bakasha_details
      from v_bakasha_last_status v
      left join netuney_tik_mechushavim n
        on v.seq_bakasha = n.seq_bakasha
       and n.code_department = 2
       and n.mispar_misra = 0
     where v.seq_bakasha = p_seq_bakasha;
  
    v_is_ezor_ovdim_relevant := pk_expiried.is_ezor_ovdim_hilan(v_seq_ezor_ovdim);
  
    if v_code_sug_bakasha = 1 and v_code_group_prisha = 3 and
       v_date_start_zakaut > add_months(sysdate, 3) and
       v_is_ezor_ovdim_relevant = 1 then
    
      v_remarks := 'תיק הקפאה, תאריך תחילת זכאות עתידי יותר מ 3 חודשים';
    
      /*if p_current_action = 12 then
        --skip to 'wait to Manager's signature gimlaot'!
        v_next_action := 148;
      els*/
      if p_current_action = 149 then
        --skip to 'send a letter'!
        v_next_action := 129;
      elsif p_current_action = 131 then
        --skip to 'wait age'!
        v_next_action := 132;
        v_next_user   := 0;
      end if;
    elsif v_code_sug_bakasha = 5 and v_code_bakasha_details = 25 and
          v_code_group_prisha = 3 and
          v_date_start_zakaut > add_months(sysdate, 3) and
          v_is_ezor_ovdim_relevant = 1 then
    
      v_remarks := 'תיק הקפאה, תאריך תחילת זכאות עתידי יותר מ 3 חודשים';
    
      /*if p_current_action = 12 then
        --skip to 'wait to Manager's signature gimlaot'!
        v_next_action := 148;
      els*/
      if p_current_action = 112 then
        --skip to 'send a letter'!
        v_next_action := 129;
      elsif p_current_action = 131 then
        --skip to 'wait age'!
        v_next_action := 134;
        v_next_user   := 0;
      end if;
    end if;
  
  end;
  ----------------------------------------------------------
  procedure skip_in_end_freeze(p_seq_bakasha           number,
                               v_current_action_in_out in out number,
                               v_next_action           in out number,
                               v_remarks               in out varchar2,
                               v_is_automatic          in out number) is
    v_is_have_gil_takanony number(1) := 0;
  begin
    select count(*)
      into v_is_have_gil_takanony
      from action_log a
     where a.seq_bakasha = p_seq_bakasha
       and a.code_action = 132;
  
    if v_is_have_gil_takanony > 0 then
      if v_current_action_in_out = 86 then
        v_next_action := 26;
        v_remarks     := 'סיום הקפאה';
      elsif v_current_action_in_out = 26 then
        v_next_action  := 27;
        v_remarks      := 'סיום הקפאה';
        v_is_automatic := 1;
      elsif v_current_action_in_out = 27 then
        --skip!
        v_next_action := 114;
        v_remarks     := 'סיום הקפאה';
      end if;
    end if;
  end;

  ----------------------------------------------------------
  procedure skip_when_Mayor(p_seq_bakasha number,
                            v_next_action in out number,
                            v_remarks     in out varchar2) is
    v_code_sug_bakasha    number;
    v_code_derug          number;
    v_code_bakasha_detail number;
  begin
  
    select b.code_sug_bakasha, b.code_bakasha_detail
      into v_code_sug_bakasha, v_code_bakasha_detail
      from bakasha b
     where b.seq_bakasha = p_seq_bakasha;
  
    select d.code_derug
      into v_code_derug
      from darga_vederug_tik d
     where d.seq_bakasha = p_seq_bakasha
     order by d.taarich_me desc fetch first 1 row only;
  
    if v_code_sug_bakasha in (8, 9) and v_code_bakasha_detail in (47, 48) then
      v_next_action := 134;
      v_remarks     := 'דרוג ראש עיר';
    end if;
  end;
  ----------------------------------------------------------
  procedure skip_to_supervisor(p_seq_bakasha number,
                               v_next_action in out number,
                               v_remarks     in out varchar2) is
    v_code_sug_bakasha  number;
    v_date_start_zakaut date;
  begin
    select v.code_sug_bakasha, n.date_start_zakaut
      into v_code_sug_bakasha, v_date_start_zakaut
      from v_bakasha_last_status v
      left join netuney_tik_mechushavim n
        on v.seq_bakasha = n.seq_bakasha
       and n.code_department = 2
       and n.mispar_misra = 0
     where v.seq_bakasha = p_seq_bakasha;
  
    if v_code_sug_bakasha in (1, 13) and
       v_date_start_zakaut < add_months(sysdate, -3) then
      v_next_action := 101;
      v_remarks     := 'תאריך זכאות מוקדם מתאריך חתימה יותר מ3 חודשים';
    end if;
  
  end;
  ----------------------------------------------------------
  procedure advance_freeze(p_seq_bakasha number,
                           v_next_action in out number,
                           v_remarks     in out varchar2) is
    v_code_sug_bakasha       number;
    v_code_bakasha_detail    number;
    v_seq_ezor_ovdim         number;
    v_is_ezor_ovdim_relevant number;
    v_seq_prisha             number;
    v_bakasha_wait_exsist    number;
    v_seq_bakasha_wait       number;
  begin
  
    select v.code_sug_bakasha,
           nvl(v.code_bakasha_detail, 0),
           v.seq_ezor_ovdim,
           v.seq_prisha
      into v_code_sug_bakasha,
           v_code_bakasha_detail,
           v_seq_ezor_ovdim,
           v_seq_prisha
      from v_bakasha_last_status v
     where v.seq_bakasha = p_seq_bakasha;
  
    v_is_ezor_ovdim_relevant := pk_expiried.is_ezor_ovdim_hilan(v_seq_ezor_ovdim);
  
    if v_code_sug_bakasha = 5 and v_code_bakasha_detail <> 25 and
       v_is_ezor_ovdim_relevant = 1 then
      --v_next_action := 115;
      --v_remarks     := 'לא הקדמת הקפאה';
      v_remarks     := v_remarks;
    else
      ----------ההקדמת הקפאה-------------
      if v_code_sug_bakasha = 5 and v_code_bakasha_detail = 25 then
        select count(*)
          into v_bakasha_wait_exsist
          from v_bakasha_last_status a
         where a.seq_prisha = v_seq_prisha
           and a.code_sug_bakasha = 1
           and a.code_action = 132;
        if v_bakasha_wait_exsist > 0 then
          select a.seq_bakasha
            into v_seq_bakasha_wait
            from v_bakasha_last_status a
           where a.seq_prisha = v_seq_prisha
             and a.code_sug_bakasha = 1
             and a.code_action = 132;
        
          insert_action_log_row(98,
                                sysdate,
                                0,
                                0,
                                'נסגר ע"י מערכת בזמן הוספת שינוי זכאות הקדמת הקפאה',
                                null,
                                null,
                                null,
                                v_seq_bakasha_wait,
                                null);
        end if;
      end if;
      -------------------------------------- 
    end if;
  end;
  ----------------------------------------------------------
  procedure defrost_freeze(p_seq_bakasha number,
                           v_next_action in out number,
                           v_remarks     in out varchar2) is
    v_code_sug_bakasha       number;
    v_code_bakasha_detail    number;
    v_seq_ezor_ovdim         number;
    v_is_ezor_ovdim_relevant number;
  begin
  
    select v.code_sug_bakasha,
           nvl(v.code_bakasha_detail, 0),
           v.seq_ezor_ovdim
      into v_code_sug_bakasha, v_code_bakasha_detail, v_seq_ezor_ovdim
      from v_bakasha_last_status v
     where v.seq_bakasha = p_seq_bakasha;
  
    v_is_ezor_ovdim_relevant := pk_expiried.is_ezor_ovdim_hilan(v_seq_ezor_ovdim);
  
    if v_code_sug_bakasha = 5 and v_code_bakasha_detail = 166 and
       v_is_ezor_ovdim_relevant = 1 then
      v_next_action := 98;
      v_remarks     := 'הפשרת הקפאה';
    end if;
  end;
  -----------------------------------------------------------
  function is_Special_population_Masach(p_code_derug number,
                                        p_code_darga number) return number is
    v_is_Special_derug number;
  begin
    if is_Special_population(p_code_derug) = 1 and
       ((nvl(p_code_derug, 0) = 82 and p_code_darga not in (32, 42, 52)) or
        nvl(p_code_derug, 0) <> 82) then
      return 1;
    else
      return 0;
    end if;
  end;
  -----------------------------------------------------------
  function is_Special_population(p_code_derug number) return number is
    v_is_Special_derug number;
  begin
    if nvl(p_code_derug, 0) in (4,
                                5,
                                6,
                                15,
                                23,
                                44,
                                45,
                                57,
                                568,
                                59,
                                566,
                                557,
                                558,
                                82,
                                83,
                                84,
                                85,
                                569) then
      return 1;
    else
      return 0;
    end if;
  end;
  -----------------------------------------------------------
  function is_Special_population_to_skip(p_code_derug number,
                                         p_code_darga number) return number is
    v_is_Special_derug number;
  begin
    if nvl(p_code_derug, 0) in
       (4, 6, 15, 44, 45, 57, 568, 59, 83, 84, 85, 569) or
       (nvl(p_code_derug, 0) = 82 and p_code_darga not in (32, 42, 52)) then
      return 1;
    else
      return 0;
    end if;
  end;
  -----------------------------------------------------------
  procedure Special_population(p_seq_bakasha number,
                               v_next_action in out number,
                               v_remarks     in out varchar2) is
    v_code_sug_bakasha number;
    v_seq_ezor_ovdim   number;
    v_code_derug       number;
    v_code_darga       number;
  begin
  
    select v.code_sug_bakasha, v.seq_ezor_ovdim, n.code_derug, n.code_darga
      into v_code_sug_bakasha, v_seq_ezor_ovdim, v_code_derug, v_code_darga
      from v_bakasha_last_status v
      left join netuney_sachar n
        on n.seq_bakasha = v.seq_bakasha
       and n.mispar_misra = 0
       and n.code_sug_maskoret = 1
     where v.seq_bakasha = p_seq_bakasha;
  
    if v_code_sug_bakasha in (1, 3, 5, 13) and
       (is_Special_population_to_skip(v_code_derug, v_code_darga) = 1 or
       v_seq_ezor_ovdim in (191, 194, 12485, 14091, 14039)) and
       pk_expiried.is_ezor_ovdim_hilan(v_seq_ezor_ovdim) = 1 then
      v_next_action := 98;
      v_remarks     := 'אוכלוסיה מיוחדת';
    end if;
  end;
