  -----------------------------------------------------------
  procedure update_participatn_by_changes(p_seq_bakasha               number,
                                          p_seq_bakasha_participation number) is
  begin
  
    --Delete old data in the participation
    delete from tkufot_avoda_mechushv
     where seq_bakasha = p_seq_bakasha_participation;
    delete from netuney_tik_mechushavim
     where seq_bakasha = p_seq_bakasha_participation;
  
    --Duplicate data
    duplicate_tkufot_avoda_mechushv(p_seq_bakasha_participation,
                                    p_seq_bakasha);
    duplicate_netuney_tik_mechushavim(p_seq_bakasha_participation,
                                      p_seq_bakasha,
                                      1);
  
    for r1 in (select rg1.code_seif_prisha,
                      rg1.taarich_prisha,
                      rg1.chinuch_mikzoa
                 from bakasha_regila rg1
                where rg1.seq_bakasha = p_seq_bakasha) loop
    
      --update bakasha_regila
      update bakasha_regila rg2
         set rg2.code_seif_prisha = r1.code_seif_prisha,
             rg2.taarich_prisha   = r1.taarich_prisha,
             rg2.chinuch_mikzoa   = r1.chinuch_mikzoa
       where rg2.seq_bakasha = p_seq_bakasha_participation;
    end loop;
  
  end;
  --------------------------------------------------------------------------- 
  procedure check_if_wait_for_gil_takanoni(p_seq_bakasha number) is
    v_seq_bakasha         number;
    v_code_sug_bakasha    number;
    v_code_bakasha_detail number;
    v_seq_prisha          number;
    --  v_code_action_lock        number;
  begin
    select a.code_sug_bakasha, a.code_bakasha_detail, a.seq_prisha
      into v_code_sug_bakasha, v_code_bakasha_detail, v_seq_prisha
      from bakasha a
     where a.seq_bakasha = p_seq_bakasha;
    if nvl(v_code_sug_bakasha, 0) = 5 and
       nvl(v_code_bakasha_detail, 0) = 25 then
      select a.seq_bakasha --,t.code_action_lock
        into v_seq_bakasha --,v_code_action_lock
        from v_bakasha_last_status a
      --   left join Code_Sug_Workflow t on t.code_sug_workflow=a.code_sug_workflow
       where a.seq_prisha = v_seq_prisha
         and a.code_sug_bakasha = 1
         and a.code_action = 132;
      if nvl(v_seq_bakasha, 0) > 0 then
        insert_action_log_row(98,
                              sysdate,
                              0,
                              0,
                              'נסגר ע"י מערכת בזמן הוספת שינוי זכאות הקדמת הקפאה',
                              null,
                              null,
                              null,
                              v_seq_bakasha,
                              null);
      end if;
    end if;
  end;
  ----------------------------------------------------------------------------
  function is_keren_participation(p_seq_bakasha number) return number is
    v_is_keren_count number;
  begin
    --Check guf if it is keren
    select count(*)
      into v_is_keren_count
      from participation p
      left join ezor_ovdim_category c
        on p.seq_guf = c.seq_ezor_ovdim
     where p.seq_bakasha = p_seq_bakasha
       and c.code_sug_ezor_ovdim in (2, 5);
  
    if v_is_keren_count = 0 then
      return 0;
    else
      return 1;
    end if;
  end;
  ---------------------------------------------------------------------------
  function is_tkufa_grtr_420_or_overlap(p_seq_bakasha number) return number is
    v_tkufa_mezaka_sherut number;
    v_tkufa_overlap_kizba number;
    v_sum_chodshey_maanak number;
  
    v_is_tkufa_grtr_420_or_overlap number := 0;
  begin
    --Get netuney tik mechushavim
    begin
      select n2.tkufa_mezaka_sherut, n2.tkufa_overlap_kizba
        into v_tkufa_mezaka_sherut, v_tkufa_overlap_kizba
        from netuney_tik_mechushavim n2
       where n2.seq_bakasha = p_seq_bakasha
         and n2.code_department = 2
         and n2.mispar_misra = 0;
    exception
      when others then
        v_tkufa_mezaka_sherut := 0;
        v_tkufa_overlap_kizba := 0;
    end;
  
    --Get sum months for the participation 
    select sum(p2.chodshey_maanak)
      into v_sum_chodshey_maanak
      from participation p2
     where p2.seq_bakasha = p_seq_bakasha;
  
    if nvl(v_tkufa_mezaka_sherut, 0) + nvl(v_sum_chodshey_maanak, 0) > 420 or
       nvl(v_tkufa_overlap_kizba, 0) > 0 then
      v_is_tkufa_grtr_420_or_overlap := 1;
    end if;
    return v_is_tkufa_grtr_420_or_overlap;
  end;
  ----------------------------------------------------------------------------
  function duplicate_new_participation(p_seq_bakasha_old number)
    return number is
    v_seq_bakasha_new number;
  begin
    for r in (select *
                from v_bakasha_last_status v
               where v.seq_bakasha = p_seq_bakasha_old) loop
      -- open new participation
      v_seq_bakasha_new := pk_load_mimshak.Add_main_tables(r.seq_porshim,
                                                           r.seq_ezor_ovdim,
                                                           17,
                                                           r.code_sug_bakasha,
                                                           sysdate,
                                                           null,
                                                           null,
                                                           null);
      duplicate_bakasha(v_seq_bakasha_new, p_seq_bakasha_old);
    end loop;
    return v_seq_bakasha_new;
  end;
  ----------------------------------------------------------------------------
  function is_action_bakash_bfor_specific(p_seq_bakasha          number,
                                          p_code_action_to_check number)
    return number is
    v_code_action              number;
    v_code_sug_workflow        number;
    v_is_action_befor_specific number;
  begin
    select b2.code_action, b2.code_sug_workflow
      into v_code_action, v_code_sug_workflow
      from v_bakasha_last_status b2
     where b2.seq_bakasha = p_seq_bakasha;
    if v_code_action = 225 then
      return 1;
    end if;
    begin
      --Action
      select case
               when w1.order_wf <= w2.order_wf then
                1
               else
                0
             end
        into v_is_action_befor_specific
      --Get the row of the action in the participation bakasha
        from workflow w1
      --Join to the WF by code_action_to_check
        left join workflow w2
          on w2.code_sug_workflow = v_code_sug_workflow
         and w2.code_action = p_code_action_to_check
       where w1.code_sug_workflow = v_code_sug_workflow
         and w1.code_action = v_code_action;
    exception
      when others then
        v_is_action_befor_specific := 0;
    end;
  
    return v_is_action_befor_specific;
  end;

  ----------------------------------------------------------------------------
  function Get_action_participation(p_seq_bakasha                  number,
                                    v_is_tkufa_grtr_420_or_overlap number)
    return number is
    v_code_action_new         number;
    v_return_to_start         number;
    v_before_edit_calculation number;
  begin
  
    v_return_to_start := is_action_bakash_bfor_specific(p_seq_bakasha, 109);
  
    if v_return_to_start = 1 or v_is_tkufa_grtr_420_or_overlap = 1 then
      --'Start' the WF
      v_code_action_new := 52;
    else
      v_before_edit_calculation := is_action_bakash_bfor_specific(p_seq_bakasha,
                                                                  64);
      if v_before_edit_calculation = 1 then
        --When the action is before 'Edit': insert only remark.
        v_code_action_new := 31;
      elsif v_before_edit_calculation = 0 then
        --'Wait to edit calculation'
        v_code_action_new := 64;
      end if;
    end if;
  
    return v_code_action_new;
  end;
  ----------------------------------------------------------------------------
  procedure mrege_changes_and_participatn(p_seq_bakasha number) is
    v_seq_bakasha_participation number;
    v_code_action_curent        number;
  
    v_is_tkufa_grtr_420_or_overlap number := 0;
  
    v_code_action_new number;
  begin
    begin
      select distinct first_value(b2.seq_bakasha) over(partition by b1.seq_bakasha order by b2.seq_bakasha desc) seq_bakasha_participation,
                      first_value(b2.code_action) over(partition by b1.seq_bakasha order by b2.seq_bakasha desc) code_action_current
        into v_seq_bakasha_participation, v_code_action_curent
        from bakasha b1
        left join v_bakasha_last_status b2
          on b1.seq_prisha = b2.seq_prisha
         and b2.code_sug_bakasha = 7
            -- and b2.seq_bakasha < b1.seq_bakasha
            --Participation is not in cancel
         and b2.code_action <> 17
       where b1.seq_bakasha = p_seq_bakasha
            --There is changes request - 'bakashat shinuyim'
         and b1.code_sug_bakasha in (3, 5);
    exception
      when no_data_found then
        --Not exist participation bakasha
        v_seq_bakasha_participation := null;
    end;
  
    if v_seq_bakasha_participation is null then
      return;
    end if;
  
    v_is_tkufa_grtr_420_or_overlap := is_tkufa_grtr_420_or_overlap(v_seq_bakasha_participation);
  
    if v_code_action_curent = 98 then
      --In end WF
      if v_is_tkufa_grtr_420_or_overlap = 0 then
        --exit
        return;
      elsif v_is_tkufa_grtr_420_or_overlap = 1 then
        --Open new bakasha and update the seq_bakasha variable
        v_seq_bakasha_participation := duplicate_new_participation(v_seq_bakasha_participation);
        --'Start' the WF
        v_code_action_new := 52;
      end if;
    
    elsif v_code_action_curent <> 98 then
      --Get action WF
      v_code_action_new := Get_action_participation(v_seq_bakasha_participation,
                                                    v_is_tkufa_grtr_420_or_overlap);
    
    end if;
    update_participatn_by_changes(p_seq_bakasha,
                                  v_seq_bakasha_participation);
  
    insert_action_log_row(v_code_action_new,
                          
                          sysdate,
                          0,
                          null,
                          'התבצע עדכון נתונים מבקשת שינוי זכאות',
                          null,
                          null,
                          null,
                          v_seq_bakasha_participation,
                          null);
  
    commit;
  end;
  -----------------------------------------------------------
  procedure mrege_change_salary_partcptn(p_seq_bakasha number) is
    v_seq_bakasha_participation number;
    v_code_action_curent        number;
  
    v_is_tkufa_grtr_420_or_overlap number := 0;
  
    v_before_edit_calculation number;
    v_code_action_new         number;
  
    v_is_keren_count number;
  begin
    begin
      select distinct first_value(b2.seq_bakasha) over(partition by b1.seq_bakasha order by b2.seq_bakasha desc) seq_bakasha_participation,
                      first_value(b2.code_action) over(partition by b1.seq_bakasha order by b2.seq_bakasha desc) code_action_current
        into v_seq_bakasha_participation, v_code_action_curent
        from bakasha b1
        left join v_bakasha_last_status b2
          on b1.seq_prisha = b2.seq_prisha
         and b2.code_sug_bakasha = 7
            --and b2.seq_bakasha < b1.seq_bakasha
            --Participation is not in cancel
         and b2.code_action <> 17
       where b1.seq_bakasha = p_seq_bakasha
            --There is changes request - 'bakashat shinuyim'
         and b1.code_sug_bakasha = 14;
    exception
      when no_data_found then
        --Not exist participation bakasha
        v_seq_bakasha_participation := null;
    end;
  
    if v_seq_bakasha_participation is null then
      return;
    end if;
  
    --Not in end
    if v_code_action_curent <> 98 then
      v_before_edit_calculation := is_action_bakash_bfor_specific(v_seq_bakasha_participation,
                                                                  64);
      if v_before_edit_calculation = 1 then
        --When the action is before 'Edit': no insert other action.
        v_code_action_new := v_code_action_curent;
      else
        --'Wait to edit calculation'
        v_code_action_new := 64;
      end if;
      --In end
    elsif v_code_action_curent = 98 then
    
      v_is_tkufa_grtr_420_or_overlap := is_tkufa_grtr_420_or_overlap(v_seq_bakasha_participation);
    
      --Sum tkufa greatrthan 420 or have overlapp periods
      if v_is_tkufa_grtr_420_or_overlap = 0 then
      
        --Check guf if it is keren
        v_is_keren_count := is_keren_participation(v_seq_bakasha_participation);
      
        if v_is_keren_count = 0 then
          --exit
          return;
        end if;
      
      end if;
      --Open new bakasha and update the seq_bakasha variable
      v_seq_bakasha_participation := duplicate_new_participation(v_seq_bakasha_participation);
      --'Start' the WF
      v_code_action_new := 52;
    end if;
  
    insert_action_log_row(v_code_action_new,
                          
                          sysdate,
                          0,
                          null,
                          'הבקשה עודכנה בעקבות שינוי שכר',
                          null,
                          null,
                          null,
                          v_seq_bakasha_participation,
                          null);
  
    commit;
  end;
  -----------------------------------------------------------

  procedure bakasha_from_meches(p_seq_bakasha number,
                                v_remarks     in out varchar2,
                                v_next_action in out number) is
    v_seq_ezor_ovdim number;
  begin
    select t.seq_ezor_ovdim
      into v_seq_ezor_ovdim
      from bakasha b
      left join prisha t
        on b.seq_prisha = t.seq_prisha
     where b.seq_bakasha = p_seq_bakasha;
  
    if v_seq_ezor_ovdim = 28 then
      v_next_action := 193;
      v_remarks     := 'מועבר לסריקת מסמכים ע"י המשרד';
      insert_action_log_row(193,
                            
                            sysdate,
                            0,
                            get_next_user_for_bakasha(193, p_seq_bakasha),
                            'מועבר לסריקת מסמכים ע"י המשרד',
                            null,
                            null,
                            null,
                            p_seq_bakasha,
                            null);
      commit;
    end if;
  end;
  -----------------------------------------------------------
  procedure gimlaot_kefel_zero(p_seq_bakasha number,
                               v_next_action in out number,
                               v_remarks     in out varchar2) is
    v_code_sug_bakasha number;
    v_kizba_chodshit   number;
    v_achuz_guf_final  number;
  begin
  
    select v.code_sug_bakasha
      into v_code_sug_bakasha
      from bakasha v
     where v.seq_bakasha = p_seq_bakasha;
  
    if v_code_sug_bakasha = 18 then
    
      begin
        select nvl(p.kizba_chodshit, 0), nvl(p.achuz_guf_final, 0)
          into v_kizba_chodshit, v_achuz_guf_final
          from participation p
         where p.seq_bakasha = p_seq_bakasha;
      exception
        when others then
          v_kizba_chodshit  := 0;
          v_achuz_guf_final := 0;
      end;
    
      if v_kizba_chodshit = 0 or v_achuz_guf_final = 0 then
        --Wait to send letter
        v_next_action := 98;
        v_remarks     := 'גמלאות כפל - סכום מתוקן או אחוז מתוקן שווה 0';
      end if;
    end if;
  
  end;
  -----------------------------------------------------------
  procedure check_current_action(v_seq_bakasha_in_out    in out number,
                                 v_current_action_in_out in out number,
                                 v_add_action            in out number,
                                 v_next_action           in out number,
                                 v_is_automatic          in out number,
                                 v_next_user             in out number,
                                 v_remarks               in out varchar2,
                                 v_sug_workflow          in number default null) is
  
    v_code_sug_bakasha    number;
    v_seq_ezor_ovdim      number;
    v_hagdala_nimuk_count number;
  begin
    --merge
    if v_current_action_in_out = 108 then
      Merge_versions(v_seq_bakasha_in_out, v_add_action);
      --bitchoni yadani - skip nzivut 
    elsif v_current_action_in_out = 30 and v_sug_workflow = 6 then
      select b.code_sug_bakasha
        into v_code_sug_bakasha
        from bakasha b
       where b.seq_bakasha = v_seq_bakasha_in_out;
      select v.seq_ezor_ovdim
        into v_seq_ezor_ovdim
        from v_bakasha_last_status v
       where v.seq_bakasha = v_seq_bakasha_in_out;
      select count(*)
        into v_hagdala_nimuk_count
        from hagdala_nimuk h
       where h.seq_bakasha = v_seq_bakasha_in_out;
    
      if v_code_sug_bakasha = 13 or v_seq_ezor_ovdim in (163, 164) or
         v_hagdala_nimuk_count = 0 then
        v_next_action := 21;
      end if;
      --skip hagdala bitachon
    elsif v_current_action_in_out = 103 and v_sug_workflow = 42 and
          v_seq_ezor_ovdim <> 10154 then
      v_next_action := 129;
      --skip in hp
    elsif v_current_action_in_out = 30 then
      skip_in_hp_wf(v_seq_bakasha_in_out, v_next_action, v_remarks);
      --skip in gishur roham
      select b.code_sug_bakasha
        into v_code_sug_bakasha
        from bakasha b
       where b.seq_bakasha = v_seq_bakasha_in_out;
      if v_code_sug_bakasha in (1, 3, 5, 13) then
        skip_in_roham_gishur_wf(v_seq_bakasha_in_out,
                                v_next_action,
                                v_remarks);
      end if;
      --skip in hp roham
    elsif v_current_action_in_out = 136 and v_sug_workflow = 21 then
      skip_in_hp_roham_wf(v_seq_bakasha_in_out, v_next_action, v_remarks);
    elsif v_current_action_in_out in (112, 131) then
      --skip in freeze
      skip_in_freeze(v_current_action_in_out,
                     v_seq_bakasha_in_out,
                     v_next_action,
                     v_remarks,
                     v_next_user);
    elsif v_current_action_in_out = 149 then
      --skip in freeze
      skip_in_freeze(v_current_action_in_out,
                     v_seq_bakasha_in_out,
                     v_next_action,
                     v_remarks,
                     v_next_user);
      --skip in hp future
      skip_in_hp_future_and_e_zakaut(v_seq_bakasha_in_out,
                                     v_next_action,
                                     v_remarks,
                                     v_next_user);
      --skip in interior after end freeze
    elsif v_current_action_in_out in (86, 26, 27) then
      skip_in_end_freeze(v_seq_bakasha_in_out,
                         v_current_action_in_out,
                         v_next_action,
                         v_remarks,
                         v_is_automatic);
    elsif v_current_action_in_out = 103 then
      advance_freeze(v_seq_bakasha_in_out, v_next_action, v_remarks);
    elsif v_current_action_in_out = 136 then
      --skip in defrost freeze
      defrost_freeze(v_seq_bakasha_in_out, v_next_action, v_remarks);
      --skip in Special population
      Special_population(v_seq_bakasha_in_out, v_next_action, v_remarks);
      --skip in participation from roam
      participation_from_roam(v_seq_bakasha_in_out,
                              v_next_action,
                              v_remarks);
      stop_payment_stop_Temporary(v_seq_bakasha_in_out,
                                  v_next_action,
                                  v_remarks);
    elsif v_current_action_in_out = 36 then
      -- skip_when_Mayor(v_seq_bakasha_in_out, v_next_action, v_remarks);
      --skip in participation to - E zakaut
      participation_2_E_zakaut(v_seq_bakasha_in_out,
                               v_next_action,
                               v_remarks);
      --skip in participation to - transfer money
      participation_2_transfer_money(v_seq_bakasha_in_out,
                                     v_next_action,
                                     v_remarks);
      --skip in participation to - moving to service
      participation_2_Moving_2_servc(v_seq_bakasha_in_out,
                                     v_next_action,
                                     v_remarks);
      --skip in participation 'keren & tel aviv municipality'
      participation_krn_or_telaviv(v_seq_bakasha_in_out,
                                   v_next_action,
                                   v_remarks);
    elsif v_current_action_in_out = 12 then
      --E zakaut
      E_zakaut_most_bakashot(v_seq_bakasha_in_out,
                             v_next_action,
                             v_remarks);
      --skip in zakai lmaanak
      --is_zakai_lmaanak(v_seq_bakasha_in_out, v_next_action, v_remarks);
      --merge between 'shinuyim' and participation
      mrege_changes_and_participatn(v_seq_bakasha_in_out);
      --skip in freeze
      skip_in_freeze(v_current_action_in_out,
                     v_seq_bakasha_in_out,
                     v_next_action,
                     v_remarks,
                     v_next_user);
    elsif v_current_action_in_out = 112 then
      --bakasha zakaut retro - sign by supervisor
    
      skip_to_supervisor(v_seq_bakasha_in_out, v_next_action, v_remarks);
      --skip in gimlaot kefel when fix fields is zero
      gimlaot_kefel_zero(v_seq_bakasha_in_out, v_next_action, v_remarks);
      --mrege change salary and partcptn
      mrege_change_salary_partcptn(v_seq_bakasha_in_out);
      /*-----------------------------------------
      ELSIF V_CURRENT_ACTION_IN_OUT = 101  THEN  
        
         CHECK_IF_WAIT_FOR_GIL_TAKANONI(V_SEQ_BAKASHA_IN_OUT);*/
      -- elsif v_current_action_in_out is null and v_sug_workflow in (17, 18) then
      ---  bakasha_from_meches(v_seq_bakasha_in_out, v_next_action, v_remarks);
    end if;
    ------------------------------------------
    if v_remarks is not null then
      v_remarks := 'התבצע דילוג עקב: ' || v_remarks;
    end if;
  
  end;
  -----------------------------------------------------------
  procedure wait_to_salary(p_seq_bakasha number) is
    v_is_sachar_was_updated number;
    v_seq_ezor_ovdim        number;
    v_last_sachar_action    number;
    v_date_confirm_payment  date;
    v_for_confirm_payment   number;
    v_code_sug_workflow     number;
    v_date_change_tkufa     date;
  begin
  
    select count(*)
      into v_is_sachar_was_updated
      from netuney_sachar t
     where t.seq_bakasha = p_seq_bakasha;
  
    select v.SEQ_EZOR_OVDIM
      into v_seq_ezor_ovdim
      from v_bakasha v
     where v.SEQ_BAKASHA = p_seq_bakasha;
    --chinuch
    if v_seq_ezor_ovdim = 206 then
    
      if v_is_sachar_was_updated = 0 then
        --there is no netuney sachar-try to get from chinuch salary interface
        v_is_sachar_was_updated := pk_chinuch_salary.update_sachar_for_bakasha(p_seq_bakasha);
      
      else
        --is payment confirm on past
        SELECT max(date_action)
          into v_date_confirm_payment
          FROM action_log
         WHERE code_action = 112
           and seq_bakasha = p_seq_bakasha;
      
        select v.code_sug_workflow
          into v_code_sug_workflow
          from v_bakasha_last_status v
         where v.seq_bakasha = p_seq_bakasha;
      
        if v_date_confirm_payment is not null then
          --is new netuney sachar after confirm
          SELECT code_action
            into v_last_sachar_action
            FROM (SELECT code_action,
                         remarks,
                         seq_action_log,
                         seq_bakasha,
                         DENSE_RANK() OVER(ORDER BY seq_action_log DESC) AS rnk
                    FROM action_log
                   WHERE code_action IN (112, 171)
                      or code_action = 31
                     and remarks like '%תאריך מזכה בשירות%') t
           WHERE t.seq_bakasha = p_seq_bakasha
             and rownum = 1;
        
          select max(t.date_action)
            into v_date_change_tkufa
            from action_log t
            left join action_log al_getmimshak
              on t.seq_bakasha = al_getmimshak.seq_bakasha
             and trunc(al_getmimshak.date_action) = trunc(t.date_action)
             and al_getmimshak.code_action = 122
           where t.seq_bakasha = p_seq_bakasha
             and t.code_action = 31
             and t.remarks like '%תאריך מזכה בשירות%'
             and al_getmimshak.seq_action_log is not null;
             
        
          if v_last_sachar_action = 112 then
            --there is no new sachar' go to hilan
            insert_action_log_row(31,
                                  sysdate,
                                  0,
                                  0,
                                  'דילוג על מחלקת תשלומים - לא השתנו נתוני שכר',
                                  null,
                                  null,
                                  null,
                                  p_seq_bakasha,
                                  null);
            Add_next_action(p_seq_bakasha, 0, v_code_sug_workflow, 112);
          elsif v_last_sachar_action = 171 then
            if v_date_confirm_payment > v_date_change_tkufa then
              --there ts new sachar, checck green pass
              select count(*)
                into v_for_confirm_payment
                from ld_salary_base t
                left join code_chinuch_salary_shinuy t1
                  on t.is_new_data = t1.code_chinuch_sug_shinuy
               where t.seq_bakasha = p_seq_bakasha
                 and t1.is_direct_hilan = 0
                 and t.date_status_get > v_date_confirm_payment;
            
              if v_for_confirm_payment = 0 then
                insert_action_log_row(31,
                                      sysdate,
                                      0,
                                      0,
                                      'דילוג על מחלקת תשלומים - לא השתנו נתוני שכר',
                                      null,
                                      null,
                                      null,
                                      p_seq_bakasha,
                                      null);
                Add_next_action(p_seq_bakasha, 0, v_code_sug_workflow, 112);
              else
                --continous to payment department
                v_is_sachar_was_updated := 1;
              end if; --end if for payments
            
            end if;
          else
            --change tkufa
            v_is_sachar_was_updated := 1;
          end if; --   end if new netuney sachar 
        else
          v_is_sachar_was_updated := 1;
        end if; -- end if confirmed by payment on past
      end if; --exists netuney sachar
    else
      --other office
      if v_is_sachar_was_updated = 0 then
        v_is_sachar_was_updated := pk_mlm_salary.update_sachar_for_bakasha(p_seq_bakasha);
      else
        v_is_sachar_was_updated := 1;
      end if;
    end if; --end if ezor ovdim
  
    if v_is_sachar_was_updated = 1 then
      insert_actions_for_bakasha(p_seq_bakasha, 0);
    end if;
end;
  -----------------------------------------------------------

  procedure check_next_action(p_seq_bakasha number, p_code_action number) is
  
  begin
    --update sachar
    if p_code_action = 146 then
      wait_to_salary(p_seq_bakasha);
    
    end if;
  end;
  -----------------------------------------------
  function Get_remarks(p_seq_bakasha number) return varchar2 is
    v_remarks varchar2(1000) := null;
  begin
    select decode(c.code_sug_action, 1, v.remarks, null)
      into v_remarks
      from v_bakasha_last_status v
      left join code_action c
        on v.code_action = c.code_action
     where v.seq_bakasha = p_seq_bakasha;
  
    return v_remarks;
  
  end;
  -----------------------------------------------
  procedure Add_next_action(v_seq_bakasha                number,
                            v_code_user_update           number,
                            v_code_sug_workflow          number,
                            v_current_action             number,
                            v_next_code_user_to_internal number default null) is
    v_next_action           number := null;
    v_next_code_user_update number;
    v_is_automatic          number(1) := 0;
    v_is_merge_with_previos number;
    v_seq_bakasha_in_out    number;
    v_current_action_in_out number;
    v_next_user_in_out      number;
    v_add_action            number := 1;
    v_remarks               varchar2(1000);
  begin
    v_seq_bakasha_in_out    := v_seq_bakasha;
    v_current_action_in_out := v_current_action;
    v_next_user_in_out      := v_next_code_user_to_internal;
  
    --check current action
    check_current_action(v_seq_bakasha_in_out,
                         v_current_action_in_out,
                         v_add_action,
                         v_next_action,
                         v_is_automatic,
                         v_next_user_in_out,
                         v_remarks,
                         v_code_sug_workflow);
  
    if v_add_action = 1 then
    
      if v_next_action is null then
        Find_next_action(v_code_sug_workflow,
                         v_current_action_in_out,
                         v_next_action,
                         v_is_automatic);
      end if;
    
      if v_remarks is null then
        v_remarks := Get_remarks(v_seq_bakasha_in_out);
      end if;
    
      insert_action_log_row(v_next_action,
                            sysdate,
                            v_code_user_update,
                            v_next_user_in_out,
                            v_remarks,
                            null, -- 'date to do' by 'days' in 'workflow' table, when it will be full
                            null,
                            null,
                            v_seq_bakasha_in_out,
                            null);
    end if;
  
    commit;
  
    --check next action
    check_next_action(v_seq_bakasha_in_out, v_next_action);
  
    --Get current action
    select v.code_user_to_internal
      into v_next_code_user_update
      from v_bakasha_last_status v
     where v.seq_bakasha = v_seq_bakasha_in_out;
  
    if v_is_automatic = 1 then
      Add_next_action(v_seq_bakasha_in_out,
                      v_next_code_user_update,
                      v_code_sug_workflow,
                      v_next_action);
    end if;
  
  end;
  -----------------------------------------------------------
  procedure insert_actions_for_bakasha(v_seq_bakasha                number,
                                       v_code_user_update           number default null,
                                       v_next_code_user_to_internal number default null) is
    v_code_sug_workflow            number;
    v_current_action               number;
    v_currnt_code_user_to_internal number;
    v_title                        varchar2(100);
    v_message                      varchar2(1000);
    v_attach                       clob;
    v_db_name                      varchar2(50);
    v_id                           number;
  begin
    --Get current action
    select v.code_action, v.code_user_to_internal, v.mispar_zehut
      into v_current_action, v_currnt_code_user_to_internal, v_id
      from v_bakasha_last_status v
     where v.seq_bakasha = v_seq_bakasha;
  
    --Get code_sug_workflow
    select w.code_sug_workflow
      into v_code_sug_workflow
      from bakasha b
      left join workflow_2_sug_bakasha w
        on b.code_sug_bakasha = w.code_sug_bakasha
       and b.code_source = w.code_source
     where b.seq_bakasha = v_seq_bakasha;
  
    if v_currnt_code_user_to_internal is null then
      v_currnt_code_user_to_internal := v_code_user_update;
    end if;
  
    Add_next_action(v_seq_bakasha,
                    v_currnt_code_user_to_internal,
                    v_code_sug_workflow,
                    v_current_action,
                    v_next_code_user_to_internal);
  exception
    when others then
      v_db_name := sys_context('userenv', 'DB_NAME');
      if (v_db_name = 'xt1' and v_current_action is not null) then
        --server is prd.
        v_title   := '''Add next action'' was failed (seq_bakasha - ' ||
                     to_char(v_seq_bakasha) || ' id - ' || to_char(v_id) || ')';
        v_message := ' code_sug_workflow is: ' ||
                     nvl(to_char(v_code_sug_workflow), 'empty') ||
                     ' and current_action is: ' ||
                     nvl(to_char(v_current_action), 'empty') ||
                     ' and the error is: ' || sqlerrm;
        v_attach  := to_char(sysdate, 'dd/mm/yyyy HH24:MI') || ' ' ||
                     v_title || v_message;
      
        pk_prm_utils.send_attach('zehavas@mof.gov.il, hanafr@mof.gov.il,dvora@mof.gov.il',
                                 v_title,
                                 v_message,
                                 v_attach,
                                 'txt',
                                 'Add_next_action_failed.txt');
      end if;
      rollback;
    
  end;
