  function get_new_code_action(old_code_action number) return number is
  begin
    return case old_code_action when 1 then 6 when 2 then 10 when 3 then 19 when 4 then 15 when 5 then 12 when 6 then 22 when 7 then 23 when 8 then 6 when 9 then 9 when 10 then 10 when 11 then 15 when 13 then 8 when 14 then 6 when 15 then 10 when 16 then 17 when 18 then 19 when 19 then 17 when 20 then 25 when 21 then 23 else 0 end;
  end;
  -----------------------------------------------------------
  function max_seq_bakasha(p_seq_bakasha number) return number result_cache is
    result number;
  begin
    begin
      select t1.seq_bakasha
        into result
        from v_regila_last_status t1
        left join bakasha t3
          on t1.seq_prisha = t3.seq_prisha
         and t3.code_sug_bakasha = 1
        left join bakasha_regila t2
          on t3.seq_bakasha = t2.seq_bakasha
       where t2.seq_bakasha = p_seq_bakasha;
    exception
      when no_data_found then
        result := -1;
    end;
    return(result);
  end;
  -----------------------------------------------------------
  function create_history_table(v_table_name varchar2) return clob is
    i   number;
    s   clob := 'create table ' || trim(substr(v_table_name, 1, 26)) ||
                '_his ' || chr(10) || '   as select * from ' ||
                v_table_name || chr(10) || ' where 1<>1;';
    s2  clob := 'alter table' || chr(10) ||
                trim(substr(v_table_name, 1, 26)) || '_his ' || chr(10) ||
                'add' || chr(10) || '   (' || chr(10) ||
                '   chg_date date         ,' || chr(10) ||
                '   chg_type varchar2(10)  ,' || chr(10) ||
                '   chg_by varchar2(100)    ' || chr(10) || '   );';
    s3  clob := 'create index ' || chr(10) ||
                trim(substr(v_table_name, 1, 22)) || '_his_idx on ' ||
                trim(substr(v_table_name, 1, 26)) || '_his ' ||
                '(chg_date,chg_by);';
    s4  varchar2(20000) := create_insert_list(v_table_name);
    s5  varchar2(20000) := create_insert_list(v_table_name, ':old.');
    s51 varchar2(20000) := replace(replace(replace(s5,
                                                   ':old.chg_date',
                                                   'sysdate'),
                                           ':old.chg_by',
                                           'user'),
                                   ':old.chg_type',
                                   'v_action');
    s6  varchar2(20000) := 'create or replace trigger ' ||
                           trim(substr(v_table_name, 1, 26)) || '_trg' ||
                           chr(10) || '  before update or delete on ' ||
                           v_table_name || chr(10) || '  for each row' ||
                           chr(10) || 'declare' || chr(10) ||
                           '  v_action varchar2(30);' || chr(10) || 'begin' ||
                           chr(10) || '  if updating then ' || chr(10) ||
                           '     v_action := ''update'';' || chr(10) ||
                           '   else v_action := ''delete'';' || chr(10) ||
                           '  end if;' || chr(10) || '    insert into ' ||
                           trim(substr(v_table_name, 1, 26)) || '_his ' || '(' ||
                           chr(10) || s4 || chr(10) || '    )' || chr(10) ||
                           '    values(' || chr(10) || s51 || chr(10) ||
                           '    );' || chr(10) || 'end ;';
  
  begin
    select count(*)
      into i
      from user_tables t
     where table_name = trim(upper(substr(v_table_name, 1, 26))) || '_his';
    if i = 1 then
      return 'the history table allready exists.';
    end if;
    return s || chr(10) || s2 || chr(10) || s3 || chr(10) || s6;
  
  end;
  -----------------------------------------------------------
  function create_insert_list(v_table_name varchar2,
                              prefix       varchar2 default '') return clob is
    tbl    varchar2(30) := upper(trim(v_table_name));
    result varchar2(32000) := '';
  begin
    for c in (select case r
                       when trunc(r) then
                        ''
                       else
                        '-- ' || to_char(trunc(r), '09')
                     end || nvl(column_name, '') ||
                     case column_id
                       when max(column_id) over() then
                        ''
                       else
                        ','
                     end clmn
                from (select '         ' ||
                             rpad(lower(prefix || column_name), 40, ' ') column_name,
                             c.column_id
                        from user_tab_columns c
                       where c.table_name = upper(tbl)
                      union all
                      select '         ' ||
                             rpad(lower(prefix || column_name), 40, ' ') column_name,
                             column_id
                        from (select case rownum
                                       when 1 then
                                        'chg_date'
                                       when 2 then
                                        'chg_type'
                                       when 3 then
                                        'chg_by'
                                     end column_name,
                                     column_id + rownum as column_id
                                from (select max(column_id) column_id
                                        from user_tab_columns c
                                       where c.table_name = upper(tbl))
                              connect by rownum <= 3)) c
                full join (select rownum r
                            from dual
                          connect by rownum <=
                                     (select max(column_id)
                                        from cols c
                                       where c.table_name = upper(tbl)) + 3
                          union all
                          select rownum * 5 + 0.5 r
                            from dual
                          connect by rownum <
                                     round(((select max(column_id)
                                               from cols c
                                              where c.table_name = upper(tbl)) + 3) / 5))
                  on column_id = r
               order by r asc) loop
      result := result || c.clmn || chr(10);
    end loop;
    return result;
  end;
