  procedure send_attach(recipient     in varchar2,
                        subject       in varchar2 default null,
                        message       in varchar2 default null,
                        att_msg       in out clob --varchar2
                       ,
                        att_mime_type in varchar2,
                        file_name     in varchar2 := 'results.xls'
                        --,mailhost in varchar2 default 'maor1'
                        ) is
    sender   varchar2(100) := 'mapam@mof.gov.il';
    mailhost varchar2(12) := 'f5_smtp_vip';
    crlf            constant varchar2(2) := chr(13) || chr(10);
    smtp_tcpip_port constant pls_integer := 25;
    --bytes_per_read constant pls_integer := 10000;
    bytes_per_read         constant pls_integer := 23829;
    boundary               constant varchar2(78) := '-------5e9i1bxfqrgl9cogs90-------';
    encapsulation_boundary constant varchar2(78) := '--' || boundary;
    final_boundary         constant varchar2(78) := '--' || boundary || '--';
  
    mail_conn   utl_smtp.connection;
    pos         pls_integer := 1;
    file_length pls_integer;
  
    diralias        varchar2(30);
    bfile_filename  varchar2(512) := file_name;
    lines_in_bigbuf pls_integer := 0;
    partial         varchar2(30000);
    rawval          raw(32000);
    to_write        varchar2(30000);
    tst_str         varchar2(30000);
    cset            varchar2(50) := '" encoding="iso-8859-8" ?';
    recipients      varchar2(200);
    ind             pls_integer := 1;
    rec             varchar2(200);
    v_db_name       varchar2(100);
    -------------------------------------------------
    procedure writedata(str in varchar2, crlfs in pls_integer default 1) is
    begin
      utl_smtp.write_data(mail_conn, str || rpad(crlf, 2 * crlfs, crlf));
    end;
    -------------------------------------------------
    function set_recipients(addressee varchar2) return varchar2 is
      v_add_src varchar2(200);
      v_addr    varchar2(200);
      slen      number := 1;
    begin
      v_add_src := replace(addressee, ' ', '_');
      if (instr(addressee, ',') = 0) then
        --return v_add_src;
        utl_smtp.rcpt(mail_conn, v_add_src);
        return v_add_src;
      else
        v_add_src := replace(addressee, ' ', '_') || ',';
        while (instr(v_add_src, ',', slen) > 0) loop
          v_addr := substr(v_add_src,
                           slen,
                           instr(substr(v_add_src, slen), ',') - 1);
          slen   := slen + instr(substr(v_add_src, slen), ',');
          utl_smtp.rcpt(mail_conn, v_addr);
        end loop;
        return v_addr;
      end if;
    end;
    -------------------------------------------------
  begin
    v_db_name := sys_context('userenv', 'DB_NAME');
    if v_db_name = 'xt1' then
      mailhost := 'smtp';
    end if;
    if v_db_name = 'ts2' then
      mailhost := 'smtp';
    end if;
    --dbms_lob.fileopen(att_bfile, dbms_lob.lob_readonly);
    att_msg     := replace(att_msg, '"?', cset);
    file_length := length(att_msg); -- dbms_lob.getlength(att_bfile);
    mail_conn   := utl_smtp.open_connection(mailhost, smtp_tcpip_port);
    utl_smtp.helo(mail_conn, mailhost);
    utl_smtp.mail(mail_conn, sender);
  
    --while  rec := length (regexp_substr('aa;bb,cc', '[^,; ]+',1, ind )) > 0
    loop
      --rec := regexp_substr('aa;bb,cc', '[^,; ]+',1, ind );
      rec := regexp_substr(recipient, '[^,; ]+', 1, ind);
      exit when length(rec) is null; --= 0;
      utl_smtp.rcpt(mail_conn, rec);
      ind := ind + 1;
    end loop;
  
    --recipients := set_recipients(recipient);
    --utl_smtp.rcpt(mail_conn, recipients);
    --utl_smtp.rcpt(mail_conn, recipient);
    utl_smtp.open_data(mail_conn);
    writedata('date: ' ||
              to_char(systimestamp, 'dy, dd mon yyyy hh24:mi:ss tzhtzm') || crlf ||
              'mime-version: 1.0' || crlf || 'from: ' || sender || crlf ||
              'subject: ' || subject || crlf || 'to: ' || recipient || crlf ||
              'content-type: multipart/mixed; boundary="' || boundary || '"',
              2);
  
    writedata(encapsulation_boundary);
    writedata('content-type: text/plain; charset=iso-8859-8; format=flowed');
    writedata('content-transfer-encoding: 7bit', 2);
    writedata(message, 2);
  
    --dbms_lob.filegetname(att_bfile, diralias, bfile_filename);
    writedata(encapsulation_boundary);
    writedata('content-type: ' || att_mime_type || '; name="' ||
              bfile_filename || '"');
    writedata('content-transfer-encoding: base64');
    writedata('content-disposition: attachment; filename="' ||
              bfile_filename || '"',
              2);
  
    /*   if file_length <= bytes_per_read then
      tst_str := to_char(att_msg);
      --rawval := utl_encode.base64_encode(dbms_lob.substr(att_msg,file_length));--(att_msg));
      rawval   := utl_encode.base64_encode(utl_raw.cast_to_raw(att_msg)); --(att_msg));
      to_write := utl_raw.cast_to_varchar2(rawval);
      writedata(to_write, 0);
    
    else*/
    while pos < file_length loop
      /*
      partial := substr(att_msg, bytes_per_read, pos);
      rawval := utl_encode.base64_encode(utl_raw.cast_to_raw(partial));
      to_write := utl_raw.cast_to_varchar2(rawval);
      writedata(to_write, 0);
      */
      writedata(utl_raw.cast_to_varchar2(utl_encode.base64_encode(utl_raw.cast_to_raw(dbms_lob.substr(att_msg,
                                                                                                      bytes_per_read,
                                                                                                      pos)))),
                0);
    
      /*
            writedata(utl_raw.cast_to_varchar2(
                        utl_encode.base64_encode
      (
                           substr(att_msg, bytes_per_read, pos))), 0);
                           */
      pos := pos + bytes_per_read;
    end loop;
    /*end if;*/
  
    writedata(crlf || crlf || final_boundary);
  
    utl_smtp.close_data(mail_conn);
    utl_smtp.quit(mail_conn);
    --dbms_lob.close(att_bfile);
    /**/
  end;
  ------------------------------------------------------------------------------------------------
  function convert_hebrew_to_ascii(s varchar2) return varchar2 is
    result varchar2(1000) := '';
    v_char varchar2(1);
  begin
    for i in 1 .. length(s) loop
      v_char := substr(s, i, 1);
      begin
        if ascii(v_char) < 32 or ascii(v_char) > 64 then
          result := result || chr(ascii(v_char) + 96);
        else
          result := result || v_char;
        end if;
      exception
        when others then
          result := result || v_char;
      end;
    end loop;
    return(result);
  exception
    when others then
      return s;
  end;
  ------------------------------------------------------------------------------------------------
  procedure reset_seq(p_seq_name in varchar2) is
    l_val number;
  begin
    execute immediate 'select ' || p_seq_name || '.nextval from dual'
      into l_val;
    execute immediate 'alter sequence ' || p_seq_name || ' increment by -' ||
                      l_val || ' minvalue 0';
    execute immediate 'select ' || p_seq_name || '.nextval from dual'
      into l_val;
    execute immediate 'alter sequence ' || p_seq_name ||
                      ' increment by 1 minvalue 0';
  end;
