  procedure Get_actions_to_id(p_id in number, cur out sys_refcursor) is
  begin
    open cur for
      select code_action.teur_action, a.seq_bakasha, a.*
        from v_regila_last_status_versions v
        left join action_log a
          on v.SEQ_BAKASHA = a.seq_bakasha
        left join code_action
          on code_action.code_action = a.code_action
       where v.MISPAR_ZEHUT = p_id
       order by a.seq_bakasha, a.seq_action_log;
  end;

