  procedure Get_gimla_number(p_prisha in number, p_user in number) is
  begin
    Get_gimla_without_commit(p_prisha, p_user);
    commit;
  end;
  ------------------------------------------------------------------------------------------------
  procedure Get_gimla_without_commit(p_prisha in number, p_user in number) is
    v_gimla_number            number := 0;
    v_count_same_gimla_number number;
    v_id                      number;
  begin
    --Check if 'prisha' has gimla number.
    select p.gimla_number, p1.mispar_zehut
      into v_gimla_number, v_id
      from prisha p
      left join poresh p1
        on p.seq_poresh = p1.porshim_seq
     where p.seq_prisha = p_prisha;
  
    --If exist gimla number, exit
    if nvl(v_gimla_number, 0) <> 0 then
      return;
    end if;
  
    --Check If there is in active emploee list from magal
    begin
      select t.gimla_number
        into v_gimla_number
        from gimla_number_active_employee t
       where t.id = v_id
         and t.date_used is null;
    
      update gimla_number_active_employee t
         set date_used = sysdate
       where t.id = v_id;
    exception
      when no_data_found then
        while true loop
          --Get new number
          v_gimla_number := gimla_number_seq.nextval;
        
          --Count rows from 'prisha' with same gimla number
          select count(*)
            into v_count_same_gimla_number
            from prisha t
           where t.gimla_number = v_gimla_number;
        
          --When the number is not exist,
          --return the number (and stop the loop)
          if v_count_same_gimla_number = 0 then
            exit;
          end if;
        end loop;
      
    end;
  
    update prisha t
       set t.gimla_number = v_gimla_number
     where t.seq_prisha = p_prisha;
  end;
