  ----------------------------------------------
  function get_holidays_number(p_date_begin date, p_date_end date)
    return number is
    holidays_number number;
  begin
    select count(*)
      into holidays_number
      from PB_system.pb_calendar t
     where to_date(to_char(t.year_g, '9999') || '/' ||
                   to_char(t.month_g, '99') || '/' ||
                   to_char(t.day_g, '99'),
                   'yyyy/mm/dd') between p_date_begin and p_date_end
       and t.holiday_type <> 'N'
       and t.holiday_type <> 'O';
    return(holidays_number);
  exception
    when others then
      return 0;
  end;
  ----------------------------------------------
  function get_action_from_step(p_wf       number,
                                p_step     number,
                                p_order_wf number) return number is
    action number;
  begin
    select w.code_action
      into action
      from workflow w, code_action ca
     where w.code_sug_workflow = p_wf
       and w.step = p_step
       and ca.code_sug_action = p_order_wf
       and w.code_action = ca.code_action;
    return(action);
  exception
    when others then
      return 0;
  end;
  ----------------------------------------------
  function get_previous_chelkiut(p_seq_perm_user_role number,
                                 p_date_from          date) return number is
    v_chelkiut number;
  begin
    select t.chelkiut
      into v_chelkiut
      from perm_user_role_chelkiut t
     where t.seq_perm_user_role = p_seq_perm_user_role
       and t.date_from =
           (select max(t1.date_from)
              from perm_user_role_chelkiut t1
             where t1.seq_perm_user_role = p_seq_perm_user_role
               and t1.date_from <= p_date_from)
       and t.seq_perm_user_role_chelkiut =
           (select max(t2.seq_perm_user_role_chelkiut)
              from perm_user_role_chelkiut t2
             where t.seq_perm_user_role = t2.seq_perm_user_role
               and t2.date_from = t.date_from);
    return(v_chelkiut);
  exception
    when others then
      return 1;
  end;
  ----------------------------------------------
  function get_cnt_bakashot_user_role_time(p_code_user        number,
                                           p_code_role        number,
                                           p_code_sug_bakasha number,
                                           p_code_department  number,
                                           p_begin_date       date,
                                           p_end_date         date)
    return number is
    mispar_bakashot number;
  begin
  
    if (p_code_user <> 0 and p_code_role <> 0) then
    
      select count(dates2.seq_bakasha)
        into mispar_bakashot
        from (select distinct dates1.seq_bakasha,
                              dates1.code_user_to_internal,
                              dates1.code_role,
                              dates1.code_department,
                              dates1.code_sug_bakasha
                from (select a.seq_action_log,
                             a.seq_bakasha,
                             a.code_user_to_internal,
                             a.code_role,
                             a.date_action,
                             decode(p_code_department,
                                    0,
                                    0,
                                    a.code_department) code_department,
                             b.code_sug_bakasha,
                             (select min(a1.date_action)
                                from action_log a1
                                left join code_sug_workflow sw
                                  on a1.code_action = sw.code_action_lock
                               where a1.seq_bakasha = a.seq_bakasha
                                 and b.code_sug_workflow =
                                     sw.code_sug_workflow) begin_date,
                             (select max(a2.date_action)
                                from action_log a2
                                left join code_sug_workflow sw
                                  on a2.code_action = sw.code_action_lock
                               where a2.seq_bakasha = a.seq_bakasha
                                 and b.code_sug_workflow =
                                     sw.code_sug_workflow) end_date
                        from action_log a
                        left join v_bakasha_last_status b
                          on b.seq_bakasha = a.seq_bakasha
                        left join code_action ca
                          on a.code_action = ca.code_action
                       where ca.is_external <> 1
                         and ca.is_status = 1
                         and ca.code_sug_action in (1, 2, 3)
                         and a.code_user_to_internal = p_code_user
                         and a.code_role = p_code_role
                         and b.code_sug_bakasha = p_code_sug_bakasha
                         and (p_code_department = 0 or
                             p_code_department <> 0 and
                             a.code_department = p_code_department)) dates1
               where dates1.end_date >= p_begin_date
                 and dates1.end_date < p_end_date
              --and dates1.date_action >= dates1.begin_date
              --and dates1.date_action <= dates1.end_date
              ) dates2
       group by dates2.code_department,
                dates2.code_user_to_internal,
                dates2.code_role,
                dates2.code_sug_bakasha
       order by dates2.code_department,
                dates2.code_user_to_internal,
                dates2.code_role,
                dates2.code_sug_bakasha;
    
    else
    
      select count(dates2.seq_bakasha)
        into mispar_bakashot
        from (select distinct dates1.seq_bakasha,
                              dates1.code_sug_bakasha,
                              dates1.code_department
                from (select a.seq_action_log,
                             a.seq_bakasha,
                             a.date_action,
                             b.code_sug_bakasha,
                             a.code_department,
                             (select min(a1.date_action)
                                from action_log a1
                                left join code_sug_workflow sw
                                  on a1.code_action = sw.code_action_lock
                               where a1.seq_bakasha = a.seq_bakasha
                                 and b.code_sug_workflow =
                                     sw.code_sug_workflow) begin_date,
                             (select max(a2.date_action)
                                from action_log a2
                                left join code_sug_workflow sw
                                  on a2.code_action = sw.code_action_lock
                               where a2.seq_bakasha = a.seq_bakasha
                                 and b.code_sug_workflow =
                                     sw.code_sug_workflow) end_date
                        from action_log a
                        left join v_bakasha_last_status b
                          on b.seq_bakasha = a.seq_bakasha
                       where b.code_sug_bakasha = p_code_sug_bakasha
                         and a.code_department = p_code_department) dates1
               where dates1.end_date >= p_begin_date
                 and dates1.end_date < p_end_date
              --and dates1.date_action >= dates1.begin_date
              --and dates1.date_action <= dates1.end_date
              ) dates2
       group by dates2.code_department, dates2.code_sug_bakasha
       order by dates2.code_department, dates2.code_sug_bakasha;
    end if;
    return mispar_bakashot;
  
  exception
    when others then
      return null;
    
  end;
