  function get_days_in_department(p_seq_action_log_end number,
                                  p_seq_bakasha        number,
                                  p_code_department    number) return number is
    department_days_number number;
    --declare
    v_code_department              number;
    v_min_seq_action_log           number := 0;
    v_date_action                  date;
    v_hefresh_department           number;
    v_next_department_date         date;
    next_department_seq_action_log number;
  begin
    department_days_number := 0;
    select a.code_department, a.seq_action_log, a.date_action
      into v_code_department, v_min_seq_action_log, v_date_action
      from action_log a
     where a.seq_bakasha = p_seq_bakasha
       and a.seq_action_log =
           (select min(a1.seq_action_log)
              from action_log a1
             where a1.seq_bakasha = a.seq_bakasha
               and a1.seq_action_log <= p_seq_action_log_end
                  --and a1.code_department in (2,5,6)
               and a1.code_department = p_code_department);
    for r in (select *
                from action_log a
               where a.seq_bakasha = p_seq_bakasha
                 and a.seq_action_log <= p_seq_action_log_end
               order by a.seq_action_log asc)
    --and a.code_department = v_code_department)
     loop
      v_date_action := r.date_action;
      if r.seq_action_log >= v_min_seq_action_log and
         r.code_department = v_code_department then
        select min(a3.seq_action_log)
          into next_department_seq_action_log
          from action_log a3
         where a3.seq_bakasha = r.seq_bakasha
           and a3.code_department <> r.code_department
           and a3.seq_action_log > r.seq_action_log;
        if next_department_seq_action_log is null then
          select max(a3.seq_action_log)
            into next_department_seq_action_log
            from action_log a3
           where a3.seq_bakasha = r.seq_bakasha
             and a3.code_department = r.code_department
             and a3.seq_action_log > r.seq_action_log;
        end if;
        select a4.date_action
          into v_next_department_date
          from action_log a4
         where a4.seq_action_log = next_department_seq_action_log;
        v_hefresh_department := v_next_department_date - v_date_action;
        v_hefresh_department := v_hefresh_department -
                                pk_prm_utils.get_holidays_number(v_date_action,
                                                                 v_next_department_date);
        --v_date_action := v_next_department_date;
        department_days_number := department_days_number +
                                  v_hefresh_department;
        v_min_seq_action_log   := next_department_seq_action_log;
      end if;
    end loop;
    return(round(department_days_number, 2));
  exception
    when no_data_found then
      return(round(department_days_number, 2));
    when others then
      return(null);
  end;
  procedure duplicate_bakasha(p_seq_bakasha_new  number,
                              p_seq_bakasha_prev number) is
    v_code_merge_bakasha_new number;
    v_code_sug_bakasha_new   number;
    v_seq_prisha             number;
    v_code_source_new        number;
    v_code_sug_bakasha_prev  number;
    v_seq_bakasha_prev       number;
    v_seq_ezor_ovdim         number;
    v_porshim_seq            number;
    v_prev_bakasha_vaada_ref number;
  begin
  
    select v.code_merge_bakasha,
           v.code_sug_bakasha,
           v.seq_prisha,
           v.code_source,
           v.seq_ezor_ovdim,
           v.seq_porshim
      into v_code_merge_bakasha_new,
           v_code_sug_bakasha_new,
           v_seq_prisha,
           v_code_source_new,
           v_seq_ezor_ovdim,
           v_porshim_seq
      from v_bakasha_last_status v
     where v.seq_bakasha = p_seq_bakasha_new;
  
    if p_seq_bakasha_prev is not null then
      select v.code_sug_bakasha
        into v_code_sug_bakasha_prev
        from v_bakasha_last_status v
       where v.seq_bakasha = p_seq_bakasha_prev;
    end if;
    --poresh doar-send mail to gvia
    if v_seq_ezor_ovdim in (191, 194) and
       v_code_sug_bakasha_new in (3, 5, 13, 14, 19, 7, 20) then
      pk_load_mimshak.send_mail_to_menahel_gvia(v_porshim_seq);
    end if;
    --
    if v_code_merge_bakasha_new in (1, 7) then
    
      select max(v.seq_bakasha)
        into v_seq_bakasha_prev
        from v_bakasha_last_status v
       where v.seq_prisha = v_seq_prisha
            ---by code_merge_bakasha
         and v.code_merge_bakasha in (1, 7)
            --not canceled bakasha
         and v.code_action <> 17
         and v.seq_bakasha < p_seq_bakasha_new;
    elsif v_code_merge_bakasha_new = 5 and v_seq_bakasha_prev is null then
      select max(v.seq_bakasha)
        into v_seq_bakasha_prev
        from v_bakasha_last_status v
       where v.seq_prisha = v_seq_prisha
            ---by code_merge_bakasha
         and v.code_merge_bakasha = 1
            --not canceled bakasha
         and v.code_action <> 17
         and v.seq_bakasha < p_seq_bakasha_new;
    else
      v_seq_bakasha_prev := p_seq_bakasha_prev;
    end if;
    if v_seq_bakasha_prev is not null then
      if v_code_merge_bakasha_new is not null and
         v_code_sug_bakasha_new <> 1 then
        if v_code_sug_bakasha_new not in (2, 14) then
          duplicate_bakasha_regila(p_seq_bakasha_new, v_seq_bakasha_prev);
          duplicate_participation_data(p_seq_bakasha_new,
                                       v_seq_bakasha_prev);
          duplicate_zakaut_data(p_seq_bakasha_new, v_seq_bakasha_prev);
          --shinuy_sachar
        elsif v_code_sug_bakasha_new = 14 then
          duplicate_netuney_sachar_data(p_seq_bakasha_new,
                                        v_seq_bakasha_prev);
        else
          --mukdemet
          duplicate_mukdemet_data(p_seq_bakasha_new, v_seq_bakasha_prev);
        end if;
      
        --for nasham
        if v_code_sug_bakasha_new in (3, 5) and v_code_source_new = 2 then
          duplicate_netuney_tik_mechushavim(p_seq_bakasha_new,
                                            v_seq_bakasha_prev);
        end if;
      
      end if;
      --hagdale after vaada refuit
      if v_code_sug_bakasha_new in (3, 5) and v_code_source_new = 11 then
        begin
          select max(t.seq_bakasha)
            into v_prev_bakasha_vaada_ref
            from v_bakasha_last_status t
           where t.seq_prisha = v_seq_prisha
             and t.code_sug_bakasha = 38
             and t.code_action = 98;
        exception
          when no_data_found then
            null;
        end;
        if nvl(v_prev_bakasha_vaada_ref, 0) <> 0 and
           v_prev_bakasha_vaada_ref > v_seq_bakasha_prev then
        
          duplicate_bakasha_regila(p_seq_bakasha_new,
                                   v_prev_bakasha_vaada_ref);
          delete from netuney_tik_mechushavim
           where seq_bakasha = p_seq_bakasha_new;
          duplicate_netuney_tik_mechushavim(p_seq_bakasha_new,
                                            v_seq_bakasha_prev);
        end if;
      end if;
      --vaada refuit
      if v_code_sug_bakasha_new = 38 then
        duplicate_bakasha_regila(p_seq_bakasha_new, v_seq_bakasha_prev);
      end if;
    else
      pk_load_mimshak.Add_details_tables(p_seq_bakasha_new,
                                         v_code_sug_bakasha_new);
    end if;
  end;
