  procedure duplicate_zakaut_data(p_seq_bakasha_new  number,
                                  p_seq_bakasha_prev number) is
    v_code_souce_bakasha_new number;
  begin
  
    --hagdala_nimuk
    insert into hagdala_nimuk
      (select code_nimuk,
              achuz_meushar,
              hearot,
              hagdala_nimuk_seq.nextval,
              taarich_bakashat_nimuk,
              code_hagdala_status_nimuk,
              me_taarich,
              ad_taarich,
              achuz_kodem,
              meushar_natsiv,
              p_seq_bakasha_new,
              months_hagdala,
              years_hagdala,
              shem_meadken_acharon,
              taarich_yetzira
         from hagdala_nimuk t
        where t.seq_bakasha = p_seq_bakasha_prev);
  
    --tkufot_avoda_mechushv
    duplicate_tkufot_avoda_mechushv(p_seq_bakasha_new, p_seq_bakasha_prev);
  
    select t.code_source
      into v_code_souce_bakasha_new
      from bakasha t
     where t.seq_bakasha = p_seq_bakasha_new;
  
    if v_code_souce_bakasha_new <> 2 then
      pk_zakaut.publc_insrt_ntuny_tik_mchshvim(p_seq_bakasha_new, 0, 2);
    end if;
  
    --darga_vederug_tik
    insert into darga_vederug_tik
      (select taarich_me,
              taarich_ad,
              code_sug_darga,
              darga_vederug_tik_seq.nextval,
              code_darga,
              code_derug,
              p_seq_bakasha_new,
              code_darga_ofek,
              code_derug_ofek,
              shem_meadken_acharon,
              taarich_yetzira
         from darga_vederug_tik t
        where t.seq_bakasha = p_seq_bakasha_prev);
    --        KAPAM_MESHICHOT
    insert into KAPAM_MESHICHOT
      (select kapam_meshichot_seq.nextval,
              p_seq_bakasha_new,
              seq_guf,
              taarich,
              schum
         from kapam_meshichot
        where seq_bakasha = p_seq_bakasha_prev);
  end;

