        where seq_bakasha = p_seq_bakasha_prev);
    for c in (select *
                from chinuch_reforma cr
               where cr.seq_bakasha = p_seq_bakasha_prev) loop
      v_seq_reforma := chinuch_reforma_seq.nextval;
      insert into chinuch_reforma
        (select v_seq_reforma,
                p_seq_bakasha_new,
                code_reforma,
