                taarich_yetzira
           from chinuch_reforma t
          where t.seq_bakasha = p_seq_bakasha_prev
            and t.seq_chinuch_reforma = c.seq_chinuch_reforma);
    
      insert into chinuch_bakara
        (select chinuch_bakara_seq.nextval,
                v_seq_reforma,
                code_bakara,
                taarich,
                amount,
                indication,
                grira,
                code_tafkid,
                mispar_kitot_yesodi,
                mispar_kitot_al_yesodi,
                mispar_kitot_yesodi_chanam,
                mispar_kitot_al_yesodi_chanam,
                ramat_murkavut,
                godel_matya,
                code_chinuch_mosad,
                ramat_murkavut,
                tafkid_acharon,
                semel_mosad
           from chinuch_bakara
          where seq_chinuch_reforma = c.seq_chinuch_reforma);
      copy_netuney_sachar(p_seq_bakasha_new,
                          p_seq_bakasha_prev,
                          v_seq_reforma,
                          c.seq_chinuch_reforma);
    
    end loop;
    --if v_seq_reforma is null then
      copy_netuney_sachar(p_seq_bakasha_new,
                          p_seq_bakasha_prev,
                          null,
                          null);
    --end if;
  end;

  -------------------------------------------------
  procedure copy_netuney_sachar(p_seq_bakasha_new  number,
                                p_seq_bakasha_prev number,
                                v_seq_reforma_new  number,
                                v_seq_reforma_prev number) is
    v_seq_netuney_sachar number;
  begin
    for r in (select t.seq_netuney_sachar, t.seq_chinuch_reforma
                from netuney_sachar t
               where t.seq_bakasha = p_seq_bakasha_prev
                 and (t.seq_chinuch_reforma = v_seq_reforma_prev or
                     v_seq_reforma_prev is null and t.seq_chinuch_reforma is null)) loop
      v_seq_netuney_sachar := netuney_sachar_seq.nextval;
      insert into netuney_sachar
        (select v_seq_netuney_sachar,
                p_seq_bakasha_new,
                mispar_misra,
                code_sug_maskoret,
                code_derug,
                code_darga,
                maskoret_kovaat,
                havraa_days,
                sum_havraa,
                ramat_bigud,
                is_maanak_yovel,
                schar_ysod,
                kovaat_161,
                date_update,
                user_update,
                remarks,
                from_date,
                sum_bigud,
                CODE_UCHLUSIA,
                CHODASHIM,
                v_seq_reforma_new,
                maskoret_kovaat_sum,
                maskoret_kovaat_percent,
                maskoret_kovaat_shiur_miztaber,
                maskoret_kovaat_tosefet,
                MASKORET_KOVAAT_SACHAR_RAYONI,
                shem_meadken_acharon,
                taarich_yetzira
           from netuney_sachar t
          where t.seq_netuney_sachar = r.seq_netuney_sachar);
    
      insert into tosefot
        (select tosefot_seq.nextval,
                v_seq_netuney_sachar,
                code_semel_tosefet,
                sum,
                percent,
                amount,
                t.date_update,
                t.user_update,
                t.shem_meadken_acharon,
                t.taarich_yetzira
           from tosefot t
           left join netuney_sachar t1
             on t.seq_netuney_sachar = t1.seq_netuney_sachar
          where t.seq_netuney_sachar = r.seq_netuney_sachar);
    
      insert into vetek_detail
        (select vetek_detail_seq.nextval,
                p_seq_bakasha_new,
                code_type_vetek,
                years,
                t.date_update,
                code_user,
                v_seq_netuney_sachar,
                t.shem_meadken_acharon,
                t.taarich_yetzira
           from vetek_detail t
         
           left join netuney_sachar t1
             on t.seq_netuney_sachar = t1.seq_netuney_sachar
          where t.seq_netuney_sachar = r.seq_netuney_sachar);
    
    end loop;
  end;
  -------------------------------------------------
  procedure duplicate_netuney_tik_mechushavim(p_seq_bakasha_new  number,
                                              p_seq_bakasha_prev number,
                                              p_is_insert_Anyway number default 0) is
    --זמני
    v_code_merge_bakasha_new       number;
    v_code_sug_bakasha_new         number;
    v_seq_prisha                   number;
    v_code_department_new          number;
    v_seq_netuney_tik_mechushavm_n number;
  begin
    --!!!!!!!!!!!!!!!!!!!!!only for stop or renew bakasha or nasham
    --זמנית, לגבי סוג הבקשה
    -- בדיקה גם בתוך הפונקציה
    --18/03/2019
    select v.code_merge_bakasha,
           v.code_sug_bakasha,
           v.seq_prisha,
           v.code_department_action,
           t.seq_netuney_tik_mechushavim
      into v_code_merge_bakasha_new,
           v_code_sug_bakasha_new,
           v_seq_prisha,
           v_code_department_new,
           v_seq_netuney_tik_mechushavm_n
      from v_bakasha_last_status v
      left join netuney_tik_mechushavim t
        on v.seq_bakasha = t.seq_bakasha
       and t.code_department = 2
       and t.mispar_misra = 0
     where v.seq_bakasha = p_seq_bakasha_new;
  
    if (p_is_insert_Anyway = 1 or (v_code_sug_bakasha_new in (19, 20) and
       v_seq_netuney_tik_mechushavm_n is null) or
       (v_code_sug_bakasha_new in (3, 5) and v_code_department_new = 1)) then
    
      ---סוף בדיקות
      for r in (select n.seq_netuney_tik_mechushavim
                  from netuney_tik_mechushavim n
                 where n.seq_bakasha = p_seq_bakasha_prev) loop
        v_seq_netuney_tik_mechushavm_n := netuney_tik_mechushavim_seq.nextval;
        insert into netuney_tik_mechushavim
        
          (select achuz_kizba_nechut,
                  achuz_kizba_chelkiyut_melea,
                  achuz_kizba_kafuf_chelkiyut,
                  keren_mezaka_shana,
                  keren_mezaka_chodesh,
                  keren_mezaka_yamim,
                  odef_sherut_shanim,
                  odef_sherut_chodashim,
                  odef_sherut_yamim,
                  chodshim_mezkim_achary_hagdala,
                  ahuz_kizb_achry_hagdl_kaf_chel,
                  chelkiyut_lefi_sherut,
                  shnot_hagdala_sofi,
                  tkufa_lo_mezaka_sherut,
                  tkufa_mezaka_sherut,
                  chodshey_hagdala_sofi,
                  achuz_kizb_achry_hagdl_chl_mla,
                  chodeshim_mezkim_out_of_srv_y,
                  chodeshim_mezkim_out_of_srv_m,
                  chodeshim_mezkim_out_of_srv_d,
                  chelkiyut_meshuklelet_sherut,
                  v_seq_netuney_tik_mechushavm_n,
                  p_seq_bakasha_new,
                  chelkiut_lefi_nechut,
                  is_zakai_lmaanak,
                  kitzba_medina_hisht_meshukll,
                  date_start_zakaut,
                  code_department,
                  is_hachlata_sofit,
                  maskoret_kizba,
                  achuz_pizuy,
                  schum_kizba,
                  schum_maanak_pizuy,
                  tkufa_overlap_kizba,
                  tkufa_overlap_maanak,
                  date_update,
                  is_salary_up_70,
                  is_complete_salary,
                  achuz_kizba_sofi,
                  chodshey_pizuy,
                  makor_maskoret_kovaat,
                  is_zakay_kizba,
                  code_group_prisha,
                  chelkiyut_sofit,
                  tkufa_mezaka_sherut_not_round,
                  code_e_zakaut,
                  achuz_kizba_fixed,
                  achuz_kizba_yechasi,
                  date_end_zakaut,
                  achuz_kizba_maximali,
                  hp_sheur_havara_max,
                  hp_tkufa_mshutefet_calc,
                  hp_is_sheerim,
                  hp_date_start_zakaut,
                  achuz_kizba_gil_60,
                  hp_date_haavara,
                  is_seif_57,
                  code_maanak_almana,
                  is_maanak_nisuin1,
                  is_maanak_nisuin2,
                  achuz_lchishuv_hivun,
                  mispar_misra,
                  null,
                  null,
                  total_child,
                  total_ben_zug,
                  interest_linkage,
                  date_zakaut_maanak_almana,
                  calc_as_of_date,
                  tkufa_mezaka_medina_only,
                  shem_meadken_acharon,
                  taarich_yetzira
             from netuney_tik_mechushavim t
            where t.seq_netuney_tik_mechushavim =
                  r.seq_netuney_tik_mechushavim);
      
        insert into netuney_tik_ben_mishpacha
          (select netuney_tik_ben_mishpacha_seq.nextval,
                  n.seq_bney_mishpacha,
                  v_seq_netuney_tik_mechushavm_n,
                  n.date_start_zakaut,
                  n.date_end_zakaut,
                  n.code_relative,
                  n.achuz_kizba_chuka,
                  n.achuz_kizba,
                  n.achuz_tosefet_chuka,
                  n.achuz_tosefet,
                  n.code_maanak_almana,
                  n.date_maanak_nisuin1,
                  n.date_maanak_nisuin2,
                  n.date_zakaut_maanak_almana,
                  n.seif_relative,
                  n.shem_meadken_acharon,
                  n.taarich_yetzira
             from netuney_tik_ben_mishpacha n
            where n.seq_netuney_tik_mechushavim =
                  r.seq_netuney_tik_mechushavim
           /*left join netuney_tik_mechushavim t
              on n.seq_netuney_tik_mechushavim =
                 t.seq_netuney_tik_mechushavim
           where t.seq_bakasha = p_seq_bakasha_prev*/
           );
      end loop;
    end if;
  end;

  ------------------------------------------------------------
  procedure skip_in_end_freeze_or_meches(p_seq_bakasha           number,
                                         v_current_action_in_out in out number,
                                         v_next_action           in out number,
                                         v_remarks               in out varchar2,
                                         v_is_automatic          in out number) is
    v_is_have_gil_takanony number(1) := 0;
    v_seq_ezor_ovdim       number := 0;
    v_code_sug_bakasha     number := 0;
  begin
    select count(*)
      into v_is_have_gil_takanony
      from action_log a
     where a.seq_bakasha = p_seq_bakasha
       and a.code_action = 132;
  
    if v_is_have_gil_takanony > 0 then
      if v_current_action_in_out = 86 then
        v_next_action := 26;
        v_remarks     := 'סיום הקפאה';
      elsif v_current_action_in_out = 26 then
        v_next_action  := 27;
        v_remarks      := 'סיום הקפאה';
        v_is_automatic := 1;
      elsif v_current_action_in_out = 27 then
        --skip!
        v_next_action := 114;
        v_remarks     := 'סיום הקפאה';
      end if;
    
    else
      -- if code ezor is meches then go to file document before gimalot
      if v_current_action_in_out = 27 then
        select v.code_sug_bakasha, v.seq_ezor_ovdim
          into v_code_sug_bakasha, v_seq_ezor_ovdim
          from v_bakasha_last_status v
         where v.seq_bakasha = p_seq_bakasha;
      
        if v_code_sug_bakasha in (1, 13) and v_seq_ezor_ovdim in (28) then
          v_next_action := 193;
          v_remarks     := 'משרד מכס ממתין לתיוק מסמכים';
        end if;
      end if;
    end if;
  end;
 --------------------------------------------------
   procedure exec_sql(p_sql nvarchar2) is
     begin
       execute immediate(trim(p_sql));
     end;
end;
/

create or replace package body prm_system_copy.PK_Reports is
  ----------------------------------------------------------------------------------------
  procedure Detailed_Report(cur         out sys_refcursor,
                            p_from_date date,
                            p_to_date   date,
                            p_data_type number) is
  begin
  
    open cur for
      select e.teur_ezor_ovdim,
             v.MISPAR_ZEHUT,
             p.shem_mishpacha,
             p.shem_prati,
             v.TAARICH_PRISHA,
             v.CODE_SEIF_PRISHA,
             s.teur_seif_prisha
      
        from v_regila_last_status v
        left join code_ezor_ovdim e
          on v.SEQ_EZOR_OVDIM = e.seq_ezor_ovdim
        left join poresh p
          on v.SEQ_PORSHIM = p.porshim_seq
        left join code_seif_prisha s
          on s.code_seif_prisha = v.CODE_SEIF_PRISHA
       where 1 = 1
         and v.CODE_SUG_BAKASHA in (1, 3, 5)
         and v.TAARICH_PRISHA >= p_from_date
         and v.TAARICH_PRISHA <= p_to_date
            --data type
         and ( --chinuch
              (p_data_type = 1 and v.CODE_MAKOR = 3) or
             --health
              (p_data_type = 2 and v.CODE_MAKOR = 1 and
              pk_load_mimshak.Get_ezor_ovdim_category(v.SEQ_EZOR_OVDIM) = 2) or
             --merkava without chinuch
              (p_data_type = 3 and v.CODE_MAKOR = 1 and
              pk_load_mimshak.Get_ezor_ovdim_category(v.SEQ_EZOR_OVDIM) <> 2) or
             --yadani
              (p_data_type = 4 and v.CODE_MAKOR = 2) or
             --get all data type
              (p_data_type = 0));
  end;
  ----------------------------------------------------------------------------------------
  procedure By_Years_Report(cur         out sys_refcursor,
                            p_from_date date,
                            p_to_date   date
                            --for same structure parameter all dochot nasham, please  no delete this parametes
                            -- ,p_data_type number default null
                            ) is
  begin
  
    open cur for
    -- In the end, Add percent columns.
      select base.*,
             round(merkava / all_tikim * 100, 1) merkava_p,
             round(merkava_health / all_tikim * 100, 1) merkava_health_p,
             round(yadany / all_tikim * 100, 1) yadany_p,
             round(chinuch / all_tikim * 100, 1) chinuch_p
        from (with t as (select *
                           from -- Get relevant rows
                                (select case
                                          when code_makor = 2 then
                                           2
                                          when code_makor = 3 then
                                           3
                                          when code_makor = 1 and
                                               pk_load_mimshak.Get_ezor_ovdim_category(t.SEQ_EZOR_OVDIM) = 1 then
                                           11
                                          when code_makor = 1 and
                                               pk_load_mimshak.Get_ezor_ovdim_category(t.SEQ_EZOR_OVDIM) = 2 then
                                           12
                                        end ezor_ovdim_type,
                                        
                                        to_char(t.TAARICH_PRISHA, 'yyyy') year_prisha,
                                        t.code_sug_bakasha,
                                        t.seq_ezor_ovdim
                                 
                                   from v_regila_last_status t
                                 --~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
                                 -- Get  tikim in one type for comparison.
                                 union all
                                 select -1 ezor_ovdim_type,
                                        to_char(t.TAARICH_PRISHA, 'yyyy') year_prisha,
                                        t.code_sug_bakasha,
                                        t.seq_ezor_ovdim
                                 
                                   from v_regila_last_status t) internal
                          where 1 = 1
                            and seq_ezor_ovdim not in
                                (select t.seq_ezor_ovdim
                                   from EZOR_OVDIM_CATEGORY t
                                  where t.code_sug_ezor_ovdim in (8, 9, 10))
                            and CODE_SUG_BAKASHA in (1, 3, 5)
                            and year_prisha >= to_char(p_from_date, 'yyyy')
                            and year_prisha <= to_char(p_to_date, 'yyyy'))
               select *
                 from t
               -- Group by years and pivot columns
               pivot(count(ezor_ovdim_type)
                  for ezor_ovdim_type in(11 as merkava,
                                         12 as merkava_health,
                                         2 as yadany,
                                         3 as chinuch,
                                         -1 as all_tikim))
                order by year_prisha) base;
  
  
  end;
  ----------------------------------------------------------------------------------------
  procedure By_seif_prisha_Report(cur         out sys_refcursor,
                                  p_from_date date,
                                  p_to_date   date,
                                  p_data_type number) is
  begin
  
    open cur for
      select year_prisha השנה,
             all_tikim   "סה כ פורשים",
             must        "פרישת חובה",
             must_p      "אחוז",
             wanted      "פרישה מרצון",
             wanted_p    "אחוז  ",
             dismissal   "פיטורין",
             dismissal_p "  אחוז",
             health      "בריאות",
             health_p    " אחוז ",
             death       "פטירה",
             death_p     " אחוז   ",
             freezing    הקפאה,
             freezing_p  "   אחוז  "
        from (with base_table as (select s.code_report_group_prisha base_code_seif_prisha,
                                         to_char(t1.taarich_prisha, 'yyyy') base_year_prisha
                                    from v_regila_last_status t1
                                    LEFT join code_seif_prisha s
                                      on t1."CODE_SEIF_PRISHA" =
                                         s.code_seif_prisha
                                   where 1 = 1
                                     and seq_ezor_ovdim not in
                                         (select t.seq_ezor_ovdim
                                            from EZOR_OVDIM_CATEGORY t
                                           where t.code_sug_ezor_ovdim in
                                                 (8, 9, 10))
                                     and t1.CODE_SUG_BAKASHA in (1, 3, 5)
                                        
                                     and to_char(t1.taarich_prisha, 'yyyy') >=
                                         to_char(p_from_date, 'yyyy')
                                     and to_char(t1.taarich_prisha, 'yyyy') <=
                                         to_char(p_to_date, 'yyyy')
                                        --data type
                                     and ( --chinuch
                                          (p_data_type = 1 and
                                          t1.CODE_MAKOR = 3) or
                                         --health
                                          (p_data_type = 2 and
                                          t1.CODE_MAKOR = 1 and
                                          pk_load_mimshak.Get_ezor_ovdim_category(t1.SEQ_EZOR_OVDIM) = 2) or
                                         --merkava without chinuch
                                          (p_data_type = 3 and
                                          t1.CODE_MAKOR = 1 and
                                          pk_load_mimshak.Get_ezor_ovdim_category(t1.SEQ_EZOR_OVDIM) <> 2) or
                                         --yadani
                                          (p_data_type = 4 and
                                          t1.CODE_MAKOR = 2) or
                                         --get all data type
                                          (p_data_type = 0)))
             
             -- In the end, Add percent columns.
               select base.*,
                      round(must / all_tikim * 100, 1) must_p,
                      round(wanted / all_tikim * 100, 1) wanted_p,
                      round(Dismissal / all_tikim * 100, 1) Dismissal_p,
                      round(health / all_tikim * 100, 1) health_p,
                      round(Death / all_tikim * 100, 1) Death_p,
                      round(Freezing / all_tikim * 100, 1) Freezing_p
                 from (with t as (
                                  -- Get relevant rows
                                  select all base_code_seif_prisha code_seif_prisha,
                                              base_year_prisha      year_prisha
                                  
                                    from base_table
                                  --~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
                                  -- Get all tikim for comparison.
                                  union all
                                  select -1               code_seif_prisha,
                                          base_year_prisha year_prisha
                                  
                                    from base_table)
                        select *
                          from t
                        -- Group by years and pivot columns
                        pivot(count(code_seif_prisha)
                           for code_seif_prisha in(1 as must,
                                                   2 as wanted,
                                                   3 as Dismissal,
                                                   4 health,
                                                   5 as Death,
                                                   6 as Freezing,
                                                   -1 as all_tikim))
                         order by year_prisha) base);
  
  
  
  end;
  ----------------------------------------------------------------------------------------
  procedure By_Age_Report(cur         out sys_refcursor,
                          p_from_date date,
                          p_to_date   date,
                          p_data_type number default 0) is
  begin
  
    open cur for
      select year_prisha השנה,
             ALL_TIKIM   "סה כ פורשים",
             a           "67+",
             a_p         "אחוז   ",
             b           "64-67",
             b_p         "אחוז",
             c           "62-64",
             c_p         "אחוז  ",
             d           "60-62",
             d_p         "אחוז ",
             e           "55-60",
             e_p         "אחוז    ",
             f           "50-55",
             f_p         "אחוז        ",
             g           "עד 50 ",
             g_p         "אחוז     ",
             AVERAGE     "גיל ממוצע"
        from (with base_table as (select trunc(months_between(t1.taarich_prisha,
                                                              p1.taarich_leda) / 12) base_age,
                                         to_char(t1.TAARICH_PRISHA, 'yyyy') base_year_prisha
                                    from v_regila_last_status t1
                                    left join poresh p1
                                      on t1.seq_porshim = p1.porshim_seq
                                   where 1 = 1
                                     and seq_ezor_ovdim not in
                                         (select t.seq_ezor_ovdim
                                            from EZOR_OVDIM_CATEGORY t
                                           where t.code_sug_ezor_ovdim in
                                                 (8, 9, 10))
                                     and t1.CODE_SUG_BAKASHA in (1, 3, 5)
                                     and to_char(t1.TAARICH_PRISHA, 'yyyy') >=
                                         to_char(p_from_date, 'yyyy')
                                     and to_char(t1.TAARICH_PRISHA, 'yyyy') <=
                                         to_char(p_to_date, 'yyyy')
                                        --data type
                                     and ( --chinuch
                                          (p_data_type = 1 and
                                          t1.CODE_MAKOR = 3) or
                                         --health
                                          (p_data_type = 2 and
                                          t1.CODE_MAKOR = 1 and
                                          pk_load_mimshak.Get_ezor_ovdim_category(t1.SEQ_EZOR_OVDIM) = 2) or
                                         --merkava without chinuch
                                          (p_data_type = 3 and
                                          t1.CODE_MAKOR = 1 and
                                          pk_load_mimshak.Get_ezor_ovdim_category(t1.SEQ_EZOR_OVDIM) <> 2) or
                                         --yadani
                                          (p_data_type = 4 and
                                          t1.CODE_MAKOR = 2) or
                                         --get all data type
                                          (p_data_type = 0)))
             -- In the end, Add percent columns.
             
               select base.*,
                      round(a / all_tikim * 100, 1) a_p,
                      round(b / all_tikim * 100, 1) b_p,
                      round(c / all_tikim * 100, 1) c_p,
                      round(d / all_tikim * 100, 1) d_p,
                      round(e / all_tikim * 100, 1) e_p,
                      round(f / all_tikim * 100, 1) f_p,
                      round(g / all_tikim * 100, 1) g_p,
                      round((select sum(base_age)
                               from base_table
                              where base_year_prisha = year_prisha) /
                            all_tikim,
                            1) Average
                 from (with t as (
                                  -- Get relevant rows
                                  select case
                                            when base_table.base_age >= 67 then
                                             1
                                            when base_table.base_age >= 64 and
                                                 base_table.base_age < 67 then
                                             2
                                            when base_table.base_age >= 62 and
                                                 base_table.base_age < 64 then
                                             3
                                            when base_table.base_age >= 60 and
                                                 base_table.base_age < 62 then
                                             4
                                            when base_table.base_age >= 55 and
                                                 base_table.base_age < 60 then
                                             5
                                            when base_table.base_age >= 50 and
                                                 base_table.base_age < 55 then
                                             6
                                            when base_table.base_age < 50 then
                                             7
                                          end age,
                                          base_table.base_year_prisha year_prisha
                                    from base_table
                                  --~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
                                  -- Get all tikim for comparison.
                                  union all
                                  select -1 age, base_year_prisha year_prisha
                                    from base_table)
                        select *
                          from t
                        -- Group by years and pivot columns
                        pivot(count(age)
                           for age in(1 as a,
                                      2 as b,
                                      3 as c,
                                      4 as d,
                                      5 as e,
                                      6 as f,
                                      7 as g,
                                      -1 as all_tikim))
                         order by year_prisha) base);
  
  
  
  end;
  ----------------------------------------------------------------------------------------
  procedure By_pension_rate_Report(cur         out sys_refcursor,
                                   p_from_date date,
                                   p_to_date   date,
                                   p_data_type number) is
  begin
  
    open cur for
    -- In the end, Add percent columns.
      select year_prisha השנה,
             a           "סה כ",
             b           "גיל ממוצע",
             c           "ממוצע שיעור הקצבה מכח השירות בפועל",
             d           "ממוצע סהכ שיעור הקצבה המוגדלת",
             e           "ממוצע הגדלת השעור הקצבה",
             f           "סה כ עובדים ששרותם הוגדל",
             g           "אחוז",
             h           "ממוצע הגדלת שיעור הקצבה למוגדלים"
        from (select to_char(t.taarich_prisha, 'yyyy') year_prisha,
                     count(p.porshim_seq) a,
                     round(sum(trunc(months_between(t.taarich_prisha,
                                                    p.taarich_leda) / 12)) /
                           count(p.porshim_seq),
                           1) b,
                     round(sum(n.achuz_kizba_kafuf_chelkiyut) /
                           count(p.porshim_seq),
                           1) c,
                     round((sum(n.achuz_kizba_kafuf_chelkiyut) +
                           sum(hn.achuz_meushar_sum)) / count(p.porshim_seq),
                           1) d,
                     round(sum(hn.achuz_meushar_sum) / count(p.porshim_seq),
                           1) e,
                     count(hn.seq_bakasha) f,
                     round(count(hn.seq_bakasha) / count(p.porshim_seq) * 100,
                           1) g,
                     round(sum(hn.achuz_meushar_sum) / count(hn.seq_bakasha),
                           1) h
                from v_regila_last_status t
                left join poresh p
                  on t.seq_porshim = p.porshim_seq
                left join netuney_tik_mechushavim n
                  on n.seq_bakasha = t.SEQ_BAKASHA
                 and n.code_department = 1
                left join (select hagdala_nimuk.seq_bakasha,
                                 sum(hagdala_nimuk.achuz_meushar) achuz_meushar_sum
                            from hagdala_nimuk
                           group by hagdala_nimuk.seq_bakasha) hn
                  on hn.seq_bakasha = t.seq_bakasha
               where 1 = 1
                 and seq_ezor_ovdim not in
                     (select t.seq_ezor_ovdim
                        from EZOR_OVDIM_CATEGORY t
                       where t.code_sug_ezor_ovdim in (8, 9, 10))
                 and t.CODE_SUG_BAKASHA in (1, 3, 5)
                 and to_char(t.taarich_prisha, 'yyyy') >=
                     to_char(p_from_date, 'yyyy')
                 and to_char(t.taarich_prisha, 'yyyy') <=
                     to_char(p_to_date, 'yyyy')
                    --data type
                 and ( --chinuch
                      (p_data_type = 1 and t.CODE_MAKOR = 3) or
                     --health
                      (p_data_type = 2 and t.CODE_MAKOR = 1 and
                      pk_load_mimshak.Get_ezor_ovdim_category(t.SEQ_EZOR_OVDIM) = 2) or
                     --merkava without chinuch
                      (p_data_type = 3 and t.CODE_MAKOR = 1 and
                      pk_load_mimshak.Get_ezor_ovdim_category(t.SEQ_EZOR_OVDIM) <> 2) or
                     --yadani
                      (p_data_type = 4 and t.CODE_MAKOR = 2) or
                     --get all data type
                      (p_data_type = 0))
               group by to_char(t.taarich_prisha, 'yyyy')
               order by year_prisha);
  end;
