  procedure address_prorshim(p_IDList varchar2, cur out sys_refcursor) is
  begin
    open cur for
      select distinct p.mispar_zehut   "מספר זהות",
                      p.shem_prati     "שם פרטי",
                      p.shem_mishpacha "שם משפחה",
                      c.teur_ir        עיר,
                      aa.street        רחוב,
                      aa.house         "מספר בית",
                      aa.apartment     "דירה",
                      aa.mikud         מיקוד
        from poresh p
       right join (select max(a.seq_address) seq_address, a.seq_poresh
                     from address a
                    group by a.seq_poresh) w
          on w.seq_poresh = p.porshim_seq
        left join address aa
          on aa.seq_address = w.seq_address
        left join code_ir c
          on c.code_ir = aa.code_city
       where p.mispar_zehut in
            
             (select to_number(column_value) as mispar_zehut
                from xmltable(p_IDlist))
      union
      select distinct o.mispar_zehut_ben_mishpacha,
                      o.shem_prati,
                      o.shem_mishpacha,
                      c.teur_ir,
                      aa.street,
                      aa.house,
                      aa.apartment,
                      aa.mikud
        from bney_mishpacha o
       right join (select max(a.seq_address) seq_address,
                          a.seq_bney_mishpacha
                     from address a
                    group by a.seq_bney_mishpacha) w
          on w.seq_bney_mishpacha = o.seq_bney_mishpacha
        left join address aa
          on aa.seq_address = w.seq_address
        left join code_ir c
          on c.code_ir = aa.code_city
       where o.mispar_zehut_ben_mishpacha in
            
             (select to_number(column_value) as mispar_zehut
                from xmltable(p_IDlist))
      
      ;
  end;
  ----------------------------------------------------------
  procedure histtfut_Signed(p_from_date date default null,
                            p_to_date   date default null,
                            
                            cur out sys_refcursor) is
  begin
    open cur for
      select distinct v.mispar_zehut     as מספר_זהות,
                      pr.gimla_number    as מספר_גמלה,
                      p.shem_prati       as שם_פרטי,
                      p.shem_mishpacha   as שם_משפחה,
                      co.teur_ezor_ovdim as משרד_פרישה,
                      v.taarich_prisha   as תאריך_פרישה,
                      --      pa.date_payment     as תאריך_תחילת_תשלום,
                      p.taarich_leda      as תאריך_לידה,
                      co2.teur_ezor_ovdim as גוף_משתתף,
                      u.teur_unit         as מחוז
      
        from v_bakasha_last_status v
        left join prisha pr
          on pr.seq_prisha = v.seq_prisha
        left join code_unit u
          on u.seq_code_unit = pr.seq_code_unit
        left join poresh p
          on p.porshim_seq = v.seq_porshim
        left join code_ezor_ovdim co
          on co.seq_ezor_ovdim = v.seq_ezor_ovdim
        left join participation pa
          on pa.seq_bakasha = v.seq_bakasha
        left join code_ezor_ovdim co2
          on pa.seq_guf = co2.seq_ezor_ovdim
        left join action_log a
          on a.code_action = 36
         and a.seq_bakasha = v.seq_bakasha
         and a.date_action >= nvl(p_from_date, v.date_action)
         and a.date_action <= nvl(p_to_date, v.date_action)
       where v.code_sug_bakasha in (8, 9)
         and a.seq_action_log is not null
      
      --   order by v.taarich_prisha
      ;
  end;
  ----------------------------------------------------------
  procedure Kabaut_Report(p_from_date date default null,
                          p_to_date   date default null,
                          cur         out sys_refcursor) is
  begin
    open cur for
      select 'M030' קוד_משתמש_מעדכן --1
            ,
             'מנהל הגמלאות ' קידומת_משתמש_מעדכן,
             P.MISPAR_ZEHUT זהות_מנ --3
            ,
             t.gimla_number מספר_תיק_ידני --4
            ,
             NULL קוד_אגף_ויחידה ---5
            ,
             NULL אגף_ויחידה --6
            ,
             P.MISPAR_ZEHUT זהות_מ_נ_אב --7
            ,
             NULL קוד_סוג_תיק --8
            ,
             NULL סוג_תיק --9
            ,
             P.SHEM_MISHPACHA שם_משפחה ---10
            ,
             P.SHEM_PRATI שם_פרטי --11
            ,
             NULL קוד_משרד --12
            ,
             teur_ezor_ovdim משרד_פרישה --13
            ,
             n.TAARICH_PRISHA תאריך_פרישה ---14
            ,
             n.date_start_zakaut תאריך_תחילת_תשלום ---15 -- מלמטה
            ,
             NULL קוד_סיבה ---16
            ,
             NULL סיבת_סגירה ---17
            ,
             NULL הערה ---18
            ,
             P.TAARICH_LEDA תאריך_לידה --19  --- הו
            ,
             n.date_start_zakaut תאריך_תחילת_תשלום2 --20 -- מלמטה
            ,
             NULL גוף_משתתף --21
        from v_bakasha_last_status t
        left join prisha pr
          on t.SEQ_PRISHA = pr.seq_prisha
        left join v_bakasha_last_zakaut n
          on t.seq_bakasha = n.seq_bakasha
        left join bakasha_regila br
          on t.SEQ_bakasha = br.seq_bakasha
        left join bakasha b
          on t.SEQ_bakasha = b.seq_bakasha
        left join poresh p
          on pr.seq_poresh = p.porshim_seq
        left join code_ezor_ovdim e
          on e.seq_ezor_ovdim = pr.seq_ezor_ovdim
        left join Code_Source m
          on t.CODE_source = m.code_source
        left join code_user u
          on t.code_user_to_internal = u.id_user
        left join code_sug_bakasha sb
          on t.CODE_SUG_BAKASHA = sb.code_sug_bakasha
        left join CODE_BAKASHA_DETAIL dt
          on dt.code_bakasha_detail = b.code_bakasha_detail
       where 2 = 2
         AND t.CODE_SUG_BAKASHA = 1
         and nvl(n.date_start_zakaut, to_date('01/01/1900', 'dd/mm/yyyy')) between
            --- to_date('01/01/2020','dd/mm/yyyy')  and to_date('01/01/9999','dd/mm/yyyy')
             nvl(p_from_date, to_date('01/01/0001', 'dd/mm/yyyy')) and
             nvl(p_to_date, to_date('01/01/9999', 'dd/mm/yyyy'))
         AND pr.SEQ_EZOR_OVDIM = 2962;
  end;
  ----------------------------------------------------------------------------------------
  procedure Wrong_If_From_Pnim_In(cur out sys_refcursor) is
  begin
    open cur for
      select distinct t.id_number as מספר_זהות,
                      t.first_name as שם_פרטי,
                      t.last_name as שם_משפחה,
                      c.teur_sug_zihuy as סוג_זיהוי,
                      'פורש' as פורש_או_שאר
        from LD_INTERIOR_ALL t
       right join poresh p
          on p.mispar_zehut = to_number(t.id_number)
        left join code_sug_zihuy c
          on c.code_sug_zihuy = p.sug_zihuy
       where t.id_number_o = '000000000'
      union
      select distinct t.id_number as מספר_זהות,
                      t.first_name as שם_פרטי,
                      t.last_name as שם_משפחה,
                      c.teur_sug_zihuy as סוג_זיהוי,
                      'שאר' as פורש_או_שאר
        from LD_INTERIOR_ALL t
       right join bney_mishpacha b
          on b.mispar_zehut_ben_mishpacha = to_number(t.id_number)
        left join code_sug_zihuy c
          on c.code_sug_zihuy = b.sug_zihuy
       where t.id_number_o = '000000000'
union
   select to_char(cnt,'9999999999') ,
                      ' מספר רשומות שנשלחו' as שם_פרטי,
                      '' as שם_משפחה,  
                      '' as סוג_זיהוי,
                      '' as פורש_או_שאר
   
 --  כמות רשומות שנשלחו למשרד הפנים:
     from
          (select l.count_success_tikim cnt
           from ld_protocol l
           where l.seq_ld_protocol =
            (select max(lp.seq_ld_protocol)
             from ld_protocol lp
              where lp.code_process = 5
               and lp.message = 'include all'
                and lp.code_sub_process = 1))

union
      select to_char(cnt,'9999999999') ,
                      'מספר רשומות שהתקבלו' as שם_פרטי,
                      '' as שם_משפחה,  
                      '' as סוג_זיהוי,
                      '' as פורש_או_שאר
   
       from          
--כמות רשומות שהתקבלו ממשרד הפנים
            (select l.count_success_tikim cnt
            from ld_protocol l
            where l.seq_ld_protocol =
             (select min(lp.seq_ld_protocol)
                from ld_protocol lp
                  where lp.code_process = 5
                   and lp.code_sub_process = 2 
                   and lp.seq_ld_protocol> (select max(lp1.seq_ld_protocol)
                                      from ld_protocol lp1
                                      where lp1.code_process = 5
                                      and lp1.message = 'include all'
                                      and lp1.code_sub_process = 1 
                                     )));
         
    
  end;
