  procedure mamtin_lekabalat_tshuva_amitim(p_from_date date,
                                           p_to_date   date,
                                           cur         out sys_refcursor) is
  begin
    open cur for
    --אין בקשה להעברת כספים בקשות מעמיתים 
      select distinct p.shem_prati as שם_פרטי,
                      p.shem_mishpacha as שם_משפחה,
                      v.mispar_zehut as מספר_זהות,
                      v.taarich_prisha as תאריך_פרישה,
                      v.code_seif_prisha as קוד_סעיף_פרישה,
                      cp.teur_seif_prisha as סעיף_פרישה,
                      p.taarich_leda as תאריך_לידה,
                      cc.teur_ezor_ovdim as משרד_פרישה,
                      ceo.teur_ezor_ovdim as גוף_משתתף,
                      v.teur_action as סטטוס,
                      to_date(v.date_action, 'dd/mm/yyyy') as תאריך_סטטוס,
                      bd.teur_bakasha_detail פירוט_בקשה
        from v_bakasha_last_status v
        left join poresh p
          on p.porshim_seq = v.seq_porshim
        left join action_log al
          on al.code_action = v.code_action
        left join code_ezor_ovdim cc
          on cc.seq_ezor_ovdim = v.seq_ezor_ovdim
        left join participation par
          on par.seq_bakasha = v.seq_bakasha
        left join code_ezor_ovdim ceo
          on par.seq_guf = ceo.seq_ezor_ovdim
        left join code_sug_ezor_ovdim cse
          on cse.code_sug_ezor_ovdim = ceo.code_sug_ezor_ovdim
        left join code_seif_prisha cp
          on cp.code_seif_prisha = v.code_seif_prisha
        left join code_bakasha_detail bd
          on bd.code_bakasha_detail = v.code_bakasha_detail  
       where v.code_action in (109)
         and v.date_action >= p_from_date
         and v.date_action <= p_to_date
         and  nvl(v.code_bakasha_detail,0) not in(26,40)
       /*  and not exists
       (select vv.mispar_zehut
                from v_bakasha_last_status vv
                left join document_bakasha db
                  on db.seq_bakasha = vv.seq_bakasha
                left join document d
                  on d.seq_document = db.seq_document
               where vv.seq_bakasha = v.seq_bakasha
                 and d.seq_document_type in (55, 75))*/
         and ceo.seq_ezor_ovdim in
             (10380, 10152, 10387, 10386, 10385, 10381, 10384, 10382)
         and v.taarich_prisha < sysdate
      union
      --יש בקשה להעברת כספים 
      select distinct p.shem_prati as שם_פרטי,
                      p.shem_mishpacha as שם_משפחה,
                      v.mispar_zehut as מספר_זהות,
                      v.taarich_prisha as תאריך_פרישה,
                      v.code_seif_prisha as קוד_סעיף_פרישה,
                      cp.teur_seif_prisha as סעיף_פרישה,
                      p.taarich_leda as תאריך_לידה,
                      cc.teur_ezor_ovdim as משרד_פרישה,
                      ceo.teur_ezor_ovdim as גוף_משתתף,
                      v.teur_action as סטטוס,
                      to_date(v.date_action, 'dd/mm/yyyy') as תאריך_סטטוס,
                      bd.teur_bakasha_detail פירוט_בקשה
        from v_bakasha_last_status v
        left join poresh p
          on p.porshim_seq = v.seq_porshim
        left join action_log al
          on al.code_action = v.code_action
        left join code_ezor_ovdim cc
          on cc.seq_ezor_ovdim = v.seq_ezor_ovdim
        left join participation par
          on par.seq_bakasha = v.seq_bakasha
        left join code_ezor_ovdim ceo
          on par.seq_guf = ceo.seq_ezor_ovdim
        left join code_sug_ezor_ovdim cse
          on cse.code_sug_ezor_ovdim = ceo.code_sug_ezor_ovdim
       -- left join document_bakasha db
        --  on db.seq_bakasha = v.seq_bakasha
      --  left join document d
      --    on d.seq_document = db.seq_document
        left join code_seif_prisha cp
          on cp.code_seif_prisha = v.code_seif_prisha
        left join code_bakasha_detail bd
          on bd.code_bakasha_detail = v.code_bakasha_detail
       where v.code_action in (109)
         and v.date_action >= p_from_date
         --and d.seq_document_type in (55, 75)
         and  nvl(v.code_bakasha_detail,0) in(26,40)
         and v.date_action <= p_to_date
         and ceo.seq_ezor_ovdim in
             (10380, 10152, 10387, 10386, 10385, 10381, 10384, 10382)
         and v.taarich_prisha < sysdate;
  end;
  ----------------------------------------------------------------------------------------
  procedure mamtin_lekabalat_tshuva_gilad(p_from_date date,
                                          p_to_date   date,
                                          cur         out sys_refcursor) is
  begin
    open cur for
    --אין בקשה להעברת כספים בקשות קרן גלעד 
      select distinct p.shem_prati as שם_פרטי,
                      p.shem_mishpacha as שם_משפחה,
                      v.mispar_zehut as מספר_זהות,
                      v.taarich_prisha as תאריך_פרישה,
                      v.code_seif_prisha as קוד_סעיף_פרישה,
                      cp.teur_seif_prisha as סעיף_פרישה,
                      p.taarich_leda as תאריך_לידה,
                      cc.teur_ezor_ovdim as משרד_פרישה,
                      ceo.teur_ezor_ovdim as גוף_משתתף,
                      v.teur_action as סטטוס,
                      to_date(v.date_action, 'dd/mm/yyyy') as תאריך_סטטוס,
                      bd.teur_bakasha_detail פירוט_בקשה
        from v_bakasha_last_status v
        left join poresh p
          on p.porshim_seq = v.seq_porshim
        left join action_log al
          on al.code_action = v.code_action
        left join code_ezor_ovdim cc
          on cc.seq_ezor_ovdim = v.seq_ezor_ovdim
        left join participation par
          on par.seq_bakasha = v.seq_bakasha
        left join code_ezor_ovdim ceo
          on par.seq_guf = ceo.seq_ezor_ovdim
        left join code_sug_ezor_ovdim cse
          on cse.code_sug_ezor_ovdim = ceo.code_sug_ezor_ovdim
        left join code_seif_prisha cp
          on cp.code_seif_prisha = v.code_seif_prisha
        left join code_bakasha_detail bd
          on bd.code_bakasha_detail = v.code_bakasha_detail
       where v.code_action in (109)
         and v.date_action >= p_from_date
         and v.date_action <= p_to_date
         /*and not exists (select vv.mispar_zehut
                from v_bakasha_last_status vv
                left join document_bakasha db
                  on db.seq_bakasha = vv.seq_bakasha
                left join document d
                  on d.seq_document = db.seq_document
               where vv.seq_bakasha = v.seq_bakasha
                 and d.seq_document_type in (55, 75))*/
         and  nvl(v.code_bakasha_detail,0) not in(26,40)        
         and ceo.seq_ezor_ovdim in (8)
         and v.taarich_prisha < sysdate
      union
      --יש בקשה להעברת כספים 
      select distinct p.shem_prati as שם_פרטי,
                      p.shem_mishpacha as שם_משפחה,
                      v.mispar_zehut as מספר_זהות,
                      v.taarich_prisha as תאריך_פרישה,
                      v.code_seif_prisha as קוד_סעיף_פרישה,
                      cp.teur_seif_prisha as סעיף_פרישה,
                      p.taarich_leda as תאריך_לידה,
                      cc.teur_ezor_ovdim as משרד_פרישה,
                      ceo.teur_ezor_ovdim as גוף_משתתף,
                      v.teur_action as סטטוס,
                      to_date(v.date_action, 'dd/mm/yyyy') as תאריך_סטטוס,
                      bd.teur_bakasha_detail פירוט_בקשה
        from v_bakasha_last_status v
        left join poresh p
          on p.porshim_seq = v.seq_porshim
        left join action_log al
          on al.code_action = v.code_action
        left join code_ezor_ovdim cc
          on cc.seq_ezor_ovdim = v.seq_ezor_ovdim
        left join participation par
          on par.seq_bakasha = v.seq_bakasha
        left join code_ezor_ovdim ceo
          on par.seq_guf = ceo.seq_ezor_ovdim
        left join code_sug_ezor_ovdim cse
          on cse.code_sug_ezor_ovdim = ceo.code_sug_ezor_ovdim
        /*left join document_bakasha db
          on db.seq_bakasha = v.seq_bakasha
        left join document d
          on d.seq_document = db.seq_document*/
        left join code_seif_prisha cp
          on cp.code_seif_prisha = v.code_seif_prisha
        left join code_bakasha_detail bd
          on bd.code_bakasha_detail = v.code_bakasha_detail
       where v.code_action in (109)
         and v.date_action >= p_from_date
   --      and d.seq_document_type in (55, 75)
         and  nvl(v.code_bakasha_detail,0) in(26,40)
         and v.date_action <= p_to_date
         and ceo.seq_ezor_ovdim in (8)
         and v.taarich_prisha < sysdate;
  end;
  ----------------------------------------------------------------------------------------
  procedure mamtin_lekabalat_tshuva_moazot(p_from_date date,
                                           p_to_date   date,
                                           cur         out sys_refcursor) is
  begin
    open cur for
    --אין בקשה להעברת כספים בקשות מועצות ועיריות 
      select distinct p.shem_prati as שם_פרטי,
                      p.shem_mishpacha as שם_משפחה,
                      v.mispar_zehut as מספר_זהות,
                      v.taarich_prisha as תאריך_פרישה,
                      v.code_seif_prisha as קוד_סעיף_פרישה,
                      cp.teur_seif_prisha as סעיף_פרישה,
                      p.taarich_leda as תאריך_לידה,
                      cc.teur_ezor_ovdim as משרד_פרישה,
                      ceo.teur_ezor_ovdim as גוף_משתתף,
                      v.teur_action as סטטוס,
                      to_date(v.date_action, 'dd/mm/yyyy') as תאריך_סטטוס,
                      bd.teur_bakasha_detail פירוט_בקשה
        from v_bakasha_last_status v
        left join poresh p
          on p.porshim_seq = v.seq_porshim
        left join action_log al
          on al.code_action = v.code_action
        left join code_ezor_ovdim cc
          on cc.seq_ezor_ovdim = v.seq_ezor_ovdim
        left join participation par
          on par.seq_bakasha = v.seq_bakasha
        left join code_ezor_ovdim ceo
          on par.seq_guf = ceo.seq_ezor_ovdim
        left join code_sug_ezor_ovdim cse
          on cse.code_sug_ezor_ovdim = ceo.code_sug_ezor_ovdim
        left join code_seif_prisha cp
          on cp.code_seif_prisha = v.code_seif_prisha
        left join code_bakasha_detail bd
          on bd.code_bakasha_detail = v.code_bakasha_detail
       where v.code_action in (109)
         and v.date_action >= p_from_date
         and v.date_action <= p_to_date
        /* and not exists
       (select vv.mispar_zehut
                from v_bakasha_last_status vv
                left join document_bakasha db
                  on db.seq_bakasha = vv.seq_bakasha
                left join document d
                  on d.seq_document = db.seq_document
               where vv.seq_bakasha = v.seq_bakasha
                 and d.seq_document_type in (55, 75))*/
         and  nvl(v.code_bakasha_detail,0) not in (26,40)        
         and ceo.seq_ezor_ovdim not in
             (8, 10380, 10152, 10387, 10386, 10385, 10381, 10384, 10382)
         and v.taarich_prisha < sysdate
      union
      --יש בקשה להעברת כספים 
      select distinct p.shem_prati as שם_פרטי,
                      p.shem_mishpacha as שם_משפחה,
                      v.mispar_zehut as מספר_זהות,
                      v.taarich_prisha as תאריך_פרישה,
                      v.code_seif_prisha as קוד_סעיף_פרישה,
                      cp.teur_seif_prisha as סעיף_פרישה,
                      p.taarich_leda as תאריך_לידה,
                      cc.teur_ezor_ovdim as משרד_פרישה,
                      ceo.teur_ezor_ovdim as גוף_משתתף,
                      v.teur_action as סטטוס,
                      to_date(v.date_action, 'dd/mm/yyyy') as תאריך_סטטוס,
                      bd.teur_bakasha_detail פירוט_בקשה
        from v_bakasha_last_status v
        left join poresh p
          on p.porshim_seq = v.seq_porshim
        left join action_log al
          on al.code_action = v.code_action
        left join code_ezor_ovdim cc
          on cc.seq_ezor_ovdim = v.seq_ezor_ovdim
        left join participation par
          on par.seq_bakasha = v.seq_bakasha
        left join code_ezor_ovdim ceo
          on par.seq_guf = ceo.seq_ezor_ovdim
        left join code_sug_ezor_ovdim cse
          on cse.code_sug_ezor_ovdim = ceo.code_sug_ezor_ovdim
       /* left join document_bakasha db
          on db.seq_bakasha = v.seq_bakasha
        left join document d
          on d.seq_document = db.seq_document*/
        left join code_seif_prisha cp
          on cp.code_seif_prisha = v.code_seif_prisha
        left join code_bakasha_detail bd
          on bd.code_bakasha_detail = v.code_bakasha_detail  
       where v.code_action in (109)
         and v.date_action >= p_from_date
        -- and d.seq_document_type in (55, 75)
         and  nvl(v.code_bakasha_detail,0) in (26,40) 
         and v.date_action <= p_to_date
         and ceo.seq_ezor_ovdim not in
             (8, 10380, 10152, 10387, 10386, 10385, 10381, 10384, 10382)
         and v.taarich_prisha < sysdate;
  end;
