  procedure audit_netuney_sachar(p_from_date date default null,
                                 p_to_date   date default null,
                                 cur         out sys_refcursor) is
  begin
    open cur for
      select *
        from audit_netuney_sachar t
       where trunc(t.aud_when) between p_from_date and p_to_date
       order by t.aud_when asc;
  end;
