  ----------------------------------------------------------
  procedure IshureChaim(cur out sys_refcursor) is
  
  begin
    open cur for
      select case
               when nvl(seq_bney, 0) = 0 then
                pcz.teur_sug_zihuy
               else
                bcz.teur_sug_zihuy
             end זיהוי,
             case
               when nvl(seq_bney, 0) = 0 then
                por.mispar_zehut
               else
                bm1.mispar_zehut_ben_mishpacha
             end מספר_זהות,
             case
               when nvl(seq_bney, 0) = 0 then
                por.shem_prati || ' ' || por.shem_mishpacha
               else
                bm1.shem_prati || ' ' || bm1.shem_mishpacha
             end שם,
             send_letter תאריך_שליחת_המכתב,
             Life_certificate תאריך_המצאת_אישור_חיים_אחרון,
             Extension_life_certificate תאריך_הארכה_אחרון
        from (select distinct v.seq_prisha prisha,
                              bm.seq_bney_mishpacha seq_bney,
                              max(a.date_action) send_letter,
                              max(d1.date_update) Life_certificate,
                              max(d2.date_update) Extension_life_certificate
              
                from v_bakasha_last_status v
              
                left join bakasha b
                  on v.seq_bakasha = b.seq_bakasha
              
                left join poresh p
                  on v.seq_porshim = p.porshim_seq
              
                left join bney_mishpacha bm
                  on b.seq_bney_mishpacha = bm.seq_bney_mishpacha
              
                left join action_log a
                  on v.seq_bakasha = a.seq_bakasha
                    --date send letter to poresh is in the Last half year
                 and a.code_action = 131
                 and trunc(a.date_action) between
                     add_months(trunc(sysdate), -6) and
                     add_months(trunc(sysdate), -1)
              
                left join bakasha v2
                  on v.seq_prisha = v2.SEQ_PRISHA
                left join document_bakasha db2
                  on v2.SEQ_BAKASHA = db2.seq_bakasha
              
                left join document d1
                  on db2.seq_document = d1.seq_document
                    --Life_certificate
                 and d1.seq_document_type = 111
              
                left join document d2
                  on db2.seq_document = d2.seq_document
                    --Extension_life_certificate
                 and d2.seq_document_type = 180
              
                left join bakasha b4
                  on v.seq_prisha = b4.seq_prisha
                 and v.seq_bakasha < b4.seq_bakasha
                    --stop payment
                 and b4.code_sug_bakasha = 19
              
              --Pniya to poresh, Life certificate
               where v.code_sug_bakasha = 25
                 and v.code_bakasha_detail = 24
                    
                    --Not 'roam' office  
                 and v.seq_ezor_ovdim <> 10154
                    
                 and a.seq_action_log is not null
                    
                 and b4.seq_bakasha is null
                    
                    --Not cancel
                 and v.code_action <> 17
                    
                    --family
                 and ((b.seq_bney_mishpacha is null and
                     --Sug zihuy is not standart
                     (nvl(p.sug_zihuy, 0) in (2, 3, 4) or
                     --Or last departure date is before Last half year 
                     (p.last_arrival_date <
                     nvl(p.last_departure_date,
                             to_date('01010001', 'ddmmyyyy')) and
                     p.last_departure_date <
                     add_months(trunc(sysdate), -6))))
                     -- poresh, last departure date is before Last half year 
                     or (b.seq_bney_mishpacha is not null and
                     --Sug zihuy (family) is not standart
                     (nvl(bm.sug_zihuy, 0) in (2, 3, 4) or
                     --Or last departure date is before Last half year 
                     (bm.last_arrival_date <
                     nvl(bm.last_departure_date,
                                to_date('01010001', 'ddmmyyyy')) and
                     bm.last_departure_date <
                     add_months(trunc(sysdate), -6)))))
              
               group by v.seq_prisha, bm.seq_bney_mishpacha) t
        left join prisha pr
          on pr.seq_prisha = t.prisha
        left join poresh por
          on por.porshim_seq = pr.seq_poresh
        left join bney_mishpacha bm1
          on bm1.seq_bney_mishpacha = seq_bney
        left join code_sug_zihuy pcz
          on por.sug_zihuy = pcz.code_sug_zihuy
        left join code_sug_zihuy bcz
          on bm1.sug_zihuy = bcz.code_sug_zihuy
       where
      --Last Life_certificate is before Last half year 
       nvl(Life_certificate, to_date('01010001', 'ddmmyyyy')) <
       add_months(trunc(sysdate), -6)
      --Last Extension_life_certificate is before Last half year 
       and nvl(Extension_life_certificate, to_date('01010001', 'ddmmyyyy')) <
       add_months(trunc(sysdate), -6)
       order by מספר_זהות;
  
  end;
  ----------------------------------------------------------
  procedure nose_misra_nifteru(p_from_date date default null,
                               p_to_date   date default null,
                               cur         out sys_refcursor) is
  begin
    open cur for
      select 'פורש' סוג_גמלאי,
             p.mispar_zehut מספר_זהות,
             p.shem_prati שם_פרטי,
             p.shem_mishpacha שם_משפחה,
             c.derug_hilan דירוג_חילן,
             c.derug_malam דירוג_מלם,
             p.taarich_ptira תאריך_פטירה,
             null מספר_זהות_אב
        from poresh p
        left join v_bakasha_last_status v
          on v.seq_porshim = p.porshim_seq
        left join netuney_sachar n
          on n.seq_bakasha = v.seq_bakasha
        left join code_derug_darga_hilan c
          on c.derug_malam = n.code_derug
       where n.code_sug_maskoret = 1
         and c.derug_hilan in
             (4, 5, 6, 15, 23, 44, 45, 57, 58, 59, 74, 78, 82, 83, 84, 85)
         and p.taarich_ptira >= p_from_date
      union
      select 'פורש',
             p.mispar_zehut,
             p.shem_prati,
             p.shem_mishpacha,
             c.derug_hilan,
             c.derug_malam,
             p.taarich_ptira,
             null
        from poresh p
        left join v_bakasha_last_status v
          on v.seq_porshim = p.porshim_seq
        left join darga_vederug_tik d
          on d.seq_bakasha = v.seq_bakasha
        left join code_derug_darga_hilan c
          on c.derug_malam = d.code_derug
       where c.derug_hilan in
             (4, 5, 6, 15, 23, 44, 45, 57, 58, 59, 74, 78, 82, 83, 84, 85)
         and p.taarich_ptira >= p_from_date
      union
      select 'שאר',
             b.mispar_zehut_ben_mishpacha,
             b.shem_prati,
             b.shem_mishpacha,
             c.derug_hilan,
             c.derug_malam,
             b.taarich_ptira,
             p.mispar_zehut
        from bney_mishpacha b
        left join poresh p
          on p.porshim_seq = b.seq_porshim
        left join v_bakasha_last_status v
          on v.seq_porshim = p.porshim_seq
        left join netuney_sachar n
          on n.seq_bakasha = v.seq_bakasha
        left join code_derug_darga_hilan c
          on c.derug_malam = n.code_derug
       where n.code_sug_maskoret = 1
         and c.derug_hilan in
             (4, 5, 6, 15, 23, 44, 45, 57, 58, 59, 74, 78, 82, 83, 84, 85)
         and b.code_relative is not null
         and b.taarich_ptira >= p_from_date
      union
      select 'שאר',
             b.mispar_zehut_ben_mishpacha,
             b.shem_prati,
             b.shem_mishpacha,
             c.derug_hilan,
             c.derug_malam,
             b.taarich_ptira,
             p.mispar_zehut
        from bney_mishpacha b
        left join poresh p
          on p.porshim_seq = b.seq_porshim
        left join v_bakasha_last_status v
          on v.seq_porshim = p.porshim_seq
        left join darga_vederug_tik d
          on d.seq_bakasha = v.seq_bakasha
        left join code_derug_darga_hilan c
          on c.derug_malam = d.code_derug
       where c.derug_hilan in
             (4, 5, 6, 15, 23, 44, 45, 57, 58, 59, 74, 78, 82, 83, 84, 85)
         and b.code_relative is not null
         and b.taarich_ptira >= p_from_date
       order by 2;
  end;
  ----------------------------------------------------------
  procedure yetom_achere_ptira(p_from_date date default null,
                               p_to_date   date default null,
                               cur         out sys_refcursor) is
  begin
    open cur for
      select distinct bz.mispar_zehut_ben_mishpacha זהות_שאר,
                      bz.shem_prati || ' ' || bz.shem_mishpacha שם_שאר,
                      tt.mispar_zehut זהות_מנוח,
                      tt.shem_prati || ' ' || tt.shem_mishpacha שם_מנוח,
                      tt.taarich_ptira תאריך_פטירה_מנוח,
                      t.mispar_zehut_ben_mishpacha זהות_ילד,
                      t.taarich_leda תאריך_לידה_ילד
        from poresh tt, bney_mishpacha t, bney_mishpacha bz
       where nvl(tt.taarich_ptira, to_date('01/01/1901', 'DD/MM/YYYY')) >
             to_date(p_from_date, 'DD/MM/YYYY')
         and tt.porshim_seq = t.seq_porshim
         and t.code_kirva = 2
         and t.taarich_leda >= tt.taarich_ptira
         and tt.porshim_seq = bz.seq_porshim
         and bz.code_kirva = 1
       order by tt.taarich_ptira desc;
  end;
  ----------------------------------------------------------------------------------------
   procedure doch_ptirot (p_from_date date default null,
                               p_to_date   date default null,
                               cur         out sys_refcursor) is
   begin
     open cur for
          select 'poresh' סוג,
                 p.mispar_zehut מספר_זהות,
                 p.sug_zihuy סוג_זהוי,
                 p.shem_prati שם_פרטי,
                 p.shem_mishpacha שם_משפחה,
                 p.taarich_ptira תאריך_פטירה,
                 pr.gimla_number מספר_גמלה,
                 c.teur_ezor_ovdim משרד,
                 cm.teur_misrad_maskoret משרד_פרישה
            from poresh p
            left join prisha pr
              on pr.seq_poresh = p.porshim_seq
            left join code_ezor_ovdim c
              on c.seq_ezor_ovdim = pr.seq_ezor_ovdim
            left join code_misrad_maskoret cm
              on cm.code_misrad_maskoret = c.code_misrad_maskret
           where nvl(p.taarich_ptira, to_date( '01/01/1901','dd/mm/yyyy'))  >  to_date(p_from_date,'dd/mm/yyyy') 
             and nvl(p.taarich_ptira, to_date( '01/01/1901','dd/mm/yyyy'))  >  to_date( '01/01/1901','dd/mm/yyyy')
             and nvl(p.sug_zihuy, 0) = 1
             and p.shem_prati <> 'הסבה'
          union
          select 'sheer' סוג,
                 b.mispar_zehut_ben_mishpacha,
                 b.sug_zihuy,
                 b.shem_prati,
                 b.shem_mishpacha,
                 b.taarich_ptira,
                 pr.gimla_number,
                 c.teur_ezor_ovdim,
                 cm.teur_misrad_maskoret
            from bney_mishpacha b
            left join prisha pr
              on pr.seq_poresh = b.seq_porshim
            left join code_ezor_ovdim c
              on c.seq_ezor_ovdim = pr.seq_ezor_ovdim
            left join code_misrad_maskoret cm
              on cm.code_misrad_maskoret = c.code_misrad_maskret
           where nvl(b.taarich_ptira,to_date( '01/01/1901','dd/mm/yyyy'))> to_date(p_from_date,'dd/mm/yyyy')
            and nvl(b.taarich_ptira, to_date( '01/01/1901','dd/mm/yyyy'))  >  to_date( '01/01/1901','dd/mm/yyyy') 
             and b.code_relative is not null
             and nvl(b.sug_zihuy, 0) = 1
           order by 2;

   end; 
   
     ----------------------------------------------------------------------------------------
   procedure chozer_laarets (cur out sys_refcursor) is
   begin
     open cur for
         select  
          p.mispar_zehut מספר_זהות,
          p.shem_prati || ' ' ||p.shem_mishpacha שם 
          ,p.last_arrival_date תאריך_כניסה_אחרון_לארץ,
          a.from_date תאריך_ההפסקה 
          from bakasha a
          left join prisha pr on pr.seq_prisha=a.seq_prisha
          left join poresh p on pr.seq_poresh=p.porshim_seq
          left join v_bakasha_last_status l on l.seq_bakasha=a.seq_bakasha
          where a.code_sug_bakasha=19 
          and a.code_bakasha_detail=12
          and l.code_action <> 17
          and p.last_arrival_date >a.from_date 
          and not exists (select * from v_bakasha_last_status v 
              where v.seq_porshim=p.porshim_seq 
              and v.code_sug_bakasha=20 
              and v.date_bakasha>a.date_bakasha)
          and  nvl(p.taarich_ptira, to_date( '01/01/1901','dd/mm/yyyy'))  =  to_date( '01/01/1901','dd/mm/yyyy')
          and a.date_bakasha > to_date('01/01/2020','dd/mm/yyyy');
   end;                                            
  ----------------------------------------------------------------------------------------
end PK_Reports;
/

create or replace package body prm_system_copy.PK_Reports1 is
  ----------------------------------------------------------------------------------------
  procedure Detailed_Report(cur         out sys_refcursor,
                            p_from_date date,
                            p_to_date   date,
                            p_data_type number) is
  begin
  
    open cur for
      select e.teur_ezor_ovdim,
             v.MISPAR_ZEHUT,
             p.shem_mishpacha,
             p.shem_prati,
             v.TAARICH_PRISHA,
             v.CODE_SEIF_PRISHA,
             s.teur_seif_prisha
      
        from v_regila_last_status v
        left join code_ezor_ovdim e
          on v.SEQ_EZOR_OVDIM = e.seq_ezor_ovdim
        left join poresh p
          on v.SEQ_PORSHIM = p.porshim_seq
        left join code_seif_prisha s
          on s.code_seif_prisha = v.CODE_SEIF_PRISHA
       where 1 = 1
         and v.CODE_SUG_BAKASHA in (1, 3, 5)
         and v.TAARICH_PRISHA >= p_from_date
         and v.TAARICH_PRISHA <= p_to_date
            --data type
         and ( --chinuch
              (p_data_type = 1 and v.CODE_MAKOR = 3) or
             --health
              (p_data_type = 2 and v.CODE_MAKOR = 1 and
              pk_load_mimshak.Get_ezor_ovdim_category(v.SEQ_EZOR_OVDIM) = 2) or
             --merkava without chinuch
              (p_data_type = 3 and v.CODE_MAKOR = 1 and
              pk_load_mimshak.Get_ezor_ovdim_category(v.SEQ_EZOR_OVDIM) <> 2) or
             --yadani
              (p_data_type = 4 and v.CODE_MAKOR = 2) or
             --get all data type
              (p_data_type = 0));
  end;
  ----------------------------------------------------------------------------------------
  procedure By_Years_Report(cur         out sys_refcursor,
                            p_from_date date,
                            p_to_date   date
                            --for same structure parameter all dochot nasham, please  no delete this parametes
                            -- ,p_data_type number default null
                            ) is
  begin
  
    open cur for
    -- In the end, Add percent columns.
      select base.*,
             round(merkava / all_tikim * 100, 1) merkava_p,
             round(merkava_health / all_tikim * 100, 1) merkava_health_p,
             round(yadany / all_tikim * 100, 1) yadany_p,
             round(chinuch / all_tikim * 100, 1) chinuch_p
        from (with t as (select *
                           from -- Get relevant rows
                                (select case
                                          when code_makor = 2 then
                                           2
                                          when code_makor = 3 then
                                           3
                                          when code_makor = 1 and
                                               pk_load_mimshak.Get_ezor_ovdim_category(t.SEQ_EZOR_OVDIM) = 1 then
                                           11
                                          when code_makor = 1 and
                                               pk_load_mimshak.Get_ezor_ovdim_category(t.SEQ_EZOR_OVDIM) = 2 then
                                           12
                                        end ezor_ovdim_type,
                                        
                                        to_char(t.TAARICH_PRISHA, 'yyyy') year_prisha,
                                        t.code_sug_bakasha,
                                        t.seq_ezor_ovdim
                                 
                                   from v_regila_last_status t
                                 --~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
                                 -- Get  tikim in one type for comparison.
                                 union all
                                 select -1 ezor_ovdim_type,
                                        to_char(t.TAARICH_PRISHA, 'yyyy') year_prisha,
                                        t.code_sug_bakasha,
                                        t.seq_ezor_ovdim
                                 
                                   from v_regila_last_status t) internal
                          where 1 = 1
                            and seq_ezor_ovdim not in
                                (select t.seq_ezor_ovdim
                                   from EZOR_OVDIM_CATEGORY t
                                  where t.code_sug_ezor_ovdim in (8, 9, 10))
                            and CODE_SUG_BAKASHA in (1, 3, 5)
                            and year_prisha >= to_char(p_from_date, 'yyyy')
                            and year_prisha <= to_char(p_to_date, 'yyyy'))
               select *
                 from t
               -- Group by years and pivot columns
               pivot(count(ezor_ovdim_type)
                  for ezor_ovdim_type in(11 as merkava,
                                         12 as merkava_health,
                                         2 as yadany,
                                         3 as chinuch,
                                         -1 as all_tikim))
                order by year_prisha) base;
  
  
  end;
  ----------------------------------------------------------------------------------------
  procedure By_seif_prisha_Report(cur         out sys_refcursor,
                                  p_from_date date,
                                  p_to_date   date,
                                  p_data_type number) is
  begin
  
    open cur for
      select year_prisha השנה,
             all_tikim   "סה כ פורשים",
             must        "פרישת חובה",
             must_p      "אחוז",
             wanted      "פרישה מרצון",
             wanted_p    "אחוז  ",
             dismissal   "פיטורין",
             dismissal_p "  אחוז",
             health      "בריאות",
             health_p    " אחוז ",
             death       "פטירה",
             death_p     " אחוז   ",
             freezing    הקפאה,
             freezing_p  "   אחוז  "
        from (with base_table as (select s.code_report_group_prisha base_code_seif_prisha,
                                         to_char(t1.taarich_prisha, 'yyyy') base_year_prisha
                                    from v_regila_last_status t1
                                    LEFT join code_seif_prisha s
                                      on t1."CODE_SEIF_PRISHA" =
                                         s.code_seif_prisha
                                   where 1 = 1
                                     and seq_ezor_ovdim not in
                                         (select t.seq_ezor_ovdim
                                            from EZOR_OVDIM_CATEGORY t
                                           where t.code_sug_ezor_ovdim in
                                                 (8, 9, 10))
                                     and t1.CODE_SUG_BAKASHA in (1, 3, 5)
                                        
                                     and to_char(t1.taarich_prisha, 'yyyy') >=
                                         to_char(p_from_date, 'yyyy')
                                     and to_char(t1.taarich_prisha, 'yyyy') <=
                                         to_char(p_to_date, 'yyyy')
                                        --data type
                                     and ( --chinuch
                                          (p_data_type = 1 and
                                          t1.CODE_MAKOR = 3) or
                                         --health
                                          (p_data_type = 2 and
                                          t1.CODE_MAKOR = 1 and
                                          pk_load_mimshak.Get_ezor_ovdim_category(t1.SEQ_EZOR_OVDIM) = 2) or
                                         --merkava without chinuch
                                          (p_data_type = 3 and
                                          t1.CODE_MAKOR = 1 and
                                          pk_load_mimshak.Get_ezor_ovdim_category(t1.SEQ_EZOR_OVDIM) <> 2) or
                                         --yadani
                                          (p_data_type = 4 and
                                          t1.CODE_MAKOR = 2) or
                                         --get all data type
                                          (p_data_type = 0)))
             
             -- In the end, Add percent columns.
               select base.*,
                      round(must / all_tikim * 100, 1) must_p,
                      round(wanted / all_tikim * 100, 1) wanted_p,
                      round(Dismissal / all_tikim * 100, 1) Dismissal_p,
                      round(health / all_tikim * 100, 1) health_p,
                      round(Death / all_tikim * 100, 1) Death_p,
                      round(Freezing / all_tikim * 100, 1) Freezing_p
                 from (with t as (
                                  -- Get relevant rows
                                  select all base_code_seif_prisha code_seif_prisha,
                                              base_year_prisha      year_prisha
                                  
                                    from base_table
                                  --~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
                                  -- Get all tikim for comparison.
                                  union all
                                  select -1               code_seif_prisha,
                                          base_year_prisha year_prisha
                                  
                                    from base_table)
                        select *
                          from t
                        -- Group by years and pivot columns
                        pivot(count(code_seif_prisha)
                           for code_seif_prisha in(1 as must,
                                                   2 as wanted,
                                                   3 as Dismissal,
                                                   4 health,
                                                   5 as Death,
                                                   6 as Freezing,
                                                   -1 as all_tikim))
                         order by year_prisha) base);
  
  
  
  end;
  ----------------------------------------------------------------------------------------
  procedure By_Age_Report(cur         out sys_refcursor,
                          p_from_date date,
                          p_to_date   date,
                          p_data_type number default 0) is
  begin
  
    open cur for
      select year_prisha השנה,
             ALL_TIKIM   "סה כ פורשים",
             a           "67+",
             a_p         "אחוז   ",
             b           "64-67",
             b_p         "אחוז",
             c           "62-64",
             c_p         "אחוז  ",
             d           "60-62",
             d_p         "אחוז ",
             e           "55-60",
             e_p         "אחוז    ",
             f           "50-55",
             f_p         "אחוז        ",
             g           "עד 50 ",
             g_p         "אחוז     ",
             AVERAGE     "גיל ממוצע"
        from (with base_table as (select trunc(months_between(t1.taarich_prisha,
                                                              p1.taarich_leda) / 12) base_age,
                                         to_char(t1.TAARICH_PRISHA, 'yyyy') base_year_prisha
                                    from v_regila_last_status t1
                                    left join poresh p1
                                      on t1.seq_porshim = p1.porshim_seq
                                   where 1 = 1
                                     and seq_ezor_ovdim not in
                                         (select t.seq_ezor_ovdim
                                            from EZOR_OVDIM_CATEGORY t
                                           where t.code_sug_ezor_ovdim in
                                                 (8, 9, 10))
                                     and t1.CODE_SUG_BAKASHA in (1, 3, 5)
                                     and to_char(t1.TAARICH_PRISHA, 'yyyy') >=
                                         to_char(p_from_date, 'yyyy')
                                     and to_char(t1.TAARICH_PRISHA, 'yyyy') <=
                                         to_char(p_to_date, 'yyyy')
                                        --data type
                                     and ( --chinuch
                                          (p_data_type = 1 and
                                          t1.CODE_MAKOR = 3) or
                                         --health
                                          (p_data_type = 2 and
                                          t1.CODE_MAKOR = 1 and
                                          pk_load_mimshak.Get_ezor_ovdim_category(t1.SEQ_EZOR_OVDIM) = 2) or
                                         --merkava without chinuch
                                          (p_data_type = 3 and
                                          t1.CODE_MAKOR = 1 and
                                          pk_load_mimshak.Get_ezor_ovdim_category(t1.SEQ_EZOR_OVDIM) <> 2) or
                                         --yadani
                                          (p_data_type = 4 and
                                          t1.CODE_MAKOR = 2) or
                                         --get all data type
                                          (p_data_type = 0)))
             -- In the end, Add percent columns.
             
               select base.*,
                      round(a / all_tikim * 100, 1) a_p,
                      round(b / all_tikim * 100, 1) b_p,
                      round(c / all_tikim * 100, 1) c_p,
                      round(d / all_tikim * 100, 1) d_p,
                      round(e / all_tikim * 100, 1) e_p,
                      round(f / all_tikim * 100, 1) f_p,
                      round(g / all_tikim * 100, 1) g_p,
                      round((select sum(base_age)
                               from base_table
                              where base_year_prisha = year_prisha) /
                            all_tikim,
                            1) Average
                 from (with t as (
                                  -- Get relevant rows
                                  select case
                                            when base_table.base_age >= 67 then
                                             1
                                            when base_table.base_age >= 64 and
                                                 base_table.base_age < 67 then
                                             2
                                            when base_table.base_age >= 62 and
                                                 base_table.base_age < 64 then
                                             3
                                            when base_table.base_age >= 60 and
                                                 base_table.base_age < 62 then
                                             4
                                            when base_table.base_age >= 55 and
                                                 base_table.base_age < 60 then
                                             5
                                            when base_table.base_age >= 50 and
                                                 base_table.base_age < 55 then
                                             6
                                            when base_table.base_age < 50 then
                                             7
                                          end age,
                                          base_table.base_year_prisha year_prisha
                                    from base_table
                                  --~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
                                  -- Get all tikim for comparison.
                                  union all
                                  select -1 age, base_year_prisha year_prisha
                                    from base_table)
                        select *
                          from t
                        -- Group by years and pivot columns
                        pivot(count(age)
                           for age in(1 as a,
                                      2 as b,
                                      3 as c,
                                      4 as d,
                                      5 as e,
                                      6 as f,
                                      7 as g,
                                      -1 as all_tikim))
                         order by year_prisha) base);
  
  
  
  end;
  ----------------------------------------------------------------------------------------
  procedure By_pension_rate_Report(cur         out sys_refcursor,
                                   p_from_date date,
                                   p_to_date   date,
                                   p_data_type number) is
  begin
  
    open cur for
    -- In the end, Add percent columns.
      select year_prisha השנה,
             a           "סה כ",
             b           "גיל ממוצע",
             c           "ממוצע שיעור הקצבה מכח השירות בפועל",
             d           "ממוצע סהכ שיעור הקצבה המוגדלת",
             e           "ממוצע הגדלת השעור הקצבה",
             f           "סה כ עובדים ששרותם הוגדל",
             g           "אחוז",
             h           "ממוצע הגדלת שיעור הקצבה למוגדלים"
        from (select to_char(t.taarich_prisha, 'yyyy') year_prisha,
                     count(p.porshim_seq) a,
                     round(sum(trunc(months_between(t.taarich_prisha,
                                                    p.taarich_leda) / 12)) /
                           count(p.porshim_seq),
                           1) b,
                     round(sum(n.achuz_kizba_kafuf_chelkiyut) /
                           count(p.porshim_seq),
                           1) c,
                     round((sum(n.achuz_kizba_kafuf_chelkiyut) +
                           sum(hn.achuz_meushar_sum)) / count(p.porshim_seq),
                           1) d,
                     round(sum(hn.achuz_meushar_sum) / count(p.porshim_seq),
                           1) e,
                     count(hn.seq_bakasha) f,
                     round(count(hn.seq_bakasha) / count(p.porshim_seq) * 100,
                           1) g,
                     round(sum(hn.achuz_meushar_sum) / count(hn.seq_bakasha),
                           1) h
                from v_regila_last_status t
                left join poresh p
                  on t.seq_porshim = p.porshim_seq
                left join netuney_tik_mechushavim n
                  on n.seq_bakasha = t.SEQ_BAKASHA
                 and n.code_department = 1
                left join (select hagdala_nimuk.seq_bakasha,
                                 sum(hagdala_nimuk.achuz_meushar) achuz_meushar_sum
                            from hagdala_nimuk
                           group by hagdala_nimuk.seq_bakasha) hn
                  on hn.seq_bakasha = t.seq_bakasha
               where 1 = 1
                 and seq_ezor_ovdim not in
                     (select t.seq_ezor_ovdim
                        from EZOR_OVDIM_CATEGORY t
                       where t.code_sug_ezor_ovdim in (8, 9, 10))
                 and t.CODE_SUG_BAKASHA in (1, 3, 5)
                 and to_char(t.taarich_prisha, 'yyyy') >=
                     to_char(p_from_date, 'yyyy')
                 and to_char(t.taarich_prisha, 'yyyy') <=
                     to_char(p_to_date, 'yyyy')
                    --data type
                 and ( --chinuch
                      (p_data_type = 1 and t.CODE_MAKOR = 3) or
                     --health
                      (p_data_type = 2 and t.CODE_MAKOR = 1 and
                      pk_load_mimshak.Get_ezor_ovdim_category(t.SEQ_EZOR_OVDIM) = 2) or
                     --merkava without chinuch
                      (p_data_type = 3 and t.CODE_MAKOR = 1 and
                      pk_load_mimshak.Get_ezor_ovdim_category(t.SEQ_EZOR_OVDIM) <> 2) or
                     --yadani
                      (p_data_type = 4 and t.CODE_MAKOR = 2) or
                     --get all data type
                      (p_data_type = 0))
               group by to_char(t.taarich_prisha, 'yyyy')
               order by year_prisha);
  end;
  -----------------------
  procedure address_prorshim(p_IDList varchar2, cur out sys_refcursor) is
  begin
    open cur for
      select distinct p.mispar_zehut   "מספר זהות",
                      p.shem_prati     "שם פרטי",
                      p.shem_mishpacha "שם משפחה",
                      c.teur_ir        עיר,
                      aa.street        רחוב,
                      aa.house         "מספר בית",
                      aa.apartment     "דירה",
                      aa.mikud         מיקוד
        from poresh p
       right join (select max(a.seq_address) seq_address, a.seq_poresh
                     from address a
                    group by a.seq_poresh) w
          on w.seq_poresh = p.porshim_seq
        left join address aa
          on aa.seq_address = w.seq_address
        left join code_ir c
          on c.code_ir = aa.code_city
       where p.mispar_zehut in
            
             (select to_number(column_value) as mispar_zehut
                from xmltable(p_IDlist))
      union
      select distinct o.mispar_zehut_ben_mishpacha,
                      o.shem_prati,
                      o.shem_mishpacha,
                      c.teur_ir,
                      aa.street,
                      aa.house,
                      aa.apartment,
                      aa.mikud
        from bney_mishpacha o
       right join (select max(a.seq_address) seq_address,
                          a.seq_bney_mishpacha
                     from address a
                    group by a.seq_bney_mishpacha) w
          on w.seq_bney_mishpacha = o.seq_bney_mishpacha
        left join address aa
          on aa.seq_address = w.seq_address
        left join code_ir c
          on c.code_ir = aa.code_city
       where o.mispar_zehut_ben_mishpacha in
            
             (select to_number(column_value) as mispar_zehut
                from xmltable(p_IDlist))
      
      ;
  end;
  ----------------------------------------------------------
  procedure histtfut_Signed(p_from_date date default null,
                            p_to_date   date default null,
                            
                            cur out sys_refcursor) is
  begin
    open cur for
      select distinct v.mispar_zehut     as מספר_זהות,
                      pr.gimla_number    as מספר_גמלה,
                      p.shem_prati       as שם_פרטי,
                      p.shem_mishpacha   as שם_משפחה,
                      co.teur_ezor_ovdim as משרד_פרישה,
                      v.taarich_prisha   as תאריך_פרישה,
                      --      pa.date_payment     as תאריך_תחילת_תשלום,
                      p.taarich_leda      as תאריך_לידה,
                      co2.teur_ezor_ovdim as גוף_משתתף,
                      u.teur_unit         as מחוז
      
        from v_bakasha_last_status v
        left join prisha pr
          on pr.seq_prisha = v.seq_prisha
        left join code_unit u
          on u.seq_code_unit = pr.seq_code_unit
        left join poresh p
          on p.porshim_seq = v.seq_porshim
        left join code_ezor_ovdim co
          on co.seq_ezor_ovdim = v.seq_ezor_ovdim
        left join participation pa
          on pa.seq_bakasha = v.seq_bakasha
        left join code_ezor_ovdim co2
          on pa.seq_guf = co2.seq_ezor_ovdim
        left join action_log a
          on a.code_action = 36
         and a.seq_bakasha = v.seq_bakasha
         and a.date_action >= nvl(p_from_date, v.date_action)
         and a.date_action <= nvl(p_to_date, v.date_action)
       where v.code_sug_bakasha in (8, 9)
         and a.seq_action_log is not null
      
      --   order by v.taarich_prisha
      ;
  end;
  ----------------------------------------------------------
  procedure Kabaut_Report(p_from_date date default null,
                          p_to_date   date default null,
                          cur         out sys_refcursor) is
  begin
    open cur for
      select 'M030' קוד_משתמש_מעדכן --1
            ,
             'מנהל הגמלאות ' קידומת_משתמש_מעדכן,
             P.MISPAR_ZEHUT זהות_מנ --3
            ,
             t.gimla_number מספר_תיק_ידני --4
            ,
             NULL קוד_אגף_ויחידה ---5
            ,
             NULL אגף_ויחידה --6
            ,
             P.MISPAR_ZEHUT זהות_מ_נ_אב --7
            ,
             NULL קוד_סוג_תיק --8
            ,
             NULL סוג_תיק --9
            ,
             P.SHEM_MISHPACHA שם_משפחה ---10
            ,
             P.SHEM_PRATI שם_פרטי --11
            ,
             NULL קוד_משרד --12
            ,
             teur_ezor_ovdim משרד_פרישה --13
            ,
             n.TAARICH_PRISHA תאריך_פרישה ---14
            ,
             n.date_start_zakaut תאריך_תחילת_תשלום ---15 -- מלמטה
            ,
             NULL קוד_סיבה ---16
            ,
             NULL סיבת_סגירה ---17
            ,
             NULL הערה ---18
            ,
             P.TAARICH_LEDA תאריך_לידה --19  --- הו
            ,
             n.date_start_zakaut תאריך_תחילת_תשלום2 --20 -- מלמטה
            ,
             NULL גוף_משתתף --21
        from v_bakasha_last_status t
        left join prisha pr
          on t.SEQ_PRISHA = pr.seq_prisha
        left join v_bakasha_last_zakaut n
          on t.seq_bakasha = n.seq_bakasha
        left join bakasha_regila br
          on t.SEQ_bakasha = br.seq_bakasha
        left join bakasha b
          on t.SEQ_bakasha = b.seq_bakasha
        left join poresh p
          on pr.seq_poresh = p.porshim_seq
        left join code_ezor_ovdim e
          on e.seq_ezor_ovdim = pr.seq_ezor_ovdim
        left join Code_Source m
          on t.CODE_source = m.code_source
        left join code_user u
          on t.code_user_to_internal = u.id_user
        left join code_sug_bakasha sb
          on t.CODE_SUG_BAKASHA = sb.code_sug_bakasha
        left join CODE_BAKASHA_DETAIL dt
          on dt.code_bakasha_detail = b.code_bakasha_detail
       where 2 = 2
         AND t.CODE_SUG_BAKASHA = 1
         and nvl(n.date_start_zakaut, to_date('01/01/1900', 'dd/mm/yyyy')) between
            --- to_date('01/01/2020','dd/mm/yyyy')  and to_date('01/01/9999','dd/mm/yyyy')
             nvl(p_from_date, to_date('01/01/0001', 'dd/mm/yyyy')) and
             nvl(p_to_date, to_date('01/01/9999', 'dd/mm/yyyy'))
         AND pr.SEQ_EZOR_OVDIM = 2962;
  end;
  ----------------------------------------------------------------------------------------
  procedure Wrong_If_From_Pnim_In(cur out sys_refcursor) is
  begin
    open cur for
      select distinct t.id_number as מספר_זהות,
                      t.first_name as שם_פרטי,
                      t.last_name as שם_משפחה,
                      c.teur_sug_zihuy as סוג_זיהוי,
                      ce.teur_ezor_ovdim as משרד_פרישה,
                      'פורש' as פורש_או_שאר
        from LD_INTERIOR_ALL t
       right join poresh p
          on p.mispar_zehut = to_number(t.id_number)
        left join code_sug_zihuy c
          on c.code_sug_zihuy = p.sug_zihuy
        left join prisha pr on pr.seq_poresh = p.porshim_seq
        left join code_ezor_ovdim ce on ce.seq_ezor_ovdim = pr.seq_ezor_ovdim
       where t.id_number_o = '000000000'
      union
      select distinct t.id_number as מספר_זהות,
                      t.first_name as שם_פרטי,
                      t.last_name as שם_משפחה,
                      c.teur_sug_zihuy as סוג_זיהוי,
                      ce.teur_ezor_ovdim as משרד_פרישה,
                      'שאר' as פורש_או_שאר
        from LD_INTERIOR_ALL t
       right join bney_mishpacha b
          on b.mispar_zehut_ben_mishpacha = to_number(t.id_number)
        left join code_sug_zihuy c
          on c.code_sug_zihuy = b.sug_zihuy
        left join prisha pr on pr.seq_poresh = b.seq_porshim
        left join code_ezor_ovdim ce on ce.seq_ezor_ovdim = pr.seq_ezor_ovdim
       where t.id_number_o = '000000000'
      union
      select to_char(cnt, '9999999999'),
             ' מספר רשומות שנשלחו' as שם_פרטי,
             '' as שם_משפחה,
             '' as סוג_זיהוי,
             '' as משרד_פרישה,
             '' as פורש_או_שאר
      
      --  כמות רשומות שנשלחו למשרד הפנים:
        from (select l.count_success_tikim cnt
                from ld_protocol l
               where l.seq_ld_protocol =
                     (select max(lp.seq_ld_protocol)
                        from ld_protocol lp
                       where lp.code_process = 5
                         and lp.message = 'include all'
                         and lp.code_sub_process = 1))
      
      union
      select to_char(cnt, '9999999999'),
             'מספר רשומות שהתקבלו' as שם_פרטי,
             '' as שם_משפחה,
             '' as סוג_זיהוי,
             '' as משרד_פרישה,
             '' as פורש_או_שאר
      
        from --כמות רשומות שהתקבלו ממשרד הפנים
             (select l.count_success_tikim cnt
                from ld_protocol l
               where l.seq_ld_protocol =
                     (select min(lp.seq_ld_protocol)
                        from ld_protocol lp
                       where lp.code_process = 5
                         and lp.code_sub_process = 2
                         and lp.seq_ld_protocol >
                             (select max(lp1.seq_ld_protocol)
                                from ld_protocol lp1
                               where lp1.code_process = 5
                                 and lp1.message = 'include all'
                                 and lp1.code_sub_process = 1)));
  
  end;
