m5.shiur_miztaber_legil_60,
m5.sachar_acharon,
case when m5.seq_bakasha is null then ns4.havraa_days else m5.havraa_days end havraa_days,
case when m5.seq_bakasha is null then ns4.sum_havraa else m5.sum_havraa end sum_havraa,
case when m5.seq_bakasha is null then ns4.ramat_bigud else m5.ramat_bigud end ramat_bigud,
case when m5.seq_bakasha is null then ns4.sum_bigud else m5.sum_bigud end sum_bigud,
case when m5.seq_bakasha is null then m4.achuz_hagdala else case when nvl(ch5.code_nimuk,0) in (7,17,11) then h5.achuz_meushar else null end end achuz_hagdala,
case when m4.seq_bakasha is null then vm5.code_seif_prisha else m4.code_seif_prisha end code_seif_prisha,
case when m5.seq_bakasha is null then m4.tkufa_mezaka_medina_only else nm5.tkufa_mezaka_medina_only end tkufa_mezaka_medina_only,
case when m5.seq_bakasha is null then m4.tkufa_mezaka_sherut else nm5.tkufa_mezaka_sherut end tkufa_mezaka_sherut,
case when m5.seq_bakasha is null then m4.chelkiyut_sofit else nm5.chelkiyut_sofit end chelkiyut_sofit,
case when m5.seq_bakasha is null then m4.chelkiyut_legil_60 else case when vm5.code_seif_prisha = 215 then nm5.chelkiyut_meshuklelet_sherut else null end end chelkiyut_legil_60,
m3.teur_mazav_mishpachti,
m3.migdar,
case when m5.seq_bakasha is null then case when br5.chinuch_mikzoa = 911 then 'גננת' else null end else m4.is_ganenet end is_ganenet,
case when m5.seq_bakasha is null then cg5.teur_group_prisha else m4.teur_group_prisha end teur_group_prisha,
nvl(m5.misra_sachar,0) misra_sachar,
nvl(m4.misra_zakaut,0) misra_zakaut,
--m5.derug
case when m5.seq_bakasha is null then
     case when m3.seq_ezor_ovdim <> 206 then cd4.teur_derug
     else null end
else m5.derug end derug
from
(select
m1.*,
(select max(m2.seq_bakasha)
from mz m2
where m2.mispar_zehut = m1.mispar_zehut
and   m2.seq_prisha   = m1.seq_prisha
and   m2.code_sug_bakasha in (1,14)) s_sachar,
(select max(m2.seq_bakasha)
from mz m2
where m2.mispar_zehut = m1.mispar_zehut
and   m2.seq_prisha   = m1.seq_prisha
and   m2.code_sug_bakasha in (1,3,5)) s_zakaut
from mz m1
) sel
left join mz m3 on
m3.seq_bakasha = case when sel.s_sachar is not null then sel.s_sachar else sel.s_zakaut end
left join mz m4 on
m4.seq_bakasha = case when sel.s_zakaut is not null then sel.s_zakaut end
left join mz m5 on
m5.seq_bakasha = case when sel.s_sachar is not null then sel.s_sachar end
left join v_bakasha_last_status vm5 on vm5.seq_bakasha = f_get_seq_bakasha_zakaut(m3.gimla_number,'poresh')
left join netuney_tik_mechushavim nm5 on nm5.seq_bakasha = vm5.seq_bakasha
                                     and nm5.code_department = 2
                                     and nvl(nm5.mispar_misra,0) = nvl(m5.misra_sachar,0)
left join code_group_prisha cg5 on cg5.code_group_prisha = nm5.code_group_prisha
left join bakasha_regila br5 on br5.seq_bakasha = vm5.seq_bakasha and br5.chinuch_mikzoa = 911
left join hagdala_nimuk h5 on h5.seq_bakasha = vm5.seq_bakasha
left join code_hagdala_nimuk ch5 on ch5.code_nimuk = h5.code_nimuk
left join v_bakasha_last_status vm4 on vm4.seq_bakasha = f_get_seq_bakasha_sachar(m3.gimla_number)
left join netuney_sachar ns4 on ns4.seq_bakasha = vm4.seq_bakasha
                            left join chinuch_reforma chr4 on chr4.seq_bakasha = ns4.seq_bakasha
                                                          and chr4.seq_chinuch_reforma = ns4.seq_chinuch_reforma
                            left join code_chinuch_reforma ccr4 on ccr4.code_chinuch_reforma = chr4.code_reforma
                            left join code_chinuch_alterntive cca4 on cca4.code_chinuch_alterntive = chr4.code_chinuch_alterntive
                            left join code_sug_maskoret cc4 on cc4.code_chinuch_alterntive = cca4.code_chinuch_alterntive
                            and cc4.code_sug_maskoret = ns4.code_sug_maskoret
                            and cc4.code_chinuch_sug_maskoret = 1
left join netuney_sachar ns4_60 on ns4_60.seq_bakasha = vm4.seq_bakasha
                            and nvl(ns4_60.mispar_misra,0) = nvl(m4.misra_zakaut,0)
                            and ns4_60.code_sug_maskoret = 2
                            --and vm4.seq_ezor_ovdim <> 206
left join code_derug cd4    on cd4.code_derug = ns4.code_derug
where (m3.code_sug_bakasha <> 1 or (m3.code_sug_bakasha = 1 and nvl(m4.misra_zakaut,0) = nvl(m5.misra_sachar,0)) )
--and not(m3.code_sug_bakasha in(1,14) and m5.maskoret_kovaat is null and m3.seq_ezor_ovdim = 206)
and not (m5.seq_bakasha is null and m3.seq_ezor_ovdim = 206 and cc4.code_sug_maskoret <> ns4.code_sug_maskoret)
--and m3.seq_ezor_ovdim <> 206

union
select distinct
/*m3.seq_bakasha,
m4.seq_bakasha,
m5.seq_bakasha,
vm4.seq_bakasha,vm4.code_sug_bakasha,
vm5.seq_bakasha,vm5.code_sug_bakasha,*/
m3.teur_bakasha,
m3.mispar_zehut,
m3.shem,
m3.taarich_leda,
case when m5.seq_bakasha is null then m4.taarich_prisha else vm5.taarich_prisha end taarich_prisha,
m3.teur_ezor_ovdim,
m5.reforma,
m5.sum_mivchaney_bagrut,
m5.sum_mivchaney_bagrut_60,
m5.sum_hinuch_kita,
m5.sum_hinuch_kita_60,
case when m5.seq_bakasha is null then m4.achuz_kizba_sofi else nm5.achuz_kizba_sofi end achuz_kizba_sofi,
case when m5.seq_bakasha is null then m4.achuz_kizba_gil_60 else nm5.achuz_kizba_gil_60 end achuz_kizba_gil_60,
case when m5.maskoret_kovaat is null  or m5.seq_bakasha is null then ns4.maskoret_kovaat
else m5.maskoret_kovaat end maskoret_kovaat,
case when m5.maskoret_kovaat_legil_60 is null or m5.seq_bakasha is null then ns4_60.maskoret_kovaat
else m5.maskoret_kovaat_legil_60 end maskoret_kovaat_legil_60,
m5.factor,
m5.shiur_miztaber,
m5.shiur_miztaber_legil_60,
m5.sachar_acharon,
--m5.havraa_days,
case when m5.havraa_days is null or m5.seq_bakasha is null then ns4.havraa_days
/*     case when m3.seq_ezor_ovdim <> 206 then ns4.havraa_days
     else null end
*/
else m5.havraa_days end havraa_days,
--m5.sum_havraa,
case when m5.sum_havraa is null or m5.seq_bakasha is null then ns4.sum_havraa
/*     case when m3.seq_ezor_ovdim <> 206 then ns4.sum_havraa
     else null end
*/
else m5.sum_havraa end sum_havraa,
--m5.ramat_bigud,
case when m5.ramat_bigud is null or m5.seq_bakasha is null then ns4.ramat_bigud
/*     case when m3.seq_ezor_ovdim <> 206 then ns4.ramat_bigud
     else null end
*/
else m5.ramat_bigud end ramat_bigud,
--m5.sum_bigud,
case when m5.sum_bigud is null or m5.seq_bakasha is null then ns4.sum_bigud
/*     case when m3.seq_ezor_ovdim <> 206 then ns4.sum_bigud
     else null end
*/
else m5.sum_bigud end sum_bigud,
case when m5.seq_bakasha is null then m4.achuz_hagdala else case when nvl(ch5.code_nimuk,0) in (7,17,11) then h5.achuz_meushar else null end end achuz_hagdala,
case when m4.seq_bakasha is null then vm5.code_seif_prisha else m4.code_seif_prisha end code_seif_prisha,
case when m5.seq_bakasha is null then m4.tkufa_mezaka_medina_only else nm5.tkufa_mezaka_medina_only end tkufa_mezaka_medina_only,
case when m5.seq_bakasha is null then m4.tkufa_mezaka_sherut else nm5.tkufa_mezaka_sherut end tkufa_mezaka_sherut,
case when m5.seq_bakasha is null then m4.chelkiyut_sofit else nm5.chelkiyut_sofit end chelkiyut_sofit,
case when m5.seq_bakasha is null then m4.chelkiyut_legil_60 else case when vm5.code_seif_prisha = 215 then nm5.chelkiyut_meshuklelet_sherut else null end end chelkiyut_legil_60,
m3.teur_mazav_mishpachti,
m3.migdar,
case when m5.seq_bakasha is null then case when br5.chinuch_mikzoa = 911 then 'גננת' else null end else m4.is_ganenet end is_ganenet,
case when m5.seq_bakasha is null then cg5.teur_group_prisha else m4.teur_group_prisha end teur_group_prisha,
nvl(m5.misra_sachar,0) misra_sachar,
nvl(m4.misra_zakaut,0) misra_zakaut,
--m5.derug
case when m5.seq_bakasha is null then
     case when m3.seq_ezor_ovdim <> 206 then cd4.teur_derug
     else null end
else m5.derug end derug
from
(select
m1.*,
(select max(m2.seq_bakasha)
from m m2
where m2.mispar_zehut = m1.mispar_zehut
and   m2.seq_prisha   = m1.seq_prisha
and   m2.code_sug_bakasha in (1,14)) s_sachar,
(select max(m2.seq_bakasha)
from m m2
where m2.mispar_zehut = m1.mispar_zehut
and   m2.seq_prisha   = m1.seq_prisha
and   m2.code_sug_bakasha in (1,3,5)) s_zakaut
from m m1
) sel
left join m m3 on
m3.seq_bakasha = case when sel.s_sachar is not null then sel.s_sachar else sel.s_zakaut end
left join m m4 on
m4.seq_bakasha = case when sel.s_zakaut is not null then sel.s_zakaut end
left join m m5 on
m5.seq_bakasha = case when sel.s_sachar is not null then sel.s_sachar end
left join v_bakasha_last_status vm5 on vm5.seq_bakasha = f_get_seq_bakasha_zakaut(m3.gimla_number,'poresh')
left join netuney_tik_mechushavim nm5 on nm5.seq_bakasha = vm5.seq_bakasha
                                     and nm5.code_department = 2
                                     and nvl(nm5.mispar_misra,0) = nvl(m5.misra_sachar,0)
left join code_group_prisha cg5 on cg5.code_group_prisha = nm5.code_group_prisha
left join bakasha_regila br5 on br5.seq_bakasha = vm5.seq_bakasha and br5.chinuch_mikzoa = 911
left join hagdala_nimuk h5 on h5.seq_bakasha = vm5.seq_bakasha
left join code_hagdala_nimuk ch5 on ch5.code_nimuk = h5.code_nimuk
left join v_bakasha_last_status vm4 on vm4.seq_bakasha = f_get_seq_bakasha_sachar(m3.gimla_number)
left join netuney_sachar ns4 on ns4.seq_bakasha = vm4.seq_bakasha
                            and nvl(ns4.mispar_misra,0) = nvl(m4.misra_zakaut,0)
                            and ns4.code_sug_maskoret = 1
                            --and vm4.seq_ezor_ovdim <> 206
left join netuney_sachar ns4_60 on ns4_60.seq_bakasha = vm4.seq_bakasha
                            and nvl(ns4_60.mispar_misra,0) = nvl(m4.misra_zakaut,0)
                            and ns4_60.code_sug_maskoret = 2
                            --and vm4.seq_ezor_ovdim <> 206
left join code_derug cd4    on cd4.code_derug = ns4.code_derug
where (m3.code_sug_bakasha <> 1 or (m3.code_sug_bakasha = 1 and nvl(m4.misra_zakaut,0) = nvl(m5.misra_sachar,0)) )
and not(m5.code_sug_bakasha in(1,14) and m5.maskoret_kovaat is null and m3.seq_ezor_ovdim = 206)
--and m3.seq_ezor_ovdim <> 206
)
order by 2;



end;

----------------------------------------------------------------------------------------

  procedure doch_bakarat_pizuim(p_from_date date,
                      p_to_date   date default null,
                      cur         out sys_refcursor) is
  begin
    open cur for
select distinct sel2.*,
case when br.chinuch_mikzoa = 911 then 'גננת' else null end is_ganenet,
case when cd.teur_derug like '%רופאים%' then 'רופא' else null end is_rofe,
case when sel2.havraa_days = 15 then 'עובד בית חולים' else null end is_oved_beit_holim,
case when nvl(br.chinuch_mikzoa,0) <> 911 and cd.teur_derug not like '%רופאים%' and nvl(sel2.havraa_days,0) <> 15 then 'כל השאר' else null end the_rest
from  (with m as
(select distinct cb.code_sug_bakasha, cb.code_teur_bakasha teur_bakasha, v.seq_bakasha, v.mispar_zehut, v.seq_prisha, p.shem_prati || ' ' || p.shem_mishpacha shem,
/*p.taarich_leda,*/ c.teur_ezor_ovdim, v.taarich_prisha,
        nm.tkufa_mezaka_sherut, nm.chelkiyut_sofit,
        nm.chelkiyut_meshuklelet_sherut,
        np.maskoret_kovaat maskoret_le_pizuim, nvl(nm.odef_sherut_chodashim,0) odef_sherut_chodashim, nvl(nm.odef_sherut_yamim,0) odef_sherut_yamim,
        /*nm.achuz_kizba_sofi, */ n.havraa_days, n.sum_havraa, n.ramat_bigud, n.sum_bigud, /*,v.code_seif_prisha,
        , cg.teur_group_prisha, */
        --,n.code_sug_maskoret
        --np.mispar_misra misra_sachar,
        nm.mispar_misra misra_zakaut,
        n.mispar_misra misra_sachar,
        n.code_derug,
        v.seq_ezor_ovdim, v.gimla_number
from v_bakasha_last_status v
left join code_sug_bakasha cb on cb.code_sug_bakasha = v.code_sug_bakasha
left join poresh p           on p.mispar_zehut = v.mispar_zehut
left join code_ezor_ovdim c  on c.seq_ezor_ovdim = v.seq_ezor_ovdim
left join netuney_tik_mechushavim nm on nm.seq_bakasha = v.seq_bakasha
                            and nm.code_department = 2
left join code_group_prisha cg on cg.code_group_prisha = nm.code_group_prisha
left join netuney_sachar np  on np.seq_bakasha = v.seq_bakasha
                            and np.code_sug_maskoret = 14
left join netuney_sachar n   on n.seq_bakasha  = v.seq_bakasha
                            and n.code_sug_maskoret <> 14
left join chinuch_reforma cr on cr.seq_chinuch_reforma = n.seq_chinuch_reforma
                            and cr.seq_bakasha = v.seq_bakasha
left join code_sug_maskoret m on m.code_chinuch_alterntive = cr.code_chinuch_alterntive
where v.code_sug_bakasha in (1,3,5,14)
--and   v.taarich_prisha >= to_date('01/01/2023','dd/mm/yyyy')
and   (v.taarich_prisha <  last_day(p_from_date) or v.code_sug_bakasha = 14)
and   v.seq_ezor_ovdim  not in (
13,
155,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
10154,
10149
)
and exists
(select 1
from action_log a
where a.seq_bakasha = v.seq_bakasha
and to_char(a.date_action,'mm/yyyy') = to_char(p_from_date,'mm/yyyy')
and a.code_action = 136)
and exists
  (select 1
  from v_bakasha_last_status v_1
  left join netuney_tik_mechushavim n_1 on n_1.seq_bakasha = v_1.seq_bakasha
  and n_1.code_department = 2
  where v_1.seq_prisha = v.seq_prisha
  and v_1.code_sug_bakasha = 1
  and v_1.code_action in (98, 129, 130)
  --and n_1.odef_sherut_chodashim > 0 or n_1.odef_sherut_yamim > 0
  )
and  (np.code_sug_maskoret = 14
      and v.code_sug_bakasha in (1,14)
      or v.code_sug_bakasha in (3,5))

and v.code_action not in (17,100)
and v.seq_ezor_ovdim = 206
union
/*select distinct v.mispar_zehut, trim(p.shem_prati) || ' ' || trim(p.shem_mishpacha) shem, p.taarich_leda, v.taarich_prisha, c.teur_ezor_ovdim,
        nm.achuz_kizba_sofi, np.maskoret_kovaat, n.havraa_days, n.sum_havraa, n.ramat_bigud, n.sum_bigud, v.code_seif_prisha,
        nm.tkufa_mezaka_sherut, nm.chelkiyut_sofit, cg.teur_group_prisha, nm.odef_sherut_chodashim
*/
select distinct cb.code_sug_bakasha, cb.code_teur_bakasha sug_bakasha, v.seq_bakasha, v.mispar_zehut, v.seq_prisha, p.shem_prati || ' ' || p.shem_mishpacha shem, /*p.taarich_leda,*/ c.teur_ezor_ovdim, v.taarich_prisha,
        nm.tkufa_mezaka_sherut, nm.chelkiyut_sofit,
        nm.chelkiyut_meshuklelet_sherut,
        n.maskoret_kovaat maskoret_kovaat, nvl(nm.odef_sherut_chodashim,0) odef_sherut_chodashim, nvl(nm.odef_sherut_yamim,0) odef_sherut_yamim,
        /*nm.achuz_kizba_sofi, */ n.havraa_days, n.sum_havraa, n.ramat_bigud, n.sum_bigud, /*,v.code_seif_prisha,
        , cg.teur_group_prisha, */
        --,n.code_sug_maskoret
        --np.mispar_misra misra_sachar,
        nm.mispar_misra misra_zakaut,
        n.mispar_misra misra_sachar,
        n.code_derug,
        v.seq_ezor_ovdim, v.gimla_number
from v_bakasha_last_status v
left join code_sug_bakasha cb on cb.code_sug_bakasha = v.code_sug_bakasha
left join poresh p           on p.mispar_zehut = v.mispar_zehut
left join code_ezor_ovdim c  on c.seq_ezor_ovdim = v.seq_ezor_ovdim
left join netuney_tik_mechushavim nm on nm.seq_bakasha = v.seq_bakasha
                            and nm.code_department = 2
left join code_group_prisha cg on cg.code_group_prisha = nm.code_group_prisha
/*left join netuney_sachar np  on np.seq_bakasha = v.seq_bakasha
                            and np.code_sug_maskoret = 14*/
left join netuney_sachar n   on n.seq_bakasha  = v.seq_bakasha
                            and n.code_sug_maskoret <> 14
where v.code_sug_bakasha in (1,3,5,14)
and   (v.taarich_prisha <  last_day(p_from_date) or v.code_sug_bakasha = 14)
and   v.seq_ezor_ovdim  not in (
155,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
10154,
10149
)
and exists
(select 1
from action_log a
where a.seq_bakasha = v.seq_bakasha
and to_char(a.date_action,'mm/yyyy') = to_char(p_from_date,'mm/yyyy')
and a.code_action = 136)
and exists
  (select 1
  from v_bakasha_last_status v_1
  left join netuney_tik_mechushavim n_1 on n_1.seq_bakasha = v_1.seq_bakasha
  and n_1.code_department = 2
  where v_1.seq_prisha = v.seq_prisha
  and v_1.code_sug_bakasha = 1
  and v_1.code_action in (98, 129, 130)
  )
and v.code_sug_bakasha in (1,3,5,14)
and v.code_action not in (17,100)
and v.seq_ezor_ovdim <> 206
order by 2
)

select distinct
m3.teur_bakasha,
m3.mispar_zehut,
m3.shem,
m3.teur_ezor_ovdim,
case when m5.seq_bakasha is null then m4.taarich_prisha else vm5.taarich_prisha end taarich_prisha,
case when m5.seq_bakasha is null then m4.tkufa_mezaka_sherut else nm5.tkufa_mezaka_sherut end tkufa_mezaka_sherut,
case when m5.seq_bakasha is null then m4.chelkiyut_sofit else nm5.chelkiyut_sofit end chelkiyut_sofit,
case when m5.seq_bakasha is null then m4.chelkiyut_meshuklelet_sherut else nm5.chelkiyut_meshuklelet_sherut end chelkiyut_meshuklelet_sherut,
case when m5.seq_bakasha is null then
     case when vm4.seq_ezor_ovdim <> 206 then ns4.maskoret_kovaat else null end
     else
     case when m5.seq_ezor_ovdim <> 206 then m5.maskoret_le_pizuim else null end
     end maskoret_kovaat,
case when m5.seq_bakasha is  null then
     case when vm4.seq_ezor_ovdim = 206 then ns4.maskoret_kovaat else null end
     else
     case when m5.seq_ezor_ovdim = 206 then m5.maskoret_le_pizuim else null end
     end maskoret_le_pizuim_chinuch,
case when m5.seq_bakasha is null then
     round(nvl(m4.odef_sherut_chodashim,0) + nvl(m4.odef_sherut_yamim,0) / (30.44),2)
     else
     round(nvl(nm5.odef_sherut_chodashim,0)  + nvl(nm5.odef_sherut_yamim,0) / (30.44),2)
     end odef_sherut,
/*case when m5.seq_bakasha is null then
     round(nvl(m4.odef_sherut_chodashim,0),2)
     else
     round(nvl(nm5.odef_sherut_chodashim,0),2)
     end odef_sherut_chodashim,
case when m5.seq_bakasha is null then
     round(nvl(m4.odef_sherut_yamim,0),2)
     else
     round(nvl(nm5.odef_sherut_yamim,0),2)
     end odef_sherut_yamim,*/
case when m5.seq_bakasha is null then
     case when vm4.seq_ezor_ovdim <> 206 then ns4.havraa_days else null end
     else
     case when m5.seq_ezor_ovdim <> 206 then m5.havraa_days else null end
     end havraa_days,
case when m5.seq_bakasha is null then
     case when vm4.seq_ezor_ovdim <> 206 then ns4.sum_havraa else null end
     else
     case when m5.seq_ezor_ovdim <> 206 then m5.sum_havraa else null end
     end sum_havraa,
case when m5.seq_bakasha is null then
     case when vm4.seq_ezor_ovdim <> 206 then ns4.ramat_bigud else null end
     else
     case when m5.seq_ezor_ovdim <> 206 then m5.ramat_bigud else null end
     end ramat_bigud,
case when m5.seq_bakasha is null then
     case when vm4.seq_ezor_ovdim <> 206 then ns4.sum_bigud else null end
     else
     case when m5.seq_ezor_ovdim <> 206 then m5.sum_bigud else null end
     end sum_bigud,
nvl(m4.misra_zakaut,0) misra_zakaut,
nvl(m5.misra_sachar,0) misra_sachar,
case when m4.seq_bakasha is null then vm5.seq_bakasha else m4.seq_bakasha end seq_bakasha_z,
case when m5.seq_bakasha is null then vm4.seq_bakasha else m5.seq_bakasha end seq_bakasha_s,
case when m5.seq_bakasha is null then ns4.code_derug else m5.code_derug end code_derug
from
(select
m1.*,
(select max(m2.seq_bakasha)
from m m2
left join v_bakasha_last_zakaut z on m2.seq_bakasha = z.SEQ_BAKASHA
where m2.mispar_zehut = m1.mispar_zehut
and   m2.seq_prisha   = m1.seq_prisha
and   m2.code_sug_bakasha in (1,14)) s_sachar,
(select max(m2.seq_bakasha)
from m m2
where m2.mispar_zehut = m1.mispar_zehut
and   m2.seq_prisha   = m1.seq_prisha
and   m2.code_sug_bakasha in (1,3,5)) s_zakaut
from m m1
) sel
left join m m3 on
m3.seq_bakasha = case when sel.s_sachar is not null then sel.s_sachar else sel.s_zakaut end
left join m m4 on
m4.seq_bakasha = case when sel.s_zakaut is not null then sel.s_zakaut end
left join m m5 on
m5.seq_bakasha = case when sel.s_sachar is not null then sel.s_sachar end
left join v_bakasha_last_status vm5 on vm5.seq_bakasha = f_get_seq_bakasha_zakaut(m3.gimla_number,'poresh')
left join netuney_tik_mechushavim nm5 on nm5.seq_bakasha = vm5.seq_bakasha
                                     and nm5.code_department = 2
                                     and nm5.mispar_misra = m5.misra_sachar
left join v_bakasha_last_status vm4 on vm4.seq_bakasha = f_get_seq_bakasha_sachar(m3.gimla_number)
left join netuney_sachar ns4 on ns4.seq_bakasha = vm4.seq_bakasha
                            and ns4.mispar_misra = m4.misra_zakaut
                            and ns4.code_sug_maskoret =
                            case when m4.seq_ezor_ovdim = 206 then 14 else 1 end
where m3.code_sug_bakasha <> 1 or (m3.code_sug_bakasha = 1 and m4.misra_zakaut = m5.misra_sachar)

--where m4.misra_zakaut = m5.misra_sachar
order by 2
) sel2
left join bakasha_regila br on br.seq_bakasha = sel2.seq_bakasha_z and br.chinuch_mikzoa = 911
left join code_derug cd on cd.code_derug = sel2.code_derug
where sel2.odef_sherut > 0;

end;

----------------------------------------------------------------------------------------
  procedure doch_hisachon_pensioni(p_from_date date,
                      p_to_date   date default null,
                      cur         out sys_refcursor) is
  begin
    open cur for
    select distinct p.mispar_zehut, p.shem_prati, p.shem_mishpacha, v.seq_bakasha, z."SEQ_BAKASHA",
bm.mispar_zehut_ben_mishpacha mispar_zehut_ben_zug_garush, bm.shem_prati shem_prati_ben_zug_garush, bm.shem_mishpacha shem_mishpacha_ben_zug_garush,
c.teur_ezor_ovdim,
trunc(n.hp_date_start_zakaut) date_zakaut_ben_zug,
trunc(z.date_start_zakaut) date_zakaut_poresh,
case when nvl(b.hp_llo_hafchata,0) = 0 then 'עם הפחתה' else 'בלי הפחתה' end hafchata
from v_bakasha_last_status v
left join netuney_tik_mechushavim n on n.seq_bakasha = v.seq_bakasha
                                   and n.code_department = 2 
left join bakasha_regila b on b.seq_bakasha = v.seq_bakasha
left join poresh p on p.mispar_zehut = v.mispar_zehut
left join bney_mishpacha bm on bm.seq_porshim = p.porshim_seq
left join code_ezor_ovdim c on c.seq_ezor_ovdim = v.seq_ezor_ovdim
left join v_bakasha_last_zakaut z on z.seq_prisha = v.seq_prisha
left join v_bakasha_last_status v1 on v1.seq_prisha = v.seq_prisha                   
where v.code_sug_bakasha = 12
and z."CODE_SUG_BAKASHA" = 1
and (v1.code_sug_bakasha = 1 or v1.code_sug_bakasha = 5 and v.code_bakasha_detail = 25)
and v1.code_action <> 17
and (bm.code_kirva = 10 or bm.code_relative = 6)
and (to_char(n.hp_date_start_zakaut,'mm/yyyy') = to_char(p_from_date,'mm/yyyy') or
     to_char(z.date_start_zakaut,'mm/yyyy') = to_char(p_from_date,'mm/yyyy'))
and v.code_action not in (17)
and v.seq_ezor_ovdim <> 164;

  end;
----------------------------------------------------------------------------------------
  procedure doch_pniyot_hatavot(p_from_date date,
                      p_to_date   date default null,
                      cur         out sys_refcursor) is
  begin
    open cur for
    select t.request_name,
       t.person_id,
       to_date(replace(substr(t.created_date,1,10),'-','/'),'yyyy/mm/dd') created_date,
       trunc(t.ld_date) interface_date,
       t.file_url,
       t.description
from LD_REQUESTS_CRM_ERRORS t
where subject_code = '68'
and t.person_id <> '310967104'
--and to_char(ld_date,'mm/yyyy') = to_char(p_from_date,'mm/yyyy')
and trunc(t.ld_date) >= trunc(p_from_date)
order by to_number(substr(t.request_name,3));

end;
----------------------------------------------------------------------------------------
   procedure doch_bakashot_mashpiot_al_hakesef_test1_test2(
                      p_from_date date default null,
                      p_to_date   date default null,
                      cur         out sys_refcursor) is
  begin
    open cur for                      
select distinct t.mispar_zehut, t.seq_bakasha, t.mispar_gimla, v.teur_action, c.code_teur_bakasha teur_bakasha,
t.seq_ld_protocol_hilan mispar_mimshak,
case when v.code_sug_bakasha = 19 then trunc(from_date) else null end from_date,
case when v.code_sug_bakasha = 19 then c.teur_bakasha_detail else null end teur_sug_hafsaka
from ld_log_events t
left join date_close_report d on to_char(d.date_close_test1,'yyyy/mm') = to_char(sysdate,'yyyy/mm')
left join v_bakasha_last_status v on v.seq_bakasha = t.seq_bakasha
left join code_sug_bakasha c on c.code_sug_bakasha = v.code_sug_bakasha
left join bakasha b on b.seq_bakasha = v.seq_bakasha
left join code_bakasha_detail c on c.code_sug_bakasha = v.code_sug_bakasha
                               and c.code_bakasha_detail = v.code_bakasha_detail
where t.date_create > d.date_close_test1
and t.date_create < trunc(d.date_close_test2) + 1
and t.code_event > 0
and t.code_event <> 218
and v.code_sug_bakasha not in (33,15,26)
and t.mispar_zehut <> 0
and exists
(select 1
from ld_log_events l
where l.seq_ld_protocol_hilan = t.seq_ld_protocol_hilan
and l.code_recode_level_message is not null)
order by t.mispar_zehut;
end;
   
----------------------------------------------------------------------------------------
   
   procedure doch_bakashot_mashpiot_al_hakesef_test2_ibud_amiti(
                      p_from_date date default null,
                      p_to_date   date default null,
                      cur         out sys_refcursor) is
  begin
    open cur for                      
select distinct t.mispar_zehut, t.seq_bakasha, t.mispar_gimla, v.teur_action, c.code_teur_bakasha teur_bakasha,
t.seq_ld_protocol_hilan mispar_mimshak,
case when v.code_sug_bakasha = 19 then trunc(from_date) else null end from_date,
case when v.code_sug_bakasha = 19 then c.teur_bakasha_detail else null end teur_sug_hafsaka
from ld_log_events t
left join date_close_report d on to_char(d.date_close_test1,'yyyy/mm') = to_char(sysdate,'yyyy/mm')
left join v_bakasha_last_status v on v.seq_bakasha = t.seq_bakasha
left join code_sug_bakasha c on c.code_sug_bakasha = v.code_sug_bakasha
left join bakasha b on b.seq_bakasha = v.seq_bakasha
left join code_bakasha_detail c on c.code_sug_bakasha = v.code_sug_bakasha
                               and c.code_bakasha_detail = v.code_bakasha_detail
where t.date_create > d.date_close_test2
and t.date_create < trunc(d.date_close_chodesh) + 1
and t.code_event > 0
and t.code_event <> 218
and v.code_sug_bakasha not in (33,15,26)
and t.mispar_zehut <> 0
and exists
(select 1
from ld_log_events l
where l.seq_ld_protocol_hilan = t.seq_ld_protocol_hilan
and l.code_recode_level_message is not null)
order by t.mispar_zehut;
end;
   
----------------------------------------------------------------------------------------
end PK_Reports1;
/

create or replace package body prm_system_copy.pk_run_mimshak is
  ------------------------------------------------------------------------------------------------  
  -- Check_last_time_of_this_process 
  procedure Check_status_process(p_seq_ld_protocol number) is
    Ld_Protocol_row        Ld_Protocol%rowtype;
    mail_recipient         varchar2(250) := '';
    process_failed_title   varchar2(250);
    process_failed_details varchar2(2000);
    v_db_name              varchar2(50);
  begin
    begin
    
      --Get the last time of this process
      select *
        into Ld_Protocol_row
        from ld_protocol t1
       where t1.seq_ld_protocol = p_seq_ld_protocol;
    
      v_db_name := sys_context('userenv', 'DB_NAME');
      if Ld_Protocol_row.Status = 0 and v_db_name = 'xt1' then
      
        process_failed_title := 'Process ' || Ld_Protocol_row.Code_Process ||
                                ' - ' || Ld_Protocol_row.Code_Sub_Process ||
                                ' is Failed ' ||
                                to_char(ld_Protocol_row.Begin_Date,
                                        'dd_mm_yyyy_HH24_MI_SS');
      
        process_failed_details := process_failed_title || chr(10) ||
                                  chr(10) || Ld_Protocol_row.Message;
      
        --Get email_list from table
        select lp.email_list
          into mail_recipient
          from ld_process lp
         where lp.code_process = Ld_Protocol_row.Code_Process
           and lp.code_sub_process = Ld_Protocol_row.Code_Sub_Process;
      
        if mail_recipient is null then
          if Ld_Protocol_row.code_process = 8 then
            mail_recipient := 'liba@mof.gov.il,yaffag@mof.gov.il';
          else
            mail_recipient :=  --'zehavas@mof.gov.il,bakarat_manof@mof.gov.il,hanafr@mof.gov.il';
             'bakarat_manof@mof.gov.il,hanafr@mof.gov.il,yaffag@mof.gov.il';
          end if;
        
          pk_prm_utils.send_attach(mail_recipient,
                                   process_failed_title,
                                   null,
                                   process_failed_details,
                                   'txt',
                                   process_failed_title || '.txt');
        end if;
      end if;
    exception
      when others then
        --todo: add other way to send message when error.
        return;
    end;
  end;
  ------------------------------------------------------------------------------------------------
  function Insert_ld_protocol(v_code_process     number,
                              v_code_sub_process number,
                              v_begin_date       date,
                              v_source_file_name varchar2,
                              v_is_ibolt         number) return number is
    v_seq_ld_protocol number := ld_protocol_seq.nextval;
  begin
  
    insert into ld_protocol
      (seq_ld_protocol,
       code_process,
       code_sub_process,
       begin_date,
       source_file_name,
       is_ibolt)
    values
      (v_seq_ld_protocol,
       v_code_process,
       v_code_sub_process,
       v_begin_date,
       v_source_file_name,
       v_is_ibolt);
    commit;
    return v_seq_ld_protocol;
  end;
  ------------------------------------------------------------------------------------------------
  procedure update_ld_protocol(v_end_date         date,
                               v_status           number,
                               v_message          varchar2,
                               v_count_success    number,
                               v_count_errors     number,
                               v_file_log         clob,
                               v_merkava_maatefet clob,
                               v_seq_ld_protocol  number) is
  begin
    update ld_protocol
       set end_date            = v_end_date,
           status              = v_status,
           message             = v_message,
           count_success_tikim = v_count_success,
           count_errors_tikim  = v_count_errors,
           ld_result           = v_file_log,
           merkava_maatefet    = v_merkava_maatefet
     where seq_ld_protocol = v_seq_ld_protocol;
  
    commit;
  
    Check_status_process(v_seq_ld_protocol);
  end;

  --------------------------------------------------------------------
  procedure send_interface_to_malam_1_3(malam_file_name out varchar2,
                                        file_malam      out clob,
                                        is_ibolt        in number) is
    status            number := 1;
    message           varchar2(250) := null;
    v_seq_ld_protocol number;
  begin
    v_seq_ld_protocol := Insert_ld_protocol(1, 3, sysdate, null, is_ibolt);
    begin
      --create file
      file_malam := pk_create_mimshak_out.create_mimshak_malam;
      --Check if file_malam is not empty.  
      if length(file_malam) is not null then
        -- Set malam file name
        malam_file_name := 'nzv_mlm_' ||
                           lpad(mimshak_mlm_seq.nextval, 6, '0') || '.txt';
      
      end if;
      --Update versions for all tikim to the orginal positive version.
      --(Part of them updated to negetive version in process 1-1)
      update bakasha_regila tikim
         set tikim.seq_bakasha = tikim.seq_bakasha * (-1)
       where tikim.seq_bakasha < 0;
      commit;
    exception
      when others then
        status  := 0;
        message := sqlerrm;
    end;
    update_ld_protocol(sysdate,
                       status,
                       message,
                       null,
                       null,
                       file_malam,
                       null,
                       v_seq_ld_protocol);
  end;
  --------------------------------------------------------------------
  procedure send_interface_to_merkava_1_2(merkava_file_name     out varchar2,
                                          maatefet_file_name    out varchar2,
                                          file_merkava          out clob,
                                          file_maatefet_merkava out clob,
                                          is_ibolt              in number) is
    status            number := 1;
    message           varchar2(250) := null;
    v_seq_ld_protocol number;
  begin
    v_seq_ld_protocol := Insert_ld_protocol(1, 2, sysdate, null, is_ibolt);
    begin
      -- Create file
      file_merkava := pk_create_mimshak_out.create_ishur_mgl_merkava;
      --Check if merkava file is not empty.
      if length(file_merkava) is not null then
        -- Create maatefet
        file_maatefet_merkava := pk_create_maatefet_merkava.create_maatefet(3,
                                                                            merkava_file_name,
                                                                            sysdate,
                                                                            null,
                                                                            maatefet_file_name);
      end if;
    exception
      when others then
        status  := 0;
        message := sqlerrm;
    end;
    update_ld_protocol(sysdate,
                       status,
                       message,
                       null,
                       null,
                       file_merkava,
                       file_maatefet_merkava,
                       v_seq_ld_protocol);
  end;
  --------------------------------------------------------------------
  procedure update_5_fields_1_1(is_ibolt in number) is
    status            number := 1;
    message           varchar2(250) := null;
    count_success     number := 0;
    count_errores     number := 0;
    log_errores       clob;
    mail_recipient    varchar2(250) := 'bakarat_manof@mof.gov.il'; --'sharong@mof.gov.il';
    v_seq_ld_protocol number;
  begin
    v_seq_ld_protocol := Insert_ld_protocol(1, 1, sysdate, null, is_ibolt);
    begin
      log_errores := pk_load_magal.Updae_5_fields(count_success,
                                                  count_errores);
      --errores
      if count_errores > 0 then
        --Send in mail
        pk_prm_utils.send_attach(mail_recipient,
                                 'Errores during Updating 5 fields from mgl',
                                 '',
                                 log_errores,
                                 'txt',
                                 'mgl_log_' ||
                                 to_char(sysdate, 'dd_mm_yyyy') || '.txt');
      end if;
    exception
      when others then
        status  := 0;
        message := sqlerrm;
    end;
    update_ld_protocol(sysdate,
                       status,
                       message,
                       count_success,
                       count_errores,
                       log_errores,
                       null,
                       v_seq_ld_protocol);
  end;
  --------------------------------------------------------------------
  procedure magal_confirm_1_0(merkava_file_name     out varchar2,
                              maatefet_file_name    out varchar2,
                              file_merkava          out clob,
                              file_maatefet_merkava out clob,
                              malam_file_name       out varchar2,
                              file_malam            out clob,
                              is_ibolt              in number) is
    status            number := 1;
    message           varchar2(250) := null;
    v_seq_ld_protocol number;
  begin
    v_seq_ld_protocol := Insert_ld_protocol(1, 0, sysdate, null, is_ibolt);
    begin
      --processes
    
      send_interface_to_merkava_1_2(merkava_file_name,
                                    maatefet_file_name,
                                    file_merkava,
                                    file_maatefet_merkava,
                                    is_ibolt);
      send_interface_to_malam_1_3(malam_file_name, file_malam, is_ibolt);
    
    exception
      when others then
        status  := 0;
        message := sqlerrm;
    end;
    update_ld_protocol(sysdate,
                       status,
                       message,
                       null,
                       null,
                       null,
                       null,
                       v_seq_ld_protocol);
  end;
  --------------------------------------------------------------------
  function send_file_log_2_3(is_ibolt       in number,
                             count_success  out number,
                             count_warnings out number,
                             count_errors   out number,
                             p_log          out clob) return clob is
    status  number := 1;
    message varchar2(250) := null;
  
    v_seq_ld_protocol       number;
    v_file_log_html         clob;
    v_html_body_only_errors clob;
  begin
    v_seq_ld_protocol := Insert_ld_protocol(2, 3, sysdate, null, is_ibolt);
    begin
      --Get file log
      v_file_log_html := pk_load.End_process(v_seq_ld_protocol,
                                             count_success,
                                             count_warnings,
                                             count_errors,
                                             p_log,
                                             v_html_body_only_errors);
    
    exception
      when others then
        status  := 0;
        message := sqlerrm;
    end;
    update_ld_protocol(sysdate,
                       status,
                       message,
                       count_success,
                       count_errors,
                       v_file_log_html,
                       null,
                       v_seq_ld_protocol);
    return v_file_log_html;
  end;
  --------------------------------------------------------------------
  procedure load_interface_2_1(chinuch_recived_file_name varchar2,
                               is_ibolt                  in number,
                               p_is_electronic           number) is
    status            number := 1;
    message           varchar2(250) := null;
    v_seq_ld_protocol number;
  begin
    v_seq_ld_protocol := Insert_ld_protocol(2,
                                            1,
                                            sysdate,
                                            chinuch_recived_file_name,
                                            is_ibolt);
    begin
      pk_chinuch.Loop_Over_All_Tikim(v_seq_ld_protocol);
    exception
      when others then
        status  := 0;
        message := sqlerrm;
    end;
    update_ld_protocol(sysdate,
                       status,
                       message,
                       null,
                       null,
                       null,
                       null,
                       v_seq_ld_protocol);
  end;
  --------------------------------------------------------------------
  procedure Insert_Documents_2_5(p_mimshak_number number,
                                 is_ibolt         in number) is
    status            number := 1;
    message           varchar2(250) := null;
    v_seq_ld_protocol number;
    v_count_success   number;
    v_count_errors    number;
  
  begin
    v_seq_ld_protocol := Insert_ld_protocol(2, 5, sysdate, null, is_ibolt);
  
    --Check missing
    pk_load.Check_missing_document;
  
    --Get count success
    select count(*)
      into v_count_success
      from ld_add_document_electronic t
     where t.mimshak_number = p_mimshak_number
       and t.is_success = 1;
  
    --Get count errors
    select count(*)
      into v_count_errors
      from ld_add_document_electronic t
     where t.mimshak_number = p_mimshak_number
       and t.is_success = 0;
  
    update_ld_protocol(sysdate,
                       status,
                       message,
                       v_count_success,
                       v_count_errors,
                       null,
                       null,
                       v_seq_ld_protocol);
  
  end;
  --------------------------------------------------------------------
  procedure chinuch_2_0_a(chinuch_recived_file_name varchar2,
                          is_ibolt                  in number,
                          mimshak_number            number,
                          is_check_mimshak_number   number default 1) is
    status                number := 1;
    message               varchar2(250) := null;
    v_seq_ld_protocol     number;
    v_prev_mimshak_number number;
  begin
    v_seq_ld_protocol := Insert_ld_protocol(2, 0, sysdate, null, is_ibolt);
  
    /* select nvl(max(l.source_mimshak_number), 0)
     into v_prev_mimshak_number
     from ld_protocol l
    where l.code_process = 2
      and l.code_sub_process = 0;*/
  
    /*if is_check_mimshak_number = 1 and
       v_prev_mimshak_number + 1 <> mimshak_number then
      RAISE_APPLICATION_ERROR(-20000,
                              'mimshak number (' || to_char(mimshak_number) ||
                              ') is not serial - not equal the previous number(' ||
                              to_char(v_prev_mimshak_number) || ') + 1');
    end if;*/
  
    --update source_mimshak_number
    update ld_protocol l
       set l.source_mimshak_number = mimshak_number
     where l.seq_ld_protocol = v_seq_ld_protocol;
    commit;
  
    -- processes
    load_interface_2_1(chinuch_recived_file_name, is_ibolt, 1);
  
  exception
    when others then
      status  := 0;
      message := sqlerrm;
    
      update_ld_protocol(sysdate,
                         status,
                         message,
                         null,
                         null,
                         null,
                         null,
                         v_seq_ld_protocol);
  end;

  --------------------------------------------------------------------
  procedure chinuch_2_0_b(p_mimshak_number number,
                          is_ibolt         number,
                          p_html_log       out clob,
                          count_success    out number,
                          count_warnings   out number,
                          count_errors     out number,
                          p_log            out clob) is
    status            number := 1;
    message           varchar2(250) := null;
    v_seq_ld_protocol number;
  begin
    select max(l.seq_ld_protocol)
      into v_seq_ld_protocol
      from ld_protocol l
     where l.code_process = 2
       and l.code_sub_process = 0
       and trunc(l.begin_date) = trunc(sysdate)
       and l.end_date is null;
    begin
      select t.message
        into message
        from ld_protocol t
       where t.seq_ld_protocol = v_seq_ld_protocol;
    
      if message is not null then
        p_html_log := message;
        return;
      end if;
    
      --processes
      Insert_Documents_2_5(p_mimshak_number, is_ibolt);
      p_html_log := send_file_log_2_3(is_ibolt,
                                      count_success,
                                      count_warnings,
                                      count_errors,
                                      p_log);
    exception
      when others then
        status  := 0;
        message := sqlerrm;
    end;
    update_ld_protocol(sysdate,
                       status,
                       message,
                       null,
                       null,
                       null,
                       null,
                       v_seq_ld_protocol);
  end;

