  --------------------------------------------------------------------

  procedure load_interface_4_1(merkava_log_file_name     out varchar2,
                               merkava_recived_file_name varchar2,
                               maatefet_file_name        out varchar2,
                               file_merkava              out clob,
                               file_maatefet_merkava     out clob,
                               is_ibolt                  in number) is
    status            number := 1;
    message           varchar2(250) := null;
    count_success     number := 0;
    count_errors      number := 0;
    v_seq_ld_protocol number;
    mail_recipient constant varchar2(250) := 'mirid@mof.gov.il,bakarat_manof@mof.gov.il,tovat@mof.gov.il,yaffag@mof.gov.il';
  begin
    v_seq_ld_protocol := Insert_ld_protocol(4,
                                            1,
                                            sysdate,
                                            merkava_recived_file_name,
                                            is_ibolt);
    begin
    
      --Check if the numerator in merkava_recived_file_name is equal to the seq 'mimshak_merkava_log_seq'.
      --Exp name of merkava_recived_file_name: MRK_EMPDATA8.csv
    
      --todo!!! ask igal , currval is not available.
      if 1 = 1
      /*(mimshak_merkava_log_seq.currval + 1 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    = to_number(regexp_substr(merkava_recived_file_name,'\d+',1,1)))*/
       then
        -- Create file
        file_merkava := pk_load_merkava.loop_over_all_tikim(count_success,
                                                            count_errors);
      
      else
        file_merkava := 'The numerator (from the file name) is not equal to the previous numerator + 1';
      
      end if;
    
      -- Create maatefet file
      file_maatefet_merkava := pk_create_maatefet_merkava.create_maatefet(1,
                                                                          merkava_log_file_name,
                                                                          sysdate,
                                                                          merkava_recived_file_name,
                                                                          maatefet_file_name);
    
      --Send in mail
      pk_prm_utils.send_attach(mail_recipient,
                               'There were ' || case count_errors when 0 then 'no' else
                               to_char(count_errors)
                               end ||
                               ' errors during the loading of the ''merkava'' interface of  ' ||
                               to_char(sysdate, 'dd/mm/yyyy'),
                               'please take care of it urgently: ',
                               file_merkava,
                               'html',
                               'report_' || to_char(sysdate, 'dd_mm_yyyy') ||
                               '.html');
    
    exception
      when others then
        status  := 0;
        message := sqlerrm;
    end;
    update_ld_protocol(sysdate,
                       status,
                       message,
                       count_success,
                       count_errors,
                       file_merkava,
                       file_maatefet_merkava,
                       v_seq_ld_protocol);
  end;
