  --------------------------------------------------------------------
  procedure run_expirieds_5_5(is_ibolt in number) is
    status                         number := 1;
    message                        varchar2(250) := null;
    v_seq_ld_protocol              number;
    v_Life_certificate_stop        varchar2(1000) := 'Include Life certificate stop';
    v_cnt_Life_certificate_stop    number;
    v_is_run_Life_certificate_stop number := 0;
  begin
    v_seq_ld_protocol := Insert_ld_protocol(5, 5, sysdate, null, is_ibolt);
    begin
    
      if to_char(sysdate, 'dd') > 19 then
        select count(*)
          into v_cnt_Life_certificate_stop
          from ld_protocol l
         where l.code_process = 5
           and l.code_sub_process = 5
           and trunc(l.begin_date, 'MONTH') = trunc(sysdate, 'MONTH')
           and l.message = v_Life_certificate_stop;
      
        if v_cnt_Life_certificate_stop = 0 then
          v_is_run_Life_certificate_stop := 1;
        end if;
      end if;
    
      pk_expiried.run_expirieds(v_is_run_Life_certificate_stop);
    
    exception
      when others then
        status  := 0;
        message := sqlerrm;
    end;
    update_ld_protocol(sysdate,
                       status,
                       message,
                       null,
                       null,
                       null,
                       null,
                       v_seq_ld_protocol);
  end;
