  --------------------------------------------------------------------
  procedure Daily_processes_5_0(header_file_name  out varchar2,
                                content_file_name out varchar2,
                                header_file       out clob,
                                content_file      out clob,
                                is_ibolt          in number) is
    status            number := 1;
    message           varchar2(250) := null;
    count_success     number := 0;
    v_seq_ld_protocol number;
  begin
    v_seq_ld_protocol := Insert_ld_protocol(5, 0, sysdate, null, is_ibolt);
    begin
      --Send interface to interior
      send_interface_to_interior_5_1(header_file_name,
                                     content_file_name,
                                     header_file,
                                     content_file,
                                     is_ibolt);
      --Add action after 30 days
      add_action_after_30_days_5_3(is_ibolt);
    
      --Add action before 3 months of date start zakaut
      add_action_Retirement_age_5_4(is_ibolt);
    
      --run expirieds
      run_expirieds_5_5(is_ibolt);
    exception
      when others then
        status  := 0;
        message := sqlerrm;
    end;
    update_ld_protocol(sysdate,
                       status,
                       message,
                       null,
                       null,
                       content_file,
                       header_file,
                       v_seq_ld_protocol);
  end;
  --------------------------------------------------------------------
  procedure send_interface_to_interior_5_1(header_file_name  out varchar2,
                                           content_file_name out varchar2,
                                           header_file       out clob,
                                           content_file      out clob,
                                           is_ibolt          in number) is
    status                       number := 1;
    message                      varchar2(250) := null;
    v_seq_ld_protocol            number;
    v_was_send_all_persons_month number := 0;
    v_is_all_persons             number := 0;
    v_is_payment_in_advance      number := 0;
  
    v_count_rows number;
  begin
    if to_char(sysdate, 'd') in (6, 7) then
      return;
    end if;
  
    if to_char(sysdate, 'dd') > 22 then
      v_is_payment_in_advance := 1;
      message                 := 'include payment in advance';
    end if;
  
    if to_char(sysdate, 'd') = 5 then
      v_is_all_persons := 1;
      message          := 'include all';
    end if;
  
    v_seq_ld_protocol := Insert_ld_protocol(5, 1, sysdate, null, is_ibolt);
    begin
      --Get files name
      header_file_name  := pk_interior.get_header_file_name;
      content_file_name := pk_interior.get_content_file_name;
      -- Create files
      header_file  := pk_interior.create_header_output;
      content_file := pk_interior.create_content_output(v_is_all_persons,
                                                        v_is_payment_in_advance,
                                                        v_count_rows);
    exception
      when others then
        status  := 0;
        message := sqlerrm;
    end;
    update_ld_protocol(sysdate,
                       status,
                       message,
                       v_count_rows,
                       null,
                       null,
                       null,
                       v_seq_ld_protocol);
  end;
