  procedure send_interface_to_hilan_8_1(v_hilan_file_name out varchar2,
                                        hilan_clob        out clob,
                                        is_ibolt          number) is
    --status                  number := 1;
    message                     varchar2(250) := null;
    count_success               number := 0;
    v_seq_ld_protocol           number;
    v_seq_ld_protocol_hilan     number;
    v_source_mimshak_number_out number;
    v_seq_ld_protocol_in        number;
    v_must_send                 boolean := true;
    v_tikim_number              number;
    v_status                    number;
  begin
    v_status := 1;
    select sys_context('userenv', 'os_user') into message from dual;
    if instr(message, 'ontrol', 1) > 0 then
      begin
        select t.source_mimshak_number
          into v_source_mimshak_number_out --מספר של קובץ הממשק האחרון שיצא
          from ld_protocol t
         where t.code_process = 8
           and t.code_sub_process = 1
           and t.status = 1
           and instr(t.message, 'ontrol', 1) > 0
           and t.seq_ld_protocol =
               (select max(p.seq_ld_protocol)
                  from ld_protocol p
                 where p.code_process = 8
                   and p.code_sub_process = 1
                   and p.status = 1
                   and instr(p.message, 'ontrol', 1) > 0);
      
        begin
          select max(t.seq_ld_protocol)
            into v_seq_ld_protocol_in
            from ld_protocol t
           where t.code_process = 8
             and t.code_sub_process = 2
             and t.source_mimshak_number = v_source_mimshak_number_out;
          if v_seq_ld_protocol_in is null /* and instr(message,'controlm')>0*/
           then
            v_status    := 0;
            v_must_send := false;
            pk_hilan_prd.run_hilan_out(null,
                                       null,
                                       hilan_clob,
                                       v_must_send,
                                       v_tikim_number);
            return;
          end if;
        end;
      end;
    end if;
  
    begin
      --     if v_must_send then     
      v_seq_ld_protocol       := insert_ld_protocol(8,
                                                    1,
                                                    sysdate,
                                                    null,
                                                    is_ibolt);
      v_seq_ld_protocol_hilan := ld_protocol_hilan_seq.nextval;
    
      select sys_context('userenv', 'os_user') into message from dual;
      -- get file name
      v_hilan_file_name := pk_hilan_prd.get_hilan_file_name(v_seq_ld_protocol,
                                                            v_seq_ld_protocol_hilan);
      -- create file
      pk_hilan_prd.run_hilan_out(v_seq_ld_protocol,
                                 v_seq_ld_protocol_hilan,
                                 hilan_clob,
                                 v_must_send,
                                 v_tikim_number);
    exception
      when others then
        v_status := 0;
        message  := trim(message) || ' - ' || sqlerrm;
    end;
    if v_tikim_number = 0 then
      v_status := 0;
      message  := trim(message) || ' - ' || 'אין תיקים תקינים להעברה';
    end if;
  
    update_ld_protocol(sysdate,
                       v_status,
                       message,
                       null,
                       null,
                       v_hilan_file_name,
                       null,
                       v_seq_ld_protocol);
  
    update ld_protocol t
       set t.source_mimshak_number = v_seq_ld_protocol_hilan
     where t.seq_ld_protocol = v_seq_ld_protocol;
    commit;
  end;

  --------------------------------------------------------------------
  procedure get_interface_frm_hilan_8_2(hilan_recived_file_name varchar2,
                                        is_ibolt                in number) is
    message                 varchar2(250) := null;
    status                  number;
    v_seq_ld_protocol       number;
    count_success           number := 0;
    count_errors            number := 0;
    v_seq_ld_protocol_hilan number;
  begin
    v_seq_ld_protocol := insert_ld_protocol(8,
                                            2,
                                            sysdate,
                                            hilan_recived_file_name,
                                            is_ibolt);
    begin
      status := 1;
      select sys_context('userenv', 'os_user') into message from dual;
      v_seq_ld_protocol_hilan := pk_hilan_prd.run_hilan_in;
    exception
      when others then
        status  := 0;
        message := trim(message) || ' - ' || sqlerrm;
    end;
    update_ld_protocol(sysdate,
                       status,
                       message,
                       null,
                       null,
                       null,
                       null,
                       v_seq_ld_protocol);
    if v_seq_ld_protocol_hilan > 0 then
      update ld_protocol t
         set t.source_mimshak_number = v_seq_ld_protocol_hilan
       where t.seq_ld_protocol = v_seq_ld_protocol;
    end if;
    commit;
  end;
