  --------------------------------------------------------------------
  function get_details_for_Process(p_code_process     number,
                                   p_code_sub_process number) return varchar2 is
    v_is_exist_row varchar2(1) := 'N';
    v_status       varchar2(1);
    v_message      varchar2(250);
  begin
    -- Check if exist row in the ld_protocol table,
    -- that reference to the specific process.  
  
    --todo: get the last process.
    select case
             when count(*) > 0 then
              'Y'
             else
              'N'
           end
      into v_is_exist_row
      from ld_protocol t
     where trunc(t.begin_date) = trunc(sysdate - 1)
       and t.code_process = p_code_process
       and t.code_sub_process = p_code_sub_process;
  
    if v_is_exist_row = 'N' then
      --If it is no exist row, return 'Not activated'.
      return 'Not activated';
    end if;
  
    select t.status, t.message
      into v_status, v_message
      from ld_protocol t
     where trunc(t.begin_date) = trunc(sysdate)
       and t.code_process = p_code_process
       and t.code_sub_process = p_code_sub_process;
  
    if v_status = 1 then
      return '<font color= green >Successed</font>';
    elsif v_status = 0 then
      return '<font color= red >failed: ' || v_message || '</font>';
    end if;
  end;
  --------------------------------------------------------------------  
  procedure summary_processes_today is
    report         clob;
    result_process varchar2(260);
    mail_recipient constant varchar2(250) := ''; --'hanafr@mof.gov.il';
  begin
    report := '<html><body>
<h1>Summary - prisha processes - ' ||
              to_char(sysdate, 'dd/mm/yyyy') || ':<h1/>';
  
    result_process := get_details_for_Process(1, 0);
    report         := report || '<h2><b>Magal confirm process: ' ||
                      result_process || '<b/> <h2/>';
    if result_process <> 'Not activated' then
      report := report || '<h3>Update five fields process: ' ||
                get_details_for_Process(1, 1) || '<h3/>';
      report := report || '<h3>Send Interface to merkava process: ' ||
                get_details_for_Process(1, 2) || '<h3/>';
      report := report || '<h3>Send interface to malam process: ' ||
                get_details_for_Process(1, 3) || '<h3/>';
    end if;
  
    result_process := get_details_for_Process(2, 0);
    report         := report || '<h2><b>Chinuch process: ' ||
                      result_process || '<b/> <h2/>';
    if result_process <> 'Not activated' then
      report := report || '<h3>Load interface process: ' ||
                get_details_for_Process(2, 1) || '<h3/>';
      report := report || '<h3>Logist process: ' ||
                get_details_for_Process(2, 2) || '<h3/>';
      report := report || '<h3>Send file log process: ' ||
                get_details_for_Process(2, 3) || '<h3/>';
    end if;
  
    result_process := get_details_for_Process(3, 0);
    report         := report || '<h2><b>Nasham confirm process: ' ||
                      result_process || '<b/> <h2/>';
    if result_process <> 'Not activated' then
      report := report || '<h3>send interface to merkava process: ' ||
                get_details_for_Process(3, 1) || '<h3/>';
      report := report || '<h3>send interface to magal process: ' ||
                get_details_for_Process(3, 2) || '<h3/>';
    end if;
  
    result_process := get_details_for_Process(4, 0);
    report         := report || '<h2><b>Merkava process: ' ||
                      result_process || '<b/> <h2/>';
    if result_process <> 'Not activated' then
      report := report || '<h3>Load interface process: ' ||
                get_details_for_Process(4, 1) || '<h3/>';
      report := report || '<h3>Send file log process: ' ||
                get_details_for_Process(4, 2) || '<h3/>';
    end if;
  
    pk_prm_utils.send_attach(mail_recipient,
                             'summary - prisha processes today',
                             'summary: ',
                             report,
                             'html',
                             'report_' || to_char(sysdate, 'dd_mm_yyyy') ||
                             '.html');
  end;
  --------------------------------------------------------------------
end;
/

create or replace package body prm_system_copy.pk_salary_base is
  --------------------------------------------------------
  v_global_message varchar2(1000);
  --------------------------------------------------------
  procedure update_ld_salary_base(p_ld_protocol              number,
                                  p_seq_ld_mlm_salary        number,
                                  p_seq_ld_chinuch_salary_01 number,
                                  p_code_status              number,
                                  p_seq_bakasha              number default null,
                                  p_is_new_data              number default 1,
                                  p_direct_hilan             number default 0) is
    pragma autonomous_transaction;
  begin
  
    merge into ld_salary_base l
    using dual
    on ((p_seq_ld_chinuch_salary_01 is not null and l.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01) or (p_seq_ld_mlm_salary is not null and l.seq_ld_mlm_salary = p_seq_ld_mlm_salary))
    when matched then
      update
         set l.code_status_get = p_code_status,
             l.date_status_get = sysdate,
             l.seq_bakasha     = p_seq_bakasha,
             l.message         = v_global_message,
             l.seq_ld_protocol = p_ld_protocol,
             l.is_new_data     = p_is_new_data,
             l.is_direct_hilan = p_direct_hilan
    when not matched then
      insert
        (seq_ld_salary_base,
         seq_ld_mlm_salary,
         seq_ld_chinuch_salary_01,
         code_status_get,
         date_status_get,
         seq_bakasha,
         message,
         seq_ld_protocol,
         is_new_data,
         is_direct_hilan)
      values
        (ld_salary_base_seq.nextval,
         p_seq_ld_mlm_salary,
         p_seq_ld_chinuch_salary_01,
         p_code_status,
         sysdate,
         p_seq_bakasha,
         v_global_message,
         p_ld_protocol,
         p_is_new_data,
         p_direct_hilan);
  
    commit;
  end;
  --------------------------------------------------------

  procedure delete_netney_sachr_frm_bkasha(v_seq_bakasha_prev number) is
  begin
  
    delete from tosefot t26
     where t26.seq_netuney_sachar in
           (select t25.seq_netuney_sachar
              from netuney_sachar t25
             where t25.seq_bakasha = v_seq_bakasha_prev);
  
    delete from vetek_detail t31
     where t31.seq_netuney_sachar in
           (select p.seq_netuney_sachar
              from netuney_sachar p
             where p.seq_bakasha = v_seq_bakasha_prev);
  
    delete from vetek_detail t31 where seq_bakasha = v_seq_bakasha_prev;
  
    delete from netuney_sachar t25
     where t25.seq_bakasha = v_seq_bakasha_prev;
    delete from chinuch_bakara t
     where t.seq_chinuch_reforma in
           (select t25.seq_chinuch_reforma
              from chinuch_reforma t25
             where t25.seq_bakasha = v_seq_bakasha_prev);
  
    delete from chinuch_reforma t25
     where t25.seq_bakasha = v_seq_bakasha_prev;
    delete from chinuch_mitve_nur t25
     where t25.seq_bakasha = v_seq_bakasha_prev;
    delete from chinuch_salary t25
     where t25.seq_bakasha = v_seq_bakasha_prev;
  end;
  --------------------------------------------------------

  procedure delete_old_data(v_seq_netuney_sachar_prev number) is
    v_seq_bakasha_prev number;
  begin
  
    delete from vetek_detail v
     where v.seq_netuney_sachar = v_seq_netuney_sachar_prev;
  
    delete from tosefot t
     where t.seq_netuney_sachar = v_seq_netuney_sachar_prev;
  
    delete from netuney_sachar n
     where n.seq_netuney_sachar = v_seq_netuney_sachar_prev;
  
  end;

  --------------------------------------------------------
  procedure code_addition_not_exist(p_code_addition      number,
                                    p_seq_netuney_sachar number) is
    v_remark varchar2(1000) := ' לא נקלטה תוספת שאינה מוכרת: ' ||
                               p_code_addition;
  begin
    --Add remark
    update netuney_sachar n
       set n.remarks = remarks || v_remark
     where n.seq_netuney_sachar = p_seq_netuney_sachar;
  end;
  ---------------------------------------------------------
  procedure insert_vetek_detail(p_seq_bakasha        number,
                                p_code_type_vetek    number,
                                p_vetek              number,
                                p_seq_netuney_sachar number) is
  begin
    if nvl(p_vetek, 0) <> 0 then
      insert into vetek_detail
        (seq_vetek_detail,
         seq_bakasha,
         code_type_vetek,
         years,
         date_update,
         seq_netuney_sachar)
      values
        (vetek_detail_seq.nextval,
         p_seq_bakasha,
         p_code_type_vetek,
         p_vetek,
         sysdate,
         p_seq_netuney_sachar) log errors into err_vetek_detail REJECT LIMIT UNLIMITED;
    end if;
  
  end;
  ----------------------------------------------------------

  function Open_new_bakasha(p_seq_prisha number) return number is
    v_new_seq_bakasha number;
  begin
    v_new_seq_bakasha := bakasha_seq.nextval;
    --insert bakasha
    insert into bakasha
      (seq_bakasha,
       seq_prisha,
       code_sug_bakasha,
       date_bakasha,
       code_source)
    values
      (v_new_seq_bakasha, p_seq_prisha, 14, sysdate, 15);
  
    return v_new_seq_bakasha;
  end;
  --------------------------------------------------------
  procedure Get_td(v_html_body                 in out clob,
                   v_code_status_get_condition number,
                   v_code_status_get           number) is
    v_ok_icon varchar2(1000) := '<center><span class="glyphicon glyphicon-ok" aria-hidden="true"></span></center>';
  begin
    v_html_body := v_html_body || '<td>';
    if v_code_status_get_condition = v_code_status_get then
      v_html_body := v_html_body || v_ok_icon;
    end if;
    v_html_body := v_html_body || '</td>';
  end Get_td;
  -------------------------------------------------------
  procedure Get_td_is_new(v_html_body        in out clob,
                          v_code_sug_bakasha number) is
    v_hand_right_icon varchar2(1000) := '<span class="glyphicon glyphicon-hand-right" aria-hidden="true"></span>';
  begin
    v_html_body := v_html_body || '<td>';
    if v_code_sug_bakasha = 1 then
      v_html_body := v_html_body || v_hand_right_icon;
    end if;
    v_html_body := v_html_body || '</td>';
  end;
  -------------------------------------------------------
  function Get_body(p_ld_protocol            number,
                    p_count_success          in out number,
                    p_count_id_not_exist_yet in out number,
                    p_count_errors           in out number) return clob is
    v_html_body clob := '';
  begin
    p_count_errors           := 0;
    p_count_success          := 0;
    p_count_id_not_exist_yet := 0;
  
    for r in (select distinct nvl(lm.identity_number, lc.b) identity_number,
                              -- To avoid double rows every id when there is several rows by type salary
                              case
                                when t.code_status_get in (1, 2, 4) then
                                 1
                                else
                                 t.code_status_get
                              end code_status_get,
                              s.teur_chinuch_sug_shinuy || '-' || t.message message,
                              b.code_sug_bakasha
                from ld_salary_base t
                left join bakasha b
                  on t.seq_bakasha = b.seq_bakasha
                left join ld_mlm_salary lm
                  on lm.seq_ld_mlm_salary = t.seq_ld_mlm_salary
                left join ld_chinuch_salary_01 lc
                  on t.seq_ld_chinuch_salary_01 =
                     lc.seq_ld_chinuch_salary_01
                left join code_chinuch_salary_shinuy s
                  on t.is_new_data = s.code_chinuch_sug_shinuy
               where nvl(t.seq_ld_protocol, 0) = p_ld_protocol) loop
      if r.code_status_get in (5) then
        --Add to errors counter
        p_count_errors := p_count_errors + 1;
        --Define danger view row
        v_html_body := v_html_body || '<tr class="danger">';
      elsif r.code_status_get in (3) then
        --Add to id_not_exist_yet counter
        p_count_id_not_exist_yet := p_count_id_not_exist_yet + 1;
        --Define id_not_exist_yet view row
        v_html_body := v_html_body || '<tr class="warning">';
      else
        --Add to success counter
        p_count_success := p_count_success + 1;
        --Define success view row
        v_html_body := v_html_body || '<tr>';
      end if;
    
      --Is new
      Get_td_is_new(v_html_body, r.code_sug_bakasha);
      -- Id
      v_html_body := v_html_body || '<td><strong>' || r.identity_number ||
                     '</strong></td>';
    
      --success
      Get_td(v_html_body, 1, r.code_status_get);
      --id_not_exist_yet
      Get_td(v_html_body, 3, r.code_status_get);
      --errors
      v_html_body := v_html_body || '<td>' || nvl(r.message, '') || '</td>';
      --end row
      v_html_body := v_html_body || '</tr>';
    end loop;
  
    return v_html_body;
  end;
  --------------------------------------------------------
  function get_report(p_ld_protocol number) return clob is
    v_body                   clob;
    v_report                 clob;
    v_count_success          number;
    v_count_id_not_exist_yet number;
    v_count_errors           number;
  
  begin
    v_body := Get_body(p_ld_protocol,
                       v_count_success,
                       v_count_id_not_exist_yet,
                       v_count_errors);
  
    v_report := '<!DOCTYPE html>
<html lang="en">
<head>
    <title>Log</title>
    <meta name="viewport" content="width=device-width, initial-scale=1"/>
    <link rel="stylesheet" href="https://maxcdn.bootstrapcdn.com/bootstrap/3.3.7/css/bootstrap.min.css"/>
    <script src="https://ajax.googleapis.com/ajax/libs/jquery/3.2.1/jquery.min.js"></script>
    <script src="https://maxcdn.bootstrapcdn.com/bootstrap/3.3.7/js/bootstrap.min.js"></script>
</head>
<body>
    <div class="container"> <h4 class="CountSuccess"> Count Success: ' ||
                v_count_success ||
                '</h4>
        <h4 class="CountWarnings"> Count Id not exist yet: ' ||
                v_count_id_not_exist_yet ||
                '</h4>
        <h4 class="CountErrors"> Count Errors: ' ||
                v_count_errors || '</h4>
        <p></p>
        <table class="table" dir="ltr">
            <thead>
                <tr>
                 <th>Is new</th>
                    <th>Id</th>
                     <th><center>Success<center></th>
                      <th><center>Not exist yet<center></th>
                    <th><center>Errors</center></th>
                </tr>
            </thead>
            <tbody>' || v_body || '</tbody>
            </table>
         </div>
</body>
</html';
  
    return v_report;
  end;
  --------------------------------------------------------
  function get_translate_message(p_sqlerrm varchar2) return varchar2 is
  begin
    if p_sqlerrm like '%UK1_NETUNEY_SACHAR%' then
      return 'לפורש כבר קיימים נתוני שכר במערכת מפמ';
    else
      return p_sqlerrm;
    end if;
  end;
  -------------------------------------------------------
  function compare_versions(p_seq_bakasha_for_compare number,
                            p_seq_bakasha_for_insert  number,
                            p_seq_netuney_sachar_new  number) return number is
    v_seq_netuney_sachar_prev number;
    v_count_rows              number;
    v_is_new_value_maskoret   number;
    v_maskoret_kovaat_new     number;
  begin
  
    if p_seq_netuney_sachar_new is null then
      return 0;
    end if;
  
    begin
      --Check if exist netuney sachar prev
      select max(n2.seq_netuney_sachar)
        into v_seq_netuney_sachar_prev
        from netuney_sachar n
        left join netuney_sachar n2
          on n2.seq_bakasha = p_seq_bakasha_for_compare
         and n2.mispar_misra =
             decode(n.mispar_misra, 99, 0, n.mispar_misra)
         and n2.code_sug_maskoret = n.code_sug_maskoret
            -- and n2.seq_chinuch_reforma = n.seq_chinuch_reforma
         and n2.seq_netuney_sachar < p_seq_netuney_sachar_new
       where n.seq_netuney_sachar = p_seq_netuney_sachar_new;
    exception
      when others then
        v_seq_netuney_sachar_prev := null;
    end;
  
    if v_seq_netuney_sachar_prev is not null then
    
      --Get maskoret kovaat new
      select n1.maskoret_kovaat
        into v_maskoret_kovaat_new
        from netuney_sachar n1
       where n1.seq_netuney_sachar = p_seq_netuney_sachar_new;
    
      --Compare maskoret kovaat
      select case
               when abs(n.maskoret_kovaat - v_maskoret_kovaat_new) < 5 then
                0
               else
                1
             end
        into v_is_new_value_maskoret
        from netuney_sachar n
       where n.seq_netuney_sachar = v_seq_netuney_sachar_prev;
    
      --Compare old data with new data
      select count(*)
        into v_count_rows
        from (select distinct n.havraa_days,
                              n.sum_bigud,
                              n.ramat_bigud,
                              n.is_maanak_yovel
                from netuney_sachar n
               where n.seq_netuney_sachar in
                     (v_seq_netuney_sachar_prev, p_seq_netuney_sachar_new));
    
      if p_seq_bakasha_for_compare = p_seq_bakasha_for_insert then
        pk_salary_base.delete_old_data(v_seq_netuney_sachar_prev);
      end if;
    
      if v_count_rows = 1 and v_is_new_value_maskoret = 0 then
        return 0;
      end if;
    
    end if;
  
    return 1;
  end;
  -------------------------------------------------------
  function Before_insert_salary_data(p_seq_bakasha_for_compare number,
                                     p_seq_bakasha_for_insert  number,
                                     p_mispar_misra            number,
                                     p_code_sug_maskoret       number,
                                     p_maskoret_kovaat         number,
                                     p_havraa_days             number,
                                     p_sum_bigud               number,
                                     p_ramat_bigud             number,
                                     p_is_maanak_yovel         number)
    return number is
    v_seq_netuney_sachar_prev number;
    v_count_rows              number;
    v_is_new_value_maskoret   number;
  begin
    begin
      --Check if exist netuney sachar prev
      select n.seq_netuney_sachar
        into v_seq_netuney_sachar_prev
        from netuney_sachar n
       where n.seq_bakasha = p_seq_bakasha_for_compare
         and n.mispar_misra = p_mispar_misra
         and n.code_sug_maskoret = p_code_sug_maskoret;
    exception
      when others then
        v_seq_netuney_sachar_prev := null;
    end;
  
    if v_seq_netuney_sachar_prev is not null then
    
      --Compare maskoret kovaat
      select case
               when abs(n.maskoret_kovaat - p_maskoret_kovaat) < 5 then
                0
               else
                1
             end
        into v_is_new_value_maskoret
        from netuney_sachar n
       where n.seq_netuney_sachar = v_seq_netuney_sachar_prev;
    
      --Compare old data with new data
      select count(*)
        into v_count_rows
        from (select p_maskoret_kovaat,
                     p_havraa_days,
                     p_sum_bigud,
                     p_ramat_bigud,
                     p_is_maanak_yovel
                from dual
              union
              select n.maskoret_kovaat,
                     n.havraa_days,
                     n.sum_bigud,
                     n.ramat_bigud,
                     n.is_maanak_yovel
                from netuney_sachar n
               where n.seq_netuney_sachar = v_seq_netuney_sachar_prev);
    
      if p_seq_bakasha_for_compare = p_seq_bakasha_for_insert then
        pk_salary_base.delete_old_data(v_seq_netuney_sachar_prev);
      end if;
    
      if v_count_rows = 1 or v_is_new_value_maskoret = 0 then
        return 0;
      end if;
    
    end if;
  
    return 1;
  end;
  -------------------------------------------------------
  function get_start_zakaut(p_seq_bakasha number) return date is
    v_date_start_zakaut date;
    v_seq_prisha        number;
  begin
    -- Get seq_bakasha
    select b.seq_prisha
      into v_seq_prisha
      from bakasha b
     where b.seq_bakasha = p_seq_bakasha;
  
    select max(v.date_start_zakaut)
      into v_date_start_zakaut
      from table(fn_obj_prisha_last_zakaut_arr(pk_select_function.fn_v_bakasha_last_zakaut(v_seq_prisha => v_seq_prisha))) v;
  
    return v_date_start_zakaut;
  exception
    when others then
      return null;
  end;
   --------------------------------------------------------
  procedure chinuch_manage_actions(p_ld_protocol number,
                                   p_seq_bakasha number) is
  
    v_is_new_data                  number;
    v_is_before_payment_department number;
    v_current_action               number;
    v_code_status_get              number;
    v_direct_hilan                 number;
    v_is_maanak_n                  number;
    v_is_maanak                    number;
    v_new_data_reson               nvarchar2(100);
    v_date_start_zakaut            date;
    v_date_prisha                  date;
  begin
    if p_seq_bakasha is null then
      rollback;
      return;
    end if;
  
    select t.taarich_prisha, t.date_start_zakaut
      into v_date_prisha, v_date_start_zakaut
      from v_bakasha_last_zakaut t
     where t."SEQ_BAKASHA" = p_seq_bakasha;
  
    select max(l.is_new_data)
      into v_is_new_data
      from ld_salary_base l
     where nvl(l.seq_ld_protocol, 0) = nvl(p_ld_protocol, 0)
       and l.seq_bakasha = p_seq_bakasha;
    select max(l.is_direct_hilan)
      into v_direct_hilan
      from ld_salary_base l
     where nvl(l.seq_ld_protocol, 0) = nvl(p_ld_protocol, 0)
       and l.seq_bakasha = p_seq_bakasha;
    select max(l.code_status_get)
      into v_code_status_get
      from ld_salary_base l
     where nvl(l.seq_ld_protocol, 0) = nvl(p_ld_protocol, 0)
       and l.seq_bakasha = p_seq_bakasha;
    v_is_before_payment_department := pk_prm_utils.is_action_bakash_bfor_specific(p_seq_bakasha,
                                                                                  119);
    select t.teur_chinuch_sug_shinuy
      into v_new_data_reson
      from code_chinuch_salary_shinuy t
     where t.code_chinuch_sug_shinuy = v_is_new_data;
  
    if v_is_new_data = 0 then
      --Rollback!
      rollback;
      update ld_salary_base l
         set l.seq_bakasha = null, l.code_status_get = 4
       where nvl(l.seq_ld_protocol, 0) = nvl(p_ld_protocol, 0)
         and l.seq_bakasha = p_seq_bakasha;
      pk_prm_utils.insert_action_log_row(171,
                                         sysdate,
                                         0,
                                         null,
                                         'התקבלו נתוני שכר זהים לנתונים קודמים',
                                         null,
                                         null,
                                         null,
                                         p_seq_bakasha,
                                         null);
      commit;
      return;
    elsif v_is_new_data in (1, 5, 6, 7, 10) or
          v_date_prisha <> v_date_start_zakaut - 1 then
    
      if v_is_before_payment_department = 0 then
        --Return the status to payment department
        pk_prm_utils.insert_action_log_row(171,
                                           sysdate,
                                           0,
                                           null,
                                           null,
                                           null,
                                           null,
                                           null,
                                           p_seq_bakasha,
                                           null);
        --   if v_current_action <> 225 then
        pk_prm_utils.insert_action_log_row(114,
                                           sysdate,
                                           0,
                                           null,
                                           v_new_data_reson,
                                           null,
                                           null,
                                           null,
                                           p_seq_bakasha,
                                           null);
        commit;
        --  end if;
      else
        pk_prm_utils.insert_action_log_row(171,
                                           sysdate,
                                           0,
                                           null,
                                           null,
                                           null,
                                           null,
                                           null,
                                           p_seq_bakasha,
                                           null);
        select v.code_action
          into v_current_action
          from v_bakasha_last_status v
         where v.seq_bakasha = p_seq_bakasha;
        if v_current_action is null or v_current_action = 146 then
          --insert action log
          pk_prm_utils.insert_actions_for_bakasha(p_seq_bakasha, 0);
        end if;
        commit;
      end if;
    
      --maanak-return to zakaut department
      v_is_maanak_n := check_zakaut_maanak(p_seq_bakasha);
      if v_is_maanak_n = 1 then
        pk_prm_utils.insert_action_log_row(171,
                                           sysdate,
                                           0,
                                           null,
                                           null,
                                           null,
                                           null,
                                           null,
                                           p_seq_bakasha,
                                           null);
        pk_prm_utils.insert_action_log_row(19,
                                           sysdate,
                                           0,
                                           null,
                                           'זכאות למענק בעקבות משכורת קובעת',
                                           null,
                                           null,
                                           null,
                                           p_seq_bakasha,
                                           null);
        commit;
      end if;
    
    elsif v_direct_hilan <> 0 or v_code_status_get = 2 and
          v_is_new_data in (2, 3, 4, 8, 11, 12, 9,13) and
          v_date_prisha + 1 = v_date_start_zakaut then
      pk_prm_utils.insert_action_log_row(171,
                                         sysdate,
                                         0,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         p_seq_bakasha,
                                         null);
      pk_prm_utils.insert_action_log_row(134,
                                         sysdate,
                                         0,
                                         null,
                                         'נשלח ישיר לחילן-' ||
                                         v_new_data_reson,
                                         null,
                                         null,
                                         null,
                                         p_seq_bakasha,
                                         null);
      commit;
    else
      --if v_direct_hilan = 0 then
      select v.code_action
        into v_current_action
        from v_bakasha_last_status v
       where v.seq_bakasha = p_seq_bakasha;
    
      --When the bakasha is in status 'wait to salary'
      if v_current_action is null or v_current_action = 146 then
        --insert action log
        pk_prm_utils.insert_actions_for_bakasha(p_seq_bakasha, 0);
      else
      
        --When the bakasha is after status 'wait to payment department'                                                                       
        if v_is_new_data not in (2, 3, 4, 8, 11, 12, 9,13) then
          --Return the status to payment department
          pk_prm_utils.insert_action_log_row(171,
                                             sysdate,
                                             0,
                                             null,
                                             null,
                                             null,
                                             null,
                                             null,
                                             p_seq_bakasha,
                                             null);
          pk_prm_utils.insert_action_log_row(114,
                                             sysdate,
                                             0,
                                             null,
                                             v_new_data_reson,
                                             null,
                                             null,
                                             null,
                                             p_seq_bakasha,
                                             null);
        else
          --Return the status to payment department
          pk_prm_utils.insert_action_log_row(171,
                                             sysdate,
                                             0,
                                             null,
                                             'נתונים יכולים להשלח ישיר לחילן, לא מוחזר לתשלומים',
                                             null,
                                             null,
                                             null,
                                             p_seq_bakasha,
                                             null);
        end if;
      
      end if;
      Commit;
    end if;
    commit;
  
  end;
   --------------------------------------------------------
  procedure load_managment_id(p_ld_protocol              number,
                              p_seq_ld_mlm_salary        number,
                              p_seq_ld_chinuch_salary_01 number,
                              p_identity_number          number,
                              p_office                   number,
                              p_function_name            varchar2) is
    v_seq_bakasha_regila           number;
    v_seq_bakasha_for_update       number;
    v_seq_prisha                   number;
    v_code_status_get              number;
    v_is_get_new_date              number;
    v_is_bakasha_was_not_confirmed number;
    v_operation                    varchar2(1000);
    v_is_get_new_salary_1          NUMBER;
  
  begin
  
    v_global_message := null;
    begin
      begin
        --Get seq bakasha
        select max(v.seq_bakasha), v.seq_prisha
          into v_seq_bakasha_regila, v_seq_prisha
          from v_bakasha_last_status v
          left join code_ezor_ovdim c
            on v.seq_ezor_ovdim = c.seq_ezor_ovdim
         where v.mispar_zehut = p_identity_number
           and c.code_misrad_maskret = p_office
           and v.code_sug_bakasha in (1, 14)
           and nvl(v.code_action, 0) not in (17, 100)
           and nvl(v.code_department_action, 0) <> 1
         group by v.seq_prisha;
      exception
        when no_data_found then
          update_ld_salary_base(p_ld_protocol,
                                p_seq_ld_mlm_salary,
                                p_seq_ld_chinuch_salary_01,
                                3);
          return;
      end;
    
      --Check if the regular bakasha was confirmed in payment department
      v_is_bakasha_was_not_confirmed := pk_prm_utils.is_bakasha_was_not_confirmed(v_seq_bakasha_regila,
                                                                                  2);
    
      if v_is_bakasha_was_not_confirmed = 1 then
      
        v_code_status_get        := 1;
        v_seq_bakasha_for_update := v_seq_bakasha_regila;
      else
        v_code_status_get        := 2;
        v_seq_bakasha_for_update := Open_new_bakasha(v_seq_prisha);
      end if;
      --chinuch
      if p_seq_ld_chinuch_salary_01 is not null then
        v_is_get_new_salary_1 := pk_chinuch_salary.is_get_new_salary_1(v_seq_bakasha_regila,
                                                                       p_seq_ld_chinuch_salary_01);
        --new  data
        if v_is_get_new_salary_1 > 0 then
          --delete old data
          if v_code_status_get = 1 then
            delete_netney_sachr_frm_bkasha(v_seq_bakasha_regila);
          
          end if;
          --there is old data
        else
        
          update_ld_salary_base(p_ld_protocol,
                                p_seq_ld_mlm_salary,
                                p_seq_ld_chinuch_salary_01,
                                4);
          return;
        end if;
        update_ld_salary_base(p_ld_protocol,
                              p_seq_ld_mlm_salary,
                              p_seq_ld_chinuch_salary_01,
                              v_code_status_get,
                              v_seq_bakasha_for_update,
                              v_is_get_new_salary_1);
      
      end if;
      --update in netuney sachar table
      v_operation := 'begin :result := ' || p_function_name ||
                     '.update_netuney_sachar(' ||
                     nvl(p_seq_ld_mlm_salary, p_seq_ld_chinuch_salary_01) || ',' ||
                     v_seq_bakasha_regila || ',' ||
                     v_seq_bakasha_for_update || '); end;';
      execute immediate v_operation
        using out v_is_get_new_date;
    
    exception
      when others then
        v_code_status_get        := 5;
        v_seq_bakasha_for_update := null;
        v_global_message         := get_translate_message(Sqlerrm);
    end;
    if p_seq_ld_chinuch_salary_01 is null or v_code_status_get = 5 then
      update_ld_salary_base(p_ld_protocol,
                            p_seq_ld_mlm_salary,
                            p_seq_ld_chinuch_salary_01,
                            v_code_status_get,
                            v_seq_bakasha_for_update,
                            v_is_get_new_date);
    end if;
  
  end;
  ------------------------------------------------------
  --------------------------------------------------------
  function check_zakaut_maanak(p_seq_bakasha number) return number is
    v_seq_netunet_tik_mechushavim number;
    v_code_sug_bakasha            number;
    v_seq_ezor_ovdim              number;
    v_is_maanak                   number;
    v_is_maanak_prev              number;
  begin
    select t.code_sug_bakasha,
           t.seq_ezor_ovdim,
           t1.seq_netuney_tik_mechushavim,
           t1.is_zakai_lmaanak
      into v_code_sug_bakasha,
           v_seq_ezor_ovdim,
           v_seq_netunet_tik_mechushavim,
           v_is_maanak_prev
      from v_bakasha_last_status t
      left join netuney_tik_mechushavim t1
        on t.seq_bakasha = t1.seq_bakasha
       and t1.code_department = 2
       and t1.mispar_misra = 0
     where t.seq_bakasha = p_seq_bakasha;
  
    if v_code_sug_bakasha = 1 and v_seq_ezor_ovdim = 206 and
       nvl(v_is_maanak_prev, 0) = 0 then
      pk_zakaut.calc_is_zakay_maanak(p_seq_bakasha,
                                     v_seq_netunet_tik_mechushavim,
                                     0,
                                     0);
      select t.is_zakai_lmaanak
        into v_is_maanak
        from netuney_tik_mechushavim t
       where t.seq_netuney_tik_mechushavim = v_seq_netunet_tik_mechushavim;
    end if;
    return v_is_maanak;
  end;
  --------------------------------------------------------
  procedure manage_actions(p_ld_protocol number, p_seq_bakasha number) is
  
    v_is_new_data                  number;
    v_is_before_payment_department number;
    v_current_action               number;
    v_code_status_get              number;
    v_direct_hilan                 number;
    v_is_maanak_n                  number;
    v_is_maanak                    number;
  begin
    if p_seq_bakasha is null then
      rollback;
      return;
    end if;
  
    select max(l.is_new_data)
      into v_is_new_data
      from ld_salary_base l
     where nvl(l.seq_ld_protocol, 0) = nvl(p_ld_protocol, 0)
       and l.seq_bakasha = p_seq_bakasha;
    select max(l.is_direct_hilan)
      into v_direct_hilan
      from ld_salary_base l
     where nvl(l.seq_ld_protocol, 0) = nvl(p_ld_protocol, 0)
       and l.seq_bakasha = p_seq_bakasha;
    if v_is_new_data = 0 then
      --Rollback!
      rollback;
      update ld_salary_base l
         set l.seq_bakasha = null, l.code_status_get = 4
       where nvl(l.seq_ld_protocol, 0) = nvl(p_ld_protocol, 0)
         and l.seq_bakasha = p_seq_bakasha;
      commit;
      return;
    
    elsif v_is_new_data = 1 then
      pk_prm_utils.insert_action_log_row(171,
                                         sysdate,
                                         0,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         p_seq_bakasha,
                                         null);
      commit;
    
      v_is_maanak_n := check_zakaut_maanak(p_seq_bakasha);
      if v_is_maanak_n = 1 then
        pk_prm_utils.insert_action_log_row(19,
                                           sysdate,
                                           0,
                                           null,
                                           'זכאות למענק בעקבות משכורת קובעת',
                                           null,
                                           null,
                                           null,
                                           p_seq_bakasha,
                                           null);
      else
      
        if v_direct_hilan = 0 then
          select v.code_action
            into v_current_action
            from v_bakasha_last_status v
           where v.seq_bakasha = p_seq_bakasha;
        
          --When the bakasha is in status 'wait to salary'
          if v_current_action is null or v_current_action = 146 then
            --insert action log
            pk_prm_utils.insert_actions_for_bakasha(p_seq_bakasha, 0);
          
            --When the bakasha is not in status 'Document filing'
          elsif (v_current_action not in (193, 194)) then
          
            v_is_before_payment_department := pk_prm_utils.is_action_bakash_bfor_specific(p_seq_bakasha,
                                                                                          119);
            --When the bakasha is after status 'wait to payment department'                                                                       
            if v_is_before_payment_department = 0 then
              --Return the status to payment department
              --   if v_current_action <> 225 then
              pk_prm_utils.insert_action_log_row(114,
                                                 sysdate,
                                                 0,
                                                 null,
                                                 'התקבלו נתוני משכורת קובעת בממשק',
                                                 null,
                                                 null,
                                                 null,
                                                 p_seq_bakasha,
                                                 null);
              --   end if;
            end if;
          
            --  end if;
            --Commit!
            commit;
          end if;
        else
          pk_prm_utils.insert_action_log_row(134,
                                             sysdate,
                                             0,
                                             null,
                                             'הפרש מזערי במשכורת קובעת, נשלח ישיר לחילן',
                                             null,
                                             null,
                                             null,
                                             p_seq_bakasha,
                                             null);
          commit;
        end if;
      end if;
    end if;
  end;
end;
/

create or replace package body prm_system_copy.pk_salary_base_old is
  --------------------------------------------------------
  v_global_message varchar2(1000);
  --------------------------------------------------------
  procedure update_ld_salary_base(p_ld_protocol              number,
                                  p_seq_ld_mlm_salary        number,
                                  p_seq_ld_chinuch_salary_01 number,
                                  p_code_status              number,
                                  p_seq_bakasha              number default null,
                                  p_is_new_data              number default 1) is
    pragma autonomous_transaction;
  begin

    merge into ld_salary_base l
    using dual
    on ((p_seq_ld_chinuch_salary_01 is not null and l.seq_ld_chinuch_salary_01 = p_seq_ld_chinuch_salary_01) or (p_seq_ld_mlm_salary is not null and l.seq_ld_mlm_salary = p_seq_ld_mlm_salary))
    when matched then
      update
         set l.code_status_get = p_code_status,
             l.date_status_get = sysdate,
             l.seq_bakasha     = p_seq_bakasha,
             l.message         = v_global_message,
             l.seq_ld_protocol = p_ld_protocol,
             l.is_new_data     = p_is_new_data
    when not matched then
      insert
        (seq_ld_salary_base,
         seq_ld_mlm_salary,
         seq_ld_chinuch_salary_01,
         code_status_get,
         date_status_get,
         seq_bakasha,
         message,
         seq_ld_protocol,
         is_new_data)
      values
        (ld_salary_base_seq.nextval,
         p_seq_ld_mlm_salary,
         p_seq_ld_chinuch_salary_01,
         p_code_status,
         sysdate,
         p_seq_bakasha,
         v_global_message,
         p_ld_protocol,
         p_is_new_data);

    commit;
  end;
  --------------------------------------------------------
  procedure delete_old_data(v_seq_netuney_sachar_prev number) is
  begin

    delete from vetek_detail v
     where v.seq_netuney_sachar = v_seq_netuney_sachar_prev;

    delete from tosefot t
     where t.seq_netuney_sachar = v_seq_netuney_sachar_prev;

    delete from netuney_sachar n
     where n.seq_netuney_sachar = v_seq_netuney_sachar_prev;

  end;

  --------------------------------------------------------
  procedure code_addition_not_exist(p_code_addition      number,
                                    p_seq_netuney_sachar number) is
    v_remark varchar2(1000) := ' לא נקלטה תוספת שאינה מוכרת: ' ||
                               p_code_addition;
  begin
    --Add remark
    update netuney_sachar n
       set n.remarks = remarks || v_remark
     where n.seq_netuney_sachar = p_seq_netuney_sachar;
  end;
  ---------------------------------------------------------
  procedure insert_vetek_detail(p_seq_bakasha        number,
                                p_code_type_vetek    number,
                                p_vetek              number,
                                p_seq_netuney_sachar number) is
  begin
    if nvl(p_vetek, 0) <> 0 then
      insert into vetek_detail
        (seq_vetek_detail,
         seq_bakasha,
         code_type_vetek,
         years,
         date_update,
         seq_netuney_sachar)
      values
        (vetek_detail_seq.nextval,
         p_seq_bakasha,
         p_code_type_vetek,
         p_vetek,
         sysdate,
         p_seq_netuney_sachar) log errors into err_vetek_detail REJECT LIMIT UNLIMITED;
    end if;

  end;
  ----------------------------------------------------------

  function Open_new_bakasha(p_seq_prisha number) return number is
    v_new_seq_bakasha number;
  begin
    v_new_seq_bakasha := bakasha_seq.nextval;
    --insert bakasha
    insert into bakasha
      (seq_bakasha,
       seq_prisha,
       code_sug_bakasha,
       date_bakasha,
       code_source)
    values
      (v_new_seq_bakasha, p_seq_prisha, 14, sysdate, 15);

    return v_new_seq_bakasha;
  end;
  --------------------------------------------------------
  procedure Get_td(v_html_body                 in out clob,
                   v_code_status_get_condition number,
                   v_code_status_get           number) is
    v_ok_icon varchar2(1000) := '<center><span class="glyphicon glyphicon-ok" aria-hidden="true"></span></center>';
  begin
    v_html_body := v_html_body || '<td>';
    if v_code_status_get_condition = v_code_status_get then
      v_html_body := v_html_body || v_ok_icon;
    end if;
    v_html_body := v_html_body || '</td>';
  end Get_td;
  -------------------------------------------------------
  procedure Get_td_is_new(v_html_body        in out clob,
                          v_code_sug_bakasha number) is
    v_hand_right_icon varchar2(1000) := '<span class="glyphicon glyphicon-hand-right" aria-hidden="true"></span>';
  begin
    v_html_body := v_html_body || '<td>';
    if v_code_sug_bakasha = 1 then
      v_html_body := v_html_body || v_hand_right_icon;
    end if;
    v_html_body := v_html_body || '</td>';
  end;
  -------------------------------------------------------
  function Get_body(p_ld_protocol            number,
                    p_count_success          in out number,
                    p_count_id_not_exist_yet in out number,
                    p_count_errors           in out number) return clob is
    v_html_body clob := '';
  begin
    p_count_errors           := 0;
    p_count_success          := 0;
    p_count_id_not_exist_yet := 0;

    for r in (select distinct nvl(lm.identity_number, lc.b) identity_number,
                              -- To avoid double rows every id when there is several rows by type salary
                              case
                                when t.code_status_get in (1, 2, 4) then
                                 1
                                else
                                 t.code_status_get
                              end code_status_get,
                              t.message,
                              b.code_sug_bakasha
                from ld_salary_base t
                left join bakasha b
                  on t.seq_bakasha = b.seq_bakasha
                left join ld_mlm_salary lm
                  on lm.seq_ld_mlm_salary = t.seq_ld_mlm_salary
                left join ld_chinuch_salary_01 lc
                  on t.seq_ld_chinuch_salary_01 =
                     lc.seq_ld_chinuch_salary_01
               where nvl(t.seq_ld_protocol, 0) = p_ld_protocol) loop
      if r.code_status_get in (5) then
        --Add to errors counter
        p_count_errors := p_count_errors + 1;
        --Define danger view row
        v_html_body := v_html_body || '<tr class="danger">';
      elsif r.code_status_get in (3) then
        --Add to id_not_exist_yet counter
        p_count_id_not_exist_yet := p_count_id_not_exist_yet + 1;
        --Define id_not_exist_yet view row
        v_html_body := v_html_body || '<tr class="warning">';
      else
        --Add to success counter
        p_count_success := p_count_success + 1;
        --Define success view row
        v_html_body := v_html_body || '<tr>';
      end if;

      --Is new
      Get_td_is_new(v_html_body, r.code_sug_bakasha);
      -- Id
      v_html_body := v_html_body || '<td><strong>' || r.identity_number ||
                     '</strong></td>';

      --success
      Get_td(v_html_body, 1, r.code_status_get);
      --id_not_exist_yet
      Get_td(v_html_body, 3, r.code_status_get);
      --errors
      v_html_body := v_html_body || '<td>' || nvl(r.message, '') || '</td>';
      --end row
      v_html_body := v_html_body || '</tr>';
    end loop;

    return v_html_body;
  end;
  --------------------------------------------------------
  function get_report(p_ld_protocol number) return clob is
    v_body                   clob;
    v_report                 clob;
    v_count_success          number;
    v_count_id_not_exist_yet number;
    v_count_errors           number;

  begin
    v_body := Get_body(p_ld_protocol,
                       v_count_success,
                       v_count_id_not_exist_yet,
                       v_count_errors);

    v_report := '<!DOCTYPE html>
<html lang="en">
<head>
    <title>Log</title>
    <meta name="viewport" content="width=device-width, initial-scale=1"/>
    <link rel="stylesheet" href="https://maxcdn.bootstrapcdn.com/bootstrap/3.3.7/css/bootstrap.min.css"/>
    <script src="https://ajax.googleapis.com/ajax/libs/jquery/3.2.1/jquery.min.js"></script>
    <script src="https://maxcdn.bootstrapcdn.com/bootstrap/3.3.7/js/bootstrap.min.js"></script>
</head>
<body>
    <div class="container"> <h4 class="CountSuccess"> Count Success: ' ||
                v_count_success ||
                '</h4>
        <h4 class="CountWarnings"> Count Id not exist yet: ' ||
                v_count_id_not_exist_yet ||
                '</h4>
        <h4 class="CountErrors"> Count Errors: ' ||
                v_count_errors || '</h4>
        <p></p>
        <table class="table" dir="ltr">
            <thead>
                <tr>
                 <th>Is new</th>
                    <th>Id</th>
                     <th><center>Success<center></th>
                      <th><center>Not exist yet<center></th>
                    <th><center>Errors</center></th>
                </tr>
            </thead>
            <tbody>' || v_body || '</tbody>
            </table>
         </div>
</body>
</html';

    return v_report;
  end;
  --------------------------------------------------------
  function get_translate_message(p_sqlerrm varchar2) return varchar2 is
  begin
    if p_sqlerrm like '%UK1_NETUNEY_SACHAR%' then
      return 'לפורש כבר קיימים נתוני שכר במערכת מפמ';
    else
      return p_sqlerrm;
    end if;
  end;
  -------------------------------------------------------
  function compare_versions(p_seq_bakasha_for_compare number,
                            p_seq_bakasha_for_insert  number,
                            p_seq_netuney_sachar_new  number) return number is
    v_seq_netuney_sachar_prev number;
    v_count_rows              number;
    v_is_new_value_maskoret   number;

    v_maskoret_kovaat_new number;
  begin

    if p_seq_netuney_sachar_new is null then
      return 0;
    end if;

    begin
      --Check if exist netuney sachar prev
      select max(n2.seq_netuney_sachar)
        into v_seq_netuney_sachar_prev
        from netuney_sachar n
        left join netuney_sachar n2
          on n2.seq_bakasha = p_seq_bakasha_for_compare
         and n2.mispar_misra =
             decode(n.mispar_misra, 99, 0, n.mispar_misra)
         and n2.code_sug_maskoret = n.code_sug_maskoret
         and n2.seq_netuney_sachar < p_seq_netuney_sachar_new
       where n.seq_netuney_sachar = p_seq_netuney_sachar_new;
    exception
      when others then
        v_seq_netuney_sachar_prev := null;
    end;

    if v_seq_netuney_sachar_prev is not null then

      --Get maskoret kovaat new
      select n1.maskoret_kovaat
        into v_maskoret_kovaat_new
        from netuney_sachar n1
       where n1.seq_netuney_sachar = p_seq_netuney_sachar_new;

      --Compare maskoret kovaat
      select case
               when abs(n.maskoret_kovaat - v_maskoret_kovaat_new) < 5 then
                0
               else
                1
             end
        into v_is_new_value_maskoret
        from netuney_sachar n
       where n.seq_netuney_sachar = v_seq_netuney_sachar_prev;

      --Compare old data with new data
      select count(*)
        into v_count_rows
        from (select distinct n.havraa_days,
                              n.sum_bigud,
                              n.ramat_bigud,
                              n.is_maanak_yovel
                from netuney_sachar n
               where n.seq_netuney_sachar in
                     (v_seq_netuney_sachar_prev, p_seq_netuney_sachar_new));

      if p_seq_bakasha_for_compare = p_seq_bakasha_for_insert then
        pk_salary_base.delete_old_data(v_seq_netuney_sachar_prev);
      end if;

      if v_count_rows = 1 and v_is_new_value_maskoret = 0 then
        return 0;
      end if;

    end if;

    return 1;
  end;
  -------------------------------------------------------
  function Before_insert_salary_data(p_seq_bakasha_for_compare number,
                                     p_seq_bakasha_for_insert  number,
                                     p_mispar_misra            number,
                                     p_code_sug_maskoret       number,
                                     p_maskoret_kovaat         number,
                                     p_havraa_days             number,
                                     p_sum_bigud               number,
                                     p_ramat_bigud             number,
                                     p_is_maanak_yovel         number)
    return number is
    v_seq_netuney_sachar_prev number;
    v_count_rows              number;
    v_is_new_value_maskoret   number;
  begin
    begin
      --Check if exist netuney sachar prev
      select n.seq_netuney_sachar
        into v_seq_netuney_sachar_prev
        from netuney_sachar n
       where n.seq_bakasha = p_seq_bakasha_for_compare
         and n.mispar_misra = p_mispar_misra
         and n.code_sug_maskoret = p_code_sug_maskoret;
    exception
      when others then
        v_seq_netuney_sachar_prev := null;
    end;

    if v_seq_netuney_sachar_prev is not null then

      --Compare maskoret kovaat
      select case
               when abs(n.maskoret_kovaat - p_maskoret_kovaat) < 5 then
                0
               else
                1
             end
        into v_is_new_value_maskoret
        from netuney_sachar n
       where n.seq_netuney_sachar = v_seq_netuney_sachar_prev;

      --Compare old data with new data
      select count(*)
        into v_count_rows
        from (select p_maskoret_kovaat,
                     p_havraa_days,
                     p_sum_bigud,
                     p_ramat_bigud,
                     p_is_maanak_yovel
                from dual
              union
              select n.maskoret_kovaat,
                     n.havraa_days,
                     n.sum_bigud,
                     n.ramat_bigud,
                     n.is_maanak_yovel
                from netuney_sachar n
               where n.seq_netuney_sachar = v_seq_netuney_sachar_prev);

      if p_seq_bakasha_for_compare = p_seq_bakasha_for_insert then
        pk_salary_base.delete_old_data(v_seq_netuney_sachar_prev);
      end if;

      if v_count_rows = 1 or v_is_new_value_maskoret = 0 then
        return 0;
      end if;

    end if;

    return 1;
  end;
  -------------------------------------------------------
  function get_start_zakaut(p_seq_bakasha number) return date is
    v_date_start_zakaut date;
    v_seq_prisha        number;
  begin
    -- Get seq_bakasha
    select b.seq_prisha
      into v_seq_prisha
      from bakasha b
     where b.seq_bakasha = p_seq_bakasha;

    select max(v.date_start_zakaut)
      into v_date_start_zakaut
      from table(fn_obj_prisha_last_zakaut_arr(pk_select_function.fn_v_bakasha_last_zakaut(v_seq_prisha => v_seq_prisha))) v;

    return v_date_start_zakaut;
  exception
    when others then
      return null;
  end;
  --------------------------------------------------------
  procedure manage_actions(p_ld_protocol number, p_seq_bakasha number) is

    v_is_new_data                  number;
    v_is_before_payment_department number;
    v_current_action               number;
  begin
    if p_seq_bakasha is null then
      rollback;
      return;
    end if;

    select max(l.is_new_data)
      into v_is_new_data
      from ld_salary_base l
     where nvl(l.seq_ld_protocol, 0) = nvl(p_ld_protocol, 0)
       and l.seq_bakasha = p_seq_bakasha;

    if v_is_new_data = 0 then
      --Rollback!
      rollback;
      update ld_salary_base l
         set l.seq_bakasha = null, l.code_status_get = 4
       where nvl(l.seq_ld_protocol, 0) = nvl(p_ld_protocol, 0)
         and l.seq_bakasha = p_seq_bakasha;
      commit;
      return;

    elsif v_is_new_data = 1 then
      pk_prm_utils.insert_action_log_row(171,
                                         sysdate,
                                         0,
                                         null,
                                         null,
                                         null,
                                         null,
                                         null,
                                         p_seq_bakasha,
                                         null);
      commit;

      select v.code_action
        into v_current_action
        from v_bakasha_last_status v
       where v.seq_bakasha = p_seq_bakasha;

      --When the bakasha is in status 'wait to salary'
      if v_current_action is null or v_current_action = 146 then
        --insert action log
        pk_prm_utils.insert_actions_for_bakasha(p_seq_bakasha, 0);
      else

        v_is_before_payment_department := pk_prm_utils.is_action_bakash_bfor_specific(p_seq_bakasha,
                                                                                      119);
        --When the bakasha is after status 'wait to payment department'
        if v_is_before_payment_department = 0 then
          --Return the status to payment department
          pk_prm_utils.insert_action_log_row(114,
                                             sysdate,
                                             0,
                                             null,
                                             'התקבלו נתוני משכורת קובעת בממשק',
                                             null,
                                             null,
                                             null,
                                             p_seq_bakasha,
                                             null);
        end if;
        --  end if;
        --Commit!
        commit;
      end if;
    end if;
  end;
  --------------------------------------------------------
  procedure load_managment_id(p_ld_protocol              number,
                              p_seq_ld_mlm_salary        number,
                              p_seq_ld_chinuch_salary_01 number,
                              p_identity_number          number,
                              p_office                   number,
                              p_function_name            varchar2) is
    v_seq_bakasha_regila           number;
    v_seq_bakasha_for_update       number;
    v_seq_prisha                   number;
    v_code_status_get              number;
    v_is_get_new_date              number;
    v_is_bakasha_was_not_confirmed number;
    v_operation                    varchar2(1000);

  begin

    v_global_message := null;
    begin
      begin
        --Get seq bakasha
        select max(v.seq_bakasha), v.seq_prisha
          into v_seq_bakasha_regila, v_seq_prisha
          from v_bakasha_last_status v
          left join code_ezor_ovdim c
            on v.seq_ezor_ovdim = c.seq_ezor_ovdim
         where v.mispar_zehut = p_identity_number
           and c.code_misrad_maskret = p_office
           and v.code_sug_bakasha in (1, 14)
           and nvl(v.code_action, 0) not in (17, 100)
         group by v.seq_prisha;
      exception
        when no_data_found then
          update_ld_salary_base(p_ld_protocol,
                                p_seq_ld_mlm_salary,
                                p_seq_ld_chinuch_salary_01,
                                3);
          return;
      end;

      --Check if the regular bakasha was confirmed in payment department
      v_is_bakasha_was_not_confirmed := pk_prm_utils.is_bakasha_was_not_confirmed(v_seq_bakasha_regila,
                                                                                  2);
      if v_is_bakasha_was_not_confirmed = 1 then
        v_code_status_get        := 1;
        v_seq_bakasha_for_update := v_seq_bakasha_regila;
      else
        v_code_status_get        := 2;
        v_seq_bakasha_for_update := Open_new_bakasha(v_seq_prisha);
      end if;

      --update in netuney sachar table
      v_operation := 'begin :result := ' || p_function_name ||
                     '.update_netuney_sachar(' ||
                     nvl(p_seq_ld_mlm_salary, p_seq_ld_chinuch_salary_01) || ',' ||
                     v_seq_bakasha_regila || ',' ||
                     v_seq_bakasha_for_update || '); end;';
      execute immediate v_operation
        using out v_is_get_new_date;

    exception
      when others then
        v_code_status_get        := 5;
        v_seq_bakasha_for_update := null;
        v_global_message         := get_translate_message(Sqlerrm);
    end;

    update_ld_salary_base(p_ld_protocol,
                          p_seq_ld_mlm_salary,
                          p_seq_ld_chinuch_salary_01,
                          v_code_status_get,
                          v_seq_bakasha_for_update,
                          v_is_get_new_date);

  end;
  ------------------------------------------------------

end;
/

create or replace package body prm_system_copy.pk_select_function is
  -------------------------------------------------------------------  
  function fn_prisha_poresh_header(v_seq_prisha number)
    return obj_prisha_last_zakaut_arr is
    result obj_prisha_last_zakaut_arr;
  begin
    with t1 as
     (select b.seq_prisha,
             max(b."SEQ_BAKASHA_ZAKAUT") keep(dense_rank first order by pk_prm_utils.is_open_bakasha_prev(b.seq_bakasha, null)
             --desc
              )
             
              max_seq_bakaasha
        from table(fn_obj_prisha_last_zakaut_arr(pk_select_function.fn_v_bakasha_last_zakaut(v_seq_prisha => v_seq_prisha))) /*v_bakasha_last_zakaut*/ b
      
       where seq_prisha = v_seq_prisha
         and not exists (select 1
                from action_log a1
               where 1 = 1
                 and a1.code_action = 17
                 and a1.seq_bakasha = b.seq_bakasha)
       group by b.seq_prisha),
    ---כולל נתוני דרוג ודרגה
    t2 as
     (select t1.seq_prisha,
             t1.max_seq_bakaasha,
             max(d.code_darga) keep(dense_rank first order by nvl(taarich_me, sysdate) desc) CODE_DARGA,
             max(d.code_derug) keep(dense_rank first order by nvl(taarich_me, sysdate) desc) code_derug
        from t1
        left join darga_vederug_tik d
          on t1.max_seq_bakaasha = d.seq_bakasha
       group by t1.seq_prisha, t1.max_seq_bakaasha)
    
    --- נתוני זכאות ודרגה לבקשה האחרונה
    select /*+ no_merge(v) ordered */
     obj_prisha_last_zakaut(v."SEQ_PRISHA",
                            v."SEQ_BAKASHA",
                            v."CODE_SUG_BAKASHA",
                            v."SEQ_BAKASHA_TAARICH_PRISHA",
                            v."SEQ_BAKASHA_CODE_SEIF_PRISHA",
                            v."SEQ_BAKASHA_ZAKAUT",
                            v."TAARICH_PRISHA",
                            v."CODE_SEIF_PRISHA",
                            v."DATE_START_ZAKAUT",
                            v."DATE_END_ZAKAUT",
                            v."ACHUZ_KIZBA_SOFI",
                            v."CHELKIYUT_SOFIT",
                            v."IS_ZAKAI_LMAANAK",
                            v."ODEF",
                            v."IS_EXIST_ANOTHER_JOB",
                            t2.CODE_DARGA,
                            t2.code_derug)
      bulk collect
      into result
      from t2
      join (select *
              from table(fn_obj_prisha_last_zakaut_arr(pk_select_function.fn_v_bakasha_last_zakaut(v_seq_prisha => v_seq_prisha))) /*v_bakasha_last_zakaut*/ v
             where v."SEQ_PRISHA" = v_seq_prisha) v
        on v.SEQ_BAKASHA = t2.max_seq_bakaasha
       and v."SEQ_PRISHA" = v_seq_prisha
    --    and v."SEQ_PRISHA" = t2.seq_prisha
    ;
    return result;
  end;
  -------------------------------------------------------------------  
  function fn_v_bakasha_last_zakaut(v_seq_prisha  number := null,
                                    v_seq_bakasha number := null /*,
                                                                        p_bakasha_seq_arr ncard_ntt := null*/)
    return obj_prisha_last_zakaut_arr is
    result            obj_prisha_last_zakaut_arr;
    v_bakasha_seq_arr ncard_ntt;
  begin
    if V_bakasha_seq_arr is null then
      select b2.seq_bakasha
        bulk collect
        into v_bakasha_seq_arr
        from PRISHA p, bakasha b, poresh r, prisha p2, bakasha b2
       where 1 = 1
         and b.seq_prisha = nvl(v_seq_prisha, b.seq_prisha)
         and b.seq_bakasha = nvl(v_seq_bakasha, b.seq_bakasha)
         and b.seq_prisha = p.seq_prisha
         and p.seq_poresh = r.porshim_seq
         and p2.seq_poresh = r.porshim_seq
         and b2.seq_prisha = p2.seq_prisha
      -- and b.seq_bakasha between 88178 and 88300
      --in(88178,88190,88170,88171,88192)    
      ;
    else
      v_bakasha_seq_arr := V_bakasha_seq_arr;
    end if;
  
    select obj_prisha_last_zakaut(seq_prisha,
                                  seq_bakasha,
                                  code_sug_bakasha,
                                  seq_bakasha_taarich_prisha,
                                  seq_bakasha_code_seif_prisha,
                                  seq_bakasha_zakaut,
                                  taarich_prisha,
                                  code_seif_prisha,
                                  date_start_zakaut,
                                  date_end_zakaut,
                                  achuz_kizba_sofi,
                                  chelkiyut_sofit,
                                  is_zakai_lmaanak,
                                  odef,
                                  is_exist_another_job,
                                  null,
                                  null)
      bulk collect
      into result
      from (with b as (select b.seq_prisha, b.seq_bakasha
                         from (select *
                                 from bakasha
                                where 1 = 1
                                  and exists
                                (select 1
                                         from table(ncard(v_bakasha_seq_arr))
                                        where column_value = seq_bakasha)) b
                         left join action_log a1
                           on a1.seq_bakasha = b.seq_bakasha
                          and a1.code_action = 17
                        where a1.seq_action_log is null
                          and b.code_sug_bakasha in (1, 3, 5)), c as (select b.seq_prisha,
                                                                             b.seq_bakasha
                                                                        from (select *
                                                                                from bakasha
                                                                               where 1 = 1
                                                                                 and exists
                                                                               (select 1
                                                                                        from table(ncard(v_bakasha_seq_arr))
                                                                                       where column_value =
                                                                                             seq_bakasha)) b
                                                                        left join code_sug_bakasha s
                                                                          on s.code_sug_bakasha =
                                                                             b.code_sug_bakasha
                                                                        left join action_log a1
                                                                          on a1.seq_bakasha =
                                                                             b.seq_bakasha
                                                                         and a1.code_action = 17
                                                                       where a1.seq_action_log is null
                                                                         and nvl(s.code_merge_bakasha,
                                                                                 0) = 1), d as (select b.seq_prisha,
                                                                                                       b.seq_bakasha
                                                                                                  from (select *
                                                                                                          from bakasha
                                                                                                         where 1 = 1
                                                                                                           and exists
                                                                                                         (select 1
                                                                                                                  from table(ncard(v_bakasha_seq_arr))
                                                                                                                 where column_value =
                                                                                                                       seq_bakasha)) b
                                                                                                  left join netuney_tik_mechushavim n
                                                                                                    on b.seq_bakasha =
                                                                                                       n.seq_bakasha
                                                                                                   and n.code_department = 2
                                                                                                   and n.mispar_misra = 0
                                                                                                  left join action_log a1
                                                                                                    on a1.seq_bakasha =
                                                                                                       b.seq_bakasha
                                                                                                   and a1.code_action = 17
                                                                                                 where a1.seq_action_log is null
                                                                                                   and n.seq_netuney_tik_mechushavim is not null), e as (select a.seq_prisha,
                                                                                                                                                                a.seq_bakasha,
                                                                                                                                                                a.code_sug_bakasha,
                                                                                                                                                                max(b.seq_bakasha) seq_bakasha_taarich_prisha,
                                                                                                                                                                max(c.seq_bakasha) seq_bakasha_code_seif_prisha,
                                                                                                                                                                a.seq_bakasha seq_bakasha_zakaut
                                                                                                                                                           from (select *
                                                                                                                                                                   from bakasha
                                                                                                                                                                  where 1 = 1
                                                                                                                                                                    and exists
                                                                                                                                                                  (select 1
                                                                                                                                                                           from table(ncard(v_bakasha_seq_arr))
                                                                                                                                                                          where column_value =
                                                                                                                                                                                seq_bakasha)) a
                                                                                                                                                           left join b
                                                                                                                                                             on a.seq_prisha =
                                                                                                                                                                b.seq_prisha
                                                                                                                                                            and a.seq_bakasha >
                                                                                                                                                                b.seq_bakasha
                                                                                                                                                           left join c
                                                                                                                                                             on a.seq_prisha =
                                                                                                                                                                c.seq_prisha
                                                                                                                                                            and a.seq_bakasha >
                                                                                                                                                                c.seq_bakasha
                                                                                                                                                          where a.code_sug_bakasha in (19,
                                                                                                                                                                                       20)
                                                                                                                                                          group by a.seq_prisha,
                                                                                                                                                                   a.seq_bakasha,
                                                                                                                                                                   a.code_sug_bakasha), f as (select a.seq_prisha,
                                                                                                                                                                                                     a.seq_bakasha,
                                                                                                                                                                                                     a.code_sug_bakasha,
                                                                                                                                                                                                     max(b.seq_bakasha) seq_bakasha_taarich_prisha,
                                                                                                                                                                                                     max(c.seq_bakasha) seq_bakasha_code_seif_prisha,
                                                                                                                                                                                                     max(d.seq_bakasha) seq_bakasha_zakaut
                                                                                                                                                                                                from (select *
                                                                                                                                                                                                        from bakasha
                                                                                                                                                                                                       where 1 = 1
                                                                                                                                                                                                         and exists
                                                                                                                                                                                                       (select 1
                                                                                                                                                                                                                from table(ncard(v_bakasha_seq_arr))
                                                                                                                                                                                                               where column_value =
                                                                                                                                                                                                                     seq_bakasha)) a
                                                                                                                                                                                                left join code_sug_bakasha s
                                                                                                                                                                                                  on s.code_sug_bakasha =
                                                                                                                                                                                                     a.code_sug_bakasha
                                                                                                                                                                                                left join b
                                                                                                                                                                                                  on a.seq_prisha =
                                                                                                                                                                                                     b.seq_prisha
                                                                                                                                                                                                 and a.seq_bakasha >=
                                                                                                                                                                                                     b.seq_bakasha
                                                                                                                                                                                                left join c
                                                                                                                                                                                                  on a.seq_prisha =
                                                                                                                                                                                                     c.seq_prisha
                                                                                                                                                                                                 and a.seq_bakasha >=
                                                                                                                                                                                                     c.seq_bakasha
                                                                                                                                                                                                left join d
                                                                                                                                                                                                  on a.seq_prisha =
                                                                                                                                                                                                     d.seq_prisha
                                                                                                                                                                                                 and a.seq_bakasha >=
                                                                                                                                                                                                     d.seq_bakasha
                                                                                                                                                                                               where (s.code_merge_bakasha is null and
                                                                                                                                                                                                     a.code_sug_bakasha not in (19,
                                                                                                                                                                                                                                 20))
                                                                                                                                                                                                  or a.code_sug_bakasha in (13,
                                                                                                                                                                                                                            14)
                                                                                                                                                                                               group by a.seq_prisha,
                                                                                                                                                                                                        a.seq_bakasha,
                                                                                                                                                                                                        a.code_sug_bakasha), g as (select *
                                                                                                                                                                                                                                     from e
                                                                                                                                                                                                                                   union all
                                                                                                                                                                                                                                   select *
                                                                                                                                                                                                                                     from f
                                                                                                                                                                                                                                   union all
                                                                                                                                                                                                                                   select b.seq_prisha,
                                                                                                                                                                                                                                          b.seq_bakasha,
                                                                                                                                                                                                                                          b.code_sug_bakasha,
                                                                                                                                                                                                                                          b.seq_bakasha      seq_bakasha_taarich_prisha,
                                                                                                                                                                                                                                          b.seq_bakasha      seq_bakasha_code_seif_prisha,
                                                                                                                                                                                                                                          b.seq_bakasha      seq_bakasha_zakaut
                                                                                                                                                                                                                                     from (select *
                                                                                                                                                                                                                                             from bakasha
                                                                                                                                                                                                                                            where 1 = 1
                                                                                                                                                                                                                                              and exists
                                                                                                                                                                                                                                            (select 1
                                                                                                                                                                                                                                                     from table(ncard(v_bakasha_seq_arr))
                                                                                                                                                                                                                                                    where column_value =
                                                                                                                                                                                                                                                          seq_bakasha)) b
                                                                                                                                                                                                                                    where b.seq_bakasha not in
                                                                                                                                                                                                                                          (select seq_bakasha
                                                                                                                                                                                                                                             from e)
                                                                                                                                                                                                                                      and b.seq_bakasha not in
                                                                                                                                                                                                                                          (select seq_bakasha
                                                                                                                                                                                                                                             from f))
             select distinct g."SEQ_PRISHA",
                             g."SEQ_BAKASHA",
                             g."CODE_SUG_BAKASHA",
                             g."SEQ_BAKASHA_TAARICH_PRISHA",
                             g."SEQ_BAKASHA_CODE_SEIF_PRISHA",
                             g."SEQ_BAKASHA_ZAKAUT",
                             r_taarich_prisha.taarich_prisha,
                             r_code_seif_prisha.code_seif_prisha,
                             n.date_start_zakaut,
                             n.date_end_zakaut,
                             n.achuz_kizba_sofi,
                             n.chelkiyut_sofit,
                             n.is_zakai_lmaanak,
                             (case
                               when n.odef_sherut_chodashim > 0 or
                                    n.odef_sherut_yamim > 0 then
                                1
                               else
                                0
                             end) as odef,
                             decode(n1.seq_netuney_tik_mechushavim,
                                    null,
                                    0,
                                    1) is_exist_another_job
               from g
               left join bakasha_regila r_taarich_prisha
                 on g.seq_bakasha_taarich_prisha =
                    r_taarich_prisha.seq_bakasha
               left join bakasha_regila r_code_seif_prisha
                 on g.seq_bakasha_code_seif_prisha =
                    r_code_seif_prisha.seq_bakasha
               left join netuney_tik_mechushavim n
                 on g.seq_bakasha_zakaut = n.seq_bakasha
                and n.code_department = 2
                and n.mispar_misra = 0
               left join action_log a1
                 on a1.seq_bakasha = g.seq_bakasha
                and a1.code_action = 17
               left join netuney_tik_mechushavim n1
                 on g.seq_bakasha_zakaut = n1.seq_bakasha
                and n1.code_department = 2
                and n1.mispar_misra = 1);
  
  
    return result;
  end;
  -------------------------------------------------------------------  

  function fn_v_last_address(v_seq_poresh number, v_seq_bakasha number)
    return obj_last_address_arr is
    result obj_last_address_arr;
  begin
  
    with a1 as
    --Get last address by bakasha for poresh and for bney_mishpacha
     (select distinct a.seq_poresh,
                      a.seq_bney_mishpacha,
                      a.seq_bakasha,
                      first_value(a.seq_address) over(partition by a.seq_poresh, a.seq_bney_mishpacha, a.seq_bakasha order by a.code_address desc, a.seq_address desc) max_seq_address
        from address a
       where a.seq_bakasha = v_seq_bakasha
         and a.seq_poresh = v_seq_poresh),
    a2 as
    --Get last address for poresh and for bney_mishpacha
     (select distinct a.seq_poresh,
                      a.seq_bney_mishpacha,
                      first_value(a.seq_address) over(partition by a.seq_poresh, a.seq_bney_mishpacha order by a.code_address desc, a.seq_address desc) max_seq_address
        from address a
       where a.seq_poresh = v_seq_poresh),
    t as
    --Get poresh for every bakasha
     (select b1.seq_bakasha, p1.seq_poresh
        from bakasha b1
        left join prisha p1
          on b1.seq_prisha = p1.seq_prisha
       where b1.seq_bakasha = v_seq_bakasha
         and p1.seq_poresh = v_seq_poresh),
    t1 as
    --Join poersh to last address
     (select t.seq_bakasha,
             t.seq_poresh,
             null as seq_bney_mishpacha,
             --Get the last address that join to the bakasha, if it's exist.
             --Else, Get the last address that join to the poresh
             nvl(a1.max_seq_address, a2.max_seq_address) max_seq_address
        from t
      --Join by bakasha
        left join a1
          on a1.seq_bakasha = t.seq_bakasha
         and a1.seq_poresh = t.seq_poresh
      --Join by poresh
        left join a2
          on a2.seq_poresh = t.seq_poresh),
    t2 as
    --Join bney mishpacha to last address
     (select t.seq_bakasha,
             null,
             b2.seq_bney_mishpacha,
             --Get the last address that join to the bakasha, if it's exist.
             --Else, Get the last address that join to the bney_mishpacha
             nvl(a1.max_seq_address, a2.max_seq_address) max_seq_address
        from bney_mishpacha b2
        left join t
          on t.seq_poresh = b2.seq_porshim
      --Join by bakasha
        left join a1
          on a1.seq_bakasha = t.seq_bakasha
         and a1.seq_bney_mishpacha = b2.seq_bney_mishpacha
      --Join by poresh
        left join a2
          on a2.seq_bney_mishpacha = b2.seq_bney_mishpacha
       where b2.seq_porshim = v_seq_poresh),
    --Union poresh and bney_mishpacha
    u as
     (select * from t1 union select * from t2)
    --Select the other fields from address
    select /*+ no_merge(v) ordered */
     obj_last_address(u.seq_poresh,
                      u.seq_bney_mishpacha,
                      t.street || ' ' || case
                        when t.apartment is null or t.apartment = 0 THEN
                         trim(to_char(t.house, 'B9999999999'))
                        when t.house is null then
                         '  /' || trim(to_char(t.apartment, 'B9999999999'))
                        else
                         trim(to_char(t.house, 'B9999999999')) || '/' ||
                         trim(to_char(t.apartment, 'B9999999999'))
                      end,
                      t.code_city,
                      t.mikud,
                      t.code_address,
                      t.street,
                      t.house,
                      t.apartment,
                      t.entrance,
                      t.house_letter,
                      u.seq_bakasha)
      bulk collect
      into result
      from u
      left join address t
        on t.seq_address = u.max_seq_address;
    return result;
  end;
  -------------------------------------------------------------------  
  function fn_v_bakasha_last_status(p_code_user      number := null,
                                    p_code_action    number default null,
                                    p_code_action_no number default null,
                                    p_is_exteral     number default null,
                                    p_zehut          number default null)
  
   return obj_last_status_arr is
    v_bakasha_seq_arr obj_last_status_arr;
  begin
    if V_bakasha_seq_arr is null then
      select /*+ ordered */
             obj_last_status(b.seq_bakasha,
                             b.seq_prisha,
                             p.seq_poresh,
                             po.mispar_zehut,
                             b.seq_bney_mishpacha,
                             l1.seq_action_log)
        bulk collect
        into v_bakasha_seq_arr
        from bakasha b
        left join (select max(l.seq_action_log) seq_action_log,
                          l.seq_bakasha
                     from action_log l
                     left join code_action c
                       on l.code_action = c.code_action
                    where c.is_status = 1
                    group by l.seq_bakasha) max_action_log
          on b.seq_bakasha = max_action_log.seq_bakasha
        left join action_log l1
          on l1.seq_action_log = max_action_log.seq_action_log
        left join code_action c1
          on c1.code_action = l1.code_action
        left join prisha p
          on b.seq_prisha = p.seq_prisha
        left join poresh po
          on p.seq_poresh = po.porshim_seq
       where l1.code_user_to_internal =
             nvl(p_code_user, l1.code_user_to_internal)
         and l1.code_action = nvl(p_code_action, l1.code_action)
         and l1.code_action <> nvl(p_code_action_no, 0)
         and c1.is_external = nvl(p_is_exteral, c1.is_external)
         and po.mispar_zehut = nvl(p_zehut, po.mispar_zehut)
      
      ;
    else
      v_bakasha_seq_arr := V_bakasha_seq_arr;
    end if;
    return v_bakasha_seq_arr;
  end;
  ----------------------------------
  function fn_v_last_mazav_mishpahti(p_seq_poresh         number default null,
                                     p_seq_bakasha        number default null,
                                     p_seq_bney_mishpacha number default null)
    return obj_last_mazav_mishpahti_arr is
    result obj_last_mazav_mishpahti_arr;
  begin
    --Select the other fields from address
    select /*+ no_merge(v) ordered */
     obj_last_mazav_mishpahti(seq_mazav_mishpachti,
                              seq_poresh,
                              code_mazav_mishpachti,
                              date_mazav_mishpachti,
                              date_update,
                              code_user,
                              seq_bakasha,
                              seq_bney_mishpacha)
      bulk collect
      into result
      from mazav_mishpachti m
      WHERE  
      (NVL(m.SEQ_BAKASHA,0) <= p_seq_bakasha OR p_seq_bakasha=0)
      AND  (( p_seq_poresh=0  AND  m.SEQ_BNEY_MISHPACHA =  p_seq_bney_mishpacha) 
        or ( p_seq_bney_mishpacha =0  and   m.SEQ_PORESH=p_seq_poresh )) 
      ORDER BY DATE_MAZAV_MISHPACHTI desc nulls last,seq_mazav_mishpachti desc
      fetch first 1 row only;
     /*where m.seq_bakasha = nvl(p_seq_bakasha, m.seq_bakasha)
     and m.seq_bney_mishpacha = nvl(p_seq_bney_mishpacha,m.seq_bney_mishpacha)
     and m.seq_poresh = nvl(p_seq_bakasha,m.seq_poresh);*/
    return result;
  end;

end;
/

create or replace package body prm_system_copy.pk_sf_requests is

const_code_source_CRM constant number := 24;

l_count                                               number;
v_is_gimla_number_required                            number;
v_is_only_poresh                                      number;
v_is_only_sheer                                       number;
v_is_to_all_prishot                                   number;
v_is_document_required                                number;
v_code_sug_bakasha                                    number;
v_code_bakasha_detail                                 number;
v_created_date                                        varchar2(19);
v_seq_bakasha                                         number;
v_seq_bakasha_first                                   number;
v_seq_bakasha_string                                  varchar2(30);
v_seq_poresh                                          number;
v_seq_poresh_beprisha                                 number;
v_seq_sheer                                           number;
v_mispar_zehut                                        number;
v_seq_ezor_ovdim                                      number;
v_code_action                                         number;
v_code_action_hakpaa                                  number;
v_seq_bakasha_hakpaa                                  number;
v_code_role                                           number;
v_code_department                                     number;
v_seq_action_log                                      number;
v_seq_document                                        number;
v_teur_subject_crm                                    varchar2(50);

v_request_name                                        varchar2(50);
v_SFID                                                varchar2(20);
v_person_id                                           varchar2(50);
v_subject_code                                        varchar2(50);
v_gimla_number                                        varchar2(50);
v_bank_number                                         number;
v_bank_branch                                         number;
v_code_sug_workflow                                   number;
v_mobile                                              varchar2(50);

v_error_code                                          number;
v_error_text                                          varchar2(3000);
v_check_result1                                       number;
v_check_result2                                       number;
v_errors                                              clob;
v_success_number                                      number;
v_error_number                                        number;
v_title                                               varchar2(2000);
v_report                                              varchar2(2000);
v_err                                                 boolean;
v_seq_ld_requests_crm_errors                          number;
v_cursor_errors                                       clob;
v_record_json                                         clob;
--v_error_text                                        clob;
