v_result_char                                         varchar2(1000);
v_seq_bakasha_error                                   number;
v_is_hishtafut_leguf                                   number;

function add_error_text(p_error_text varchar2, p_field_name varchar2) return varchar2 is

  f_v_error_text varchar2(2000);
begin
  if v_error_text is null then
    f_v_error_text := v_request_name || '(' || v_SFID || ')  '  ||  p_field_name || ' -- '|| p_error_text || '(' || to_char(v_error_code) || ')' || ' -- ';
  else
    f_v_error_text := v_error_text   || chr(10) || p_error_text || '(' || to_char(v_error_code) || ')' || ' -- ';
  end if;
  return f_v_error_text;
end;


procedure add_row_to_errors(p_i number) is
  begin
  if v_error_text is not null  then
 
  v_errors := v_errors || '<br />' || v_error_text;
  --dbms_output.put_line(v_error_text);
  v_error_number := v_error_number + 1;
  insert into Ld_Requests_Crm_Errors t
      (t.request_name,
       t.Request_URL,
       t.created_date,
       t.person_id,
       t.request_source,
       t.subject_code,
       t.description,
       t.benefit_number,
       t.bank_number,
       t.bank_branch,
       t.account_number,
       t.street,
       t.street_number,
       t.entrance,
       t.apartment_number,
       t.city_code,
       t.postal_code,
       t.email,
       t.mobile,
       t.file_url,
       t.sfid,
       t.ld_date,
       t.error_text,
       t.seq_ld_requests_crm_errors
)
VALUES(
apex_json.get_varchar2(p_path => 'records[%d].Name', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].attributes.url', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].CreatedDate', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Pensioner__r.GIM_PersonIdNumber__pc', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Source__c', p0 => p_i),
