procedure check_sf_requests(i integer) is
  v_is_one_poresh number;
  v_house_number varchar(20);
  begin
v_error_code := 0;
v_error_text := '';
v_request_name := apex_json.get_varchar2(p_path => 'records[%d].Name', p0 => i);
v_SFID := apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => i);

--PersonIdNumber
v_person_id := apex_json.get_varchar2(p_path => 'records[%d].Pensioner__r.GIM_PersonIdNumber__pc', p0 => i);

if v_person_id = '078715216' then --רימונד מרלי
  v_error_code := 1000;
  v_error_text := add_error_text('Criminale!!','Pensioner__r.GIM_PersonIdNumber__pc')
  ; 
  end if;
if v_person_id = '076629237' then --מיכאל כהן
  v_error_code := 1000;
  v_error_text := add_error_text('Criminale!!','Pensioner__r.GIM_PersonIdNumber__pc')
  ; 
  end if; 
/*if v_person_id = '068061563' then  --יהודה אביטל
--הפורש נפטר
  v_error_code := 1000;
  v_error_text := add_error_text('Criminale!!','Pensioner__r.GIM_PersonIdNumber__pc')
  ; 
  end if;*/
select validate_conversion(v_person_id as number) into v_check_result1 from dual;
select (case when not exists(
  select p.mispar_zehut
  from poresh p
  where p.mispar_zehut = to_number(v_person_id))
  and not exists(
  select b.mispar_zehut_ben_mishpacha
  from bney_mishpacha b
  where b.mispar_zehut_ben_mishpacha = to_number(v_person_id)
  --and b.code_relative is null
  )
  then 0 else 1 end)
    into v_check_result2 from dual;
if v_person_id is null then
  v_error_code := 10;
  v_error_text := add_error_text('Pensioner ID is required','Pensioner__r.GIM_PersonIdNumber__pc')
  ;
end if;
if v_check_result1 = 0 then
  v_error_code := 20;
  v_error_text := add_error_text('Pensioner ID is not numeric','Pensioner__r.GIM_PersonIdNumber__pc')
  ;
end if;
if v_check_result2 = 0 then
  v_error_code := 30;
  v_error_text := add_error_text('Pensioner ID does not exist in MAPAM ','Pensioner__r.GIM_PersonIdNumber__pc')
  ;
end if;

--SubjectCode
if v_error_text is null then
v_subject_code := apex_json.get_varchar2(p_path => 'records[%d].RequestSubject__r.APIName__c', p0 => i);
if v_subject_code is null then
  v_error_code := 110;
  v_error_text := add_error_text('Code Subject is required','RequestSubject__r.APIName__c')
  ;
end if;
select validate_conversion(v_subject_code as number) into v_check_result1 from dual;
if v_check_result1 = 0 then
  v_error_code := 120;
  v_error_text := add_error_text('Code Subject is not numeric','RequestSubject__r.APIName__c')
  ;
else
  select (case when not exists(
  select p.code_subject_crm
  from perm_subject_crm_sug_bakasha p
  where p.code_subject_crm = to_number(nvl(v_subject_code,0)))
  then 0 else 1 end)
  into v_check_result2 from dual;
  if v_check_result2 = 0 then
    v_error_code := 130;
    v_error_text := add_error_text('Code Subject does not exist','RequestSubject__r.APIName__c')
    ;
  end if;
end if;
end if;

--BenefitNumber
if v_error_text is null then
v_gimla_number := apex_json.get_varchar2(p_path => 'records[%d].Eligibility__r.Retirement__r.BenefitNumber__c', p0 => i);

select p.code_sug_bakasha, p.is_document_required, p.is_gimla_number_required,
       p.only_poresh, p.only_sheer, p.code_bakasha_detail, p.is_to_all_prishot
  into v_code_sug_bakasha,
       v_is_document_required,
       v_is_gimla_number_required,
       v_is_only_poresh,
       v_is_only_sheer,
       v_code_bakasha_detail,
       v_is_to_all_prishot
from perm_subject_crm_sug_bakasha p
where p.code_subject_crm = to_number(v_subject_code);

select validate_conversion(v_gimla_number as number) into v_check_result1 from dual;
if v_gimla_number is not null then select (case when not exists(
  select pr.seq_prisha
  from prisha pr
  left join poresh p on p.porshim_seq = pr.seq_poresh
  left join bney_mishpacha b on b.seq_porshim = pr.seq_poresh
  where pr.gimla_number = to_number(v_gimla_number)
  and (p.mispar_zehut = to_number(v_person_id) or
       b.mispar_zehut_ben_mishpacha = to_number(v_person_id)))
  then 0 else 1 end)
  into v_check_result2 from dual;

if v_check_result2 = 0 then
  v_error_code := 130;
  v_error_text := add_error_text('Retirement does not exist: Pensioner ID - ' ||
  pk_hilan_prd.rpad_blanks(to_number(v_person_id),9) || ' ; Benefit Number - ' || to_char(v_gimla_number) ,'Eligibility__r.Retirement__r.BenefitNumber__c')
  ;
end if;
end if;

if v_is_gimla_number_required = 1 then
   if v_gimla_number is null then
     select count(*)
      into v_is_one_poresh
      from prisha pr
      left join poresh p on
      p.porshim_seq = pr.seq_poresh
      where p.mispar_zehut = to_number(v_person_id);
      if v_is_only_poresh = 1 and v_is_one_poresh > 1 then
        v_error_code := 110;
        v_error_text := add_error_text('Benefit Number is required','Eligibility__r.Retirement__r.BenefitNumber__c');
      else
        select pr.gimla_number
        into v_gimla_number
        from prisha pr
        left join poresh p on
        p.porshim_seq = pr.seq_poresh
        where p.mispar_zehut = to_number(v_person_id);
      end if;
  end if;
end if;

if v_check_result1 = 0 then
  v_error_code := 120;
  v_error_text := add_error_text('BenefitNumber is not numeric','Eligibility__r.Retirement__r.BenefitNumber__c')
  ;
end if;
/*else
v_gimla_number := null;*/
end if;

--FileLink
if v_is_document_required = 1 then
if apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => i) is null then
  v_error_code := 210;
  v_error_text := add_error_text('Document is required','FileLink__c');
end if;
end if;


if v_error_text is null then
if apex_json.get_varchar2(p_path => 'records[%d].Source__c', p0 => i) is not null then
   select validate_conversion(apex_json.get_varchar2(p_path => 'records[%d].Source__c', p0 => i) as number) into v_check_result1 from dual;
   if v_check_result1 = 0 then v_error_text := add_error_text('Source is not numeric','Source__c');
end if;
end if;
if apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => i) is not null then
   select validate_conversion(apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => i) as number) into v_check_result1 from dual;
   if v_check_result1 = 0 then v_error_text := add_error_text('Bank number is not numeric','Bank__r.BankNumber__c');
end if;
end if;
if apex_json.get_varchar2(p_path => 'records[%d].BankBranch__r.BranchNumber__c', p0 => i) is not null then
   select validate_conversion(apex_json.get_varchar2(p_path => 'records[%d].BankBranch__r.BranchNumber__c', p0 => i) as number) into v_check_result1 from dual;
   if v_check_result1 = 0 then v_error_text := add_error_text('Bank Branch number is not numeric','BankBranch__r.BranchNumber__c');
end if;
end if;
if apex_json.get_varchar2(p_path => 'records[%d].BankAccountNumber__c', p0 => i) is not null then
   select validate_conversion(apex_json.get_varchar2(p_path => 'records[%d].BankAccountNumber__c', p0 => i) as number) into v_check_result1 from dual;
   if v_check_result1 = 0 then v_error_text := add_error_text('Bank Account number is not numeric','BankAccountNumber__c');
end if;
end if;
if apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i) is not null then  
   select apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i)
   --regexp_replace(apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i),'\D')
   into v_house_number
   from dual;                    
   select validate_conversion(apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i) as number) into v_check_result1 from dual;
   if v_house_number is null then v_check_result1 := 0; end if;
   if v_check_result1 = 0 then v_error_text := add_error_text('Street number is not numeric','StreetNumber__c');
end if;
end if;
/*if apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i) is not null then
   select validate_conversion(apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i) as number) into v_check_result1 from dual;
   if v_check_result1 = 0 then v_error_text := add_error_text('Street number is not numeric','StreetNumber__c');
end if;*/
if apex_json.get_varchar2(p_path => 'records[%d].ApartmentNumber__c', p0 => i) is not null then
   select validate_conversion(apex_json.get_varchar2(p_path => 'records[%d].ApartmentNumber__c', p0 => i) as number) into v_check_result1 from dual;
   if v_check_result1 = 0 then v_error_text := add_error_text('Apartment number is not numeric','ApartmentNumber__c');
end if;
end if;
if apex_json.get_varchar2(p_path => 'records[%d].City__r.CityCode__c', p0 => i) is not null then
   select validate_conversion(apex_json.get_varchar2(p_path => 'records[%d].City__r.CityCode__c', p0 => i) as number) into v_check_result1 from dual;
   if v_check_result1 = 0 then v_error_text := add_error_text('City Code is not numeric','City__r.CityCode__c');
end if;
end if;
if apex_json.get_varchar2(p_path => 'records[%d].Email__c', p0 => i) is null
   and apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => i) is null
   and v_subject_code = '169' then
       v_error_text := add_error_text('The email was not sent','Email__c');
end if;
if apex_json.get_varchar2(p_path => 'records[%d].Mobile__c', p0 => i) is null
   and apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => i) is null
   and v_subject_code = '175' then
       v_error_text := add_error_text('The solular number was not sent','Email__c');
end if;
if v_subject_code = '196' then
begin  
  select v.code_action, v.seq_bakasha
  into v_code_action_hakpaa, v_seq_bakasha_hakpaa
  from v_bakasha_last_status v
  where v.code_sug_bakasha = 1
  and v.gimla_number = v_gimla_number
  and v.seq_bakasha = 
  (select max (v1.seq_bakasha)
  from v_bakasha_last_status v1
  where v1.code_sug_bakasha = 1
  and v1.gimla_number = v.gimla_number
  );
exception
when others then
      v_code_action_hakpaa := 999;
end;
  if v_code_action_hakpaa not in (98,132)
  then
       v_error_text := add_error_text('The case status doesn"t fit for freeze',' ');
  elsif v_code_action_hakpaa = 132 then
       pk_prm_utils.insert_action_log_row(98,sysdate,0,0,'הקדמת הקפאה',null,null,null,v_seq_bakasha_hakpaa,null);
  end if;
end if;
end if;
end;

procedure find_gimlay is
  v_e_text            varchar(100);
  begin
    v_seq_poresh     := null;
    v_seq_sheer      := null;
    v_mispar_zehut   := null;
    v_seq_ezor_ovdim := null;
    

    --if v_code_sug_bakasha <> 30 then
    begin
      if v_is_only_sheer <> 1 then
      select p.mispar_zehut, p.porshim_seq, pr.seq_ezor_ovdim
        into v_mispar_zehut, v_seq_poresh, v_seq_ezor_ovdim
      from poresh p, prisha pr
      where p.porshim_seq = pr.seq_poresh
      and (v_gimla_number is not null and pr.gimla_number = v_gimla_number or v_gimla_number is null)
      and p.mispar_zehut = to_number(v_person_id)
      and pr.seq_ezor_ovdim not in (
155,
158,
13,
154,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149
)
      and rownum = 1;
      v_seq_poresh_beprisha := v_seq_poresh;
      end if;
    exception
    when others then
      v_mispar_zehut := 0;
      v_seq_poresh := null;
    end;
    --end if;

    if nvl(v_mispar_zehut,0) = 0 or v_subject_code = 31 then
    begin
      if v_is_only_poresh <> 1 then
      select b.mispar_zehut_ben_mishpacha, b.seq_bney_mishpacha, b.seq_porshim, pr.seq_ezor_ovdim
        into v_mispar_zehut, v_seq_sheer, v_seq_poresh_beprisha, v_seq_ezor_ovdim
      from bney_mishpacha b, prisha pr
      where b.seq_porshim = pr.seq_poresh
      and b.mispar_zehut_ben_mishpacha = to_number(v_person_id)
      and nvl(b.code_relative,0) <> 0
      and (v_gimla_number is not null and pr.gimla_number = v_gimla_number or v_gimla_number is null)
      and pr.seq_ezor_ovdim not in (
155,
158,
13,
154,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149,
13
)
      and rownum = 1;
      --if v_seq_ezor_ovdim = 10154 and v_code_sug_bakasha = 15 then v_code_sug_workflow := 25; end if;

      end if;
    exception
    when others then
      v_mispar_zehut := 0;
      v_seq_sheer := null;
    end;
    end if;
    if v_seq_poresh is null and v_seq_sheer is null then
      v_e_text := add_error_text('אין גמלאי פעיל תואם לפניה', v_request_name);
      return;
    end if;
end;

procedure add_document_and_status(p_i number, p_add_document number default 1) is
begin
    if v_seq_bakasha <> 0 then
      
    --if v_seq_ezor_ovdim = 10154 and v_code_sug_bakasha = 15 then v_code_sug_workflow := 25; end if;

    begin
    if v_code_sug_bakasha = 35 and length(nvl(pk_hilan.get_telephone(v_mobile,1),'0'))>10
       then v_code_action := 136;
    elsif not(v_code_sug_bakasha = 27 and v_code_bakasha_detail = 191) then
      if v_code_action is null then
        select w.next_action
        into v_code_action
        from workflow w
        where w.code_sug_workflow = v_code_sug_workflow
        and w.order_wf = 1;
      end if;
    else
      v_code_action := 98;
    end if;
    exception
    when others then
      if v_subject_code = 196 then 
        v_code_action := 19;
      else
        v_code_action := 172;
      end if;
    end;

    pk_prm_utils.insert_action_log_row(v_code_action,
                                       sysdate,
                                       0,
                                       case when v_subject_code = 196 then 168 /*נתב תיקים פיזי*/ else null end,
                                       'פניית CRM ' || 
                                       case when v_code_sug_bakasha = 35 and v_code_action = 136 then
                                       ', ' || 'מספר בינלאומי - לא נשלח לחילן'
                                            else ' '
                                       end,
                                       null,
                                       null,
                                       null,
                                       v_seq_bakasha,
                                       null);

     if v_code_sug_bakasha = 35 and v_code_action = 136 then  
       pk_prm_utils.insert_action_log_row(98, sysdate, 0, null, 'פניית CRM ' ||  ', ' || 'מספר בינלאומי - לא נשלח לחילן',
                                                       null, null,  null, v_seq_bakasha, null);
       return;                                                       
     end if;   
                                                         
     select al.code_role, al.code_department, al.seq_action_log
     into v_code_role, v_code_department, v_seq_action_log
     from action_log al
     where al.seq_bakasha = v_seq_bakasha;

     if apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => p_i)  is not null
        and p_add_document = 1 then
      v_seq_document := document_seq.nextval;
      insert into document d
      (d.seq_document,
       d.seq_document_type,
       d.document_url,
       d.teur,
       d.date_update,
       d.code_user,
       d.remarks,
       d.date_create,
       d.page_count,
       d.source_document_id,
       d.is_exist,
       d.is_same,
       d.is_valid_data,
       d.code_document_direction,
       d.code_role,
       d.code_department,
       d.id_archive,
       d.source_type,
       d.document_maor_url)
       values
       (v_seq_document,
       v_subject_code,
       apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => p_i),
       v_teur_subject_crm,
       sysdate,
       null,
       v_teur_subject_crm,
       null,
       null,
       null,
       0,
       0,
       0,
       null,
       v_code_role,
       v_code_department,
       null,
       null,
       null);
      insert into document_bakasha db
     (db.seq_document_bakasha,
       db.seq_document,
       db.seq_bakasha,
       db.seq_action_log,
       db.pail)
     values (
     document_bakasha_seq.nextval,
     v_seq_document,
     v_seq_bakasha,
     v_seq_action_log,
     1);
    end if;
    end if;
end;

function add_bank_account(p_i number)
                    return boolean is
v_seq_bakasha_tmp number := null;
v_seq_poresh_lesheer number;

begin
      if v_gimla_number is not null then
        
      select count(*)
      into v_is_hishtafut_leguf
      from v_bakasha_last_status v
      where v.code_sug_bakasha in (8,9)
      and v.code_action <> 17
      and v.gimla_number  = v_gimla_number;
      
      if v_is_hishtafut_leguf > 0 then
          v_error_text := add_error_text('Change bank account for participation',' ');
          add_row_to_errors(p_i);
          return false;
      end if;
      
      if v_seq_sheer is null then

          v_seq_bakasha := pk_load_mimshak.Add_main_tables(v_seq_poresh,
                                            v_seq_ezor_ovdim,
                                            case when v_seq_ezor_ovdim = 10154 and v_code_sug_bakasha = 15 then 25
                                                 else const_code_source_CRM end,
                                            v_code_sug_bakasha,
                                            sysdate,
                                            null,
                                            v_seq_sheer);
        else
          select b.seq_porshim
          into v_seq_poresh_lesheer
          from bney_mishpacha b
          where b.seq_bney_mishpacha = v_seq_sheer;
           v_seq_bakasha := pk_load_mimshak.Add_main_tables(v_seq_poresh_lesheer,
                                            v_seq_ezor_ovdim,
                                            case when v_seq_ezor_ovdim = 10154 and v_code_sug_bakasha = 15 then 25
                                                 else const_code_source_CRM end,
                        v_code_sug_bakasha,
                                            sysdate,
                                            null,
                                            v_seq_sheer);
         end if;
         
        v_seq_bakasha_first := v_seq_bakasha;
        insert into bank_account ba
          (ba.seq_bank_account,
           ba.seq_bney_mishpacha,
           ba.seq_bakasha,
           ba.code_bank,
           ba.code_snif,
           ba.account_number,
           ba.date_update,
           ba.user_update)
        values
          (bank_account_seq.nextval,
           v_seq_sheer,
           v_seq_bakasha,
           to_number(apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => p_i)),
           to_number(apex_json.get_varchar2(p_path => 'records[%d].BankBranch__r.BranchNumber__c', p0 => p_i)),
           to_number(apex_json.get_varchar2(p_path => 'records[%d].BankAccountNumber__c', p0 => p_i)),
           sysdate,
           0
          );
        v_seq_bakasha_first := v_seq_bakasha;
        v_seq_bakasha_string := to_char(v_seq_bakasha);

        add_document_and_status(p_i);
        return true;
      else
      for r in (
        select p.mispar_zehut, p.porshim_seq, pr.seq_ezor_ovdim
        from poresh p, prisha pr
        where p.porshim_seq = pr.seq_poresh
        and p.mispar_zehut = to_number(v_person_id)
        and pr.seq_ezor_ovdim not in (
155,
158,
13,
154,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149)
       and (
       exists
       (select l.mispar_zehut
       from ld_log_events l
       where l.mispar_zehut = p.mispar_zehut
       and instr(to_char(l.mispar_gimla),to_char(pr.gimla_number)) = 1
       and l.code_record_level is not null)
       or exists
       (select h.a
       from temp_porshim_hilan_30092020 h
       where h.a = p.mispar_zehut
       and instr(h.ab,to_char(pr.gimla_number)) = 1)
       or exists
       (select s.mispar_zehut
       from sf_gimlaim_nosafim s
       where s.mispar_zehut = p.mispar_zehut)
       or exists
       (select 1
       from v_bakasha_last_status v
       where v.mispar_zehut = p.mispar_zehut
       and v.code_action not in (17,100,98,128,129)
       and v.code_sug_bakasha = 1))
       )
       loop
         
      select count(*)
      into v_is_hishtafut_leguf
      from v_bakasha_last_status v
      where v.code_sug_bakasha in (8,9)
      and v.code_action <> 17
      and v.seq_prisha = (
      select p1.seq_prisha
      from prisha p1
      where p1.seq_poresh = r.porshim_seq
      and   p1.seq_ezor_ovdim = r.seq_ezor_ovdim
      );
      
      if v_is_hishtafut_leguf > 0 then
          v_error_text := add_error_text('Change bank account for participation',' ');
          add_row_to_errors(p_i);
          continue;
      end if;

      v_seq_bakasha := pk_load_mimshak.Add_main_tables(r.porshim_seq,
                                            r.seq_ezor_ovdim,
                                           case when v_seq_ezor_ovdim = 10154 and v_code_sug_bakasha = 15 then 25
                                                 else const_code_source_CRM end,
                                            v_code_sug_bakasha,
                                            sysdate,
                                            null,
                                            null);
       if v_seq_bakasha_tmp is null then v_seq_bakasha_tmp := v_seq_bakasha; end if;
       insert into bank_account ba
          (ba.seq_bank_account,
           ba.seq_bney_mishpacha,
           ba.seq_bakasha,
           ba.code_bank,
           ba.code_snif,
           ba.account_number,
           ba.date_update,
           ba.user_update)
        values
          (bank_account_seq.nextval,
           null,
           v_seq_bakasha,
           to_number(apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => p_i)),
           to_number(apex_json.get_varchar2(p_path => 'records[%d].BankBranch__r.BranchNumber__c', p0 => p_i)),
           to_number(apex_json.get_varchar2(p_path => 'records[%d].BankAccountNumber__c', p0 => p_i)),
           sysdate,
           0
          );
          if v_seq_bakasha_first = 0 then
            v_seq_bakasha_first := v_seq_bakasha;
            v_seq_bakasha_string := to_char(v_seq_bakasha);
          else
            v_seq_bakasha_string := v_seq_bakasha_string || ',' || to_char(v_seq_bakasha);
          end if;
          add_document_and_status(p_i);
    end loop;
      for r in (
        select b.mispar_zehut_ben_mishpacha, b.seq_porshim, b.seq_bney_mishpacha, pr.seq_ezor_ovdim
        from bney_mishpacha b, prisha pr
        where b.seq_porshim = pr.seq_poresh
        and b.mispar_zehut_ben_mishpacha = to_number(v_person_id)
        and pr.seq_ezor_ovdim not in (
155,
158,
13,
154,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149)
       and (
       exists
       (select l.mispar_zehut
       from ld_log_events l
       where l.mispar_zehut = b.mispar_zehut_ben_mishpacha
       and instr(to_char(l.mispar_gimla),to_char(pr.gimla_number)) = 1
       and l.code_record_level is not null)
       or exists
       (select h.a
       from temp_porshim_hilan_30092020 h
       where h.a = b.mispar_zehut_ben_mishpacha
       and (instr(h.ab,to_char(pr.gimla_number)) = 1 or h.am='חיסכון פנסיוני')
       ))
       )
       loop
         
      select count(*)
      into v_is_hishtafut_leguf
      from v_bakasha_last_status v
      where v.code_sug_bakasha in (8,9)
      and v.code_action <> 17
      and v.seq_prisha = (
      select p1.seq_prisha
      from prisha p1
      where p1.seq_poresh = r.seq_porshim
      and   p1.seq_ezor_ovdim = r.seq_ezor_ovdim
      );
      
      if v_is_hishtafut_leguf > 0 then
          v_error_text := add_error_text('Change bank account for participation',' ');
          add_row_to_errors(p_i);
          continue;
      end if;
      
      v_seq_bakasha := pk_load_mimshak.Add_main_tables(r.seq_porshim,
                                            r.seq_ezor_ovdim,
                                           case when v_seq_ezor_ovdim = 10154 and v_code_sug_bakasha = 15 then 25
                                                 else const_code_source_CRM end,
                        v_code_sug_bakasha,
                                            sysdate,
                                            null,
                                            r.seq_bney_mishpacha)
                                            ;
       if v_seq_bakasha_tmp is null then v_seq_bakasha_tmp := v_seq_bakasha; end if;
       insert into bank_account ba
          (ba.seq_bank_account,
           ba.seq_bney_mishpacha,
           ba.seq_bakasha,
           ba.code_bank,
           ba.code_snif,
           ba.account_number,
           ba.date_update,
           ba.user_update)
        values
          (bank_account_seq.nextval,
           r.seq_bney_mishpacha,
           v_seq_bakasha,
           to_number(apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => p_i)),
           to_number(apex_json.get_varchar2(p_path => 'records[%d].BankBranch__r.BranchNumber__c', p0 => p_i)),
           to_number(apex_json.get_varchar2(p_path => 'records[%d].BankAccountNumber__c', p0 => p_i)),
           sysdate,
           0
          );
          if v_seq_bakasha_first = 0 then
            v_seq_bakasha_first := v_seq_bakasha;
            v_seq_bakasha_string := to_char(v_seq_bakasha);
          else
            v_seq_bakasha_string := v_seq_bakasha_string || ',' || to_char(v_seq_bakasha);
          end if;
     add_document_and_status(p_i);
    end loop;
    if v_seq_bakasha_tmp is null then
      v_seq_bakasha := 0;
      v_error_text := add_error_text('no pensioners are fit',' ');
      add_row_to_errors(p_i);
      return false;
    else
      v_seq_bakasha := v_seq_bakasha_first;
      return true;
    end if;
    end if;
    exception
    when others then
      v_seq_bakasha := 0;
      v_error_text := add_error_text(sqlerrm,' ');
      add_row_to_errors(p_i);
      return false;
end;

function add_address(p_seq_poresh in number,
                    p_seq_sheer in number,
                    p_seq_bakasha in number,
                    p_i number)
                    return boolean is
begin
      insert into address a
      (a.seq_bakasha,
       a.code_address,
       a.code_city,
       a.mikud,
       a.date_update,
       a.code_user_update,
       a.seq_address,
       a.seq_poresh,
       a.seq_bney_mishpacha,
       a.street,
       a.house,
       a.apartment,
       a.entrance,
       a.house_letter,
       a.seq_apotropus)
    values
      (p_seq_bakasha,
      2,
      to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].City__r.CityCode__c', p0 => p_i),'0')),
      apex_json.get_varchar2(p_path => 'records[%d].PostalCode__c', p0 => p_i),
      sysdate,
      0,
      address_seq.nextval,
      p_seq_poresh,
      p_seq_sheer,
      apex_json.get_varchar2(p_path => 'records[%d].Street__c', p0 => p_i),
      apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => p_i),
      --to_number(regexp_replace(nvl(apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => p_i),'0'),'\D')),
      to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].ApartmentNumber__c', p0 => p_i),'0')),
      apex_json.get_varchar2(p_path => 'records[%d].Entrance__c', p0 => p_i),
      --replace(regexp_replace(nvl(apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => p_i),'0'),'\d'),' ',''),
      null,
      null
      );
    return true;
    exception
    when others then
      --v_seq_bakasha := 0;
      v_error_text := add_error_text(sqlerrm,' ');
      add_row_to_errors(p_i);
      return false;
end;

function add_bakasha( p_i in number) return varchar2 is
v_max_19_from_date date;
v_max_20_from_date date;
v_seq_bakasha_old number;
v_is_telephone boolean;
v_code_sug_bakasha_old number;

begin
    find_gimlay;
   
  select w.code_sug_workflow,
  case when p.code_action is not null then p.code_action else p.code_action_with_data end,
  d.teur_document_type
  into v_code_sug_workflow, v_code_action, v_teur_subject_crm
  from perm_subject_crm_sug_bakasha p
  left join workflow_2_sug_bakasha w on
  w.code_source =  case when v_seq_ezor_ovdim = 10154 and v_code_sug_bakasha = 15 then 25
                   else const_code_source_CRM end
  and w.code_sug_bakasha = p.code_sug_bakasha
  left join code_document_type d on
  d.seq_document_type = p.code_subject_crm
  where p.code_subject_crm = v_subject_code;  
    if v_seq_poresh is null and v_seq_sheer is null 
      then
         return '0';
    end if;
    if v_subject_code not in (31, 32, 111) or
       v_subject_code = 32 and apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => p_i) is null
    then   
      v_seq_bakasha := pk_load_mimshak.Add_main_tables(v_seq_poresh_beprisha,
                                            v_seq_ezor_ovdim,
                                            case when v_seq_ezor_ovdim = 10154 and v_code_sug_bakasha = 15 then 25
                                                 else const_code_source_CRM end,
                                            v_code_sug_bakasha,
                                            sysdate,
                                            null,
                                            v_seq_sheer,
                                            v_code_bakasha_detail);
/*     ---******
       if v_person_id = 6666663 then v_gimla_number := 135153; end if; --למקרה של 2 פרישות של אותו פורש
     ---*****
*/                                            
     if v_code_sug_bakasha = 13 then
       begin
       begin
       select v.seq_bakasha, v.code_sug_bakasha
       into v_seq_bakasha_old, v_code_sug_bakasha_old
       from v_bakasha_last_status v
       left join darga_vederug_tik d on
       d.seq_bakasha = v.seq_bakasha
       where v.mispar_zehut = v_person_id
       and v.seq_ezor_ovdim = v_seq_ezor_ovdim
       and (v_gimla_number is null or v.gimla_number = v_gimla_number)      
       and d.taarich_me = (select max (d1.taarich_me)
       from darga_vederug_tik d1
       where d1.seq_bakasha = d.seq_bakasha)
       and (v.code_sug_bakasha = 1 or v.code_sug_bakasha = 8 and nvl(d.code_derug,0) = 45)
       and v.code_action = 98;
       exception
           when others then 
             v_code_sug_bakasha_old := 1;
       end;
       --pk_load_mimshak.Add_details_tables(v_seq_bakasha,13);
       if v_code_sug_bakasha_old = 8 then
         update bakasha b
         set b.code_sug_bakasha = 9
         where b.seq_bakasha = v_seq_bakasha;
         v_code_sug_workflow := 52;
       end if;
       pk_prm_utils.duplicate_bakasha(v_seq_bakasha, v_seq_bakasha_old);
       if v_code_sug_bakasha_old = 1 then
          pk_load_mimshak.Add_details_tables(v_seq_bakasha, 13);
       else
          pk_load_mimshak.Add_details_tables(v_seq_bakasha, 9);
       end if;
    exception
    when others then
      v_seq_bakasha := 0;
      v_error_text := add_error_text(sqlerrm,' ');
      add_row_to_errors(p_i);
      return (v_seq_bakasha);
     end;
     end if;
     
     if v_code_sug_bakasha = 5 and v_subject_code = 196 then
       pk_prm_utils.duplicate_bakasha(v_seq_bakasha, v_seq_bakasha_hakpaa);
       pk_load_mimshak.Add_details_tables(v_seq_bakasha,5);
     end if;
     
    if nvl(v_seq_sheer,0) <> 0 and v_subject_code <> 31 then
      update bakasha b
      set b.seq_bney_mishpacha = v_seq_sheer
      where b.seq_bakasha = v_seq_bakasha;
    end if;
    end if;

   v_seq_bakasha_first := 0;
   v_seq_bakasha_string := '';

   if v_code_sug_bakasha = 21 then
   --שינוי בתובת

    if apex_json.get_varchar2(p_path => 'records[%d].City__r.CityCode__c', p0 => p_i) is null then
      v_code_action := null;
      return (v_seq_bakasha);
    else
     if v_seq_sheer is null then
       if v_seq_poresh is null then v_seq_bakasha := 0; return(v_seq_bakasha); end if;
       v_result := add_address(v_seq_poresh, null, v_seq_bakasha, p_i);
         if v_result = false then
            v_seq_bakasha := 0;
            return (v_seq_bakasha);
         end if;
     else
          v_result := add_address(null, v_seq_sheer, v_seq_bakasha, p_i);
          if v_result = false then
            v_seq_bakasha := 0;
            return (v_seq_bakasha);
         end if;
       end if;
    end if;

    --שינוי חשבון בנק
    elsif v_code_sug_bakasha = 15 then --שינוי חשבון בנק
      if apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => p_i) is null then
        v_code_action := null;
      else
    begin
        v_result := add_bank_account(p_i);
    exception
    when others then
      v_seq_bakasha := 0;
      v_error_text := add_error_text(sqlerrm,' ');
      add_row_to_errors(p_i);
    end;
    end if;

   elsif v_code_sug_bakasha = 33 then
   --שינוי דואר אלקטרוני
       if apex_json.get_varchar2(p_path => 'records[%d].Email__c', p0 => p_i) is null then
        v_code_action := null;
        elsif v_seq_poresh is not null then
            update poresh p
            set p.email = apex_json.get_varchar2(p_path => 'records[%d].Email__c', p0 => p_i),
            p.date_update_pelmail = sysdate
            where p.porshim_seq = v_seq_poresh;
        elsif v_seq_sheer is not null then
            update bney_mishpacha b
            set b.email = apex_json.get_varchar2(p_path => 'records[%d].Email__c', p0 => p_i),
            b.date_update_pelmail = sysdate
            where b.seq_bney_mishpacha = v_seq_sheer;
        end if;
    elsif v_code_sug_bakasha = 35 then
   --שינוי טלפון נייד
       v_mobile := trim(apex_json.get_varchar2(p_path => 'records[%d].Mobile__c', p0 => p_i));

       if apex_json.get_varchar2(p_path => 'records[%d].Mobile__c', p0 => p_i) is null then
        v_code_action := null;
       elsif v_seq_poresh is not null then
         if substr(pk_hilan.get_telephone(v_mobile,1),1,2) = '05' or length(v_mobile ) > 10 
           then v_is_telephone := false;
           else v_is_telephone := true;
         end if;
         if v_is_telephone then
            update poresh p
            set p.telephon = v_mobile,
            p.date_update_pelmail = sysdate
            where p.porshim_seq = v_seq_poresh;
         else
            update poresh p
            set p.pelephon = v_mobile,
            p.date_update_pelmail = sysdate
            where p.porshim_seq = v_seq_poresh;
         end if;
       elsif v_seq_sheer is not null then
         if substr(pk_hilan.get_telephone(v_mobile),1,2) = '05' or length(v_mobile ) > 10
           then v_is_telephone := false;
           else v_is_telephone := true;
         end if;
         if v_is_telephone then
            update bney_mishpacha b
            set b.telephone = v_mobile,
            b.date_update_pelmail = sysdate
            where b.seq_bney_mishpacha = v_seq_sheer;
         else
            update bney_mishpacha b
            set b.pelephone = v_mobile,
            b.date_update_pelmail = sysdate
            where b.seq_bney_mishpacha = v_seq_sheer;
         end if;
       end if;
    elsif v_code_sug_bakasha in (
    16, --היוון -בקשה לביצוע
    17, --השתכרות
    18, --גמלאות כפל
    18, --הודעה על ביטול פרישה
    20, --אישור שיחרור ממאסר
    26, --פרוד/ידועה בציבור
    27, --פסק דין משפטי
        --מסקנות ועדה רפואית
    29, --חלוקת חיסכון פנסיוני
    30, --אישור שירות בצה"ל/שירות לאומי
    32, --צו אפוטרופס
    13, --שאר פמסיונר
    37,  --יורשים
    5   --שינוי זכאות עם הקדמת הקפאה
    ) and v_code_bakasha_detail <> 191 --אישור חיים
    then
      v_seq_bakasha_first := v_seq_bakasha;

  --elsif v_code_sug_bakasha <> 13 then--שאר פנסיונר
    elsif v_code_sug_bakasha = 19 then --תעודת פטירה
        v_seq_bakasha_first := 0;
        if v_seq_poresh is not null then
          for r in
            (select pr.*
            from prisha pr
            where pr.seq_poresh = v_seq_poresh
            and exists
            (select 1
            from v_bakasha_last_status v
            where v.seq_prisha = pr.seq_prisha
            and v.code_sug_bakasha = 1
            and v.code_action <> 17
            )
            and pr.seq_ezor_ovdim not in (
155,
158,
13,
154,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149
)
            )
          loop
            v_code_sug_bakasha := 19;
            v_code_bakasha_detail := 6;
            v_code_action := 115;
            v_seq_bakasha := pk_load_mimshak.Add_main_tables(v_seq_poresh,
                                            r.seq_ezor_ovdim,
                                            const_code_source_CRM,
                                            v_code_sug_bakasha,
                                            sysdate,
                                            null,
                                            null,
                                            v_code_bakasha_detail);

            if v_seq_bakasha_first = 0 then
              v_seq_bakasha_first  := v_seq_bakasha;
              v_seq_bakasha_string := to_char(v_seq_bakasha);
            else
              v_seq_bakasha_string := v_seq_bakasha_string || ',' || to_char(v_seq_bakasha);
            end if;

            add_document_and_status(p_i);

          end loop;
          end if;
  
        if v_seq_sheer is not null then
          for r in
            (select pr.*
            from prisha pr
            where pr.seq_poresh = v_seq_poresh_beprisha
            and exists
            (select 1
            from v_bakasha_last_status v
            where v.seq_prisha = pr.seq_prisha
            and v.code_sug_bakasha = 1
            and v.code_action <> 17
            )
            and pr.seq_ezor_ovdim not in (
155,
158,
13,
154,
--159,
163,
164,
--225,
10150,
10152,
10155,
10156,
10157,
10153,
10151,
--10154,
10149
)
            )
          loop
            v_code_sug_bakasha := 19;
            v_code_bakasha_detail := 19;
            v_code_action := 115;
            v_seq_bakasha := pk_load_mimshak.Add_main_tables(v_seq_poresh_beprisha,
                                            r.seq_ezor_ovdim,
                                            const_code_source_CRM,
                                            v_code_sug_bakasha,
                                            sysdate,
                                            null,
                                            v_seq_sheer,
                                            v_code_bakasha_detail);

            if v_seq_bakasha_first = 0 then
              v_seq_bakasha_first  := v_seq_bakasha;
              v_seq_bakasha_string := to_char(v_seq_bakasha);
            else
              v_seq_bakasha_string := v_seq_bakasha_string || ',' || to_char(v_seq_bakasha);
            end if;

            add_document_and_status(p_i);

          end loop;
        end if;
          
    elsif v_code_sug_bakasha = 27 and v_code_bakasha_detail = 191 then --אישור חיים

        v_seq_bakasha_first := 0;
        if v_seq_poresh is not null then

        for r in (
            select s.from_date max_19_from_date , s.gimla_number, s.seq_ezor_ovdim from
            (select b.from_date/* max_19_from_date*/ , pr.gimla_number, pr.seq_ezor_ovdim
            from  prisha pr
            left join bakasha b on
            b.seq_prisha = pr.seq_prisha
            and b.code_sug_bakasha = 19
            and b.code_bakasha_detail = 12
            and b.seq_bney_mishpacha is null
            where pr.seq_poresh = v_seq_poresh
            and (v_gimla_number is null or v_gimla_number is not null and pr.gimla_number = v_gimla_number)
            order by b.from_date desc
            )s
            where rownum = 1
            ) loop

            select max(b.from_date)
            into v_max_20_from_date
            from  prisha pr
            left join bakasha b on
            b.seq_prisha = pr.seq_prisha
            left join v_bakasha_last_status v on
            v.seq_bakasha = b.seq_bakasha
            where pr.seq_poresh = v_seq_poresh
            and   pr.gimla_number = r.gimla_number
            and b.code_sug_bakasha = 20
            --and b.code_bakasha_detail = 17
            and b.seq_bney_mishpacha is null
            and v.code_action <> 17;

            v_code_sug_bakasha := 27;
            v_code_bakasha_detail := 191;
            v_code_action := 98;
            v_seq_bakasha := pk_load_mimshak.Add_main_tables(v_seq_poresh_beprisha,
                                            r.seq_ezor_ovdim,
                                            case when v_seq_ezor_ovdim = 10154 and v_code_sug_bakasha = 15 then 25
                                                 else const_code_source_CRM end,
                                            v_code_sug_bakasha,
                                            sysdate,
                                            null,
                                            null,
                                            v_code_bakasha_detail);

            if v_seq_bakasha_first = 0 then
              v_seq_bakasha_first  := v_seq_bakasha;
              v_seq_bakasha_string := to_char(v_seq_bakasha);
            else
              v_seq_bakasha_string := v_seq_bakasha_string || ',' || to_char(v_seq_bakasha);
            end if;

            add_document_and_status(p_i);

            v_max_19_from_date := trunc(r.max_19_from_date);

            if v_max_19_from_date is not null and
               v_max_19_from_date > nvl(v_max_20_from_date, to_date('01/01/1910','dd/mm/yyyy')) then
               v_code_sug_bakasha := 20;
               v_code_bakasha_detail := 17;
               v_code_action := 114;
               v_seq_bakasha := pk_load_mimshak.Add_main_tables(v_seq_poresh_beprisha,
                                            r.seq_ezor_ovdim,
                                            case when v_seq_ezor_ovdim = 10154 and v_code_sug_bakasha = 15 then 25
                                                 else const_code_source_CRM end,
                                            v_code_sug_bakasha,
                                            sysdate,
                                            null,
                                            null,
                                            null);
            v_seq_bakasha_string := v_seq_bakasha_string || ',' || to_char(v_seq_bakasha);

            add_document_and_status(p_i, 0);
            end if;
            end loop;
        end if;

        for r in (
            select s.from_date max_19_from_date , s.gimla_number, s.seq_ezor_ovdim, s.seq_bney_mishpacha, s.seq_prisha, s.seq_poresh from
            (select b.from_date, pr.gimla_number, pr.seq_ezor_ovdim, bm.seq_bney_mishpacha, pr.seq_prisha, pr.seq_poresh
            from  prisha pr
            left join bakasha b on
            b.seq_prisha = pr.seq_prisha
            and b.code_sug_bakasha = 19
            and b.code_bakasha_detail = 12
            left join bney_mishpacha bm on
            bm.seq_porshim = pr.seq_poresh
            and (bm.seq_bney_mishpacha = b.seq_bney_mishpacha  or b.seq_bakasha is null)
            where bm.mispar_zehut_ben_mishpacha = to_number(v_person_id)
            and bm.code_relative is not null
            and (v_gimla_number is null or v_gimla_number is not null and pr.gimla_number = v_gimla_number)
            and bm.seq_bney_mishpacha is not null
            order by b.from_date desc
            )s
            where rownum = 1
            ) loop

            select max(b.from_date)
            into v_max_20_from_date
            from  prisha pr
            left join bakasha b on
            b.seq_prisha = pr.seq_prisha
            where pr.seq_prisha = r.seq_prisha
            and b.code_sug_bakasha = 20
            --and b.code_bakasha_detail = 17
            and b.seq_bney_mishpacha = r.seq_bney_mishpacha;
            
            
            v_code_sug_bakasha := 27;
            v_code_bakasha_detail := 191;
            v_code_action := 98;

            
            v_seq_bakasha := pk_load_mimshak.Add_main_tables(r.seq_poresh,
                                            r.seq_ezor_ovdim,
                                            case when v_seq_ezor_ovdim = 10154 and v_code_sug_bakasha = 15 then 25
                                                 else const_code_source_CRM end,
                                            v_code_sug_bakasha,
                                            sysdate,
                                            null,
                                            r.seq_bney_mishpacha,
                                            v_code_bakasha_detail );
            if nvl(r.seq_bney_mishpacha,0) <> 0 then
              update bakasha b
              set b.seq_bney_mishpacha = r.seq_bney_mishpacha
              where b.seq_bakasha = v_seq_bakasha;
            end if;
           if v_seq_bakasha_first = 0 then
              v_seq_bakasha_first  := v_seq_bakasha;
              v_seq_bakasha_string := to_char(v_seq_bakasha);
            else
              v_seq_bakasha_string := v_seq_bakasha_string || ',' || to_char(v_seq_bakasha);
            end if;

            add_document_and_status(p_i);

            v_max_19_from_date := trunc(r.max_19_from_date);

            if v_max_19_from_date is not null and
               v_max_19_from_date > nvl(v_max_20_from_date, to_date('01/01/1910','dd/mm/yyyy')) then
               v_code_sug_bakasha := 20;
               v_code_bakasha_detail := 17;
               v_code_action := 114;
               v_seq_bakasha := pk_load_mimshak.Add_main_tables(r.seq_poresh,
                                            r.seq_ezor_ovdim,
                                           case when v_seq_ezor_ovdim = 10154 and v_code_sug_bakasha = 15 then 25
                                                 else const_code_source_CRM end,                v_code_sug_bakasha,
                                            sysdate,
                                            null,
                                            r.seq_bney_mishpacha,
                                            null);
              if nvl(r.seq_bney_mishpacha,0) <> 0 then
                update bakasha b
                set b.seq_bney_mishpacha = r.seq_bney_mishpacha
                where b.seq_bakasha = v_seq_bakasha;
              end if;
              v_seq_bakasha_string := v_seq_bakasha_string || ',' || to_char(v_seq_bakasha);

              add_document_and_status(p_i, 0);
            end if;
            end loop;
            v_seq_bakasha := v_seq_bakasha_first;
            
            if v_seq_bakasha = 0 and v_seq_sheer is not null then
                v_seq_bakasha := pk_load_mimshak.Add_main_tables(v_seq_poresh_beprisha,
                                            v_seq_ezor_ovdim,
                                            case when v_seq_ezor_ovdim = 10154 and v_code_sug_bakasha = 15 then 25
                                                 else const_code_source_CRM end,
                         v_code_sug_bakasha,
                                            sysdate,
                                            null,
                                            v_seq_sheer,
                                            v_code_bakasha_detail );
            if nvl(v_seq_sheer,0) <> 0 then
              update bakasha b
              set b.seq_bney_mishpacha = v_seq_sheer
              where b.seq_bakasha = v_seq_bakasha;
            end if;
              add_document_and_status(p_i);
            end if;
   end if;

   if v_seq_bakasha <> 0 and (
     v_subject_code not in (31, 32,111)
     or v_subject_code = 32 and apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => p_i) is null)
     then add_document_and_status(p_i);
   end if;

   update bakasha b
   set b.crm_number = apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => p_i),
       b.crm_link = apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => p_i),
       b.code_source = case when v_seq_ezor_ovdim = 10154 and v_code_sug_bakasha = 15 then 25
                            else const_code_source_CRM end
   where b.seq_bakasha = v_seq_bakasha;

   return v_seq_bakasha;
end;



