     else to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].City__r.CityCode__c', p0 => i),'0')) end,
apex_json.get_varchar2(p_path => 'records[%d].PostalCode__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Email__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Mobile__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => i),
sysdate,
v_seq_bakasha,
0,
v_seq_bakasha_string
);
   exception
    when others then
      v_error_text := add_error_text(sqlerrm,' ');
      add_row_to_errors(i);
end;
end if;


end loop;
commit;
if v_error_number > 0 then
  v_cursor_errors := f_get_crm_errors_json(v_seq_ld_requests_crm_errors);
  --send_mail;
  p_errors := v_cursor_errors;
  --DBMS_OUTPUT.put_line(v_cursor_errors);
  end if;


/*exception
  when others*/
end;


end pk_sf_requests;
/

create or replace package body prm_system_copy.pk_sf_requests_kpm is

   procedure get_sf_requests_kpm
   (p_kpm_interface_id In Varchar2,
      p_request_name In Varchar2,
      p_mispar_zehut In Number) is
     
      v_count number := 0;
      stam boolean := true;
      v_seq_poresh number;
      v_seq_prisha number;
      v_seq_bakasha number;
      v_seq_participation number;
      v_seq_document number;
      v_code_user number;
      v_err_message varchar2(500); 
      v_err_table_name varchar2(50);
      v_err_field_name varchar2(50);     
      v_err_foreign_key varchar2(50);
      v_err_fields_name varchar2(100);
      
      begin
      
      v_seq_prisha := null;
      
      select t.id_user
      into v_code_user
      from ld_kpm t
      where t.kpm_interface_id = p_kpm_interface_id
        and t.mispar_zehut = p_mispar_zehut
        and t.crm_number = p_request_name;

      select count(*)
      into v_count
      from v_bakasha_last_status v
      where v.mispar_zehut = p_mispar_zehut
      and v.code_sug_bakasha in (10,11)
      and v.code_action <> 17;
      if v_count > 0 then
        begin
          select distinct lk.kpm_bakasha_num
          into v_seq_bakasha
          from ld_kpm lk
          where lk.mispar_zehut = p_mispar_zehut
          and to_char(lk.date_bakasha,'yyyy') = to_char(sysdate,'yyyy')
          and nvl(lk.kpm_bakasha_num ,0) <> 0
          and lk.kpm_error_desc is null;
        exception
          when others then
          update ld_kpm t
            set t.kpm_bakasha_num = 0,
                t.kpm_error_desc = 'קיימת בקשת קפ"מ עבור הפורש'
            where t.kpm_interface_id = p_kpm_interface_id
                  and t.mispar_zehut = p_mispar_zehut
                  and t.crm_number = p_request_name;
            commit; 
           return;
        end;
         if nvl(v_seq_bakasha,0) > 0 then goto get_documents; end if; 
      
      update ld_kpm t
        set  t.kpm_bakasha_num = 0,
            t.kpm_error_desc = 'קיימת בקשת קפ"מ עבור הפורש'
        where t.kpm_interface_id = p_kpm_interface_id
              and t.mispar_zehut = p_mispar_zehut
              and t.crm_number = p_request_name;
        commit; 
        return;
      end if;    

      select count(*)
        into v_count
        from poresh p
        where p.mispar_zehut = p_mispar_zehut;
      
      if v_count > 0 then
        select p.porshim_seq
        into v_seq_poresh
        from poresh p
        where p.mispar_zehut = p_mispar_zehut;
        
        begin
        select pr.seq_prisha
        into v_seq_prisha
        from prisha pr
        where pr.seq_poresh = v_seq_poresh
        and pr.seq_ezor_ovdim = 206;
        exception
          when others then
            v_seq_prisha := null;
        end;
 
        update poresh p
        set p.telephon =
        (select case when t.telephon is not null then t.telephon else p.telephon end
        from ld_kpm t
         where t.kpm_interface_id = p_kpm_interface_id
         and t.mispar_zehut = p_mispar_zehut
         and t.crm_number = p_request_name)
         where p.mispar_zehut = p_mispar_zehut;

        update poresh p
        set p.pelephon =
        (select case when t.pelephon is not null then t.pelephon else p.pelephon end
        from ld_kpm t
         where t.kpm_interface_id = p_kpm_interface_id
         and t.mispar_zehut = p_mispar_zehut
         and t.crm_number = p_request_name)
        where p.mispar_zehut = p_mispar_zehut;
 
        update poresh p
        set p.email =
        (select case when t.email is not null then t.email else p.email end
        from ld_kpm t
         where t.kpm_interface_id = p_kpm_interface_id
         and t.mispar_zehut = p_mispar_zehut
         and t.crm_number = p_request_name)
        where p.mispar_zehut = p_mispar_zehut;
         
       else
        select porshim_seq.nextval
        into v_seq_poresh
        from dual;
        
        insert into poresh p
               (p.mispar_zehut,
               p.shem_prati,
               p.shem_mishpacha,
               p.taarich_leda,
               p.porshim_seq,
               p.telephon,
               p.pelephon,
               p.code_min,
               p.sug_zihuy,
               p.email)
        select
               t.mispar_zehut,
               t.shem_prati,
               t.shem_mishpacha,
               t.taarich_leda,
               v_seq_poresh,
               t.telephon,
               t.pelephon,
               t.code_min,
               1,
               t.email
       from ld_kpm t
       where t.kpm_interface_id = p_kpm_interface_id
         and t.mispar_zehut = p_mispar_zehut
         and t.crm_number = p_request_name;
         
      insert into mazav_mishpachti m
             (m.seq_mazav_mishpachti,
             m.seq_poresh,
             m.code_mazav_mishpachti,
             m.date_mazav_mishpachti,
             m.date_update,
             m.code_user,
             m.seq_bakasha,
             m.seq_bney_mishpacha
            )
            values
            (mazav_mishpachti_seq.nextval,
            v_seq_poresh,
            999,
            sysdate,
            sysdate,
            0,
            v_seq_bakasha,
            null);    

       end if;
       
      if v_seq_prisha is null then
      select prisha_seq.nextval
        into v_seq_prisha
        from dual;
        
      insert into prisha pr
             (pr.seq_prisha,
             pr.seq_poresh,
             pr.seq_ezor_ovdim,
             pr.seq_code_unit)
         select
             v_seq_prisha,
             v_seq_poresh,
             206,
             t.seq_code_unit
         from ld_kpm t
         where t.kpm_interface_id = p_kpm_interface_id
         and t.mispar_zehut = p_mispar_zehut
         and t.crm_number = p_request_name;

      pk_prm_utils.Get_gimla_without_commit(v_seq_prisha, 0);
      
      else
         update  prisha pr
         set pr.seq_code_unit =        
         (select case when t.seq_code_unit is not null then t.seq_code_unit else pr.seq_code_unit end
         from ld_kpm t
         where t.kpm_interface_id = p_kpm_interface_id
         and t.mispar_zehut = p_mispar_zehut)
         where pr.seq_prisha = v_seq_prisha;
      end if;
                       
      select bakasha_seq.nextval
        into v_seq_bakasha
        from dual;
      
      pk_load_mimshak.Add_main_tables_internal(v_seq_bakasha,
                                     v_seq_poresh,
                                     206,
                                     6,--24,
                                     10);
      pk_prm_utils.insert_action_log_row(38, sysdate, 10, 
      case when v_code_user is null then null else v_code_user end,
      '', null, null, null, v_seq_bakasha, null);
/*      select v.code_user_to_internal
      into v_code_user
      from v_bakasha_last_status v
      where v.seq_bakasha = v_seq_bakasha;  
*/      
      update bakasha bk
      set bk.crm_number = p_kpm_interface_id  || ' ' || p_request_name
      where bk.seq_bakasha = v_seq_bakasha;

      insert into bakasha_regila br
      (br.taarich_prisha,
       br.taarich_ishur,
       br.date_payment,
       br.seq_bakasha,
       br.seq_baalut,
       br.code_chavra,
       br.chisuv_lefy_sheerut
      )
      select
               t.taarich_prisha,
               t.taarich_ishur,
               t.date_payment,
               v_seq_bakasha,
               t.seq_baalut,
               t.code_chavra,
               1
       from ld_kpm t
       where t.kpm_interface_id = p_kpm_interface_id
         and t.mispar_zehut = p_mispar_zehut
         and t.crm_number = p_request_name;

      for r in (select * 
       from ld_kpm_participation t1
       left join ld_kpm t2 on t2.kpm_interface_id = t1.kpm_interface_id
                          and t2.mispar_zehut = t1.mispar_zehut
                          and t2.crm_number = t1.crm_number
       where t1.kpm_interface_id = p_kpm_interface_id
         and t1.mispar_zehut = p_mispar_zehut
         and t1.crm_number = p_request_name) 
      loop   
     
      select participation_seq.nextval
      into v_seq_participation
      from dual;
                     
      insert into participation pt
      (pt.seq_participation,
       pt.date_start,
       pt.date_end,
       pt.code_participation,
       pt.seq_guf,
       pt.date_payment,
       pt.seq_bakasha,
       pt.date_pniya,
       pt.sum,
       pt.factor,
       pt.kizba_chodshit,
       pt.partial_period_calc,
       pt.percent_participate_calc)   
       values
       (v_seq_participation,
       r.date_start,
       r.date_end,
       4,
       r.seq_guf,
       r.date_payment,
       v_seq_bakasha,
       r.date_bakasha,
       r.sum,
       r.factor,
       r.kizba_chodshit,
       r.partial_period_calc,
       r.percent_participate_calc);
       end loop;

      insert into address a
              (a.seq_bakasha,
               a.code_address,
               a.code_city,
               a.mikud,
               a.date_update,
               a.code_user_update,
               a.seq_address,
               a.seq_poresh,
               a.street,
               a.house,
               a.apartment,
               a.entrance)
          select
               v_seq_bakasha,
               2,
               t.code_city,
               t.mikud,
               sysdate,
               0,
               address_seq.nextval,
               v_seq_poresh,
               t.street,
               t.house,
               t.apartment,
               t.entrance       
          from ld_kpm t
          where t.kpm_interface_id = p_kpm_interface_id
          and t.mispar_zehut = p_mispar_zehut
          and t.crm_number = p_request_name
          and t.code_city is not null;       
      
 <<get_documents>>
      select v.code_user_to_internal
      into v_code_user
      from v_bakasha_last_status v
      where v.seq_bakasha = v_seq_bakasha;  

      for r in
           (select * from ld_kpm_documents t
            where t.kpm_interface_id = p_kpm_interface_id
            and t.mispar_zehut = p_mispar_zehut
            and t.crm_number = p_request_name)
      loop
          select document_seq.nextval
          into v_seq_document
          from dual; 
          
          insert into document d
          (d.seq_document,
           d.seq_document_type,
           d.document_url,
           d.teur,
           d.date_update,
           d.code_user,
           d.date_create,
           d.code_document_direction,
           d.code_role,
           d.code_department)
          values(
           v_seq_document,
           r.seq_document_type,
           r.document_url,
           r.teur,
           sysdate,
           v_code_user,
           r.date_create,
           2,
           11,
           4);       
 
           
          insert into document_bakasha db
           (db.seq_document_bakasha,
            db.seq_document,
            db.seq_bakasha,
            db.pail)
            values
            (document_bakasha_seq.nextval,
             v_seq_document,
             v_seq_bakasha,
             1);
      end loop;
      
      update ld_kpm t
      set t.kpm_bakasha_num = v_seq_bakasha
      where t.kpm_interface_id = p_kpm_interface_id
            and t.mispar_zehut = p_mispar_zehut
            and t.crm_number = p_request_name;

      commit;
      exception
      when others then
        v_err_message := sqlerrm;
        rollback;
        if v_err_message like '%parent key not found%' then
        v_err_foreign_key := substr(v_err_message,instr(v_err_message,'.') + 1,
                          instr(v_err_message,')') - instr(v_err_message,'.') - 1);
        SELECT CONS.TABLE_NAME
        into v_err_table_name
        FROM USER_CONSTRAINTS CONS
        WHERE CONS.CONSTRAINT_TYPE = 'R'
        and CONS.CONSTRAINT_NAME = v_err_foreign_key;
        v_err_fields_name := '';
        for r in
        (SELECT COLS.COLUMN_NAME
        FROM USER_CONSTRAINTS CONS
        LEFT JOIN USER_CONS_COLUMNS COLS ON COLS.CONSTRAINT_NAME = CONS.CONSTRAINT_NAME
        WHERE CONS.CONSTRAINT_TYPE = 'R'
        and CONS.CONSTRAINT_NAME = v_err_foreign_key)
        loop
        v_err_field_name := r.column_name; 
        v_err_fields_name := v_err_fields_name || ' ' || v_err_field_name;
        end loop;
        v_err_message := 'integrity  constrate: table - ' ||
                         v_err_table_name || ' fields - ' ||
                         v_err_fields_name;               
        end if;
        update ld_kpm t
        set t.kpm_bakasha_num = 0,
            t.kpm_error_desc = v_err_message
        where t.kpm_interface_id = p_kpm_interface_id
              and t.mispar_zehut = p_mispar_zehut
              and t.crm_number = p_request_name;
        commit;       
      end;
end pk_sf_requests_kpm;
/

create or replace package body prm_system_copy.pk_sf_requests_kpm_json is

const_code_source_CRM constant number := 24;

v_birth_date                                           varchar2(30);
v_bakasha_date                                         varchar2(30);
v_prisha_date                                           varchar2(30);
v_documents_date                                            varchar2(30);
l_count                                               number;
j_count                                               number;
x_count                                               number;
v_is_gimla_number_required                            number;
v_is_only_poresh                                      number;
v_is_only_sheer                                       number;
v_is_to_all_prishot                                   number;
v_is_document_required                                number;
v_code_sug_bakasha                                    number;
v_code_bakasha_detail                                 number;
v_created_date                                        varchar2(19);
v_seq_bakasha                                         number;
v_seq_bakasha_first                                   number;
v_seq_bakasha_string                                  varchar2(30);
v_seq_poresh                                          number;
v_seq_poresh_beprisha                                 number;
v_seq_sheer                                           number;
v_mispar_zehut                                        number;
v_seq_ezor_ovdim                                      number;
v_code_action                                         number;
v_code_role                                           number;
v_code_department                                     number;
v_seq_action_log                                      number;
v_seq_document                                        number;
v_teur_subject_crm                                    varchar2(50);

v_request_name                                        varchar2(50);
v_SFID                                                varchar2(20);
v_person_id                                           varchar2(50);
v_subject_code                                        varchar2(50);
v_gimla_number                                        varchar2(50);
v_bank_number                                         number;
v_bank_branch                                         number;
v_code_sug_workflow                                   number;
v_mobile                                              varchar2(50);

v_error_code                                          number;
v_error_text                                          varchar2(2000);
v_check_result1                                       number;
v_check_result2                                       number;
v_errors                                              clob;
v_success_number                                      number;
v_error_number                                        number;
v_title                                               varchar2(2000);
v_report                                              varchar2(2000);
v_err                                                 boolean;
v_seq_ld_requests_crm_errors                          number;
v_cursor_errors                                       clob;
v_record_json                                         clob;
--v_error_text                                     clob;
v_result                                              boolean;
v_result_char                                         varchar2(1000);
v_seq_bakasha_error                                   number;
 

function add_error_text(p_error_text varchar2, p_field_name varchar2) return varchar2 is

  f_v_error_text varchar2(2000);
begin
  if v_error_text is null then
    f_v_error_text := v_request_name || '(' || v_SFID || ')  '  ||  p_field_name || ' -- '|| p_error_text || '(' || to_char(v_error_code) || ')' || ' -- ';
  else
    f_v_error_text := v_error_text   || chr(10) || p_error_text || '(' || to_char(v_error_code) || ')' || ' -- ';
  end if;
  return f_v_error_text;
end;


procedure add_row_to_errors(p_i number) is
  begin
  if v_error_text is not null  then
 
  v_errors := v_errors || '<br />' || v_error_text;
  --dbms_output.put_line(v_error_text);
  v_error_number := v_error_number + 1;
  insert into Ld_Requests_Crm_Errors t
      (t.request_name,
       t.Request_URL,
       t.created_date,
       t.person_id,
       t.request_source,
       t.subject_code,
       t.description,
       t.benefit_number,
       t.bank_number,
       t.bank_branch,
       t.account_number,
       t.street,
       t.street_number,
       t.entrance,
       t.apartment_number,
       t.city_code,
       t.postal_code,
       t.email,
       t.mobile,
       t.file_url,
       t.sfid,
       t.ld_date,
       t.error_text,
       t.seq_ld_requests_crm_errors
)
VALUES(
apex_json.get_varchar2(p_path => 'records[%d].Name', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].attributes.url', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].CreatedDate', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Pensioner__r.GIM_PersonIdNumber__pc', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Source__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].RequestSubject__r.APIName__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Description__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Eligibility__r.Retirement__r.BenefitNumber__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].BankBranch__r.BranchNumber__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].BankAccountNumber__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Street__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Entrance__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].ApartmentNumber__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].City__r.CityCode__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].PostalCode__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Email__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Mobile__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => p_i),
sysdate,
v_error_text,
ld_requests_crm_errors_seq.nextval);
if v_seq_ld_requests_crm_errors is null then
  v_seq_ld_requests_crm_errors := ld_requests_crm_errors_seq.currval;
end if;
end if;
end;

procedure send_mail is
  begin
    --dbms_output.put_line(v_errors);

v_title := 'total success requests: ' || to_char(v_success_number) || chr(10) ||
           'total errors requests: ' || to_char(v_error_number) || chr(10);

v_report := '<html><body>' || '<h1>' ||
                'requests interface finished' || '</h1>' ||
                '<h1>' || 'total success rows: ' || to_char(v_success_number) || '<h1/>' ||
                '<h1>' || 'total errors rows: '  || to_char(v_error_number)   || '<h1/>' ||
                '<h4><html/><body/>' || v_cursor_errors || '<html/><body/><h4/>';

    --select sys_context('userenv', 'DB_NAME') into v_userenv from dual;
    pk_prm_utils.send_attach(

    /*case when v_userenv='xt1' then*/ 'liba@mof.gov.il'
                              /*else 'liba@mof.gov.il' end*/,
                               'The requests interface finished',
                               v_title,
                               v_report,
                               'html',
                               'requests_interface.htm');
end;

procedure check_sf_requests(i integer) is
  v_is_one_poresh number;
  v_house_number varchar(20);
  begin
v_error_code := 0;
v_error_text := '';
v_request_name := apex_json.get_varchar2(p_path => 'records[%d].Name', p0 => i);
v_SFID := apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => i);

--PersonIdNumber
v_person_id := apex_json.get_varchar2(p_path => 'records[%d].Pensioner__r.GIM_PersonIdNumber__pc', p0 => i);
select validate_conversion(v_person_id as number) into v_check_result1 from dual;
select (case when not exists(
  select p.mispar_zehut
  from poresh p
  where p.mispar_zehut = to_number(v_person_id))
  and not exists(
  select b.mispar_zehut_ben_mishpacha
  from bney_mishpacha b
  where b.mispar_zehut_ben_mishpacha = to_number(v_person_id)
  --and b.code_relative is null
  )
  then 0 else 1 end)
    into v_check_result2 from dual;
if v_person_id is null then
  v_error_code := 10;
  v_error_text := add_error_text('Pensioner ID is required','Pensioner__r.GIM_PersonIdNumber__pc')
  ;
end if;
if v_check_result1 = 0 then
  v_error_code := 20;
  v_error_text := add_error_text('Pensioner ID is not numeric','Pensioner__r.GIM_PersonIdNumber__pc')
  ;
end if;
if v_check_result2 = 0 then
  v_error_code := 30;
  v_error_text := add_error_text('Pensioner ID does not exist in MAPAM ','Pensioner__r.GIM_PersonIdNumber__pc')
  ;
end if;

--SubjectCode
if v_error_text is null then
v_subject_code := apex_json.get_varchar2(p_path => 'records[%d].RequestSubject__r.APIName__c', p0 => i);
if v_subject_code is null then
  v_error_code := 110;
  v_error_text := add_error_text('Code Subject is required','RequestSubject__r.APIName__c')
  ;
end if;
select validate_conversion(v_subject_code as number) into v_check_result1 from dual;
if v_check_result1 = 0 then
  v_error_code := 120;
  v_error_text := add_error_text('Code Subject is not numeric','RequestSubject__r.APIName__c')
  ;
else
  select (case when not exists(
  select p.code_subject_crm
  from perm_subject_crm_sug_bakasha p
  where p.code_subject_crm = to_number(nvl(v_subject_code,0)))
  then 0 else 1 end)
  into v_check_result2 from dual;
  if v_check_result2 = 0 then
    v_error_code := 130;
    v_error_text := add_error_text('Code Subject does not exist','RequestSubject__r.APIName__c')
    ;
  end if;
end if;
end if;

--BenefitNumber
if v_error_text is null then
v_gimla_number := apex_json.get_varchar2(p_path => 'records[%d].Eligibility__r.Retirement__r.BenefitNumber__c', p0 => i);

select p.code_sug_bakasha, p.is_document_required, p.is_gimla_number_required,
       p.only_poresh, p.only_sheer, p.code_bakasha_detail
  into v_code_sug_bakasha,
       v_is_document_required,
       v_is_gimla_number_required,
       v_is_only_poresh,
       v_is_only_sheer,
       v_code_bakasha_detail
from perm_subject_crm_sug_bakasha p
where p.code_subject_crm = to_number(v_subject_code);

select validate_conversion(v_gimla_number as number) into v_check_result1 from dual;
if v_gimla_number is not null then select (case when not exists(
  select pr.seq_prisha
  from prisha pr
  left join poresh p on p.porshim_seq = pr.seq_poresh
  left join bney_mishpacha b on b.seq_porshim = pr.seq_poresh
  where pr.gimla_number = to_number(v_gimla_number)
  and (p.mispar_zehut = to_number(v_person_id) or
       b.mispar_zehut_ben_mishpacha = to_number(v_person_id)))
  then 0 else 1 end)
  into v_check_result2 from dual;

if v_check_result2 = 0 then
  v_error_code := 130;
  v_error_text := add_error_text('Retirement does not exist: Pensioner ID - ' ||
  pk_hilan_prd.rpad_blanks(to_number(v_person_id),9) || ' ; Benefit Number - ' || to_char(v_gimla_number) ,'Eligibility__r.Retirement__r.BenefitNumber__c')
  ;
end if;
end if;

if v_is_gimla_number_required = 1 then
   if v_gimla_number is null then
     select count(*)
      into v_is_one_poresh
      from prisha pr
      left join poresh p on
      p.porshim_seq = pr.seq_poresh
      where p.mispar_zehut = to_number(v_person_id);
      if v_is_only_poresh = 1 and v_is_one_poresh > 1 then
        v_error_code := 110;
        v_error_text := add_error_text('Benefit Number is required','Eligibility__r.Retirement__r.BenefitNumber__c');
      end if;
  end if;
end if;

if v_check_result1 = 0 then
  v_error_code := 120;
  v_error_text := add_error_text('BenefitNumber is not numeric','Eligibility__r.Retirement__r.BenefitNumber__c')
  ;
end if;
/*else
v_gimla_number := null;*/
end if;

--FileLink
if v_is_document_required = 1 then
if apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => i) is null then
  v_error_code := 210;
  v_error_text := add_error_text('Document is required','FileLink__c');
end if;
end if;


