/*if apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i) is not null then
   select validate_conversion(apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i) as number) into v_check_result1 from dual;
   if v_check_result1 = 0 then v_error_text := add_error_text('Street number is not numeric','StreetNumber__c');
end if;*/
if apex_json.get_varchar2(p_path => 'records[%d].ApartmentNumber__c', p0 => i) is not null then
   select validate_conversion(apex_json.get_varchar2(p_path => 'records[%d].ApartmentNumber__c', p0 => i) as number) into v_check_result1 from dual;
   if v_check_result1 = 0 then v_error_text := add_error_text('Apartment number is not numeric','ApartmentNumber__c');
