        v_result_char := pk_prm_utils.delete_bakasha(v_seq_bakasha_error);
    end if; 
    continue;
  end if;

  v_bank_number := case when apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => i) is null
                        then null
                        else to_number(apex_json.get_varchar2(p_path => 'records[%d].Bank__r.BankNumber__c', p0 => i)) end;
  v_bank_branch := case when apex_json.get_varchar2(p_path => 'records[%d].BankBranch__r.BranchNumber__c', p0 => i) is null
                        then null
                        else to_number(apex_json.get_varchar2(p_path => 'records[%d].BankBranch__r.BranchNumber__c', p0 => i)) end;

  v_created_date := replace(substr(apex_json.get_varchar2(p_path => 'records[%d].CreatedDate', p0 => i),1,19),'T',' ');

  select count(*)
  into v_count_sfid
  from Requests_Crm t
  where t.sfid = apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => i)
  and t.Is_Bakasha_Butla = 0;
  if v_count_sfid > 0 then
    update Requests_Crm t
    set t.is_bakasha_butla = 1
    where t.sfid = apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => i)
    and t.is_bakasha_butla = 0;

    \*for r in (select t.seq_bakasha
    --into v_seq_bakasha_sfid
    from Requests_Crm t
    where t.sfid = apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => i)
      and t.is_bakasha_butla = 1)
      loop
        v_seq_bakasha_sfid := r.seq_bakasha;
        select count(*)
          into v_count_no_135
          from v_bakasha_last_status v
          where v.seq_bakasha = r.seq_bakasha;
        if v_count_no_135 > 0 then
          select count(*)
          into v_count_no_135
          from action_log a
          where a.code_action = 135
          and a.seq_bakasha = r.seq_bakasha;

          if v_count_no_135 = 0 then
           pk_prm_utils.insert_action_log_row
             (17,sysdate,0,0,'CRM-בוטל עקב ממשק חדש מ',null,null,null,v_seq_bakasha_sfid,null);
          end if;
        end if;
      end loop;*\
  end if;

  begin
    insert into Requests_Crm t
      (t.request_name,
       t.Request_URL,
       t.created_date,
       t.person_id,
       t.request_source,
       t.subject_code,
       t.description,
       t.benefit_number,
       t.bank_number,
       t.bank_branch,
       t.account_number,
       t.street,
       t.street_number,
       t.entrance,
       t.apartment_number,
       t.city_code,
       t.postal_code,
       t.email,
       t.mobile,
       t.file_url,
       t.sfid,
       t.ld_date,
       t.seq_bakasha,
       t.is_bakasha_butla,
       t.seq_bakasha_all
)
values(
apex_json.get_varchar2(p_path => 'records[%d].Name', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].attributes.url', p0 => i),
to_date(v_created_date,'yyyy-mm-dd HH24:MI:SS'),
to_number(apex_json.get_varchar2(p_path => 'records[%d].Pensioner__r.GIM_PersonIdNumber__pc', p0 => i)),
case when apex_json.get_varchar2(p_path => 'records[%d].Source__c', p0 => i) is null then null
     else to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].Source__c', p0 => i),'0')) end,
v_subject_code,
apex_json.get_varchar2(p_path => 'records[%d].Description__c', p0 => i),
case when apex_json.get_varchar2(p_path => 'records[%d].Eligibility__r.Retirement__r.BenefitNumber__c', p0 => i) is null then null
     else to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].Eligibility__r.Retirement__r.BenefitNumber__c', p0 => i),'0')) end,
v_bank_number,
v_bank_branch,
case when apex_json.get_varchar2(p_path => 'records[%d].BankAccountNumber__c', p0 => i) is null then null
     else to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].BankAccountNumber__c', p0 => i),'0')) end,
apex_json.get_varchar2(p_path => 'records[%d].Street__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Entrance__c', p0 => i),
\*case when apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i) is null then null
     else to_number(regexp_replace(nvl(apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i),'0'),'\D')) end,
case when apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i) is null then null
     else replace(regexp_replace(nvl(apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i),'0'),'\d'),' ','') end,
*\
case when apex_json.get_varchar2(p_path => 'records[%d].ApartmentNumber__c', p0 => i) is null then null
     else to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].ApartmentNumber__c', p0 => i),'0')) end,
case when apex_json.get_varchar2(p_path => 'records[%d].City__r.CityCode__c', p0 => i) is null then null
     else to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].City__r.CityCode__c', p0 => i),'0')) end,
apex_json.get_varchar2(p_path => 'records[%d].PostalCode__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Email__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Mobile__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => i),
sysdate,
v_seq_bakasha,
0,
v_seq_bakasha_string
);
   exception
    when others then
      v_error_text := add_error_text(sqlerrm,' ');
      add_row_to_errors(i);
end;
end if;*/


end loop;
commit;
if v_error_number > 0 then
  v_cursor_errors := f_get_crm_errors_json(v_seq_ld_requests_crm_errors);
  --send_mail;
  p_errors := v_cursor_errors;
  --DBMS_OUTPUT.put_line(v_cursor_errors);
  end if;


/*exception
  when others*/
end;


end pk_sf_requests_kpm_json;
