     else replace(regexp_replace(nvl(apex_json.get_varchar2(p_path => 'records[%d].StreetNumber__c', p0 => i),'0'),'\d'),' ','') end,
*/
case when apex_json.get_varchar2(p_path => 'records[%d].ApartmentNumber__c', p0 => i) is null then null
     else to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].ApartmentNumber__c', p0 => i),'0')) end,
case when apex_json.get_varchar2(p_path => 'records[%d].City__r.CityCode__c', p0 => i) is null then null
     else to_number(nvl(apex_json.get_varchar2(p_path => 'records[%d].City__r.CityCode__c', p0 => i),'0')) end,
apex_json.get_varchar2(p_path => 'records[%d].PostalCode__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Email__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Mobile__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => i),
sysdate,
v_seq_bakasha,
0,
v_seq_bakasha_string
);
   exception
    when others then
      v_error_text := add_error_text(sqlerrm,' ');
      add_row_to_errors(i);
end;
end if;


end loop;
commit;
if v_error_number > 0 then
  v_cursor_errors := f_get_crm_errors_json(v_seq_ld_requests_crm_errors);
  --send_mail;
  p_errors := v_cursor_errors;
  --DBMS_OUTPUT.put_line(v_cursor_errors);
  end if;


/*exception
  when others*/
end;


end pk_sf_requests_new;
