apex_json.get_varchar2(p_path => 'records[%d].Mobile__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].FileLink__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => p_i),
sysdate,
v_error_text,
