function add_error_text(p_error_text varchar2, p_field_name varchar2) return varchar2 is

  f_v_error_text varchar2(2000);
begin
  if v_error_text is null then
    f_v_error_text := v_request_name || '(' || v_SFID || ')  '  ||  p_field_name || ' -- '|| p_error_text || '(' || to_char(v_error_code) || ')' || ' -- ';
  else
    f_v_error_text := v_error_text   || chr(10) || p_error_text || '(' || to_char(v_error_code) || ')' || ' -- ';
  end if;
  return f_v_error_text;
end;


procedure add_row_to_errors(p_i number) is
  begin
  if v_error_text is not null  then
 
  v_errors := v_errors || '<br />' || v_error_text;
  --dbms_output.put_line(v_error_text);
  v_error_number := v_error_number + 1;
  insert into Ld_documents_Crm_Errors t
      (       t.person_id,
       t.benefit_number,
       t.code,
       t.link,
       t.scanned_time,
       t.sfid,
       t.ld_date,
       t.error_text,
       t.seq_ld_documents_crm_errors
)
VALUES(
apex_json.get_varchar2(p_path => 'records[%d].Account__r.GIM_PersonIdNumber__pc', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Eligibility__r.Retirement__r.BenefitNumber__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Type__r.Code__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Link__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].ScannedTime__c', p0 => p_i),
apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => p_i),
sysdate,
v_error_text,
ld_documents_crm_errors_seq.nextval);
if v_seq_ld_documents_crm_errors is null then
  v_seq_ld_documents_crm_errors := ld_documents_crm_errors_seq.currval;
end if;
end if;
end;


procedure send_mail is
  begin
    --dbms_output.put_line(v_errors);

v_title := 'total success documents: ' || to_char(v_success_number) || chr(10) ||
           'total errors documents: ' || to_char(v_error_number) || chr(10);

v_report := '<html><body>' || '<h1>' ||
                'documents interface finished' || '</h1>' ||
                '<h1>' || 'total success rows: ' || to_char(v_success_number) || '<h1/>' ||
                '<h1>' || 'total errors rows: '  || to_char(v_error_number)   || '<h1/>' ||
                '<h4><html/><body/>' || v_cursor_errors || '<html/><body/><h4/>';

    --select sys_context('userenv', 'DB_NAME') into v_userenv from dual;
    pk_prm_utils.send_attach(

    /*case when v_userenv='xt1' then*/ 'liba@mof.gov.il'
                              /*else 'liba@mof.gov.il' end*/,
                               'The documents interface finished',
                               v_title,
                               v_report,
                               'html',
                               'documents_interface.htm');
end;


procedure check_sf_documents(i integer) is
  v_is_one_poresh number;
/*  v_house_number varchar(20);*/
  begin
v_error_code := 0;
v_error_text := '';
v_request_name := apex_json.get_varchar2(p_path => 'records[%d].Name', p0 => i);
v_SFID := apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => i);

--PersonIdNumber
v_person_id := apex_json.get_varchar2(p_path => 'records[%d].Account__r.GIM_PersonIdNumber__pc', p0 => i);
select validate_conversion(v_person_id as number) into v_check_result1 from dual;
select (case when not exists(
  select p.mispar_zehut
  from poresh p
  where p.mispar_zehut = to_number(v_person_id))
  and not exists(
  select b.mispar_zehut_ben_mishpacha
  from bney_mishpacha b
  where b.mispar_zehut_ben_mishpacha = to_number(v_person_id)
  --and b.code_relative is null
  )
  then 0 else 1 end)
    into v_check_result2 from dual;
if v_person_id is null then
  v_error_code := 10;
  v_error_text := add_error_text('Pensioner ID is required','Pensioner__r.GIM_PersonIdNumber__pc')
  ;
end if;
if v_check_result1 = 0 then
  v_error_code := 20;
  v_error_text := add_error_text('Pensioner ID is not numeric','Pensioner__r.GIM_PersonIdNumber__pc')
  ;
end if;
if v_check_result2 = 0 then
  v_error_code := 30;
  v_error_text := add_error_text('Pensioner ID does not exist in MAPAM ','Pensioner__r.GIM_PersonIdNumber__pc')
  ;
end if;

--BenefitNumber
if v_error_text is null then
v_gimla_number := apex_json.get_varchar2(p_path => 'records[%d].Eligibility__r.Retirement__r.BenefitNumber__c', p0 => i);

if v_gimla_number is null then
  v_error_code := 110;
  v_error_text := add_error_text(' Retirement is required: Pensioner ID - ' ||
  pk_hilan_prd.rpad_blanks(to_number(v_person_id),9),' ; Eligibility__r.Retirement__r.BenefitNumber__c');
end if;

select validate_conversion(v_gimla_number as number) into v_check_result1 from dual;

if v_check_result1 = 0 then
  v_error_code := 120;
  v_error_text := add_error_text('Retirement is not numeric: Pensioner ID - ' ||
  pk_hilan_prd.rpad_blanks(to_number(v_person_id),9) || ' ; Benefit Number - ' || to_char(v_gimla_number) ,'Eligibility__r.Retirement__r.BenefitNumber__c');
end if; 

if v_gimla_number is not null then select (case when not exists(
  select pr.seq_prisha
  from prisha pr
  left join poresh p on p.porshim_seq = pr.seq_poresh
  left join bney_mishpacha b on b.seq_porshim = pr.seq_poresh
  where pr.gimla_number = to_number(v_gimla_number)
  and (p.mispar_zehut = to_number(v_person_id) or
       b.mispar_zehut_ben_mishpacha = to_number(v_person_id)))
  then 0 else 1 end)
  into v_check_result2 from dual;

if v_check_result2 = 0 then
  v_error_code := 130;
  v_error_text := add_error_text('Retirement does not exist: Pensioner ID - ' ||
  pk_hilan_prd.rpad_blanks(to_number(v_person_id),9) || ' ; Benefit Number - ' || to_char(v_gimla_number) ,'Eligibility__r.Retirement__r.BenefitNumber__c');
end if;
end if;
end if;


if v_error_text is null then
--CodeDocumentType

v_CodeDocumentType := apex_json.get_varchar2(p_path => 'records[%d].Type__r.Code__c', p0 => i);

if v_CodeDocumentType is null then
  v_error_code := 210;
  v_error_text := add_error_text(' CodeDocumentType is required: Pensioner ID - ' ||
  pk_hilan_prd.rpad_blanks(to_number(v_person_id),9),' ; Type__r.Code__c');
end if;

select validate_conversion(v_CodeDocumentType as number) into v_check_result1 from dual;

if v_check_result1 = 0 then
  v_error_code := 220;
  v_error_text := add_error_text(' CodeDocumentType is not numeric: Pensioner ID - ' ||
  pk_hilan_prd.rpad_blanks(to_number(v_person_id),9) || ' ; CodeDocumentType - ' || to_char(v_CodeDocumentType) ,'Type__r.Code__c');
end if; 

if v_CodeDocumentType is not null then select (case when exists(
  select c.seq_document_type
  from code_document_type c
  where c.seq_document_type = to_number(v_CodeDocumentType))
  then 1 else 0 end) 
  into v_check_result2
  from dual;
end if;

if v_check_result2 = 0 then
  v_error_code := 230;
  v_error_text := add_error_text(' CodeDocumentType does not exist: Pensioner ID - ' ||
  pk_hilan_prd.rpad_blanks(to_number(v_person_id),9) || ' ; CodeDocumentType - ' || to_char(v_CodeDocumentType) ,'Type__r.Code__c');
else
  begin
  select t.teur_document_type
  into v_teurDocumentType
  from code_document_type t
  where t.seq_document_type = to_number(v_CodeDocumentType);
      exception
      when no_data_found then
      v_error_code := 230;
      v_error_text := add_error_text(' CodeDocumentType does not exist: Pensioner ID - ' ||
      pk_hilan_prd.rpad_blanks(to_number(v_person_id),9) || ' ; CodeDocumentType - ' || to_char(v_CodeDocumentType) ,'Type__r.Code__c');
  end;
end if;

end if;


/*v_doc_location := reverse(v_link);
v_doc_location := reverse(substr(reverse(v_link),1,instr(reverse(v_link),'\') - 1));
*/
/*if v_error_text is null then
  
v_link := apex_json.get_varchar2(p_path => 'records[%d].Link__c', p0 => i);
v_link := substr(v_link,24);

select reverse(substr(reverse(v_link),1,instr(reverse(v_link),'\')-1))
into v_doc_filename
from dual;
select reverse(substr(reverse(v_link),instr(reverse(v_link),'\')))
into v_doc_location
from dual;

  UTL_FILE.FGETATTR
  (v_doc_location, 
  v_doc_filename,
  v_doc_exists,
  v_doc_file_length,
  v_doc_blocksize
);
end if;*/

end;

procedure get_sf_scanned_documents(p_from_date In Varchar2, p_scanned_documents In Clob, p_errors Out clob) is
  begin
 v_success_number := 0;
 v_error_number := 0;
   
 apex_json.parse(p_scanned_documents);
 l_count := apex_json.get_count (p_path => 'records');
for i IN 1 .. l_count
loop
v_sfid:= apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => i);
insert into LD_Documents_CRM t
(
       t.person_id,
       t.benefit_number,
       t.code,
       t.link,
       t.scanned_time,
       t.sfid,
       t.ld_date
)
VALUES(
apex_json.get_varchar2(p_path => 'records[%d].Account__r.GIM_PersonIdNumber__pc', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Eligibility__r.Retirement__r.BenefitNumber__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Type__r.Code__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Link__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].ScannedTime__c', p0 => i),
apex_json.get_varchar2(p_path => 'records[%d].Id', p0 => i),
sysdate
);

check_sf_documents(i);

if v_error_text is not null then
 add_row_to_errors(i);
 
else
  
select max(v.seq_bakasha)
into v_seq_bakasha
from v_bakasha_last_status v
left join prisha pr on pr.seq_prisha = v.seq_prisha
where pr.gimla_number = v_gimla_number
and v.code_sug_bakasha in (1,8)
and v.code_action not in (17,100);

v_seq_document := document_seq.nextval;
--2023-02-20T11:07:02.000+0000
v_ScannedTime := to_date(replace(substr(apex_json.get_varchar2(p_path => 'records[%d].ScannedTime__c', p0 => i),1,19),'T',' '),'YYYY-MM-DD HH24:MI:SS');
v_link := apex_json.get_varchar2(p_path => 'records[%d].Link__c', p0 => i);

for r in
(select db.*
from documents_crm t
left join document_bakasha db on
db.seq_document = t.seq_document
and db.seq_bakasha = t.seq_bakasha
where t.sfid = v_SFID)
loop
  update document_bakasha db1
  set db1.pail = 0
  where db1.seq_bakasha = r.seq_bakasha
  and   db1.seq_document = r.seq_document;
end loop;

insert into documents_crm t
        (
        t.person_id,
        t.benefit_number,
        t.code,
        t.link,
        t.sfid,
        t.ld_date,
        t.seq_bakasha,
        t.seq_document
        )
 values (
        v_person_id,
        v_gimla_number,
        v_CodeDocumentType,
        v_link,
        v_sfid,
        sysdate,
        v_seq_bakasha,
        v_seq_document
        );        
insert into document t
       (
       t.seq_document,
       t.seq_document_type,
       t.document_url,
       t.teur,
       t.date_update,
       t.code_user,
       t.remarks,
       t.date_create,
       t.source_type,
       t.code_department
       )
       values
       (
       v_seq_document,
       v_CodeDocumentType,
       v_link,
       v_teurDocumentType || ' - ' || v_person_id,
       sysdate,
       0,
       'scanned documents',
       v_ScannedTime,
       5,
       3 --חיצוני
       );
insert into document_bakasha t
       (
       t.seq_document_bakasha,
       t.seq_document,
       t.seq_bakasha,
       t.pail
       )
       values
       (
       document_bakasha_seq.nextval,
       v_seq_document,
       v_seq_bakasha,
       1
       );             
end if;
     
commit;
end loop;
if v_error_number > 0 then
  v_cursor_errors := f_get_crm_doc_errors_json(v_seq_ld_documents_crm_errors);
  --send_mail;
  p_errors := v_cursor_errors;
  --DBMS_OUTPUT.put_line(v_cursor_errors);
  --p_errors := 'NO_ERRORS';
end if;


end;
end pk_sf_scanned_documents/*_work*/;
/

create or replace package body prm_system_copy.pk_vpd as
  -----------------------------------------------------------
  v_context_name   varchar2(100) := 'vpd_mpm';
  v_attribute_name varchar2(100) := 'filter_by_seq_ezor_ovdim';
  -------------------------------------------------------------
  procedure get_policeis(cur out sys_refcursor) is
  begin
    open cur for
      select *
        from V$VPD_POLICY v
       where v.OBJECT_OWNER like '%PRM_SYSTEM%';
  end;
  -----------------------------------------------------------
  procedure Initialize_mpm_context is
  begin
    execute immediate 'create or replace context ' || v_context_name ||
                      ' using ' || user || '.pk_vpd';
  end;
  -----------------------------------------------------------
  procedure drop_mpm_context is
  begin
    execute immediate 'drop context ' || v_context_name;
  end;
  -------------------------------------------------------------
  procedure set_prem_ezor_ovdim(p_code_user number) is
    v_seq_ezor_ovdim varchar2(1000);
  
  begin
    -- Initialize_mpm_context
    Initialize_mpm_context();
  
    -- Get seq_ezor_ovdim for user 
    select string_agg(t.seq_ezor_ovdim)
      into v_seq_ezor_ovdim
      from perm_vpd t
     where t.code_user = p_code_user;
  
    -- Set mpm context
    dbms_session.set_context(v_context_name,
                             v_attribute_name,
                             v_seq_ezor_ovdim);
  end;
  -------------------------------------------------------------
  function range_prisha(p_value_ezor_ovdim varchar2) return varchar2 is
  begin
    if p_value_ezor_ovdim is not null then
      return ' seq_ezor_ovdim in (' || p_value_ezor_ovdim || ')';
    else
      return null;
    end if;
  end;
  -------------------------------------------------------------
  function range_bakasha(p_value_ezor_ovdim varchar2) return varchar2 is
  begin
    if p_value_ezor_ovdim is not null then
      return ' seq_prisha in
             (select p.seq_prisha from prisha p
             where' || range_prisha(p_value_ezor_ovdim) || ' )';
    else
      return null;
    end if;
  end;
  -------------------------------------------------------------
  function vpd_range_tables(schema_name in varchar2,
                            object_name in varchar2) return varchar2 is
  begin
    if sys_context(v_context_name, v_attribute_name) is not null then
      return ' seq_bakasha in (select b.seq_bakasha
                         from bakasha b where ' || range_bakasha(sys_context(v_context_name,
                                                                                   v_attribute_name)) || ')';
    else
      return null;
    end if;
  end;

  -------------------------------------------------------------
  function vpd_range_bakasha(schema_name in varchar2,
                             object_name in varchar2) return varchar2 is
  begin
    return range_bakasha(sys_context(v_context_name, v_attribute_name));
  end;

  -------------------------------------------------------------
  function vpd_range_prisha(schema_name in varchar2,
                            object_name in varchar2) return varchar2 is
  begin
    return range_prisha(sys_context(v_context_name, v_attribute_name));
  end;
  -------------------------------------------------------------
  procedure drop_policy(p_table_name varchar2) is
  begin
    dbms_rls.drop_policy(object_name => p_table_name,
                         policy_name => p_table_name);
  end;
  -------------------------------------------------------------
  procedure add_policy(p_table_name varchar2) is
    v_policy_function varchar2(100);
  begin
    if p_table_name in ('prisha', 'v_ezor_ovdim_category_vpd') then
      v_policy_function := 'pk_vpd.vpd_range_prisha';
    elsif p_table_name = 'bakasha' then
      v_policy_function := 'pk_vpd.vpd_range_bakasha';
    else
      v_policy_function := 'pk_vpd.vpd_range_tables';
    end if;
  
    dbms_rls.add_policy(object_name     => p_table_name,
                        policy_name     => p_table_name,
                        policy_function => v_policy_function,
                        statement_types => 'select, insert, update, delete',
                        update_check    => TRUE,
                        enable          => TRUE,
                        static_policy   => FALSE);
  end;
  -------------------------------------------------------------
  procedure add_policy_to_system is
  begin
    begin
      add_policy('prisha');
    exception
      when others then
        dbms_output.put_line('err add policy in bakasha');
    end;
  
    begin
      add_policy('bakasha');
    exception
      when others then
        dbms_output.put_line('err add policy in bakasha');
    end;
  
    begin
