create or replace package body prm_system_copy.pk_zakaut is
  ----------------------------------------------
  function Get_seq_netuny_tik_mechushavim(p_seq_bakasha     in number,
                                          p_code_department in number,
                                          p_mispar_misra    number default null)
    return number is
    v_seq_netuney_tik_mechushavim number;
  begin
    begin
      select n.seq_netuney_tik_mechushavim
        into v_seq_netuney_tik_mechushavim
        from netuney_tik_mechushavim n
       where n.seq_bakasha = p_seq_bakasha
         and n.code_department = p_code_department
         and n.mispar_misra = nvl(p_mispar_misra, 0);
    exception
      when no_data_found then
        v_seq_netuney_tik_mechushavim := netuney_tik_mechushavim_seq.nextval;
    end;
    return v_seq_netuney_tik_mechushavim;
  end;
  --------------------------------------------
  procedure restart_the_fields(p_seq_bakasha     number,
                               p_code_department number,
                               p_mispar_misra    number default null) is
  begin
    update netuney_tik_mechushavim n
       set n.achuz_kizba_sofi  = null,
           n.code_group_prisha = null,
           n.is_hachlata_sofit = 0,
           --n.date_update           = null,
           n.chelkiyut_sofit       = null,
           n.odef_sherut_chodashim = null,
           n.odef_sherut_yamim     = null,
           n.is_zakay_kizba        = 0,
           n.date_start_zakaut     = null,
           n.is_zakai_lmaanak      = 0,
           n.code_e_zakaut         = null, --e
           n.total_ben_zug         = null,
           n.total_child           = null
     where n.seq_bakasha = p_seq_bakasha
       and n.code_department = p_code_department
       and (n.mispar_misra = p_mispar_misra or p_mispar_misra is null);
  
  end;

  --------------------------------------------
  procedure Get_total_Fields_mechushavim(p_seq_bakasha                  in number,
                                         v_total_months                 in out number,
                                         v_chelkiyut_meshuklelet_sherut in out number,
                                         v_achuz_kizba_kafuf_chelkiyut  in out number,
                                         v_tkufa_lo_mezaka              in out number,
                                         v_achuz_kizba_chelkiyut_melea  in out number,
                                         v_ahuz_kizb_achry_hgdl_kaf_chl in out number,
                                         v_chelkiyut_sofit              in out number,
                                         v_achuz_kizba_sofi             in out number,
                                         p_type_query                   in number,
                                         p_mispar_misra                 number default null,
                                         p_code_department              number) is
    v_years_mezaka                 number := 0;
    v_months_mezaka                number := 0;
    v_achuz_kizba_hagdala          number := 0;
    v_md_acz_kzb_achry_hgdl_kf_chl number := 0;
  begin
  
    select tkufa_mezaka_sherut,
           chelkiyut_meshuklelet_sherut,
           achuz_kizba_kafuf_chelkiyut,
           tkufa_lo_mezaka_sherut,
           achuz_kizba_chelkiyut_melea,
           ahuz_kizb_achry_hagdl_kaf_chel,
           chelkiyut_sofit,
           achuz_kizba_sofi
      into v_total_months,
           v_chelkiyut_meshuklelet_sherut,
           v_achuz_kizba_kafuf_chelkiyut,
           v_tkufa_lo_mezaka,
           v_achuz_kizba_chelkiyut_melea,
           v_ahuz_kizb_achry_hgdl_kaf_chl,
           v_chelkiyut_sofit,
           v_achuz_kizba_sofi
      from netuney_tik_mechushavim n
     where n.seq_bakasha = p_seq_bakasha
       and n.code_department = p_code_department
       and n.mispar_misra = nvl(p_mispar_misra, 0);
  
  end Get_total_Fields_mechushavim;
  --------------------------------------------
  function insrt_ntuny_tik_mchshvim_mdina(v_total_months                 number,
                                          v_chelkiyut_meshuklelet_sherut number,
                                          v_achuz_kizba_kafuf_chelkiyut  number,
                                          v_tkufa_lo_mezaka              number,
                                          v_achuz_kizba_chelkiyut_melea  number,
                                          v_ahuz_kizb_achry_hgdl_kaf_chl number,
                                          v_chelkiyut_sofit              number,
                                          v_achuz_kizba_sofi             number,
                                          
                                          v_is_zakai_lmaanak             number,
                                          v_achuz_kizba_gil_60           number,
                                          p_seq_bakasha                  number,
                                          p_code_department              number,
                                          p_mispar_misra                 number default null,
                                          p_peroid_medina_service        number,
                                          p_peroid_medina_out_of_service number)
    return number is
    v_seq_netuney_tik_mechushavim number;
  
    v_date_start_zakazut number;
    v_is_hoze_bchirim    number := 0;
  begin
  
    v_seq_netuney_tik_mechushavim := Get_seq_netuny_tik_mechushavim(p_seq_bakasha,
                                                                    p_code_department,
                                                                    p_mispar_misra);
  
    merge into netuney_tik_mechushavim t
    using dual
    on (seq_netuney_tik_mechushavim = v_seq_netuney_tik_mechushavim)
    when matched then
      update
         set tkufa_mezaka_sherut_not_round   = round(v_total_months, 3),
             tkufa_mezaka_sherut             = round(v_total_months),
             tkufa_lo_mezaka_sherut          = v_tkufa_lo_mezaka,
             chelkiyut_meshuklelet_sherut    = v_chelkiyut_meshuklelet_sherut,
             achuz_kizba_kafuf_chelkiyut     = v_achuz_kizba_kafuf_chelkiyut,
             achuz_kizba_chelkiyut_melea     = v_achuz_kizba_chelkiyut_melea,
             ahuz_kizb_achry_hagdl_kaf_chel  = v_ahuz_kizb_achry_hgdl_kaf_chl,
             achuz_kizb_achry_hagdl_chl_mla  = round(v_ahuz_kizb_achry_hgdl_kaf_chl *
                                                     v_chelkiyut_meshuklelet_sherut,
                                                     2),
             chelkiyut_sofit                 = v_chelkiyut_sofit,
             achuz_kizba_sofi                = v_achuz_kizba_sofi,
             t.is_zakai_lmaanak              = v_is_zakai_lmaanak,
             t.achuz_kizba_gil_60            = v_achuz_kizba_gil_60,
             t.tkufa_mezaka_medina_only      = p_peroid_medina_service,
             t.chodeshim_mezkim_out_of_srv_m = p_peroid_medina_out_of_service
      
    
    when not matched then
      insert
        (seq_netuney_tik_mechushavim,
         seq_bakasha,
         code_department,
         mispar_misra,
         tkufa_mezaka_sherut,
         tkufa_lo_mezaka_sherut,
         chelkiyut_meshuklelet_sherut,
         achuz_kizba_kafuf_chelkiyut,
         achuz_kizba_chelkiyut_melea,
         ahuz_kizb_achry_hagdl_kaf_chel,
         achuz_kizb_achry_hagdl_chl_mla,
         chelkiyut_sofit,
         achuz_kizba_sofi,
         tkufa_mezaka_sherut_not_round,
         t.is_zakai_lmaanak,
         t.achuz_kizba_gil_60,
         tkufa_mezaka_medina_only,
         chodeshim_mezkim_out_of_srv_m)
      values
        (v_seq_netuney_tik_mechushavim,
         p_seq_bakasha,
         p_code_department,
         p_mispar_misra,
         round(v_total_months),
         v_tkufa_lo_mezaka,
         v_chelkiyut_meshuklelet_sherut,
         v_achuz_kizba_kafuf_chelkiyut,
         v_achuz_kizba_chelkiyut_melea,
         v_ahuz_kizb_achry_hgdl_kaf_chl,
         round(v_ahuz_kizb_achry_hgdl_kaf_chl *
               v_chelkiyut_meshuklelet_sherut,
               2),
         v_chelkiyut_sofit,
         v_achuz_kizba_sofi,
         round(v_total_months, 3),
         v_is_zakai_lmaanak,
         v_achuz_kizba_gil_60,
         p_peroid_medina_service,
         p_peroid_medina_out_of_service) log errors into err_netuney_tik_mechushavim REJECT LIMIT UNLIMITED;
  
    return 1;
  end;
  --------------------------------------------
  procedure calc_by_sherut(p_seq_bakasha     number,
                           p_code_department number default 2) is
  begin
    update netuney_tik_mechushavim n
       set n.code_group_prisha = 1
     where n.code_department = p_code_department
       and n.seq_bakasha = p_seq_bakasha;
  
  end;
  --------------------------------------------
  function calc_sheerim(p_seq_bakasha                 number,
                        p_seq_netuney_tik_mechushavim number,
                        p_gimlat_kefel                number,
                        p_maskoret_kovaat_tikra       number,
                        p_is_zakai_maanak_sheer       out number,
                        p_code_department             number,
                        p_as_of_date                  date default null)
    return number is
  
    v_sum_achuz_kizba       number := 0;
    v_is_sheerim            number := 0;
    v_check_sheerim         number := 0;
    v_code_job              number;
    v_e_zakaut              number;
    v_code_seif_prisha      number;
    v_achuz_kizba_sofi      number;
    v_max_achuz_kizba       number;
    v_sum_achuz_kizba_chuka number;
  
  begin
  
    select t.code_seif_prisha
      into v_code_seif_prisha
      from bakasha_regila t
      left join code_seif_prisha t1
        on t.code_seif_prisha = t1.code_seif_prisha
     where t.seq_bakasha = p_seq_bakasha;
    if get_sheer_group(p_seq_bakasha) = 1 then
      v_check_sheerim := 1;
    end if;
    if v_check_sheerim = 1 then
    
      publc_insrt_ntuny_tik_mchshvim(p_seq_bakasha, 0, p_code_department);
    
      calc_by_sherut(p_seq_netuney_tik_mechushavim);
      if v_code_seif_prisha not in (128, 228, 328, 428, 528) then
        calc_pizuy_odef_shanim(p_seq_bakasha,
                               p_gimlat_kefel,
                               p_maskoret_kovaat_tikra,
                               p_code_department);
      end if;
      calc_chelkiyut_lefy_nechut(p_seq_bakasha,
                                 p_seq_netuney_tik_mechushavim,
                                 p_code_department);
    
      sheerim_calc_achuz_kizba(p_seq_bakasha,
                               v_is_sheerim,
                               v_sum_achuz_kizba,
                               v_max_achuz_kizba,
                               p_is_zakai_maanak_sheer,
                               v_e_zakaut,
                               null,
                               p_as_of_date,
                               v_sum_achuz_kizba_chuka,
                               p_code_department);
    
      if v_is_sheerim = 0 then
        update netuney_tik_mechushavim n
           set n.code_e_zakaut      = 99,
               n.date_update        = sysdate,
               n.code_maanak_almana = null
         where n.seq_bakasha = p_seq_bakasha
           and n.code_department = p_code_department;
      
        RAISE_APPLICATION_ERROR(-20000, 'error');
      end if;
    
    end if;
  
    --unless 3 year merrige or 45 years but  there is no child
    if nvl(p_is_zakai_maanak_sheer, 0) > 0 and
       nvl(v_sum_achuz_kizba, 0) <> 0 then
      v_e_zakaut := null;
    end if;
  
    if v_is_sheerim = 1 then
      update netuney_tik_mechushavim n
         set n.achuz_kizba_sofi  = round(v_sum_achuz_kizba, 2),
             n.code_group_prisha = 4,
             n.chelkiyut_sofit   = n.chelkiut_lefi_nechut,
             n.code_e_zakaut     = v_e_zakaut --,
      -- n.code_maanak_almana = p_is_zakai_maanak_sheer
      
       where n.seq_netuney_tik_mechushavim = p_seq_netuney_tik_mechushavim;
    end if;
  
    return v_is_sheerim;
  
  end;
  ----------------------------------------------
  function sheerin_get_prev_netuney_tik(p_seq_bakasha     number,
                                        p_code_department number default 2)
    return number is
    v_seq_netuney_tk_mchushvim_prv number;
    v_seq_action_log_prv           number;
  begin
    begin
      with a as
       (select v.*
          from bakasha t
          left join v_bakasha_last_status v
            on t.seq_prisha = v.seq_prisha
         where t.seq_bakasha = p_seq_bakasha)
      
      select t.seq_netuney_tik_mechushavim, al.seq_action_log
        into v_seq_netuney_tk_mchushvim_prv, v_seq_action_log_prv
        from bakasha t1
        left join a t2
          on t1.seq_prisha = t2.seq_prisha
         and t2.seq_bakasha < t1.seq_bakasha
         and (t2.code_sug_bakasha in (1, 3, 5) or
             (t1.code_sug_bakasha = 7 and t2.code_sug_bakasha = 7))
        left join netuney_tik_mechushavim t
          on t.seq_bakasha = t2.seq_bakasha
         and t.code_department = p_code_department
         and t.mispar_misra = 0
        left join action_log al
      --only from hasavot
          on t.seq_bakasha = al.seq_bakasha
         and (al.code_action in (99, 145) or
             al.code_action in (148, 12) and
             al.date_action < to_date('01/01/2019', 'dd/mm/yyyy'))
       where t1.seq_bakasha = p_seq_bakasha
         and pk_prm_utils.is_bakasha_was_not_confirmed(t2.seq_bakasha, 1) = 0
         and t2.code_action <> 17
      --and al.seq_action_log is not null
       order by t2.seq_bakasha desc fetch first 1 rows only;
    
      --if bakasha not from hasava - return null
      if v_seq_action_log_prv is null then
        v_seq_netuney_tk_mchushvim_prv := null;
      end if;
    exception
      when no_data_found then
        v_seq_netuney_tk_mchushvim_prv := null;
    end;
    return v_seq_netuney_tk_mchushvim_prv;
  end;
  --------------------------------------------\
  function get_code_yadani(p_seq_bakasha number) return number is
    v_code_yadani number;
  begin
    begin
      select max(t.yadani)
        into v_code_yadani
        from netuney_tik_mechushavim t
       where t.seq_bakasha = p_seq_bakasha;
    
    exception
      when no_data_found then
        v_code_yadani := null;
    end;
    return v_code_yadani;
  end;
  --------------------------------------------
  procedure sheerim_calc_achuz_kizba(p_seq_bakasha           number,
                                     p_is_sheerim            out number,
                                     p_sum_achuz_kizba       out number,
                                     p_max_achuz_kizba       out number,
                                     p_is_zakai_maanak       out number,
                                     p_code_e_zakaut         out number,
                                     p_mispar_misra          number default null,
                                     p_as_of_date            date default null,
                                     p_sum_achuz_kizba_chuka out number,
                                     p_code_department       number default 2) is
    v_achuz_kizba_sheer       number;
    v_achuz_kizba_global      number;
    v_achuz_kizba_global_max  number;
    v_total_achuz_kizba_child number := 0;
    v_code_relative           number;
    v_count_sheer_child       number := 0;
    v_is_sheerim              number := 0;
    v_is_without_parent       number := 0;
    v_is_without_children     number := 0;
    v_is_achuz_yachasi        number;
    v_youngest_child_seq      number;
    v_yonest_achuz_kizba      number;
    v_global_achuz            number := 0;
    v_global_max              number := 0;
    v_date_end_zakaut         date;
    v_achuz_kizba_sofi        number;
    v_age_min                 number;
    v_max_achuz_ben_zug       number := 40;
    v_odef_achuz_ben_zug      number := 0;
    v_seq_valid_sheer         number;
    v_achuz_kizba_sheer_sofi  number;
    v_group_sheer             number;
    v_taarich                 date;
    v_achuz_tosefet           number := 0;
    v_hp_seq_bakasha          number;
    v_hp_seq_bney_mishpacha   number;
    v_hp_shiur_haavara        number;
    v_hp_achuz_kizba_sofi     number;
    v_hp_shiur_hafchata       number;
    v_hp_date_start_zakaut    date;
    v_hp_min_bzl              number;
    --צריך להיות פרמטר עבור פגי תוקף
    v_taarich_tokef               date;
    v_date_maanak_almana          date;
    v_seq_netuney_tik_mechushavim number;
    v_date_start_zakaut           number;
    v_overlap_percent             number;
    v_seif_relative               number;
  begin
    p_sum_achuz_kizba := 0;
    p_is_zakai_maanak := 0;
  
    select t.seq_netuney_tik_mechushavim
      into v_seq_netuney_tik_mechushavim
      from netuney_tik_mechushavim t
     where t.seq_bakasha = p_seq_bakasha
       and t.code_department = p_code_department
       and t.mispar_misra = nvl(p_mispar_misra, 0);
  
    -----restart data
    --bney mishpacha
    for r in (select b.seq_bney_mishpacha
                from v_bakasha_last_status v
                left join bney_mishpacha b
                  on v.seq_porshim = b.seq_porshim
               where v.seq_bakasha = p_seq_bakasha) loop
      update bney_mishpacha m
         set m.code_relative = 9
       where m.seq_bney_mishpacha = r.seq_bney_mishpacha
         and m.code_relative is not null
         and m.code_relative <> 9;
    end loop;
  
    --netuney bney mishpacha
    for r in (select ntb.seq_netuney_tik_ben_mishpacha
                from v_bakasha_last_status v
                left join netuney_tik_mechushavim t
                  on t.seq_bakasha = v.seq_bakasha
                 and t.code_department = p_code_department
                 and t.mispar_misra = p_mispar_misra
                left join NETUNEY_TIK_BEN_MISHPACHA ntb
                  on t.seq_netuney_tik_mechushavim =
                     ntb.seq_netuney_tik_mechushavim
               where v.seq_bakasha = p_seq_bakasha) loop
    
      delete from NETUNEY_TIK_BEN_MISHPACHA ntb
       where ntb.seq_netuney_tik_mechushavim =
             v_seq_netuney_tik_mechushavim;
    end loop;
  
    v_is_without_parent := sheerim_is_without_parent(p_seq_bakasha);
  
    v_group_sheer := get_sheer_group(p_seq_bakasha);
    --מתמלא כרגע במקום להתקבל כפרמטר
    if p_as_of_date is null then
      select case
               when v_group_sheer in (1, 2) then
                p.taarich_ptira
               else
                v.taarich_prisha
             end
        into v_taarich_tokef
        from v_bakasha_last_status v
        left join poresh p
          on v.seq_porshim = p.porshim_seq
       where v.seq_bakasha = p_seq_bakasha;
    
    else
      v_taarich_tokef := p_as_of_date;
    end if;
  
    if v_group_sheer in (2, 3) then
      select t.achuz_kizba_maximali
        into v_achuz_kizba_sofi
        from netuney_tik_mechushavim t
       where t.seq_bakasha = p_seq_bakasha
         and t.code_department = p_code_department
         and t.mispar_misra = p_mispar_misra;
    end if;
  
    --hisachon_pensyoni
    select max(b.seq_bney_mishpacha),
           max(t.hp_sheur_havara),
           max(b.code_min),
           max(nt.hp_date_start_zakaut)
      into v_hp_seq_bney_mishpacha,
           v_hp_shiur_haavara,
           v_hp_min_bzl,
           v_hp_date_start_zakaut
      from v_bakasha_last_status v
      left join bney_mishpacha b
        on v.seq_porshim = b.seq_porshim
       and b.code_kirva = 10
      left join poresh p
        on v.seq_porshim = p.porshim_seq
      left join (select max(vv.seq_bakasha) seq_bakasha,
                        vv.seq_prisha,
                        max(vv.code_sug_workflow) code_sug_workflow,
                        max(vv.code_action) code_action
                   from v_bakasha_last_status vv
                  where vv.code_sug_bakasha = 12
                  group by vv.seq_prisha, null, null) v_hp
        on v.seq_prisha = v_hp.seq_prisha
      left join workflow w
        on w.code_sug_workflow = v_hp.code_sug_workflow
       and w.code_action = v_hp.code_action
    -- get confirm action
      left join code_sug_workflow sw
        on sw.code_sug_workflow = v_hp.code_sug_workflow
    --Get the order_wf of confirm action
      left join workflow w2
        on w2.code_sug_workflow = sw.code_sug_workflow
          --bakasha has siyum tipul
       and w2.code_action = sw.code_action_lock
      left join bakasha_regila t
        on t.seq_bakasha = v_hp.seq_bakasha
      left join netuney_tik_mechushavim nt
        on nt.seq_bakasha = v_hp.seq_bakasha
       and nt.code_department = p_code_department
     where v.seq_bakasha = p_seq_bakasha
       and (w.order_wf >= w2.order_wf or v_hp.code_action = 98 or
           v_hp.code_action = 132);
  
    --only ben zug lesheavar
    if v_hp_seq_bney_mishpacha is not null and
       v_hp_shiur_haavara is not null and
       (v_hp_date_start_zakaut < p_as_of_date or v_group_sheer in (2, 3)) then
    
      v_achuz_kizba_sheer      := 40;
      v_achuz_kizba_sheer_sofi := 40;
      if v_group_sheer in (2, 3) then
      
        v_achuz_kizba_sheer_sofi := 60;
      
        /*if v_max_achuz_ben_zug / v_achuz_kizba_sofi * 100 <
           v_achuz_kizba_sheer_sofi then
          v_odef_achuz_ben_zug     := round(v_achuz_kizba_sheer_sofi -
                                            v_max_achuz_ben_zug /
                                            v_achuz_kizba_sofi * 100,
                                            2);
          v_achuz_kizba_sheer_sofi := v_max_achuz_ben_zug /
                                      v_achuz_kizba_sofi * 100;
        end if;*/
        if v_hp_min_bzl = 1 then
          v_hp_shiur_hafchata := 1.2;
        else
          v_hp_shiur_hafchata := 2.8;
        end if;
      else
        v_hp_shiur_hafchata := 0;
      end if;
    
      v_hp_achuz_kizba_sofi := round(case
                                       when v_group_sheer in (2, 3) then
                                        (v_achuz_kizba_sofi / 100)
                                       else
                                        1
                                     end * (v_hp_shiur_haavara *
                                     (1 - v_hp_shiur_hafchata / 100)) / 100 *
                                     (v_achuz_kizba_sheer_sofi),
                                     2);
      update bney_mishpacha b
         set b.code_relative = 6, b.to_date_sium_zakaut = v_date_end_zakaut
      -- b.achuz_kizba         = v_hp_achuz_kizba_sofi,
      --b.achuz_tosefet       = null,              
      --b.achuz_kizba_chuka   = v_achuz_kizba_sheer
       where b.seq_bney_mishpacha = v_hp_seq_bney_mishpacha;
    
      insert_netuny_tk_ben_mishpacha(v_hp_seq_bney_mishpacha,
                                     v_seq_netuney_tik_mechushavim,
                                     6,
                                     v_achuz_kizba_sheer,
                                     v_hp_achuz_kizba_sofi,
                                     v_seif_relative,
                                     
                                     v_date_end_zakaut);
    
      p_is_sheerim      := 1;
      p_sum_achuz_kizba := (v_hp_shiur_haavara *
                           (1 - v_hp_shiur_hafchata / 100)) / 100 *
                           (v_achuz_kizba_sheer_sofi);
    
    end if;
    for r in (select b.seq_bney_mishpacha,
                     b.code_kirva,
                     v.code_seif_prisha,
                     --months_between(v.taarich_prisha + 1, b.taarich_leda) / 12 age,
                     months_between(v_taarich_tokef + 1, b.taarich_leda) / 12 age,
                     b.is_army_ishur,
                     b.is_taluy,
                     case
                       when d.code_derug in (6, 83, 84) or
                            d.code_derug = 82 and
                            d.code_darga not in (32, 42, 52) then
                        6
                       else
                        null
                     end as code_job,
                     b.taarich_leda,
                     b.taarich_nisuin,
                     v.taarich_prisha,
                     p.taarich_ptira,
                     b.to_date_sium_zakaut,
                     v.code_sug_bakasha
                from v_bakasha_last_status v
                left join bney_mishpacha b
                  on v.seq_porshim = b.seq_porshim
                left join poresh p
                  on v.seq_porshim = p.porshim_seq
                left join (select k.seq_bakasha,
                                 max(k.code_derug) keep(dense_rank first order by k.taarich_me desc) code_derug,
                                 max(k.code_darga) keep(dense_rank first order by k.taarich_me desc) code_darga
                            from darga_vederug_tik k
                           group by seq_bakasha) d
                  on v.SEQ_BAKASHA = d.seq_bakasha
               where v.seq_bakasha = p_seq_bakasha
                    --only ben zug, yadua  or child
                 and b.code_kirva in (1, 2, 14)
                 and b.taarich_ptira is null
              -- order by taarich leda
               order by decode(b.code_kirva, 14, 1, b.code_kirva),
                        b.taarich_leda desc) loop
      v_date_maanak_almana := null;
      v_seq_valid_sheer    := sheerim_seq_valid_sheer(r.code_kirva,
                                                      mod(r.code_seif_prisha,
                                                          100) + 100,
                                                      r.age,
                                                      r.is_army_ishur,
                                                      v_is_without_parent,
                                                      r.is_taluy,
                                                      r.code_job,
                                                      v_seif_relative);
      -- sheer not suit to seif prisha 
      if v_seq_valid_sheer is null then
        continue;
      end if;
    
      -- sheer not suit to seif prisha 
      if r.code_kirva = 2 and r.to_date_sium_zakaut <= v_taarich_tokef then
        continue;
      end if;
    
      if v_group_sheer in (2, 3) or r.code_job = 6 then
        v_is_achuz_yachasi := 1;
      end if;
    
      p_is_sheerim := 1;
    
      --code_job = 6, no limit on sheer
      if r.code_job = 6 then
        v_max_achuz_ben_zug := 100;
      end if;
    
      select t.achuz_kizba_per_sheer,
             t.achuz_kizba_global,
             t.achuz_kizba_global_max --+ nvl(v_odef_achuz_ben_zug, 0)
            ,
             t.code_relative,
             t.age_min
        into v_achuz_kizba_sheer,
             v_achuz_kizba_global,
             v_achuz_kizba_global_max,
             
             v_code_relative,
             v_age_min
        from PERM_DECISION_ZAKAUT_SHEER t
       where t.seq_perm_decision_zakaut_sheer = v_seq_valid_sheer;
      v_achuz_kizba_sheer_sofi := v_achuz_kizba_sheer;
      -- Calc total achuz kizba sheer
    
      if r.code_kirva = 2 then
        --v_total_achuz_kizba_child := v_achuz_kizba_sheer;
        --Count child
        v_count_sheer_child := v_count_sheer_child + 1;
        v_global_achuz      := v_achuz_kizba_global;
        v_global_max        := v_achuz_kizba_global_max;
        --if not taluy set date end zakaut
        if nvl(r.is_taluy, 0) = 0 then
          if r.is_army_ishur = 1 then
            v_date_end_zakaut := nvl(r.to_date_sium_zakaut,
                                     last_day(add_months(r.taarich_leda, 252)));
          else
            v_date_end_zakaut := last_day(add_months(r.taarich_leda, 240));
          end if;
        end if;
        if v_count_sheer_child = 1 then
          v_youngest_child_seq := r.seq_bney_mishpacha;
        end if;
        if nvl(v_achuz_kizba_global_max, 0) <> 0 and
          --Check if the child can get the achuz_kizba_global 
           v_count_sheer_child <=
           v_achuz_kizba_global_max / v_achuz_kizba_sheer then
          --Add achuz_kizba_global
          --            v_total_achuz_kizba_sheer := v_total_achuz_kizba_sheer + v_achuz_kizba_sheer;
          v_total_achuz_kizba_child := v_total_achuz_kizba_child +
                                       v_achuz_kizba_sheer;
        
          if v_is_achuz_yachasi = 1 then
            v_achuz_kizba_sheer_sofi := v_achuz_kizba_sheer;
          end if;
        elsif nvl(v_achuz_kizba_global_max, 0) >
              nvl(v_total_achuz_kizba_child, 0) then
          v_achuz_kizba_sheer       := (v_achuz_kizba_global_max -
                                       v_total_achuz_kizba_child);
          v_achuz_kizba_sheer_sofi  := v_achuz_kizba_sheer;
          v_total_achuz_kizba_child := v_total_achuz_kizba_child +
                                       (v_achuz_kizba_global_max -
                                       v_total_achuz_kizba_child);
        
          --שאר פנסיוני
          --קיימת יתרה מתקרת בן הזוג להוסיף עבור היתומים -
          --06-2019 אברהם אלפסי מהדואר
        elsif nvl(v_odef_achuz_ben_zug, 0) <> 0 then
          v_total_achuz_kizba_child := v_total_achuz_kizba_child +
                                       v_odef_achuz_ben_zug;
          if v_is_achuz_yachasi = 1 then
            v_achuz_kizba_sheer_sofi := v_odef_achuz_ben_zug;
            v_achuz_kizba_sheer      := v_odef_achuz_ben_zug;
          end if;
          v_odef_achuz_ben_zug := 0;
        else
          v_achuz_kizba_sheer_sofi := 0;
          v_achuz_kizba_sheer      := 0;
          --v_date_end_zakaut        := null;
        end if;
      
      elsif r.code_kirva in (1, 14) then
        --איפוס שדות מהנתונים שנשמרו בחחפ, כיון שהם נכללים מתוך אחוזי בן הזוג
        p_sum_achuz_kizba       := 0;
        p_sum_achuz_kizba_chuka := 0;
      
        --when r.code_kirva =1 - ben zug
        --sheer pensyony = max 40% from maskoret_kovaat
      
        if v_is_achuz_yachasi = 1 then
          if r.code_sug_bakasha in (9, 23) then
            v_overlap_percent := round(pk_participation_2_guff.Get_overlapping_months(p_seq_bakasha,
                                                                                      r.code_sug_bakasha,
                                                                                      1)/6,
                                       2);
          end if;
          v_achuz_kizba_sheer_sofi := (round(v_achuz_kizba_sheer, 2));
        
          if v_max_achuz_ben_zug /
             (v_achuz_kizba_sofi - nvl(v_overlap_percent, 0)) * 100 <
             v_achuz_kizba_sheer_sofi then
            v_odef_achuz_ben_zug     := round(v_achuz_kizba_sheer_sofi -
                                              v_max_achuz_ben_zug /
                                              v_achuz_kizba_sofi * 100,
                                              2);
            v_achuz_kizba_sheer_sofi := v_max_achuz_ben_zug /
                                        v_achuz_kizba_sofi * 100;
          
          end if;
        
        end if;
      
        select case
                 when count(*) > 0 then
                  0
                 else
                  1
               end
          into v_is_without_children
          from bney_mishpacha t
          left join v_bakasha_last_status t1
            on t.seq_porshim = t1.seq_porshim
         where t1.seq_bakasha = p_seq_bakasha
           and t.code_kirva = 2;
        if v_group_sheer = 2 then
          v_taarich := r.taarich_ptira;
        else
          v_taarich := r.taarich_prisha;
        end if;
        --unless 3 year merrige or ben zug less 45 years
        if add_months(r.taarich_nisuin, 36) > v_taarich and
           v_is_without_children = 1 then
          p_code_e_zakaut          := 9;
          p_is_zakai_maanak        := 1;
          v_achuz_kizba_sheer_sofi := 0;
          v_date_maanak_almana     := last_day(v_taarich_tokef) + 1;
        end if;
      
        if r.age < 45 and v_is_without_children = 1 then
          --    p_code_e_zakaut      := 10;
          v_date_maanak_almana     := last_day(v_taarich_tokef) + 1;
          v_achuz_kizba_sheer_sofi := 0;
          if r.age < 43 then
            p_is_zakai_maanak := 2;
          
          else
            p_is_zakai_maanak := 1;
          end if;
          --v_achuz_kizba_sheer_sofi := 0;
        end if;
      
        p_sum_achuz_kizba := p_sum_achuz_kizba + v_achuz_kizba_sheer_sofi;
      
        merge into netuney_tik_mechushavim t
        using dual
        on (t.seq_bakasha = p_seq_bakasha and t.code_department = p_code_department and t.mispar_misra = nvl(p_mispar_misra, 0))
        when matched then
          update
             set t.code_group_prisha = 4,
                 t.total_ben_zug     = round(case
                                               when v_is_achuz_yachasi = 1 then
                                                v_achuz_kizba_sofi / 100
                                               else
                                                1
                                             end * p_sum_achuz_kizba,
                                             2)
                 
                  when not matched then insert(seq_netuney_tik_mechushavim, seq_bakasha, code_department, mispar_misra, code_group_prisha, total_ben_zug) values(netuney_tik_mechushavim_seq.nextval, p_seq_bakasha, p_code_department, 0, 4, round(case
                   when v_is_achuz_yachasi = 1 then
                    v_achuz_kizba_sofi / 100
                   else
                    1
                 end * p_sum_achuz_kizba, 2));
      
        p_max_achuz_kizba := p_max_achuz_kizba + v_max_achuz_ben_zug;
      else
        p_sum_achuz_kizba := p_sum_achuz_kizba + v_achuz_kizba_sheer_sofi;
        p_max_achuz_kizba := p_max_achuz_kizba + v_achuz_kizba_sheer;
      end if;
    
      --Update ben_mishpacha
      update bney_mishpacha b
         set /*b.achuz_kizba = round(case
                                     when v_is_achuz_yachasi = 1 then
                                      v_achuz_kizba_sofi / 100
                                     else
                                      1
                                   end * v_achuz_kizba_sheer_sofi,
                                   2) - nvl(v_hp_achuz_kizba_sofi, 0),
             b.achuz_tosefet       = null,
             b.achuz_kizba_chuka   = v_achuz_kizba_sheer,*/       b.code_relative = v_code_relative,
             b.to_date_sium_zakaut = v_date_end_zakaut
       where b.seq_bney_mishpacha = r.seq_bney_mishpacha;
      insert_netuny_tk_ben_mishpacha(r.seq_bney_mishpacha,
                                     v_seq_netuney_tik_mechushavim,
                                     v_code_relative,
                                     v_achuz_kizba_sheer,
                                     round(case when v_is_achuz_yachasi = 1 then
                                           v_achuz_kizba_sofi / 100 else 1
                                           end * v_achuz_kizba_sheer_sofi,
                                           2) - case when
                                     r.code_kirva in (1, 14) then
                                     nvl(v_hp_achuz_kizba_sofi, 0) else 0 end,
                                     v_seif_relative,
                                     null,
                                     v_date_end_zakaut,
                                     null,
                                     null,
                                     p_is_zakai_maanak,
                                     null,
                                     null,
                                     v_date_maanak_almana);
    
      v_date_end_zakaut     := null;
      v_hp_achuz_kizba_sofi := 0;
    end loop;
  
    p_sum_achuz_kizba := p_sum_achuz_kizba +
                         round(least(v_total_achuz_kizba_child +
                                     nvl(v_global_achuz, 0),
                                     v_global_max),
                               2);
  
    if v_is_achuz_yachasi = 1 then
      p_sum_achuz_kizba_chuka := p_sum_achuz_kizba;
      p_sum_achuz_kizba       := round((p_sum_achuz_kizba) *
                                       v_achuz_kizba_sofi / 100,
                                       2);
    end if;
    p_max_achuz_kizba := p_max_achuz_kizba + v_achuz_kizba_sheer +
                         least(v_total_achuz_kizba_child +
                               nvl(v_global_achuz, 0),
                               v_global_max);
  
    if v_total_achuz_kizba_child < v_global_max then
      v_achuz_tosefet := least(v_global_achuz,
                               v_global_max - v_total_achuz_kizba_child);
      /* update bney_mishpacha b
        set b.ACHUZ_TOSEFET      = least(v_global_achuz,
                                         v_global_max -
                                         v_total_achuz_kizba_child),
            b.achuz_tosefet_sofi = case
                                     when v_is_achuz_yachasi = 1 then
                                      v_achuz_kizba_sofi / 100
                                     else
                                      1
                                   end *
                                   least(v_global_achuz,
                                         v_global_max -
                                         v_total_achuz_kizba_child)
      where b.seq_bney_mishpacha = v_youngest_child_seq
        and nvl(b.achuz_kizba, 0) <> 0;*/
      select sum(nvl(b.achuz_kizba, 0))
        into v_yonest_achuz_kizba
        from netuney_tik_ben_mishpacha b
       where b.seq_bney_mishpacha = v_youngest_child_seq
         and b.seq_netuney_tik_mechushavim = v_seq_netuney_tik_mechushavim;
      if v_yonest_achuz_kizba <> 0 then
        insert_netuny_tk_ben_mishpacha(v_youngest_child_seq,
                                       v_seq_netuney_tik_mechushavim,
                                       v_code_relative,
                                       null,
                                       null,
                                       v_seif_relative,
                                       null,
                                       null,
                                       least(v_global_achuz,
                                             v_global_max -
                                             v_total_achuz_kizba_child),
                                       case when v_is_achuz_yachasi = 1 then
                                       v_achuz_kizba_sofi / 100 else 1
                                       end *
                                       least(v_global_achuz,
                                             v_global_max -
                                             v_total_achuz_kizba_child),
                                       p_is_zakai_maanak,
                                       null,
                                       null,
                                       v_date_maanak_almana);
      end if;
    end if;
  
    merge into netuney_tik_mechushavim t
    using dual
    on (t.seq_bakasha = p_seq_bakasha and t.code_department = p_code_department and t.mispar_misra = nvl(p_mispar_misra, 0))
    when matched then
      update
         set t.code_group_prisha = 4,
             t.total_child       = round(case
                                           when v_is_achuz_yachasi = 1 then
                                            v_achuz_kizba_sofi / 100
                                           else
                                            1
                                         end * (v_total_achuz_kizba_child +
                                         nvl(v_achuz_tosefet, 0)),
                                         2) when not matched then insert(seq_netuney_tik_mechushavim, seq_bakasha, code_department, mispar_misra, code_group_prisha, total_child) values(netuney_tik_mechushavim_seq.nextval, p_seq_bakasha, p_code_department, 0, 4, round(case
               when v_is_achuz_yachasi = 1 then
                v_achuz_kizba_sofi / 100
               else
                1
             end * (v_total_achuz_kizba_child + nvl(v_achuz_tosefet, 0)), 2))
      
      ;
  
    /*update netuney_tik_mechushavim t
      set t.total_child = round(case
                                  when v_is_achuz_yachasi = 1 then
                                   v_achuz_kizba_sofi / 100
                                  else
                                   1
                                end * (v_total_achuz_kizba_child +
                                nvl(v_achuz_tosefet, 0)),
                                2)
    
    where t.seq_bakasha = p_seq_bakasha
      and t.code_department = p_code_department 
      and t.mispar_misra = nvl(p_mispar_misra, 0);*/
  
  end;
  --------------------------------------------
  procedure main(p_seq_bakasha     number,
                 p_code_department in number default 2,
                 p_as_of_date      in date default null) is
  begin
    internal_main(p_seq_bakasha, p_code_department, p_as_of_date);
    commit;
  end;
  --------------------------------------------
  procedure internal_main(p_seq_bakasha     number,
                          p_code_department in number default 2,
                          p_as_of_date      in date default null) is
    v_seq_netuney_tik_mechushavim  number;
    v_is_by_nechut                 number;
    v_is_by_sheerim                number;
    v_date_start_zakaut            date;
    v_code_seif_prisha             number;
    v_achuz_kizba_sofi             number;
    v_achuz_kizba_guf              number;
    v_tkufa_mezaka_guf             number;
    v_public_tkufa_mezaka_guf      number;
    v_maskoret_kovaat_medina       number;
    v_maskoret_kovaat_maanak       number;
    v_maskoret_kovaat_guf          number;
    v_maskoret_kovaat_tikra        number;
    v_maskoret_maanak_tikra        number;
    v_is_gimlat_kefel              number;
    v_overlap_percent              number;
    v_achuz_kizba_fixed            number;
    v_chelkiyut_sofit              number;
    v_percent_sherut_zahal         number;
    v_odef_chodashim               number;
    v_odef_yamim                   number;
    v_odef                         number;
    v_is_sheerim                   number;
    v_sum_achuz_kizba              number;
    v_max_achuz_kizba              number;
    v_e_zakaut                     number;
    v_is_zakai_maanak_sheer        number;
    v_sum_hafchata                 number;
    v_achuz_kizba_chelkiyut_melea  number;
    v_achz_kzba_chel_mela_achry_hg number;
    v_code_group_prisha            number;
    v_code_sug_bakasha             number;
    v_seq_netuney_tk_mchushvim_prv number;
    v_seq_bakasha_zakaut_prev      number;
    v_code_yadani                  number;
    v_date_end_zakaut              date;
    v_sum_achuz_kizba_chuka        number;
    v_code_bakasha_details         number;
    v_tkufa_mezaka                 number;
    v_kpm_tkz_prtcption            number;
    v_overlap_percent_maanak       number;
  begin
    ---if chuka yadanit- return!!
    v_code_yadani := get_code_yadani(p_seq_bakasha);
    if nvl(v_code_yadani, 0) > 0 then
      return;
    end if;
  
    select t.code_sug_bakasha, t.code_bakasha_detail
      into v_code_sug_bakasha, v_code_bakasha_details
      from bakasha t
     where t.seq_bakasha = p_seq_bakasha;
  
    --sheer penyoni - get achuz from previos bakasha
    if sheerim_is_by_prev_bakasha(v_code_sug_bakasha,
                                  v_code_bakasha_details) = 1 then
      v_seq_netuney_tk_mchushvim_prv := sheerin_get_prev_netuney_tik(p_seq_bakasha,
                                                                     p_code_department);
    
      --exists netuney zkakur in prev bakasha
      if v_seq_netuney_tk_mchushvim_prv is not null then
        select t.chelkiyut_sofit,
               t.achuz_kizba_sofi,
               t.tkufa_mezaka_sherut,
               t.seq_bakasha
          into v_chelkiyut_sofit,
               v_achuz_kizba_sofi,
               v_tkufa_mezaka,
               v_seq_bakasha_zakaut_prev
          from netuney_tik_mechushavim t
         where t.seq_netuney_tik_mechushavim =
               v_seq_netuney_tk_mchushvim_prv;
      
      end if;
    end if;
  
    if v_seq_netuney_tk_mchushvim_prv is not null and
       v_chelkiyut_sofit is not null and v_achuz_kizba_sofi is not null and
       (nvl(v_tkufa_mezaka, 0) <> 0 or v_code_sug_bakasha not in (9, 23)) then
      restart_the_fields(p_seq_bakasha, p_code_department, null);
      for r in (select t.achuz_kizba_sofi,
                       t.chelkiyut_sofit,
                       t.achuz_kizba_kafuf_chelkiyut,
                       t.chelkiyut_meshuklelet_sherut,
                       t.tkufa_mezaka_sherut,
                       t.tkufa_lo_mezaka_sherut,
                       t.achuz_kizba_chelkiyut_melea,
                       t.mispar_misra,
                       t.ahuz_kizb_achry_hagdl_kaf_chel,
                       t.code_group_prisha,
                       t.tkufa_mezaka_medina_only,
                       t.chodeshim_mezkim_out_of_srv_m
                  from netuney_tik_mechushavim t
                 where t.seq_bakasha = v_seq_bakasha_zakaut_prev
                   and t.code_department = p_code_department) loop
        v_seq_netuney_tik_mechushavim := insrt_ntuny_tik_mchshvim_mdina(r.tkufa_mezaka_sherut,
                                                                        r.chelkiyut_meshuklelet_sherut,
                                                                        r.achuz_kizba_kafuf_chelkiyut,
                                                                        r.tkufa_lo_mezaka_sherut,
                                                                        --temp 22-05-2019
                                                                        case
                                                                          when v_code_sug_bakasha = 23 and
                                                                               r.code_group_prisha <> 2 then
                                                                           nvl(r.achuz_kizba_chelkiyut_melea,
                                                                               r.achuz_kizba_sofi)
                                                                          else
                                                                           r.achuz_kizba_sofi
                                                                        end,
                                                                        /*r.achuz_kizba_sofi,*/
                                                                        r.achuz_kizba_sofi,
                                                                        r.chelkiyut_sofit,
                                                                        r.achuz_kizba_sofi,
                                                                        null,
                                                                        null,
                                                                        p_seq_bakasha,
                                                                        p_code_department,
                                                                        r.mispar_misra,
                                                                        r.tkufa_mezaka_medina_only,
                                                                        r.chodeshim_mezkim_out_of_srv_m);
      
        update netuney_tik_mechushavim t
           set t.ahuz_kizb_achry_hagdl_kaf_chel = r.achuz_kizba_sofi
         where t.seq_bakasha = p_seq_bakasha
           and t.code_department = p_code_department
           and t.mispar_misra = r.mispar_misra;
      
      end loop;
    
    else
      --not sheerim or not exists netuney zkakur in prev bakasha -- calc data of current bakasha
      publc_insrt_ntuny_tik_mchshvim(p_seq_bakasha,
                                     1,
                                     p_code_department,
                                     p_as_of_date);
      --חישוב חוקה מלא, בטל אזהרה על חישוב חלקי
      update netuney_tik_mechushavim n
         set n.code_e_zakaut = null
       where n.seq_bakasha = p_seq_bakasha
         and n.code_department = p_code_department;
    
      v_seq_netuney_tik_mechushavim := Get_seq_netuny_tik_mechushavim(p_seq_bakasha,
                                                                      p_code_department,
                                                                      0);
      --   check gimlaot kefel
      select count(*), max(p.sum)
        into v_is_gimlat_kefel, v_maskoret_kovaat_guf
        from participation p
       where p.code_participation = 6
         and p.seq_bakasha = p_seq_bakasha;
    
      if (v_is_gimlat_kefel >= 1) then
        select sum(t.percent_participate * t.sum * t.partial_period /
                   v_maskoret_kovaat_guf),
               max(t1.maskoret_kovaat-nvl(t1.mikdmat_yoker,0)),
               max(nvl(t1.maskoret_lemaanak, t1.maskoret_kovaat)-nvl(t1.mikdmat_yoker,0)),
               greatest(v_maskoret_kovaat_guf, max(t1.maskoret_kovaat-nvl(t1.mikdmat_yoker,0))),
               greatest(v_maskoret_kovaat_guf,
                        max(nvl(t1.maskoret_lemaanak, t1.maskoret_kovaat)-nvl(t1.mikdmat_yoker,0))),
               sum(t.tkufa_mezaka),
               sum(t.public_tkufa_mezaka)
          into v_achuz_kizba_guf,
               v_maskoret_kovaat_medina,
               v_maskoret_kovaat_maanak,
               v_maskoret_kovaat_tikra,
               v_maskoret_maanak_tikra,
               v_tkufa_mezaka_guf,
               v_public_tkufa_mezaka_guf
          from participation t
          left join bakasha_regila t1
            on t.seq_bakasha = t1.seq_bakasha
         where t.seq_bakasha = p_seq_bakasha
           and t.code_participation = 6;
      
        select nvl(round(sum(months_between(t.date_to + 1, t.date_from)) / 6,
                         2),
                   0)
          into v_percent_sherut_zahal
          from participation_tkufot t
          left join participation t1
            on t.seq_participation = t1.seq_participation
         where t1.seq_guf = 165
           and t.code_sug_tkufa = 3
           and t1.seq_bakasha = p_seq_bakasha;
      
        if v_percent_sherut_zahal > 0 then
          v_percent_sherut_zahal := round_percent_by_months(v_percent_sherut_zahal);
          update participation t
             set t.achuz_guf_zahal = v_percent_sherut_zahal
           where t.seq_guf = 165
             and t.seq_bakasha = p_seq_bakasha;
        
        end if;
      
      end if;
    
      v_is_by_nechut := calc_achuz_kizba_lefy_nechut(p_seq_bakasha,
                                                     v_seq_netuney_tik_mechushavim,
                                                     p_code_department);
    
      v_is_by_sheerim := calc_sheerim(p_seq_bakasha,
                                      v_seq_netuney_tik_mechushavim,
                                      v_is_gimlat_kefel,
                                      v_maskoret_kovaat_tikra,
                                      v_is_zakai_maanak_sheer,
                                      p_code_department,
                                      p_as_of_date);
    
      if v_is_by_nechut = 0 and
         (v_is_by_sheerim = 0 or get_sheer_group(p_seq_bakasha) in (2, 3)) then
        calc_by_sherut(p_seq_bakasha, p_code_department);
      
        calc_pizuy_odef_shanim(p_seq_bakasha,
                               v_is_gimlat_kefel,
                               v_maskoret_kovaat_tikra,
                               p_code_department);
      
      end if;
    
      if (v_is_gimlat_kefel >= 1) then
        select t2.achuz_kizb_achry_hagdl_chl_mla,
               t2.achuz_kizba_chelkiyut_melea,
               t2.achuz_kizba_sofi,
               case
                 when t2.code_group_prisha = 1 then
                  least(t2.chelkiyut_meshuklelet_sherut, t2.chelkiyut_sofit)
                 else
                  t2.chelkiyut_sofit
               end
          into v_achz_kzba_chel_mela_achry_hg,
               v_achuz_kizba_chelkiyut_melea,
               v_achuz_kizba_sofi,
               v_chelkiyut_sofit
          from netuney_tik_mechushavim t2
         where t2.seq_bakasha = p_seq_bakasha
           and t2.code_department = p_code_department
           and t2.mispar_misra = 0;
      
        v_overlap_percent := pk_participation_2_guff.Get_overlapping_months(p_seq_bakasha,
                                                                            1,
                                                                            1) / 6;
      v_overlap_percent_maanak := pk_participation_2_guff.Get_overlapping_months(p_seq_bakasha,
                                                                            1,
                                                                            0) / 6;
        calc_gimlaot_kefel(v_maskoret_kovaat_guf * v_achuz_kizba_guf * 0.01,
                           v_maskoret_kovaat_tikra,
                           v_maskoret_kovaat_medina,
                           v_achuz_kizba_chelkiyut_melea,
                           v_achz_kzba_chel_mela_achry_hg,
                           v_achuz_kizba_sofi,
                           v_achuz_kizba_fixed,
                           v_overlap_percent,
                           v_chelkiyut_sofit,
                           v_percent_sherut_zahal,
                           v_maskoret_kovaat_guf,
                           v_achuz_kizba_guf,
                           v_maskoret_kovaat_maanak,
                           v_maskoret_maanak_tikra,
                           v_odef_chodashim,
                           v_odef_yamim,
                           v_sum_hafchata,
                           v_odef,
                           v_overlap_percent_maanak);
                           
     if is_zakai_odef(p_seq_bakasha) = 0 then
       v_odef :=0;
       v_odef_chodashim :=0;
       v_odef_yamim :=0;
       end if;                   
                           
        update netuney_tik_mechushavim n
           set n.achuz_kizba_sofi    = v_achuz_kizba_sofi,
               n.achuz_kizba_fixed   = v_achuz_kizba_fixed,
               n.tkufa_overlap_kizba = round(v_overlap_percent * 6, 2),
               --19/07/18 by rivka 
               --Add the case condition to the 2 next fields
               n.chodshey_pizuy = case
                                    when nvl(v_odef, 0) < 0 then
                                     0
                                    else
                                     nvl(v_odef, 0)
                                  end,
               n.odef_sherut_chodashim = case
                                           when nvl(v_odef_chodashim, 0) < 0 then
                                            0
                                           else
                                            nvl(v_odef_chodashim, 0)
                                         end,
               n.odef_sherut_yamim = case
                                       when nvl(v_odef_yamim, 0) < 0 then
                                        0
                                       else
                                        nvl(v_odef_yamim, 0)
                                     end
         where n.seq_netuney_tik_mechushavim =
               v_seq_netuney_tik_mechushavim;
      end if;
    
      if v_is_by_sheerim <> 1 then
        calc_is_zakay_maanak(p_seq_bakasha,
                             v_seq_netuney_tik_mechushavim,
                             v_is_gimlat_kefel,
                             v_overlap_percent);
        if p_code_department = 2 then
          calc_hoze_bchirim(p_seq_bakasha, p_code_department);
        end if;
      end if;
    end if;
    v_date_start_zakaut := calc_is_zakay_kizba(p_seq_bakasha,
                                               v_seq_netuney_tik_mechushavim,
                                               v_code_seif_prisha,
                                               v_date_end_zakaut,
                                               p_code_department,
                                               p_as_of_date);
  
    update netuney_tik_mechushavim n
       set n.date_update       = sysdate,
           n.date_start_zakaut = v_date_start_zakaut,
           n.date_end_zakaut   = v_date_end_zakaut
     where n.seq_bakasha = p_seq_bakasha
       and n.code_department = p_code_department;
  
    if v_date_start_zakaut is not null then
    
      --stop kapam
      select max(t.seq_participation)
        into v_kpm_tkz_prtcption
        from v_bakasha_last_status v
        left join v_bakasha_last_status b_kpm
          on v.seq_prisha = b_kpm.seq_prisha
         and b_kpm.code_sug_bakasha in (10, 11)
        left join participation t
          on t.seq_bakasha = b_kpm.seq_bakasha
       where v.seq_bakasha = p_seq_bakasha
         and t.seq_guf = 552
         and t.code_participation = 4
         and b_kpm.code_action <> 17;
      --there is kapam taktzivit
      if v_kpm_tkz_prtcption is not null then
        update participation t
           set t.date_end = v_date_start_zakaut - 1, t.code_hafsaka = 6
         where t.seq_participation = v_kpm_tkz_prtcption;
      end if;
    
      update bakasha_regila b
         set b.code_seif_prisha = v_code_seif_prisha
       where b.seq_bakasha = p_seq_bakasha;
    end if;
    --calc sheer pensyoni
  
    --if get_sheer_group(p_seq_bakasha) = 2 then
    if sheerim_is_by_prev_bakasha(v_code_sug_bakasha,
                                  v_code_bakasha_details) = 1 then
      for r in (select t.mispar_misra
                  from netuney_tik_mechushavim t
                 where t.seq_bakasha = p_seq_bakasha
                   and t.code_department = p_code_department) loop
        ---------------save achuz kizba sofi
        update netuney_tik_mechushavim t
           set t.achuz_kizba_maximali = t.achuz_kizba_sofi
         where t.seq_bakasha = p_seq_bakasha
           and t.code_department = p_code_department
           and t.mispar_misra = r.mispar_misra;
      
        sheerim_calc_achuz_kizba(p_seq_bakasha,
                                 v_is_sheerim,
                                 v_sum_achuz_kizba,
                                 v_max_achuz_kizba,
                                 v_is_zakai_maanak_sheer,
                                 v_e_zakaut,
                                 r.mispar_misra,
                                 p_as_of_date,
                                 v_sum_achuz_kizba_chuka,
                                 p_code_department);
      
        update netuney_tik_mechushavim n
           set n.achuz_kizba_sofi = v_sum_achuz_kizba,
               --n.code_maanak_almana = v_is_zakai_maanak_sheer,
               n.code_e_zakaut = v_e_zakaut
         where n.seq_bakasha = p_seq_bakasha
           and n.code_department = p_code_department
           and n.mispar_misra = r.mispar_misra;
      end loop;
    end if;
    --calc hisachon pensyoni
  
  exception
    when others then
      update netuney_tik_mechushavim n
         set n.code_e_zakaut = nvl(n.code_e_zakaut, 999),
             n.date_update   = sysdate
       where n.seq_netuney_tik_mechushavim = v_seq_netuney_tik_mechushavim;
    
  end;
  -----------------------------------------------
  function is_zakai_odef(p_seq_bakasha number) return number is
    v_seq_ezor_ovdim number ;
    v_age number;
    v_is_ganenet number;
  begin
    select v.seq_ezor_ovdim,
           months_between(v.taarich_prisha, p.taarich_leda) / 12,
           case br.chinuch_mikzoa
             when 911 then
              1
             else
              0
           end
      into v_seq_ezor_ovdim,
           v_age,
           v_is_ganenet
      from v_bakasha_last_status v
      left join poresh p
        on v.seq_porshim = p.porshim_seq
      left join bakasha_regila br
        on v.seq_bakasha = br.seq_bakasha
     where v.SEQ_BAKASHA = p_seq_bakasha;
     
          if  (get_sheer_group(p_seq_bakasha) not in (2, 3) and
       (((v_seq_ezor_ovdim not in (163, 164, 225) and
       (v_age >= 60 or (v_age >= 59 and v_is_ganenet = 1))) or
       (v_seq_ezor_ovdim in (163, 164, 225) and v_age >= 57)))) then
       return 1;
       else
         return 0;
         end if;
       
  end;
  ----------------------------------------------
  procedure publc_insrt_ntuny_tik_mchshvim(p_seq_bakasha     number,
                                           p_calc_all        number default 0,
                                           p_code_department number,
                                           p_as_of_date      in date default null) is
    v_seq                          number;
    v_total_months                 number;
    v_chelkiyut_meshuklelet_sherut number;
    v_achuz_kizba_kafuf_chelkiyut  number;
    v_tkufa_lo_mezaka              number;
    v_achuz_kizba_chelkiyut_melea  number;
    v_ahuz_kizb_achry_hgdl_kaf_chl number;
    v_chelkiyut_sofit              number;
    v_achuz_kizba_sofi             number;
    v_peroid_medina_service        number;
    v_peroid_medina_out_of_service number;
    v_seq_ezor_ovdim               number;
  begin
  if p_seq_bakasha <> -1 then
    pk_prm_utils.update_misra_when_choze_bchirim(p_seq_bakasha);
    end if;
    if p_calc_all = 1 then
      delete from netuney_tik_mechushavim t
       where t.seq_bakasha = p_seq_bakasha
         and t.code_department = p_code_department
         and t.mispar_misra <> 0;
    end if;
  
    if p_code_department = 1 or p_calc_all = 1 then
    
      calc_ntuny_tik_mchshvim_medina(p_seq_bakasha,
                                     v_total_months,
                                     v_chelkiyut_meshuklelet_sherut,
                                     v_achuz_kizba_kafuf_chelkiyut,
                                     v_tkufa_lo_mezaka,
                                     v_achuz_kizba_chelkiyut_melea,
                                     v_ahuz_kizb_achry_hgdl_kaf_chl,
                                     v_chelkiyut_sofit,
                                     v_achuz_kizba_sofi,
                                     0,
                                     null,
                                     p_as_of_date,
                                     v_peroid_medina_service,
                                     v_peroid_medina_out_of_service);
      restart_the_fields(p_seq_bakasha, p_code_department, null);
      v_seq := insrt_ntuny_tik_mchshvim_mdina(v_total_months,
                                              v_chelkiyut_meshuklelet_sherut,
                                              v_achuz_kizba_kafuf_chelkiyut,
                                              v_tkufa_lo_mezaka,
                                              v_achuz_kizba_chelkiyut_melea,
                                              v_ahuz_kizb_achry_hgdl_kaf_chl,
                                              v_chelkiyut_sofit,
                                              v_achuz_kizba_sofi,
                                              null,
                                              null,
                                              p_seq_bakasha,
                                              p_code_department,
                                              0,
                                              v_peroid_medina_service,
                                              v_peroid_medina_out_of_service);
    else
      for r in (select max(t.mispar_misra) mispar_misra
                  from tkufot_avoda_mechushv t
                 where t.seq_bakasha = p_seq_bakasha
                 group by t.mispar_misra
                 order by mispar_misra) loop
      
        calc_ntuny_tik_mchshvim_medina(p_seq_bakasha,
                                       v_total_months,
                                       v_chelkiyut_meshuklelet_sherut,
                                       v_achuz_kizba_kafuf_chelkiyut,
                                       v_tkufa_lo_mezaka,
                                       v_achuz_kizba_chelkiyut_melea,
                                       v_ahuz_kizb_achry_hgdl_kaf_chl,
                                       v_chelkiyut_sofit,
                                       v_achuz_kizba_sofi,
                                       0,
                                       r.mispar_misra,
                                       p_as_of_date,
                                       v_peroid_medina_service,
                                       v_peroid_medina_out_of_service);
        restart_the_fields(p_seq_bakasha, p_code_department, null);
        v_seq := insrt_ntuny_tik_mchshvim_mdina(v_total_months,
                                                v_chelkiyut_meshuklelet_sherut,
                                                v_achuz_kizba_kafuf_chelkiyut,
                                                v_tkufa_lo_mezaka,
                                                v_achuz_kizba_chelkiyut_melea,
                                                v_ahuz_kizb_achry_hgdl_kaf_chl,
                                                v_chelkiyut_sofit,
                                                v_achuz_kizba_sofi,
                                                null,
                                                null,
                                                p_seq_bakasha,
                                                p_code_department,
                                                r.mispar_misra,
                                                v_peroid_medina_service,
                                                v_peroid_medina_out_of_service);
      end loop;
    end if;
    --remark--only netuney tkufot calc
   
  if p_seq_bakasha<>-1 then
   update netuney_tik_mechushavim t
       set t.code_e_zakaut = 11
     where t.seq_bakasha = p_seq_bakasha
       and t.code_department = p_code_department
       and t.mispar_misra = 0
       and nvl(t.yadani, 0) = 0;
  end if;
    if p_code_department = 1 then
      publc_insrt_ntuny_tik_mchshvim(p_seq_bakasha, 0, 2);
    end if;
    select p.seq_ezor_ovdim
      into v_seq_ezor_ovdim
      from prisha p
      left join bakasha b
        on p.seq_prisha = b.seq_prisha
     where b.seq_bakasha = p_seq_bakasha;
    if p_code_department = 2 and
       pk_zakaut.is_security_special(v_seq_ezor_ovdim) = 1 then
    
      update netuney_tik_mechushavim t
         set t.ahuz_kizb_achry_hagdl_kaf_chel = greatest(nvl(t.ahuz_kizb_achry_hagdl_kaf_chel,
                                                             0),
                                                         nvl(v_ahuz_kizb_achry_hgdl_kaf_chl,
                                                             0))
       where t.seq_bakasha = p_seq_bakasha
         and t.code_department = 1
         and t.mispar_misra = 0
         and nvl(t.yadani, 0) = 0;
    end if;
  
  end;
  ---------------------------------------------
  procedure calc_hoze_bchirim(p_seq_bakasha     number,
                              p_code_department number,
                              p_as_of_date      date) is
    v_achuz_kizba_sofi_misra_0     number;
    v_is_hoze_bchirim              number;
    v_code_chishuv_bchirim         number;
    v_total_months                 number;
    v_chelkiyut_meshuklelet_sherut number;
    v_achuz_kizba_kafuf_chelkiyut  number;
    v_tkufa_lo_mezaka              number;
    v_achuz_kizba_chelkiyut_melea  number;
    v_ahuz_kizb_achry_hgdl_kaf_chl number;
    v_chelkiyut_sofit              number;
    v_achuz_kizba_sofi             number;
    v_seq                          number;
    v_total_months_all             number;
    v_total_months_all_not_round   number;
    v_achuz_kizba_sofi_all         number;
    v_is_zakai_lmaanak             number;
    v_achuz_kizba_gil_60           number;
    v_code_group_prisha            number;
    v_achuz_kizba_gil_60_all       number;
    v_achuz_kizba_gil_60_misra_0   number;
    v_pizuy_odef_shanim            number;
    v_peroid_medina_service        number := 0;
    v_peroid_medina_out_of_service number := 0;
  begin
    --קיים חוזה בכירים?
    select max(t.mispar_misra) mispar_misra
      into v_is_hoze_bchirim
      from tkufot_avoda_mechushv t
     where t.seq_bakasha = p_seq_bakasha;
  
    if v_is_hoze_bchirim > 0 then
    
      select b.code_chishuv_bchirim,
             n.tkufa_mezaka_sherut_not_round,
             n.achuz_kizba_sofi,
             n.achuz_kizba_gil_60,
             n.chodshey_pizuy,
             n.tkufa_mezaka_sherut
        into v_code_chishuv_bchirim,
             v_total_months_all_not_round,
             v_achuz_kizba_sofi_all,
             v_achuz_kizba_gil_60_all,
             v_pizuy_odef_shanim,
             v_total_months_all
        from bakasha_regila b
        left join netuney_tik_mechushavim n
          on n.seq_bakasha = p_seq_bakasha
         and n.code_department = p_code_department
         and n.mispar_misra = 0
       where b.seq_bakasha = p_seq_bakasha;
    
      --loop to calc each misra
      for r in (select max(t.mispar_misra) mispar_misra
                  from tkufot_avoda_mechushv t
                 where t.seq_bakasha = p_seq_bakasha
                 group by t.mispar_misra
                 order by mispar_misra) loop
      
        calc_ntuny_tik_mchshvim_medina(p_seq_bakasha,
                                       v_total_months,
                                       v_chelkiyut_meshuklelet_sherut,
                                       v_achuz_kizba_kafuf_chelkiyut,
                                       v_tkufa_lo_mezaka,
                                       v_achuz_kizba_chelkiyut_melea,
                                       v_ahuz_kizb_achry_hgdl_kaf_chl,
                                       v_chelkiyut_sofit,
                                       v_achuz_kizba_sofi,
                                       0,
                                       r.mispar_misra,
                                       p_as_of_date,
                                       v_peroid_medina_service,
                                       v_peroid_medina_out_of_service);
        --if total of all misrot bigger then 0.5 ' it rounded up
        --add 1 month to the misra that has bigger number after the natural number      
        if mod(v_total_months_all_not_round, 1) > 0.5 and
           mod(v_total_months_all_not_round, 1) - mod(v_total_months, 1) <
           mod(v_total_months, 1) then
          v_total_months := floor(v_total_months) + 1;
        else
          v_total_months := round(v_total_months);
        end if;
        --type 1 : achuz_kizba_kafuf_chlkyt_all / 2
        if v_code_chishuv_bchirim = 1 then
          v_achuz_kizba_sofi := v_achuz_kizba_sofi_all / 2;
          if r.mispar_misra = 1 and
             v_achuz_kizba_sofi + v_achuz_kizba_sofi_misra_0 <>
             round_percent_by_months(v_achuz_kizba_sofi +
                                     v_achuz_kizba_sofi_misra_0) then
            v_achuz_kizba_sofi := round_percent_by_months(v_achuz_kizba_sofi +
                                                          v_achuz_kizba_sofi_misra_0) -
                                  v_achuz_kizba_sofi_misra_0;
          end if;
          --type 2 : meshuklal 
        elsif v_code_chishuv_bchirim = 2 then
          v_achuz_kizba_sofi := v_total_months / v_total_months_all *
                                v_achuz_kizba_sofi_all;
        
          --type 3 : meshupar
        else
          if r.mispar_misra = 0 then
            v_achuz_kizba_sofi := least(v_total_months / 420 * 70, 50);
          
          else
            v_achuz_kizba_sofi := least(70 - v_achuz_kizba_sofi_misra_0,
                                        v_total_months / 420 * 70);
          
          end if;
        end if;
      
        if v_achuz_kizba_gil_60_all is not null then
          v_achuz_kizba_gil_60 := round(v_achuz_kizba_sofi /
                                        v_achuz_kizba_sofi_all *
                                        v_achuz_kizba_gil_60_all,
                                        2);
        end if;
      
        --שיטות חישוב     
        v_achuz_kizba_sofi := round(v_achuz_kizba_sofi, 2);
        if r.mispar_misra = 0 then
        
          v_achuz_kizba_sofi_misra_0 := v_achuz_kizba_sofi;
        end if;
        if r.mispar_misra = 1 then
          if (nvl(v_code_chishuv_bchirim, 0) in (1, 2) and
             v_achuz_kizba_sofi_all <>
             round_percent_by_months(v_achuz_kizba_sofi +
                                      v_achuz_kizba_sofi_misra_0)) then
            v_achuz_kizba_sofi := round_percent_by_months(v_achuz_kizba_sofi_all) -
                                  v_achuz_kizba_sofi_misra_0;
          elsif ((nvl(v_code_chishuv_bchirim, 0) not in (1, 2) and
                v_achuz_kizba_sofi + v_achuz_kizba_sofi_misra_0 <>
                round_percent_by_months(v_achuz_kizba_sofi +
                                          v_achuz_kizba_sofi_misra_0))) then
            v_achuz_kizba_sofi := round_percent_by_months(v_achuz_kizba_sofi +
                                                          v_achuz_kizba_sofi_misra_0) -
                                  v_achuz_kizba_sofi_misra_0;
          end if;
        end if;
        select t2.code_group_prisha, t2.is_zakai_lmaanak
        --t2.achuz_kizba_gil_60
          into v_code_group_prisha, v_is_zakai_lmaanak
        --v_achuz_kizba_gil_60
          from netuney_tik_mechushavim t2
         where t2.seq_bakasha = p_seq_bakasha
           and t2.code_department = p_code_department
           and t2.mispar_misra = 0;
      
        --if there is pizuy odef shanim then always chelkiyut sofit is 1
        if nvl(v_pizuy_odef_shanim, 0) > 0 then
          v_chelkiyut_sofit := 1;
        end if;
        v_seq := insrt_ntuny_tik_mchshvim_mdina(v_total_months,
                                                v_chelkiyut_meshuklelet_sherut,
                                                v_achuz_kizba_kafuf_chelkiyut,
                                                v_tkufa_lo_mezaka,
                                                v_achuz_kizba_chelkiyut_melea,
                                                v_ahuz_kizb_achry_hgdl_kaf_chl,
                                                v_chelkiyut_sofit,
                                                v_achuz_kizba_sofi,
                                                v_is_zakai_lmaanak,
                                                v_achuz_kizba_gil_60,
                                                p_seq_bakasha,
                                                p_code_department,
                                                r.mispar_misra,
                                                v_peroid_medina_service,
                                                v_peroid_medina_out_of_service);
      
      end loop;
    
    end if; --חוזה בכירים
  end;
  ---------------------------------------------
  procedure calc_data_tkufa_mezaka(p_seq_bakasha                  in number,
                                   p_type_query                   in number,
                                   p_chelkiyut_meshuklelet_sherut out number,
                                   p_achuz_kizba_kafuf_chelkiyut  out number,
                                   v_peroid                       in out number,
                                   p_mispar_misra                 number default null) is
    -- p_type_query : 0 - regular,
    -- 1 - add keva, 
    --2 - only chova 
    --3 - only avoda medina 
    --4 only kviut 
    --5 only work in police
    --6 minimum years service
    --7 only medina servise
    --8 only medinaout of servise 
    --9 only medinaout of servise for WS
    v_first_peroid_before_chova date;
    v_first_peroid_from_date    date;
    v_is_security               number;
    v_seq_ezor_ovdim            number;
  begin
    --Calculate data to tkufa mezaka 
    select t.seq_ezor_ovdim
      into v_seq_ezor_ovdim
      from v_bakasha_last_status t
     where t.seq_bakasha = p_seq_bakasha;
  
    v_is_security := is_security(v_seq_ezor_ovdim);
  
    select min(t.taarich_me)
      into v_first_peroid_from_date
      from tkufot_avoda_mechushv t
      left join code_sug_zchuyot_mechushavim t1
        on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
     where t.seq_bakasha = p_seq_bakasha
          --and t.code_sugey_tkufot = 3
       and t1.haim_nirkash = 1;
    select min(t.taarich_me)
      into v_first_peroid_before_chova
      from tkufot_avoda_mechushv t
      left join code_sug_zchuyot_mechushavim t1
        on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
     where t.seq_bakasha = p_seq_bakasha
       and t.code_sugey_tkufot <> 5
       and t1.haim_nirkash = 1;
  
    with a as
     (select months_between(t.taarich_ad + 1, t.taarich_me) -
             nvl(t.except_from_tkufa, 0) peroid,
             least(t.achuz_chelkyut, 1) achuz_chelkyut,
             decode(t.code_achuz_mugdal, null, 6, 4) achuz_kizba
        from tkufot_avoda_mechushv t
        left join code_sug_zchuyot_mechushavim t1
          on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
       where t.seq_bakasha = p_seq_bakasha
         and (t.mispar_misra = p_mispar_misra or p_mispar_misra is null)
            -- haim nirkash
         and (t1.haim_nirkash = 1
             
             and
             ((p_type_query in (0, 1, 3, 4, 5, 6, 7, 8, 9) and
             (t.achuz_chelkyut >= 0.333 or
             t.taarich_ad < to_date('01/01/1967', 'dd/mm/yyyy')
             --15-01-2025 for merkava WS
             or p_type_query = 9) and
             (t.code_sugey_tkufot not in (4, 20) or p_type_query <> 4) and
             --only keren
             (t.code_sugey_tkufot = 7 or p_type_query <> 8) and
             --only keren
             (t.code_sugey_tkufot = 7 or p_type_query <> 9) and
             --except 
             (t.code_sugey_tkufot <> 7 or p_type_query <> 7) and
             (t.ezor_ovdim_be_tkufa in (163, 164, 225) or
             p_type_query <> 5) and (t.code_sugey_tkufot not in (5) or
             v_first_peroid_from_date <
             to_date('01/01/2001', 'dd/mm/yyyy')) and
             (t.code_sugey_tkufot not in (5) or p_type_query not in (3) or
             (v_first_peroid_before_chova < t.taarich_me and
             is_security(v_seq_ezor_ovdim) = 0))) or
             ((p_type_query in (1) and t.code_sugey_tkufot = 6) or
             (p_type_query in (2) and t.code_sugey_tkufot = 5)))
             
             or p_type_query = 6 and t.code_sugey_tkufot = 7)),
    b as
     (select sum(achuz_chelkyut * peroid) / sum(peroid) chelkiyut_meshuklelet_sherut,
             
             sum(peroid) total_peroid
        from a),
    c as
     (select
      
       round(sum(peroid)) / 6 achuz_kizba_kafuf_chelkiyut
        from a
      
      )
    select b.chelkiyut_meshuklelet_sherut,
           b.total_peroid,
           c.achuz_kizba_kafuf_chelkiyut
      into p_chelkiyut_meshuklelet_sherut,
           v_peroid,
           p_achuz_kizba_kafuf_chelkiyut
      from b, c;
  /*if v_peroid > 420 and p_chelkiyut_meshuklelet_sherut < 1 then
      p_chelkiyut_meshuklelet_sherut := calc_chelkiyut_over_70(p_seq_bakasha);
    end if;*/
  end;
  ---------------------------------------------
  function calc_chelkiyut_over_70(p_seq_bakasha number) return number is
    v_months_count    number := 0;
    v_chelkiyut       number := 0;
    v_chelkiyut_zvura number := 0;
  begin
    begin
    
      --Calc chelkiyut from 420 best
      for r in (select least(t.achuz_chelkyut, 1) chelkiyut,
                       months_between(t.taarich_ad + 1, t.taarich_me) months,
                       rownum
                  from tkufot_avoda_mechushv t
                  left join code_sug_zchuyot_mechushavim t1
                    on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
                 where t.seq_bakasha = p_seq_bakasha
                   and t1.haim_nirkash = 1
                 order by t.achuz_chelkyut desc) loop
      
        v_chelkiyut_zvura := v_chelkiyut_zvura +
                             (least(r.chelkiyut, 1) *
                             least(r.months, 420 - v_months_count));
        v_months_count    := v_months_count + r.months;
      
        if v_months_count >= 420 then
          exit;
        end if;
      end loop;
    end;
    v_chelkiyut := v_chelkiyut_zvura / 420;
    return v_chelkiyut;
  
  end;

  ---------------------------------------------
  procedure calc_ntuny_tik_mchshvim_medina(p_seq_bakasha                  number,
                                           p_total_months                 out number,
                                           p_chelkiyut_meshuklelet_sherut out number,
                                           p_achuz_kizba_kafuf_chelkiyut  out number,
                                           p_tkufa_lo_mezaka              out number,
                                           p_achuz_kizba_chelkiyut_melea  in out number,
                                           p_ahuz_kizb_achry_hgdl_kaf_chl in out number,
                                           p_chelkiyut_sofit              in out number,
                                           p_achuz_kizba_sofi             in out number,
                                           p_is_add_keva                  number,
                                           p_mispar_misra                 number default null,
                                           p_as_of_date                   in date default null,
                                           p_peroid_medina_service        out number,
                                           p_peroid_medina_out_of_service out number) is
  
    v_peroid                         number := 0;
    v_mod_achuz_kizba_hagdala        number := 0;
    v_achuz_kizba_hagdala            number := 0;
    v_chelkiyut_meshuklelet_sherut_f number;
    v_achuz_kizba_kafuf_chelkiyut_f  number;
  begin
    calc_data_tkufa_mezaka(p_seq_bakasha,
                           p_is_add_keva,
                           p_chelkiyut_meshuklelet_sherut,
                           p_achuz_kizba_kafuf_chelkiyut,
                           v_peroid,
                           p_mispar_misra);
    p_total_months := v_peroid;
  
    --Calculate period tkufa_lo_mezaka
    select sum(months_between(t.taarich_ad + 1, t.taarich_me)) peroid
      into p_tkufa_lo_mezaka
      from tkufot_avoda_mechushv t
      left join code_sug_zchuyot_mechushavim t1
        on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
     where t.seq_bakasha = p_seq_bakasha
          -- haim nirkash
       and t1.haim_nirkash = 0;
  
    calc_hagdalot(p_seq_bakasha, v_achuz_kizba_hagdala, 0, p_as_of_date);
  
    --The order of the round is important:
    p_chelkiyut_meshuklelet_sherut := round(p_chelkiyut_meshuklelet_sherut,
                                            3);
    p_achuz_kizba_kafuf_chelkiyut  := round(p_achuz_kizba_kafuf_chelkiyut,
                                            2);
    p_achuz_kizba_chelkiyut_melea  := round((p_chelkiyut_meshuklelet_sherut *
                                            p_achuz_kizba_kafuf_chelkiyut),
                                            2);
  
    p_tkufa_lo_mezaka              := round(p_tkufa_lo_mezaka, 0);
    p_ahuz_kizb_achry_hgdl_kaf_chl := round_percent_by_months(p_achuz_kizba_kafuf_chelkiyut +
                                                              nvl(v_achuz_kizba_hagdala,
                                                                  0));
    p_chelkiyut_sofit              := p_chelkiyut_meshuklelet_sherut;
    p_achuz_kizba_sofi             := p_ahuz_kizb_achry_hgdl_kaf_chl;
  
    --peroid medina service
    calc_data_tkufa_mezaka(p_seq_bakasha,
                           7,
                           v_chelkiyut_meshuklelet_sherut_f,
                           v_achuz_kizba_kafuf_chelkiyut_f,
                           p_peroid_medina_service,
                           p_mispar_misra);
    p_peroid_medina_service := round(p_peroid_medina_service);
    --peroid medina out of service
    calc_data_tkufa_mezaka(p_seq_bakasha,
                           8,
                           v_chelkiyut_meshuklelet_sherut_f,
                           v_achuz_kizba_kafuf_chelkiyut_f,
                           p_peroid_medina_out_of_service,
                           p_mispar_misra);
    p_peroid_medina_out_of_service := round(p_peroid_medina_out_of_service);
  end;

  --------------------------------------------
  function is_security(p_seq_ezor_ovdim number) return number is
    v_count_security_ezor_ovdim number;
  begin
    select count(*)
      into v_count_security_ezor_ovdim
      from ezor_ovdim_category c
     where c.seq_ezor_ovdim = p_seq_ezor_ovdim
       and c.code_sug_ezor_ovdim = 9;
  
    if v_count_security_ezor_ovdim > 0 then
      return 1;
    else
      return 0;
    end if;
  
  end;

  --------------------------------------------
  function is_security_special(p_seq_ezor_ovdim number) return number is
    v_count_security_ezor_ovdim number;
  
  begin
    select count(*)
      into v_count_security_ezor_ovdim
      from (select c.seq_ezor_ovdim
              from ezor_ovdim_category c
             where c.code_sug_ezor_ovdim = 17
               and c.seq_ezor_ovdim = p_seq_ezor_ovdim
            /*minus
            select c.seq_ezor_ovdim
              from ezor_ovdim_category c
             where c.code_sug_ezor_ovdim = 9
               and c.seq_ezor_ovdim = p_seq_ezor_ovdim)*/
            );
  
    if v_count_security_ezor_ovdim > 0 then
      return 1;
    else
      return 0;
    end if;
  
  end;

  --------------------------------------------
  procedure calc_hagdalot(p_seq_bakasha         number,
                          p_achuz_kizba_hagdala in out number,
                          p_maanak              number,
                          p_as_of_date          in date default null) is
    v_mod_achuz_kizba_hagdala number;
    v_date_prisha             date;
    v_seq_ezor_ovdim          number;
  begin
  
    if p_as_of_date is null then
      select t1.taarich_prisha, t1.seq_ezor_ovdim
        into v_date_prisha, v_seq_ezor_ovdim
        from v_bakasha_last_status t1
       where t1.seq_bakasha = p_seq_bakasha;
    else
      v_date_prisha := p_as_of_date;
    end if;
    if is_security_special(v_seq_ezor_ovdim) = 1 then
      calc_secuerity_hagdala(p_seq_bakasha);
    end if;
    --Get sum hagdala
    select nvl(sum(t.achuz_meushar), 0)
      into p_achuz_kizba_hagdala
      from hagdala_nimuk t
      left join bakasha_regila t1
        on t.seq_bakasha = t1.seq_bakasha
     where t.seq_bakasha = p_seq_bakasha
       and t.code_hagdala_status_nimuk = 3
          --maanak: without prisha_mukdemet(11) and beriut(7)
       and (t.code_nimuk not in (7, 11) or nvl(p_maanak, 0) = 0)
       and ((t1.to_date_zakaut is null or t1.to_date_zakaut > v_date_prisha) or
           t.code_nimuk <> 7);
  
    p_achuz_kizba_hagdala := round_percent_by_months(p_achuz_kizba_hagdala);
  
  end;
  ---------------------------------------------------------------------------
  procedure calc_secuerity_hagdala(p_seq_bakasha number) is
    v_periods_mugdal            number;
    v_secuerity_hagdala_percent number;
    v_md_percent                number;
  begin
    select sum(((((achuz_mugdal - 12) / 6) *
               (months_between(t.taarich_ad + 1, t.taarich_me))) / 12))
      into v_secuerity_hagdala_percent
      from tkufot_avoda_mechushv t
    
      left join code_sug_zchuyot_mechushavim t1
        on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
     where t.seq_bakasha = p_seq_bakasha
       and nvl(t.achuz_mugdal, 0) > 0
       and t1.haim_nirkash = 1;
    if nvl(v_secuerity_hagdala_percent, 0) > 0 then
    
      --  v_secuerity_hagdala_percent := round_percent_by_months(v_secuerity_hagdala_percent);
      v_md_percent := mod(v_secuerity_hagdala_percent, 2);
      if v_md_percent not in (0, 2) then
        --Round 
        select v_secuerity_hagdala_percent - v_md_percent +
               max(i.achuz_meugal)
          into v_secuerity_hagdala_percent
          from igul_chodashim i
         where i.from_achuz < v_md_percent;
      end if;
      v_secuerity_hagdala_percent := round(v_secuerity_hagdala_percent, 2);
    
      merge into hagdala_nimuk t
      using dual
      on (t.seq_bakasha = p_seq_bakasha and t.code_nimuk = 81)
      when matched then
        update set t.achuz_meushar = v_secuerity_hagdala_percent
      when not matched then
        insert
          (t.seq_hagdala_nimuk,
           t.seq_bakasha,
           t.code_nimuk,
           t.achuz_meushar,
           t.code_hagdala_status_nimuk)
        values
          (hagdala_nimuk_seq.nextval,
           p_seq_bakasha,
           81,
           v_secuerity_hagdala_percent,
           3);
    end if;
  end;
  ---------------------------------------------------------------------------
  procedure calc_pizuy_odef_shanim(p_seq_bakasha number,
                                   
                                   p_gimlat_kefel          number,
                                   p_maskoret_kovaat_tikra number,
                                   p_code_department       number,
                                   p_as_of_date            date) is
    v_is_zakay_maanak_pizuy        number;
    v_code_seif_prisha             number;
    v_age                          number;
    v_is_ganenet                   number;
    v_ahuz_kizb_achry_hgdl_kaf_chl number := 0;
    v_chelkiyut_meshuklelet_sherut number := 0;
    v_achuz_kizba_chelkuyt_mela    number := 0;
    v_achuz_kizba_chelk_mel_hgd    number := 0;
    v_is_security                  number;
    v_seq_ezor_ovdim               number;
    v_odef                         number := 0;
    v_odef_chodashim               number := 0;
    v_odef_yamim                   number := 0;
    v_achuz_kizba_kafuf_chelkiyut  number := 0;
    v_periods                      number := 0;
    v_periods_2                    number := 0;
    v_achuz_kizba_kafuf_chelkiyt_2 number := 0;
    v_achz_kizb_ahry_hgdl_kf_chl_2 number := 0;
    v_chelkiyt_meshukllet_sherut_2 number := 0;
    v_achuz_kizba_chelkuyt_mela_2  number := 0;
    v_peroid_medina_service        number := 0;
    v_peroid_medina_out_of_service number := 0;
  
    v_achuz_kizba_sofi number := 0;
    v_chelkiyut_sofit  number := 0;
    v_achuz_max        number := 70;
    --v_total_months_f     number;
    v_tkufa_lo_mezaka_f  number;
    v_chelkiyut_sofit_f  number;
    v_achuz_kizba_sofi_f number;
    v_for_odef_yamim     number;
    v_achuz_hagdala_21   number := 0;
  
    --gimlaot kefel
    v_guf_peroids                 number := 0;
    v_achuz_kizba_fixed           number := 0;
    v_overlap_months              number := 0;
    v_maskoret_kovaat_medina      number;
    v_seq_netuney_tik_mechushavim number;
  begin
  
    select v.code_seif_prisha,
           v.seq_ezor_ovdim,
           months_between(v.taarich_prisha, p.taarich_leda) / 12,
           case br.chinuch_mikzoa
             when 911 then
              1
             else
              0
           end,
           br.maskoret_kovaat
      into v_code_seif_prisha,
           v_seq_ezor_ovdim,
           v_age,
           v_is_ganenet,
           v_maskoret_kovaat_medina
      from v_bakasha_last_status v
      left join poresh p
        on v.seq_porshim = p.porshim_seq
      left join bakasha_regila br
        on v.seq_bakasha = br.seq_bakasha
     where v.SEQ_BAKASHA = p_seq_bakasha;
  
    v_is_security := is_security(v_seq_ezor_ovdim);
    --לולאה למספר משרה
  
    v_seq_netuney_tik_mechushavim := Get_seq_netuny_tik_mechushavim(p_seq_bakasha,
                                                                    p_code_department,
                                                                    0);
    if v_is_security = 1 then
    
      calc_ntuny_tik_mchshvim_medina(p_seq_bakasha,
                                     v_periods,
                                     v_chelkiyut_meshuklelet_sherut,
                                     v_achuz_kizba_kafuf_chelkiyut,
                                     v_tkufa_lo_mezaka_f,
                                     v_achuz_kizba_chelkuyt_mela,
                                     v_ahuz_kizb_achry_hgdl_kaf_chl,
                                     v_chelkiyut_sofit_f,
                                     v_achuz_kizba_sofi_f,
                                     1,
                                     null,
                                     p_as_of_date,
                                     v_peroid_medina_service,
                                     v_peroid_medina_out_of_service);
      v_achuz_kizba_chelkuyt_mela := nvl(v_achuz_kizba_kafuf_chelkiyut, 0) *
                                     nvl(v_chelkiyut_meshuklelet_sherut, 0);
    
      v_achuz_kizba_chelk_mel_hgd := nvl(v_ahuz_kizb_achry_hgdl_kaf_chl, 0) *
                                     nvl(v_chelkiyut_meshuklelet_sherut, 0);
    
      -- Get calculations for must periods ('sherut chova') only.
      calc_ntuny_tik_mchshvim_medina(p_seq_bakasha,
                                     v_periods_2,
                                     v_chelkiyt_meshukllet_sherut_2,
                                     v_achuz_kizba_kafuf_chelkiyt_2,
                                     v_tkufa_lo_mezaka_f,
                                     v_achuz_kizba_chelkuyt_mela_2,
                                     v_achz_kizb_ahry_hgdl_kf_chl_2,
                                     v_chelkiyut_sofit_f,
                                     v_achuz_kizba_sofi_f,
                                     2,
                                     null,
                                     p_as_of_date,
                                     v_peroid_medina_service,
                                     v_peroid_medina_out_of_service);
      v_achuz_kizba_chelkuyt_mela_2 := nvl(v_achuz_kizba_chelkuyt_mela_2, 0) *
                                       nvl(v_chelkiyt_meshukllet_sherut_2,
                                           0);
      --Get achuz hagdala 21 . 
      select nvl(sum(t.achuz_meushar), 0)
        into v_achuz_hagdala_21
        from hagdala_nimuk t
        left join bakasha_regila b
          on t.seq_bakasha = b.seq_bakasha
       where t.seq_bakasha = p_seq_bakasha
         and t.code_nimuk = 21
         and t.code_hagdala_status_nimuk = 3
         and b.taarich_prisha <= to_date('19/07/2017', 'dd/mm/yyyy');
    
      v_achuz_kizba_chelkuyt_mela_2 := v_achuz_kizba_chelkuyt_mela_2 +
                                       v_achuz_hagdala_21;
    else
      Get_total_Fields_mechushavim(p_seq_bakasha,
                                   v_periods,
                                   v_chelkiyut_meshuklelet_sherut,
                                   v_achuz_kizba_kafuf_chelkiyut,
                                   v_tkufa_lo_mezaka_f,
                                   v_achuz_kizba_chelkuyt_mela,
                                   v_ahuz_kizb_achry_hgdl_kaf_chl,
                                   v_chelkiyut_sofit_f,
                                   v_achuz_kizba_sofi_f,
                                   0,
                                   0,
                                   p_code_department);
      v_achuz_kizba_chelk_mel_hgd := v_ahuz_kizb_achry_hgdl_kaf_chl *
                                     v_chelkiyut_meshuklelet_sherut;
    
    end if;
  
    v_periods                     := round(v_periods, 0);
    v_periods_2                   := round(v_periods_2);
    v_achuz_kizba_chelkuyt_mela   := round(v_achuz_kizba_chelkuyt_mela, 2);
    v_achuz_kizba_chelkuyt_mela_2 := round(v_achuz_kizba_chelkuyt_mela_2, 2);
    v_achuz_kizba_chelk_mel_hgd   := round(v_achuz_kizba_chelk_mel_hgd, 2);
  
    if /* Temporary removed for checking magal v_code_seif_prisha in (217, 118) and*/
     v_achuz_kizba_chelk_mel_hgd >= 70 + v_achuz_kizba_chelkuyt_mela_2 then
      v_is_zakay_maanak_pizuy := 1;
    
      v_achuz_kizba_sofi := 70 + v_achuz_kizba_chelkuyt_mela_2;
      v_chelkiyut_sofit  := 1;
    
      update netuney_tik_mechushavim n
         set n.chelkiyut_sofit      = v_chelkiyut_sofit,
             n.achuz_kizba_sofi     = v_achuz_kizba_sofi,
             n.achuz_kizba_maximali = 70 +
                                      nvl(v_achuz_kizba_kafuf_chelkiyt_2, 0)
       where n.seq_netuney_tik_mechushavim = v_seq_netuney_tik_mechushavim;
    
      /*commit;*/
    end if;
  
    if v_is_zakay_maanak_pizuy = 1 and
       get_sheer_group(p_seq_bakasha) not in (2, 3) and
       (((v_seq_ezor_ovdim not in (163, 164, 225) and
       (v_age >= 60 or (v_age >= 59 and v_is_ganenet = 1))) or
       (v_seq_ezor_ovdim in (163, 164, 225) and v_age >= 57))) then
    
      calc_ntuny_tik_mchshvim_medina(p_seq_bakasha,
                                     v_periods,
                                     v_chelkiyut_meshuklelet_sherut,
                                     v_achuz_kizba_kafuf_chelkiyut,
                                     v_tkufa_lo_mezaka_f,
                                     v_achuz_kizba_chelkuyt_mela,
                                     v_ahuz_kizb_achry_hgdl_kaf_chl,
                                     v_chelkiyut_sofit_f,
                                     v_achuz_kizba_sofi_f,
                                     3,
                                     null,
                                     p_as_of_date,
                                     v_peroid_medina_service,
                                     v_peroid_medina_out_of_service);
      v_periods                   := round(v_periods, 0);
      v_achuz_kizba_chelkuyt_mela := round(v_achuz_kizba_chelkuyt_mela, 2);
      --calc maskoret_kovaat for gimlaot kefel
      if ((nvl(v_periods, 0) * nvl(v_chelkiyut_meshuklelet_sherut, 0)) -
         (420)) > 0 then
      
        v_odef := nvl(v_periods, 0) *
                  nvl(v_chelkiyut_meshuklelet_sherut, 0) - (420);
      
        v_odef_chodashim := floor(v_odef);
      
        v_for_odef_yamim := mod(v_odef, 1) * 30.44;
      
        v_odef_yamim := round(v_for_odef_yamim);
      end if;
    
    end if;
  
    --update chelkiyut_sofit
    update netuney_tik_mechushavim n
       set n.odef_sherut_chodashim = v_odef_chodashim,
           n.odef_sherut_yamim     = v_odef_yamim,
           n.chodshey_pizuy        = v_odef
     where n.seq_netuney_tik_mechushavim = v_seq_netuney_tik_mechushavim;
  
  end;
  --------------------------------------------
  function get_guf_peroids(p_seq_bakasha           number,
                           p_maskoret_kovaat_tikra number) return number is
    v_peroids number := 0;
  begin
    select sum(nvl(t.chodshey_maanak, 0) * t.partial_period * t.sum /
               p_maskoret_kovaat_tikra)
      into v_peroids
      from participation t
     where t.seq_bakasha = p_seq_bakasha
       and t.code_participation = 6;
  
    return v_peroids;
  end;

  --------------------------------------------
  function calc_is_zakay_kizba(p_seq_bakasha                 number,
                               p_seq_netuney_tik_mechushavim number,
                               p_code_seif_prisha            out number,
                               p_date_end_zakaut             out date,
                               p_code_department             number,
                               p_as_of_date                  date default null)
    return date is
    v_is_ganenet                   number;
    v_is_zakay_kizba               number;
    v_code_seif_prisha             number;
    v_age                          number;
    v_years_service                number;
    v_is_died                      number(1);
    v_code_job                     number;
    v_is_medical_vaada             number;
    v_mdicl_vaada_percent_minimum  number;
    v_chelkiyut_meshuklelet_sherut number;
    v_achuz_kizba_kafuf_chelkiyut  number;
    v_peroid                       number;
    v_taarich_prisha               date;
    v_taarich_leda                 date;
    v_date_vaada_ref               date;
    v_date_zakaut                  date;
    v_code_e_zakaut                number; --e
    v_age_minimum                  number; --e
    v_age_maximum                  number;
    v_years_service_minimum        number; --e
    v_group_prisha                 number; --e
    v_seq_ezor_ovdim               number; --e
    v_is_security                  number; --e
    v_medical_vaada_percnt_minimum number;
    v_perm_is_died                 number;
    v_ezor_ovdim                   number;
    v_date_end_work                date;
    v_kviut_peroids                number;
    v_from_date_zakaut             date;
    v_end_date_zakaut              date;
    v_date_sign_form               date;
    v_achuz_kizba_sofi             number;
    v_taarich_ptira                date;
    v_code_sug_bakasha             number;
    v_sug_bakasha_details          number;
    v_din_mishmaati                number;
    v_seif_57                      number;
  begin
  
    select v.code_seif_prisha,
           months_between(v.taarich_prisha + 1, p.taarich_leda) / 12,
           decode(p.taarich_ptira, null, 0, 0, 0, 1),
           
           decode(b.NECHUT_TAARICH_HAMIGBALA, null, 0, 1),
           nvl(b.nechut_achuz, 0),
           v.taarich_prisha,
           b.nechut_taarich_hamigbala,
           p.taarich_leda,
           v.seq_ezor_ovdim,
           case v.seq_ezor_ovdim
             when 206 then
              case nvl(b.chinuch_mikzoa, 0)
                when 911 then
                 2
                when 912 then
                 8
                when 0 then
                 3
                else
                 null
              end
             else
              null
           end,
           v.seq_ezor_ovdim,
           b.date_end_work,
           b.from_date_zakaut,
           b.taarich_chatimat_tofes,
           n.achuz_kizba_sofi,
           p.taarich_ptira,
           v.code_sug_bakasha,
           b.to_date_zakaut,
           v.code_bakasha_detail,
           b.is_din_mishmaati,
           n.code_e_zakaut
      into v_code_seif_prisha,
           v_age,
           v_is_died,
           v_is_medical_vaada,
           v_mdicl_vaada_percent_minimum,
           v_taarich_prisha,
           v_date_vaada_ref,
           v_taarich_leda,
           v_seq_ezor_ovdim,
           v_code_job,
           v_seq_ezor_ovdim,
           v_date_end_work,
           v_from_date_zakaut,
           v_date_sign_form,
           v_achuz_kizba_sofi,
           v_taarich_ptira,
           v_code_sug_bakasha,
           v_end_date_zakaut,
           v_sug_bakasha_details,
           v_din_mishmaati,
           v_code_e_zakaut
      from v_bakasha_last_status v
      left join poresh p
        on v.seq_porshim = p.porshim_seq
      left join bakasha_regila b
        on v.seq_bakasha = b.seq_bakasha
      left join netuney_tik_mechushavim n
        on n.seq_bakasha = p_seq_bakasha
       and n.code_department = p_code_department
       and n.mispar_misra = 0
     where v.seq_bakasha = p_seq_bakasha;
  
    v_is_security := is_security(v_seq_ezor_ovdim);
    if v_is_security = 1 then
      v_code_job := 4;
    end if;
  
    if v_seq_ezor_ovdim in (163, 164, 225) then
      v_code_job := 5;
    end if;
  
    if v_code_seif_prisha = 315 and v_mdicl_vaada_percent_minimum = 0 then
      return null;
    end if;
  
    select t.code_group_prisha
      into v_group_prisha
      from code_seif_prisha t
     where t.code_seif_prisha = v_code_seif_prisha;
  
    --Get peroids
  
    calc_data_tkufa_mezaka(p_seq_bakasha,
                           6,
                           v_chelkiyut_meshuklelet_sherut,
                           v_achuz_kizba_kafuf_chelkiyut,
                           v_peroid);
  
    v_years_service := v_peroid / 12;
  
    begin
      select case count(*)
               when 0 then
                0
               else
                1
             end
        into v_is_zakay_kizba
        from perm_decision_zakaut p
       where p.code_seif_prisha = v_code_seif_prisha
         and p.age_minimum <= v_age
         and (v_age < p.age_maximum or p.age_maximum is null)
         and p.years_service_minimum <= v_years_service
         and (p.is_died = v_is_died or
             get_sheer_group(p_seq_bakasha) not in (1, 2))
         and (nvl(p.code_job, 0) = nvl(v_code_job, 0))
            
         and (p.is_medical_vaada = v_is_medical_vaada) fetch first 1 rows only
      -- nvl(v_mdicl_vaada_percent_minimum, 0))
      --and nvl(p.is_security, 0) = nvl(v_is_security, 0)
      ;
      --e
    
      select p.age_minimum,
             p.years_service_minimum,
             p.medical_vaada_percent_minimum,
             p.is_died,
             p.age_maximum
        into v_age_minimum,
             v_years_service_minimum,
             v_medical_vaada_percnt_minimum,
             v_perm_is_died,
             v_age_maximum
        from perm_decision_zakaut p
        left join code_seif_prisha sp
          on sp.code_seif_prisha = p.code_seif_prisha
       where p.code_seif_prisha = v_code_seif_prisha
         and (nvl(p.code_job, 0) = nvl(v_code_job, 0))
            --06/07/2019 for seif 217
         and (p.is_medical_vaada = v_is_medical_vaada) fetch first 1 rows only
      -- and p.is_medical_vaada = v_is_medical_vaada
      --and nvl(p.is_security, 0) = nvl(v_is_security, 0)
      ; --e
    
    exception
      when no_data_found then
        v_is_zakay_kizba := 0;
      when others then
        dbms_output.put_line(to_char(p_seq_bakasha) || ', ' ||
                             to_char(v_code_seif_prisha));
    end;
  
    if v_code_e_zakaut = 11 then
      v_code_e_zakaut := null;
      update netuney_tik_mechushavim n
         set n.code_e_zakaut = v_code_e_zakaut
       where n.seq_bakasha = p_seq_bakasha
         and n.code_department = p_code_department;
    end if;
  
    --סעיף 417 שנות שרות 25 שמתוכם לפחות 15 במשטרה 
    if v_code_seif_prisha = 417 and v_code_job = 5 and
       v_years_service >= 25 and v_age < v_age_maximum and
       v_age >= v_age_minimum then
      calc_data_tkufa_mezaka(p_seq_bakasha,
                             5,
                             v_chelkiyut_meshuklelet_sherut,
                             v_achuz_kizba_kafuf_chelkiyut,
                             v_peroid);
      if v_peroid / 12 >= 15 then
        v_is_zakay_kizba := 1;
      else
        v_is_zakay_kizba := 0;
      end if;
    end if;
  
    if v_is_zakay_kizba = 1 or
       sheerim_is_by_prev_bakasha(v_code_sug_bakasha, v_sug_bakasha_details) = 1 then
    
      if v_group_prisha = 3 or v_group_prisha = 4 then
        update netuney_tik_mechushavim n
           set n.code_group_prisha = v_group_prisha
         where n.seq_bakasha = p_seq_bakasha
           and n.code_department = p_code_department;
      
      end if;
      if v_group_prisha = 3 then
        calc_data_tkufa_mezaka(p_seq_bakasha,
                               4,
                               v_chelkiyut_meshuklelet_sherut,
                               v_achuz_kizba_kafuf_chelkiyut,
                               v_kviut_peroids);
      end if;
    
      p_code_seif_prisha := v_code_seif_prisha;
      --when sheerim, add 3 months
      if v_end_date_zakaut is not null and
         (p_as_of_date < v_end_date_zakaut or p_as_of_date is null) then
        p_date_end_zakaut := v_end_date_zakaut;
      end if;
    
      if p_as_of_date is not null then
        v_date_zakaut := last_day(p_as_of_date) + 1;
      elsif v_from_date_zakaut is not null then
        v_date_zakaut := v_from_date_zakaut;
      elsif v_group_prisha = 4 and get_sheer_group(p_seq_bakasha) = 1 then
        if nvl(v_achuz_kizba_sofi, 0) <> 0 then
          v_date_zakaut := trunc(add_months(v_taarich_prisha, 1 + 3),
                                 'MONTH');
        end if;
      elsif v_group_prisha = 3 then
        --hakpaa     
      
        if v_date_vaada_ref is null then
          --get age 67 ,ganenet 59
          if
          --ganenet
           v_code_job = 2 and v_kviut_peroids / 12 >= 20 then
            --08/09/2024 change ganenet hakpaa from 59 to 60
           -- v_date_zakaut := last_day(add_months(v_taarich_leda, 720)) + 1;
           --16/08/2026 change ganenet hakpaa from 60 to 59 //Chavi
           v_date_zakaut := last_day(add_months(v_taarich_leda, 708)) + 1;

            --p_code_seif_prisha := 317;
            --teacher or stopped working
          elsif v_seq_ezor_ovdim = 206 and nvl(v_code_job, 0) in (3, 8) and
                v_kviut_peroids / 12 >= 20 then
            v_date_zakaut := last_day(add_months(v_taarich_leda, 720)) + 1;
            --p_code_seif_prisha := 317;
          elsif v_date_end_work is not null then
            v_date_zakaut      := greatest(last_day(v_date_end_work) + 1,
                                           last_day(add_months(v_taarich_leda,
                                                               720)) + 1);
            p_code_seif_prisha := 171;
          
          else
            --67 age
            v_date_zakaut      := last_day(add_months(v_taarich_leda, 804)) + 1;
            p_code_seif_prisha := 171;
          end if;
        else
          --is vaada refuit
          v_date_zakaut := v_date_vaada_ref;
        
        end if;
        if v_years_service >= 25 and (v_age >= 57 and v_age < 60) and
           nvl(v_code_job, 0) <> 2 then
          v_date_zakaut      := last_day(add_months(v_taarich_leda, 12 * 60)) + 1;
          p_code_seif_prisha := 117;
        end if;
      
      elsif v_group_prisha = 4 and get_sheer_group(p_seq_bakasha) = 2 and
            nvl(v_achuz_kizba_sofi, 0) <> 0 and nvl(v_code_e_zakaut, 0) = 0 then
        v_date_zakaut := trunc(add_months(v_taarich_ptira, 1), 'MONTH');
      elsif v_group_prisha = 4 and get_sheer_group(p_seq_bakasha) = 3 and
            nvl(v_achuz_kizba_sofi, 0) <> 0 then
        v_date_zakaut := v_taarich_prisha + 1;
      
      else
        v_date_zakaut := v_taarich_prisha + 1;
      end if;
    
      --seif 57
      if v_din_mishmaati = 1 and (v_peroid > 300 and months_between(v_taarich_prisha+1,v_taarich_leda) >= 57*12 or months_between(v_date_zakaut+1,v_taarich_leda)>=60) then
        v_seif_57 := 1;
      end if;
      update netuney_tik_mechushavim n
         set n.is_seif_57 = v_seif_57
       where n.seq_bakasha = p_seq_bakasha
         and n.code_department = p_code_department;
    
    else
      if v_age < v_age_minimum then
        v_code_e_zakaut := 1;
      elsif v_age >= v_age_maximum then
        v_code_e_zakaut := 6;
      elsif v_years_service < v_years_service_minimum then
        v_code_e_zakaut := 3;
      elsif v_mdicl_vaada_percent_minimum < v_medical_vaada_percnt_minimum then
        v_code_e_zakaut := 4;
      elsif v_is_died = 1 and v_perm_is_died = 0 then
        v_code_e_zakaut := 5;
      else
        v_code_e_zakaut := 99;
      end if; --e
      update netuney_tik_mechushavim n
         set n.code_e_zakaut     = v_code_e_zakaut,
             n.is_zakay_kizba    = v_is_zakay_kizba,
             n.achuz_kizba_sofi  = 0,
             n.is_zakai_lmaanak  = 0,
             n.date_start_zakaut = v_date_zakaut,
             n.date_end_zakaut   = v_end_date_zakaut,
             n.is_seif_57        = null
       where n.seq_bakasha = p_seq_bakasha
         and n.code_department = p_code_department;
    
    end if;
    return v_date_zakaut;
  end;

  --------------------------------------------
  procedure calc_is_zakay_maanak(p_seq_bakasha                 number,
                                 p_seq_netuney_tik_mechushavim number,
                                 p_is_gimlat_kefel             number,
                                 p_overlap_percent             number) is
    v_is_zakay_maanak              number := 0;
    v_seq_ezor_ovdim               number;
    v_is_din_mishmat               number;
    v_age                          number;
    v_code_seif_prisha             number;
    v_ahuz_kizb_achry_hgdl_kaf_chl number;
    v_chelkiyut_meshuklelet_sherut number;
    v_max_vetek                    number;
    v_vetek_poresh                 number;
    v_code_job                     number;
    v_code_group_prisha            number;
    v_age_max_nechut               number;
    v_achuz_kizba_nechut           number;
    v_chelkiut_lefi_nechut         number;
    v_achuz_kizba_sofi             number;
    v_chelkiut_sofit               number;
    v_achuz_kizba_chelkiyut_melea  number;
    v_achuz_kizba_kafuf_chelkiyut  number;
    v_achuz_hagdala                number;
    v_achuz_kizba_gil_60           number;
    v_maskoret_kovvat              number;
    v_maskoret_kovvat_60           number;
    v_overlap_percent              number;
    v_mispar_misra                 number;
    v_sug_bakasha                  number;
    v_taarich_prisha               date;
    v_seq_bakasha_sachar           number;
    v_seq_prisha                   number;
    v_is_chinuch_reforma           number;
  begin
    select v.seq_ezor_ovdim,
           b.is_din_mishmaati,
           months_between(v.taarich_prisha + 1, p.taarich_leda) / 12,
           b.vetek,
           cd.max_vetek,
           v.code_seif_prisha,
           case b.chinuch_mikzoa
             when 911 then
              2
             else
              null
           end,
           s.code_group_prisha,
           v.code_sug_bakasha,
           v.taarich_prisha,
           v.seq_prisha
      into v_seq_ezor_ovdim,
           v_is_din_mishmat,
           v_age,
           v_vetek_poresh,
           v_max_vetek,
           v_code_seif_prisha,
           v_code_job,
           v_code_group_prisha,
           v_sug_bakasha,
           v_taarich_prisha,
           v_seq_prisha
      from v_bakasha_last_status v
      left join bakasha_regila b
        on v.seq_bakasha = b.seq_bakasha
      left join code_seif_prisha s
        on b.code_seif_prisha = s.code_seif_prisha
      left join poresh p
        on v.seq_porshim = p.porshim_seq
    --Get code_derug from the last period
      left join (select k.seq_bakasha,
                        max(k.code_derug) keep(dense_rank first order by k.taarich_me desc) code_derug
                   from darga_vederug_tik k
                  group by seq_bakasha) d
        on v.SEQ_BAKASHA = d.seq_bakasha
    
      left join code_derug cd
        on d.code_derug = cd.code_derug
     where v.seq_bakasha = p_seq_bakasha;
  
    select n.chelkiyut_meshuklelet_sherut,
           n.achuz_kizba_nechut,
           n.chelkiut_lefi_nechut,
           n.achuz_kizba_chelkiyut_melea,
           n.achuz_kizba_sofi,
           n.chelkiyut_sofit,
           n.achuz_kizba_kafuf_chelkiyut,
           n.mispar_misra
      into v_chelkiyut_meshuklelet_sherut,
           v_achuz_kizba_nechut,
           v_chelkiut_lefi_nechut,
           v_achuz_kizba_chelkiyut_melea,
           v_achuz_kizba_sofi,
           v_chelkiut_sofit,
           v_achuz_kizba_kafuf_chelkiyut,
           v_mispar_misra
      from netuney_tik_mechushavim n
     where n.seq_netuney_tik_mechushavim = p_seq_netuney_tik_mechushavim;
  
    calc_hagdalot(p_seq_bakasha, v_achuz_hagdala, 1);
  
    --if seif prisha (415, 315, 215), check if kizba lefi sherut until 60 years greater then kizba lefi nechut
    if v_code_seif_prisha in (415, 315, 215) and
       nvl(v_is_din_mishmat, 0) not in (1, 3) and
       (nvl(v_code_job, 0) <> 2 and v_age <= 59.75 or
       nvl(v_code_job, 0) = 2 and v_age <= 58.75) and
       is_security(v_seq_ezor_ovdim) = 0 then
      if nvl(v_code_job, 0) <> 2 then
        v_age_max_nechut := 60;
      else
        v_age_max_nechut := 59;
      end if;
      if v_code_seif_prisha in (415, 315) then
        v_achuz_kizba_gil_60 := round(least(round_percent_by_months(round(v_achuz_kizba_kafuf_chelkiyut +
                                                                          v_achuz_hagdala +
                                                                          greatest(v_age_max_nechut -
                                                                                   v_age,
                                                                                   0) * 2,
                                                                          2)),
                                            70 /
                                            
                                            v_chelkiut_sofit),
                                      2);
        v_overlap_percent    := nvl(p_overlap_percent, 0) /
                                v_chelkiut_sofit;
      else
        v_achuz_kizba_gil_60 := round(least(round_percent_by_months(round(v_achuz_kizba_kafuf_chelkiyut +
                                                                          v_achuz_hagdala +
                                                                          greatest(v_age_max_nechut -
                                                                                   v_age,
                                                                                   0) * 2,
                                                                          2)),
                                            70 /
                                            
                                            v_chelkiyut_meshuklelet_sherut),
                                      2);
        v_overlap_percent    := nvl(p_overlap_percent, 0) /
                                v_chelkiyut_meshuklelet_sherut;
      end if;
    
      if p_is_gimlat_kefel = 1 then
        v_achuz_kizba_gil_60 := v_achuz_kizba_gil_60 -
                                nvl(v_overlap_percent, 0);
      end if;
    
      --maskoret gil 60
      begin
        if v_sug_bakasha = 1 then
          v_seq_bakasha_sachar := p_seq_bakasha;
        else
          select max(vb.seq_bakasha)
            into v_seq_bakasha_sachar
            from v_bakasha_last_status vb
           where vb.seq_prisha = v_seq_prisha
             and vb.code_sug_bakasha in (14, 1)
             and vb.code_action <> 17;
        end if;
        if v_seq_ezor_ovdim = 206 and
           v_taarich_prisha >= to_date('01/01/2021', 'dd/mm/yyyy') then
          v_is_chinuch_reforma := 1;
          select t.maskoret_kovaat_meshuklelet,
                 t.maskoret_kovaat_meshuklelet_60
            into v_maskoret_kovvat, v_maskoret_kovvat_60
            from chinuch_salary t
           where t.seq_bakasha = v_seq_bakasha_sachar;
        else
          select t.maskoret_kovaat
            into v_maskoret_kovvat
            from netuney_sachar t
           where t.seq_bakasha = v_seq_bakasha_sachar
             and t.code_sug_maskoret = 1
             and t.mispar_misra = v_mispar_misra;
          select t.maskoret_kovaat
            into v_maskoret_kovvat_60
            from netuney_sachar t
           where t.seq_bakasha = v_seq_bakasha_sachar
             and t.code_sug_maskoret = 2
             and t.mispar_misra = v_mispar_misra;
        end if;
      exception
        when no_data_found then
          v_maskoret_kovvat    := 0;
          v_maskoret_kovvat_60 := 0;
      end;
      if v_code_seif_prisha in (415, 315) and
        
         (v_achuz_kizba_sofi * v_chelkiut_sofit <
         v_achuz_kizba_gil_60 * v_chelkiut_sofit
         
         or v_achuz_kizba_sofi * v_chelkiut_sofit =
         v_achuz_kizba_gil_60 * v_chelkiut_sofit and
         --when chinuch reforma' check maskoret, else check vetek
          ((v_is_chinuch_reforma = 1 and
          v_maskoret_kovvat < v_maskoret_kovvat_60 and
          v_maskoret_kovvat_60 <> 0) or
          nvl(v_vetek_poresh, 0) < nvl(v_max_vetek, 0))) then
      
        v_is_zakay_maanak := 1;
      elsif v_code_seif_prisha = 215 and
            (v_achuz_kizba_sofi * v_chelkiut_sofit <
            v_achuz_kizba_gil_60 * v_chelkiyut_meshuklelet_sherut) then
      
        v_is_zakay_maanak := 1;
      end if;
    
    end if;
  
    if is_security(v_seq_ezor_ovdim) = 1 and nvl(v_is_din_mishmat, 0) = 0 and
       v_code_group_prisha <> 3 and
       get_sheer_group(p_seq_bakasha) not in (2, 3) then
      --When security
      v_is_zakay_maanak := 1;
    
    end if;
  
    update netuney_tik_mechushavim n
       set n.is_zakai_lmaanak   = v_is_zakay_maanak,
           n.achuz_kizba_gil_60 = v_achuz_kizba_gil_60
     where n.seq_netuney_tik_mechushavim = p_seq_netuney_tik_mechushavim;
 /* if v_is_zakay_maanak = 0 and p_is_gimlat_kefel = 1 then
       update netuney_tik_mechushavim n
       set n.odef_sherut_chodashim   = null,
           n.odef_sherut_yamim = null
           where n.seq_netuney_tik_mechushavim = p_seq_netuney_tik_mechushavim;
     end if;*/
  
  end;

  --------------------------------------------
  function calc_achuz_kizba_lefy_nechut(p_seq_bakasha                 number,
                                        p_seq_netuney_tik_mechushavim number,
                                        p_code_department             number)
    return number is
    v_achuz_kizba_sofi_lefy_nechut number := 0;
    v_achuz_kizba_sofi_sherut      number := 0;
    v_code_seif_prisha             number;
    v_achuz_nechut                 number;
    v_chekkyut_meshuklelet_sherut  number;
    v_chekkyut_lefi_nechut         number;
    v_date_end_zakaut              date;
    v_date_medical_vaada           date;
    v_is_zakay_nechut              number;
    v_age                          number;
    v_years_service                number;
    v_is_died                      number(1);
    v_code_job                     number;
    v_is_medical_vaada             number;
    v_mdicl_vaada_percent_minimum  number;
    v_chelkiyut_meshuklelet_sherut number;
    v_achuz_kizba_kafuf_chelkiyut  number;
    v_peroid                       number;
    v_achz_kzba_kff_chlkyt_ach_hgd number;
    v_achuz_kizba_hagdala          number;
    v_type_query                   number := 0;
  
    ----for participation from guf
    v_code_sug_bakasha          number;
    v_temp_schum_kizba_guf      number;
    v_maskoret_kovvat_guf       number;
    v_maskoret_kovvat_medina    number := 0;
    v_achuz_kizba_guf           number := 0;
    v_achuz_kizba_guf_yachasi   number := 0;
    v_seq_guf                   number;
    v_chodshey_maanak           number;
    v_schum_maanak_baguf        number;
    v_participation_seq_bakasha number;
    v_seq_prisha                number;
    v_overlapping_months        number;
    v_is_overlap_from_guf       number;
  begin
    select v.code_seif_prisha,
           nvl(b.nechut_achuz, 0) - nvl(b.nechut_achuz_nechut_bknisa, 0),
           --b.nechut_taarich_end_hamigbala,
           b.nechut_taarich_hamigbala,
           decode(b.NECHUT_TAARICH_HAMIGBALA, null, 0, 1),
           months_between(v.taarich_prisha + 1, p.taarich_leda) / 12,
           decode(p.taarich_ptira, null, 0, 0, 0, 1),
           nvl(b.nechut_achuz, 0),
           v.code_sug_bakasha,
           b.maskoret_kovaat,
           v.seq_prisha
      into v_code_seif_prisha,
           v_achuz_nechut,
           --v_date_end_zakaut,
           v_date_medical_vaada,
           v_is_medical_vaada,
           v_age,
           v_is_died,
           v_mdicl_vaada_percent_minimum,
           v_code_sug_bakasha,
           v_maskoret_kovvat_medina,
           v_seq_prisha
      from v_bakasha_last_status v
      left join bakasha_regila b
        on v.seq_bakasha = b.seq_bakasha
      left join poresh p
        on v.seq_porshim = p.porshim_seq
      left join bakasha_regila b
        on v.seq_bakasha = b.seq_bakasha
     where v.seq_bakasha = p_seq_bakasha;
  
    if v_date_medical_vaada is null then
      return 0;
    end if;
    v_code_job := get_code_job(p_seq_bakasha);
  
    calc_data_tkufa_mezaka(p_seq_bakasha,
                           6,
                           v_chelkiyut_meshuklelet_sherut,
                           v_achuz_kizba_kafuf_chelkiyut,
                           v_peroid);
  
    v_years_service := v_peroid / 12;
  
    calc_chelkiyut_lefy_nechut(p_seq_bakasha,
                               p_seq_netuney_tik_mechushavim,
                               p_code_department);
  
    select t.chelkiut_lefi_nechut,
           t.chelkiyut_meshuklelet_sherut,
           t.achuz_kizba_kafuf_chelkiyut,
           ahuz_kizb_achry_hagdl_kaf_chel
    
      into v_chekkyut_lefi_nechut,
           v_chelkiyut_meshuklelet_sherut,
           v_achuz_kizba_kafuf_chelkiyut,
           v_achz_kzba_kff_chlkyt_ach_hgd
      from netuney_tik_mechushavim t
     where t.seq_netuney_tik_mechushavim = p_seq_netuney_tik_mechushavim;
  
    --participation mguf or exists confirmed participation mguf
    if v_code_sug_bakasha <> 7 then
      v_participation_seq_bakasha := exists_confirmed_bakasha(p_seq_bakasha,
                                                              7);
    else
      v_participation_seq_bakasha := p_seq_bakasha;
    end if;
    if v_code_sug_bakasha = 7 and v_code_seif_prisha = 215 or
       v_participation_seq_bakasha is not null and
       v_code_seif_prisha in (215, 315) then
      begin
        pk_participation_2_guff.Get_data_guf(v_participation_seq_bakasha,
                                             v_temp_schum_kizba_guf,
                                             v_maskoret_kovvat_guf,
                                             v_achuz_kizba_guf,
                                             v_seq_guf,
                                             v_chodshey_maanak,
                                             v_schum_maanak_baguf,
                                             0);
        if nvl(v_maskoret_kovvat_medina, 0) > 0 then
          v_achuz_kizba_guf_yachasi := round(v_achuz_kizba_guf *
                                             v_maskoret_kovvat_guf /
                                             v_maskoret_kovvat_medina,
                                             2);
          v_is_overlap_from_guf     := pk_participation_2_guff.is_overlap_from_guf(p_seq_bakasha);
          if v_is_overlap_from_guf = 1 then
            v_overlapping_months := 0;
          else
            v_overlapping_months := pk_participation_2_guff.Get_overlapping_months(p_seq_bakasha,
                                                                                   v_code_sug_bakasha, --7
                                                                                   1);
          
          end if;
        
        end if;
      exception
        when others then
          v_maskoret_kovvat_guf := 0;
          v_achuz_kizba_guf     := 0;
      end;
    end if;
  
    select case count(*)
             when 0 then
              0
             else
              1
           end
      into v_is_zakay_nechut
      from perm_decision_zakaut p
     where p.code_seif_prisha = v_code_seif_prisha
       and p.age_minimum <= v_age
       and (v_age < p.age_maximum or p.age_maximum is null)
       and p.years_service_minimum <= v_years_service
          --and p.is_died = v_is_died
       and (nvl(p.code_job, 0) = nvl(v_code_job, 0))
          
       and (p.is_medical_vaada = v_is_medical_vaada and
           nvl(p.medical_vaada_percent_minimum, 0) <=
           nvl(v_mdicl_vaada_percent_minimum, 0) or is_medical_vaada = 0);
  
    --if v_code_seif_prisha in (215, 315) then
    if v_is_zakay_nechut = 1 and
       (v_code_sug_bakasha <> 7 or v_code_seif_prisha = 215) then
    
      v_achuz_kizba_sofi_lefy_nechut := round((0.2 +
                                              (0.003 *
                                              nvl(v_achuz_nechut, 0))) * 100,
                                              2);
      v_chekkyut_lefi_nechut         := round(v_chekkyut_lefi_nechut, 3);
      if v_achuz_kizba_sofi_lefy_nechut * v_chekkyut_lefi_nechut >=
         (v_achz_kzba_kff_chlkyt_ach_hgd) * v_chelkiyut_meshuklelet_sherut +
         v_achuz_kizba_guf_yachasi - nvl(v_overlapping_months / 6, 0) then
        update netuney_tik_mechushavim n
           set n.achuz_kizba_sofi   = v_achuz_kizba_sofi_lefy_nechut,
               n.achuz_kizba_nechut = v_achuz_kizba_sofi_lefy_nechut,
               n.chelkiyut_sofit    = v_chekkyut_lefi_nechut,
               n.code_group_prisha  = 2
         where n.seq_netuney_tik_mechushavim =
               p_seq_netuney_tik_mechushavim;
      
        if v_code_seif_prisha in (215, 315) then
          update bakasha_regila b
             set b.code_seif_prisha = 215
           where b.seq_bakasha = p_seq_bakasha;
        
        end if;
      
        return 1;
      else
        --change code baksha details
        if v_code_seif_prisha = 215 and v_code_sug_bakasha = 7 then
          update bakasha b
             set code_bakasha_detail = 43
           where b.seq_bakasha = p_seq_bakasha;
        end if;
      
        if v_code_seif_prisha in (215, 315) then
          update bakasha_regila b
             set b.code_seif_prisha = 315
           where b.seq_bakasha = p_seq_bakasha;
          --calc by nechut but save achuz kizba nechut
          update netuney_tik_mechushavim n
             set n.achuz_kizba_nechut = v_achuz_kizba_sofi_lefy_nechut
           where n.seq_netuney_tik_mechushavim =
                 p_seq_netuney_tik_mechushavim;
        
        end if;
      end if;
    
    end if;
    return 0;
  end;
  -----------------------------------------------
  function get_code_job(p_seq_bakasha number) return number is
    v_code_job       number;
    v_chinuch_mikzoa number;
    v_seq_ezor_ovdim number;
    v_is_security    number;
  begin
    select b.chinuch_mikzoa, p.seq_ezor_ovdim
      into v_chinuch_mikzoa, v_seq_ezor_ovdim
      from bakasha_regila b
      left join bakasha b1
        on b.seq_bakasha = b1.seq_bakasha
      left join prisha p
        on b1.seq_prisha = p.seq_prisha
     where b.seq_bakasha = p_seq_bakasha;
  
    v_is_security := is_security(v_seq_ezor_ovdim);
  
    if nvl(v_chinuch_mikzoa, 0) = 911 and v_seq_ezor_ovdim = 206 then
      v_code_job := 2;
    elsif nvl(v_chinuch_mikzoa, 0) = 0 and v_seq_ezor_ovdim = 206 then
      v_code_job := 3;
    elsif v_seq_ezor_ovdim in (163, 164, 225) then
      v_code_job := 5;
    elsif v_is_security = 1 then
      v_code_job := 4;
    else
      v_code_job := null;
    end if;
    return v_code_job;
  end;
  --------------------------------------------
  procedure calc_chelkiyut_lefy_nechut(p_seq_bakasha                 number,
                                       p_seq_netuney_tik_mechushavim number,
                                       p_code_department             number) is
    v_chelkiyut_mechushavim number;
    v_chelkiyut_tkufot_5    number;
    v_chelkiyut_tkufot_10   number;
    v_chelkiyut_tkufot_max  number;
    v_last_chelkiyut        number;
    v_chelkiyut_zvura       number := 0;
    v_months_count          number := 0;
    v_5_years               number := 5 * 12;
    v_achuz_nechut          number;
    v_code_job              number;
    v_exists_months         number;
    v_code_group_prisha     number;
  begin
    --Get chelkiyut from all periods
    select n.chelkiyut_meshuklelet_sherut,
           b.nechut_achuz,
           s.code_group_prisha
      into v_chelkiyut_mechushavim, v_achuz_nechut, v_code_group_prisha
      from netuney_tik_mechushavim n
      left join bakasha_regila b
        on n.seq_bakasha = b.seq_bakasha
      left join code_seif_prisha s
        on b.code_seif_prisha = s.code_seif_prisha
     where n.seq_netuney_tik_mechushavim = p_seq_netuney_tik_mechushavim;
    begin
      --last chelkiyut
      select least(t.achuz_chelkyut, 1)
        into v_last_chelkiyut
        from tkufot_avoda_mechushv t
        left join code_sug_zchuyot_mechushavim t1
          on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
       where t.seq_bakasha = p_seq_bakasha
         and t.taarich_ad =
             (select max(t1.taarich_ad)
                from tkufot_avoda_mechushv t1
                left join code_sug_zchuyot_mechushavim t2
                  on t1.code_sugey_zchuyot = t2.code_sugey_zchuyot
               where t1.seq_bakasha = t.seq_bakasha
                 and t2.haim_nirkash = 1);
    
      --Calc chelkiyut from 5 last years
      for r in (select least(t.achuz_chelkyut, 1) chelkiyut,
                       months_between(t.taarich_ad + 1, t.taarich_me) months,
                       rownum
                  from tkufot_avoda_mechushv t
                  left join code_sug_zchuyot_mechushavim t1
                    on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
                 where t.seq_bakasha = p_seq_bakasha
                   and t1.haim_nirkash = 1
                 order by t.taarich_ad desc) loop
      
        v_chelkiyut_zvura := v_chelkiyut_zvura +
                             (r.chelkiyut *
                             least(r.months, v_5_years - v_months_count));
        v_months_count    := v_months_count + r.months;
      
        if v_months_count > v_5_years then
          exit;
        end if;
      end loop;
      v_chelkiyut_tkufot_5 := v_chelkiyut_zvura / v_5_years;
    
      v_months_count    := 0;
      v_chelkiyut_zvura := 0;
      if v_chelkiyut_tkufot_5 < v_last_chelkiyut and
         v_chelkiyut_mechushavim < v_last_chelkiyut then
        if v_achuz_nechut >= 25 or v_code_job = 5 or
           v_code_group_prisha = 4 then
          v_exists_months := 59;
        else
          v_exists_months := 119;
        end if;
      
        --check if there is 59 months whith chelkiyut greatest then last chelkiyut
        for r in (select least(t.achuz_chelkyut, 1) chelkiyut,
                         months_between(t.taarich_ad + 1, t.taarich_me) months
                    from tkufot_avoda_mechushv t
                    left join code_sug_zchuyot_mechushavim t1
                      on t.code_sugey_zchuyot = t1.code_sugey_zchuyot
                   where t.seq_bakasha = p_seq_bakasha
                     and t1.haim_nirkash = 1
                     and t.achuz_chelkyut >= v_last_chelkiyut
                   order by t.achuz_chelkyut desc) loop
        
          v_months_count := v_months_count + r.months;
        
          if v_months_count > v_exists_months then
            exit;
          end if;
        end loop;
        if v_months_count < v_exists_months then
          v_last_chelkiyut := 0;
        end if;
      else
        v_last_chelkiyut := 0;
      end if;
      v_chelkiyut_tkufot_max := greatest(v_chelkiyut_tkufot_5,
                                         v_last_chelkiyut,
                                         v_chelkiyut_mechushavim);
    exception
      when others then
        v_chelkiyut_tkufot_max := 0;
    end;
    --Update the max chelkiyut
    update netuney_tik_mechushavim n
       set n.chelkiut_lefi_nechut = round(v_chelkiyut_tkufot_max, 3)
     where n.seq_netuney_tik_mechushavim = p_seq_netuney_tik_mechushavim;
  
  end;
  -------------------------------------------------------------------------
  procedure calc_gimlaot_kefel(p_schum_kizba_guf              number,
                               p_maskoret_kovaat_tikra        number,
                               p_maskoret_kovaat_medina       number,
                               p_achuz_kizba_chelkiyut_melea  in out number,
                               p_achz_kzba_chel_mela_achry_hg in out number,
                               p_achuz_kizba_sofi             in out number,
                               p_achuz_kizba_fixed            in out number,
                               p_overlap_percent              number,
                               p_chelkiyut_sofit              number,
                               p_percent_sherut_zahal         number,
                               p_maskoret_kovaat_guf          number,
                               p_achuz_kizba_guf              number,
                               p_maskoret_maanak              number,
                               p_maskoret_maanak_tikra        number,
                               p_odef_chodashim               in out number,
                               p_odef_yamim                   in out number,
                               p_sum_hafchata                 in out number,
                               p_odef                         in out number,
                               p_overlap_percent_maanak       number) is
    v_odef     number := 0;
    v_is_up_70 number := 0;
  begin
    v_is_up_70 := is_up_70_gimlaot_kefel(p_achz_kzba_chel_mela_achry_hg,
                                         p_maskoret_kovaat_tikra,
                                         p_maskoret_kovaat_medina,
                                         p_schum_kizba_guf,
                                         p_achuz_kizba_fixed,
                                         p_overlap_percent,
                                         p_chelkiyut_sofit,
                                         p_percent_sherut_zahal,
                                         p_maskoret_maanak,
                                         p_maskoret_maanak_tikra);
    if v_is_up_70 = 1 then
      v_odef := ((nvl(p_achuz_kizba_chelkiyut_melea, 0) *
                
                nvl(p_maskoret_kovaat_medina, 1) /
                nvl(p_maskoret_kovaat_tikra, 1) +
                nvl(p_achuz_kizba_guf, 0) * nvl(p_maskoret_kovaat_guf, 1) /
                nvl(p_maskoret_kovaat_tikra, 1) -
                p_overlap_percent_maanak *
                
                nvl(p_maskoret_kovaat_medina, 1) /
                nvl(p_maskoret_kovaat_tikra, 1)) -
                (70 + nvl(p_percent_sherut_zahal, 0))) * 6;
      v_odef := v_odef * nvl(p_maskoret_kovaat_tikra, 1) /
                nvl(p_maskoret_kovaat_medina, 1);
    
      p_odef_chodashim := floor(v_odef);
    
      p_odef_yamim := mod(v_odef, 1) * 30.44;
    
      p_odef_yamim := round(p_odef_yamim);
      p_odef       := v_odef;
      --p_achuz_kizba_sofi := p_achuz_kizba_fixed;
    
      p_achuz_kizba_sofi := least(p_achuz_kizba_sofi, p_achuz_kizba_fixed);
      p_sum_hafchata     := p_maskoret_kovaat_medina *
                            p_achuz_kizba_chelkiyut_melea * 0.01 +
                            p_schum_kizba_guf -
                            (p_maskoret_kovaat_tikra *
                            (0.7 + nvl(p_percent_sherut_zahal, 0) * 0.01));
    
      p_achuz_kizba_sofi := greatest(p_achuz_kizba_sofi, 0);
    
    elsif nvl(p_overlap_percent, 0) <> 0 then
      p_achuz_kizba_sofi := p_achuz_kizba_fixed;
    end if;
  
  end;
  ----------------------------------------------------------------------
  function is_up_70_gimlaot_kefel(p_achz_kzba_chel_mela_achry_hg in out number,
                                  p_maskoret_kovaat_tikra        number,
                                  p_maskoret_kovaat_medina       number,
                                  p_schum_kizba_guf              number,
                                  p_achuz_kizba_fixed            in out number,
                                  p_overlap_percent              number,
                                  p_chelkiyut_sofit              number,
                                  p_percent_sherut_zahal         number,
                                  p_maskoret_maanak              number,
                                  p_maskoret_maanak_tikra        number)
    return number is
    v_overlap_months number;
  begin
    p_achuz_kizba_fixed := round(p_achz_kzba_chel_mela_achry_hg /
                                 p_chelkiyut_sofit -
                                 nvl(p_overlap_percent, 0) /
                                 p_chelkiyut_sofit,
                                 3);
  
    if (p_achuz_kizba_fixed) * p_maskoret_kovaat_medina / 100 +
       p_schum_kizba_guf >
       p_maskoret_kovaat_tikra * 0.7 + p_percent_sherut_zahal / 100 then
      return 1;
    else
      return 0;
    end if;
  
  end;

  -----------------------------------------------------------------------
  function round_percent_by_months(p_percent number) return number is
    v_md_percent number;
    v_percent    number;
  begin
    v_percent    := p_percent;
    v_md_percent := mod(v_percent, 2);
    if v_md_percent not in (0, 2) then
      --Round 
      select v_percent - v_md_percent + i.achuz_meugal
        into v_percent
        from igul_chodashim i
       where v_md_percent between i.from_achuz and i.to_achuz;
    end if;
  
    v_percent := round(v_percent, 2);
    return v_percent;
  end;
  -----------------------------------------------
  function get_sheer_group(p_seq_bakasha number) return number is
    v_sheer_group number;
  begin
    select case
             when b.code_seif_prisha in (126, 226, 326, 426, 526, 626, 826) then
              1 --sheer pail
             when b.code_seif_prisha in (128, 228, 328, 428, 528, 628, 828) then
              2 --sheer pensyoni
             when b.code_seif_prisha in (162, 262, 362, 462, 562) then
              3 --gimlat chesed
             else
              0
           end
      into v_sheer_group
      from bakasha_regila b
     where b.seq_bakasha = p_seq_bakasha;
    return v_sheer_group;
  end;
  ----------------------------------------------
  function exists_confirmed_bakasha(p_seq_bakasha      number,
                                    p_code_sug_bakasha number) return number is
    v_is_bakasha number;
  begin
    select max(t1.seq_bakasha)
      into v_is_bakasha
      from v_bakasha_last_status t
      join v_bakasha_last_status t1
        on t.seq_prisha = t1.seq_prisha
       and t1.seq_bakasha < t.seq_bakasha
       and t1.code_sug_bakasha = p_code_sug_bakasha
      join workflow w_conf
        on w_conf.code_sug_workflow = t1.code_sug_workflow
       and w_conf.code_action = 35
      left join workflow w_curr
        on w_curr.code_sug_workflow = t1.code_sug_workflow
       and w_curr.code_action = t1.code_action
     where t.seq_bakasha = p_seq_bakasha
       and (w_conf.order_wf < w_curr.order_wf or t1.code_action = 98);
    return v_is_bakasha;
  end;
  -----------------------------------------------------------
  function sheerim_seq_valid_sheer(v_code_kirva        number,
                                   v_code_seif_prisha  number,
                                   v_age               number,
                                   v_is_army_ishur     number,
                                   v_is_without_parent number,
                                   v_taluy             number,
                                   v_code_job          number,
                                   v_seif_relative     in out number)
    return number is
    v_is_valid             number;
    v_mod_code_seif_prisha number;
  begin
  
    select t.seq_perm_decision_zakaut_sheer
      into v_is_valid
      from PERM_DECISION_ZAKAUT_SHEER t
     where t.code_kirva = v_code_kirva
       and t.code_seif_prisha = v_code_seif_prisha
       and (t.age_max is null or v_age <= t.age_max)
       and (nvl(t.is_was_in_zahal, 0) = nvl(v_is_army_ishur, 0) or
           v_code_kirva <> 2)
       and (nvl(t.is_taluy, 0) = nvl(v_taluy, 0))
          
       and (nvl(t.is_without_parent, 0) = nvl(v_is_without_parent, 0) or
           v_code_kirva <> 2)
       and (nvl(t.code_job, 0) = nvl(v_code_job, 0));
    return v_is_valid;
  exception
    when no_data_found then
      return null;
    
  end;
  --------------------------------------------------------
  function sheerim_is_without_parent(p_seq_bakasha number) return number is
    v_is_without_parent number := 0;
  begin
  
    select case
             when count(*) > 0 then
              0
             else
              1
           end
      into v_is_without_parent
      from bney_mishpacha t
      left join v_bakasha_last_status t1
        on t.seq_porshim = t1.seq_porshim
     where t1.seq_bakasha = p_seq_bakasha
       and t.code_kirva in (1, 14, 10, 24)
          /*and not exists (select *
           from bney_mishpacha bm
          where bm.seq_porshim = t.seq_porshim
            and bm.code_kirva in (10, 24)
            and bm.taarich_ptira is null)*/
       and t.taarich_ptira is null;
    return v_is_without_parent;
  end;
  --------------------------------------------------------
  function sheerim_is_by_prev_bakasha(p_sug_bakasha         number,
                                      p_sug_bakasha_details number)
    return number is
  begin
    if p_sug_bakasha in (13, 23) or
       p_sug_bakasha = 5 and p_sug_bakasha_details in (28, 29, 32) then
      return 1;
    else
      return 0;
    end if;
  end;
  ---------------------------------------------------------
  ---------------------------------------------------------
  procedure insert_netuny_tk_ben_mishpacha(p_seq_bney_mishpacha          number,
                                           p_seq_netuney_tik_mechushavim number,
                                           p_code_relative               number,
                                           p_achuz_kizba_chuka           number,
                                           p_achuz_kizba                 number,
                                           p_seif_relative               in out number,
                                           p_date_start_zakaut           date default null,
                                           p_date_end_zakaut             date default null,
                                           p_achuz_tosefet_chuka         number default null,
                                           p_achuz_tosefet               number default null,
                                           p_code_maanak_almana          number default null,
                                           p_date_maanak_nisuin1         date default null,
                                           p_date_maanak_nisuin2         date default null,
                                           p_date_zakaut_maanak_almana   date default null) is
  
  begin
  
    merge into NETUNEY_TIK_BEN_MISHPACHA tt
    using dual
    on (seq_netuney_tik_mechushavim = p_seq_netuney_tik_mechushavim and seq_bney_mishpacha = p_seq_bney_mishpacha)
    when matched then
      update
         set date_start_zakaut         = nvl(p_date_start_zakaut,
                                             date_start_zakaut),
             date_end_zakaut           = nvl(p_date_end_zakaut,
                                             date_end_zakaut),
             code_relative             = nvl(p_code_relative, code_relative),
             achuz_kizba_chuka         = nvl(p_achuz_kizba_chuka,
                                             achuz_kizba_chuka),
             achuz_kizba               = nvl(p_achuz_kizba, achuz_kizba),
             achuz_tosefet_chuka       = nvl(p_achuz_tosefet_chuka,
                                             achuz_tosefet_chuka),
             achuz_tosefet             = nvl(p_achuz_tosefet, achuz_tosefet),
             code_maanak_almana        = nvl(p_code_maanak_almana,
                                             code_maanak_almana),
             date_maanak_nisuin1       = nvl(p_date_maanak_nisuin1,
                                             date_maanak_nisuin1),
             date_maanak_nisuin2       = nvl(p_date_maanak_nisuin2,
                                             date_maanak_nisuin2),
             date_zakaut_maanak_almana = nvl(p_date_zakaut_maanak_almana,
                                             date_zakaut_maanak_almana),
             
             seif_relative = p_seif_relative
    when not matched then
    
      insert
        (seq_netuney_tik_ben_mishpacha,
         seq_bney_mishpacha,
         seq_netuney_tik_mechushavim,
         date_start_zakaut,
         date_end_zakaut,
         code_relative,
         achuz_kizba_chuka,
         achuz_kizba,
         achuz_tosefet_chuka,
         achuz_tosefet,
         code_maanak_almana,
         date_maanak_nisuin1,
         date_maanak_nisuin2,
         date_zakaut_maanak_almana,
         seif_relative)
      values
        (netuney_tik_ben_mishpacha_seq.nextval,
         p_seq_bney_mishpacha,
         p_seq_netuney_tik_mechushavim,
         p_date_start_zakaut,
         p_date_end_zakaut,
         p_code_relative,
         p_achuz_kizba_chuka,
         p_achuz_kizba,
         p_achuz_tosefet_chuka,
         p_achuz_tosefet,
         p_code_maanak_almana,
         p_date_maanak_nisuin1,
         p_date_maanak_nisuin2,
         p_date_zakaut_maanak_almana,
         p_seif_relative);
  
  end;
end;
/

create or replace package body prm_system_copy.pk_zakaut_stop_payment is

  procedure main(p_seq_bakasha number) is
    v_seq_prisha          number;
    v_seq_bakasha_zakaut  number;
    v_from_date           date;
    v_code_bakasha_detail number;
    v_seq_bney_mishpacha  number;
    v_code_sug_bakasha    number;
    v_code_yadani         number;
    v_last_code_relative  number;
    v_to_date_sium_zakaut date;
    v_exists_netuney_zakaut    number;
    v_seif_sheer               number;
  begin
  
    --get date end
    select b.from_date,
           b.code_bakasha_detail,
           b.seq_prisha,
           b.seq_bney_mishpacha,
           b.code_sug_bakasha
      into v_from_date,
           v_code_bakasha_detail,
           v_seq_prisha,
           v_seq_bney_mishpacha,
           v_code_sug_bakasha
      from bakasha b
     where b."SEQ_BAKASHA" = p_seq_bakasha;
  
     ---if chuka yadanit- return!!
    v_code_yadani := pk_zakaut.get_code_yadani(p_seq_bakasha);
    if nvl(v_code_yadani, 0) > 0  then
      return;
    end if;
  
    --last zakaut
    --hafsaka
    select v."SEQ_BAKASHA_ZAKAUT"
      into v_seq_bakasha_zakaut
      from table(fn_obj_prisha_last_zakaut_arr(pk_select_function.fn_prisha_poresh_header(v_seq_prisha))) v;
    --hidush
    if v_code_sug_bakasha = 20 then
      select max(t.seq_bakasha)
        into v_seq_bakasha_zakaut
        from v_bakasha_last_status t
        left join bakasha b1
          on t.seq_bakasha = b1.seq_bakasha
       where t.seq_prisha = v_seq_prisha
         and t.code_sug_bakasha = 19
         and b1.seq_bney_mishpacha = v_seq_bney_mishpacha
         and t.code_action = 98;
         if v_code_bakasha_detail = 196 then
           select count(t.seq_bakasha)
           into v_exists_netuney_zakaut
           from netuney_tik_mechushavim t
           where t.seq_bakasha=v_seq_bakasha_zakaut
           and t.code_department=2;
           if v_exists_netuney_zakaut = 0 then
             select max(t.seq_bakasha) 
        into v_seq_bakasha_zakaut
        from v_bakasha_last_status t
        left join bakasha b1
          on t.seq_bakasha = b1.seq_bakasha
       where t.seq_prisha = v_seq_prisha
         and t.code_sug_bakasha in(1,3,5,13)
         --and b1.seq_bney_mishpacha = v_seq_bney_mishpacha
         and t.code_action = 98;
         end if;
           end if;
          end if;
               
    /*  select t."SEQ_BAKASHA_ZAKAUT"
     into v_seq_bakasha_zakaut
     from v_prisha_last_zakaut t
    where t."SEQ_PRISHA" = v_seq_prisha;*/
    if v_seq_bakasha_zakaut is not null and v_from_date is not null then
      --duplicate record
      delete from netuney_tik_mechushavim t
       where t.seq_bakasha = p_seq_bakasha;
      pk_prm_utils.duplicate_netuney_tik_mechushavim(p_seq_bakasha,
                                                     v_seq_bakasha_zakaut,
                                                     1);
     update netuney_tik_mechushavim t
        set t.code_e_zakaut = null
      where t.seq_bakasha =
            p_seq_bakasha;
                                                     
                                                     
      if v_code_sug_bakasha = 19 then
        if v_seq_bney_mishpacha is null then
          --set date_end_zakaut
          update netuney_tik_mechushavim t
             set t.date_end_zakaut = v_from_date - 1,
                 t.date_update     = sysdate
           where t."SEQ_BAKASHA" = p_seq_bakasha
             and t.code_department = 2;
        else
          for r in (select *
                      from netuney_tik_mechushavim n
                     where n."SEQ_BAKASHA" = p_seq_bakasha
                       and n.code_department = 2) loop
            update netuney_tik_ben_mishpacha b
               set b.date_end_zakaut = v_from_date - 1, b.code_relative = 9
             where b.seq_netuney_tik_mechushavim =
                   r.seq_netuney_tik_mechushavim
               and b.seq_bney_mishpacha = v_seq_bney_mishpacha;
            update bney_mishpacha t
               set t.code_relative       = 9,
                   t.to_date_sium_zakaut = nvl(to_date_sium_zakaut,
                                               v_from_date - 1)
             where t.seq_bney_mishpacha = v_seq_bney_mishpacha;
          
          end loop;
        end if;
      
        --sheer merride again
        if v_code_bakasha_detail = 8 then
          sheer_merride_calc_maanak(p_seq_bakasha, v_seq_bney_mishpacha);
          update bney_mishpacha t
             set t.code_kirva = 24, t.code_relative = 9
           where t.seq_bney_mishpacha = v_seq_bney_mishpacha
             and t.code_kirva = 1;
        end if;
      else
        --hidush
      
        update netuney_tik_mechushavim t
           set t.date_end_zakaut   = null,
               t.date_update       = sysdate,
               t.date_start_zakaut = v_from_date
         where t."SEQ_BAKASHA" = p_seq_bakasha
           and t.code_department = 2;
      
        if v_seq_bney_mishpacha is not null then
          select case
                   when b.to_date_sium_zakaut < v_from_date then
                    null
                   else
                    b.to_date_sium_zakaut
                 end
            into v_to_date_sium_zakaut
            from bney_mishpacha b
           where b.seq_bney_mishpacha = v_seq_bney_mishpacha;
          --get prev code relative 
          select max(n.code_relative) keep(dense_rank first order by n.seq_netuney_tik_mechushavim desc) code_relative
            into v_last_code_relative
            from netuney_tik_ben_mishpacha n
            left join netuney_tik_mechushavim n1
              on n.seq_netuney_tik_mechushavim =
                 n1.seq_netuney_tik_mechushavim
            left join v_bakasha_last_status v
              on n1.seq_bakasha = v.seq_bakasha
           where v.seq_prisha = v_seq_prisha
             and n.code_relative <> 9
             and n.seq_bney_mishpacha = v_seq_bney_mishpacha;
          --if there is no prev code_relaive then calc code relaive by decision table
          if v_last_code_relative is null then
            v_last_code_relative := pk_zakaut_stop_payment.sheer_calc_code_relative(p_seq_bakasha,
                                                                                    v_seq_bney_mishpacha,
                                                                                    v_from_date,
                                                                                    v_seif_sheer);
          end if;
          for r in (select *
                      from netuney_tik_mechushavim n
                     where n."SEQ_BAKASHA" = p_seq_bakasha
                       and n.code_department = 2) loop
          
            merge into netuney_tik_ben_mishpacha b using dual
            on (b.seq_netuney_tik_mechushavim =
                   r.seq_netuney_tik_mechushavim
               and b.seq_bney_mishpacha = v_seq_bney_mishpacha)
               when matched then
      update
               set b.date_end_zakaut   = v_to_date_sium_zakaut,
                   b.date_start_zakaut = v_from_date,
                   b.code_relative     = v_last_code_relative
             where b.seq_netuney_tik_mechushavim =
                   r.seq_netuney_tik_mechushavim
               and b.seq_bney_mishpacha = v_seq_bney_mishpacha
               when not matched then insert
                ( b.seq_netuney_tik_ben_mishpacha,
                 b.seq_bney_mishpacha,
                 b.seq_netuney_tik_mechushavim,
                 b.date_start_zakaut,
                 b.date_end_zakaut,
                 b.code_relative,
                 b.seif_relative
                 )
                 values
                 (netuney_tik_ben_mishpacha_seq.nextval,
                 v_seq_bney_mishpacha,
                 r.seq_netuney_tik_mechushavim,
                 v_from_date,
                 v_to_date_sium_zakaut,
                 v_last_code_relative,
                 v_seif_sheer)
                 ;
            update bney_mishpacha t
               set t.to_date_sium_zakaut = v_to_date_sium_zakaut,
                   t.code_relative       = v_last_code_relative
             where t.seq_bney_mishpacha = v_seq_bney_mishpacha;
          end loop;
        end if;
      end if;
    end if;
  exception
    when others then
      return;
      commit;
  end;
  --------------------------------------------
  procedure sheer_merride_calc_maanak(p_seq_bakasha        number,
                                      p_seq_bney_mishpacha number) is
    v_from_date                   date;
    v_seq_netuney_tik_mechushavim number;
  begin
  
    select b.from_date
      into v_from_date
      from bakasha b
     where b."SEQ_BAKASHA" = p_seq_bakasha;
  
    select t.seq_netuney_tik_mechushavim
      into v_seq_netuney_tik_mechushavim
      from netuney_tik_mechushavim t
     where t.seq_bakasha = p_seq_bakasha
       and t.code_department = 2
       and t.mispar_misra = 0;
    /* update netuney_tik_mechushavim t
      set t.is_maanak_nisuin1 = TRUNC(v_from_date - 1, 'MONTH'),
          t.is_maanak_nisuin2 = add_months(TRUNC(v_from_date - 1, 'MONTH'),
                                           25)
    where t.seq_bakasha = p_seq_bakasha
      and t.code_department = 2
      and t.mispar_misra = 0;*/
  
    update netuney_tik_ben_mishpacha t
       set t.date_maanak_nisuin1 = TRUNC(v_from_date - 1, 'MONTH'),
           t.date_maanak_nisuin2 = add_months(TRUNC(v_from_date - 1, 'MONTH'),
                                              25)
     where t.seq_bney_mishpacha = p_seq_bney_mishpacha
       and t.seq_netuney_tik_mechushavim = v_seq_netuney_tik_mechushavim;
  
  end;
  --------------------------------------------
  function sheer_calc_code_relative(p_seq_bakasha       number,
                                    p_seq_ben_mishpacha number,
                                    p_to_date           date,
                                    p_seif_sheer in out number) return number is
    v_code_relative           number;
    v_seq_bakasha_last_zakaut number;
    v_code_job                number;
    v_is_without_parent       number;
    v_code_seif_prisha        number;
  begin
  
    select v."SEQ_BAKASHA_ZAKAUT",
           case
             when v.code_derug in (6, 83, 84) or
                  v.code_derug = 82 and v.code_darga not in (32, 42, 52) then
              6
             else
              null
           end as code_job,
           v.code_seif_prisha
      into v_seq_bakasha_last_zakaut, v_code_job, v_code_seif_prisha
      from v_prisha_last_zakaut v
      left join bakasha b
        on b.seq_prisha = v."SEQ_PRISHA"
     where b.seq_bakasha = p_seq_bakasha;
  
    v_is_without_parent := pk_zakaut.sheerim_is_without_parent(v_seq_bakasha_last_zakaut);
  
    select max(t.code_relative),max(t.seif_relative)
      into v_code_relative,p_seif_sheer
      from bney_mishpacha b
      left join PERM_DECISION_ZAKAUT_SHEER t
        on t.code_kirva = b.code_kirva
       and t.code_seif_prisha = mod(v_code_seif_prisha,100)+100
       and (t.age_max is null or
           months_between(p_to_date + 1, b.taarich_leda) / 12 <= t.age_max)
       and (nvl(t.is_was_in_zahal, 0) = nvl(b.is_army_ishur, 0) or
           b.code_kirva <> 2)
       and (nvl(t.is_taluy, 0) = nvl(b.is_taluy, 0))
          
       and (nvl(t.is_without_parent, 0) = nvl(v_is_without_parent, 0) or
           b.code_kirva <> 2)
       and (nvl(t.code_job, 0) = nvl(v_code_job, 0))
       and  b.seq_bney_mishpacha=p_seq_ben_mishpacha;
    return v_code_relative;
  exception
    when no_data_found then
      return null;
  end;

end;
/

