CREATE OR REPLACE TRIGGER PRM_SYSTEM_COPY."BANK_ACCOUNT_HIS_TRG"
after  update or delete on BANK_ACCOUNT
for each row
begin
if :old.ACCOUNT_NUMBER <> :new.ACCOUNT_NUMBER then
insert into BANK_ACCOUNT_HIS
(  SEQ_BANK_ACCOUNT, date_change, shem_meadken_acharon, col_name , old_value , new_value)
values
(:new.SEQ_BANK_ACCOUNT,sysdate, :new.shem_meadken_acharon,'חשבון',:old.ACCOUNT_NUMBER,:new.ACCOUNT_NUMBER);
end if;
if :old.CODE_BANK <> :new.CODE_BANK then
insert into BANK_ACCOUNT_HIS
(  SEQ_BANK_ACCOUNT, date_change, shem_meadken_acharon, col_name , old_value , new_value)
