(:new.SEQ_BANK_ACCOUNT,sysdate, :new.shem_meadken_acharon,'תאריך עדכון',:old.DATE_UPDATE,:new.DATE_UPDATE);
end if;
if :old.SEQ_BAKASHA <> :new.SEQ_BAKASHA then
insert into BANK_ACCOUNT_HIS
(  SEQ_BANK_ACCOUNT, date_change, shem_meadken_acharon, col_name , old_value , new_value)
