CREATE OR REPLACE TRIGGER PRM_SYSTEM_COPY."ERROR_ON_ID_UPDATE"
before UPDATE
   ON poresh
   FOR EACH ROW
declare
message clob := 'The next Id should not be changed.';
BEGIN
if :new.MISPAR_ZEHUT <> :old.MISPAR_ZEHUT
  then
    message := message ||' from: '|| to_char(:old.MISPAR_ZEHUT)|| ' to: '|| to_char(:new.MISPAR_ZEHUT);
     RAISE_APPLICATION_ERROR
     (-20000,message);
end if;
END;
/

