CREATE OR REPLACE TRIGGER PRM_SYSTEM_COPY."INSERT_DOCUMENT_UPDATE_DATE"
  before insert or update of date_update
  on document
  for each row
 begin
  if :new.date_update = trunc(:new.date_update)
     and trunc(:new.date_update) = trunc(sysdate) then
     :new.date_update := sysdate;
     end if;
end document_update_date;
/

