CREATE OR REPLACE TRIGGER PRM_SYSTEM_COPY."T-136-trigger"
  after insert or update of code_action
   on action_log
  for each row
begin
  if :new.code_action = 136 then
    data_duplication_136(:new.seq_bakasha);
  end if;
end "T-136-trigger";
/

